export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

/**
 * Admin panel API client.
 *
 * Same contract as the desktop client's: bearer access token, refresh on 401,
 * one retry. The refresh token lives in localStorage under its own key so a
 * panel session and a chat session on the same host do not overwrite each
 * other.
 */
import type {
  AdminAuditPage,
  AdminOAuthProvider,
  AdminOAuthProviderUpdate,
  AdminSmtpSettings,
  AdminSmtpTestResult,
  AdminServerHealth,
  AdminSmtpUpdate,
  AdminStatus,
  AdminUser,
  AdminUserPage,
  AdminUserUpdate,
  ApiErrorBody,
  AuthResponse,
  AuthTokens,
  OAuthProviderSummary,
  PublicUser,
} from '@betweenus/shared-types';

// Optional chaining rather than a plain read: `import.meta.env` is Vite's, and
// this module is also pulled in by the screens' self-checks, which run under
// plain Node where it does not exist at all. An empty base URL is what the
// browser bundle gets anyway when the variable is unset.
const API_URL = import.meta.env?.VITE_API_URL ?? '';
const REFRESH_KEY = 'betweenus.admin.refreshToken';

export class ApiError extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

let accessToken: string | null = null;

export const session = {
  get token(): string | null {
    return accessToken;
  },
  get refreshToken(): string | null {
    return localStorage.getItem(REFRESH_KEY);
  },
  start(tokens: AuthTokens): void {
    accessToken = tokens.accessToken;
    localStorage.setItem(REFRESH_KEY, tokens.refreshToken);
  },
  end(): void {
    accessToken = null;
    localStorage.removeItem(REFRESH_KEY);
  },
};

/** Single-flight, because refresh tokens rotate and a race kills the session. */
let refreshInFlight: Promise<string | null> | null = null;

async function refresh(): Promise<string | null> {
  if (refreshInFlight) return refreshInFlight;

  refreshInFlight = (async () => {
    const stored = session.refreshToken;
    if (!stored) return null;
    try {
      const tokens = await request<AuthTokens>(
        '/api/v1/auth/refresh',
        { method: 'POST', body: JSON.stringify({ refreshToken: stored }) },
        false,
      );
      session.start(tokens);
      return tokens.accessToken;
    } catch {
      session.end();
      return null;
    } finally {
      refreshInFlight = null;
    }
  })();

  return refreshInFlight;
}

async function request<T>(path: string, init: RequestInit = {}, retry = true): Promise<T> {
  const response = await fetch(`${API_URL}${path}`, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
      ...init.headers,
    },
  });

  if (response.status === 401 && retry && session.refreshToken) {
    const refreshed = await refresh();
    if (refreshed) return request<T>(path, init, false);
  }

  if (response.status === 204) return undefined as T;

  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const body = payload as ApiErrorBody | null;
    throw new ApiError(
      body?.error?.code ?? 'REQUEST_FAILED',
      body?.error?.message ?? 'Request failed',
      response.status,
    );
  }
  return payload as T;
}

/** Rows per request. Small enough that the first page draws immediately. */
const PAGE_SIZE = 50;

export const api = {
  /** Public - answers whether `pnpm admin:create` has been run. */
  status: (): Promise<AdminStatus> => request('/api/v1/admin/status'),

  /** Public - which sign-in providers the operator switched on. */
  signInProviders: (): Promise<OAuthProviderSummary[]> =>
    request('/api/v1/auth/oauth/providers'),

  /**
   * Where to send the browser to sign in with a provider. It comes back to this
   * origin with `?code=`, which `exchangeOAuthCode` trades for a session.
   */
  signInUrl: (provider: string): string =>
    `${API_URL}/api/v1/auth/oauth/${provider}/start?redirect=${encodeURIComponent(
      `${window.location.origin}${window.location.pathname}`,
    )}`,

  exchangeOAuthCode: (code: string): Promise<AuthResponse> =>
    request('/api/v1/auth/oauth/exchange', { method: 'POST', body: JSON.stringify({ code }) }),

  login: (identifier: string, password: string): Promise<AuthResponse> =>
    request('/api/v1/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email: identifier, password }),
    }),

  me: (): Promise<PublicUser> => request('/api/v1/auth/me'),

  logout: (refreshToken: string): Promise<void> =>
    request('/api/v1/auth/logout', { method: 'POST', body: JSON.stringify({ refreshToken }) }),

  changePassword: (currentPassword: string, newPassword: string): Promise<AuthResponse> =>
    request('/api/v1/auth/account/password', {
      method: 'POST',
      body: JSON.stringify({ currentPassword, newPassword }),
    }),

  updateAccount: (update: { username?: string; displayName?: string }): Promise<PublicUser> =>
    request('/api/v1/auth/account', { method: 'PATCH', body: JSON.stringify(update) }),

  users: (query: string, cursor?: string): Promise<AdminUserPage> =>
    request(
      `/api/v1/admin/users?query=${encodeURIComponent(query)}&take=${PAGE_SIZE}` +
        (cursor ? `&cursor=${encodeURIComponent(cursor)}` : ''),
    ),

  audit: (cursor?: string): Promise<AdminAuditPage> =>
    request(
      `/api/v1/admin/audit?take=${PAGE_SIZE}` +
        (cursor ? `&cursor=${encodeURIComponent(cursor)}` : ''),
    ),

  updateUser: (id: string, update: AdminUserUpdate): Promise<AdminUser> =>
    request(`/api/v1/admin/users/${id}`, { method: 'PATCH', body: JSON.stringify(update) }),

  deleteUser: (id: string): Promise<void> =>
    request(`/api/v1/admin/users/${id}`, { method: 'DELETE' }),

  smtp: (): Promise<AdminSmtpSettings> => request('/api/v1/admin/smtp'),

  updateSmtp: (update: AdminSmtpUpdate): Promise<AdminSmtpSettings> =>
    request('/api/v1/admin/smtp', { method: 'PUT', body: JSON.stringify(update) }),

  testSmtp: (to?: string): Promise<AdminSmtpTestResult> =>
    request('/api/v1/admin/smtp/test', { method: 'POST', body: JSON.stringify(to ? { to } : {}) }),

  /**
   * One snapshot of the deployment: dependencies, runtime, storage, traffic and
   * live sockets. `days` sizes the bandwidth window only; everything else is
   * measured at the moment of the call, so this is polled rather than cached.
   */
  health: (days?: number): Promise<AdminServerHealth> =>
    request(`/api/v1/admin/health${days === undefined ? '' : `?days=${days}`}`),

  oauthProviders: (): Promise<AdminOAuthProvider[]> => request('/api/v1/admin/oauth'),

  updateOAuthProvider: (
    provider: string,
    update: AdminOAuthProviderUpdate,
  ): Promise<AdminOAuthProvider> =>
    request(`/api/v1/admin/oauth/${provider}`, { method: 'PUT', body: JSON.stringify(update) }),
};

export { refresh as refreshSession };

/**
 * Admin panel shell.
 *
 * Four states, in order: no administrator exists yet (explain the CLI), signed
 * out, signed in but still on a generated password, and the panel proper.
 */
import { useCallback, useEffect, useState } from 'react';
import type { AuthResponse, PublicUser } from '@betweenus/shared-types';
import { ApiError, api, refreshSession, session } from './api';
import { LoginScreen } from './screens/LoginScreen';
import { BootstrapScreen } from './screens/BootstrapScreen';
import { ChangePasswordScreen } from './screens/ChangePasswordScreen';
import { UsersScreen } from './screens/UsersScreen';
import { AuditScreen } from './screens/AuditScreen';
import { OAuthScreen } from './screens/OAuthScreen';
import { MailScreen } from './screens/MailScreen';
import { HealthScreen } from './screens/HealthScreen';
import { AccountScreen } from './screens/AccountScreen';

/**
 * `health` leads the nav because it is the question an operator opens this
 * panel with when something is wrong, and the only tab whose answer is time
 * sensitive - the other four are administration, which waits.
 */
type Tab = 'health' | 'users' | 'audit' | 'oauth' | 'mail' | 'account';

export default function App(): JSX.Element {
  const [hasAdmin, setHasAdmin] = useState<boolean | null>(null);
  const [user, setUser] = useState<PublicUser | null>(null);
  const [booting, setBooting] = useState(true);
  const [tab, setTab] = useState<Tab>('health');
  const [signInError, setSignInError] = useState<string | null>(null);

  const load = useCallback(async (): Promise<void> => {
    const status = await api.status().catch(() => ({ hasAdmin: true }));
    setHasAdmin(status.hasAdmin);

    // Coming back from a provider. The code is single-use and is stripped from
    // the address bar either way, so a reload cannot try to spend it twice.
    const code = new URLSearchParams(window.location.search).get('code');
    if (code) {
      window.history.replaceState(null, '', window.location.pathname);
      try {
        const result = await api.exchangeOAuthCode(code);
        const refused = adminOnly(result);
        if (refused) setSignInError(refused);
        else setUser(result.user);
      } catch (caught) {
        setSignInError(messageOf(caught));
      }
      setBooting(false);
      return;
    }

    // A stored refresh token is worth one attempt; anything else means signed out.
    if (session.refreshToken) {
      try {
        if (await refreshSession()) setUser(await api.me());
      } catch {
        session.end();
      }
    }
    setBooting(false);
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const signOut = async (): Promise<void> => {
    const stored = session.refreshToken;
    session.end();
    setUser(null);
    if (stored) await api.logout(stored).catch(() => undefined);
  };

  if (booting) {
    return (
      <div className="grid h-full place-items-center" aria-busy="true">
        <p className="animate-pulse text-lg font-semibold text-slate-300">BetweenUs Admin</p>
      </div>
    );
  }

  if (hasAdmin === false && !user) return <BootstrapScreen onRetry={load} />;
  if (!user) return <LoginScreen onSignedIn={setUser} initialError={signInError} />;
  if (user.mustChangePassword) return <ChangePasswordScreen user={user} onDone={setUser} />;

  return (
    <div className="mx-auto flex h-full max-w-6xl flex-col px-6 py-6">
      <header className="mb-6 flex items-center gap-4">
        <h1 className="text-xl font-semibold text-slate-50">BetweenUs Admin</h1>

        <nav className="ml-6 flex gap-1" aria-label="Sections">
          {(
            [
              ['health', 'Health'],
              ['users', 'Users'],
              ['audit', 'Audit log'],
              ['oauth', 'Sign-in providers'],
              ['mail', 'Outgoing mail'],
              ['account', 'My account'],
            ] as Array<[Tab, string]>
          ).map(([key, label]) => (
            <button
              key={key}
              type="button"
              onClick={() => setTab(key)}
              aria-current={tab === key ? 'page' : undefined}
              className={`cursor-pointer rounded-md px-3 py-1.5 text-sm transition-colors duration-200 ${
                tab === key
                  ? 'bg-surface-800 text-slate-50'
                  : 'text-slate-400 hover:bg-surface-800/60 hover:text-slate-200'
              }`}
            >
              {label}
            </button>
          ))}
        </nav>

        <div className="ml-auto flex items-center gap-3 text-sm text-slate-400">
          <span>@{user.username}</span>
          <button
            type="button"
            onClick={() => void signOut()}
            className="cursor-pointer rounded-md border border-surface-700 px-3 py-1.5 transition-colors duration-200 hover:border-red-500 hover:text-red-300"
          >
            Sign out
          </button>
        </div>
      </header>

      <main className="min-h-0 flex-1 overflow-y-auto">
        {tab === 'health' && <HealthScreen />}
        {tab === 'users' && <UsersScreen currentUserId={user.id} />}
        {tab === 'audit' && <AuditScreen />}
        {tab === 'oauth' && <OAuthScreen />}
        {tab === 'mail' && <MailScreen />}
        {tab === 'account' && <AccountScreen user={user} onUpdated={setUser} />}
      </main>
    </div>
  );
}

/** Shared by the screens: an API error is a message, anything else is generic. */
export function messageOf(error: unknown): string {
  if (error instanceof ApiError) return error.message;
  return 'Could not reach the server.';
}

/**
 * Starts the session if the account is an administrator, and refuses it
 * otherwise. Signing in correctly is not the same as being allowed in here, and
 * both doors - password and provider - have to say so.
 */
export function adminOnly(result: AuthResponse): string | null {
  if (result.user.role !== 'ADMIN') {
    session.end();
    return 'That account is not an administrator.';
  }
  session.start(result);
  return null;
}

/**
 * The arithmetic behind every number on the health screen.
 *
 * Worth pinning because these are the failures that never look like failures.
 * A byte formatter that divides by 1000 renders a perfectly plausible screen
 * that is wrong by 2.4% per unit; a duration that forgets to carry hours out of
 * days reports a fortnight of uptime as fourteen days and twenty-six hours. Both
 * pass an eyeball and neither passes an assertion.
 *
 * Run with: pnpm --filter @betweenus/admin check
 */
import assert from 'node:assert/strict';
import { formatBytes, formatCount, formatDuration, percentOf } from './format';

// The divisor is 1024, not 1000. This is the whole reason the module exists.
assert.equal(formatBytes(0), '0 B');
assert.equal(formatBytes(999), '999 B');
assert.equal(formatBytes(1023), '1023 B', 'still bytes right up to the boundary');
assert.equal(formatBytes(1024), '1.00 KB', 'the boundary is 1024, never 1000');
assert.equal(formatBytes(1000), '1000 B', 'a thousand bytes is not a kilobyte');
assert.equal(formatBytes(1024 * 1024), '1.00 MB');
assert.equal(formatBytes(1024 ** 3), '1.00 GB');
assert.equal(formatBytes(1024 ** 4), '1.00 TB');
assert.equal(formatBytes(1024 ** 5), '1.00 PB');
// Past the last unit it keeps counting in petabytes rather than falling off the
// end of the table and rendering `undefined`.
assert.equal(formatBytes(1024 ** 6), '1024 PB');

// Precision shrinks as the unit grows, so a column of sizes stays scannable.
assert.equal(formatBytes(1536), '1.50 KB');
assert.equal(formatBytes(1024 * 50), '50.0 KB');
assert.equal(formatBytes(1024 * 500), '500 KB');

// Not-a-number is a missing measurement, and must never render as a size.
assert.equal(formatBytes(Number.NaN), '—');
assert.equal(formatBytes(Number.POSITIVE_INFINITY), '—');

assert.equal(formatDuration(0), '0s');
assert.equal(formatDuration(45), '45s');
assert.equal(formatDuration(60), '1m');
assert.equal(formatDuration(90), '1m 30s');
assert.equal(formatDuration(3600), '1h');
assert.equal(formatDuration(3600 + 12 * 60), '1h 12m');
assert.equal(formatDuration(86400), '1d');
// The carry that goes wrong: a day and a bit is `1d 4h`, never `1d 28h`.
assert.equal(formatDuration(86400 + 4 * 3600 + 59 * 60), '1d 4h');
assert.equal(formatDuration(14 * 86400 + 3600), '14d 1h');
assert.equal(formatDuration(-1), '—', 'a negative uptime is a bug, not a duration');

assert.equal(formatCount(0), '0');
assert.equal(formatCount(Number.NaN), '—');

// A server reporting no connection cap must not paint a bar `NaN%` wide, which
// CSS reads as "as wide as you like".
assert.equal(percentOf(5, 0), 0);
assert.equal(percentOf(5, 10), 50);
assert.equal(percentOf(30, 10), 100, 'clamped: a bar never overflows its track');
assert.equal(percentOf(-5, 10), 0);

console.log('format.check.ts: ok');

/**
 * Human formatting for the numbers the health screen draws.
 *
 * These live in a module of their own rather than inline in the screen for one
 * reason: a byte formatter that divides by 1000 where it should divide by 1024
 * is invisible on screen. Every size still looks like a size, the units still
 * look right, and the panel simply reports a database 2.4% larger than it is -
 * a lie nobody catches by looking. So the arithmetic sits somewhere a
 * self-check can reach it (`format.check.ts`), and the screen only calls it.
 *
 * The divisor is 1024, and the unit labels are the short ones (KB, MB, GB)
 * rather than the pedantic ones (KiB, MiB). That is deliberately what
 * `pg_size_pretty` does, and the database section of this screen is read
 * side-by-side with `psql` output often enough that agreeing with it matters
 * more than being right about the IEC spelling.
 */

const UNITS = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'] as const;

/**
 * Bytes as an operator reads them: `1.4 GB`, `812 KB`, `0 B`.
 *
 * Precision shrinks as the unit grows, because "1.44 GB" carries information
 * that "144.32 KB" does not - the second decimal of a kilobyte figure is noise
 * that makes a column of numbers harder to scan.
 */
export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes)) return '—';
  const negative = bytes < 0;
  let value = Math.abs(bytes);
  let unit = 0;
  while (value >= 1024 && unit < UNITS.length - 1) {
    value /= 1024;
    unit += 1;
  }
  // Bytes are whole things; a fractional byte is a rounding artefact, not data.
  const decimals = unit === 0 ? 0 : value < 10 ? 2 : value < 100 ? 1 : 0;
  return `${negative ? '-' : ''}${value.toFixed(decimals)} ${UNITS[unit] ?? 'B'}`;
}

/**
 * Seconds as a duration: `6d 4h`, `3h 12m`, `48s`.
 *
 * Two units at most. An uptime of "6 days, 4 hours, 11 minutes and 3 seconds"
 * is answering a question nobody asked - the reason anybody reads an uptime is
 * to know whether the process restarted recently, and two units settle that.
 */
export function formatDuration(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return '—';
  const whole = Math.floor(seconds);
  const days = Math.floor(whole / 86400);
  const hours = Math.floor((whole % 86400) / 3600);
  const minutes = Math.floor((whole % 3600) / 60);
  const rest = whole % 60;

  if (days > 0) return hours > 0 ? `${days}d ${hours}h` : `${days}d`;
  if (hours > 0) return minutes > 0 ? `${hours}h ${minutes}m` : `${hours}h`;
  if (minutes > 0) return rest > 0 ? `${minutes}m ${rest}s` : `${minutes}m`;
  return `${whole}s`;
}

/**
 * A count with thousands separators. Row estimates and socket counts run into
 * seven figures on a busy deployment and are unreadable without them.
 */
export function formatCount(value: number): string {
  if (!Number.isFinite(value)) return '—';
  return Math.round(value).toLocaleString();
}

/**
 * A share of a whole, as a percentage string, safe at zero.
 *
 * Written out because the two places that need it - the connection gauge and
 * the per-table bars - both divide by a number the server supplies, and a
 * deployment reporting `maxConnections: 0` would otherwise paint every bar
 * `NaN%` wide, which CSS reads as "as wide as you like".
 */
export function percentOf(part: number, whole: number): number {
  if (!Number.isFinite(part) || !Number.isFinite(whole) || whole <= 0) return 0;
  return Math.min(100, Math.max(0, (part / whole) * 100));
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

const container = document.getElementById('root');
if (!container) throw new Error('Missing #root element');

ReactDOM.createRoot(container).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import { useState } from 'react';
import type { PublicUser } from '@betweenus/shared-types';
import { api, session } from '../api';
import { messageOf } from '../App';

/** The administrator's own account: name, username, password. */
export function AccountScreen({
  user,
  onUpdated,
}: {
  user: PublicUser;
  onUpdated: (user: PublicUser) => void;
}): JSX.Element {
  return (
    <div className="grid max-w-3xl gap-6">
      <ProfileCard user={user} onUpdated={onUpdated} />
      <PasswordCard onUpdated={onUpdated} />
    </div>
  );
}

function ProfileCard({
  user,
  onUpdated,
}: {
  user: PublicUser;
  onUpdated: (user: PublicUser) => void;
}): JSX.Element {
  const [username, setUsername] = useState(user.username);
  const [displayName, setDisplayName] = useState(user.displayName);
  const [state, setState] = useState<{ error?: string; status?: string }>({});
  const [busy, setBusy] = useState(false);

  const save = async (): Promise<void> => {
    setBusy(true);
    setState({});
    try {
      const updated = await api.updateAccount({ username: username.trim(), displayName: displayName.trim() });
      onUpdated(updated);
      setState({ status: 'Saved.' });
    } catch (caught) {
      setState({ error: messageOf(caught) });
    } finally {
      setBusy(false);
    }
  };

  return (
    <Card title="Profile">
      <Field id="username" label="Username" value={username} onChange={setUsername} />
      <Field id="displayName" label="Display name" value={displayName} onChange={setDisplayName} />
      <Footer busy={busy} onSave={() => void save()} {...state} />
    </Card>
  );
}

function PasswordCard({ onUpdated }: { onUpdated: (user: PublicUser) => void }): JSX.Element {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [state, setState] = useState<{ error?: string; status?: string }>({});
  const [busy, setBusy] = useState(false);

  const save = async (): Promise<void> => {
    setBusy(true);
    setState({});
    try {
      const result = await api.changePassword(currentPassword, newPassword);
      // Changing the password revoked every session; keep this one alive.
      session.start(result);
      onUpdated(result.user);
      setCurrentPassword('');
      setNewPassword('');
      setState({ status: 'Password changed. Other sessions were signed out.' });
    } catch (caught) {
      setState({ error: messageOf(caught) });
    } finally {
      setBusy(false);
    }
  };

  return (
    <Card title="Password">
      <Field
        id="current"
        label="Current password"
        type="password"
        value={currentPassword}
        onChange={setCurrentPassword}
      />
      <Field
        id="new"
        label="New password"
        type="password"
        value={newPassword}
        onChange={setNewPassword}
        hint="At least 8 characters, with a letter and a number."
      />
      <Footer busy={busy} onSave={() => void save()} {...state} />
    </Card>
  );
}

function Card({ title, children }: { title: string; children: React.ReactNode }): JSX.Element {
  return (
    <section className="rounded-lg border border-surface-700 bg-surface-800 p-6">
      <h2 className="mb-4 text-lg font-semibold text-slate-50">{title}</h2>
      {children}
    </section>
  );
}

function Field({
  id,
  label,
  value,
  onChange,
  type = 'text',
  hint,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  type?: string;
  hint?: string;
}): JSX.Element {
  return (
    <div className="mb-4">
      <label htmlFor={id} className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400">
        {label}
      </label>
      <input
        id={id}
        type={type}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="w-full max-w-sm rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-sm text-slate-100 focus:border-accent"
      />
      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
    </div>
  );
}

function Footer({
  busy,
  onSave,
  status,
  error,
}: {
  busy: boolean;
  onSave: () => void;
  status?: string;
  error?: string;
}): JSX.Element {
  return (
    <div className="flex items-center gap-4">
      <button
        type="button"
        onClick={onSave}
        disabled={busy}
        className="cursor-pointer rounded-md bg-accent px-4 py-2 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-60"
      >
        {busy ? 'Saving…' : 'Save'}
      </button>
      {status && <span className="text-sm text-emerald-300">{status}</span>}
      {error && (
        <span role="alert" className="text-sm text-red-300">
          {error}
        </span>
      )}
    </div>
  );
}

/**
 * What administrators have done: who disabled or deleted whom, and when.
 *
 * Read-only by construction - the API has no write route and no delete route,
 * because a log an administrator can edit answers nothing.
 */
import { useEffect, useState } from 'react';
import type { AdminAuditEntry } from '@betweenus/shared-types';
import { api } from '../api';
import { messageOf } from '../App';

/** Actions worth a sentence rather than a dotted identifier. */
const SENTENCES: Record<string, string> = {
  'user.role.changed': 'changed the platform role of',
  'user.disabled': 'disabled',
  'user.enabled': 'enabled',
  'user.deleted': 'deleted',
  'oauth.updated': 'changed sign-in provider',
};

export function AuditScreen(): JSX.Element {
  const [entries, setEntries] = useState<AdminAuditEntry[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const load = async (from?: string): Promise<void> => {
    setLoading(true);
    try {
      const page = await api.audit(from);
      setEntries((current) => (from ? [...current, ...page.entries] : page.entries));
      setCursor(page.nextCursor);
      setError(null);
    } catch (caught) {
      setError(messageOf(caught));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, []);

  return (
    <section>
      {error && (
        <p role="alert" className="mb-4 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {error}
        </p>
      )}

      <div className="overflow-x-auto rounded-lg border border-surface-700">
        <table className="w-full text-left text-sm">
          <thead className="bg-surface-800 text-xs uppercase tracking-wide text-slate-400">
            <tr>
              <th scope="col" className="px-4 py-3">When</th>
              <th scope="col" className="px-4 py-3">Who</th>
              <th scope="col" className="px-4 py-3">Did</th>
              <th scope="col" className="px-4 py-3">Detail</th>
            </tr>
          </thead>
          <tbody>
            {entries.map((entry) => (
              <tr key={entry.id} className="border-t border-surface-700/60">
                <td className="px-4 py-3 text-slate-400">
                  {new Date(entry.createdAt).toLocaleString()}
                </td>
                <td className="px-4 py-3 text-slate-200">
                  {/* Null once that administrator's own account is deleted. */}
                  {entry.actorLabel ?? 'a deleted account'}
                </td>
                <td className="px-4 py-3 text-slate-200">
                  {SENTENCES[entry.action] ?? entry.action}{' '}
                  <span className="text-slate-400">{entry.targetLabel ?? ''}</span>
                </td>
                <td className="px-4 py-3 font-mono text-xs text-slate-500">
                  {entry.detail ? JSON.stringify(entry.detail) : ''}
                </td>
              </tr>
            ))}

            {!loading && entries.length === 0 && (
              <tr>
                <td colSpan={4} className="px-4 py-8 text-center text-slate-500">
                  Nothing has been done from this panel yet.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {cursor && (
        <button
          type="button"
          disabled={loading}
          onClick={() => void load(cursor)}
          className="mt-4 w-full cursor-pointer rounded-md border border-surface-700 px-4 py-2 text-sm text-slate-300 transition-colors duration-200 hover:border-accent disabled:cursor-not-allowed disabled:opacity-60"
        >
          {loading ? 'Loading…' : 'Load more'}
        </button>
      )}
    </section>
  );
}

import { useState, type FormEvent } from 'react';
import type { PublicUser } from '@betweenus/shared-types';
import { api, session } from '../api';
import { messageOf } from '../App';

/**
 * Forced on first login. The generated password was printed to a terminal and
 * possibly a scrollback buffer, so it is treated as already compromised.
 */
export function ChangePasswordScreen({
  user,
  onDone,
}: {
  user: PublicUser;
  onDone: (user: PublicUser) => void;
}): JSX.Element {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    if (newPassword !== confirmation) {
      setError('The two new passwords do not match.');
      return;
    }

    setBusy(true);
    setError(null);
    try {
      const result = await api.changePassword(currentPassword, newPassword);
      // Every old session died; this response carries the replacement.
      session.start(result);
      onDone(result.user);
    } catch (caught) {
      setError(messageOf(caught));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="grid h-full place-items-center px-4">
      <form onSubmit={submit} className="w-full max-w-sm rounded-xl bg-surface-800 p-8 shadow-2xl" noValidate>
        <h1 className="mb-1 text-2xl font-semibold text-slate-50">Choose a password</h1>
        <p className="mb-6 text-sm text-slate-400">
          @{user.username} is still on the password the CLI generated. Pick your own to continue.
        </p>

        <Field
          id="current"
          label="Generated password"
          value={currentPassword}
          onChange={setCurrentPassword}
          autoComplete="current-password"
        />
        <Field
          id="new"
          label="New password"
          value={newPassword}
          onChange={setNewPassword}
          autoComplete="new-password"
          hint="At least 8 characters, with a letter and a number."
        />
        <Field
          id="confirm"
          label="Repeat new password"
          value={confirmation}
          onChange={setConfirmation}
          autoComplete="new-password"
        />

        {error && (
          <p role="alert" className="mt-4 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
            {error}
          </p>
        )}

        <button
          type="submit"
          disabled={busy}
          className="mt-6 w-full cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-60"
        >
          {busy ? 'Saving…' : 'Save password'}
        </button>
      </form>
    </div>
  );
}

function Field({
  id,
  label,
  value,
  onChange,
  autoComplete,
  hint,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  autoComplete: string;
  hint?: string;
}): JSX.Element {
  return (
    <div className="mb-4">
      <label htmlFor={id} className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400">
        {label}
      </label>
      <input
        id={id}
        type="password"
        required
        autoComplete={autoComplete}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-slate-100 focus:border-accent"
      />
      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
    </div>
  );
}

/**
 * The health screen, rendered against a typed fixture.
 *
 * The endpoint this screen reads is built separately, so until it lands there
 * is no live snapshot to look at - and the shapes worth looking at are the ones
 * a healthy deployment never produces anyway: an S3 driver that cannot report a
 * disk size, a component that is down and carrying an error sentence, a window
 * with no traffic in it. A fixture reaches all three in a second and a running
 * deployment reaches none of them on demand.
 *
 * What it actually guards: **that a null never renders as a zero.** Every other
 * assertion here is a section being present; that one is the bug this screen
 * could ship. "0 B" of media on an S3 deployment is a panel inventing a
 * measurement, and an operator has no way to tell it apart from a real one.
 *
 * The fixtures live in this file rather than beside the screen so nothing in
 * the production bundle can import them by accident.
 *
 * Run with: pnpm --filter @betweenus/admin check
 */
