import { useEffect, useState, type FormEvent } from 'react';
import type { OAuthProviderSummary, PublicUser } from '@betweenus/shared-types';
import { api } from '../api';
import { adminOnly, messageOf } from '../App';

export function LoginScreen({
  onSignedIn,
  initialError,
}: {
  onSignedIn: (user: PublicUser) => void;
  /** A provider round trip that came back refused; it happened before this screen. */
  initialError?: string | null;
}): JSX.Element {
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(initialError ?? null);
  const [busy, setBusy] = useState(false);
  const [providers, setProviders] = useState<OAuthProviderSummary[]>([]);

  // Providers are whatever the operator switched on, so the buttons are drawn
  // from the server rather than hard-coded; none configured means none shown.
  useEffect(() => {
    api
      .signInProviders()
      .then(setProviders)
      .catch(() => setProviders([]));
  }, []);

  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    setBusy(true);
    setError(null);
    try {
      const result = await api.login(identifier.trim(), password);
      const refused = adminOnly(result);
      if (refused) {
        setError(refused);
        return;
      }
      onSignedIn(result.user);
    } catch (caught) {
      setError(messageOf(caught));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="grid h-full place-items-center px-4">
      <form onSubmit={submit} className="w-full max-w-sm rounded-xl bg-surface-800 p-8 shadow-2xl" noValidate>
        <h1 className="mb-1 text-2xl font-semibold text-slate-50">BetweenUs Admin</h1>
        <p className="mb-6 text-sm text-slate-400">Sign in with your administrator account.</p>

        <label htmlFor="identifier" className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400">
          Username or email
        </label>
        <input
          id="identifier"
          autoFocus
          autoComplete="username"
          value={identifier}
          onChange={(event) => setIdentifier(event.target.value)}
          className="mb-4 w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-slate-100 placeholder-slate-500 focus:border-accent"
          placeholder="betweenusadmin"
        />

        <label htmlFor="password" className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400">
          Password
        </label>
        <input
          id="password"
          type="password"
          autoComplete="current-password"
          value={password}
          onChange={(event) => setPassword(event.target.value)}
          className="w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-slate-100 focus:border-accent"
        />

        {error && (
          <p role="alert" className="mt-4 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
            {error}
          </p>
        )}

        <button
          type="submit"
          disabled={busy}
          className="mt-6 w-full cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-60"
        >
          {busy ? 'Signing in…' : 'Sign in'}
        </button>

        {providers.length > 0 && (
          <>
            <p className="my-4 text-center text-xs uppercase tracking-wide text-slate-500">or</p>
            {providers.map((provider) => (
              <a
                key={provider.provider}
                // A full navigation, not fetch: the provider's own screen has to
                // be a real browser page the person can see the address of.
                href={api.signInUrl(provider.provider)}
                className="mb-2 block rounded-md border border-surface-700 px-4 py-2.5 text-center text-slate-200 transition-colors duration-200 hover:border-accent"
              >
                Continue with {provider.label}
              </a>
            ))}
          </>
        )}
      </form>
    </div>
  );
}

import { useEffect, useState, type FormEvent } from 'react';
import type { AdminSmtpSettings } from '@betweenus/shared-types';
import { api } from '../api';
import { messageOf } from '../App';

/**
 * The deployment's outgoing mail server.
 *
 * It is what decides whether anybody on this deployment can reset a forgotten
 * password on their own. With nothing here every client's forgot-password
 * screen says "ask your administrator" instead of offering to send anything -
 * which is the honest answer for a self-hosted deployment that has no mail
 * server and does not want one, and is why this screen is optional rather than
 * a step in setup.
 */
export function MailScreen(): JSX.Element {
  const [settings, setSettings] = useState<AdminSmtpSettings | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api
      .smtp()
      .then(setSettings)
      .catch((caught: unknown) => setError(messageOf(caught)));
  }, []);

  if (error) {
    return (
      <p role="alert" className="rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
        {error}
      </p>
    );
  }
  if (!settings) return <p className="text-sm text-slate-500">Loading…</p>;

  return <MailForm settings={settings} onSaved={setSettings} />;
}

function MailForm({
  settings,
  onSaved,
}: {
  settings: AdminSmtpSettings;
  onSaved: (settings: AdminSmtpSettings) => void;
}): JSX.Element {
  const [enabled, setEnabled] = useState(settings.enabled);
  const [host, setHost] = useState(settings.host);
  const [port, setPort] = useState(String(settings.port));
  const [secure, setSecure] = useState(settings.secure);
  const [username, setUsername] = useState(settings.username);
  const [password, setPassword] = useState('');
  const [fromAddress, setFromAddress] = useState(settings.fromAddress);
  const [fromName, setFromName] = useState(settings.fromName);
  const [testTo, setTestTo] = useState('');
  const [status, setStatus] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const save = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    setBusy(true);
    setError(null);
    setStatus(null);
    try {
      // An empty password field means "keep the stored one" - it can never be
      // shown back, so the form has to be savable without retyping it.
      const saved = await api.updateSmtp({
        enabled,
        host: host.trim(),
        port: Number(port) || 587,
        secure,
        username: username.trim(),
        ...(password.trim() ? { password: password.trim() } : {}),
        fromAddress: fromAddress.trim(),
        fromName: fromName.trim(),
      });
      setPassword('');
      setStatus('Saved.');
      onSaved(saved);
    } catch (caught) {
      setError(messageOf(caught));
      setEnabled(settings.enabled);
    } finally {
      setBusy(false);
    }
  };

  /**
   * The transport's own refusal is shown verbatim rather than flattened into
   * "failed". "535 authentication failed" and "getaddrinfo ENOTFOUND" are two
   * different afternoons, and this is the only screen anybody reads the
   * difference on.
   */
  const test = async (): Promise<void> => {
    setBusy(true);
    setError(null);
    setStatus(null);
    try {
      const result = await api.testSmtp(testTo.trim() || undefined);
      if (result.ok) setStatus('Test message sent.');
      else setError(result.error ?? 'The mail server refused it.');
    } catch (caught) {
      setError(messageOf(caught));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section className="space-y-6">
      <article className="rounded-lg border border-surface-700 bg-surface-800 p-6">
        <header className="mb-4 flex items-center gap-3">
          <h2 className="text-lg font-semibold text-slate-50">Outgoing mail (SMTP)</h2>
          <span
            className={`rounded px-2 py-0.5 text-xs ${
              settings.enabled
                ? 'bg-emerald-500/15 text-emerald-300'
                : 'bg-surface-700 text-slate-400'
            }`}
          >
            {settings.enabled ? 'enabled' : 'disabled'}
          </span>
        </header>

        <p className="mb-5 text-sm text-slate-400">
          With no mail server configured, the forgot-password screen tells people to ask an
          administrator, and you reset an account from the Users tab instead. Nothing else on
          BetweenUs sends email.
        </p>

        <form onSubmit={(event) => void save(event)} className="grid gap-4 sm:grid-cols-2">
          <Field id="smtp-host" label="Host" value={host} onChange={setHost} placeholder="smtp.example.com" />
          <Field id="smtp-port" label="Port" value={port} onChange={setPort} placeholder="587" />
          <Field
            id="smtp-username"
            label="Username"
            value={username}
            onChange={setUsername}
            placeholder="Blank for an unauthenticated relay"
          />
          <Field
            id="smtp-password"
            label="Password"
            type="password"
            value={password}
            onChange={setPassword}
            placeholder={settings.hasPassword ? 'Stored - leave blank to keep' : 'Optional'}
          />
          <Field
            id="smtp-from"
            label="From address"
            value={fromAddress}
            onChange={setFromAddress}
            placeholder="betweenus@example.com"
          />
          <Field id="smtp-from-name" label="From name" value={fromName} onChange={setFromName} />

          <div className="sm:col-span-2 flex flex-wrap items-center gap-5">
            <label className="flex cursor-pointer items-center gap-2 text-sm text-slate-300">
              <input
                type="checkbox"
                checked={secure}
                onChange={(event) => setSecure(event.target.checked)}
                className="h-4 w-4 cursor-pointer accent-accent"
              />
              Implicit TLS (port 465)
            </label>

            <label className="flex cursor-pointer items-center gap-2 text-sm text-slate-300">
              <input
                type="checkbox"
                checked={enabled}
                onChange={(event) => setEnabled(event.target.checked)}
                className="h-4 w-4 cursor-pointer accent-accent"
              />
              Send password reset emails
            </label>

            <button
              type="submit"
              disabled={busy}
              className="cursor-pointer rounded-md bg-accent px-4 py-2 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-60"
            >
              {busy ? 'Saving…' : 'Save'}
            </button>
          </div>
        </form>

        <div className="mt-6 border-t border-surface-700 pt-5">
          <p className="mb-3 text-sm text-slate-400">
            Send one message, so the settings are proved before somebody needs them.
          </p>
          <div className="flex flex-wrap items-center gap-3">
            <input
              value={testTo}
              onChange={(event) => setTestTo(event.target.value)}
              aria-label="Send the test to"
              placeholder="Your own address by default"
              className="w-72 rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-sm text-slate-100 placeholder-slate-500 focus:border-accent"
            />
            <button
              type="button"
              onClick={() => void test()}
              disabled={busy}
              className="cursor-pointer rounded-md border border-surface-700 px-4 py-2 text-sm text-slate-300 transition-colors duration-200 hover:border-accent disabled:cursor-not-allowed disabled:opacity-60"
            >
              Send test
            </button>

            {status && <span className="text-sm text-emerald-300">{status}</span>}
            {error && (
              <span role="alert" className="text-sm text-red-300">
                {error}
              </span>
            )}
          </div>
        </div>
      </article>
    </section>
  );
}

function Field({
  id,
  label,
  value,
  onChange,
  placeholder,
  type = 'text',
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
}): JSX.Element {
  return (
    <div>
      <label
        htmlFor={id}
        className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400"
      >
        {label}
      </label>
      <input
        id={id}
        type={type}
        value={value}
        placeholder={placeholder}
        onChange={(event) => onChange(event.target.value)}
        className="w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-sm text-slate-100 placeholder-slate-500 focus:border-accent"
      />
    </div>
  );
}

import { useEffect, useState } from 'react';
import type { AdminOAuthProvider } from '@betweenus/shared-types';
import { api } from '../api';
import { messageOf } from '../App';

/**
 * Google and GitHub sign-in, configured here rather than in the environment.
 * Turning a provider on makes its button appear on every client's login screen.
 */
export function OAuthScreen(): JSX.Element {
  const [providers, setProviders] = useState<AdminOAuthProvider[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api
      .oauthProviders()
      .then(setProviders)
      .catch((caught: unknown) => setError(messageOf(caught)));
  }, []);

  return (
    <section className="space-y-6">
      {error && (
        <p role="alert" className="rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {error}
        </p>
      )}

      {providers.map((provider) => (
        <ProviderCard
          key={provider.provider}
          provider={provider}
          onSaved={(saved) =>
            setProviders((current) =>
              current.map((item) => (item.provider === saved.provider ? saved : item)),
            )
          }
        />
      ))}
    </section>
  );
}

function ProviderCard({
  provider,
  onSaved,
}: {
  provider: AdminOAuthProvider;
  onSaved: (provider: AdminOAuthProvider) => void;
}): JSX.Element {
  const [clientId, setClientId] = useState(provider.clientId);
  const [clientSecret, setClientSecret] = useState('');
  const [enabled, setEnabled] = useState(provider.enabled);
  const [status, setStatus] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const save = async (): Promise<void> => {
    setBusy(true);
    setError(null);
    setStatus(null);
    try {
      // An empty secret field means "keep the stored one" - it can never be
      // shown back, so the form has to be savable without retyping it.
      const saved = await api.updateOAuthProvider(provider.provider, {
        enabled,
        clientId: clientId.trim(),
        ...(clientSecret.trim() ? { clientSecret: clientSecret.trim() } : {}),
      });
      setClientSecret('');
      setStatus('Saved.');
      onSaved(saved);
    } catch (caught) {
      setError(messageOf(caught));
      setEnabled(provider.enabled);
    } finally {
      setBusy(false);
    }
  };

  return (
    <article className="rounded-lg border border-surface-700 bg-surface-800 p-6">
      <header className="mb-4 flex items-center gap-3">
        <h2 className="text-lg font-semibold text-slate-50">{provider.label}</h2>
        <span
          className={`rounded px-2 py-0.5 text-xs ${
            provider.enabled ? 'bg-emerald-500/15 text-emerald-300' : 'bg-surface-700 text-slate-400'
          }`}
        >
          {provider.enabled ? 'enabled' : 'disabled'}
        </span>
      </header>

      <p className="mb-4 text-sm text-slate-400">
        Add this as the authorised redirect URI in the {provider.label} console:
      </p>
      <pre className="mb-5 overflow-x-auto rounded bg-surface-950 px-3 py-2 font-mono text-xs text-emerald-300">
        {provider.callbackUrl}
      </pre>

      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label
            htmlFor={`${provider.provider}-id`}
            className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400"
          >
            Client ID
          </label>
          <input
            id={`${provider.provider}-id`}
            value={clientId}
            onChange={(event) => setClientId(event.target.value)}
            className="w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-sm text-slate-100 focus:border-accent"
          />
        </div>

        <div>
          <label
            htmlFor={`${provider.provider}-secret`}
            className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400"
          >
            Client secret
          </label>
          <input
            id={`${provider.provider}-secret`}
            type="password"
            value={clientSecret}
            onChange={(event) => setClientSecret(event.target.value)}
            placeholder={provider.hasSecret ? 'Stored - leave blank to keep' : 'Required'}
            className="w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-sm text-slate-100 placeholder-slate-500 focus:border-accent"
          />
        </div>
      </div>

      <div className="mt-5 flex items-center gap-4">
        <label className="flex cursor-pointer items-center gap-2 text-sm text-slate-300">
          <input
            type="checkbox"
            checked={enabled}
            onChange={(event) => setEnabled(event.target.checked)}
            className="h-4 w-4 cursor-pointer accent-accent"
          />
          Offer {provider.label} sign-in
        </label>

        <button
          type="button"
          onClick={() => void save()}
          disabled={busy}
          className="cursor-pointer rounded-md bg-accent px-4 py-2 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-60"
        >
          {busy ? 'Saving…' : 'Save'}
        </button>

        {status && <span className="text-sm text-emerald-300">{status}</span>}
        {error && (
          <span role="alert" className="text-sm text-red-300">
            {error}
          </span>
        )}
      </div>
    </article>
  );
}

import { useEffect, useState } from 'react';
import type { AdminUser } from '@betweenus/shared-types';
import { api } from '../api';
import { messageOf } from '../App';

/** Every account on the platform: who they are, and what may be done to them. */
export function UsersScreen({ currentUserId }: { currentUserId: string }): JSX.Element {
  const [query, setQuery] = useState('');
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Typing in the search box should not fire a request per keystroke.
    const timer = setTimeout(() => {
      setLoading(true);
      api
        .users(query)
        .then((page) => {
          // A new search starts a new list; it never appends to the old one.
          setUsers(page.users);
          setCursor(page.nextCursor);
          setError(null);
        })
        .catch((caught: unknown) => setError(messageOf(caught)))
        .finally(() => setLoading(false));
    }, 250);
    return () => clearTimeout(timer);
  }, [query]);

  const loadMore = async (): Promise<void> => {
    if (!cursor) return;
    setLoading(true);
    try {
      const page = await api.users(query, cursor);
      setUsers((current) => [...current, ...page.users]);
      setCursor(page.nextCursor);
    } catch (caught) {
      setError(messageOf(caught));
    } finally {
      setLoading(false);
    }
  };

  const act = async (action: Promise<AdminUser | void>, userId: string): Promise<void> => {
    setError(null);
    try {
      const updated = await action;
      setUsers((current) =>
        updated
          ? current.map((user) => (user.id === userId ? updated : user))
          : current.filter((user) => user.id !== userId),
      );
    } catch (caught) {
      setError(messageOf(caught));
    }
  };

  return (
    <section>
      <div className="mb-4 flex items-center gap-3">
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          aria-label="Search users"
          placeholder="Search by name, username or email"
          className="w-80 rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-sm text-slate-100 placeholder-slate-500 focus:border-accent"
        />
        <span className="text-sm text-slate-500">
          {loading
            ? 'Loading…'
            : `${users.length}${cursor ? '+' : ''} account${users.length === 1 ? '' : 's'}`}
        </span>
      </div>

      {error && (
        <p role="alert" className="mb-4 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {error}
        </p>
      )}

      <div className="overflow-x-auto rounded-lg border border-surface-700">
        <table className="w-full text-left text-sm">
          <thead className="bg-surface-800 text-xs uppercase tracking-wide text-slate-400">
            <tr>
              <th scope="col" className="px-4 py-3">User</th>
              <th scope="col" className="px-4 py-3">Sign-in</th>
              <th scope="col" className="px-4 py-3">Servers</th>
              <th scope="col" className="px-4 py-3">Joined</th>
              <th scope="col" className="px-4 py-3">Status</th>
              <th scope="col" className="px-4 py-3 text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user.id} className="border-t border-surface-700/60">
                <td className="px-4 py-3">
                  <div className="font-medium text-slate-100">{user.displayName}</div>
                  <div className="text-xs text-slate-500">
                    @{user.username} · {user.email}
                  </div>
                </td>
                <td className="px-4 py-3 text-slate-400">
                  {user.identities.length > 0 ? user.identities.join(', ') : 'password'}
                </td>
                <td className="px-4 py-3 text-slate-400">{user.serverCount}</td>
                <td className="px-4 py-3 text-slate-400">
                  {new Date(user.createdAt).toLocaleDateString()}
                </td>
                <td className="px-4 py-3">
                  <div className="flex flex-wrap gap-1">
                    {user.role === 'ADMIN' && <Badge tone="accent">admin</Badge>}
                    {user.disabledAt && <Badge tone="danger">disabled</Badge>}
                    {user.mustChangePassword && <Badge tone="muted">password pending</Badge>}
                    {resetOpen(user) && <Badge tone="accent">reset open</Badge>}
                    {user.id === currentUserId && <Badge tone="muted">you</Badge>}
                  </div>
                </td>
                <td className="px-4 py-3">
                  <div className="flex justify-end gap-2">
                    <Action
                      onClick={() =>
                        void act(
                          api.updateUser(user.id, {
                            role: user.role === 'ADMIN' ? 'USER' : 'ADMIN',
                          }),
                          user.id,
                        )
                      }
                    >
                      {user.role === 'ADMIN' ? 'Revoke admin' : 'Make admin'}
                    </Action>
                    <Action
                      onClick={() =>
                        void act(
                          api.updateUser(user.id, { disabled: user.disabledAt === null }),
                          user.id,
                        )
                      }
                    >
                      {user.disabledAt ? 'Enable' : 'Disable'}
                    </Action>
                    <Action
                      onClick={() => {
                        // The strongest thing this panel can say about somebody:
                        // for the next day they can set a password without
                        // knowing the old one. Worth a sentence and a click.
                        if (
                          !resetOpen(user) &&
                          !confirm(
                            `Let ${user.username} set a new password without the old one?\n\n` +
                              'They enter their username on the forgot-password screen and are ' +
                              'taken straight to a new-password form. The permission expires ' +
                              'on its own and is used once.',
                          )
                        ) {
                          return;
                        }
                        void act(
                          api.updateUser(user.id, { passwordReset: !resetOpen(user) }),
                          user.id,
                        );
                      }}
                    >
                      {resetOpen(user) ? 'Cancel reset' : 'Reset password'}
                    </Action>
                    <Action
                      danger
                      onClick={() => {
                        // Deletion cascades through messages and memberships.
                        if (!confirm(`Delete ${user.username}? This cannot be undone.`)) return;
                        void act(api.deleteUser(user.id), user.id);
                      }}
                    >
                      Delete
                    </Action>
                  </div>
                </td>
              </tr>
            ))}

            {!loading && users.length === 0 && (
              <tr>
                <td colSpan={6} className="px-4 py-8 text-center text-slate-500">
                  No accounts match that search.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {cursor && (
        <button
          type="button"
          disabled={loading}
          onClick={() => void loadMore()}
          className="mt-4 w-full cursor-pointer rounded-md border border-surface-700 px-4 py-2 text-sm text-slate-300 transition-colors duration-200 hover:border-accent disabled:cursor-not-allowed disabled:opacity-60"
        >
          {loading ? 'Loading…' : 'Load more'}
        </button>
      )}
    </section>
  );
}

/** True while the administrator-granted reset window is still in the future. */
function resetOpen(user: AdminUser): boolean {
  return user.passwordResetUntil !== null && new Date(user.passwordResetUntil) > new Date();
}

function Badge({
  tone,
  children,
}: {
  tone: 'accent' | 'danger' | 'muted';
  children: string;
}): JSX.Element {
  const tones = {
    accent: 'bg-accent/15 text-accent',
    danger: 'bg-red-500/15 text-red-300',
    muted: 'bg-surface-700 text-slate-300',
  } as const;
  return <span className={`rounded px-1.5 py-0.5 text-xs ${tones[tone]}`}>{children}</span>;
}

function Action({
  children,
  onClick,
  danger,
}: {
  children: string;
  onClick: () => void;
  danger?: boolean;
}): JSX.Element {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`cursor-pointer rounded border border-surface-700 px-2 py-1 text-xs transition-colors duration-200 ${
        danger ? 'text-red-300 hover:border-red-500' : 'text-slate-300 hover:border-accent'
      }`}
    >
      {children}
    </button>
  );
}

