/**
 * Crop and rotate a picture before it is sent or stored.
 *
 * The port of `apps/desktop/src/components/ImageEditor.tsx`, and the arithmetic
 * that makes the written file match what was framed is shared with it through
 * [ImageEdit] - which is the only part worth being careful about, and the only
 * part that is tested.
 *
 * Drag to move, pinch or drag the slider to zoom, two buttons to turn. The
 * frame is the crop: what is inside it when Done is pressed is what gets
 * written, to a file in the cache that the caller then treats like any other
 * picked file.
 */
@Composable
fun ImageEditorDialog(
    source: Uri,
    title: String,
    /** Width over height. 1 for an avatar; the picture's own when null. */
    aspect: Float? = null,
    /** The longest edge of the written file. Never upscales past the source. */
    maxOutputEdge: Int = 2048,
    onCancel: () -> Unit,
    onDone: (Uri) -> Unit,
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val density = LocalDensity.current

    var bitmap by remember(source) { mutableStateOf<Bitmap?>(null) }
    var failure by remember(source) { mutableStateOf<String?>(null) }
    var edit by remember(source) { mutableStateOf(ImageEdit.NONE) }
    var busy by remember(source) { mutableStateOf(false) }

    /**
     * The crop box, in device pixels. Measured where it is drawn and held here
     * because Done needs it too: the frame *is* the crop, so writing the file
     * without it would be writing a different picture from the one on screen.
     */
    var frame by remember(source) { mutableStateOf(ImageEdit.Size(1f, 1f)) }

    LaunchedEffect(source) {
        // Downsampled: the editor never needs more pixels than the screen can
        // show, and a 50 megapixel photo decoded whole is an out-of-memory
        // crash on the phones most likely to have taken one. The crop is
        // written from this same bitmap, so the ceiling is deliberately
        // generous rather than screen-sized.
        bitmap = decodeForEditing(context, source)
        if (bitmap == null) failure = "That file could not be read as a picture"
    }

    Dialog(
        onDismissRequest = { if (!busy) onCancel() },
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        Column(
            Modifier
                .fillMaxSize()
                .background(Surface950)
                .statusBarsPadding()
                .navigationBarsPadding(),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(6.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                IconAction(BetweenUsIcons.X, "Cancel", { if (!busy) onCancel() })
                Text(
                    text = title,
                    style = MaterialTheme.typography.titleSmall,
                    color = Slate100,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f).padding(start = 6.dp),
                )
            }

            BoxWithConstraints(
                modifier = Modifier.weight(1f).fillMaxWidth().background(Color.Black),
                contentAlignment = Alignment.Center,
            ) {
                val picture = bitmap
                if (picture == null) {
                    if (failure == null) {
                        CircularProgressIndicator(Modifier.size(28.dp))
                    }
                } else {
                    // The frame is the largest box of the wanted shape that fits
                    // the space, in device pixels - the same unit every offset
                    // and every scale in ImageEdit is measured in.
                    val boxWidth = with(density) { maxWidth.toPx() } * 0.92f
                    val boxHeight = with(density) { maxHeight.toPx() } * 0.92f
                    val ratio = aspect ?: (picture.width.toFloat() / picture.height)
                    val measured = fit(boxWidth, boxHeight, ratio)
                    // After composition rather than during it: writing state
                    // while composing the same subtree is how a recomposition
                    // loop starts, and this one settles on the first pass.
                    SideEffect { if (measured != frame) frame = measured }

                    Box(
                        modifier = Modifier
                            .size(
                                width = with(density) { frame.width.toDp() },
                                height = with(density) { frame.height.toDp() },
                            )
                            .background(Color.Black)
                            .pointerInput(picture, frame, edit.rotation) {
                                detectTransformGestures { _, pan, zoom, _ ->
                                    edit = ImageEdit.clamp(
                                        image = picture.size(),
                                        frame = frame,
                                        edit = edit.copy(
                                            zoom = edit.zoom * zoom,
                                            offsetX = edit.offsetX + pan.x,
                                            offsetY = edit.offsetY + pan.y,
                                        ),
                                    )
                                }
                            },
                        contentAlignment = Alignment.Center,
                    ) {
                        val scale =
                            ImageEdit.coverScale(picture.size(), frame, edit.rotation) * edit.zoom
                        androidx.compose.foundation.Image(
                            bitmap = picture.asImageBitmap(),
                            contentDescription = title,
                            contentScale = ContentScale.None,
                            modifier = Modifier
                                .size(
                                    width = with(density) { picture.width.toFloat().toDp() },
                                    height = with(density) { picture.height.toFloat().toDp() },
                                )
                                .graphicsLayer(
                                    // Compose applies rotation and scale about
                                    // the centre and then translates, which is
                                    // the order ImageEdit.drawEdit replays.
                                    rotationZ = edit.rotation.toFloat(),
                                    scaleX = scale,
                                    scaleY = scale,
                                    translationX = edit.offsetX,
                                    translationY = edit.offsetY,
                                    clip = false,
                                ),
                        )
                    }
                }
            }

            failure?.let {
                Text(
                    text = it,
                    style = MaterialTheme.typography.bodySmall,
                    color = Danger,
                    modifier = Modifier.padding(horizontal = 16.dp, vertical = 6.dp),
                )
            }

            val picture = bitmap
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                IconAction(BetweenUsIcons.RotateLeft, "Rotate left", {
                    if (!busy) edit = ImageEdit.Edit(rotation = ImageEdit.rotate(edit.rotation, -1))
                })
                Slider(
                    value = edit.zoom,
                    onValueChange = { zoom ->
                        val shown = picture ?: return@Slider
                        // Clamped through the same function the gesture uses:
                        // zooming out has to pull the picture back over the
                        // frame, or the edge it was dragged past stays showing.
                        edit = ImageEdit.clamp(shown.size(), frame, edit.copy(zoom = zoom))
                    },
                    valueRange = 1f..ImageEdit.MAX_ZOOM,
                    enabled = !busy && picture != null,
                    modifier = Modifier.weight(1f),
                )
                IconAction(BetweenUsIcons.RotateRight, "Rotate right", {
                    if (!busy) edit = ImageEdit.Edit(rotation = ImageEdit.rotate(edit.rotation, 1))
                })
            }

            Row(
                modifier = Modifier.fillMaxWidth().padding(16.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text(
                    text = "Drag to move, pinch to zoom",
                    style = MaterialTheme.typography.bodySmall,
                    color = Slate500,
                    modifier = Modifier.weight(1f),
                )
                Chip(text = "Cancel", onClick = { if (!busy) onCancel() })
                Chip(
                    text = if (busy) "Working…" else "Done",
                    onClick = {
                        val picked = bitmap ?: return@Chip
                        if (busy) return@Chip
                        busy = true
                        scope.launch {
                            val written = runCatching {
                                writeEdited(context, picked, frame, edit, maxOutputEdge)
                            }
                            busy = false
                            written.getOrNull()?.let(onDone)
                                ?: run { failure = "That picture could not be written" }
                        }
                    },
                )
            }
        }
    }
}

private fun Bitmap.size() = ImageEdit.Size(width.toFloat(), height.toFloat())

/** The largest box of the given shape that fits inside the space. */
private fun fit(width: Float, height: Float, ratio: Float): ImageEdit.Size =
    if (width / height > ratio) ImageEdit.Size(height * ratio, height)
    else ImageEdit.Size(width, width / ratio)

/** Big enough to crop from, small enough not to be an out-of-memory crash. */
private const val MAX_EDIT_EDGE_PX = 2560

private suspend fun decodeForEditing(context: Context, uri: Uri): Bitmap? =
    withContext(Dispatchers.IO) {
        runCatching {
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            context.contentResolver.openInputStream(uri)?.use {
                BitmapFactory.decodeStream(it, null, bounds)
            }
            val options = BitmapFactory.Options().apply {
                inSampleSize = sampleSizeFor(bounds.outWidth, bounds.outHeight, MAX_EDIT_EDGE_PX)
            }
            context.contentResolver.openInputStream(uri)?.use {
                BitmapFactory.decodeStream(it, null, options)
            }
        }.getOrNull()
    }

private suspend fun writeEdited(
    context: Context,
    source: Bitmap,
    frame: ImageEdit.Size,
    edit: ImageEdit.Edit,
    maxOutputEdge: Int,
): Uri = withContext(Dispatchers.IO) {
    val output = ImageEdit.outputSize(source.size(), frame, edit, maxOutputEdge)
    val cropped = ImageEdit.drawEdit(source, frame, output, edit)
    val directory = File(context.cacheDir, "edited").apply { mkdirs() }
    val file = File(directory, "edited-${System.currentTimeMillis()}.jpg")
    file.outputStream().use { cropped.compress(Bitmap.CompressFormat.JPEG, 92, it) }
    cropped.recycle()
    androidx.core.content.FileProvider.getUriForFile(context, "${context.packageName}.files", file)
}

package com.aatech.betweenus.feature.chat

import android.graphics.Bitmap
import android.net.Uri
import android.util.LruCache
import java.io.File
import java.util.concurrent.ConcurrentHashMap

/**
 * What has already been decrypted, kept for as long as the app is running.
 *
 * A `LazyColumn` throws a row away the moment it leaves the screen and builds a
 * new one when it comes back. Every piece of state a row held goes with it, and
 * for an attachment that state was the whole of the work: the ciphertext had
 * been downloaded, decrypted under the channel key, and decoded into a bitmap -
 * and scrolling a picture off the top and back threw all three away and did
 * them again. That is what "it goes back to loading" was. Not a slow network: a
 * cache that did not exist.
 *
 * The desktop has had one since attachments landed - a `Map` of blobs in
 * `services/attachments.ts` - and this is the same idea with the same bound.
 * Keyed on the attachment key, which is the object's name in storage: unique
 * per file, and the same across every message that carries it.
 *
 * Bitmaps are the expensive half and are held under a memory budget, so a long
 * scroll through a channel of photos drops the oldest rather than growing until
 * the process is killed. Videos are cached as the `Uri` of the plaintext file
 * already written into the app's cache directory - the bytes are on disk
 * either way, and it is Android that decides when that directory is cleared.
 */
object MediaCache {

    /**
     * An eighth of the heap. The conventional share for a bitmap cache: enough
     * that a screen or two of photos survives a scroll, small enough that the
     * rest of the app is not squeezed out by pictures nobody is looking at.
     */
    private val bitmaps = object : LruCache<String, Bitmap>(
        ((Runtime.getRuntime().maxMemory() / 1024) / 8).toInt().coerceAtLeast(4 * 1024),
    ) {
        // The cache is measured in kilobytes, so the sizes stay inside an Int.
        override fun sizeOf(key: String, value: Bitmap): Int = value.byteCount / 1024
    }

    /** Small, and read from whichever thread a row happens to compose on. */
    private val videos = ConcurrentHashMap<String, Uri>()

    fun bitmap(key: String): Bitmap? = bitmaps.get(key)

    fun putBitmap(key: String, bitmap: Bitmap) {
        bitmaps.put(key, bitmap)
    }

    /** A video's first frame is a bitmap too, under a key of its own. */
    fun poster(key: String): Bitmap? = bitmaps.get(posterKey(key))

    fun putPoster(key: String, frame: Bitmap) {
        bitmaps.put(posterKey(key), frame)
    }

    fun video(key: String): Uri? = videos[key]

    fun putVideo(key: String, uri: Uri) {
        videos[key] = uri
    }

    /**
     * Forgets specific attachments: a deleted message's, a burned one's, or
     * one whose disappearing window closed.
     *
     * The video half matters more than the bitmap half. A bitmap is memory and
     * goes when the process does; a decrypted video is a real file in the
     * app's cache directory, and without this it outlived the message by
     * however long Android took to decide the directory was worth clearing.
     * Deleting a photo is supposed to mean deleting the photo.
     */
    fun forget(keys: Collection<String>) {
        for (key in keys) {
            bitmaps.remove(key)
            bitmaps.remove(posterKey(key))
            // The `Uri` is one this app wrote, so the file behind it is one
            // this app may remove. A path it cannot resolve is one it never
            // wrote, and is left alone.
            videos.remove(key)?.path?.let { path -> runCatching { File(path).delete() } }
        }
    }

    /**
     * Emptied on sign-out: the plaintext of another account's conversation has
     * no business surviving into the next one.
     */
    fun clear() {
        bitmaps.evictAll()
        // The files too, not only the map that named them: the decrypted
        // videos are on disk, and signing out should not leave them there.
        for (uri in videos.values) uri.path?.let { path -> runCatching { File(path).delete() } }
        videos.clear()
    }

    private fun posterKey(key: String): String = "$key#poster"
}

package com.aatech.betweenus.feature.chat

import android.content.ContentUris
import android.content.Context
import android.net.Uri
import android.provider.MediaStore
import android.provider.OpenableColumns
import android.webkit.MimeTypeMap
import androidx.core.content.FileProvider
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File

/** One item in the attachment sheet's grid. */
data class MediaItem(val uri: Uri, val isVideo: Boolean)

/** A file about to become an attachment, read and named. */
data class PickedFile(val name: String, val contentType: String, val bytes: ByteArray) {
    // A data class holding a ByteArray compares by reference and hashes by
    // identity unless told otherwise, which is a trap rather than a decision.
    override fun equals(other: Any?): Boolean =
        other is PickedFile && name == other.name && contentType == other.contentType &&
            bytes.contentEquals(other.bytes)

    override fun hashCode(): Int =
        31 * (31 * name.hashCode() + contentType.hashCode()) + bytes.contentHashCode()
}

/**
 * The phone's photos and videos, newest first.
 *
 * One query across `MediaStore.Files` rather than one per type, because the two
 * have to come back interleaved by date - a grid that showed every photo and
 * then every video would put this morning's clip below last year's screenshot.
 *
 * Whoever calls this has already been granted something; on API 34 that may be
 * "only these photos", and then this returns exactly those, which is correct
 * and not an error.
 */
suspend fun recentMedia(context: Context, limit: Int = 90): List<MediaItem> =
    withContext(Dispatchers.IO) {
        // "external" rather than `MediaStore.VOLUME_EXTERNAL`, which is API 29
        // and this module still runs on 24.
        val collection = MediaStore.Files.getContentUri("external")
        val columns = arrayOf(MediaStore.Files.FileColumns._ID, MediaStore.Files.FileColumns.MEDIA_TYPE)
        val image = MediaStore.Files.FileColumns.MEDIA_TYPE_IMAGE
        val video = MediaStore.Files.FileColumns.MEDIA_TYPE_VIDEO

        runCatching {
            context.contentResolver.query(
                collection,
                columns,
                "${MediaStore.Files.FileColumns.MEDIA_TYPE} IN (?, ?)",
                arrayOf(image.toString(), video.toString()),
                // No SQL LIMIT: MediaStore stopped honouring one appended to
                // the sort order, and the cursor is walked with a bound anyway.
                "${MediaStore.Files.FileColumns.DATE_MODIFIED} DESC",
            )?.use { cursor ->
                val idColumn = cursor.getColumnIndexOrThrow(MediaStore.Files.FileColumns._ID)
                val typeColumn = cursor.getColumnIndexOrThrow(MediaStore.Files.FileColumns.MEDIA_TYPE)
                buildList {
                    while (cursor.moveToNext() && size < limit) {
                        add(
                            MediaItem(
                                uri = ContentUris.withAppendedId(collection, cursor.getLong(idColumn)),
                                isVideo = cursor.getInt(typeColumn) == video,
                            ),
                        )
                    }
                }
            }.orEmpty()
        }.getOrDefault(emptyList())
    }

/**
 * Reads a picked URI and gives it the name it is actually called.
 *
 * The last path segment is not a filename. For anything the document browser
 * or the photo picker returns it is an opaque id - `image:1000012345`, `msf:42`
 * - so every attachment sent from a phone arrived on the other clients called
 * something like that, with no extension for anything to open it by. The name
 * lives in `OpenableColumns.DISPLAY_NAME`, and the provider is the only thing
 * that knows it.
 */
suspend fun readPicked(context: Context, uri: Uri): PickedFile = withContext(Dispatchers.IO) {
    val described = describe(context, uri)
    val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
        ?: error("That file could not be read")

    PickedFile(described.name, described.contentType, bytes)
}

/**
 * Everything knowable about a picked URI without opening it.
 *
 * One resolver for both callers, because they used to have one each and the
 * two did not agree: `describePicked` answered at pick time and `readPicked`
 * answered again at send time, and whichever was worse is the one that reached
 * the wire. Now there is a single answer and a single place to fix it.
 *
 * The order of what is asked matters, and it is the order in `PickedNames.kt`:
 * the provider first, then the URI, then a generated name carrying the right
 * extension. Every step exists because a real provider skipped the one above
 * it - the document browser gives an opaque id for a name, and a `file://` URI
 * has no provider to ask at all.
 */
private fun describe(context: Context, uri: Uri): PickedPreview {
    val resolver = context.contentResolver

    val displayName = runCatching {
        resolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor ->
            val column = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
            if (column >= 0 && cursor.moveToFirst()) cursor.getString(column) else null
        }
    }.getOrNull()

    // A `file://` URI has nothing to query, and `getType` on one answers from
    // the extension - so the name has to be worked out before the type, or the
    // type has nothing to be guessed from.
    val provided = runCatching { resolver.getType(uri) }.getOrNull()
    val fromSystem = if (typeIsUseful(provided)) provided else guessType(uri, displayName)

    val name = pickedName(displayName, uri.lastPathSegment, fromSystem ?: OPAQUE_TYPE)
    return PickedPreview(uri = uri, name = name, contentType = pickedType(fromSystem, name))
}

/**
 * The platform's own extension-to-type table, for anything not in ours.
 *
 * Wrapped because `MimeTypeMap` is an Android class: in a JVM unit test it is
 * an unmocked stub that throws, and this path is a fallback rather than
 * something worth failing a send over.
 */
private fun guessType(uri: Uri, displayName: String?): String? {
    val name = displayName?.takeIf { it.isNotBlank() } ?: nameFromSegment(uri.lastPathSegment) ?: return null
    val extension = name.substringAfterLast('.', "").lowercase()
    if (extension.isEmpty()) return null
    return runCatching {
        MimeTypeMap.getSingleton().getMimeTypeFromExtension(extension)
    }.getOrNull()
}

/**
 * Name and kind without reading the file.
 *
 * The send preview needs to label what was picked and decide whether to draw a
 * player or a picture; reading a 200 MB video into memory to answer that would
 * be absurd, and the content resolver answers both from the index.
 */
suspend fun describePicked(context: Context, uri: Uri): PickedPreview =
    withContext(Dispatchers.IO) { describe(context, uri) }

/** Somewhere for the camera app to put a photo, and a URI it may write to. */
fun cameraTarget(context: Context): Uri {
    val directory = File(context.cacheDir, "camera").apply { mkdirs() }
    val file = File(directory, "photo-${System.currentTimeMillis()}.jpg")
    return FileProvider.getUriForFile(context, "${context.packageName}.files", file)
}

/**
 * A picked file, made ready to send.
 *
 * The one thing that happens between the picker and the upload: a video is
 * re-encoded smaller. Everything else is read as it stands - pictures are
 * already normalised on the way through `Conversation.uploadAttachment`, and a
 * document has nothing to normalise.
 *
 * A temporary file the compressor wrote is deleted once it has been read, so
 * the cache does not fill up with copies of everything anybody has ever sent.
 */
suspend fun prepareForSending(
    context: Context,
    uri: Uri,
    name: String,
    contentType: String,
    onCompress: (Float) -> Unit = {},
): PickedFile {
    if (!contentType.startsWith("video/")) {
        // The bytes are read fresh; the name and the type are not re-derived.
        //
        // This used to `return readPicked(...)` and throw away both arguments,
        // which meant the send used a second lookup made minutes later in a
        // different coroutine rather than the one the picker itself produced.
        // Whichever of the two was worse won, and for an audio file that was
        // reliably the second: it arrived called `attachment`, typed as bytes,
        // and drew as an anonymous document instead of something playable.
        val read = readPicked(context, uri)
        return PickedFile(
            name = name.ifBlank { read.name },
            // The caller's type unless it never had one either.
            contentType = if (typeIsUseful(contentType)) contentType else read.contentType,
            bytes = read.bytes,
        )
    }

    val prepared = compressVideo(context, uri, sizeOf(context, uri), onCompress)
    val read = readPicked(context, prepared.uri)
    if (prepared.temporary) {
        withContext(Dispatchers.IO) { runCatching { context.contentResolver.delete(prepared.uri, null, null) } }
    }
    // The compressor always writes MP4/H.264, whatever went in, and the name
    // has to say so: a file that lies about its type confuses every client
    // that opens it.
    return if (prepared.temporary) {
        PickedFile(
            name = name.substringBeforeLast('.', name) + ".mp4",
            contentType = "video/mp4",
            bytes = read.bytes,
        )
    } else {
        PickedFile(name = name, contentType = contentType, bytes = read.bytes)
    }
}

/** What the provider says the file weighs, or 0 when it will not say. */
suspend fun sizeOf(context: Context, uri: Uri): Long = withContext(Dispatchers.IO) {
    runCatching {
        context.contentResolver.query(uri, arrayOf(OpenableColumns.SIZE), null, null, null)
            ?.use { cursor ->
                val column = cursor.getColumnIndex(OpenableColumns.SIZE)
                if (column >= 0 && cursor.moveToFirst()) cursor.getLong(column) else 0L
            }
    }.getOrNull() ?: 0L
}

