/**
 * Formats a clean media file name with `bu_YYYYMMDD_HHmmss.ext` timestamp matching modern social apps.
 */
fun formatBuMediaName(originalName: String? = null, fallbackExt: String = "jpg"): String {
    val dateStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
    val ext = originalName?.substringAfterLast('.', "")?.takeIf { it.isNotBlank() } ?: fallbackExt
    return "bu_${dateStr}.${ext.lowercase(Locale.US)}"
}

/**
 * Fullscreen Interactive Image Viewer modal with pinch-to-zoom, pan, save to Pictures/BetweenUs album, and share.
 */
@Composable
fun ImageViewerDialog(
    bitmap: Bitmap,
    title: String,
    onDismiss: () -> Unit,
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    var scale by remember { mutableFloatStateOf(1f) }
    var offsetX by remember { mutableFloatStateOf(0f) }
    var offsetY by remember { mutableFloatStateOf(0f) }
    var saving by remember { mutableStateOf(false) }
    var savedMessage by remember { mutableStateOf<String?>(null) }

    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black.copy(alpha = 0.96f)),
        ) {
            // Main Zoomable Image View
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .pointerInput(Unit) {
                        detectTransformGestures { _, pan, zoom, _ ->
                            scale = (scale * zoom).coerceIn(1f, 5f)
                            if (scale > 1f) {
                                val maxOffsetX = (size.width * (scale - 1)) / 2
                                val maxOffsetY = (size.height * (scale - 1)) / 2
                                offsetX = (offsetX + pan.x * scale).coerceIn(-maxOffsetX, maxOffsetX)
                                offsetY = (offsetY + pan.y * scale).coerceIn(-maxOffsetY, maxOffsetY)
                            } else {
                                offsetX = 0f
                                offsetY = 0f
                            }
                        }
                    },
                contentAlignment = Alignment.Center,
            ) {
                Image(
                    bitmap = bitmap.asImageBitmap(),
                    contentDescription = title,
                    contentScale = ContentScale.Fit,
                    modifier = Modifier
                        .fillMaxSize()
                        .graphicsLayer(
                            scaleX = scale,
                            scaleY = scale,
                            translationX = offsetX,
                            translationY = offsetY,
                        ),
                )
            }

            // Top Header Bar
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.TopCenter)
                    .background(Color.Black.copy(alpha = 0.6f))
                    .statusBarsPadding()
                    .padding(horizontal = 12.dp, vertical = 8.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.weight(1f),
                ) {
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(Surface900)
                            .clickable(onClick = onDismiss),
                        contentAlignment = Alignment.Center,
                    ) {
                        BetweenUsIcon(BetweenUsIcons.X, tint = Slate100, size = 18.dp)
                    }

                    Text(
                        text = if (title.isBlank() || title.endsWith(".jpg", true) || title.endsWith(".jpeg", true) || title.endsWith(".png", true) || title.endsWith(".webp", true)) "Photo" else title,
                        style = MaterialTheme.typography.titleMedium,
                        color = Slate100,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    // Save to Pictures/BetweenUs button
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(Surface900)
                            .clickable(enabled = !saving) {
                                scope.launch {
                                    saving = true
                                    val uri = saveImageToStorage(context, bitmap, title)
                                    saving = false
                                    if (uri != null) {
                                        savedMessage = "Saved to Pictures/BetweenUs"
                                        Toast.makeText(context, "Saved to Pictures/BetweenUs", Toast.LENGTH_SHORT).show()
                                    } else {
                                        Toast.makeText(context, "Failed to save image", Toast.LENGTH_SHORT).show()
                                    }
                                }
                            },
                        contentAlignment = Alignment.Center,
                    ) {
                        if (saving) {
                            CircularProgressIndicator(modifier = Modifier.size(18.dp), strokeWidth = 2.dp, color = Accent)
                        } else {
                            BetweenUsIcon(BetweenUsIcons.Download, tint = if (savedMessage != null) StatusOnline else Accent, size = 18.dp)
                        }
                    }

                    // Share button
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(Surface900)
                            .clickable { shareBitmap(context, bitmap, title) },
                        contentAlignment = Alignment.Center,
                    ) {
                        BetweenUsIcon(BetweenUsIcons.ScreenShare, tint = Slate300, size = 18.dp)
                    }
                }
            }

            // Bottom Saved confirmation banner or Reset Zoom hint
            Column(
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .navigationBarsPadding()
                    .padding(bottom = 20.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                savedMessage?.let { msg ->
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(20.dp))
                            .background(Surface900.copy(alpha = 0.9f))
                            .padding(horizontal = 16.dp, vertical = 8.dp),
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp),
                        ) {
                            BetweenUsIcon(BetweenUsIcons.Check, tint = StatusOnline, size = 16.dp)
                            Text(
                                text = msg,
                                style = MaterialTheme.typography.labelSmall,
                                color = Slate100,
                                fontWeight = FontWeight.SemiBold,
                            )
                        }
                    }
                }

                if (scale > 1.2f) {
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(20.dp))
                            .background(Surface900.copy(alpha = 0.8f))
                            .clickable {
                                scale = 1f
                                offsetX = 0f
                                offsetY = 0f
                            }
                            .padding(horizontal = 16.dp, vertical = 8.dp),
                    ) {
                        Text(
                            text = "Reset Zoom (${(scale * 100).toInt()}%)",
                            style = MaterialTheme.typography.labelSmall,
                            color = Accent,
                            fontWeight = FontWeight.Bold,
                        )
                    }
                }
            }
        }
    }
}

/**
 * In-App Fullscreen Video Player Dialog with playback controls and save to Movies/BetweenUs.
 */
@Composable
fun VideoPlayerDialog(
    videoUri: Uri,
    title: String,
    onDismiss: () -> Unit,
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    var isReady by remember { mutableStateOf(false) }
    var saving by remember { mutableStateOf(false) }

    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black),
            contentAlignment = Alignment.Center,
        ) {
            AndroidView(
                factory = { ctx ->
                    VideoView(ctx).apply {
                        val controller = MediaController(ctx)
                        controller.setAnchorView(this)
                        setMediaController(controller)
                        setVideoURI(videoUri)
                        setOnPreparedListener { mp ->
                            isReady = true
                            mp.isLooping = true
                            start()
                        }
                        setOnErrorListener { _, _, _ ->
                            onDismiss()
                            true
                        }
                    }
                },
                modifier = Modifier.fillMaxSize(),
            )

            if (!isReady) {
                CircularProgressIndicator(color = Accent)
            }

            // Top Header Bar
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.TopCenter)
                    .background(Color.Black.copy(alpha = 0.6f))
                    .statusBarsPadding()
                    .padding(horizontal = 12.dp, vertical = 8.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.weight(1f),
                ) {
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(Surface900)
                            .clickable(onClick = onDismiss),
                        contentAlignment = Alignment.Center,
                    ) {
                        BetweenUsIcon(BetweenUsIcons.X, tint = Slate100, size = 18.dp)
                    }

                    Text(
                        text = if (title.isBlank() || title.endsWith(".mp4", true) || title.endsWith(".mov", true) || title.endsWith(".webm", true)) "Video" else title,
                        style = MaterialTheme.typography.titleMedium,
                        color = Slate100,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    // Save to Movies/BetweenUs button
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(Surface900)
                            .clickable(enabled = !saving) {
                                scope.launch {
                                    saving = true
                                    val bytes = runCatching {
                                        context.contentResolver.openInputStream(videoUri)?.use { it.readBytes() }
                                    }.getOrNull()
                                    if (bytes != null) {
                                        val uri = saveMediaToStorage(context, bytes, title, "video/mp4")
                                        if (uri != null) {
                                            Toast.makeText(context, "Saved to Movies/BetweenUs", Toast.LENGTH_SHORT).show()
                                        } else {
                                            Toast.makeText(context, "Failed to save video", Toast.LENGTH_SHORT).show()
                                        }
                                    }
                                    saving = false
                                }
                            },
                        contentAlignment = Alignment.Center,
                    ) {
                        if (saving) {
                            CircularProgressIndicator(modifier = Modifier.size(18.dp), strokeWidth = 2.dp, color = Accent)
                        } else {
                            BetweenUsIcon(BetweenUsIcons.Download, tint = Accent, size = 18.dp)
                        }
                    }

                    // External player button
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(Surface900)
                            .clickable { openExternalPlayer(context, videoUri) },
                        contentAlignment = Alignment.Center,
                    ) {
                        BetweenUsIcon(BetweenUsIcons.ScreenShare, tint = Slate300, size = 18.dp)
                    }
                }
            }
        }
    }
}

/**
 * Saves an image to the device gallery under Pictures/BetweenUs album with bu_YYYYMMDD_HHmmss.jpg naming.
 */
suspend fun saveImageToStorage(
    context: Context,
    bitmap: Bitmap,
    fileName: String? = null,
): Uri? = withContext(Dispatchers.IO) {
    runCatching {
        val resolver = context.contentResolver
        val safeName = formatBuMediaName(fileName, "jpg")

        val contentValues = ContentValues().apply {
            put(MediaStore.Images.Media.DISPLAY_NAME, safeName)
            put(MediaStore.Images.Media.MIME_TYPE, "image/jpeg")
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                put(MediaStore.Images.Media.RELATIVE_PATH, "Pictures/BetweenUs")
                put(MediaStore.Images.Media.IS_PENDING, 1)
            }
        }

        val uri = resolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues)
            ?: error("Could not insert image into MediaStore")

        resolver.openOutputStream(uri)?.use { stream ->
            bitmap.compress(Bitmap.CompressFormat.JPEG, 95, stream)
        }

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            contentValues.clear()
            contentValues.put(MediaStore.Images.Media.IS_PENDING, 0)
            resolver.update(uri, contentValues, null, null)
        }

        uri
    }.getOrNull()
}

/**
 * Saves decrypted media bytes (video, audio, image, document) to public storage under Pictures/BetweenUs,
 * Movies/BetweenUs, or Download/BetweenUs with standard social media timestamp naming.
 */
suspend fun saveMediaToStorage(
    context: Context,
    bytes: ByteArray,
    name: String,
    contentType: String,
): Uri? = withContext(Dispatchers.IO) {
    runCatching {
        val resolver = context.contentResolver
        val isVideo = contentType.startsWith("video/")
        val isImage = contentType.startsWith("image/")
        val isAudio = contentType.startsWith("audio/")

        val collection: Uri
        val relativeDir: String
        val mime: String
        val defaultExt: String

        when {
            isImage -> {
                collection = MediaStore.Images.Media.EXTERNAL_CONTENT_URI
                relativeDir = "Pictures/BetweenUs"
                mime = contentType.ifBlank { "image/jpeg" }
                defaultExt = "jpg"
            }
            isVideo -> {
                collection = MediaStore.Video.Media.EXTERNAL_CONTENT_URI
                relativeDir = "Movies/BetweenUs"
                mime = contentType.ifBlank { "video/mp4" }
                defaultExt = "mp4"
            }
            isAudio -> {
                collection = MediaStore.Audio.Media.EXTERNAL_CONTENT_URI
                relativeDir = "Music/BetweenUs"
                mime = contentType.ifBlank { "audio/mpeg" }
                defaultExt = "mp3"
            }
            else -> {
                collection = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                    MediaStore.Downloads.EXTERNAL_CONTENT_URI
                } else {
                    MediaStore.Files.getContentUri("external")
                }
                relativeDir = "Download/BetweenUs"
                mime = contentType.ifBlank { "application/octet-stream" }
                defaultExt = "bin"
            }
        }

        val safeName = if (isImage || isVideo) {
            formatBuMediaName(name, defaultExt)
        } else {
            name.ifBlank { formatBuMediaName(name, defaultExt) }
        }

        val contentValues = ContentValues().apply {
            put(MediaStore.MediaColumns.DISPLAY_NAME, safeName)
            put(MediaStore.MediaColumns.MIME_TYPE, mime)
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                put(MediaStore.MediaColumns.RELATIVE_PATH, relativeDir)
                put(MediaStore.MediaColumns.IS_PENDING, 1)
            }
        }

        val uri = resolver.insert(collection, contentValues) ?: error("Failed to insert media row")

        resolver.openOutputStream(uri)?.use { stream ->
            stream.write(bytes)
        }

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            contentValues.clear()
            contentValues.put(MediaStore.MediaColumns.IS_PENDING, 0)
            resolver.update(uri, contentValues, null, null)
        }

        uri
    }.getOrNull()
}

/**
 * Saves decrypted bytes into app cache and returns a content Uri through FileProvider.
 */
fun cacheDecryptedMedia(context: Context, bytes: ByteArray, fileName: String): Uri {
    val directory = File(context.cacheDir, "media").apply { mkdirs() }
    val safeName = fileName.replace(Regex("[^a-zA-Z0-9._-]"), "_")
    val file = File(directory, "${System.currentTimeMillis()}_$safeName")
    FileOutputStream(file).use { it.write(bytes) }
    return FileProvider.getUriForFile(context, "${context.packageName}.files", file)
}

/**
 * The first frame of a video, for the card in the message list.
 *
 * A decrypted video used to be a grey rectangle with a play button: the bytes
 * were already on the device and the picture was still a tap away. The
 * retriever wants a file rather than a byte array, which is the same file the
 * player is handed when the tap does come.
 */
suspend fun videoPoster(uri: Uri, context: Context): Bitmap? = withContext(Dispatchers.IO) {
    runCatching {
        MediaMetadataRetriever().use { retriever ->
            retriever.setDataSource(context, uri)
            // A frame a moment in, not frame zero: a video that fades in from
            // black has a first frame that is black.
            retriever.getFrameAtTime(500_000) ?: retriever.frameAtTime
        }
    }.getOrNull()
}

private fun shareBitmap(context: Context, bitmap: Bitmap, title: String) {
    runCatching {
        val directory = File(context.cacheDir, "media").apply { mkdirs() }
        val file = File(directory, "shared_${System.currentTimeMillis()}.jpg")
        FileOutputStream(file).use { out ->
            bitmap.compress(Bitmap.CompressFormat.JPEG, 95, out)
        }
        val uri = FileProvider.getUriForFile(context, "${context.packageName}.files", file)
        val intent = Intent(Intent.ACTION_SEND).apply {
            type = "image/jpeg"
            putExtra(Intent.EXTRA_STREAM, uri)
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
        context.startActivity(Intent.createChooser(intent, "Share $title"))
    }
}

private fun openExternalPlayer(context: Context, videoUri: Uri) {
    runCatching {
        val intent = Intent(Intent.ACTION_VIEW).apply {
            setDataAndType(videoUri, "video/*")
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
        context.startActivity(Intent.createChooser(intent, "Play video with"))
    }
}

