/**
 * A one-time message in the conversation, and the viewer behind it.
 *
 * Three states, and the middle one is the feature. Before: a card naming what
 * is inside, deliberately not a thumbnail - a thumbnail is a look, and it
 * would be a look nobody chose to spend. During: a viewer with the ordinary
 * affordances removed. After: a line saying it is gone, which is all that is
 * left, because the server destroyed the row and the blobs the moment the
 * viewer opened.
 *
 * The author is not a viewer. Somebody re-reading what they themselves sent
 * has not spent anybody's one look, so their own copy opens as often as they
 * like and burns nothing - and the server agrees, which is what makes that
 * safe rather than a client-side courtesy.
 *
 * ## What "protected" can and cannot mean here
 *
 * The viewer sets `FLAG_SECURE` on the window, which is the strongest thing
 * Android offers: the screenshot gesture fails, the screen recorder captures
 * black, the app does not appear in the recents thumbnail, and the window
 * refuses to render onto a non-secure external display. It is real, it is
 * enforced by the platform rather than by this app, and it is more than a
 * desktop can do.
 *
 * It is still not a guarantee, and the copy on screen says so. A second phone
 * pointed at the first one defeats it and always will, and no amount of DRM on
 * a device somebody physically holds changes that. What this feature honestly
 * provides is that the file stops existing - on the server, in the object
 * store, and in every client's cache - the moment it has been seen once.
 */
@Composable
fun OneTimeCard(
    channelId: String,
    messageId: String,
    attachments: List<MessageAttachment>,
    /** Whether *this account* has already spent its look. One look each. */
    viewedByMe: Boolean,
    mine: Boolean,
) {
    val scheme = MaterialTheme.colorScheme
    var open by remember(messageId) { mutableStateOf(false) }

    /**
     * The author does not get to open their own one-time message.
     *
     * They sent it. It was never theirs to look at again, and a sender who can
     * re-open it on another device has a message that is one-time for exactly
     * one of the two people in the conversation - which is not what the sender
     * chose when they turned the switch on.
     *
     * The server refuses them the bytes too; this only stops the app offering
     * something that would fail. See `mayOpenOneTime` in the uploads
     * controller, which is where the guarantee actually lives.
     */
    val spent = mine || viewedByMe

    // The viewer is drawn first, and outside everything below, because it must
    // outlive the state changes its own opening causes.
    //
    // Reporting the look comes back as an updated message with this account in
    // `viewedBy`, which flips `viewedByMe` true - and the card used to return
    // early on that, so the dialog was dropped a second or two after it opened.
    // That is what "it closes itself" was. Whether this account has looked
    // decides what the *card* says; it has nothing to do with whether a viewer
    // that is already open stays open.
    if (open) {
        OneTimeViewer(
            channelId = channelId,
            attachments = attachments,
            onSpend = { Conversation.spendLook(messageId) },
            onDismiss = {
                open = false
                // Now it may go, if the server said so while it was open.
                Conversation.releaseMessage(messageId)
            },
        )
    }

    // Nothing left to open: this account has looked, or it is the author's own
    // and never was theirs to open. Somebody *else's* look does not close it -
    // a one-time message holds one for each person who can see it.
    if (spent) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            BetweenUsIcon(BetweenUsIcons.OneTime, tint = scheme.onSurfaceVariant, size = 16.dp)
            Text(
                text = if (mine) "One-time — only they can open it" else "Opened",
                style = MaterialTheme.typography.bodyMedium,
                color = scheme.onSurfaceVariant,
            )
        }
        return
    }

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(12.dp))
            .background(scheme.primary.copy(alpha = 0.08f))
            .border(1.dp, scheme.primary.copy(alpha = 0.4f), RoundedCornerShape(12.dp))
            .clickable {
                // Held first, and burned later - by the viewer, once it
                // actually has the bytes.
                //
                // Burning from here was the bug: the burn deletes the blob
                // from the object store, and the viewer was still downloading
                // that blob. The two raced, and on a phone the download always
                // lost, so the picture never arrived at all. "You have had
                // your look" has to mean the bytes reached you, not that you
                // tapped something.
                Conversation.holdMessage(messageId)
                open = true
            }
            .padding(horizontal = 12.dp, vertical = 10.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        BetweenUsIcon(BetweenUsIcons.OneTime, tint = scheme.primary, size = 26.dp)
        Column(Modifier.weight(1f)) {
            Text(
                text = describeOneTime(attachments),
                style = MaterialTheme.typography.bodyMedium,
                color = scheme.onSurface,
            )
            Text(
                text = "One-time — you get one look",
                style = MaterialTheme.typography.bodySmall,
                color = scheme.onSurfaceVariant,
            )
        }
    }

}

/** What is inside, said in the words a person would use for it. */
fun describeOneTime(attachments: List<MessageAttachment>): String {
    val kinds = attachments.map { attachment ->
        when {
            attachment.contentType.startsWith("image/") -> "Photo"
            attachment.contentType.startsWith("video/") -> "Video"
            attachment.contentType.startsWith("audio/") -> "Voice message"
            else -> "File"
        }
    }.toSet()
    val only = if (kinds.size == 1) kinds.first() else "File"
    return if (attachments.size > 1) "${attachments.size} ${only.lowercase()}s" else only
}

/**
 * The viewer, behind `FLAG_SECURE`.
 *
 * The flag is set on the dialog's own window and cleared when it closes, so it
 * covers exactly the moment the picture is on screen and does not leave the
 * rest of the app unable to be screenshotted. See the note above for what it
 * does and does not buy.
 */
@Composable
private fun OneTimeViewer(
    channelId: String,
    attachments: List<MessageAttachment>,
    /**
     * Records this account's look. Awaited, and nothing is drawn until it
     * returns - a picture shown before the server has written the look down is
     * a look that was never spent.
     */
    onSpend: suspend () -> Unit,
    onDismiss: () -> Unit,
) {
    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        val window = (LocalView.current.parent as? DialogWindowProvider)?.window
        DisposableEffect(window) {
            window?.setFlags(
                WindowManager.LayoutParams.FLAG_SECURE,
                WindowManager.LayoutParams.FLAG_SECURE,
            )
            onDispose { window?.clearFlags(WindowManager.LayoutParams.FLAG_SECURE) }
        }

        var at by remember { mutableStateOf(0) }
        val index = at.coerceIn(0, attachments.lastIndex)
        val current = attachments[index]

        /**
         * Every file, fetched and decrypted before anything is reported as
         * seen.
         *
         * All of them, not the one on screen: burning destroys the blobs of
         * the whole message, so a second picture still to fetch when the first
         * is reported would be a picture whose bytes are already gone. One
         * message, one look, and everything in it has to arrive first.
         *
         * Held here and nowhere else - deliberately not in `MediaCache`, which
         * is keyed on the storage key and would outlive the message this whole
         * feature exists to destroy.
         */
        var loaded by remember { mutableStateOf<List<android.graphics.Bitmap?>?>(null) }
        var spentLook by remember { mutableStateOf(false) }
        var failure by remember { mutableStateOf<String?>(null) }

        val context = LocalContext.current
        LaunchedEffect(attachments) {
            runCatching {
                attachments.map { attachment ->
                    val bytes = Conversation.openAttachment(channelId, attachment)
                    if (attachment.contentType.startsWith("image/")) {
                        decodeDownsampled(bytes, MAX_DECODE_EDGE_PX)
                    } else {
                        // A video or a voice note cannot be played from a byte
                        // array, so it goes to disk under the key the ordinary
                        // players already look in - otherwise they would fetch
                        // it themselves, from a blob this look is about to
                        // destroy.
                        //
                        // It does not linger: the plaintext is removed with
                        // the message, and the removal is what `releaseMessage`
                        // applies when this viewer closes.
                        MediaCache.putVideo(
                            attachment.key,
                            cacheDecryptedMedia(context, bytes, attachment.name),
                        )
                        null
                    }
                }
            }.onSuccess { decoded ->
                loaded = decoded
                // Two orderings meet here and both matter. The burn deletes
                // the blobs, so it cannot come first - that raced the download
                // and lost. And the picture cannot come first either: drawing
                // it and then recording is a look spent only if the write
                // happened to succeed, which is one look on a good network
                // rather than one look.
                //
                // So: fetch, record, draw. A failure draws nothing and spends
                // nothing, and the person may try again - the server has no
                // row for it, so nothing has been taken from them.
                runCatching { onSpend() }
                    .onSuccess { spentLook = true }
                    .onFailure {
                        failure = "That could not be opened. Nothing has been used up — try again."
                    }
            }.onFailure {
                failure = "That could not be opened"
            }
        }

        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black.copy(alpha = 0.94f))
                .clickable(onClick = onDismiss),
            contentAlignment = Alignment.Center,
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(20.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(14.dp),
            ) {
                when {
                    failure != null -> Text(
                        text = failure.orEmpty(),
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.error,
                        textAlign = TextAlign.Center,
                    )

                    loaded == null || !spentLook -> Text(
                        text = "Decrypting…",
                        style = MaterialTheme.typography.bodyMedium,
                        color = Color.White.copy(alpha = 0.7f),
                    )

                    else -> OneTimeMedia(channelId, current, loaded?.getOrNull(index))
                }

                if (attachments.size > 1) {
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        attachments.forEachIndexed { position, _ ->
                            Box(
                                Modifier
                                    .size(8.dp)
                                    .clip(RoundedCornerShape(4.dp))
                                    .background(
                                        if (position == index) Color.White
                                        else Color.White.copy(alpha = 0.3f),
                                    )
                                    .clickable { at = position },
                            )
                        }
                    }
                }

                // Said plainly. Screenshots really are blocked here - Android
                // enforces it - but a second phone pointed at this one is not,
                // and a viewer that implied otherwise would be lying to the
                // person who decided what to send.
                Text(
                    text = "This is gone once you close it. Screenshots are blocked, but " +
                        "another camera is not — only send what you would trust them with.",
                    style = MaterialTheme.typography.bodySmall,
                    color = Color.White.copy(alpha = 0.6f),
                    textAlign = TextAlign.Center,
                )
            }
        }
    }
}

/**
 * One file inside the viewer.
 *
 * Handed its bitmap rather than fetching one: the viewer above has already
 * downloaded and decrypted every file, because reporting the look is what
 * destroys the blobs and nothing may still be waiting on them when it does.
 */
@Composable
private fun OneTimeMedia(
    channelId: String,
    attachment: MessageAttachment,
    bitmap: android.graphics.Bitmap?,
) {
    val isImage = attachment.contentType.startsWith("image/")
    // A local binding rather than the parameter: a nullable parameter cannot
    // be smart-cast across the branches below.
    val drawable = bitmap

    when {
        isImage && drawable == null -> Text(
            text = "That could not be drawn",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.error,
        )

        isImage && drawable != null -> Image(
            bitmap = drawable.asImageBitmap(),
            contentDescription = null,
            contentScale = ContentScale.Fit,
            modifier = Modifier.fillMaxWidth(),
        )

        // A voice note, played in place. It reads the decrypted file the
        // prefetch above already put in `MediaCache`, so nothing here goes
        // back to a blob this look has destroyed.
        attachment.isAudio -> VoiceMessage(
            channelId = channelId,
            attachment = attachment,
            author = null,
            mine = false,
            fileName = attachment.name.takeUnless { attachment.isVoiceNote },
        )

        // Video: the ordinary card, inside a secure window, playing the file
        // the prefetch wrote rather than fetching one of its own.
        else -> {
            Spacer(Modifier.height(8.dp))
            AttachmentCard(channelId, attachment, { _, _ -> }, { _, _ -> })
        }
    }
}

package com.aatech.betweenus.feature.chat

import android.content.Context
import android.net.Uri
import com.aatech.betweenus.core.data.MessageAttachment
import com.aatech.betweenus.core.data.MessageReply
import com.aatech.betweenus.core.data.NetworkWatch
import com.aatech.betweenus.core.store.Conversation
import com.aatech.betweenus.feature.notifications.PushGate
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * Messages that carry files, sent in the background.
 *
 * Sending used to happen in the coroutine scope of the chat screen, which is
 * the one place it must not: a minute-long video is a minute of holding one
 * screen open, and leaving the channel - or the app - abandoned the upload
 * with the parts already in storage and nothing to finish them. What the
 * screenshot showed was the honest version of that, a preview dialog pinned
 * open at 14%.
 *
 * So it is a queue instead. Handing a message over returns at once, the preview
 * closes, and the send carries on under [UploadService] - a foreground service,
 * because that is the only promise Android makes about work outliving the
 * screen. Progress comes back through [progress], which the composer draws as a
 * bar and the notification draws as a percentage.
 *
 * One at a time, deliberately: two videos sealing at once is twice the heap on
 * a phone that already asks for `largeHeap` to manage one, and the uplink is
 * the bottleneck either way. Parallelism that helps is inside a single upload,
 * where the parts go up together - see `Conversation.putBytes`.
 */
object Outbox {

    /** What is happening to one queued message, for the bar and the notification. */
    data class Progress(
        val channelId: String,
        /** The file being worked on now. */
        val name: String,
        /** 1-based, within this message. */
        val index: Int,
        val total: Int,
        /** Across the whole message, 0 to 1. */
        val fraction: Float,
        /** Messages still waiting behind this one. */
        val queued: Int,
    )

    private data class Item(
        val uri: Uri,
        val name: String,
        val contentType: String,
        /**
         * Measured while this was recorded, when it was. Rides inside the
         * encrypted manifest with everything else about the file, so the
         * server learns nothing from it - and every client draws the same
         * shape for the same message.
         */
        val voice: VoiceNote.Recorded? = null,
    )

    private data class Send(
        val channelId: String,
        val caption: String,
        val items: List<Item>,
        val replyTo: MessageReply?,
        /** Set for a text-only message that is on disk until it is sent. */
        val pendingId: Long? = null,
        /** One-time: the files may be opened once, and opening destroys them. */
        val viewOnce: Boolean = false,
    )

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private val queue = Channel<Send>(Channel.UNLIMITED)

    private val _progress = MutableStateFlow<Progress?>(null)
    val progress: StateFlow<Progress?> = _progress.asStateFlow()

    /** The last thing that went wrong, per channel, for the screen to show. */
    private val _failures = MutableStateFlow<Map<String, String>>(emptyMap())
    val failures: StateFlow<Map<String, String>> = _failures.asStateFlow()

    private var waiting = 0
    private var started = false

    /** Called once, from the application. Idempotent. */
    fun init(context: Context) {
        if (started) return
        started = true
        val app = context.applicationContext
        PendingReplies.init(app)
        scope.launch {
            for (send in queue) {
                waiting = (waiting - 1).coerceAtLeast(0)
                runSend(app, send)
            }
        }
        // Anything a previous run could not send, and anything that failed
        // while the phone had no network. `onAvailable` fires again on a
        // handover, so this has to be safe to run twice - it is, because a
        // send that succeeds takes its row off the disk first.
        replay(app)
        NetworkWatch.onAvailable { replay(app) }
    }

    /**
     * A text message queued to disk first, then sent.
     *
     * This is what a reply typed into the notification shade uses. It used to
     * be sent inline by the broadcast receiver and dropped - without a word -
     * when that failed, which is every reply written in a lift or on a train.
     */
    fun enqueueText(context: Context, channelId: String, text: String) {
        init(context)
        val pending = PendingReplies.add(channelId, text)
        waiting += 1
        queue.trySend(
            Send(
                channelId = channelId,
                caption = text,
                items = emptyList(),
                replyTo = null,
                pendingId = pending.id,
            ),
        )
    }

    /** Whether anything is still waiting to go out, for a screen to say so. */
    fun pendingFor(channelId: String): Int =
        PendingReplies.all().count { it.channelId == channelId }

    /** Sign-out throws unsent words away rather than sending them as somebody else. */
    fun forgetPending() {
        PendingReplies.clear()
    }

    private fun replay(context: Context) {
        val rows = PendingReplies.all()
        if (rows.isEmpty()) return
        rows.forEach { row ->
            waiting += 1
            queue.trySend(
                Send(
                    channelId = row.channelId,
                    caption = row.text,
                    items = emptyList(),
                    replyTo = null,
                    pendingId = row.id,
                ),
            )
        }
    }

    fun clearFailure(channelId: String) {
        _failures.update { it - channelId }
    }

    /**
     * Queues a message. Returns immediately - the caller closes its preview and
     * gets on with something else, which is the whole point.
     */
    fun enqueue(
        context: Context,
        channelId: String,
        caption: String,
        items: List<PickedPreview>,
        replyTo: MessageReply? = null,
        viewOnce: Boolean = false,
        /** Set when the single item is a recording this app just made. */
        voice: VoiceNote.Recorded? = null,
    ) {
        init(context)
        _failures.update { it - channelId }
        waiting += 1
        UploadService.start(context.applicationContext)
        queue.trySend(
            Send(
                channelId = channelId,
                caption = caption,
                items = items.map { Item(it.uri, it.name, it.contentType, voice) },
                replyTo = replyTo,
                viewOnce = viewOnce,
            ),
        )
    }

    private suspend fun runSend(context: Context, send: Send) {
        if (send.pendingId != null) {
            runTextSend(send)
            return
        }
        val total = send.items.size
        try {
            val uploaded = ArrayList<MessageAttachment>(total)
            send.items.forEachIndexed { index, item ->
                report(send.channelId, item.name, index + 1, total, index.toFloat() / total)

                // A video is re-encoded before it is sealed, and that is minutes
                // rather than seconds, so it gets its own half of this file's
                // share of the bar. Anything else has nothing to prepare and
                // the whole share is the upload.
                val video = item.contentType.startsWith("video/")
                val prepared = prepareForSending(
                    context = context,
                    uri = item.uri,
                    name = item.name,
                    contentType = item.contentType,
                    onCompress = { fraction ->
                        report(
                            send.channelId,
                            item.name,
                            index + 1,
                            total,
                            (index + fraction * 0.5f) / total,
                        )
                    },
                )
                require(prepared.bytes.size <= MAX_ATTACHMENT_BYTES) {
                    "${prepared.name} is larger than ${MAX_ATTACHMENT_BYTES / (1024 * 1024)} MB"
                }
                uploaded += Conversation.uploadAttachment(
                    channelId = send.channelId,
                    name = prepared.name,
                    contentType = prepared.contentType,
                    bytes = prepared.bytes,
                    duration = item.voice?.duration,
                    waveform = item.voice?.waveform.orEmpty(),
                    // Across the whole batch rather than per file: three files
                    // is one wait, and a bar that restarts twice reads as a
                    // send that has gone wrong.
                    onProgress = { fraction ->
                        val within = if (video) 0.5f + fraction * 0.5f else fraction
                        report(send.channelId, prepared.name, index + 1, total, (index + within) / total)
                    },
                )
            }
            Conversation.send(
                send.channelId,
                send.caption.trim(),
                uploaded,
                send.replyTo,
                send.viewOnce,
            )
        } catch (error: Throwable) {
            _failures.update {
                it + (send.channelId to (error.message ?: "That message could not be sent"))
            }
        } finally {
            _progress.value = null
            if (waiting == 0) UploadService.stop(context)
        }
    }

    /**
     * A message with no files in it, which is a send and a row to delete.
     *
     * The row goes first only on success: a failure leaves it on disk, and the
     * next validated network - or the next launch - tries it again. A duplicate
     * would be worse than a delay, so nothing here retries in a loop.
     */
    private suspend fun runTextSend(send: Send) {
        val sent = runCatching {
            // A replay at launch runs before anything has signed in, and a
            // send with no session fails for a reason that has nothing to do
            // with the network.
            requireNotNull(PushGate.ensureSession()) { "not signed in" }
            Conversation.send(send.channelId, send.caption.trim(), emptyList())
        }
        if (sent.isSuccess) {
            PendingReplies.remove(send.pendingId ?: return)
            _failures.update { it - send.channelId }
        } else {
            _failures.update {
                it + (send.channelId to "Waiting to send - this phone is offline")
            }
        }
    }

    private fun report(channelId: String, name: String, index: Int, total: Int, fraction: Float) {
        val progress = Progress(
            channelId = channelId,
            name = name,
            index = index,
            total = total,
            fraction = fraction.coerceIn(0f, 1f),
            queued = waiting,
        )
        _progress.value = progress
        UploadService.update(progress)
    }
}

package com.aatech.betweenus.feature.chat

import android.content.Context
import android.content.SharedPreferences
import org.json.JSONArray
import org.json.JSONObject

/**
 * Text messages that have not been sent yet, on disk.
 *
 * [Outbox] is a queue in memory, which is right for a message with a video in
 * it: a content URI is not worth persisting because the permission behind it
 * does not survive the process either. A reply typed into the notification
 * shade is the opposite case - it is a sentence, it is worth keeping, and the
 * process that took it is a broadcast receiver Android may kill the moment it
 * returns. Dropping one because the phone was in a lift is what this closes,
 * and it was dropped *silently*, which is worse than the drop.
 *
 * A file rather than a database: this holds a handful of sentences at most, and
 * a Room table for that is a migration to maintain for no gain.
 */
internal object PendingReplies {

    data class Pending(val id: Long, val channelId: String, val text: String)

    private const val FILE = "betweenus.outbox"
    private const val KEY = "pending"

    private lateinit var prefs: SharedPreferences

    fun init(context: Context) {
        if (::prefs.isInitialized) return
        prefs = context.applicationContext.getSharedPreferences(FILE, Context.MODE_PRIVATE)
    }

    @Synchronized
    fun add(channelId: String, text: String): Pending {
        val pending = Pending(System.currentTimeMillis(), channelId, text)
        write(all() + pending)
        return pending
    }

    @Synchronized
    fun remove(id: Long) {
        write(all().filterNot { it.id == id })
    }

    @Synchronized
    fun all(): List<Pending> {
        if (!::prefs.isInitialized) return emptyList()
        val raw = prefs.getString(KEY, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            (0 until array.length()).map { index ->
                val row = array.getJSONObject(index)
                Pending(
                    id = row.getLong("id"),
                    channelId = row.getString("channelId"),
                    text = row.getString("text"),
                )
            }
        }.getOrDefault(emptyList())
    }

    /**
     * Everything queued is thrown away with the account it belonged to. An
     * unsent reply is a message somebody wrote, and sending it from the next
     * account to sign in on this phone would be the worst possible outcome.
     */
    @Synchronized
    fun clear() {
        if (::prefs.isInitialized) prefs.edit().remove(KEY).apply()
    }

    private fun write(rows: List<Pending>) {
        val array = JSONArray()
        rows.forEach { row ->
            array.put(
                JSONObject()
                    .put("id", row.id)
                    .put("channelId", row.channelId)
                    .put("text", row.text),
            )
        }
        prefs.edit().putString(KEY, array.toString()).apply()
    }
}

