/**
 * What you are about to send, before you send it.
 *
 * The port of `apps/desktop/src/features/chat/SendPreview.tsx`. Pictures and
 * video used to be uploaded the instant they were picked and named on a chip,
 * which is the one moment nobody can check what they actually chose - and
 * picking the wrong photo out of a roll of near-identical ones is the most
 * ordinary mistake there is.
 *
 * Nothing here is encrypted or uploaded yet: these are local content URIs the
 * picker just handed back. Sending hands the batch to [Outbox], which does the
 * reading, sealing and uploading under a foreground service - so this screen
 * closes at once and never has to show a spinner of its own.
 *
 * Everything picked comes through here, a PDF as much as a photo. A file with
 * nothing to look at gets a card with its name on it, because the question the
 * screen asks - "is this the one you meant?" - is the same question either way,
 * and it used to be asked of pictures only while a document was uploaded the
 * instant it was picked.
 */
@Composable
fun SendPreviewDialog(
    items: List<PickedPreview>,
    caption: String,
    onCaption: (String) -> Unit,
    onRemove: (PickedPreview) -> Unit,
    /** A picture that came back from the crop screen, in place of the original. */
    onReplace: (PickedPreview, PickedPreview) -> Unit,
    onAdd: () -> Unit,
    /** Whether these files are being sent as a one-time message. */
    viewOnce: Boolean,
    onViewOnce: (Boolean) -> Unit,
    onCancel: () -> Unit,
    onSend: () -> Unit,
) {
    if (items.isEmpty()) return
    var at by remember(items.size) { mutableStateOf(0) }
    val index = at.coerceIn(0, items.lastIndex)
    val current = items[index]
    var cropping by remember { mutableStateOf(false) }

    if (cropping && current.isImage) {
        ImageEditorDialog(
            source = current.uri,
            title = current.name,
            onCancel = { cropping = false },
            onDone = { edited ->
                cropping = false
                // The editor always writes a JPEG, so the name follows: a file
                // that lies about its type confuses every client that opens it.
                onReplace(
                    current,
                    PickedPreview(
                        uri = edited,
                        name = current.name.substringBeforeLast('.', current.name) + ".jpg",
                        contentType = "image/jpeg",
                    ),
                )
            },
        )
    }

    Dialog(
        onDismissRequest = onCancel,
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        Column(
            Modifier
                .fillMaxSize()
                .background(Surface950)
                .statusBarsPadding()
                .navigationBarsPadding()
                .imePadding(),
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 6.dp, vertical = 6.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                IconAction(BetweenUsIcons.X, "Back to the message box", onCancel)
                Column(Modifier.weight(1f).padding(start = 6.dp)) {
                    Text(
                        text = if (items.size == 1) current.name else "${items.size} files",
                        style = MaterialTheme.typography.titleSmall,
                        color = Slate100,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        text = "Encrypted before it leaves this phone",
                        style = MaterialTheme.typography.bodySmall,
                        fontSize = 11.sp,
                        color = Slate500,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                if (current.isImage) {
                    IconAction(BetweenUsIcons.Crop, "Crop and rotate", { cropping = true })
                }
                IconAction(BetweenUsIcons.Paperclip, "Add another file", onAdd)
                IconAction(BetweenUsIcons.Trash, "Remove this one", { onRemove(current) })
            }

            Box(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .background(Color.Black),
                contentAlignment = Alignment.Center,
            ) {
                when {
                    current.isVideo -> AndroidView(
                        factory = { ctx ->
                            VideoView(ctx).apply {
                                val controller = MediaController(ctx)
                                controller.setAnchorView(this)
                                setMediaController(controller)
                                setVideoURI(current.uri)
                                // Paused on the first frame: this is a check of
                                // what was picked, not a screening of it.
                                setOnPreparedListener { seekTo(1) }
                            }
                        },
                        // A new pick is a new video; without this the view keeps
                        // playing whatever it was given first.
                        update = { it.setVideoURI(current.uri) },
                        modifier = Modifier.fillMaxSize(),
                    )

                    current.isImage -> AsyncImage(
                        model = current.uri,
                        contentDescription = current.name,
                        contentScale = ContentScale.Fit,
                        modifier = Modifier.fillMaxSize(),
                    )

                    // A spreadsheet has nothing to look at. It still has a name
                    // and a type, which is the whole of what can be checked
                    // about it before it goes.
                    else -> Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier.padding(32.dp),
                    ) {
                        BetweenUsIcon(BetweenUsIcons.File, tint = Slate400, size = 48.dp)
                        Spacer(Modifier.height(12.dp))
                        Text(
                            text = current.name,
                            style = MaterialTheme.typography.titleSmall,
                            color = Slate100,
                            textAlign = TextAlign.Center,
                        )
                        Text(
                            text = current.contentType,
                            style = MaterialTheme.typography.bodySmall,
                            color = Slate500,
                        )
                    }
                }
            }

            if (items.size > 1) {
                LazyRow(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Surface900)
                        .padding(horizontal = 8.dp, vertical = 8.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    items(items, key = { it.uri.toString() }) { item ->
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .clip(RoundedCornerShape(8.dp))
                                .background(Surface800)
                                .border(
                                    width = if (item == current) 2.dp else 1.dp,
                                    color = if (item == current) Accent else Edge,
                                    shape = RoundedCornerShape(8.dp),
                                )
                                .clickable { at = items.indexOf(item) },
                            contentAlignment = Alignment.Center,
                        ) {
                            when {
                                item.isVideo ->
                                    BetweenUsIcon(BetweenUsIcons.Play, tint = Slate400, size = 20.dp)

                                item.isImage -> AsyncImage(
                                    model = item.uri,
                                    contentDescription = item.name,
                                    contentScale = ContentScale.Crop,
                                    modifier = Modifier.fillMaxSize(),
                                )

                                else ->
                                    BetweenUsIcon(BetweenUsIcons.File, tint = Slate400, size = 20.dp)
                            }
                        }
                    }
                }
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Surface950)
                    .padding(horizontal = 12.dp, vertical = 10.dp),
                verticalAlignment = Alignment.Bottom,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .clip(RoundedCornerShape(22.dp))
                        .background(Surface800)
                        .padding(horizontal = 14.dp, vertical = 10.dp),
                ) {
                    if (caption.isEmpty()) {
                        Text(
                            text = "Add a caption…",
                            style = MaterialTheme.typography.bodyLarge,
                            color = Slate500,
                        )
                    }
                    BasicTextField(
                        value = caption,
                        onValueChange = onCaption,
                        textStyle = TextStyle(color = Slate100, fontSize = 16.sp),
                        cursorBrush = SolidColor(Accent),
                        modifier = Modifier.fillMaxWidth(),
                    )
                }

                // This is the screen where somebody actually looks at the
                // photo they are about to send, so it is the screen where they
                // decide it is one they would rather did not stay anywhere.
                Box(
                    modifier = Modifier
                        .size(48.dp)
                        .clip(CircleShape)
                        .background(if (viewOnce) Accent.copy(alpha = 0.18f) else Surface800)
                        .clickable { onViewOnce(!viewOnce) },
                    contentAlignment = Alignment.Center,
                ) {
                    BetweenUsIcon(
                        BetweenUsIcons.OneTime,
                        contentDescription = if (viewOnce) {
                            "One-time is on"
                        } else {
                            "Send as a one-time message"
                        },
                        tint = if (viewOnce) Accent else Slate400,
                        size = 20.dp,
                    )
                }

                Box(
                    modifier = Modifier
                        .size(48.dp)
                        .clip(CircleShape)
                        .background(Accent)
                        .clickable { onSend() },
                    contentAlignment = Alignment.Center,
                ) {
                    // No spinner. Sending is a hand-off to [Outbox] that
                    // returns at once, and the progress lives in the ongoing
                    // notification and the bar above the conversation.
                    BetweenUsIcon(BetweenUsIcons.Send, tint = Color.White, size = 20.dp)
                }
            }

            Spacer(Modifier.height(4.dp))
        }
    }
}

/** One thing the picker handed back, before anything has been read off disk. */
data class PickedPreview(val uri: Uri, val name: String, val contentType: String) {
    val isVideo: Boolean get() = contentType.startsWith("video/")
    val isImage: Boolean get() = contentType.startsWith("image/")
}

package com.aatech.betweenus.feature.chat

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.content.pm.ServiceInfo
import android.os.Build
import android.os.IBinder
import androidx.core.app.NotificationCompat
import com.aatech.betweenus.MainActivity
import com.aatech.betweenus.R

/**
 * The promise that a message with a video in it finishes.
 *
 * Without a foreground service, work that outlives the screen is work Android
 * is entitled to stop, and it does - so leaving the channel, or answering a
 * call, or putting the phone in a pocket, abandoned an upload with its parts
 * already in object storage. This is the ongoing notification that says a file
 * is going out, which is both the disclosure the platform requires and the
 * progress bar somebody actually wants.
 *
 * It knows nothing about uploading. [Outbox] owns the queue and pushes what to
 * draw; this only draws it.
 */
class UploadService : Service() {

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        live = this
        startForeground(NOTIFICATION_ID, notification(latest), foregroundType())
        // Never START_STICKY: a restarted service is an ongoing "sending…"
        // notification for a queue the process no longer has.
        return START_NOT_STICKY
    }

    override fun onDestroy() {
        if (live === this) live = null
        stopForeground(STOP_FOREGROUND_REMOVE)
        super.onDestroy()
    }

    private fun foregroundType(): Int =
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC
        } else {
            0
        }

    private fun notification(progress: Outbox.Progress?): Notification {
        ensureChannel(this)

        val open = PendingIntent.getActivity(
            this,
            0,
            Intent(this, MainActivity::class.java)
                .setAction(Intent.ACTION_MAIN)
                .addCategory(Intent.CATEGORY_LAUNCHER)
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_SINGLE_TOP),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
        )

        val percent = ((progress?.fraction ?: 0f) * 100).toInt()
        val title = progress?.name ?: "Sending"
        val line = buildString {
            append("Encrypting and uploading… $percent%")
            if (progress != null && progress.total > 1) {
                append(" · ${progress.index} of ${progress.total}")
            }
            if (progress != null && progress.queued > 0) append(" · ${progress.queued} waiting")
        }

        return NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_betweenus_notification)
            .setContentTitle(title)
            .setContentText(line)
            .setContentIntent(open)
            .setOngoing(true)
            .setSilent(true)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setCategory(NotificationCompat.CATEGORY_PROGRESS)
            // Indeterminate until there is a number worth reading: a small file
            // is sealed and gone before a percentage would settle.
            .setProgress(100, percent, progress == null)
            .build()
    }

    companion object {
        private const val CHANNEL_ID = "betweenus.uploads"
        private const val NOTIFICATION_ID = 1002

        private var live: UploadService? = null
        private var latest: Outbox.Progress? = null

        fun ensureChannel(context: Context) {
            if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
            val manager = context.getSystemService(NotificationManager::class.java)
            if (manager.getNotificationChannel(CHANNEL_ID) != null) return
            manager.createNotificationChannel(
                NotificationChannel(CHANNEL_ID, "Sending files", NotificationManager.IMPORTANCE_LOW)
                    .apply {
                        description = "Shown while a message with files attached is going out"
                        setShowBadge(false)
                        setSound(null, null)
                        enableVibration(false)
                    },
            )
        }

        fun start(context: Context) {
            ensureChannel(context)
            val intent = Intent(context, UploadService::class.java)
            runCatching {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                    context.startForegroundService(intent)
                } else {
                    context.startService(intent)
                }
            }
            // A start refused because the app is in the background is not a
            // reason to lose the message: the queue runs either way, it simply
            // has no promise of surviving the process being trimmed.
        }

        /** Redraws the notification in place. Cheap, and called about once a second. */
        fun update(progress: Outbox.Progress) {
            latest = progress
            val service = live ?: return
            runCatching {
                service.getSystemService(NotificationManager::class.java)
                    .notify(NOTIFICATION_ID, service.notification(progress))
            }
        }

        fun stop(context: Context) {
            latest = null
            runCatching { context.stopService(Intent(context, UploadService::class.java)) }
        }
    }
}

package com.aatech.betweenus.feature.chat

import android.content.Context
import android.media.MediaMetadataRetriever
import android.net.Uri
import androidx.media3.common.MediaItem
import androidx.media3.common.MimeTypes
import androidx.media3.common.util.UnstableApi
import androidx.media3.effect.Presentation
import androidx.media3.transformer.Composition
import androidx.media3.transformer.DefaultEncoderFactory
import androidx.media3.transformer.EditedMediaItem
import androidx.media3.transformer.Effects
import androidx.media3.transformer.ExportException
import androidx.media3.transformer.ExportResult
import androidx.media3.transformer.Transformer
import androidx.media3.transformer.VideoEncoderSettings
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import java.io.File
import kotlin.coroutines.resume
import kotlin.math.max
import kotlin.math.min

/**
 * Shrinking a video before it is sent.
 *
 * A phone records at whatever its camera can do - 4K at 50 Mbps is ordinary -
 * and none of that survives being watched in a message list. Sending it as it
 * was recorded was the difference between a clip arriving in seconds and a clip
 * arriving in ten minutes, on a phone uplink, with the app pinned open the
 * whole time. Every chat app compresses; this is that.
 *
 * The rules, in the order they are applied:
 *
 * - the short side is brought down to [SHORT_SIDE] and never raised;
 * - the video is re-encoded as H.264 at a bitrate set by the result's size;
 * - audio is left as it is, because audio is a rounding error next to video
 *   and re-encoding it only costs quality;
 * - a file that is already small enough is not touched at all, because a
 *   re-encode of an already-small clip is slower *and* worse.
 *
 * The output is a file in the cache. Everything the caller does after this -
 * seal, upload, send - is the same as for any other file.
 */
private const val SHORT_SIDE = 720

/** Below this a clip is not worth a re-encode: it is already message-sized. */
private const val LEAVE_ALONE_UNDER_BYTES = 6L * 1024 * 1024

/**
 * About what 720p needs to look like the recording it came from, and roughly
 * what every other chat app settles on. Not a guess at quality: it is the
 * number that decides whether the upload is seconds or minutes.
 */
private const val TARGET_BITRATE = 2_500_000

/** Above this, a re-encode would cost more time than the upload it saves. */
private const val MAX_DURATION_MS = 20L * 60 * 1000

/** What came back: a file to send, and whether it is a new one to delete after. */
data class PreparedVideo(val uri: Uri, val temporary: Boolean)

/**
 * Re-encodes [source] smaller, or gives it back untouched.
 *
 * Never throws for a video it cannot handle. A codec that refuses, a container
 * nothing can read, a device with no encoder to spare - all of them mean "send
 * what was picked", which is slower and works, rather than an error about a
 * file the person can see is fine.
 */
@androidx.annotation.OptIn(UnstableApi::class)
suspend fun compressVideo(
    context: Context,
    source: Uri,
    sizeBytes: Long,
    onProgress: (Float) -> Unit = {},
): PreparedVideo = withContext(Dispatchers.Main) {
    if (sizeBytes in 1..LEAVE_ALONE_UNDER_BYTES) return@withContext PreparedVideo(source, false)

    val facts = videoFacts(context, source)
    if (facts != null && facts.durationMs > MAX_DURATION_MS) {
        return@withContext PreparedVideo(source, false)
    }
    // Already at or below the target on both counts: re-encoding would spend
    // minutes to make it very slightly worse.
    if (facts != null && facts.shortSide <= SHORT_SIDE && facts.bitrate in 1..TARGET_BITRATE) {
        return@withContext PreparedVideo(source, false)
    }

    val directory = File(context.cacheDir, "outgoing").apply { mkdirs() }
    val target = File(directory, "video-${System.currentTimeMillis()}.mp4")

    val transformer = Transformer.Builder(context)
        .setVideoMimeType(MimeTypes.VIDEO_H264)
        // The bitrate is the whole point. Left to the default, Transformer
        // picks one from the source's own - so a 50 Mbps recording comes out
        // large, correctly encoded, and just as slow to send as it was.
        .setEncoderFactory(
            DefaultEncoderFactory.Builder(context)
                .setRequestedVideoEncoderSettings(
                    VideoEncoderSettings.Builder().setBitrate(TARGET_BITRATE).build(),
                )
                // A device with no hardware encoder for these settings falls
                // back to a software one rather than refusing: slow beats "your
                // video could not be sent".
                .setEnableFallback(true)
                .build(),
        )
        .build()

    val item = EditedMediaItem.Builder(MediaItem.fromUri(source))
        .setEffects(
            Effects(
                // Audio untouched: it is a rounding error next to the video
                // track, and re-encoding it only costs quality.
                emptyList(),
                listOf(Presentation.createForShortSide(SHORT_SIDE)),
            ),
        )
        .build()

    val done = suspendCancellableCoroutine { continuation ->
        val listener = object : Transformer.Listener {
            override fun onCompleted(composition: Composition, result: ExportResult) {
                if (continuation.isActive) continuation.resume(true)
            }

            override fun onError(
                composition: Composition,
                result: ExportResult,
                exception: ExportException,
            ) {
                if (continuation.isActive) continuation.resume(false)
            }
        }
        transformer.addListener(listener)
        continuation.invokeOnCancellation { transformer.cancel() }

        runCatching { transformer.start(item, target.absolutePath) }
            .onFailure { if (continuation.isActive) continuation.resume(false) }

        // Transformer reports progress by being asked, not by calling back.
        // One second apart: fine enough for a bar and cheap enough to ignore.
        pollProgress(transformer, onProgress, continuation)
    }

    if (!done || !target.exists() || target.length() == 0L) {
        target.delete()
        return@withContext PreparedVideo(source, false)
    }
    // A "compressed" file bigger than what went in is a re-encode that lost.
    if (sizeBytes > 0 && target.length() >= sizeBytes) {
        target.delete()
        return@withContext PreparedVideo(source, false)
    }

    PreparedVideo(
        androidx.core.content.FileProvider.getUriForFile(
            context,
            "${context.packageName}.files",
            target,
        ),
        temporary = true,
    )
}

@androidx.annotation.OptIn(UnstableApi::class)
private fun pollProgress(
    transformer: Transformer,
    onProgress: (Float) -> Unit,
    continuation: kotlinx.coroutines.CancellableContinuation<Boolean>,
) {
    val handler = android.os.Handler(android.os.Looper.getMainLooper())
    val holder = androidx.media3.transformer.ProgressHolder()
    val tick = object : Runnable {
        override fun run() {
            if (!continuation.isActive) return
            val state = transformer.getProgress(holder)
            if (state == Transformer.PROGRESS_STATE_AVAILABLE) {
                onProgress(holder.progress / 100f)
            }
            handler.postDelayed(this, 1000)
        }
    }
    handler.postDelayed(tick, 1000)
    continuation.invokeOnCancellation { handler.removeCallbacks(tick) }
}

private class VideoFacts(val shortSide: Int, val bitrate: Int, val durationMs: Long)

/** Size, bitrate and length, read from the container's own index. */
private fun videoFacts(context: Context, uri: Uri): VideoFacts? = runCatching {
    MediaMetadataRetriever().use { reader ->
        reader.setDataSource(context, uri)
        fun number(key: Int): Long = reader.extractMetadata(key)?.toLongOrNull() ?: 0L

        val width = number(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH).toInt()
        val height = number(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT).toInt()
        val rotation = number(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION).toInt()
        // A portrait recording is a landscape frame plus a rotation flag, and
        // the short side is the short side of what is actually shown.
        val shown = if (rotation == 90 || rotation == 270) height to width else width to height

        VideoFacts(
            shortSide = min(shown.first, shown.second).let { if (it > 0) it else max(width, height) },
            bitrate = number(MediaMetadataRetriever.METADATA_KEY_BITRATE).toInt(),
            durationMs = number(MediaMetadataRetriever.METADATA_KEY_DURATION),
        )
    }
}.getOrNull()

/** `MediaMetadataRetriever` is only `AutoCloseable` from API 29. */
private inline fun <T> MediaMetadataRetriever.use(block: (MediaMetadataRetriever) -> T): T = try {
    block(this)
} finally {
    runCatching { release() }
}

