/**
 * A voice message, drawn as one.
 *
 * What this replaces was the generic file card: an icon, a filename that is a
 * timestamp, "95 KB · Tap to decrypt", and a download button. Every part of it
 * was wrong for somebody talking - nobody wants to read
 * `voice_20260830_011311.ogg`, nobody wants to press download and then press
 * play, and the card announces "here is a file" when what arrived was a voice.
 *
 * So: a play button, the shape of the recording, and how long it is. The
 * waveform is the seek bar, because it is already a picture of the timeline and
 * a slider under it would be the same axis drawn twice.
 *
 * The bars are measured on the sender while the message is being recorded and
 * travel inside the encrypted manifest - see [MessageAttachment.waveform]. That
 * is what lets the shape be on screen before the audio has been fetched, which
 * is the whole reason to draw one.
 *
 * `MediaPlayer` rather than the Media3 player the video viewer uses: this is a
 * few seconds of speech from a local file with no surface, no transitions and
 * no controls of its own, which is the one job `MediaPlayer` is still the right
 * size for.
 */
@Composable
fun VoiceMessage(
    channelId: String,
    attachment: MessageAttachment,
    author: UserSummary?,
    mine: Boolean,
    /**
     * Shown above the player for audio that is not a recording.
     *
     * A voice note needs no label - it is somebody talking, and its name is a
     * timestamp. A track somebody chose to share is the opposite: the name is
     * most of what they were sharing.
     */
    fileName: String? = null,
) {
    val context = LocalContext.current
    val scheme = MaterialTheme.colorScheme

    var player by remember(attachment.key) { mutableStateOf<MediaPlayer?>(null) }
    var playing by remember(attachment.key) { mutableStateOf(false) }
    var at by remember(attachment.key) { mutableFloatStateOf(0f) }
    var failed by remember(attachment.key) { mutableStateOf(false) }
    /**
     * The length the player reports, once there is one.
     *
     * Preferred over the manifest's number because it is what the seek maths
     * has to agree with - a bar tapped at 40% has to land at 40% of what will
     * actually play. The manifest's value is what gets drawn before there is a
     * player at all, which is most of the time this is on screen.
     */
    var measured by remember(attachment.key) { mutableStateOf<Float?>(null) }

    val bars = attachment.waveform.ifEmpty { PLACEHOLDER }
    val total = measured ?: attachment.duration ?: 0f

    /**
     * Fetched, decrypted and prepared as soon as the row is drawn, without
     * being asked.
     *
     * A voice message is seconds long and tens of kilobytes. Making somebody
     * tap download, wait, and then tap play is three interactions for
     * something that should be one - and the download button was the honest
     * answer only while the alternative was spending a video's worth of
     * somebody's connection on a message they scrolled past. That is not this.
     *
     * Keyed on the attachment, so a `LazyColumn` recycling this row does not
     * re-fetch: `MediaCache` already holds the decrypted file from the first
     * time it was on screen.
     */
    LaunchedEffect(attachment.key) {
        val uri = MediaCache.video(attachment.key) ?: runCatching {
            val bytes = Conversation.openAttachment(channelId, attachment)
            cacheDecryptedMedia(context, bytes, attachment.name)
        }.onFailure { failed = true }.getOrNull() ?: return@LaunchedEffect

        // Cached under the same key the pictures use. The file is on disk
        // either way, and this is what stops a scroll past re-decrypting it.
        MediaCache.putVideo(attachment.key, uri)

        runCatching {
            MediaPlayer().apply {
                setDataSource(context, uri)
                setOnPreparedListener { prepared ->
                    measured = prepared.duration / 1000f
                }
                setOnCompletionListener {
                    playing = false
                    // Back to the start, so the next tap replays rather than
                    // doing nothing - and so the waveform empties again.
                    at = 0f
                    runCatching { seekTo(0) }
                }
                prepare()
            }
        }.onSuccess { player = it }.onFailure { failed = true }
    }

    // A player holds a codec and an open file. Leaving the conversation has to
    // give both back, or a long scroll through a channel of voice messages is
    // a slow leak of decoder instances.
    DisposableEffect(attachment.key) {
        onDispose {
            runCatching { player?.release() }
            player = null
        }
    }

    // The position, while it is moving. One loop while playing and none at all
    // the rest of the time.
    LaunchedEffect(playing) {
        while (playing) {
            at = (player?.currentPosition ?: 0) / 1000f
            kotlinx.coroutines.delay(60)
        }
    }

    fun toggle() {
        val current = player ?: return
        if (current.isPlaying) {
            current.pause()
            playing = false
        } else {
            current.start()
            playing = true
        }
    }

    fun seekToFraction(fraction: Float) {
        val current = player ?: return
        val clamped = fraction.coerceIn(0f, 1f)
        val target = (clamped * (measured ?: return) * 1000).roundToInt()
        current.seekTo(target)
        at = target / 1000f
    }

    val accent = if (mine) scheme.primary else scheme.onSurface
    val spent = if (total > 0f) ((at / total).coerceIn(0f, 1f) * bars.size).roundToInt() else 0

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(18.dp))
            .background(scheme.surfaceContainerHigh)
            .padding(horizontal = 10.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        if (author != null) {
            Box {
                Avatar(author.id, author.label, author.avatarUrl, size = 40.dp)
                // The mark that says what kind of message this is, on the one
                // part of the bubble that is otherwise just a face.
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .size(16.dp)
                        .clip(CircleShape)
                        .background(scheme.surfaceContainerHigh),
                    contentAlignment = Alignment.Center,
                ) {
                    BetweenUsIcon(BetweenUsIcons.Mic, tint = accent, size = 11.dp)
                }
            }
        }

        Box(
            modifier = Modifier
                .size(36.dp)
                .clip(CircleShape)
                .pointerInput(player) { detectTapGestures { toggle() } },
            contentAlignment = Alignment.Center,
        ) {
            BetweenUsIcon(
                if (playing) BetweenUsIcons.Pause else BetweenUsIcons.Play,
                tint = if (player == null) scheme.onSurfaceVariant else scheme.onSurface,
                size = 22.dp,
            )
        }

        Column(Modifier.weight(1f)) {
            if (fileName != null) {
                Text(
                    text = fileName,
                    style = MaterialTheme.typography.bodySmall,
                    color = scheme.onSurface,
                    maxLines = 1,
                    overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
                )
            }

            // The waveform *is* the seek bar. A slider underneath would be the
            // same axis drawn twice.
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(28.dp)
                    .pointerInput(player, measured) {
                        detectTapGestures { offset ->
                            seekToFraction(offset.x / size.width)
                        }
                    }
                    .pointerInput(player, measured) {
                        detectHorizontalDragGestures { change, _ ->
                            seekToFraction(change.position.x / size.width)
                        }
                    },
                contentAlignment = Alignment.CenterStart,
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(2.dp),
                ) {
                    bars.forEachIndexed { index, height ->
                        Box(
                            Modifier
                                .weight(1f)
                                // A floor in dp as well as in the data: a bar
                                // rounded below a pixel disappears, and a
                                // waveform with holes reads as a damaged file.
                                .height((2f + height.coerceIn(0f, 1f) * 22f).dp)
                                .clip(RoundedCornerShape(1.dp))
                                .background(
                                    if (index < spent) accent else scheme.onSurfaceVariant.copy(alpha = 0.4f),
                                ),
                        )
                    }
                }
            }

            Spacer(Modifier.height(2.dp))

            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    // While it is playing, how far in; otherwise how long it
                    // is. Both are the number somebody wants at that moment,
                    // and "0:00 / 0:07" is showing one of them twice.
                    text = VoiceNote.formatDuration(if (playing || at > 0f) at else total),
                    style = MaterialTheme.typography.bodySmall,
                    color = scheme.onSurfaceVariant,
                )
                if (failed || player == null) {
                    Spacer(Modifier.width(8.dp))
                    Text(
                        text = if (failed) "Could not be opened" else "Decrypting…",
                        style = MaterialTheme.typography.bodySmall,
                        color = if (failed) scheme.error else scheme.onSurfaceVariant,
                    )
                }
            }
        }
    }
}

/**
 * What to draw when the sender's client never measured a waveform - audio
 * picked off the phone, or a message sent before waveforms existed.
 *
 * A gentle repeating shape rather than a flat line or random noise. Flat reads
 * as a broken file; random reads as a real waveform and is a lie about where
 * the loud parts are. This is visibly a placeholder and still gives the finger
 * something to aim at.
 */
private val PLACEHOLDER: List<Float> =
    List(VoiceNote.WAVEFORM_BARS) { index ->
        0.35f + 0.25f * kotlin.math.sin(index / 2.2f)
    }

package com.aatech.betweenus.feature.chat

import android.content.Context
import android.media.MediaRecorder
import android.net.Uri
import android.os.Build
import androidx.core.net.toUri
import java.io.File
import java.util.Locale

/**
 * Recording a voice message.
 *
 * A voice message is not a new kind of message. It is a recording, sealed and
 * uploaded exactly like a file picked with the paperclip, and it arrives as an
 * audio attachment the message list already knows how to play. Everything
 * downstream of "here is a file" already existed, which is why this is short.
 *
 * What it does own is the awkward half: holding a microphone open, stopping it
 * without losing the last of the recording, and giving the microphone back on
 * every path out - including the ones nobody plans for, like leaving the
 * screen mid-recording. A recording indicator left on is the one bug in this
 * area nobody forgives.
 */
object VoiceNote {

    /**
     * Longer than this and the recorder stops itself.
     *
     * What it really guards is somebody starting a recording and walking away:
     * without a ceiling that is an open microphone and a growing file until
     * the process is killed.
     */
    const val MAX_SECONDS: Int = 5 * 60

    /**
     * A recording shorter than this is a slip of the finger, not a message.
     *
     * Every messenger has this threshold because every messenger has the same
     * gesture: a tap meant as a hold produces a quarter-second of room tone,
     * and sending it is never what anybody meant.
     */
    const val MIN_SECONDS: Int = 1

    /**
     * How many bars a voice message is drawn with. Mirrors
     * `VOICE_WAVEFORM_BARS` in `packages/shared-types`, and the two have to
     * agree or a message drawn on a phone is a different width to the same one
     * on a laptop.
     */
    const val WAVEFORM_BARS: Int = 48

    /** No bar is ever shorter than this, so a pause is a line and not a hole. */
    private const val MIN_BAR = 0.08f

    /** A finished recording: the file, and what it looked like being made. */
    data class Recorded(
        val file: PickedPreview,
        /** Seconds, rounded to a tenth - the label, not a seek position. */
        val duration: Float,
        /** Bar heights 0..1, [WAVEFORM_BARS] of them. */
        val waveform: List<Float>,
    )

    /**
     * A recording in progress.
     *
     * Two ways out, and they are not the same. [stop] returns the recording;
     * [cancel] throws it away. Both release the microphone.
     */
    class Recording internal constructor(
        private val recorder: MediaRecorder,
        private val file: File,
        private val startedAt: Long,
        private val contentType: String,
    ) {
        private var finished = false

        /**
         * The level, sampled while recording.
         *
         * `getMaxAmplitude` is the peak since the previous call, which makes it
         * a meter and a consumable in one - so it has to be read on a steady
         * beat by exactly one caller, and [sample] is that caller. Reading it
         * anywhere else would silently steal from the waveform.
         */
        private val samples = ArrayList<Float>()

        /** Seconds recorded so far, for the counter on screen. */
        fun elapsed(): Float = (System.currentTimeMillis() - startedAt) / 1000f

        /**
         * Takes one level reading. Called from the screen's ticker, because
         * that loop already exists and this has to run on a steady beat.
         *
         * Returns the reading so the composer can draw a live meter from the
         * same numbers that end up in the manifest - two meters that disagree
         * would be two chances to be wrong.
         */
        fun sample(): Float {
            if (finished) return 0f
            // 32767 is the top of a 16-bit sample, which is what the recorder
            // reports against whatever the input gain happens to be.
            val level = runCatching { recorder.maxAmplitude / 32_767f }.getOrDefault(0f)
            samples.add(level)
            return level
        }

        /** The tail of what has been measured, for the live meter. */
        fun levels(): List<Float> = samples.toList()

        /**
         * Finishes and returns what was recorded, or null when it was too
         * short to be a message - or when the recorder failed on the way out.
         *
         * `MediaRecorder.stop` throws when it is stopped before it has
         * captured anything, which is exactly the too-short case, so the two
         * failures answer the same way rather than one of them crashing.
         */
        fun stop(): Recorded? {
            if (finished) return null
            val measured = samples.toList()
            finished = true

            val seconds = elapsed()
            val captured = runCatching {
                recorder.stop()
            }.isSuccess
            release()

            if (!captured || seconds < MIN_SECONDS || file.length() == 0L) {
                file.delete()
                return null
            }
            return Recorded(
                file = PickedPreview(file.toUri(), file.name, contentType),
                duration = Math.round(seconds * 10) / 10f,
                waveform = toWaveform(measured),
            )
        }

        /** Abandons it: the microphone goes back, and so does the disk. */
        fun cancel() {
            if (finished) return
            finished = true
            runCatching { recorder.stop() }
            release()
            file.delete()
        }

        private fun release() {
            runCatching { recorder.reset() }
            runCatching { recorder.release() }
        }
    }

    /**
     * Opens the microphone and starts recording.
     *
     * Returns null when the microphone cannot be opened - refused permission,
     * or another app already holding it. The caller puts that on screen: it is
     * the one failure here somebody can do something about.
     */
    fun start(context: Context): Recording? {
        val app = context.applicationContext

        // Opus where the platform has it, AAC before that. Opus is what the
        // call path and the other two clients already use and is markedly
        // smaller for speech; AAC in an MP4 is what every Android since this
        // app's minimum can write, and every client can play.
        val opus = Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q
        val extension = if (opus) "ogg" else "m4a"
        val contentType = if (opus) "audio/ogg" else "audio/mp4"

        // The app's own cache directory: this file is plaintext until it is
        // sealed for upload, so it goes somewhere no other app can read and
        // somewhere the system may reclaim.
        val file = File(app.cacheDir, "${name()}.$extension")

        @Suppress("DEPRECATION")
        val recorder = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            MediaRecorder(app)
        } else {
            MediaRecorder()
        }

        return runCatching {
            recorder.apply {
                setAudioSource(MediaRecorder.AudioSource.VOICE_COMMUNICATION)
                if (opus) {
                    setOutputFormat(MediaRecorder.OutputFormat.OGG)
                    setAudioEncoder(MediaRecorder.AudioEncoder.OPUS)
                    // What Opus is tuned for, and what a spoken message needs.
                    setAudioSamplingRate(48_000)
                    setAudioEncodingBitRate(24_000)
                } else {
                    setOutputFormat(MediaRecorder.OutputFormat.MPEG_4)
                    setAudioEncoder(MediaRecorder.AudioEncoder.AAC)
                    setAudioSamplingRate(44_100)
                    setAudioEncodingBitRate(64_000)
                }
                setAudioChannels(1)
                // The ceiling, enforced by the recorder rather than by a timer
                // somewhere else: a recording walked away from is precisely the
                // one nobody is watching a timer for.
                setMaxDuration(MAX_SECONDS * 1000)
                setOutputFile(file.absolutePath)
                prepare()
                start()
            }
            Recording(recorder, file, System.currentTimeMillis(), contentType)
        }.getOrElse {
            runCatching { recorder.release() }
            file.delete()
            null
        }
    }

    /**
     * What a recording is called.
     *
     * Named for when it was, so a channel of them reads as a list rather than
     * as six files called "audio". Local time, because it is a label for
     * whoever is looking at it and not a timestamp anything parses.
     */
    private fun name(at: Long = System.currentTimeMillis()): String {
        val stamp = java.text.SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US)
            .format(java.util.Date(at))
        return "voice_$stamp"
    }

    /**
     * Raw amplitude samples, as the bars a player draws.
     *
     * Two steps, and the second is the one that matters. Downsampling to a
     * fixed count makes every message the same width, so a three-second
     * message and a three-minute one are the same shape of thing. Normalising
     * against the loudest bar makes a quiet recording look like a recording
     * rather than like silence - input gain varies by an order of magnitude
     * between phones, and a waveform is read as a shape, never a measurement.
     *
     * A floor under every bar, because a waveform with gaps in it reads as a
     * damaged file rather than as a pause for breath.
     */
    fun toWaveform(samples: List<Float>, bars: Int = WAVEFORM_BARS): List<Float> {
        if (samples.isEmpty()) return emptyList()

        val buckets = List(bars) { index ->
            val from = index * samples.size / bars
            val to = maxOf(from + 1, (index + 1) * samples.size / bars)
            (from until minOf(to, samples.size)).map { samples[it] }.average().toFloat()
        }

        val loudest = buckets.max()
        // Everything was silence: a flat line is honest, and dividing by zero
        // is not.
        if (loudest <= 0f) return buckets.map { MIN_BAR }
        return buckets.map { (it / loudest).coerceIn(MIN_BAR, 1f) }
    }

    /** `m:ss`, which is how long a voice message is ever worth spelling out. */
    fun formatDuration(seconds: Float): String {
        val whole = seconds.toInt().coerceAtLeast(0)
        return "${whole / 60}:${(whole % 60).toString().padStart(2, '0')}"
    }

    /** Whether a picked file is one of these, for the row that draws it. */
    fun isVoice(uri: Uri): Boolean = uri.lastPathSegment?.startsWith("voice_") == true
}

package com.aatech.betweenus.feature.home

import androidx.compose.foundation.background
