/**
 * Home: friends, requests, and the conversations they belong to.
 *
 * The port of `apps/desktop/src/features/home/FriendsView.tsx`. Opening a
 * direct message from here is the only way one gets created, on every client.
 *
 * The field at the top narrows *this list*; it does not go looking for
 * strangers. Finding somebody new is [AddFriendScreen], behind the button in
 * the header, which is the split the desktop's "Add friend" tab already makes:
 * a box that searched the directory while sitting above the friends list left
 * people who were already friends sitting in both halves of the same screen.
 */
@Composable
fun FriendsScreen(
    /** Null when the channel list is already on screen beside this one. */
    onOpenMenu: (() -> Unit)?,
    onOpenChannel: (String) -> Unit,
    onAddFriend: () -> Unit,
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val friends by Workspace.friends.collectAsState()
    val statuses by Presence.statuses.collectAsState()

    var query by remember { mutableStateOf("") }
    var note by remember { mutableStateOf<String?>(null) }
    var busy by remember { mutableStateOf(false) }
    /** Who a Block button was pressed for, until the sentence has been read. */
    var blocking by remember { mutableStateOf<UserSummary?>(null) }

    var permissionTick by remember { mutableIntStateOf(0) }
    LifecycleResumeEffect(Unit) {
        permissionTick++
        onPauseOrDispose { }
    }

    var notificationBannerDismissed by rememberSaveable { mutableStateOf(false) }
    val notificationsGranted = remember(permissionTick) {
        BetweenUsPermissions.granted(context, BetweenUsPermissions.NOTIFICATIONS)
    }

    val notificationLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestPermission(),
    ) { allowed ->
        permissionTick++
        if (!allowed) {
            BetweenUsPermissions.openSettings(context)
        }
    }

    LaunchedEffect(Unit) { Workspace.loadFriends() }

    // Local, and on both halves of a name: the list is already in memory, so
    // filtering it is not a round trip, and somebody typing "sam" is as likely
    // to be after the display name as the username.
    val term = query.trim()
    fun matches(friend: Friend): Boolean =
        term.isEmpty() ||
            friend.user.username.contains(term, ignoreCase = true) ||
            friend.user.displayName.contains(term, ignoreCase = true)

    val incoming = friends.filter { it.incoming && matches(it) }
    val outgoing = friends.filter { it.outgoing && matches(it) }
    val accepted = friends.filter { it.status.name == "ACCEPTED" && matches(it) }
    val filtering = term.isNotEmpty()

    fun act(block: suspend () -> Unit) {
        scope.launch {
            busy = true
            note = runCatching { block() }.exceptionOrNull()?.let { Session.messageOf(it) }
            busy = false
        }
    }

    Column(
        Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .navigationBarsPadding(),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surfaceContainer)
                .statusBarsPadding()
                .padding(start = 4.dp, end = 12.dp, top = 6.dp, bottom = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            // Absent on a tablet or an unfolded foldable: a button that opens a
            // panel already open is a control that appears to do nothing.
            onOpenMenu?.let {
                IconAction(BetweenUsIcons.LayoutSidebar, "Open the channel list", it)
            }
            Text(
                text = "Friends",
                style = MaterialTheme.typography.titleLargeEmphasized,
                color = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier.weight(1f).padding(start = 8.dp),
            )
            IconAction(BetweenUsIcons.UserPlus, "Add a friend", onAddFriend)
        }

        // Notification Permission Warning Banner (if user denied or turned off notifications)
        if (BetweenUsPermissions.NOTIFICATIONS != null && !notificationsGranted && !notificationBannerDismissed) {
            NotificationPermissionBanner(
                onEnable = {
                    notificationLauncher.launch(BetweenUsPermissions.NOTIFICATIONS)
                },
                onDismiss = {
                    notificationBannerDismissed = true
                },
            )
        }

        LazyColumn(Modifier.fillMaxSize()) {
            item {
                Column(Modifier.padding(horizontal = 12.dp, vertical = 12.dp)) {
                    BetweenUsField(
                        label = "Search your friends",
                        value = query,
                        onValueChange = { query = it; note = null },
                        placeholder = "A name on this list",
                        imeAction = ImeAction.Search,
                        enabled = !busy,
                    )
                    note?.let {
                        Notice(it, MaterialTheme.colorScheme.error, Modifier.padding(top = 8.dp))
                    }
                }
            }

            if (incoming.isNotEmpty()) {
                item { SectionLabel("Wants to be friends") }
                items(incoming, key = { "in-${it.user.id}" }) { friend ->
                    PersonRow(
                        user = friend.user,
                        status = statuses[friend.user.id]?.wire ?: "offline",
                        trailing = {
                            IconAction(BetweenUsIcons.Check, "Accept", tint = StatusOnline, onClick = {
                                act { BetweenUsApi.acceptFriend(friend.user.id); Workspace.loadFriends() }
                            })
                            IconAction(BetweenUsIcons.X, "Refuse", tint = MaterialTheme.colorScheme.error, onClick = {
                                act { BetweenUsApi.removeFriend(friend.user.id); Workspace.loadFriends() }
                            })
                        },
                    )
                }
            }

            if (outgoing.isNotEmpty()) {
                item { SectionLabel("Asked") }
                items(outgoing, key = { "out-${it.user.id}" }) { friend ->
                    PersonRow(
                        user = friend.user,
                        status = statuses[friend.user.id]?.wire ?: "offline",
                        trailing = { Chip("Pending") },
                    )
                }
            }

            item { SectionLabel("Friends") }
            if (accepted.isEmpty()) {
                item {
                    EmptyState(
                        icon = BetweenUsIcons.Users,
                        title = if (filtering) "Nobody on this list matches" else "No friends yet",
                        detail = if (filtering) {
                            "This only searches the people you are already friends with. " +
                                "Use Add friend to look for somebody else."
                        } else {
                            "Add friend, at the top, finds somebody to send the first request to."
                        },
                        action = if (filtering) null else {
                            { BetweenUsButton("Add friend", onAddFriend) }
                        },
                    )
                }
            }
            items(accepted, key = { "friend-${it.user.id}" }) { friend ->
                PersonRow(
                    user = friend.user,
                    status = statuses[friend.user.id]?.wire ?: "offline",
                    onClick = {
                        act {
                            val direct = Workspace.openDirect(friend.user.id)
                            onOpenChannel(direct.channelId)
                        }
                    },
                    trailing = {
                        IconAction(BetweenUsIcons.Message, "Open a conversation", {
                            act {
                                val direct = Workspace.openDirect(friend.user.id)
                                onOpenChannel(direct.channelId)
                            }
                        })
                        IconAction(BetweenUsIcons.X, "Remove", tint = MaterialTheme.colorScheme.error, onClick = {
                            act { BetweenUsApi.removeFriend(friend.user.id); Workspace.loadFriends() }
                        })
                        IconAction(
                            BetweenUsIcons.Block,
                            "Block ${friend.user.label}",
                            tint = MaterialTheme.colorScheme.error,
                            onClick = { blocking = friend.user },
                        )
                    },
                )
            }
        }
    }

    // Confirmed, because it is not the same button as Remove: it ends the
    // friendship *and* closes the conversation, and neither side can start it
    // again while it stands. The sentence about nothing being deleted is the
    // part somebody actually needs to read.
    blocking?.let { person ->
        AlertDialog(
            onDismissRequest = { blocking = null },
            title = { Text("Block ${person.label}?") },
            text = {
                Text(
                    "They will not be able to message you or send you a request, and your " +
                        "conversation disappears for both of you.\n\n" +
                        "Nothing is deleted - unblocking brings it back. You can undo this in " +
                        "Settings.",
                )
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        blocking = null
                        act { Workspace.block(person.id) }
                    },
                ) {
                    Text("Block", color = MaterialTheme.colorScheme.error)
                }
            },
            dismissButton = {
                TextButton(onClick = { blocking = null }) { Text("Cancel") }
            },
        )
    }
}

@Composable
private fun PersonRow(
    user: UserSummary,
    status: String,
    onClick: (() -> Unit)? = null,
    trailing: @Composable androidx.compose.foundation.layout.RowScope.() -> Unit,
) {
    ListRow(
        title = user.label,
        subtitle = user.handle,
        leading = {
            AvatarWithStatus(
                id = user.id,
                label = user.label,
                url = user.avatarUrl?.let { Endpoint.absolute(it) },
                status = status,
                size = 36.dp,
            )
        },
        trailing = trailing,
        onClick = onClick,
    )
}

