import com.aatech.betweenus.ui.theme.Slate400
import com.aatech.betweenus.ui.theme.Slate500

/**
 * Who somebody is: their picture, whether they are here, when they were last
 * here, and their about line.
 *
 * The same card the desktop opens when the pointer rests on a name, reached by
 * the gesture a phone has instead of hovering - a double tap on the message, on
 * the face beside it or on the header. A sheet rather than a floating card
 * because a phone has no room beside anything, and the gesture that opens it is
 * one nothing else on the row had claimed: a single tap does nothing, a long
 * press opens the message's own actions, and a swipe replies.
 *
 * It reads presence live rather than taking a snapshot, so somebody who comes
 * online while the sheet is open stops reading as away without it being closed
 * and opened again.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ProfileSheet(
    /**
     * Who to draw, as whoever opened the sheet knows them. It may be a message's
     * author, which carries no about line - see `person` below.
     */
    personArg: UserSummary,
    onDismiss: () -> Unit,
) {
    val sheet = rememberModalBottomSheetState(skipPartiallyExpanded = true)
    val statuses by Presence.statuses.collectAsState()
    val lastSeen by Presence.lastSeen.collectAsState()
    val members by Workspace.members.collectAsState()
    val friends by Workspace.friends.collectAsState()
    val directs by Workspace.directChannels.collectAsState()

    /**
     * The fullest copy of this person the app is holding.
     *
     * A message carries who wrote it - an id, a name and a picture - and never
     * an about line: the same person writes fifty messages, and fifty copies of
     * one sentence in a channel's history is fifty copies to keep in step when
     * they edit it. So the sheet opened from a message was handed a summary with
     * an empty `about` and drew no About section at all, which looked like the
     * feature was missing rather than like the data was somewhere else.
     *
     * It is somewhere else: the member list, the friend list and the
     * conversation list all carry it, because those are fetched per person
     * rather than per message. Resolved here rather than at each call site so
     * that every way into this sheet - a message, a face, a header, a member
     * row - gets the same answer.
     *
     * Whatever was passed in stays the fallback, so somebody who has left the
     * server still gets a sheet with their name and their presence on it.
     */
    val person = remember(personArg, members, friends, directs) {
        // The first copy that actually carries a line, not the first copy that
        // exists: a member row whose about is blank must not shadow the friend
        // row that has one, which is the same person seen through two lists.
        val candidates = sequence {
            members.values.forEach { list ->
                list.forEach { if (it.userId == personArg.id) yield(it.summary) }
            }
            friends.forEach { if (it.user.id == personArg.id) yield(it.user) }
            directs.forEach { if (it.participant.id == personArg.id) yield(it.participant) }
        }.toList()
        // Merged rather than "the first copy that has an about line": the cover
        // and the about line are carried by different lists - a member row has
        // both, a friend row has neither - so picking one winning copy loses
        // whichever field that copy happens to be missing.
        (candidates.firstOrNull { it.about.isNotBlank() } ?: personArg).copy(
            coverUrl = candidates.firstNotNullOfOrNull { it.coverUrl } ?: personArg.coverUrl,
        )
    }

    // A `presence.sync` carries only the people who are here, so the one case
    // the line exists for is the one the socket has said nothing about. Asked
    // once, when the sheet opens: a timestamp a few minutes stale reads
    // identically, and somebody coming back arrives as an event of its own.
    LaunchedEffect(person.id) { Presence.askLastSeen(listOf(person.id)) }

    val status = statuses[person.id] ?: PresenceStatus.OFFLINE
    // `profile` and not `sentence`: a sheet always says something. Offline with
    // no timestamp - a new account, or one whose last seen is hidden from you -
    // used to draw nothing at all here, which read as a sheet that had failed
    // to load rather than as somebody nobody has seen.
    val line = LastSeen.profile(status, lastSeen[person.id])

    ModalBottomSheet(onDismissRequest = onDismiss, sheetState = sheet) {
        // A short band rather than the full one the screen below draws: this is
        // a sheet, and a picture tall enough to be looked at properly is the
        // reason that screen exists.
        ProfileCover(coverUrl = person.coverUrl?.let { Endpoint.absolute(it) }, height = 72.dp)

        Column(
            Modifier
                .fillMaxWidth()
                .navigationBarsPadding()
                .padding(horizontal = 20.dp)
                .padding(top = 16.dp, bottom = 24.dp),
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(14.dp),
                modifier = Modifier.fillMaxWidth(),
            ) {
                AvatarWithStatus(
                    id = person.id,
                    label = person.label,
                    url = person.avatarUrl?.let { Endpoint.absolute(it) },
                    status = status.wire,
                    size = 56.dp,
                )
                Column(Modifier.weight(1f)) {
                    Text(
                        text = person.label,
                        style = MaterialTheme.typography.titleMediumEmphasized,
                        color = MaterialTheme.colorScheme.onSurface,
                        maxLines = 1,
                    )
                    person.handle?.let {
                        Text(text = it, style = MaterialTheme.typography.bodySmall, color = Slate500)
                    }
                    Text(
                        text = line,
                        style = MaterialTheme.typography.bodySmall,
                        color = Slate400,
                        modifier = Modifier.padding(top = 2.dp),
                    )
                }
            }

            // Drawn only when there is one. A heading over an empty space is a
            // section that looks like it failed to load.
            if (person.about.isNotBlank()) {
                Spacer(Modifier.height(18.dp))
                HorizontalDivider()
                Spacer(Modifier.height(14.dp))
                Text(
                    text = "ABOUT",
                    style = MaterialTheme.typography.labelSmall,
                    color = Slate500,
                )
                Text(
                    text = person.about,
                    style = MaterialTheme.typography.bodyMedium,
                    color = Slate200,
                    // Clamped here and nowhere else: a sheet that grows past a
                    // few lines starts covering the conversation it was opened
                    // from. The whole line is one tap away, below.
                    maxLines = 4,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.padding(top = 6.dp),
                )
            }

            Spacer(Modifier.height(18.dp))
            BetweenUsButton(
                text = "View full profile",
                onClick = {
                    // Closed first: two things at this depth on screen at once
                    // leaves the sheet visible behind a full-screen dialog, and
                    // dismissing that one would reveal a sheet nobody asked to
                    // still be open.
                    onDismiss()
                    FullProfile.open(person)
                },
                modifier = Modifier.fillMaxWidth(),
            )
        }
    }
}

package com.aatech.betweenus.feature.notifications

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import androidx.core.app.RemoteInput
import com.aatech.betweenus.core.data.AuthPhase
import com.aatech.betweenus.core.data.BetweenUsApi
import com.aatech.betweenus.core.data.Session
import com.aatech.betweenus.core.store.Conversation
import com.aatech.betweenus.feature.chat.Outbox
import com.aatech.betweenus.core.store.Workspace
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch
import kotlinx.coroutines.withTimeoutOrNull

/**
 * What the buttons on a message notification do.
 *
 * All three are broadcasts and none of them opens the app: replying from the
 * shade that opens a chat screen is not replying from the shade. `goAsync` is
 * what buys the time to seal the reply and post it - a receiver's `onReceive`
 * returning is Android's cue that the process may go, and encrypting and
 * sending is a network round trip.
 */
class NotificationActionReceiver : BroadcastReceiver() {

    override fun onReceive(context: Context, intent: Intent) {
        val channelId = intent.getStringExtra(EXTRA_CHANNEL_ID) ?: return
        val application = context.applicationContext

        when (intent.action) {
            ACTION_DISMISS -> {
                // Swiped away: forget the thread so the next message starts a
                // fresh one rather than re-posting what was dismissed.
                MessageNotifications.clear(application, channelId)
                return
            }

            ACTION_DECLINE_CALL -> {
                // Not answering is a decision, and it lasts as long as the
                // call does: every arrival and departure is another roster
                // push, and each one would ring again.
                SocialNotifications.declineCall(application, channelId)

                // And it is a decision for the *account*, not for this phone.
                // A ring lands on every device signed in, so saying no here
                // and nowhere else leaves a laptop ringing at somebody who has
                // already decided. Best effort: the ringer on this phone is
                // already down, which is what the button asked for, and the
                // other devices ring out on their own timer if this fails.
                val pending = goAsync()
                scope.launch {
                    try {
                        withTimeoutOrNull(TIMEOUT_MS) {
                            PushGate.ensureSession()
                            runCatching { BetweenUsApi.declineCall(channelId) }
                        }
                    } finally {
                        pending.finish()
                    }
                }
                return
            }

            ACTION_MARK_READ -> {
                val pending = goAsync()
                scope.launch {
                    try {
                        withTimeoutOrNull(TIMEOUT_MS) {
                            PushGate.ensureSession()
                            Workspace.markRead(channelId)
                        }
                        MessageNotifications.clear(application, channelId)
                    } finally {
                        pending.finish()
                    }
                }
                return
            }

            ACTION_REPLY -> {
                val text = RemoteInput.getResultsFromIntent(intent)
                    ?.getCharSequence(MessageNotifications.REPLY_KEY)
                    ?.toString()
                    ?.trim()
                    .orEmpty()
                if (text.isEmpty()) return

                val pending = goAsync()
                scope.launch {
                    try {
                        val sent = withTimeoutOrNull(TIMEOUT_MS) {
                            PushGate.ensureSession() ?: return@withTimeoutOrNull false
                            runCatching { Conversation.send(channelId, text, emptyList()) }.isSuccess
                        } ?: false

                        // Offline, or the send failed: the words are kept on
                        // disk and go out on the next network rather than
                        // disappearing, which is what used to happen and
                        // happened without a word.
                        if (!sent) Outbox.enqueueText(application, channelId, text)

                        val self = (Session.state.value as? AuthPhase.SignedIn)?.user
                        if (self != null) {
                            // Shown back in the thread, which is what makes a
                            // reply from the shade feel like it went anywhere.
                            MessageNotifications.noteOwnReply(
                                context = application,
                                channelId = channelId,
                                conversationTitle = PushGate.conversationTitle(channelId),
                                isGroup = PushGate.isGroup(channelId),
                                selfName = self.label,
                                // Said plainly while it is still queued: a
                                // reply shown as sent and then not sent is the
                                // failure this whole change is about.
                                text = if (sent) text else "$text (sending…)",
                            )
                            // The reply is the read: nobody replies to a
                            // conversation and then wants it still unread.
                            if (sent) Workspace.markRead(channelId)
                        }
                    } finally {
                        pending.finish()
                    }
                }
            }
        }
    }

    companion object {
        const val ACTION_REPLY = "com.aatech.betweenus.notification.REPLY"
        const val ACTION_MARK_READ = "com.aatech.betweenus.notification.MARK_READ"
        const val ACTION_DISMISS = "com.aatech.betweenus.notification.DISMISS"
        const val ACTION_DECLINE_CALL = "com.aatech.betweenus.notification.DECLINE_CALL"
        const val EXTRA_CHANNEL_ID = "channelId"

        /**
         * A broadcast receiver is given about ten seconds. Sealing a message
         * and posting it is well inside that on any working connection, and
         * giving up is better than being killed halfway.
         */
        private const val TIMEOUT_MS = 8_000L

        private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    }
}

package com.aatech.betweenus.feature.notifications

import android.graphics.Bitmap
import com.aatech.betweenus.core.crypto.E2ee
import com.aatech.betweenus.core.data.AuthPhase
import com.aatech.betweenus.core.data.Http
import com.aatech.betweenus.core.data.MessageBody
import com.aatech.betweenus.core.data.PushTokens
import com.aatech.betweenus.core.data.Session
import com.aatech.betweenus.core.store.Conversation
import com.aatech.betweenus.core.store.Workspace
import com.aatech.betweenus.feature.voice.CallService
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeoutOrNull

/**
 * Where a push arrives.
 *
 * The payload is data-only and deliberately so: the words are sealed with the
 * channel key, so no server could write a notification worth reading, and no
 * server knows whether this phone is already showing the conversation. Both
 * decisions are made here, which is the same shape WhatsApp has and the reason
 * a message that arrives while you are reading it makes no sound.
 *
 * The order of the gates matters. Cheap and local first - my own message, the
 * channel on screen - then the session, then the key, then the picture. A push
 * that is going to be dropped should cost nothing.
 *
 * Five kinds arrive here. One of them - `message.deleted` - exists to take a
 * notification off the screen rather than put one on it, and is the only one
 * that is allowed to do its work with no session and no key: removing
 * something already drawn needs neither.
 */
class PushService : FirebaseMessagingService() {

    /**
     * FCM rotated the token: after a restore, a clear-data, or on its own
     * schedule. The old one is dead the moment this is called, so the row has
     * to be updated before the next message is sent to nowhere.
     */
    override fun onNewToken(token: String) {
        scope.launch { PushTokens.register() }
    }

    /**
     * `onMessageReceived` is given a background thread and a short window, and
     * the process may be killed the moment it returns - so the work is done
     * here and blocked on, rather than launched and hoped for.
     */
    override fun onMessageReceived(message: RemoteMessage) {
        val data = message.data
        runBlocking {
            withTimeoutOrNull(BUDGET_MS) {
                when (data["type"]) {
                    "message.created" -> handle(data)
                    "message.deleted" -> handleDeleted(data)
                    "channel.read" -> handleRead(data)
                    "friend.request" -> handleFriend(data, accepted = false)
                    "friend.accepted" -> handleFriend(data, accepted = true)
                    "server.member.added" -> handleServerAdded(data)
                    "call.roster" -> handleCallRoster(data)
                    "call.ring" -> handleCallRing(data)
                    "call.handled" -> handleCallHandled(data)
                    "remote.session" -> handleRemoteSession(data)
                    else -> Unit
                }
            }
        }
    }

    /**
     * A message was deleted, so the notification drawn for it is a lie.
     *
     * No session, no channel key and no preferences: there is nothing to read
     * and nothing to decide. Either this device drew that message, in which
     * case the line goes, or it did not, in which case this costs one map
     * lookup. It is the one push that is never suppressed - a notification
     * standing for a message that no longer exists is the thing being fixed,
     * and every gate here is a way to leave it standing.
     */
    private fun handleDeleted(data: Map<String, String>) {
        val channelId = data["channelId"] ?: return
        val messageId = data["messageId"] ?: return
        MessageNotifications.remove(
            context = applicationContext,
            channelId = channelId,
            messageId = messageId,
            conversationTitle = PushGate.conversationTitle(channelId),
            isGroup = PushGate.isGroup(channelId),
            selfName = (Session.state.value as? AuthPhase.SignedIn)?.user?.label.orEmpty(),
        )
    }

    /**
     * This account read the conversation on another of its devices.
     *
     * The notification here has been dealt with by somebody sitting at a
     * laptop, and a phone still showing it is a phone asking to be checked for
     * something already seen. The unread badge goes with it, for the same
     * reason.
     *
     * Like a deletion, this is never suppressed and needs nothing: no session,
     * no channel key, no preferences. Every gate here would be a way to leave a
     * notification standing that its owner has already answered.
     *
     * The device that did the reading gets this too and has nothing to do -
     * opening the channel cleared its own notification a moment ago.
     */
    private fun handleRead(data: Map<String, String>) {
        val channelId = data["channelId"] ?: return
        MessageNotifications.clear(applicationContext, channelId)
        Workspace.noteReadElsewhere(channelId)
    }

    /** Somebody asked to be friends, or said yes. No words, so nothing to open. */
    private suspend fun handleFriend(data: Map<String, String>, accepted: Boolean) {
        val actorId = data["actorId"] ?: return
        if (!wanted()) return
        SocialNotifications.friend(
            context = applicationContext,
            actorId = actorId,
            actorName = data["actorName"].orEmpty().ifBlank { "Someone" },
            actorAvatar = avatar(data["actorAvatarUrl"]),
            accepted = accepted,
        )
        // The friends screen reads its list from the network, so it has to be
        // told there is something new to read.
        runCatching { withTimeoutOrNull(REFRESH_MS) { Workspace.refresh() } }
    }

    /** Added to a server. The workspace is refreshed so it is actually there. */
    private suspend fun handleServerAdded(data: Map<String, String>) {
        val serverId = data["serverId"] ?: return
        if (!wanted()) return
        runCatching { withTimeoutOrNull(REFRESH_MS) { Workspace.refresh() } }
        SocialNotifications.serverAdded(
            context = applicationContext,
            serverId = serverId,
            serverName = data["serverName"].orEmpty().ifBlank { "a server" },
            icon = avatar(data["serverIconUrl"]),
        )
    }

    /**
     * Somebody started or ended a remote session on a machine this account owns.
     *
     * **`wanted()` is not consulted, and that is the point.** Every other
     * notification here can be muted, because a mute is somebody choosing not
     * to be told about a conversation. This one is somebody being told that
     * their machine is being driven while they are not at it, and a
     * notification a mute could switch off is a notification an attacker could
     * arrange to be switched off. The server already refuses to send it to an
     * account that has turned notifications off entirely, which is the account
     * saying it wants no pushes at all rather than "not this one".
     */
    private fun handleRemoteSession(data: Map<String, String>) {
        val sessionId = data["sessionId"] ?: return
        SocialNotifications.remoteSession(
            context = applicationContext,
            sessionId = sessionId,
            machineName = data["machineName"].orEmpty().ifBlank { "your machine" },
            actorName = data["actorName"].orEmpty().ifBlank { "Someone" },
            started = data["state"] != "ended",
        )
    }

    /**
     * Who is in a call in a channel this account can hear and is not in.
     *
     * A roster of nobody is the call ending, and it cancels rather than posts -
     * so it runs before every gate below it. A phone that was told about a call
     * and then told nothing has a notification for a call that finished an hour
     * ago, which is worse than never having been told.
     */
    private suspend fun handleCallRoster(data: Map<String, String>) {
        val channelId = data["channelId"] ?: return
        val count = data["count"]?.toIntOrNull() ?: 0
        if (count == 0) {
            SocialNotifications.clearCall(applicationContext, channelId)
            return
        }
        if (!wanted()) return
        // The channel is open in front of somebody: the call is already on
        // their screen, in the roster under the channel.
        if (PushGate.shouldSuppress(channelId)) return
        runCatching { withTimeoutOrNull(REFRESH_MS) { Workspace.refresh() } }

        // A direct conversation is somebody calling *you*, and that rings: a
        // full-screen answer screen over a locked phone. A server's voice
        // channel is something happening nearby, and it keeps the quiet
        // notification below - a phone that rings for every one of those is a
        // phone somebody turns notifications off on.
        val direct = Workspace.directChannel(channelId)
        if (direct != null) {
            SocialNotifications.ringing(
                context = applicationContext,
                channelId = channelId,
                caller = data["participants"].orEmpty().ifBlank { direct.participant.label },
                callerPicture = avatar(direct.participant.avatarUrl),
            )
            return
        }

        SocialNotifications.callRoster(
            context = applicationContext,
            channelId = channelId,
            channelName = Workspace.channel(channelId)?.name ?: "a channel",
            participants = data["participants"].orEmpty(),
            count = count,
        )
    }

    /**
     * Somebody is ringing this phone into a call.
     *
     * The aimed version of [handleCallRoster], and the difference is what
     * earns the full-screen answer screen for a server's voice channel too: a
     * person pressed a button with this account's name under it, where a
     * roster is a fact about a room that everybody in it gets told.
     *
     * Two things stop it. Being in a call already - a ringer over your own
     * call is a way to be hung up on by accident - and the ordinary gates:
     * quiet hours are minutes on this phone's clock, so the server sent this
     * and left the decision here. Muting the *caller* was decided on the
     * server, which is where the preference lives.
     *
     * A muted channel deliberately does not stop it: muting a room is saying
     * you do not want to hear about the room, not that a colleague may never
     * call you from it.
     */
    /**
     * This account answered or declined that ring somewhere else.
     *
     * A ring is aimed at an account and lands on every device it owns, so
     * dealing with it on one of them left the rest ringing at somebody who was
     * already talking, or who had already said no - until they timed out, or
     * until the whole call ended. Neither half could be seen from here.
     * Answering puts the account in the roster, and the roster announcement
     * goes to everyone who can hear the channel *minus whoever is in the
     * call*; declining was not sent anywhere at all.
     *
     * `how` decides what this phone remembers afterwards. A decline has to
     * last as long as the call does, or the next roster this device has not
     * seen yet rings it again for something already refused.
     *
     * No session, no preferences and no gates. There is nothing to draw and
     * nothing to decide: an account that has switched notifications off can
     * still have a ringer up from before it did, and taking one down is not a
     * notification.
     */
    private fun handleCallHandled(data: Map<String, String>) {
        val channelId = data["channelId"] ?: return
        if (data["how"] == "declined") {
            SocialNotifications.declineCall(applicationContext, channelId)
        } else {
            SocialNotifications.clearRinging(applicationContext, channelId)
        }
    }

    private suspend fun handleCallRing(data: Map<String, String>) {
        val channelId = data["channelId"] ?: return
        if (CallService.inCall) return
        if (!wanted()) return
        // So the channel exists by the time Answer hands it to MainActivity.
        runCatching { withTimeoutOrNull(REFRESH_MS) { Workspace.refresh() } }

        SocialNotifications.ringing(
            context = applicationContext,
            channelId = channelId,
            caller = data["callerName"].orEmpty().ifBlank { "Someone" },
            callerPicture = avatar(data["callerAvatarUrl"]),
        )
    }

    /**
     * The gates every notification-drawing push shares: a session to be sure
     * whose phone this is, and quiet hours, which are minutes on this phone's
     * clock and therefore nobody else's decision to make.
     *
     * The server has already refused the account that turned notifications off.
     */
    private suspend fun wanted(): Boolean {
        PushGate.ensureSession() ?: return false
        val preferences = PushGate.preferences()
        if (preferences?.enabled == false) return false
        return !PushGate.quiet(preferences)
    }

    private suspend fun handle(data: Map<String, String>) {
        val channelId = data["channelId"] ?: return
        val authorId = data["authorId"] ?: return
        val content = data["content"] ?: return

        // Somebody's own message, sent from their other machine. It is already
        // on their screen everywhere it matters.
        val selfId = (Session.state.value as? AuthPhase.SignedIn)?.user?.id
        if (selfId != null && authorId == selfId) return

        // The WhatsApp rule, and the reason a push is data-only at all: the
        // conversation is open, in front of somebody, right now. Both halves
        // are needed - a locked phone still has the chat screen composed.
        if (PushGate.shouldSuppress(channelId)) return

        val self = PushGate.ensureSession() ?: return
        if (authorId == self.id) return

        val preferences = PushGate.preferences()
        if (preferences?.enabled == false) return
        if (channelId in preferences?.mutedChannelIds.orEmpty()) return
        // Quiet hours are minutes on this phone's clock, which is why the
        // server sent the push and left the decision here.
        if (PushGate.quiet(preferences)) return

        // Names for the conversation come out of the workspace, which a cold
        // process fills from its local cache before it asks the network.
        runCatching { withTimeoutOrNull(REFRESH_MS) { Workspace.refresh() } }

        val plaintext = runCatching { E2ee.decryptForChannel(channelId, content) }.getOrNull()
        val body = plaintext?.let { MessageBody.decode(it) }

        // A mentions-only channel: the mention is inside the body, so this is
        // the first moment anybody could have checked. An unreadable body in
        // such a channel stays silent - guessing loudly is the worse mistake.
        if (data["mentionsOnly"] == "1") {
            val text = body?.text ?: return
            if (!PushGate.mentions(text, self)) return
        }

        val text = describe(body)
        val image = body?.attachments?.firstOrNull { it.isImage }?.let { attachment ->
            runCatching {
                withTimeoutOrNull(ATTACHMENT_MS) {
                    MessageNotifications.decodeForNotification(
                        Conversation.openAttachment(channelId, attachment),
                    )
                }
            }.getOrNull()
        }

        MessageNotifications.show(
            context = applicationContext,
            channelId = channelId,
            messageId = data["messageId"].orEmpty(),
            conversationTitle = PushGate.conversationTitle(channelId),
            isGroup = PushGate.isGroup(channelId),
            selfName = self.label,
            authorId = authorId,
            authorName = data["authorName"].orEmpty().ifBlank { "Someone" },
            authorAvatar = avatar(data["authorAvatarUrl"]),
            text = text,
            at = System.currentTimeMillis(),
            image = image,
        )

        // The badge, so opening the app agrees with the notification that woke
        // it. Harmless when the socket already counted it: the same channel is
        // marked read the moment it is opened.
        Workspace.noteUnread(channelId, 1)
    }

    /**
     * What to show when there are no words.
     *
     * An undecryptable body is not an error to hide: this device has not been
     * given the channel key yet, and saying so is better than a notification
     * that reads as an empty message.
     */
    private fun describe(body: MessageBody?): String {
        if (body == null) return "New message"
        val attachments = body.attachments
        if (body.text.isNotBlank()) return body.text
        val picture = attachments.count { it.isImage }
        val video = attachments.count { it.isVideo }
        return when {
            picture > 0 && video == 0 -> if (picture == 1) "Photo" else "$picture photos"
            video > 0 && picture == 0 -> if (video == 1) "Video" else "$video videos"
            attachments.isNotEmpty() -> "${attachments.size} attachments"
            else -> "New message"
        }
    }

    /** The sender's picture, which is stored in the clear and is just a URL. */
    private fun avatar(url: String?): Bitmap? {
        if (url.isNullOrBlank()) return null
        return runCatching {
            val response = Http.get(url)
            if (response.status !in 200..299) return null
            MessageNotifications.decodeForNotification(response.bytes, maxPixels = 128)
        }.getOrNull()
    }

    companion object {
        /**
         * FCM allows around twenty seconds of work for a high-priority message.
         * Fifteen leaves room to post the notification after the budget is up
         * rather than being killed mid-decrypt.
         */
        private const val BUDGET_MS = 15_000L
        private const val REFRESH_MS = 4_000L
        private const val ATTACHMENT_MS = 8_000L

        private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    }
}

