data class PermissionDetailData(
    val id: String,
    val title: String,
    val category: String,
    val icon: Int,
    val overview: String,
    val whyNeeded: String,
    val technicalDetails: String,
    val privacyGuarantee: String,
    val permissions: List<String>,
    val requiresAny: Boolean = false,
)

fun getPermissionDetailData(id: String): PermissionDetailData {
    return when (id) {
        "notifications" -> PermissionDetailData(
            id = "notifications",
            title = "Notifications",
            category = "Alerts & Incoming Calls",
            icon = BetweenUsIcons.Bell,
            overview = "Alerts for incoming direct messages, server mentions, incoming voice/video calls, and remote sessions.",
            whyNeeded = "On Android 13 (API 33)+, apps must explicitly request notification access. Without it, Android blocks all notifications when the app is in the background or closed.",
            technicalDetails = "Delivered via background data push. The system displays high-priority CallStyle heads-up banners for incoming calls and standard notifications for chats.",
            privacyGuarantee = "Push payloads are data-only and end-to-end encrypted. Message bodies are decrypted locally on your device only when received.",
            permissions = listOfNotNull(BetweenUsPermissions.NOTIFICATIONS),
        )
        "mic" -> PermissionDetailData(
            id = "mic",
            title = "Microphone",
            category = "Calls & Voice Channels",
            icon = BetweenUsIcons.Mic,
            overview = "Speaking in voice channels, 1-on-1 audio/video calls, and recording voice notes.",
            whyNeeded = "Required to capture your voice in real time and stream it to call participants over WebRTC mesh.",
            technicalDetails = "Processes audio using Opus codec at 48 kHz. Supports noise suppression, acoustic echo cancellation, and software gate sensitivity.",
            privacyGuarantee = "No background audio capture. Active only while in an ongoing call or recording a voice note. Android 12+ privacy dot displays when active.",
            permissions = listOf(BetweenUsPermissions.MICROPHONE),
        )
        "camera" -> PermissionDetailData(
            id = "camera",
            title = "Camera",
            category = "Video Calls & Media Capture",
            icon = BetweenUsIcons.Video,
            overview = "Streaming live video during calls and capturing instant photos to send in chats.",
            whyNeeded = "Required when you choose to turn your camera on during a video call or take an instant picture to attach.",
            technicalDetails = "Streams VP8/H.264 video peer-to-peer over DTLS-SRTP encrypted connections.",
            privacyGuarantee = "Camera is never turned on automatically. It activates strictly when you press the video toggle in a call or snap a photo.",
            permissions = listOf(BetweenUsPermissions.CAMERA),
        )
        "bluetooth" -> PermissionDetailData(
            id = "bluetooth",
            title = "Nearby Devices",
            category = "Wireless Audio Routing",
            icon = BetweenUsIcons.Speaker,
            overview = "Detecting, connecting, and routing call audio to Bluetooth wireless headsets and earbuds.",
            whyNeeded = "Android 12+ requires the BLUETOOTH_CONNECT permission to discover paired Bluetooth headsets and route voice audio.",
            technicalDetails = "Communicates with Android AudioManager to dynamically route call audio between built-in earpiece, speakerphone, and Bluetooth headsets.",
            privacyGuarantee = "BetweenUs does not scan for nearby beacons or track location. It only queries already-paired Bluetooth audio peripherals.",
            permissions = listOfNotNull(BetweenUsPermissions.BLUETOOTH),
        )
        "media" -> PermissionDetailData(
            id = "media",
            title = "Photos & Media Storage",
            category = "Gallery & File Attachments",
            icon = BetweenUsIcons.Image,
            overview = "Browsing and attaching images and videos directly from your local device gallery into chats.",
            whyNeeded = "Allows fast in-app inline gallery thumbnail previews when opening the attachment sheet.",
            technicalDetails = "Reads local MediaStore images and videos. Selected media is encrypted with AES-256-GCM prior to chunked upload.",
            privacyGuarantee = "Only images you explicitly choose to attach are encrypted and sent. The system document picker works even without this permission.",
            permissions = BetweenUsPermissions.MEDIA,
            requiresAny = true,
        )
        else -> PermissionDetailData(
            id = id,
            title = "App Permission",
            category = "Device Access",
            icon = BetweenUsIcons.Shield,
            overview = "Hardware or platform capability requested by BetweenUs.",
            whyNeeded = "Used to provide core secure communication capabilities.",
            technicalDetails = "Android runtime permission system.",
            privacyGuarantee = "Protected by end-to-end encryption and strict client-side controls.",
            permissions = emptyList(),
        )
    }
}

/**
 * Dedicated Full Sub-Page for an Individual Android Permission.
 *
 * Provides deep architectural rationales, hardware usage details, live permission state,
 * interactive request launchers, and system settings integration for a specific permission.
 */
@Composable
fun PermissionDetailScreen(
    permissionId: String,
    onBack: () -> Unit,
    onNavigateToSettings: (() -> Unit)? = null,
) {
    val context = LocalContext.current
    val data = remember(permissionId) { getPermissionDetailData(permissionId) }

    var tick by remember { mutableIntStateOf(0) }
    LifecycleResumeEffect(Unit) {
        tick++
        onPauseOrDispose { }
    }

    var refused by remember { mutableStateOf(false) }

    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions(),
    ) { results ->
        tick++
        if (results.values.any { !it }) {
            refused = true
        }
    }

    val isGranted = remember(tick, data) {
        if (data.permissions.isEmpty()) true
        else if (data.requiresAny) {
            BetweenUsPermissions.anyGranted(context, data.permissions)
        } else {
            data.permissions.all { BetweenUsPermissions.granted(context, it) }
        }
    }

    fun request() {
        val missing = if (data.requiresAny) {
            if (BetweenUsPermissions.anyGranted(context, data.permissions)) emptyList() else data.permissions
        } else {
            data.permissions.filterNot { BetweenUsPermissions.granted(context, it) }
        }
        if (missing.isNotEmpty()) {
            launcher.launch(missing.toTypedArray())
        }
    }

    Column(
        Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .navigationBarsPadding(),
    ) {
        // --- Top Bar ---
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surfaceContainer)
                .statusBarsPadding()
                .padding(start = 4.dp, end = 12.dp, top = 6.dp, bottom = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            IconAction(BetweenUsIcons.ChevronLeft, "Back", onBack)
            Text(
                text = data.title,
                style = MaterialTheme.typography.titleLargeEmphasized,
                color = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier.weight(1f).padding(start = 8.dp),
            )
            Chip(
                text = "System Settings",
                onClick = { BetweenUsPermissions.openSettings(context) },
            )
        }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 12.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp),
        ) {
            // --- Hero Status Card ---
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(16.dp))
                    .background(MaterialTheme.colorScheme.surfaceContainer)
                    .border(
                        1.dp,
                        if (isGranted) StatusOnline.copy(alpha = 0.35f) else MaterialTheme.colorScheme.outlineVariant,
                        RoundedCornerShape(16.dp),
                    )
                    .padding(20.dp),
            ) {
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth(),
                ) {
                    Box(
                        modifier = Modifier
                            .size(64.dp)
                            .clip(CircleShape)
                            .background(
                                if (isGranted) StatusOnline.copy(alpha = 0.15f)
                                else MaterialTheme.colorScheme.primaryContainer,
                            ),
                        contentAlignment = Alignment.Center,
                    ) {
                        BetweenUsIcon(
                            icon = data.icon,
                            tint = if (isGranted) StatusOnline else MaterialTheme.colorScheme.primary,
                            size = 32.dp,
                        )
                    }

                    Text(
                        text = data.title,
                        style = MaterialTheme.typography.titleLargeEmphasized,
                        color = MaterialTheme.colorScheme.onSurface,
                    )

                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        modifier = Modifier
                            .clip(RoundedCornerShape(8.dp))
                            .background(
                                if (isGranted) StatusOnline.copy(alpha = 0.15f)
                                else if (refused) StatusIdle.copy(alpha = 0.15f)
                                else MaterialTheme.colorScheme.surfaceContainerHighest,
                            )
                            .padding(horizontal = 12.dp, vertical = 6.dp),
                    ) {
                        BetweenUsIcon(
                            icon = if (isGranted) BetweenUsIcons.Check else if (refused) BetweenUsIcons.X else BetweenUsIcons.Shield,
                            tint = if (isGranted) StatusOnline else if (refused) StatusIdle else MaterialTheme.colorScheme.onSurfaceVariant,
                            size = 16.dp,
                        )
                        Text(
                            text = if (isGranted) "Permission Granted" else if (refused) "Permission Refused" else "Permission Required",
                            style = MaterialTheme.typography.labelLarge,
                            fontWeight = FontWeight.Bold,
                            color = if (isGranted) StatusOnline else if (refused) StatusIdle else MaterialTheme.colorScheme.onSurface,
                        )
                    }

                    Text(
                        text = data.overview,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.padding(top = 4.dp),
                    )
                }
            }

            // --- Why Needed Section ---
            SectionLabel("Why BetweenUs Needs This")
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(12.dp))
                    .background(MaterialTheme.colorScheme.surfaceContainer)
                    .padding(14.dp),
            ) {
                Text(
                    text = data.whyNeeded,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurface,
                )
            }

            // --- Technical Operation ---
            SectionLabel("Technical Operation & Hardware")
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(12.dp))
                    .background(MaterialTheme.colorScheme.surfaceContainer)
                    .padding(14.dp),
            ) {
                Text(
                    text = data.technicalDetails,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurface,
                )
            }

            // --- Privacy & Security Guarantee ---
            SectionLabel("Privacy & Encryption")
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(12.dp))
                    .background(MaterialTheme.colorScheme.surfaceContainer)
                    .padding(14.dp),
            ) {
                Text(
                    text = data.privacyGuarantee,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }

            Spacer(Modifier.height(8.dp))

            // --- Action Buttons ---
            if (!isGranted) {
                BetweenUsButton(
                    text = if (refused) "Open System Settings" else "Grant ${data.title} Access",
                    onClick = {
                        if (refused) BetweenUsPermissions.openSettings(context)
                        else request()
                    },
                    modifier = Modifier.fillMaxWidth(),
                )
            }

            OutlinedButton(
                onClick = { BetweenUsPermissions.openSettings(context) },
                shape = RoundedCornerShape(12.dp),
                colors = ButtonDefaults.outlinedButtonColors(
                    contentColor = MaterialTheme.colorScheme.onSurface,
                ),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                modifier = Modifier
                    .fillMaxWidth()
                    .height(48.dp),
            ) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    BetweenUsIcon(BetweenUsIcons.Settings, size = 18.dp)
                    Text(
                        text = "Android System App Settings",
                        style = MaterialTheme.typography.bodyMedium,
                    )
                }
            }

            Spacer(Modifier.height(24.dp))
        }
    }
}

package com.aatech.betweenus.feature.settings

import android.Manifest
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import android.os.Build
import android.provider.Settings
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.platform.LocalContext
import androidx.core.content.ContextCompat

/**
 * Android's runtime permissions, asked for at the moment they mean something.
 *
 * Nothing here is requested on launch. A microphone prompt before anybody has
 * joined a call is a prompt with no context, and the honest answer to it is
 * "no" - which then has to be undone in system settings rather than by tapping
 * the thing again. So each one is tied to the action that needs it:
 *
 *   RECORD_AUDIO      joining a voice channel
 *   CAMERA            turning the camera on inside a call, or taking a photo
 *                     to send
 *   READ_MEDIA_*      opening the attachment sheet, for the grid of recent
 *                     photos - and only for that; the system photo picker and
 *                     the document browser need nothing
 *   POST_NOTIFICATIONS  the first time a notification would be worth showing
 *
 * A permanently refused permission is not asked for twice; the caller is told,
 * and offers the settings screen instead.
 */
object BetweenUsPermissions {
    const val MICROPHONE = Manifest.permission.RECORD_AUDIO
    const val CAMERA = Manifest.permission.CAMERA

    /**
     * Only exists from API 31, and declaring it in the manifest is not holding
     * it: without the grant the platform reports no Bluetooth communication
     * device at all, so a paired headset is not offered and cannot be chosen.
     * See `CallAudio`.
     */
    val BLUETOOTH: String? =
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            Manifest.permission.BLUETOOTH_CONNECT
        } else {
            null
        }

    /** Only exists from API 33; before that a notification needs no permission. */
    val NOTIFICATIONS: String? =
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            Manifest.permission.POST_NOTIFICATIONS
        } else {
            null
        }

    /** Only needed on API <= 28 for writing to public storage; API 29+ uses Scoped MediaStore without permission. */
    val WRITE_STORAGE: String? =
        if (Build.VERSION.SDK_INT <= Build.VERSION_CODES.P) {
            Manifest.permission.WRITE_EXTERNAL_STORAGE
        } else {
            null
        }

    /**
     * What it takes to read the phone's photos, which changed twice.
     *
     * API 33 split storage into per-type permissions; API 34 added a third that
     * means "these photos and no others", granted precisely when the first two
     * are refused. So this is a list and the test is [anyGranted]: holding only
     * the user-selected one is real access to a real set of photos, and calling
     * that "no" would show an empty grid to somebody who had just chosen what
     * to share.
     */
    val MEDIA: List<String> = when {
        Build.VERSION.SDK_INT >= 34 -> listOf(
            Manifest.permission.READ_MEDIA_IMAGES,
            Manifest.permission.READ_MEDIA_VIDEO,
            Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED,
        )

        Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU -> listOf(
            Manifest.permission.READ_MEDIA_IMAGES,
            Manifest.permission.READ_MEDIA_VIDEO,
        )

        else -> listOf(Manifest.permission.READ_EXTERNAL_STORAGE)
    }

    /**
     * Everything the app can ask for, in the order the global screen lists it.
     *
     * The list is what a person is shown up front; it is not a gate. Every one
     * of these is still asked for again at the moment it is needed, because
     * somebody who skipped the screen - or refused one thing on it - has to be
     * able to change their mind by tapping the thing they wanted.
     */
    fun all(): List<String> = listOfNotNull(NOTIFICATIONS, MICROPHONE, CAMERA, BLUETOOTH) + MEDIA

    /**
     * How many of them are not held, with the photo permissions counted as the
     * one thing they are: on API 34 holding "only these photos" is access, and
     * counting the other two as missing would say two things are wrong when
     * nothing is.
     */
    fun missing(context: Context): Int {
        val singles = listOfNotNull(NOTIFICATIONS, MICROPHONE, CAMERA, BLUETOOTH)
            .count { !granted(context, it) }
        return singles + if (anyGranted(context, MEDIA)) 0 else 1
    }

    fun granted(context: Context, permission: String?): Boolean =
        permission == null ||
            ContextCompat.checkSelfPermission(context, permission) == PackageManager.PERMISSION_GRANTED

    /** True when at least one of [permissions] is held. See [MEDIA]. */
    fun anyGranted(context: Context, permissions: List<String>): Boolean =
        permissions.any { granted(context, it) }

    /**
     * Whether the global screen has been shown once.
     *
     * Once, and never again on its own: a screen full of prompts is worth
     * showing on the way in and is nagging on the way back. It stays reachable
     * from settings afterwards.
     */
    fun introduced(context: Context): Boolean =
        prefs(context).getBoolean("introduced", false)

    fun markIntroduced(context: Context) {
        prefs(context).edit().putBoolean("introduced", true).apply()
    }

    private fun prefs(context: Context) =
        context.applicationContext.getSharedPreferences("betweenus.permissions", Context.MODE_PRIVATE)

    fun openSettings(context: Context) {
        context.startActivity(
            Intent(
                Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                Uri.fromParts("package", context.packageName, null),
            ).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
        )
    }
}

/**
 * Asks for one permission when the action that needs it is taken.
 *
 * Returns a function to call at that moment: it runs [onGranted] straight away
 * if the permission is already held, and otherwise asks and runs it on the way
 * back. [refused] turns true once the system has stopped showing the dialog, so
 * a screen can say what is missing rather than appearing to do nothing.
 */
@Composable
fun rememberPermission(
    permission: String?,
    onGranted: () -> Unit,
): PermissionRequest {
    val context = LocalContext.current
    var refused by remember { mutableStateOf(false) }

    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestPermission(),
    ) { allowed ->
        refused = !allowed
        if (allowed) onGranted()
    }

    return PermissionRequest(
        refused = refused,
        onRequest = {
            if (BetweenUsPermissions.granted(context, permission)) {
                onGranted()
            } else {
                refused = false
                launcher.launch(permission!!)
            }
        },
        onOpenSettings = { BetweenUsPermissions.openSettings(context) },
    )
}

/**
 * Asks for several permissions at once, where only [required] decides whether
 * the action goes ahead.
 *
 * Joining a call is the case this exists for. It needs the microphone, and it
 * wants notifications - a call that cannot show its ongoing notification still
 * works, it is just harder to get back to - so refusing the second must not
 * refuse the first. Android shows the prompts one after another and reports
 * them together.
 */
@Composable
fun rememberPermissions(
    permissions: List<String>,
    required: String,
    onGranted: () -> Unit,
): PermissionRequest {
    val context = LocalContext.current
    var refused by remember { mutableStateOf(false) }
    val asked = remember(permissions) { permissions.distinct() }

    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions(),
    ) { results ->
        val allowed = results[required] ?: BetweenUsPermissions.granted(context, required)
        refused = !allowed
        if (allowed) onGranted()
    }

    return PermissionRequest(
        refused = refused,
        onRequest = {
            val missing = asked.filterNot { BetweenUsPermissions.granted(context, it) }
            if (missing.isEmpty()) {
                onGranted()
            } else {
                refused = false
                launcher.launch(missing.toTypedArray())
            }
        },
        onOpenSettings = { BetweenUsPermissions.openSettings(context) },
    )
}

/**
 * Functions, not `() -> Unit` properties, and that is the point.
 *
 * As properties, `camera.request` compiled - it is a perfectly good lambda
 * value - and did nothing, so the camera button in a call silently never asked
 * for the permission and never turned the camera on. As a member function the
 * same line will not compile. Anywhere one is genuinely wanted as a callback,
 * `{ camera.request() }` says so.
 */
/**
 * Asks for a set of permissions where holding any one of them is enough.
 *
 * Reading photos is the case this exists for: on API 34 "only these photos" is
 * a different permission from "all photos", and somebody who chose the first
 * has granted access, not refused it. See [BetweenUsPermissions.MEDIA].
 */
@Composable
fun rememberAnyPermission(
    permissions: List<String>,
    onGranted: () -> Unit,
): PermissionRequest {
    val context = LocalContext.current
    var refused by remember { mutableStateOf(false) }

    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions(),
    ) {
        // The results map is not consulted: what matters is what is held now,
        // and on API 34 the system can grant a permission that was not asked
        // for in place of one that was.
        val allowed = BetweenUsPermissions.anyGranted(context, permissions)
        refused = !allowed
        if (allowed) onGranted()
    }

    return PermissionRequest(
        refused = refused,
        onRequest = {
            if (BetweenUsPermissions.anyGranted(context, permissions)) {
                onGranted()
            } else {
                refused = false
                launcher.launch(permissions.toTypedArray())
            }
        },
        onOpenSettings = { BetweenUsPermissions.openSettings(context) },
    )
}

class PermissionRequest(
    val refused: Boolean,
    private val onRequest: () -> Unit,
    private val onOpenSettings: () -> Unit,
) {
    fun request() = onRequest()

    fun openSettings() = onOpenSettings()
}

