import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontStyle
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextDecoration
import androidx.compose.ui.unit.dp
import com.aatech.betweenus.core.data.Markup
import com.aatech.betweenus.ui.theme.Edge
import com.aatech.betweenus.ui.theme.Slate100
import com.aatech.betweenus.ui.theme.Slate300
import com.aatech.betweenus.ui.theme.Slate400
import com.aatech.betweenus.ui.theme.Slate500
import com.aatech.betweenus.ui.theme.Surface950

/**
 * A GitHub release body, drawn.
 *
 * The notes are markdown - `### Features` and a list under it, `**bold**`, a
 * fenced block of shell - and until this they were dropped into a single [Text]
 * with the hashes, asterisks and backticks still in them. Which is exactly the
 * shape that makes somebody stop reading the thing telling them what changed.
 *
 * It is the message parser, not a second one: [Markup.parseNotes] is
 * [Markup.parse] with headings switched on, because a heading in a chat line is
 * shouting and a release note is nothing but headings. What is not shared is
 * the drawing - `MessageRow` lays custom emoji and tappable links over its
 * blocks, and none of that belongs in a changelog.
 *
 * The desktop client draws the same blocks in `components/ReleaseNotes.tsx`.
 * Changing one changes both, or the same release reads differently on two
 * screens.
 */
@Composable
fun ReleaseNotes(notes: String, modifier: Modifier = Modifier) {
    val blocks = remember(notes) {
        // parseNotes treats a blank line as a paragraph break, so nothing
        // empty should come back. This is the belt to that pair of braces: an
        // empty block draws as an empty row on top of the spacing this already
        // has, and a release note has a blank line under every heading.
        Markup.parseNotes(notes.trim())
            .filter { it.kind != Markup.Kind.Body || it.text.isNotBlank() }
    }
    if (blocks.isEmpty()) return

    Column(modifier = modifier, verticalArrangement = Arrangement.spacedBy(4.dp)) {
        blocks.forEach { block ->
            when (block.kind) {
                Markup.Kind.Heading -> Text(
                    text = annotate(block),
                    // Two sizes, not six. A release note's own `##` and `###`
                    // are the only levels that appear, and a changelog in a
                    // sheet needs its sections findable, not an outline.
                    style = if (block.ordinal <= 2) {
                        MaterialTheme.typography.titleSmall
                    } else {
                        MaterialTheme.typography.labelLarge
                    },
                    color = Slate100,
                    modifier = Modifier.padding(top = 6.dp),
                )

                Markup.Kind.Bullet, Markup.Kind.Number -> Row(Modifier.fillMaxWidth()) {
                    // The marker sits in a gutter of its own rather than
                    // inline, so a wrapped item lines up under its own first
                    // word instead of under the bullet.
                    Text(
                        text = if (block.kind == Markup.Kind.Number) "${block.ordinal}." else "\u2022",
                        style = MaterialTheme.typography.bodySmall,
                        color = Slate500,
                        modifier = Modifier.width(18.dp),
                    )
                    Text(
                        text = annotate(block),
                        style = MaterialTheme.typography.bodySmall,
                        color = Slate300,
                    )
                }

                Markup.Kind.Code -> Text(
                    text = block.text,
                    style = MaterialTheme.typography.bodySmall,
                    fontFamily = FontFamily.Monospace,
                    color = Slate300,
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(6.dp))
                        .background(Surface950)
                        .padding(horizontal = 10.dp, vertical = 8.dp),
                )

                Markup.Kind.Quote -> Row(Modifier.height(IntrinsicSize.Min)) {
                    Box(
                        modifier = Modifier
                            .width(3.dp)
                            .fillMaxHeight()
                            .clip(RoundedCornerShape(2.dp))
                            .background(Edge),
                    )
                    Text(
                        text = annotate(block),
                        style = MaterialTheme.typography.bodySmall,
                        color = Slate400,
                        modifier = Modifier.padding(start = 8.dp),
                    )
                }

                Markup.Kind.Body -> Text(
                    text = annotate(block),
                    style = MaterialTheme.typography.bodySmall,
                    color = Slate300,
                )
            }
        }
    }
}

/** A block's words, with its styles laid over them. */
private fun annotate(block: Markup.Block) = buildAnnotatedString {
    append(block.text)
    block.spans.forEach { span ->
        // Clamped, because a style is only as trustworthy as the string it was
        // measured against.
        val from = span.start.coerceIn(0, length)
        val to = span.end.coerceIn(from, length)
        if (to > from) addStyle(span.style.span(), from, to)
    }
}

private fun Markup.Style.span(): SpanStyle = when (this) {
    Markup.Style.Bold -> SpanStyle(fontWeight = FontWeight.Bold, color = Slate100)
    Markup.Style.Italic -> SpanStyle(fontStyle = FontStyle.Italic)
    Markup.Style.Strike -> SpanStyle(textDecoration = TextDecoration.LineThrough)
    Markup.Style.Code -> SpanStyle(fontFamily = FontFamily.Monospace, background = Surface950)
}

package com.aatech.betweenus.feature.update

/**
 * What a GitHub release is, and which one of them this device should install.
 *
 * All of it is pure: no Android, no network, no clock. The release workflow
 * names versions `0.0.2-alpha.1`, `0.0.2-beta.1` and `0.0.2`, and names the
 * APKs `BetweenUs-<version>-<abi>.apk` with a `universal` one alongside them -
 * so picking the right build is entirely a matter of parsing two strings, and
 * the parsing is the part worth testing. See `.github/workflows/release.yml`.
 */

/** Which builds a device is willing to be offered. */
enum class UpdateChannel(val label: String, val detail: String, val stage: Int) {
    STABLE("Stable", "Finished releases only.", Version.STABLE),
    BETA("Beta", "Release candidates, plus every stable release.", Version.BETA),
    ALPHA("Alpha", "Everything, the moment it is built.", Version.ALPHA);

    /**
     * A channel takes its own builds and everything steadier. Somebody on beta
     * who is offered nothing but betas would never be offered the stable
     * release that supersedes the one they are running.
     */
    fun accepts(version: Version): Boolean = version.stage >= stage

    companion object {
        fun of(name: String?): UpdateChannel =
            entries.firstOrNull { it.name.equals(name, ignoreCase = true) } ?: STABLE

        /**
         * The channel a build belongs to, used as the default: somebody who
         * installed an alpha wants alphas, and defaulting them to stable would
         * strand them until the version they are running is released.
         */
        fun forVersion(versionName: String): UpdateChannel = when (Version.parse(versionName)?.stage) {
            Version.ALPHA -> ALPHA
            Version.BETA -> BETA
            else -> STABLE
        }
    }
}

/**
 * A semantic version, ordered.
 *
 * Only the shapes the release workflow can produce are understood -
 * `1.2.3`, `1.2.3-alpha.4`, `1.2.3-beta.4`, with or without a leading `v`.
 * Anything else parses to null and is skipped rather than guessed at, because
 * a guess here installs the wrong APK.
 */
data class Version(
    val major: Int,
    val minor: Int,
    val patch: Int,
    val stage: Int,
    val stageNumber: Int,
) : Comparable<Version> {

    override fun compareTo(other: Version): Int =
        compareValuesBy(this, other, { it.major }, { it.minor }, { it.patch }, { it.stage }, { it.stageNumber })

    companion object {
        const val ALPHA = 0
        const val BETA = 1
        const val STABLE = 2

        private val PATTERN =
            Regex("""^v?(\d+)\.(\d+)\.(\d+)(?:-(alpha|beta)\.(\d+))?$""", RegexOption.IGNORE_CASE)

        fun parse(text: String?): Version? {
            val match = PATTERN.matchEntire(text?.trim().orEmpty()) ?: return null
            val (major, minor, patch, label, number) = match.destructured
            return Version(
                major = major.toInt(),
                minor = minor.toInt(),
                patch = patch.toInt(),
                stage = when (label.lowercase()) {
                    "alpha" -> ALPHA
                    "beta" -> BETA
                    // No pre-release part at all: the finished release, which
                    // sorts above every pre-release of the same numbers.
                    else -> STABLE
                },
                // A stable release has no pre-release number, and must still
                // beat `-beta.9` of the same version.
                stageNumber = number.toIntOrNull() ?: Int.MAX_VALUE,
            )
        }
    }
}

data class ReleaseAsset(val name: String, val url: String, val size: Long)

data class Release(
    val version: Version,
    val name: String,
    val notes: String,
    val publishedAt: String,
    val assets: List<ReleaseAsset>,
)

object Releases {
    /**
     * Where the APKs come from. A constant rather than a setting: this is the
     * project that signs the builds, and an APK from anywhere else would not
     * install over this one anyway - Android refuses an update signed by a
     * different key.
     */
    const val REPOSITORY = "aiyu-ayaan/BetweenUs"

    const val API = "https://api.github.com/repos/$REPOSITORY/releases?per_page=30"

    /**
     * The newest release on [channel] that is newer than what is installed, or
     * null when there is nothing to offer.
     *
     * "Newer" is by version, never by publish date: a stable release cut after
     * an alpha is still not an upgrade for the person running that alpha.
     */
    fun pick(releases: List<Release>, installed: Version?, channel: UpdateChannel): Release? =
        releases
            .filter { channel.accepts(it.version) }
            .filter { installed == null || it.version > installed }
            .maxByOrNull { it.version }

    /**
     * The APK built for this device, not the universal one.
     *
     * `Build.SUPPORTED_ABIS` is in the device's own order of preference - a
     * 64-bit phone lists `arm64-v8a` before `armeabi-v7a` - so the first match
     * wins. The universal APK carries every ABI's native libraries and is
     * roughly three times the download, which is why it is the fallback and
     * never the choice.
     */
    fun apkFor(release: Release, abis: List<String>): ReleaseAsset? {
        val apks = release.assets.filter { it.name.endsWith(".apk", ignoreCase = true) }
        // Suffix matching, not `contains`: `-x86.apk` must not match
        // `BetweenUs-1.0.0-x86_64.apk`.
        abis.forEach { abi ->
            apks.firstOrNull { it.name.endsWith("-$abi.apk", ignoreCase = true) }?.let { return it }
        }
        return apks.firstOrNull { it.name.endsWith("-universal.apk", ignoreCase = true) }
    }
}

package com.aatech.betweenus.feature.update

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.pm.PackageInstaller

/**
 * How an install ended.
 *
 * A `PackageInstaller` session answers here, and there are only three answers
 * worth acting on:
 *
 *   PENDING_USER_ACTION  the system's confirmation dialog, handed back rather
 *                        than shown. Somebody has to start it, and that is the
 *                        whole reason this receiver exists.
 *   SUCCESS              nothing to do: this process is about to be replaced.
 *   anything else        a reason, said out loud on the update screen.
 *
 * The failure this is really for is `INSTALL_FAILED_UPDATE_INCOMPATIBLE`: an
 * APK signed with a different key from the installed build. It is what somebody
 * sideloading their first release hits, and with the older `ACTION_VIEW` install
 * it appeared as a dialog that closed and an app that had not changed.
 *
 * Not exported. The only thing that may send this is the platform, answering a
 * session this app created.
 */
class UpdateInstallReceiver : BroadcastReceiver() {

    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != ACTION_STATUS) return

        when (intent.getIntExtra(PackageInstaller.EXTRA_STATUS, Int.MIN_VALUE)) {
            PackageInstaller.STATUS_PENDING_USER_ACTION -> {
                val confirm = intent.extra(Intent.EXTRA_INTENT) ?: return
                // Started from a receiver, so it has no task of its own to
                // live in.
                confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                runCatching { context.startActivity(confirm) }
                    .onFailure { Updates.fail(it.message ?: "Android would not show the install screen") }
            }

            // The new build is being written over this one. There is nothing
            // useful to say and nobody left to say it to.
            PackageInstaller.STATUS_SUCCESS -> Unit

            PackageInstaller.STATUS_FAILURE_ABORTED -> Updates.dismiss()

            PackageInstaller.STATUS_FAILURE_CONFLICT -> Updates.fail(
                "Android refused the update: this APK is signed with a different key from the " +
                    "installed build. Uninstall this copy first, and note that uninstalling " +
                    "takes its data with it.",
            )

            else -> Updates.fail(
                intent.getStringExtra(PackageInstaller.EXTRA_STATUS_MESSAGE)
                    ?: "The install failed",
            )
        }
    }

    @Suppress("DEPRECATION")
    private fun Intent.extra(name: String): Intent? =
        if (android.os.Build.VERSION.SDK_INT >= 33) {
            getParcelableExtra(name, Intent::class.java)
        } else {
            getParcelableExtra(name)
        }

    companion object {
        const val ACTION_STATUS = "com.aatech.betweenus.UPDATE_INSTALL_STATUS"
    }
}

package com.aatech.betweenus.feature.update

import android.content.Context
import android.content.Intent
import android.app.PendingIntent
import android.content.SharedPreferences
import android.content.pm.PackageInstaller
import android.net.Uri
import android.os.Build
import android.provider.Settings
import com.aatech.betweenus.BuildConfig
import com.aatech.betweenus.core.data.Http
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.withContext
import okhttp3.Request
import org.json.JSONArray
import java.io.File

/**
 * The app keeping itself up to date, from the GitHub releases it was built by.
 *
 * There is no Play Store in the loop: BetweenUs is self-hosted and its APKs are
 * published by `.github/workflows/release.yml`, so the app has to be the thing
 * that notices a new one. What it does is deliberately small - ask GitHub what
 * exists, work out whether any of it is newer than what is running, download
 * the build for this device's ABI, and hand the file to Android's own package
 * installer.
 *
 * It never installs anything on its own. Android has no silent install for an
 * app that is not the device owner, and it should not: the last screen is
 * always the system's, showing what is about to replace what.
 *
 * The check runs when the app is opened, and once a day while it is not - see
 * [UpdateWorker], which exists because the launch check reaches everybody
 * except the phone that has not opened BetweenUs in three weeks, and that is
 * precisely the phone running a three-week-old build.
 *
 * ponytail: SharedPreferences and one in-memory state, like the endpoint and
 * the audio settings. Six values do not need a database.
 */
object Updates {

    private const val FILE = "betweenus.updates"
    private const val KEY_ENABLED = "enabled"
    private const val KEY_CHANNEL = "channel"
    private const val KEY_SNOOZE_DAYS = "snoozeDays"
    private const val KEY_SNOOZED_UNTIL = "snoozedUntil"
    private const val KEY_LAST_CHECKED = "lastChecked"

    /** One day, which is the point of a snooze: later today is not later. */
    const val DEFAULT_SNOOZE_DAYS = 1

    private const val DAY_MILLIS = 24L * 60 * 60 * 1000

    private lateinit var prefs: SharedPreferences
    private lateinit var downloads: File

    /**
     * The application context, held only so the switch can start and stop the
     * daily job. Nothing else here keeps a context: a settings screen turning
     * auto update off has no business passing one in.
     */
    private var scheduler: Context? = null

    /**
     * What this build is, or null for a checkout whose manifest could not be
     * read and which fell back to `0.0.0`.
     */
    val installed: Version? by lazy { Version.parse(BuildConfig.VERSION_NAME) }

    val installedName: String get() = BuildConfig.VERSION_NAME

    /** The build behind the name - the release run number, or 1 by hand. */
    val installedCode: Int get() = BuildConfig.VERSION_CODE

    private val _state = MutableStateFlow<UpdateState>(UpdateState.Idle)
    val state: StateFlow<UpdateState> = _state.asStateFlow()

    fun init(context: Context) {
        val app = context.applicationContext
        scheduler = app
        prefs = app.getSharedPreferences(FILE, Context.MODE_PRIVATE)
        downloads = File(app.cacheDir, "updates")
        // Idempotent: KEEP leaves an already-running period alone, so this is
        // safe to call on every launch and is the only place it has to be
        // called at all.
        runCatching { UpdateWorker.schedule(app) }
    }

    private val ready: Boolean get() = ::prefs.isInitialized

    /**
     * On by default. An app distributed as an APK has no store to tell anybody
     * a security fix exists, so the useful default is the one that notices.
     */
    var enabled: Boolean
        get() = !ready || prefs.getBoolean(KEY_ENABLED, true)
        set(value) {
            if (ready) prefs.edit().putBoolean(KEY_ENABLED, value).apply()
            if (!value) _state.value = UpdateState.Idle
            // A switch that says "no" and leaves a daily job running is a
            // switch that lied. [scheduler] is set by the application.
            scheduler?.let { context -> runCatching { UpdateWorker.schedule(context) } }
        }

    /**
     * Defaults to the channel this build came from: somebody running an alpha
     * asked for alphas, and defaulting them to stable would strand them on the
     * build they have until its version is released.
     */
    var channel: UpdateChannel
        get() = if (ready && prefs.contains(KEY_CHANNEL)) {
            UpdateChannel.of(prefs.getString(KEY_CHANNEL, null))
        } else {
            UpdateChannel.forVersion(installedName)
        }
        set(value) {
            if (ready) prefs.edit().putString(KEY_CHANNEL, value.name).apply()
            // What was on offer came from the old channel, and on a narrower
            // one it may not be on offer at all.
            _state.value = UpdateState.Idle
        }

    /** How long "not now" lasts. */
    var snoozeDays: Int
        get() = if (ready) prefs.getInt(KEY_SNOOZE_DAYS, DEFAULT_SNOOZE_DAYS) else DEFAULT_SNOOZE_DAYS
        set(value) {
            if (ready) prefs.edit().putInt(KEY_SNOOZE_DAYS, value.coerceIn(1, 30)).apply()
        }

    val lastChecked: Long get() = if (ready) prefs.getLong(KEY_LAST_CHECKED, 0) else 0

    private val snoozedUntil: Long get() = if (ready) prefs.getLong(KEY_SNOOZED_UNTIL, 0) else 0

    /**
     * Quiet until the snooze runs out. Asking again tomorrow is asking; asking
     * again on the next launch is nagging.
     */
    fun snoozed(now: Long = System.currentTimeMillis()): Boolean = now < snoozedUntil

    fun snooze(now: Long = System.currentTimeMillis()) {
        if (ready) {
            prefs.edit().putLong(KEY_SNOOZED_UNTIL, now + snoozeDays * DAY_MILLIS).apply()
        }
        _state.value = UpdateState.Idle
    }

    /** Dismissing the prompt without deciding. It comes back on the next launch. */
    fun dismiss() {
        _state.value = UpdateState.Idle
    }

    /**
     * Ask GitHub what exists.
     *
     * [manual] is the difference between the button on the settings screen and
     * the check on launch: the button says so when there is nothing new and
     * ignores a snooze, and the launch check stays silent.
     */
    suspend fun check(manual: Boolean = false): UpdateState = withContext(Dispatchers.IO) {
        if (!manual && (!enabled || snoozed())) return@withContext _state.value
        _state.value = UpdateState.Checking

        val next = runCatching {
            val response = Http.get(Releases.API)
            if (response.status !in 200..299) error("GitHub answered ${response.status}")
            val releases = parse(response.body)
            val pick = Releases.pick(releases, installed, channel)
                ?: return@runCatching UpdateState.UpToDate
            val apk = Releases.apkFor(pick, Build.SUPPORTED_ABIS.toList())
            // A release with no APK for this device is not an offer. It
            // happens: a release whose Android job failed still exists.
                ?: return@runCatching UpdateState.UpToDate
            UpdateState.Available(pick, apk)
        }.getOrElse { UpdateState.Failed(it.message ?: "The update check failed") }

        if (ready) prefs.edit().putLong(KEY_LAST_CHECKED, System.currentTimeMillis()).apply()
        _state.value = next
        next
    }

    /**
     * The releases GitHub returned, minus the drafts and anything whose tag is
     * not a version this app understands.
     */
    internal fun parse(body: String): List<Release> {
        val array = JSONArray(body)
        return (0 until array.length()).mapNotNull { index ->
            val json = array.getJSONObject(index)
            if (json.optBoolean("draft")) return@mapNotNull null
            val version = Version.parse(json.optString("tag_name")) ?: return@mapNotNull null
            val assets = json.optJSONArray("assets")
            Release(
                version = version,
                name = json.optString("name").ifBlank { json.optString("tag_name") },
                notes = json.optString("body"),
                publishedAt = json.optString("published_at"),
                assets = (0 until (assets?.length() ?: 0)).map { position ->
                    val asset = assets!!.getJSONObject(position)
                    ReleaseAsset(
                        name = asset.optString("name"),
                        url = asset.optString("browser_download_url"),
                        size = asset.optLong("size"),
                    )
                },
            )
        }
    }

    /**
     * Fetch the APK, reporting progress, and leave it in the cache.
     *
     * Streamed to disk rather than read into memory: an APK is tens of
     * megabytes and this app already asks for a large heap for a different
     * reason. The cache is the right place - an installed update has no further
     * use for the file, and Android may reclaim one that was never installed.
     */
    suspend fun download(
        release: Release,
        asset: ReleaseAsset,
        onProgress: (Float) -> Unit = {},
    ): File = withContext(Dispatchers.IO) {
        downloads.mkdirs()
        // Everything else in the directory is a previous attempt or a previous
        // version, and neither is worth keeping.
        downloads.listFiles()?.forEach { if (it.name != asset.name) it.delete() }
        val target = File(downloads, asset.name)
        if (asset.size > 0 && target.length() == asset.size) {
            _state.value = UpdateState.Ready(release, target)
            return@withContext target
        }

        _state.value = UpdateState.Downloading(release, 0f)
        val request = Request.Builder().url(asset.url).build()
        Http.client.newCall(request).execute().use { response ->
            val body = response.body
            if (!response.isSuccessful || body == null) error("The download failed (${response.code})")
            val total = if (asset.size > 0) asset.size else body.contentLength()
            var written = 0L
            body.byteStream().use { input ->
                target.outputStream().use { output ->
                    val buffer = ByteArray(64 * 1024)
                    while (true) {
                        val read = input.read(buffer)
                        if (read == -1) break
                        output.write(buffer, 0, read)
                        written += read
                        if (total > 0) {
                            val fraction = (written.toFloat() / total).coerceIn(0f, 1f)
                            onProgress(fraction)
                            _state.value = UpdateState.Downloading(release, fraction)
                        }
                    }
                }
            }
        }
        _state.value = UpdateState.Ready(release, target)
        target
    }

    /**
     * Whether Android will let this app start an install at all.
     *
     * From API 26 "install unknown apps" is a per-app setting rather than a
     * device-wide one, and it is not a runtime permission: it cannot be asked
     * for with a dialog, only opened in settings. Below 26 the manifest
     * declaration is the whole of it.
     */
    fun canInstall(context: Context): Boolean =
        Build.VERSION.SDK_INT < Build.VERSION_CODES.O || context.packageManager.canRequestPackageInstalls()

    /** The settings page that grants it, for this app alone. */
    fun requestInstallPermission(context: Context) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        context.startActivity(
            Intent(
                Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,
                Uri.parse("package:${context.packageName}"),
            ).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
        )
    }

    /**
     * Hand the APK to Android's package installer, which shows what is about to
     * replace what and asks. That screen is the system's and is not skippable,
     * which is the correct end to this: nothing here installs anything behind
     * anybody's back.
     *
     * A `PackageInstaller` session rather than an `ACTION_VIEW` intent on a
     * `content://` URI. Both end at the same confirmation dialog, and the
     * difference is entirely what happens afterwards: the intent form is fire
     * and forget, so the most likely failure of all - an APK signed with a
     * different key from the installed build, which is what somebody
     * sideloading their first release hits - came back as a dialog that closed
     * and an app that had not changed. A session reports its outcome to
     * [UpdateInstallReceiver], and the reason can be said out loud.
     *
     * Suspending because it copies tens of megabytes into the session, which is
     * not something to do while a finger is still on the button.
     */
    suspend fun install(context: Context, apk: File): Unit = withContext(Dispatchers.IO) {
        val installer = context.applicationContext.packageManager.packageInstaller
        val parameters = PackageInstaller.SessionParams(
            PackageInstaller.SessionParams.MODE_FULL_INSTALL,
        ).apply {
            setAppPackageName(context.packageName)
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) setRequireUserAction(
                PackageInstaller.SessionParams.USER_ACTION_REQUIRED,
            )
        }

        val sessionId = installer.createSession(parameters)
        installer.openSession(sessionId).use { session ->
            session.openWrite(SESSION_FILE, 0, apk.length()).use { sink ->
                apk.inputStream().use { it.copyTo(sink) }
                session.fsync(sink)
            }
            // The receiver is where the answer arrives - including the one that
            // matters, which is "user action required": the system dialog is
            // handed back rather than shown, and something has to start it.
            val status = PendingIntent.getBroadcast(
                context.applicationContext,
                sessionId,
                Intent(context.applicationContext, UpdateInstallReceiver::class.java)
                    .setAction(UpdateInstallReceiver.ACTION_STATUS),
                PendingIntent.FLAG_MUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
            )
            session.commit(status.intentSender)
        }
    }

    private const val SESSION_FILE = "betweenus.apk"

    fun fail(message: String) {
        _state.value = UpdateState.Failed(message)
    }
}

/** Where a check, a download or an install has got to. */
sealed interface UpdateState {
    data object Idle : UpdateState

    data object Checking : UpdateState

    data object UpToDate : UpdateState

    data class Available(val release: Release, val apk: ReleaseAsset) : UpdateState

    data class Downloading(val release: Release, val progress: Float) : UpdateState

    data class Ready(val release: Release, val file: File) : UpdateState

    data class Failed(val message: String) : UpdateState
}

