/**
 * The game the call is playing, on the phone.
 *
 * The referee is `call-service` and the board arrives whole on every change, so
 * this draws what came and sends taps back. Nothing here decides a rule.
 *
 * Three of the six are tappable from a phone and three are watched, and the
 * line between them is not effort - it is whether a legal move can be read off
 * the board. Reversi's cannot without walking eight directions from every empty
 * square, and Ludo's and Carrom's boards live in numbers only their own rules
 * module understands. Porting those to Kotlin would be a second implementation
 * of rules that have exactly one, and the first time the two disagreed it would
 * be two people looking at different games.
 */
@Composable
fun PlayStage(selfId: String, modifier: Modifier = Modifier) {
    val session by Play.session.collectAsStateWithLifecycle()
    val live = session ?: return
    PlayStageContent(live, selfId, modifier)
}

@Composable
private fun PlayStageContent(
    session: GameSession,
    selfId: String,
    modifier: Modifier = Modifier,
) {
    val scheme = MaterialTheme.colorScheme
    val info = Games.of(session.gameId) ?: return
    val state = session.state
    val mySeat = session.seatOf(selfId)
    val myTurn = mySeat >= 0 && mySeat == state.turn && !state.over

    Column(
        modifier = modifier
            .fillMaxWidth()
            .clip(MaterialTheme.shapes.large)
            .background(scheme.surfaceContainerHigh)
            .padding(14.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Column(Modifier.weight(1f)) {
                Text(
                    text = info.name,
                    style = MaterialTheme.typography.titleSmall,
                    color = scheme.onSurface,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = statusLine(session, info.seatNames, mySeat),
                    style = MaterialTheme.typography.bodySmall,
                    color = scheme.onSurfaceVariant,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            IconAction(
                icon = BetweenUsIcons.X,
                contentDescription = "Close the game for everybody",
                onClick = { Play.close() },
            )
        }

        // --- the chairs ---
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            info.seatNames.forEachIndexed { seat, name ->
                val sitter = session.seats.getOrNull(seat)
                val colour = info.seatColours.getOrNull(seat)?.let { Color(it) } ?: scheme.primary
                Row(
                    modifier = Modifier
                        .weight(1f)
                        .clip(MaterialTheme.shapes.small)
                        .background(
                            if (seat == state.turn && !state.over) {
                                colour.copy(alpha = 0.28f)
                            } else {
                                scheme.surfaceContainerHighest
                            },
                        )
                        .padding(horizontal = 8.dp, vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                ) {
                    BetweenUsIcon(
                        icon = BetweenUsIcons.User,
                        size = 14.dp,
                        tint = colour,
                        contentDescription = null,
                    )
                    Text(
                        text = sitter?.username ?: name,
                        style = MaterialTheme.typography.labelMedium,
                        color = if (sitter == null) scheme.onSurfaceVariant else scheme.onSurface,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f),
                    )
                    Text(
                        text = "${session.wins.getOrNull(seat) ?: 0}",
                        style = MaterialTheme.typography.labelMedium,
                        color = scheme.onSurfaceVariant,
                    )
                }
            }
        }

        GameBoard(
            info = info,
            state = state,
            // Tappable only when it is genuinely this person's move. A board
            // that accepts taps out of turn sends moves the referee refuses,
            // which reads as a board that ignores you.
            onMove = if (myTurn && info.playableHere) {
                { move -> Play.move(move) }
            } else {
                null
            },
        )

        // Said, rather than left as a board that does not respond.
        if (!info.playableHere) {
            Text(
                text = "${info.name} is played from a desktop. This phone shows the board, " +
                    "the chairs and the score.",
                style = MaterialTheme.typography.bodySmall,
                color = scheme.onSurfaceVariant,
            )
        }

        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            if (mySeat >= 0) {
                BetweenUsButton(
                    text = "Stand up",
                    onClick = { Play.sit(-1) },
                    modifier = Modifier.weight(1f),
                )
            } else {
                val free = session.seats.indexOfFirst { it == null }
                if (free >= 0) {
                    BetweenUsButton(
                        text = "Take a chair",
                        onClick = { Play.sit(free) },
                        modifier = Modifier.weight(1f),
                    )
                }
            }
            if (state.over) {
                BetweenUsButton(
                    text = "Play again",
                    onClick = { Play.rematch() },
                    modifier = Modifier.weight(1f),
                )
            }
        }
    }
}

/**
 * The one line under the game's name: what just happened, or whose move it is.
 *
 * A finished game says so first. Whose turn it is matters only while there is
 * one, and a board that still says "Your move" after somebody won is the most
 * confusing thing this can say.
 */
fun statusLine(session: GameSession, seatNames: List<String>, mySeat: Int): String {
    val state = session.state
    val winner = state.winner
    if (winner != null) {
        return when {
            winner == -1 -> "A draw."
            winner == mySeat -> "You won."
            else -> "${session.seats.getOrNull(winner)?.username ?: seatNames.getOrNull(winner) ?: "They"} won."
        }
    }
    if (mySeat < 0) {
        val up = session.seats.getOrNull(state.turn)?.username
            ?: seatNames.getOrNull(state.turn)
            ?: "Somebody"
        return "Watching · $up to move"
    }
    return if (state.turn == mySeat) "Your move." else "Their move."
}

/**
 * The library, for starting one.
 *
 * Every game is offered, including the three this phone can only watch: a
 * person on a phone in a call with two desktops is a reasonable person to start
 * a game of Carrom, and refusing to let them would be the phone deciding what
 * the room may play.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun GameLibrarySheet(onDismiss: () -> Unit) {
    val sheet = rememberModalBottomSheetState(skipPartiallyExpanded = true)
    val scheme = MaterialTheme.colorScheme

    ModalBottomSheet(onDismissRequest = onDismiss, sheetState = sheet) {
        Column(Modifier.fillMaxWidth().navigationBarsPadding()) {
            Text(
                text = "Play together",
                style = MaterialTheme.typography.titleMedium,
                color = scheme.onSurface,
                modifier = Modifier.padding(horizontal = 20.dp, vertical = 8.dp),
            )
            LazyColumn(Modifier.padding(bottom = 16.dp)) {
                items(Games.ALL, key = { it.id }) { game ->
                    ListRow(
                        title = game.name,
                        subtitle = if (game.playableHere) {
                            game.blurb
                        } else {
                            "${game.blurb} · Played from a desktop"
                        },
                        leading = { BetweenUsIcon(BetweenUsIcons.Activity) },
                        onClick = {
                            Play.open(game.id)
                            onDismiss()
                        },
                    )
                }
            }
        }
    }
}

package com.aatech.betweenus.feature.voice

import kotlin.math.max
import kotlin.math.min
import kotlin.math.roundToInt

/**
 * What the phone tells the other end it is willing to receive.
 *
 * Sending quality is the sender's business; receiving quality is not. Three
 * things in an SDP decide what arrives, and Android's defaults get all three
 * wrong for a screen share:
 *
 * **The H.264 level.** `profile-level-id` ends in a level byte, and a level is
 * a hard ceiling on resolution and frame rate - 3.1, which is what a phone
 * decoder usually advertises, means 1280x720 at 30. The sender obeys it: a
 * desktop sharing 1080p60 to a phone that asked for level 3.1 encodes 720p30
 * and there is nothing on the receiving end that can put back the difference.
 * Every phone shipping an H.264 decoder in the last decade can decode far more
 * than its default answer admits to, so the level is raised to 5.2.
 *
 * **The bandwidth line.** With no `b=AS` the sender is left to guess, and
 * WebRTC's estimator guesses conservatively. Saying the number is what makes
 * the difference between a picture that sharpens over ten seconds and one that
 * starts sharp.
 *
 * **The start bitrate.** Congestion control begins around 300 kbps and ramps
 * slowly, which on a direct peer-to-peer link is caution paid for by every
 * viewer in the first ten seconds. `x-google-start-bitrate` skips the ramp -
 * with a probe the path can absorb rather than a fraction of the ceiling. See
 * [START_KBPS].
 *
 * Every number written here is a ceiling or a starting point, and none of them
 * is a floor. [bitrateHints] has the one that used to be, and what it cost.
 *
 * The same three the desktop patches into its own descriptions - see
 * `patchVideoBandwidth` in `apps/desktop/src/services/share-quality.ts`. The
 * two clients are talking to each other, so what one asks for the other has to
 * be able to say.
 *
 * Pure string work on purpose: this is the part worth testing, and it needs no
 * peer connection to test.
 */
object SdpQuality {

    /**
     * H.264 level 5.2: 4K at 60, far more than anything here sends. The point
     * is to stop the level being the limit; the bitrate ceiling and congestion
     * control are what actually decide.
     */
    private const val TARGET_LEVEL = 0x34

    /**
     * Where congestion control begins, in kbps.
     *
     * A fast start, not a guess at the link: the estimator has to survive its
     * first probe, and a probe the path cannot absorb is answered with loss,
     * which collapses the estimate far below where it would have climbed on its
     * own. The same number the desktop probes with.
     */
    private const val START_KBPS = 2_500

    /** Video payload types with no encoder behind them. See [bitrateHints]. */
    private val NOT_A_PICTURE = setOf("rtx", "red", "ulpfec", "flexfec-03")

    /** Applies all three to every video section of an SDP. */
    fun patch(sdp: String, maxBitrateBps: Int): String {
        val maxKbps = max(1, (maxBitrateBps / 1000.0).roundToInt())
        val startKbps = min(maxKbps, START_KBPS)

        // Split before each m= line, so a section is one media stream and
        // whatever preceded the first one is left alone.
        return sdp.split(Regex("(?=m=)")).joinToString("") { section ->
            if (!section.startsWith("m=video")) {
                section
            } else {
                section
                    .let { bandwidth(it, maxKbps, maxBitrateBps) }
                    .let { bitrateHints(it, maxKbps, startKbps) }
                    .let { raiseH264Level(it) }
            }
        }
    }

    /**
     * What the microphone is worth, said in the one place Opus listens.
     *
     * Bitrate, stereo and DTX are payload parameters: they live in the `fmtp`
     * line of the audio section and are fixed when the connection is
     * negotiated, which is why they cannot be set on a live sender the way a
     * video bitrate can. The desktop writes the same three - see `micEncoding`
     * in `voice-quality.ts` - and the two clients are talking to each other.
     *
     * `maxaveragebitrate` is in bits per second, and `sprop-stereo` is what
     * tells the *far end* to send stereo; `stereo` is what this end will
     * accept. Both, or a hi-fi call is mono in one direction.
     */
    fun patchAudio(sdp: String, encoding: MicEncoding): String =
        sdp.split(Regex("(?=m=)")).joinToString("") { section ->
            if (!section.startsWith("m=audio")) section else opusParameters(section, encoding)
        }

    internal fun opusParameters(section: String, encoding: MicEncoding): String {
        val payloads = Regex("^a=rtpmap:(\\d+)\\s+opus/48000", RegexOption.MULTILINE)
            .findAll(section)
            .map { it.groupValues[1] }
            .toList()

        val wanted = mapOf(
            "maxaveragebitrate" to encoding.maxBitrate.toString(),
            "stereo" to if (encoding.stereo) "1" else "0",
            "sprop-stereo" to if (encoding.stereo) "1" else "0",
            "usedtx" to if (encoding.dtx) "1" else "0",
            // Redundancy: a packet carries the previous one, so a single loss is
            // inaudible. Cheap at these bitrates and worth it either way.
            "useinbandfec" to "1",
        )

        var patched = section
        for (payload in payloads) {
            val fmtp = Regex("^a=fmtp:$payload (.+)$", RegexOption.MULTILINE)
            val existing = fmtp.find(patched)?.groupValues?.get(1)
            val merged = mergeParameters(existing, wanted)
            patched = if (existing != null) {
                fmtp.spliceFirst(patched) { "a=fmtp:$payload $merged" }
            } else {
                Regex("a=rtpmap:$payload[^\r\n]*\r?\n", RegexOption.MULTILINE)
                    .spliceFirst(patched) { "${it.value}a=fmtp:$payload $merged\r\n" }
            }
        }
        return patched
    }

    /**
     * The parameters already there, with ours laid over them.
     *
     * Merged rather than appended: an `fmtp` line with `stereo=0;stereo=1` in
     * it is a line whose meaning depends on which end reads it first, and the
     * stack that wrote the first copy is not the one that has to agree with it.
     */
    internal fun mergeParameters(existing: String?, wanted: Map<String, String>): String {
        val parameters = LinkedHashMap<String, String>()
        existing
            ?.split(';')
            ?.mapNotNull { it.trim().takeIf(String::isNotEmpty) }
            ?.forEach { entry ->
                val key = entry.substringBefore('=')
                parameters[key] = entry.substringAfter('=', "")
            }
        wanted.forEach { (key, value) -> parameters[key] = value }
        return parameters.entries.joinToString(";") { (key, value) ->
            if (value.isEmpty()) key else "$key=$value"
        }
    }

    /** `b=AS` in kbps and `b=TIAS` in bps, right after the connection line. */
    internal fun bandwidth(section: String, maxKbps: Int, maxBps: Int): String {
        val stripped = section
            .replace(Regex("b=AS:\\d+\\r?\\n", RegexOption.IGNORE_CASE), "")
            .replace(Regex("b=TIAS:\\d+\\r?\\n", RegexOption.IGNORE_CASE), "")

        val lines = "b=AS:$maxKbps\r\nb=TIAS:$maxBps\r\n"
        val connection = Regex("c=IN[^\\r\\n]*\\r?\\n", RegexOption.IGNORE_CASE)
        return if (connection.containsMatchIn(stripped)) {
            connection.spliceFirst(stripped) { "${it.value}$lines" }
        } else {
            Regex("m=video[^\\r\\n]*\\r?\\n").spliceFirst(stripped) { "${it.value}$lines" }
        }
    }

    /**
     * Google's non-standard but universally honoured bitrate hints.
     *
     * A ceiling and a starting point, and never a floor. `x-google-min-bitrate`
     * used to be one - a quarter of the ceiling, so 5 Mbps against the 20 this
     * is called with at negotiation time, which is call-join time, long before
     * anybody shares. An encoder told to meet a bitrate floor its link cannot
     * afford pays for it in pixels, because 640x480 at 5 Mbps is reachable and
     * 1920x1080 is not. Paired with a start of 60% of that same ceiling - 12
     * Mbps thrown at a phone's link in its first second, answered with loss,
     * collapsing the estimate below where it would have climbed unaided - that
     * is the share which starts sharp and is at 480p ten seconds later on a
     * connection with room for 1080p.
     *
     * It matters on this side and not only the desktop's, which fixed the same
     * two numbers: these hints configure whichever encoder reads them, and the
     * ones written into an answer are read by the far end. A phone asking for a
     * floor is a phone telling a desktop to shrink the screen it is sending.
     *
     * Only payloads with an encoder behind them. Retransmission and the error
     * correction codecs share the 90 kHz video clock and have nothing to hint
     * at, and `apt=96` is the whole of an `rtx` format line - appending to it is
     * how a patched description gets refused in one piece, which loses the
     * hints on the codecs that did want them and the raised level with them.
     */
    internal fun bitrateHints(section: String, maxKbps: Int, startKbps: Int): String {
        val hints = "x-google-max-bitrate=$maxKbps;x-google-start-bitrate=$startKbps"

        var patched = section
        for (payload in Regex("^a=rtpmap:(\\d+)\\s+([^\\s/]+)/90000", RegexOption.MULTILINE)
            .findAll(section)
            .filterNot { it.groupValues[2].lowercase() in NOT_A_PICTURE }
            .map { it.groupValues[1] }
            .toList()) {
            val fmtp = Regex("^a=fmtp:$payload (.+)$", RegexOption.MULTILINE)
            patched = if (fmtp.containsMatchIn(patched)) {
                fmtp.spliceFirst(patched) { "a=fmtp:$payload ${it.groupValues[1]};$hints" }
            } else {
                Regex("a=rtpmap:$payload[^\\r\\n]*\\r?\\n", RegexOption.MULTILINE)
                    .spliceFirst(patched) { "${it.value}a=fmtp:$payload $hints\r\n" }
            }
        }
        return patched
    }

    /**
     * Replaces the first match with whatever [transform] makes of it.
     *
     * `Regex.replaceFirst` only takes a literal, and `Regex.replace` with a
     * lambda replaces every match - which here would put the bandwidth line
     * after every connection line in the section.
     */
    private fun Regex.spliceFirst(input: String, transform: (MatchResult) -> String): String {
        val match = find(input) ?: return input
        return input.substring(0, match.range.first) +
            transform(match) +
            input.substring(match.range.last + 1)
    }

    /**
     * Raises the level byte of every `profile-level-id`, leaving the profile
     * and its constraint flags alone - those say what the decoder can parse,
     * and claiming a profile it cannot is a stream it cannot decode at all.
     * The level is the only part being under-claimed.
     */
    internal fun raiseH264Level(section: String): String =
        Regex("profile-level-id=([0-9a-fA-F]{6})").replace(section) { match ->
            val id = match.groupValues[1]
            val level = id.substring(4, 6).toInt(16)
            if (level >= TARGET_LEVEL) {
                match.value
            } else {
                "profile-level-id=${id.substring(0, 4)}${"%02x".format(TARGET_LEVEL)}"
            }
        }
}

package com.aatech.betweenus.feature.voice

import android.annotation.SuppressLint
import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioPlaybackCaptureConfiguration
import android.media.AudioRecord
import android.media.projection.MediaProjection
import android.os.Build
import android.os.Process
import androidx.annotation.RequiresApi
import java.nio.ByteBuffer
import kotlin.math.min

/**
 * The sound coming out of the phone, going out with the shared screen.
 *
 * A share used to be silent. Somebody putting a video, a game or a call on the
 * stage sent every frame of it and none of the sound, and the far end had no
 * way to tell that from a video with no soundtrack.
 *
 * ## Why it rides on the microphone
 *
 * The wire has a `screenAudio` slot and this does not use it, which looks wrong
 * and is not. A track in libwebrtc's Android build can only come from the audio
 * device module, there is exactly one of those per factory, and it reads the
 * microphone: there is no public way to hand arbitrary PCM to a second audio
 * track. So the choice is between no screen sound at all and mixing it into the
 * one capture that does exist, and the far end plays what arrives on the
 * microphone slot either way.
 *
 * Two consequences, both deliberate:
 *
 * - Muting cannot mean "stop the track", because the track is now carrying two
 *   things. [VoiceEngine.applyMute] closes the microphone at the device module
 *   instead, which is where mute has always genuinely happened - the buffer
 *   arrives already zeroed and this adds the screen's sound to the silence.
 * - The mixed signal goes through the call's echo canceller and noise
 *   suppressor, which were tuned for a voice in a room. Music through them is
 *   thinner than music through a path built for it.
 *
 * ponytail: an SFU or a second peer connection would carry this on its own
 * m-line at full quality. Both are much larger than the feature, and this is
 * the version that works today on the library the app already has.
 *
 * ## What is captured
 *
 * `AudioPlaybackCaptureConfiguration` is API 29 and later, and it needs a live
 * `MediaProjection` - the same consent the screen capture is already running
 * under, taken off the capturer rather than asked for again, because the
 * system hands out one projection per consent and asking twice fails.
 *
 * This app's own UID is excluded, and that is not a nicety: without it the
 * capture picks up the call this share is part of and sends the other people
 * in it back to themselves, one buffer late, for ever.
 */
class ShareAudio {

    private var record: AudioRecord? = null

    /** Scratch for one buffer's worth of playback, sized on the first mix. */
    private var scratch = ByteArray(0)

    val running: Boolean get() = record != null

    /**
     * Starts capturing, at the shape the microphone is already being read in.
     *
     * The rate and the channel count are the ones the device module reports on
     * its own capture buffer, so the two streams can be added sample for sample
     * with no resampling and no downmix - which is the only reason this is
     * cheap enough to do on the audio thread.
     *
     * Returns false and leaves nothing running when the platform is too old or
     * the record cannot be built. A share with no sound is the old behaviour;
     * a call that dies because a soundtrack could not start is not.
     */
    fun start(projection: MediaProjection, sampleRate: Int, channelCount: Int): Boolean {
        // minSdk is 24 and playback capture is 29. The whole of the API lives
        // in [open], so a phone below that never loads a class it has no
        // implementation of.
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) return false
        if (record != null) return true
        return open(projection, sampleRate, channelCount)
    }

    @RequiresApi(Build.VERSION_CODES.Q)
    @SuppressLint("MissingPermission")
    private fun open(projection: MediaProjection, sampleRate: Int, channelCount: Int): Boolean {
        return runCatching {
            val configuration = AudioPlaybackCaptureConfiguration.Builder(projection)
                // What a person means by "share the sound": media, games, and
                // the unmarked stream every app that never set a usage plays
                // through. Notifications and ringtones are deliberately absent -
                // sharing a screen must not put somebody's message alerts on
                // the call.
                .addMatchingUsage(AudioAttributes.USAGE_MEDIA)
                .addMatchingUsage(AudioAttributes.USAGE_GAME)
                .addMatchingUsage(AudioAttributes.USAGE_UNKNOWN)
                // Ourselves, or the call feeds itself; see the class comment.
                .excludeUid(Process.myUid())
                .build()

            val mask = if (channelCount >= 2) {
                AudioFormat.CHANNEL_IN_STEREO
            } else {
                AudioFormat.CHANNEL_IN_MONO
            }
            val format = AudioFormat.Builder()
                .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                .setSampleRate(sampleRate)
                .setChannelMask(mask)
                .build()

            // Room for several of the device module's 10ms buffers. The minimum
            // is a figure the platform will accept rather than one that
            // survives a scheduling hiccup, and an underrun here is an audible
            // gap in the shared sound.
            val minimum = AudioRecord.getMinBufferSize(sampleRate, mask, AudioFormat.ENCODING_PCM_16BIT)
            val size = if (minimum > 0) minimum * 2 else sampleRate * channelCount * 2 / 5

            AudioRecord.Builder()
                .setAudioPlaybackCaptureConfig(configuration)
                .setAudioFormat(format)
                .setBufferSizeInBytes(size)
                .build()
                .also { it.startRecording() }
        }.onSuccess { record = it }.isSuccess
    }

    /**
     * Adds whatever the phone has played since the last buffer, in place.
     *
     * On the audio thread, several hundred times a second: an integer pass over
     * the buffer and nothing else. The read is non-blocking on purpose - this
     * thread belongs to the microphone, and waiting here for the playback
     * stream to catch up would stall the call itself rather than the share.
     *
     * ponytail: a shortfall is padded with silence rather than held in a ring
     * buffer, so two clocks drifting apart cost the occasional short gap
     * instead of a growing delay. A jitter buffer is the upgrade if it turns
     * out to be audible.
     */
    fun mix(buffer: ByteBuffer, bytes: Int) {
        val source = record ?: return
        val usable = min(bytes, buffer.capacity())
        if (usable <= 0) return

        if (scratch.size < usable) scratch = ByteArray(usable)
        val read = runCatching {
            source.read(scratch, 0, usable, AudioRecord.READ_NON_BLOCKING)
        }.getOrDefault(0)
        if (read <= 1) return

        var index = 0
        val end = read - 1
        while (index < end) {
            val mic = ((buffer.get(index + 1).toInt() shl 8) or
                (buffer.get(index).toInt() and 0xFF)).toShort()
            val screen = ((scratch[index + 1].toInt() shl 8) or
                (scratch[index].toInt() and 0xFF)).toShort()
            // Added and clipped rather than averaged: halving both would make a
            // person's voice quiet for the whole of every share, which is the
            // wrong trade against the rare moment two loud things coincide.
            val sum = (mic + screen).coerceIn(-32768, 32767)
            buffer.put(index, (sum and 0xFF).toByte())
            buffer.put(index + 1, ((sum shr 8) and 0xFF).toByte())
            index += 2
        }
    }

    /** Stops and releases. Safe to call when nothing was ever started. */
    fun stop() {
        val source = record ?: return
        record = null
        runCatching { source.stop() }
        runCatching { source.release() }
    }
}

