package com.aatech.betweenus.feature.chat

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * The sentence an arrival gets, which is derived rather than stored.
 *
 * The point of these is the last two: they pin the same numbers
 * `apps/desktop/src/features/chat/arrival.check.ts` pins. A phone and a laptop
 * looking at the same conversation have to say the same thing happened in it,
 * and nothing in the row itself says what that is - so the only thing holding
 * the two clients together is that they compute it the same way.
 */
class ArrivalLineTest {

    @Test
    fun `the same id always gets the same line`() {
        val id = "3f1c0b2e-9a4d-4e7b-8c11-6d5a2f0e9b73"
        assertEquals(arrivalLine(id), arrivalLine(id))
    }

    @Test
    fun `an empty id is still a line rather than a crash`() {
        assertEquals("is here.", arrivalLine(""))
    }

    /** 'a' is 97, and 97 % 6 is 1. The desktop check asserts the same. */
    @Test
    fun `single character matches the desktop`() {
        assertEquals("just landed.", arrivalLine("a"))
    }

    /** 97 * 31 + 98 = 3105, and 3105 % 6 is 3. The desktop check asserts the same. */
    @Test
    fun `two characters match the desktop`() {
        assertEquals("joined the party.", arrivalLine("ab"))
    }
}

package com.aatech.betweenus.feature.chat

import com.aatech.betweenus.core.data.Message
import com.aatech.betweenus.core.data.MessageBody
import com.aatech.betweenus.core.data.UserSummary
import com.aatech.betweenus.core.store.ReadableMessage
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The same cases as the desktop's `SearchPanel`, which is where the rules were
 * decided: a floor on the term, deleted rows skipped, the newest matches first,
 * and a snippet that contains what was typed.
 *
 * Worth pinning because every one of them fails silently. A search that ranks
 * oldest-first still returns results; one that matches a tombstone offers a jump
 * to a message that is not there; a snippet taken from the front of a long body
 * shows a result with no visible reason for being a result.
 */
class ChannelSearchTest {

    private fun readable(
        id: String,
        text: String,
        deletedAt: String? = null,
    ) = ReadableMessage(
        message = Message(
            id = id,
            channelId = "c1",
            content = "",
            author = UserSummary("ana", "ana", "Ana", null),
            createdAt = "2026-01-01T10:00:00.000Z",
            editedAt = null,
            deletedAt = deletedAt,
            deletedBy = null,
            pinnedAt = null,
            reactions = emptyList(),
        ),
        body = MessageBody(text = text),
    )

    private val history = listOf(
        readable("m1", "shall we ship it on Friday"),
        readable("m2", "the SHIPPING address is wrong"),
        readable("m3", "nothing to do with it"),
        readable("m4", "ship", deletedAt = "2026-01-02T10:00:00.000Z"),
    )

    @Test
    fun `a term shorter than the floor matches nothing at all`() {
        // Not "everything": one character matches most of a channel, and a
        // list of every message is not an answer to a search.
        assertEquals(emptyList<ReadableMessage>(), searchMessages(history, "s"))
        assertEquals(emptyList<ReadableMessage>(), searchMessages(history, ""))
        assertEquals(emptyList<ReadableMessage>(), searchMessages(history, "   "))
    }

    @Test
    fun `matching is case-insensitive and on any part of the word`() {
        assertEquals(
            listOf("m2", "m1"),
            searchMessages(history, "SHIP").map { it.id },
        )
    }

    @Test
    fun `a deleted message never matches`() {
        // Its body is empty and the row is a tombstone; jumping to it lands on
        // "this message was deleted", which is not what was searched for.
        assertTrue(searchMessages(history, "ship").none { it.id == "m4" })
    }

    @Test
    fun `results are newest first, and capped`() {
        val many = (1..150).map { readable("m$it", "ship number $it") }
        val found = searchMessages(many, "ship")
        assertEquals(SEARCH_LIMIT, found.size)
        // The last hundred, newest first - so the most recent match is at the
        // top and the ones dropped are the oldest.
        assertEquals("m150", found.first().id)
        assertEquals("m51", found.last().id)
    }

    @Test
    fun `the snippet contains the term, wherever it is in the body`() {
        val near = "ship it on Friday"
        assertEquals(near, searchSnippet(near, "ship"))

        val far = "x".repeat(300) + "ship it on Friday"
        val snippet = searchSnippet(far, "ship")
        assertTrue("the snippet should carry the term", snippet.contains("ship"))
        assertTrue("a trimmed snippet says it was trimmed", snippet.startsWith("…"))
    }

    @Test
    fun `a term at the very end of a long body still lands inside the snippet`() {
        // The bound that is easy to get wrong: `at + 120` runs past the end.
        val text = "y".repeat(200) + "ship"
        assertTrue(searchSnippet(text, "ship").contains("ship"))
    }
}

package com.aatech.betweenus.feature.chat

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.ZoneId
import java.util.Locale

/**
 * The message list's date dividers.
 *
 * The desktop's `day.check.ts` holds the same cases. If one of these ever has
 * to change, so does that one.
 */
class DayTest {

    private val today = LocalDate.of(2026, 8, 29) // Saturday

    /** A local timestamp, so the cases read as the reader's own clock does. */
    private fun at(y: Int, m: Int, d: Int, h: Int = 12, min: Int = 0): String =
        LocalDateTime.of(y, m, d, h, min).atZone(ZoneId.systemDefault()).toInstant().toString()

    @Test
    fun `the two days that get names`() {
        assertEquals("Today", dayLabel(at(2026, 8, 29, 9, 14), today))
        // Just past midnight is still today, wherever the server put it.
        assertEquals("Today", dayLabel(at(2026, 8, 29, 0, 5), today))
        assertEquals("Yesterday", dayLabel(at(2026, 8, 28, 23, 55), today))
    }

    @Test
    fun `a weekday for the week just gone`() {
        assertEquals("Monday", dayLabel(at(2026, 8, 24), today))
        assertEquals("Sunday", dayLabel(at(2026, 8, 23), today))
    }

    @Test
    fun `and the date once a weekday would name two days`() {
        val week = dayLabel(at(2026, 8, 22), today)
        assertFalse("a week back must not read as a weekday", week.contains("Saturday"))
        assertTrue(week.contains("2026"))
        assertTrue(dayLabel(at(2025, 3, 4), today).contains("2025"))
    }

    @Test
    fun `where the dividers go`() {
        assertTrue(sameDay(at(2026, 8, 29, 0, 1), at(2026, 8, 29, 23, 59)))
        // Two minutes apart either side of midnight: one run of messages to the
        // grouping rule, two days to the reader, and the divider says so.
        assertFalse(sameDay(at(2026, 8, 28, 23, 59), at(2026, 8, 29, 0, 1)))
    }

    @Test
    fun `the clock follows the device, not the locale`() {
        // The device's *Use 24-hour format* switch decides, whatever the locale
        // would have picked on its own: a reader whose phone says 14:32
        // everywhere else must not be shown 2:32 PM here, or the other way
        // round. The pattern is the locale's way of writing the one it is told.
        val us = Locale.US
        assertTrue(clockPattern(is24Hour = true, locale = us).contains("H"))
        assertFalse(clockPattern(is24Hour = true, locale = us).contains("a"))
        assertTrue(clockPattern(is24Hour = false, locale = us).contains("h"))
        assertTrue(clockPattern(is24Hour = false, locale = us).contains("a"))
        // A locale that is 24-hour by habit still answers the switch.
        val de = Locale.GERMANY
        assertTrue(clockPattern(is24Hour = false, locale = de).contains("h"))
        assertTrue(clockPattern(is24Hour = true, locale = de).contains("H"))
        // Minutes, always.
        assertTrue(clockPattern(is24Hour = true, locale = us).contains("mm"))
    }

    @Test
    fun `nonsense is not a day`() {
        assertEquals("", dayLabel("not a timestamp", today))
        assertFalse(sameDay("not a timestamp", at(2026, 8, 29)))
    }
}

package com.aatech.betweenus.feature.chat

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The message list's latch.
 *
 * Every case here is a bug somebody has already reported: a channel of photos
 * that stopped following the conversation, a chat that opened somewhere in the
 * middle of itself. The rule is arithmetic, so it is checked as arithmetic
 * rather than by scrolling a phone.
 *
 * The desktop's `follow.check.ts` holds the same cases against a scroll
 * position. If one of these ever has to change, so does that one.
 */
class FollowTest {

    @Test
    fun `at the end of the conversation, however it got there`() {
        assertTrue(nextFollow(following = true, scrolledUp = false, gapPx = 0))
        assertTrue(nextFollow(following = false, scrolledUp = false, gapPx = 0))
        // Coming back to the end re-pins even though the reader scrolled to get
        // there - the direction stops mattering once they have arrived.
        assertTrue(nextFollow(following = false, scrolledUp = true, gapPx = 0))
        // Within the slack still counts: a fling that is a pixel from settling
        // must not read as somebody walking away.
        assertTrue(nextFollow(following = true, scrolledUp = false, gapPx = FOLLOW_SLACK_PX - 1))
    }

    @Test
    fun `the reader scrolling up is what stops the following`() {
        assertFalse(nextFollow(following = true, scrolledUp = true, gapPx = 900))
        // And having stopped, scrolling down without reaching the end does not
        // start it again on its own.
        assertFalse(nextFollow(following = false, scrolledUp = false, gapPx = 900))
    }

    @Test
    fun `a row growing must never stop the following`() {
        // A picture decrypted and its row became three hundred taller: the end
        // of the list is suddenly far below the screen and nobody scrolled.
        // This is the case the old rule got wrong.
        assertTrue(nextFollow(following = true, scrolledUp = false, gapPx = 300))
        // A channel of them, one after another.
        var following = true
        for (gap in listOf(300, 640, 980, 1320)) {
            following = nextFollow(following, scrolledUp = false, gapPx = gap)
        }
        assertTrue(following)
        // A reader who had already walked away is not dragged back by any of it.
        assertFalse(nextFollow(following = false, scrolledUp = false, gapPx = 300))
    }

    @Test
    fun `the newest message being off screen is as far away as it gets`() {
        // Scrolled up into history: the last row laid out is not the last row
        // there is, so there is nothing to measure and no need to.
        assertEquals(Int.MAX_VALUE, bottomGap(40, 1200, totalItems = 80, viewportEnd = 2000))
        // The newest message is on screen and its bottom is above the fold.
        assertEquals(-140, bottomGap(79, 1860, totalItems = 80, viewportEnd = 2000))
        // On screen, and hanging 300 below it - the row that just grew.
        assertEquals(300, bottomGap(79, 2300, totalItems = 80, viewportEnd = 2000))
    }

    @Test
    fun `up is the first visible item, then how far into it`() {
        assertTrue(scrolledUp(previous = 8 to 40, current = 7 to 900))
        assertTrue(scrolledUp(previous = 8 to 400, current = 8 to 40))
        assertFalse(scrolledUp(previous = 8 to 40, current = 9 to 0))
        assertFalse(scrolledUp(previous = 8 to 40, current = 8 to 400))
        // Standing still is not scrolling in either direction.
        assertFalse(scrolledUp(previous = 8 to 40, current = 8 to 40))
    }

    @Test
    fun `growth pushing the end away leaves the list following, and a jump back`() {
        // The whole sequence, as it happens when a channel of photos opens:
        // pinned at the end, four rows decrypt and grow, and the list is still
        // following - so the correction after each one puts it back.
        var following = true
        var position = 12 to 0
        for (gap in listOf(0, 300, 0, 620, 0, 940, 0)) {
            // The list only ever moves down when it is the one moving.
            val next = if (gap == 0) position.first + 1 to 0 else position
            following = nextFollow(following, scrolledUp(position, next), gap)
            position = next
        }
        assertTrue("growth must leave the list following", following)
    }
}

package com.aatech.betweenus.feature.chat

import com.aatech.betweenus.core.data.Message
import com.aatech.betweenus.core.data.MessageWebhook
import com.aatech.betweenus.core.data.UserSummary
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Which rows carry a body, and therefore which rows a bubble may group with.
 *
 * Grouping decides whether a message draws a name and a face of its own, so
 * getting it wrong is not cosmetic: a message wrongly grouped is a message from
 * nobody, and one wrongly split is somebody's name repeated down the screen.
 *
 * The case worth pinning is the one that shipped. An arrival line sits in the
 * same list as the bubbles and carries the arriving person as its author, so
 * "mobile is here." followed by mobile's own "Hi" matched on author id, grouped
 * with the arrival, and drew neither a name nor a picture.
 *
 * The desktop pins the same rule in `ChatView.check.ts`.
 */
class GroupingTest {

    private fun message(
        kind: String = Message.KIND_USER,
        authorId: String = "u1",
        webhook: MessageWebhook? = null,
    ) = Message(
        id = "m1",
        channelId = "c1",
        kind = kind,
        content = "hi",
        author = UserSummary(authorId, "mobile", "mobile", null),
        createdAt = "2026-09-03T18:04:00.000Z",
        editedAt = null,
        deletedAt = null,
        deletedBy = null,
        pinnedAt = null,
        reactions = emptyList(),
        webhook = webhook,
    )

    @Test
    fun `an arrival line carries no body, so nothing groups with it`() {
        // This is the whole bug: `hasBody` is what MessageRow now checks before
        // it will treat the row above as the start of a run.
        assertFalse(message(kind = Message.KIND_MEMBER_JOIN).hasBody)
        assertTrue(message(kind = Message.KIND_MEMBER_JOIN).isArrival)
    }

    @Test
    fun `a person's message carries one`() {
        assertTrue(message().hasBody)
        assertFalse(message().isArrival)
        assertFalse(message().isWebhook)
    }

    @Test
    fun `a webhook message carries one too`() {
        // The regression that made the allowlist necessary. `kind != USER` meant
        // "the server wrote this and it has no text", which was true while
        // MEMBER_JOIN was the only other kind and silently became "a webhook
        // message renders empty" the moment a third existed.
        val hook = message(
            kind = Message.KIND_WEBHOOK,
            webhook = MessageWebhook("w1", "Deploys", null),
        )
        assertTrue(hook.hasBody)
        assertTrue(hook.isWebhook)
        assertFalse(hook.isArrival)
    }

    @Test
    fun `an unknown future kind carries no body`() {
        // An allowlist and not a denylist, so a client that has never heard of a
        // kind draws nothing for it rather than drawing the wrong thing.
        assertFalse(message(kind = "SOMETHING_ADDED_LATER").hasBody)
    }
}

package com.aatech.betweenus.feature.chat

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Naming and typing a picked file.
 *
 * The bug these pin: an audio file picked on a phone reached every other
 * client called `attachment`, with no extension and a type of
 * `application/octet-stream`, so it drew as an anonymous document rather than
 * as something with a play button. Nothing failed, nothing was logged, and
 * every type in the codebase was satisfied - the only symptom was a card with
 * the wrong words on it.
 */
class PickedNamesTest {

    @Test
    fun `every kind of file gets an extension, not only photos and videos`() {
        // The whole of the original defect: this answered for image and video
        // by splitting the type on its slash, and empty for everything else.
        assertEquals(".mp3", extensionForType("audio/mpeg"))
        assertEquals(".m4a", extensionForType("audio/mp4"))
        assertEquals(".ogg", extensionForType("audio/ogg"))
        assertEquals(".wav", extensionForType("audio/x-wav"))
        assertEquals(".pdf", extensionForType("application/pdf"))

        // And the two it did answer for still answer the same.
        assertEquals(".jpg", extensionForType("image/jpeg"))
        assertEquals(".mp4", extensionForType("video/mp4"))
    }

    @Test
    fun `a type the table has never heard of still yields its subtype`() {
        assertEquals(".avif", extensionForType("image/avif"))
        // Parameters and structured suffixes are not part of an extension.
        assertEquals(".jpg", extensionForType("image/jpeg; charset=binary"))
        assertEquals(".svg", extensionForType("image/svg+xml"))
    }

    @Test
    fun `a type that says nothing yields nothing rather than a nonsense extension`() {
        assertEquals("", extensionForType(OPAQUE_TYPE))
        assertEquals("", extensionForType(""))
        assertEquals("", extensionForType("audio/*"))
        assertEquals("", extensionForType("nonsense"))
    }

    @Test
    fun `a name is read back as a type when nothing else will say`() {
        assertEquals("audio/mpeg", typeForName("song.mp3"))
        assertEquals("audio/ogg", typeForName("voice_20260830_011311.ogg"))
        // Case is not part of an extension.
        assertEquals("image/jpeg", typeForName("HOLIDAY.JPG"))

        assertNull("a name with no extension says nothing", typeForName("attachment"))
        assertNull("an extension nobody knows says nothing", typeForName("archive.sevenzip"))
    }

    @Test
    fun `octet-stream is a non-answer, not an answer`() {
        // Treating it as an answer is how a song became a document: the
        // provider said "I do not know" and it was written down as a fact.
        assertFalse(typeIsUseful(OPAQUE_TYPE))
        assertFalse(typeIsUseful("application/octet-stream; charset=binary"))
        assertFalse(typeIsUseful(null))
        assertFalse(typeIsUseful("  "))

        assertTrue(typeIsUseful("audio/mpeg"))
    }

    @Test
    fun `a URI segment is a name only when it looks like one`() {
        // A `file://` URI's last segment IS the filename, and a file URI has no
        // provider to query - which is how this app's own voice recordings
        // lost their names on the way out.
        assertEquals("voice_20260830_011311.ogg", nameFromSegment("voice_20260830_011311.ogg"))
        assertEquals("holiday.jpg", nameFromSegment("/storage/emulated/0/DCIM/holiday.jpg"))

        // What the document browser and the photo picker actually hand back,
        // and none of it is a filename.
        assertNull(nameFromSegment("msf:42"))
        assertNull(nameFromSegment("image:1000012345"))
        assertNull(nameFromSegment("1000012345"))
        assertNull(nameFromSegment(null))
        assertNull(nameFromSegment(""))
    }

    @Test
    fun `the name falls back in the order the sources are worth trusting`() {
        // What the provider calls it always wins.
        assertEquals(
            "Interview take 2.mp3",
            pickedName("Interview take 2.mp3", "msf:42", "audio/mpeg"),
        )
        // Then the URI, when it looks like a name.
        assertEquals("voice_1.ogg", pickedName(null, "voice_1.ogg", "audio/ogg"))
        assertEquals("voice_1.ogg", pickedName("   ", "voice_1.ogg", "audio/ogg"))
        // Then a generated name that at least carries the right extension, so
        // the far end has something it can open.
        assertEquals("attachment.mp3", pickedName(null, "msf:42", "audio/mpeg"))
        // The old behaviour, and the reason the bug was visible: with nothing
        // to go on and no extension for audio, this was bare "attachment".
        assertEquals("attachment", pickedName(null, "msf:42", OPAQUE_TYPE))
    }

    @Test
    fun `the type falls back to the name before it gives up`() {
        assertEquals("audio/mpeg", pickedType("audio/mpeg", "whatever.bin"))
        // The provider knows nothing, so the name is asked - this is the step
        // that was missing, and the one that makes a picked song playable.
        assertEquals("audio/mpeg", pickedType(null, "song.mp3"))
        assertEquals("audio/mpeg", pickedType(OPAQUE_TYPE, "song.mp3"))
        assertEquals("audio/ogg", pickedType("", "voice_20260830_011311.ogg"))
        // Nothing says anything: honest bytes, and a plain document card.
        assertEquals(OPAQUE_TYPE, pickedType(null, "attachment"))
    }

    @Test
    fun `a picked audio file survives the whole chain`() {
        // The reported bug, end to end: a provider that answers neither, which
        // is what a `file://` URI does.
        val name = pickedName(displayName = null, uriSegment = "ringtone.mp3", contentType = OPAQUE_TYPE)
        val type = pickedType(providerType = null, name = name)

        assertEquals("ringtone.mp3", name)
        assertEquals("audio/mpeg", type)
        assertTrue("it has to be recognisable as audio", type.startsWith("audio/"))
    }
}

package com.aatech.betweenus.feature.chat

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * How much a picture is shrunk while it is decoded.
 *
 * The one part of the decode that is arithmetic rather than platform, and the
 * one worth checking: too large a sample size is a blurry picture, too small is
 * a decode that saves nothing - and both look like somebody else's bug rather
 * than a number in this file.
 */
class SampleSizeTest {

    @Test
    fun `a picture already small enough is not shrunk`() {
        assertEquals(1, sampleSizeFor(800, 600, 1080))
        assertEquals(1, sampleSizeFor(1080, 1080, 1080))
    }

    @Test
    fun `a phone photo is halved until it is about the target`() {
        // 4000 -> 2000 -> 1000, and 1000 is under the target, so it stops at 2.
        assertEquals(2, sampleSizeFor(4000, 3000, 1080))
        // 8000 -> 4000 -> 2000 -> 1000.
        assertEquals(4, sampleSizeFor(8000, 6000, 1080))
    }

    @Test
    fun `the longest edge is what decides, whichever way round it is`() {
        assertEquals(sampleSizeFor(4000, 500, 1080), sampleSizeFor(500, 4000, 1080))
    }

    @Test
    fun `the result never leaves it softer than what is drawn`() {
        // The rule: after shrinking, the longest edge is still at or above the
        // target - anything else is a picture drawn larger than it was decoded.
        for (edge in listOf(1081, 2000, 2160, 4000, 6000, 12000)) {
            val sample = sampleSizeFor(edge, edge / 2, 1080)
            assert(edge / sample >= 1080) { "$edge / $sample is under the target" }
        }
    }

    @Test
    fun `a size the decoder could not read is left alone`() {
        // `inJustDecodeBounds` reports -1 for anything it cannot parse, and a
        // sample size derived from that would be a crash or a blank row.
        assertEquals(1, sampleSizeFor(-1, -1, 1080))
        assertEquals(1, sampleSizeFor(0, 0, 1080))
        assertEquals(1, sampleSizeFor(4000, 3000, 0))
    }
}

package com.aatech.betweenus.feature.chat

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The waveform arithmetic, which fails silently in three different ways.
 *
 * A wrong bucket count draws a message at the wrong width. A missing normalise
 * draws a quiet recording as silence. A missing floor draws a pause as a hole,
 * which reads as a damaged file rather than as somebody drawing breath.
 *
 * The counts here also have to agree with `VOICE_WAVEFORM_BARS` in
 * `packages/shared-types` and with the desktop's `toWaveform`, or the same
 * message is a different shape on a phone than on a laptop - and a waveform
 * that differs between devices is one nobody can trust as a position.
 */
class VoiceNoteTest {

    @Test
    fun `every message is the same number of bars`() {
        val short = VoiceNote.toWaveform(listOf(0.1f, 0.9f))
        val long = VoiceNote.toWaveform(List(3000) { (it % 7) / 7f })

        assertEquals(VoiceNote.WAVEFORM_BARS, short.size)
        assertEquals(VoiceNote.WAVEFORM_BARS, long.size)
        // Nothing measured draws nothing, and the player falls back to its
        // placeholder rather than to a row of zero-height bars.
        assertTrue(VoiceNote.toWaveform(emptyList()).isEmpty())
    }

    @Test
    fun `the same shape at any volume is the same waveform`() {
        // Input gain differs by an order of magnitude between phones. A
        // waveform is read as a shape, never as a measurement, so a quiet
        // recording has to look like a recording rather than like silence.
        val quiet = VoiceNote.toWaveform(listOf(0.001f, 0.002f, 0.004f, 0.002f), bars = 4)
        val loud = VoiceNote.toWaveform(listOf(0.25f, 0.5f, 1f, 0.5f), bars = 4)

        assertEquals(quiet.size, loud.size)
        quiet.indices.forEach { at ->
            assertEquals(loud[at], quiet[at], 0.0001f)
        }
        assertEquals(1f, loud.max(), 0.0001f)
    }

    @Test
    fun `a pause is a line and not a hole`() {
        val gap = VoiceNote.toWaveform(listOf(1f, 0f, 0f, 1f), bars = 4)

        assertTrue("silence is still drawn", gap.min() > 0f)
        assertTrue("and is still visibly quieter than speech", gap.min() < 0.2f)
    }

    @Test
    fun `silence throughout is a flat line rather than a divide by zero`() {
        val silent = VoiceNote.toWaveform(listOf(0f, 0f, 0f), bars = 4)

        assertEquals(4, silent.size)
        assertTrue(silent.all { it.isFinite() && it > 0f })
    }

    @Test
    fun `bars stay inside the range the renderer scales against`() {
        val bars = VoiceNote.toWaveform(List(500) { (it % 13) / 13f })

        assertTrue(bars.all { it > 0f && it <= 1f })
    }

    @Test
    fun `the counter agrees with the minimum length under it`() {
        assertEquals("0:00", VoiceNote.formatDuration(0f))
        assertEquals("0:09", VoiceNote.formatDuration(9f))
        assertEquals("1:09", VoiceNote.formatDuration(69f))
        assertEquals("10:00", VoiceNote.formatDuration(600f))
        // Part-seconds round down, so the counter never reads 0:01 for a
        // recording MIN_SECONDS would refuse to send.
        assertEquals("0:00", VoiceNote.formatDuration(0.9f))
        assertEquals("0:00", VoiceNote.formatDuration(-5f))
    }
}

package com.aatech.betweenus.feature.notifications

import com.aatech.betweenus.core.data.NotificationPreferences
import com.aatech.betweenus.core.data.PublicUser
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.LocalTime

/**
 * The two gates a server cannot answer, and the two that are easy to get
 * backwards: a quiet-hours window that wraps midnight, and what counts as a
 * mention of me.
 */
class PushGateTest {

    private fun preferences(start: Int?, end: Int?) = NotificationPreferences(
        enabled = true,
        quietStartMinute = start,
        quietEndMinute = end,
        mutedChannelIds = emptyList(),
        mutedUserIds = emptyList(),
    )

    private val self = PublicUser(
        id = "u1",
        email = "ada@example.com",
        username = "ada",
        displayName = "Ada Lovelace",
        avatarUrl = null,
        role = "USER",
    )

    @Test
    fun `no window means never quiet`() {
        assertFalse(PushGate.quiet(preferences(null, null), LocalTime.of(3, 0)))
        assertFalse(PushGate.quiet(null, LocalTime.of(3, 0)))
        // Half a window is not a window: one end alone says nothing.
        assertFalse(PushGate.quiet(preferences(1320, null), LocalTime.of(23, 0)))
    }

    @Test
    fun `an ordinary window covers its own hours only`() {
        val nine_to_five = preferences(9 * 60, 17 * 60)
        assertTrue(PushGate.quiet(nine_to_five, LocalTime.of(12, 0)))
        assertFalse(PushGate.quiet(nine_to_five, LocalTime.of(8, 59)))
        assertFalse(PushGate.quiet(nine_to_five, LocalTime.of(20, 0)))
        // The start is inside and the end is not, so two windows meeting at an
        // hour do not both claim it.
        assertTrue(PushGate.quiet(nine_to_five, LocalTime.of(9, 0)))
        assertFalse(PushGate.quiet(nine_to_five, LocalTime.of(17, 0)))
    }

    @Test
    fun `a window may wrap midnight`() {
        // 22:00 to 08:00, which is the one people actually set.
        val night = preferences(22 * 60, 8 * 60)
        assertTrue(PushGate.quiet(night, LocalTime.of(23, 30)))
        assertTrue(PushGate.quiet(night, LocalTime.of(0, 1)))
        assertTrue(PushGate.quiet(night, LocalTime.of(7, 59)))
        assertFalse(PushGate.quiet(night, LocalTime.of(8, 0)))
        assertFalse(PushGate.quiet(night, LocalTime.of(13, 0)))
    }

    @Test
    fun `a mention is my name, not a word containing it`() {
        assertTrue(PushGate.mentions("morning @ada, ready?", self))
        assertTrue(PushGate.mentions("@Ada Lovelace can you look", self))
        assertTrue(PushGate.mentions("@everyone standup in five", self))
        assertTrue(PushGate.mentions("@here quick one", self))
        assertFalse(PushGate.mentions("ada said the same thing", self))
        assertFalse(PushGate.mentions("ask @adam about it", self))
    }

    @Test
    fun `suppresses push when the exact channel is open in the foreground`() {
        val server1General = "chan_server1_general"
        val server2General = "chan_server2_general"
        val server1Random = "chan_server1_random"

        // Server 1 general is open in foreground: suppress push for server 1 general
        assertTrue(
            PushGate.shouldSuppress(
                channelId = server1General,
                isForeground = true,
                visibleChannelId = server1General,
            )
        )

        // Server 1 general is open in foreground: DO NOT suppress push for server 2 general
        assertFalse(
            PushGate.shouldSuppress(
                channelId = server2General,
                isForeground = true,
                visibleChannelId = server1General,
            )
        )

        // Server 1 general is open in foreground: DO NOT suppress push for server 1 random
        assertFalse(
            PushGate.shouldSuppress(
                channelId = server1Random,
                isForeground = true,
                visibleChannelId = server1General,
            )
        )

        // App is in background: DO NOT suppress push even if visibleChannelId matches
        assertFalse(
            PushGate.shouldSuppress(
                channelId = server1General,
                isForeground = false,
                visibleChannelId = server1General,
            )
        )

        // No channel is open (e.g., friends tab, drawer): DO NOT suppress
        assertFalse(
            PushGate.shouldSuppress(
                channelId = server1General,
                isForeground = true,
                visibleChannelId = null,
            )
        )
    }
}

package com.aatech.betweenus.feature.settings

import com.aatech.betweenus.core.data.Pictures
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs

/**
 * The centre crop a stored picture is framed to.
 *
 * Worth pinning because the two cases that go wrong are the two nobody has to
 * hand while writing it: a portrait photograph cropped down to a 4:1 band, and
 * a panorama cropped up to a square. Both are arithmetic, so neither needs a
 * decoded bitmap or a device.
 *
 * The desktop pins the same arithmetic in `picture-crop.check.ts`, with the
 * same numbers. Two clients that frame the same photograph differently store
 * two different pictures for one upload.
 */
class PictureCropTest {

    @Test
    fun `a square comes out of the short edge of a landscape photograph`() {
        val box = Pictures.cropBox(1600, 900, 1f)
        assertEquals(900, box.width)
        assertEquals(900, box.height)
        assertEquals(350, box.x)
        assertEquals(0, box.y)
    }

    @Test
    fun `and out of the short edge of a portrait one`() {
        val box = Pictures.cropBox(900, 1600, 1f)
        assertEquals(900, box.width)
        assertEquals(900, box.height)
        assertEquals(0, box.x)
        assertEquals(350, box.y)
    }

    @Test
    fun `an ordinary photograph gives up height to become a cover band`() {
        // 4:3 is far taller than 4:1, so the full width is kept.
        val box = Pictures.cropBox(4000, 3000, Pictures.COVER_ASPECT)
        assertEquals(4000, box.width)
        assertEquals(1000, box.height)
        assertEquals(0, box.x)
        // Taken from the middle, so a horizon stays near the centre.
        assertEquals(1000, box.y)
    }

    @Test
    fun `a panorama gives up width instead`() {
        // 8:1 is flatter than 4:1, so this time width is what runs out.
        val box = Pictures.cropBox(8000, 1000, Pictures.COVER_ASPECT)
        assertEquals(1000, box.height)
        assertEquals(4000, box.width)
        assertEquals(0, box.y)
        assertEquals(2000, box.x)
    }

    @Test
    fun `the crop is always the requested shape and always inside the picture`() {
        // The property that actually matters. A crop that escaped the source
        // draws transparent pixels down one edge, which is the bug this
        // function exists to not have.
        val sizes = listOf(100 to 100, 1920 to 1080, 1080 to 1920, 3000 to 401, 17 to 4001)
        for ((width, height) in sizes) {
            for (aspect in listOf(1f, Pictures.COVER_ASPECT, 16f / 9f)) {
                val box = Pictures.cropBox(width, height, aspect)
                // Within a pixel, not within a ratio. A crop is measured in
                // whole pixels, so on a 17-pixel-wide source the truncation is
                // a quarter of a pixel and 6% of the aspect - checking the
                // ratio to a fixed tolerance fails on exactly the small
                // pictures where being off by one pixel does not matter.
                assertTrue(
                    "$width x $height at $aspect keeps its shape",
                    abs(box.width / aspect - box.height) <= 1f,
                )
                assertTrue("starts inside", box.x >= 0 && box.y >= 0)
                assertTrue(
                    "ends inside",
                    box.x + box.width <= width && box.y + box.height <= height,
                )
            }
        }
    }
}

package com.aatech.betweenus.feature.shell

import com.aatech.betweenus.core.data.Channel
import com.aatech.betweenus.core.data.ChannelType
import com.aatech.betweenus.core.data.DirectChannel
import com.aatech.betweenus.core.data.ServerRole
import com.aatech.betweenus.core.data.ServerWithRole
import com.aatech.betweenus.core.data.UserSummary
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * What the switcher offers, and in what order.
 *
 * The order is the interesting part and the part that fails quietly: a switcher
 * that lists servers first still works, still filters, and is still wrong -
 * the coarsest destination sits above the specific ones somebody was typing a
 * name to reach.
 */
class QuickSwitcherTest {

    private fun server(id: String, name: String) = ServerWithRole(
        id = id,
        name = name,
        slug = id,
        iconUrl = null,
        ownerId = "me",
        messageTtlSeconds = null,
        role = ServerRole.MEMBER,
        permissions = emptyList(),
    )

    private fun channel(id: String, serverId: String, name: String, type: ChannelType) = Channel(
        id = id,
        serverId = serverId,
        name = name,
        type = type,
        topic = null,
        isPrivate = false,
    )

    private fun direct(id: String, name: String) = DirectChannel(
        channelId = id,
        participant = UserSummary(name, name, name, null),
    )

    private val servers = listOf(server("s1", "Workshop"), server("s2", "Garden"))

    private val channels = mapOf(
        "s1" to listOf(
            channel("c1", "s1", "general", ChannelType.TEXT),
            channel("c2", "s1", "Lounge", ChannelType.VOICE),
        ),
        "s2" to listOf(channel("c3", "s2", "general", ChannelType.TEXT)),
    )

    private val directs = listOf(direct("d1", "Ana"))

    @Test
    fun `conversations first, then channels, then servers`() {
        assertEquals(
            listOf("d1", "c1", "c2", "c3", "s1", "s2"),
            switchTargets(servers, channels, directs, "").map { it.id },
        )
    }

    @Test
    fun `every server's channels are offered, not only one server's`() {
        // The one place this deliberately differs from the desktop, and the
        // reason it can: the phone has already loaded them all.
        val ids = switchTargets(servers, channels, directs, "general").map { it.id }
        assertEquals(listOf("c1", "c3"), ids)
    }

    @Test
    fun `two channels with the same name are told apart by their server`() {
        val hints = switchTargets(servers, channels, directs, "general").map { it.hint }
        assertEquals(listOf("Workshop", "Garden"), hints)
    }

    @Test
    fun `a voice channel says so, and carries its own kind`() {
        val lounge = switchTargets(servers, channels, directs, "lounge").single()
        assertEquals(SwitchKind.VOICE_CHANNEL, lounge.kind)
        assertEquals("Voice · Workshop", lounge.hint)
    }

    @Test
    fun `matching is case-insensitive and on any part of the name`() {
        assertEquals(listOf("s1"), switchTargets(servers, channels, directs, "WORKSH").map { it.id })
        assertEquals(listOf("d1"), switchTargets(servers, channels, directs, "an").map { it.id })
    }

    @Test
    fun `a blank term lists everywhere rather than nowhere`() {
        // The sheet opens onto the whole map: with nothing typed there is no
        // reason to show an empty list of places somebody could go.
        assertEquals(6, switchTargets(servers, channels, directs, "   ").size)
    }

    @Test
    fun `a channel carries the server the shell has to select with it`() {
        val target = switchTargets(servers, channels, directs, "lounge").single()
        assertEquals("s1", target.serverId)
        // A conversation belongs to no server, and saying otherwise would put
        // the rail on a server the person is not in.
        assertTrue(switchTargets(servers, channels, directs, "ana").single().serverId == null)
    }

    @Test
    fun `keys are unique across kinds`() {
        val keys = switchTargets(servers, channels, directs, "").map { it.key }
        assertEquals(keys.size, keys.toSet().size)
    }
}

package com.aatech.betweenus.feature.status

import org.junit.Assert.assertEquals
import org.junit.Test
import java.time.Duration
import java.time.Instant

/** The boundaries of [statusAge], and the clock that runs fast. */
class StatusAgeTest {

    private val now: Instant = Instant.parse("2026-09-03T12:00:00Z")

    private fun ago(duration: Duration): String = now.minus(duration).toString()

    @Test
    fun `the first minute is just now`() {
        assertEquals("just now", statusAge(ago(Duration.ZERO), now))
        assertEquals("just now", statusAge(ago(Duration.ofSeconds(59)), now))
    }

    @Test
    fun `minutes, then hours`() {
        assertEquals("1m ago", statusAge(ago(Duration.ofMinutes(1)), now))
        assertEquals("59m ago", statusAge(ago(Duration.ofMinutes(59)), now))
        assertEquals("1h ago", statusAge(ago(Duration.ofHours(1)), now))
        assertEquals("23h ago", statusAge(ago(Duration.ofHours(23)), now))
    }

    @Test
    fun `a phone clock behind the server reads as just now, never as negative`() {
        assertEquals("just now", statusAge(now.plusSeconds(5).toString(), now))
    }

    @Test
    fun `something that is not a timestamp draws nothing`() {
        assertEquals("", statusAge("not a date", now))
    }
}

package com.aatech.betweenus.feature.update

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The three things that decide what gets installed: what a version string
 * means, which releases a channel is allowed to see, and which APK belongs to
 * this device. Getting any of them wrong installs the wrong build, silently.
 */
class ReleasesTest {

    private fun release(tag: String, vararg assets: String) = Release(
        version = requireNotNull(Version.parse(tag)) { "unparseable tag $tag" },
        name = tag,
        notes = "",
        publishedAt = "",
        assets = assets.map { ReleaseAsset(it, "https://example.invalid/$it", 1) },
    )

    @Test
    fun `a stable release beats every pre-release of the same version`() {
        val alpha = requireNotNull(Version.parse("0.0.2-alpha.9"))
        val beta = requireNotNull(Version.parse("0.0.2-beta.1"))
        val stable = requireNotNull(Version.parse("v0.0.2"))

        assertTrue(alpha < beta)
        assertTrue(beta < stable)
        assertTrue(stable < requireNotNull(Version.parse("0.0.3-alpha.1")))
    }

    @Test
    fun `pre-release numbers are compared as numbers`() {
        val second = requireNotNull(Version.parse("0.0.1-alpha.2"))
        val tenth = requireNotNull(Version.parse("0.0.1-alpha.10"))
        assertTrue(second < tenth)
    }

    @Test
    fun `nonsense parses to null rather than to something`() {
        assertNull(Version.parse("nightly"))
        assertNull(Version.parse("1.2"))
        assertNull(Version.parse("1.2.3-rc.1"))
        assertNull(Version.parse(null))
    }

    @Test
    fun `a channel takes its own builds and everything steadier`() {
        val alpha = requireNotNull(Version.parse("1.0.0-alpha.1"))
        val beta = requireNotNull(Version.parse("1.0.0-beta.1"))
        val stable = requireNotNull(Version.parse("1.0.0"))

        assertTrue(UpdateChannel.ALPHA.accepts(alpha))
        assertTrue(UpdateChannel.ALPHA.accepts(stable))
        assertTrue(!UpdateChannel.BETA.accepts(alpha))
        assertTrue(UpdateChannel.BETA.accepts(beta))
        assertTrue(!UpdateChannel.STABLE.accepts(beta))
        assertTrue(UpdateChannel.STABLE.accepts(stable))
    }

    @Test
    fun `the newest release on the channel wins, and only if it is newer`() {
        val releases = listOf(
            release("v0.0.2-alpha.1"),
            release("v0.0.2-beta.2"),
            release("v0.0.1"),
        )
        val installed = Version.parse("0.0.1")

        assertEquals("v0.0.2-beta.2", Releases.pick(releases, installed, UpdateChannel.ALPHA)?.name)
        assertEquals("v0.0.2-beta.2", Releases.pick(releases, installed, UpdateChannel.BETA)?.name)
        assertNull(Releases.pick(releases, installed, UpdateChannel.STABLE))
    }

    @Test
    fun `a stable release cut after an alpha is not an upgrade for that alpha`() {
        val releases = listOf(release("v0.0.1"), release("v0.0.2-alpha.1"))
        val installed = Version.parse("0.0.2-alpha.1")
        assertNull(Releases.pick(releases, installed, UpdateChannel.STABLE))
    }

    @Test
    fun `the device's own ABI is preferred, in the device's own order`() {
        val build = release(
            "v1.0.0",
            "BetweenUs-1.0.0-armeabi-v7a.apk",
            "BetweenUs-1.0.0-arm64-v8a.apk",
            "BetweenUs-1.0.0-universal.apk",
            "BetweenUs-1.0.0.aab",
        )
        assertEquals(
            "BetweenUs-1.0.0-arm64-v8a.apk",
            Releases.apkFor(build, listOf("arm64-v8a", "armeabi-v7a"))?.name,
        )
    }

    @Test
    fun `x86 does not match the x86_64 build`() {
        val build = release("v1.0.0", "BetweenUs-1.0.0-x86_64.apk", "BetweenUs-1.0.0-universal.apk")
        assertEquals("BetweenUs-1.0.0-universal.apk", Releases.apkFor(build, listOf("x86"))?.name)
    }

    @Test
    fun `universal is the fallback, never the choice`() {
        val build = release("v1.0.0", "BetweenUs-1.0.0-universal.apk")
        assertEquals("BetweenUs-1.0.0-universal.apk", Releases.apkFor(build, listOf("arm64-v8a"))?.name)
        assertNull(Releases.apkFor(release("v1.0.0", "BetweenUs-1.0.0.aab"), listOf("arm64-v8a")))
    }

    @Test
    fun `the default channel is the one the installed build came from`() {
        assertEquals(UpdateChannel.ALPHA, UpdateChannel.forVersion("0.0.1-alpha.5"))
        assertEquals(UpdateChannel.BETA, UpdateChannel.forVersion("0.0.1-beta.1"))
        assertEquals(UpdateChannel.STABLE, UpdateChannel.forVersion("1.2.3"))
        assertEquals(UpdateChannel.STABLE, UpdateChannel.forVersion("0.0.0"))
    }
}

package com.aatech.betweenus.feature.voice

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The two decisions in [AudioPrefs] that nobody can check by looking at a phone.
 *
 * Both are pure functions taking what would otherwise be read out of
 * `SharedPreferences` and off an `AudioManager`, which is the only reason they
 * are testable at all: the object itself needs a `Context`, and a silent
 * failure in either of these looks exactly like the app working.
 *
 * The migration is the more dangerous of the two. A person who turned noise
 * suppression off did it because their microphone sounded wrong with it on;
 * quietly turning it back on during an update is the same bug as never having
 * had the setting.
 */
class AudioPrefsTest {

    @Test
    fun `the old switch carries over to the level that means the same thing`() {
        assertEquals(
            AudioPrefs.NoiseSuppression.STANDARD,
            AudioPrefs.suppressionOf(level = null, legacy = true),
        )
        assertEquals(
            AudioPrefs.NoiseSuppression.OFF,
            AudioPrefs.suppressionOf(level = null, legacy = false),
        )
    }

    @Test
    fun `a phone that has never had either key gets the default`() {
        assertEquals(
            AudioPrefs.NoiseSuppression.STANDARD,
            AudioPrefs.suppressionOf(level = null, legacy = null),
        )
    }

    @Test
    fun `a chosen level outranks whatever the old switch still says`() {
        // The old key is read and never written, so it keeps saying "on" long
        // after somebody has turned suppression off in the new control.
        assertEquals(
            AudioPrefs.NoiseSuppression.OFF,
            AudioPrefs.suppressionOf(level = "OFF", legacy = true),
        )
        assertEquals(
            AudioPrefs.NoiseSuppression.HIGH,
            AudioPrefs.suppressionOf(level = "HIGH", legacy = false),
        )
    }

    @Test
    fun `a level this build cannot read falls back to the migration, not the default`() {
        // A newer build writing a level this one does not know must not turn
        // suppression back on for somebody who had turned it off.
        assertEquals(
            AudioPrefs.NoiseSuppression.OFF,
            AudioPrefs.suppressionOf(level = "AGGRESSIVE", legacy = false),
        )
    }

    @Test
    fun `the earpiece is left to the phone's own cancellers`() {
        val setup = AudioPrefs.hardwareProcessingFor(
            mode = AudioPrefs.Mode.CLEAR,
            echo = true,
            suppression = AudioPrefs.NoiseSuppression.STANDARD,
            loudspeaker = false,
        )
        assertTrue(setup.echoCanceller)
        assertTrue(setup.noiseSuppressor)
    }

    @Test
    fun `the loudspeaker is where WebRTC cancels the echo itself`() {
        // The actual fix. The OEM canceller is tuned for an earpiece and the
        // loudspeaker is what people complain about.
        val setup = AudioPrefs.hardwareProcessingFor(
            mode = AudioPrefs.Mode.CLEAR,
            echo = true,
            suppression = AudioPrefs.NoiseSuppression.STANDARD,
            loudspeaker = true,
        )
        assertFalse(setup.echoCanceller)
    }

    @Test
    fun `high suppression refuses the hardware path on both counts`() {
        val setup = AudioPrefs.hardwareProcessingFor(
            mode = AudioPrefs.Mode.CLEAR,
            echo = true,
            suppression = AudioPrefs.NoiseSuppression.HIGH,
            loudspeaker = false,
        )
        assertFalse(setup.echoCanceller)
        assertFalse(setup.noiseSuppressor)
    }

    @Test
    fun `switching echo cancellation off asks nobody to cancel it`() {
        val setup = AudioPrefs.hardwareProcessingFor(
            mode = AudioPrefs.Mode.CLEAR,
            echo = false,
            suppression = AudioPrefs.NoiseSuppression.STANDARD,
            loudspeaker = false,
        )
        assertFalse(setup.echoCanceller)
    }

    @Test
    fun `suppression off leaves the hardware suppressor alone too`() {
        val setup = AudioPrefs.hardwareProcessingFor(
            mode = AudioPrefs.Mode.CLEAR,
            echo = true,
            suppression = AudioPrefs.NoiseSuppression.OFF,
            loudspeaker = false,
        )
        assertFalse(setup.noiseSuppressor)
    }

    @Test
    fun `high fidelity mode turns every canceller off, as it does the constraints`() {
        val setup = AudioPrefs.hardwareProcessingFor(
            mode = AudioPrefs.Mode.HIFI,
            echo = true,
            suppression = AudioPrefs.NoiseSuppression.STANDARD,
            loudspeaker = false,
        )
        assertFalse(setup.echoCanceller)
        assertFalse(setup.noiseSuppressor)
    }
}

