package com.aatech.betweenus.feature.voice

import java.nio.ByteBuffer
import java.nio.ByteOrder
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The noise gate on the phone.
 *
 * Three things here are wrong in ways nobody hears until it ships, and all
 * three are arithmetic:
 *
 * - **A gate that latches.** Once shut it must still be able to open, which is
 *   the whole reason the level is measured before the attenuation rather than
 *   after it. A gate that reads its own silence never opens again, and the
 *   symptom is a microphone that works for one sentence.
 * - **A ramp that does not arrive.** Too fast is a click, too slow is a
 *   microphone that fades out mid-word, and never reaching the target at all is
 *   a call that gets quieter the longer it goes on.
 * - **A sample read with the wrong sign.** A loud negative sample read as
 *   unsigned is a quiet one, so a gate would sit closed through half of every
 *   waveform.
 */
class MicGateTest {

    /** 16-bit little-endian PCM, the format the capture hook hands over. */
    private fun pcm(vararg samples: Int): ByteBuffer {
        val buffer = ByteBuffer.allocate(samples.size * 2).order(ByteOrder.LITTLE_ENDIAN)
        samples.forEach { buffer.putShort(it.toShort()) }
        buffer.rewind()
        return buffer
    }

    private fun samplesOf(buffer: ByteBuffer, count: Int): List<Int> =
        (0 until count).map { buffer.order(ByteOrder.LITTLE_ENDIAN).getShort(it * 2).toInt() }

    // --- Measuring -----------------------------------------------------------

    @Test
    fun `silence is the floor and an empty buffer is not a crash`() {
        assertEquals(-100.0, MicGate.amplitudeToDb(0.0), 1e-9)
        assertEquals(0.0, MicGate.rootMeanSquare(pcm(0, 0, 0, 0), 8), 1e-9)
        assertEquals(0.0, MicGate.rootMeanSquare(ByteBuffer.allocate(0), 0), 1e-9)
        // A byte count larger than the buffer must read what is there, not off
        // the end of it.
        assertEquals(0.0, MicGate.rootMeanSquare(pcm(0, 0), 4096), 1e-9)
    }

    @Test
    fun `a loud negative sample is as loud as a positive one`() {
        val up = MicGate.rootMeanSquare(pcm(32767, 32767), 4)
        val down = MicGate.rootMeanSquare(pcm(-32767, -32767), 4)
        assertEquals(1.0, up, 1e-4)
        assertEquals(up, down, 1e-6)
    }

    @Test
    fun `full scale is zero dBFS and half amplitude is about six down`() {
        assertEquals(0.0, MicGate.amplitudeToDb(1.0), 1e-6)
        assertEquals(-6.02, MicGate.amplitudeToDb(0.5), 0.01)
    }

    // --- Deciding ------------------------------------------------------------

    @Test
    fun `a voice opens it and a quiet room does not`() {
        val quiet = MicGate.step(MicGate.CLOSED, -70.0, -50.0, 1_000)
        assertFalse(quiet.open)

        val speech = MicGate.step(MicGate.CLOSED, -30.0, -50.0, 1_000)
        assertTrue(speech.open)
    }

    @Test
    fun `it holds through the gaps inside a word`() {
        val open = MicGate.step(MicGate.CLOSED, -30.0, -50.0, 1_000)
        // A stop consonant: silence, well below the threshold, 100 ms later.
        val gap = MicGate.step(open, -90.0, -50.0, 1_100)
        assertTrue("a gate that shuts inside a word chops every sentence", gap.open)
        // Half a second of nothing is the end of the sentence.
        val after = MicGate.step(gap, -90.0, -50.0, 1_500)
        assertFalse(after.open)
    }

    @Test
    fun `hysteresis stops it fluttering on a voice sitting at the threshold`() {
        val open = MicGate.step(MicGate.CLOSED, -49.0, -50.0, 1_000)
        assertTrue(open.open)
        // Past the hold, 3 dB under the threshold: still open, because it is
        // already open. Without this it would chatter once per buffer.
        val under = MicGate.step(open, -53.0, -50.0, 2_000)
        assertTrue(under.open)
        // 10 dB under is past the hysteresis and is genuinely nothing.
        val well = MicGate.step(under, -60.0, -50.0, 2_100)
        assertFalse(well.open)
    }

    @Test
    fun `a closed gate can still open, because the level is read before the gain`() {
        // The failure this guards is the whole reason the gate is not built on
        // the microphone mute: attenuating first would feed the next decision
        // its own silence and the gate would never reopen.
        var state = MicGate.step(MicGate.CLOSED, -90.0, -50.0, 1_000)
        assertFalse(state.open)
        state = MicGate.step(state, -20.0, -50.0, 1_010)
        assertTrue("a gate that cannot reopen is a microphone that works once", state.open)
    }

    // --- Ramping -------------------------------------------------------------

    @Test
    fun `the ramp arrives, and takes about as long as it says`() {
        // 480 samples at 48 kHz is 10 ms, which is two attack windows.
        assertEquals(1.0, MicGate.rampTo(0.0, open = true, samples = 480, sampleRate = 48_000), 1e-9)
        // One 10 ms buffer is a fifteenth of the 150 ms release, so closing
        // takes several buffers rather than snapping.
        val afterOne = MicGate.rampTo(1.0, open = false, samples = 480, sampleRate = 48_000)
        assertTrue("a release that finishes in one buffer is a click", afterOne > 0.8)
        assertTrue(afterOne < 1.0)
    }

    @Test
    fun `the ramp never overshoots in either direction`() {
        assertEquals(1.0, MicGate.rampTo(0.99, open = true, samples = 480, sampleRate = 48_000), 1e-9)
        assertEquals(0.0, MicGate.rampTo(0.001, open = false, samples = 48_000, sampleRate = 48_000), 1e-9)
    }

    @Test
    fun `a nonsense buffer size leaves the gain alone rather than dividing by zero`() {
        assertEquals(0.5, MicGate.rampTo(0.5, open = true, samples = 0, sampleRate = 48_000), 1e-9)
        assertEquals(0.5, MicGate.rampTo(0.5, open = true, samples = 480, sampleRate = 0), 1e-9)
    }

    // --- Applying ------------------------------------------------------------

    @Test
    fun `a fully closed gate writes silence`() {
        val buffer = pcm(20000, -20000, 15000, -15000)
        MicGate.applyRamp(buffer, 8, fromGain = 0.0, toGain = 0.0)
        assertEquals(listOf(0, 0, 0, 0), samplesOf(buffer, 4))
    }

    @Test
    fun `a fully open gate leaves the samples exactly as they were`() {
        val original = listOf(20000, -20000, 15000, -15000)
        val buffer = pcm(*original.toIntArray())
        val ended = MicGate.applyRamp(buffer, 8, fromGain = 1.0, toGain = 1.0)
        assertEquals(1.0, ended, 1e-9)
        assertEquals(original, samplesOf(buffer, 4))
    }

    @Test
    fun `a ramp is applied across the buffer, not in one step at its edge`() {
        // Every sample the same, so any difference in the output is the ramp.
        val buffer = pcm(10000, 10000, 10000, 10000, 10000, 10000, 10000, 10000)
        MicGate.applyRamp(buffer, 16, fromGain = 1.0, toGain = 0.0)
        val out = samplesOf(buffer, 8)

        assertEquals("the first sample is untouched", 10000, out.first())
        assertTrue("the last is nearly silent, was ${out.last()}", out.last() < 2000)
        // Monotonic: a staircase or a jump would be audible as zipper noise.
        for (index in 1 until out.size) {
            assertTrue("sample $index went up during a close", out[index] <= out[index - 1])
        }
    }

    @Test
    fun `a full-scale sample survives unity gain without wrapping`() {
        // Multiplying by exactly one goes through a Double and back; getting
        // the rounding wrong here turns the loudest sample into the quietest,
        // which is a crack on every peak.
        val buffer = pcm(32767, -32768)
        MicGate.applyRamp(buffer, 4, fromGain = 0.999, toGain = 1.0)
        val out = samplesOf(buffer, 2)
        assertTrue("positive peak wrapped: ${out[0]}", out[0] > 32000)
        assertTrue("negative peak wrapped: ${out[1]}", out[1] < -32000)
    }

    @Test
    fun `an empty buffer is not a crash and reports the target gain`() {
        assertEquals(0.5, MicGate.applyRamp(ByteBuffer.allocate(0), 0, 1.0, 0.5), 1e-9)
    }
}

package com.aatech.betweenus.feature.voice

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The microphone level behind the green ring around your own tile.
 *
 * It is a hand-rolled pass over a byte array with an endianness and a sign in
 * it, which is the shape of thing that is silently wrong: a level that never
 * reaches the threshold is a ring that never lights, and one that never leaves
 * it is a ring that never goes out. Neither looks like a bug, they both look
 * like the feature not working.
 */
class MicrophoneLevelTest {

    /** 16-bit little-endian PCM, the format the device module hands over. */
    private fun pcm(vararg samples: Int): ByteArray {
        val bytes = ByteArray(samples.size * 2)
        samples.forEachIndexed { index, sample ->
            bytes[index * 2] = (sample and 0xFF).toByte()
            bytes[index * 2 + 1] = ((sample shr 8) and 0xFF).toByte()
        }
        return bytes
    }

    @Test
    fun `silence is zero, and an empty buffer is not a crash`() {
        assertEquals(0.0, VoiceEngine.rootMeanSquare(pcm(0, 0, 0, 0)), 1e-9)
        assertEquals(0.0, VoiceEngine.rootMeanSquare(ByteArray(0)), 1e-9)
        // An odd byte count cannot happen and must not read off the end.
        assertEquals(0.0, VoiceEngine.rootMeanSquare(ByteArray(1)), 1e-9)
    }

    @Test
    fun `full scale is one, in both directions`() {
        assertEquals(1.0, VoiceEngine.rootMeanSquare(pcm(32767, 32767)), 1e-4)
        // Negative samples must square to the same thing. Reading the high byte
        // as unsigned would make a loud negative sample read as a quiet one.
        assertEquals(1.0, VoiceEngine.rootMeanSquare(pcm(-32767, -32767)), 1e-4)
        assertEquals(1.0, VoiceEngine.rootMeanSquare(pcm(32767, -32767)), 1e-4)
    }

    @Test
    fun `a voice crosses the threshold and a quiet room does not`() {
        // -40 dBFS is the bar every remote tile is judged by; a normal speaking
        // level sits well above it.
        val speech = VoiceEngine.rootMeanSquare(pcm(3000, -3200, 2800, -2900))
        val room = VoiceEngine.rootMeanSquare(pcm(30, -25, 18, -22))
        assertTrue("speech should register, was $speech", speech >= 0.01)
        assertTrue("a quiet room should not, was $room", room < 0.01)
    }

    @Test
    fun `the level is a mean, not a peak`() {
        // One loud sample in a buffer of silence is a click, not a voice.
        val click = VoiceEngine.rootMeanSquare(pcm(32767) + ByteArray(998))
        assertTrue("a single spike should stay low, was $click", click < 0.1)
    }
}

package com.aatech.betweenus.feature.voice

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Where the self-view lands when it is let go.
 *
 * The tile is dragged in stage pixels and settles into a corner, and the two
 * things that make that wrong are both arithmetic: a corner worked out from
 * the tile's top-left rather than its centre snaps the wrong way for every
 * drag that ends past the middle by less than half a tile, and insets bigger
 * than the stage produce a range that runs backwards.
 */
class PipCornerTest {

    private val stage = Size(1080f, 2400f)
    private val tile = Size(300f, 420f)
    private val side = 40f
    private val top = 200f
    private val bottom = 300f

    private val bounds = pipBounds(stage, tile, side, top, bottom)

    private fun corner(x: Float, y: Float) = pipNearestCorner(bounds, stage, tile, Offset(x, y))

    @Test
    fun `the bounds are the four resting places`() {
        assertEquals(40f, bounds.left, 0.01f)
        assertEquals(200f, bounds.top, 0.01f)
        // 1080 - 300 - 40, and 2400 - 420 - 300.
        assertEquals(740f, bounds.right, 0.01f)
        assertEquals(1680f, bounds.bottom, 0.01f)
    }

    @Test
    fun `each quadrant settles into its own corner`() {
        assertEquals(Offset(40f, 200f), corner(100f, 300f))
        assertEquals(Offset(740f, 200f), corner(700f, 300f))
        assertEquals(Offset(40f, 1680f), corner(100f, 2000f))
        assertEquals(Offset(740f, 1680f), corner(700f, 2000f))
    }

    @Test
    fun `it is the tile's centre that picks the corner, not its top-left`() {
        // Top-left at 400 is left of the 540 midline, but the tile spans
        // 400..700 and its centre is at 550 - so it belongs on the right.
        assertEquals(bounds.right, corner(400f, 1000f).x, 0.01f)
        // And one pixel further left it does not.
        assertEquals(bounds.left, corner(389f, 1000f).x, 0.01f)
    }

    @Test
    fun `a stage with no room left collapses rather than inverting`() {
        val cramped = pipBounds(Size(200f, 400f), tile, side, top, bottom)
        assertEquals(side, cramped.left, 0.01f)
        assertEquals(side, cramped.right, 0.01f)
        assertEquals(top, cramped.top, 0.01f)
        assertEquals(top, cramped.bottom, 0.01f)
        // Which is still a position the tile can be clamped to, not a range
        // that throws when it is used as one.
        assertEquals(
            side,
            500f.coerceIn(cramped.left, cramped.right),
            0.01f,
        )
    }
}

package com.aatech.betweenus.feature.voice

import com.aatech.betweenus.core.store.GameSeat
import com.aatech.betweenus.core.store.GameSession
import com.aatech.betweenus.core.store.GameState
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * The one line under a game's name.
 *
 * Small, and worth pinning because the failure is silent and confusing rather
 * than loud: a board that still says "Your move" after somebody has won is the
 * most misleading thing this screen can say, and nothing about it throws.
 */
class PlayStatusTest {

    private val names = listOf("X", "O")

    private fun session(
        turn: Int = 0,
        winner: Int? = null,
        seats: List<GameSeat?> = listOf(GameSeat("ana", "Ana"), GameSeat("bo", "Bo")),
    ) = GameSession(
        rev = 1,
        gameId = "tic-tac-toe",
        seats = seats,
        state = GameState(
            gameId = "tic-tac-toe",
            cells = List(9) { -1 },
            boxes = emptyList(),
            data = emptyList(),
            turn = turn,
            winner = winner,
            lastMove = null,
            moveCount = 0,
        ),
        round = 0,
        wins = listOf(0, 0),
        byUserId = "ana",
    )

    @Test
    fun `whose move it is, from the seat's own point of view`() {
        assertEquals("Your move.", statusLine(session(turn = 0), names, mySeat = 0))
        assertEquals("Their move.", statusLine(session(turn = 1), names, mySeat = 0))
    }

    @Test
    fun `a finished game never reports a turn`() {
        // The case this test exists for.
        assertEquals("You won.", statusLine(session(turn = 0, winner = 0), names, mySeat = 0))
        assertEquals("Bo won.", statusLine(session(turn = 0, winner = 1), names, mySeat = 0))
        assertEquals("A draw.", statusLine(session(turn = 0, winner = -1), names, mySeat = 0))
    }

    @Test
    fun `a watcher is told who is up, not that it is their move`() {
        assertEquals("Watching · Ana to move", statusLine(session(turn = 0), names, mySeat = -1))
        assertEquals("Watching · Bo to move", statusLine(session(turn = 1), names, mySeat = -1))
    }

    @Test
    fun `an empty chair falls back to the seat's name`() {
        val open = session(turn = 1, seats = listOf(GameSeat("ana", "Ana"), null))
        assertEquals("Watching · O to move", statusLine(open, names, mySeat = -1))
    }

    @Test
    fun `a watcher of a finished game is told who won by name`() {
        val done = session(winner = 1)
        assertEquals("Bo won.", statusLine(done, names, mySeat = -1))
    }
}

package com.aatech.betweenus.feature.voice

import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The same cases as `apps/desktop/src/services/push-to-talk.check.ts`, plus the
 * one the desktop does not have: an interruption, which on a phone is a real
 * telephone call arriving.
 *
 * Every case here fails silently in the direction that matters. A policy that
 * wrongly *passes* audio is a microphone somebody believes is closed, and
 * nothing on screen distinguishes it from one that is.
 */
class PushToTalkTest {

    @Test
    fun `with the mode off the microphone is simply open`() {
        // What a call did before any of this existed, and what it must still do
        // for everybody who never turns this on.
        assertTrue(PushToTalk.shouldPassAudio(muted = false, held = false, pushToTalk = false, talking = false))
        assertTrue(PushToTalk.shouldPassAudio(muted = false, held = false, pushToTalk = false, talking = true))
    }

    @Test
    fun `with the mode on nothing passes until the control is down`() {
        assertFalse(PushToTalk.shouldPassAudio(muted = false, held = false, pushToTalk = true, talking = false))
        assertTrue(PushToTalk.shouldPassAudio(muted = false, held = false, pushToTalk = true, talking = true))
    }

    @Test
    fun `mute outranks a held control`() {
        // Somebody who muted themselves and then leans on the talk button meant
        // the mute. The opposite reading makes the mute button a suggestion.
        assertFalse(PushToTalk.shouldPassAudio(muted = true, held = false, pushToTalk = true, talking = true))
        assertFalse(PushToTalk.shouldPassAudio(muted = true, held = false, pushToTalk = false, talking = true))
    }

    @Test
    fun `an interruption outranks everything`() {
        // The system took the audio. Nothing this app decides changes that, and
        // pretending otherwise sends silence while drawing a live microphone.
        assertFalse(PushToTalk.shouldPassAudio(muted = false, held = true, pushToTalk = true, talking = true))
        assertFalse(PushToTalk.shouldPassAudio(muted = false, held = true, pushToTalk = false, talking = false))
    }

    @Test
    fun `the far end is told what the capture is doing, not what the button says`() {
        // Push to talk, control up, button not muted: no audio is arriving, so
        // a tile that reads "live" is a tile somebody waits on.
        assertTrue(
            PushToTalk.publishedAsMuted(muted = false, held = false, pushToTalk = true, talking = false),
        )
        assertFalse(
            PushToTalk.publishedAsMuted(muted = false, held = false, pushToTalk = true, talking = true),
        )
        // And with the mode off it is exactly the button, as it always was.
        assertFalse(
            PushToTalk.publishedAsMuted(muted = false, held = false, pushToTalk = false, talking = false),
        )
    }
}

package com.aatech.betweenus.feature.voice

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * What the phone says it will accept, which is what decides what it is sent.
 *
 * These are the lines that made a 1080p60 share from the web arrive as 720p30:
 * an H.264 level of 3.1 is a hard ceiling of exactly that, and the sender obeys
 * it. Worth asserting rather than reading, because an SDP is a wall of text
 * where one wrong byte is invisible.
 */
class SdpQualityTest {

    private val offer = listOf(
        "v=0",
        "o=- 1 2 IN IP4 127.0.0.1",
        "s=-",
        "t=0 0",
        "m=audio 9 UDP/TLS/RTP/SAVPF 111",
        "c=IN IP4 0.0.0.0",
        "a=rtpmap:111 opus/48000/2",
        "m=video 9 UDP/TLS/RTP/SAVPF 96 98",
        "c=IN IP4 0.0.0.0",
        "a=rtpmap:96 H264/90000",
        "a=fmtp:96 level-asymmetry-allowed=1;packetization-mode=1;profile-level-id=42001f",
        "a=rtpmap:98 VP8/90000",
    ).joinToString("\r\n") + "\r\n"

    @Test
    fun `the H264 level is raised off its 720p30 ceiling`() {
        val patched = SdpQuality.patch(offer, 20_000_000)

        assertTrue("level not raised: $patched", patched.contains("profile-level-id=420034"))
        assertFalse(patched.contains("profile-level-id=42001f"))
    }

    @Test
    fun `the profile and its constraint flags are left alone`() {
        // 4d = Main, 0x40 constraint flags. Claiming a profile the decoder
        // cannot parse is a stream it cannot decode at all - only the level is
        // being under-claimed, so only the level moves.
        val patched = SdpQuality.raiseH264Level("profile-level-id=4d401f")
        assertEquals("profile-level-id=4d4034", patched)
    }

    @Test
    fun `a level already high enough is not lowered`() {
        assertEquals("profile-level-id=64003c", SdpQuality.raiseH264Level("profile-level-id=64003c"))
    }

    @Test
    fun `bandwidth is stated on the video section and only there`() {
        val patched = SdpQuality.patch(offer, 20_000_000)
        val sections = patched.split(Regex("(?=m=)"))

        val audio = sections.first { it.startsWith("m=audio") }
        val video = sections.first { it.startsWith("m=video") }

        assertTrue(video.contains("b=AS:20000"))
        assertTrue(video.contains("b=TIAS:20000000"))
        assertFalse("audio must not be given a video ceiling", audio.contains("b=AS"))

        // After the connection line, which is where a b= line belongs.
        assertTrue(video.indexOf("c=IN") < video.indexOf("b=AS"))
    }

    @Test
    fun `every video codec gets the start bitrate hint`() {
        val patched = SdpQuality.patch(offer, 20_000_000)

        // H264 already had an fmtp line, so the hints are appended to it.
        assertTrue(patched.contains("profile-level-id=420034;x-google-max-bitrate=20000"))
        // VP8 had none, so one is written.
        assertTrue(patched.contains("a=fmtp:98 x-google-max-bitrate=20000"))
        assertTrue(patched.contains("x-google-start-bitrate=2500"))
    }

    @Test
    fun `nothing here is a floor`() {
        // A minimum the link cannot afford is paid for in pixels: 640x480 at 5
        // Mbps is reachable and 1920x1080 is not, so an encoder made to meet
        // the floor sends 480p on a connection with room for 1080p.
        assertFalse(SdpQuality.patch(offer, 20_000_000).contains("x-google-min-bitrate"))
    }

    @Test
    fun `the start bitrate is a probe a real link can absorb`() {
        // Not a fraction of the ceiling. 12 Mbps thrown at a phone's link in
        // its first second is answered with loss, which collapses the estimate
        // below where it would have climbed unaided.
        val start = Regex("x-google-start-bitrate=(\\d+)")
            .find(SdpQuality.patch(offer, 50_000_000))
            ?.groupValues?.get(1)?.toInt()
        assertEquals(2500, start)

        // And a ceiling under the probe is the ceiling, not the probe.
        assertTrue(SdpQuality.patch(offer, 1_000_000).contains("x-google-start-bitrate=1000"))
    }

    @Test
    fun `retransmission is not a picture`() {
        // `apt=96` is the whole of an rtx format line and there is no encoder
        // behind it. Appending to it is how a patched description gets refused
        // in one piece, losing the hints on the codecs that did want them - and
        // the raised H264 level with them.
        val withRtx = SdpQuality.patch(
            listOf(
                "v=0",
                "m=video 9 UDP/TLS/RTP/SAVPF 96 97",
                "c=IN IP4 0.0.0.0",
                "a=rtpmap:96 H264/90000",
                "a=fmtp:96 packetization-mode=1",
                "a=rtpmap:97 rtx/90000",
                "a=fmtp:97 apt=96",
            ).joinToString("\r\n") + "\r\n",
            20_000_000,
        )

        assertTrue("rtx was hinted at: $withRtx", withRtx.contains("a=fmtp:97 apt=96\r\n"))
        assertTrue(withRtx.contains("a=fmtp:96 packetization-mode=1;x-google-max-bitrate=20000"))
    }

    @Test
    fun `patching twice does not stack bandwidth lines`() {
        val once = SdpQuality.patch(offer, 20_000_000)
        val twice = SdpQuality.patch(once, 20_000_000)

        assertEquals(1, Regex("b=AS:").findAll(twice).count())
        assertEquals(1, Regex("b=TIAS:").findAll(twice).count())
    }

    // --- The microphone half -------------------------------------------------

    private val audioSdp = """v=0
m=audio 9 UDP/TLS/RTP/SAVPF 111 63
c=IN IP4 0.0.0.0
a=rtpmap:111 opus/48000/2
a=fmtp:111 minptime=10;useinbandfec=1
m=video 9 UDP/TLS/RTP/SAVPF 96
c=IN IP4 0.0.0.0
a=rtpmap:96 H264/90000
"""

    @Test
    fun `opus is told the bitrate, the channel count and whether to stop for silence`() {
        val patched = SdpQuality.patchAudio(
            audioSdp,
            MicEncoding(maxBitrate = 128_000, stereo = true, dtx = false),
        )
        val fmtp = patched.lines().first { it.startsWith("a=fmtp:111") }

        assertTrue(fmtp.contains("maxaveragebitrate=128000"))
        // Both, or a hi-fi call is stereo in one direction only.
        assertTrue(fmtp.contains("stereo=1"))
        assertTrue(fmtp.contains("sprop-stereo=1"))
        assertTrue(fmtp.contains("usedtx=0"))
        // What was already there survives.
        assertTrue(fmtp.contains("minptime=10"))
    }

    @Test
    fun `an existing parameter is replaced rather than repeated`() {
        val patched = SdpQuality.patchAudio(
            """m=audio 9 x 111
a=rtpmap:111 opus/48000/2
a=fmtp:111 stereo=1;usedtx=1
""",
            MicEncoding(maxBitrate = 64_000, stereo = false, dtx = true),
        )
        val fmtp = patched.lines().first { it.startsWith("a=fmtp:111") }

        // "stereo=1;stereo=0" is a line whose meaning depends on which end
        // reads it first, which is not a thing to ship.
        assertEquals(1, Regex("stereo=").findAll(fmtp).count() - Regex("sprop-stereo=").findAll(fmtp).count())
        assertTrue(fmtp.contains("stereo=0"))
        assertTrue(fmtp.contains("usedtx=1"))
    }

    @Test
    fun `the video section is left alone by the audio patch`() {
        val patched = SdpQuality.patchAudio(
            audioSdp,
            MicEncoding(maxBitrate = 64_000, stereo = false, dtx = true),
        )
        val video = patched.substringAfter("m=video")

        assertTrue(video.contains("a=rtpmap:96 H264/90000"))
        assertTrue(!video.contains("maxaveragebitrate"))
    }
}

package com.aatech.betweenus.feature.voice

import org.json.JSONObject
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test

/**
 * Who is allowed to hand this phone a mouse, and who is not.
 *
 * The rule worth asserting is the one that is invisible when it breaks: a
 * `grant` is only meaningful from the peer that was actually asked. Without
 * that check, anybody in the call could send an unsolicited "yes" and this
 * client would start sending mouse events at them - not a security hole in the
 * usual sense, since it is their own machine that would be driven, but a
 * client doing something nobody asked for and nothing on screen explaining it.
 */
class ShareControlTest {

    private val sent = mutableListOf<Pair<String, JSONObject>>()

    @Before
    fun attach() {
        sent.clear()
        ShareControl.attach { peerId, envelope -> sent += peerId to envelope }
    }

    @After
    fun detach() = ShareControl.detach()

    private fun message(index: Int): JSONObject = sent[index].second.getJSONObject("message")

    @Test
    fun `asking names the peer and carries the desktop's topic`() {
        ShareControl.ask("alice")
        assertEquals("alice", ShareControl.asking.value)
        assertEquals("alice", sent[0].first)
        assertEquals(ShareControl.TOPIC, sent[0].second.getString("topic"))
        assertEquals("ask", message(0).getString("k"))
    }

    @Test
    fun `a grant from the peer that was asked starts the drive`() {
        ShareControl.ask("alice")
        ShareControl.receive("alice", JSONObject().put("k", "grant"))
        assertEquals("alice", ShareControl.driving.value)
        assertNull(ShareControl.asking.value)
    }

    @Test
    fun `a grant from somebody who was never asked is ignored`() {
        ShareControl.ask("alice")
        ShareControl.receive("mallory", JSONObject().put("k", "grant"))
        assertNull(ShareControl.driving.value)
        // And the real request is still outstanding rather than cancelled by it.
        assertEquals("alice", ShareControl.asking.value)
    }

    @Test
    fun `a refusal from a third party does not cancel the real request either`() {
        ShareControl.ask("alice")
        ShareControl.receive("mallory", JSONObject().put("k", "deny").put("why", "no"))
        assertEquals("alice", ShareControl.asking.value)
        assertNull(ShareControl.refusal.value)
    }

    @Test
    fun `a refusal carries its reason, and a blank one still says something`() {
        ShareControl.ask("alice")
        ShareControl.receive("alice", JSONObject().put("k", "deny").put("why", "Sharing a window"))
        assertEquals("Sharing a window", ShareControl.refusal.value)
        assertNull(ShareControl.asking.value)

        ShareControl.ask("alice")
        ShareControl.receive("alice", JSONObject().put("k", "deny"))
        assertEquals("They said no", ShareControl.refusal.value)
    }

    @Test
    fun `the sharer taking it back ends the drive`() {
        ShareControl.ask("alice")
        ShareControl.receive("alice", JSONObject().put("k", "grant"))
        ShareControl.receive("alice", JSONObject().put("k", "revoke"))
        assertNull(ShareControl.driving.value)
    }

    @Test
    fun `somebody asking to drive this phone is told why not`() {
        ShareControl.receive("alice", JSONObject().put("k", "ask"))
        assertEquals("alice", sent[0].first)
        assertEquals("deny", message(0).getString("k"))
        assertTrue(message(0).getString("why").isNotBlank())
    }

    @Test
    fun `input aimed at this phone is dropped rather than answered`() {
        ShareControl.receive("alice", JSONObject().put("k", "m").put("a", "down"))
        ShareControl.receive("alice", JSONObject().put("k", "key").put("a", "down"))
        assertTrue(sent.isEmpty())
    }

    @Test
    fun `nothing is sent while nothing is being driven`() {
        // A stray touch after the drive ended must not reach anybody's machine.
        ShareControl.sendMouse("down", 0.5f, 0.5f, button = "left")
        assertTrue(sent.isEmpty())
    }

    @Test
    fun `coordinates are fractions, and are clamped to the picture`() {
        ShareControl.ask("alice")
        ShareControl.receive("alice", JSONObject().put("k", "grant"))
        sent.clear()
        ShareControl.sendMouse("down", -0.5f, 2f, button = "left")
        val move = message(0)
        assertEquals(0.0, move.getDouble("x"), 0.0001)
        assertEquals(1.0, move.getDouble("y"), 0.0001)
        assertEquals("left", move.getString("b"))
    }
}

package com.aatech.betweenus.feature.voice

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The capture size and the bitrate ceiling, which are the two numbers that
 * decide whether a share arrives readable.
 *
 * They are checked rather than eyeballed because getting either wrong is
 * invisible at the sending end: the phone looks fine, and only the person
 * watching sees the soft picture.
 */
class ShareQualityTest {

    @Test
    fun `a 1080p display is captured whole`() {
        val size = ShareQuality.scaleToFit(1080, 1920)
        assertEquals(1080, size.width)
        assertEquals(1920, size.height)
    }

    @Test
    fun `a taller than 1080p display is brought down by its long edge, in shape`() {
        // A 1440x3120 phone. The long edge lands on the cap and the aspect
        // ratio survives, because a share in the wrong shape is worse than a
        // smaller one.
        val size = ShareQuality.scaleToFit(1440, 3120)
        assertEquals(1920, size.height)
        assertEquals(886, size.width)

        val before = 1440.0 / 3120.0
        val after = size.width.toDouble() / size.height.toDouble()
        assertTrue("aspect drifted: $before to $after", kotlin.math.abs(before - after) < 0.01)
    }

    @Test
    fun `capture sizes are always even`() {
        // An odd dimension is a size no H264 encoder will take, and the failure
        // is a share that produces no frames at all rather than a warning.
        for (height in listOf(2001, 2399, 1081, 999)) {
            val size = ShareQuality.scaleToFit(1079, height)
            assertEquals(0, size.width % 2)
            assertEquals(0, size.height % 2)
        }
    }

    @Test
    fun `bitrate scales with pixels and stays inside its bounds`() {
        val fullHd = ShareQuality.screenBitrate(ShareQuality.Size(1920, 1080))
        assertEquals(20_000_000, fullHd)

        // Small screens still get a floor worth having: the old default was
        // about 3 Mbps at any size, which is what made this soft.
        val small = ShareQuality.screenBitrate(ShareQuality.Size(640, 360))
        assertEquals(8_000_000, small)

        // And a huge one cannot ask for the moon.
        val huge = ShareQuality.screenBitrate(ShareQuality.Size(7680, 4320))
        assertEquals(50_000_000, huge)
    }

    // --- Which codec, and which H.264 ---------------------------------------

    @Test
    fun `H264 outranks everything else`() {
        assertTrue(
            ShareQuality.codecRank("H264", emptyMap()) >
                ShareQuality.codecRank("VP9", mapOf("profile-level-id" to "64001f")),
        )
    }

    @Test
    fun `high profile outranks the baseline a phone offers first`() {
        val baseline = ShareQuality.codecRank(
            "H264",
            mapOf("profile-level-id" to "42e01f", "packetization-mode" to "1"),
        )
        val high = ShareQuality.codecRank(
            "H264",
            mapOf("profile-level-id" to "64001f", "packetization-mode" to "1"),
        )
        assertTrue("baseline $baseline should not beat high $high", high > baseline)
    }

    @Test
    fun `high profile is read from the profile byte, not the whole prefix`() {
        // 640c1f is High with constraint_set3 set. Matching on "6400" alone
        // would rank it as baseline and hand a phone the softer encoder.
        val constrained = ShareQuality.codecRank("H264", mapOf("profile-level-id" to "640c1f"))
        val plain = ShareQuality.codecRank("H264", mapOf("profile-level-id" to "64001f"))
        assertEquals(plain, constrained)
    }

    @Test
    fun `a whole NAL unit beats one chopped to the MTU`() {
        val mode1 = ShareQuality.codecRank(
            "H264",
            mapOf("profile-level-id" to "42e01f", "packetization-mode" to "1"),
        )
        val mode0 = ShareQuality.codecRank("H264", mapOf("profile-level-id" to "42e01f"))
        assertTrue(mode1 > mode0)
    }
}

package com.aatech.betweenus.core.crypto

import org.json.JSONObject
import java.math.BigInteger
import java.security.AlgorithmParameters
import java.security.KeyFactory
import java.security.KeyPairGenerator
import java.security.PrivateKey
import java.security.PublicKey
import java.security.SecureRandom
import java.security.spec.ECGenParameterSpec
import java.security.spec.ECParameterSpec
import java.security.spec.ECPoint
import java.security.spec.ECPrivateKeySpec
import java.security.spec.ECPublicKeySpec
import java.security.interfaces.ECPrivateKey
import java.security.interfaces.ECPublicKey
import javax.crypto.Cipher
import javax.crypto.KeyAgreement
import javax.crypto.Mac
import javax.crypto.SecretKeyFactory
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.PBEKeySpec
import javax.crypto.spec.SecretKeySpec
import okio.ByteString.Companion.decodeBase64
import okio.ByteString.Companion.toByteString

/**
 * End-to-end encryption primitives, matching
 * `apps/desktop/src/services/e2ee-crypto.ts` byte for byte. Anything that
 * disagrees here produces ciphertext the other two clients cannot open, which
 * is a failure that looks exactly like a bug in the message list.
 *
 * The scheme, from development/E2EE.md:
 *   - identity: ECDH P-256 key pair per device, private half never leaves it
 *   - channel key: random AES-256-GCM key per channel, per epoch
 *   - distribution: ECDH(sender, recipient) -> HKDF-SHA256 -> AES-GCM wrap
 *   - messages and attachments: AES-256-GCM under the channel key
 *
 * Keys cross the wire as JWK, because that is what WebCrypto exports and the
 * directory stores. Java speaks X.509/PKCS#8 instead, so the conversion is done
 * by hand below - a P-256 JWK is just the curve point's two coordinates, and
 * the private one adds the scalar.
 */
object Crypto {
    private const val CURVE = "secp256r1"
    private const val WRAP_INFO = "betweenus/e2ee/v1/channel-key-wrap"
    private const val IV_BYTES = 12
    private const val GCM_TAG_BITS = 128
    private const val CHANNEL_KEY_BYTES = 32
    private const val BACKUP_SALT_BYTES = 16

    /**
     * PBKDF2 rounds for the identity backup, and it has to be the number the
     * other clients use: the blob says which count sealed it, but a *new* blob
     * sealed here with fewer rounds would quietly weaken an account's backup.
     */
    const val BACKUP_ITERATIONS = 600_000

    private val random = SecureRandom()

    data class KeyPairJwk(val publicKey: String, val privateKey: String)

    data class Wrapped(val wrappedKey: String, val iv: String)

    data class Sealed(val iv: String, val ciphertext: ByteArray) {
        override fun equals(other: Any?): Boolean =
            other is Sealed && iv == other.iv && ciphertext.contentEquals(other.ciphertext)

        override fun hashCode(): Int = 31 * iv.hashCode() + ciphertext.contentHashCode()
    }

    // --- identity ---

    fun generateIdentity(): KeyPairJwk {
        val generator = KeyPairGenerator.getInstance("EC")
        generator.initialize(ECGenParameterSpec(CURVE), random)
        val pair = generator.generateKeyPair()
        return KeyPairJwk(
            publicKey = publicToJwk(pair.public as ECPublicKey),
            privateKey = privateToJwk(pair.private as ECPrivateKey, pair.public as ECPublicKey),
        )
    }

    /**
     * Seals the identity key pair so the server can hold it without being able
     * to open it. This is what makes an account portable: the same identity
     * comes back on any device that can supply the secret, so channel keys
     * already sealed for it keep opening.
     */
    fun sealIdentity(pair: KeyPairJwk, secret: String, iterations: Int = BACKUP_ITERATIONS): Triple<String, String, String> {
        val salt = randomBytes(BACKUP_SALT_BYTES)
        val key = deriveBackupKey(secret, salt, iterations)
        val iv = randomBytes(IV_BYTES)
        val plaintext = JSONObject()
            .put("publicKey", pair.publicKey)
            .put("privateKey", pair.privateKey)
            .toString()
        val sealed = aes(Cipher.ENCRYPT_MODE, key, iv, plaintext.toByteArray())
        return Triple(base64(salt), base64(iv), base64(sealed))
    }

    /** Throws if the secret is wrong - AES-GCM's tag is the only check needed. */
    fun openIdentity(
        salt: String,
        iv: String,
        ciphertext: String,
        secret: String,
        iterations: Int,
    ): KeyPairJwk {
        val key = deriveBackupKey(secret, unbase64(salt), iterations)
        val opened = aes(Cipher.DECRYPT_MODE, key, unbase64(iv), unbase64(ciphertext))
        val json = JSONObject(String(opened))
        val public = json.optString("publicKey")
        val private = json.optString("privateKey")
        require(public.isNotEmpty() && private.isNotEmpty()) {
            "Backup did not contain an identity key pair"
        }
        return KeyPairJwk(public, private)
    }

    private fun deriveBackupKey(secret: String, salt: ByteArray, iterations: Int): ByteArray {
        val spec = PBEKeySpec(secret.toCharArray(), salt, iterations, 256)
        return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).encoded
    }

    // --- channel keys ---

    fun generateChannelKey(): String = base64(randomBytes(CHANNEL_KEY_BYTES))

    fun wrapChannelKey(channelKey: String, privateJwk: String, peerPublicJwk: String): Wrapped {
        val key = deriveWrappingKey(privateJwk, peerPublicJwk)
        val iv = randomBytes(IV_BYTES)
        val sealed = aes(Cipher.ENCRYPT_MODE, key, iv, unbase64(channelKey))
        return Wrapped(base64(sealed), base64(iv))
    }

    fun unwrapChannelKey(wrapped: Wrapped, privateJwk: String, peerPublicJwk: String): String {
        val key = deriveWrappingKey(privateJwk, peerPublicJwk)
        return base64(aes(Cipher.DECRYPT_MODE, key, unbase64(wrapped.iv), unbase64(wrapped.wrappedKey)))
    }

    /**
     * The raw ECDH output is a curve point, not a uniform key, so it goes
     * through HKDF before it is used as an AES key. The salt is 32 zero bytes
     * and the info string domain-separates this use of the secret - both have
     * to match the other clients exactly.
     */
    private fun deriveWrappingKey(privateJwk: String, peerPublicJwk: String): ByteArray {
        val agreement = KeyAgreement.getInstance("ECDH")
        agreement.init(privateFromJwk(privateJwk))
        agreement.doPhase(publicFromJwk(peerPublicJwk), true)
        val shared = agreement.generateSecret()
        return hkdfSha256(shared, ByteArray(32), WRAP_INFO.toByteArray(), 32)
    }

    /** RFC 5869, extract then expand. One block is enough for a 256-bit key. */
    fun hkdfSha256(input: ByteArray, salt: ByteArray, info: ByteArray, length: Int): ByteArray {
        val extract = Mac.getInstance("HmacSHA256").run {
            init(SecretKeySpec(salt, "HmacSHA256"))
            doFinal(input)
        }
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(extract, "HmacSHA256"))

        val output = ByteArray(length)
        var block = ByteArray(0)
        var written = 0
        var counter = 1
        while (written < length) {
            mac.reset()
            mac.update(block)
            mac.update(info)
            mac.update(counter.toByte())
            block = mac.doFinal()
            val take = minOf(block.size, length - written)
            System.arraycopy(block, 0, output, written, take)
            written += take
            counter += 1
        }
        return output
    }

    /**
     * `HMAC-SHA256(channel key, fingerprint)`, base64 - what signs a DTLS
     * fingerprint so the signalling relay cannot substitute one of its own.
     *
     * The key is the UTF-8 bytes of the base64 *string*, not the 32 bytes it
     * decodes to. That is what `signFingerprint` in the desktop's mesh.ts does,
     * and matching it is the whole requirement: a signature computed over
     * different key bytes verifies nowhere and every call fails to connect.
     */
    fun signFingerprint(channelKey: String, fingerprint: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(channelKey.toByteArray(), "HmacSHA256"))
        return base64(mac.doFinal(fingerprint.toByteArray()))
    }

    // --- content ---

    fun encrypt(plaintext: String, channelKey: String): Sealed {
        val iv = randomBytes(IV_BYTES)
        return Sealed(base64(iv), aes(Cipher.ENCRYPT_MODE, unbase64(channelKey), iv, plaintext.toByteArray()))
    }

    fun decrypt(ciphertext: String, iv: String, channelKey: String): String =
        String(aes(Cipher.DECRYPT_MODE, unbase64(channelKey), unbase64(iv), unbase64(ciphertext)))

    fun encryptBytes(plaintext: ByteArray, channelKey: String): Sealed {
        val iv = randomBytes(IV_BYTES)
        return Sealed(base64(iv), aes(Cipher.ENCRYPT_MODE, unbase64(channelKey), iv, plaintext))
    }

    fun decryptBytes(ciphertext: ByteArray, iv: String, channelKey: String): ByteArray =
        aes(Cipher.DECRYPT_MODE, unbase64(channelKey), unbase64(iv), ciphertext)

    private fun aes(mode: Int, key: ByteArray, iv: ByteArray, input: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(mode, SecretKeySpec(key, "AES"), GCMParameterSpec(GCM_TAG_BITS, iv))
        return cipher.doFinal(input)
    }

    private fun randomBytes(length: Int) = ByteArray(length).also { random.nextBytes(it) }

    // --- JWK <-> Java keys ---
    //
    // WebCrypto exports P-256 keys as JWK: `x` and `y` are the public point's
    // coordinates and `d` is the private scalar, each 32 big-endian bytes in
    // base64url. Java wants ECPublicKeySpec/ECPrivateKeySpec, so the conversion
    // is arithmetic rather than parsing.

    private fun curveSpec(): ECParameterSpec {
        val parameters = AlgorithmParameters.getInstance("EC")
        parameters.init(ECGenParameterSpec(CURVE))
        return parameters.getParameterSpec(ECParameterSpec::class.java)
    }

    fun publicFromJwk(jwk: String): PublicKey {
        val json = JSONObject(jwk)
        val point = ECPoint(coordinate(json.getString("x")), coordinate(json.getString("y")))
        return KeyFactory.getInstance("EC").generatePublic(ECPublicKeySpec(point, curveSpec()))
    }

    fun privateFromJwk(jwk: String): PrivateKey {
        val json = JSONObject(jwk)
        val scalar = coordinate(json.getString("d"))
        return KeyFactory.getInstance("EC").generatePrivate(ECPrivateKeySpec(scalar, curveSpec()))
    }

    private fun publicToJwk(key: ECPublicKey): String = JSONObject()
        .put("kty", "EC")
        .put("crv", "P-256")
        .put("x", coordinateBase64Url(key.w.affineX))
        .put("y", coordinateBase64Url(key.w.affineY))
        .put("ext", true)
        .toString()

    private fun privateToJwk(key: ECPrivateKey, public: ECPublicKey): String = JSONObject()
        .put("kty", "EC")
        .put("crv", "P-256")
        .put("x", coordinateBase64Url(public.w.affineX))
        .put("y", coordinateBase64Url(public.w.affineY))
        .put("d", coordinateBase64Url(key.s))
        .put("ext", true)
        .put("key_ops", org.json.JSONArray().put("deriveBits"))
        .toString()

    /** Always 32 bytes, left-padded: a short coordinate is still a coordinate. */
    private fun coordinateBase64Url(value: BigInteger): String {
        val raw = value.toByteArray()
        val fixed = ByteArray(32)
        when {
            raw.size == 32 -> System.arraycopy(raw, 0, fixed, 0, 32)
            // BigInteger prepends a sign byte when the top bit is set.
            raw.size > 32 -> System.arraycopy(raw, raw.size - 32, fixed, 0, 32)
            else -> System.arraycopy(raw, 0, fixed, 32 - raw.size, raw.size)
        }
        return base64Url(fixed)
    }

    private fun coordinate(base64Url: String) = BigInteger(1, unbase64Url(base64Url))

    // --- base64 ---
    //
    // Standard alphabet for everything the wire calls base64 (btoa on the other
    // clients), URL-safe and unpadded inside a JWK, which is what RFC 7515 says.

    fun base64(bytes: ByteArray): String = bytes.toByteString().base64()

    fun unbase64(value: String): ByteArray =
        (value.decodeBase64() ?: throw IllegalArgumentException("Not base64")).toByteArray()

    /** JWK members are base64url and unpadded, which is what RFC 7515 says. */
    private fun base64Url(bytes: ByteArray): String = bytes.toByteString().base64Url().trimEnd('=')

    private fun unbase64Url(value: String): ByteArray =
        (value.decodeBase64() ?: throw IllegalArgumentException("Not base64")).toByteArray()
}

package com.aatech.betweenus.core.crypto

import android.content.Context
import com.aatech.betweenus.core.data.ApiError
import com.aatech.betweenus.core.data.ChannelKeyEntry
import com.aatech.betweenus.core.data.ChannelKeys
import com.aatech.betweenus.core.data.DeviceKey
import com.aatech.betweenus.core.data.IdentityBackup
import com.aatech.betweenus.core.data.StatusEntry
import com.aatech.betweenus.core.data.StatusKeyEntry
import com.aatech.betweenus.core.data.BetweenUsApi
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import org.json.JSONObject
import java.util.concurrent.ConcurrentHashMap

/** What opens an identity backup. Held only for the moment a sign-in needs it. */
data class BackupSecret(val value: String, val kind: String) {
    companion object {
        fun password(value: String) = BackupSecret(value, "password")
        fun passphrase(value: String) = BackupSecret(value, "passphrase")
    }
}

class MissingChannelKeyError : Exception("No channel key on this device yet")

/**
 * There is no `Locked`. A device that cannot open the account backup mints a
 * key of its own and signs in anyway - see [E2ee.initIdentity] - so there is no
 * state in which the app is signed in and waiting to be told a secret. That
 * fork used to be permanent; it is provisional now, and every later sign-in
 * with a secret that opens the backup undoes it.
 */
sealed interface IdentityStatus {
    data object Absent : IdentityStatus

    /**
     * `backedUp` is whether *this device's* key is the one in the backup.
     *
     * `provisional` is this device having minted its own because it could not
     * open the account's - so it reads what arrives from now on, and history is
     * still sealed to an identity it does not hold.
     */
    data class Ready(val backedUp: Boolean, val provisional: Boolean = false) : IdentityStatus

    /**
     * The owner revoked this machine from another one. Nothing new is wrapped
     * for it, so it reads what it already had and nothing since - saying so
     * beats a screen full of "no key on this device yet".
     */
    data object Revoked : IdentityStatus
}

/**
 * The end-to-end encryption service: this device's identity, the channel keys
 * it can open, and sealing and opening content with them.
 *
 * The port of `apps/desktop/src/services/e2ee.ts`. Every decision here about
 * *when* to mint an epoch, when to re-wrap for a member, and what to do when a
 * key cannot be opened is that file's, because the three clients share one
 * channel and disagreeing about any of it locks somebody out of their history.
 */
object E2ee {
    /**
     * Shown instead of a message this device holds no key for.
     *
     * Two words: it is drawn once per message, and a sentence repeated down a
     * whole screen is not eight times as informative as one. Why, and what to
     * do about it, is said once for the channel.
     */
    const val UNDECRYPTABLE = "🔒 Encrypted"

    private lateinit var store: SecureStore

    private var identity: Crypto.KeyPairJwk? = null
    private var userId: String? = null

    /**
     * The secret this session signed in with, kept for the length of the session.
     *
     * It used to be an argument and nothing else, so a sign-in whose identity
     * setup failed once - the network dropped, the token was a moment late -
     * lost it. [currentIdentity] then retried with no secret, could not open the
     * account backup, and minted a device-local key instead, which was
     * permanent. A password typed into a login form is dropped when the session
     * ends, and that is the only thing keeping it here has to guarantee.
     */
    @Volatile
    private var signInSecret: BackupSecret? = null

    private val identityLock = Mutex()
    private val channelLocks = ConcurrentHashMap<String, Mutex>()

    /** Every epoch this device can open, per channel, so old history stays readable. */
    private class ChannelKeyState(val epoch: Int, val keys: Map<Int, String>)

    private val channels = ConcurrentHashMap<String, ChannelKeyState>()

    /**
     * Channels this session has already tried to re-key for itself. Without it,
     * a device that cannot open its own wrapped keys would mint a fresh epoch
     * every time the channel is opened and drag the whole channel along with it.
     */
    private val rekeyed = ConcurrentHashMap.newKeySet<String>()

    /**
     * Epochs this client has already gone back to the directory for and still
     * not found. Without it, a channel holding one genuinely unreadable message
     * would re-read the key directory every time that message is drawn.
     */
    private val missedEpochs = ConcurrentHashMap.newKeySet<String>()

    private val _status = MutableStateFlow<IdentityStatus>(IdentityStatus.Absent)
    val status: StateFlow<IdentityStatus> = _status.asStateFlow()

    fun init(context: Context) {
        store = SecureStore(context)
    }

    // --- identity ---

    /**
     * Loads this device's identity key and publishes the public half. Called
     * once per sign-in, with the password when there is one to hand.
     *
     * It never fails for want of a secret, and it never asks for one.
     */
    suspend fun initIdentity(userId: String, secret: BackupSecret? = null): Crypto.KeyPairJwk =
        identityLock.withLock {
            identity?.let { if (this.userId == userId) return@withLock it }
            this.userId = userId
            // Held past this call on purpose: [currentIdentity] retries with no
            // secret of its own, and a retry without one forks permanently.
            if (secret != null) signInSecret = secret
            val opener = secret ?: signInSecret

            val storageKey = "identity:$userId"
            store.get(storageKey)?.let { stored ->
                val saved = runCatching { readStored(stored) }.getOrNull()
                if (saved != null) {
                    // A device that forked gets another go, every time a secret
                    // is at hand. This is the whole of "sign in on a new phone
                    // and your messages are there": the fork below is silent and
                    // one-way, so the only thing that makes it recoverable is
                    // trying the backup again on the next sign-in rather than
                    // short-circuiting on the key the fork left behind.
                    if (saved.provisional && opener != null) {
                        restoreFromBackup(storageKey, opener)?.let { return@withLock it }
                    }
                    adopt(saved.pair, provisional = saved.provisional)
                    // A device that already worked may still have no backup.
                    // Fix it quietly when a secret is at hand rather than
                    // waiting for the next reinstall to notice.
                    ensureBackup(saved.pair, opener)
                    return@withLock saved.pair
                }
            }

            // A failed fetch must not be read as "there is no backup": that
            // would seal a fresh key over one that exists. It throws, and the
            // sign-in retries.
            val backups = BetweenUsApi.identityBackups()

            // The account's own key, when the secret that opens it is at hand.
            // The good path and the only instant one: every epoch already
            // sealed for that identity opens the moment it lands.
            if (opener != null) {
                restoreFromBackup(storageKey, opener, backups)?.let { return@withLock it }
            }

            // Otherwise this device gets a key of its own and the sign-in
            // carries on. It used to stop and ask - and asking is not something
            // every sign-in can answer: a provider sign-in has no account
            // password to offer, and an account that has only ever used one has
            // no password at all.
            //
            // Minting is safe because a channel key is wrapped per *device*:
            // this device publishes its own public key under its own device id
            // and takes nothing from the devices already in the directory.
            // History arrives from them - `fillGaps` hands every epoch a device
            // holds to the owner's devices missing it - so the account
            // converges without anyone typing anything. What it costs is that
            // history is not instant; it appears as the other devices open
            // those channels. See apps/desktop/src/services/e2ee.ts.
            //
            // The fork is marked when the account *had* a backup this device
            // could not open, and that mark is what lets the next sign-in undo
            // it. Unmarked means there was nothing to restore from, so this key
            // is the account's own.
            val provisional = backups.isNotEmpty()
            val pair = Crypto.generateIdentity()
            store.put(storageKey, writePair(pair, provisional))
            adopt(pair, provisional = provisional)
            ensureBackup(pair, opener)
            pair
        }

    /**
     * Opens whichever backup [secret] fits and makes it this device's identity.
     *
     * Null means "not this secret" - a wrong password, or a passphrase-only
     * account signing in with a password - which is an ordinary outcome here,
     * not a failure.
     *
     * Every channel key held on this device is dropped on the way out. They are
     * still valid, but they are the *subset* a forked identity could reach, and
     * the caches in front of them - memory and the sealed store both - would
     * keep serving that subset while the wraps this identity can now open sat
     * unread in the directory. Dropping them costs one re-read of a directory
     * we have just been talking to.
     */
    private suspend fun restoreFromBackup(
        storageKey: String,
        secret: BackupSecret,
        known: List<IdentityBackup>? = null,
    ): Crypto.KeyPairJwk? {
        val backups = known ?: runCatching { BetweenUsApi.identityBackups() }.getOrNull() ?: return null
        val sealed = backups.firstOrNull { it.kind == secret.kind } ?: return null
        val pair = openBackup(sealed, secret) ?: return null

        store.put(storageKey, writePair(pair))
        forgetAllKeys()
        adopt(pair, backedUp = true)
        return pair
    }

    /** Seals the current identity under a secret the user chose. */
    suspend fun backupIdentity(secret: BackupSecret) {
        val pair = currentIdentity()
        BetweenUsApi.putIdentityBackup(seal(pair, secret))
        _status.value = IdentityStatus.Ready(backedUp = true)
    }

    /**
     * Re-seals the backup after a password change. Skipped silently when the
     * backup is keyed to a passphrase, which a password change does not touch.
     */
    suspend fun rewrapBackupForPassword(newPassword: String) {
        if (BetweenUsApi.identityBackups().none { it.kind == "password" }) return
        backupIdentity(BackupSecret.password(newPassword))
        // The secret this session holds is now the old one, and a retry using it
        // would fail to open the blob it has just re-sealed.
        signInSecret = BackupSecret.password(newPassword)
    }

    /**
     * Whether the account password can still recover this identity on a device
     * that has never seen it.
     *
     * The one thing a settings screen has to be able to say plainly: it is the
     * difference between "sign in anywhere" and "sign in anywhere and type a
     * passphrase you wrote down once".
     */
    suspend fun passwordRecoveryEnabled(): Boolean =
        BetweenUsApi.identityBackups().any { it.kind == "password" }

    /**
     * Turns the password path off, for somebody who set a recovery passphrase
     * *because* a live server sees the password at sign-in and they would rather
     * it could never open the backup.
     *
     * Refuses when it would leave the account with no backup at all. That is not
     * a security setting, it is losing every message on the next reinstall.
     */
    suspend fun disablePasswordRecovery() {
        if (BetweenUsApi.identityBackups().none { it.kind == "passphrase" }) {
            error("Set a recovery passphrase first, or this account has no way back at all")
        }
        BetweenUsApi.deleteIdentityBackup("password")
    }

    fun reset() {
        // Key material is per-user; a sign-out must not leak it into the next
        // session. What is on disk stays - it is sealed, and the same account
        // signing back in should not have to fetch its backup again.
        identity = null
        userId = null
        signInSecret = null
        channels.clear()
        channelLocks.clear()
        rekeyed.clear()
        missedEpochs.clear()
        _status.value = IdentityStatus.Absent
    }

    private suspend fun adopt(
        pair: Crypto.KeyPairJwk,
        backedUp: Boolean = false,
        provisional: Boolean = false,
    ) {
        identity = pair
        try {
            // Idempotent: re-publishing keeps the directory correct if the row
            // was lost, and refreshes when this phone was last seen.
            BetweenUsApi.registerDeviceKey(DeviceIdentity.id(), pair.publicKey, DeviceIdentity.label())
        } catch (error: ApiError) {
            // Revoked from another machine. Not a thing to retry, and not a
            // reason to mint a new id - minting one is how a revoked phone
            // would walk straight back into the directory.
            if (error.code == "DEVICE_REVOKED") {
                _status.value = IdentityStatus.Revoked
            }
            throw error
        }
        _status.value = IdentityStatus.Ready(backedUp, provisional)
    }

    /**
     * Uploads a backup when the account has none for this identity and a secret
     * is available to seal it with. Never throws into a sign-in: an account
     * without a backup still works, it is only unrecoverable, and settings says so.
     */
    private suspend fun ensureBackup(pair: Crypto.KeyPairJwk, secret: BackupSecret?) {
        runCatching {
            val backups = BetweenUsApi.identityBackups()
            val backedUp = backups.any { it.publicKey == pair.publicKey }

            // A backup that already stands is not this device's to replace
            // unless it is this device's key in it. Since a device that could
            // not open one mints its own, sealing over it here would take the
            // account's recoverable identity away from every device still
            // restoring from it. Deliberate re-sealing is [backupIdentity]'s.
            //
            // Scoped to the *kind* now. An account holding a passphrase backup
            // and no password one is exactly the account that cannot recover on
            // a fresh sign-in, so filling that gap when the password is at hand
            // is the point rather than an overreach - and it only ever seals the
            // key this device already holds, which is the identity the other
            // devices restore from whenever `backedUp` says so.
            if (secret == null || backups.any { it.kind == secret.kind } || !backedUp) {
                _status.value = IdentityStatus.Ready(
                    backedUp = backedUp,
                    provisional = backups.isNotEmpty() && !backedUp,
                )
                return
            }
            BetweenUsApi.putIdentityBackup(seal(pair, secret))
            _status.value = IdentityStatus.Ready(backedUp = true)
        }
        // Offline, or a server older than this client. Nothing is lost that was
        // not already missing.
    }

    private fun seal(pair: Crypto.KeyPairJwk, secret: BackupSecret): IdentityBackup {
        val (salt, iv, ct) = Crypto.sealIdentity(pair, secret.value)
        return IdentityBackup(
            kind = secret.kind,
            iterations = Crypto.BACKUP_ITERATIONS,
            salt = salt,
            iv = iv,
            ct = ct,
            publicKey = pair.publicKey,
        )
    }

    /** The wrong secret is an ordinary outcome here, not an error: null, and on. */
    private fun openBackup(backup: IdentityBackup, secret: BackupSecret): Crypto.KeyPairJwk? =
        runCatching {
            Crypto.openIdentity(backup.salt, backup.iv, backup.ct, secret.value, backup.iterations)
        }.getOrNull()

    /**
     * What the sealed store holds. `provisional` marks a key this device minted
     * for itself *while the account had a backup it could not open* - the fork
     * described in [initIdentity]. It is the flag that makes the fork
     * recoverable: without it the stored key short-circuits every later launch
     * and the backup is never tried again, on any sign-in, ever.
     */
    private class StoredIdentity(val pair: Crypto.KeyPairJwk, val provisional: Boolean)

    private fun writePair(pair: Crypto.KeyPairJwk, provisional: Boolean = false) = JSONObject()
        .put("publicKey", pair.publicKey)
        .put("privateKey", pair.privateKey)
        .put("provisional", provisional)
        .toString()

    private fun readStored(stored: String): StoredIdentity {
        val json = JSONObject(stored)
        return StoredIdentity(
            pair = Crypto.KeyPairJwk(json.getString("publicKey"), json.getString("privateKey")),
            // Absent on a blob written before the fork was recoverable. False is
            // the safe reading: it was minted under rules that had no mark, and
            // a sign-in that opens the backup replaces it either way.
            provisional = json.optBoolean("provisional", false),
        )
    }

    private suspend fun currentIdentity(): Crypto.KeyPairJwk =
        identity
            // With the session's secret, not without it. A retry that dropped it
            // opened no backup, minted a device-local key, and forked for good.
            ?: userId?.let { initIdentity(it, signInSecret) }
            ?: throw MissingChannelKeyError()

    // --- content ---

    suspend fun encryptForChannel(channelId: String, plaintext: String): String {
        val state = ensureChannelKey(channelId)
        val key = state.keys[state.epoch] ?: throw MissingChannelKeyError()
        val sealed = Crypto.encrypt(plaintext, key)
        return JSONObject()
            .put("v", 1)
            .put("epoch", state.epoch)
            .put("iv", sealed.iv)
            .put("ct", Crypto.base64(sealed.ciphertext))
            .toString()
    }

    /**
     * Reads a stored message body. Anything that is not an envelope is returned
     * as it stands, so plaintext rows written before E2EE still render.
     */
    suspend fun decryptForChannel(channelId: String, content: String): String {
        val envelope = parseEnvelope(content) ?: return content
        val key = keyForEpoch(channelId, envelope.epoch) ?: return UNDECRYPTABLE
        return runCatching { Crypto.decrypt(envelope.ct, envelope.iv, key) }
            .getOrDefault(UNDECRYPTABLE)
    }

    suspend fun encryptFileForChannel(channelId: String, plaintext: ByteArray): Pair<Crypto.Sealed, Int> {
        val state = ensureChannelKey(channelId)
        val key = state.keys[state.epoch] ?: throw MissingChannelKeyError()
        return Crypto.encryptBytes(plaintext, key) to state.epoch
    }

    suspend fun decryptFileForChannel(
        channelId: String,
        ciphertext: ByteArray,
        iv: String,
        epoch: Int,
    ): ByteArray {
        val key = keyForEpoch(channelId, epoch) ?: throw MissingChannelKeyError()
        return Crypto.decryptBytes(ciphertext, iv, key)
    }

    /**
     * The key a call's DTLS fingerprint is signed with. It is the channel key,
     * which the server has never held - which is exactly why a signature made
     * with it proves the relay did not substitute a fingerprint of its own.
     */
    suspend fun callKeyForChannel(channelId: String, refresh: Boolean = false): String {
        // `refresh` is what a call asks for when somebody new arrives. Joining a
        // channel you hold no key for mints the next epoch - that is the only
        // way a new member gets one - so the newcomer's key is a generation
        // ahead of the one everybody already in the call read when they joined,
        // and without the re-read the two sides sign fingerprints with
        // different keys and refuse each other for good.
        if (refresh) forgetKeys(channelId)
        val state = ensureChannelKey(channelId)
        return state.keys[state.epoch] ?: throw MissingChannelKeyError()
    }


    // --- statuses ---
    //
    // A status has no channel, so it has no epoch and nothing to rotate: one
    // key per post, wrapped once per device that may read it, and gone in a
    // day. None of the channel machinery above applies - there is no state to
    // load, no gap to fill and no rekey.
    //
    // The wrap list is the audience, built from the directory at the moment of
    // posting. A friendship made afterwards adds nothing to a post already
    // written, which is why a new friend does not see yesterday's moment.

    /** A post, sealed and ready to send. */
    class SealedStatus(
        val caption: String?,
        val media: Crypto.Sealed?,
        val keys: List<StatusKeyEntry>,
        val senderDeviceId: String,
    )

    /**
     * Seals one post for one audience.
     *
     * This phone may not be in the directory yet - one that signed in a moment
     * ago has not been listed - so we always wrap for ourselves. Posting
     * something we cannot open is the one failure with no way back.
     */
    suspend fun sealStatus(
        caption: String?,
        media: ByteArray?,
        devices: List<DeviceKey>,
    ): SealedStatus {
        val self = currentIdentity()
        val key = Crypto.generateChannelKey()
        val mine = DeviceIdentity.id()
        val recipients = if (devices.any { it.userId == userId && it.deviceId == mine }) {
            devices
        } else {
            devices + DeviceKey(userId.orEmpty(), mine, self.publicKey)
        }

        val keys = recipients.mapNotNull { device ->
            runCatching {
                val wrapped = Crypto.wrapChannelKey(key, self.privateKey, device.publicKey)
                StatusKeyEntry(
                    recipientUserId = device.userId,
                    recipientDeviceId = device.deviceId,
                    senderPublicKey = self.publicKey,
                    wrappedKey = wrapped.wrappedKey,
                    iv = wrapped.iv,
                )
            }.getOrNull()
            // A directory row with a malformed public key must not stop the
            // post being sealed for everybody else.
        }

        // Epoch 0 in the envelope: a status has no generations, and the field
        // is there because the shape is shared with messages.
        val sealedCaption = caption?.takeIf { it.isNotBlank() }?.let {
            val sealed = Crypto.encrypt(it, key)
            JSONObject()
                .put("v", 1)
                .put("epoch", 0)
                .put("iv", sealed.iv)
                .put("ct", Crypto.base64(sealed.ciphertext))
                .toString()
        }
        return SealedStatus(
            caption = sealedCaption,
            media = media?.let { Crypto.encryptBytes(it, key) },
            keys = keys,
            senderDeviceId = mine,
        )
    }

    /**
     * The key to one post, from whichever wrap this phone's private half opens.
     *
     * Null rather than a throw for the ordinary cases: a post written before
     * this device existed, or before the friendship did, carries no wrap for
     * us. Both happen, and neither is an error.
     */
    suspend fun statusKey(post: StatusEntry): String? {
        if (post.keys.isEmpty()) return null
        val self = currentIdentity()
        for (wrap in post.keys) {
            val opened = runCatching {
                Crypto.unwrapChannelKey(
                    Crypto.Wrapped(wrap.wrappedKey, wrap.iv),
                    self.privateKey,
                    wrap.senderPublicKey,
                )
            }.getOrNull()
            if (opened != null) return opened
        }
        return null
    }

    /** A post's caption in the clear, or the placeholder. Never throws. */
    suspend fun openStatusCaption(post: StatusEntry): String? {
        val caption = post.caption ?: return null
        // Written before statuses were sealed. It expires within the day.
        val envelope = parseEnvelope(caption) ?: return caption
        val key = statusKey(post) ?: return UNDECRYPTABLE
        return runCatching { Crypto.decrypt(envelope.ct, envelope.iv, key) }
            .getOrDefault(UNDECRYPTABLE)
    }

    /** A post's media in the clear. Null when this device holds no key for it. */
    suspend fun openStatusMedia(post: StatusEntry, ciphertext: ByteArray): ByteArray? {
        // No IV means it was stored in the clear, before this. Hand it back.
        val iv = post.mediaIv ?: return ciphertext
        val key = statusKey(post) ?: return null
        return runCatching { Crypto.decryptBytes(ciphertext, iv, key) }.getOrNull()
    }

    private class Envelope(val epoch: Int, val iv: String, val ct: String)

    private fun parseEnvelope(content: String): Envelope? {
        if (!content.startsWith("{")) return null
        return runCatching {
            val json = JSONObject(content)
            if (json.optInt("v") != 1) return null
            val iv = json.optString("iv")
            val ct = json.optString("ct")
            if (iv.isEmpty() || ct.isEmpty() || !json.has("epoch")) return null
            Envelope(json.getInt("epoch"), iv, ct)
        }.getOrNull()
    }

    // --- channel keys ---

    /**
     * Re-wraps the current key for members who have none. Called when a channel
     * is opened, so somebody who joined after the key was minted becomes able to
     * read without anyone restarting the app.
     */
    suspend fun syncChannelKeys(channelId: String) {
        val state = runCatching { ensureChannelKey(channelId) }.getOrNull() ?: return
        val latest = BetweenUsApi.channelKeys(channelId)

        // Held state now survives a restart, so it can be days rather than
        // minutes behind. A different epoch means somebody re-keyed the channel
        // while this device was closed: ours is stale and theirs is the one
        // that counts. Without this the client would go on sealing under a dead
        // epoch until something else happened to invalidate it.
        if (latest.epoch != state.epoch) {
            forgetKeys(channelId)
            runCatching { ensureChannelKey(channelId) }
            return
        }

        fillGaps(channelId, state, latest)
    }

    /**
     * Hands every epoch this phone holds to the machines that are missing it.
     *
     * This is what lets a second machine read *history* rather than only what
     * is written after it arrives. Re-wrapping the current epoch and nothing
     * else left a machine that signed in today missing every epoch before
     * today - it holds none of them so it cannot repair itself, and with nobody
     * looking on its behalf it minted a fresh epoch and the whole conversation
     * before that moment stayed a padlock for good.
     *
     * The server only ever lists a machine whose *owner* already holds that
     * epoch, so this repairs one person's own second machine and hands nothing
     * to somebody who joined last week.
     *
     * Failures are per epoch and never fatal: a racing rotation or a device
     * revoked between the read and the write fails one wrap, and neither is a
     * reason to stop opening the channel.
     */
    private suspend fun fillGaps(channelId: String, state: ChannelKeyState, latest: ChannelKeys) {
        // Belt and braces for a server older than `gaps`, where this is the
        // only re-wrap that happens.
        state.keys[state.epoch]?.let { key ->
            if (latest.missingRecipients.isNotEmpty()) {
                runCatching { shareKey(channelId, state.epoch, key, latest.missingRecipients) }
            }
        }

        for (gap in latest.gaps) {
            // An epoch we cannot open is not ours to hand out, and the server
            // would refuse it anyway: only a holder may add to an existing one.
            val key = state.keys[gap.epoch] ?: continue
            if (gap.devices.isEmpty()) continue
            runCatching { shareKey(channelId, gap.epoch, key, gap.devices) }
        }
    }

    /** Keys a channel that was just created, so whoever opens it first can read. */
    suspend fun keyChannel(channelId: String) {
        runCatching { ensureChannelKey(channelId) }
    }

    private suspend fun keyForEpoch(channelId: String, epoch: Int): String? {
        channels[channelId]?.keys?.get(epoch)?.let { return it }
        runCatching { ensureChannelKey(channelId) }.getOrNull()?.keys?.get(epoch)?.let { return it }

        // An epoch we hold nothing for, on a channel we have already loaded.
        // Somebody re-keyed it while we were holding the old one - which is
        // exactly what a member who joined after the key was minted does, since
        // waiting for a re-wrap is not a fix - and our cached state is behind.
        //
        // Without re-reading here, the two clients sit on different epochs
        // until one of them is restarted: each renders the other's messages as
        // "no key on this device", and each keeps *sending* under its own stale
        // epoch so the reply is unreadable too. Reloading also moves this
        // client onto the newer epoch, which is what makes the conversation
        // work in both directions again.
        if (!missedEpochs.add("$channelId#$epoch")) return null
        forgetKeys(channelId)

        val fresh = runCatching { ensureChannelKey(channelId) }.getOrNull()?.keys?.get(epoch)
        // It was there after all, so anything else given up on for this channel
        // deserves another go.
        if (fresh != null) missedEpochs.removeAll { it.startsWith("$channelId#") }
        return fresh
    }

    /**
     * Resolves the channel's key, creating and distributing one if the channel
     * has never been keyed. Concurrent callers share one round trip.
     */
    private suspend fun ensureChannelKey(channelId: String): ChannelKeyState {
        channels[channelId]?.let { return it }
        val lock = channelLocks.getOrPut(channelId) { Mutex() }
        return lock.withLock {
            channels[channelId]
                ?: recallKeys(channelId)?.also { channels[channelId] = it }
                ?: loadChannelKey(channelId).also {
                    channels[channelId] = it
                    rememberKeys(channelId, it)
                }
        }
    }

    // --- channel keys at rest ---
    //
    // Without these, the message cache is useless: every cached row is an
    // envelope, and opening one meant a round trip to the key directory first.
    // A conversation would come back off disk instantly and then sit there
    // saying it had no key until the network answered - and say it for good
    // when there was no network to answer.
    //
    // They go in the same Keystore-sealed store the identity does, and not in
    // the cache database, which is deliberately worth nothing on its own.

    private fun keyStorageKey(channelId: String): String? =
        userId?.let { "channelkeys:$it:$channelId" }

    private fun rememberKeys(channelId: String, state: ChannelKeyState) {
        val name = keyStorageKey(channelId) ?: return
        runCatching {
            val keys = JSONObject()
            state.keys.forEach { (epoch, key) -> keys.put(epoch.toString(), key) }
            store.put(name, JSONObject().put("epoch", state.epoch).put("keys", keys).toString())
        }
    }

    private fun recallKeys(channelId: String): ChannelKeyState? {
        val name = keyStorageKey(channelId) ?: return null
        return runCatching {
            val json = JSONObject(store.get(name) ?: return null)
            val keys = json.getJSONObject("keys")
            ChannelKeyState(
                epoch = json.getInt("epoch"),
                keys = keys.keys().asSequence().associate { it.toInt() to keys.getString(it) },
            )
        }.getOrNull()
    }

    /** Drops a channel's keys from memory and from disk, so the next read refetches. */
    private fun forgetKeys(channelId: String) {
        channels.remove(channelId)
        keyStorageKey(channelId)?.let { runCatching { store.remove(it) } }
    }

    /**
     * Drops every channel key this device holds, in memory and at rest.
     *
     * Called when the identity changes under it - [restoreFromBackup]. The keys
     * are still valid, but they are the *subset* the old identity could reach,
     * and both caches would go on serving that subset while the wraps the new
     * identity can open sat unread in the directory.
     */
    private fun forgetAllKeys() {
        channels.clear()
        rekeyed.clear()
        missedEpochs.clear()
        userId?.let { runCatching { store.removeByPrefix("channelkeys:$it:") } }
    }

    private suspend fun loadChannelKey(channelId: String): ChannelKeyState {
        val self = currentIdentity()
        var response = BetweenUsApi.channelKeys(channelId)
        var keys = openKeys(response.keys, self)

        // We hold nothing for the current epoch. Either nobody has keyed the
        // channel yet, or it was keyed before we joined and every holder who
        // could re-wrap it for us is offline. Waiting on them is not a fix, so
        // mint the next epoch and wrap it for everybody - which is exactly what
        // the server lets any member who may send a message do. Earlier epochs
        // are untouched, so history from before we were a member stays closed.
        if (!keys.containsKey(response.epoch) && rekeyed.add(channelId)) {
            createChannelKey(channelId, response.epoch + 1)
            // Re-read rather than trusting our own write: another member may
            // have won the race, and then theirs is the epoch that counts.
            response = BetweenUsApi.channelKeys(channelId)
            keys = openKeys(response.keys, self)
        }

        if (!keys.containsKey(response.epoch)) throw MissingChannelKeyError()

        // Members who joined after the key was minted cannot read anything
        // until a holder re-wraps it for them. We hold it, so we do it.
        if (response.missingRecipients.isNotEmpty()) {
            keys[response.epoch]?.let {
                runCatching { shareKey(channelId, response.epoch, it, response.missingRecipients) }
            }
        }

        return ChannelKeyState(response.epoch, keys)
    }

    /** Opens every entry sealed for us, keyed by epoch. */
    private fun openKeys(
        entries: List<ChannelKeyEntry>,
        self: Crypto.KeyPairJwk,
    ): MutableMap<Int, String> {
        val keys = mutableMapOf<Int, String>()
        for (entry in entries) {
            runCatching {
                keys[entry.epoch] = Crypto.unwrapChannelKey(
                    Crypto.Wrapped(entry.wrappedKey, entry.iv),
                    self.privateKey,
                    entry.senderPublicKey,
                )
            }
            // A key sealed for another of our machines, or for an identity we
            // have since replaced. Both are rows this private half cannot open.
        }
        return keys
    }

    /**
     * Mints an epoch for a channel this device holds no key for - one nobody has
     * keyed, or one that was keyed before we were a member.
     */
    private suspend fun createChannelKey(channelId: String, epoch: Int) {
        val self = currentIdentity()
        val key = Crypto.generateChannelKey()
        val devices = BetweenUsApi.channelDevices(channelId)

        // Our own row may not be in the directory yet on a device that signed in
        // a moment ago. Minting a key we cannot open - or, with an empty
        // directory, publishing nothing at all - leaves the channel unkeyed and
        // the sender told there is no key, so always seal one for ourselves.
        // Being listed under our user id is no longer enough: the directory is a
        // row per machine, and that row may be the other laptop.
        val mine = DeviceIdentity.id()
        val recipients = if (devices.any { it.userId == userId && it.deviceId == mine }) {
            devices
        } else {
            devices + DeviceKey(userId.orEmpty(), mine, self.publicKey)
        }

        try {
            shareKey(channelId, epoch, key, recipients)
        } catch (error: ApiError) {
            // Another member keyed it first: harmless, the caller re-reads and
            // finds theirs. Which code comes back depends on whether they landed
            // on the epoch we wanted or ran past it. Anything else is a real
            // failure and must not be mistaken for "this device has no key".
            val raced = error.code == "EPOCH_OUT_OF_ORDER" || error.code == "EPOCH_NOT_HELD"
            if (!raced) throw error
        }
    }

    private suspend fun shareKey(
        channelId: String,
        epoch: Int,
        key: String,
        recipients: List<DeviceKey>,
    ) {
        if (recipients.isEmpty()) return
        val self = currentIdentity()
        val entries = recipients.mapNotNull { recipient ->
            runCatching {
                val wrapped = Crypto.wrapChannelKey(key, self.privateKey, recipient.publicKey)
                ChannelKeyEntry(
                    recipientUserId = recipient.userId,
                    recipientDeviceId = recipient.deviceId,
                    senderUserId = userId.orEmpty(),
                    senderDeviceId = DeviceIdentity.id(),
                    senderPublicKey = self.publicKey,
                    wrappedKey = wrapped.wrappedKey,
                    iv = wrapped.iv,
                    epoch = epoch,
                )
            }.getOrNull()
            // A directory row with a malformed public key must not stop the
            // channel being keyed for everybody else.
        }
        if (entries.isEmpty()) return
        BetweenUsApi.publishChannelKeys(channelId, epoch, DeviceIdentity.id(), entries)
    }
}

package com.aatech.betweenus.core.crypto

import android.content.Context
import android.content.SharedPreferences
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec
import android.util.Base64

/**
 * Where private key material is kept at rest.
 *
 * The desktop client hands identity keys to its main process, which seals them
 * with the OS keychain. This is the same idea with the parts Android has: an
 * AES key generated *inside* the hardware-backed keystore - it cannot be
 * exported, only used - wrapping the value that then sits in ordinary
 * preferences. A rooted device can read the preferences file and get
 * ciphertext; opening it means asking the keystore, which means being this app
 * on this device.
 *
 * Deliberately no user authentication requirement on the key: a channel key has
 * to be openable to render a message list, and prompting for a fingerprint per
 * message is not a product. Locking the identity behind biometrics is a setting
 * worth having later, not a default that would make the app unusable.
 */
class SecureStore(context: Context) {
    private val prefs: SharedPreferences =
        context.applicationContext.getSharedPreferences("betweenus.secure", Context.MODE_PRIVATE)

    private val keyStore = KeyStore.getInstance(KEYSTORE).apply { load(null) }

    fun get(name: String): String? {
        val stored = prefs.getString(name, null) ?: return null
        val separator = stored.indexOf(':')
        if (separator <= 0) return null
        return runCatching {
            val iv = Base64.decode(stored.substring(0, separator), Base64.NO_WRAP)
            val ciphertext = Base64.decode(stored.substring(separator + 1), Base64.NO_WRAP)
            val cipher = Cipher.getInstance(TRANSFORMATION)
            cipher.init(Cipher.DECRYPT_MODE, secretKey(), GCMParameterSpec(128, iv))
            String(cipher.doFinal(ciphertext))
        }.getOrNull()
        // A null here means the wrapping key is gone - the app was reinstalled,
        // or the user reset their screen lock on an older device. The identity
        // is then recovered from the account backup, which is what it is for.
    }

    fun put(name: String, value: String) {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, secretKey())
        val ciphertext = cipher.doFinal(value.toByteArray())
        val encoded = Base64.encodeToString(cipher.iv, Base64.NO_WRAP) + ":" +
            Base64.encodeToString(ciphertext, Base64.NO_WRAP)
        prefs.edit().putString(name, encoded).apply()
    }

    fun remove(name: String) {
        prefs.edit().remove(name).apply()
    }

    /**
     * Drops every entry whose name starts with [prefix].
     *
     * What "forget the channel keys this identity could reach" is made of. The
     * names carry the user id and channel id, so a prefix is the only way to
     * name a set of them without keeping a second index of what was written.
     */
    fun removeByPrefix(prefix: String) {
        val editor = prefs.edit()
        prefs.all.keys.filter { it.startsWith(prefix) }.forEach { editor.remove(it) }
        editor.apply()
    }

    private fun secretKey(): SecretKey {
        (keyStore.getEntry(KEY_ALIAS, null) as? KeyStore.SecretKeyEntry)?.let { return it.secretKey }

        val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, KEYSTORE)
        generator.init(
            KeyGenParameterSpec.Builder(
                KEY_ALIAS,
                KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,
            )
                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                .build(),
        )
        return generator.generateKey()
    }

    private companion object {
        const val KEYSTORE = "AndroidKeyStore"
        const val KEY_ALIAS = "betweenus.identity.wrap"
        const val TRANSFORMATION = "AES/GCM/NoPadding"
    }
}

package com.aatech.betweenus.core.data

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.MultipartBody
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.net.URLEncoder

data class AuthTokens(val accessToken: String, val refreshToken: String)

data class AuthResponse(val user: PublicUser, val tokens: AuthTokens)

/** The signed-in account. A superset of [UserSummary]; the account's own view. */
data class PublicUser(
    val id: String,
    val email: String,
    val username: String,
    val displayName: String,
    val avatarUrl: String?,
    /** The wide band behind the name on a profile. See [UserSummary.coverUrl]. */
    val coverUrl: String? = null,
    /** The line under the name on a profile card. See `ABOUT_MAX_LENGTH`. */
    val about: String = "",
    /** Who may read this account's last-seen time. Reciprocal at NOBODY. */
    val lastSeenVisibility: LastSeenVisibility = LastSeenVisibility.EVERYONE,
    val role: String,
    /**
     * This account's own disappearing window in seconds, or null for "keep
     * everything".
     *
     * One-sided and personal: history older than the window is not returned to
     * this account on any of its devices, and every other participant's copy is
     * untouched. A server's own window outranks it - that one deletes the row.
     */
    val messageTtlSeconds: Int? = null,
) {
    val label: String get() = displayName.ifBlank { username }
    val summary: UserSummary
        get() = UserSummary(id, username, displayName, avatarUrl, coverUrl, about)

    /** The "@name" line, or null when it would only repeat [label]. */
    val handle: String? get() = summary.handle

    companion object {
        fun from(json: JSONObject) = PublicUser(
            id = json.getString("id"),
            email = json.optString("email"),
            username = json.optString("username"),
            displayName = json.optString("displayName"),
            avatarUrl = json.stringOrNull("avatarUrl"),
            coverUrl = json.stringOrNull("coverUrl"),
            about = json.optString("about"),
            lastSeenVisibility = LastSeenVisibility.of(json.optString("lastSeenVisibility")),
            role = json.optString("role", "USER"),
            messageTtlSeconds = if (json.isNull("messageTtlSeconds")) null
            else json.optInt("messageTtlSeconds").takeIf { it > 0 },
        )
    }
}

data class LinkPreview(
    val url: String,
    val title: String?,
    val description: String?,
    val image: String?,
    val siteName: String?,
    val favicon: String?,
) {
    companion object {
        fun from(json: JSONObject) = LinkPreview(
            url = json.optString("url"),
            title = json.stringOrNull("title"),
            description = json.stringOrNull("description"),
            image = json.stringOrNull("image"),
            siteName = json.stringOrNull("siteName"),
            favicon = json.stringOrNull("favicon"),
        )
    }
}

/** The shape every service answers an error with. See section 24 of CLAUDE.md. */
class ApiError(val code: String, message: String, val status: Int) : Exception(message)

/**
 * The client for the whole REST surface, matching
 * `apps/desktop/src/services/api.ts`: bearer access token, one refresh on a
 * 401, one retry.
 *
 * Every path is resolved against [Endpoint.current] at call time rather than
 * captured, so switching servers does not leave a stale base behind. Every call
 * moves itself to the IO dispatcher, so a caller never has to remember to.
 */
object BetweenUsApi {

    // --- auth ---

    suspend fun login(email: String, password: String): AuthResponse =
        authResponse("/api/v1/auth/login", obj("email" to email, "password" to password))

    suspend fun register(email: String, username: String, password: String): AuthResponse =
        authResponse(
            "/api/v1/auth/register",
            obj("email" to email, "username" to username, "password" to password),
        )

    suspend fun refresh(refreshToken: String): AuthTokens = io {
        tokensOf(public("POST", "/api/v1/auth/refresh", obj("refreshToken" to refreshToken)))
    }

    suspend fun logout(refreshToken: String): Unit = io {
        public("POST", "/api/v1/auth/logout", obj("refreshToken" to refreshToken))
    }

    suspend fun me(): PublicUser = io { PublicUser.from(authed("GET", "/api/v1/auth/me")) }

    suspend fun updateAccount(
        displayName: String?,
        username: String?,
        avatarUrl: String?,
        about: String? = null,
    ): PublicUser =
        io {
            val body = JSONObject()
            displayName?.let { body.put("displayName", it) }
            username?.let { body.put("username", it) }
            avatarUrl?.let { body.put("avatarUrl", it) }
            // An empty string is a value here - "draw no line under my name" -
            // so it is null that means "leave it alone", as it does above.
            about?.let { body.put("about", it) }
            PublicUser.from(authed("PATCH", "/api/v1/auth/account", body))
        }

    /**
     * Who may see when this account was last here.
     *
     * Its own call rather than a field on [updateAccount] because it is a
     * switch and not a field being edited: it is saved the moment it is
     * pressed, and a privacy switch that waits for a Save button is one people
     * believe they have set when they have not.
     */
    suspend fun setLastSeenVisibility(visibility: LastSeenVisibility): PublicUser = io {
        val body = JSONObject().put("lastSeenVisibility", visibility.wire)
        PublicUser.from(authed("PATCH", "/api/v1/auth/account", body))
    }

    /**
     * Sets this account's own disappearing window, or clears it with null.
     *
     * Its own call for the same reason [setAvatar] is: null means "switch it
     * off" here and "leave it alone" in [updateAccount], and one function
     * cannot mean both.
     */
    suspend fun setMessageWindow(seconds: Int?): PublicUser = io {
        val body = JSONObject().put("messageTtlSeconds", seconds ?: JSONObject.NULL)
        PublicUser.from(authed("PATCH", "/api/v1/auth/account", body))
    }

    /**
     * Sets or clears this account's picture.
     *
     * Separate from [updateAccount] because null means two different things
     * there: that call leaves out what it is not changing, so it can never send
     * "no avatar". This one always sends the field, and null clears it.
     */
    suspend fun setAvatar(url: String?): PublicUser = io {
        val body = JSONObject().put("avatarUrl", url ?: JSONObject.NULL)
        PublicUser.from(authed("PATCH", "/api/v1/auth/account", body))
    }

    /** Sets or clears the wide band behind the name. Null clears, as in [setAvatar]. */
    suspend fun setCover(url: String?): PublicUser = io {
        val body = JSONObject().put("coverUrl", url ?: JSONObject.NULL)
        PublicUser.from(authed("PATCH", "/api/v1/auth/account", body))
    }

    /** Signs every other session out; this one keeps its tokens. */
    suspend fun changePassword(currentPassword: String, newPassword: String): Unit = io {
        authed(
            "POST",
            "/api/v1/auth/account/password",
            obj("currentPassword" to currentPassword, "newPassword" to newPassword),
        )
    }

    /**
     * Whether a username can be registered.
     *
     * Public, because the form that asks is the one filled in before there is
     * an account. Cheap on the server - a Bloom filter answers the common case
     * without touching the database - so the sign-up form asks while somebody
     * is typing rather than when they press the button.
     */
    suspend fun usernameAvailable(username: String): UsernameAvailability = io {
        UsernameAvailability.from(
            public("GET", "/api/v1/auth/username-available?username=${enc(username)}", null),
        )
    }

    /**
     * What can be done about a forgotten password on this deployment.
     *
     * Three answers, and only one of them is about the account: a link was sent
     * (which is also what an account that does not exist gets), an
     * administrator has already authorised a reset and here is the token, or
     * this deployment has no mail server at all.
     */
    suspend fun forgotPassword(identifier: String): ForgotPasswordAnswer = io {
        ForgotPasswordAnswer.from(
            public("POST", "/api/v1/auth/forgot-password", obj("identifier" to identifier)),
        )
    }

    /** Spends a reset token. The one path that sets a password without the old one. */
    suspend fun resetPassword(token: String, newPassword: String): AuthResponse =
        authResponse(
            "/api/v1/auth/reset-password",
            obj("token" to token, "newPassword" to newPassword),
        )

    // --- servers ---

    suspend fun servers(): List<ServerWithRole> = io {
        authedArray("GET", "/api/v1/servers").map { ServerWithRole.from(it) }
    }

    suspend fun createServer(name: String): ServerWithRole = io {
        ServerWithRole.from(authed("POST", "/api/v1/servers", obj("name" to name)))
    }

    /** An invite code, not a slug: a slug is a name and no longer opens a door. */
    suspend fun joinServer(code: String): ServerWithRole = io {
        ServerWithRole.from(authed("POST", "/api/v1/servers/join", obj("code" to code)))
    }

    /** Whose server a code leads to, and how big it is, before joining it. */
    suspend fun invitePreview(code: String): InvitePreview = io {
        InvitePreview.from(authed("GET", "/api/v1/servers/invites/${enc(code)}"))
    }

    suspend fun serverInvites(serverId: String): List<ServerInvite> = io {
        authedArray("GET", "/api/v1/servers/$serverId/invites").map { ServerInvite.from(it) }
    }

    /** Null hours never expires; null uses is unlimited. */
    suspend fun createServerInvite(
        serverId: String,
        expiresInHours: Int?,
        maxUses: Int?,
    ): ServerInvite = io {
        val body = JSONObject()
        expiresInHours?.let { body.put("expiresInHours", it) }
        maxUses?.let { body.put("maxUses", it) }
        ServerInvite.from(authed("POST", "/api/v1/servers/$serverId/invites", body))
    }

    suspend fun revokeServerInvite(serverId: String, code: String): ServerInvite = io {
        ServerInvite.from(authed("DELETE", "/api/v1/servers/$serverId/invites/${enc(code)}"))
    }

    suspend fun updateServer(serverId: String, name: String?, iconUrl: String?): ServerWithRole = io {
        val body = JSONObject()
        name?.let { body.put("name", it) }
        iconUrl?.let { body.put("iconUrl", it) }
        ServerWithRole.from(authed("PATCH", "/api/v1/servers/$serverId", body))
    }

    /** Sets a server's disappearing window, or clears it with null. MANAGE_SERVER. */
    suspend fun setServerMessageWindow(serverId: String, seconds: Int?): ServerWithRole = io {
        val body = JSONObject().put("messageTtlSeconds", seconds ?: JSONObject.NULL)
        ServerWithRole.from(authed("PATCH", "/api/v1/servers/$serverId", body))
    }

    /** Sets or clears a server's icon. Null clears it, as [setAvatar] does. */
    suspend fun setServerIcon(serverId: String, url: String?): ServerWithRole = io {
        val body = JSONObject().put("iconUrl", url ?: JSONObject.NULL)
        ServerWithRole.from(authed("PATCH", "/api/v1/servers/$serverId", body))
    }

    suspend fun deleteServer(serverId: String): Unit = io {
        authed("DELETE", "/api/v1/servers/$serverId")
    }

    suspend fun leaveServer(serverId: String): Unit = io {
        authed("POST", "/api/v1/servers/$serverId/leave")
    }

    suspend fun members(serverId: String): List<ServerMember> = io {
        authedArray("GET", "/api/v1/servers/$serverId/members").map { ServerMember.from(it) }
    }

    /**
     * [shareHistory] is whether they arrive able to read what was said before
     * they got here. Off is the default and is what the encryption does on its
     * own: they hold no earlier channel key and nothing offers them one. On, the
     * key directory starts listing every epoch as missing for their devices and
     * a machine that already holds them seals them across. See E2EE.md.
     */
    suspend fun addMember(
        serverId: String,
        username: String,
        shareHistory: Boolean = false,
    ): ServerMember = io {
        ServerMember.from(
            authed(
                "POST",
                "/api/v1/servers/$serverId/members",
                obj("username" to username, "shareHistory" to shareHistory),
            ),
        )
    }

    suspend fun removeMember(serverId: String, userId: String): Unit = io {
        authed("DELETE", "/api/v1/servers/$serverId/members/$userId")
    }

    suspend fun updateMember(
        serverId: String,
        userId: String,
        role: ServerRole? = null,
        granted: List<String>? = null,
        denied: List<String>? = null,
        roleIds: List<String>? = null,
    ): ServerMember = io {
        val body = JSONObject()
        role?.let { body.put("role", it.name) }
        granted?.let { body.put("grantedPermissions", jsonArrayOf(it)) }
        denied?.let { body.put("deniedPermissions", jsonArrayOf(it)) }
        // Replaces the whole set rather than adding to it, which is what the
        // server does with it: an empty list takes every custom role away.
        roleIds?.let { body.put("roleIds", jsonArrayOf(it)) }
        ServerMember.from(authed("PATCH", "/api/v1/servers/$serverId/members/$userId", body))
    }

    // --- custom roles ---

    suspend fun serverRoles(serverId: String): List<ServerCustomRole> = io {
        authedArray("GET", "/api/v1/servers/$serverId/roles").map { ServerCustomRole.from(it) }
    }

    suspend fun createServerRole(
        serverId: String,
        name: String,
        colour: String?,
        permissions: List<String>,
    ): ServerCustomRole = io {
        val body = JSONObject().put("name", name).put("permissions", jsonArrayOf(permissions))
        colour?.let { body.put("colour", it) }
        ServerCustomRole.from(authed("POST", "/api/v1/servers/$serverId/roles", body))
    }

    /** Only what is passed is changed; anything null is left as it was. */
    suspend fun updateServerRole(
        serverId: String,
        roleId: String,
        name: String? = null,
        colour: String? = null,
        permissions: List<String>? = null,
        rank: Int? = null,
    ): ServerCustomRole = io {
        val body = JSONObject()
        name?.let { body.put("name", it) }
        colour?.let { body.put("colour", it) }
        permissions?.let { body.put("permissions", jsonArrayOf(it)) }
        rank?.let { body.put("rank", it) }
        ServerCustomRole.from(authed("PATCH", "/api/v1/servers/$serverId/roles/$roleId", body))
    }

    suspend fun deleteServerRole(serverId: String, roleId: String): Unit = io {
        authed("DELETE", "/api/v1/servers/$serverId/roles/$roleId")
    }

    // --- webhooks ---
    //
    // A URL an outside system posts into a channel with. Every call here needs
    // MANAGE_WEBHOOK on the channel's server; the URL itself comes back exactly
    // twice in a webhook's life - at creation and at rotation - because the
    // server keeps only a hash of the token.

    suspend fun webhooks(channelId: String): List<Webhook> = io {
        authedArray("GET", "/api/v1/webhooks?channelId=${enc(channelId)}").map { Webhook.from(it) }
    }

    suspend fun createWebhook(channelId: String, name: String): WebhookWithToken = io {
        val body = JSONObject().put("channelId", channelId).put("name", name)
        WebhookWithToken.from(authed("POST", "/api/v1/webhooks", body))
    }

    /** A new URL, invalidating the old one. The way back from a leak, and from a URL nobody kept. */
    suspend fun rotateWebhook(webhookId: String): WebhookWithToken = io {
        WebhookWithToken.from(authed("POST", "/api/v1/webhooks/$webhookId/rotate", JSONObject()))
    }

    suspend fun deleteWebhook(webhookId: String): Unit = io {
        authed("DELETE", "/api/v1/webhooks/$webhookId")
    }

    // --- channels ---

    suspend fun channels(serverId: String): List<Channel> = io {
        authedArray("GET", "/api/v1/channels?serverId=${enc(serverId)}").map { Channel.from(it) }
    }

    suspend fun createChannel(
        serverId: String,
        name: String,
        type: ChannelType,
        isPrivate: Boolean,
        memberIds: List<String>,
    ): Channel = io {
        val body = JSONObject()
            .put("serverId", serverId)
            .put("name", name)
            .put("type", type.name)
            .put("isPrivate", isPrivate)
        if (memberIds.isNotEmpty()) body.put("memberIds", jsonArrayOf(memberIds))
        Channel.from(authed("POST", "/api/v1/channels", body))
    }

    suspend fun updateChannel(channelId: String, name: String?, topic: String?): Channel = io {
        val body = JSONObject()
        name?.let { body.put("name", it) }
        topic?.let { body.put("topic", it) }
        Channel.from(authed("PATCH", "/api/v1/channels/$channelId", body))
    }

    suspend fun deleteChannel(channelId: String): Unit = io {
        authed("DELETE", "/api/v1/channels/$channelId")
    }

    suspend fun channelMembers(channelId: String): List<ChannelMember> = io {
        authedArray("GET", "/api/v1/channels/$channelId/members").map { ChannelMember.from(it) }
    }

    suspend fun setChannelMembers(channelId: String, userIds: List<String>): List<ChannelMember> =
        io {
            authedArray(
                "PUT",
                "/api/v1/channels/$channelId/members",
                JSONObject().put("userIds", jsonArrayOf(userIds)),
            ).map { ChannelMember.from(it) }
        }

    // --- messages ---

    suspend fun messages(channelId: String, before: String? = null): Page<Message> = io {
        val path = "/api/v1/messages?channelId=${enc(channelId)}" +
            (before?.let { "&before=${enc(it)}" } ?: "")
        val json = authed("GET", path)
        Page(
            items = json.optJSONArray("items")?.map { Message.from(it) }.orEmpty(),
            nextCursor = json.stringOrNull("nextCursor"),
        )
    }

    /**
     * `content` is the sealed envelope; this client never sends a plaintext body.
     *
     * `attachmentKeys` names the blobs that envelope carries. The server cannot
     * read the manifest inside it, so this is the only way an upload is ever
     * tied to a message - and the only way a deleted message takes its files.
     */
    suspend fun sendMessage(
        channelId: String,
        content: String,
        attachmentKeys: List<String> = emptyList(),
        viewOnce: Boolean = false,
    ): Message = io {
        Message.from(
            authed(
                "POST",
                "/api/v1/messages",
                obj(
                    "channelId" to channelId,
                    "content" to content,
                    "attachmentKeys" to JSONArray(attachmentKeys),
                    "viewOnce" to viewOnce,
                ),
            ),
        )
    }

    suspend fun editMessage(messageId: String, content: String): Message = io {
