}

package com.aatech.betweenus.core.data

import android.content.Context
import android.net.ConnectivityManager
import android.net.Network
import android.net.NetworkCapabilities
import android.net.NetworkRequest
import java.util.concurrent.CopyOnWriteArraySet

/**
 * When this phone has a usable connection again.
 *
 * Every socket already reconnects on its own, with a backoff that doubles to
 * thirty seconds. That is the right shape for a server that is down and the
 * wrong one for a phone: the connection comes back the instant a lift door
 * opens or wifi is reached, and the app then sat there for up to half a minute
 * waiting out a timer that was measuring a problem which no longer existed.
 *
 * The backoff is still what handles a server that is refusing connections. This
 * is the other half - the moment the *phone* changed - and it makes the wait
 * nothing rather than shortening it.
 *
 * `onAvailable` fires per network, and a handover from mobile data to wifi
 * fires it again while the old one is still up, so a listener here has to be
 * idempotent. Every one of them is: opening a socket that is already open is a
 * no-op, and `NET_CAPABILITY_VALIDATED` is what separates "attached to a wifi
 * access point" from "that access point reaches the internet" - a captive
 * portal is the case where the difference is the whole story.
 */
object NetworkWatch {
    private val listeners = CopyOnWriteArraySet<() -> Unit>()

    @Volatile
    private var registered = false

    /** True once the system has told us about a validated network. */
    @Volatile
    var online: Boolean = true
        private set

    fun init(context: Context) {
        if (registered) return
        val manager = context.applicationContext.getSystemService(ConnectivityManager::class.java)
            ?: return

        val request = NetworkRequest.Builder()
            .addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
            .addCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)
            .build()

        runCatching {
            manager.registerNetworkCallback(
                request,
                object : ConnectivityManager.NetworkCallback() {
                    override fun onAvailable(network: Network) {
                        online = true
                        listeners.forEach { runCatching { it() } }
                    }

                    override fun onLost(network: Network) {
                        // Not "offline" on its own - a handover loses the old
                        // network while the new one is already carrying
                        // traffic. What this is for is not pretending the app
                        // is fine when the last network really has gone, and
                        // the sockets notice that themselves within a ping.
                        online = manager.activeNetwork != null
                    }
                },
            )
            registered = true
        }
    }

    /** Calls back whenever a usable network arrives. Returns the unsubscribe. */
    fun onAvailable(listener: () -> Unit): () -> Unit {
        listeners.add(listener)
        return { listeners.remove(listener) }
    }
}

package com.aatech.betweenus.core.data

import com.aatech.betweenus.core.crypto.DeviceIdentity

/**
 * This installation's push registration, as far as the session is concerned.
 *
 * The token itself comes from Firebase, which lives in `:app` - `:core` has no
 * business depending on Google Play services to make an HTTP call. So the token
 * arrives through [provider], set once at startup by whoever does own Firebase,
 * and this object is what the *session* calls: registered when a session
 * begins, and unregistered while there is still an access token to unregister
 * with. A row left behind pushes one account's messages at whoever signs in on
 * the phone next, which is the failure this ordering exists to prevent.
 *
 * With no provider - a build with no `google-services.json` - every call here
 * is a no-op and nothing else changes.
 */
object PushTokens {
    /** Set by `:app`. Returns the FCM registration token, or null if it cannot. */
    @Volatile
    var provider: (suspend () -> String?)? = null

    /** What the server should call this phone in a list of devices. */
    @Volatile
    var label: String? = null

    /** The client build, so a push a version cannot render can be skipped. */
    @Volatile
    var appVersion: String? = null

    /**
     * Called on sign-in, on restore, and on every rotation. Failure is not
     * worth surfacing: it means this phone gets nothing while it is closed,
     * which the next successful registration fixes on its own.
     */
    suspend fun register() {
        val token = runCatching { provider?.invoke() }.getOrNull() ?: return
        runCatching {
            BetweenUsApi.registerDevice(
                token = token,
                deviceId = DeviceIdentity.id(),
                label = label,
                appVersion = appVersion,
            )
        }
    }

    /** Called before the tokens are discarded, which is the only moment it works. */
    suspend fun unregister() {
        if (provider == null) return
        runCatching { BetweenUsApi.unregisterDevice(DeviceIdentity.id()) }
    }
}

package com.aatech.betweenus.core.data

import android.content.Context
import android.content.SharedPreferences
import com.aatech.betweenus.core.crypto.SecureStore
import com.aatech.betweenus.core.crypto.BackupSecret
import com.aatech.betweenus.core.crypto.E2ee
import com.aatech.betweenus.core.store.Cache
import com.aatech.betweenus.core.store.Conversation
import com.aatech.betweenus.core.store.Presence
import com.aatech.betweenus.core.store.Statuses
import com.aatech.betweenus.core.store.Workspace
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch
import kotlinx.coroutines.withTimeoutOrNull
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlin.math.min

/**
 * Whether a failed token exchange means this session is over.
 *
 * Exactly one thing does: the server refusing the credential. Everything else -
 * a host that will not resolve, a gateway that has not finished starting, a
 * phone in a tunnel, a coroutine cancelled because an activity was recreated -
 * says nothing about whether the refresh token is still good, and treating it
 * as an ending is what signed people out at random while holding a token valid
 * for another month.
 *
 * Pure, and separate from [Session], so the rule can be checked without an
 * Android device to run it on.
 */
fun endsSession(error: Throwable): Boolean = error is ApiError && error.status == 401

/** What the app shows: the splash, the sign-in form, or the app itself. */
sealed interface AuthPhase {
    /**
     * Cold start, with a refresh token to try. Nothing is drawn but the mark.
     *
     * [problem] is set once a restore has failed for a reason that is not the
     * token being refused - an unreachable server, a gateway still starting.
     * The session is not over in that case and the token is kept, so the splash
     * says what is wrong and keeps trying rather than dropping somebody onto a
     * sign-in form for a credential nobody rejected.
     */
    data class Restoring(val problem: String? = null) : AuthPhase

    /** No session. [reason] is set when the last attempt failed for a reason
     *  worth repeating - a server that was unreachable, not a wrong password. */
    data class SignedOut(val reason: String? = null) : AuthPhase

    data class SignedIn(val user: PublicUser) : AuthPhase
}

/**
 * The one session this process has.
 *
 * The access token lives in memory only - it is short-lived and a process
 * death is a refresh away. The refresh token is what survives a restart, and
 * the email is remembered so signing in again does not mean typing it again.
 * A password is never stored anywhere.
 *
 * The refresh token is sealed by the Keystore rather than written in the
 * clear: preferences are private to the app and readable on a rooted device,
 * and a refresh token is a sign-in that lasts. It is keyed per deployment, so
 * a phone that has used two servers holds a token for each and switching
 * deployments cannot present one server's token to another. The email is not
 * a secret and stays where it was.
 *
 * A token written by an older build is moved on the first launch that finds
 * it, and the plaintext removed - which is the only reason [REFRESH_KEY] still
 * exists.
 */
object Session {
    private const val REFRESH_KEY = "refreshToken"
    private const val EMAIL_KEY = "lastEmail"

    private lateinit var prefs: SharedPreferences
    private lateinit var secure: SecureStore
    private val refreshLock = Mutex()

    @Volatile
    var accessToken: String? = null
        private set

    private val _state = MutableStateFlow<AuthPhase>(AuthPhase.SignedOut())
    val state: StateFlow<AuthPhase> = _state.asStateFlow()

    fun init(context: Context) {
        prefs = context.applicationContext.getSharedPreferences("betweenus.session", Context.MODE_PRIVATE)
        secure = SecureStore(context)

        // A build before this one wrote the token in the clear. Move it once
        // and delete it, rather than leaving a readable copy behind for the
        // life of the install.
        prefs.getString(REFRESH_KEY, null)?.let { legacy ->
            secure.put(secureKey(), legacy)
            prefs.edit().remove(REFRESH_KEY).apply()
        }

        // A stored refresh token means there is something to restore, and the
        // splash should stay up until it is known whether it still works.
        if (refreshToken != null) _state.value = AuthPhase.Restoring()
    }

    /**
     * One entry per deployment.
     *
     * A phone that has signed into two servers holds a token for each, and
     * switching between them cannot present one server's token to the other -
     * which the old single key did, once, per switch.
     */
    private fun secureKey(): String = "refreshToken:" + Endpoint.current()

    /** Prefills the sign-in form. Empty on a device nobody has signed in on. */
    fun rememberedEmail(): String = prefs.getString(EMAIL_KEY, "").orEmpty()

    private var refreshToken: String?
        get() = secure.get(secureKey())
        set(value) {
            if (value == null) secure.remove(secureKey()) else secure.put(secureKey(), value)
        }

    /**
     * A sign-in or a registration that worked.
     *
     * The password is passed through rather than stored: it is the secret that
     * opens this account's identity backup, so a sign-in is the one moment
     * where a new device can recover its keys without asking for anything. It
     * is used here and dropped.
     */
    fun start(response: AuthResponse, email: String? = null, password: String? = null) {
        accessToken = response.tokens.accessToken
        refreshToken = response.tokens.refreshToken
        if (email != null) prefs.edit().putString(EMAIL_KEY, email).apply()
        _state.value = AuthPhase.SignedIn(response.user)
        begin(response.user, password?.let { BackupSecret.password(it) })
    }

    /**
     * Everything a live session needs running: both sockets, and the identity
     * key that makes messages readable.
     *
     * The identity is allowed to fail without ending the session. A locked one
     * puts [E2ee.status] into `Locked` and the app asks for the secret; an
     * offline one is retried the next time a channel needs a key. Neither is a
     * reason to throw somebody back to a login form they have just filled in.
     */
    private fun begin(user: PublicUser, secret: BackupSecret?) {
        val token = accessToken ?: return
        // Before either store starts reading from it: a cache belonging to
        // another account has to be gone, not merely about to be.
        Cache.claim(user.id)
        ChatSocket.connect(token)
        PresenceSocket.connect(token)
        Presence.start()
        Conversation.start()
        Workspace.start()
        Statuses.start()
        scope.launch { runCatching { E2ee.initIdentity(user.id, secret) } }
        // The push registration belongs to the account, not to the app: it is
        // made here on every sign-in and every restore, so a token that rotated
        // while the app was closed is put back under the right user.
        scope.launch { PushTokens.register() }
    }

    /**
     * Cold start.
     *
     * A missing token is simply a signed-out app, and a token the server
     * *rejects* is a session that ended while the app was closed. Nothing else
     * is: an unreachable server, a gateway that has not finished starting, a
     * phone that woke up in a tunnel - none of them say anything about whether
     * this session is still good, and signing out over one is what put somebody
     * back on a login form holding a refresh token that was valid the whole
     * time.
     *
     * So a failure that is not a refusal keeps the token, stays on the splash
     * with the reason on it, and tries again - on a backoff, and immediately
     * whenever the phone gets a network back.
     *
     * Single-flight, and owned by [scope] rather than by whoever asked. A
     * restore driven from an activity's scope died with the activity - a
     * rotation, a themed recreate, a process the system paused - and the
     * `CancellationException` that came out of it was being read as a failed
     * sign-in. That is the whole of "Job was cancelled" on a login form.
     */
    suspend fun restore() {
        current().join()
    }

    /** The same restore, for a caller with no coroutine to wait in. */
    fun restoreAsync() {
        current()
    }

    @Synchronized
    private fun current(): Job =
        restoring?.takeIf { it.isActive } ?: scope.launch { runRestore() }.also { restoring = it }

    /** The restore in flight, so two callers do not spend the token twice. */
    @Volatile
    private var restoring: Job? = null

    private suspend fun runRestore() {
        var attempt = 0
        while (true) {
            if (refreshToken == null) {
                _state.value = AuthPhase.SignedOut()
                return
            }
            if (_state.value !is AuthPhase.SignedIn) _state.value = AuthPhase.Restoring()

            val problem = attemptRestore() ?: return

            // Still restoring, still holding the token, now saying why.
            _state.value = AuthPhase.Restoring(problem)
            attempt += 1
            waitBeforeRetry(attempt)
        }
    }

    /**
     * One go. Returns null when the session is settled either way - restored,
     * or genuinely signed out - and the reason to show when it is worth trying
     * again.
     */
    private suspend fun attemptRestore(): String? {
        val token = refreshAccessToken()
        if (token == null) {
            // A refusal has already cleared the token and moved the state on;
            // anything else left both alone and is worth retrying.
            if (refreshToken == null) return null
            return lastRefreshProblem ?: "Could not reach ${Http.hostOf(Endpoint.current())}"
        }
        return try {
            val user = BetweenUsApi.me()
            _state.value = AuthPhase.SignedIn(user)
            begin(user, secret = null)
            null
        } catch (cancelled: CancellationException) {
            throw cancelled
        } catch (error: Exception) {
            // The same rule as the refresh: only a refusal ends the session.
            if (endsSession(error)) {
                refreshToken = null
                accessToken = null
                _state.value = AuthPhase.SignedOut()
                null
            } else {
                messageOf(error)
            }
        }
    }

    /**
     * Backoff, cut short by a network coming back.
     *
     * The wait is for a server that is down, where hammering it is exactly
     * wrong. A phone that has just found wifi is the other case entirely, and
     * making it wait out a timer measuring a problem it no longer has is how a
     * splash screen sits there for half a minute after the lift doors open.
     */
    private suspend fun waitBeforeRetry(attempt: Int) {
        val delayMs = min(2_000L shl min(attempt - 1, 4), 30_000L)
        val woken = CompletableDeferred<Unit>()
        val stop = NetworkWatch.onAvailable { woken.complete(Unit) }
        try {
            withTimeoutOrNull(delayMs) { woken.await() }
        } finally {
            stop()
        }
    }

    /**
     * The button on the splash: try the whole thing again now.
     *
     * The retry loop is already waiting on a backoff, so this is only ever
     * shortening a wait - the job is replaced rather than raced, because two
     * restores would each spend the stored refresh token and one would lose.
     */
    @Synchronized
    fun retryRestore() {
        if (_state.value !is AuthPhase.Restoring) return
        restoring?.cancel()
        restoring = scope.launch { runRestore() }
    }

    /** Somebody would rather sign in again than watch a splash keep trying. */
    @Synchronized
    fun abandonRestore() {
        if (_state.value !is AuthPhase.Restoring) return
        restoring?.cancel()
        restoring = null
        _state.value = AuthPhase.SignedOut()
    }

    /** Why the last refresh failed, when it failed for something retryable. */
    @Volatile
    private var lastRefreshProblem: String? = null

    /**
     * Rotating refresh, single-flight: two calls racing would each spend the
     * stored token and one of them would lose the session.
     *
     * Only the server *rejecting* the token ends the session. A network
     * failure, a 502, or a backend that has not finished starting says nothing
     * about whether this session is still good, and throwing the token away
     * there signs people out permanently the first time the phone opens the app
     * before the server is up.
     */
    suspend fun refreshAccessToken(): String? = refreshLock.withLock {
        val stored = refreshToken ?: run {
            clear()
            return@withLock null
        }
        try {
            val tokens = BetweenUsApi.refresh(stored)
            refreshToken = tokens.refreshToken
            accessToken = tokens.accessToken
            // Both sockets carry the access token in their URL, so a rotation
            // is a reconnect. They are idempotent when already open.
            ChatSocket.connect(tokens.accessToken)
            PresenceSocket.connect(tokens.accessToken)
            lastRefreshProblem = null
            tokens.accessToken
        } catch (cancelled: CancellationException) {
            // A cancelled coroutine is not a refused credential. It used to be
            // caught below and turned into "Job was cancelled" on a sign-in
            // form - a session thrown away because an activity was recreated.
            throw cancelled
        } catch (error: Exception) {
            if (!endsSession(error)) {
                // The credential was never refused - the network was - so the
                // stored token stays and the next request refreshes again.
                // Nothing about the session ends here, whatever phase it is in:
                // ending it over a lift, a handover or a gateway restart is
                // what signed people out at random, and it did so on the one
                // path that had no guard: a cold start.
                lastRefreshProblem = messageOf(error)
                return@withLock null
            }
            refreshToken = null
            accessToken = null
            lastRefreshProblem = null
            _state.value = AuthPhase.SignedOut()
            null
        }
    }

    /**
     * Fire-and-forget refresh, for a caller with no coroutine of its own.
     *
     * A socket whose token was rejected is the only one that needs this: it is
     * the one thing holding an access token that nothing else will notice has
     * expired.
     */
    fun renewAccessToken() {
        scope.launch { runCatching { refreshAccessToken() } }
    }

    /**
     * Ends the session on the server while it can still be reached, then
     * locally regardless - a sign-out that fails because the network is down
     * still has to sign this device out.
     */
    suspend fun signOut() {
        val stored = refreshToken
        // Before the tokens go, because unregistering needs one. A row left
        // behind delivers this account's messages to whoever signs in next.
        PushTokens.unregister()
        if (stored != null) runCatching { BetweenUsApi.logout(stored) }
        clear()
        // Only a deliberate sign-out empties the cache. A session that expired
        // on its own is coming back, and should come back instantly.
        Cache.clear()
    }

    /**
     * The account changed something about itself.
     *
     * A display name or an avatar is drawn from `AuthPhase.SignedIn`, which was
     * written once at sign-in and never again - so changing either updated the
     * server and nothing on screen until the next launch. Ignored while signed
     * out, where there is nobody to update.
     */
    fun updateUser(user: PublicUser) {
        if (_state.value !is AuthPhase.SignedIn) return
        _state.value = AuthPhase.SignedIn(user)
    }

    /**
     * The same profile, changed on another of this account's devices, arriving
     * over the socket. Only the three public fields move - the address and the
     * platform role are not in the event and are not what changed.
     */
    fun applyProfile(summary: UserSummary) {
        val signedIn = _state.value as? AuthPhase.SignedIn ?: return
        if (signedIn.user.id != summary.id) return
        _state.value = AuthPhase.SignedIn(
            signedIn.user.copy(
                username = summary.username,
                displayName = summary.displayName,
                avatarUrl = summary.avatarUrl,
            ),
        )
    }

    /**
     * A sign-in that failed with no form on screen to put the error on.
     *
     * The provider hand-off comes back through an intent rather than through a
     * button, so there is no view model holding the attempt when it goes wrong.
     * Ignored while signed in: a stale callback must not throw somebody out of
     * a session they already have.
     */
    fun reportSignInFailure(message: String) {
        if (_state.value is AuthPhase.SignedIn) return
        _state.value = AuthPhase.SignedOut(message)
    }

    private fun clear() {
        accessToken = null
        refreshToken = null
        ChatSocket.forget()
        ChatSocket.disconnect()
        PresenceSocket.disconnect()
        CallSocket.disconnect()
        RemoteSocket.disconnect()
        E2ee.reset()
        Workspace.stop()
        Statuses.stop()
        Conversation.stop()
        Presence.stop()
        _state.value = AuthPhase.SignedOut()
    }

    /** Outlives any one screen: sockets and key setup belong to the session. */
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    fun messageOf(error: Throwable): String =
        error.message?.takeIf { it.isNotBlank() } ?: "Something went wrong"
}

package com.aatech.betweenus.core.data

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import org.json.JSONArray
import org.json.JSONObject
import java.net.URLEncoder
import java.util.concurrent.CopyOnWriteArraySet
import kotlin.math.min
import kotlin.math.pow

/**
 * A reconnecting JSON WebSocket.
 *
 * All four of BetweenUs's sockets - chat, presence, call signalling and remote -
 * are the same thing with different vocabularies: a token in the query string
 * (a WebSocket cannot set an Authorization header), JSON objects with a `type`,
 * and a close code of 4401 meaning the token was rejected and reconnecting
 * would only loop.
 *
 * The queue matters more here than on the desktop. A phone loses its connection
 * constantly - a lift, a train, a screen that went off - and a `send` that
 * silently did nothing while reconnecting is a message that vanishes.
 */
open class JsonSocket(private val path: String) {
    private var socket: WebSocket? = null
    private var token: String? = null
    private var attempt = 0
    private var closedByUs = false
    /** When this socket was last up, which is what the deadline measures from. */
    private var downSince: Long? = null
    private val listeners = CopyOnWriteArraySet<(JSONObject) -> Unit>()
    private val connectionListeners = CopyOnWriteArraySet<(Boolean) -> Unit>()

    /** Sent the moment the socket opens, in order. */
    private val pending = ArrayDeque<String>()

    @Volatile
    var connected: Boolean = false
        private set

    fun connect(token: String) {
        this.token = token
        closedByUs = false
        if (downSince == null && !connected) downSince = System.currentTimeMillis()
        open()
    }

    /**
     * Try now: the banner's button, and the app coming back to the screen.
     *
     * Whatever the backoff had climbed to belonged to a network that has been
     * replaced, so the ladder starts again at the bottom.
     *
     * A socket that is not *connected* is dropped and opened again, and that
     * part is the fix rather than an optimisation. A phone in the background is
     * one Android may stop from running anything at all: the reconnect thread
     * is held in doze, the keepalive ping never fires, and the connection dies
     * with neither end told. What comes back to the foreground is then either a
     * backoff frozen since last night or a `WebSocket` object that is a corpse
     * nothing has noticed - and the old test, `if (socket == null)`, did
     * nothing in both cases while having just announced "Reconnecting…". That
     * is a banner that stays up until the app is killed, and a button that
     * makes it worse.
     *
     * A socket that really is connected is left alone. If it turns out not to
     * be, the ping resumes with the app and finds out inside thirty seconds.
     */
    @Synchronized
    fun retry() {
        if (closedByUs || token == null) return
        attempt = 0
        if (connected) return
        // Cancelled rather than closed: a close is a handshake, and there may
        // be nothing at the other end left to complete it.
        socket?.cancel()
        socket = null
        downSince = System.currentTimeMillis()
        log("retry")
        Connectivity.report(path, Connectivity.State.RECONNECTING)
        open()
    }

    /**
     * Never the token, never a message body - see section 23 of CLAUDE.md. Just
     * enough to tell a socket that is refusing to open from one that opened and
     * was never spoken to, which is a distinction that cost a day.
     */
    private fun log(what: String) = android.util.Log.i("betweenus.socket", "$path $what")

    @Synchronized
    private fun open() {
        val token = this.token ?: return
        if (socket != null) return

        // The device goes with the token. `call-service` hangs a peer id on it,
        // so a peer keeps its name across a reconnect instead of arriving as a
        // stranger and making everybody rebuild their connection to it. Every
        // socket carries it; the ones that have no use for it ignore it.
        val url = buildString {
            append(Endpoint.webSocket())
            append(path)
            append("?token=")
            append(URLEncoder.encode(token, "UTF-8"))
            deviceId()?.let {
                append("&device=")
                append(URLEncoder.encode(it, "UTF-8"))
            }
        }
        socket = Http.client.newWebSocket(
            Request.Builder().url(url).build(),
            object : WebSocketListener() {
                override fun onOpen(webSocket: WebSocket, response: Response) {
                    log("open")
                    attempt = 0
                    downSince = null
                    connected = true
                    Connectivity.report(path, Connectivity.State.ONLINE)
                    onConnected()
                    synchronized(this@JsonSocket) {
                        while (pending.isNotEmpty()) webSocket.send(pending.removeFirst())
                    }
                    connectionListeners.forEach { it(true) }
                }

                override fun onMessage(webSocket: WebSocket, text: String) {
                    val event = runCatching { JSONObject(text) }.getOrNull() ?: return
                    listeners.forEach { it(event) }
                }

                override fun onClosed(webSocket: WebSocket, code: Int, reason: String) {
                    log("closed code=$code reason=$reason")
                    drop(code)
                }

                override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                    log("failed http=${response?.code ?: 0} ${t.javaClass.simpleName}: ${t.message}")
                    drop(response?.code ?: 0)
                }
            },
        )
    }

    @Synchronized
    private fun drop(code: Int) {
        socket = null
        connected = false
        connectionListeners.forEach { it(false) }
        if (closedByUs) return
        // 4401 is the token being rejected, not the connection failing. A socket
        // carries the access token in its URL, so it outlives it - fifteen
        // minutes in, or over any doze longer than that - and a socket that gave
        // up here stayed down until the app was restarted: no messages, no
        // presence, an app that looks signed out while the session behind it is
        // fine. Ask for a fresh token (a refresh that works calls connect()
        // itself) and still fall through to the backoff, so a refresh that
        // cannot happen right now is retried rather than being the end of it.
        if (code == 4401) Session.renewAccessToken()
        scheduleReconnect()
    }

    private fun scheduleReconnect() {
        val since = downSince ?: System.currentTimeMillis().also { downSince = it }
        // Given up on rather than retried more slowly: past the deadline the app
        // says it is disconnected and waits to be told to try again. A backoff
        // that never stops is a spinner that never stops.
        if (System.currentTimeMillis() - since >= RECONNECT_DEADLINE_MS) {
            log("gave up after ${RECONNECT_DEADLINE_MS}ms")
            Connectivity.report(path, Connectivity.State.OFFLINE)
            return
        }
        Connectivity.report(path, Connectivity.State.RECONNECTING)

        val delay = min(1000.0 * 2.0.pow(attempt), 30_000.0).toLong()
        attempt += 1
        Thread {
            Thread.sleep(delay)
            if (!closedByUs) open()
        }.apply { isDaemon = true }.start()
    }

    /**
     * The phone has a connection again, so stop waiting out a timer that was
     * measuring a problem which no longer exists.
     *
     * The backoff still handles the other case - a server that is refusing
     * connections, where hammering it is exactly wrong. This is only ever
     * called when the *phone* changed, and `open()` is a no-op on a socket that
     * is already up, so a handover firing it twice costs nothing.
     */
    @Synchronized
    private fun networkReturned() {
        if (closedByUs || token == null || socket != null) return
        // The next failure starts the ladder from the bottom: whatever the
        // count had climbed to belonged to a network that has been replaced.
        // The deadline restarts with it - a socket that had been given up on
        // is exactly the one a returning network should try again.
        attempt = 0
        downSince = System.currentTimeMillis()
        log("network returned")
        Connectivity.report(path, Connectivity.State.RECONNECTING)
        open()
    }

    init {
        NetworkWatch.onAvailable { networkReturned() }
    }

    /**
     * This installation's id, or null before it exists.
     *
     * Null is not a failure: a socket opened before `DeviceIdentity.init` has
     * run gets the old behaviour - a random peer id per connection - rather
     * than a crash on a `lateinit`.
     */
    private fun deviceId(): String? =
        runCatching { com.aatech.betweenus.core.crypto.DeviceIdentity.id() }.getOrNull()

    /** Overridden to re-subscribe: the server keeps nothing across connections. */
    protected open fun onConnected() = Unit

    @Synchronized
    fun send(event: JSONObject) {
        val text = event.toString()
        val live = socket
        if (connected && live != null) {
            live.send(text)
        } else {
            log("queued ${event.optString("type")} (not connected)")
            pending.addLast(text)
        }
    }

    fun on(listener: (JSONObject) -> Unit): () -> Unit {
        listeners.add(listener)
        return { listeners.remove(listener) }
    }

    fun onConnection(listener: (Boolean) -> Unit): () -> Unit {
        connectionListeners.add(listener)
        return { connectionListeners.remove(listener) }
    }

    @Synchronized
    fun disconnect() {
        closedByUs = true
        downSince = null
        pending.clear()
        socket?.close(1000, null)
        socket = null
        connected = false
        // A deliberate sign-out is not a connection problem, and a banner left
        // up over the login form is a lie about a socket nothing wants open.
        Connectivity.forget(path)
    }

    companion object {
        /**
         * How long a socket may keep retrying before it is given up on.
         *
         * Thirty seconds of "Reconnecting…" is already longer than anybody
         * waits before deciding the app is broken. Past it the app says so and
         * offers the retry as a button, which somebody who has just walked back
         * into wifi presses and is back in a second - an exponential backoff
         * sitting on its thirty-second step is not.
         */
        const val RECONNECT_DEADLINE_MS = 30_000L
    }
}

/**
 * Whether this app can reach the backend, for the reconnecting banner.
 *
 * Every socket reports into it and the worst answer wins: presence being down
 * with chat up is still an app that is missing events, and saying so is the
 * whole point. Call and remote sockets only exist during a session of their
 * own, so they report too and stop counting the moment they are closed.
 */
object Connectivity {
    enum class State { ONLINE, RECONNECTING, OFFLINE }

    private val perSocket = mutableMapOf<String, State>()
    private val _state = MutableStateFlow(State.ONLINE)
    val state: StateFlow<State> = _state.asStateFlow()

    @Synchronized
    internal fun report(path: String, state: State) {
        perSocket[path] = state
        publish()
    }

    @Synchronized
    internal fun forget(path: String) {
        perSocket.remove(path)
        publish()
    }

    private fun publish() {
        val states = perSocket.values
        _state.value = when {
            states.contains(State.OFFLINE) -> State.OFFLINE
            states.contains(State.RECONNECTING) -> State.RECONNECTING
            else -> State.ONLINE
        }
    }

    /**
     * Every socket starts its ladder again, and any that is not really up is
     * opened again rather than waited on. The banner's button, and what the app
     * does the moment it is back on screen. See [JsonSocket.retry].
     */
    fun retry() {
        ChatSocket.retry()
        PresenceSocket.retry()
        CallSocket.retry()
        RemoteSocket.retry()
    }
}

/**
 * `/ws/chat`: messages, and the announcements that a friend list or a member
 * list has changed.
 *
 * The client stays subscribed to every text channel it can read, not only the
 * one on screen - otherwise a message in another channel never arrives and
 * there is nothing to badge or notify about.
 */
object ChatSocket : JsonSocket("/ws/chat") {
    private val channels = LinkedHashSet<String>()
    private val servers = LinkedHashSet<String>()

    /**
     * Run once the subscriptions are back.
     *
     * Re-subscribing does not replay anything: the server sends what happens
     * next, not what happened while nobody was listening. Whatever missed the
     * gap has to be re-read over REST, and `Conversation` is what knows which
     * channel that is - a callback rather than a direct call, because that
     * lives in `core.store` and this is `core.data`.
     */
    @Volatile
    var onReconnect: (() -> Unit)? = null

    override fun onConnected() {
        synchronized(channels) {
            channels.forEach { send(JSONObject().put("type", "channel.subscribe").put("channelId", it)) }
        }
        synchronized(servers) {
            servers.forEach { send(JSONObject().put("type", "server.subscribe").put("serverId", it)) }
        }
        onReconnect?.invoke()
    }

    /** Subscribes to exactly these channels, dropping anything else. */
    fun syncSubscriptions(channelIds: Collection<String>) = synchronized(channels) {
        val wanted = channelIds.toSet()
        (channels - wanted).forEach {
            channels.remove(it)
            send(JSONObject().put("type", "channel.unsubscribe").put("channelId", it))
        }
        (wanted - channels).forEach {
            channels.add(it)
            send(JSONObject().put("type", "channel.subscribe").put("channelId", it))
        }
    }

    /**
     * Watches exactly these servers. Separate from channel subscriptions
     * because a member joining or leaving is not news about any one channel.
     */
    fun syncServers(serverIds: Collection<String>) = synchronized(servers) {
        val wanted = serverIds.toSet()
        (servers - wanted).forEach {
            servers.remove(it)
            send(JSONObject().put("type", "server.unsubscribe").put("serverId", it))
        }
        (wanted - servers).forEach {
            servers.add(it)
            send(JSONObject().put("type", "server.subscribe").put("serverId", it))
        }
    }

    fun forget() {
        synchronized(channels) { channels.clear() }
        synchronized(servers) { servers.clear() }
    }
}

/** `/ws/presence`: online status, typing indicators, voice-channel membership. */
object PresenceSocket : JsonSocket("/ws/presence") {
    private var status: PresenceStatus = PresenceStatus.ONLINE

    /**
     * Run on every connection, after the status has been re-sent.
     *
     * `ChannelFocus` sets it, and a callback rather than a direct call because
     * that lives in `core.store` and this is `core.data`: the socket is not
     * allowed to know what a channel focus is.
     */
    @Volatile
    var onReconnect: (() -> Unit)? = null

    override fun onConnected() {
        // The server defaults a new connection to online; say so explicitly, so
        // a status chosen before a reconnect survives it.
        setStatus(status)
        // Nothing survives a reconnect on the server side, so anything this
        // client had claimed has to be claimed again.
        onReconnect?.invoke()
    }

    fun setStatus(next: PresenceStatus) {
        if (next == PresenceStatus.OFFLINE) return
        status = next
        send(JSONObject().put("type", "status.set").put("status", next.wire))
    }

    fun typing(channelId: String) =
        send(JSONObject().put("type", "typing.start").put("channelId", channelId))

    /**
     * "When were these people last here?"
     *
     * Asked when a conversation opens or a profile sheet does. The answers come
     * back as ordinary `presence.changed` events, so nothing waits on a reply
     * and the store has one road in rather than two.
     */
    fun query(userIds: List<String>) {
        if (userIds.isEmpty()) return
        send(
            JSONObject()
                .put("type", "presence.query")
                .put("userIds", JSONArray().also { array -> userIds.forEach(array::put) }),
        )
    }

    /**
     * "This conversation is on screen in front of me."
     *
     * What stops a push waking this account's other devices for a message it
     * is already reading here. See `core/store/ChannelFocus.kt`.
     */
    fun focus(channelId: String) =
        send(JSONObject().put("type", "channel.focus").put("channelId", channelId))

    fun blur(channelId: String) =
        send(JSONObject().put("type", "channel.blur").put("channelId", channelId))

    fun joinVoice(channelId: String) =
        send(JSONObject().put("type", "voice.join").put("channelId", channelId))

    fun leaveVoice(channelId: String) =
        send(JSONObject().put("type", "voice.leave").put("channelId", channelId))
}

/**
 * `/ws/call`: the switchboard. It carries the roster, the offers, the answers
 * and the ICE candidates, and never a byte of media - see section 28 of
 * CLAUDE.md, which is the rule the whole design is built around.
 *
 * The server keeps nothing across connections, so a call has to be rejoined on
 * every reconnect exactly as chat has to be resubscribed. Without that, a phone
 * losing its signal for a moment - a lift, a train, a screen that went off -
 * came back on a socket the call service had never heard of: still showing a
 * call, absent from everybody else's roster, and never told why.
 */
object CallSocket : JsonSocket("/ws/call") {
    @Volatile
    private var channelId: String? = null

    override fun onConnected() {
        channelId?.let { send(JSONObject().put("type", "join").put("channelId", it)) }
    }

    /**
     * Joins, and remembers the call for as long as it lasts.
     *
     * Nothing is queued when the socket is down: [onConnected] sends it on the
     * way up, and queuing as well would arrive as two joins.
     */
    fun join(channelId: String) {
        this.channelId = channelId
        if (connected) send(JSONObject().put("type", "join").put("channelId", channelId))
    }

    /**
     * Goodbye, with what this client measured on it.
     *
     * The report is built by the caller because the caller is the only thing
     * holding the peer connections: media is peer to peer, so a byte counted
     * anywhere else does not exist. A leave with no report - an older path, or
     * a call nothing was measured in - is still a leave.
     */
    fun leave(report: JSONObject? = null) {
        channelId = null
        send(report ?: JSONObject().put("type", "leave"))
    }

    /**
     * "I am about to share my screen" and "I have stopped".
     *
     * One share at a time in a call, and the gateway is what decides whose: two
     * people pressing the button at the same moment need one answer, and a mesh
     * has no ordering to give one. Everybody is then told who holds it, and
     * whoever was sharing before stops.
     */
    fun claimScreen() = send(JSONObject().put("type", "screen.claim"))

    fun releaseScreen() = send(JSONObject().put("type", "screen.release"))
}

/** `/ws/remote`: remote-session handshake, input and signalling. Never the screen. */
object RemoteSocket : JsonSocket("/ws/remote")

package com.aatech.betweenus.core.store

import android.app.Activity
import android.app.Application
import android.os.Bundle
import com.aatech.betweenus.core.data.Connectivity

/**
 * Whether somebody is actually looking at the app.
 *
 * Half of the WhatsApp rule. A push for the channel already on screen must not
 * become a notification - but "on screen" is two facts, not one:
 * `Conversation.visibleChannelId` says which conversation the app is showing,
 * and this says whether the app is being shown at all. Without the second, a
 * phone locked mid-conversation goes silent for that channel forever, because
 * the chat screen is still composed behind the lock screen.
 *
 * Counted rather than flagged: a `startActivity` resumes the new activity
 * before pausing the old one, so a boolean flickers false in the middle of a
 * navigation that never left the app.
 */
object AppForeground {
    @Volatile
    private var resumed = 0

    val visible: Boolean get() = resumed > 0

    fun init(application: Application) {
        application.registerActivityLifecycleCallbacks(
            object : Application.ActivityLifecycleCallbacks {
                override fun onActivityResumed(activity: Activity) {
                    val returning = resumed == 0
                    resumed += 1
                    // Coming back to the app, rather than moving between two of
                    // its screens. The sockets are asked whether they are really
                    // up before anything else is: a background Android froze
                    // leaves a connection that is dead and a backoff that never
                    // ran, and both look like a banner that says "Reconnecting…"
                    // for as long as the app is left open.
                    if (returning) Connectivity.retry()
                    // A phone that has come back to the app is a phone reading
                    // whatever is on screen, and the server has to hear so.
                    ChannelFocus.apply()
                    // It is also a phone whose socket Android was free to drop
                    // while nobody was looking, so what is on screen may be
                    // several messages behind. Coming back is the other moment
                    // - besides a reconnect - when it has to be re-read.
                    Conversation.resumeVisible()
                }

                override fun onActivityPaused(activity: Activity) {
                    resumed = (resumed - 1).coerceAtLeast(0)
                    ChannelFocus.apply()
                }

                override fun onActivityCreated(activity: Activity, state: Bundle?) = Unit
                override fun onActivityStarted(activity: Activity) = Unit
                override fun onActivityStopped(activity: Activity) = Unit
                override fun onActivitySaveInstanceState(activity: Activity, out: Bundle) = Unit
                override fun onActivityDestroyed(activity: Activity) = Unit
            },
        )
    }
}

package com.aatech.betweenus.core.store

import android.content.Context
import androidx.room.Dao
import androidx.room.Database
import androidx.room.Entity
import androidx.room.Index
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.PrimaryKey
import androidx.room.Query
import androidx.room.Room
import androidx.room.RoomDatabase
import com.aatech.betweenus.core.data.Channel
import com.aatech.betweenus.core.data.DirectChannel
import com.aatech.betweenus.core.data.Friend
import com.aatech.betweenus.core.data.Message
import com.aatech.betweenus.core.data.ServerMember
import com.aatech.betweenus.core.data.ServerWithRole
import com.aatech.betweenus.core.data.jsonArrayOfObjects
import com.aatech.betweenus.core.data.map
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch
import org.json.JSONArray
import org.json.JSONObject

/**
 * A row of whatever list it is named after, as the JSON the server sent.
 *
 * Storing the wire shape rather than a column per field is deliberate. These
 * lists are read and written whole, never queried into, and `Models.kt` already
 * holds a parser for every one of them - a column layout would buy nothing and
 * would have to be migrated every time a field is added to the contract.
 */
@Entity(tableName = "cache")
internal data class CacheRow(@PrimaryKey val id: String, val json: String)

/**
 * One message, still sealed. `channelId` and `createdAt` are columns because
 * they are what the reads sort and filter on; the rest stays in the blob.
 */
@Entity(tableName = "message", indices = [Index("channelId")])
internal data class MessageRow(
    @PrimaryKey val id: String,
    val channelId: String,
    val createdAt: String,
    val json: String,
)

@Dao
internal interface CacheDao {
    @Query("SELECT json FROM cache WHERE id = :id")
    suspend fun read(id: String): String?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun write(row: CacheRow)

    @Query("DELETE FROM cache")
    suspend fun clearLists()

    /** Newest first, which is the cheap end of the index to read a page from. */
    @Query("SELECT * FROM message WHERE channelId = :channelId ORDER BY createdAt DESC LIMIT :limit")
    suspend fun latest(channelId: String, limit: Int): List<MessageRow>

    @Query(
        "SELECT * FROM message WHERE channelId = :channelId AND createdAt < :before " +
            "ORDER BY createdAt DESC LIMIT :limit",
    )
    suspend fun before(channelId: String, before: String, limit: Int): List<MessageRow>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun writeMessages(rows: List<MessageRow>)

    @Query("DELETE FROM message")
    suspend fun clearMessages()

    @Query("DELETE FROM message WHERE channelId = :channelId")
    suspend fun clearChannel(channelId: String)

    @Query("DELETE FROM message WHERE id IN (:ids)")
    suspend fun forgetMessages(ids: List<String>)
}

@Database(entities = [CacheRow::class, MessageRow::class], version = 1, exportSchema = false)
internal abstract class BetweenUsDatabase : RoomDatabase() {
    abstract fun cache(): CacheDao
}

/**
 * What the app knew last time it ran.
 *
 * The point of it is that opening BetweenUs shows a conversation rather than a
 * spinner: the stores draw from here first and let the network catch up behind
 * them, the way WhatsApp does. Nothing here is authoritative - the server is,
 * and every read is followed by a refresh - but on a cold start, on a train,
 * or against a backend that is having a bad day, this is what is on screen.
 *
 * Two things are deliberately *not* stored:
 *
 * - **Plaintext.** Messages are cached exactly as they arrived, still sealed.
 *   Decryption happens on the way to the screen. A database pulled off a rooted
 *   phone is worth what the server's own rows are worth, which is nothing
 *   without a channel key - and those live in the Keystore, not here.
 * - **Anything for another account.** [claim] wipes the lot when the user id
 *   changes, and every read waits for it, so a second account cannot flash the
 *   first one's servers on screen while the network catches up.
 *
 * Writes are fire-and-forget: a cache that cannot be written is a slower app,
 * never a broken one, so nothing here throws into a caller.
 */
object Cache {
    private const val OWNER = "owner"
    private const val PAGE = 50

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    @Volatile
    private var db: BetweenUsDatabase? = null

    /** Completes when the cache is known to belong to whoever is signed in. */
    @Volatile
    private var claimed = CompletableDeferred<Unit>()

    fun init(context: Context) {
        db = Room.databaseBuilder(
            context.applicationContext,
            BetweenUsDatabase::class.java,
            "betweenus-cache.db",
        )
            // A cache has nothing in it that cannot be fetched again, so a
            // schema change throws it away rather than carrying a migration.
            .fallbackToDestructiveMigration(dropAllTables = true)
            .build()
    }

    /**
     * Binds the cache to an account. A different one than last time means
     * everything here belongs to somebody else and goes.
     */
    fun claim(userId: String) {
        scope.launch {
            runCatching {
                val dao = db?.cache() ?: return@runCatching
                if (dao.read(OWNER) != userId) {
                    dao.clearLists()
                    dao.clearMessages()
                    dao.write(CacheRow(OWNER, userId))
                }
            }
            claimed.complete(Unit)
        }
    }

    /**
     * Forgets everything. Signing out is the one moment a person has said they
     * are done with this device - a session that merely expired keeps its cache,
     * so signing back in is still instant.
     */
    suspend fun clear() {
        claimed = CompletableDeferred()
        runCatching {
            db?.cache()?.let {
                it.clearLists()
                it.clearMessages()
            }
        }
    }

    /**
     * Forgets one conversation's messages and nothing else.
     *
     * What "clear this chat" needs. [clear] would work and is shorter, but it
     * throws away every other conversation this phone has cached - so clearing
     * one chat would turn the next four things somebody opens into spinners,
     * for a reason they could not connect to what they just did.
     *
     * The lists are left alone: the channel still exists and still belongs in
     * the rail. What went is what was said in it.
     */
    suspend fun forgetChannel(channelId: String) {
        runCatching { db?.cache()?.clearChannel(channelId) }
    }

    /**
     * Forgets specific messages, by id.
     *
     * For the two deletions that leave no tombstone - a one-time message that
     * was opened, and one whose disappearing window closed. An ordinary delete
     * does not come through here: its tombstone is written over the old row by
     * [putMessages], which is what makes a conversation still say "this was
     * here and is gone" after the app is restarted.
     */
    suspend fun forgetMessages(ids: List<String>) {
        if (ids.isEmpty()) return
        runCatching { db?.cache()?.forgetMessages(ids) }
    }

    // --- lists ---

    suspend fun servers(): List<ServerWithRole>? = readList("servers") { ServerWithRole.from(it) }

    fun putServers(servers: List<ServerWithRole>) =
        writeList("servers", jsonArrayOfObjects(servers) { it.toJson() })

    suspend fun channels(): Map<String, List<Channel>>? =
        readMap("channels") { array -> array.map { Channel.from(it) } }

    fun putChannels(channels: Map<String, List<Channel>>) =
        writeMap("channels", channels.mapValues { (_, list) -> jsonArrayOfObjects(list) { it.toJson() } })

    suspend fun directChannels(): List<DirectChannel>? =
        readList("directChannels") { DirectChannel.from(it) }

    fun putDirectChannels(channels: List<DirectChannel>) =
        writeList("directChannels", jsonArrayOfObjects(channels) { it.toJson() })

    suspend fun friends(): List<Friend>? = readList("friends") { Friend.from(it) }

    fun putFriends(friends: List<Friend>) =
        writeList("friends", jsonArrayOfObjects(friends) { it.toJson() })

    suspend fun members(): Map<String, List<ServerMember>>? =
        readMap("members") { array -> array.map { ServerMember.from(it) } }

    fun putMembers(members: Map<String, List<ServerMember>>) =
        writeMap("members", members.mapValues { (_, list) -> jsonArrayOfObjects(list) { it.toJson() } })

    suspend fun unread(): Map<String, Int>? = read("unread")?.let { stored ->
        runCatching {
            val json = JSONObject(stored)
            json.keys().asSequence().associateWith { json.getInt(it) }
        }.getOrNull()
    }

    fun putUnread(unread: Map<String, Int>) {
        val json = JSONObject()
        unread.forEach { (channelId, count) -> json.put(channelId, count) }
        write("unread", json.toString())
    }

    // --- messages ---

    /** The newest page of a channel, oldest first, as the screen wants it. */
    suspend fun messages(channelId: String): List<Message> =
        readMessages { it.latest(channelId, PAGE) }

    /** The page before [before], which is a `createdAt`, not an id. */
    suspend fun messagesBefore(channelId: String, before: String): List<Message> =
        readMessages { it.before(channelId, before, PAGE) }

    /**
     * Keeps everything, and is meant to: history that has been fetched once
     * should never need fetching again, and a few thousand rows of text is not
     * a size worth pruning. If it ever becomes one, prune by channel here.
     */
    fun putMessages(messages: List<Message>) {
        if (messages.isEmpty()) return
        scope.launch {
            runCatching {
                dao()?.writeMessages(
                    messages.map {
                        MessageRow(it.id, it.channelId, it.createdAt, it.toJson().toString())
                    },
                )
            }
        }
    }

    // --- plumbing ---

    private suspend fun dao(): CacheDao? {
        claimed.await()
        return db?.cache()
    }

    private suspend fun readMessages(query: suspend (CacheDao) -> List<MessageRow>): List<Message> =
        runCatching {
            val dao = dao() ?: return emptyList()
            query(dao).mapNotNull { row ->
                runCatching { Message.from(JSONObject(row.json)) }.getOrNull()
            }.sortedBy { it.createdAt }
        }.getOrDefault(emptyList())

    private suspend fun read(id: String): String? =
        runCatching { dao()?.read(id) }.getOrNull()

    private fun write(id: String, json: String) {
        scope.launch { runCatching { dao()?.write(CacheRow(id, json)) } }
    }

    private suspend fun <T> readList(id: String, parse: (JSONObject) -> T): List<T>? =
        read(id)?.let { stored -> runCatching { JSONArray(stored).map(parse) }.getOrNull() }

    private fun writeList(id: String, array: JSONArray) = write(id, array.toString())

    private suspend fun <T> readMap(id: String, parse: (JSONArray) -> List<T>): Map<String, List<T>>? =
        read(id)?.let { stored ->
            runCatching {
                val json = JSONObject(stored)
                json.keys().asSequence().associateWith { parse(json.getJSONArray(it)) }
            }.getOrNull()
        }

    private fun writeMap(id: String, byKey: Map<String, JSONArray>) {
        val json = JSONObject()
        byKey.forEach { (key, array) -> json.put(key, array) }
        write(id, json.toString())
    }
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.data.PresenceSocket
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

/**
 * Telling the server which conversation is on this screen.
 *
 * The other half of the rule [PushGate] applies locally, and the half only a
 * server can apply: a message in a channel somebody is reading on their laptop
 * should not wake the phone in their pocket. `notification-service` asks
 * presence-service who has a channel focused before it fans a push out - see
 * `docs/docs/architecture/push-suppression.md`.
 *
 * Two facts make a focus, and both already exist here: which conversation is
 * open ([Conversation.visibleChannelId]) and whether the app is in front of
 * anybody ([AppForeground]). A phone locked mid-conversation is not somebody
 * reading it - the chat screen is still composed behind the lock screen, which
 * is exactly the case that would otherwise go silent forever.
 *
 * ponytail: no lifecycle observers of its own. Both facts are already tracked
 * for the local rule; this only reports them.
 */
object ChannelFocus {

    /**
     * Well inside presence-service's 90-second staleness window. The socket's
     * own heartbeat refreshes the entry too; this covers a reconnect that
     * landed on a different presence instance.
     */
    private const val HEARTBEAT_MS = 60_000L

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    /** What the server has been told, so nothing is said twice. */
    @Volatile
    private var reported: String? = null

    private var started = false

    fun init() {
        if (started) return
        started = true

        // Re-asserted on every reconnect, like the status and the call join: the
        // server keeps nothing across connections, and a focus that is not
        // re-sent ages out into a phone that starts buzzing for a conversation
        // that is still on screen.
        PresenceSocket.onReconnect = {
            reported = null
            apply()
        }

        scope.launch {
            while (true) {
                delay(HEARTBEAT_MS)
                // Re-sent rather than skipped when nothing has changed: this is
                // the heartbeat, and saying the same thing again is its job.
                reported?.let { PresenceSocket.focus(it) }
            }
        }
    }

    /**
     * Called whenever either half of the fact changes - a channel opened or
     * closed, or the app coming to the front or going away.
     */
    fun apply() {
        val next = if (AppForeground.visible) Conversation.visibleChannelId else null
        val previous = reported
        if (next == previous) return

        // The old channel is blurred rather than left to expire: ninety seconds
        // of a stale focus is ninety seconds of missed notifications for a
        // conversation this phone has already left.
        if (previous != null) PresenceSocket.blur(previous)
        if (next != null) PresenceSocket.focus(next)
        reported = next
    }

    /** Signing out: this account is not reading anything any more. */
    fun forget() {
        reported?.let { PresenceSocket.blur(it) }
        reported = null
    }
}

