import java.util.concurrent.ConcurrentHashMap

/**
 * One message, ready to draw: the stored row plus whatever came out of the
 * envelope. Decryption happens once, here, rather than in a composable that
 * would redo it on every recomposition.
 */
data class ReadableMessage(
    val message: Message,
    val body: MessageBody,
) {
    val id: String get() = message.id
    val text: String get() = body.text
    val attachments: List<MessageAttachment> get() = body.attachments
    val replyTo: MessageReply? get() = body.replyTo

    /** What a reply to this message quotes. */
    fun quote(): MessageReply = MessageReply(
        id = message.id,
        author = message.author.label,
        preview = when {
            text.isNotBlank() -> MessageReply.preview(text)
            attachments.isNotEmpty() -> "${attachments.size} file" +
                if (attachments.size == 1) "" else "s"
            else -> ""
        },
    )
}

/**
 * Message history, per channel.
 *
 * The port of the message half of `apps/desktop/src/stores/chat.ts`. It holds
 * every channel that has been opened this session, because coming back to a
 * conversation should not be a spinner, and because a socket event for a
 * channel that is not on screen still has to update the count in the sidebar.
 */
object Conversation {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    private val _messages = MutableStateFlow<Map<String, List<ReadableMessage>>>(emptyMap())
    val messages: StateFlow<Map<String, List<ReadableMessage>>> = _messages.asStateFlow()

    private val _loading = MutableStateFlow<Set<String>>(emptySet())
    val loading: StateFlow<Set<String>> = _loading.asStateFlow()

    /**
     * channelId -> everyone else's read marker in it. The "seen by" row under
     * your own messages is derived from these; see [Receipts]. Loaded when a
     * channel is opened and kept current by the `channel.read` event.
     */
    private val _receipts = MutableStateFlow<Map<String, List<ChannelReadReceipt>>>(emptyMap())
    val receipts: StateFlow<Map<String, List<ChannelReadReceipt>>> = _receipts.asStateFlow()

    /** The oldest id fetched per channel, which is what "load more" asks before. */
    private val cursors = ConcurrentHashMap<String, String>()
    private val exhausted = ConcurrentHashMap.newKeySet<String>()

    /** The channel currently on screen; its messages are read, not counted. */
    @Volatile
    var visibleChannelId: String? = null
        private set

    private var wired = false

    fun start() {
        if (wired) return
        wired = true
        ChatSocket.on { event -> scope.launch { onEvent(event) } }
        // A socket that was down missed every message that arrived while it
        // was, and re-subscribing does not deliver them - the server sends what
        // happens next, not what happened. A phone is down constantly (a lift,
        // a lock screen, an OS that dropped the connection while the app was in
        // the background), so coming back has to re-read rather than assume.
        ChatSocket.onReconnect = { resumeVisible() }
    }

    fun stop() {
        _messages.value = emptyMap()
        _receipts.value = emptyMap()
        cursors.clear()
        exhausted.clear()
        visibleChannelId = null
    }

    private suspend fun onEvent(event: JSONObject) {
        // Somebody read a channel this client is subscribed to. It carries no
        // message, so it is answered before the message is even looked for.
        if (event.optString("type") == "channel.read") {
            onChannelRead(event.optString("channelId"), event.optString("userId"), event.optString("at"))
            return
        }
        // Somebody changed their picture or their name. Every message they ever
        // sent in an open channel is signed with a copy of it, as is every read
        // receipt, so the copies are rewritten rather than the history refetched.
        if (event.optString("type") == "user.updated") {
            event.optJSONObject("user")?.let { patchProfile(UserSummary.from(it)) }
            return
        }
        // This account cleared its own history, here or on another of its
        // devices. Everything held goes: the cache is full of sealed envelopes
        // the server will no longer hand back, and the open channel is full of
        // the decrypted ones. Re-reading is what fills both again, with
        // whatever arrived after the cut.
        if (event.optString("type") == "chats.cleared") {
            val cleared = if (event.isNull("channelId")) null else event.optString("channelId")
            if (cleared == null) {
                Cache.clear()
                _messages.value = emptyMap()
                _receipts.value = emptyMap()
                cursors.clear()
                exhausted.clear()
            } else {
                // One conversation leaves the rest of the cache alone. Throwing
                // it all away would turn "clear this chat" into a spinner on the
                // next four things the person opens, for a reason they could not
                // connect to what they just did.
                Cache.forgetChannel(cleared)
                _messages.update { it - cleared }
                _receipts.update { it - cleared }
                cursors.remove(cleared)
                exhausted.remove(cleared)
            }
            Workspace.loadUnread()
            // Re-opened only when it is the one on screen; anything else is
            // fetched when somebody actually goes there.
            visibleChannelId?.let { if (cleared == null || cleared == it) open(it) }
            return
        }
        // A message that left no tombstone: a one-time message somebody opened,
        // or one whose disappearing window closed. Handled before the message
        // is read out of the frame, because this frame carries none - there is
        // nothing to draw in its place, only something to forget.
        if (event.optString("type") == "message.gone") {
            val goneId = event.optString("messageId")
            if (goneId.isEmpty()) return
            // Not while somebody is looking at it. A one-time message is
            // burned as its viewer opens, and the viewer is drawn inside the
            // message row - so removing the message here took the row down,
            // and the row took the viewer with it. That was a one-time picture
            // vanishing the instant it was opened.
            if (heldOpen.contains(goneId)) {
                goneWhileOpen.add(goneId)
                return
            }
            forget(setOf(goneId))
            return
        }
        val message = event.optJSONObject("message")?.let { Message.from(it) } ?: return
        // Cached whether or not the channel is open. A conversation nobody has
        // looked at this session is exactly the one that should not be a spinner
        // when the badge is finally tapped.
        Cache.putMessages(listOf(message))
        when (event.optString("type")) {
            "message.created" -> {
                // Only decrypt for a channel already open: a message arriving in
                // a channel nobody has looked at costs a key fetch, and the
                // badge does not need the text.
                if (_messages.value.containsKey(message.channelId)) {
                    insert(read(message))
                }
                val mine = message.author.id == (Session.state.value as? com.aatech.betweenus.core.data.AuthPhase.SignedIn)?.user?.id
                if (!mine) {
                    // On screen *and* in front of somebody. The chat screen is
                    // still composed behind a lock screen, so `visibleChannelId`
                    // alone would count a message nobody has seen as read.
                    if (message.channelId == visibleChannelId && AppForeground.visible) {
                        // Read as soon as it is drawn, so the marker moves on
                        // the account too. Without this the marker only moved
                        // when the channel was opened, and a conversation held
                        // open never told anyone it had been read.
                        markReadSoon(message.channelId)
                    } else {
                        Workspace.noteUnread(message.channelId, 1)
                    }
                }
            }
            // An edit, a deletion, a pin and a reaction are all "this message is
            // not what you last saw", so they share one event carrying the whole
            // message.
            "message.updated" -> if (_messages.value.containsKey(message.channelId)) {
                // A tombstone carries no manifest - the body is empty - so the
                // keys are read off the copy still held here, before it is
                // replaced. After the swap nothing names the files, and the
                // decrypted photo would sit in the media cache with nothing
                // left that could ever remove it.
                if (message.deleted) {
                    val keys = _messages.value[message.channelId]
                        ?.firstOrNull { it.id == message.id }
                        ?.attachments
                        ?.map { it.key }
                        .orEmpty()
                    if (keys.isNotEmpty()) onAttachmentsGone?.invoke(keys)
                }
                replace(read(message))
            }
        }
    }

    /**
     * Rewrite one account's face in every message and receipt held here.
     *
     * `replyTo.author` is deliberately left alone: it is how the quoted message
     * was signed when the reply was written, not a live reference to anybody.
     */
    private fun patchProfile(user: UserSummary) {
        _messages.update { byChannel ->
            byChannel.mapValues { (_, list) ->
                list.map { readable ->
                    val message = readable.message
                    val author =
                        if (message.author.id == user.id) user else message.author
                    val deletedBy =
                        if (message.deletedBy?.id == user.id) user else message.deletedBy
                    if (author === message.author && deletedBy === message.deletedBy) {
                        readable
                    } else {
                        readable.copy(
                            message = message.copy(author = author, deletedBy = deletedBy),
                        )
                    }
                }
            }
        }
        _receipts.update { byChannel ->
            byChannel.mapValues { (_, list) ->
                list.map { if (it.user.id == user.id) it.copy(user = user) else it }
            }
        }
    }

    /** Opens a channel: history, key sync, and the read marker. */
    fun open(channelId: String) {
        visibleChannelId = channelId
        // The server is told too: it is what keeps this account's other devices
        // from being woken for a conversation being read here.
        ChannelFocus.apply()
        Workspace.markRead(channelId)
        // Who has read it, for the "seen by" row. Per open channel rather than
        // for every channel at sign-in: it is only ever drawn for the one on
        // screen, and it goes stale the moment somebody reads anyway.
        loadReceipts(channelId)
        // Already in memory, but not necessarily current: whatever arrived
        // while the socket was down is missing from it, and re-opening the
        // channel is exactly when somebody expects to see it.
        if (_messages.value.containsKey(channelId)) {
            refresh(channelId)
            return
        }
        scope.launch {
            _loading.update { it + channelId }
            // What was on screen last time, before anything is asked of the
            // network. A conversation that has been read before opens at once,
            // and opens at all with no signal.
            val cached = Cache.messages(channelId).map { read(it) }
            if (cached.isNotEmpty() && !_messages.value.containsKey(channelId)) {
                _messages.update { it + (channelId to cached) }
            }
            runCatching {
                // Re-wrap the key for anyone who joined since it was minted, so
                // they can read without waiting for a restart.
                launch { runCatching { E2ee.syncChannelKeys(channelId) } }
                val page = BetweenUsApi.messages(channelId)
                page.items.lastOrNull()?.let { cursors[channelId] = it.id }
                if (page.nextCursor == null && page.items.size < 2) exhausted.add(channelId)
                Cache.putMessages(page.items)
                val readable = page.items.map { read(it) }
                // Merged over what came out of the cache rather than replacing
                // it: the fresh page is the newest 50, and dropping everything
                // else would throw away history somebody had already scrolled to.
                _messages.update { all -> all + (channelId to merge(all[channelId], readable)) }
            }
            _loading.update { it - channelId }
        }
    }

    /**
     * The newest page again, merged over what is held.
     *
     * Deliberately not [open]'s fetch: that one sets the cursor, and setting it
     * from the newest page would throw away how far back somebody had already
     * scrolled. This only fills in what is missing at the end.
     */
    fun refresh(channelId: String) {
        scope.launch {
            runCatching {
                val page = BetweenUsApi.messages(channelId)
                Cache.putMessages(page.items)
                val readable = page.items.map { read(it) }
                _messages.update { all -> all + (channelId to merge(all[channelId], readable)) }
            }
        }
    }

    /**
     * The app came back to the front, or the socket did.
     *
     * Three things go stale together while a phone is asleep: the messages that
     * arrived, who has read them, and the fact that this account is looking at
     * the channel again. All three are re-asserted here, and nowhere else needs
     * to know which of the two events it was.
     */
    fun resumeVisible() {
        val channelId = visibleChannelId ?: return
        if (!AppForeground.visible) return
        refresh(channelId)
        loadReceipts(channelId)
        Workspace.markRead(channelId)
    }

    /** The pending "this channel has been read", if a burst is still arriving. */
    private var readJob: Job? = null

    /**
     * Ten messages landing at once are one read, not ten POSTs. Coalesced
     * rather than rate-limited: the last one wins, which is the marker that is
     * actually true.
     */
    private fun markReadSoon(channelId: String) {
        readJob?.cancel()
        readJob = scope.launch {
            delay(700)
            Workspace.markRead(channelId)
        }
    }

    /** Who else has read this channel. Quiet on failure: it is a decoration. */
    fun loadReceipts(channelId: String) {
        scope.launch {
            runCatching { BetweenUsApi.channelReads(channelId) }.onSuccess { rows ->
                _receipts.update { it + (channelId to rows) }
            }
        }
    }

    /**
     * A marker moved. One marker per person, replaced rather than appended: it
     * only ever moves forwards, and keeping the old one would draw a face
     * against a message they have since read past.
     */
    private fun onChannelRead(channelId: String, userId: String, at: String) {
        if (channelId.isBlank() || userId.isBlank()) return
        // Your own marker, from another of your devices. Not a receipt: the row
        // is about who else has seen your message.
        val self = (Session.state.value as? com.aatech.betweenus.core.data.AuthPhase.SignedIn)?.user
        if (userId == self?.id) return

        // A channel this client has never opened has no list to patch, and one
        // is fetched whole when it is opened.
        val known = _receipts.value[channelId] ?: return
        if (known.none { it.user.id == userId }) {
            // Somebody who had never read this channel before: their name is on
            // no list here, so the whole thing is re-read rather than invented.
            loadReceipts(channelId)
            return
        }
        _receipts.update { all ->
            all + (channelId to known.map { if (it.user.id == userId) it.copy(readAt = at) else it })
        }
    }

    fun close(channelId: String) {
        if (visibleChannelId == channelId) visibleChannelId = null
        ChannelFocus.apply()
    }

    fun loadOlder(channelId: String) {
        if (channelId in exhausted || channelId in _loading.value) return
        val oldest = _messages.value[channelId]?.firstOrNull()?.message ?: return
        scope.launch {
            _loading.update { it + channelId }

            // History already on this device first. Anything fetched once is
            // kept, so scrolling back through a conversation a second time is
            // a database read and not a round trip - which is the difference
            // between a list that moves and one that stutters.
            val local = Cache.messagesBefore(channelId, oldest.createdAt)
            if (local.isNotEmpty()) {
                val older = local.map { read(it) }
                _messages.update { all -> all + (channelId to merge(all[channelId], older)) }
            } else {
                runCatching { BetweenUsApi.messages(channelId, oldest.id) }.onSuccess { page ->
                    if (page.items.isEmpty()) {
                        exhausted.add(channelId)
                    } else {
                        Cache.putMessages(page.items)
                        val older = page.items.map { read(it) }
                        _messages.update { all -> all + (channelId to merge(all[channelId], older)) }
                    }
                }
            }
            _loading.update { it - channelId }
        }
    }

    // --- sending ---

    suspend fun send(
        channelId: String,
        text: String,
        attachments: List<MessageAttachment>,
        replyTo: MessageReply? = null,
        /**
         * One-time: the files may be opened once by somebody other than the
         * author, and that opening destroys the message and its blobs.
         *
         * Travels outside the envelope because the server has to act on it,
         * and a server that cannot read the body cannot be told by the body.
         */
        viewOnce: Boolean = false,
        /** Set when this is somebody else's message, carried in from elsewhere. */
        forwardedFrom: MessageForward? = null,
        /**
         * The emoji pictures to carry, when the caller already knows them.
         *
         * A forward is why: its text was written in another server, so working
         * them out from the destination would drop exactly the shortcodes the
         * pictures exist to keep readable.
         */
        emoji: List<MessageCustomEmoji>? = null,
    ) {
        // The pictures for whatever custom emoji the text uses, taken from the
        // server this channel belongs to. They travel inside the envelope, so a
        // reader who is not in that server still sees them.
        val body = MessageBody(
            text,
            attachments,
            replyTo,
            emoji ?: usedEmoji(channelId, text),
            forwardedFrom,
        ).encode()
        val sealed = E2ee.encryptForChannel(channelId, body)
        // The keys go outside the envelope as well as inside it: the server
        // cannot read the manifest, and without them nothing could ever sweep
        // these blobs when the message is deleted.
        val message = BetweenUsApi.sendMessage(
            channelId,
            sealed,
            attachments.map { it.key },
            // A message with no files cannot be one-time: there would be
            // nothing to open once, and the text is in everybody's history
            // either way.
            viewOnce = viewOnce && attachments.isNotEmpty(),
        )
        insert(read(message))
    }

    /**
     * The same message again, in another channel.
     *
     * A copy and not a pointer, because a pointer could not be read: every body
     * and every blob is sealed under the key of the channel it was sent to, and
     * the destination holds a different one. So the plaintext is re-sealed
     * there, and the files are opened here and uploaded again - which is also
     * why this is slow enough to want a progress indication for a video.
     *
     * What travels is what the message said, not what happened to it since. The
     * reactions, the pins and the read receipts belong to the original and stay
     * with it; only the tag saying whose words these were comes along.
     *
     * A one-time message is not forwardable and is not offered as one - the
     * whole point of it is that it is seen once, by the people it was sent to.
     */
    suspend fun forward(
        readable: ReadableMessage,
        toChannelId: String,
        onProgress: ((Float) -> Unit)? = null,
    ) {
        val from = readable.message.channelId
        val files = readable.attachments
        val carried = files.mapIndexed { index, attachment ->
            val bytes = openAttachment(from, attachment)
            uploadAttachment(
                channelId = toChannelId,
                name = attachment.name,
                contentType = attachment.contentType,
                bytes = bytes,
                // Counted across the whole list, so three files read as one
                // job rather than three bars that each start again at zero.
                onProgress = { part ->
                    onProgress?.invoke((index + part) / files.size)
                },
                duration = attachment.duration,
                waveform = attachment.waveform,
            )
        }
        send(
            channelId = toChannelId,
            text = readable.text,
            attachments = carried,
            forwardedFrom = MessageForward(
                author = readable.message.author.label,
                channel = originName(from),
            ),
            // The pictures the original carried, not the destination's. The
            // text was written somewhere else and its shortcodes mean what
            // they meant there.
            emoji = readable.body.emoji,
        )
    }

    /**
     * What to call the place a forward came from.
     *
     * A channel has a name; a direct message has a person, and naming them is
     * the honest answer to "where did this come from" - the alternative was a
     * blank, which reads as a forward from nowhere.
     */
    private fun originName(channelId: String): String =
        Workspace.channel(channelId)?.name
            ?: Workspace.directChannel(channelId)?.participant?.label
            ?: ""

    suspend fun edit(message: Message, text: String) {
        val existing = _messages.value[message.channelId]?.firstOrNull { it.id == message.id }
        // An edit changes the words. What the message was answering is not one
        // of them, so the quote rides along untouched.
        val body = MessageBody(
            text,
            existing?.attachments.orEmpty(),
            existing?.body?.replyTo,
            // An edit may introduce a shortcode that was not there before, so
            // the manifest is recomputed rather than carried over.
            usedEmoji(message.channelId, text),
        ).encode()
        val sealed = E2ee.encryptForChannel(message.channelId, body)
        replace(read(BetweenUsApi.editMessage(message.id, sealed)))
    }

    suspend fun delete(message: Message) {
        BetweenUsApi.deleteMessage(message.id)
        // The tombstone arrives on the socket; nothing to do locally but wait.
    }

    suspend fun react(message: Message, emoji: String) {
        replace(read(BetweenUsApi.reactToMessage(message.id, emoji)))
    }

    suspend fun pin(message: Message, pinned: Boolean) {
        replace(read(BetweenUsApi.pinMessage(message.id, pinned)))
    }

    suspend fun pins(channelId: String): List<ReadableMessage> =
        BetweenUsApi.pins(channelId).map { read(it) }

    /**
     * Seals a file under the channel key and uploads the ciphertext.
     *
     * [onProgress] is called with 0..1 across the upload, counted in parts. A
     * hundred megabytes over a phone's uplink is minutes, and minutes with no
     * sign of movement is a send that looks stuck.
     */
    suspend fun uploadAttachment(
        channelId: String,
        name: String,
        contentType: String,
        bytes: ByteArray,
        onProgress: ((Float) -> Unit)? = null,
        /** Seconds, for a recording. See [MessageAttachment.duration]. */
        duration: Float? = null,
        /** Bar heights, for a recording. See [MessageAttachment.waveform]. */
        waveform: List<Float> = emptyList(),
    ): MessageAttachment {
        val photo = asJpeg(bytes, contentType)
        val payload = photo?.bytes ?: bytes
        val (sealed, epoch) = E2ee.encryptFileForChannel(channelId, payload)
        val stored = putBytes(sealed.ciphertext, onProgress)
        val pixels = if (contentType.startsWith("image/")) pixelSize(payload) else null
        return MessageAttachment(
            key = stored.key,
            url = stored.url,
            // What was converted has to say so. A JPEG called .heic is a file
            // that lies about itself to every client that opens it.
            name = if (photo != null) withExtension(name, "jpg") else name,
            contentType = if (photo != null) "image/jpeg" else contentType,
            size = payload.size.toLong(),
            iv = sealed.iv,
            epoch = epoch,
            width = pixels?.first,
            height = pixels?.second,
            duration = duration,
            waveform = waveform,
        )
    }

    /**
     * One part of a large upload. Comfortably over S3's 5 MiB minimum and under
     * the server's own per-request cap, with room for the multipart form
     * framing. The same number the desktop uses.
     */
    private const val PART_BYTES = 8 * 1024 * 1024

    /**
     * One request when it fits in one; otherwise a part at a time.
     *
     * The phone used to only have the first branch, and a 25 MB ceiling to go
     * with it - so a file the desktop sent happily was refused here, and the
     * refusal was the client's, not the deployment's. The server has taken
     * multipart uploads all along.
     *
     * A few parts at a time, exactly as on the desktop. One at a time was the
     * old answer and it was the wrong one: a single request spends most of its
     * life waiting - the round trip to the gateway, the tunnel, the store's own
     * acknowledgement - and none of that is uplink. [UPLOAD_LANES] slices held
     * at once is the cost, which is why it is a small number.
     */
    private suspend fun putBytes(
        ciphertext: ByteArray,
        onProgress: ((Float) -> Unit)?,
    ): UploadedObject {
        if (ciphertext.size <= PART_BYTES) {
            return BetweenUsApi.uploadAttachment(ciphertext).also { onProgress?.invoke(1f) }
        }

        val opened = BetweenUsApi.startMultipart(ciphertext.size)
        val partSize = minOf(PART_BYTES, opened.maxPartBytes)
        val total = (ciphertext.size + partSize - 1) / partSize

        try {
            val parts = arrayOfNulls<UploadedPart>(total)
            val next = java.util.concurrent.atomic.AtomicInteger(0)
            val done = java.util.concurrent.atomic.AtomicInteger(0)

            coroutineScope {
                repeat(minOf(UPLOAD_LANES, total)) {
                    launch {
                        while (true) {
                            val index = next.getAndIncrement()
                            if (index >= total) break
                            val from = index * partSize
                            val to = minOf(ciphertext.size, from + partSize)
                            parts[index] = BetweenUsApi.uploadPart(
                                ticket = opened.ticket,
                                partNumber = index + 1,
                                bytes = ciphertext.copyOfRange(from, to),
                            )
                            onProgress?.invoke(done.incrementAndGet().toFloat() / total)
                        }
                    }
                }
            }
            return BetweenUsApi.completeMultipart(opened.ticket, parts.filterNotNull())
        } catch (error: Throwable) {
            // Leave no half-uploaded parts behind for a file nobody will send.
            runCatching { BetweenUsApi.abortMultipart(opened.ticket) }
            throw error
        }
    }

    /**
     * How many parts are in flight at once.
     *
     * Three rather than one, and not many more: past this the parts start
     * competing for the same uplink instead of covering each other's latency,
     * and each one in flight is another slice of the ciphertext held in memory
     * on a phone that already asks for `largeHeap` to seal one file.
     */
    private const val UPLOAD_LANES = 3

    /** Matches MAX_IMAGE_EDGE in `apps/desktop/src/services/attachments.ts`. */
    private const val MAX_IMAGE_EDGE = 1920

    /** Below this a JPEG is left alone; re-encoding it would only cost quality. */
    private const val KEEP_JPEG_UNDER_BYTES = 512 * 1024

    private class Photo(val bytes: ByteArray, val width: Int, val height: Int)

    /**
     * A picture, normalised to JPEG - and HEIC is why this exists.
     *
     * A phone camera writes HEIC by default. This platform decodes it natively,
     * so a photo sent from here looked perfectly fine *here*, and arrived on
     * desktop and web as a broken image: Chromium has never shipped a HEIF
     * decoder. Those clients can now decode one they are given, but a picture
     * no browser can read has no business being sent in the first place, so the
     * sender converts.
     *
     * Everything else a camera or a screenshot produces goes the same way, for
     * the same reason the desktop re-encodes: a 12 megapixel photo is several
     * megabytes of detail nobody will look at in a message list. GIF and SVG
     * are left alone - a bitmap would flatten an animation to its first frame,
     * and rasterise a drawing that was meant to scale.
     *
     * Returns null when there is nothing worth doing, and when anything at all
     * goes wrong: sending the file as it came is better than not sending it. On
     * API 24 to 27, where the platform cannot decode HEIC, that is the path a
     * HEIC takes - and those releases predate the cameras that write one.
     */
    private fun asJpeg(bytes: ByteArray, contentType: String): Photo? = try {
        val type = contentType.lowercase()
        val heic = type.startsWith("image/hei")
        val size = pixelSize(bytes)
        val longest = maxOf(size?.first ?: 0, size?.second ?: 0)
        when {
            !type.startsWith("image/") -> null
            type == "image/gif" || type == "image/svg+xml" -> null
            // A small JPEG is already what this would have produced. A HEIC is
            // never that, whatever its size.
            !heic && type == "image/jpeg" && longest <= MAX_IMAGE_EDGE &&
                bytes.size <= KEEP_JPEG_UNDER_BYTES -> null
            else -> encode(bytes, longest)
        }
    } catch (_: Throwable) {
        // OutOfMemoryError included: a photo too big for the heap is still a
        // photo somebody asked to send.
        null
    }

    private fun encode(bytes: ByteArray, longest: Int): Photo? {
        // `inSampleSize` throws whole powers of two away during the decode, so
        // the full-size bitmap never has to exist. It only halves, so it lands
        // at or above the target and the exact fit is done afterwards.
        val options = BitmapFactory.Options().apply {
            var sample = 1
            while (longest > 0 && longest / (sample * 2) >= MAX_IMAGE_EDGE) sample *= 2
            inSampleSize = sample
        }
        val decoded = BitmapFactory.decodeByteArray(bytes, 0, bytes.size, options) ?: return null
        val upright = upright(decoded, bytes)
        val scale = minOf(1f, MAX_IMAGE_EDGE.toFloat() / maxOf(upright.width, upright.height))
        val scaled = if (scale < 1f) {
            Bitmap.createScaledBitmap(
                upright,
                (upright.width * scale).toInt().coerceAtLeast(1),
                (upright.height * scale).toInt().coerceAtLeast(1),
                true,
            )
        } else {
            upright
        }

        val out = ByteArrayOutputStream(bytes.size / 2 + 1024)
        scaled.compress(Bitmap.CompressFormat.JPEG, 85, out)
        val photo = Photo(out.toByteArray(), scaled.width, scaled.height)
        if (scaled !== upright) scaled.recycle()
        if (upright !== decoded) upright.recycle()
        decoded.recycle()
        return photo
    }

    /**
     * The picture the right way up.
     *
     * A phone stores a photo in the sensor's own orientation and records how to
     * turn it in an EXIF tag, which every viewer honours. Re-encoding drops the
     * tag, so a photo that was upright before the conversion would be on its
     * side after it. The rotation is baked into the pixels instead.
     */
    private fun upright(bitmap: Bitmap, bytes: ByteArray): Bitmap {
        val turn = when (
            runCatching {
                ExifInterface(ByteArrayInputStream(bytes))
                    .getAttributeInt(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL)
            }.getOrDefault(ExifInterface.ORIENTATION_NORMAL)
        ) {
            ExifInterface.ORIENTATION_ROTATE_90 -> 90f
            ExifInterface.ORIENTATION_ROTATE_180 -> 180f
            ExifInterface.ORIENTATION_ROTATE_270 -> 270f
            else -> return bitmap
        }
        return Bitmap.createBitmap(
            bitmap,
            0,
            0,
            bitmap.width,
            bitmap.height,
            Matrix().apply { postRotate(turn) },
            true,
        )
    }

    /** The port of `withExtension` in `services/attachments.ts`. */
    private fun withExtension(name: String, extension: String): String {
        val dot = name.lastIndexOf('.')
        return (if (dot > 0) name.substring(0, dot) else name) + "." + extension
    }

    /**
     * A picture's pixel size, recorded in the manifest so the receiver can
     * reserve its space.
     *
     * Every client draws a placeholder while an attachment is still ciphertext,
     * and without a size that placeholder is one line tall and then jumps to
     * three hundred as the picture arrives - which moves every message below it
     * under a scroll that had already finished. The desktop has recorded this
     * since it started shrinking images on the way out; a picture sent from a
     * phone carried nothing, so it was the one that always jumped, on every
     * client including this one.
     *
     * `inJustDecodeBounds` reads the header alone: no pixels are decoded and no
     * bitmap is allocated. It reports -1 for anything it cannot parse, and a
     * size that is not a size is not recorded.
     */
    private fun pixelSize(bytes: ByteArray): Pair<Int, Int>? = runCatching {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)
        if (bounds.outWidth > 0 && bounds.outHeight > 0) {
            bounds.outWidth to bounds.outHeight
        } else {
            null
        }
    }.getOrNull()

    suspend fun openAttachment(channelId: String, attachment: MessageAttachment): ByteArray =
        E2ee.decryptFileForChannel(
            channelId,
            BetweenUsApi.fetchObject(attachment.url),
            attachment.iv,
            attachment.epoch,
        )

    /**
     * The emoji a message actually uses, and nothing else.
     *
     * A server with two hundred of them must not put two hundred URLs into
     * every "ok". Deduplicated, because the same one three times is one
     * picture. The port of `usedEmoji` in `services/server-emoji.ts`.
     */
    private fun usedEmoji(channelId: String, text: String): List<MessageCustomEmoji> {
        val serverId = Workspace.channel(channelId)?.serverId ?: return emptyList()
        val available = Workspace.emojiFor(serverId)
        if (available.isEmpty()) return emptyList()

        val byName = available.associateBy { it.name }
        return Regex(":([a-z0-9_]{2,32}):")
            .findAll(text)
            .mapNotNull { byName[it.groupValues[1]] }
            .distinctBy { it.name }
            .map { MessageCustomEmoji(it.name, it.url, it.animated) }
            .toList()
    }

    // --- plumbing ---

    private suspend fun read(message: Message): ReadableMessage {
        if (message.deleted) return ReadableMessage(message, MessageBody(""))
        // The server wrote this one and it has no body to open - what it says
        // is in its kind and its author. Handing an empty string to the channel
        // key would only produce a padlock for a row nobody sealed.
        if (!message.hasBody) return ReadableMessage(message, MessageBody(""))
        // A webhook body needs no key and never had one. `decryptForChannel`
        // returns anything that is not an envelope untouched, which is the same
        // path every row written before E2EE already takes - so there is
        // nothing special to do for one here, only something special *not* to
        // do, which was blanking it above.
        val plaintext = E2ee.decryptForChannel(message.channelId, message.content)
        return ReadableMessage(message, MessageBody.decode(plaintext))
    }

    /** One channel's list with [arrivals] laid over it, oldest first. */
    private fun merge(
        existing: List<ReadableMessage>?,
        arrivals: List<ReadableMessage>,
    ): List<ReadableMessage> {
        val fresh = arrivals.map { it.id }.toSet()
        return (existing.orEmpty().filterNot { it.id in fresh } + arrivals)
            .sortedBy { it.message.createdAt }
    }

    /**
     * Told the storage keys of every message that has just gone, so whoever is
     * holding decrypted copies of its files can drop them.
     *
     * A hook rather than a direct call because the decrypted media lives in
     * the app module and this store is in core - and because "who is holding
     * plaintext" is a question this store should not have to know the answer
     * to. The app wires `MediaCache` to it once, at startup.
     */
    var onAttachmentsGone: ((List<String>) -> Unit)? = null

    /**
     * Messages a viewer is currently open over, and the ones the server
     * destroyed while that was true.
     *
     * The problem these solve is a lifecycle one. A one-time message is burned
     * as its viewer opens - deliberately, because closing the viewer is not a
     * promise anybody can keep - and the server answers by destroying the row
     * and saying so. The viewer is drawn inside the message row, so acting on
     * that at once unmounted the very thing somebody had just spent their one
     * look on.
     *
     * Plain sets rather than state: nothing draws from them, and a screen that
     * recomposed every row when a picture was opened would be worse than the
     * bug.
     */
    private val heldOpen = java.util.Collections.synchronizedSet(mutableSetOf<String>())
    private val goneWhileOpen = java.util.Collections.synchronizedSet(mutableSetOf<String>())

    /** Keeps a message on screen while its viewer is open, whatever the server says. */
    fun holdMessage(messageId: String) {
        heldOpen.add(messageId)
    }

    /** Lets it go again, and applies the removal if one arrived in the meantime. */
    fun releaseMessage(messageId: String) {
        heldOpen.remove(messageId)
        if (goneWhileOpen.remove(messageId)) forget(setOf(messageId))
    }

    /**
     * Removes messages from every list this store keeps one in, and tells
     * whoever is holding their decrypted files to let go.
     *
     * The keys have to be read before the rows are dropped: the manifest lives
     * inside the encrypted body, so once the copy here is gone nothing is left
     * that names the files.
     */
    private fun forget(ids: Set<String>) {
        if (ids.isEmpty()) return

        val keys = _messages.value.values
            .flatten()
            .filter { it.id in ids }
            .flatMap { readable -> readable.attachments.map { it.key } }
        if (keys.isNotEmpty()) onAttachmentsGone?.invoke(keys)

        _messages.update { all -> all.mapValues { (_, list) -> list.filterNot { it.id in ids } } }
        scope.launch { Cache.forgetMessages(ids.toList()) }
    }

    /**
     * Drops whatever has outlived a disappearing window - either of them.
     *
     * The server destroys what is past its own stamp and says so, but only to
     * a client connected to hear it, and this one is holding decrypted copies
     * no event can reach if it was asleep. A phone that has been in a pocket
     * since yesterday is exactly the case this exists for.
     *
     * The account's own window is never enforced by deletion anywhere, because
     * it is one-sided - the rows are somebody else's history too. The server
     * leaves them out of a history page; this leaves them out of what has
     * already been fetched, without which switching the setting on appeared to
     * do nothing.
     */
    fun pruneExpired(now: Long = System.currentTimeMillis()) {
        val personal = (Session.state.value as? AuthPhase.SignedIn)?.user?.messageTtlSeconds
        val floor = personal?.let { now - it * 1000L }

        val gone = _messages.value.values.flatten().filter { readable ->
            readable.message.expired(now) ||
                (floor != null && olderThan(readable.message.createdAt, floor))
        }.map { it.id }.toSet()

        forget(gone)
    }

    /**
     * Records this account's look at a one-time message, which is what spends
     * it.
     *
     * Suspending and not caught, because the viewer waits on it before it
     * draws anything: a picture shown when the look was never written down is
     * a look spent only when the network happened to be working, which is not
     * one look. A failure therefore has to reach the caller.
     */
    suspend fun spendLook(messageId: String) {
        BetweenUsApi.burnMessage(messageId)
    }

    /** Whether an ISO stamp is at or before [floor]. Unparseable counts as not. */
    private fun olderThan(iso: String, floor: Long): Boolean =
        runCatching { Instant.parse(iso).toEpochMilli() }.getOrNull()?.let { it <= floor } ?: false

    private fun insert(readable: ReadableMessage) {
        Cache.putMessages(listOf(readable.message))
        _messages.update { all ->
            val channelId = readable.message.channelId
            val existing = all[channelId] ?: return@update all
            if (existing.any { it.id == readable.id }) return@update all
            all + (channelId to (existing + readable).sortedBy { it.message.createdAt })
        }
    }

    private fun replace(readable: ReadableMessage) {
        Cache.putMessages(listOf(readable.message))
        _messages.update { all ->
            val channelId = readable.message.channelId
            val existing = all[channelId] ?: return@update all
            all + (channelId to existing.map { if (it.id == readable.id) readable else it })
        }
    }
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.data.PresenceStatus
import java.time.Duration
import java.time.Instant
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter
import java.time.format.DateTimeParseException
import java.time.format.FormatStyle
import java.time.temporal.ChronoUnit

/**
 * "online", or when somebody was last here, in words.
 *
 * The line under a name in a direct message's header and on the profile sheet.
 * It is read at a glance and never studied, so it says the least that still
 * places the moment: the clock for today, "yesterday" and the clock, the
 * weekday while a weekday still names one day, and the date once it stops.
 *
 * The port of `apps/desktop/src/services/last-seen.ts`, rule for rule - two
 * clients in the same conversation must not disagree about when somebody was
 * last here. If one changes, so does the other.
 *
 * Every timestamp is UTC on the wire and read in the reader's own zone, so the
 * clock in this line is the clock on the wall of whoever is looking at it.
 */
object LastSeen {
    /** Past this, a weekday no longer names exactly one day. */
    private val WEEK: Duration = Duration.ofDays(7)

    private val CLOCK: DateTimeFormatter = DateTimeFormatter.ofLocalizedTime(FormatStyle.SHORT)
    private val WEEKDAY: DateTimeFormatter = DateTimeFormatter.ofPattern("EEEE")
    private val DATE_THIS_YEAR: DateTimeFormatter = DateTimeFormatter.ofPattern("d MMMM")
    private val DATE_WITH_YEAR: DateTimeFormatter = DateTimeFormatter.ofPattern("d MMMM yyyy")

    /**
     * The whole line, ready to draw: `last seen today at 7:07 PM`.
     *
     * Null for an account nobody has ever seen go offline - a new one, or one
     * whose only sessions predate the column. The caller draws nothing at all
     * in that case rather than a date in 1970 or the word "never", which reads
     * as an accusation about somebody who simply signed up this morning.
     */
    fun label(
        iso: String?,
        now: LocalDateTime = LocalDateTime.now(),
        zone: ZoneId = ZoneId.systemDefault(),
    ): String? {
        if (iso.isNullOrBlank()) return null

        val parsed = try {
            LocalDateTime.ofInstant(Instant.parse(iso), zone)
        } catch (_: DateTimeParseException) {
            return null
        }

        // Clamped to now, because a phone whose clock is a few minutes ahead of
        // the server's would otherwise be told somebody was last seen in the
        // future - and "last seen today at 3:34 PM" beside a status bar reading
        // 3:30 reads as broken software rather than as a wrong clock.
        val at = if (parsed.isAfter(now)) now else parsed

        // Every line carries the clock. A day on its own answers "roughly when"
        // and leaves the question people actually have - was that this morning
        // or ten minutes before I looked - to be worked out from nothing.
        val time = at.format(CLOCK)

        // Calendar days apart, not elapsed hours: 00:05 this morning is today
        // however few minutes ago, and 20:00 last night is yesterday however
        // recently. The message list's dividers count the same way - `Day.kt`.
        val days = ChronoUnit.DAYS.between(at.toLocalDate(), now.toLocalDate())

        return when {
            days == 0L -> "last seen today at $time"
            days == 1L -> "last seen yesterday at $time"
            Duration.between(at, now) < WEEK -> "last seen ${at.format(WEEKDAY)} at $time"
            else -> {
                val date = if (at.year == now.year) DATE_THIS_YEAR else DATE_WITH_YEAR
                "last seen ${at.format(date)} at $time"
            }
        }
    }

    /**
     * What the header under a name says, status and last-seen time together.
     *
     * One function rather than a conditional at every call site, because the
     * interesting case is the one that is easy to get wrong: somebody who is
     * *here* is not "last seen a moment ago", and drawing both is saying the
     * same thing twice with the second half already going stale.
     *
     * Idle and do-not-disturb are deliberately not spelled out. The coloured
     * dot beside the name already says which, and a header reading "do not
     * disturb" over a conversation somebody is about to type into is a worse
     * guess than "online" at what the reader wants to know - which is whether a
     * message will be read now.
     */
    fun line(
        status: PresenceStatus,
        lastSeenAt: String?,
        now: LocalDateTime = LocalDateTime.now(),
        zone: ZoneId = ZoneId.systemDefault(),
    ): String? =
        if (status != PresenceStatus.OFFLINE) "online" else label(lastSeenAt, now, zone)

    /** The same line with its first letter raised, for a heading. */
    fun sentence(
        status: PresenceStatus,
        lastSeenAt: String?,
        now: LocalDateTime = LocalDateTime.now(),
        zone: ZoneId = ZoneId.systemDefault(),
    ): String? = line(status, lastSeenAt, now, zone)?.replaceFirstChar { it.uppercase() }

    /**
     * The same fact for a profile sheet, which unlike a header **always** says
     * something.
     *
     * A header may draw nothing: the name is above it, and an empty line under
     * a name is just a name. A sheet cannot - it is a panel opened to answer
     * "who is this", and a blank where the status belongs reads as a sheet that
     * failed to load rather than as an account nobody has seen. That case is
     * commoner than it sounds: a new account, one whose last-seen time is
     * hidden from you, and one you have disqualified yourself from reading all
     * arrive with no timestamp at all.
     *
     * It also spells out idle and do-not-disturb, where [line] collapses both
     * to "online". A header answers "will this be read now"; a sheet is where
     * somebody went looking for detail, and the dot beside it is the only other
     * thing that says which.
     *
     * The mirror of `profilePresence` in `last-seen.ts`.
     */
    fun profile(
        status: PresenceStatus,
        lastSeenAt: String?,
        now: LocalDateTime = LocalDateTime.now(),
        zone: ZoneId = ZoneId.systemDefault(),
    ): String = when (status) {
        PresenceStatus.ONLINE -> "Online"
        PresenceStatus.IDLE -> "Idle"
        PresenceStatus.DND -> "Do not disturb"
        // Only ever your own: everybody else's invisible is resolved to offline
        // before it leaves the server.
        PresenceStatus.INVISIBLE -> "Invisible"
        PresenceStatus.OFFLINE ->
            label(lastSeenAt, now, zone)?.replaceFirstChar { it.uppercase() } ?: "Offline"
    }
}

package com.aatech.betweenus.core.store

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * A channel this app was asked to open, waiting for a screen to open it.
 *
 * Tapping a notification is an intent, and an intent is not a navigation
 * controller. It leaves the channel id here and the shell picks it up - the
 * same shape [PendingInvite] uses, for the same reason. Memory only: a tap that
 * has already been honoured must not reopen on the next launch.
 */
object PendingChannel {

    /**
     * [join] is set only when somebody answered a ringing call. Opening a
     * voice channel from a tapped notification is not consent to open a
     * microphone; pressing Answer on a ringing one is exactly that, and the
     * two arrive down the same path.
     */
    data class Target(val channelId: String, val join: Boolean = false)

    private val _target = MutableStateFlow<Target?>(null)
    val target: StateFlow<Target?> = _target.asStateFlow()

    fun offer(id: String, join: Boolean = false) {
        _target.value = Target(id, join)
    }

    /** Taken once, by whoever opened it. */
    fun clear() {
        _target.value = null
    }
}

package com.aatech.betweenus.core.store

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * An invite this app was opened by, waiting for somewhere to show it.
 *
 * The link arrives as an intent, which is not a screen and cannot ask anybody
 * anything. It is left here instead, and the shell picks it up and opens the
 * card - so a link never joins a server on its own, exactly as on the desktop.
 *
 * Memory only, unlike the desktop's, which survives a page reload because
 * signing in reloads the page there. Here the process stays up across a
 * sign-in, so there is nothing to survive; a link tapped and then abandoned is
 * meant to be forgotten.
 */
object PendingInvite {
    private val _code = MutableStateFlow<String?>(null)
    val code: StateFlow<String?> = _code.asStateFlow()

    fun offer(value: String) {
        _code.value = value
    }

    /** Taken once. A card that was closed must not reopen on the next redraw. */
    fun clear() {
        _code.value = null
    }
}

package com.aatech.betweenus.core.store

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Somewhere other than a channel this app was asked to open.
 *
 * The same shape [PendingChannel] uses and for the same reason - an intent is
 * not a navigation controller - but for the two places a notification can lead
 * that are not a conversation: a friend request, which belongs on the friends
 * screen, and a server somebody was just added to.
 */
object PendingPlace {

    sealed interface Place {
        /** A friend request, or somebody accepting one. */
        data object Friends : Place

        /** Added to a server: its first text channel is where anybody lands. */
        data class Server(val serverId: String) : Place

        /**
         * Somebody is on one of this account's machines.
         *
         * It leads to the machine list rather than to the session. A session
         * that has already started is somebody else's, and joining it from a
         * notification is not what the notification is telling you about -
         * what it is telling you is that you may want to end it.
         */
        data object Remote : Place

        /**
         * A newer release, found by the daily check while the app was closed.
         * It leads to the auto update screen rather than straight to an
         * install: the decision is still somebody's to make.
         */
        data object AutoUpdate : Place
    }

    private val _place = MutableStateFlow<Place?>(null)
    val place: StateFlow<Place?> = _place.asStateFlow()

    fun offer(place: Place) {
        _place.value = place
    }

    /** Taken once, by whoever went there. */
    fun clear() {
        _place.value = null
    }
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.data.PresenceSocket
import com.aatech.betweenus.core.data.PresenceStatus
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * Who is online, who is typing, and who is in which voice channel.
 *
 * The port of `apps/desktop/src/stores/presence.ts`. A typing indicator is
 * given a lifetime here rather than by the server: the protocol only says
 * "somebody typed", and a client that never expires that shows a phantom
 * indicator forever if the person closes their laptop mid-word.
 */
object Presence {
    private const val TYPING_LIFETIME_MS = 6_000L

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    private val _statuses = MutableStateFlow<Map<String, PresenceStatus>>(emptyMap())
    val statuses: StateFlow<Map<String, PresenceStatus>> = _statuses.asStateFlow()

    /** Usernames typing, per channel. */
    private val _typing = MutableStateFlow<Map<String, Set<String>>>(emptyMap())
    val typing: StateFlow<Map<String, Set<String>>> = _typing.asStateFlow()

    /** User ids in each voice channel. */
    private val _voice = MutableStateFlow<Map<String, List<String>>>(emptyMap())
    val voice: StateFlow<Map<String, List<String>>> = _voice.asStateFlow()

    /**
     * userId -> when that person was last here, ISO-8601.
     *
     * Only filled for people who are away: the server sends no timestamp for
     * anybody online, because "online, last seen a moment ago" says one thing
     * twice and the second half is the half that goes stale.
     */
    private val _lastSeen = MutableStateFlow<Map<String, String>>(emptyMap())
    val lastSeen: StateFlow<Map<String, String>> = _lastSeen.asStateFlow()

    private val _self = MutableStateFlow(PresenceStatus.ONLINE)
    val self: StateFlow<PresenceStatus> = _self.asStateFlow()

    private var wired = false
    private var lastTypingSentAt = 0L

    fun start() {
        if (wired) return
        wired = true
        PresenceSocket.on { event ->
            when (event.optString("type")) {
                "status.self" -> _self.value = PresenceStatus.of(event.optString("status"))

                "presence.sync" -> {
                    val users = event.optJSONArray("users")
                    val next = mutableMapOf<String, PresenceStatus>()
                    if (users != null) {
                        for (index in 0 until users.length()) {
                            val user = users.getJSONObject(index)
                            next[user.optString("userId")] =
                                PresenceStatus.of(user.optString("status"))
                        }
                    }
                    _statuses.value = next

                    val voice = event.optJSONArray("voice")
                    val rooms = mutableMapOf<String, List<String>>()
                    if (voice != null) {
                        for (index in 0 until voice.length()) {
                            val room = voice.getJSONObject(index)
                            val ids = room.optJSONArray("userIds")
                            rooms[room.optString("channelId")] =
                                (0 until (ids?.length() ?: 0)).map { ids!!.getString(it) }
                        }
                    }
                    _voice.value = rooms
                }

                "presence.changed" -> event.optJSONObject("user")?.let { user ->
                    val userId = user.optString("userId")
                    _statuses.update { it + (userId to PresenceStatus.of(user.optString("status"))) }

                    // Kept rather than replaced when the event carries nothing:
                    // somebody coming online sends no timestamp, and dropping
                    // the old one would leave the line under their name blank
                    // for the rest of the session once they went away again.
                    val seen = user.optString("lastSeenAt")
                    if (seen.isNotBlank()) _lastSeen.update { it + (userId to seen) }
                }

                "voice.changed" -> event.optJSONObject("voice")?.let { room ->
                    val ids = room.optJSONArray("userIds")
                    _voice.update {
                        it + (room.optString("channelId") to
                            (0 until (ids?.length() ?: 0)).map { index -> ids!!.getString(index) })
                    }
                }

                "typing" -> {
                    val channelId = event.optString("channelId")
                    val username = event.optString("username")
                    _typing.update { it + (channelId to (it[channelId].orEmpty() + username)) }
                    scope.launch {
                        delay(TYPING_LIFETIME_MS)
                        _typing.update { it + (channelId to (it[channelId].orEmpty() - username)) }
                    }
                }
            }
        }
    }

    fun stop() {
        _statuses.value = emptyMap()
        _typing.value = emptyMap()
        _voice.value = emptyMap()
        _lastSeen.value = emptyMap()
    }

    fun statusOf(userId: String): PresenceStatus = _statuses.value[userId] ?: PresenceStatus.OFFLINE

    fun lastSeenOf(userId: String): String? = _lastSeen.value[userId]

    /**
     * "When were these people last here?"
     *
     * Called when a conversation goes on screen or a profile sheet opens. A
     * `presence.sync` carries only the people who *are* here, so the one case
     * a last-seen line exists for is the one case the socket says nothing about
     * until it is asked.
     */
    fun askLastSeen(userIds: List<String>) = PresenceSocket.query(userIds.filter { it.isNotBlank() })

    fun setStatus(status: PresenceStatus) {
        _self.value = status
        PresenceSocket.setStatus(status)
    }

    /**
     * Throttled: the composer calls this on every keystroke, and the indicator
     * lives for six seconds, so one event every three is more than enough.
     */
    fun noteTyping(channelId: String) {
        val now = System.currentTimeMillis()
        if (now - lastTypingSentAt < 3_000) return
        lastTypingSentAt = now
        PresenceSocket.typing(channelId)
    }

    fun voiceMembers(channelId: String): List<String> = _voice.value[channelId].orEmpty()
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.data.ChannelReadReceipt
import java.time.Instant

/**
 * Read receipts, derived from read markers.
 *
 * The port of `apps/desktop/src/features/chat/receipts.ts`, and the same
 * arithmetic for the same reason: the server stores one marker per person per
 * channel - "read up to here" - and never a row per message, so "who has seen
 * this message" is "whose marker is at or past its timestamp".
 *
 * Two questions, and they are not the same one:
 *
 * - [seenBy] - who has seen *this* message. What the dialog lists.
 * - [anchorReceipts] - where each person's face is drawn. Once, on the newest
 *   message of yours they have read. Drawing everybody against every message
 *   would repeat the same four faces down the whole conversation.
 */
object Receipts {
    /** How many faces the row draws before it starts counting instead. */
    const val FACES = 4

    private fun at(iso: String): Long =
        runCatching { Instant.parse(iso).toEpochMilli() }.getOrDefault(0L)

    /** Everyone whose marker is at or past this message. Oldest reader first. */
    fun seenBy(sentAt: String, receipts: List<ChannelReadReceipt>): List<ChannelReadReceipt> {
        val sent = at(sentAt)
        return receipts.filter { at(it.readAt) >= sent }.sortedBy { at(it.readAt) }
    }

    /**
     * messageId -> the readers whose row it is, for [selfId]'s messages only.
     *
     * Somebody else's message never carries a receipt: it is their message that
     * was read, and telling you who else has read it is a different feature.
     */
    fun anchorReceipts(
        messages: List<ReadableMessage>,
        receipts: List<ChannelReadReceipt>,
        selfId: String?,
    ): Map<String, List<ChannelReadReceipt>> {
        if (selfId == null) return emptyMap()
        val mine = messages
            .filter { it.message.author.id == selfId }
            .sortedBy { at(it.message.createdAt) }
        if (mine.isEmpty()) return emptyMap()

        val anchors = mutableMapOf<String, MutableList<ChannelReadReceipt>>()
        for (receipt in receipts) {
            val read = at(receipt.readAt)
            // The newest message this marker has reached. A marker older than
            // everything on screen anchors nowhere, which is the "has not seen
            // it yet" case and draws nothing at all.
            val newest = mine.lastOrNull { at(it.message.createdAt) <= read } ?: continue
            anchors.getOrPut(newest.id) { mutableListOf() }.add(receipt)
        }

        // Oldest reader first within a row, so the faces stop shuffling every
        // time somebody else opens the channel.
        return anchors.mapValues { (_, row) -> row.sortedBy { at(it.readAt) } }
    }

    /** "Seen by Ana", "Seen by Ana and Bo", "Seen by Ana, Bo and 3 others". */
    fun seenByLabel(receipts: List<ChannelReadReceipt>): String {
        val names = receipts.map { it.user.label }
        return when {
            names.isEmpty() -> "Not seen yet"
            names.size == 1 -> "Seen by ${names[0]}"
            names.size == 2 -> "Seen by ${names[0]} and ${names[1]}"
            else -> {
                val rest = names.size - 2
                "Seen by ${names[0]}, ${names[1]} and $rest other" + if (rest == 1) "" else "s"
            }
        }
    }
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.data.BetweenUsApi
import com.aatech.betweenus.core.data.ChatSocket
import com.aatech.betweenus.core.data.AuthPhase
import com.aatech.betweenus.core.data.Session
import com.aatech.betweenus.core.data.StatusEntry
import com.aatech.betweenus.core.data.StatusKind
import com.aatech.betweenus.core.data.StatusRun
import com.aatech.betweenus.core.data.StatusViewer
import com.aatech.betweenus.core.crypto.E2ee
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * The status tray: posts that expire after a day, from accepted friends.
 *
 * The port of `apps/desktop/src/stores/status.ts`, and an object rather than a
 * ViewModel for the same reason [Workspace] is - a socket saying somebody
 * posted has to land somewhere whatever screen is in front of the user.
 *
 * The whole tray is one call and it is re-read rather than patched, which is
 * the bargain the friend list already makes: it is small, it changes rarely,
 * and `seen` and `viewCount` differ per reader - so a carried event would be a
 * different payload per recipient composed on the server.
 *
 * The one thing held locally is which posts *this* device has opened. The
 * server is told immediately, but the ring has to stop glowing under the
 * reader's thumb rather than a round trip later.
 */
object Statuses {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    /** This account's own live posts, oldest first. */
    private val _mine = MutableStateFlow<List<StatusEntry>>(emptyList())
    val mine: StateFlow<List<StatusEntry>> = _mine.asStateFlow()

    private val _runs = MutableStateFlow<List<StatusRun>>(emptyList())

    /** Everybody else's runs, unopened first, with this device's looks folded in. */
    val runs: StateFlow<List<StatusRun>> = _runs.asStateFlow()

    private val _loading = MutableStateFlow(false)
    val loading: StateFlow<Boolean> = _loading.asStateFlow()

    private val _loaded = MutableStateFlow(false)

    /** Whether the tray has been read once, so an empty one can say it is empty. */
    val loaded: StateFlow<Boolean> = _loaded.asStateFlow()

    private val _error = MutableStateFlow<String?>(null)
    val error: StateFlow<String?> = _error.asStateFlow()

    /** Posts this device has opened since it started. See the note above. */
    private val seenHere = MutableStateFlow<Set<String>>(emptySet())

    /**
     * The tray exactly as the server sent it, before this device's own looks
     * are folded in. Kept apart from [runs] so a fresh look re-derives rather
     * than editing what the server said - which is what makes a refresh and a
     * local look compose instead of overwriting each other.
     */
    private var _received: List<StatusRun> = emptyList()

    private var wired = false

    /** Called once a session exists. Idempotent - a reconnect must not re-wire. */
    fun start() {
        if (!wired) {
            wired = true
            ChatSocket.on { event ->
                if (event.optString("type") == "status.changed") scope.launch { refresh() }
            }
            // A phone that was out of signal missed whatever was announced while
            // it was, and nothing replays it. One call covers all of it.
            ChatSocket.onConnection { up -> if (up) scope.launch { refresh() } }
        }
        scope.launch { refresh() }
    }

    fun stop() {
        _mine.value = emptyList()
        _received = emptyList()
        _runs.value = emptyList()
        _loaded.value = false
        _error.value = null
        seenHere.value = emptySet()
    }

    /** Re-reads the tray. Cheap enough to call on resume and on reconnect. */
    suspend fun refresh() {
        _loading.value = true
        runCatching { BetweenUsApi.statusFeed() }
            .onSuccess { feed ->
                // Captions are opened once, here, rather than where each is
                // drawn: decryption suspends and the tray, the player and the
                // content descriptions do not. A post this phone holds no key
                // for keeps the padlock and is drawn like any other, because a
                // friendship younger than the post is not an error.
                _mine.value = feed.mine.map { open(it) }
                _received = feed.others.map { run -> run.copy(statuses = run.statuses.map { open(it) }) }
                _error.value = null
            }
            // A deployment that has not been migrated yet answers 404 here, and
            // a missing tray is not a reason for the home screen to fail.
            .onFailure { _error.value = it.message }
        _loading.value = false
        _loaded.value = true
        recompute()
    }

    /**
     * Posts one, and puts it in the tray without waiting for the announcement
     * to come back around - the poster is looking at the row they posted into.
     */
    suspend fun post(
        kind: StatusKind,
        caption: String? = null,
        background: String? = null,
        durationMs: Long? = null,
        media: ByteArray? = null,
        mediaContentType: String? = null,
    ) {
        // The directory is read now rather than held: this list is the
        // audience, as it stands at the moment of posting, which is what makes
        // a friendship made afterwards not a way into what was posted before
        // it. See `E2ee.sealStatus`.
        val sealed = E2ee.sealStatus(caption, media, BetweenUsApi.statusAudience())
        val entry = BetweenUsApi.postStatus(
            kind = kind,
            caption = sealed.caption,
            background = background,
            durationMs = durationMs,
            media = sealed.media?.ciphertext,
            mediaIv = sealed.media?.iv,
            mediaType = mediaContentType,
            senderDeviceId = sealed.senderDeviceId,
            keys = sealed.keys,
        )
        // With the caption that was typed, not the envelope that came back:
        // this phone has the words already.
        _mine.update { it + entry.copy(caption = caption) }
    }

    /** One post with its caption opened. See the note in [refresh]. */
    private suspend fun open(post: StatusEntry): StatusEntry =
        post.copy(caption = E2ee.openStatusCaption(post))

    /**
     * Records a look, here and on the server.
     *
     * Locally first and unconditionally: the ring has to stop glowing as the
     * post opens. The call behind it is fire-and-forget - a failed marker means
     * the run reads as unwatched again next launch, which is smaller than a
     * viewer that will not advance because a request is in flight.
     */
    fun markSeen(statusId: String) {
        if (statusId in seenHere.value) return
        seenHere.update { it + statusId }
        recompute()
        scope.launch { runCatching { BetweenUsApi.markStatusSeen(statusId) } }
    }

    /** Who opened one of your posts, newest first. Refused to anybody else. */
    suspend fun viewersOf(statusId: String): List<StatusViewer> =
        BetweenUsApi.statusViewers(statusId)

    /** Takes one of your own down early. */
    suspend fun remove(statusId: String) {
        BetweenUsApi.deleteStatus(statusId)
        _mine.update { posts -> posts.filterNot { it.id == statusId } }
    }

    /** One person's run, or null when they have posted nothing live. */
    fun runOf(userId: String): StatusRun? = _runs.value.firstOrNull { it.author.id == userId }

    /**
     * How many posts to draw a ring around this person for, and whether any of
     * them is unopened. Zero means no ring at all.
     *
     * Asked by every avatar in the app, including ones that have never heard of
     * statuses, so it is a cheap lookup rather than a subscription per row.
     */
    fun ringFor(userId: String): Pair<Int, Boolean> {
        if (userId == (Session.state.value as? AuthPhase.SignedIn)?.user?.id) {
            return _mine.value.size to false
        }
        val run = runOf(userId) ?: return 0 to false
        return run.statuses.size to run.unseen
    }

    /**
     * Folds this device's own looks into the server's answer, and orders the
     * tray: unopened runs first, then newest first inside each half.
     *
     * That order is not a preference. Sorted purely by time, a run you have
     * already watched jumps above one you have not the moment its author posts
     * again, and the thing under your thumb stops being the thing you opened
     * the screen for.
     */
    private fun recompute() {
        val looked = seenHere.value
        _runs.value = _received
            .map { run ->
                val statuses = run.statuses.map { it.copy(seen = it.seen || it.id in looked) }
                run.copy(statuses = statuses, unseen = statuses.any { !it.seen })
            }
            // ISO-8601 in UTC sorts lexicographically, so the timestamps are
            // compared as strings rather than parsed back into instants.
            .sortedWith(compareByDescending<StatusRun> { it.unseen }.thenByDescending { it.latestAt })
    }
}

package com.aatech.betweenus.core.store

import android.content.Context
import android.content.SharedPreferences
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Persisted theme and appearance preferences for BetweenUs Android.
 *
 * Saves selected theme, system auto-sync state, dynamic wallpaper theming (Material You),
 * and custom accent tint.
 */
object ThemePreferences {
    private lateinit var prefs: SharedPreferences

    private const val PREFS_NAME = "betweenus.theme"
    private const val KEY_THEME = "selectedTheme"
    private const val KEY_FOLLOW_SYSTEM = "followSystem"
    private const val KEY_DYNAMIC_COLOR = "dynamicColor"
    private const val KEY_ACCENT = "customAccentId"

    private val _selectedTheme = MutableStateFlow("dark")
    val selectedTheme: StateFlow<String> = _selectedTheme.asStateFlow()

    private val _followSystem = MutableStateFlow(false)
    val followSystem: StateFlow<Boolean> = _followSystem.asStateFlow()

    private val _dynamicColor = MutableStateFlow(false)
    val dynamicColor: StateFlow<Boolean> = _dynamicColor.asStateFlow()

    private val _customAccentId = MutableStateFlow("default")
    val customAccentId: StateFlow<String> = _customAccentId.asStateFlow()

    fun init(context: Context) {
        prefs = context.applicationContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        _selectedTheme.value = prefs.getString(KEY_THEME, "dark") ?: "dark"
        _followSystem.value = prefs.getBoolean(KEY_FOLLOW_SYSTEM, false)
        _dynamicColor.value = prefs.getBoolean(KEY_DYNAMIC_COLOR, false)
        _customAccentId.value = prefs.getString(KEY_ACCENT, "default") ?: "default"
    }

    fun setTheme(themeId: String) {
        _selectedTheme.value = themeId
        _followSystem.value = false
        _dynamicColor.value = false
        if (::prefs.isInitialized) {
            prefs.edit()
                .putString(KEY_THEME, themeId)
                .putBoolean(KEY_FOLLOW_SYSTEM, false)
                .putBoolean(KEY_DYNAMIC_COLOR, false)
                .apply()
        }
    }

    fun setFollowSystem(follow: Boolean) {
        _followSystem.value = follow
        if (follow) {
            _dynamicColor.value = false
        }
        if (::prefs.isInitialized) {
            prefs.edit()
                .putBoolean(KEY_FOLLOW_SYSTEM, follow)
                .apply {
                    if (follow) putBoolean(KEY_DYNAMIC_COLOR, false)
                }
                .apply()
        }
    }

    fun setDynamicColor(dynamic: Boolean) {
        _dynamicColor.value = dynamic
        if (dynamic) {
            _followSystem.value = false
        }
        if (::prefs.isInitialized) {
            prefs.edit()
                .putBoolean(KEY_DYNAMIC_COLOR, dynamic)
                .apply {
                    if (dynamic) putBoolean(KEY_FOLLOW_SYSTEM, false)
                }
                .apply()
        }
    }

    fun setCustomAccent(accentId: String) {
        _customAccentId.value = accentId
        if (::prefs.isInitialized) {
            prefs.edit().putString(KEY_ACCENT, accentId).apply()
        }
    }
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.crypto.E2ee
import com.aatech.betweenus.core.data.Channel
import com.aatech.betweenus.core.data.ChannelType
import com.aatech.betweenus.core.data.BlockedUser
import com.aatech.betweenus.core.data.ChatSocket
import com.aatech.betweenus.core.data.DirectChannel
import com.aatech.betweenus.core.data.Friend
import com.aatech.betweenus.core.data.BetweenUsApi
import com.aatech.betweenus.core.data.ServerEmoji
import com.aatech.betweenus.core.data.ServerMember
import com.aatech.betweenus.core.data.ServerWithRole
import com.aatech.betweenus.core.data.Session
import com.aatech.betweenus.core.data.UserSummary
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * What the app is looking at: the servers this account is in, their channels,
 * the direct-message list, the friend list and the unread counts.
 *
 * The port of the parts of `apps/desktop/src/stores/chat.ts` that are not
 * messages. It is an object rather than a ViewModel because a socket event
 * about a server the user is not currently looking at still has to land
 * somewhere - a store scoped to a screen would miss every one of them.
 */
object Workspace {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    private val _servers = MutableStateFlow<List<ServerWithRole>>(emptyList())
    val servers: StateFlow<List<ServerWithRole>> = _servers.asStateFlow()

    /** Channels by server id. Loaded when a server is first opened, then kept. */
    private val _channels = MutableStateFlow<Map<String, List<Channel>>>(emptyMap())
    val channels: StateFlow<Map<String, List<Channel>>> = _channels.asStateFlow()

    private val _directChannels = MutableStateFlow<List<DirectChannel>>(emptyList())
    val directChannels: StateFlow<List<DirectChannel>> = _directChannels.asStateFlow()

    private val _friends = MutableStateFlow<List<Friend>>(emptyList())
    val friends: StateFlow<List<Friend>> = _friends.asStateFlow()

    /**
     * Everyone this account has blocked.
     *
     * Not cached to disk, unlike the lists above. It is read on one settings
     * screen rather than drawn on every frame, so the one round trip it costs
     * to open that screen is cheaper than a codec and a round-trip test for a
     * list nobody is waiting on.
     */
    private val _blocked = MutableStateFlow<List<BlockedUser>>(emptyList())
    val blocked: StateFlow<List<BlockedUser>> = _blocked.asStateFlow()

    private val _members = MutableStateFlow<Map<String, List<ServerMember>>>(emptyMap())
    val members: StateFlow<Map<String, List<ServerMember>>> = _members.asStateFlow()

    private val _unread = MutableStateFlow<Map<String, Int>>(emptyMap())
    val unread: StateFlow<Map<String, Int>> = _unread.asStateFlow()

    /** serverId -> that server's own emoji. */
    private val _emoji = MutableStateFlow<Map<String, List<ServerEmoji>>>(emptyMap())
    val emoji: StateFlow<Map<String, List<ServerEmoji>>> = _emoji.asStateFlow()

    private val _loading = MutableStateFlow(false)
    val loading: StateFlow<Boolean> = _loading.asStateFlow()

    private val _error = MutableStateFlow<String?>(null)
    val error: StateFlow<String?> = _error.asStateFlow()

    private var wired = false

    /** Called once a session exists. Idempotent - a reconnect must not re-wire. */
    fun start() {
        if (!wired) {
            wired = true
            ChatSocket.on { event ->
                when (event.optString("type")) {
                    // A request, an acceptance, a removal - and a block, which
                    // the server announces as a removal on purpose, so the far
                    // side is never told which of the two it was.
                    "friends.changed" -> scope.launch {
                        loadFriends()
                        // The conversation list too: a block hides a DM from
                        // both sides, and leaving a dead channel in the rail
                        // would leave a row that answers 404 when it is tapped.
                        loadDirectChannels()
                    }

                    // A picture or a name changed. Patched in place rather
                    // than refetched: the event carries the four fields every
                    // list here holds, and going back to the API for them would
                    // be three calls to learn what already arrived.
                    "user.updated" -> event.optJSONObject("user")
                        ?.let { UserSummary.from(it) }
                        ?.let {
                            patchProfile(it)
                            // Their own account, changed on another device: the
                            // avatar in the drawer is drawn from the session.
                            Session.applyProfile(it)
                        }

                    "server.updated" -> {
                        val serverId = event.optString("serverId")
                        val iconUrl =
                            if (event.isNull("iconUrl")) null else event.optString("iconUrl")
                        _servers.update { list ->
                            list.map {
                                if (it.id == serverId) {
                                    it.copy(name = event.optString("name"), iconUrl = iconUrl)
                                } else {
                                    it
                                }
                            }
                        }
                        scope.launch { Cache.putServers(_servers.value) }
                    }

                    "server.members.changed" -> scope.launch {
                        val serverId = event.optString("serverId")
                        // The event goes to everyone watching the server *and*
                        // to whoever joined or left it - so a server we have
                        // never heard of means this account was just added to
                        // one. Refreshing the member list of a server that is
                        // not in our list yet does nothing visible, which is
                        // why being added from another client used to need the
                        // app restarting before it showed up.
                        if (_servers.value.none { it.id == serverId }) refresh()
                        else loadMembers(serverId, force = true)
                    }
                }
            }

            // A socket that has been away has missed whatever happened while it
            // was gone, and nothing replays it. Re-reading on every reconnect is
            // one round trip and covers every event that was dropped - which on
            // a phone, going in and out of signal, is the common case rather
            // than the exception.
            ChatSocket.onConnection { up -> if (up) scope.launch { refresh() } }
        }
        scope.launch {
            hydrate()
            refresh()
        }
    }

    /**
     * Puts last session's workspace on screen before the network is asked for
     * anything. Everything here is replaced by [refresh] a moment later - the
     * point is only that the moment has something in it other than an empty rail.
     */
    private suspend fun hydrate() {
        if (_servers.value.isNotEmpty()) return
        Cache.servers()?.let { _servers.value = it }
        Cache.channels()?.let { _channels.value = it }
        Cache.directChannels()?.let { _directChannels.value = it }
        Cache.friends()?.let { _friends.value = it }
        Cache.members()?.let { _members.value = it }
        Cache.unread()?.let { _unread.value = it }
    }

    fun stop() {
        _servers.value = emptyList()
        _channels.value = emptyMap()
        _directChannels.value = emptyList()
        _friends.value = emptyList()
        _blocked.value = emptyList()
        _members.value = emptyMap()
        _unread.value = emptyMap()
    }

    /** Re-reads everything. Cheap enough to call on resume and on reconnect. */
    suspend fun refresh() {
        _loading.value = true
        try {
            val servers = BetweenUsApi.servers()
            _servers.value = servers
            Cache.putServers(servers)
            ChatSocket.syncServers(servers.map { it.id })
            // Every server's channels, not only the one on screen: the socket
            // has to be subscribed to all of them or a message in another
            // channel never arrives and there is nothing to badge.
            servers.forEach { loadChannels(it.id) }
            servers.forEach { loadEmoji(it.id) }
            // And the member lists. Presence reports who is in a voice channel
            // as user ids, and the member list is the only thing that turns one
            // into a name - so without this every voice roster in the sidebar
            // read "Someone" until the members screen had been opened once.
            servers.forEach { loadMembers(it.id, force = true) }
            loadDirectChannels()
            loadFriends()
            loadBlocked()
            loadUnread()
            resubscribe()
            _error.value = null
        } catch (error: Exception) {
            _error.value = Session.messageOf(error)
        } finally {
            _loading.value = false
        }
    }

    suspend fun loadChannels(serverId: String) {
        runCatching { BetweenUsApi.channels(serverId) }.onSuccess { channels ->
            _channels.update { it + (serverId to channels) }
            Cache.putChannels(_channels.value)
            resubscribe()
        }
    }

    suspend fun loadDirectChannels() {
        runCatching { BetweenUsApi.directChannels() }.onSuccess {
            _directChannels.value = it
            Cache.putDirectChannels(it)
            resubscribe()
        }
    }

    suspend fun loadFriends() {
        runCatching { BetweenUsApi.friends() }.onSuccess {
            _friends.value = it
            Cache.putFriends(it)
        }
    }

    suspend fun loadBlocked() {
        // A deployment that has not been redeployed yet answers 404 here, and a
        // missing block list is not a reason for a settings screen to fail.
        runCatching { BetweenUsApi.blocked() }.onSuccess { _blocked.value = it }
    }

    /**
     * Blocks somebody, and takes them out of every list this store holds.
     *
     * Done here rather than left to the announcement that follows, because that
     * announcement is deliberately indistinguishable from an ordinary removal -
     * so the screen the block was pressed on has to be right immediately, not a
     * round trip later.
     */
    suspend fun block(userId: String) {
        val entry = BetweenUsApi.blockUser(userId)
        _blocked.update { listOf(entry) + it.filterNot { existing -> existing.user.id == userId } }
        _friends.update { list -> list.filterNot { it.user.id == userId } }
        _directChannels.update { list -> list.filterNot { it.participant.id == userId } }
        Cache.putFriends(_friends.value)
        Cache.putDirectChannels(_directChannels.value)
        resubscribe()
    }

    /**
     * Lifts a block. It does not restore the friendship the block ended.
     *
     * The conversation comes back with its history, so the lists are re-read
     * rather than reconstructed - this phone stopped being told about that
     * channel while the block stood and has nothing to reconstruct from.
     */
    suspend fun unblock(userId: String) {
        BetweenUsApi.unblockUser(userId)
        _blocked.update { list -> list.filterNot { it.user.id == userId } }
        loadDirectChannels()
        loadFriends()
    }

    /**
     * A server's own emoji, kept per server.
     *
     * Fetched with the channels rather than lazily: the list decides what a
     * `:name:` in an arriving message means, so it has to be in hand before the
     * first message renders rather than after it.
     */
    suspend fun loadEmoji(serverId: String) {
        runCatching { BetweenUsApi.serverEmoji(serverId) }.onSuccess { list ->
            _emoji.value = _emoji.value + (serverId to list)
        }
    }

    /** What this phone knows for a server. Empty until it has been fetched. */
    fun emojiFor(serverId: String?): List<ServerEmoji> =
        serverId?.let { _emoji.value[it] }.orEmpty()

    suspend fun loadUnread() {
        runCatching { BetweenUsApi.unread() }.onSuccess { list ->
            _unread.value = list.associate { it.channelId to it.count }
            Cache.putUnread(_unread.value)
        }
    }

    suspend fun loadMembers(serverId: String, force: Boolean = false) {
        if (!force && _members.value.containsKey(serverId)) return
        runCatching { BetweenUsApi.members(serverId) }.onSuccess { members ->
            _members.update { it + (serverId to members) }
            Cache.putMembers(_members.value)
        }
    }

    /**
     * Repaint one account's face wherever this store holds a copy of it: the
     * member list of every server, the conversation list and the friend list.
     *
     * [Conversation] keeps the copies inside message history and does its own.
     */
    fun patchProfile(user: UserSummary) {
        _members.update { byServer ->
            byServer.mapValues { (_, list) ->
                list.map {
                    if (it.userId == user.id) {
                        it.copy(
                            username = user.username,
                            displayName = user.displayName,
                            avatarUrl = user.avatarUrl,
                        )
                    } else {
                        it
                    }
                }
            }
        }
        _directChannels.update { list ->
            list.map { if (it.participant.id == user.id) it.copy(participant = user) else it }
        }
        _friends.update { list ->
            list.map { if (it.user.id == user.id) it.copy(user = user) else it }
        }
        scope.launch {
            Cache.putMembers(_members.value)
            Cache.putDirectChannels(_directChannels.value)
            Cache.putFriends(_friends.value)
        }
    }

    /** Subscribes the socket to every text channel this account can read. */
    private fun resubscribe() {
        val text = _channels.value.values.flatten()
            .filter { it.type == ChannelType.TEXT }
            .map { it.id }
        ChatSocket.syncSubscriptions(text + _directChannels.value.map { it.channelId })
    }

    fun channelsOf(serverId: String): List<Channel> = _channels.value[serverId].orEmpty()

    fun channel(channelId: String): Channel? =
        _channels.value.values.flatten().firstOrNull { it.id == channelId }

    fun server(serverId: String?): ServerWithRole? =
        serverId?.let { id -> _servers.value.firstOrNull { it.id == id } }

    /**
     * Sets a server's disappearing window, and puts the answer back in the
     * list every screen reads from.
     *
     * Patched here rather than waiting for a refetch, because `server.updated`
     * carries a name and a picture and not this - and adding it there would
     * broadcast one server's retention policy to every member on every change,
     * to update a control almost none of them are looking at.
     */
    suspend fun setServerMessageWindow(serverId: String, seconds: Int?) {
        val updated = BetweenUsApi.setServerMessageWindow(serverId, seconds)
        _servers.update { list -> list.map { if (it.id == updated.id) updated else it } }
        Cache.putServers(_servers.value)
    }

    fun directChannel(channelId: String): DirectChannel? =
        _directChannels.value.firstOrNull { it.channelId == channelId }

    fun unreadOf(channelId: String): Int = _unread.value[channelId] ?: 0

    fun unreadOfServer(serverId: String): Int =
        channelsOf(serverId).sumOf { unreadOf(it.id) }

    fun noteUnread(channelId: String, delta: Int) {
        _unread.update { it + (channelId to ((it[channelId] ?: 0) + delta)) }
        Cache.putUnread(_unread.value)
    }

    fun markRead(channelId: String) {
        _unread.update { it - channelId }
        Cache.putUnread(_unread.value)
        scope.launch { runCatching { BetweenUsApi.markChannelRead(channelId) } }
    }

    /**
     * The same channel, read on one of this account's other devices.
     *
     * Everything [markRead] does except telling the server, which already knows
     * - it is what sent this. Posting the marker back would have every device
     * answering every other device's read with one of its own, for as long as
     * they are all awake.
     */
    fun noteReadElsewhere(channelId: String) {
        if (_unread.value[channelId] == null) return
        _unread.update { it - channelId }
        Cache.putUnread(_unread.value)
    }

    // --- mutations ---

    suspend fun createServer(name: String): ServerWithRole =
        BetweenUsApi.createServer(name).also { refresh() }

    suspend fun joinServer(code: String): ServerWithRole =
        BetweenUsApi.joinServer(code).also { refresh() }

    suspend fun leaveServer(serverId: String) {
        BetweenUsApi.leaveServer(serverId)
        refresh()
    }

    suspend fun deleteServer(serverId: String) {
        BetweenUsApi.deleteServer(serverId)
        refresh()
    }

    suspend fun createChannel(
        serverId: String,
        name: String,
        type: ChannelType,
        isPrivate: Boolean,
        memberIds: List<String>,
    ): Channel {
        val channel = BetweenUsApi.createChannel(serverId, name, type, isPrivate, memberIds)
        loadChannels(serverId)
        // Key it now, so it is usable by whoever opens it first rather than by
        // whoever happens to type in it first.
        if (channel.type == ChannelType.TEXT) runCatching { E2ee.keyChannel(channel.id) }
        return channel
    }

    suspend fun deleteChannel(channel: Channel) {
        BetweenUsApi.deleteChannel(channel.id)
        channel.serverId?.let { loadChannels(it) }
    }

    suspend fun openDirect(userId: String): DirectChannel =
        BetweenUsApi.openDirectChannel(userId).also { loadDirectChannels() }
}

package com.aatech.betweenus.core.crypto

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Interop with the other two clients.
 *
 * The constants below were produced by `apps/desktop/src/services/e2ee-crypto.ts`
 * running under Node, and are opened here by the Kotlin port. That is the only
 * check worth having: an implementation that is self-consistent but disagrees
 * with WebCrypto about the HKDF salt, the JWK coordinate padding or the GCM tag
 * length passes every round trip of its own and still cannot read a single
 * message anybody else sent.
 */
class CryptoInteropTest {

    private val alicePublic = """{"key_ops":[],"ext":true,"kty":"EC","x":"GhoGdz3ZlCS1kzWmWqChzPy5ZeUJFYP4v5hhNCHslq4","y":"cRuXtu41UymTZ8RJyp3SqiFJoKrK0Hk_-X-RZWOA1BM","crv":"P-256"}"""
    private val alicePrivate = """{"key_ops":["deriveBits"],"ext":true,"kty":"EC","x":"GhoGdz3ZlCS1kzWmWqChzPy5ZeUJFYP4v5hhNCHslq4","y":"cRuXtu41UymTZ8RJyp3SqiFJoKrK0Hk_-X-RZWOA1BM","crv":"P-256","d":"EL3svFYNqog8jWC3k7M_zPsmxhOWPufAu8YcucsJnqs"}"""
    private val bobPublic = """{"key_ops":[],"ext":true,"kty":"EC","x":"oR0iqVZXu7fnps6FvfKK2auXEX-LppwAiklWZizSqck","y":"f_m3aR0bCNk7W3F1OUwBE_LJ-faqSo_rHkZgUy8Pqdk","crv":"P-256"}"""
    private val bobPrivate = """{"key_ops":["deriveBits"],"ext":true,"kty":"EC","x":"oR0iqVZXu7fnps6FvfKK2auXEX-LppwAiklWZizSqck","y":"f_m3aR0bCNk7W3F1OUwBE_LJ-faqSo_rHkZgUy8Pqdk","crv":"P-256","d":"-6nNC4nY25ox_WjnQ9BE_8PTwkVqm6Bm6O-mrSJCSFM"}"""

    private val channelKey = "5s1CyOUmHg45joTlUG0O4oshw7YdMXUg5vaVxiX6HwE="

    @Test
    fun `unwraps a channel key the desktop sealed`() {
        val opened = Crypto.unwrapChannelKey(
            Crypto.Wrapped("cAsOKmra+Dg4JFx9T8FhvMmxEkB1zrk9sFsFsaGJizEEPVOPHKVOJm+0shN3mia4", "Kud3/ImK6g43o1X0"),
            bobPrivate,
            alicePublic,
        )
        assertEquals(channelKey, opened)
    }

    @Test
    fun `decrypts a message the desktop encrypted`() {
        val text = Crypto.decrypt("QWYtiov88E51eiFj5uQlrj0gJ1qHC6TKOp17tREQnKPwjXbs194=", "FApZx/bMpvhoVSuf", channelKey)
        assertEquals("the desktop wrote this", text)
    }

    @Test
    fun `opens an identity backup the desktop sealed`() {
        val pair = Crypto.openIdentity(
            salt = "Nh3JF1S1JEZFKQ6JbgMtkg==",
            iv = "/MtrnCK3nyHrZ0aE",
            ciphertext = "",
            secret = "correct horse battery staple",
            iterations = 600000,
        )
        assertEquals(alicePublic, pair.publicKey)
        assertEquals(alicePrivate, pair.privateKey)
    }

    /**
     * The other direction. ECDH is symmetric, so wrapping from Bob's side and
     * opening from Alice's proves the two derivations agreed rather than that
     * one implementation is consistent with itself.
     */
    @Test
    fun `seals a channel key the desktop keys can open`() {
        val wrapped = Crypto.wrapChannelKey(channelKey, bobPrivate, alicePublic)
        assertEquals(channelKey, Crypto.unwrapChannelKey(wrapped, alicePrivate, bobPublic))
    }

    @Test
    fun `a freshly generated identity round-trips through JWK`() {
        val pair = Crypto.generateIdentity()
        val key = Crypto.generateChannelKey()
        val wrapped = Crypto.wrapChannelKey(key, pair.privateKey, alicePublic)
        assertEquals(key, Crypto.unwrapChannelKey(wrapped, alicePrivate, pair.publicKey))
    }

    @Test
    fun `content sealed here opens here`() {
        val sealed = Crypto.encrypt("hello from the phone", channelKey)
        assertEquals(
            "hello from the phone",
            Crypto.decrypt(Crypto.base64(sealed.ciphertext), sealed.iv, channelKey),
        )
    }
}

package com.aatech.betweenus.core.data

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The three answers a forgotten password can get, and the one way of being
 * wrong about them that matters.
 *
 * `RESET` is the only outcome that puts somebody in front of a new-password
 * form, and it is the one an administrator has to have authorised. So the
 * failure worth proving impossible is a payload this client does not recognise
 * being read *as* `RESET` - a client that guessed that way would offer the form
 * to anybody who could make the server answer something unexpected. Everything
 * unknown reads as `EMAILED`, which shows a sentence and does nothing.
 */
class AccountRecoveryTest {

    @Test
    fun `an administrator's window carries a token`() {
        val answer = ForgotPasswordAnswer.from(
            JSONObject("""{"outcome":"reset","resetToken":"tok_abc"}"""),
        )
        assertEquals(ForgotPasswordOutcome.RESET, answer.outcome)
        assertEquals("tok_abc", answer.resetToken)
    }

    @Test
    fun `a deployment with no mail server says so`() {
        val answer = ForgotPasswordAnswer.from(
            JSONObject("""{"outcome":"unavailable","message":"Ask your administrator."}"""),
        )
        assertEquals(ForgotPasswordOutcome.UNAVAILABLE, answer.outcome)
        assertEquals("Ask your administrator.", answer.message)
        assertNull(answer.resetToken)
    }

    @Test
    fun `an emailed link carries nothing else`() {
        val answer = ForgotPasswordAnswer.from(JSONObject("""{"outcome":"emailed"}"""))
        assertEquals(ForgotPasswordOutcome.EMAILED, answer.outcome)
        assertNull(answer.resetToken)
        assertNull(answer.message)
    }

    @Test
    fun `nothing unrecognised is ever read as an authorised reset`() {
        val nonsense = listOf(
            """{}""",
            """{"outcome":""}""",
            """{"outcome":"RESET"}""",
            """{"outcome":"something-new"}""",
            """{"outcome":null}""",
            // A token with no outcome saying so is not an authorisation.
            """{"resetToken":"tok_abc"}""",
        )
        for (body in nonsense) {
            assertEquals(
                "$body must not read as an authorised reset",
                ForgotPasswordOutcome.EMAILED,
                ForgotPasswordAnswer.from(JSONObject(body)).outcome,
            )
        }
    }

    /**
     * The availability hint may save the sign-up form a round trip; it must
     * never invent a refusal. A missing or malformed field reads as "not
     * available" here, and the screen shows a hint - the registration itself is
     * still gated by the unique index on the server.
     */
    @Test
    fun `username availability parses both answers`() {
        val free = UsernameAvailability.from(
            JSONObject("""{"username":"ada","available":true}"""),
        )
        assertTrue(free.available)
        assertEquals("ada", free.username)
        assertNull(free.reason)

        val taken = UsernameAvailability.from(
            JSONObject("""{"username":"ada","available":false,"reason":"taken"}"""),
        )
        assertEquals(false, taken.available)
        assertEquals("taken", taken.reason)

        val malformed = UsernameAvailability.from(JSONObject("""{"username":"ada"}"""))
        assertEquals(false, malformed.available)
    }

    @Test
    fun `a blocked entry names the person and when`() {
        val entry = BlockedUser.from(
            JSONObject(
                """
                {
                  "user": {
                    "id": "u1",
                    "username": "ada",
                    "displayName": "Ada Lovelace",
                    "avatarUrl": null
                  },
                  "blockedAt": "2026-08-28T10:00:00.000Z"
                }
                """.trimIndent(),
            ),
        )
        assertEquals("u1", entry.user.id)
        assertEquals("Ada Lovelace", entry.user.label)
        assertNull(entry.user.avatarUrl)
        assertEquals("2026-08-28T10:00:00.000Z", entry.blockedAt)
    }
}

package com.aatech.betweenus.core.data

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Everything the local cache writes has to come back off disk as what went in.
 *
 * `from` is written against the server's JSON and `toJson` against `from`, so
 * the two drift the moment a field is added to one and not the other - and the
 * symptom is not a crash, it is a message whose author has no avatar or a
 * server whose permissions are silently empty until the next refresh. A
 * round trip catches it here instead.
 */
class CacheCodecTest {
    private val user = UserSummary(
        id = "u1",
        username = "ada",
        displayName = "Ada Lovelace",
        avatarUrl = "https://example.test/a.png",
    )

    private fun <T> roundTrip(value: T, toJson: (T) -> JSONObject, from: (JSONObject) -> T) {
        assertEquals(value, from(JSONObject(toJson(value).toString())))
    }

    @Test
    fun `user survives a round trip`() {
        roundTrip(user, UserSummary::toJson, UserSummary::from)
        roundTrip(user.copy(avatarUrl = null), UserSummary::toJson, UserSummary::from)
    }

    @Test
    fun `server survives a round trip`() {
        val server = ServerWithRole(
            id = "s1",
            name = "BetweenUs",
            slug = "betweenus",
            iconUrl = null,
            ownerId = "u1",
            messageTtlSeconds = 86_400,
            role = ServerRole.ADMIN,
            permissions = listOf("SEND_MESSAGE", "MANAGE_ROLE"),
        )
        roundTrip(server, ServerWithRole::toJson, ServerWithRole::from)
        // Off is a value here, not an absence, and it has to survive the cache
        // as one: a window that came back as "an hour" after a restart because
        // null did not round-trip would delete history nobody asked to lose.
        roundTrip(server.copy(messageTtlSeconds = null), ServerWithRole::toJson, ServerWithRole::from)
    }

    @Test
    fun `member survives a round trip`() {
        val member = ServerMember(
            userId = "u1",
            username = "ada",
            displayName = "Ada",
            avatarUrl = null,
            role = ServerRole.MODERATOR,
            permissions = listOf("VIEW_CHANNEL"),
            grantedPermissions = listOf("DELETE_MESSAGE"),
            deniedPermissions = emptyList(),
            roleIds = listOf("role-1", "role-2"),
        )
        roundTrip(member, ServerMember::toJson, ServerMember::from)
    }

    @Test
    fun `channel survives a round trip`() {
        val channel = Channel(
            id = "c1",
            serverId = "s1",
            name = "general",
            type = ChannelType.VOICE,
            topic = "anything",
            isPrivate = true,
        )
        roundTrip(channel, Channel::toJson, Channel::from)
        // A DM has no server and no topic, and both are dropped from the JSON
        // rather than written as the string "null".
        roundTrip(
            channel.copy(serverId = null, topic = null, type = ChannelType.DM),
            Channel::toJson,
            Channel::from,
        )
    }

    @Test
    fun `direct channel and friend survive a round trip`() {
        roundTrip(DirectChannel("c1", user), DirectChannel::toJson, DirectChannel::from)
        roundTrip(
            Friend(user, FriendshipStatus.PENDING, "incoming"),
            Friend::toJson,
            Friend::from,
        )
        roundTrip(Friend(user, FriendshipStatus.ACCEPTED, null), Friend::toJson, Friend::from)
    }

    @Test
    fun `a voice note survives a round trip, waveform and all`() {
        val voice = MessageAttachment(
            key = "k1",
            url = "/api/v1/uploads/k1",
            name = "voice_20260830_011311.ogg",
            contentType = "audio/ogg",
            size = 97_280,
            iv = "aXY",
            epoch = 2,
            duration = 5.4f,
            waveform = listOf(0.08f, 0.5f, 1f, 0.25f),
        )
        roundTrip(voice, MessageAttachment::toJson, MessageAttachment::from)

        // The two signals that make something a voice note rather than a file
        // with a player stapled to it. Either is enough, and neither may catch
        // a music track somebody chose to share.
        assertTrue(voice.isVoiceNote)
        assertTrue(voice.copy(waveform = emptyList()).isVoiceNote)
        assertFalse(voice.copy(name = "interview.mp3", waveform = emptyList()).isVoiceNote)
        assertFalse(voice.copy(contentType = "video/mp4", waveform = emptyList()).isVoiceNote)
        // The name check must not match something merely starting with the word.
        assertFalse(voice.copy(name = "voice_memo.ogg", waveform = emptyList()).isVoiceNote)

        // Audio picked off the phone has no waveform and must survive as none -
        // an empty list that came back as a single zero bar would draw a
        // waveform claiming the recording was silent.
        val picked = voice.copy(name = "song.mp3", contentType = "audio/mpeg", waveform = emptyList(), duration = null)
        roundTrip(picked, MessageAttachment::toJson, MessageAttachment::from)
        assertTrue(MessageAttachment.from(picked.toJson()).waveform.isEmpty())
    }

    @Test
    fun `message survives a round trip, envelope and all`() {
        val message = Message(
            id = "m1",
            channelId = "c1",
            content = """{"v":1,"epoch":2,"iv":"aXY","ct":"Y3Q"}""",
            author = user,
            createdAt = "2026-08-15T10:00:00.000Z",
            editedAt = "2026-08-15T10:01:00.000Z",
            deletedAt = null,
            deletedBy = null,
            pinnedAt = "2026-08-15T10:02:00.000Z",
            reactions = listOf(MessageReaction("👍", listOf("u1", "u2"))),
        )
        roundTrip(message, Message::toJson, Message::from)

        val tombstone = message.copy(
            content = "",
            editedAt = null,
            deletedAt = "2026-08-15T10:03:00.000Z",
            deletedBy = user,
            pinnedAt = null,
            reactions = emptyList(),
        )
        roundTrip(tombstone, Message::toJson, Message::from)

        // A one-time message with a window on it. Both fields decide whether
        // something is drawn or destroyed, so both have to survive the cache:
        // a `viewOnce` that came back false would draw a picture the sender
        // was promised nobody would get twice.
        val fleeting = message.copy(
            expiresAt = "2026-08-16T10:00:00.000Z",
            viewOnce = true,
            viewedBy = listOf("u2", "u3"),
        )
        roundTrip(fleeting, Message::toJson, Message::from)

        // Whose look has been spent decides whether this device draws the card
        // or the word "Opened", so an empty list has to survive as an empty
        // list. Coming back as a single blank id would tell one account it had
        // already looked at something it had never been shown.
        val untouched = fleeting.copy(viewedBy = emptyList())
        roundTrip(untouched, Message::toJson, Message::from)
        assertTrue(Message.from(untouched.toJson()).viewedBy.isEmpty())
    }

    @Test
    fun `a window that has closed is one the screen stops drawing`() {
        val at = java.time.Instant.parse("2026-08-15T12:00:00.000Z").toEpochMilli()
        val message = Message(
            id = "m2",
            channelId = "c1",
            content = "",
            author = user,
            createdAt = "2026-08-15T10:00:00.000Z",
            editedAt = null,
            deletedAt = null,
            deletedBy = null,
            pinnedAt = null,
            reactions = emptyList(),
        )

        // No window at all is the common case, and it never expires.
        assertFalse(message.expired(at))

        // A stamp in the past has closed; one in the future has not.
        assertTrue(message.copy(expiresAt = "2026-08-15T11:59:59.000Z").expired(at))
        assertFalse(message.copy(expiresAt = "2026-08-15T12:00:01.000Z").expired(at))
        // The boundary itself counts as closed, matching the server's `lte`.
        assertTrue(message.copy(expiresAt = "2026-08-15T12:00:00.000Z").expired(at))

        // A stamp that cannot be read counts as not expired. One malformed
        // field must not make a conversation disappear - far worse than one
        // message outstaying its welcome until the next refetch drops it.
        assertFalse(message.copy(expiresAt = "not a date").expired(at))
    }

    @Test
    fun `the cached envelope is still the envelope`() {
        val sealed = """{"v":1,"epoch":1,"iv":"aXY","ct":"Y3Q"}"""
        val stored = Message(
            id = "m1",
            channelId = "c1",
            content = sealed,
            author = user,
            createdAt = "2026-08-15T10:00:00.000Z",
            editedAt = null,
            deletedAt = null,
            deletedBy = null,
            pinnedAt = null,
            reactions = emptyList(),
        ).toJson().toString()

        // No plaintext is written, and the ciphertext is not re-encoded on the
        // way through - a stored row is byte for byte what the server holds.
        assertEquals(sealed, JSONObject(stored).getString("content"))
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Splitting a message around its custom emoji, checked against the desktop's
 * `server-emoji.check.ts` case for case.
 *
 * The two clients read each other's messages, so what one writes as `:shipit:`
 * the other has to draw as the same picture - and a splitter that is one
 * character out turns a message into half a message.
 */
class CustomEmojiTest {

    private val shipit = MessageCustomEmoji("shipit", "/api/v1/uploads/pictures/a.webp", false)
    private val parrot = MessageCustomEmoji("party_parrot", "/api/v1/uploads/pictures/b.gif", true)
    private val manifest = listOf(shipit, parrot)

    @Test
    fun `a message with no emoji is one piece of text`() {
        assertEquals(listOf(CustomEmoji.Piece.Text("hello")), CustomEmoji.split("hello", emptyList()))
        assertEquals(emptyList<CustomEmoji.Piece>(), CustomEmoji.split("", emptyList()))
    }

    @Test
    fun `text either side is kept exactly, spaces and all`() {
        val pieces = CustomEmoji.split("a :shipit: b", manifest)

        assertEquals(3, pieces.size)
        assertEquals(CustomEmoji.Piece.Text("a "), pieces[0])
        assertEquals(CustomEmoji.Piece.Emoji(shipit), pieces[1])
        assertEquals(CustomEmoji.Piece.Text(" b"), pieces[2])
    }

    @Test
    fun `a shortcode with no picture stays a word`() {
        // A deleted emoji, or one from a server this reader is not in. It must
        // read as what somebody typed rather than as a broken image.
        assertEquals(listOf(CustomEmoji.Piece.Text("look :gone:")), CustomEmoji.split("look :gone:", manifest))
    }

    @Test
    fun `two in a row are two pictures`() {
        val pieces = CustomEmoji.split(":shipit::party_parrot:", manifest)

        assertEquals(
            listOf(CustomEmoji.Piece.Emoji(shipit), CustomEmoji.Piece.Emoji(parrot)),
            pieces,
        )
    }

    @Test
    fun `a message that is only emoji is drawn large`() {
        assertTrue(CustomEmoji.isOnlyEmoji(CustomEmoji.split(":shipit:", manifest)))
        assertTrue(CustomEmoji.isOnlyEmoji(CustomEmoji.split(" :shipit:  :party_parrot: ", manifest)))
        assertFalse(CustomEmoji.isOnlyEmoji(CustomEmoji.split("ship it :shipit:", manifest)))
        assertFalse(CustomEmoji.isOnlyEmoji(emptyList()))
    }

    @Test
    fun `a body carries its emoji through a round trip`() {
        val body = MessageBody("ship it :shipit:", emoji = listOf(shipit))
        val decoded = MessageBody.decode(body.encode())

        assertEquals("ship it :shipit:", decoded.text)
        assertEquals(1, decoded.emoji.size)
        assertEquals("shipit", decoded.emoji[0].name)
        assertEquals(shipit.url, decoded.emoji[0].url)
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The same cases as `emoji-names.check.ts`, because the shortcodes are a
 * contract between the clients: a name that resolves here and nowhere else
 * sends a message the others draw as the word somebody typed.
 */
class EmojiNamesTest {

    @Test
    fun `the table parses and every entry has a name`() {
        assertTrue(EmojiNames.ALL.size > 300)
        assertTrue(EmojiNames.ALL.all { it.emoji.isNotEmpty() && it.names.isNotEmpty() })
        assertTrue(EmojiNames.ALL.all { entry -> entry.names.none { it.contains(':') } })
    }

    @Test
    fun `the flame beats the fire engine`() {
        // The ranking is the whole feature: a prefix match on a longer name
        // must not come before the emoji actually called that.
        val found = EmojiNames.search("fire").map { it.emoji }
        assertEquals("🔥", found.first())
    }

    @Test
    fun `an alias finds the same emoji as its name`() {
        assertEquals(
            EmojiNames.search("thumbsup").first().emoji,
            EmojiNames.search("+1").first().emoji,
        )
    }

    @Test
    fun `a term nothing is called finds nothing`() {
        assertTrue(EmojiNames.search("qwertyuiop").isEmpty())
    }

    @Test
    fun `the menu is capped`() {
        assertTrue(EmojiNames.search("a").size <= EmojiNames.SUGGESTION_LIMIT)
    }

    @Test
    fun `a shortcode being typed is found with where it starts`() {
        val query = EmojiNames.queryAt("hey :fir", 8)
        assertNotNull(query)
        assertEquals("fir", query!!.term)
        assertEquals(4, query.start)
    }

    @Test
    fun `a colon in a URL or a clock opens nothing`() {
        assertNull(EmojiNames.queryAt("https://example.com", 19))
        assertNull(EmojiNames.queryAt("at 10:30am", 10))
    }

    @Test
    fun `a closed shortcode is finished, not a search`() {
        assertNull(EmojiNames.queryAt(":tada: ", 7))
        // The caret inside a closed one is still a search - the second colon is
        // after the caret and this only ever reads what is behind it.
        assertNotNull(EmojiNames.queryAt(":tada:", 5))
    }

    @Test
    fun `one character offers nothing`() {
        assertNull(EmojiNames.queryAt("a :f", 4))
        assertNotNull(EmojiNames.queryAt("a :fi", 5))
    }

    @Test
    fun `a space ends it`() {
        assertNull(EmojiNames.queryAt(": fire", 6))
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * The address parsing behind the server picker, which is the part that fails
 * silently: a base URL that is subtly wrong does not throw, it just sends every
 * later request somewhere that answers 404 or drops the bearer token.
 *
 * These are the same cases as `apps/desktop/src/services/endpoint.check.ts`,
 * so the two clients can be shown to agree.
 */
class EndpointTest {

    @Test
    fun `what a person types becomes a base URL`() {
        assertEquals("https://betweenus.example.com", Endpoint.normalize("betweenus.example.com"))
        assertEquals("https://betweenus.example.com", Endpoint.normalize("  betweenus.example.com/  "))
        assertEquals("http://192.168.1.4:8080", Endpoint.normalize("http://192.168.1.4:8080"))
        assertEquals("https://example.com:8443", Endpoint.normalize("https://example.com:8443///"))
    }

    @Test
    fun `a path is part of a base and a query is not`() {
        assertEquals("https://example.com/betweenus", Endpoint.normalize("https://example.com/betweenus"))
        assertEquals("https://example.com/betweenus", Endpoint.normalize("https://example.com/betweenus/?a=1#b"))
    }

    @Test
    fun `nonsense is refused rather than stored`() {
        for (bad in listOf("", "   ", "ftp://example.com", "https://")) {
            assertThrows(bad, IllegalArgumentException::class.java) { Endpoint.normalize(bad) }
        }
    }

    /**
     * Where the probe ended is what gets stored: a redirect to another origin
     * would otherwise strip the Authorization header off every authenticated
     * request, and the server would answer "Missing bearer token" under every
     * screen.
     */
    @Test
    fun `the stored base is where the probe landed`() {
        val probe = "/api/v1/auth/oauth/providers"
        assertEquals(
            "https://betweenus.example.com",
            Endpoint.baseFromProbeUrl("https://betweenus.example.com$probe", "http://betweenus.example.com"),
        )
        assertEquals(
            "https://example.com/betweenus",
            Endpoint.baseFromProbeUrl("https://example.com/betweenus$probe", "https://example.com/betweenus"),
        )
        // Redirected somewhere that is not the probe path: keep what was asked for.
        assertEquals(
            "https://example.com",
            Endpoint.baseFromProbeUrl("https://example.com/login", "https://example.com/"),
        )
    }
}

package com.aatech.betweenus.core.data

import com.aatech.betweenus.core.data.ImageEdit.Edit
import com.aatech.betweenus.core.data.ImageEdit.Size
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The property worth guarding is that the frame is always covered: a scale or a
 * clamp wrong by a pixel is an avatar with a sliver of nothing down one side,
 * and it only shows on the pictures whose aspect ratio happens to hit it.
 *
 * Mirrors `apps/desktop/src/services/image-edit.check.ts`. The two clients frame
 * the same photograph and have to agree about what "the frame" means.
 */
class ImageEditTest {

    private val square = Size(512f, 512f)
    private val wide = Size(4000f, 3000f)
    private val tall = Size(1080f, 1920f)
    private val frame = Size(300f, 300f)
    private val banner = Size(320f, 180f)

    @Test
    fun `quarter turns wrap both ways`() {
        assertEquals(90, ImageEdit.rotate(0, 1))
        assertEquals(0, ImageEdit.rotate(270, 1))
        assertEquals(270, ImageEdit.rotate(0, -1))
        assertEquals(0, ImageEdit.rotate(180, 2))
    }

    @Test
    fun `turning swaps the shown size only on the quarter turns`() {
        assertTrue(ImageEdit.isSideways(90))
        assertTrue(ImageEdit.isSideways(270))
        assertFalse(ImageEdit.isSideways(180))
        assertEquals(Size(3000f, 4000f), ImageEdit.turned(wide, 90))
        assertEquals(wide, ImageEdit.turned(wide, 180))
    }

    @Test
    fun `cover scale covers the frame and has nothing to spare`() {
        for (image in listOf(square, wide, tall, Size(40f, 900f))) {
            for (box in listOf(frame, banner, Size(200f, 400f))) {
                for (rotation in listOf(0, 90, 180, 270)) {
                    val scale = ImageEdit.coverScale(image, box, rotation)
                    val shown = ImageEdit.turned(image, rotation)
                    assertTrue("covers width", shown.width * scale >= box.width - 1e-3f)
                    assertTrue("covers height", shown.height * scale >= box.height - 1e-3f)
                    val slack = minOf(
                        shown.width * scale - box.width,
                        shown.height * scale - box.height,
                    )
                    assertTrue("no scale to spare", slack < 1e-2f)
                }
            }
        }
    }

    @Test
    fun `a square in a square has nowhere to go`() {
        assertEquals(Size(0f, 0f), ImageEdit.panRange(square, frame, ImageEdit.NONE))
        assertEquals(
            ImageEdit.NONE,
            ImageEdit.clamp(square, frame, Edit(offsetX = 90f, offsetY = -90f)),
        )
    }

    @Test
    fun `a wide picture slides sideways, and up once it is turned`() {
        val flat = ImageEdit.panRange(wide, frame, ImageEdit.NONE)
        assertTrue(flat.width > 0f)
        assertEquals(0f, flat.height, 0f)

        val turned = ImageEdit.panRange(wide, frame, Edit(rotation = 90))
        assertEquals(0f, turned.width, 0f)
        assertTrue(turned.height > 0f)
    }

    @Test
    fun `zoom is clamped at both ends`() {
        assertEquals(1f, ImageEdit.clamp(square, frame, Edit(zoom = 0.2f)).zoom, 0f)
        assertEquals(ImageEdit.MAX_ZOOM, ImageEdit.clamp(square, frame, Edit(zoom = 99f)).zoom, 0f)
    }

    @Test
    fun `zooming in gives the picture somewhere to go, and the clamp keeps it there`() {
        val zoomed = ImageEdit.clamp(square, frame, Edit(zoom = 2f, offsetX = 10_000f))
        assertEquals(2f, zoomed.zoom, 0f)
        assertTrue(zoomed.offsetX > 0f)
        assertEquals(ImageEdit.panRange(square, frame, zoomed).width, zoomed.offsetX, 1e-3f)
    }

    @Test
    fun `a degenerate picture does not produce a NaN that would blank the canvas`() {
        assertEquals(1f, ImageEdit.coverScale(Size(0f, 0f), frame, 0), 0f)
    }

    @Test
    fun `the output is the crop in source pixels, never upscaled`() {
        // A 512 square framed square at zoom 1: the whole picture, capped only
        // by the ceiling when the ceiling is smaller than the source.
        assertEquals(Size(512f, 512f), ImageEdit.outputSize(square, frame, ImageEdit.NONE, 2048))
        assertEquals(Size(256f, 256f), ImageEdit.outputSize(square, frame, ImageEdit.NONE, 256))
        // Zoomed to 2, half as much of the picture is in the frame.
        assertEquals(
            Size(256f, 256f),
            ImageEdit.outputSize(square, frame, Edit(zoom = 2f), 2048),
        )
    }

    @Test
    fun `an untouched edit is recognised as one`() {
        assertTrue(ImageEdit.isUnedited(ImageEdit.NONE))
        assertFalse(ImageEdit.isUnedited(Edit(rotation = 90)))
        assertFalse(ImageEdit.isUnedited(Edit(offsetX = 1f)))
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * The same cases as `apps/desktop/src/services/invite-link.check.ts`.
 *
 * Both clients read what somebody pasted, and a code the phone accepts and the
 * desktop refuses - or the other way round - is a link that works for one
 * person and not for the person they sent it to.
 */
class InviteLinkTest {
    @Test
    fun `builds a link against a deployment`() {
        assertEquals(
            "https://betweenus.example.com/invite/k3m9x2qp",
            InviteLink.of("https://betweenus.example.com", "k3m9x2qp"),
        )
        assertEquals(
            "https://betweenus.example.com/invite/k3m9x2qp",
            InviteLink.of("https://betweenus.example.com/", "k3m9x2qp"),
        )
    }

    @Test
    fun `reads the code out of a link`() {
        assertEquals("k3m9x2qp", InviteLink.codeIn("https://betweenus.example.com/invite/k3m9x2qp"))
        assertEquals("k3m9x2qp", InviteLink.codeIn("  https://betweenus.example.com/invite/k3m9x2qp  "))
        assertEquals("k3m9x2qp", InviteLink.codeIn("https://betweenus.example.com/invite/k3m9x2qp?from=chat"))
        assertEquals("k3m9x2qp", InviteLink.codeIn("https://betweenus.example.com/invite/k3m9x2qp#top"))
        assertEquals("k3m9x2qp", InviteLink.codeIn("https://betweenus.example.com/?invite=k3m9x2qp"))
        // Another deployment's link: the code is still the code.
        assertEquals("zz12", InviteLink.codeIn("http://192.168.1.4:8080/invite/zz12"))
    }

    @Test
    fun `reads a bare code`() {
        assertEquals("k3m9x2qp", InviteLink.codeIn("k3m9x2qp"))
        assertEquals("k3m9x2qp", InviteLink.codeIn("  k3m9x2qp "))
    }

    @Test
    fun `refuses anything that is not one`() {
        assertNull(InviteLink.codeIn(""))
        assertNull(InviteLink.codeIn("   "))
        assertNull(InviteLink.codeIn("come and join my invite please"))
        assertNull(InviteLink.codeIn("ab"))
    }
}

package com.aatech.betweenus.core.data

import com.aatech.betweenus.core.data.Markup.Kind
import com.aatech.betweenus.core.data.Markup.Span
import com.aatech.betweenus.core.data.Markup.Style
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The offsets are the part with a bug in it. A style is drawn over indices
 * into the text the parser *returns*, and the marks have been taken out of
 * that text - so every case here asserts both halves, because a parser that
 * strips two characters and reports the range it saw before stripping paints
 * the wrong words and looks almost right.
 */
class MarkupTest {

    private fun one(text: String): Markup.Block =
        Markup.parse(text).single()

    @Test
    fun `plain text is one block and no spans`() {
        val block = one("hello there")
        assertEquals(Kind.Body, block.kind)
        assertEquals("hello there", block.text)
        assertTrue(block.spans.isEmpty())
    }

    @Test
    fun `bold loses its marks and keeps its range`() {
        val block = one("a **b** c")
        assertEquals("a b c", block.text)
        assertEquals(listOf(Span(2, 3, Style.Bold)), block.spans)
    }

    @Test
    fun `two asterisks are bold, not two italics`() {
        assertEquals(listOf(Span(0, 4, Style.Bold)), one("**bold**").spans)
    }

    @Test
    fun `italic takes either mark`() {
        assertEquals(listOf(Span(0, 1, Style.Italic)), one("*a*").spans)
        assertEquals(listOf(Span(0, 1, Style.Italic)), one("_a_").spans)
    }

    @Test
    fun `an identifier is not two italics`() {
        val block = one("call snake_case_name now")
        assertEquals("call snake_case_name now", block.text)
        assertTrue(block.spans.isEmpty())
    }

    @Test
    fun `nesting styles both, over the inner text`() {
        val block = one("**bold _and_ italic**")
        assertEquals("bold and italic", block.text)
        assertEquals(
            listOf(Span(5, 8, Style.Italic), Span(0, 15, Style.Bold)),
            block.spans,
        )
    }

    @Test
    fun `code is literal inside`() {
        val block = one("use `a*b*c` here")
        assertEquals("use a*b*c here", block.text)
        assertEquals(listOf(Span(4, 9, Style.Code)), block.spans)
    }

    @Test
    fun `an unmatched mark is just a character`() {
        val block = one("2 * 3 = 6")
        assertEquals("2 * 3 = 6", block.text)
        assertTrue(block.spans.isEmpty())
    }

    @Test
    fun `an empty pair is not a style`() {
        assertEquals("****", one("****").text)
    }

    @Test
    fun `a backslash escapes the mark it precedes`() {
        val block = one("a \\*not italic\\* b")
        assertEquals("a *not italic* b", block.text)
        assertTrue(block.spans.isEmpty())
    }

    @Test
    fun `a fence is its own block and is never parsed inside`() {
        val blocks = Markup.parse("before\n```\nval x = *2*\n```\nafter")
        assertEquals(listOf(Kind.Body, Kind.Code, Kind.Body), blocks.map { it.kind })
        assertEquals("val x = *2*", blocks[1].text)
        assertTrue(blocks[1].spans.isEmpty())
    }

    @Test
    fun `an unclosed fence still codes the rest`() {
        val blocks = Markup.parse("look\n```\nraw text")
        assertEquals(listOf(Kind.Body, Kind.Code), blocks.map { it.kind })
        assertEquals("raw text", blocks[1].text)
    }

    @Test
    fun `quoted lines group into one block and lose the marker`() {
        val blocks = Markup.parse("> one\n> two\nreply")
        assertEquals(listOf(Kind.Quote, Kind.Body), blocks.map { it.kind })
        assertEquals("one\ntwo", blocks[0].text)
        assertEquals("reply", blocks[1].text)
    }

    @Test
    fun `a greater-than inside a line is not a quote`() {
        val block = one("2 > 1")
        assertEquals(Kind.Body, block.kind)
        assertEquals("2 > 1", block.text)
    }

    @Test
    fun `a bullet is its own block and loses its marker`() {
        val blocks = Markup.parse("shopping\n- eggs\n- milk")
        assertEquals(listOf(Kind.Body, Kind.Bullet, Kind.Bullet), blocks.map { it.kind })
        assertEquals("eggs", blocks[1].text)
        assertEquals("milk", blocks[2].text)
    }

    @Test
    fun `a bullet still carries its inline styles`() {
        val blocks = Markup.parse("- buy **eggs**")
        assertEquals("buy eggs", blocks[0].text)
        assertEquals(listOf(Span(4, 8, Style.Bold)), blocks[0].spans)
    }

    @Test
    fun `a numbered run is renumbered from its first item`() {
        val blocks = Markup.parse("1. one\n1. two\n1. three")
        assertEquals(listOf(1, 2, 3), blocks.map { it.ordinal })
        assertEquals(listOf("one", "two", "three"), blocks.map { it.text })
    }

    @Test
    fun `a numbered run that starts elsewhere keeps its start`() {
        val blocks = Markup.parse("5. five\n6. six")
        assertEquals(listOf(5, 6), blocks.map { it.ordinal })
    }

    @Test
    fun `a paragraph between two runs starts the numbering again`() {
        val blocks = Markup.parse("1. one\nprose\n1. one again")
        assertEquals(listOf(Kind.Number, Kind.Body, Kind.Number), blocks.map { it.kind })
        assertEquals(1, blocks[2].ordinal)
    }

    @Test
    fun `a close paren numbers a list too`() {
        assertEquals(Kind.Number, Markup.parse("1) one").single().kind)
    }

    @Test
    fun `a marker glued to its word is a mark, not a list`() {
        // The space after the marker is the whole difference, and it is what
        // keeps every *italic* in the app from becoming a bullet.
        val block = one("*italic*")
        assertEquals(Kind.Body, block.kind)
        assertEquals("italic", block.text)
    }

    @Test
    fun `a hyphen mid-sentence is not a bullet`() {
        val block = one("well - maybe not")
        assertEquals(Kind.Body, block.kind)
        assertEquals("well - maybe not", block.text)
    }

    @Test
    fun `a decimal is not a numbered item`() {
        val block = one("3.14 is pi")
        assertEquals(Kind.Body, block.kind)
        assertEquals("3.14 is pi", block.text)
    }

    @Test
    fun `a list marker inside a fence is left alone`() {
        val blocks = Markup.parse("```\n- not a bullet\n```")
        assertEquals(listOf(Kind.Code), blocks.map { it.kind })
        assertEquals("- not a bullet", blocks[0].text)
    }

    @Test
    fun `there is nothing to continue outside a list`() {
        assertNull(Markup.continueList("just words", 10))
        // A marker with nothing after it is not a list yet.
        assertNull(Markup.continueList("-", 1))
        // The caret in prose under a list is an ordinary newline.
        assertNull(Markup.continueList("- eggs\nprose", 12))
    }

    @Test
    fun `a bullet offers the next bullet`() {
        assertEquals(Markup.Continuation("- eggs\n- ", 9), Markup.continueList("- eggs", 6))
    }

    @Test
    fun `the exact marker is kept`() {
        assertEquals(Markup.Continuation("* eggs\n* ", 9), Markup.continueList("* eggs", 6))
        assertEquals(Markup.Continuation("  + eggs\n  + ", 13), Markup.continueList("  + eggs", 8))
    }

    @Test
    fun `a numbered item offers the one after it`() {
        assertEquals(Markup.Continuation("1. one\n2. ", 10), Markup.continueList("1. one", 6))
        assertEquals(Markup.Continuation("3) three\n4) ", 12), Markup.continueList("3) three", 8))
    }

    @Test
    fun `an empty item ends the list`() {
        assertEquals(Markup.Continuation("- eggs\n", 7), Markup.continueList("- eggs\n- ", 9))
        assertEquals(Markup.Continuation("1. one\n", 7), Markup.continueList("1. one\n2. ", 10))
    }

    @Test
    fun `only the line the caret is on counts`() {
        assertEquals(
            Markup.Continuation("prose\n- eggs\n- ", 15),
            Markup.continueList("prose\n- eggs", 12),
        )
    }

    @Test
    fun `a caret mid-item splits it and carries the list on`() {
        assertEquals(Markup.Continuation("- eggs\n- milk", 9), Markup.continueList("- eggsmilk", 6))
    }

    @Test
    fun `isPlain agrees with parse doing nothing`() {
        for (text in listOf(
            "hello",
            "a b c",
            "2 > 1 yes",
            "https://example.com/a_b",
            "- a bullet",
            "1. an item",
            "1) an item",
            "well - maybe not",
            "3.14 is pi",
        )) {
            val plain = Markup.isPlain(text)
            val unchanged = Markup.parse(text).let {
                it.size == 1 && it[0].kind == Kind.Body && it[0].text == text && it[0].spans.isEmpty()
            }
            // isPlain may be pessimistic; it must never be optimistic.
            if (plain) assertTrue("said plain but changed: $text", unchanged)
        }
    }

    @Test
    fun `a shortcode survives the parse so the emoji splitter still sees it`() {
        // The two run in order over the same string; a mark eating a colon
        // would turn a picture back into words.
        val block = one("**a** :shipit: b")
        assertEquals("a :shipit: b", block.text)
        assertEquals(listOf(Span(0, 1, Style.Bold)), block.spans)
    }
    // --- Release notes are the same parser with headings on ------------------
    //
    // Case for case with `markup.check.ts` on the desktop side. The two parsers
    // are separate code and have to stay one behaviour, or the same release
    // reads differently depending on which screen it is opened on.

    @Test
    fun `a chat line never grows a heading`() {
        // "### not a heading" is what somebody typed, and drawing it as one is
        // the reason parse does not have them.
        val block = one("### Features")
        assertEquals(Kind.Body, block.kind)
        assertEquals("### Features", block.text)
    }

    @Test
    fun `the same line read as a document is a heading, and carries its level`() {
        val heading = Markup.parseNotes("### Features").single()
        assertEquals(Kind.Heading, heading.kind)
        assertEquals("Features", heading.text)
        assertEquals(3, heading.ordinal)
        assertEquals(2, Markup.parseNotes("## Install").single().ordinal)
        assertEquals(1, Markup.parseNotes("# One").single().ordinal)
    }

    @Test
    fun `a hash with no space after it is not a heading`() {
        // `#general` is a channel, and `#` alone is a stray character.
        assertEquals(Kind.Body, Markup.parseNotes("#general is quiet").single().kind)
        assertEquals(Kind.Body, Markup.parseNotes("#").single().kind)
    }

    @Test
    fun `closing hashes are decoration, not text`() {
        assertEquals("Install", Markup.parseNotes("## Install ##").single().text)
    }

    @Test
    fun `marks apply inside a heading, and the offsets are into what comes back`() {
        val marked = Markup.parseNotes("### The **Artifacts** table").single()
        assertEquals("The Artifacts table", marked.text)
        assertEquals(listOf(Span(4, 13, Style.Bold)), marked.spans)
    }

    @Test
    fun `a table rule is swallowed and the rows are left as the pipes they are`() {
        // Legible for the three rows a release note carries, and not a table
        // parser. The two rows are one paragraph, which draws as the two lines
        // it was because a paragraph keeps its newlines.
        val blocks = Markup.parseNotes(
            "| Platform | This release |\n| --- | --- |\n| Android | Built here |",
        )
        assertEquals(listOf("| Platform | This release |\n| Android | Built here |"), blocks.map { it.text })
        // A chat line of dashes and pipes is untouched.
        assertEquals("| --- | --- |", one("| --- | --- |").text)
    }

    @Test
    fun `a blank line separates paragraphs in a document and joins them in a message`() {
        // Which is what keeps a note's paragraphs from carrying a newline at
        // each end, and keeps a deliberate gap in a message.
        assertEquals(
            listOf("one", "two"),
            Markup.parseNotes("one\n\ntwo").map { it.text },
        )
        assertEquals("one\n\ntwo", one("one\n\ntwo").text)
    }

    @Test
    fun `the shape a real release note has, from one pass`() {
        // A blank line is a paragraph break in a document, so nothing empty
        // comes back at all - unlike parse, where the gap is something
        // somebody typed on purpose.
        val blocks = Markup.parseNotes(
            listOf(
                "### Bug fixes",
                "",
                "* Fixed the thing",
                "* Fixed the other",
                "",
                "```bash",
                "docker compose pull",
                "```",
            ).joinToString("\n"),
        )

        assertEquals(
            listOf(
                Kind.Heading to "Bug fixes",
                Kind.Bullet to "Fixed the thing",
                Kind.Bullet to "Fixed the other",
                Kind.Code to "docker compose pull",
            ),
            blocks.map { it.kind to it.text },
        )
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * The message body encoding, checked against the desktop's
 * `apps/desktop/src/services/message-body.check.ts` case for case.
 *
 * This exists because the two clients disagreed and nothing caught it: Android
 * wrote bare JSON and sniffed for a leading `{`, the desktop wrote a
 * NUL-marked document, and a photo sent from a phone arrived on the web as a
 * paragraph of JSON. An encoding shared by three clients needs the same cases
 * asserted in each of them.
 */
class MessageBodyTest {

    private val attachment = MessageAttachment(
        key = "attachments/u1/2026-08/abc",
        url = "/api/v1/uploads/attachments/u1/2026-08/abc",
        name = "cat.png",
        contentType = "image/png",
        size = 1024,
        iv = "aXY",
        epoch = 4,
    )

    @Test
    fun `text with no files stays exactly as it was typed`() {
        assertEquals("hello", MessageBody("hello").encode())
        assertEquals(MessageBody("hello"), MessageBody.decode("hello"))
    }

    @Test
    fun `a message that looks like an envelope is still just text`() {
        // The hole the marker closes: no text field can produce a NUL, so a
        // person typing this cannot forge an attachment.
        val impostor = "{\"text\":\"nope\",\"attachments\":[]}"
        assertEquals(MessageBody(impostor), MessageBody.decode(impostor))
    }

    @Test
    fun `files survive a round trip`() {
        val body = MessageBody("look at this", listOf(attachment))
        val decoded = MessageBody.decode(body.encode())

        assertEquals("look at this", decoded.text)
        assertEquals(1, decoded.attachments.size)
        assertEquals(attachment.key, decoded.attachments[0].key)
        assertEquals(attachment.name, decoded.attachments[0].name)
        assertEquals(attachment.iv, decoded.attachments[0].iv)
        assertEquals(attachment.epoch, decoded.attachments[0].epoch)
    }

    @Test
    fun `a forward carries its tag and no files and is still a document`() {
        val body = MessageBody(
            text = "worth reading",
            forwardedFrom = MessageForward("Ada", "general"),
        )
        val decoded = MessageBody.decode(body.encode())

        assertEquals("worth reading", decoded.text)
        assertEquals(MessageForward("Ada", "general"), decoded.forwardedFrom)
    }

    @Test
    fun `a forward with no author is not a forward`() {
        val encoded = MessageBody.BODY_MARKER +
            "{\"text\":\"hi\",\"attachments\":[],\"forwardedFrom\":{\"channel\":\"general\"}}"
        assertEquals(null, MessageBody.decode(encoded).forwardedFrom)
    }

    @Test
    fun `an encoded body carries the marker the desktop looks for`() {
        val encoded = MessageBody("hi", listOf(attachment)).encode()
        assertEquals("\u0000betweenus-body:1\n", encoded.take(MessageBody.BODY_MARKER.length))
    }

    @Test
    fun `a reply carries no files and is still a document`() {
        val body = MessageBody("agreed", replyTo = MessageReply("m-1", "Ada", "shall we ship it"))
        val decoded = MessageBody.decode(body.encode())

        assertEquals("agreed", decoded.text)
        assertEquals(MessageReply("m-1", "Ada", "shall we ship it"), decoded.replyTo)
    }

    @Test
    fun `a quote with no id is dropped rather than drawn unclickable`() {
        val encoded = "\u0000betweenus-body:1\n{\"text\":\"hi\",\"replyTo\":{\"author\":\"Ada\"}}"
        assertEquals(null, MessageBody.decode(encoded).replyTo)
    }

    @Test
    fun `a quote is one line however many the original had`() {
        assertEquals("two lines", MessageReply.preview("  two\n\nlines  "))
        assertEquals(MessageReply.PREVIEW_CHARS, MessageReply.preview("x".repeat(500)).length)
    }

    @Test
    fun `a marked body that will not parse is shown rather than swallowed`() {
        val broken = "\u0000betweenus-body:1\nnot json at all"
        assertEquals(broken, MessageBody.decode(broken).text)
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The challenge this client sends has to be the one the server computes.
 *
 * There is no way to find out at runtime that these two disagree: the sign-in
 * simply fails at the exchange, after the browser round trip, with an error
 * about a sign-in that started somewhere else. So the digest is pinned to a
 * value produced by the server's own `challengeFor`, and if either side changes
 * its encoding this is what says so.
 */
class OAuthFlowTest {
    @Test
    fun `challenge matches the server's digest`() {
        assertEquals(
            "_-BU_nrgy23GXDr5th1SCfQ5hR20PQulmXM33xVGaOs",
            OAuthFlow.challengeFor("a".repeat(64)),
        )
    }

    @Test
    fun `challenge is base64url of the length the server insists on`() {
        val challenge = OAuthFlow.challengeFor("some-verifier")
        assertEquals(43, challenge.length)
        // base64url: no padding, and none of standard base64's + / =
        assertTrue(challenge, Regex("^[A-Za-z0-9_-]{43}$").matches(challenge))
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * A person is named once in a row, not twice.
 *
 * Every list of people draws [UserSummary.label] over the handle beneath it,
 * and an account that never set a display name has the two be the same string -
 * so the row read "test" over "@test", which looks like a rendering fault
 * rather than a name. [UserSummary.handle] is the rule that decides whether the
 * second line is worth drawing, and it is here rather than in each screen
 * because there are five of them.
 */
class PersonLabelTest {
    private fun user(username: String, displayName: String) =
        UserSummary(id = "u1", username = username, displayName = displayName, avatarUrl = null)

    @Test
    fun `a display name of its own is worth a second line`() {
        val ada = user("ada", "Ada Lovelace")
        assertEquals("Ada Lovelace", ada.label)
        assertEquals("@ada", ada.handle)
    }

    @Test
    fun `a display name that is the username is not repeated`() {
        assertNull(user("test", "test").handle)
        // The server lower-cases nothing, so the same name in another case is
        // still the same name.
        assertNull(user("test", "Test").handle)
    }

    @Test
    fun `an account with no display name is named by its username once`() {
        val blank = user("test", "")
        assertEquals("test", blank.label)
        assertNull(blank.handle)
    }

    @Test
    fun `a member follows the same rule as a search result`() {
        fun member(username: String, displayName: String) = ServerMember(
            userId = "u1",
            username = username,
            displayName = displayName,
            avatarUrl = null,
            role = ServerRole.MEMBER,
            permissions = emptyList(),
            grantedPermissions = emptyList(),
            deniedPermissions = emptyList(),
            roleIds = emptyList(),
        )
        assertEquals("@ada", member("ada", "Ada Lovelace").handle)
        assertNull(member("test", "test").handle)
        assertNull(member("test", "").handle)
    }
}

package com.aatech.betweenus.core.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import kotlin.math.abs

/**
 * The clock the client trusts.
 *
 * The desktop's `server-clock.check.ts` holds the same cases. If one of these
 * ever has to change, so does that one.
 */
class ServerClockTest {

    private val hour = 60 * 60 * 1000L

    @Before
    fun clear() = ServerClock.reset()

    @Test
    fun `an unmeasured clock is this phone's clock`() {
        assertEquals(0L, ServerClock.offsetMs.value)
        assertTrue(abs(ServerClock.nowMs() - System.currentTimeMillis()) < 50)
        assertFalse(ServerClock.isWrong())
    }

    @Test
    fun `a reply with no usable date teaches nothing`() {
        // A proxy that strips `Date`, or writes nonsense into it, must not be
        // able to move this client's idea of the time.
        ServerClock.sample(0, 100, null)
        ServerClock.sample(0, 100, 0)
        ServerClock.sample(0, 100, -1)
        assertEquals(0L, ServerClock.offsetMs.value)
    }

    @Test
    fun `an hour behind, measured across a round trip`() {
        // Out 200ms, and the server stamped it an hour ahead of this phone: the
        // estimate is the midpoint, so the offset is the hour plus the 100ms
        // the reply spent in flight.
        val sent = 1_000_000L
        ServerClock.sample(sent, sent + 200, sent + hour + 100)
        assertTrue(abs(ServerClock.offsetMs.value - hour) < 1_000)
        assertTrue(ServerClock.isWrong())
        // A positive offset means the phone is behind; the wording must agree.
        assertTrue(ServerClock.wording(hour).contains("behind"))
        assertTrue(ServerClock.wording(-hour).contains("ahead of"))
    }

    @Test
    fun `the fastest round trip decides`() {
        // A slow round trip is slow because something queued, and a queue is
        // rarely symmetric - so a delayed sample is biased, not merely noisy.
        ServerClock.sample(0, 8_000, 2_000)
        ServerClock.sample(0, 100, 1_000_050)
        assertTrue(abs(ServerClock.offsetMs.value - 1_000_000L) < 200)
    }

    @Test
    fun `only the last few measurements are kept`() {
        // A clock corrected an hour ago stops being held against the phone.
        ServerClock.sample(0, 100, hour)
        repeat(ServerClock.SAMPLES + 4) { ServerClock.sample(0, 100, 50) }
        assertTrue(abs(ServerClock.offsetMs.value) < 1_000)
    }

    @Test
    fun `five minutes is the line`() {
        // Below it nothing on screen misleads, and a phone whose clock drifts a
        // little must not be nagged about it.
        assertFalse(ServerClock.isWrong(ServerClock.WARNING_MS - 1))
        assertFalse(ServerClock.isWrong(-(ServerClock.WARNING_MS - 1)))
        assertTrue(ServerClock.isWrong(ServerClock.WARNING_MS))
        assertTrue(ServerClock.isWrong(-ServerClock.WARNING_MS))
    }

    @Test
    fun `the wording scales with the gap`() {
        assertTrue(ServerClock.wording(10 * 60 * 1000L).contains("10 minutes"))
        assertTrue(ServerClock.wording(5 * hour).contains("5 hours"))
        assertTrue(ServerClock.wording(3 * 24 * hour).contains("3 days"))
    }
}

package com.aatech.betweenus.core.data

import kotlinx.coroutines.CancellationException
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.IOException

/**
 * The one rule that decides whether somebody is put back on a login form.
 *
 * Every case here was a real sign-out: a phone that opened the app before the
 * server was up, one that woke in a tunnel, and an activity recreated mid
 * restore, which arrived as `CancellationException` and read as a failed
 * sign-in - "Job was cancelled" over a session that was never questioned.
 */
class SessionRuleTest {

    @Test
    fun `a refused credential ends the session`() {
        assertTrue(endsSession(ApiError("UNAUTHORIZED", "Token expired", 401)))
    }

    @Test
    fun `an unreachable server does not`() {
        assertFalse(endsSession(IOException("Could not reach betweenus.example")))
    }

    @Test
    fun `a gateway that has not finished starting does not`() {
        assertFalse(endsSession(ApiError("BAD_GATEWAY", "Bad gateway", 502)))
    }

    @Test
    fun `a cancelled coroutine does not`() {
        assertFalse(endsSession(CancellationException("Job was cancelled")))
    }
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.data.PresenceStatus
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.ZoneOffset

/**
 * The line under a name.
 *
 * The mirror of `apps/desktop/src/services/last-seen.check.ts`, case for case:
 * two clients in the same conversation must not disagree about when somebody
 * was last here.
 */
class LastSeenTest {
    /** Saturday 29 August 2026, 15:30. Fixed so a weekday case means something. */
    private val now = LocalDateTime.of(2026, 8, 29, 15, 30)

    /** UTC throughout, so the wire value and the rendered clock are the same. */
    private val zone: ZoneId = ZoneOffset.UTC

    private fun at(y: Int, m: Int, d: Int, h: Int = 12, min: Int = 0): String =
        LocalDateTime.of(y, m, d, h, min).toInstant(ZoneOffset.UTC).toString()

    private fun label(iso: String?) = LastSeen.label(iso, now, zone)

    // --- nothing to say ------------------------------------------------------

    @Test
    fun `never seen draws no line at all`() {
        assertNull(label(null))
        assertNull(label(""))
        assertNull(label("not a date"))
    }

    // --- every line carries the time -----------------------------------------

    @Test
    fun `every line says what time of day it was`() {
        // The whole point of the line: "yesterday" alone does not answer the
        // question anybody actually has about somebody who is not here.
        val moments = listOf(
            at(2026, 8, 29, 9, 14),
            at(2026, 8, 28, 23, 55),
            at(2026, 8, 24, 8, 5),
            at(2026, 8, 22, 19, 7),
            at(2025, 3, 4, 6, 30),
        )
        for (moment in moments) {
            assertTrue(moment, label(moment)?.contains(" at ") == true)
        }
    }

    @Test
    fun `a clock that runs fast does not report the future`() {
        // "last seen in four minutes" is not a sentence; it is clamped to now.
        assertEquals(label(at(2026, 8, 29, 15, 30)), label(at(2026, 8, 29, 15, 34)))
    }

    // --- today and yesterday name themselves ---------------------------------

    @Test
    fun `today and yesterday are named, by the calendar and not by the hour`() {
        assertTrue(label(at(2026, 8, 29, 9, 14))!!.startsWith("last seen today at "))
        assertTrue(label(at(2026, 8, 28, 23, 55))!!.startsWith("last seen yesterday at "))

        // Local midnight, not 24 hours: 00:05 today is today however few
        // minutes ago, and 20:00 last night is yesterday however recently.
        assertTrue(label(at(2026, 8, 29, 0, 5))!!.startsWith("last seen today at "))
        assertTrue(label(at(2026, 8, 28, 20, 0))!!.startsWith("last seen yesterday at "))
    }

    // --- the week just gone, then the date -----------------------------------

    @Test
    fun `a weekday only while it still names one day`() {
        assertTrue(label(at(2026, 8, 24))!!.startsWith("last seen Monday at "))

        // Seven days back is the same weekday as today, so it must not say
        // "Saturday" - that would name two days, one of them a week out.
        val week = label(at(2026, 8, 22))!!
        assertTrue(week, !week.contains("Saturday"))
        assertTrue(week, week.contains("August"))
        assertTrue(week, week.contains(" at "))
    }

    @Test
    fun `the year appears only when it is not this one`() {
        assertTrue(!label(at(2026, 3, 4))!!.contains("2026"))
        assertTrue(label(at(2025, 3, 4))!!.contains("2025"))
    }

    // --- status wins over the timestamp --------------------------------------

    @Test
    fun `somebody who is here is not somebody who was last seen`() {
        assertEquals("online", LastSeen.line(PresenceStatus.ONLINE, at(2026, 8, 24), now, zone))

        // The dot beside the name says idle; the line says whether a message
        // will be read now, and the answer to that is the same as for online.
        assertEquals("online", LastSeen.line(PresenceStatus.IDLE, at(2026, 8, 24), now, zone))
        assertEquals("online", LastSeen.line(PresenceStatus.DND, null, now, zone))
    }

    @Test
    fun `offline falls through to the timestamp, and to nothing without one`() {
        val line = LastSeen.line(PresenceStatus.OFFLINE, at(2026, 8, 28, 23, 55), now, zone)
        assertTrue(line!!.startsWith("last seen yesterday"))
        assertNull(LastSeen.line(PresenceStatus.OFFLINE, null, now, zone))
    }

    // --- a sheet always says something ---------------------------------------

    @Test
    fun `a profile sheet never draws a blank where the status belongs`() {
        // The bug this exists for: offline with no timestamp said nothing at
        // all, so a sheet opened on a new account - or on somebody whose last
        // seen is hidden from you - had a hole in it and read as broken.
        assertEquals("Offline", LastSeen.profile(PresenceStatus.OFFLINE, null, now, zone))
        assertEquals("Offline", LastSeen.profile(PresenceStatus.OFFLINE, "", now, zone))
        assertEquals("Offline", LastSeen.profile(PresenceStatus.OFFLINE, "not a date", now, zone))

        // With a timestamp it is the sentence, capitalised for a sheet.
        assertTrue(
            LastSeen.profile(PresenceStatus.OFFLINE, at(2026, 8, 28, 23, 55), now, zone)
                .startsWith("Last seen yesterday at "),
        )
    }

    @Test
    fun `a profile sheet spells out which kind of here this is`() {
        // Unlike the header, which collapses both to "online" because it is
        // answering "will this be read now". The dot beside it is the only
        // other thing that says which.
        assertEquals("Online", LastSeen.profile(PresenceStatus.ONLINE, null, now, zone))
        assertEquals("Idle", LastSeen.profile(PresenceStatus.IDLE, null, now, zone))
        assertEquals("Do not disturb", LastSeen.profile(PresenceStatus.DND, null, now, zone))
        assertEquals("Invisible", LastSeen.profile(PresenceStatus.INVISIBLE, null, now, zone))

        // And a status other than offline still wins over any timestamp.
        assertEquals("Online", LastSeen.profile(PresenceStatus.ONLINE, at(2026, 8, 24), now, zone))
    }

    @Test
    fun `every combination says something`() {
        // The whole contract of `profile`, and the thing the header is allowed
        // to break and this is not.
        for (status in PresenceStatus.entries) {
            for (seen in listOf(null, "", "nonsense", at(2026, 8, 24))) {
                assertTrue(
                    "$status/$seen",
                    LastSeen.profile(status, seen, now, zone).isNotEmpty(),
                )
            }
        }
    }

    @Test
    fun `a heading raises the first letter and changes nothing else`() {
        assertEquals("Online", LastSeen.sentence(PresenceStatus.ONLINE, null, now, zone))
        assertTrue(
            LastSeen.sentence(PresenceStatus.OFFLINE, at(2026, 8, 28), now, zone)!!
                .startsWith("Last seen yesterday"),
        )
    }
}

package com.aatech.betweenus.core.store

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * When a player is pulled back into step, and - more importantly - when it is
 * left alone.
 *
 * The half that fails silently is the second one. A correction that fires too
 * eagerly does not throw or log; it seeks, and a seek is a gap in the music. A
 * session that stutters every few minutes is how this feature stops being used,
 * and nothing in a stack trace would ever say so.
 *
 * The numbers are the desktop's on purpose. Two clients correcting on different
 * tolerances is two clients that disagree about whether they are in step.
 */
class ListenSyncTest {

    private fun session(
        paused: Boolean = false,
        positionMs: Long = 10_000,
        atServerMs: Long = 100_000,
        durationMs: Long = 0,
    ) = ListenSession(
        rev = 1,
        queue = listOf(
            ListenTrack(
                id = "t1",
                provider = "youtube",
                ref = "r",
                title = "",
                durationMs = durationMs,
                addedByUserId = "ana",
                addedByUsername = "ana",
            ),
        ),
        index = 0,
        paused = paused,
        positionMs = positionMs,
        atServerMs = atServerMs,
        byUserId = null,
    )

    @Test
    fun `small drift is left alone`() {
        val playing = session()
        // The call is at 10s; this player is a second out either way.
        assertNull(ListenSync.correction(playing, 100_000, 9_000))
        assertNull(ListenSync.correction(playing, 100_000, 11_000))
        // Exactly at the tolerance is still inside it.
        assertNull(ListenSync.correction(playing, 100_000, 8_500))
    }

    @Test
    fun `drift past the tolerance is corrected in one jump`() {
        val playing = session()
        assertEquals(10_000L, ListenSync.correction(playing, 100_000, 8_400))
        assertEquals(10_000L, ListenSync.correction(playing, 100_000, 30_000))
    }

    @Test
    fun `the target is where the call is now, not where it was measured`() {
        // Ten seconds after the state was made, the call is at 20s - and that
        // is what the player is sent to. Seeking to the stamped 10s is how a
        // correction lands ten seconds behind and immediately needs another.
        val playing = session(positionMs = 10_000, atServerMs = 100_000)
        assertEquals(20_000L, ListenSync.correction(playing, 110_000, 0))
    }

    @Test
    fun `a paused session has almost no tolerance`() {
        val paused = session(paused = true, positionMs = 10_000)
        // A quarter second out is fine; anything a person could read is not.
        assertNull(ListenSync.correction(paused, 999_999, 10_200))
        assertEquals(10_000L, ListenSync.correction(paused, 999_999, 10_400))
    }

    @Test
    fun `a paused session ignores how long ago it was paused`() {
        // Nothing is moving, so the clock does not enter into it. Reading the
        // elapsed time here would drag a stopped track forward.
        val paused = session(paused = true, positionMs = 10_000, atServerMs = 0)
        assertNull(ListenSync.correction(paused, 5_000_000, 10_000))
    }

    @Test
    fun `drift is signed, and positive means behind`() {
        val playing = session()
        assertEquals(2_000L, ListenSync.driftOf(playing, 100_000, 8_000))
        assertEquals(-2_000L, ListenSync.driftOf(playing, 100_000, 12_000))
    }

    @Test
    fun `a player past the end of a known track is pulled back to the end`() {
        // The position formula clamps to the duration, so the correction cannot
        // ask a player to seek past the end of its own video.
        val playing = session(positionMs = 0, atServerMs = 0, durationMs = 30_000)
        assertEquals(30_000L, ListenSync.correction(playing, 500_000, 0))
    }
}

package com.aatech.betweenus.core.store

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Before
import org.junit.Test

/**
 * The position formula, and the rule that stops a queue jumping backwards.
 *
 * The formula is written twice - here and as `listenPositionAt` in
 * `packages/shared-types` - because a phone and a desktop in the same session
 * have to put the needle in the same place. The cases below are the ones where
 * two plausible implementations disagree, which is exactly where a session goes
 * quietly out of step rather than loudly wrong.
 */
class ListenTest {

    private fun track(id: String, durationMs: Long = 0) = ListenTrack(
        id = id,
        provider = "youtube",
        ref = "dQw4w9WgXcQ",
        title = "",
        durationMs = durationMs,
        addedByUserId = "ana",
        addedByUsername = "ana",
    )

    private fun session(
        rev: Int = 1,
        paused: Boolean = false,
        positionMs: Long = 0,
        atServerMs: Long = 1_000,
        durationMs: Long = 0,
    ) = ListenSession(
        rev = rev,
        queue = listOf(track("t1", durationMs)),
        index = 0,
        paused = paused,
        positionMs = positionMs,
        atServerMs = atServerMs,
        byUserId = "ana",
    )

    @Before
    fun reset() = Listen.clear()

    @Test
    fun `a playing track advances with the clock`() {
        val playing = session(positionMs = 5_000, atServerMs = 10_000)
        assertEquals(5_000L, listenPositionAt(playing, 10_000))
        assertEquals(8_000L, listenPositionAt(playing, 13_000))
    }

    @Test
    fun `a paused track does not`() {
        // The whole point of the pair: `positionMs` is where it was, and while
        // paused that is also where it is, however long ago the state was made.
        val paused = session(paused = true, positionMs = 5_000, atServerMs = 10_000)
        assertEquals(5_000L, listenPositionAt(paused, 10_000))
        assertEquals(5_000L, listenPositionAt(paused, 900_000))
    }

    @Test
    fun `a clock behind the stamp does not run the track backwards`() {
        // A phone whose offset has not been measured yet reads "now" as earlier
        // than the state was made. Without the floor that is a negative elapsed
        // and a position before the one the gateway sent.
        val playing = session(positionMs = 5_000, atServerMs = 10_000)
        assertEquals(5_000L, listenPositionAt(playing, 1_000))
    }

    @Test
    fun `the position is clamped to a known duration`() {
        // A session left playing while everybody was away must not report a
        // position in the next hour.
        val playing = session(positionMs = 0, atServerMs = 0, durationMs = 30_000)
        assertEquals(30_000L, listenPositionAt(playing, 500_000))
    }

    @Test
    fun `an unknown duration is not a clamp to zero`() {
        // `durationMs` is 0 until some player reports it, and reading that as a
        // length is a track that is over before it starts.
        val playing = session(positionMs = 0, atServerMs = 0, durationMs = 0)
        assertEquals(500_000L, listenPositionAt(playing, 500_000))
    }

    @Test
    fun `an older revision is dropped`() {
        Listen.apply(session(rev = 5, positionMs = 5_000))
        Listen.apply(session(rev = 4, positionMs = 99_000))
        assertEquals(5_000L, Listen.session.value?.positionMs)

        // The same revision too: it is an echo of what is already held.
        Listen.apply(session(rev = 5, positionMs = 77_000))
        assertEquals(5_000L, Listen.session.value?.positionMs)

        Listen.apply(session(rev = 6, positionMs = 12_000))
        assertEquals(12_000L, Listen.session.value?.positionMs)
    }

    @Test
    fun `the end of a session always applies`() {
        // There is no revision on "nothing is playing", so refusing it would
        // leave a dead track on screen for ever.
        Listen.apply(session(rev = 9))
        Listen.apply(null)
        assertNull(Listen.session.value)
    }

    @Test
    fun `a session parses off the wire`() {
        val json = JSONObject(
            """
            {"rev":3,"index":1,"paused":true,"positionMs":4200,"atServerMs":99,
             "byUserId":null,
             "queue":[
               {"id":"a","provider":"youtube","ref":"r1","title":"","durationMs":0,
                "addedByUserId":"u1","addedByUsername":"ana"},
               {"id":"b","provider":"youtube","ref":"r2","title":"Two","durationMs":1000,
                "addedByUserId":"u2","addedByUsername":"bo"}]}
            """.trimIndent(),
        )
        val parsed = ListenSession.from(json)
        assertEquals(3, parsed.rev)
        assertEquals(2, parsed.queue.size)
        // `byUserId` is nullable on the wire, and `optString` on a JSON null
        // answers the string "null" rather than null - which would draw a line
        // saying somebody called null skipped the track.
        assertNull(parsed.byUserId)
        assertEquals("Two", parsed.current?.title)
    }
}

package com.aatech.betweenus.core.store

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test

/**
 * What arrives from the referee, and the geometry this client mirrors.
 *
 * No game rules are tested here because none are implemented here - the only
 * implementation is `packages/shared-types/src/games/`. What is tested is the
 * three things a client can get wrong on its own: reading a board off the wire,
 * dropping a state it has already seen, and the index arithmetic it needs to
 * draw a grid and turn a tap back into the move the referee expects.
 */
class PlayTest {

    private fun state(
        gameId: String = "tic-tac-toe",
        cells: List<Int> = List(9) { -1 },
        winner: Int? = null,
    ) = GameState(
        gameId = gameId,
        cells = cells,
        boxes = emptyList(),
        data = emptyList(),
        turn = 0,
        winner = winner,
        lastMove = null,
        moveCount = 0,
    )

    private fun session(rev: Int = 1, winner: Int? = null) = GameSession(
        rev = rev,
        gameId = "tic-tac-toe",
        seats = listOf(GameSeat("ana", "ana"), null),
        state = state(winner = winner),
        round = 0,
        wins = listOf(0, 0),
        byUserId = "ana",
    )

    @Before
    fun reset() = Play.clear()

    @Test
    fun `a game in progress has no winner, and seat zero has not won it`() {
        // The bug this exists for: `optInt` answers 0 for an absent key, so a
        // board still being played reports seat zero as the winner of it.
        val json = JSONObject(
            """{"gameId":"tic-tac-toe","cells":[-1,-1,-1],"boxes":[],"data":[],
                "turn":1,"winner":null,"lastMove":null,"moveCount":0}""",
        )
        val parsed = GameState.from(json)
        assertNull(parsed.winner)
        assertFalse(parsed.over)
        assertNull(parsed.lastMove)
    }

    @Test
    fun `a draw is a winner of minus one, which is not the same as no winner`() {
        val drawn = GameState.from(
            JSONObject(
                """{"gameId":"tic-tac-toe","cells":[],"boxes":[],"data":[],
                    "turn":0,"winner":-1,"lastMove":4,"moveCount":9}""",
            ),
        )
        assertEquals(-1, drawn.winner)
        assertTrue(drawn.over)
        assertEquals(4, drawn.lastMove)
    }

    @Test
    fun `an empty chair parses as an empty chair`() {
        val json = JSONObject(
            """{"rev":2,"gameId":"tic-tac-toe","round":0,"wins":[1,0],"byUserId":"ana",
                "seats":[{"userId":"ana","username":"ana"},null],
                "state":{"gameId":"tic-tac-toe","cells":[],"boxes":[],"data":[],
                         "turn":0,"winner":null,"lastMove":null,"moveCount":0}}""",
        )
        val parsed = GameSession.from(json)
        assertEquals(2, parsed.seats.size)
        assertEquals("ana", parsed.seats[0]?.username)
        assertNull(parsed.seats[1])
        assertEquals(0, parsed.seatOf("ana"))
        // Nobody, rather than seat zero.
        assertEquals(-1, parsed.seatOf("bo"))
    }

    @Test
    fun `a revision at or below the one held is dropped`() {
        Play.apply(session(rev = 5))
        Play.apply(session(rev = 5, winner = 0))
        Play.apply(session(rev = 4, winner = 1))
        assertNull(Play.session.value?.state?.winner)

        Play.apply(session(rev = 6, winner = 0))
        assertEquals(0, Play.session.value?.state?.winner)
    }

    @Test
    fun `closing the game always applies`() {
        Play.apply(session(rev = 9))
        Play.apply(null)
        assertNull(Play.session.value)
    }

    @Test
    fun `a disc falls to the lowest free square in its column`() {
        val empty = List(Boards.CONNECT_COLUMNS * Boards.CONNECT_ROWS) { -1 }
        // Bottom row, column 0: row 5 of 6.
        assertEquals(5 * Boards.CONNECT_COLUMNS, Boards.landing(empty, 0))

        val oneDeep = empty.toMutableList().also { it[5 * Boards.CONNECT_COLUMNS] = 0 }
        assertEquals(4 * Boards.CONNECT_COLUMNS, Boards.landing(oneDeep, 0))

        val full = List(Boards.CONNECT_COLUMNS * Boards.CONNECT_ROWS) { 0 }
        assertEquals(-1, Boards.landing(full, 0))
    }

    @Test
    fun `dots and boxes line indices match the rules module's own`() {
        // Mirrored arithmetic, so it is asserted rather than assumed: the
        // horizontals come first and the verticals follow them, and a client
        // that got the offset wrong would draw one line and play another.
        assertEquals(0, Boards.horizontal(0, 0))
        assertEquals(Boards.BOX_CELLS, Boards.horizontal(1, 0))
        assertEquals(Boards.HORIZONTALS, Boards.vertical(0, 0))
        assertEquals(Boards.HORIZONTALS + Boards.DOTS, Boards.vertical(1, 0))
        // Forty lines in total, and no index collides across the two families.
        val all = (0 until Boards.DOTS).flatMap { r ->
            (0 until Boards.BOX_CELLS).map { c -> Boards.horizontal(r, c) }
        } + (0 until Boards.BOX_CELLS).flatMap { r ->
            (0 until Boards.DOTS).map { c -> Boards.vertical(r, c) }
        }
        assertEquals(40, all.size)
        assertEquals(40, all.toSet().size)
    }

    @Test
    fun `the library agrees with itself about seats`() {
        // A seat rail drawn from `seats` and coloured from `seatColours` needs
        // one entry per chair, or a four-player game draws two of them.
        for (game in Games.ALL) {
            assertEquals(game.name, game.seats, game.seatNames.size)
            assertEquals(game.name, game.seats, game.seatColours.size)
        }
    }
}

package com.aatech.betweenus.core.store

import com.aatech.betweenus.core.data.ChannelReadReceipt
import com.aatech.betweenus.core.data.Message
import com.aatech.betweenus.core.data.MessageBody
import com.aatech.betweenus.core.data.UserSummary
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * The same cases as `apps/desktop/src/features/chat/receipts.check.ts`.
 *
 * Both clients derive receipts from the same markers, and a phone that draws a
 * face against a different message than the desktop does is two answers to one
 * question - which is exactly the bug a shared derivation is meant to avoid.
 */
class ReceiptsTest {
    private fun reader(name: String, readAt: String) = ChannelReadReceipt(
        user = UserSummary(id = name, username = name, displayName = name, avatarUrl = null),
        readAt = readAt,
    )

    private fun message(id: String, createdAt: String, authorId: String) = ReadableMessage(
        message = Message(
            id = id,
            channelId = "c1",
            content = "",
            author = UserSummary(authorId, authorId, authorId, null),
            createdAt = createdAt,
            editedAt = null,
            deletedAt = null,
            deletedBy = null,
            pinnedAt = null,
            reactions = emptyList(),
        ),
        body = MessageBody(text = "hello"),
    )

    private val first = message("m1", "2026-01-01T10:00:00.000Z", "me")
    private val second = message("m2", "2026-01-01T10:05:00.000Z", "me")
    private val third = message("m3", "2026-01-01T10:10:00.000Z", "me")
    private val mine = listOf(first, second, third)

    private val readers = listOf(
        reader("ana", "2026-01-01T10:06:00.000Z"),
        reader("bo", "2026-01-01T10:11:00.000Z"),
    )

    @Test
    fun `seenBy is everyone whose marker is at or past the message`() {
        assertEquals(
            listOf("ana", "bo"),
            Receipts.seenBy(first.message.createdAt, readers).map { it.user.id },
        )
        assertEquals(
            listOf("bo"),
            Receipts.seenBy(third.message.createdAt, readers).map { it.user.id },
        )
        // The marker landing on the same millisecond counts: it was read.
        assertEquals(
            1,
            Receipts.seenBy(
                second.message.createdAt,
                listOf(reader("cy", second.message.createdAt)),
            ).size,
        )
    }

    @Test
    fun `each reader is drawn once, on the newest message they have read`() {
        val anchors = Receipts.anchorReceipts(mine, readers, "me")
        assertEquals(setOf("m2", "m3"), anchors.keys)
        assertEquals(listOf("ana"), anchors["m2"]?.map { it.user.id })
        assertEquals(listOf("bo"), anchors["m3"]?.map { it.user.id })
        assertNull(anchors["m1"])
    }

    @Test
    fun `a marker older than everything on screen anchors nowhere`() {
        val old = listOf(reader("old", "2026-01-01T09:00:00.000Z"))
        assertEquals(emptyMap<String, List<ChannelReadReceipt>>(), Receipts.anchorReceipts(mine, old, "me"))
    }

    @Test
    fun `somebody else's message never carries a receipt`() {
        val theirs = listOf(message("t1", "2026-01-01T10:00:00.000Z", "them"))
        assertEquals(emptyMap<String, List<ChannelReadReceipt>>(), Receipts.anchorReceipts(theirs, readers, "me"))
        assertEquals(emptyMap<String, List<ChannelReadReceipt>>(), Receipts.anchorReceipts(mine, readers, null))
    }

    @Test
    fun `out of order input does not change the answer`() {
        val shuffled = listOf(third, first, second)
        assertEquals(setOf("m2", "m3"), Receipts.anchorReceipts(shuffled, readers, "me").keys)
    }

    @Test
    fun `the label counts the readers it did not name`() {
        assertEquals("Not seen yet", Receipts.seenByLabel(emptyList()))
        assertEquals("Seen by ana", Receipts.seenByLabel(readers.take(1)))
        assertEquals("Seen by ana and bo", Receipts.seenByLabel(readers))
        assertEquals(
            "Seen by ana, bo and 1 other",
            Receipts.seenByLabel(readers + reader("cy", "2026-01-01T10:12:00.000Z")),
        )
    }
}

package com.aatech.betweenus.ui.components

import androidx.compose.material3.adaptive.currentWindowAdaptiveInfo
import androidx.compose.material3.adaptive.currentWindowSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp

/**
 * How much of the app fits on screen at once.
 *
 * A phone shows one thing and reaches the rest through a drawer. A tablet, an
 * unfolded foldable and a phone turned sideways have room for the channel list
 * *and* the conversation, and hiding one behind a hamburger on a 10-inch screen
 * is throwing away the screen.
 */
enum class ShellPanes {
    /** The navigation lives in a modal drawer, over the content. */
    SINGLE,

    /** The navigation lives permanently beside the content. */
    TWO,
}

/**
 * The shape of the shell for one window: how many panes, how wide the first one
 * is, and what to leave empty between them.
 */
data class ShellFrame(
    val panes: ShellPanes,
    /** Meaningless when [panes] is [ShellPanes.SINGLE]. */
    val navPaneWidth: Dp,
    /**
     * The gap between the two panes, which is the hinge when there is one.
     *
     * A folding screen is two panels with a physical seam between them. Content
     * drawn across that seam is content drawn on a hinge - unreadable on a book-
     * posture device and cut in half on one with a real gap - so the seam is
     * left empty rather than covered.
     */
    val hingeGap: Dp,
)

/**
 * Below this, one pane. It is the Material window-size-class boundary between
 * compact and medium, which is where a phone in portrait stops and everything
 * else starts - a large phone in landscape, a small tablet, an unfolded
 * foldable.
 */
val TWO_PANE_MIN_WIDTH: Dp = 600.dp

/** Narrower than this and the channel list stops being a list and starts being a column of ellipses. */
val NAV_PANE_MIN_WIDTH: Dp = 280.dp

/** Wider than this it is just empty space; the rail and one column of channels is all it holds. */
val NAV_PANE_MAX_WIDTH: Dp = 360.dp

/** A conversation narrower than this is a phone screen's worth, and below it messages stop being readable. */
val DETAIL_PANE_MIN_WIDTH: Dp = 320.dp

/** How much of a wide window the navigation takes when no hinge decides for it. */
private const val NAV_PANE_FRACTION = 0.35f

/**
 * Decides the shell's shape from the window and the hardware.
 *
 * Pure, and separated from the composable that feeds it, because every
 * interesting case here is a device nobody testing this will be holding: a
 * foldable half-opened, a hinge closer to one edge than the other, a tablet in
 * portrait. Those are cheap to assert about and expensive to find by hand.
 *
 * [hingeStart] and [hingeEnd] describe a *vertical, separating* fold only.
 * A horizontal one - a laptop-posture foldable, screen above keyboard - does
 * not split the window left from right and so has no bearing on this.
 */
fun shellFrame(width: Dp, hingeStart: Dp? = null, hingeEnd: Dp? = null): ShellFrame {
    if (width < TWO_PANE_MIN_WIDTH) return ShellFrame(ShellPanes.SINGLE, 0.dp, 0.dp)

    // A hinge is where the split belongs, when it leaves both halves usable.
    // Ignoring it would put the channel list across the fold on exactly the
    // devices this exists for; obeying one that sits 40dp from the edge would
    // give the navigation a pane it cannot draw anything in.
    if (
        hingeStart != null &&
        hingeEnd != null &&
        hingeEnd >= hingeStart &&
        hingeStart >= NAV_PANE_MIN_WIDTH &&
        width - hingeEnd >= DETAIL_PANE_MIN_WIDTH
    ) {
        return ShellFrame(ShellPanes.TWO, hingeStart, hingeEnd - hingeStart)
    }

    // No usable hinge: a share of the width, bounded at both ends. The lower
    // bound is what makes the narrowest two-pane window still work - at exactly
    // TWO_PANE_MIN_WIDTH the fraction would hand the navigation 210dp, which is
    // a column of truncated channel names.
    val proportional = width * NAV_PANE_FRACTION
    return ShellFrame(
        panes = ShellPanes.TWO,
        navPaneWidth = proportional.coerceIn(NAV_PANE_MIN_WIDTH, NAV_PANE_MAX_WIDTH),
        hingeGap = 0.dp,
    )
}

/**
 * [shellFrame] for the window this composable is drawn in.
 *
 * Recomposes when the window changes, which on Android is not only a rotation:
 * unfolding a phone, dragging a freeform window's edge and entering split
 * screen all resize it while the app is running, and all three used to leave
 * the layout as whatever it was at launch.
 *
 * The width is read from the window rather than from a size class enum on
 * purpose. The enum has been renamed more than once across the adaptive
 * library's versions, and what this actually needs is a number.
 */
@Composable
fun rememberShellFrame(): ShellFrame {
    val windowSize = currentWindowSize()
    val posture = currentWindowAdaptiveInfo().windowPosture
    val density = LocalDensity.current

    // Only a fold that is both vertical and separating splits the window into
    // two places to put things. A flat one is a screen with a crease, which is
    // still one screen.
    val hinge = posture.hingeList.firstOrNull { it.isVertical && it.isSeparating }

    return remember(windowSize, hinge, density) {
        with(density) {
            shellFrame(
                width = windowSize.width.toDp(),
                hingeStart = hinge?.bounds?.left?.toDp(),
                hingeEnd = hinge?.bounds?.right?.toDp(),
            )
        }
    }
}

