/**
 * Where a tap on a ringed avatar goes.
 *
 * Two small state holders rather than one, because they answer different
 * questions and are opened from different places:
 *
 * [StatusStory] is "show me this person's posts", which the tray, a ring and
 * the chooser below all ask for. The player that answers it lives in the app
 * module - this is only the door, so that an [Avatar] in this module can open
 * something it cannot import.
 *
 * [AvatarChoice] is the question a tap has to ask when there are two answers
 * behind one circle: the profile photo, or the status. Before statuses existed
 * a tap had one answer and [Avatar] simply opened it; picking one now would
 * make the ring decoration, since a tap on it would ignore the only thing it
 * was drawn to say.
 */
object StatusStory {
    /** Whose run is open, or null. */
    var authorId: String? by mutableStateOf(null)
        private set

    fun open(authorId: String) {
        this.authorId = authorId
    }

    fun close() {
        authorId = null
    }
}

/** The composer, opened from the tray and from the "My status" row. */
object StatusComposerDoor {
    var open: Boolean by mutableStateOf(false)
        private set

    fun show() {
        open = true
    }

    fun close() {
        open = false
    }
}

object AvatarChoice {
    data class Asking(
        val userId: String,
        val name: String,
        val avatarUrl: String?,
        /** How many live posts they have, for the line under the status choice. */
        val count: Int,
    )

    var asking: Asking? by mutableStateOf(null)
        private set

    fun ask(asking: Asking) {
        this.asking = asking
    }

    fun close() {
        asking = null
    }
}

/** Mounted once, at the root, beside `ProfileDialogHost`. */
@Composable
fun AvatarChoiceHost() {
    val asking = AvatarChoice.asking ?: return
    Dialog(onDismissRequest = { AvatarChoice.close() }) {
        Column(
            modifier = Modifier
                .widthIn(max = 320.dp)
                .clip(RoundedCornerShape(24.dp))
                .background(MaterialTheme.colorScheme.surfaceContainerHigh),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(16.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Avatar(
                    id = asking.userId,
                    label = asking.name,
                    url = asking.avatarUrl,
                    size = 40.dp,
                    viewable = false,
                )
                Text(
                    text = asking.name,
                    style = MaterialTheme.typography.titleMedium,
                    color = MaterialTheme.colorScheme.onSurface,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.padding(start = 12.dp),
                )
            }
            HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant)
            Choice(
                icon = BetweenUsIcons.User,
                label = "View profile photo",
                onClick = {
                    val url = asking.avatarUrl
                    AvatarChoice.close()
                    if (url != null) ProfileViewer.open(asking.name, url)
                },
            )
            Choice(
                icon = BetweenUsIcons.Eye,
                label = "View status",
                hint = if (asking.count == 1) "1 update" else "${asking.count} updates",
                onClick = {
                    val id = asking.userId
                    AvatarChoice.close()
                    StatusStory.open(id)
                },
            )
        }
    }
}

@Composable
private fun Choice(
    @DrawableRes icon: Int,
    label: String,
    hint: String? = null,
    onClick: () -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .padding(horizontal = 16.dp, vertical = 14.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        BetweenUsIcon(icon, contentDescription = null)
        Text(
            text = label,
            style = MaterialTheme.typography.bodyLarge,
            color = MaterialTheme.colorScheme.onSurface,
            modifier = Modifier.weight(1f).padding(start = 16.dp),
        )
        if (hint != null) {
            Text(
                text = hint,
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

package com.aatech.betweenus.ui.theme

import androidx.compose.animation.core.FiniteAnimationSpec
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.ReadOnlyComposable

/**
 * Motion, said once.
 *
 * Expressive animates with springs rather than durations: a spring has no fixed
 * length, so an interrupted one carries its velocity into whatever happens next
 * instead of restarting. The four specs below are the whole vocabulary this
 * client uses.
 *
 * The `spatial` half is for anything that moves or resizes; the `effect` half is
 * for anything that only changes colour or alpha. They are different because a
 * bouncing colour looks like a bug and a non-bouncing slide looks dead - only
 * the spatial springs overshoot.
 *
 * Each is generic in what it animates, because the caller decides whether it is
 * a `Dp`, a `Color`, an `IntOffset` or a bare float. Everything reads
 * `MaterialTheme.motionScheme`, which is what [BetweenUsTheme] sets; nothing in
 * this app should hand-write a `tween`.
 */
object BetweenUsMotion {

    /** Something arriving, leaving, or changing size. Springy, slight overshoot. */
    @Composable
    @ReadOnlyComposable
    fun <T> spatial(): FiniteAnimationSpec<T> = MaterialTheme.motionScheme.defaultSpatialSpec()

    /** The same, for a small thing that should settle fast. */
    @Composable
    @ReadOnlyComposable
    fun <T> spatialFast(): FiniteAnimationSpec<T> = MaterialTheme.motionScheme.fastSpatialSpec()

    /** A colour or an alpha. No overshoot: colour does not bounce. */
    @Composable
    @ReadOnlyComposable
    fun <T> effect(): FiniteAnimationSpec<T> = MaterialTheme.motionScheme.defaultEffectsSpec()

    /** The same, for a press - fast enough to feel like part of the touch. */
    @Composable
    @ReadOnlyComposable
    fun <T> effectFast(): FiniteAnimationSpec<T> = MaterialTheme.motionScheme.fastEffectsSpec()
}

package com.aatech.betweenus.ui.components

import androidx.compose.ui.unit.dp
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The shape of the shell, for the windows nobody testing this will be holding.
 *
 * Every interesting case here is a device or a posture that is awkward to
 * reproduce by hand - a foldable half-opened, a hinge nearer one edge than the
 * other, a tablet in portrait, a freeform window being dragged narrower while
 * the app runs. They are all one function call, so they are asserted here
 * instead of hoped for.
 */
class ShellFrameTest {

    @Test
    fun `a phone in portrait is one pane`() {
        // A small phone, a large phone, and the widest window that is still
        // one - 599dp, one below the boundary.
        for (width in listOf(320.dp, 411.dp, 599.dp)) {
            assertEquals(
                "$width should be a single pane",
                ShellPanes.SINGLE,
                shellFrame(width).panes,
            )
        }
    }

    @Test
    fun `a tablet and a phone in landscape are two panes`() {
        for (width in listOf(600.dp, 800.dp, 1280.dp)) {
            assertEquals(
                "$width should be two panes",
                ShellPanes.TWO,
                shellFrame(width).panes,
            )
        }
    }

    /**
     * The narrowest two-pane window is the one that breaks. A flat fraction of
     * 600dp hands the navigation 210dp, which is a column of truncated channel
     * names next to a conversation - so the lower bound is what makes the
     * boundary case usable rather than merely two panes.
     */
    @Test
    fun `the narrowest two-pane window still leaves both panes usable`() {
        val frame = shellFrame(600.dp)
        assertTrue("nav pane too narrow: ${frame.navPaneWidth}", frame.navPaneWidth >= NAV_PANE_MIN_WIDTH)
        assertTrue(
            "detail pane too narrow: ${600.dp - frame.navPaneWidth}",
            600.dp - frame.navPaneWidth >= DETAIL_PANE_MIN_WIDTH,
        )
    }

    @Test
    fun `a very wide window does not give the navigation the whole of it`() {
        // A desktop-sized freeform window. A third of 2400dp is 800dp of
        // channel list, which is 700dp of nothing.
        assertEquals(NAV_PANE_MAX_WIDTH, shellFrame(2400.dp).navPaneWidth)
    }

    @Test
    fun `an unfolded foldable splits on the hinge and leaves it empty`() {
        // A 7.6-inch book-posture device: two panels either side of a hinge
        // that is a few dp of real gap.
        val frame = shellFrame(width = 674.dp, hingeStart = 333.dp, hingeEnd = 341.dp)

        assertEquals(ShellPanes.TWO, frame.panes)
        assertEquals("the split belongs on the fold", 333.dp, frame.navPaneWidth)
        assertEquals("nothing is drawn on the hinge", 8.dp, frame.hingeGap)
    }

    /**
     * A hinge is a suggestion, not an order. One sitting near an edge would
     * hand a pane less room than it can draw anything in, and the proportional
     * split is the better answer.
     */
    @Test
    fun `a hinge too near an edge is ignored`() {
        // Hinge 60dp from the left: obeying it gives the navigation 60dp.
        val nearLeft = shellFrame(width = 900.dp, hingeStart = 60.dp, hingeEnd = 68.dp)
        assertEquals(ShellPanes.TWO, nearLeft.panes)
        assertTrue(nearLeft.navPaneWidth >= NAV_PANE_MIN_WIDTH)
        assertEquals("no gap when the hinge was not used", 0.dp, nearLeft.hingeGap)

        // Hinge 100dp from the right: obeying it gives the conversation 100dp.
        val nearRight = shellFrame(width = 900.dp, hingeStart = 792.dp, hingeEnd = 800.dp)
        assertTrue(900.dp - nearRight.navPaneWidth >= DETAIL_PANE_MIN_WIDTH)
        assertEquals(0.dp, nearRight.hingeGap)
    }

    /**
     * A folded foldable is a narrow phone that happens to have a hinge behind
     * the screen. Width decides, and it decides first.
     */
    @Test
    fun `a hinge on a narrow window does not force two panes`() {
        val frame = shellFrame(width = 400.dp, hingeStart = 200.dp, hingeEnd = 208.dp)
        assertEquals(ShellPanes.SINGLE, frame.panes)
        assertEquals(0.dp, frame.hingeGap)
    }

    /**
     * A laptop-posture foldable folds top to bottom. It does not split the
     * window left from right, so it never reaches this function as a hinge at
     * all - and a window with no hinge must not grow a gap out of nothing.
     */
    @Test
    fun `no hinge means no gap`() {
        assertEquals(0.dp, shellFrame(1000.dp).hingeGap)
        assertEquals(0.dp, shellFrame(1000.dp, hingeStart = null, hingeEnd = null).hingeGap)
    }

    /** Half-described hinges come back from real devices; neither half alone is a fold. */
    @Test
    fun `a half-described hinge is not a hinge`() {
        assertEquals(0.dp, shellFrame(900.dp, hingeStart = 400.dp, hingeEnd = null).hingeGap)
        assertEquals(0.dp, shellFrame(900.dp, hingeStart = null, hingeEnd = 408.dp).hingeGap)
        // Inverted bounds are nonsense rather than a zero-width fold.
        assertEquals(0.dp, shellFrame(900.dp, hingeStart = 500.dp, hingeEnd = 400.dp).hingeGap)
    }

    /**
     * A flat fold - a crease with no gap - is still where the split belongs.
     * The two panels are separate places to put things even when the seam has
     * no width to leave empty.
     */
    @Test
    fun `a zero-width fold still decides the split`() {
        val frame = shellFrame(width = 800.dp, hingeStart = 400.dp, hingeEnd = 400.dp)
        assertEquals(400.dp, frame.navPaneWidth)
        assertEquals(0.dp, frame.hingeGap)
    }
}

package com.aatech.betweenus.ui.components

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The segmented ring's geometry.
 *
 * Worth asserting because it is arithmetic nobody reads back off the screen: an
 * off-by-one in the angles draws overlapping arcs or a gap that grows around
 * the circle, and it looks like a rendering quirk rather than a bug in a
 * formula. The same assertions the desktop makes in `StatusRing.check.ts`.
 */
class StatusRingTest {

    @Test
    fun `one post is a whole circle with no notch in it`() {
        val arcs = ringArcs(1)
        assertEquals(1, arcs.size)
        assertEquals(360f, arcs[0].sweepDegrees, 0.001f)
        // Starting at the top, not at three o'clock: a ring that starts on the
        // side looks tilted next to a circular avatar.
        assertEquals(-90f, arcs[0].startDegrees, 0.001f)
    }

    @Test
    fun `four posts are four evenly spaced arcs`() {
        val arcs = ringArcs(4)
        assertEquals(4, arcs.size)
        arcs.forEachIndexed { index, arc ->
            assertEquals(-90f + index * 90f + 3f, arc.startDegrees, 0.001f)
            assertEquals(84f, arc.sweepDegrees, 0.001f)
        }
    }

    @Test
    fun `the arcs and the gaps between them are exactly one circle`() {
        val arcs = ringArcs(7)
        val drawn = arcs.sumOf { it.sweepDegrees.toDouble() }
        // Seven arcs, seven gaps, and no drift: what is not drawn is the gaps.
        assertEquals(360.0 - 7 * 6.0, drawn, 0.001)
    }

    @Test
    fun `past the point where arcs are shorter than gaps the ring goes solid`() {
        assertEquals(MAX_STATUS_SEGMENTS, ringArcs(MAX_STATUS_SEGMENTS).size)
        val many = ringArcs(MAX_STATUS_SEGMENTS + 1)
        assertEquals(1, many.size)
        assertEquals(360f, many[0].sweepDegrees, 0.001f)
    }

    @Test
    fun `nothing posted does not divide by zero`() {
        // The caller draws no ring at all for a zero, but a zero reaching here
        // must not come back as NaN.
