contextBridge.exposeInMainWorld('betweenus', api);

export type BetweenUsBridge = typeof api;

/**
 * Injecting mouse and keyboard events into the machine being controlled.
 *
 * This is the one part of remote desktop that cannot be done with what Electron
 * already has: `webContents.sendInputEvent` reaches the app's own window, and
 * the point of a remote session is everything *outside* it.
 *
 * ponytail: Windows only, through one long-lived PowerShell process that
 * P/Invokes user32. No native module, no node-gyp, no prebuilt binary per
 * Electron version - and the process is spawned once and fed lines, not spawned
 * per event, which is what makes it fast enough to drag a window with.
 *
 * The helper is written to a file and run with `-File`, not piped into
 * `-Command -`: with `-Command -` PowerShell consumes stdin as the script
 * itself, so the event stream and the program would be the same pipe and
 * nothing after the first read would arrive. That is what made control appear
 * to do nothing at all.
 *
 * `mouse_event`/`keybd_event` rather than `SendInput`: the legacy calls take
 * flat arguments instead of a union struct, they still work, and the difference
 * only shows up for injecting into elevated windows, which this cannot do
 * anyway without running elevated itself.
 *
 * macOS and Linux report unsupported, and a session there is view-only. The
 * upgrade is a per-platform backend behind this same interface - CGEventPost on
 * macOS, XTEST or uinput on Linux.
 */
import { spawn, type ChildProcessWithoutNullStreams } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { app, screen } from 'electron';
import {
  MODIFIER_VIRTUAL_KEYS,
  modifierOf,
  planModifiers,
  readModifiers,
  type Modifier,
} from './modifiers';

/**
 * Which of the two ways somebody can be driving this machine an event came
 * from. They are independent: a machine can be in a remote session and handing
 * control out in a call at the same time, watching a different monitor in each,
 * and a single target meant whichever was set last captured both.
 */
export type InputSource = 'session' | 'call';

export interface MouseInput {
  action: 'move' | 'down' | 'up' | 'wheel';
  /** Fraction of the shared screen, 0..1, so the two sides need no shared DPI. */
  x: number;
  y: number;
  button?: 'left' | 'right' | 'middle';
  deltaY?: number;
  /** Defaults to a remote session, which is the older of the two paths. */
  source?: InputSource;
}

export interface KeyInput {
  action: 'down' | 'up';
  /** The character where there is one - `a`, `A`, `?`. */
  key: string;
  /** The physical key - `KeyA`, `Enter`, `ArrowLeft`. */
  code: string;
  /**
   * Which modifiers the controller was holding when this happened. Sent with
   * every event, because a chord cannot be reconstructed from the order three
   * separate events happened to arrive in - see `modifiers.ts`.
   */
  modifiers?: string[];
  source?: InputSource;
}

/**
 * The helper. One line in, one call to user32 out.
 *
 * The casting lives in C# rather than in PowerShell on purpose: `[uint32]-120`
 * throws in PowerShell, and a scroll upwards is exactly that number.
 */
const SCRIPT = `
$ErrorActionPreference = 'Stop'
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class BetweenUsInput {
  [DllImport("user32.dll")] static extern bool SetCursorPos(int X, int Y);
  [DllImport("user32.dll")] static extern void mouse_event(uint flags, uint dx, uint dy, uint data, IntPtr extra);
  [DllImport("user32.dll")] static extern void keybd_event(byte vk, byte scan, uint flags, IntPtr extra);
  [DllImport("user32.dll")] static extern short VkKeyScan(char ch);

  const uint LEFTDOWN = 0x0002, LEFTUP = 0x0004;
  const uint RIGHTDOWN = 0x0008, RIGHTUP = 0x0010;
  const uint MIDDLEDOWN = 0x0020, MIDDLEUP = 0x0040;
  const uint WHEEL = 0x0800;
  const uint KEYUP = 0x0002;

  public static void Move(int x, int y) { SetCursorPos(x, y); }

  public static void Button(string button, bool down) {
    uint flag;
    if (button == "right") flag = down ? RIGHTDOWN : RIGHTUP;
    else if (button == "middle") flag = down ? MIDDLEDOWN : MIDDLEUP;
    else flag = down ? LEFTDOWN : LEFTUP;
    mouse_event(flag, 0, 0, 0, IntPtr.Zero);
  }

  public static void Wheel(int amount) {
    mouse_event(WHEEL, 0, 0, unchecked((uint)amount), IntPtr.Zero);
  }

  public static void Key(int vk, bool down) {
    keybd_event((byte)vk, 0, down ? 0 : KEYUP, IntPtr.Zero);
  }

  // A character is resolved through the active keyboard layout, which is what
  // makes a non-US keyboard type what was actually pressed. The high byte says
  // whether the layout needs Shift held to produce it.
  public static void Char(char ch, bool down) {
    short scan = VkKeyScan(ch);
    if (scan == -1) return;
    int vk = scan & 0xFF;
    bool shift = (scan & 0x100) != 0;
    if (shift && down) keybd_event(0x10, 0, 0, IntPtr.Zero);
    keybd_event((byte)vk, 0, down ? 0 : KEYUP, IntPtr.Zero);
    if (shift && !down) keybd_event(0x10, 0, KEYUP, IntPtr.Zero);
  }
}
"@

while ($true) {
  $line = [Console]::In.ReadLine()
  if ($null -eq $line) { break }
  $p = $line.Split(' ')
  try {
    switch ($p[0]) {
      'm' { [BetweenUsInput]::Move([int]$p[1], [int]$p[2]) }
      'd' { [BetweenUsInput]::Move([int]$p[2], [int]$p[3]); [BetweenUsInput]::Button($p[1], $true) }
      'u' { [BetweenUsInput]::Button($p[1], $false) }
      'w' { [BetweenUsInput]::Wheel([int]$p[1]) }
      'k' { [BetweenUsInput]::Key([int]$p[2], $p[1] -eq 'down') }
      'c' { [BetweenUsInput]::Char([char][int]$p[2], $p[1] -eq 'down') }
    }
  } catch {
    # One malformed line must not end the session's input.
  }
}
`;

/** Browser `code` values that are not a character, mapped to a virtual key. */
const VIRTUAL_KEYS: Record<string, number> = {
  Backspace: 0x08,
  Tab: 0x09,
  Enter: 0x0d,
  NumpadEnter: 0x0d,
  ShiftLeft: 0x10,
  ShiftRight: 0x10,
  ControlLeft: 0x11,
  ControlRight: 0x11,
  AltLeft: 0x12,
  AltRight: 0x12,
  Pause: 0x13,
  CapsLock: 0x14,
  Escape: 0x1b,
  Space: 0x20,
  PageUp: 0x21,
  PageDown: 0x22,
  End: 0x23,
  Home: 0x24,
  ArrowLeft: 0x25,
  ArrowUp: 0x26,
  ArrowRight: 0x27,
  ArrowDown: 0x28,
  PrintScreen: 0x2c,
  Insert: 0x2d,
  Delete: 0x2e,
  MetaLeft: 0x5b,
  MetaRight: 0x5c,
  F1: 0x70,
  F2: 0x71,
  F3: 0x72,
  F4: 0x73,
  F5: 0x74,
  F6: 0x75,
  F7: 0x76,
  F8: 0x77,
  F9: 0x78,
  F10: 0x79,
  F11: 0x7a,
  F12: 0x7b,
};

let backend: ChildProcessWithoutNullStreams | null = null;
/** Last error the helper printed, surfaced through `inputDiagnostics`. */
let lastError: string | null = null;

export function inputSupported(): boolean {
  return process.platform === 'win32';
}

/** What the settings panel shows when control is not working. */
export function inputDiagnostics(): { supported: boolean; running: boolean; error: string | null } {
  return {
    supported: inputSupported(),
    running: backend !== null && !backend.killed,
    error: lastError,
  };
}

function scriptPath(): string {
  const file = path.join(app.getPath('userData'), 'betweenus-remote-input.ps1');
  // Rewritten every start: an old copy from a previous version would be worse
  // than no copy at all.
  fs.writeFileSync(file, SCRIPT, 'utf8');
  return file;
}

/** Starts the helper on first use and reuses it for the rest of the session. */
function ensureBackend(): ChildProcessWithoutNullStreams | null {
  if (!inputSupported()) return null;
  if (backend && !backend.killed) return backend;

  try {
    backend = spawn(
      'powershell.exe',
      ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', scriptPath()],
      { windowsHide: true },
    );
  } catch (error) {
    lastError = error instanceof Error ? error.message : 'PowerShell could not be started';
    backend = null;
    return null;
  }

  backend.on('exit', () => {
    backend = null;
  });
  // A helper that fails to compile its own P/Invoke says so once, on stderr.
  // Swallowing it is what made this silent the first time round.
  backend.stderr.on('data', (chunk: Buffer) => {
    lastError = chunk.toString().trim().split('\n')[0] ?? null;
    console.error('[remote-input]', lastError);
  });
  lastError = null;
  return backend;
}

/** Ends the helper. Called when the last session closes and on quit. */
export function stopInputBackend(): void {
  // Before the helper goes: a modifier is held by the operating system, not by
  // the process that pressed it, so killing the helper mid-chord would leave
  // the machine holding Ctrl with nobody left to let go of it.
  releaseModifiers();
  backend?.stdin.end();
  backend?.kill();
  backend = null;
}

function write(line: string): void {
  const child = ensureBackend();
  if (!child) return;
  try {
    child.stdin.write(`${line}\n`);
  } catch {
    // A helper that died takes the next event with it and is respawned on the
    // one after; dropping a mouse move is not worth throwing over.
    backend = null;
  }
}

/**
 * The display an input event is a fraction of, per source, or null for the
 * primary one.
 *
 * A controller watching the second monitor sends a click at the middle of what
 * it can see; mapping that onto the primary display puts it on a different
 * screen entirely. Whoever chose the monitor sets this - and a remote session
 * and a call are allowed to have chosen differently, which is why there is one
 * of these per source rather than one for the process.
 */
const targetDisplays = new Map<InputSource, string | null>();

export function setInputDisplay(displayId: string | null, source: InputSource = 'session'): void {
  targetDisplays.set(source, displayId);
}

/**
 * Fraction of the shared screen -> a physical pixel on that screen.
 *
 * `bounds` is in device-independent pixels and `SetCursorPos` wants real ones,
 * so on a display running at anything other than 100% scaling the two differ by
 * the scale factor - which is why a click at the bottom right of a 150% screen
 * landed two thirds of the way across it. `dipToScreenPoint` is Electron's own
 * conversion, so this stays right for a display that is scaled *and* offset -
 * and a second monitor is always offset.
 */
function toScreenPoint(x: number, y: number, source: InputSource): { x: number; y: number } {
  const wanted = targetDisplays.get(source) ?? null;
  const target =
    screen.getAllDisplays().find((display) => String(display.id) === wanted) ??
    screen.getPrimaryDisplay();
  const bounds = target.bounds;
  const clamp = (value: number): number => Math.min(1, Math.max(0, value));
  return screen.dipToScreenPoint({
    x: bounds.x + clamp(x) * bounds.width,
    y: bounds.y + clamp(y) * bounds.height,
  });
}

export function applyMouse(input: MouseInput): void {
  const point = toScreenPoint(input.x, input.y, input.source ?? 'session');
  const button = input.button ?? 'left';

  switch (input.action) {
    case 'move':
      write(`m ${point.x} ${point.y}`);
      return;
    case 'down':
      // Position and press in one line: a click that lands where the pointer
      // used to be is the classic remote-desktop bug.
      write(`d ${button} ${point.x} ${point.y}`);
      return;
    case 'up':
      write(`u ${button}`);
      return;
    case 'wheel': {
      // A browser's deltaY grows downward, a Windows wheel notch upward.
      const notches = Math.round(-(input.deltaY ?? 0));
      if (notches !== 0) write(`w ${notches}`);
      return;
    }
  }
}

/**
 * What the machine is currently holding down on each controller's behalf.
 *
 * Per source for the same reason the target display is: two people can be
 * driving at once, and one of them letting go of Ctrl says nothing about the
 * other. What the operating system holds is the union, which is the price of
 * two drivers and not something this can fix.
 */
const heldModifiers = new Map<InputSource, Modifier[]>();

/**
 * Brings the machine's modifiers in line with the controller's, and returns
 * whether the event was itself a modifier - in which case there is nothing
 * further to press: the state change *is* the keystroke.
 */
function reconcileModifiers(input: KeyInput): boolean {
  const source = input.source ?? 'session';
  const own = modifierOf(input.code);
  // A modifier's own event is the most reliable statement of its state there
  // is, and `event.ctrlKey` on the Ctrl keydown itself is not consistent
  // across browsers - so take the action at its word for that one modifier.
  const wanted = new Set(readModifiers(input.modifiers));
  if (own) {
    if (input.action === 'down') wanted.add(own);
    else wanted.delete(own);
  }

  for (const step of planModifiers(heldModifiers.get(source) ?? [], wanted)) {
    write(`k ${step.action} ${MODIFIER_VIRTUAL_KEYS[step.modifier]}`);
  }
  heldModifiers.set(source, [...wanted]);
  return own !== null;
}

/** Lets go of everything, so a session that ends cannot leave Ctrl down. */
export function releaseModifiers(source?: InputSource): void {
  for (const [held, modifiers] of heldModifiers) {
    if (source && held !== source) continue;
    for (const step of planModifiers(modifiers, [])) {
      write(`k ${step.action} ${MODIFIER_VIRTUAL_KEYS[step.modifier]}`);
    }
    heldModifiers.set(held, []);
  }
}

export function applyKey(input: KeyInput): void {
  if (reconcileModifiers(input)) return;

  const virtualKey = VIRTUAL_KEYS[input.code];
  if (virtualKey !== undefined) {
    write(`k ${input.action} ${virtualKey}`);
    return;
  }

  const character = input.key.length === 1 ? input.key : '';
  if (!character) return;
  write(`c ${input.action} ${character.codePointAt(0) ?? 0}`);
}

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  accepts,
  assetFor,
  channelOf,
  compareVersions,
  downloadAsset,
  findUpdate,
  flavorFrom,
  parseReleases,
  parseVersion,
  pickRelease,
  versionOfFile,
  type Release,
} from './updates';

// --- Versions ---------------------------------------------------------------

const v = (text: string) => {
  const parsed = parseVersion(text);
  assert.ok(parsed, `${text} should parse`);
  return parsed;
};

assert.equal(parseVersion('nightly'), null, 'an unparseable tag is skipped, not guessed at');
assert.equal(parseVersion('1.2'), null);
assert.deepEqual(parseVersion('v1.2.3')?.major, 1, 'a leading v is optional');

assert.ok(compareVersions(v('0.0.2'), v('0.0.1')) > 0);
assert.ok(compareVersions(v('0.1.0'), v('0.0.9')) > 0);
assert.ok(
  compareVersions(v('0.0.2'), v('0.0.2-beta.9')) > 0,
  'a stable release beats every pre-release of the same version',
);
assert.ok(compareVersions(v('0.0.2-beta.1'), v('0.0.2-alpha.7')) > 0);
assert.equal(compareVersions(v('1.0.0'), v('v1.0.0')), 0);

// --- Channels ---------------------------------------------------------------

assert.equal(accepts('stable', v('0.0.2-beta.1')), false, 'stable is offered stable only');
assert.equal(accepts('stable', v('0.0.2')), true);
assert.equal(accepts('beta', v('0.0.2-alpha.1')), false);
assert.equal(accepts('beta', v('0.0.2')), true, 'a channel takes everything steadier than itself');
assert.equal(accepts('alpha', v('0.0.2-alpha.1')), true);

assert.equal(channelOf('0.0.1-alpha.9'), 'alpha', 'an alpha install defaults to the alpha channel');
assert.equal(channelOf('0.0.1-beta.2'), 'beta');
assert.equal(channelOf('1.4.0'), 'stable');
assert.equal(channelOf(undefined), 'stable');

// --- Flavours ---------------------------------------------------------------

assert.equal(flavorFrom(false), 'unpacked', 'a development run has nothing to update to');
assert.equal(flavorFrom(true), 'installer');

// --- Releases ---------------------------------------------------------------

const payload = [
  {
    tag_name: 'v0.0.3-beta.1',
    name: 'Beta 1',
    body: 'notes',
    published_at: '2026-01-02T00:00:00Z',
    assets: [
      { name: 'BetweenUs-0.0.3-beta.1-Setup.exe', browser_download_url: 'https://x/setup', size: 90 },
      { name: 'BetweenUs-0.0.3-beta.1-Portable.exe', browser_download_url: 'https://x/portable', size: 88 },
      { name: 'BetweenUs-0.0.3-beta.1-arm64-v8a.apk', browser_download_url: 'https://x/apk', size: 30 },
    ],
  },
  {
    tag_name: 'v0.0.2',
    name: '',
    body: '',
    published_at: '2026-01-03T00:00:00Z',
    assets: [
      { name: 'BetweenUs-0.0.2-Setup.exe', browser_download_url: 'https://x/setup2', size: 90 },
      { name: 'BetweenUs-0.0.2-Portable.exe', browser_download_url: 'https://x/portable2', size: 88 },
    ],
  },
  { tag_name: 'v0.0.4', draft: true, assets: [] },
  { tag_name: 'not-a-version', assets: [] },
];

const releases = parseReleases(payload);
assert.equal(releases.length, 2, 'drafts and unparseable tags are dropped');
assert.equal(releases[1]?.name, 'v0.0.2', 'an unnamed release falls back to its tag');
assert.equal(parseReleases(null).length, 0, 'a body that is not a list is no releases, not a throw');

assert.equal(
  pickRelease(releases, v('0.0.1'), 'stable')?.tag,
  'v0.0.2',
  'stable skips the newer beta',
);
assert.equal(
  pickRelease(releases, v('0.0.1'), 'beta')?.tag,
  'v0.0.3-beta.1',
  'newest by version, not by publish date - v0.0.2 was published later',
);
assert.equal(pickRelease(releases, v('0.0.3'), 'alpha'), null, 'nothing newer, nothing offered');
assert.equal(pickRelease(releases, v('0.0.2'), 'stable'), null, 'the version in hand is not an upgrade');

const beta = releases[0] as Release;
assert.equal(assetFor(beta, 'installer')?.name, 'BetweenUs-0.0.3-beta.1-Setup.exe');
assert.equal(assetFor(beta, 'unpacked'), null);

// A release built for the other platforms only: Windows is offered nothing
// rather than something it cannot run.
const androidOnly: Release = {
  ...beta,
  assets: beta.assets.filter((asset) => asset.name.endsWith('.apk')),
};
assert.equal(assetFor(androidOnly, 'installer'), null);

// The portable exe that used to ship beside the installer is not an update for
// anybody now, and must not be picked up as one.
const portableOnly: Release = {
  ...beta,
  assets: beta.assets.filter((asset) => asset.name.endsWith('-Portable.exe')),
};
assert.equal(assetFor(portableOnly, 'installer'), null);

// A downloaded file names its own version, which is what makes the updates
// directory the record of what is waiting. Round-trip against the name the
// release workflow actually attaches.
assert.equal(versionOfFile('BetweenUs-0.0.3-beta.1-Setup.exe'), '0.0.3-beta.1');
assert.equal(versionOfFile('BetweenUs-1.4.2-Setup.exe'), '1.4.2');
assert.equal(versionOfFile('BetweenUs-0.0.3-Portable.exe'), null, 'not ours to keep');
assert.equal(versionOfFile('BetweenUs-nightly-Setup.exe'), null, 'an unparseable version is not one');
assert.equal(versionOfFile('BetweenUs-0.0.3-Setup.exe.part'), null, 'a half-finished download');

// --- findUpdate -------------------------------------------------------------

const okJson = (body: unknown): typeof fetch =>
  (async () =>
    new Response(JSON.stringify(body), {
      status: 200,
      headers: { 'content-type': 'application/json' },
    })) as unknown as typeof fetch;

const installerOffer = await findUpdate('0.0.1-alpha.9', 'beta', 'installer', okJson(payload));
assert.equal(installerOffer?.version, '0.0.3-beta.1', 'the version drops its leading v');
assert.equal(installerOffer?.asset.name, 'BetweenUs-0.0.3-beta.1-Setup.exe');

assert.equal(
  await findUpdate('0.0.1', 'stable', 'unpacked', okJson(payload)),
  null,
  'a development run never calls GitHub at all',
);
assert.equal(await findUpdate('9.9.9', 'alpha', 'installer', okJson(payload)), null);

await assert.rejects(
  findUpdate(
    '0.0.1',
    'stable',
    'installer',
    (async () => new Response('rate limited', { status: 403 })) as unknown as typeof fetch,
  ),
  /403/,
  'a refused check is reported, not swallowed',
);

// --- downloadAsset ----------------------------------------------------------

const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'betweenus-updates-'));
try {
  const bytes = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8]);
  const progress: number[] = [];
  const file = await downloadAsset(
    { name: 'BetweenUs-0.0.3-Setup.exe', url: 'https://x/setup', size: bytes.length },
    directory,
    (fraction) => progress.push(fraction),
    (async () =>
      new Response(bytes, {
        status: 200,
        headers: { 'content-length': String(bytes.length) },
      })) as unknown as typeof fetch,
  );

  assert.equal(path.basename(file), 'BetweenUs-0.0.3-Setup.exe');
  assert.deepEqual([...fs.readFileSync(file)], [...bytes]);
  assert.equal(progress.at(-1), 1, 'progress ends at whole');
  assert.equal(fs.existsSync(`${file}.part`), false, 'the part file is gone once it is complete');

  await assert.rejects(
    downloadAsset(
      { name: 'BetweenUs-0.0.4-Setup.exe', url: 'https://x/gone', size: 0 },
      directory,
      () => {},
      (async () => new Response('nope', { status: 404 })) as unknown as typeof fetch,
    ),
    /404/,
  );
  assert.equal(
    fs.existsSync(path.join(directory, 'BetweenUs-0.0.4-Setup.exe')),
    false,
    'a failed download leaves nothing runnable behind',
  );
} finally {
  fs.rmSync(directory, { recursive: true, force: true });
}

console.log('updates.check.ts: ok');

/**
 * Desktop updates: what is out there, which build of it this install wants, and
 * getting it onto the disk.
 *
 * This is deliberately the same shape as the Android updater in
 * `apps/android/.../feature/update` rather than electron-updater: the release
 * workflow already publishes named assets to a GitHub Release, so a check is
 * one API call and a download is one more. electron-updater would want a
 * `latest.yml` published alongside them, a `publish` block in
 * `electron-builder.yml`, and a second release path to keep working.
 *
 * Nothing here imports Electron, so it runs under `tsx` in `updates.check.ts`.
 * Applying the download is the one part that needs the app, and that lives in
 * `main.ts`.
 */
import fs from 'node:fs';
import path from 'node:path';

/**
 * Where the builds come from. A constant rather than a setting, same reasoning
 * as Android: this is the project that signs the releases.
 */
export const REPOSITORY = 'aiyu-ayaan/BetweenUs';

export const RELEASES_API = `https://api.github.com/repos/${REPOSITORY}/releases?per_page=30`;

// --- Versions ---------------------------------------------------------------

export const ALPHA = 0;
export const BETA = 1;
export const STABLE = 2;

export interface Version {
  major: number;
  minor: number;
  patch: number;
  /** ALPHA | BETA | STABLE - a finished release sorts above its pre-releases. */
  stage: number;
  stageNumber: number;
}

const VERSION_PATTERN = /^v?(\d+)\.(\d+)\.(\d+)(?:-(alpha|beta)\.(\d+))?$/i;

/**
 * Only the shapes `scripts/release-version.mjs` can produce are understood.
 * Anything else is null and is skipped rather than guessed at, because a guess
 * here downloads the wrong build.
 */
export function parseVersion(text: string | null | undefined): Version | null {
  const match = VERSION_PATTERN.exec((text ?? '').trim());
  if (!match) return null;
  const [, major, minor, patch, label, number] = match;
  const stage = label?.toLowerCase() === 'alpha' ? ALPHA : label?.toLowerCase() === 'beta' ? BETA : STABLE;
  return {
    major: Number(major),
    minor: Number(minor),
    patch: Number(patch),
    stage,
    // A stable release has no pre-release number and must still beat `-beta.9`
    // of the same version.
    stageNumber: number === undefined ? Number.MAX_SAFE_INTEGER : Number(number),
  };
}

export function compareVersions(a: Version, b: Version): number {
  return (
    a.major - b.major ||
    a.minor - b.minor ||
    a.patch - b.patch ||
    a.stage - b.stage ||
    a.stageNumber - b.stageNumber
  );
}

// --- Channels ---------------------------------------------------------------

export type Channel = 'stable' | 'beta' | 'alpha';

const CHANNEL_STAGE: Record<Channel, number> = { stable: STABLE, beta: BETA, alpha: ALPHA };

export const CHANNELS: Channel[] = ['stable', 'beta', 'alpha'];

export function isChannel(value: unknown): value is Channel {
  return typeof value === 'string' && (CHANNELS as string[]).includes(value);
}

/**
 * A channel takes its own builds and everything steadier. Somebody on beta who
 * was offered nothing but betas would never be offered the stable release that
 * supersedes the one they are running.
 */
export function accepts(channel: Channel, version: Version): boolean {
  return version.stage >= CHANNEL_STAGE[channel];
}

/**
 * The channel a build belongs to, used as the default: somebody who installed
 * an alpha wants alphas, and defaulting them to stable would strand them until
 * the version they are running is released.
 */
export function channelOf(version: string | null | undefined): Channel {
  const parsed = parseVersion(version);
  if (parsed?.stage === ALPHA) return 'alpha';
  if (parsed?.stage === BETA) return 'beta';
  return 'stable';
}

// --- Flavours ---------------------------------------------------------------

/**
 * Which Windows build this is.
 *
 * `installer` was put here by `BetweenUs-<version>-Setup.exe` and updates
 * itself with the next one; `unpacked` is a development run, which has no
 * release to update to and must never be offered one.
 *
 * There was a third, `portable`, for the single exe that shipped beside the
 * installer. Windows ships one build now, so a copy of that portable exe is
 * treated as an install and is offered the setup exe - which is the only
 * update it can be given, and installs properly over it.
 */
export type Flavor = 'installer' | 'unpacked';

export function flavorFrom(packaged: boolean): Flavor {
  return packaged ? 'installer' : 'unpacked';
}

// --- Releases ---------------------------------------------------------------

export interface ReleaseAsset {
  name: string;
  url: string;
  size: number;
}

export interface Release {
  version: Version;
  tag: string;
  name: string;
  notes: string;
  publishedAt: string;
  assets: ReleaseAsset[];
}

/** The GitHub JSON this understands, trimmed to what it reads. */
interface GithubRelease {
  tag_name?: string;
  name?: string;
  body?: string;
  published_at?: string;
  draft?: boolean;
  assets?: Array<{ name?: string; browser_download_url?: string; size?: number }>;
}

export function parseReleases(payload: unknown): Release[] {
  if (!Array.isArray(payload)) return [];
  const releases: Release[] = [];
  for (const entry of payload as GithubRelease[]) {
    if (entry?.draft) continue;
    const version = parseVersion(entry?.tag_name);
    if (!version) continue;
    releases.push({
      version,
      tag: entry.tag_name ?? '',
      name: entry.name?.trim() || (entry.tag_name ?? ''),
      notes: entry.body ?? '',
      publishedAt: entry.published_at ?? '',
      assets: (entry.assets ?? [])
        .filter((asset) => asset?.name && asset?.browser_download_url)
        .map((asset) => ({
          name: asset.name as string,
          url: asset.browser_download_url as string,
          size: asset.size ?? 0,
        })),
    });
  }
  return releases;
}

/**
 * The newest release on `channel` that is newer than what is installed.
 *
 * "Newer" is by version, never by publish date: a stable release cut after an
 * alpha is still not an upgrade for somebody running that alpha.
 */
export function pickRelease(
  releases: Release[],
  installed: Version | null,
  channel: Channel,
): Release | null {
  let best: Release | null = null;
  for (const release of releases) {
    if (!accepts(channel, release.version)) continue;
    if (installed && compareVersions(release.version, installed) <= 0) continue;
    if (!best || compareVersions(release.version, best.version) > 0) best = release;
  }
  return best;
}

/**
 * The asset this install can actually apply: the setup exe, and nothing else.
 * A release that built the other platforms only offers nothing rather than
 * handing Windows an APK.
 */
export function assetFor(release: Release, flavor: Flavor): ReleaseAsset | null {
  if (flavor === 'unpacked') return null;
  return release.assets.find((asset) => asset.name.toLowerCase().endsWith('-setup.exe')) ?? null;
}

/**
 * The version in a downloaded file's name, or null if it is not one of ours.
 *
 * The other half of the naming contract `assetFor` matches on: the release
 * workflow names the asset, this reads it back, and the directory a download
 * waits in needs nothing written down beside it. See main.ts.
 */
export function versionOfFile(name: string): string | null {
  const label = /^BetweenUs-(.+)-Setup\.exe$/i.exec(name)?.[1];
  return label && parseVersion(label) ? label : null;
}

// --- The network side -------------------------------------------------------

export interface UpdateOffer {
  version: string;
  name: string;
  notes: string;
  publishedAt: string;
  asset: ReleaseAsset;
}

/**
 * What this install should be offered, or null for "nothing to do".
 *
 * Unauthenticated, so it is subject to GitHub's sixty-requests-an-hour-per-
 * address limit. That is ample for a check on launch and a button in settings,
 * and it is why a failure here is reported rather than retried.
 */
export async function findUpdate(
  installedVersion: string,
  channel: Channel,
  flavor: Flavor,
  fetchImpl: typeof fetch = fetch,
): Promise<UpdateOffer | null> {
  if (flavor === 'unpacked') return null;
  const response = await fetchImpl(RELEASES_API, {
    headers: { Accept: 'application/vnd.github+json' },
  });
  if (!response.ok) throw new Error(`GitHub answered ${response.status}`);
  const release = pickRelease(
    parseReleases(await response.json()),
    parseVersion(installedVersion),
    channel,
  );
  if (!release) return null;
  const asset = assetFor(release, flavor);
  if (!asset) return null;
  return {
    version: release.tag.replace(/^v/, ''),
    name: release.name,
    notes: release.notes,
    publishedAt: release.publishedAt,
    asset,
  };
}

/**
 * Streams the asset into `directory` and answers with where it landed.
 *
 * Streamed rather than buffered because these are ninety-megabyte executables
 * and this process is also the one drawing the window. `onProgress` gets a
 * fraction, or -1 for as long as the total length is unknown.
 */
export async function downloadAsset(
  asset: ReleaseAsset,
  directory: string,
  onProgress: (fraction: number) => void,
  fetchImpl: typeof fetch = fetch,
): Promise<string> {
  const target = path.join(directory, asset.name);
  const response = await fetchImpl(asset.url, { headers: { Accept: 'application/octet-stream' } });
  if (!response.ok || !response.body) throw new Error(`Download answered ${response.status}`);

  // Content-Length is the redirected object's, which is the honest one; the
  // release metadata's size is the fallback for a server that omits it.
  const total = Number(response.headers.get('content-length')) || asset.size;
  const partial = `${target}.part`;
  const sink = fs.createWriteStream(partial);
  let received = 0;

  try {
    for await (const chunk of response.body as unknown as AsyncIterable<Uint8Array>) {
      received += chunk.byteLength;
      if (!sink.write(chunk)) await new Promise<void>((resolve) => sink.once('drain', () => resolve()));
      onProgress(total > 0 ? Math.min(1, received / total) : -1);
    }
    await new Promise<void>((resolve, reject) => {
      sink.end((error?: Error | null) => (error ? reject(error) : resolve()));
    });
  } catch (error) {
    sink.destroy();
    fs.rmSync(partial, { force: true });
    throw error;
  }

  // A half-written file must never be runnable, so it only gets its real name
  // once every byte is on the disk.
  fs.rmSync(target, { force: true });
  fs.renameSync(partial, target);
  return target;
}

