/**
 * A real web origin for the Listen Together player to live in.
 *
 * A packaged build serves the renderer from `file://`, and a YouTube embed
 * framed by a `file://` document is refused: "Video player configuration
 * error", error 153, over a black frame. The embed decides that from what the
 * browser tells it about the page it is on, and a `file://` page has nothing to
 * tell it - no origin worth the name and no referrer.
 *
 * Two things were measured before this was written, because both are the
 * obvious fix and neither works:
 *
 * - **Filling in the `Referer` header** for the embed request. It changes the
 *   refusal from 153 to 152 and nothing else; not one byte of media is
 *   fetched. The header is not what the player reads.
 * - **Serving the renderer from a custom `app://` scheme**, registered
 *   standard and secure. Identical: 153 bare, 152 with a referrer. Only
 *   `http`/`https` counts as somewhere a player may be embedded.
 *
 * What does work is giving the embed an ancestor that is a real web origin. So
 * the main process runs a loopback HTTP server with exactly one page on it, and
 * the renderer frames *that* instead of framing YouTube directly. The page
 * frames the embed and relays messages between it and the app in both
 * directions, so the protocol in `src/services/youtube.ts` is unchanged -
 * commands go down, state comes up, and the only difference is which window
 * they pass through.
 *
 * The app's own origin does not move, which is the point of doing it this way
 * rather than serving the whole renderer over `http://127.0.0.1`. That would
 * work too, and it would move every user's device identity, endpoint and
 * settings to a new origin - a re-login and a re-keyed E2EE device for a music
 * player.
 *
 * What the server is:
 *
 * - Bound to `127.0.0.1` on a port the OS picks. Nothing off this machine can
 *   reach it, and nothing about it is guessable between launches.
 * - One page, behind a random path. A page in the user's browser cannot find it
 *   by scanning ports, and finding it would gain nothing: it holds no data and
 *   answers no questions.
 * - Static HTML with no app state in it at all. The video id arrives in the
 *   query string and is checked against YouTube's own id shape before it is put
 *   anywhere.
 */
import { createServer, type Server } from 'node:http';
import { randomBytes } from 'node:crypto';

/** The only origins the relay will speak to, in either direction. */
export const YOUTUBE_ORIGINS = [
  'https://www.youtube.com',
  'https://www.youtube-nocookie.com',
  'https://youtube.com',
  'https://youtube-nocookie.com',
  'https://m.youtube.com',
  'https://music.youtube.com',
];

const EMBED_HOST = 'https://www.youtube.com';

/** YouTube's id shape. Anything else is not put into a frame `src`. */
export function validVideoId(value: string | null): string | null {
  return value && /^[A-Za-z0-9_-]{11}$/.test(value) ? value : null;
}

/**
 * The page, as it is served.
 *
 * It is deliberately small enough to read in one go, because it sits between
 * the app and a third party and both directions of that channel are checked
 * here:
 *
 * - Down: only messages from the window that framed this page, which is the
 *   app, are passed to the embed.
 * - Up: only messages from the embed frame, on a YouTube origin, are passed to
 *   the app. Anything else on the machine that got hold of this URL can post
 *   all it likes and be ignored.
 */
export function relayHtml(): string {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>BetweenUs player</title>
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; frame-src https://www.youtube.com https://www.youtube-nocookie.com https://youtube.com https://youtube-nocookie.com; style-src 'unsafe-inline'; script-src 'unsafe-inline'">
<meta name="referrer" content="strict-origin-when-cross-origin">
<style>html,body{margin:0;height:100%;background:#000;overflow:hidden}iframe{border:0;width:100%;height:100%;display:block}</style>
</head>
<body>
<script>
(function () {
  var origins = ${JSON.stringify(YOUTUBE_ORIGINS)};
  var id = new URLSearchParams(location.search).get('v') || '';
  if (!/^[A-Za-z0-9_-]{11}$/.test(id)) return;

    var safeOrigin = location.origin.replace('127.0.0.1', 'localhost');
    var params = new URLSearchParams({
      enablejsapi: '1',
      autoplay: '1',
      controls: '0',
      disablekb: '1',
      rel: '0',
      modestbranding: '1',
      playsinline: '1',
      fs: '1',
      // The player is told what origin it runs on, mapped to localhost hostname
      // rather than raw 127.0.0.1 which triggers YouTube's domain filters.
      origin: safeOrigin,
      widget_referrer: safeOrigin,
    });

  var frame = document.createElement('iframe');
  frame.title = 'Listen Together';
  frame.allow = 'autoplay; encrypted-media; fullscreen; picture-in-picture';
  frame.setAttribute('allowfullscreen', 'true');
  frame.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
  frame.referrerPolicy = 'strict-origin-when-cross-origin';
  frame.src = '${EMBED_HOST}/embed/' + id + '?' + params.toString();
  document.body.appendChild(frame);

  window.addEventListener('message', function (event) {
    // Up: the embed talking. Origin and source both, because either alone is
    // a hole - one lets any frame on a YouTube origin in, the other lets a
    // window that got a handle to this one in.
    if (event.source === frame.contentWindow) {
      if (origins.indexOf(event.origin) === -1) return;
      parent.postMessage(event.data, '*');
      return;
    }
    // Down: the app talking. Only the window that framed this page.
    if (event.source === parent && frame.contentWindow) {
      frame.contentWindow.postMessage(event.data, '*');
    }
  });
})();
</script>
</body>
</html>
`;
}

export interface Relay {
  /** The page URL, path token included. The renderer appends `&v=<id>`. */
  url: string;
  /** `http://127.0.0.1:<port>`, which is what messages from it arrive as. */
  origin: string;
  close: () => void;
}

/**
 * Starts the server and answers with where it is.
 *
 * A rejected promise is not fatal anywhere: the renderer falls back to framing
 * the embed directly, which is what the web client does and what a development
 * run - served over `http://localhost` already - needs anyway.
 */
export function startYouTubeRelay(): Promise<Relay> {
  const token = randomBytes(16).toString('hex');
  const pathname = `/${token}/player.html`;
  const body = relayHtml();

  return new Promise((resolve, reject) => {
    const server: Server = createServer((request, response) => {
      const requested = (request.url ?? '').split('?')[0];
      if (request.method !== 'GET' || requested !== pathname) {
        response.writeHead(404).end();
        return;
      }
      response.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-store',
        // Nothing off this page may be framed by anything but the app, and
        // nothing about it is worth guessing at.
        'X-Content-Type-Options': 'nosniff',
        'Referrer-Policy': 'origin',
      });
      response.end(body);
    });

    server.on('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const address = server.address();
      if (typeof address === 'string' || address === null) {
        server.close();
        reject(new Error('The player relay got no port.'));
        return;
      }
      const origin = `http://127.0.0.1:${address.port}`;
      resolve({
        url: `${origin}${pathname}`,
        origin,
        close: () => server.close(),
      });
    });
  });
}

/**
 * The real youtube.com, inside the app window.
 *
 * The point of this file is that pasting links is not browsing. Somebody who
 * wants to put music on wants to sign in, look at their subscriptions and their
 * playlists, search for a thing they half remember, and press it - and none of
 * that is reachable from an `/embed/` frame.
 *
 * It cannot be an iframe either. youtube.com sends `X-Frame-Options` and a
 * `frame-ancestors` policy that refuse framing outright, so a browser tab can
 * never show the site inside another page - and that is not a thing a client
 * gets to work around. Only `/embed/<id>` is frameable, which is the player and
 * nothing else. This is therefore a **desktop-only** capability, and the web
 * client says so rather than pretending.
 *
 * What it is not: `webviewTag`. Turning that on would give the renderer the
 * ability to mount arbitrary web content anywhere, which is a permission the
 * whole hardening story in `main.ts` exists to withhold. Instead the main
 * process owns a `WebContentsView`, and the renderer may only ask for it to be
 * put over a rectangle - the same "follow a slot" arrangement the embedded
 * player uses, for the same reason: the view must not be destroyed and rebuilt
 * every time a React component happens to unmount.
 *
 * Three things make it safe to point at the open web:
 *
 * - **Its own session partition.** `persist:youtube` keeps a signed-in Google
 *   account for next time and keeps it entirely apart from the app's own
 *   cookies. Nothing here can read a BetweenUs session and nothing in the app
 *   is reachable from a page loaded here.
 * - **No preload, no Node.** It is an ordinary browser context with no bridge
 *   into this application at all.
 * - **It cannot wander.** Navigation is confined to Google's own hosts, which
 *   is what a sign-in flow needs and is a great deal less than "the internet";
 *   anything else is opened in the user's real browser instead. New windows are
 *   refused for the same reason.
 */
import { WebContentsView, session as electronSession, shell, type BrowserWindow } from 'electron';

/** The site, and the hosts a Google sign-in legitimately passes through. */
const ALLOWED_HOSTS = [
  'youtube.com',
  'www.youtube.com',
  'm.youtube.com',
  'music.youtube.com',
  'studio.youtube.com',
  'accounts.google.com',
  'accounts.youtube.com',
  'myaccount.google.com',
  'consent.youtube.com',
  'consent.google.com',
];

const HOME = 'https://www.youtube.com';

export interface ViewBounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** What the renderer is told every time the page changes. */
export interface YouTubeNavigation {
  url: string;
  title: string;
  /** The video id, when the current page is one. Null everywhere else. */
  videoId: string | null;
  canGoBack: boolean;
  canGoForward: boolean;
  loading: boolean;
}

let view: WebContentsView | null = null;
let owner: BrowserWindow | null = null;

function hostOf(url: string): string | null {
  try {
    return new URL(url).hostname.toLowerCase();
  } catch {
    return null;
  }
}

function allowed(url: string): boolean {
  if (url === 'about:blank') return true;
  const host = hostOf(url);
  return host !== null && ALLOWED_HOSTS.includes(host);
}

/**
 * The video id on the page, if this page is a video.
 *
 * Deliberately the same shapes the pasted-link parser accepts, because they are
 * the same URLs - a person browsing lands on exactly what a person copying
 * would have copied.
 */
export function videoIdOf(url: string): string | null {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  const path = parsed.pathname.split('/').filter(Boolean);
  const valid = (id: string | null | undefined): string | null =>
    id && /^[A-Za-z0-9_-]{11}$/.test(id) ? id : null;

  if (parsed.hostname === 'youtu.be') return valid(path[0]);
  if (path[0] === 'shorts' || path[0] === 'embed' || path[0] === 'live') return valid(path[1]);
  return valid(parsed.searchParams.get('v'));
}

/**
 * Stops whatever the page has started playing.
 *
 * The browser is for picking. A watch page autoplays, an SPA click starts one
 * without a load event, YouTube runs the next video when one ends, and a person
 * poking the page can start one by hand - so "pause it after navigating" was
 * four races, and it lost some of them. `media-started-playing` is the one
 * place all four arrive: whatever begins, whenever it begins, this is the
 * event, and pausing from it needs no timing guess at all.
 *
 * The video element rather than the whole WebContents, because muting a page is
 * not stopping it: a muted video is still decoded and still downloaded, for a
 * picture nobody chose to watch.
 */
function quieten(): void {
  const contents = view?.webContents;
  if (!contents || contents.isDestroyed()) return;
  void contents
    .executeJavaScript('document.querySelectorAll("video").forEach((v) => v.pause());', true)
    .catch(() => undefined);
}

function report(): void {
  if (!view || !owner || owner.isDestroyed()) return;
  const contents = view.webContents;
  const url = contents.getURL();
  owner.webContents.send('youtube:navigated', {
    url,
    title: contents.getTitle(),
    videoId: videoIdOf(url),
    canGoBack: contents.canGoBack(),
    canGoForward: contents.canGoForward(),
    loading: contents.isLoading(),
  } satisfies YouTubeNavigation);
}

export function openYouTubeView(window: BrowserWindow, bounds: ViewBounds): void {
  if (view && owner === window) {
    view.setVisible(true);
    // Muted again on every show, not only when the view is built. The mute is
    // a property of the *page*, and a page that navigated, crashed and was
    // reloaded, or came back through the sign-in flow is not guaranteed to
    // still carry the one set on the WebContents that first loaded it.
    view.webContents.setAudioMuted(true);
    setYouTubeBounds(bounds);
    return;
  }
  closeYouTubeView();

  owner = window;
  view = new WebContentsView({
    webPreferences: {
      // Its own cookie jar, so a signed-in Google account survives a restart and
      // is nowhere near the app's own session.
      session: electronSession.fromPartition('persist:youtube'),
      // No preload and no Node: this is an ordinary browser context with no way
      // into this application.
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
      // The picture must keep decoding when the window is behind something.
      backgroundThrottling: false,
    },
  });

  const contents = view.webContents;
  // Silent, always. This half of the panel is for *choosing* a track: the sound
  // of the call is the shared player, which every window runs in step. An
  // unmuted browser here plays a second, unsynchronised copy of the same song
  // in one person's headphones over the one everybody agreed on.
  contents.setAudioMuted(true);
  // A real browser's, because YouTube serves a degraded page to anything it
  // does not recognise - and an Electron user agent is one of those.
  contents.setUserAgent(
    contents.getUserAgent().replace(/ Electron\/[\d.]+/, '').replace(/ BetweenUs\/[\d.]+/, ''),
  );

  contents.setWindowOpenHandler(({ url }) => {
    // A link out of YouTube is a link out of the app: it opens in the real
    // browser, where the user's own extensions, bookmarks and judgement live.
    if (!allowed(url)) void shell.openExternal(url);
    else void contents.loadURL(url);
    return { action: 'deny' };
  });

  contents.on('will-navigate', (event, url) => {
    if (allowed(url)) return;
    event.preventDefault();
    void shell.openExternal(url);
  });

  // Every one of these, because YouTube is a single-page application: a click
  // from the home page to a video is `did-navigate-in-page` and nothing else,
  // and listening only for `did-navigate` means the "add this" button stays
  // grey on the video somebody just opened.
  // Trying to play something in here is how somebody says "play this" - the
  // thumbnail they clicked, the play button they pressed, the next video the
  // page queued up. So it is not refused, it is *redirected*: the page is
  // paused and the call is told to play that video, which is the same picture
  // in the place everybody can see it.
  //
  // This is the whole trigger, and it replaced watching for navigations. A
  // navigation is a proxy for the intent and a bad one - it fires for a page
  // opened to read the description, and misses the play pressed on a page
  // already open.
  contents.on('media-started-playing', () => {
    quieten();
    const videoId = videoIdOf(contents.getURL());
    if (!videoId || !owner || owner.isDestroyed()) return;
    owner.webContents.send('youtube:play', videoId);
  });

  contents.on('did-navigate', () => report());
  contents.on('did-navigate-in-page', () => report());
  contents.on('did-finish-load', () => report());
  contents.on('did-stop-loading', () => report());
  contents.on('page-title-updated', () => report());

  window.contentView.addChildView(view);
  setYouTubeBounds(bounds);
  void contents.loadURL(HOME);
}

export function setYouTubeBounds(bounds: ViewBounds): void {
  if (!view) return;
  view.setBounds({
    x: Math.round(bounds.x),
    y: Math.round(bounds.y),
    width: Math.max(0, Math.round(bounds.width)),
    height: Math.max(0, Math.round(bounds.height)),
  });
}

/**
 * Hides without destroying.
 *
 * A `WebContentsView` is a real browser: closing it loses the scroll position,
 * the search that was typed and the video that was half watched. Collapsing the
 * panel should not cost any of that, so the view is only made invisible - the
 * renderer asks for it to be destroyed when the call ends.
 */
export function hideYouTubeView(): void {
  view?.setVisible(false);
  // And stop whatever it had started. The site plays a video the moment it is
  // clicked, and a hidden view goes on decoding it - a second copy of the same
  // stream, pulled down for nobody, while the shared player plays the real one.
  // Muted was enough for the sound; this is the bandwidth.
  quieten();
}

export function closeYouTubeView(): void {
  if (view && owner && !owner.isDestroyed()) owner.contentView.removeChildView(view);
  view?.webContents.close();
  view = null;
  owner = null;
}

export function youTubeGoBack(): void {
  const contents = view?.webContents;
  if (contents?.canGoBack()) contents.goBack();
}

export function youTubeGoForward(): void {
  const contents = view?.webContents;
  if (contents?.canGoForward()) contents.goForward();
}

export function youTubeHome(): void {
  void view?.webContents.loadURL(HOME);
}

/** Search, as a URL rather than as an API call - no key, and the real results. */
export function youTubeSearch(query: string): void {
  const url = `${HOME}/results?search_query=${encodeURIComponent(query.slice(0, 200))}`;
  void view?.webContents.loadURL(url);
}

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

/**
 * The service worker: what is left of BetweenUs when the tab is closed.
 *
 * Its whole job is push. There is no offline caching here and no fetch handler
 * on purpose - a cached shell of an end-to-end encrypted app that cannot reach
 * its server is a login screen that does not work, which is worse than the
 * browser's own offline page.
 *
 * ## What it can and cannot say
 *
 * A message body is sealed with the channel key. That key is unwrapped with the
 * account's identity key, which lives in the *page*, and the wrapped copies are
 * behind an authenticated API call. None of that is reachable from here, and
 * building it here would mean a second copy of the key ladder running in a
 * context the user cannot see.
 *
 * So this worker never shows the words. A message becomes "Ayaan sent a
 * message"; opening it hands over to the app, which has the keys and shows what
 * was actually said. Everything that carries no sealed content - a friend
 * request, being added to a server, who is in a call - is shown in full,
 * because there is nothing to hide.
 *
 * That is a real difference from Android, where the app itself is woken and
 * decrypts in a cold process. It is written down in `docs/architecture/
 * notifications.md` rather than left to be discovered.
 *
 * ## The open tab wins
 *
 * If a client is already running, the push is handed to it and no notification
 * is drawn here. That client can decrypt, and it knows what is on screen. The
 * worker only draws when nobody is there to do it better.
 */

/* eslint-env serviceworker */
/* global clients */

/** One notification per channel, replaced rather than stacked. */
const tagFor = (data) => {
  switch (data.type) {
    case 'message.created':
    case 'message.deleted':
    case 'channel.read':
      return `channel:${data.channelId}`;
    case 'call.roster':
      return `call:${data.channelId}`;
    // Its own tag, not the roster's: a ring must not be replaced by the quiet
    // announcement that arrives a second later when the caller joins.
    // `call.handled` shares it because its only job is to close it - this
    // account answered or declined the call on another device.
    case 'call.ring':
    case 'call.handled':
      return `ring:${data.channelId}`;
    case 'remote.session':
      return `remote:${data.sessionId}`;
    case 'friend.request':
    case 'friend.accepted':
      return `friend:${data.actorId}`;
    case 'server.member.added':
      return `server:${data.serverId}`;
    default:
      return 'betweenus';
  }
};

/**
 * What to show, or null for a push whose only job is to take something away.
 *
 * `message.created` is the one that has to lie by omission: the body is
 * ciphertext and this worker holds no key, so it says that something was said
 * rather than what.
 */
function present(data) {
  switch (data.type) {
    case 'message.created':
      return {
        title: data.authorName || 'New message',
        body: 'Sent a message',
        icon: data.authorAvatarUrl || '/icon.png',
      };
    case 'friend.request':
      return { title: data.actorName, body: 'Sent you a friend request', icon: data.actorAvatarUrl || '/icon.png' };
    case 'friend.accepted':
      return { title: data.actorName, body: 'Accepted your friend request', icon: data.actorAvatarUrl || '/icon.png' };
    case 'server.member.added':
      return { title: data.serverName, body: 'You were added to this server', icon: data.serverIconUrl || '/icon.png' };
    case 'call.roster':
      // An empty roster is the call ending, and the notification for it is
      // cancelled rather than rewritten - see below.
      return data.count === '0'
        ? null
        : {
            title: `Call in ${data.channelName}`,
            body: data.participants ? `${data.participants} in the call` : 'Somebody is in the call',
            icon: '/icon.png',
            requireInteraction: true,
          };
    case 'call.ring':
      return {
        title: `${data.callerName} is calling`,
        body: `Ringing you into ${data.channelName}`,
        icon: data.callerAvatarUrl || '/icon.png',
        // It stays until it is answered or dismissed. Everything else here can
        // be caught up with later; a person waiting for an answer cannot.
        requireInteraction: true,
      };
    case 'remote.session':
      return data.state === 'ended'
        ? null
        : {
            title: 'Remote session',
            body: `${data.actorName} connected to ${data.machineName}`,
            icon: '/icon.png',
            requireInteraction: true,
          };
    // These exist only to close something.
    case 'message.deleted':
    case 'channel.read':
    case 'call.handled':
      return null;
    default:
      return null;
  }
}

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()));

self.addEventListener('push', (event) => {
  let data;
  try {
    data = event.data ? event.data.json() : null;
  } catch {
    data = null;
  }
  if (!data || typeof data.type !== 'string') return;

  event.waitUntil(
    (async () => {
      // A running client can decrypt and knows what is on screen. Handing the
      // push over rather than drawing here is what stops a notification
      // appearing beside the conversation it is about.
      const running = await clients.matchAll({ type: 'window', includeUncontrolled: true });
      if (running.length > 0) {
        for (const client of running) client.postMessage({ betweenus: 'push', data });
        return;
      }

      const shown = present(data);
      if (!shown) {
        // Nothing to draw: this push exists to take a notification away.
        const open = await self.registration.getNotifications({ tag: tagFor(data) });
        for (const notification of open) notification.close();
        return;
      }

      await self.registration.showNotification(shown.title, {
        body: shown.body,
        icon: shown.icon,
        badge: '/icon.png',
        tag: tagFor(data),
        renotify: true,
        requireInteraction: shown.requireInteraction === true,
        data,
      });
    })(),
  );
});

/**
 * Tap-through: what opening a notification is supposed to do.
 *
 * A notification nobody can act on is a notification people turn off. Focusing
 * a tab that is already open beats opening a second one, and either way the
 * app is told where to go rather than being dropped at the front door.
 */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const data = event.notification.data ?? {};
  const route = routeFor(data);

  event.waitUntil(
    (async () => {
      const running = await clients.matchAll({ type: 'window', includeUncontrolled: true });
      for (const client of running) {
        if ('focus' in client) {
          client.postMessage({ betweenus: 'open', route });
          await client.focus();
          return;
        }
      }
      // Nothing running. The route travels in the URL instead, which is the
      // only channel a page that does not exist yet can be told anything on.
      await clients.openWindow(route.url);
    })(),
  );
});

/** Where a push points. One shape, whether it is delivered by URL or message. */
function routeFor(data) {
  switch (data.type) {
    case 'message.created':
      return { kind: 'channel', channelId: data.channelId, url: `/?channel=${encodeURIComponent(data.channelId)}` };
    case 'call.roster':
    case 'call.ring':
    case 'call.handled':
      return { kind: 'call', channelId: data.channelId, url: `/?call=${encodeURIComponent(data.channelId)}` };
    case 'remote.session':
      return { kind: 'remote', machineId: data.machineId, url: `/?remote=${encodeURIComponent(data.machineId)}` };
    case 'friend.request':
    case 'friend.accepted':
      return { kind: 'friends', url: '/?view=friends' };
    case 'server.member.added':
      return { kind: 'server', serverId: data.serverId, url: `/?server=${encodeURIComponent(data.serverId)}` };
    default:
      return { kind: 'home', url: '/' };
  }
}

import { useEffect, useState } from 'react';
import { useAuthStore } from './stores/auth';
import { useChatStore } from './stores/chat';
import { captureInviteFromUrl } from './services/invite-link';
import { startChannelFocus } from './services/channel-focus';
import { useFriendsStore } from './stores/friends';
import { useStatusStore } from './stores/status';
import { releaseAllStatusMedia } from './services/status-media';
import { usePresenceStore } from './stores/presence';
import {
  loadNotificationPreferences,
  onNotificationActivate,
  resetNotificationPreferences,
} from './services/notifications';
import { stopAgent, useAgentStore } from './services/remote-agent';
import { isDesktopRuntime } from './services/platform';
import {
  onPushMessage,
  startWebPush,
  takeStartupRoute,
  type PushRoute,
} from './services/web-push';
import { useRemoteStore } from './stores/remote';
import { useRingStore } from './stores/ring';
import { LoginScreen } from './features/auth/LoginScreen';
import { ServerRail } from './features/servers/ServerRail';
import { ServerSettings } from './features/servers/ServerSettings';
import { ChannelSidebar } from './features/channels/ChannelSidebar';
import { HomeSidebar } from './features/home/HomeSidebar';
import { FriendsView } from './features/home/FriendsView';
import { StatusScreen } from './features/status/StatusScreen';
import { StatusViewer } from './features/status/StatusViewer';
import { StatusComposer } from './features/status/StatusComposer';
import { RemoteView } from './features/remote/RemoteView';
import { RemoteConsent } from './features/remote/RemoteConsent';
import { RemoteSessionView } from './features/remote/RemoteSessionView';
import { MemberList } from './features/members/MemberList';
import { ChatView } from './features/chat/ChatView';
import { PinnedPanel } from './features/chat/PinnedPanel';
import { SearchPanel } from './features/chat/SearchPanel';
import { UserSettings } from './features/settings/UserSettings';
import { VoiceChannelView } from './features/voice/VoiceChannelView';
import { CallAudio } from './features/voice/CallAudio';
import { ShareControlConsent } from './features/voice/ShareControlConsent';
import { IncomingCall } from './features/voice/IncomingCall';
import { ProfileView } from './components/ProfileView';
import { AvatarChoice } from './components/AvatarChoice';
import { ProfileScreen } from './components/ProfileScreen';
