import { BetweenUsLogoIcon } from './components/icons';
import { ErrorBoundary } from './components/ErrorBoundary';
import { closedPanelProps, useFocusTrap } from './services/focus-trap';

/**
 * Both clients mount this: the Electron renderer and the browser bundle in
 * `apps/web`. The boundary is here rather than in either entry point so neither
 * can be the one that forgot it - a render that throws anywhere below this is a
 * message on screen, not an empty window.
 */
export default function App(): JSX.Element {
  return (
    <ErrorBoundary>
      <Session />
    </ErrorBoundary>
  );
}

function Session(): JSX.Element {
  const status = useAuthStore((state) => state.status);
  const restore = useAuthStore((state) => state.restore);
  const loadServers = useChatStore((state) => state.loadServers);
  const loadDirects = useChatStore((state) => state.loadDirects);
  const loadFriends = useFriendsStore((state) => state.load);
  const loadStatuses = useStatusStore((state) => state.load);
  const loadUnread = useChatStore((state) => state.loadUnread);
  const reset = useChatStore((state) => state.reset);
  const resetFriends = useFriendsStore((state) => state.reset);

  const login = useAuthStore((state) => state.login);
  // Sign-in is attempted before anything renders, so a restored or scripted
  // session never flashes the login form on the way in.
  const [booting, setBooting] = useState(true);

  // Before anything else, and before the first render: a window opened by an
  // invite link has the code in its address bar, and the sign-in that may
  // follow reloads the page. Taking it now means it survives that.
  useEffect(() => {
    captureInviteFromUrl();
  }, []);

  useEffect(() => {
    void (async () => {
      try {
        await restore();
        if (useAuthStore.getState().status !== 'authenticated') {
          // `pnpm dev:duo` hands each test window an identity so two clients can
          // be driven side by side without typing credentials twice.
          const credentials = await window.betweenus?.devLogin();
          if (credentials) await login(credentials.email, credentials.password);
        }
      } finally {
        setBooting(false);
      }
    })();
  }, [restore, login]);

  const resetPresence = usePresenceStore((state) => state.reset);

  /**
   * Coming back to the window means the channel on screen has been read.
   *
   * Without this a message that arrived while the window was in the background
   * kept its badge forever: the count is cleared when a channel is opened, and
   * the channel it arrived in was already open.
   */
  useEffect(() => {
    const read = (): void => {
      if (document.hidden) return;
      useChatStore.getState().markActiveRead();
    };
    window.addEventListener('focus', read);
    document.addEventListener('visibilitychange', read);
    return () => {
      window.removeEventListener('focus', read);
      document.removeEventListener('visibilitychange', read);
    };
  }, []);

  /**
   * Which conversation is in front of this person, told to the server so it
   * does not wake their phone for it. See services/channel-focus.ts.
   */
  useEffect(() => startChannelFocus(), []);

  // Clicking a notification brings the window back and opens what it was about.
  useEffect(
    () =>
      onNotificationActivate((channelId) =>
        void useChatStore.getState().selectChannel(channelId),
      ),
    [],
  );

  /**
   * The same thing for a browser, where the notification was drawn by the
   * service worker and the tab may not have existed when it was tapped.
   *
   * Two ways in, because there are two situations. A tab that is already
   * running is told over `postMessage`; one that had to be opened is told in
   * the query string, which is the only channel a page that does not exist yet
   * can be told anything on. Both end here, in one function, so a route can
   * never work one way and not the other.
   */
  useEffect(() => {
    const startup = takeStartupRoute();
    if (startup) followPushRoute(startup);
    return onPushMessage((message) => {
      if (message.betweenus === 'open') {
        followPushRoute(message.route);
        return;
      }
      // A ring that arrived as a push while this tab was open. The presence
      // socket normally gets there first and this is the same ring by another
      // road, which the store recognises - but a socket that has dropped and
      // not yet reconnected is exactly when somebody rings, so the push is
      // worth listening to rather than assuming the socket was up.
      if (message.betweenus === 'push' && message.data.type === 'call.ring') {
        const ring = message.data;
        useRingStore.getState().show({
          channelId: ring.channelId,
          channelName: ring.channelName,
          callerId: ring.callerId,
          callerName: ring.callerName,
          ...(ring.callerAvatarUrl ? { callerAvatarUrl: ring.callerAvatarUrl } : {}),
        });
        return;
      }
      // Answered or declined on another device. The presence socket says the
      // same thing - the roster for an answer, `call.handled` for a decline -
      // and for the same reason as above it is not the only road worth
      // listening on.
      if (message.betweenus === 'push' && message.data.type === 'call.handled') {
        useRingStore.getState().handledElsewhere(message.data.channelId);
      }
    });
  }, []);

  // ─── Auto Picture-in-Picture on minimize ──────────────────────────────────
  // When minimized during an active voice call, open a floating PiP overlay.
  // It only shows the other participant (active remote speaker or remote share).
  useEffect(() => {
    if (!window.betweenus?.onWindowMinimize) return;

    const unsubMinimize = window.betweenus.onWindowMinimize(() => {
      const voice = useVoiceStore.getState();
      if (voice.status === 'connected') {
        void window.betweenus?.openPip();
      }
    });

    const unsubRestore = window.betweenus.onWindowRestore?.(() => {
      void window.betweenus?.closePip();
    });

    const unsubAction = window.betweenus.onPipAction?.((action) => {
      if (action.type === 'toggleMic') {
        void useVoiceStore.getState().toggleMic();
      } else if (action.type === 'toggleCamera') {
        void useVoiceStore.getState().toggleCamera();
      } else if (action.type === 'leave') {
        void useVoiceStore.getState().leave();
      }
    });

    return () => {
      unsubMinimize();
      unsubRestore?.();
      unsubAction?.();
    };
  }, []);

  // ─── PiP State & Video Streamer ──────────────────────────────────────────
  // Periodically synchronizes remote speaker state and video frames with the PiP overlay.
  useEffect(() => {
    if (!window.betweenus?.sendPipState) return;

    let offscreenCanvas: HTMLCanvasElement | null = null;
    let offscreenCtx: CanvasRenderingContext2D | null = null;

    const syncInterval = setInterval(() => {
      const voice = useVoiceStore.getState();
      if (voice.status !== 'connected') return;

      const remoteTiles = voice.tiles.filter((t) => !t.isLocal);
      const remoteShares = voice.shares.filter((s) => !s.isLocal);

      // Prioritize remote screen share, then actively speaking peer, then last spoke / first peer
      const activeShare = remoteShares.find((s) => s.track && s.track.readyState === 'live');
      const activeSpeakingTile = remoteTiles.find((t) => t.speaking);
      const latestTile = [...remoteTiles].sort((a, b) => b.lastSpokeAt - a.lastSpokeAt)[0];
      const activeTile = activeSpeakingTile ?? latestTile ?? remoteTiles[0];

      let hasVideo = false;
      let targetTrack: MediaStreamTrack | null = null;

      if (activeShare && activeShare.track) {
        hasVideo = true;
        targetTrack = activeShare.track;
      } else if (activeTile && activeTile.videoTrack && activeTile.videoTrack.readyState === 'live') {
        hasVideo = true;
        targetTrack = activeTile.videoTrack;
      }

      const activeSpeaker = activeShare
        ? {
            name: `${activeShare.name}'s screen`,
            speaking: false,
            micEnabled: true,
            hasVideo: true,
          }
        : activeTile
        ? {
            name: activeTile.name,
            speaking: activeTile.speaking,
            micEnabled: activeTile.micEnabled,
            hasVideo,
          }
        : null;

      window.betweenus?.sendPipState?.({
        channelName: voice.channelName ?? 'Voice Channel',
        activeSpeaker,
        totalParticipants: voice.tiles.length,
        localMicEnabled: voice.micEnabled,
        localCameraEnabled: voice.cameraEnabled,
      });

      // If there is an active video, capture and stream frame with native aspect ratio
      if (hasVideo && targetTrack) {
        const videos = Array.from(document.querySelectorAll('video'));
        const matchingVideo = videos.find((v) => {
          const stream = v.srcObject;
          if (stream instanceof MediaStream) {
            return stream.getTracks().some((t) => t === targetTrack || t.id === targetTrack?.id);
          }
          return false;
        });

        const videoToCapture = matchingVideo ?? videos.find((v) => v.srcObject instanceof MediaStream && v.videoWidth > 0);

        if (videoToCapture && videoToCapture.videoWidth > 0 && videoToCapture.videoHeight > 0) {
          const rawW = videoToCapture.videoWidth;
          const rawH = videoToCapture.videoHeight;
          const maxDim = 640;
          const scale = Math.min(1, maxDim / Math.max(rawW, rawH));
          const targetW = Math.round(rawW * scale);
          const targetH = Math.round(rawH * scale);

          if (!offscreenCanvas || offscreenCanvas.width !== targetW || offscreenCanvas.height !== targetH) {
            offscreenCanvas = document.createElement('canvas');
            offscreenCanvas.width = targetW;
            offscreenCanvas.height = targetH;
            offscreenCtx = offscreenCanvas.getContext('2d');
          }
          if (offscreenCtx) {
            try {
              offscreenCtx.drawImage(videoToCapture, 0, 0, targetW, targetH);
              const frameData = offscreenCanvas.toDataURL('image/jpeg', 0.7);
              window.betweenus?.sendPipFrame?.(frameData);
            } catch {
              // Frame capture error ignored
            }
          }
        }
      }
    }, 60);

    return () => {
      clearInterval(syncInterval);
    };
  }, []);

  useEffect(() => {
    if (status === 'authenticated') {
      void loadServers();
      void loadDirects();
      void loadFriends();
      void loadStatuses();
      // The agent only offers this machine while somebody is signed in on it:
      // enrolment belongs to an account, and so does the audit trail. A browser
      // tab is not a machine anyone can be given control of, so it never enrols.
      const userId = useAuthStore.getState().user?.id;
      if (userId && isDesktopRuntime()) void useAgentStore.getState().restore(userId);
      // Preferences before unread: the badge is harmless either way, but a
      // notification raised in the half-second between them would ignore a mute.
      void loadNotificationPreferences().then(() => loadUnread());
      // A browser tab is unreachable the moment it is closed, which is what
      // this fixes and the desktop app never needed. It is a no-op in Electron
      // and on a deployment with no VAPID keys.
      void startWebPush();
      // The invite a link carried is not redeemed here any more, and not
      // redeemed automatically at all: `ServerRail` picks it up and asks. See
      // `InviteDialog`.
      return;
    }
    reset();
    resetFriends();
    resetPresence();
    useStatusStore.getState().reset();
    releaseAllStatusMedia();
    resetNotificationPreferences();
    useRemoteStore.getState().reset();
    void stopAgent();
  }, [
    status,
    loadServers,
    loadDirects,
    loadFriends,
    loadStatuses,
    loadUnread,
    reset,
    resetFriends,
    resetPresence,
  ]);

  if (booting) {
    return (
      <div className="flex h-full h-[100dvh] flex-col items-center justify-center gap-4 bg-ground" aria-busy="true">
        <div className="flex h-14 w-14 animate-pulse items-center justify-center rounded-2xl border border-edge bg-accent/15 p-3">
          <BetweenUsLogoIcon className="h-full w-full text-accent" />
        </div>
        <p className="animate-pulse text-sm font-medium tracking-[0.2em] text-slate-500">BETWEENUS</p>
      </div>
    );
  }

  if (status !== 'authenticated') return <LoginScreen />;

  return <Workbench />;
}

/**
 * The workbench: a top bar over a row of floating panels - rail, sidebar, the
 * thing you are looking at, and a right-hand panel when one is open. Settings
 * take the whole window on top of all of it.
 *
 * The panels are separate cards on a dark ground rather than columns butted up
 * against each other, and the gutter between them is the ground showing
 * through. That is the shape the layout is built around: every region can be
 * hidden without leaving a seam behind, because there was never a seam.
 */
function Workbench(): JSX.Element {
  const view = useChatStore((state) => state.view);
  const activeChannelId = useChatStore((state) => state.activeChannelId);
  const channel = useChatStore((state) => state.activeChannel());

  /**
   * A one-to-one call has no voice channel to stand in for it.
   *
   * A direct message *is* the channel the call service admits, so the call
   * happens on a channel whose type is DM - and the stage used to be chosen by
   * that type alone, which meant a DM call played through the sidebar dock with
   * the conversation still on screen and nowhere to see a camera or a shared
   * screen. The call being in the channel that is open is the other thing that
   * earns the stage.
   */
  const callChannelId = useVoiceStore((state) => state.channelId);
  const callStatus = useVoiceStore((state) => state.status);

  const rightPanel = useChatStore((state) => state.rightPanel);
  const remoteSession = useRemoteStore((state) => state.session);
  const isMobile = useIsMobile();

  const [settings, setSettings] = useState<'none' | 'user' | 'server'>('none');
  const [homeScreen, setHomeScreen] = useState<'friends' | 'status' | 'remote' | null>('friends');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [switcher, setSwitcher] = useState(false);
  const [shortcutSheet, setShortcutSheet] = useState(false);
  const [showDrawer, setShowDrawer] = useState(false);

  const isRightPanelOpen =
    rightPanel === 'pins' ||
    rightPanel === 'search' ||
    (rightPanel === 'members' && view === 'server');
  const rightSheet = useFocusTrap<HTMLDivElement>(isRightPanelOpen);

  const handleCloseRightPanel = () => {
    useChatStore.getState().showPanel('none');
  };

  // Lock body scroll while mobile right sheet is open
  useEffect(() => {
    if (isMobile && isRightPanelOpen) {
      const originalOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
      return () => {
        document.body.style.overflow = originalOverflow;
      };
    }
  }, [isMobile, isRightPanelOpen]);

  // Escape key closes mobile right sheet
  useEffect(() => {
    if (!isMobile || !isRightPanelOpen) return;
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        handleCloseRightPanel();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [isMobile, isRightPanelOpen]);

  // Opening a conversation is what leaves the friends screen; nothing else has
  // to know about that flag.
  useEffect(() => {
    if (activeChannelId) setHomeScreen(null);
  }, [activeChannelId]);

  // The global bindings. `Ctrl+K` was for a long time the only one, on the
  // reasoning that everything is reachable from it - which is right about
  // navigation and was quietly taken to mean the whole keyboard.
  //
  // The list a person sees lives in `services/shortcuts.ts`, so adding a
  // binding and telling anybody about it are one edit.
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault();
        setSwitcher((open) => !open);
        return;
      }
      // Search this conversation. `Ctrl+F` is what every application on the
      // machine means by it, and the panel it opens has existed all along with
      // no way to reach it from the keyboard.
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'f') {
        if (!useChatStore.getState().activeChannelId) return;
        event.preventDefault();
        useChatStore.getState().showPanel('search');
        return;
      }
      if (opensShortcutSheet(event)) {
        event.preventDefault();
        setShortcutSheet(true);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  return (
    <div className="flex h-full h-[100dvh] flex-col overflow-hidden">
      {/* The strips go *under* the top bar, not over it. Windows draws the
          minimise/maximise/close overlay into the top forty pixels of the
          window whatever is painted there, and TopBar is the only row that
          leaves a gap for it - a notice on top instead had its button sliced
          in half by the close button, which is what "Res" in the update strip
          was. */}
      <TopBar
        onOpenSwitcher={() => setSwitcher(true)}
        sidebarOpen={sidebarOpen}
        onToggleSidebar={() => setSidebarOpen((open) => !open)}
      />
      <ConnectionNotice />
      {/* Almost never drawn: it fires only for an account whose key exists on
          this machine and nowhere else, which is a provider sign-in that never
          set a recovery passphrase. */}
      <BackupNotice onOpenSettings={() => setSettings('user')} />
      <ClockNotice />
      <VersionNotice />
      <UpdateNotice />

      <div className="flex min-h-0 flex-1 gap-1.5 px-1.5 pb-1.5">
        <ServerRail className="hidden md:flex" />

        {sidebarOpen &&
          (view === 'home' ? (
            <HomeSidebar
              showingFriends={homeScreen === 'friends'}
              onShowFriends={() => setHomeScreen('friends')}
              showingStatus={homeScreen === 'status'}
              onShowStatus={() => setHomeScreen('status')}
              showingRemote={homeScreen === 'remote'}
              onShowRemote={() => setHomeScreen('remote')}
              onOpenUserSettings={() => setSettings('user')}
              className="hidden md:flex w-60"
            />
          ) : (
            <ChannelSidebar
              onOpenUserSettings={() => setSettings('user')}
              onOpenServerSettings={() => setSettings('server')}
              className="hidden md:flex w-60"
            />
          ))}

        {view === 'home' && homeScreen === 'remote' ? (
          <RemoteView onOpenMenu={() => setShowDrawer(true)} />
        ) : view === 'home' && homeScreen === 'status' ? (
          <StatusScreen onOpenMenu={() => setShowDrawer(true)} />
        ) : view === 'home' && homeScreen === 'friends' ? (
          <FriendsView onOpenMenu={() => setShowDrawer(true)} />
        ) : channel?.type === 'VOICE' ||
          (channel && callStatus !== 'idle' && callChannelId === channel.id) ? (
          <VoiceChannelView channel={channel} onOpenMenu={() => setShowDrawer(true)} />
        ) : (
          <>
            <ChatView
              onToggleMembers={() => {
                const current = useChatStore.getState().rightPanel;
                useChatStore.getState().showPanel(current === 'members' ? 'none' : 'members');
              }}
              showMembers={rightPanel === 'members'}
              onOpenMenu={() => setShowDrawer(true)}
            />
            {/* Desktop right-hand panels (side-by-side) */}
            {!isMobile && (
              <>
                {rightPanel === 'pins' && <PinnedPanel onClose={handleCloseRightPanel} />}
                {rightPanel === 'search' && <SearchPanel onClose={handleCloseRightPanel} />}
                {rightPanel === 'members' && view === 'server' && (
                  <MemberList onClose={handleCloseRightPanel} />
                )}
              </>
            )}
          </>
        )}
      </div>

      {/* Mobile Slide-Over Right Sheet (MemberList, PinnedPanel, SearchPanel) */}
      {isMobile && (
        <>
          <div
            onClick={handleCloseRightPanel}
            aria-hidden="true"
            className={`fixed inset-0 z-40 bg-black/60 backdrop-blur-sm transition-opacity duration-300 ${
              isRightPanelOpen ? 'opacity-100' : 'pointer-events-none opacity-0'
            }`}
          />
          {/* Mounted whether or not it is open, because it slides rather than
              appears - so it has to be taken out of the keyboard and out of the
              accessibility tree by hand while it is shut. `pointer-events-none`
              below stops a mouse and does nothing to Tab. */}
          <div
            ref={rightSheet}
            {...closedPanelProps(isRightPanelOpen)}
            role="dialog"
            aria-label="Details panel"
            aria-modal="true"
            className={`fixed inset-y-0 end-0 z-50 flex w-[320px] max-w-[85vw] flex-col bg-surface-900 border-s border-edge shadow-2xl transition-transform duration-300 ease-out ${
              isRightPanelOpen ? 'translate-x-0' : 'translate-x-full pointer-events-none'
            }`}
          >
            {rightPanel === 'pins' && (
              <PinnedPanel onClose={handleCloseRightPanel} className="h-full w-full border-none bg-surface-900" />
            )}
            {rightPanel === 'search' && (
              <SearchPanel onClose={handleCloseRightPanel} className="h-full w-full border-none bg-surface-900" />
            )}
            {rightPanel === 'members' && view === 'server' && (
              <MemberList onClose={handleCloseRightPanel} className="h-full w-full border-none bg-surface-900 flex" />
            )}
          </div>
        </>
      )}

      {/* Mobile Navigation Drawer (Left Sheet) */}
      <MobileDrawer
        open={showDrawer}
        onClose={() => setShowDrawer(false)}
        onOpenUserSettings={() => setSettings('user')}
        onOpenServerSettings={() => setSettings('server')}
        onShowFriends={() => setHomeScreen('friends')}
        onShowStatus={() => setHomeScreen('status')}
        onShowRemote={() => setHomeScreen('remote')}
        showingFriends={homeScreen === 'friends'}
        showingStatus={homeScreen === 'status'}
        showingRemote={homeScreen === 'remote'}
      />

      {switcher && <QuickSwitcher onClose={() => setSwitcher(false)} />}
      {shortcutSheet && <ShortcutSheet onClose={() => setShortcutSheet(false)} />}

      {/* A remote session covers the window wherever it was started from - the
          machine list, or the "Request control" button on somebody's screen
          share in a voice channel. Leaving it inside the machine list meant the
          second of those had nowhere to appear. */}
      {remoteSession && (
        <div className="fixed inset-0 z-40 flex">
          <RemoteSessionView />
        </div>
      )}

      {/* Somebody asking to reach this machine has to be answered wherever the
          window happens to be, so the prompt sits above everything. The same
          goes for somebody in a call asking for the mouse on a screen being
          shared - a machine being driven by another person is never a
          background event. */}
      {/* The call's ears, at the root and outside every column: a sidebar swap
          or a screen change must never be able to unmount them. */}
      <CallAudio />

      <RemoteConsent />
      <ShareControlConsent />
      {/* Above every other overlay, because it is the only one somebody is
          waiting on the other end of. */}
      <IncomingCall />

      {/* The picture behind any avatar in the app, and the line that says
          somebody has not set one. */}
      <ProfileView />
      <ProfileScreen />
      {/* A tap on an avatar with a ring around it has two answers; this is
          where it asks which. Above the profile overlays it opens. */}
      <AvatarChoice />
      {/* The story player and the composer, at the root for the same reason
          the profile overlays are: a ring in a sidebar, a row in the tray and
          an avatar in a conversation all open the same one. */}
      <StatusViewer />
      <StatusComposer />

      {settings === 'user' && <UserSettings onClose={() => setSettings('none')} />}
      {settings === 'server' && <ServerSettings onClose={() => setSettings('none')} />}
    </div>
  );
}

/**
 * Opens what a notification was about.
 *
 * One function for both ways in - a message to a running tab and a query
 * string on a cold start - because a route that worked one way and not the
 * other is a bug nobody would find: the two paths are taken by the same tap on
 * two different days.
 *
 * A destination that no longer exists is not an error. The channel was
 * deleted, the machine was removed, access lapsed - the app stays where it is
 * rather than throwing, because the person tapped a notification and deserves
 * a running app either way.
 */
function followPushRoute(route: PushRoute): void {
  const chat = useChatStore.getState();
  switch (route.kind) {
    case 'channel':
    case 'call':
      // A call notification opens the channel it is in. Joining is still a
      // decision somebody makes on the screen, not one a tap makes for them.
      if (route.channelId) void chat.selectChannel(route.channelId).catch(() => undefined);
      return;
    case 'server':
      if (route.serverId) void chat.selectServer(route.serverId).catch(() => undefined);
      return;
    case 'remote':
      // The machine list rather than the session: a remote session that has
      // already started is somebody else's, and reconnecting to it from a
      // notification is not what the notification is telling you about.
      chat.showHome();
      void useRemoteStore.getState().load().catch(() => undefined);
      return;
    case 'friends':
      chat.showHome();
      return;
    default:
      return;
  }
}

import type { PresenceStatus } from '@betweenus/shared-types';
import { absoluteUrl } from '../services/endpoint';
import { usePresenceStore } from '../stores/presence';
import { useAuthStore } from '../stores/auth';
import { runOf, useStatusStore } from '../stores/status';
import { viewProfile } from './ProfileView';
import { askAvatarChoice } from './AvatarChoice';
import { StatusRing } from './StatusRing';

const SIZES = {
  sm: 'h-8 w-8 text-xs',
  md: 'h-10 w-10 text-sm',
  lg: 'h-20 w-20 text-2xl',
} as const;

const DOT_SIZES = {
  sm: 'h-3 w-3 border-[3px]',
  md: 'h-3.5 w-3.5 border-[3px]',
  lg: 'h-6 w-6 border-4',
} as const;

const DOT_COLOURS: Record<PresenceStatus, string> = {
  online: 'bg-status-online',
  idle: 'bg-status-idle',
  dnd: 'bg-status-dnd',
  // Someone's own client is the only place this is ever seen; to everyone else
  // an invisible user is simply offline.
  invisible: 'bg-status-offline',
  offline: 'bg-status-offline',
};

const DOT_LABELS: Record<PresenceStatus, string> = {
  online: 'Online',
  idle: 'Idle',
  dnd: 'Do not disturb',
  invisible: 'Invisible',
  offline: 'Offline',
};

/**
 * A person's avatar that looks its own presence up, by id.
 *
 * `Avatar` takes a status because most callers already hold one - a member row
 * has the whole roster in hand. A message does not: it carries who wrote it and
 * nothing about whether they are here, and threading a status down through the
 * conversation would subscribe the message list to every status change in the
 * deployment and repaint it when a stranger goes idle.
 *
 * So the lookup lives in the leaf, and the selector is scalar: this re-renders
 * when *this* person's status changes and at no other time.
 */
export function PersonAvatar({
  userId,
  name,
  avatarUrl,
  size = 'md',
  ringColour,
}: {
  userId: string;
  name: string;
  avatarUrl?: string | null;
  size?: keyof typeof SIZES;
  ringColour?: string;
}): JSX.Element {
  const status = usePresenceStore((state) => state.statuses.get(userId) ?? 'offline');
  return (
    <Avatar
      userId={userId}
      name={name}
      avatarUrl={avatarUrl}
      status={status}
      size={size}
      {...(ringColour ? { ringColour } : {})}
    />
  );
}

/**
 * A round avatar with an optional status dot punched out of its corner, which
 * is how every list in this app identifies a person.
 */
export function Avatar({
  userId,
  name,
  avatarUrl,
  status,
  size = 'md',
  ringColour = 'border-surface-800',
  viewable = true,
}: {
  /**
   * Who this is, where the caller knows. Optional because plenty of these
   * circles stand for a place, a webhook or a control rather than a person -
   * and it is what the status ring and the tap-to-choose need, so an avatar
   * without it behaves exactly as it did before statuses existed.
   */
  userId?: string;
  name: string;
  avatarUrl?: string | null;
  /**
   * Omitted where status is meaningless - a server's icon, or a circle inside
   * a control. Where the caller has a person's id but not their status,
   * `PersonAvatar` above looks it up rather than being handed one.
   */
  status?: PresenceStatus;
  size?: keyof typeof SIZES;
  /**
   * Border colour class for the dot's cut-out. It has to match whatever the
   * avatar is sitting on, which only the caller knows.
   */
  ringColour?: string;
  /**
   * Whether tapping it opens the picture. True for a person, which is nearly
   * everywhere; false where the circle stands for a place or is inside a
   * control whose own job the tap belongs to.
   */
  viewable?: boolean;
}): JSX.Element {
  // The ring, and what a tap does, both come from here. Every list in the app
  // draws people through this component, so putting it here is what makes a
  // ring appear in the sidebar, the member list and a conversation header at
  // once - rather than in whichever three of them somebody remembered.
  const selfId = useAuthStore((state) => state.user?.id ?? null);
  const own = useStatusStore((state) => state.mine);
  const run = useStatusStore((state) => (userId && userId !== selfId ? runOf(state, userId) : null));
  const posts = userId && userId === selfId ? own : (run?.statuses ?? []);
  const unseen = run?.unseen ?? false;

  const tapped = (): void => {
    // Two things behind one circle: ask which. See `AvatarChoice`.
    if (posts.length > 0 && userId) {
      askAvatarChoice({ userId, name, avatarUrl: avatarUrl ?? null, count: posts.length });
      return;
    }
    viewProfile(name, avatarUrl);
  };

  return (
    <div
      // A div and not a button: most of these sit inside a row that is itself
      // a button, and a button inside a button is not markup a browser will
      // keep. Stopping the event is what keeps the row from also firing.
      onClick={
        viewable
          ? (event) => {
              event.preventDefault();
              event.stopPropagation();
              tapped();
            }
          : undefined
      }
      title={
        viewable
          ? posts.length > 0
            ? `View ${name}'s profile photo or status`
            : `View ${name}'s profile photo`
          : undefined
      }
      className={`relative shrink-0 ${SIZES[size]} ${viewable ? 'cursor-pointer' : ''}`}
    >
      {posts.length > 0 && <StatusRing count={posts.length} unseen={unseen} />}

      {avatarUrl ? (
        <img
          // Stored pictures come back rooted at /api/v1/uploads; resolve them
          // against the deployment, not against file:// in a packaged window.
          src={absoluteUrl(avatarUrl)}
          alt=""
          className="h-full w-full rounded-full object-cover"
        />
      ) : (
        <div
          aria-hidden="true"
          className="flex h-full w-full items-center justify-center rounded-full bg-accent font-semibold uppercase text-white"
        >
          {name.trim().charAt(0) || '?'}
        </div>
      )}

      {status && (
        <span
          title={DOT_LABELS[status]}
          className={`absolute -bottom-0.5 -end-0.5 rounded-full border-solid ${DOT_SIZES[size]} ${DOT_COLOURS[status]} ${ringColour}`}
        >
          <span className="sr-only">{DOT_LABELS[status]}</span>
        </span>
      )}
    </div>
  );
}

/**
 * What a tap on an avatar means, when it could mean two things.
 *
 * Before statuses existed a tap had one answer - the picture, full size - and
 * `Avatar` simply opened it. Now somebody with a status has two things behind
 * the same circle, and picking one of them for the reader is how you get an
 * app where the ring is decoration: a tap on a ring that opens a profile photo
 * has ignored the only thing the ring was there to say.
 *
 * So the tap asks, and only when there is something to ask about. An avatar
 * with no status behind it opens the picture exactly as it always did - see
 * `Avatar`, which is the only caller.
 *
 * One overlay at the root, like `ProfileView` beside it, because every avatar
 * in the tree shares it.
 */
import { useEffect } from 'react';
import { create } from 'zustand';
import { absoluteUrl } from '../services/endpoint';
import { useFocusTrap } from '../services/focus-trap';
import { openStatus } from '../features/status/StatusViewer';
import { viewProfile } from './ProfileView';
import { EyeIcon, UserIcon } from './icons';

interface Asking {
  userId: string;
  name: string;
  avatarUrl: string | null;
  /** How many live posts they have, for the line under the status choice. */
  count: number;
}

const useAvatarChoice = create<{ asking: Asking | null }>(() => ({ asking: null }));

/** Called by `Avatar` when the person behind it has something posted. */
export function askAvatarChoice(asking: Asking): void {
  useAvatarChoice.setState({ asking });
}

export function AvatarChoice(): JSX.Element | null {
  const trap = useFocusTrap<HTMLDivElement>();
  const asking = useAvatarChoice((state) => state.asking);
  const close = (): void => useAvatarChoice.setState({ asking: null });

  useEffect(() => {
    if (!asking) return;
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') close();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [asking]);

  if (!asking) return null;

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label={`${asking.name}: profile or status`}
      onClick={close}
      className="fixed inset-0 z-[65] flex animate-fade items-center justify-center bg-black/75 px-4"
    >
      <div
        onClick={(event) => event.stopPropagation()}
        className="w-full max-w-xs animate-pop overflow-hidden rounded-xl border border-edge bg-surface-900 shadow-pop"
      >
        <div className="flex items-center gap-3 border-b border-edge px-4 py-3">
          {asking.avatarUrl ? (
            <img
              src={absoluteUrl(asking.avatarUrl)}
              alt=""
              className="h-10 w-10 rounded-full object-cover"
            />
          ) : (
            <div className="flex h-10 w-10 items-center justify-center rounded-full bg-accent font-semibold uppercase text-white">
              {asking.name.trim().charAt(0) || '?'}
            </div>
          )}
          <p className="min-w-0 flex-1 truncate text-sm font-semibold text-slate-100">
            {asking.name}
          </p>
        </div>

        <Choice
          icon={<UserIcon className="h-5 w-5" />}
          label="View profile photo"
          onClick={() => {
            close();
            viewProfile(asking.name, asking.avatarUrl);
          }}
        />
        <Choice
          icon={<EyeIcon className="h-5 w-5" />}
          label="View moments"
          hint={asking.count === 1 ? '1 update' : `${asking.count} updates`}
          onClick={() => {
            close();
            openStatus(asking.userId);
          }}
        />
      </div>
    </div>
  );
}

function Choice({
  icon,
  label,
  hint,
  onClick,
}: {
  icon: JSX.Element;
  label: string;
  hint?: string;
  onClick: () => void;
}): JSX.Element {
  return (
    <button
      type="button"
      onClick={onClick}
      className="flex w-full cursor-pointer items-center gap-3 px-4 py-3 text-start transition-colors duration-150 hover:bg-white/[0.05]"
    >
      <span className="text-slate-400">{icon}</span>
      <span className="flex-1 text-sm text-slate-200">{label}</span>
      {hint && <span className="text-xs text-slate-500">{hint}</span>}
    </button>
  );
}

import { useState } from 'react';
import { useIdentityStore } from '../stores/identity';
import {
  readDismissedUntil,
  shouldWarnAboutBackup,
  SNOOZE_KEY,
  SNOOZE_MS,
} from '../services/backup-warning';

/**
 * The one notice that says an account cannot be recovered.
 *
 * `ensureBackup` in `e2ee.ts` ends with a comment that is exactly right and is
 * exactly the problem: an account without a backup still works, it is only
 * unrecoverable, "and the settings panel says so". It does. Nothing brought
 * anybody to the settings panel.
 *
 * Almost nobody sees this. A password sign-in seals a backup on its own, so the
 * accounts it fires for are the ones with no password to derive from - a Google
 * or GitHub sign-in - which until now were never told that the machine in front
 * of them is the only thing holding their key.
 *
 * The wording is deliberately about the consequence rather than about
 * cryptography. "Set a recovery passphrase" is a chore; "if you lose this
 * computer you lose these conversations" is the reason to do it, and it is the
 * true one - the server holds ciphertext and no key, so there is no support
 * route that gets them back.
 */
export function BackupNotice({ onOpenSettings }: { onOpenSettings: () => void }): JSX.Element | null {
  const identity = useIdentityStore((state) => state.identity);
  // On disk now, and for thirty days - see `SNOOZE_MS`. It used to be per
  // session, which meant this returned on every single launch; a warning that
  // comes back that often is a nag, and a nag gets ignored in place, which is
  // the failure the per-session rule was written to avoid.
  //
  // Read once, lazily, rather than on every render: the stamp only changes when
  // this component writes it.
  const [dismissedUntil, setDismissedUntil] = useState<number | null>(() =>
    typeof window === 'undefined' ? null : readDismissedUntil(window.localStorage),
  );

  const snooze = (): void => {
    const until = Date.now() + SNOOZE_MS;
    try {
      window.localStorage.setItem(SNOOZE_KEY, String(until));
    } catch {
      // Storage can be unavailable. Hiding it for this session is still the
      // right answer to the button somebody just pressed.
    }
    setDismissedUntil(until);
  };

  if (!shouldWarnAboutBackup(identity, dismissedUntil)) return null;

  return (
    <div
      role="status"
      aria-live="polite"
      className="flex flex-wrap items-center justify-center gap-x-3 gap-y-1.5 bg-amber-500/15 px-3 py-1.5 text-sm text-amber-200"
    >
      <span>
        This computer holds the only copy of your encryption key. If you lose it, these
        conversations cannot be recovered — not by us either.
      </span>
      <span className="flex items-center gap-2">
        <button
          type="button"
          onClick={onOpenSettings}
          className="rounded-md bg-amber-500/20 px-2 py-0.5 font-medium hover:bg-amber-500/30"
        >
          Set up recovery
        </button>
        <button
          type="button"
          onClick={snooze}
          aria-label="Hide this for 30 days"
          title="Hidden for 30 days. It disappears for good once recovery is set up."
          className="rounded-md px-2 py-0.5 font-medium text-amber-200/80 hover:bg-amber-500/15 hover:text-amber-100"
        >
          Not now
        </button>
      </span>
    </div>
  );
}

/**
 * One line at the top of the window when this machine's clock is wrong.
 *
 * The same strip as VersionNotice next to it. A clock that is out by minutes
 * cannot open anything - every expiry is decided on the server, and
 * `services/server-clock.ts` says why that is not negotiable - but it does make
 * the app lie quietly to the person reading it: yesterday's conversation filed
 * under "Today", an invite still offered after it lapsed. Saying so once, where
 * it can be dismissed, is the difference between a wrong clock and software
 * that looks broken.
 */
import { clockIsWrong, skewWording, useServerClock } from '../services/server-clock';
import { ClockIcon, XIcon } from './icons';
import { useState } from 'react';

export function ClockNotice(): JSX.Element | null {
  const offsetMs = useServerClock((state) => state.offsetMs);
  const [dismissed, setDismissed] = useState(false);

  if (dismissed || !clockIsWrong(offsetMs)) return null;

  return (
    <div
      role="status"
      className="flex shrink-0 items-center gap-2 bg-amber-500/15 px-4 py-1.5 text-xs text-amber-200"
    >
      <ClockIcon className="h-3.5 w-3.5 shrink-0" />
      <span className="min-w-0 flex-1">{skewWording(offsetMs)}</span>
      <button
        type="button"
        aria-label="Dismiss"
        onClick={() => setDismissed(true)}
        className="cursor-pointer rounded p-0.5 transition-colors duration-150 hover:bg-white/10"
      >
        <XIcon className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

import { useEffect, useState } from 'react';
import {
  connectionState,
  onConnectionChange,
  retryConnection,
  type ConnectionState,
} from '../services/socket';
import { t } from '../services/i18n';

/**
 * What the realtime connection is doing, when it is not simply working.
 *
 * Nothing is drawn while both sockets are up, which is almost always. A window
 * whose sockets are down looks identical to one that is idle - no messages
 * arrive either way - and that silence was the thing people read as the app
 * being broken. It is a bar rather than a modal: the history on screen is still
 * readable, and reading it is most of what somebody does while waiting.
 *
 * The worked example for `services/i18n.ts`: every string here goes through
 * `t(key, english)`, which is what the rest of the client's screens will look
 * like once each is extracted. Nothing else in the app does yet - the
 * extraction is per-screen and this is one screen.
 */
export function ConnectionNotice(): JSX.Element | null {
  const [state, setState] = useState<ConnectionState>(connectionState);

  useEffect(() => onConnectionChange(setState), []);

  if (state === 'online') return null;

  const reconnecting = state === 'reconnecting';

  return (
    <div
      role="status"
      aria-live="polite"
      className={`flex items-center justify-center gap-2 px-3 py-1.5 text-sm ${
        reconnecting ? 'bg-amber-500/15 text-amber-200' : 'bg-red-500/15 text-red-200'
      }`}
    >
      {reconnecting && <Spinner />}
      <span>{reconnecting
          ? t('connection.reconnecting', 'Reconnecting…')
          : t('connection.offline', 'Disconnected')}</span>
      {!reconnecting && (
        <button
          type="button"
          onClick={retryConnection}
          className="rounded-md bg-red-500/20 px-2 py-0.5 font-medium hover:bg-red-500/30"
        >
          {t('connection.retry', 'Try again')}
        </button>
      )}
    </div>
  );
}

/** The circular one. `animate-spin` on a ring with a quarter of it missing. */
function Spinner(): JSX.Element {
  return (
    <span
      aria-hidden="true"
      className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-current border-t-transparent"
    />
  );
}

import { useEffect, useState } from 'react';
import {
  onDevicesChanged,
  readDevices,
  refreshDevices,
  chosenIsMissing,
} from '../services/audio-devices';

/**
 * A microphone or speaker picker, used by Voice & Video in settings and by the
 * one in the call controls - the two must never disagree about what is chosen.
 *
 * `null` is the system default and stays a real option: a machine whose chosen
 * device has since been unplugged should fall back rather than fail a join.
 * Device labels are blank until the microphone has been granted once, which is
 * the operating system's rule and not something the app can work around.
 */
export function DeviceSelect({
  label,
  kind,
  devices,
  value,
  onChange,
}: {
  label: string;
  kind: MediaDeviceKind;
  devices: MediaDeviceInfo[];
  value: string | null;
  onChange: (deviceId: string | null) => void;
}): JSX.Element {
  const options = devices.filter((device) => device.kind === kind && device.deviceId !== 'default');
  // A chosen device that is no longer plugged in is captured with `exact` like
  // any other, refused, and retried on the system default by `openAudioCapture`.
  // The person still hears a microphone they did not choose, so the substitution
  // is said out loud here rather than left to be discovered.
  const missing = chosenIsMissing(devices, kind, value);

  return (
    <label className="block">
      <span className="block text-xs font-bold uppercase tracking-wide text-slate-400">{label}</span>
      <select
        value={missing ? '' : (value ?? '')}
        onChange={(event) => onChange(event.target.value || null)}
        className="mt-2 w-full cursor-pointer rounded-lg border border-edge bg-surface-950 px-3 py-2 text-slate-100 outline-none transition-colors focus:border-accent/60"
      >
        <option value="">System default</option>
        {options.map((device) => (
          <option key={device.deviceId} value={device.deviceId}>
            {device.label || 'Unnamed device'}
          </option>
        ))}
      </select>
      {missing && (
        <span className="mt-1.5 block text-xs text-amber-300">
          The device you chose is not connected. The system default is being used instead - pick
          another to make it stick.
        </span>
      )}
    </label>
  );
}

/**
 * The device list, refreshed when the operating system's changes - plugging in
 * a headset mid-call is the moment somebody goes looking for this menu.
 *
 * One list for the whole window rather than one enumeration per picker: the
 * settings screen and the in-call popover were reading the hardware separately
 * and could disagree about what was plugged in. The refresh function is for the
 * other case - the labels are blank until the microphone has been granted once,
 * so whoever opens one wants the list read again afterwards.
 */
export function useDevices(): [MediaDeviceInfo[], () => void] {
  const [devices, setDevices] = useState<MediaDeviceInfo[]>(readDevices);

  useEffect(() => {
    refreshDevices();
    return onDevicesChanged(setDevices);
  }, []);

  return [devices, refreshDevices];
}

/**
 * Picking a disappearing window.
 *
 * One component for both places it is asked, because it is the same question
 * asked of two different things - a server's window and an account's own - and
 * two pickers would be two chances to disagree about what the durations are
 * called or which order they come in.
 *
 * A row of buttons rather than a `<select>`: there are five options, they are
 * all short, and the one that matters most is "Off" - which a dropdown hides
 * behind a click. Seeing the current setting without opening anything is the
 * whole point of a control like this.
 */
import { DISAPPEARING_WINDOWS, disappearingWindowLabel } from '@betweenus/shared-types';

export function DisappearingPicker({
  value,
  disabled = false,
  onChange,
}: {
  /** Seconds, or null for off. */
  value: number | null;
  disabled?: boolean;
  onChange: (next: number | null) => void;
}): JSX.Element {
  // Off first, then shortest to longest. The list itself is ordered - see the
  // check beside it - so nothing is sorted here.
  const options: Array<number | null> = [null, ...DISAPPEARING_WINDOWS];

  return (
    <div role="radiogroup" aria-label="Disappearing messages" className="mt-4 flex flex-wrap gap-2">
      {options.map((seconds) => {
        const on = seconds === value;
        return (
          <button
            key={seconds ?? 'off'}
            type="button"
            role="radio"
            aria-checked={on}
            disabled={disabled}
            onClick={() => onChange(seconds)}
            className={`cursor-pointer rounded-md border px-3 py-1.5 text-sm transition-colors duration-200 disabled:cursor-not-allowed disabled:opacity-60 ${
              on
                ? 'border-accent bg-accent/15 text-slate-100'
                : 'border-edge text-slate-300 hover:border-accent hover:text-slate-100'
            }`}
          >
            {disappearingWindowLabel(seconds)}
          </button>
        );
      })}
    </div>
  );
}

/**
 * The last thing between a bug and a blank window.
 *
 * React unmounts the entire tree when a render throws, and an unmounted tree is
 * an empty page: no message, no navigation, nothing to report but "it went
 * blank". That is what one `null` where an array was promised did to this app -
 * the sort of mistake that will happen again, in some other store, and it must
 * not cost the whole window.
 *
 * This is a report, not a recovery: whatever threw is still wrong, so the state
 * it threw on is not offered back. Reloading is the way out, and the message is
 * the thing worth carrying to a bug report - which is why it is on screen rather
 * than only in the console, where nobody who is not already debugging will look.
 *
 * Class component because that is the only kind React runs this on; there is no
 * hook for it.
 */
import { Component, type ErrorInfo, type ReactNode } from 'react';

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<{ children: ReactNode }, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    // The component stack is the half that says *where*, and it is not on the
    // Error - so it is only ever seen if it is logged here.
    console.error('[ErrorBoundary] the interface stopped rendering:', error, info.componentStack);
  }

  render(): ReactNode {
    const { error } = this.state;
    if (!error) return this.props.children;

    return (
      <div
        role="alert"
        className="flex h-full flex-col items-center justify-center gap-4 bg-surface-950 p-8 text-center"
      >
        <h1 className="text-lg font-semibold text-slate-100">BetweenUs hit a bug and stopped</h1>
        <p className="max-w-xl break-words font-mono text-sm text-red-300">
          {error.message || String(error)}
        </p>
        <p className="max-w-md text-sm text-slate-400">
          Nothing was lost - the window has to be reloaded to carry on. The full detail is in the
          developer console.
        </p>
        <button
          type="button"
          onClick={() => window.location.reload()}
          className="cursor-pointer rounded-full bg-slate-100 px-6 py-2.5 font-semibold text-slate-900 transition-colors duration-200 hover:bg-white"
        >
          Reload
        </button>
      </div>
    );
  }
}

/**
 * Crop and rotate a picture before it is sent or stored.
 *
 * Every chat app has this and this one did not: a picked file went up exactly
 * as it came off the camera, sideways photos included. There is nothing clever
 * here - drag to move, wheel or slider to zoom, two buttons to turn - and that
 * is the point, because the arithmetic that makes the written file match the
 * preview lives in `services/image-edit.ts`, where it is checked rather than
 * eyeballed.
 *
 * The frame is the crop. What is inside it when Done is pressed is what gets
 * written, so a square frame is an avatar and a free frame is a photo about to
 * be sent.
 */
import { useEffect, useMemo, useRef, useState } from 'react';
import { decodeImage } from '../services/attachments';
import {
  type Edit,
  type Size,
  MAX_ZOOM,
  NO_EDIT,
  clampEdit,
  coverScale,
  cssTransform,
  drawEdit,
  panRange,
  rotate,
} from '../services/image-edit';

/** The longest edge of the preview box, in CSS pixels. */
const FRAME_LONG = 360;

export function ImageEditor({
  file,
  aspect,
  maxOutputEdge = 2048,
  type = 'image/jpeg',
  quality = 0.92,
  title,
  onCancel,
  onDone,
}: {
  file: File;
  /** Width over height. 1 for an avatar; the picture's own when omitted. */
  aspect?: number;
  /** The longest edge of the written file. Never upscales past the source. */
  maxOutputEdge?: number;
  type?: string;
  quality?: number;
  title?: string;
  onCancel: () => void;
  onDone: (edited: Blob) => void;
}): JSX.Element {
  const [bitmap, setBitmap] = useState<ImageBitmap | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const [edit, setEdit] = useState<Edit>(NO_EDIT);
  const [busy, setBusy] = useState(false);
  const dragging = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    let live = true;
    let decoded: ImageBitmap | null = null;
    void (async () => {
      try {
        decoded = await decodeImage(file);
        if (!live) {
          decoded.close();
          return;
        }
        setBitmap(decoded);
      } catch {
        if (live) setFailure('That file could not be read as a picture');
      }
    })();
    return () => {
      live = false;
      decoded?.close();
    };
  }, [file]);

  // A free frame takes the picture's own shape, so opening the editor and
  // pressing Done straight away returns the picture rather than a crop nobody
  // asked for.
  const ratio = aspect ?? (bitmap ? bitmap.width / bitmap.height : 1);
  const frame: Size = useMemo(
    () =>
      ratio >= 1
        ? { width: FRAME_LONG, height: Math.max(1, Math.round(FRAME_LONG / ratio)) }
        : { width: Math.max(1, Math.round(FRAME_LONG * ratio)), height: FRAME_LONG },
    [ratio],
  );

  // The source is a bitmap for the arithmetic and an object URL for the
  // preview: an <img> the browser lays out costs nothing to move and turn,
  // where a canvas would be repainted on every pointer move.
  const [url, setUrl] = useState<string | null>(null);
  useEffect(() => {
    const objectUrl = URL.createObjectURL(file);
    setUrl(objectUrl);
    return () => {
      URL.revokeObjectURL(objectUrl);
    };
  }, [file]);

  const apply = (next: Edit): void => {
    if (bitmap) setEdit(clampEdit(bitmap, frame, next));
  };

  const done = async (): Promise<void> => {
    if (!bitmap) return;
    setBusy(true);
    try {
      // What the frame covers, measured in the source's own pixels. Capping by
      // that rather than by the ceiling matters: upscaling a small picture to
      // 2048 makes a bigger file of exactly the same detail.
      const scale = coverScale(bitmap, frame, edit.rotation) * edit.zoom;
      const cropped = { width: frame.width / scale, height: frame.height / scale };
      const shrink = Math.min(1, maxOutputEdge / Math.max(cropped.width, cropped.height));
      const output: Size = {
        width: Math.max(1, Math.round(cropped.width * shrink)),
        height: Math.max(1, Math.round(cropped.height * shrink)),
      };

      const canvas = document.createElement('canvas');
      canvas.width = output.width;
      canvas.height = output.height;
      const context = canvas.getContext('2d');
      if (!context) throw new Error('This device cannot process images');
      drawEdit(context, bitmap, frame, output, edit);

      const blob = await new Promise<Blob | null>((resolve) =>
        canvas.toBlob(resolve, type, quality),
      );
      if (!blob) throw new Error('That picture could not be written');
      onDone(blob);
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'That picture could not be written');
    } finally {
      setBusy(false);
    }
  };

  const range = bitmap ? panRange(bitmap, frame, edit) : { width: 0, height: 0 };
  const movable = range.width > 0 || range.height > 0;

  return (
    <div className="fixed inset-0 z-50 flex flex-col items-center justify-center gap-4 bg-black/80 p-6">
      <p className="max-w-md truncate text-sm text-slate-200">{title ?? file.name}</p>

      <div
        className="relative overflow-hidden rounded-lg border border-edge bg-black"
        style={{ width: frame.width, height: frame.height, cursor: movable ? 'grab' : 'default' }}
        onPointerDown={(event) => {
          if (!movable) return;
          dragging.current = { x: event.clientX, y: event.clientY };
          event.currentTarget.setPointerCapture(event.pointerId);
        }}
        onPointerMove={(event) => {
          const from = dragging.current;
          if (!from) return;
          dragging.current = { x: event.clientX, y: event.clientY };
          apply({
            ...edit,
            offsetX: edit.offsetX + (event.clientX - from.x),
            offsetY: edit.offsetY + (event.clientY - from.y),
          });
        }}
        onPointerUp={() => {
          dragging.current = null;
        }}
        onPointerCancel={() => {
          dragging.current = null;
        }}
        onWheel={(event) => apply({ ...edit, zoom: edit.zoom * (event.deltaY < 0 ? 1.1 : 1 / 1.1) })}
      >
        {bitmap && url && (
          <img
            src={url}
            alt=""
            draggable={false}
            className="pointer-events-none absolute left-1/2 top-1/2 max-w-none select-none"
            style={{
              width: bitmap.width,
              height: bitmap.height,
              // Centred on the frame's centre first; everything after that is
              // the transform the canvas replays.
              marginLeft: -bitmap.width / 2,
              marginTop: -bitmap.height / 2,
              transform: cssTransform(bitmap, frame, edit),
            }}
          />
        )}
        {!bitmap && !failure && (
          <p className="flex h-full items-center justify-center text-sm text-slate-400">Opening…</p>
        )}
      </div>

      <div className="flex w-full max-w-md items-center gap-3">
        <button
          type="button"
          aria-label="Rotate left"
          title="Rotate left"
          onClick={() => apply({ ...NO_EDIT, rotation: rotate(edit.rotation, -1) })}
          className="cursor-pointer rounded px-3 py-1.5 text-lg text-slate-200 hover:bg-surface-800"
        >
          ⟲
        </button>
        <input
          type="range"
          aria-label="Zoom"
          min={1}
          max={MAX_ZOOM}
          step={0.01}
          value={edit.zoom}
          onChange={(event) => apply({ ...edit, zoom: Number(event.target.value) })}
          className="flex-1 cursor-pointer"
        />
        <button
          type="button"
          aria-label="Rotate right"
          title="Rotate right"
          onClick={() => apply({ ...NO_EDIT, rotation: rotate(edit.rotation, 1) })}
          className="cursor-pointer rounded px-3 py-1.5 text-lg text-slate-200 hover:bg-surface-800"
        >
          ⟳
        </button>
      </div>

      {failure && <p className="text-sm text-danger">{failure}</p>}

      <div className="flex gap-2">
        <button
          type="button"
          onClick={onCancel}
          disabled={busy}
          className="cursor-pointer rounded px-4 py-1.5 text-sm text-slate-300 hover:text-slate-100 disabled:cursor-not-allowed"
        >
          Cancel
        </button>
        <button
          type="button"
          onClick={() => void done()}
          disabled={busy || !bitmap}
          className="cursor-pointer rounded bg-accent px-4 py-1.5 text-sm text-white hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-60"
        >
          {busy ? 'Working…' : 'Done'}
        </button>
      </div>
    </div>
  );
}

/**
 * Choose, upload and clear a picture - an avatar or a server icon.
 *
 * Pictures are the one thing the client uploads in the clear, because every
 * other client has to render them without holding a channel key. So the work
 * is done before the upload rather than after: the file is cropped square and
 * re-encoded small here, and what reaches the server is what everyone fetches.
 */
import { useRef, useState } from 'react';
import { api } from '../services/api';
import { preparePicture } from '../services/attachments';
import { ImageEditor } from './ImageEditor';

export function PicturePicker({
  label,
  onChange,
  onClear,
  children,
  aspect = 1,
  maxWidth = 512,
  hint,
}: {
  /** Names the control for a screen reader: "avatar", "server icon", "cover". */
  label: string;
  onChange: (url: string) => Promise<void> | void;
  /** Omitted when there is nothing to clear back to. */
  onClear?: () => Promise<void> | void;
  /** The picture as it looks now - an Avatar, usually. Omitted when already displayed elsewhere. */
  children?: React.ReactNode;
  /**
   * Width over height of the frame the picture is cropped to. 1 for an avatar
   * or an icon, `COVER_ASPECT` for the band behind a name.
   *
   * The frame is the same number in the editor and in what is stored, because
   * a person who moves a photograph inside a square frame and then gets a wide
   * crop of it has been shown a lie about what they were choosing.
   */
  aspect?: number;
  /** The widest the stored picture is kept. See `COVER_MAX_WIDTH`. */
  maxWidth?: number;
  /** Replaces the line under the buttons; the default describes a square. */
  hint?: string;
}): JSX.Element {
  const picker = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);

  /**
   * The picked file, held while it is being framed. A centre crop is what this
   * used to do on its own, and it is the wrong crop for most photographs of a
   * person - who is rarely in the middle of their own picture.
   */
  const [editing, setEditing] = useState<File | null>(null);

  const upload = async (picture: Blob): Promise<void> => {
    setBusy(true);
    setFailure(null);
    try {
      // The editor already framed it to `aspect`, so this is a scale to the
      // stored size rather than a second crop - which is why the same aspect
      // has to be passed to both.
      const framed = await preparePicture(
        new File([picture], 'picture.webp', { type: picture.type }),
        maxWidth,
        aspect,
      );
      const stored = await api.uploadPicture(framed, 'picture.webp');
      await onChange(stored.url);
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'That picture could not be uploaded');
    } finally {
      setBusy(false);
    }
  };

  const clear = async (): Promise<void> => {
    if (!onClear) return;
    setBusy(true);
    setFailure(null);
    try {
      await onClear();
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'That could not be removed');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className={aspect === 1 ? 'flex items-center gap-4' : 'space-y-3'}>
      {editing && (
        <ImageEditor
          file={editing}
          aspect={aspect}
          title={`Frame your ${label}`}
          type="image/webp"
          maxOutputEdge={Math.max(1024, maxWidth)}
          onCancel={() => setEditing(null)}
          onDone={(edited) => {
            setEditing(null);
            void upload(edited);
          }}
        />
      )}

      {children && (
        <button
          type="button"
          onClick={() => picker.current?.click()}
          disabled={busy}
          aria-label={`Change ${label}`}
          title={`Change ${label}`}
          className={`group relative cursor-pointer disabled:cursor-not-allowed shrink-0 ${
            aspect === 1 ? 'rounded-full' : 'w-full rounded-lg'
          }`}
        >
          {children}
          <span
            className={`absolute inset-0 flex items-center justify-center bg-black/60 text-[10px] font-bold uppercase tracking-wide text-white opacity-0 transition-opacity duration-200 group-hover:opacity-100 ${
              aspect === 1 ? 'rounded-full' : 'rounded-lg'
            }`}
          >
            {busy ? '…' : 'Change'}
          </span>
        </button>
      )}

      <div>
        <input
          ref={picker}
          type="file"
          accept="image/png,image/jpeg,image/gif,image/webp"
          hidden
          onChange={(event) => {
            const file = event.target.files?.[0];
            if (file) {
              setFailure(null);
              setEditing(file);
            }
            // Reset, or choosing the same file twice in a row does nothing.
            event.target.value = '';
          }}
        />
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => picker.current?.click()}
            disabled={busy}
            className="cursor-pointer rounded bg-accent px-3 py-1.5 text-sm text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-60"
          >
            {busy ? 'Uploading…' : `Upload ${label}`}
          </button>
          {onClear && (
            <button
              type="button"
              onClick={() => void clear()}
              disabled={busy}
              className="cursor-pointer rounded px-3 py-1.5 text-sm text-slate-300 transition-colors duration-200 hover:text-danger disabled:cursor-not-allowed"
            >
              Remove
            </button>
          )}
        </div>
        <p className="mt-1 text-xs text-slate-400">
          {failure ?? hint ?? `A square is cropped from the middle and scaled to ${maxWidth}px.`}
        </p>
      </div>
    </div>
  );
}

/** Run with `tsx src/components/ProfileCard.check.ts`. Where the hover card lands. */
import assert from 'node:assert/strict';
import { place } from './ProfileCard';

const screen = { width: 1440, height: 900 };
const CARD = { width: 288, height: 200 };

// --- the ordinary case: beside the row, on the left ---------------------------

// A member column sits at the right-hand edge, so the card opens leftwards.
const beside = place({ x: 1180, y: 300 }, CARD.width, CARD.height, screen);
assert.equal(beside.x, 1180 - 288 - 12, 'a card opens to the left of what it belongs to');
assert.equal(beside.y, 300, 'and starts level with it');

// --- and flips when there is no room on that side -----------------------------

// A name at the far left has nothing to its left, so the card goes the other way.
const flipped = place({ x: 20, y: 300 }, CARD.width, CARD.height, screen);
assert.equal(flipped.x, 32, 'no room on the left means opening to the right');

// A screen narrower than the card plus both gaps cannot satisfy either side;
// the card is pinned to the edge rather than pushed off it.
const narrow = place({ x: 10, y: 100 }, CARD.width, CARD.height, { width: 300, height: 900 });
assert.equal(narrow.x, 8, 'a card never starts off the left edge');
assert.ok(narrow.x >= 8, 'nor past it');

// --- and slides up rather than hanging off the bottom -------------------------

const low = place({ x: 1180, y: 860 }, CARD.width, CARD.height, screen);
assert.equal(low.y, 900 - 200 - 8, 'a row near the bottom slides the card up to fit');
assert.ok(low.y + CARD.height <= screen.height, 'and it is fully on screen');

// A card taller than the window is pinned to the top rather than centred off
// both edges - the top is the half worth reading.
const tall = place({ x: 600, y: 500 }, CARD.width, 2_000, screen);
assert.equal(tall.y, 8);

// --- height is measured, not assumed -----------------------------------------

// The same anchor with a taller card is placed differently. This is why the
// component measures itself instead of trusting the constant it guessed with.
const short = place({ x: 1180, y: 800 }, CARD.width, 160, screen);
const long = place({ x: 1180, y: 800 }, CARD.width, 320, screen);
assert.ok(long.y < short.y, 'a longer about line pushes the card further up');

console.log('ProfileCard: ok');

/**
 * The card that appears when the pointer rests on somebody's name or picture.
 *
 * What Teams does, and for the reason Teams does it: a member column is a list
 * of names, and the questions you actually have about a name - are they here,
 * when were they last here, what does their line say - are not worth a click,
 * a dialog and a way back out. Resting on the name answers them, moving on
 * dismisses it, and nothing has been navigated to.
 *
 * It is a hover affordance and therefore a pointer affordance: a touch screen
 * has no "resting", so the same information is reached by the gesture that
 * screen already has - a long press here, a double tap on Android. The card
 * itself is identical either way, which is the point of it being one component.
 */
import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { PresenceStatus } from '@betweenus/shared-types';
import { usePresenceStore } from '../stores/presence';
import { profilePresence } from '../services/last-seen';
import { Avatar } from './Avatar';
import { ProfileCover } from './ProfileCover';
import { openProfile } from './ProfileScreen';

/**
 * How long the pointer has to rest before the card opens.
 *
 * Long enough that crossing a member column on the way somewhere else opens
 * nothing, short enough that resting on a name is a gesture rather than a wait.
 * Teams and Slack both sit around here; a delay measured in seconds turns a
 * hover card into a feature nobody discovers.
 */
const OPEN_AFTER_MS = 600;

/**
 * And how long it survives the pointer leaving.
 *
 * The gap between a name and the card that opened beside it is crossed by a
 * pointer that is briefly over neither, so a card that closed the instant it
 * was left could not be reached to read.
 */
const CLOSE_AFTER_MS = 200;

/**
 * How long a finger has to stay down before the card opens on a touch screen.
 *
 * The same information, reached by the gesture a screen with no pointer has.
 * Android's double tap is the same decision made against a different set of
 * gestures already spoken for.
 */
const PRESS_AFTER_MS = 500;

/** Roughly the card's own size, for the first placement before it is measured. */
const CARD_WIDTH = 288;
// The cover band and the footer button both made the card taller than the 200
// it used to guess at. Only a first guess - it is measured on the next frame -
// but a guess that is 60px short makes the first paint jump, which is exactly
// what measuring was added to stop.
const CARD_HEIGHT = 300;

export interface ProfileCardPerson {
  userId: string;
  displayName: string;
  username: string;
  avatarUrl: string | null;
  /** The band behind the name. Null or absent draws the accent gradient. */
  coverUrl?: string | null;
  about: string;
  /** The colour of their highest-ranked role, where they have one. */
  colour?: string | null;
}

/**
 * Wraps whatever draws a person and opens the card over it.
 *
 * A wrapper rather than a prop on `Avatar`, because the thing worth resting on
 * is the name *and* the picture together - in a member row they are one target,
 * and two independent hover zones side by side would flicker between them.
 */
export function ProfileHover({
  person,
  children,
  className = '',
}: {
  person: ProfileCardPerson;
  children: React.ReactNode;
  className?: string;
}): JSX.Element {
  const [at, setAt] = useState<{ x: number; y: number } | null>(null);
  const anchor = useRef<HTMLDivElement | null>(null);
  const openTimer = useRef<number | null>(null);
  const closeTimer = useRef<number | null>(null);

  const cancel = (): void => {
    if (openTimer.current !== null) window.clearTimeout(openTimer.current);
    if (closeTimer.current !== null) window.clearTimeout(closeTimer.current);
    openTimer.current = null;
    closeTimer.current = null;
  };

  useEffect(() => cancel, []);

  const open = (after: number): void => {
    cancel();
    openTimer.current = window.setTimeout(() => {
      const box = anchor.current?.getBoundingClientRect();
      if (!box) return;
      setAt({ x: box.left, y: box.top });
      // Asked once per opening rather than kept fresh: a last-seen time that is
      // a minute stale reads exactly the same, and a card that polls is a
      // request every time somebody's pointer crosses a list.
      usePresenceStore.getState().askLastSeen([person.userId]);
    }, after);
  };

  const close = (): void => {
    cancel();
    closeTimer.current = window.setTimeout(() => setAt(null), CLOSE_AFTER_MS);
  };

  return (
    <div
      ref={anchor}
      onPointerEnter={(event) => {
        // A touch "enters" on contact and never leaves, so hovering is not a
        // gesture it has. The long press below is what a finger uses instead.
        if (event.pointerType === 'touch') return;
        open(OPEN_AFTER_MS);
      }}
      onPointerLeave={(event) => {
        if (event.pointerType === 'touch') return;
        close();
      }}
      onTouchStart={() => open(PRESS_AFTER_MS)}
      // A finger that moved was scrolling the list, not resting on a name.
      onTouchMove={cancel}
      onTouchEnd={cancel}
      className={className}
    >
      {children}
      {at && (
        <ProfileCard
          person={person}
          at={at}
          onPointerEnter={cancel}
          onPointerLeave={close}
          onDismiss={() => {
            cancel();
            setAt(null);
          }}
        />
      )}
    </div>
  );
}

/**
 * The card itself, positioned beside `at` and flipped to whichever side of it
 * has the room. Exported so a click or a double tap can open one directly.
 */
export function ProfileCard({
  person,
  at,
  onPointerEnter,
  onPointerLeave,
  onDismiss,
}: {
  person: ProfileCardPerson;
  at: { x: number; y: number };
  onPointerEnter?: () => void;
  onPointerLeave?: () => void;
  onDismiss: () => void;
}): JSX.Element {
  const status = usePresenceStore((state) => state.statuses.get(person.userId) ?? 'offline');
  const lastSeenAt = usePresenceStore((state) => state.lastSeen.get(person.userId) ?? null);
  const card = useRef<HTMLDivElement | null>(null);
  const [box, setBox] = useState(() => place(at, CARD_WIDTH, CARD_HEIGHT));

  // Measured once it is real, because the about line decides the height and a
  // card guessed at 200px tall hangs off the bottom of the window when it is
  // 260. A layout effect rather than an effect, so it never paints in the
  // guessed place first and jumps.
  useLayoutEffect(() => {
    const size = card.current?.getBoundingClientRect();
    if (size) setBox(place(at, size.width, size.height));
  }, [at, person.about]);

  useEffect(() => {
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onDismiss();
    };
    document.addEventListener('keydown', escape);
    return () => document.removeEventListener('keydown', escape);
  }, [onDismiss]);

  // `profilePresence` and not `presenceLine`: a card always says something.
  // Offline with no timestamp - a new account, or one whose last seen is hidden
  // from you - used to draw nothing at all here, which read as a card that had
  // failed to load rather than as somebody nobody has seen.
  const line = profilePresence(status as PresenceStatus, lastSeenAt);

  return (
    <div
      ref={card}
      role="dialog"
      aria-label={`Profile of ${person.displayName}`}
      onPointerEnter={onPointerEnter}
      onPointerLeave={onPointerLeave}
      style={{ left: box.x, top: box.y }}
      className="fixed z-[70] w-72 animate-pop overflow-hidden rounded-xl border border-edge bg-surface-800 shadow-pop"
    >
      {/* A short band rather than the full one the profile screen draws: this
          is a card, and a picture tall enough to be looked at properly is the
          reason the screen below exists. */}
      {/* Written out rather than built from a constant: Tailwind reads these
          class names out of the source at build time and never sees one that
          was concatenated at runtime. */}
      <ProfileCover coverUrl={person.coverUrl} className="h-[60px]" />

      <div className="px-4 pb-4">
        <div className="-mt-8 inline-block rounded-full border-[5px] border-surface-800">
          <Avatar
            name={person.displayName}
            avatarUrl={person.avatarUrl}
            status={status as PresenceStatus}
            size="md"
            ringColour="border-surface-800"
          />
        </div>
        <p
          className="truncate text-[15px] font-semibold text-slate-50"
          style={person.colour ? { color: person.colour } : undefined}
        >
          {person.displayName}
        </p>
        <p className="truncate text-xs text-slate-400">@{person.username}</p>

        <p className="mt-3 text-xs text-slate-400">{line}</p>

        {person.about.trim() && (
          <>
            <p className="mt-3 text-[10px] font-bold uppercase tracking-wide text-slate-500">
              About
            </p>
            {/* Wrapped and clamped: 140 characters is two lines at this width,
                and a card that grows past three moves whatever is under it.
                The unclamped line is one click away, below. */}
            <p className="mt-1 line-clamp-3 whitespace-pre-wrap break-words text-sm text-slate-200">
              {person.about}
            </p>
          </>
        )}

        {/* The way out of a hover affordance and into a place. Its own button
            rather than making the whole card clickable: a card that opens
            something when the pointer stops moving on it would fire every time
            somebody crossed a member list on the way elsewhere. */}
        <button
          type="button"
          onClick={() => {
            onDismiss();
            openProfile(person);
          }}
          className="mt-4 w-full cursor-pointer rounded-md bg-surface-700 px-3 py-2 text-xs font-medium text-slate-200 transition-colors duration-150 hover:bg-white/[0.08] hover:text-white"
        >
          View full profile
        </button>
      </div>
    </div>
  );
}

/**
 * Where the card goes: beside the anchor, flipped to whichever side has room,
 * and never off the edge of the window.
 *
 * Exported for the check, which is the only way to test placement without a
 * browser - and the cases worth testing are exactly the ones that need a member
 * column pinned to the right-hand edge of a screen to reproduce by hand.
 */
export function place(
  at: { x: number; y: number },
  width: number,
  height: number,
  viewport: { width: number; height: number } = {
    width: window.innerWidth,
    height: window.innerHeight,
  },
): { x: number; y: number } {
  const GAP = 12;
  const EDGE = 8;

  // Left of the anchor by preference: the member column lives on the right, so
  // opening rightwards would put every card of the common case off the screen.
  let x = at.x - width - GAP;
  if (x < EDGE) x = Math.min(at.x + GAP, viewport.width - width - EDGE);
  x = Math.max(EDGE, x);

  // Vertically it starts level with the row and slides up only as far as it has
  // to, so the card stays attached to whatever opened it.
  let y = at.y;
  if (y + height > viewport.height - EDGE) y = viewport.height - height - EDGE;
  y = Math.max(EDGE, y);

  return { x, y };
}

/**
 * The wide band behind a name at the top of a profile.
 *
 * One component for all three places that draw one - the settings header, the
 * hover card and the full profile - because the fallback is the interesting
 * part and it has to be the same fallback everywhere. An account with no cover
 * gets the accent colour, which is exactly what every one of those places drew
 * before covers existed, so nothing looks broken on an account that has not
 * chosen a picture.
 *
 * A gradient rather than a flat fill on the fallback: a flat band under a round
 * avatar reads as a placeholder that failed to load, and the accent at two
 * stops reads as a decision. It is the same colour either way, so a deployment
 * that has themed its accent gets a themed cover for free.
 */
import { absoluteUrl } from '../services/endpoint';

export function ProfileCover({
  coverUrl,
  className = '',
  children,
}: {
  coverUrl: string | null | undefined;
  /** Sets the height; the aspect is fixed by whatever draws it. */
  className?: string;
  /** Drawn over the band - a close button, usually. */
  children?: React.ReactNode;
}): JSX.Element {
  return (
    <div
      className={`relative overflow-hidden bg-gradient-to-br from-accent to-accent-hover ${className}`}
    >
      {coverUrl && (
        <img
          src={absoluteUrl(coverUrl)}
          alt=""
          // Decorative: the name under it is the label, and a screen reader
          // announcing "cover photo" before every profile is noise.
          aria-hidden="true"
          className="h-full w-full object-cover"
        />
      )}
      {/* A scrim only under a real picture. The name and the avatar sit on the
          bottom edge of this band, and a photograph with a bright lower half
          makes both of them unreadable - where the accent gradient never
          does, so darkening that would only mute the theme for nothing. */}
      {coverUrl && (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/45 to-transparent"
        />
      )}
      {children}
    </div>
  );
}

/**
 * Everything about one person, on a page of its own.
 *
 * The hover card answers the questions that are not worth a click - are they
 * here, what does their line say. This answers the ones that are: the whole
 * about line rather than three clamped lines of it, the cover picture at a size
 * worth having uploaded, the rung they hold in this server, and when they
 * joined it. A card that grew to hold all of that would stop being a card,
 * which is why this is a second thing rather than a bigger first one.
 *
 * Opened from the card's own footer button, and from a click on an avatar. It
 * is deliberately reachable from both: the button is the discoverable route and
 * the avatar is the one people try first.
 */
import { useEffect } from 'react';
import { create } from 'zustand';
import type { PresenceStatus } from '@betweenus/shared-types';
import { usePresenceStore } from '../stores/presence';
import { useChatStore } from '../stores/chat';
import { profilePresence } from '../services/last-seen';
import { useFocusTrap } from '../services/focus-trap';
import { absoluteUrl } from '../services/endpoint';
import { Avatar } from './Avatar';
import { ProfileCover } from './ProfileCover';
import { XIcon } from './icons';

/** What the screen needs that is not looked up from a store while it is open. */
export interface ProfilePerson {
  userId: string;
  displayName: string;
  username: string;
  avatarUrl: string | null;
  coverUrl?: string | null;
  about: string;
  /** The colour of their highest-ranked role, where they have one. */
  colour?: string | null;
}

interface ProfileScreenState {
  shown: ProfilePerson | null;
}

const useProfileScreen = create<ProfileScreenState>(() => ({ shown: null }));

/**
 * Opens the full profile. Called by the hover card's footer button and by
 * anything else that has a whole person to hand.
 */
export function openProfile(person: ProfilePerson): void {
  useProfileScreen.setState({ shown: person });
  // The same one-shot the card does. A last-seen line that is a minute stale
  // reads identically, and a screen that polls is a request per glance.
  usePresenceStore.getState().askLastSeen([person.userId]);
}

export function closeProfile(): void {
  useProfileScreen.setState({ shown: null });
}

export function ProfileScreen(): JSX.Element | null {
  const shown = useProfileScreen((state) => state.shown);
  if (!shown) return null;
  // Keyed on the person, so opening a second profile from inside the first
  // remounts rather than carrying the previous one's scroll position.
  return <Screen key={shown.userId} person={shown} />;
}

function Screen({ person }: { person: ProfilePerson }): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const status = usePresenceStore((state) => state.statuses.get(person.userId) ?? 'offline');
  const lastSeenAt = usePresenceStore((state) => state.lastSeen.get(person.userId) ?? null);

  // Read live rather than frozen into `person`: a member row carries the roles,
  // the join date and the cover, and whoever opened this may have had only a
  // message author to hand. Absent is fine - every line below is optional.
  const member = useChatStore((state) => state.members.find((row) => row.userId === person.userId));

  useEffect(() => {
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') closeProfile();
    };
    document.addEventListener('keydown', escape);
    return () => document.removeEventListener('keydown', escape);
  }, []);

  const cover = person.coverUrl ?? member?.coverUrl ?? null;
  const about = (member?.about ?? person.about).trim();
  const colour = person.colour ?? member?.colour ?? null;

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label={`${person.displayName} profile`}
      onClick={closeProfile}
      className="fixed inset-0 z-[75] flex animate-fade items-center justify-center bg-black/70 px-4 py-8"
    >
      <div
        onClick={(event) => event.stopPropagation()}
        className="max-h-full w-full max-w-md animate-pop overflow-y-auto rounded-xl border border-edge bg-surface-900 shadow-pop"
      >
        <ProfileCover coverUrl={cover} className="h-[132px]">
          <button
            type="button"
            onClick={closeProfile}
            aria-label="Close profile"
            className="absolute end-2 top-2 flex h-8 w-8 cursor-pointer items-center justify-center rounded-full bg-black/40 text-white transition-colors duration-150 hover:bg-black/60"
          >
            <XIcon className="h-4 w-4" />
          </button>
        </ProfileCover>

        <div className="px-5 pb-5">
          {/* Pulled up over the band, the way every profile since Twitter has
              done it - it is what ties the round picture to the wide one. */}
          <div className="-mt-12 inline-block rounded-full border-[6px] border-surface-900">
            <Avatar
              name={person.displayName}
              avatarUrl={person.avatarUrl}
              status={status as PresenceStatus}
              size="lg"
              ringColour="border-surface-900"
            />
          </div>

          <h2
            className="mt-2 break-words text-xl font-bold text-slate-50"
            style={colour ? { color: colour } : undefined}
          >
            {person.displayName}
          </h2>
          <p className="text-sm text-slate-400">@{member?.username ?? person.username}</p>
          <p className="mt-2 text-xs text-slate-400">
            {profilePresence(status as PresenceStatus, lastSeenAt)}
          </p>

          {about && (
            <section className="mt-5 rounded-lg bg-surface-800 p-4">
              <h3 className="text-[10px] font-bold uppercase tracking-wide text-slate-500">
                About
              </h3>
              {/* Unclamped, unlike the card. This screen exists so the whole
                  line can be read; clamping it here would make it the card
                  again, only slower to reach. */}
              <p className="mt-1 whitespace-pre-wrap break-words text-sm text-slate-200">{about}</p>
            </section>
          )}

          {/* The base rung, not the custom roles. Those are fetched per server
              and are not in any store this screen can read, and a request per
              profile opened is not worth a row of chips - the rung is what a
              member list already shows beside a name anyway. */}
          {member && (
            <section className="mt-3 rounded-lg bg-surface-800 p-4">
              <h3 className="text-[10px] font-bold uppercase tracking-wide text-slate-500">
                Role
              </h3>
              <p className="mt-1 flex items-center gap-2 text-sm text-slate-200">
                <span
                  aria-hidden="true"
                  className="h-2 w-2 rounded-full"
                  style={{ backgroundColor: colour ?? '#94a3b8' }}
                />
                {member.role.charAt(0) + member.role.slice(1).toLowerCase()}
              </p>
            </section>
          )}

          {member && (
            <section className="mt-3 rounded-lg bg-surface-800 p-4">
              <h3 className="text-[10px] font-bold uppercase tracking-wide text-slate-500">
                Member since
              </h3>
              <p className="mt-1 text-sm text-slate-200">{memberSince(member.joinedAt)}</p>
            </section>
          )}

          {/* The cover at full width, for the same reason tapping an avatar
              opens the picture: somebody who uploaded one meant it to be
              looked at. Only when there is one - the accent band is not a
              photograph and there is nothing to open. */}
          {cover && (
            <a
              href={absoluteUrl(cover)}
              target="_blank"
              rel="noreferrer"
              className="mt-3 block text-xs text-slate-500 transition-colors duration-150 hover:text-slate-300"
            >
              Open cover photo
            </a>
          )}
        </div>
      </div>
    </div>
  );
}

/** A join date reads as a date, not a duration - "3 months" ages while you look at it. */
function memberSince(iso: string): string {
  const when = new Date(iso);
  return Number.isNaN(when.getTime()) ? '—' : when.toLocaleDateString();
}

/**
 * The picture behind an avatar, full size, with the name under it.
 *
 * One overlay for the whole app rather than one per avatar: every `Avatar` in
 * the tree calls `viewProfile`, and this is the single thing mounted at the
 * root that answers. Somebody with no picture gets a line saying so instead of
 * a dialog showing the same initial they just tapped.
 */
import { useEffect } from 'react';
import { create } from 'zustand';
import { absoluteUrl } from '../services/endpoint';
import { useFocusTrap } from '../services/focus-trap';

interface ProfileViewState {
  /** The person being looked at, or null when nothing is open. */
  shown: { name: string; avatarUrl: string } | null;
  /** The "no picture" line, cleared on a timer. */
  notice: string | null;
}

const useProfileView = create<ProfileViewState>(() => ({ shown: null, notice: null }));

/** Called by `Avatar`. A picture opens the dialog; the lack of one says so. */
export function viewProfile(name: string, avatarUrl?: string | null): void {
  if (avatarUrl) {
    useProfileView.setState({ shown: { name, avatarUrl }, notice: null });
  } else {
    useProfileView.setState({ notice: `${name} has no profile photo` });
    window.setTimeout(() => useProfileView.setState({ notice: null }), 2500);
  }
}

export function ProfileView(): JSX.Element | null {
  const trap = useFocusTrap<HTMLDivElement>();
  const shown = useProfileView((state) => state.shown);
  const notice = useProfileView((state) => state.notice);
  const close = (): void => useProfileView.setState({ shown: null });

  useEffect(() => {
    if (!shown) return;
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') close();
    };
    document.addEventListener('keydown', escape);
    return () => document.removeEventListener('keydown', escape);
  }, [shown]);

  if (notice) {
    return (
      <div
        role="status"
        className="pointer-events-none fixed inset-x-0 bottom-8 z-[60] flex animate-fade justify-center px-4"
      >
        <p className="rounded-full border border-edge bg-surface-800 px-4 py-2 text-sm text-slate-200 shadow-pop">
          {notice}
        </p>
      </div>
    );
  }

  if (!shown) return null;

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label={`${shown.name}'s profile photo`}
      onClick={close}
      className="fixed inset-0 z-[60] flex animate-fade items-center justify-center bg-black/75 px-4"
    >
      <div
        onClick={(event) => event.stopPropagation()}
        className="flex w-full max-w-xs animate-pop flex-col items-center gap-4 rounded-xl border border-edge bg-surface-900 p-5 shadow-pop"
      >
        <img
          src={absoluteUrl(shown.avatarUrl)}
          alt={`${shown.name}'s profile photo`}
          className="aspect-square w-full rounded-lg object-cover"
        />
        <h2 className="max-w-full truncate text-lg font-semibold text-slate-50">{shown.name}</h2>
        <button
          type="button"
          onClick={close}
          className="w-full cursor-pointer rounded-lg border border-edge px-4 py-2 text-sm font-medium text-slate-300 transition-colors duration-150 hover:bg-white/[0.04] hover:text-slate-100"
        >
          Close
        </button>
      </div>
    </div>
  );
}

/**
 * A GitHub release body, drawn.
 *
 * The notes are markdown - `### Features` and a list under it, `**bold**`, a
 * fenced block of shell - and until this they were dropped into a `<pre>`-ish
 * paragraph, hashes, asterisks, backticks and all. Which is exactly the shape
 * that makes somebody stop reading the thing telling them what changed.
 *
 * It is the message parser, not a second one: `parseNotes` is `parse` with
 * headings switched on, because a heading in a chat line is shouting and a
 * release note is nothing but headings. What is not shared is the drawing -
 * the message list lays custom emoji and link previews over its runs, and none
 * of that belongs in a changelog.
 *
 * Android draws the same blocks in `feature/update/ReleaseNotes.kt`. Changing
 * one changes both, or the same release reads differently on two screens.
 */
import { parseNotes, styleRuns, type Block, type Run } from '../services/markup';

export function ReleaseNotes({ text }: { text: string }): JSX.Element | null {
  const trimmed = text.trim();
  if (trimmed.length === 0) return null;

  return (
    <div className="space-y-1.5 text-sm text-slate-300">
      {group(blocks(trimmed)).map((run, index) =>
        run.kind === 'list' ? (
          <List key={index} items={run.blocks} />
        ) : (
          <Piece key={index} block={run.blocks[0]!} />
        ),
      )}
    </div>
  );
}

/**
 * `parseNotes` treats a blank line as a paragraph break, so nothing empty
 * should come back. This is the belt to that pair of braces: a block with
 * nothing in it draws as an empty paragraph on top of the spacing this already
 * has, and a release note has a blank line under every heading.
 */
function blocks(text: string): Block[] {
  return parseNotes(text).filter((block) => block.kind !== 'body' || block.text.trim() !== '');
}

/**
 * Consecutive list items are one list. The parser keeps its blocks flat -
 * each item its own - and turning a run of them back into a `<ul>` is the
 * renderer's job, the same way the message list does it.
 */
function group(blocks: Block[]): Array<{ kind: 'list' | 'one'; blocks: Block[] }> {
  const groups: Array<{ kind: 'list' | 'one'; blocks: Block[] }> = [];
  for (const block of blocks) {
    const isItem = block.kind === 'bullet' || block.kind === 'number';
    const open = groups[groups.length - 1];
    if (isItem && open?.kind === 'list' && open.blocks[0]!.kind === block.kind) {
      open.blocks.push(block);
    } else {
      groups.push({ kind: isItem ? 'list' : 'one', blocks: [block] });
    }
  }
  return groups;
}

function List({ items }: { items: Block[] }): JSX.Element {
  const numbered = items[0]!.kind === 'number';
  const Tag = numbered ? 'ol' : 'ul';

  // The marker sits in a gutter of its own rather than inline, so a wrapped
  // item lines up under its own first word instead of under the bullet.
  return (
    <Tag className="space-y-0.5">
      {items.map((item, index) => (
        <li key={index} className="flex gap-2">
          <span aria-hidden="true" className="w-4 shrink-0 text-end text-slate-500">
            {numbered ? `${item.ordinal}.` : '•'}
          </span>
          <span className="min-w-0 flex-1">
            <Inline block={item} />
          </span>
        </li>
      ))}
    </Tag>
  );
}

/**
 * Two sizes of heading, not six. A release note's own `##` and `###` are the
 * only levels that appear, and a changelog in a settings panel is not a
 * document that needs an outline - it needs the sections to be findable.
 */
const HEADING_CLASS: Record<number, string> = {
  1: 'mt-3 text-base font-semibold text-slate-100',
  2: 'mt-3 text-sm font-semibold text-slate-100',
};

function Piece({ block }: { block: Block }): JSX.Element {
  if (block.kind === 'heading') {
    const Tag = block.ordinal <= 2 ? 'h3' : 'h4';
    return (
      <Tag className={`${HEADING_CLASS[Math.min(block.ordinal, 2)]} first:mt-0`}>
        <Inline block={block} />
      </Tag>
    );
  }

  if (block.kind === 'code') {
    return (
      <pre className="overflow-x-auto rounded-md border border-edge bg-surface-950 px-3 py-2 font-mono text-xs text-slate-100">
        <code>{block.text}</code>
      </pre>
    );
  }

  if (block.kind === 'quote') {
    return (
      <blockquote className="whitespace-pre-wrap break-words border-s-[3px] border-edge ps-2.5 text-slate-400">
        <Inline block={block} />
      </blockquote>
    );
  }

  return (
    <p className="whitespace-pre-wrap break-words">
      <Inline block={block} />
    </p>
  );
}

/** A block's words, with its styles laid over them. */
function Inline({ block }: { block: Block }): JSX.Element {
  return (
    <>
      {styleRuns(block.text, block.spans).map((run, index) => (
        <Styled key={index} run={run} />
      ))}
    </>
  );
}

function Styled({ run }: { run: Run }): JSX.Element {
  let node: JSX.Element = run.styles.includes('code') ? (
    <code className="rounded bg-surface-950 px-1 py-0.5 font-mono text-[0.9em]">{run.text}</code>
  ) : (
    <>{run.text}</>
  );

  if (run.styles.includes('strike')) node = <del>{node}</del>;
  if (run.styles.includes('italic')) node = <em>{node}</em>;
  if (run.styles.includes('bold')) node = <strong className="font-semibold text-slate-100">{node}</strong>;
  return node;
}

import { absoluteUrl } from '../services/endpoint';

/**
 * A server's picture, or its initials when it has none - the same fallback
 * Discord uses, and the reason a server without an icon is still recognisable
 * in the rail.
 */
const SIZES = {
  /** Beside a section heading, where it sits at the cap height of the words. */
  xs: 'h-4 w-4 text-[8px]',
  sm: 'h-7 w-7 text-xs',
  rail: 'h-full w-full text-xs',
  md: 'h-10 w-10 text-sm',
  lg: 'h-20 w-20 text-2xl',
} as const;

export function ServerIcon({
  server,
  size = 'md',
  className,
}: {
  server: { name: string; iconUrl?: string | null } | undefined;
  size?: keyof typeof SIZES;
  className?: string;
}): JSX.Element {
  if (server?.iconUrl) {
    return (
      <img
        src={absoluteUrl(server.iconUrl)}
        alt=""
        className={`${SIZES[size]} ${size === 'rail' ? 'rounded-none' : 'rounded-full'} object-cover ${className ?? ''}`}
      />
    );
  }

  return (
    <span
      className={`flex ${SIZES[size]} items-center justify-center font-semibold ${
        size === 'rail'
          ? 'bg-transparent text-inherit'
          : 'rounded-full bg-surface-700 text-slate-100'
      } ${className ?? ''}`}
    >
      {initials(server?.name ?? '?')}
    </span>
  );
}

/** Up to two letters, one per word, the way a server pill reads at a glance. */
export function initials(name: string): string {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? '')
    .join('');
}

import { useEffect, useMemo } from 'react';
import { commandKey, shortcuts, type Shortcut } from '../services/shortcuts';
import { useFocusTrap } from '../services/focus-trap';

/**
 * What the keyboard can do, on `?`.
 *
 * The list itself lives in `services/shortcuts.ts` so that adding a binding and
 * telling anybody about it are the same edit. A shortcut whose only record is
 * the handler that implements it is one nobody presses.
 *
 * Grouped by where each works, because "nothing happened" is what an
 * unqualified list produces: `F` full-screens a call and does nothing in a
 * conversation, and a sheet that does not say so has taught somebody the app is
 * broken.
 */
export function ShortcutSheet({ onClose }: { onClose: () => void }): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const groups = useMemo(() => {
    const all = shortcuts(commandKey());
    const order: Shortcut['where'][] = ['Anywhere', 'In a conversation', 'In a call'];
    return order
      .map((where) => ({ where, items: all.filter((entry) => entry.where === where) }))
      .filter((group) => group.items.length > 0);
  }, []);

  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label="Keyboard shortcuts"
      className="fixed inset-0 z-50 flex animate-fade justify-center bg-black/50 px-2 pt-[6vh] sm:px-4 sm:pt-[12vh]"
      onClick={onClose}
    >
      <div
        className="h-fit w-full max-w-lg animate-pop overflow-hidden rounded-xl border border-edge bg-surface-900 shadow-pop"
        onClick={(event) => event.stopPropagation()}
      >
        <header className="border-b border-edge px-4 py-3">
          <h2 className="text-[15px] font-semibold text-slate-100">Keyboard shortcuts</h2>
        </header>

        <div className="max-h-[60vh] overflow-y-auto p-2">
          {groups.map((group) => (
            <section key={group.where} className="mb-2 last:mb-0">
              <h3 className="px-2 py-1.5 text-xs font-semibold uppercase tracking-wide text-slate-500">
                {group.where}
              </h3>
              <ul>
                {group.items.map((entry) => (
                  <li
                    key={`${group.where}:${entry.keys.join('+')}`}
                    className="flex items-center gap-3 rounded-lg px-2 py-2"
                  >
                    <span className="min-w-0 flex-1 text-sm text-slate-200">{entry.what}</span>
                    <span className="flex shrink-0 items-center gap-1">
                      {entry.keys.map((key) => (
                        <kbd
                          key={key}
                          className="rounded border border-edge bg-surface-700 px-1.5 py-0.5 text-xs font-medium text-slate-200"
                        >
                          {key}
                        </kbd>
                      ))}
                    </span>
                  </li>
                ))}
              </ul>
            </section>
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * The two things a list draws when it has no rows: grey bars while it waits,
 * and a sentence when there is genuinely nothing.
 *
 * Both were written per-list before this, which is how the client ended up with
 * one list that skeletons (the conversation), three that go blank, and two that
 * claim to be empty while they are still fetching. `services/list-state.ts`
 * decides which of the three a list is in; this draws two of them.
 *
 * ## Why the pulse is `motion-safe:`
 *
 * `index.css` already flattens every animation under
 * `prefers-reduced-motion: reduce`, so the pulse would stop anyway. The variant
 * is here so the *intent* is in the markup rather than only in a global
 * override somebody may one day scope more narrowly - a skeleton that keeps
 * throbbing is exactly the kind of thing that setting exists to turn off.
 */
import type { ReactNode } from 'react';

/**
 * One grey bar. `className` carries its size, because a skeleton is only
 * useful if it is the shape of the thing it stands in for.
 */
export function Skeleton({ className = '' }: { className?: string }): JSX.Element {
  return <div aria-hidden="true" className={`motion-safe:animate-pulse rounded bg-surface-800 ${className}`} />;
}

/**
 * `rows` placeholder people: a round avatar and a name beside it.
 *
 * The shape most of this client's lists are - members, friends, machines - so
 * one component covers them and a list that gains a skeleton later does not
 * invent a fourth grey rectangle.
 *
 * `aria-busy` and nothing else: a screen reader is told the region is working
 * and is spared a reading of six meaningless boxes. The rows themselves are
 * `aria-hidden` through `Skeleton`.
 */
export function SkeletonRows({
  rows = 5,
  className = '',
  label = 'Loading',
}: {
  rows?: number;
  className?: string;
  /** What is loading, for anybody who cannot see the bars. */
  label?: string;
}): JSX.Element {
  return (
    <div aria-busy="true" aria-label={label} role="status" className={`space-y-3 ${className}`}>
      {Array.from({ length: rows }, (_, row) => (
        <div key={row} className="flex items-center gap-3">
          <Skeleton className="h-8 w-8 shrink-0 rounded-full" />
          {/* Varied widths on purpose. A column of identical bars reads as a
              table that failed to load; uneven ones read as names. */}
          <Skeleton className={`h-3 ${['w-32', 'w-24', 'w-40', 'w-28'][row % 4]}`} />
        </div>
      ))}
    </div>
  );
}

/**
 * Nothing here, and what to do about it.
 *
 * The hint is not optional and is not decoration: an empty state that says only
 * "No machines" has told somebody the same thing the blank screen did. The one
 * that says how to get a machine into the list is the whole point.
 */
export function EmptyState({
  icon,
  title,
  hint,
  className = '',
}: {
  icon?: ReactNode;
  title: string;
  hint?: ReactNode;
  className?: string;
}): JSX.Element {
  return (
    <div className={`flex flex-col items-center justify-center px-6 py-10 text-center ${className}`}>
      {icon && <div aria-hidden="true" className="mb-3 text-slate-600">{icon}</div>}
      <p className="text-sm font-semibold text-slate-200">{title}</p>
      {hint && <p className="mt-1.5 max-w-xs text-sm text-slate-400">{hint}</p>}
    </div>
  );
}

/**
 * Self-check for the segmented ring's geometry.
 *
 * Worth asserting because it is arithmetic nobody reads back off the screen:
 * an off-by-one in the offsets draws a ring that is subtly wrong - segments
 * that overlap, or a gap that grows around the circle - and it looks like a
 * rendering quirk rather than a bug in a formula.
 */
import assert from 'node:assert/strict';
import { MAX_SEGMENTS, ringSegments } from './StatusRing';

const CIRCUMFERENCE = 2 * Math.PI * 47;

/** The drawn part of a dasharray. */
const arcOf = (dash: string): number => Number(dash.split(' ')[0]);

// One post is a whole circle with no notch in it: a lone arc with a gap reads
// as a rendering fault, not as a count of one.
const single = ringSegments(1);
assert.equal(single.length, 1);
assert.equal(arcOf(single[0]!.dash), CIRCUMFERENCE);
assert.equal(single[0]!.offset, 0);

// Four posts are four arcs, evenly spaced, starting at the top of each quarter.
const four = ringSegments(4);
assert.equal(four.length, 4);
const step = CIRCUMFERENCE / 4;
four.forEach((segment, index) => {
  assert.equal(segment.offset, -index * step);
  // Each arc is its share of the circle less one gap.
  assert.ok(Math.abs(arcOf(segment.dash) - (step - 5)) < 1e-9);
});

// Every arc plus every gap is exactly one circle - no drift, no overlap.
const total = four.reduce((sum, segment) => sum + arcOf(segment.dash) + 5, 0);
assert.ok(Math.abs(total - CIRCUMFERENCE) < 1e-9);

// Past the point where an arc would be shorter than the gap beside it, the
// count stops being drawn and the ring goes solid. It stopped being legible
// well before that, and arcs shorter than their gaps read as a dashed line.
const many = ringSegments(MAX_SEGMENTS + 1);
assert.equal(many.length, 1);
assert.equal(arcOf(many[0]!.dash), CIRCUMFERENCE);

// The last size that is still counted really is counted.
assert.equal(ringSegments(MAX_SEGMENTS).length, MAX_SEGMENTS);

// Nothing posted draws nothing, and the caller never asks - but a zero must
// not divide by itself into NaN if it ever does.
assert.equal(ringSegments(0).length, 1);

console.log('status ring check ok');

/**
 * The ring around an avatar that says somebody has posted, split into one arc
 * per post.
 *
 * The split is the whole point: a solid ring says "there is something here"
 * and a ring in four pieces says "there are four things here", which is the
 * question people actually have before deciding to open it. It is the same
 * device the tray uses to count, so the count is never a number to read.
 *
 * Drawn as an SVG stroke rather than a border, because a border cannot be cut
 * into arcs and a conic gradient cannot leave a gap between them.
 */
const RADIUS = 47;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

/** The gap between two arcs, in user units of the 100-wide viewBox. */
const GAP = 5;

export interface RingSegment {
  /** `stroke-dasharray`: the drawn arc, then the rest of the circle. */
  dash: string;
  /** Where that arc starts, as a negative `stroke-dashoffset`. */
  offset: number;
}

/**
 * One entry per post, as dash geometry.
 *
 * A single post gets the whole circle with no gap - a lone arc with a notch in
 * it reads as a rendering fault rather than as a count. Above a dozen or so
 * the arcs would be shorter than the gaps between them, so the count stops
 * being drawn and the ring goes solid; the exact number stopped being legible
 * long before that.
 */
export const MAX_SEGMENTS = 12;

export function ringSegments(count: number): RingSegment[] {
  if (count <= 1 || count > MAX_SEGMENTS) {
    return [{ dash: `${CIRCUMFERENCE} 0`, offset: 0 }];
  }
  const step = CIRCUMFERENCE / count;
  const arc = step - GAP;
  return Array.from({ length: count }, (_, index) => ({
    dash: `${arc} ${CIRCUMFERENCE - arc}`,
    // SVG strokes start at three o'clock and run clockwise; a negative offset
    // walks the start of each arc forward around the circle.
    offset: -index * step,
  }));
}

/**
 * The ring itself, sized to whatever it is laid over.
 *
 * Green while there is something unopened, and grey once there is not - the
 * two states everybody already reads without being told which is which.
 */
export function StatusRing({
  count,
  unseen,
}: {
  count: number;
  unseen: boolean;
}): JSX.Element {
  return (
    <svg
      viewBox="0 0 100 100"
      aria-hidden="true"
      className="pointer-events-none absolute inset-[-4px] h-[calc(100%+8px)] w-[calc(100%+8px)]"
    >
      {ringSegments(count).map((segment, index) => (
        <circle
          key={index}
          cx="50"
          cy="50"
          r={RADIUS}
          fill="none"
          strokeWidth="5"
          strokeLinecap="round"
          strokeDasharray={segment.dash}
          strokeDashoffset={segment.offset}
          className={unseen ? 'stroke-status-online' : 'stroke-slate-600'}
        />
      ))}
    </svg>
  );
}

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Where the notice strips sit, which is a layout rule the components cannot
 * state for themselves.
 *
 * Windows paints the minimise/maximise/close overlay into the top forty pixels
 * of the window no matter what the renderer draws there, and TopBar is the one
 * row that reserves a gap for it. A strip above TopBar therefore ran underneath
 * the close button - which sliced "Restart and install" down to "Res".
 */
const here = path.dirname(fileURLToPath(import.meta.url));
const app = fs.readFileSync(path.join(here, '..', 'App.tsx'), 'utf8');

const topBar = app.indexOf('<TopBar');
assert.ok(topBar > 0, 'App still renders TopBar');

for (const notice of ['<ConnectionNotice />', '<VersionNotice />', '<UpdateNotice />']) {
  const at = app.indexOf(notice);
  assert.ok(at > 0, `App still renders ${notice}`);
  assert.ok(
    at > topBar,
    `${notice} must sit below TopBar, or the window controls overlay lands on top of it`,
  );
}

console.log('UpdateNotice.check.ts ok');

/**
 * One line at the top of the window when there is a newer BetweenUs.
 *
 * The same strip as VersionNotice next to it, and for the same reason: an
 * update is worth saying and is not worth a dialog over a conversation
 * somebody is in the middle of. It can be dismissed, and dismissing it is per
 * version, so the next release says so again.
 *
 * What the buttons do differs by client - a download and a restart on the
 * desktop, a reload in a tab - but the deciding is all in stores/updates.ts;
 * this only draws it.
 */
import { useEffect } from 'react';
import { useUpdateStore } from '../stores/updates';
import { DownloadIcon, XIcon } from './icons';

export function UpdateNotice(): JSX.Element | null {
  const start = useUpdateStore((state) => state.start);
  const showing = useUpdateStore((state) => state.showing());
  const stage = useUpdateStore((state) => state.stage);
  const offer = useUpdateStore((state) => state.offer);
  const progress = useUpdateStore((state) => state.progress);
  const error = useUpdateStore((state) => state.error);
  const reloadReady = useUpdateStore((state) => state.reloadReady);
  const download = useUpdateStore((state) => state.download);
  const install = useUpdateStore((state) => state.install);
  const dismiss = useUpdateStore((state) => state.dismiss);

  // The one place the watch is started, whichever client this is.
  useEffect(() => start(), [start]);

  if (!showing) return null;

  return (
    <div
      role="status"
      className="flex shrink-0 items-center gap-3 bg-accent/15 px-4 py-1.5 text-xs text-slate-100"
    >
      <DownloadIcon className="h-3.5 w-3.5 shrink-0" />

      <span className="min-w-0 flex-1 truncate">
        {reloadReady
          ? 'A newer version of BetweenUs has been deployed. Reload to pick it up.'
          : `BetweenUs ${offer?.version ?? ''} is available.`}
        {error ? <span className="ms-2 text-amber-200">{error}</span> : null}
      </span>

      {stage === 'downloading' ? (
        <span className="shrink-0 tabular-nums text-slate-300">
          {progress < 0 ? 'Downloading…' : `Downloading… ${Math.round(progress * 100)}%`}
        </span>
      ) : null}

      {reloadReady ? (
        <NoticeButton onClick={() => location.reload()}>Reload</NoticeButton>
      ) : stage === 'available' ? (
        <NoticeButton onClick={() => void download()}>Download</NoticeButton>
      ) : stage === 'ready' ? (
        <NoticeButton onClick={() => void install()}>Restart and install</NoticeButton>
      ) : null}

      <button
        type="button"
        aria-label="Dismiss"
        title="Dismiss"
        onClick={dismiss}
        className="cursor-pointer rounded p-1 transition-colors duration-150 hover:bg-white/10"
      >
        <XIcon className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

function NoticeButton({
  onClick,
  children,
}: {
  onClick: () => void;
  children: string;
}): JSX.Element {
  return (
    <button
      type="button"
      onClick={onClick}
      className="shrink-0 cursor-pointer rounded bg-white/10 px-2 py-0.5 font-semibold transition-colors duration-150 hover:bg-white/20"
    >
      {children}
    </button>
  );
}

/**
 * "This client and this deployment do not agree."
 *
 * Until now a client too old for a deployment found out through a request that
 * failed - a 404 on a route that moved, or a body it could not parse - which
 * reads as "the app is broken" and gets reported as one. The contract number is
 * one integer that only moves when something a client can notice changes, so
 * the mismatch can be said in a sentence instead.
 *
 * Deliberately not a wall: the client is very often still usable, and refusing
 * to start over a number would turn a warning into an outage. It can also be
 * dismissed, because somebody who has read it and cannot upgrade today should
 * not have to read it again every launch.
 */
import { useEffect, useState } from 'react';
import { API_CONTRACT_VERSION } from '@betweenus/shared-types';
import { fetchServerContract, serverUrl, versionVerdict } from '../services/endpoint';
import { XIcon } from './icons';

const DISMISSED_KEY = 'betweenus.versionNoticeDismissed';

const WORDING = {
  'client-too-old':
    'This deployment is newer than this client. Some things will not work until the app is updated.',
  'server-too-old':
    'This deployment is older than this client. Some things will not work until the server is updated.',
} as const;

export function VersionNotice(): JSX.Element | null {
  const [verdict, setVerdict] = useState<keyof typeof WORDING | null>(null);

  useEffect(() => {
    let cancelled = false;
    void fetchServerContract().then((contract) => {
      if (cancelled) return;
      const result = versionVerdict(contract, API_CONTRACT_VERSION);
      if (!result) return;
      // Dismissal is per deployment and per pair of numbers: a different server,
      // or either side moving, is news again.
      const stamp = `${serverUrl()}:${contract}:${API_CONTRACT_VERSION}`;
      if (localStorage.getItem(DISMISSED_KEY) === stamp) return;
      setVerdict(result);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  if (!verdict) return null;

  return (
    <div
      role="status"
      className="flex shrink-0 items-center gap-2 bg-amber-500/15 px-4 py-1.5 text-xs text-amber-200"
    >
      <span className="min-w-0 flex-1">{WORDING[verdict]}</span>
      <button
        type="button"
        aria-label="Dismiss"
        title="Dismiss"
        onClick={() => {
          void fetchServerContract().then((contract) => {
            localStorage.setItem(
              DISMISSED_KEY,
              `${serverUrl()}:${contract}:${API_CONTRACT_VERSION}`,
            );
          });
          setVerdict(null);
        }}
        className="cursor-pointer rounded p-1 transition-colors duration-150 hover:bg-white/10"
      >
        <XIcon className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { useAuthStore } from '../../stores/auth';
import { api } from '../../services/api';

/**
 * The way back into an account nobody remembers the password for.
 *
 * It is two screens wearing one, and which one you get is decided by the
 * deployment rather than by anything you type. Naming an account either sends a
 * link, says the deployment has no mail server and to ask an administrator, or -
 * when an administrator has already opened a reset window on that account -
 * takes you straight to the new-password form with the token in hand.
 *
 * The three answers are deliberately not equally informative about the account.
 * "A link is on its way" is what an account that does not exist gets too,
 * because anything else would make this form a way to find out who has an
 * account here.
 */
export function ForgotPassword({ onDone }: { onDone: () => void }): JSX.Element {
  /** `ask` names the account; `reset` chooses the new password. */
  const [step, setStep] = useState<'ask' | 'reset'>('ask');
  const [identifier, setIdentifier] = useState('');
  const [token, setToken] = useState('');
  const [password, setPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [notice, setNotice] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const resetPassword = useAuthStore((state) => state.resetPassword);

  const ask = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const answer = await api.forgotPassword(identifier.trim());
      if (answer.outcome === 'reset' && answer.resetToken) {
        // An administrator authorised this one. Straight to the form, with the
        // token carried across rather than shown - nobody has to copy it.
        setToken(answer.resetToken);
        setStep('reset');
        setNotice('Your administrator has authorised a reset. Choose a new password.');
        return;
      }
      if (answer.outcome === 'unavailable') {
        setError(answer.message ?? 'This server cannot send email. Ask your administrator.');
        return;
      }
      setNotice(
        'If that account exists, a reset link is on its way. Paste the code from the email below.',
      );
      setStep('reset');
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not reach the server.');
    } finally {
      setBusy(false);
    }
  };

  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    if (password !== confirmation) {
      setError('Those two passwords are not the same.');
      return;
    }
    setBusy(true);
    setError(null);
    try {
      await resetPassword(token.trim(), password);
      // A successful reset signs in; the shell takes over from here.
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not reset the password.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="relative flex h-full items-center justify-center bg-ground px-4">
      <div className="drag-region absolute inset-x-0 top-0 h-10" />
      <div className="w-full max-w-md animate-pop rounded-2xl border border-edge bg-surface-900 p-8 shadow-pop">
        <h1 className="mb-1 text-2xl font-semibold text-slate-50">
          {step === 'ask' ? 'Forgot your password?' : 'Choose a new password'}
        </h1>
        <p className="mb-6 text-sm text-slate-400">
          {step === 'ask'
            ? 'Enter your username or email address.'
            : 'This signs every other device out.'}
        </p>

        {step === 'ask' ? (
          <form onSubmit={(event) => void ask(event)} className="space-y-4" noValidate>
            <Field
              id="forgot-identifier"
              label="Email or username"
              value={identifier}
              onChange={setIdentifier}
              placeholder="you@example.com or ayaan"
              autoComplete="username"
            />
            <Submit busy={busy} label="Continue" />
          </form>
        ) : (
          <form onSubmit={(event) => void submit(event)} className="space-y-4" noValidate>
            {/* Hidden when it arrived from the administrator's window: there is
                nothing to paste, and an empty box would look like a step. */}
            {!token && (
              <Field
                id="reset-token"
                label="Code from the email"
                value={token}
                onChange={setToken}
                placeholder="Paste it here"
              />
            )}
            <Field
              id="reset-password"
              label="New password"
              type="password"
              value={password}
              onChange={setPassword}
              placeholder="At least 8 characters"
              autoComplete="new-password"
            />
            <Field
              id="reset-confirm"
              label="Repeat it"
              type="password"
              value={confirmation}
              onChange={setConfirmation}
              autoComplete="new-password"
            />
            <Submit busy={busy} label="Set password" />
          </form>
        )}

        {notice && (
          <p className="mt-4 rounded-md bg-accent/10 px-3 py-2 text-sm text-slate-300">{notice}</p>
        )}
        {error && (
          <p role="alert" className="mt-4 rounded-md bg-danger/10 px-3 py-2 text-sm text-danger">
            {error}
          </p>
        )}

        <button
          type="button"
          onClick={onDone}
          className="mt-6 w-full cursor-pointer text-sm text-slate-400 transition-colors duration-200 hover:text-slate-200"
        >
          Back to sign in
        </button>
      </div>
    </div>
  );
}

function Field({
  id,
  label,
  value,
  onChange,
  placeholder,
  type = 'text',
  autoComplete,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
  autoComplete?: string;
}): JSX.Element {
  return (
    <div>
      <label
        htmlFor={id}
        className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400"
      >
        {label}
      </label>
      <input
        id={id}
        type={type}
        required
        value={value}
        autoComplete={autoComplete}
        placeholder={placeholder}
        onChange={(event) => onChange(event.target.value)}
        className="w-full rounded-md border border-edge bg-surface-950 px-3 py-2 text-slate-100 placeholder-slate-500 transition-colors duration-200 focus:border-accent"
      />
    </div>
  );
}

function Submit({ busy, label }: { busy: boolean; label: string }): JSX.Element {
  return (
    <button
      type="submit"
      disabled={busy}
      className="w-full cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-60"
    >
      {busy ? 'Please wait…' : label}
    </button>
  );
}

import { useEffect, useState, type FormEvent } from 'react';
import type { OAuthProviderSummary } from '@betweenus/shared-types';
import { rememberedEmail, useAuthStore } from '../../stores/auth';
import { api } from '../../services/api';
import { GlobeIcon, BetweenUsLogoIcon } from '../../components/icons';
import { ServerPicker, serverLabel } from './ServerPicker';
import { ForgotPassword } from './ForgotPassword';

export function LoginScreen(): JSX.Element {
  const [mode, setMode] = useState<'login' | 'register' | 'forgot'>('login');
  const [pickingServer, setPickingServer] = useState(false);
  // Signing in again on this machine should not mean typing the address again.
  const [email, setEmail] = useState(rememberedEmail);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  /** Empty until the server answers; nothing is offered that is not configured. */
  const [providers, setProviders] = useState<OAuthProviderSummary[]>([]);

  const { login, loginWithProvider, register, status, error, clearError } = useAuthStore();
  const busy = status === 'loading';

  useEffect(() => {
    void api
      .oauthProviders()
      .then(setProviders)
      // A server that cannot answer just means no provider buttons.
      .catch(() => setProviders([]));
  }, []);

  /**
   * Whether the typed username is free, as the server last answered.
   *
   * Asked while somebody types rather than when they press the button, which
   * the server can afford: a Bloom filter answers the common case - a name
   * nobody has - without touching the database. Null means nothing has been
   * asked yet, which is also what a short or half-typed name gets.
   */
  const [nameCheck, setNameCheck] = useState<{ available: boolean; reason?: string } | null>(null);

  useEffect(() => {
    if (mode !== 'register' || username.trim().length < 3) {
      setNameCheck(null);
      return;
    }
    // Debounced, so a name is checked once rather than once per keystroke.
    const timer = setTimeout(() => {
      void api
        .usernameAvailable(username.trim())
        .then((answer) => setNameCheck({ available: answer.available, reason: answer.reason }))
        // A server that cannot answer means no hint, never a false refusal:
        // the registration itself is still gated by the unique index.
        .catch(() => setNameCheck(null));
    }, 250);
    return () => clearTimeout(timer);
  }, [username, mode]);

  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    if (mode === 'login') await login(email, password);
    else await register(email, username, password);
  };

  if (mode === 'forgot') {
    return (
      <ForgotPassword
        onDone={() => {
          setMode('login');
          clearError();
        }}
      />
    );
  }

  return (
    <div className="relative flex h-full items-center justify-center bg-ground px-4">
      {/* The window has no native title bar, and this screen has no top bar of
          its own, so without this strip there is nowhere to grab the window. */}
      <div className="drag-region absolute inset-x-0 top-0 h-10" />
      <div className="w-full max-w-md animate-pop rounded-2xl border border-edge bg-surface-900 p-8 shadow-pop">
        <div className="mb-6 text-center">
          <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-xl border border-edge bg-accent/15 p-2.5">
            <BetweenUsLogoIcon className="h-full w-full text-accent" />
          </div>
          <h1 className="text-2xl font-semibold text-slate-50">
            {mode === 'login' ? 'Welcome back' : 'Create your account'}
          </h1>
          <p className="mt-1 text-sm text-slate-400">
            {mode === 'login'
              ? 'Sign in to continue to BetweenUs'
              : 'Pick a username your teammates will see'}
          </p>
        </div>

        <form onSubmit={submit} className="space-y-4" noValidate>
          <div>
            <label htmlFor="email" className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400">
              {mode === 'login' ? 'Email or username' : 'Email'}
            </label>
            {/*
              Signing in takes either, and the server has accepted either all
              along - it is the same field, and an address contains an @ where a
              username may not. What did not take either was this input: `email`
              asks the browser for an address, offers only addresses to autofill,
              and puts an address keyboard on a phone. Registering still asks
              for an address, because that one really is one.
            */}
            <input
              id="email"
              type={mode === 'login' ? 'text' : 'email'}
              required
              autoComplete={mode === 'login' ? 'username' : 'email'}
              value={email}
              onChange={(event) => {
                setEmail(event.target.value);
                clearError();
              }}
              className="w-full rounded-md border border-edge bg-surface-950 px-3 py-2 text-slate-100 placeholder-slate-500 transition-colors duration-200 focus:border-accent"
              placeholder={mode === 'login' ? 'you@example.com or ayaan' : 'you@example.com'}
            />
          </div>

          {mode === 'register' && (
            <div>
              <label
                htmlFor="username"
                className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400"
              >
                Username
              </label>
              <input
                id="username"
                type="text"
                required
                minLength={3}
                maxLength={32}
                autoComplete="username"
                value={username}
                onChange={(event) => {
                  setUsername(event.target.value);
                  clearError();
                }}
                className="w-full rounded-md border border-edge bg-surface-950 px-3 py-2 text-slate-100 placeholder-slate-500 transition-colors duration-200 focus:border-accent"
                placeholder="ayaan"
              />
              {nameCheck && (
                <p
                  className={`mt-1 text-xs ${
                    nameCheck.available ? 'text-emerald-400' : 'text-danger'
                  }`}
                >
                  {nameCheck.available
                    ? `${username.trim().toLowerCase()} is available`
                    : nameCheck.reason === 'invalid'
                      ? 'Letters, numbers, dot, dash and underscore only'
                      : 'That username is already taken'}
                </p>
              )}
            </div>
          )}

          <div>
            <label
              htmlFor="password"
              className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400"
            >
              Password
            </label>
            <input
              id="password"
              type="password"
              required
              minLength={8}
              autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
              value={password}
              onChange={(event) => {
                setPassword(event.target.value);
                clearError();
              }}
              className="w-full rounded-md border border-edge bg-surface-950 px-3 py-2 text-slate-100 placeholder-slate-500 transition-colors duration-200 focus:border-accent"
              placeholder="At least 8 characters"
            />
            {mode === 'register' ? (
              <p className="mt-1 text-xs text-slate-500">Must contain a letter and a number.</p>
            ) : (
              <button
                type="button"
                onClick={() => {
                  setMode('forgot');
                  clearError();
                }}
                className="mt-1.5 cursor-pointer text-xs text-slate-500 transition-colors duration-200 hover:text-slate-300"
              >
                Forgot your password?
              </button>
            )}
          </div>

          {error && (
            <p role="alert" className="rounded-md bg-danger/10 px-3 py-2 text-sm text-danger">
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={busy}
            className="w-full cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-60"
          >
            {busy ? 'Please wait…' : mode === 'login' ? 'Sign in' : 'Create account'}
          </button>
        </form>

        {providers.length > 0 && (
          <div className="mt-6">
            <div className="mb-3 flex items-center gap-3">
              <span className="h-px flex-1 bg-white/10" />
              <span className="text-xs uppercase tracking-wide text-slate-500">or continue with</span>
              <span className="h-px flex-1 bg-white/10" />
            </div>

            <div className="space-y-2">
              {providers.map((provider) => (
                <button
                  key={provider.provider}
                  type="button"
                  disabled={busy}
                  onClick={() => void loginWithProvider(provider.provider)}
                  className="w-full cursor-pointer rounded-md border border-edge bg-surface-950 px-4 py-2.5 font-medium text-slate-100 transition-colors duration-200 hover:border-accent disabled:cursor-not-allowed disabled:opacity-60"
                >
                  Continue with {provider.label}
                </button>
              ))}
            </div>

            <p className="mt-2 text-center text-xs text-slate-500">
              Opens your browser; come back here when it is done.
            </p>
          </div>
        )}

        <button
          type="button"
          onClick={() => {
            setMode(mode === 'login' ? 'register' : 'login');
            clearError();
          }}
          className="mt-4 w-full cursor-pointer text-sm text-slate-400 transition-colors duration-200 hover:text-slate-200"
        >
          {mode === 'login' ? 'Need an account? Register' : 'Already registered? Sign in'}
        </button>

        {/* Which deployment this is. BetweenUs is meant to be self-hosted, so the
            address is worth showing even when nobody wants to change it. */}
        <div className="mt-6 border-t border-edge pt-4">
          <button
            type="button"
            onClick={() => setPickingServer(true)}
            className="mx-auto flex cursor-pointer items-center gap-2 text-sm text-slate-400 transition-colors duration-200 hover:text-slate-200"
          >
            <GlobeIcon className="h-4 w-4" />
            Connect to a self-hosted instance
          </button>
          <p className="mt-1.5 text-center text-xs text-slate-500">
            Signing in to <span className="text-slate-400">{serverLabel()}</span>
          </p>
        </div>
      </div>

      {pickingServer && <ServerPicker onClose={() => setPickingServer(false)} />}
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import {
  defaultServerUrl,
  forgetServer,
  isDefaultServer,
  normalizeServerUrl,
  probeServer,
  recentServers,
  serverUrl,
  setServerUrl,
} from '../../services/endpoint';
import { useAuthStore } from '../../stores/auth';
import { GlobeIcon, XIcon } from '../../components/icons';

/**
 * Points this window at a different deployment.
 *
 * BetweenUs is meant to be self-hosted, so the address the build shipped with is a
 * default and not a decision. The address is checked before it is stored - a
 * typo should be a line under the field, not an app that no longer starts.
 *
 * Switching signs the window out: tokens, device keys and every id in them
 * belong to the deployment that issued them, and none of it means anything on
 * another one. The window then reloads, which is the honest way to get every
 * store, socket and cache to let go of the old server at once.
 */
export function ServerPicker({ onClose }: { onClose: () => void }): JSX.Element {
  const [address, setAddress] = useState(serverUrl);
  const [note, setNote] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  // Everywhere this client has been, minus wherever it is now - offering to
  // connect to the address you are already on is a button that does nothing.
  const [recent, setRecent] = useState(() =>
    recentServers().filter((url) => url !== serverUrl()),
  );

  const signedIn = useAuthStore((state) => state.status) === 'authenticated';

  const connect = async (raw: string): Promise<void> => {
    setBusy(true);
    setNote(null);
    try {
      // What the probe answers on, not what was typed: a redirect to another
      // origin would strip the Authorization header off every later request.
      const base = await probeServer(normalizeServerUrl(raw));

      // Ends the session on the server we are leaving, while we can still
      // reach it; a no-op when nobody is signed in.
      await useAuthStore.getState().logout();
      setServerUrl(base === defaultServerUrl() ? null : base);
      window.location.reload();
    } catch (error) {
      setNote(error instanceof Error ? error.message : 'That address did not work');
      setBusy(false);
    }
  };

  const submit = (event: FormEvent): void => {
    event.preventDefault();
    void connect(address);
  };

  return (
    <div className="fixed inset-0 z-50 flex animate-fade items-center justify-center bg-black/60 px-4">
      <div className="w-full max-w-md animate-pop rounded-xl border border-edge bg-surface-900 p-6 shadow-pop">
        <div className="mb-4 flex items-start gap-3">
          <GlobeIcon className="mt-0.5 h-5 w-5 shrink-0 text-accent" />
          <div className="min-w-0 flex-1">
            <h2 className="text-lg font-semibold text-slate-50">Connect to a server</h2>
            <p className="mt-1 text-sm text-slate-400">
              The address of the BetweenUs deployment this app talks to. Everything else - chat,
              voice, files - is behind it.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="cursor-pointer rounded-md p-1 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
          >
            <XIcon className="h-4 w-4" />
          </button>
        </div>

        <form onSubmit={submit} className="space-y-3" noValidate>
          <label
            htmlFor="server-url"
            className="block text-xs font-semibold uppercase tracking-wide text-slate-400"
          >
            Server address
          </label>
          <input
            id="server-url"
            type="text"
            autoFocus
            spellCheck={false}
            autoComplete="url"
            value={address}
            onChange={(event) => {
              setAddress(event.target.value);
              setNote(null);
            }}
            className="w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-slate-100 placeholder-slate-500 transition-colors duration-200 focus:border-accent"
            placeholder="betweenus.example.com"
          />
          <p className="text-xs text-slate-500">
            No http:// means https://. This one is currently{' '}
            <span className="text-slate-300">{serverUrl()}</span>
            {isDefaultServer() && ', the default this app was built with'}.
          </p>

          {recent.length > 0 && (
            <div>
              <p className="text-xs font-semibold uppercase tracking-wide text-slate-400">
                Recently connected
              </p>
              <ul className="mt-2 space-y-1">
                {recent.map((url) => (
                  <li key={url} className="flex items-center gap-1">
                    <button
                      type="button"
                      disabled={busy}
                      onClick={() => {
                        // Filled in rather than connected to: one click away
                        // from signing out of the server you are on is one
                        // click too few.
                        setAddress(url);
                        setNote(null);
                      }}
                      className="min-w-0 flex-1 cursor-pointer truncate rounded-md bg-surface-800 px-3 py-1.5 text-start text-sm text-slate-300 transition-colors duration-150 hover:bg-white/[0.06] hover:text-slate-100 disabled:opacity-60"
                    >
                      {url}
                    </button>
                    <button
                      type="button"
                      disabled={busy}
                      aria-label={`Forget ${url}`}
                      title="Forget this address"
                      onClick={() => {
                        forgetServer(url);
                        setRecent((list) => list.filter((item) => item !== url));
                      }}
                      className="cursor-pointer rounded-md p-1.5 text-slate-500 transition-colors duration-150 hover:text-danger disabled:opacity-60"
                    >
                      <XIcon className="h-3.5 w-3.5" />
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {signedIn && (
            <p className="rounded-md bg-amber-500/10 px-3 py-2 text-sm text-amber-200">
              Connecting somewhere else signs you out of this server.
            </p>
          )}

          {note && (
            <p role="alert" className="rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
              {note}
            </p>
          )}

          <button
            type="submit"
            disabled={busy}
            className="w-full cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-60"
          >
            {busy ? 'Checking…' : 'Connect'}
          </button>
        </form>

        {!isDefaultServer() && (
          <button
            type="button"
            disabled={busy}
            onClick={() => void connect(defaultServerUrl())}
            className="mt-3 w-full cursor-pointer text-sm text-slate-400 transition-colors duration-200 hover:text-slate-200 disabled:opacity-60"
          >
            Back to {defaultServerUrl()}
          </button>
        )}
      </div>
    </div>
  );
}

/** The host this window is talking to, for a line under a sign-in form. */
export function serverLabel(): string {
  return serverUrl().replace(/^https?:\/\//i, '');
}

import { useState } from 'react';
import type { Channel, ChannelType } from '@betweenus/shared-types';
import { PERMISSIONS } from '@betweenus/permissions';
import { useChatStore } from '../../stores/chat';
import { usePresenceStore } from '../../stores/presence';
import { useVoiceStore } from '../../stores/voice';
import { VoicePanel } from '../voice/VoicePanel';
import { UserPanel } from '../settings/UserPanel';
import { CreateChannelDialog } from './CreateChannelDialog';
import {
  ChevronDownIcon,
  HashIcon,
  LockIcon,
  PlusIcon,
  SettingsIcon,
  SpeakerIcon,
  XIcon,
} from '../../components/icons';
import { Skeleton } from '../../components/Skeleton';
