      }`}
    >
      {level === 'none' ? <BellOffIcon className="h-5 w-5" /> : <BellIcon className="h-5 w-5" />}
    </button>
  );
}

/**
 * The profile card over a message's author, in a server channel.
 *
 * A message carries only who wrote it - a name, a picture and an id - and the
 * card also wants the about line, which is on the member row the right-hand
 * column is already holding. Looked up rather than sent with every message:
 * the same person writes fifty of them, and fifty copies of one sentence in a
 * channel's history is fifty copies to keep in step when they edit it.
 *
 * An author who is no longer a member - somebody who left, or wrote in a
 * conversation this window has no member list for - simply gets a card with no
 * about line rather than no card, because the half of it that comes from
 * presence is the half worth resting on a name for.
 */
/** How long a gap may be before a run of messages is two runs. */
export const GROUP_WITHIN_MS = 5 * 60 * 1000;

/**
 * Whether `message` continues the run `previous` started - which is what
 * decides whether it draws a name and a face of its own.
 *
 * Pure and exported so `ChatView.check.ts` can pin it. The case that made that
 * worth doing: an arrival line ("mobile is here.") sits in the same list as the
 * bubbles and carries the arriving person as its author, so the message they
 * sent immediately afterwards matched on author id, grouped with the arrival,
 * and drew neither a name nor a picture. On screen that is a message from
 * nobody, directly under a line naming them.
 */
export function groupsWith(
  previous: DecryptedMessage | undefined,
  message: DecryptedMessage,
): boolean {
  if (!previous) return false;
  // Only a bubble can be grouped with. An arrival is the conversation talking
  // rather than a person, and it is drawn as a line rather than a bubble.
  if (!hasBody(previous.kind) || !hasBody(message.kind)) return false;
  if (previous.author.id !== message.author.id) return false;
  // A webhook posts as the account that opened it, so two different robots -
  // and a robot and the person who set it up - all share an author id. Grouping
  // on that alone stacked a build notification under somebody's sentence and
  // drew one name over both.
  if ((previous.webhook?.id ?? null) !== (message.webhook?.id ?? null)) return false;
  // A day boundary always breaks the run: a divider sits between the two
  // bubbles, and a run reading across it visibly is not one.
  if (!sameDay(previous.createdAt, message.createdAt)) return false;
  return (
    new Date(message.createdAt).getTime() - new Date(previous.createdAt).getTime() <
    GROUP_WITHIN_MS
  );
}

function AuthorHover({
  author,
  children,
}: {
  author: DecryptedMessage['author'];
  children: React.ReactNode;
}): JSX.Element {
  const member = useChatStore((state) => state.members.find((row) => row.userId === author.id));

  return (
    <ProfileHover
      person={{
        userId: author.id,
        displayName: author.displayName,
        username: member?.username ?? author.username,
        avatarUrl: author.avatarUrl,
        // Only the member row carries a cover; a message author does not. An
        // author who has left the server therefore gets the accent band, which
        // is what the card drew for everybody before covers existed.
        coverUrl: member?.coverUrl ?? null,
        about: member?.about ?? '',
        colour: member?.colour ?? null,
      }}
    >
      {children}
    </ProfileHover>
  );
}

/**
 * "online", or when this person was last here, under their name in the header.
 *
 * Its own component so that a status change re-renders one line rather than the
 * whole conversation: `ChatView` holds the message list, and subscribing it to
 * a presence map that ticks every time anybody anywhere goes idle would repaint
 * every message on screen to change four words.
 *
 * It re-renders on its own clock as well as on events, because "last seen today
 * at 7:07 PM" is fixed but "last seen yesterday" is not - a conversation left
 * open across midnight would otherwise go on calling it today until something
 * else happened to redraw.
 */
function PeerPresence({ userId }: { userId: string }): JSX.Element | null {
  const statusOf = useStatusOf();
  const lastSeenOf = useLastSeenOf();
  const [, tick] = useState(0);

  useEffect(() => {
    const timer = window.setInterval(() => tick((count) => count + 1), 60_000);
    return () => window.clearInterval(timer);
  }, []);

  const line = presenceLine(statusOf(userId), lastSeenOf(userId));
  if (!line) return null;

  return <p className="truncate text-xs text-slate-400">{line}</p>;
}

/**
 * "VILEN is here."
 *
 * Somebody joined the server. It is the conversation talking rather than a
 * person, so it is a line rather than a bubble: an arrow, a name, a few words
 * and the time, the way Discord draws it - which reads as an event in the
 * history instead of as a message somebody could reply to.
 *
 * The sentence comes from `arrival.ts`, which explains why it is picked rather
 * than stored and why the Android client has to pick the same one.
 */
function ArrivalRow({ message }: { message: DecryptedMessage }): JSX.Element {
  const line = arrivalLine(message.id);
  const name = message.author.displayName || message.author.username;

  return (
    <li
      id={`message-${message.id}`}
      className="mt-3 flex items-baseline gap-2 px-3 text-sm text-slate-400"
    >
      <span aria-hidden="true" className="text-status-online">
        &rarr;
      </span>
      <span className="min-w-0">
        <AuthorHover author={message.author}>
          <span className="cursor-pointer font-semibold text-slate-200 hover:underline">{name}</span>
        </AuthorHover>{' '}
        {line}
      </span>
      <time dateTime={message.createdAt} className="shrink-0 text-xs text-slate-500">
        {clockTime(message.createdAt)}
      </time>
    </li>
  );
}

