import { useEffect, useMemo, useRef, useState } from 'react';
import { EMOJI_GROUPS } from './emoji';

/**
 * A floating emoji grid. Used twice - by the composer to type one, and by a
 * message to react with one - so it knows nothing about either: it reports the
 * emoji that was chosen and closes.
 *
 * `anchor` is a screen position, because the picker is rendered `fixed` above
 * everything rather than inside a scrolling list that would clip it.
 */
export function EmojiPicker({
  anchor,
  onPick,
  onClose,
}: {
  anchor: { x: number; y: number };
  onPick: (emoji: string) => void;
  onClose: () => void;
}): JSX.Element {
  const [query, setQuery] = useState('');
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const away = (event: MouseEvent): void => {
      if (!box.current?.contains(event.target as Node)) onClose();
    };
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    // Deferred: the click that opened this must not immediately close it.
    const timer = window.setTimeout(() => document.addEventListener('mousedown', away), 0);
    document.addEventListener('keydown', escape);
    return () => {
      window.clearTimeout(timer);
      document.removeEventListener('mousedown', away);
      document.removeEventListener('keydown', escape);
    };
  }, [onClose]);

  // Search is by group name, because this set carries no shortcodes; it is
  // enough to get from "food" to the food row without scrolling.
  const groups = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return EMOJI_GROUPS;
    return EMOJI_GROUPS.filter((group) => group.name.toLowerCase().includes(term));
  }, [query]);

  const width = 320;
  const height = 360;
  const left = Math.min(Math.max(8, anchor.x - width / 2), window.innerWidth - width - 8);
  const top = Math.min(Math.max(8, anchor.y - height - 8), window.innerHeight - height - 8);

  return (
    <div
      ref={box}
      role="dialog"
      aria-label="Pick an emoji"
      style={{ left, top, width, height }}
      className="fixed z-50 flex animate-pop flex-col overflow-hidden rounded-xl border border-edge bg-surface-900 shadow-pop"
    >
      <div className="shrink-0 p-2">
        <input
          autoFocus
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Search categories"
          aria-label="Search emoji categories"
          className="w-full rounded bg-surface-950 px-2.5 py-1.5 text-sm text-slate-100 placeholder-slate-500 focus:outline-none"
        />
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto px-2 pb-2">
        {groups.map((group) => (
          <section key={group.name}>
            <h3 className="sticky top-0 bg-surface-800 py-1 text-xs font-bold uppercase tracking-wide text-slate-400">
              {group.name}
            </h3>
            <div className="grid grid-cols-8 gap-0.5">
              {group.emoji.map((emoji) => (
                <button
                  key={emoji}
                  type="button"
                  onClick={() => {
                    onPick(emoji);
                    onClose();
                  }}
                  aria-label={emoji}
                  className="cursor-pointer rounded p-1 text-xl leading-none transition-colors duration-150 hover:bg-white/[0.06]"
                >
                  {emoji}
                </button>
              ))}
            </div>
          </section>
        ))}
        {groups.length === 0 && <p className="p-3 text-sm text-slate-400">No category by that name.</p>}
      </div>
    </div>
  );
}

/**
 * The `:` menu: type two letters and pick an emoji without leaving the keyboard.
 *
 * The picker button already exists and is the wrong tool mid-sentence - it
 * takes a hand off the keyboard, covers the message, and has to be closed
 * again. Teams, Slack and Discord all answer this the same way and people
 * arrive expecting it: `:` then a name.
 *
 * It renders above the composer rather than at the caret. A menu that follows
 * the caret needs the caret's pixel position, which a textarea does not offer
 * without measuring the text in a mirror element - a well-known trick and a
 * well-known source of off-by-a-line bugs at every font size and wrap. Above
 * the box is where the composer's other popovers already are.
 */
import { useEffect, useState } from 'react';
import type { ServerEmoji } from '@betweenus/shared-types';
import { EMOJI_SUGGESTION_LIMIT, searchEmoji, type NamedEmoji } from './emoji-names';
import { absoluteUrl } from '../../services/endpoint';

/**
 * One row of the menu: a Unicode emoji from the table, or one of this server's
 * own. They are the same choice to whoever is typing, so they are the same
 * list - the server's come first, because a server that has invented `:shipit:`
 * has invented it for a reason.
 */
type Suggestion =
  | { kind: 'unicode'; entry: NamedEmoji }
  | { kind: 'custom'; emoji: ServerEmoji };

function suggestionsFor(term: string, custom: readonly ServerEmoji[]): Suggestion[] {
  const needle = term.trim().toLowerCase().replace(/^:+/, '');

  const mine = custom
    .filter((emoji) => emoji.name.includes(needle))
    // Exact first, then a prefix, then anything containing it - the same
    // ranking the Unicode table uses, for the same reason.
    .sort((left, right) => rank(left.name, needle) - rank(right.name, needle))
    .map((emoji): Suggestion => ({ kind: 'custom', emoji }));

  const rest = searchEmoji(term, EMOJI_SUGGESTION_LIMIT).map(
    (entry): Suggestion => ({ kind: 'unicode', entry }),
  );

  return [...mine, ...rest].slice(0, EMOJI_SUGGESTION_LIMIT);
}

function rank(name: string, needle: string): number {
  if (name === needle) return 0;
  if (name.startsWith(needle)) return 1;
  return 2;
}

export function EmojiSuggest({
  term,
  custom,
  onPick,
  onClose,
}: {
  /** What has been typed after the colon. */
  term: string;
  /** This server's own emoji, offered above the Unicode ones. */
  custom: readonly ServerEmoji[];
  /**
   * What to put in the box. A Unicode emoji is the character itself; a custom
   * one is its `:name:`, because the shortcode is what the message carries and
   * the picture is resolved from the manifest at render time.
   */
  onPick: (text: string) => void;
  onClose: () => void;
}): JSX.Element | null {
  const [matches, setMatches] = useState<Suggestion[]>([]);
  const [active, setActive] = useState(0);

  useEffect(() => {
    const found = suggestionsFor(term, custom);
    setMatches(found);
    // Back to the top whenever the term changes: keeping the index would leave
    // the highlight on whatever happens to be in that row now, which is how a
    // menu sends the wrong emoji.
    setActive(0);
  }, [term, custom]);

  /**
   * The keys are caught here rather than in the composer.
   *
   * Capture phase and on the window, because the textarea has its own handler
   * for Enter - it sends the message - and it must not while this is open.
   * That is the whole reason this listens instead of being handed events: the
   * two handlers disagree about what Enter means, and the one that is on screen
   * wins.
   */
  useEffect(() => {
    if (matches.length === 0) return;

    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'ArrowDown') {
        event.preventDefault();
        setActive((at) => (at + 1) % matches.length);
      } else if (event.key === 'ArrowUp') {
        event.preventDefault();
        setActive((at) => (at - 1 + matches.length) % matches.length);
      } else if (event.key === 'Enter' || event.key === 'Tab') {
        event.preventDefault();
        event.stopPropagation();
        const chosen = matches[active];
        if (chosen) onPick(textFor(chosen));
      } else if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        onClose();
      }
    };

    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, [matches, active, onPick, onClose]);

  if (matches.length === 0) return null;

  return (
    <div
      role="listbox"
      aria-label="Emoji suggestions"
      className="absolute bottom-full inset-x-3.5 z-30 mb-2 overflow-hidden rounded-xl border border-edge bg-surface-900 py-1 shadow-pop"
    >
      <p className="px-3 pb-1 text-[11px] uppercase tracking-wide text-slate-500">
        Emoji matching :{term}
      </p>
      <ul>
        {matches.map((match, index) => (
          <li key={match.kind === 'custom' ? match.emoji.id : match.entry.emoji}>
            <button
              type="button"
              role="option"
              aria-selected={index === active}
              // The pointer must not take focus off the textarea: losing the
              // caret mid-insert is what turns a click into a message with the
              // half-typed shortcode still in it.
              onMouseDown={(event) => event.preventDefault()}
              onMouseEnter={() => setActive(index)}
              onClick={() => onPick(textFor(match))}
              className={`flex w-full items-center gap-3 px-3 py-1.5 text-start transition-colors duration-100 ${
                index === active ? 'bg-white/[0.07]' : ''
              }`}
            >
              {match.kind === 'custom' ? (
                <>
                  <img
                    src={absoluteUrl(match.emoji.url)}
                    alt=""
                    className="h-[22px] w-[22px] object-contain"
                  />
                  <span className="text-sm text-slate-200">:{match.emoji.name}:</span>
                  <span className="ms-auto text-xs text-slate-500">
                    {match.emoji.animated ? 'this server · animated' : 'this server'}
                  </span>
                </>
              ) : (
                <>
                  <span className="text-lg leading-none">{match.entry.emoji}</span>
                  <span className="text-sm text-slate-200">:{match.entry.names[0]}:</span>
                  {match.entry.names.length > 1 && (
                    <span className="ms-auto truncate text-xs text-slate-500">
                      {match.entry.names.slice(1).map((alias) => `:${alias}:`).join(' ')}
                    </span>
                  )}
                </>
              )}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

/**
 * What choosing one puts in the box.
 *
 * A Unicode emoji is the character. A custom one stays `:name:` - the message
 * carries the shortcode and a manifest of pictures, so what goes in the
 * textarea is the thing that will still make sense if the emoji is deleted.
 */
function textFor(suggestion: Suggestion): string {
  return suggestion.kind === 'custom' ? `:${suggestion.emoji.name}:` : suggestion.entry.emoji;
}

/** Run with `tsx src/features/chat/follow.check.ts`. The message list's latch. */
import assert from 'node:assert/strict';
import { FOLLOW_SLACK_PX, nextFollow, type ScrollBox } from './follow';

/** A viewport 600 tall holding `content`, scrolled to `top`. */
const box = (content: number, top: number): ScrollBox => ({
  scrollHeight: content,
  scrollTop: top,
  clientHeight: 600,
});

// --- at the bottom -----------------------------------------------------------

// Pinned to the bottom, however it got there.
assert.equal(nextFollow(true, 1400, box(2000, 1400)), true);
assert.equal(nextFollow(false, 1400, box(2000, 1400)), true, 'coming back re-pins');
// Within the slack still counts: a smooth scroll that is a pixel from settling
// must not read as somebody walking away.
assert.equal(nextFollow(true, 1400, box(2000, 1400 - (FOLLOW_SLACK_PX - 1))), true);

// --- the reader scrolls away -------------------------------------------------

// Up and out of the slack: the one thing content cannot do to itself.
assert.equal(nextFollow(true, 1400, box(2000, 900)), false);
// A nudge up that stays within the slack is still reading the newest message.
assert.equal(nextFollow(true, 1400, box(2000, 1390)), true);
// Scrolling down, but not all the way back, does not re-pin on its own.
assert.equal(nextFollow(false, 900, box(2000, 1000)), false);

// --- the content moves, not the reader ---------------------------------------

// A picture decrypted and the row grew by 300: same scroll position, bottom
// suddenly 300 away. This is the case the old rule got wrong, and the reason
// a channel of photos stopped following the conversation.
assert.equal(nextFollow(true, 1400, box(2300, 1400)), true, 'growth must not un-pin');
// Several of them, one after another, as a channel of photos decrypts.
let following = true;
for (const grown of [2300, 2600, 2900, 3200]) {
  following = nextFollow(following, 1400, box(grown, 1400));
}
assert.equal(following, true, 'a channel of photos must still be following');

// The viewport shrank instead - a typing indicator appeared, or the composer
// grew a preview of the photo about to be sent. Nothing scrolled at all.
assert.equal(
  nextFollow(true, 1400, { scrollHeight: 2000, scrollTop: 1400, clientHeight: 440 }),
  true,
  'a shorter viewport must not un-pin',
);

// And a reader who had already walked away is not dragged back by any of it.
assert.equal(nextFollow(false, 900, box(2300, 900)), false);

// --- the list is shorter than the viewport -----------------------------------

// Nothing to scroll: an empty or nearly empty channel is at the bottom by
// definition, and the first message must land under the follow.
assert.equal(nextFollow(true, 0, box(300, 0)), true);
assert.equal(nextFollow(false, 0, box(300, 0)), true);

