/**
 * Whether the message list is still following the newest message.
 *
 * This used to be one line in the scroll handler: "following" meant the bottom
 * of the content was within a slack of the bottom of the viewport, recomputed
 * on every scroll event. That reads as obviously right and is the bug, because
 * it answers a different question from the one being asked. The question is
 * "has the reader gone somewhere else"; that rule answers "is the bottom of the
 * list near the bottom of the screen", and those two come apart the moment
 * anything moves that the reader did not move.
 *
 * Attachments are exactly that. A picture is ciphertext until it has been
 * fetched and decrypted, so a row is laid out at one height and becomes three
 * hundred pixels taller a moment later - and the bottom of the list is suddenly
 * far away without a single scroll having happened. Same for the viewport
 * itself: a typing indicator appearing, or the composer growing a preview of
 * the photo about to be sent, makes the viewport shorter under a scroll
 * position that has not changed.
 *
 * So following is a latch, and only the reader may release it: it goes off when
 * they scroll up and away, and back on when they come back to the bottom. What
 * the content does underneath them never touches it.
 */

/** The three numbers the rule needs. `HTMLElement` satisfies this. */
export interface ScrollBox {
  scrollTop: number;
  scrollHeight: number;
  clientHeight: number;
}

/** How far off the bottom still counts as reading the newest message. */
export const FOLLOW_SLACK_PX = 120;

/**
 * The next state of the latch.
 *
 * `previousTop` is the scroll position at the previous event: scrolling *up* is
 * the one thing content growing underneath cannot do, which is what makes it a
 * usable signal for "the reader went somewhere else".
 */
export function nextFollow(following: boolean, previousTop: number, box: ScrollBox): boolean {
  // At the bottom, however it got there - a fling, a jump, or the list putting
  // itself back after a row grew.
  if (box.scrollHeight - box.scrollTop - box.clientHeight < FOLLOW_SLACK_PX) return true;
  // Away from the bottom because the reader scrolled up.
  if (box.scrollTop < previousTop) return false;
  // Away from the bottom because something grew. Not the reader's doing, so not
  // the reader's decision.
  return following;
}

/**
 * Where a message is being forwarded to.
 *
 * Everywhere it could go, minus the one place it already is. This started as
 * the current server's other text channels and that was too narrow to be
 * usable: a server with one channel in it - which is every server on the day
 * it is made - offered nothing at all, and the dialog's whole answer was that
 * there was no answer. A forward is not a per-server action.
 *
 * So it is every direct message and every server's text channels, searchable,
 * in one column - the same list the phone's forward sheet draws, because two
 * pickers that answer "which conversation" differently is one of them being
 * wrong.
 *
 * The store only holds the *active* server's channels, since `selectServer`
 * clears them on every switch. The other servers are fetched here, once, while
 * the dialog is open, and thrown away with it - a list this is read from for
 * as long as it takes to click a row does not belong in the store, where it
 * would go stale for the sidebar to trip over.
 *
 * Nothing is sent from here. Picking hands the channel back, and the send
 * happens on the chat view where a failure has somewhere to be reported.
 */
import { useEffect, useMemo, useState } from 'react';
import type { Channel } from '@betweenus/shared-types';
import { useChatStore } from '../../stores/chat';
import { useFriendsStore } from '../../stores/friends';
import { useStatusOf } from '../../stores/presence';
import { api } from '../../services/api';
import { Avatar } from '../../components/Avatar';
import { ServerIcon } from '../../components/ServerIcon';
import { HashIcon, SearchIcon } from '../../components/icons';
import { useFocusTrap } from '../../services/focus-trap';

/**
 * How many conversations the list shows before it stops.
 *
 * Somebody with sixty of them would otherwise get sixty rows above the first
 * server heading, and the channels - the other half of what this picker is
 * for - would be off the bottom of a dialog that is already as tall as it is
 * allowed to get. Six is about a screen's worth of "the people I actually talk
 * to"; the rest are one click or one search away, and searching lifts the cap
 * entirely because a search is somebody naming who they want.
 */
const DIRECTS_SHOWN = 6;

export function ForwardDialog({
  fromChannelId,
  onPick,
  onClose,
}: {
  fromChannelId: string;
  onPick: (channelId: string, name: string) => void;
  onClose: () => void;
}): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const servers = useChatStore((state) => state.servers);
  const loadedChannels = useChatStore((state) => state.channels);
  const activeServerId = useChatStore((state) => state.activeServerId);
  // The friends store's copy, not the chat store's: that one flattens a
  // conversation into a `Channel` and drops the participant, which is where the
  // face and the online dot live. A row that says who it is with a grey bubble
  // is a row that has forgotten the only thing worth drawing on it.
  const directChannels = useFriendsStore((state) => state.directChannels);
  const loadFriends = useFriendsStore((state) => state.load);
  const statusOf = useStatusOf();
  const [fetched, setFetched] = useState<Record<string, Channel[]>>({});
  const [query, setQuery] = useState('');
  const [allDirects, setAllDirects] = useState(false);

  useEffect(() => {
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', escape);
    return () => document.removeEventListener('keydown', escape);
  }, [onClose]);

  useEffect(() => {
    let live = true;
    void loadFriends().catch(() => undefined);
    // A server whose channels have never been opened has none in the store, and
    // a list that is short because nothing fetched it looks exactly like a list
    // that is short because there is nowhere to send it.
    for (const server of servers) {
      if (server.id === activeServerId) continue;
      void api
        .channels(server.id)
        .then((channels) => {
          if (live) setFetched((known) => ({ ...known, [server.id]: channels }));
        })
        .catch(() => undefined);
    }
    return () => {
      live = false;
    };
    // Servers do not change while a dialog is open; this is the one fetch pass.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const needle = query.trim().toLowerCase();
  const matches = (text: string): boolean =>
    needle.length === 0 || text.toLowerCase().includes(needle);

  const matched = directChannels.filter(
    (direct) =>
      direct.channelId !== fromChannelId &&
      (matches(direct.participant.displayName) || matches(direct.participant.username)),
  );
  // A search is somebody naming who they want, so it lifts the cap rather than
  // hiding the one row they typed the name of.
  const capped = allDirects || needle.length > 0;
  const people = capped ? matched : matched.slice(0, DIRECTS_SHOWN);
  const hidden = matched.length - people.length;

  const sections = useMemo(
    () =>
      servers
        .map((server) => ({
          server,
          channels: (server.id === activeServerId
            ? loadedChannels
            : (fetched[server.id] ?? [])
          ).filter(
            (channel) =>
              channel.type === 'TEXT' && channel.id !== fromChannelId && matches(channel.name),
          ),
        }))
        .filter((section) => section.channels.length > 0),
    // `matches` closes over `needle`, which is what actually changes here.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [servers, activeServerId, loadedChannels, fetched, fromChannelId, needle],
  );

  const empty = people.length === 0 && sections.length === 0;

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label="Forward message"
      className="fixed inset-0 z-50 flex animate-fade items-end justify-center bg-black/60 px-4 sm:items-center"
      onClick={onClose}
    >
      <div
        className="flex max-h-[75vh] w-full max-w-sm animate-pop flex-col overflow-hidden rounded-t-xl border border-edge bg-surface-900 shadow-pop sm:rounded-xl"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="border-b border-edge px-5 py-4">
          <h2 className="text-base font-bold text-slate-50">Forward to</h2>
          <label className="mt-3 flex items-center gap-2 rounded-lg border border-edge bg-surface-950 px-2.5 py-1.5">
            <SearchIcon className="h-4 w-4 shrink-0 text-slate-500" />
            <input
              autoFocus
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="A name or a channel"
              aria-label="Search for somewhere to forward this to"
              className="min-w-0 flex-1 bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
            />
          </label>
        </div>

        <div className="overflow-y-auto px-2 py-2">
          {empty ? (
            <p className="px-3 py-6 text-center text-sm text-slate-500">
              {needle.length > 0
                ? 'Nothing by that name.'
                : 'Start a conversation or make another channel, and it will be on this list.'}
            </p>
          ) : (
            <ul>
              {people.length > 0 && <Heading label="Direct messages" />}
              {people.map((direct) => (
                <Row
                  key={direct.channelId}
                  name={direct.participant.displayName || direct.participant.username}
                  icon={
                    <Avatar
                      name={direct.participant.displayName}
                      avatarUrl={direct.participant.avatarUrl}
                      status={statusOf(direct.participant.id)}
                      size="sm"
                      ringColour="border-surface-900"
                      // The face is part of the row, not a control of its own:
                      // clicking it must pick the conversation, not open the
                      // photo over the top of the picker.
                      viewable={false}
                    />
                  }
                  onClick={() =>
                    onPick(
                      direct.channelId,
                      direct.participant.displayName || direct.participant.username,
                    )
                  }
                />
              ))}
              {hidden > 0 && (
                <li>
                  <button
                    type="button"
                    onClick={() => setAllDirects(true)}
                    className="w-full cursor-pointer rounded-lg px-3 py-1.5 text-start text-xs font-medium text-slate-400 transition-colors duration-150 hover:bg-white/[0.05] hover:text-slate-200"
                  >
                    Show {hidden} more conversation{hidden === 1 ? '' : 's'}
                  </button>
                </li>
              )}

              {sections.map(({ server, channels }) => (
                <li key={server.id}>
                  <ul>
                    <Heading
                      label={server.name}
                      // The server's own picture beside its name. A column of
                      // "# general" rows all look alike, and the heading is the
                      // only thing saying which server one belongs to.
                      icon={<ServerIcon server={server} size="xs" />}
                    />
                    {channels.map((channel) => (
                      <Row
                        key={channel.id}
                        name={channel.name}
                        icon={<HashIcon className="h-4 w-4 shrink-0 text-slate-500" />}
                        onClick={() => onPick(channel.id, `#${channel.name}`)}
                      />
                    ))}
                  </ul>
                </li>
              ))}
            </ul>
          )}
        </div>

        <button
          type="button"
          onClick={onClose}
          className="cursor-pointer border-t border-edge px-5 py-3 text-sm font-medium text-slate-300 transition-colors duration-150 hover:bg-white/[0.04] hover:text-slate-100"
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

function Heading({ label, icon }: { label: string; icon?: JSX.Element }): JSX.Element {
  return (
    <li className="flex items-center gap-2 px-3 pb-1 pt-3 text-xs font-semibold uppercase tracking-wide text-slate-500">
      {icon}
      <span className="min-w-0 truncate">{label}</span>
    </li>
  );
}

function Row({
  name,
  icon,
  onClick,
}: {
  name: string;
  icon: JSX.Element;
  onClick: () => void;
}): JSX.Element {
  return (
    <li>
      <button
        type="button"
        onClick={onClick}
        className="flex w-full cursor-pointer items-center gap-3 rounded-lg px-3 py-2 text-start transition-colors duration-150 hover:bg-white/[0.05]"
      >
        {icon}
        <span className="min-w-0 flex-1 truncate text-sm text-slate-100">{name}</span>
      </button>
    </li>
  );
}

import { useEffect, useRef } from 'react';
import { QUICK_REACTIONS } from './emoji';
import {
  CopyIcon,
  ReplyIcon,
  PencilIcon,
  PinIcon,
  SmileIcon,
  TrashIcon,
} from '../../components/icons';

export interface MessageMenuActions {
  onReact: (emoji: string) => void;
  /** Answers this message. Absent on a tombstone, which has nothing to quote. */
  onReply?: () => void;
  /**
   * Carries this message into another channel. Absent when there is nothing
   * to carry: a tombstone, or a one-time message, whose whole bargain is that
   * it is seen once by the people it was sent to.
   */
  onForward?: () => void;
  /** Opens the full picker at the position the menu was standing in. */
  onMoreEmoji: (at: { x: number; y: number }) => void;
  onEdit?: () => void;
  onPin?: () => void;
  onCopy?: () => void;
  onDelete?: () => void;
  pinned: boolean;
  /**
   * Why pinning is not on offer, when it is not. An item that is simply absent
   * looks like a missing feature; one that says which permission it wants is
   * something an administrator can act on.
   */
  pinDisabledReason?: string;
}

/**
 * The right-click menu on a message. It replaces the hover bin: hover controls
 * have to be discovered by accident and they cover the message they belong to,
 * while a context menu is where everybody already looks for "do something to
 * this thing" - and it has room for the actions a corner button never had.
 *
 * The first click on a destructive item arms it; the second confirms. Same
 * bargain the bin made, without a modal for a one-line message.
 */
export function MessageMenu({
  at,
  actions,
  armedDelete,
  onArmDelete,
  onClose,
}: {
  at: { x: number; y: number };
  actions: MessageMenuActions;
  armedDelete: boolean;
  onArmDelete: () => void;
  onClose: () => void;
}): JSX.Element {
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const away = (event: MouseEvent): void => {
      if (!box.current?.contains(event.target as Node)) onClose();
    };
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    const timer = window.setTimeout(() => document.addEventListener('mousedown', away), 0);
    document.addEventListener('keydown', escape);
    return () => {
      window.clearTimeout(timer);
      document.removeEventListener('mousedown', away);
      document.removeEventListener('keydown', escape);
    };
  }, [onClose]);

  const width = 208;
  const rows =
    1 +
    [
      actions.onReply,
      actions.onForward,
      actions.onEdit,
      actions.onPin,
      actions.onCopy,
      actions.onDelete,
    ].filter(
      Boolean,
    ).length;
  const height = 52 + rows * 34;
  const left = Math.min(at.x, window.innerWidth - width - 8);
  const top = Math.min(at.y, window.innerHeight - height - 8);

  return (
    <div
      ref={box}
      role="menu"
      aria-label="Message actions"
      style={{ left, top, width }}
      className="fixed z-50 animate-pop overflow-hidden rounded-xl border border-edge bg-surface-900 py-1 shadow-pop"
    >
      <div className="flex items-center gap-1 border-b border-edge px-2 pb-2 pt-1">
        {QUICK_REACTIONS.map((emoji) => (
          <button
            key={emoji}
            type="button"
            role="menuitem"
            onClick={() => {
              actions.onReact(emoji);
              onClose();
            }}
            aria-label={`React with ${emoji}`}
            className="cursor-pointer rounded p-1 text-lg leading-none transition-colors duration-150 hover:bg-white/[0.06]"
          >
            {emoji}
          </button>
        ))}
        <button
          type="button"
          role="menuitem"
          onClick={() => {
            actions.onMoreEmoji(at);
            onClose();
          }}
          aria-label="More emoji"
          title="More emoji"
          className="ms-auto cursor-pointer rounded p-1 text-slate-300 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
        >
          <SmileIcon className="h-4 w-4" />
        </button>
      </div>

      {actions.onReply && (
        <Item
          icon={<ReplyIcon className="h-4 w-4" />}
          label="Reply"
          onClick={() => {
            actions.onReply?.();
            onClose();
          }}
        />
      )}
      {actions.onForward && (
        <Item
          // The reply mark, mirrored - which is the forward mark. One glyph
          // rather than a second that says the same thing pointing the other way.
          icon={<ReplyIcon className="h-4 w-4 -scale-x-100" />}
          label="Forward"
          onClick={() => {
            actions.onForward?.();
            onClose();
          }}
        />
      )}
      {actions.onEdit && (
        <Item icon={<PencilIcon className="h-4 w-4" />} label="Edit message" onClick={() => {
          actions.onEdit?.();
          onClose();
        }} />
      )}
      {actions.onPin ? (
        <Item
          icon={<PinIcon className="h-4 w-4" />}
          label={actions.pinned ? 'Unpin message' : 'Pin message'}
          onClick={() => {
            actions.onPin?.();
            onClose();
          }}
        />
      ) : (
        <Item
          icon={<PinIcon className="h-4 w-4" />}
          label="Pin message"
          hint={actions.pinDisabledReason}
          disabled
          onClick={() => undefined}
        />
      )}
      {actions.onCopy && (
        <Item icon={<CopyIcon className="h-4 w-4" />} label="Copy text" onClick={() => {
          actions.onCopy?.();
          onClose();
        }} />
      )}
      {actions.onDelete && (
        <Item
          icon={<TrashIcon className="h-4 w-4" />}
          label={armedDelete ? 'Click again to delete' : 'Delete message'}
          danger
          onClick={() => {
            if (!armedDelete) {
              onArmDelete();
              return;
            }
            actions.onDelete?.();
            onClose();
          }}
        />
      )}
    </div>
  );
}

function Item({
  icon,
  label,
  onClick,
  danger = false,
  disabled = false,
  hint,
}: {
  icon: JSX.Element;
  label: string;
  onClick: () => void;
  danger?: boolean;
  disabled?: boolean;
  hint?: string;
}): JSX.Element {
  return (
    <button
      type="button"
      role="menuitem"
      onClick={onClick}
      disabled={disabled}
      title={hint}
      className={`flex w-full items-center gap-2 px-3 py-1.5 text-start text-sm transition-colors duration-150 ${
        disabled
          ? 'cursor-not-allowed text-slate-500'
          : danger
            ? 'cursor-pointer text-danger hover:bg-danger hover:text-white'
            : 'cursor-pointer text-slate-200 hover:bg-white/[0.07] hover:text-slate-100'
      }`}
    >
      {icon}
      <span className="min-w-0 flex-1">
        {label}
        {disabled && hint && <span className="block text-xs text-slate-600">{hint}</span>}
      </span>
    </button>
  );
}

import assert from 'node:assert/strict';
import { PinnedPanel } from './PinnedPanel';

assert.equal(typeof PinnedPanel, 'function', 'PinnedPanel should be a function component');

console.log('PinnedPanel.check.ts ok');

import { useEffect } from 'react';
import { useChatStore, type DecryptedMessage } from '../../stores/chat';
import { useAuthStore } from '../../stores/auth';
import { PersonAvatar } from '../../components/Avatar';
import { PinIcon, XIcon } from '../../components/icons';
import { SkeletonRows } from '../../components/Skeleton';
import { listState } from '../../services/list-state';

export interface PinnedPanelProps {
  onClose?: () => void;
  className?: string;
}

/**
 * Pinned messages, in the same column the member list uses - it is the same
 * kind of thing (a list about this channel), and two panels open at once would
 * leave nothing to read.
 *
 * Clicking one scrolls the conversation to it rather than opening a copy: a pin
 * is a bookmark into the channel, not a separate document.
 */
export function PinnedPanel({
  onClose,
  className = 'w-60 shrink-0',
}: PinnedPanelProps = {}): JSX.Element {
  const me = useAuthStore((state) => state.user);
  const pins = useChatStore((state) => state.pins);
  const loadingPins = useChatStore((state) => state.loadingPins);
  const loadPins = useChatStore((state) => state.loadPins);
  const jumpToMessage = useChatStore((state) => state.jumpToMessage);
  const showPanel = useChatStore((state) => state.showPanel);
  const channelId = useChatStore((state) => state.activeChannelId);

  useEffect(() => {
    void loadPins();
  }, [loadPins, channelId]);

  const handleClose = () => {
    if (onClose) {
      onClose();
    } else {
      showPanel('members');
    }
  };

  return (
    <aside className={`panel flex flex-col bg-surface-850 ${className}`}>
      <header className="flex h-12 shrink-0 items-center gap-2 border-b border-edge px-3">
        <PinIcon className="h-4 w-4 text-slate-400" />
        <h2 className="flex-1 text-sm font-semibold text-slate-100">Pinned</h2>
        <button
          type="button"
          onClick={handleClose}
          aria-label="Close pinned messages"
          className="flex h-8 w-8 min-h-[44px] min-w-[44px] sm:min-h-0 sm:min-w-0 sm:h-7 sm:w-7 cursor-pointer items-center justify-center rounded-md p-1 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
        >
          <XIcon className="h-4 w-4" />
        </button>
      </header>

      {listState(pins.length, loadingPins) === 'loading' ? (
        <SkeletonRows rows={3} label="Loading pinned messages" className="p-3" />
      ) : listState(pins.length, loadingPins) === 'empty' ? (
        <p className="px-4 py-6 text-sm text-slate-400">
          Nothing pinned yet. Right-click a message and choose <em>Pin</em>.
        </p>
      ) : (
        <ul className="min-h-0 flex-1 space-y-2 overflow-y-auto p-2">
          {pins.map((message) => (
            <li key={message.id}>
              <button
                type="button"
                onClick={() => jumpToMessage(message.id)}
                className="w-full cursor-pointer rounded-lg bg-surface-800 p-2.5 text-start transition-colors duration-200 hover:bg-white/[0.06]"
              >
                <span className="flex items-center gap-2">
                  <PersonAvatar
                    userId={message.author.id}
                    name={message.author.displayName}
                    avatarUrl={message.author.avatarUrl}
                    size="sm"
                    ringColour="border-surface-800"
                  />
                  <span
                    className={`min-w-0 flex-1 truncate text-sm font-medium ${
                      message.author.id === me?.id ? 'font-semibold text-accent' : 'text-slate-100'
                    }`}
                  >
                    {message.author.id === me?.id ? 'You' : message.author.displayName}
                  </span>
                </span>
                <span className="mt-1.5 block line-clamp-3 break-words text-sm text-slate-300">
                  {preview(message)}
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </aside>
  );
}

/** A file-only message still needs a line of text to be recognised by. */
function preview(message: DecryptedMessage): string {
  if (message.content.trim()) return message.content;
  if (message.attachments.length === 1) return message.attachments[0]?.name ?? 'Attachment';
  if (message.attachments.length > 1) return `${message.attachments.length} attachments`;
  return 'Empty message';
}

/** Run with `tsx src/features/chat/receipts.check.ts`. Read receipts from markers. */
import assert from 'node:assert/strict';
import type { ChannelReadReceipt } from '@betweenus/shared-types';
import { anchorReceipts, seenBy, seenByLabel, type ReceiptMessage } from './receipts';

const reader = (name: string, readAt: string): ChannelReadReceipt => ({
  user: { id: name, username: name, displayName: name, avatarUrl: null },
  readAt,
});

const message = (id: string, createdAt: string, authorId: string): ReceiptMessage => ({
  id,
  createdAt,
  authorId,
});

const first = message('m1', '2026-01-01T10:00:00.000Z', 'me');
const second = message('m2', '2026-01-01T10:05:00.000Z', 'me');
const third = message('m3', '2026-01-01T10:10:00.000Z', 'me');
const mine = [first, second, third];

// --- seenBy ------------------------------------------------------------------

const readers = [
  reader('ana', '2026-01-01T10:06:00.000Z'),
  reader('bo', '2026-01-01T10:11:00.000Z'),
];

assert.deepEqual(
  seenBy(first, readers).map((r) => r.user.id),
  ['ana', 'bo'],
  'both markers are past the first message',
);
assert.deepEqual(
  seenBy(third, readers).map((r) => r.user.id),
  ['bo'],
  'only the marker past the newest message counts',
);
// The marker landing on the same millisecond counts: it was read, not missed.
assert.equal(seenBy(second, [reader('cy', second.createdAt)]).length, 1);

// --- anchorReceipts ----------------------------------------------------------

const anchors = anchorReceipts(mine, readers, 'me');
assert.deepEqual(Object.keys(anchors).sort(), ['m2', 'm3']);
assert.deepEqual(anchors.m2?.map((r) => r.user.id), ['ana'], 'ana stops at the second');
assert.deepEqual(anchors.m3?.map((r) => r.user.id), ['bo'], 'bo reached the newest');
assert.equal(anchors.m1, undefined, 'nobody is drawn twice');

// A marker older than anything on screen anchors nowhere.
assert.deepEqual(anchorReceipts(mine, [reader('old', '2026-01-01T09:00:00.000Z')], 'me'), {});

// Somebody else's messages never carry a receipt, and neither does a signed-out
// client that has no idea which messages are its own.
const theirs = [message('t1', '2026-01-01T10:00:00.000Z', 'them')];
assert.deepEqual(anchorReceipts(theirs, readers, 'me'), {});
assert.deepEqual(anchorReceipts(mine, readers, undefined), {});

// Out-of-order input must not change the answer: the list is sorted first.
const shuffled = [third, first, second];
assert.deepEqual(Object.keys(anchorReceipts(shuffled, readers, 'me')).sort(), ['m2', 'm3']);

// --- seenByLabel -------------------------------------------------------------

assert.equal(seenByLabel([]), 'Not seen yet');
assert.equal(seenByLabel([reader('Ana', '2026-01-01T10:06:00.000Z')]), 'Seen by Ana');
assert.equal(seenByLabel(readers.slice(0, 2)), 'Seen by ana and bo');
assert.equal(
  seenByLabel([...readers, reader('cy', '2026-01-01T10:12:00.000Z')]),
  'Seen by ana, bo and 1 other',
);

console.log('receipts.check.ts ok');

/**
 * Read receipts, derived from read markers.
 *
 * The server stores one marker per person per channel - "read up to here" -
 * and never a row per message. Everything below is the arithmetic that turns
 * those markers back into "who has seen this message", which is why there is
 * no receipt table to keep in step with anything.
 *
 * Two questions, and they are not the same one:
 *
 * - `seenBy` - who has seen *this* message. Every marker at or past it. That
 *   is what the dialog lists.
 * - `anchorReceipts` - where each person's face is drawn. A reader is shown
 *   once, on the newest message of yours they have read, the way Messenger
 *   does it. Drawing everybody against every message would repeat the same
 *   four avatars down the whole conversation and say nothing new each time.
 */
import type { ChannelReadReceipt } from '@betweenus/shared-types';

/** How many faces the row draws before it starts counting instead. */
export const SEEN_BY_FACES = 4;

/** The shape both callers need from a message; the real one carries far more. */
export interface ReceiptMessage {
  id: string;
  createdAt: string;
  authorId: string;
}

const at = (iso: string): number => new Date(iso).getTime();

/** Everyone whose marker is at or past this message. Newest reader first. */
export function seenBy(
  message: Pick<ReceiptMessage, 'createdAt'>,
  receipts: ChannelReadReceipt[],
): ChannelReadReceipt[] {
  const sent = at(message.createdAt);
  return receipts
    .filter((receipt) => at(receipt.readAt) >= sent)
    .sort((a, b) => at(a.readAt) - at(b.readAt));
}

/**
 * messageId -> the readers whose row it is, for your own messages only.
 *
 * Somebody else's message never carries a receipt: it is their message that
 * was read, and telling you who else has read it is a different feature.
 */
export function anchorReceipts(
  messages: ReceiptMessage[],
  receipts: ChannelReadReceipt[],
  meId: string | undefined,
): Record<string, ChannelReadReceipt[]> {
  if (!meId) return {};
  const mine = messages
    .filter((message) => message.authorId === meId)
    .sort((a, b) => at(a.createdAt) - at(b.createdAt));
  if (mine.length === 0) return {};

  const anchors: Record<string, ChannelReadReceipt[]> = {};
  for (const receipt of receipts) {
    const read = at(receipt.readAt);
    // The newest of your messages this marker has reached. A marker older than
    // everything on screen anchors nowhere, which is the "has not seen it yet"
    // case and draws nothing at all.
    let newest: ReceiptMessage | null = null;
    for (const message of mine) {
      if (at(message.createdAt) <= read) newest = message;
      else break;
    }
    if (!newest) continue;
    (anchors[newest.id] ??= []).push(receipt);
  }

  // Oldest reader first within a row, so the faces stop shuffling every time
  // somebody else opens the channel.
  for (const row of Object.values(anchors)) row.sort((a, b) => at(a.readAt) - at(b.readAt));
  return anchors;
}

/** "Seen by Ana", "Seen by Ana and Bo", "Seen by Ana, Bo and 3 others". */
export function seenByLabel(receipts: ChannelReadReceipt[]): string {
  const names = receipts.map((receipt) => receipt.user.displayName || receipt.user.username);
  if (names.length === 0) return 'Not seen yet';
  if (names.length === 1) return `Seen by ${names[0]}`;
  if (names.length === 2) return `Seen by ${names[0]} and ${names[1]}`;
  const rest = names.length - 2;
  return `Seen by ${names[0]}, ${names[1]} and ${rest} other${rest === 1 ? '' : 's'}`;
}

import assert from 'node:assert/strict';
import { SearchPanel } from './SearchPanel';

assert.equal(typeof SearchPanel, 'function', 'SearchPanel should be a function component');

console.log('SearchPanel.check.ts ok');

import { useMemo, useState } from 'react';
import { dayLabel } from './day';
import { useChatStore, type DecryptedMessage } from '../../stores/chat';
import { useAuthStore } from '../../stores/auth';
import { PersonAvatar } from '../../components/Avatar';
import { SearchIcon, XIcon } from '../../components/icons';

export interface SearchPanelProps {
  onClose?: () => void;
  className?: string;
}

/**
 * Search inside the open conversation.
 *
 * It runs in the client, over the decrypted history this window is holding,
 * and it has to: `messages.content` is ciphertext, so the server cannot match a
 * word in it without being given the channel key, which is the one thing the
 * design will not do. What this means in practice is documented rather than
 * hidden - the footer says how far back the search reached, and scrolling the
 * conversation further back widens it.
 */
export function SearchPanel({
  onClose,
  className = 'w-60 shrink-0',
}: SearchPanelProps = {}): JSX.Element {
  const me = useAuthStore((state) => state.user);
  const channelId = useChatStore((state) => state.activeChannelId);
  const history = useChatStore((state) => (channelId ? state.history[channelId] : undefined));
  const messages = useChatStore((state) => state.messages);
  const jumpToMessage = useChatStore((state) => state.jumpToMessage);
  const showPanel = useChatStore((state) => state.showPanel);

  const [query, setQuery] = useState('');
  const searchable = history ?? messages;

  const results = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (term.length < 2) return [];
    return searchable
      .filter((message) => !message.deletedAt && message.content.toLowerCase().includes(term))
      .slice(-100)
      .reverse();
  }, [query, searchable]);

  const handleClose = () => {
    if (onClose) {
      onClose();
    } else {
      showPanel('members');
    }
  };

  return (
    <aside className={`panel flex flex-col bg-surface-850 ${className}`}>
      <header className="flex h-12 shrink-0 items-center gap-2 border-b border-edge px-3">
        <SearchIcon className="h-4 w-4 text-slate-400" />
        <h2 className="flex-1 text-sm font-semibold text-slate-100">Search</h2>
        <button
          type="button"
          onClick={handleClose}
          aria-label="Close search"
          className="flex h-8 w-8 min-h-[44px] min-w-[44px] sm:min-h-0 sm:min-w-0 sm:h-7 sm:w-7 cursor-pointer items-center justify-center rounded-md p-1 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
        >
          <XIcon className="h-4 w-4" />
        </button>
      </header>

      <div className="shrink-0 p-2">
        <input
          autoFocus
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Search this channel"
          aria-label="Search this channel"
          className="w-full rounded bg-surface-950 px-2.5 py-1.5 text-sm text-slate-100 placeholder-slate-500 focus:outline-none"
        />
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto px-2 pb-2">
        {query.trim().length >= 2 && results.length === 0 && (
          <p className="px-2 py-4 text-sm text-slate-400">Nothing in the loaded history matches.</p>
        )}

        <ul className="space-y-2">
          {results.map((message) => (
            <li key={message.id}>
              <button
                type="button"
                onClick={() => jumpToMessage(message.id)}
                className="w-full cursor-pointer rounded-lg bg-surface-800 p-2.5 text-start transition-colors duration-200 hover:bg-white/[0.06]"
              >
                <span className="flex items-center gap-2">
                  <PersonAvatar
                    userId={message.author.id}
                    name={message.author.displayName}
                    avatarUrl={message.author.avatarUrl}
                    size="sm"
                    ringColour="border-surface-800"
                  />
                  <span
                    className={`min-w-0 flex-1 truncate text-sm font-medium ${
                      message.author.id === me?.id ? 'font-semibold text-accent' : 'text-slate-100'
                    }`}
                  >
                    {message.author.id === me?.id ? 'You' : message.author.displayName}
                  </span>
                  <time dateTime={message.createdAt} className="shrink-0 text-xs text-slate-500">
                    {dayLabel(message.createdAt)}
                  </time>
                </span>
                <span className="mt-1.5 block line-clamp-3 break-words text-sm text-slate-300">
                  {highlight(message, query)}
                </span>
              </button>
            </li>
          ))}
        </ul>
      </div>

      <p className="shrink-0 border-t border-edge px-3 py-2 text-xs text-slate-500">
        Searches the {searchable.length} messages this window has decrypted. Messages are encrypted,
        so the server cannot search them.
      </p>
    </aside>
  );
}

/** Trims a long body down to the part the term is actually in. */
function highlight(message: DecryptedMessage, query: string): string {
  const at = message.content.toLowerCase().indexOf(query.trim().toLowerCase());
  if (at <= 60) return message.content.slice(0, 160);
  return `…${message.content.slice(at - 40, at + 120)}`;
}

/**
 * The "seen by" row under your own messages, and the dialog behind it.
 *
 * A row of faces rather than a tick or a "read" caption: the question people
 * actually ask of a group is *who* has seen it, and four faces answer it
 * without being read. Four, then a count - past that the faces stop being
 * recognisable and start being a texture.
 *
 * Every timestamp here is the read *marker*, so it says "had this channel open
 * at" rather than "looked at this message at". That is the honest reading of
 * what the server stores, and the dialog says so rather than implying more.
 */
import { clockTime, dayLabel } from './day';
import { useEffect, useRef } from 'react';
import type { ChannelReadReceipt } from '@betweenus/shared-types';
import { absoluteUrl } from '../../services/endpoint';
import { SEEN_BY_FACES, seenByLabel } from './receipts';
import { useFocusTrap } from '../../services/focus-trap';

/** One small round face. Its own markup: `Avatar` starts at 32px, twice this. */
function Face({ receipt, size }: { receipt: ChannelReadReceipt; size: number }): JSX.Element {
  const name = receipt.user.displayName || receipt.user.username;
  return receipt.user.avatarUrl ? (
    <img
      src={absoluteUrl(receipt.user.avatarUrl)}
      alt=""
      style={{ height: size, width: size }}
      className="rounded-full border border-surface-900 object-cover"
    />
  ) : (
    <span
      aria-hidden="true"
      style={{ height: size, width: size, fontSize: size * 0.45 }}
      className="flex items-center justify-center rounded-full border border-surface-900 bg-accent/25 font-semibold uppercase leading-none text-slate-100"
    >
      {name.slice(0, 1)}
    </span>
  );
}

/**
 * The row itself. Nothing is drawn for a message nobody has read yet: an empty
 * "seen by nobody" line under every message you send is a nag, not a fact.
 */
export function SeenByRow({
  receipts,
  onOpen,
}: {
  receipts: ChannelReadReceipt[];
  onOpen: () => void;
}): JSX.Element | null {
  if (receipts.length === 0) return null;

  const shown = receipts.slice(-SEEN_BY_FACES);
  const rest = receipts.length - shown.length;
  const label = seenByLabel(receipts);

  return (
    <div className="mt-1 flex justify-end">
      <button
        type="button"
        onClick={onOpen}
        title={label}
        aria-label={`${label}. Open for details`}
        className="flex cursor-pointer items-center gap-1 rounded-full px-1 py-0.5 transition-colors duration-150 hover:bg-white/[0.06]"
      >
        {/* Overlapped, so four faces cost the width of two and a half. */}
        <span className="flex -space-x-1.5 rtl:space-x-reverse">
          {shown.map((receipt) => (
            <Face key={receipt.user.id} receipt={receipt} size={16} />
          ))}
        </span>
        {rest > 0 && <span className="text-[10px] font-medium text-slate-500">+{rest}</span>}
      </button>
    </div>
  );
}

/**
 * When it was sent, and when each person read it. Opened from the row, and the
 * only place the times are spelled out - the row itself is faces and a count,
 * because that is what fits under a message without competing with it.
 */
export function SeenByDialog({
  sentAt,
  receipts,
  onClose,
}: {
  sentAt: string;
  receipts: ChannelReadReceipt[];
  onClose: () => void;
}): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', escape);
    return () => document.removeEventListener('keydown', escape);
  }, [onClose]);

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label="Message info"
      className="fixed inset-0 z-50 flex animate-fade items-end justify-center bg-black/60 px-4 sm:items-center"
      onClick={onClose}
    >
      <div
        ref={box}
        className="mb-0 flex max-h-[75vh] w-full max-w-sm animate-pop flex-col overflow-hidden rounded-t-xl border border-edge bg-surface-900 shadow-pop sm:mb-0 sm:rounded-xl"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="border-b border-edge px-5 py-4">
          <h2 className="text-base font-bold text-slate-50">Message info</h2>
          <p className="mt-1 text-xs text-slate-400">
            Sent {formatStamp(sentAt)}
          </p>
        </div>

        <div className="overflow-y-auto px-2 py-2">
          {receipts.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-slate-500">Nobody has read it yet.</p>
          ) : (
            <ul>
              {receipts.map((receipt) => (
                <li
                  key={receipt.user.id}
                  className="flex items-center gap-3 rounded-lg px-3 py-2 hover:bg-white/[0.03]"
                >
                  <Face receipt={receipt} size={32} />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm text-slate-100">
                      {receipt.user.displayName || receipt.user.username}
                    </span>
                    {/* The marker, said plainly: it is when they had the
                        channel open, which is not quite when their eyes were
                        on this message and should not pretend to be. */}
                    <span className="block text-xs text-slate-500">
                      Read {formatStamp(receipt.readAt)}
                    </span>
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>

        <button
          type="button"
          onClick={onClose}
          className="cursor-pointer border-t border-edge px-5 py-3 text-sm font-medium text-slate-300 transition-colors duration-150 hover:bg-white/[0.04] hover:text-slate-100"
        >
          Close
        </button>
      </div>
    </div>
  );
}

/**
 * When somebody read it: "Today at 14:32", "Yesterday at 9:14 AM".
 *
 * The same words and the same clock the message list's dividers use - the day
 * from `dayLabel`, the time in the reader's own locale and 12/24-hour setting -
 * because a receipt sitting under a conversation must not name the day, or tell
 * the time, differently from the conversation.
 */
function formatStamp(iso: string): string {
  return `${dayLabel(iso)} at ${clockTime(iso)}`;
}

/**
 * What you are about to send, before you send it.
 *
 * Pictures and video used to go out as a filename on a chip, which is the one
 * moment nobody can check what they picked - and picking the wrong photo out of
 * a folder of near-identical ones is the most ordinary mistake there is. This is
 * the screen WhatsApp puts between the picker and the send button: the file
 * itself, big, with the caption box under it and a strip of everything else in
 * the batch along the bottom.
 *
 * Nothing here is encrypted yet. These are local files the user just chose, so
 * they are shown straight from an object URL - the upload, and the encryption
 * that precedes it, only happen on send.
 */
import { useEffect, useState } from 'react';
import { formatBytes } from '../../services/attachments';
import { ImageEditor } from '../../components/ImageEditor';
import {
  CropIcon,
  FileIcon,
  ImageIcon,
  OneTimeIcon,
  PaperclipIcon,
  SendIcon,
  TrashIcon,
  XIcon,
} from '../../components/icons';
import { useFocusTrap } from '../../services/focus-trap';

const IMAGE_EXT_RE = /\.(png|jpe?g|gif|webp|svg|bmp|ico|heic)$/i;
const VIDEO_EXT_RE = /\.(mp4|webm|mov|m4v|ogg)$/i;

export function isImage(file: File): boolean {
  return file.type.startsWith('image/') || IMAGE_EXT_RE.test(file.name);
}

export function isVideo(file: File): boolean {
  return file.type.startsWith('video/') || VIDEO_EXT_RE.test(file.name);
}

/** True for the files this screen has something to show rather than name. */
export function isPreviewable(file: File): boolean {
  return isImage(file) || isVideo(file);
}

/**
 * The one-time switch.
 *
 * A toggle rather than a menu item, and it sits next to what it applies to,
 * because it changes what pressing send means: this message's files may be
 * opened once by the person receiving them, and that opening destroys them
 * everywhere. It is worth being able to see the state of that without opening
 * anything.
 */
export function OneTimeToggle({
  on,
  onChange,
}: {
  on: boolean;
  onChange: (next: boolean) => void;
}): JSX.Element {
  return (
    <button
      type="button"
      onClick={() => onChange(!on)}
      aria-pressed={on}
      aria-label="Send as a one-time message"
      title={
        on
          ? 'One-time: the files disappear once they have been opened'
          : 'Send as a one-time message'
      }
      className={`flex h-8 w-8 min-h-[36px] min-w-[36px] sm:min-h-0 sm:min-w-0 sm:h-8 sm:w-8 shrink-0 cursor-pointer items-center justify-center rounded-md transition-colors duration-200 ${
        on ? 'bg-accent/15 text-accent' : 'text-slate-400 hover:text-slate-100'
      }`}
    >
      <OneTimeIcon className="h-4.5 w-4.5" />
    </button>
  );
}

export function SendPreview({
  files,
  caption,
  placeholder,
  sending,
  uploading,
  failure,
  viewOnce,
  onViewOnce,
  onCaption,
  onRemove,
  onReplace,
  onAdd,
  onSend,
  onClose,
}: {
  files: File[];
  caption: string;
  placeholder: string;
  sending: boolean;
  /** The file being encrypted and uploaded right now, if any. */
  uploading: { name: string; percent: number } | null;
  failure: string | null;
  /** Whether these files are being sent as a one-time message. */
  viewOnce: boolean;
  onViewOnce: (next: boolean) => void;
  onCaption: (text: string) => void;
  onRemove: (index: number) => void;
  /** A picture that came back from the crop screen, in place of the original. */
  onReplace: (index: number, file: File) => void;
  onAdd: () => void;
  onSend: () => void;
  onClose: () => void;
}): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const [at, setAt] = useState(0);
  const [cropping, setCropping] = useState(false);
  // Clamped rather than reset: removing a file should keep you looking at the
  // batch, not throw you back to the first one.
  const index = Math.min(at, files.length - 1);
  const current = files[index];

  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape' && !sending) onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose, sending]);

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label="Send files"
      className="fixed inset-0 z-50 flex flex-col items-center justify-center bg-black/85 p-6"
    >
      {cropping && current && (
        <ImageEditor
          file={current}
          title={current.name}
          onCancel={() => setCropping(false)}
          onDone={(edited) => {
            setCropping(false);
            // Same name, so the batch strip and the caption do not jump about;
            // the extension follows the type the editor actually wrote.
            onReplace(index, new File([edited], withExtension(current.name, 'jpg'), {
              type: edited.type,
            }));
          }}
        />
      )}

      <div className="flex max-h-full w-full max-w-3xl animate-pop flex-col overflow-hidden rounded-xl border border-edge bg-surface-900 shadow-pop">
        <header className="flex h-12 shrink-0 items-center gap-3 border-b border-edge px-4">
          <p className="truncate text-sm font-medium text-slate-100">
            {files.length === 1 ? current?.name : `${files.length} files`}
          </p>
          {current && (
            <span className="shrink-0 text-xs text-slate-400">{formatBytes(current.size)}</span>
          )}
          <button
            type="button"
            onClick={onClose}
            disabled={sending}
            aria-label="Discard files"
            title="Discard"
            className="ms-auto cursor-pointer rounded-md p-1.5 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100 disabled:cursor-not-allowed"
          >
            <XIcon className="h-4 w-4" />
          </button>
        </header>

        <div className="flex min-h-[240px] flex-1 items-center justify-center bg-black/40 p-4">
          {current ? <Preview file={current} /> : null}
        </div>

        {files.length > 1 && (
          <ul className="flex shrink-0 gap-2 overflow-x-auto border-t border-edge px-3 py-2">
            {files.map((file, position) => (
              <li key={`${file.name}-${position}`}>
                <button
                  type="button"
                  onClick={() => setAt(position)}
                  aria-current={position === index}
                  aria-label={`Show ${file.name}`}
                  className={`flex h-14 w-14 cursor-pointer items-center justify-center overflow-hidden rounded border ${
                    position === index ? 'border-accent' : 'border-edge'
                  } bg-surface-850`}
                >
                  <Thumbnail file={file} />
                </button>
              </li>
            ))}
          </ul>
        )}

        {uploading && (
          <p className="shrink-0 truncate border-t border-edge px-4 py-1.5 text-xs text-slate-400" aria-live="polite">
            Encrypting and uploading {uploading.name} — {uploading.percent}%
          </p>
        )}
        {failure && (
          <p role="alert" className="shrink-0 border-t border-edge px-4 py-1.5 text-xs text-danger">
            {failure}
          </p>
        )}

        <div className="flex shrink-0 items-end gap-2 border-t border-edge px-4 py-3">
          <button
            type="button"
            onClick={onAdd}
            disabled={sending}
            aria-label="Add another file"
            title="Add another file"
            className="cursor-pointer rounded-md p-1.5 text-slate-300 transition-colors duration-200 hover:text-accent disabled:cursor-not-allowed disabled:text-slate-600"
          >
            <PaperclipIcon className="h-5 w-5" />
          </button>
          {current && isImage(current) && (
            <button
              type="button"
              onClick={() => setCropping(true)}
              disabled={sending}
              aria-label={`Crop and rotate ${current.name}`}
              title="Crop and rotate"
              className="cursor-pointer rounded-md p-1.5 text-slate-300 transition-colors duration-200 hover:text-accent disabled:cursor-not-allowed disabled:text-slate-600"
            >
              <CropIcon className="h-5 w-5" />
            </button>
          )}
          <button
            type="button"
            onClick={() => onRemove(index)}
            disabled={sending || files.length === 0}
            aria-label={`Remove ${current?.name ?? 'this file'}`}
            title="Remove this file"
            className="cursor-pointer rounded-md p-1.5 text-slate-300 transition-colors duration-200 hover:text-danger disabled:cursor-not-allowed disabled:text-slate-600"
          >
            <TrashIcon className="h-5 w-5" />
          </button>

          {/* Here as well as on the composer, and driving the same state. This
              is the screen where somebody actually looks at the photo they are
              about to send, so it is the screen where they decide it is one
              they would rather did not stay anywhere. */}
          <OneTimeToggle on={viewOnce} onChange={onViewOnce} />

          <label htmlFor="send-caption" className="sr-only">
            {placeholder}
          </label>
          <textarea
            id="send-caption"
            autoFocus
            rows={1}
            value={caption}
            disabled={sending}
            onChange={(event) => onCaption(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault();
                onSend();
              }
            }}
            placeholder={placeholder}
            className="max-h-32 min-h-[24px] flex-1 resize-none rounded-lg bg-surface-800 px-3 py-2 text-slate-100 placeholder-slate-500 focus:outline-none"
          />

          <button
            type="button"
            onClick={onSend}
            disabled={sending || files.length === 0}
            aria-label="Send"
            className="cursor-pointer rounded-full bg-accent p-2.5 text-white transition-colors duration-200 hover:brightness-110 disabled:cursor-not-allowed disabled:opacity-50"
          >
            <SendIcon className="h-5 w-5" />
          </button>
        </div>
      </div>
    </div>
  );
}

/** The big one. A video gets a real player: this is the last chance to watch it. */
function Preview({ file }: { file: File }): JSX.Element {
  const url = useObjectUrl(file);

  if (isImage(file)) {
    return url ? (
      <img src={url} alt={file.name} className="max-h-[55vh] max-w-full object-contain" />
    ) : (
      <div className="flex h-48 w-full items-center justify-center">
        <div className="h-6 w-6 animate-spin rounded-full border-2 border-slate-600 border-t-accent" />
      </div>
    );
  }
  if (isVideo(file)) {
    return url ? (
      <video src={url} controls className="max-h-[55vh] max-w-full bg-black" />
    ) : (
      <div className="flex h-48 w-full items-center justify-center">
        <div className="h-6 w-6 animate-spin rounded-full border-2 border-slate-600 border-t-accent" />
      </div>
    );
  }
  return (
    <div className="flex flex-col items-center gap-2 text-slate-300">
      <FileIcon className="h-10 w-10" />
      <p className="max-w-xs truncate text-sm">{file.name}</p>
      <p className="text-xs text-slate-500">{formatBytes(file.size)}</p>
    </div>
  );
}

function Thumbnail({ file }: { file: File }): JSX.Element {
  const url = useObjectUrl(file);

  if (isImage(file)) {
    return url ? (
      <img src={url} alt="" className="h-full w-full object-cover" />
    ) : (
      <ImageIcon className="h-5 w-5 text-slate-400" />
    );
  }
  if (isVideo(file)) {
    return url ? (
      <video src={url} muted className="h-full w-full object-cover" />
    ) : (
      <FileIcon className="h-5 w-5 text-slate-400" />
    );
  }
  return <FileIcon className="h-5 w-5 text-slate-400" />;
}

/** An object URL for a local file, released when it stops being shown. */
export function useObjectUrl(file: File | null | undefined): string | null {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    if (!file) {
      setUrl(null);
      return;
    }
    const objectUrl = URL.createObjectURL(file);
    setUrl(objectUrl);
    return () => {
      URL.revokeObjectURL(objectUrl);
    };
  }, [file]);

  return url;
}

/** `holiday.heic` -> `holiday.jpg`. A file that lies about its type confuses every client that opens it. */
function withExtension(name: string, extension: string): string {
  const dot = name.lastIndexOf('.');
  return `${dot > 0 ? name.slice(0, dot) : name}.${extension}`;
}

/**
 * A voice message, drawn as one.
 *
 * What this replaces was a browser `<audio controls>` inside a card with the
 * file name and a download button under it. Every part of that was wrong for a
 * spoken message: the chrome is the browser's rather than the app's, it is a
 * different width and colour in every engine, the file name is a timestamp
 * nobody wants to read, and the whole thing announces "here is a file" when the
 * thing that arrived was somebody talking.
 *
 * So: a play button, the shape of the recording, how long it is, and nothing
 * else. The waveform is the seek bar - there is no second slider, because the
 * waveform is already a picture of the timeline and putting a track under it
 * would be drawing the same axis twice.
 *
 * The bars come from the sender, measured while the message was being recorded
 * and carried in the encrypted manifest. That is what lets the shape be on
 * screen before the audio has been fetched, which is the whole reason to draw
 * one. See `MessageAttachment.waveform`.
 */
import { useEffect, useRef, useState } from 'react';
import { VOICE_WAVEFORM_BARS, type MessageAttachment } from '@betweenus/shared-types';
import { openAttachment } from '../../services/attachments';

import { Avatar } from '../../components/Avatar';
import { PauseIcon, PlayIcon } from '../../components/icons';

/**
 * What to draw when the sender's client never measured one - audio picked off
 * a disk, or a message sent before waveforms existed.
 *
 * A gentle repeating shape rather than a flat line or random noise. Flat reads
 * as a broken file; random reads as a real waveform and is a lie about where
 * the loud parts are. This is visibly a placeholder and still gives the eye
 * something to aim a click at.
 */
const PLACEHOLDER = Array.from({ length: VOICE_WAVEFORM_BARS }, (_, index) =>
  0.35 + 0.25 * Math.sin(index / 2.2),
);

export function VoiceMessage({
  channelId,
  attachment,
  author,
  mine,
  fileName,
}: {
  channelId: string;
  attachment: MessageAttachment;
  /**
   * Shown above the player for audio that is not a recording.
   *
   * A voice note needs no label - it is somebody talking, and its name is a
   * timestamp. A track somebody chose to share is the opposite: the name is
   * most of what they were sharing.
   */
  fileName?: string;
  /** Drawn on the bubble the way every phone messenger draws a voice note. */
  author?: { displayName: string; avatarUrl: string | null };
  /** Whether this account sent it, which decides the accent. */
  mine?: boolean;
}): JSX.Element {
  const audio = useRef<HTMLAudioElement | null>(null);
  const [url, setUrl] = useState<string | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const [playing, setPlaying] = useState(false);
  const [at, setAt] = useState(0);
  /**
   * The length the element reports, once it knows one.
   *
   * Preferred over the manifest's number because it is the one the seek maths
   * has to agree with - a bar clicked at 40% has to land at 40% of what the
   * element will actually play. The manifest's value is what gets drawn before
   * there is an element at all, which is most of the time this is on screen.
   */
  const [measured, setMeasured] = useState<number | null>(null);

  /**
   * Every bar the sender measured. That they all fit - on a phone bubble as
   * well as a desktop one - is arithmetic rather than a hope: see
   * `waveform.ts` and the check beside it, which is what this feature was
   * missing the first time round.
   */
  const bars = attachment.waveform?.length ? attachment.waveform : PLACEHOLDER;
  const total = measured ?? attachment.duration ?? 0;
  const fraction = total > 0 ? Math.min(1, at / total) : 0;

  /**
   * Fetched and decrypted as soon as it is drawn, without being asked.
   *
   * A voice message is seconds long and tens of kilobytes. Making somebody
   * press a download button, wait, and then press play is three interactions
   * for something that should be one - and the button was the honest answer
   * only while the alternative was spending a video's worth of somebody's
   * connection on a message they scrolled past. That is not this.
   */
  useEffect(() => {
    let cancelled = false;
    let objectUrl: string | null = null;

    void openAttachment(channelId, attachment)
      .then((blob) => {
        if (cancelled) return;
        objectUrl = URL.createObjectURL(blob);
        setUrl(objectUrl);
      })
      .catch(() => {
        if (!cancelled) setFailure('This voice message could not be opened');
      });

    return () => {
      cancelled = true;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [channelId, attachment]);

  const toggle = (): void => {
    const element = audio.current;
    if (!element) return;
    if (element.paused) void element.play().catch(() => setFailure('That could not be played'));
    else element.pause();
  };

  /** Where in the message a click on the waveform lands. */
  const seekTo = (event: React.MouseEvent<HTMLDivElement>): void => {
    const element = audio.current;
    if (!element || total <= 0) return;
    const box = event.currentTarget.getBoundingClientRect();
    const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
    element.currentTime = ratio * total;
    setAt(element.currentTime);
  };

  const accent = mine ? 'bg-accent' : 'bg-slate-200';
  const spent = Math.round(fraction * bars.length);

  return (
    /* No card of its own. This is already inside a message bubble, and drawing
       a bordered box inside a bordered bubble is the same edge twice - which
       is exactly what it looked like: a black rectangle sitting in a purple
       one. The player is laid straight into the bubble instead. */
    <div className="mt-0.5 flex w-full items-center gap-2.5 sm:min-w-[17rem] sm:max-w-[22rem]">
      {author && (
        <Avatar name={author.displayName} avatarUrl={author.avatarUrl} size="sm" />
      )}

      <button
        type="button"
        onClick={toggle}
        disabled={!url}
        aria-label={playing ? 'Pause' : 'Play'}
        className="flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center rounded-full text-slate-100 transition-colors duration-200 disabled:cursor-progress disabled:opacity-50"
      >
        {playing ? <PauseIcon className="h-5 w-5" /> : <PlayIcon className="h-5 w-5" />}
      </button>

      <div className="min-w-0 flex-1">
        {fileName && (
          <p className="truncate text-xs text-slate-200" title={fileName}>
            {fileName}
          </p>
        )}
        {/* The waveform *is* the seek bar. A slider underneath would be the
            same axis drawn twice. */}
        <div
          role="slider"
          tabIndex={0}
          aria-label="Seek"
          aria-valuemin={0}
          aria-valuemax={Math.round(total)}
          aria-valuenow={Math.round(at)}
          onClick={seekTo}
          onKeyDown={(event) => {
            const element = audio.current;
            if (!element) return;
            if (event.key === 'ArrowLeft') element.currentTime = Math.max(0, element.currentTime - 5);
            if (event.key === 'ArrowRight') element.currentTime = Math.min(total, element.currentTime + 5);
            if (event.key === ' ' || event.key === 'Enter') {
              event.preventDefault();
              toggle();
            }
          }}
          // A one-pixel gap, not two. Forty-seven gaps at 2px eat ninety-odd
          // pixels of a bubble that is a few hundred wide, which left each bar
          // about a pixel across - drawn, and invisible.
          className="flex h-8 cursor-pointer items-center gap-px"
        >
          {bars.map((height, index) => (
            <span
              key={index}
              // `flex-1`, not `w-full`. Forty-eight siblings each asking for
              // the container's whole width shrink to sub-pixel slivers that
              // round away to nothing, which is what "the bars are missing"
              // was. An equal share of the free space is what was meant, and
              // it is the same thing Android says with `weight(1f)`.
              className={`min-w-0 flex-1 rounded-full transition-colors duration-100 ${
                // The unplayed bars have to read on two different grounds -
                // an accent-tinted bubble and a plain surface one - so they
                // are a translucent light rather than a fixed grey. A dark
                // grey vanished on both.
                index < spent ? accent : 'bg-slate-100/25'
              }`}
              // A floor in pixels as well as in the data: a bar rounded to
              // less than two pixels disappears at some zoom levels, and a
              // waveform with holes in it reads as a damaged file.
              style={{ height: `${Math.max(3, Math.round(height * 26))}px` }}
            />
          ))}
        </div>

        <div className="flex items-center gap-2 text-xs text-slate-400">
          <span className="tabular-nums">
            {/* While it is playing, how far in; otherwise how long it is.
                Both are the number somebody wants at that moment, and showing
                "0:00 / 0:07" is showing one of them twice. */}
            {formatClock(playing || at > 0 ? at : total)}
          </span>
          {failure && <span className="truncate text-danger">{failure}</span>}
          {!failure && !url && <span className="truncate">Decrypting…</span>}
        </div>
      </div>

      {url && (
        <audio
          ref={audio}
          src={url}
          preload="metadata"
          onLoadedMetadata={(event) => {
            const length = event.currentTarget.duration;
            // A stream with no seekable length reports Infinity, which is what
            // a WebM written by MediaRecorder does until it has been played
            // through once. The manifest's number covers exactly that case.
            if (Number.isFinite(length) && length > 0) setMeasured(length);
          }}
          onTimeUpdate={(event) => setAt(event.currentTarget.currentTime)}
          onPlay={() => setPlaying(true)}
          onPause={() => setPlaying(false)}
          onEnded={() => {
            setPlaying(false);
            // Back to the start, so the next press replays rather than doing
            // nothing - and so the waveform empties again.
            setAt(0);
            if (audio.current) audio.current.currentTime = 0;
          }}
          className="hidden"
        />
      )}
    </div>
  );
}

/** `m:ss`. Seconds are floored, so a message never reads one second long than it is. */
function formatClock(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  return `${Math.floor(whole / 60)}:${(whole % 60).toString().padStart(2, '0')}`;
}

/**
 * Whether a voice message's bars actually fit in the space they are drawn in.
 *
 * This is the check the original bug needed and did not have. Forty-eight bars
 * went into a couple of hundred pixels, the gaps between them ate most of the
 * width, and every bar came out about a pixel across - rendered, correct by
 * every type in the codebase, and invisible on screen. Nothing but arithmetic
 * would have caught it.
 *
 * So the arithmetic is asserted here, at both widths the player is laid out
 * at. Changing the bar count, the gap, or the size of the avatar and the play
 * button without checking the budget fails this rather than shipping a blank
 * strip.
 */
import assert from 'node:assert/strict';
import { VOICE_WAVEFORM_BARS } from '@betweenus/shared-types';
import { WAVE_LAYOUT, barWidthPx } from './waveform';

const bars = Array.from({ length: VOICE_WAVEFORM_BARS }, () => 0.5);

// --- The desktop width -----------------------------------------------------

const wide = WAVE_LAYOUT.minPlayerPx - WAVE_LAYOUT.fixedPx;
const wideBar = barWidthPx(bars.length, wide);
assert.ok(
  wideBar >= WAVE_LAYOUT.minBarPx,
  `a bar is ${wideBar.toFixed(2)}px at the narrowest desktop layout; ` +
    `below ${WAVE_LAYOUT.minBarPx}px it reads as nothing`,
);

// --- The phone width -------------------------------------------------------

const narrow = WAVE_LAYOUT.mobilePlayerPx - WAVE_LAYOUT.fixedPx;
const narrowBar = barWidthPx(bars.length, narrow);
assert.ok(
  narrowBar >= WAVE_LAYOUT.minBarPx,
  `a bar is ${narrowBar.toFixed(2)}px on a phone; below ${WAVE_LAYOUT.minBarPx}px it reads as nothing`,
);

// --- What actually bought the room -----------------------------------------
//
// The gap, not the bar count. Forty-seven gaps at the old two pixels is
// ninety-four pixels of a bubble a few hundred wide - more than half the
// waveform spent on the spaces between it. Stated as an assertion because the
// first attempt at a fix was to halve the bar count, and the arithmetic says
// that was never the problem.
const atOldGap = (narrow - (bars.length - 1) * 2) / bars.length;
assert.ok(atOldGap < WAVE_LAYOUT.minBarPx, 'the old two-pixel gap was survivable after all');
assert.ok(narrowBar > atOldGap, 'a smaller gap is what widens the bars');

// --- The formula itself ----------------------------------------------------

// Gaps are between bars, not around them: n bars have n-1 gaps.
assert.equal(barWidthPx(1, 100), 100, 'one bar has no gap to pay for');
assert.equal(barWidthPx(2, 101), 50, 'two bars share one gap');
assert.equal(barWidthPx(0, 100), 0, 'no bars, no width');

console.log('waveform: ok');

/**
 * How many bars of a voice message actually get drawn, and whether they fit.
 *
 * This exists because they did not. Forty-eight bars were rendered into a
 * couple of hundred pixels with a gap between each one, the gaps ate most of
 * the width, and every bar came out about a pixel across - drawn, present in
 * the DOM, and invisible. "The waveform is missing" was a width budget nobody
 * had done the arithmetic for.
 *
 * So the arithmetic lives here, next to a check that runs it. It is the kind
 * of layout bug that cannot be caught by types and is only ever noticed by
 * somebody looking at a screen, which is the worst way to find out.
 *
 * No imports on purpose: this is arithmetic, and keeping it free of app wiring
 * means it also runs under Node for `pnpm --filter @betweenus/desktop check`.
 */

/**
 * The pixel budget the player is laid out in, as the stylesheet spends it.
 *
 * Kept as numbers rather than read back off the DOM: the point is to be able
 * to assert on the layout without a browser, and these are the values the
 * classes in `VoiceMessage.tsx` compile to. If one is changed there, the check
 * beside this fails - which is the entire reason to write them down twice.
 */
export const WAVE_LAYOUT = {
  /** `sm:min-w-[17rem]` on the player. The narrowest it is ever laid out at. */
  minPlayerPx: 17 * 16,
  /** What a phone bubble realistically leaves, at `max-w-[78%]` of a 360px screen. */
  mobilePlayerPx: Math.floor(360 * 0.78) - 24,
  /** `h-8 w-8` avatar, `h-9 w-9` play button, and two `gap-2.5` between them. */
  fixedPx: 32 + 36 + 10 + 10,
  /** `gap-px` between bars. */
  gapPx: 1,
  /** Below this a bar is a hairline that reads as nothing at all. */
  minBarPx: 2,
} as const;

/**
 * The width one bar ends up with, given how many are drawn in what space.
 *
 * Flexbox with `flex-1` on every bar shares the leftover space equally, which
 * is what this computes - and is why the bars use `flex-1` rather than
 * `w-full`. Forty-eight items each asking for the container's *whole* width
 * shrink to slivers instead; that was the original bug.
 */
export function barWidthPx(count: number, availablePx: number): number {
  if (count <= 0) return 0;
  const gaps = (count - 1) * WAVE_LAYOUT.gapPx;
  return (availablePx - gaps) / count;
}

import { useState } from 'react';
import type { Friend } from '@betweenus/shared-types';
import { useFriendsStore } from '../../stores/friends';
import { usePresenceStore, useStatusOf } from '../../stores/presence';
import { Avatar } from '../../components/Avatar';
import {
  BlockIcon,
  CheckIcon,
  MenuIcon,
  MessageIcon,
  UserPlusIcon,
  UsersIcon,
  XIcon,
} from '../../components/icons';
import { EmptyState, SkeletonRows } from '../../components/Skeleton';
import { listState } from '../../services/list-state';

type Tab = 'online' | 'all' | 'pending' | 'add';

const TABS: Array<{ id: Tab; label: string }> = [
  { id: 'online', label: 'Online' },
  { id: 'all', label: 'All' },
  { id: 'pending', label: 'Pending' },
];

/** Discord's friends screen: the tabs, and the "add friend" form behind one. */
export function FriendsView({ onOpenMenu }: { onOpenMenu?: () => void } = {}): JSX.Element {
  const [tab, setTab] = useState<Tab>('online');
  const friends = useFriendsStore((state) => state.friends);
  const loading = useFriendsStore((state) => state.loading);
  const isOnline = usePresenceStore((state) => state.online);

  const accepted = friends.filter((friend) => friend.status === 'ACCEPTED');
  const pending = friends.filter((friend) => friend.status === 'PENDING');
  const online = accepted.filter((friend) => isOnline.has(friend.user.id));

  const shown = tab === 'online' ? online : tab === 'all' ? accepted : pending;

  return (
    <section className="panel flex min-w-0 flex-1 flex-col bg-surface-900">
      {/* Mobile Header (md:hidden) */}
      <header className="flex h-12 shrink-0 items-center justify-between border-b border-edge px-2.5 md:hidden">
        <div className="flex items-center gap-2">
          {onOpenMenu && (
            <button
              type="button"
              onClick={onOpenMenu}
              aria-label="Open navigation menu"
              title="Open menu"
              className="flex h-9 w-9 min-h-[44px] min-w-[44px] cursor-pointer items-center justify-center rounded-md text-slate-300 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
            >
              <MenuIcon className="h-5 w-5" />
            </button>
          )}
          <span className="flex items-center gap-2 font-semibold text-slate-50 text-[15px]">
            <UsersIcon className="h-5 w-5 text-accent" />
            Friends
          </span>
        </div>

        <button
          type="button"
          onClick={() => setTab('add')}
          aria-selected={tab === 'add'}
          className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold transition-colors duration-200 ${
            tab === 'add'
              ? 'bg-status-online text-white shadow-sm'
              : 'bg-status-online/15 text-status-online hover:bg-status-online/25'
          }`}
        >
          <UserPlusIcon className="h-3.5 w-3.5" />
          <span>Add friend</span>
        </button>
      </header>

      {/* Mobile Tab Strip (md:hidden) */}
      <div
        role="tablist"
        aria-label="Friends"
        className="flex items-center gap-1.5 border-b border-edge/60 bg-surface-950/40 px-2.5 py-2 overflow-x-auto no-scrollbar md:hidden"
      >
        {TABS.map((entry) => (
          <button
            key={entry.id}
            type="button"
            role="tab"
            aria-selected={tab === entry.id}
            onClick={() => setTab(entry.id)}
            className={`min-h-[36px] cursor-pointer whitespace-nowrap rounded-lg px-3 py-1.5 text-xs font-medium transition-colors duration-200 shrink-0 ${
              tab === entry.id
                ? 'bg-surface-700 text-slate-100 shadow-sm'
                : 'text-slate-400 hover:bg-white/[0.05] hover:text-slate-200'
            }`}
