            {entry.label}
            {entry.id === 'pending' && pending.length > 0 && (
              <span className="ms-1.5 rounded-full bg-danger px-1.5 py-0.2 text-[10px] font-bold text-white">
                {pending.length}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Desktop Header (hidden md:flex) */}
