              type="button"
              role="tab"
              aria-selected={tab === entry.id}
              onClick={() => setTab(entry.id)}
              className={`cursor-pointer whitespace-nowrap rounded px-2.5 py-1 text-sm transition-colors duration-200 shrink-0 ${
