function FriendList({
  friends,
  tab,
  loading,
}: {
  friends: Friend[];
  tab: Tab;
  loading: boolean;
}): JSX.Element {
  const statusOf = useStatusOf();
  const accept = useFriendsStore((state) => state.accept);
  const remove = useFriendsStore((state) => state.remove);
  const block = useFriendsStore((state) => state.block);
  const openDirect = useFriendsStore((state) => state.openDirect);

  // The list is empty before the fetch answers *and* when there is genuinely
  // nobody, and this screen used to say the second every time it opened - an
  // account with forty friends was told "No friends yet. Add someone by their
  // username." for as long as the round trip took.
  const state = listState(friends.length, loading);

  if (state === 'loading') {
    return <SkeletonRows rows={6} label="Loading friends" className="flex-1 px-4 sm:px-6 py-4" />;
  }

  if (state === 'empty') {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <EmptyState
          icon={<UsersIcon className="h-10 w-10" />}
          title={
            tab === 'pending'
              ? 'No pending requests'
              : tab === 'online'
                ? 'Nobody is around right now'
                : 'No friends yet'
          }
          hint={
            tab === 'pending'
              ? 'When someone asks, they will be here.'
              : tab === 'online'
                ? 'The All tab has everybody, online or not.'
                : 'Add someone by their username on the Add friend tab.'
          }
        />
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-6 py-4">
      <p className="mb-3 text-xs font-bold uppercase tracking-wide text-slate-400">
        {tab === 'pending' ? 'Pending' : tab === 'online' ? 'Online' : 'All friends'} —{' '}
        {friends.length}
      </p>

      <ul>
        {friends.map((friend) => (
          <li
            key={friend.user.id}
            className="flex items-center gap-3 border-t border-surface-700/60 py-3 first:border-t-0"
          >
            <Avatar
              name={friend.user.displayName}
              avatarUrl={friend.user.avatarUrl}
              status={statusOf(friend.user.id)}
              ringColour="border-surface-900"
            />
            <div className="min-w-0 flex-1">
              <p className="truncate font-semibold text-slate-100">{friend.user.displayName}</p>
              <p className="truncate text-sm text-slate-400">
                @{friend.user.username}
                {friend.direction === 'incoming' && ' · Incoming request'}
                {friend.direction === 'outgoing' && ' · Request sent'}
              </p>
            </div>

            <div className="flex shrink-0 items-center gap-1.5 sm:gap-2">
              {friend.status === 'ACCEPTED' && (
                <IconButton
                  label={`Message ${friend.user.displayName}`}
                  onClick={() => void openDirect(friend.user.id)}
                >
                  <MessageIcon className="h-5 w-5" />
                </IconButton>
              )}
              {friend.direction === 'incoming' && (
                <IconButton
                  label={`Accept ${friend.user.displayName}`}
                  onClick={() => void accept(friend.user.id)}
                  hoverClasses="hover:text-status-online"
                >
                  <CheckIcon className="h-5 w-5" />
                </IconButton>
              )}
              <IconButton
                label={
                  friend.status === 'ACCEPTED'
                    ? `Remove ${friend.user.displayName}`
                    : `Cancel request to ${friend.user.displayName}`
                }
                onClick={() => void remove(friend.user.id)}
                hoverClasses="hover:text-danger"
              >
                <XIcon className="h-5 w-5" />
              </IconButton>
              <IconButton
                label={`Block ${friend.user.displayName}`}
                onClick={() => {
                  // Confirmed, because it is not the same button as Remove: it
                  // ends the friendship *and* closes the conversation, and
                  // neither side can start it again while it stands.
                  if (
                    !confirm(
                      `Block ${friend.user.displayName}?\n\n` +
                        'They will not be able to message you or send a request, and your ' +
                        'conversation disappears for both of you. Nothing is deleted - ' +
                        'unblocking brings it back. You can undo this in Settings.',
                    )
                  ) {
                    return;
                  }
                  void block(friend.user.id);
                }}
                hoverClasses="hover:text-danger"
              >
                <BlockIcon className="h-5 w-5" />
              </IconButton>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

function AddFriend(): JSX.Element {
  const search = useFriendsStore((state) => state.search);
  const results = useFriendsStore((state) => state.searchResults);
  const add = useFriendsStore((state) => state.add);
  const error = useFriendsStore((state) => state.error);

  const [query, setQuery] = useState('');
  const [sent, setSent] = useState<string | null>(null);

  const send = async (username: string): Promise<void> => {
    setSent(null);
    try {
      await add(username);
      setSent(username);
    } catch {
      // The store already carries the reason; nothing to add here.
    }
  };

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-8 py-6">
      <h2 className="text-base font-bold uppercase tracking-wide text-slate-100">Add friend</h2>
      <p className="mt-1 text-sm text-slate-400">
        You can add a friend with their BetweenUs username.
      </p>

      <div className="mt-4 flex flex-col sm:flex-row items-stretch sm:items-center gap-2 rounded-lg border border-edge bg-surface-950 p-2 sm:px-4 sm:py-2.5 transition-colors focus-within:border-accent/60">
        <input
          value={query}
          autoFocus
          onChange={(event) => {
            setQuery(event.target.value);
            void search(event.target.value);
          }}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && query.trim()) void send(query.trim());
          }}
          placeholder="Enter a username"
          aria-label="Username"
          className="flex-1 bg-transparent px-2 py-1 sm:p-0 text-slate-100 placeholder-slate-500 focus:outline-none min-h-[36px]"
        />
        <button
          type="button"
          disabled={query.trim().length === 0}
          onClick={() => void send(query.trim())}
          className="cursor-pointer rounded bg-accent px-4 py-2 sm:py-1.5 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:opacity-40 min-h-[40px] sm:min-h-0"
        >
          Send request
        </button>
      </div>

      {sent && (
        <p role="status" className="mt-3 text-sm text-status-online">
          Request sent to {sent}.
        </p>
      )}
      {error && (
        <p role="alert" className="mt-3 text-sm text-danger">
          {error}
        </p>
      )}

      {results.length > 0 && (
        <>
          <p className="mt-8 text-xs font-bold uppercase tracking-wide text-slate-400">
            Matching people
          </p>
          <ul className="mt-2">
            {results.map((person) => (
              <li
                key={person.id}
                className="flex items-center gap-3 border-t border-surface-700/60 py-3 first:border-t-0"
              >
                <Avatar
                  name={person.displayName}
                  avatarUrl={person.avatarUrl}
                  ringColour="border-surface-900"
                />
                <div className="min-w-0 flex-1">
                  <p className="truncate font-semibold text-slate-100">{person.displayName}</p>
                  <p className="truncate text-sm text-slate-400">@{person.username}</p>
                </div>
                <IconButton
                  label={`Send a request to ${person.displayName}`}
                  onClick={() => void send(person.username)}
                  hoverClasses="hover:text-status-online"
                >
                  <UserPlusIcon className="h-5 w-5" />
                </IconButton>
              </li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

function IconButton({
  label,
  onClick,
  children,
  hoverClasses = 'hover:text-slate-50',
}: {
  label: string;
  onClick: () => void;
  children: React.ReactNode;
  hoverClasses?: string;
}): JSX.Element {
  return (
    <button
      type="button"
      onClick={onClick}
      title={label}
      aria-label={label}
      className={`flex min-h-[40px] min-w-[40px] items-center justify-center cursor-pointer rounded-full bg-surface-850 p-2.5 text-slate-300 transition-colors duration-200 hover:bg-white/[0.06] ${hoverClasses}`}
    >
      {children}
    </button>
  );
}

import { useChatStore } from '../../stores/chat';
import { useFriendsStore } from '../../stores/friends';
import { useStatusOf } from '../../stores/presence';
import { runsOf, useStatusStore } from '../../stores/status';
import { isDesktopRuntime } from '../../services/platform';
import { UserPanel } from '../settings/UserPanel';
import { VoicePanel } from '../voice/VoicePanel';
import { Avatar } from '../../components/Avatar';
import { ActivityIcon, MonitorIcon, UsersIcon, XIcon } from '../../components/icons';
import { SkeletonRows } from '../../components/Skeleton';
import { listState } from '../../services/list-state';

/**
 * The home sidebar: the Friends screen at the top, then one row per open
 * conversation. Closing a conversation only hides it - the messages stay, and
 * it comes back the moment anything new arrives in it.
 */
export function HomeSidebar({
  showingFriends,
  onShowFriends,
  showingStatus,
  onShowStatus,
  showingRemote,
  onShowRemote,
  onOpenUserSettings,
  className = 'w-60',
}: {
  showingFriends: boolean;
  onShowFriends: () => void;
  showingStatus: boolean;
  onShowStatus: () => void;
  showingRemote: boolean;
  onShowRemote: () => void;
  onOpenUserSettings: () => void;
  className?: string;
}): JSX.Element {
  const directChannels = useFriendsStore((state) => state.directChannels);
  // Same fetch as the friends screen, and the same lie it used to tell: "No
  // conversations yet. Add a friend and start one." to somebody with twelve.
  const directsState = listState(
    directChannels.length,
    useFriendsStore((state) => state.loading),
  );
  const openDirect = useFriendsStore((state) => state.openDirect);
  const activeChannelId = useChatStore((state) => state.activeChannelId);
  const unread = useChatStore((state) => state.unread);
  const statusOf = useStatusOf();
  const pending = useFriendsStore((state) =>
    state.friends.filter((friend) => friend.direction === 'incoming').length,
  );
  // How many people have something unwatched. The same number the ring says,
  // counted per person rather than per post: what the badge is answering is
  // "is there anybody to catch up on", not "how many pictures are there".
  const unwatched = useStatusStore((state) => runsOf(state).filter((run) => run.unseen).length);

  return (
    <aside className={`panel flex shrink-0 flex-col bg-surface-800 ${className}`}>
      <header className="flex h-11 shrink-0 items-center border-b border-edge px-3">
        <h2 className="text-xs font-semibold uppercase tracking-[0.08em] text-slate-400">
          Messages
        </h2>
      </header>

      <nav aria-label="Direct messages" className="min-h-0 flex-1 overflow-y-auto px-2 py-2">
        <button
          type="button"
          onClick={onShowFriends}
          aria-current={showingFriends ? 'page' : undefined}
          className={`flex w-full cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-start transition-colors duration-200 ${
            showingFriends
              ? 'row-active'
              : 'row-idle'
          }`}
        >
          <UsersIcon className="h-5 w-5 shrink-0" />
          <span className="flex-1 font-medium">Friends</span>
          {pending > 0 && (
            <span className="rounded-full bg-danger px-1.5 text-xs font-bold text-white">
              {pending}
              <span className="sr-only"> pending requests</span>
            </span>
          )}
        </button>

        {/* Statuses sit under Friends rather than in the conversation list:
            they are a place to go, not a conversation, and a row that came and
            went as people posted would move the list under somebody's cursor. */}
        <button
          type="button"
          onClick={onShowStatus}
          aria-current={showingStatus ? 'page' : undefined}
          className={`mt-0.5 flex w-full cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-start transition-colors duration-200 ${
            showingStatus ? 'row-active' : 'row-idle'
          }`}
        >
          <ActivityIcon className="h-5 w-5 shrink-0" />
          <span className="flex-1 font-medium">Moments</span>
          {unwatched > 0 && (
            <span className="rounded-full bg-status-online px-1.5 text-xs font-bold text-surface-900">
              {unwatched}
              <span className="sr-only"> people with new updates</span>
            </span>
          )}
        </button>

        {/* Machines sit beside people on purpose: reaching your desktop is the
            same kind of thing as opening a conversation with someone.

            Not in a browser tab, though: remote desktop is a desktop-app
            section end to end - the agent that offers a machine is the Electron
            main process - so the web client does not advertise a door it cannot
            open. See services/platform.ts. */}
        {isDesktopRuntime() && (
          <button
            type="button"
            onClick={onShowRemote}
            aria-current={showingRemote ? 'page' : undefined}
            className={`mt-0.5 flex w-full cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-start transition-colors duration-200 ${
              showingRemote
                ? 'row-active'
                : 'row-idle'
            }`}
          >
            <MonitorIcon className="h-5 w-5 shrink-0" />
            <span className="flex-1 font-medium">Remote machines</span>
          </button>
        )}

        <p className="px-2 pb-1 pt-5 text-xs font-bold uppercase tracking-wide text-slate-400">
          Direct messages
        </p>

        <div className="space-y-0.5">
          {directsState === 'loading' && (
            <SkeletonRows rows={4} label="Loading conversations" className="px-2 py-2" />
          )}
          {directsState === 'empty' && (
            <p className="px-2 py-2 text-sm text-slate-500">
              No conversations yet. Add a friend and start one.
            </p>
          )}
          {directChannels.map((direct) => {
            const active = !showingFriends && direct.channelId === activeChannelId;
            const count = unread[direct.channelId] ?? 0;
            return (
              <button
                key={direct.channelId}
                type="button"
                onClick={() => void openDirect(direct.participant.id)}
                aria-current={active ? 'page' : undefined}
                className={`group flex w-full cursor-pointer items-center gap-3 rounded-md px-2 py-1.5 text-start transition-colors duration-200 ${
                  active
                    ? 'row-active'
                    : 'row-idle'
                }`}
              >
                <Avatar
                  name={direct.participant.displayName}
                  avatarUrl={direct.participant.avatarUrl}
                  status={statusOf(direct.participant.id)}
                  size="sm"
                  ringColour="border-surface-800"
                />
                <span className={`flex-1 truncate ${count ? 'font-semibold text-white' : ''}`}>
                  {direct.participant.displayName}
                </span>
                {count > 0 ? (
                  <span className="rounded-full bg-danger px-1.5 text-xs font-bold text-white">
                    {count}
                    <span className="sr-only"> unread messages</span>
                  </span>
                ) : (
                  <XIcon className="h-4 w-4 opacity-0 transition-opacity group-hover:opacity-60" />
                )}
              </button>
            );
          })}
        </div>
      </nav>

      {/* A call started in a server keeps running while you read a direct
          message, so its controls have to be reachable from here too. */}
      <VoicePanel />
      <UserPanel onOpenSettings={onOpenUserSettings} />
    </aside>
  );
}

