import { useEffect, useState } from 'react';
import type { PresenceStatus, ServerMember, ServerRole } from '@betweenus/shared-types';
import { useChatStore } from '../../stores/chat';
import { useFriendsStore } from '../../stores/friends';
import { usePresenceStore, useStatusOf } from '../../stores/presence';
import { useAuthStore } from '../../stores/auth';
import { Avatar } from '../../components/Avatar';
import { ProfileHover } from '../../components/ProfileCard';
import {
  isUserMuted,
  onPreferencesChanged,
  setUserMuted,
} from '../../services/notifications';
import { api } from '../../services/api';
import { useVoiceStore } from '../../stores/voice';
import { UsersIcon, XIcon } from '../../components/icons';
import { EmptyState, SkeletonRows } from '../../components/Skeleton';
import { listState } from '../../services/list-state';
import { SafetyNumberDialog } from './SafetyNumberDialog';

export interface MemberListProps {
  onClose?: () => void;
  className?: string;
}

/**
 * The right-hand column in a server: who is here, online first. Members are
 * grouped by built-in role the way Discord groups by hoisted role - a server
 * this size does not need a section per custom role. A custom role does show
 * here, though, in the one place it is worth a whole column: the name is drawn
 * in the colour of the highest-ranked role its holder has, which is the answer
 * the server already works out and sends as `colour`.
 */
export function MemberList({
  onClose,
  className = 'w-60 shrink-0 flex',
}: MemberListProps = {}): JSX.Element {
  const members = useChatStore((state) => state.members);
  const online = usePresenceStore((state) => state.online);
  const statusOf = useStatusOf();
  const [menu, setMenu] = useState<{ member: ServerMember; at: { x: number; y: number } } | null>(
    null,
  );
  const [verifying, setVerifying] = useState<ServerMember | null>(null);
  const channelId = useChatStore((state) => state.activeChannelId);

  // A server that has not answered yet has no members, and so does a server
  // with nobody in it. This column used to draw the second while the first was
  // true - and drew it as an empty column with a heading that said "Members —
  // 0", which is a statement rather than a wait.
  const loading = useChatStore((state) => state.loadingServer);
  const state = listState(members.length, loading);

  const here = members.filter((member) => online.has(member.userId));
  const away = members.filter((member) => !online.has(member.userId));

  const staff = here.filter((member) => isStaff(member.role));
  const rest = here.filter((member) => !isStaff(member.role));

  return (
    <aside
      aria-label="Members"
      className={`panel flex flex-col bg-surface-800 ${className}`}
    >
      <header className="flex h-12 shrink-0 items-center gap-2 border-b border-edge px-3">
        <UsersIcon className="h-4 w-4 text-slate-400" />
        <h2 className="flex-1 text-sm font-semibold text-slate-100">
          {state === 'loading' ? 'Members' : `Members — ${members.length}`}
        </h2>
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            aria-label="Close member list"
            className="flex h-8 w-8 min-h-[44px] min-w-[44px] sm:min-h-0 sm:min-w-0 sm:h-7 sm:w-7 cursor-pointer items-center justify-center rounded-md p-1 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
          >
            <XIcon className="h-4 w-4" />
          </button>
        )}
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto px-2 py-4">
        {state === 'loading' && <SkeletonRows rows={6} label="Loading members" className="px-2" />}

        {state === 'empty' && (
          <EmptyState
            title="Nobody here yet"
            hint="Invite somebody from the server menu and they will show up in this column."
          />
        )}

        <Group label={`Admins — ${staff.length}`} members={staff} statusOf={statusOf} onOpen={setMenu} />
        <Group label={`Online — ${rest.length}`} members={rest} statusOf={statusOf} onOpen={setMenu} />
        <Group
          label={`Offline — ${away.length}`}
          members={away}
          statusOf={statusOf}
          muted
          onOpen={setMenu}
        />
      </div>

      {menu && (
        <MemberMenu
          member={menu.member}
          at={menu.at}
          onClose={() => setMenu(null)}
          onVerify={(member) => {
            setMenu(null);
            setVerifying(member);
          }}
        />
      )}

      {/* The directory read the dialog needs is scoped to a channel, so there
          is nothing to show without one. In this column there always is one. */}
      {verifying && channelId && (
        <SafetyNumberDialog
          userId={verifying.userId}
          displayName={verifying.displayName}
          channelId={channelId}
          onClose={() => setVerifying(null)}
        />
      )}
    </aside>
  );
}

function Group({
  label,
  members,
  statusOf,
  muted = false,
  onOpen,
}: {
  label: string;
  members: ServerMember[];
  statusOf: (userId: string) => PresenceStatus;
  muted?: boolean;
  onOpen: (menu: { member: ServerMember; at: { x: number; y: number } }) => void;
}): JSX.Element | null {
  if (members.length === 0) return null;

  return (
    <>
      <p className="px-2 pb-1 pt-4 text-xs font-bold uppercase tracking-wide text-slate-400 first:pt-0">
        {label}
      </p>
      <ul>
        {members.map((member) => (
          <li key={member.userId}>
            {/* Resting on the row opens the card; the click and the right
                click still open the menu of things to *do* about the person.
                Two gestures, two questions - "who is this" wants no click at
                all, and "message them" was never going to be answered by
                hovering. */}
            <ProfileHover
              person={{
                userId: member.userId,
                displayName: member.displayName,
                username: member.username,
                avatarUrl: member.avatarUrl,
                coverUrl: member.coverUrl,
                about: member.about,
                colour: member.colour,
              }}
            >
            <div
              onContextMenu={(event) => {
                event.preventDefault();
                onOpen({ member, at: { x: event.clientX, y: event.clientY } });
              }}
              onClick={(event) =>
                onOpen({ member, at: { x: event.clientX, y: event.clientY } })
              }
              className={`flex min-h-[44px] sm:min-h-0 cursor-pointer items-center gap-3 rounded-md px-2 py-1.5 transition-colors duration-200 hover:bg-white/[0.05] ${
                muted ? 'opacity-40' : ''
              }`}
            >
              <Avatar
                name={member.displayName}
                avatarUrl={member.avatarUrl}
                status={statusOf(member.userId)}
                size="sm"
                ringColour="border-surface-800"
              />
              <span className="min-w-0 flex-1">
                <span
                  className="block truncate text-[15px] text-slate-200"
                  style={member.colour ? { color: member.colour } : undefined}
                >
                  {member.displayName}
                </span>
                {isStaff(member.role) && (
                  <span className="block truncate text-xs text-slate-500">
                    {member.role.toLowerCase()}
                  </span>
                )}
              </span>
            </div>
            </ProfileHover>
          </li>
        ))}
      </ul>
    </>
  );
}

function isStaff(role: ServerRole): boolean {
  return role === 'OWNER' || role === 'ADMIN' || role === 'MODERATOR';
}

/**
 * What you can do about one person, from the column that lists them.
 *
 * A member list that only draws names is a member list you have to leave to act
 * on: a direct message is on the friends screen, a friend request is on the
 * search, and muting one loud person was not anywhere at all. Everything here
 * is about the person rather than the server - moderation stays in server
 * settings, where the permission that allows it is also explained.
 */
function MemberMenu({
  member,
  at,
  onClose,
  onVerify,
}: {
  member: ServerMember;
  at: { x: number; y: number };
  onClose: () => void;
  onVerify: (member: ServerMember) => void;
}): JSX.Element | null {
  const me = useAuthStore((state) => state.user);
  const friends = useFriendsStore((state) => state.friends);
  const addFriend = useFriendsStore((state) => state.add);
  const openDirect = useFriendsStore((state) => state.openDirect);
  // The call this person is in right now, if any. Ringing somebody into a call
  // you are not in is a message about a room you have not entered - so the
  // action only exists while there is a call to pull them into.
  const call = useVoiceStore((state) => (state.status === 'idle' ? null : state.channelId));
  const callName = useVoiceStore((state) => state.channelName);
  const inCall = usePresenceStore((state) =>
    call ? (state.voice.get(call) ?? []).includes(member.userId) : false,
  );
  const [muted, setMuted] = useState(() => isUserMuted(member.userId));
  const [note, setNote] = useState<string | null>(null);

  useEffect(() => onPreferencesChanged(() => setMuted(isUserMuted(member.userId))), [member.userId]);

  useEffect(() => {
    const away = (event: MouseEvent): void => {
      if (!(event.target as HTMLElement).closest('[data-member-menu]')) onClose();
    };
    const escape = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    const timer = window.setTimeout(() => document.addEventListener('mousedown', away), 0);
    document.addEventListener('keydown', escape);
    return () => {
      window.clearTimeout(timer);
      document.removeEventListener('mousedown', away);
      document.removeEventListener('keydown', escape);
    };
  }, [onClose]);

  // Nothing here applies to yourself: you cannot befriend, mute or message you.
  if (member.userId === me?.id) return null;

  const relationship = friends.find((friend) => friend.user.id === member.userId);
  const width = 224;
  const left = Math.min(at.x, window.innerWidth - width - 8);
  const top = Math.min(at.y, window.innerHeight - 200);

  const act = (work: Promise<unknown>, said: string): void => {
    void work
      .then(() => {
        setNote(said);
        window.setTimeout(onClose, 700);
      })
      .catch((error: unknown) => {
        setNote(error instanceof Error ? error.message : 'That did not work');
      });
  };

  return (
    <div
      data-member-menu
      role="menu"
      aria-label={`Actions for ${member.displayName}`}
      style={{ left, top, width }}
      className="fixed z-50 animate-pop overflow-hidden rounded-xl border border-edge bg-surface-900 py-1 shadow-pop"
    >
      <p className="truncate px-3 py-1.5 text-xs text-slate-500">@{member.username}</p>

      {/* A direct message needs a friendship, and the service says so - which
          is why this reports rather than assuming it worked. */}
      <Item
        label="Message"
        onClick={() =>
          act(openDirect(member.userId), 'Opening the conversation')
        }
      />

      {/* A friendship is what a direct message needs, so it is offered right
          beside it. Somebody already asked, or already accepted, is told which
          rather than offered a button that does nothing. */}
      {!relationship && (
        <Item
          label="Add friend"
          onClick={() => act(addFriend(member.username), 'Request sent')}
        />
      )}
      {relationship?.direction === 'outgoing' && <Item label="Friend request sent" disabled />}
      {relationship?.direction === 'incoming' && (
        <Item
          label="Accept friend request"
          onClick={() => act(addFriend(member.username), 'Friends')}
        />
      )}

      {/* Discord's "invite to voice channel", and the reason the ring exists at
          all: the roster announcement tells a whole channel that a call is
          happening, which is why it may not ring anybody's phone. This is
          aimed at one person, so it may. */}
      {call && !inCall && (
        <Item
          label={callName ? `Ring into ${callName}` : 'Ring into the call'}
          hint="Rings them, wherever they are signed in"
          onClick={() => act(api.callRing(call, member.userId), 'Ringing them')}
        />
      )}
      {call && inCall && <Item label="Already in the call" disabled />}

      <Item
        label={muted ? 'Unmute notifications' : 'Mute notifications'}
        hint={muted ? undefined : 'Silences them wherever they write, including mentions'}
        onClick={() => act(setUserMuted(member.userId, !muted), muted ? 'Unmuted' : 'Muted')}
      />

      {/* The only thing in this app that catches a server lying about a public
          key, which is why it sits with the everyday actions rather than
          somewhere in settings nobody opens. */}
      <Item
        label="Verify safety number"
        hint="Compare sixty digits with them, over something that is not this app"
        onClick={() => onVerify(member)}
      />

      <Item
        label="Copy user ID"
        onClick={() => {
          void navigator.clipboard?.writeText(member.userId);
          onClose();
        }}
      />

      {note && <p className="px-3 py-1.5 text-xs text-slate-400">{note}</p>}
    </div>
  );
}

function Item({
  label,
  hint,
  onClick,
  disabled = false,
}: {
  label: string;
  hint?: string;
  onClick?: () => void;
  disabled?: boolean;
}): JSX.Element {
  return (
    <button
      type="button"
      role="menuitem"
      disabled={disabled}
      onClick={onClick}
      title={hint}
      className={`block w-full px-3 py-1.5 text-start text-sm transition-colors duration-150 ${
        disabled
          ? 'cursor-not-allowed text-slate-500'
          : 'cursor-pointer text-slate-200 hover:bg-white/[0.07] hover:text-slate-100'
      }`}
    >
      {label}
    </button>
  );
}

import { useEffect, useState } from 'react';
import { useAuthStore } from '../../stores/auth';
import { api } from '../../services/api';
import {
  formatSafetyNumber,
  identityMaterial,
  safetyNumber,
  userFingerprint,
} from '../../services/safety-numbers';
import {
  clearVerified,
  markVerified,
  verificationOf,
  type VerificationState,
} from '../../services/safety-verification';
import { ShieldIcon, XIcon } from '../../components/icons';

/**
 * The screen where two people check they hold each other's real keys.
 *
 * Everything else in the encryption design protects a message from whoever
 * reads the database. This is the only part that protects against the server
 * *lying about a public key*, and it is the only part that cannot be done by
 * software alone: the comparison has to happen over a channel the server does
 * not control - a phone call, a room, anything but this app.
 *
 * So the dialog's job is not to compute the number. It is to make the
 * comparison something a person will actually do: sixty digits, grouped the way
 * they are read aloud, with a plain sentence about what a mismatch means.
 */
export function SafetyNumberDialog({
  userId,
  displayName,
  channelId,
  onClose,
}: {
  userId: string;
  displayName: string;
  channelId: string;
  onClose: () => void;
}): JSX.Element {
  const me = useAuthStore((state) => state.user);
  const [digits, setDigits] = useState<string | null>(null);
  const [theirs, setTheirs] = useState('');
  const [state, setState] = useState<VerificationState>('unverified');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let live = true;

    void (async () => {
      try {
        // The same directory read the channel already does. There is no
        // endpoint that answers "this one person's keys", on purpose: asking
        // about somebody through a channel you share is a question you are
        // already entitled to ask, and a per-user lookup would be a new one.
        const devices = await api.channelDevices(channelId);
        const mine = devices.filter((device) => device.userId === me?.id);
        const them = devices.filter((device) => device.userId === userId);

        const [ours, yours] = await Promise.all([
          userFingerprint(me?.id ?? '', await identityMaterial(mine)),
          userFingerprint(userId, await identityMaterial(them)),
        ]);
        if (!live) return;

        setTheirs(yours);
        setDigits(safetyNumber(ours, yours));
        setState(verificationOf(userId, yours));
      } catch (problem) {
        if (!live) return;
        setError(problem instanceof Error ? problem.message : 'Could not read the key directory');
        setDigits('');
      }
    })();

    return () => {
      live = false;
    };
  }, [channelId, me?.id, userId]);

  return (
    <div className="fixed inset-0 z-50 flex animate-fade items-center justify-center bg-black/60 px-4">
      <div className="w-full max-w-md animate-pop rounded-xl border border-edge bg-surface-900 shadow-pop">
        <header className="flex items-center gap-3 border-b border-edge px-5 py-4">
          <ShieldIcon className="h-5 w-5 text-accent" />
          <div className="min-w-0 flex-1">
            <h2 className="truncate text-lg font-semibold text-slate-50">Safety number</h2>
            <p className="truncate text-xs text-slate-400">You and {displayName}</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="cursor-pointer rounded-md p-1 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
          >
            <XIcon className="h-4 w-4" />
          </button>
        </header>

        <div className="px-5 py-4">
          {state === 'changed' && (
            <p
              role="alert"
              className="mb-4 rounded-md bg-amber-500/10 px-3 py-2 text-sm text-amber-200"
            >
              This number has changed since you last checked it. That happens
              when {displayName} adds or removes a device — and it is also what
              it would look like if somebody replaced their key. There is no way
              to tell those apart from here, so check the new number with them
              before you trust it.
            </p>
          )}

          {error && (
            <p role="alert" className="mb-4 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
              {error}
            </p>
          )}

          {digits === null && <p className="py-6 text-center text-sm text-slate-400">Working it out…</p>}

          {digits === '' && !error && (
            <p className="py-6 text-center text-sm text-slate-400">
              {displayName} has not published a device key yet, so there is
              nothing to compare. Their messages cannot be sealed for them
              either — this is the same thing seen from another angle.
            </p>
          )}

          {digits && (
            <>
              <pre className="select-text rounded-lg bg-surface-850 px-4 py-4 text-center font-mono text-base leading-8 tracking-[0.15em] text-slate-100">
                {formatSafetyNumber(digits)}
              </pre>

              <p className="mt-4 text-sm text-slate-400">
                Read these digits to {displayName} over something that is not
                this app — a phone call, or in person. If they see the same
                sixty digits, nobody is between you.
              </p>

              <div className="mt-4 flex gap-2">
                {state === 'verified' ? (
                  <button
                    type="button"
                    onClick={() => {
                      clearVerified(userId);
                      setState('unverified');
                    }}
                    className="cursor-pointer rounded bg-surface-700 px-4 py-2 text-sm text-slate-100 transition-colors duration-200 hover:bg-white/[0.1]"
                  >
                    Mark as unverified
                  </button>
                ) : (
                  <button
                    type="button"
                    onClick={() => {
                      markVerified(userId, theirs);
                      setState('verified');
                    }}
                    className="cursor-pointer rounded bg-accent px-4 py-2 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98]"
                  >
                    They match
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => void navigator.clipboard?.writeText(formatSafetyNumber(digits))}
                  className="cursor-pointer rounded bg-surface-700 px-4 py-2 text-sm text-slate-200 transition-colors duration-200 hover:bg-white/[0.1]"
                >
                  Copy
                </button>
              </div>

              {state === 'verified' && (
                <p className="mt-3 text-xs text-emerald-300">
                  Verified on this machine. Verification is not shared with the
                  server or with your other devices — a server that could set it
                  could also lie about the key it applies to.
                </p>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { useAgentStore } from '../../services/remote-agent';
import { MonitorIcon } from '../../components/icons';

/**
 * "NAME wants to connect to this machine."
 *
 * Shown only when the person asking is not the machine's owner. The owner
 * reaching their own desktop from another device is the case remote access
 * exists for, and making them walk over and click yes would defeat it - a grant
 * to anyone else is permission to ask, not permission to start.
 *
 * Nothing is captured until this is answered, and not answering refuses.
 */
export function RemoteConsent(): JSX.Element | null {
  const pending = useAgentStore((state) => state.pending);
  const accept = useAgentStore((state) => state.accept);
  const refuse = useAgentStore((state) => state.refuse);
  const session = useAgentStore((state) => state.session);
  const controlRequest = useAgentStore((state) => state.controlRequest);
  const answerControl = useAgentStore((state) => state.answerControl);

  // Asking for the mouse and keyboard part way through a session. Separate
  // from the prompt above because the answer is different: the screen is
  // already shared, and this is only about who is driving.
  if (controlRequest) {
    return (
      <div className="fixed inset-0 z-[70] flex animate-fade items-center justify-center bg-black/70 px-4">
        <div className="w-full max-w-md animate-pop rounded-xl border border-edge bg-surface-900 p-6 shadow-pop">
          <div className="flex items-start gap-3">
            <MonitorIcon className="mt-0.5 h-6 w-6 shrink-0 text-accent" />
            <div>
              <h2 className="text-lg font-semibold text-slate-50">
                {controlRequest.controllerName} is asking for control
              </h2>
              <p className="mt-2 text-sm text-slate-300">
                They can already see this screen. Allowing this lets them use the mouse and
                keyboard as well, until the session ends or you take it back.
              </p>
            </div>
          </div>

          <div className="mt-5 flex gap-3">
            <button
              type="button"
              onClick={() => answerControl(false)}
              className="flex-1 cursor-pointer rounded-md bg-white/[0.07] px-4 py-2.5 font-medium text-slate-100 transition-colors duration-150 hover:bg-white/[0.12]"
            >
              Keep control
            </button>
            <button
              type="button"
              onClick={() => answerControl(true)}
              className="flex-1 cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98]"
            >
              Give control
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (session && !pending) {
    return (
      <div className="pointer-events-none fixed inset-x-0 top-0 z-[60] flex justify-center p-2">
        <p className="rounded-full bg-red-600/90 px-4 py-1.5 text-sm font-medium text-white shadow-lg">
          {session.controllerName} is{' '}
          {session.permissions.includes('REMOTE_CONTROL')
            ? 'controlling this machine'
            : 'watching this screen'}
        </p>
      </div>
    );
  }

  if (!pending) return null;

  const controls = pending.permissions.includes('REMOTE_CONTROL');

  return (
    <div className="fixed inset-0 z-[70] flex animate-fade items-center justify-center bg-black/70 px-4">
      <div className="w-full max-w-md animate-pop rounded-xl border border-edge bg-surface-900 p-6 shadow-pop">
        <div className="flex items-start gap-3">
          <MonitorIcon className="mt-0.5 h-6 w-6 shrink-0 text-accent" />
          <div>
            <h2 className="text-lg font-semibold text-slate-50">
              {pending.controllerName} wants to connect
            </h2>
            <p className="mt-2 text-sm text-slate-300">
              They would be able to {controls ? 'see this screen and use the mouse and keyboard' : 'see this screen'}.
            </p>
            <p className="mt-2 text-xs text-slate-500">
              Nothing is shared until you allow it. Doing nothing refuses.
            </p>
          </div>
        </div>

        <div className="mt-5 flex gap-3">
          <button
            type="button"
            onClick={() => refuse()}
            className="flex-1 cursor-pointer rounded-md bg-white/[0.07] px-4 py-2.5 font-medium text-slate-100 transition-colors duration-150 hover:bg-white/[0.12]"
          >
            Refuse
          </button>
          <button
            type="button"
            onClick={accept}
            className="flex-1 cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98]"
          >
            Allow
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useRemoteStore } from '../../stores/remote';
import { modifiersOf } from '../../services/keyboard';
import { formatBytes } from '../../services/remote-transfer';
import { MonitorIcon, PhoneOffIcon, XIcon } from '../../components/icons';

/**
 * The remote screen, and the input that goes back to it.
 *
 * Coordinates are sent as a fraction of the video, never as pixels: the two
 * machines have different resolutions and different scaling, and the agent is
 * the only side that knows what its own display measures.
 *
 * Control is a mode, not a permission: watching is the default even for a
 * session allowed to control, and taking it is one button. A session that was
 * not granted control asks the machine for it instead, RDP style, and somebody
 * sitting there answers. Escape always hands it back and never travels - one
 * key has to stay local or an unresponsive session traps the keyboard.
 */
export function RemoteSessionView(): JSX.Element {
  const session = useRemoteStore((state) => state.session);
  const status = useRemoteStore((state) => state.status);
  const endedReason = useRemoteStore((state) => state.endedReason);
  const track = useRemoteStore((state) => state.track);
  const disconnect = useRemoteStore((state) => state.disconnect);
  const sendMouse = useRemoteStore((state) => state.sendMouse);
  const sendKey = useRemoteStore((state) => state.sendKey);
  const can = useRemoteStore((state) => state.can);

  const controlling = useRemoteStore((state) => state.controlling);
  const requesting = useRemoteStore((state) => state.requestingControl);
  const requestControl = useRemoteStore((state) => state.requestControl);
  const releaseControl = useRemoteStore((state) => state.releaseControl);
  const error = useRemoteStore((state) => state.error);
  const screens = useRemoteStore((state) => state.screens);
  const activeScreenId = useRemoteStore((state) => state.activeScreenId);
  const selectScreen = useRemoteStore((state) => state.selectScreen);

  const audioTrack = useRemoteStore((state) => state.audioTrack);
  const listening = useRemoteStore((state) => state.listening);
  const setListening = useRemoteStore((state) => state.setListening);
  const transfer = useRemoteStore((state) => state.transfer);
  const sendFile = useRemoteStore((state) => state.sendFile);
  const cancelTransfer = useRemoteStore((state) => state.cancelTransfer);
  const dismissTransfer = useRemoteStore((state) => state.dismissTransfer);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileRef = useRef<HTMLInputElement | null>(null);
  const [dropping, setDropping] = useState(false);
  const mayControl = can('REMOTE_CONTROL');
  const clipboard = can('REMOTE_CLIPBOARD');
  const mayTransfer = can('REMOTE_FILE_TRANSFER');
  const busy = transfer?.status === 'offering' || transfer?.status === 'sending';

  useEffect(() => {
    const element = videoRef.current;
    if (!element || !track) return;
    element.srcObject = new MediaStream([track]);
    void element.play().catch(() => undefined);
    return () => {
      element.srcObject = null;
    };
  }, [track]);

  // The machine's sound plays from its own element rather than from the video,
  // which stays muted: the two are independent, and a mute that also had to
  // silence the picture would have to unmute it again to be turned off.
  useEffect(() => {
    const element = audioRef.current;
    if (!element || !audioTrack) return;
    element.srcObject = new MediaStream([audioTrack]);
    void element.play().catch(() => undefined);
    return () => {
      element.srcObject = null;
    };
  }, [audioTrack]);

  // Keys are listened for on the window, not the video: a video element is not
  // focusable, and a controller expects to type the moment the pointer is over
  // the screen.
  useEffect(() => {
    if (!controlling || !mayControl) return;

    const onKey = (event: KeyboardEvent): void => {
      // Escape hands control back, so it never travels: without one key that
      // always stays local, a session that stops responding traps the keyboard.
      if (event.key === 'Escape') {
        releaseControl();
        return;
      }
      event.preventDefault();
      sendKey({
        action: event.type === 'keydown' ? 'down' : 'up',
        key: event.key,
        code: event.code,
        // Sent with every key, not only when a modifier changes: a chord is
        // only a chord if the far side knows what was held at the moment the
        // key was struck, and a modifier released while this window was not
        // focused never arrives as an event of its own.
        modifiers: modifiersOf(event),
      });
    };

    window.addEventListener('keydown', onKey);
    window.addEventListener('keyup', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('keyup', onKey);
    };
  }, [controlling, mayControl, sendKey, releaseControl]);

  const pointFrom = (event: React.MouseEvent<HTMLVideoElement>): { x: number; y: number } => {
    const rect = event.currentTarget.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) / rect.width,
      y: (event.clientY - rect.top) / rect.height,
    };
  };

  const buttonOf = (button: number): 'left' | 'right' | 'middle' =>
    button === 2 ? 'right' : button === 1 ? 'middle' : 'left';

  return (
    <div className="flex min-w-0 flex-1 flex-col bg-black">
      <header className="flex h-12 shrink-0 items-center gap-3 border-b border-black/40 bg-surface-800 px-4">
        <MonitorIcon className="h-5 w-5 text-slate-400" />
        <span className="truncate font-medium text-slate-100">{session?.machineName}</span>
        <span className="rounded bg-surface-700 px-2 py-0.5 text-xs text-slate-300">
          {controlling ? 'Controlling' : 'Watching'}
        </span>
        {clipboard && (
          <span className="hidden rounded bg-surface-700 px-2 py-0.5 text-xs text-slate-400 sm:inline">
            Clipboard shared
          </span>
        )}

        {/* Only when there is sound to hear. A session granted the permission on
            a machine that cannot capture loopback gets no track and no button,
            rather than a control that does nothing. */}
        {audioTrack && (
          <button
            type="button"
            onClick={() => setListening(!listening)}
            aria-pressed={listening}
            className="cursor-pointer rounded bg-surface-700 px-2 py-1 text-xs text-slate-200 transition-colors duration-200 hover:bg-white/[0.1]"
          >
            {listening ? 'Sound on' : 'Sound off'}
          </button>
        )}

        {mayTransfer && (
          <>
            <input
              ref={fileRef}
              type="file"
              className="hidden"
              onChange={(event) => {
                const chosen = event.target.files?.[0];
                if (chosen) void sendFile(chosen);
                // Cleared, or picking the same file twice in a row fires no
                // change event and the second send silently does nothing.
                event.target.value = '';
              }}
            />
            <button
              type="button"
              disabled={busy || !track}
              onClick={() => fileRef.current?.click()}
              className="cursor-pointer rounded bg-surface-700 px-2 py-1 text-xs text-slate-200 transition-colors duration-200 hover:bg-white/[0.1] disabled:cursor-not-allowed disabled:opacity-40"
            >
              Send file
            </button>
          </>
        )}
        {status === 'waiting' && (
          <span className="text-sm text-slate-400">Waiting for the machine…</span>
        )}

        {/* Only when there is a choice to make. One monitor needs no chooser. */}
        {screens.length > 1 && (
          <label className="flex items-center gap-1.5 text-xs text-slate-400">
            <span className="sr-only">Monitor</span>
            <select
              value={activeScreenId ?? ''}
              onChange={(event) => selectScreen(event.target.value)}
              className="cursor-pointer rounded bg-surface-700 px-2 py-1 text-xs text-slate-100"
            >
              {screens.map((entry, index) => (
                <option key={entry.id} value={entry.id}>
                  {entry.label || `Monitor ${index + 1}`} · {entry.width}×{entry.height}
                  {entry.primary ? ' (main)' : ''}
                </option>
              ))}
            </select>
          </label>
        )}

        {/* One button. Control that was granted up front starts straight away;
            otherwise this asks the machine and somebody there answers. */}
        <button
          type="button"
          disabled={requesting || !track}
          onClick={() => (controlling ? releaseControl() : requestControl())}
          className={`ms-auto cursor-pointer rounded px-3 py-1.5 text-sm font-medium transition-colors duration-200 disabled:cursor-not-allowed disabled:opacity-50 ${
            controlling
              ? 'bg-surface-600 text-slate-100 hover:bg-surface-500'
              : 'bg-accent text-white hover:bg-accent-hover active:scale-[0.98]'
          }`}
        >
          {controlling
            ? 'Release control (Esc)'
            : requesting
              ? 'Asking the machine…'
              : mayControl
                ? 'Take control'
                : 'Request control'}
        </button>

        <button
          type="button"
          onClick={() => void disconnect()}
          className="flex cursor-pointer items-center gap-2 rounded bg-red-600 px-3 py-1.5 text-sm font-medium text-white transition-colors duration-200 hover:bg-red-500"
        >
          <PhoneOffIcon className="h-4 w-4" />
          Disconnect
        </button>
      </header>

      {error && (
        <p role="alert" className="bg-red-500/10 px-4 py-2 text-center text-sm text-red-300">
          {error}
        </p>
      )}

      {transfer && (
        <div className="flex items-center gap-3 border-b border-edge bg-surface-850 px-4 py-2 text-sm">
          <span className="min-w-0 truncate text-slate-200">{transfer.name}</span>
          <span className="shrink-0 text-xs text-slate-400">
            {transfer.status === 'done'
              ? `Saved on the machine · ${formatBytes(transfer.size)}`
              : transfer.status === 'offering'
                ? 'Waiting for the machine…'
                : transfer.status === 'sending'
                  ? `${formatBytes(transfer.moved)} of ${formatBytes(transfer.size)}`
                  : (transfer.detail ?? transfer.status)}
          </span>

          {transfer.status === 'sending' && (
            <span className="h-1 min-w-0 flex-1 overflow-hidden rounded bg-surface-700">
              <span
                className="block h-full bg-accent transition-[width] duration-200"
                // A file of no bytes is already whole; dividing by its size
                // would put NaN in a style attribute and draw nothing.
                style={{
                  width: `${transfer.size === 0 ? 100 : Math.round((transfer.moved / transfer.size) * 100)}%`,
                }}
              />
            </span>
          )}

          <button
            type="button"
            onClick={() => (busy ? cancelTransfer() : dismissTransfer())}
            aria-label={busy ? 'Cancel the transfer' : 'Dismiss'}
            className="ms-auto shrink-0 cursor-pointer rounded p-1 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
          >
            <XIcon className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* Muted follows the toggle; the element exists as soon as there is a
          track so turning sound on does not have to wait for one to mount. */}
      {audioTrack && <audio ref={audioRef} autoPlay muted={!listening} />}

      <div
        className="relative flex min-h-0 flex-1 items-center justify-center"
        // Dropping a file onto the remote screen is the gesture people try
        // first, and it is the same send the button does. Both halves of the
        // handler are needed: without `onDragOver` preventing its default, the
        // browser navigates the window to the file that was dropped.
        onDragOver={(event) => {
          if (!mayTransfer || busy) return;
          event.preventDefault();
          setDropping(true);
        }}
        onDragLeave={() => setDropping(false)}
        onDrop={(event) => {
          event.preventDefault();
          setDropping(false);
          if (!mayTransfer || busy) return;
          const dropped = event.dataTransfer.files[0];
          if (dropped) void sendFile(dropped);
        }}
      >
        {dropping && (
          <div className="pointer-events-none absolute inset-4 z-10 flex items-center justify-center rounded-lg border-2 border-dashed border-accent bg-black/50 text-sm text-slate-100">
            Drop to send to {session?.machineName}
          </div>
        )}
        {track ? (
          <video
            ref={videoRef}
            muted
            playsInline
            // Never `cursor-none`. Hiding the local pointer assumed the capture
            // draws the machine's own cursor into the frame, and it does not
            // reliably - so taking control made the pointer vanish entirely and
            // left nothing to aim with. A crosshair says "this is going to the
            // other machine" without ever leaving the user without a pointer.
            className={`max-h-full max-w-full ${controlling ? 'cursor-crosshair' : ''}`}
            onMouseMove={(event) => sendMouse({ action: 'move', ...pointFrom(event) })}
            onMouseDown={(event) =>
              sendMouse({ action: 'down', button: buttonOf(event.button), ...pointFrom(event) })
            }
            onMouseUp={(event) =>
              sendMouse({ action: 'up', button: buttonOf(event.button), ...pointFrom(event) })
            }
            onWheel={(event) =>
              sendMouse({
                action: 'wheel',
                x: 0,
                y: 0,
                deltaY: Math.sign(event.deltaY) * 120,
              })
            }
            // The machine's own context menu is what a right-click is for.
            onContextMenu={(event) => event.preventDefault()}
          />
        ) : (
          <div className="text-center">
            <p className="text-slate-300">
              {status === 'ended'
                ? `Session ended${endedReason ? `: ${endedReason}` : ''}`
                : 'Connecting to the machine…'}
            </p>
            {status === 'ended' && (
              <button
                type="button"
                onClick={() => void disconnect()}
                className="mt-3 cursor-pointer rounded bg-surface-700 px-4 py-2 text-sm text-slate-100 transition-colors duration-200 hover:bg-white/[0.1]"
              >
                Back to machines
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import type {
  RemoteAuditEntry,
  RemoteGrantSummary,
  RemoteMachineSummary,
  RemotePermission,
  UserSummary,
} from '@betweenus/shared-types';
import { useRemoteStore } from '../../stores/remote';
import { useAuthStore } from '../../stores/auth';
import { api } from '../../services/api';
import { Avatar } from '../../components/Avatar';
import { MenuIcon, MonitorIcon, ShieldIcon, XIcon } from '../../components/icons';
import { SkeletonRows } from '../../components/Skeleton';
import { listState } from '../../services/list-state';

/** Labels, and the order they read in: what you can see, then what you can do. */
const PERMISSION_LABELS: Array<{ id: RemotePermission; label: string; hint: string }> = [
  { id: 'REMOTE_VIEW', label: 'View the screen', hint: 'Always needed; everything else adds to it' },
  { id: 'REMOTE_CONTROL', label: 'Mouse and keyboard', hint: 'Full control of the machine' },
  { id: 'REMOTE_CLIPBOARD', label: 'Clipboard', hint: 'Copy and paste in both directions' },
  {
    id: 'REMOTE_FILE_TRANSFER',
    label: 'File transfer',
    hint: 'Send files to the machine; they land in its downloads folder',
  },
  { id: 'REMOTE_AUDIO', label: 'Audio', hint: "Hear the machine's own sound" },
  { id: 'REMOTE_ADMIN', label: 'Manage access', hint: 'Hand this machine out to other people' },
];

export function RemoteView({ onOpenMenu }: { onOpenMenu?: () => void } = {}): JSX.Element {
  const machines = useRemoteStore((state) => state.machines);
  const loading = useRemoteStore((state) => state.loading);
  const error = useRemoteStore((state) => state.error);
  const load = useRemoteStore((state) => state.load);
  const connect = useRemoteStore((state) => state.connect);

  const [managing, setManaging] = useState<RemoteMachineSummary | null>(null);

  useEffect(() => {
    void load();
  }, [load]);

  // A live session is drawn over the whole window by `App`, not here: it can be
  // started from a screen share in a voice channel too, and that has no machine
  // list to take over.
  return (
    <div className="panel flex min-w-0 flex-1 flex-col bg-surface-900">
      <header className="flex h-12 shrink-0 items-center gap-2 border-b border-edge px-2.5 md:px-4">
        {onOpenMenu && (
          <button
            type="button"
            onClick={onOpenMenu}
            aria-label="Open navigation menu"
            title="Open menu"
            className="flex h-9 w-9 min-h-[44px] min-w-[44px] cursor-pointer items-center justify-center rounded-md text-slate-300 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100 md:hidden"
          >
            <MenuIcon className="h-5 w-5" />
          </button>
        )}
        <MonitorIcon className="h-5 w-5 text-slate-400" />
        <h1 className="font-semibold text-slate-100">Remote machines</h1>
        <button
          type="button"
          onClick={() => void load()}
          className="ms-auto cursor-pointer rounded px-3 py-1.5 text-sm text-slate-300 transition-colors duration-200 hover:bg-white/[0.1] min-h-[36px]"
        >
          Refresh
        </button>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto p-6">
        {error && (
          <p role="alert" className="mb-4 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
            {error}
          </p>
        )}

        {/* The first list this screen draws is a fetch away, and it used to be
            drawn as nothing at all - a blank panel with a Refresh button, which
            reads as a screen that failed rather than one that is working. */}
        {listState(machines.length, loading) === 'loading' && (
          <SkeletonRows rows={3} label="Loading machines" className="mx-auto max-w-md pt-8" />
