/**
 * Who may reach this machine, and what they may do once they are on it.
 *
 * Everything here is one call per person: a permission set and an optional
 * expiry, replaced wholesale. Unticking everything is the revocation, which is
 * also what ends a session that person is holding right now.
 */
function AccessDialog({
  machine,
  onClose,
}: {
  machine: RemoteMachineSummary;
  onClose: () => void;
}): JSX.Element {
  const [grants, setGrants] = useState<RemoteGrantSummary[]>([]);
  const [audit, setAudit] = useState<RemoteAuditEntry[]>([]);
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<UserSummary[]>([]);
  const [note, setNote] = useState<string | null>(null);
  const [tab, setTab] = useState<'people' | 'audit'>('people');

  useEffect(() => {
    void api.machineGrants(machine.id).then(setGrants).catch(() => undefined);
    void api.machineAudit(machine.id).then(setAudit).catch(() => undefined);
  }, [machine.id]);

  useEffect(() => {
    if (query.trim().length < 2) {
      setResults([]);
      return;
    }
    const timer = window.setTimeout(() => {
      void api
        .searchUsers(query.trim())
        .then((found) =>
          setResults(
            found.filter(
              (user) =>
                user.id !== machine.ownerId && !grants.some((grant) => grant.userId === user.id),
            ),
          ),
        )
        .catch(() => setResults([]));
    }, 250);
    return () => window.clearTimeout(timer);
  }, [query, grants, machine.ownerId]);

  const save = async (
    userId: string,
    permissions: RemotePermission[],
    expiresAt: string | null,
  ): Promise<void> => {
    setNote(null);
    try {
      setGrants(await api.setMachineGrant(machine.id, userId, permissions, expiresAt));
      setQuery('');
      setAudit(await api.machineAudit(machine.id));
    } catch (error) {
      setNote(error instanceof Error ? error.message : 'That could not be saved');
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex animate-fade items-center justify-center bg-black/60 px-4">
      <div className="flex max-h-[80vh] w-full max-w-2xl animate-pop flex-col rounded-xl border border-edge bg-surface-900 shadow-pop">
        <header className="flex items-center gap-3 border-b border-edge px-5 py-4">
          <ShieldIcon className="h-5 w-5 text-accent" />
          <div className="min-w-0 flex-1">
            <h2 className="truncate text-lg font-semibold text-slate-50">{machine.name}</h2>
            <p className="text-xs text-slate-400">
              Remote access is granted per person and never comes from a server role.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="cursor-pointer rounded-md p-1 text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
          >
            <XIcon className="h-4 w-4" />
          </button>
        </header>

        <nav className="flex gap-1 border-b border-edge px-5 py-2">
          {(['people', 'audit'] as const).map((entry) => (
            <button
              key={entry}
              type="button"
              onClick={() => setTab(entry)}
              aria-current={tab === entry ? 'page' : undefined}
              className={`cursor-pointer rounded px-3 py-1 text-sm transition-colors duration-200 ${
                tab === entry ? 'bg-surface-700 text-slate-100' : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              {entry === 'people' ? 'People' : 'History'}
            </button>
          ))}
        </nav>

        <div className="min-h-0 flex-1 overflow-y-auto p-5">
          {note && (
            <p role="alert" className="mb-3 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
              {note}
            </p>
          )}

          {tab === 'people' ? (
            <>
              <label htmlFor="remote-search" className="mb-1 block text-xs font-semibold uppercase tracking-wide text-slate-400">
                Give someone access
              </label>
              <input
                id="remote-search"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="Search by username"
                className="w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-2 text-slate-100 placeholder-slate-500 transition-colors duration-200 focus:border-accent"
              />
              {results.length > 0 && (
                <ul className="mt-2 space-y-1">
                  {results.map((user) => (
                    <li key={user.id}>
                      <button
                        type="button"
                        onClick={() => void save(user.id, ['REMOTE_VIEW'], null)}
                        className="flex w-full cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-start transition-colors duration-200 hover:bg-white/[0.06]"
                      >
                        <Avatar name={user.displayName} avatarUrl={user.avatarUrl} size="sm" />
                        <span className="min-w-0 flex-1 truncate text-sm text-slate-100">
                          {user.displayName}
                          <span className="ms-1 text-slate-500">@{user.username}</span>
                        </span>
                        <span className="text-xs text-slate-400">Add as viewer</span>
                      </button>
                    </li>
                  ))}
                </ul>
              )}

              <div className="mt-5 space-y-4">
                {grants.length === 0 && (
                  <p className="text-sm text-slate-400">
                    Nobody else can reach this machine. You can, because you own it.
                  </p>
                )}
                {grants.map((grant) => (
                  <GrantRow key={grant.userId} grant={grant} onSave={save} />
                ))}
              </div>
            </>
          ) : (
            <ol className="space-y-2">
              {audit.length === 0 && <p className="text-sm text-slate-400">Nothing yet.</p>}
              {audit.map((entry) => (
                <li key={entry.id} className="rounded bg-surface-850 px-3 py-2 text-sm">
                  <span className="text-slate-200">{entry.action}</span>
                  {entry.actorUsername && (
                    <span className="text-slate-400"> · {entry.actorUsername}</span>
                  )}
                  <span className="ms-2 text-xs text-slate-500">{formatWhen(entry.createdAt)}</span>
                  {entry.detail && (
                    <pre className="mt-1 overflow-x-auto text-xs text-slate-500">
                      {JSON.stringify(entry.detail)}
                    </pre>
                  )}
                </li>
              ))}
            </ol>
          )}
        </div>
      </div>
    </div>
  );
}

function GrantRow({
  grant,
  onSave,
}: {
  grant: RemoteGrantSummary;
  onSave: (
    userId: string,
    permissions: RemotePermission[],
    expiresAt: string | null,
  ) => Promise<void>;
}): JSX.Element {
  const toggle = (permission: RemotePermission): void => {
    const next = grant.permissions.includes(permission)
      ? grant.permissions.filter((value) => value !== permission)
      : [...grant.permissions, permission];
    void onSave(grant.userId, next, grant.expiresAt);
  };

  return (
    <div className="rounded-lg bg-surface-850 p-3">
      <div className="flex items-center gap-3">
        <Avatar name={grant.displayName} avatarUrl={grant.avatarUrl} size="sm" />
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-medium text-slate-100">{grant.displayName}</p>
          <p className="truncate text-xs text-slate-500">@{grant.username}</p>
        </div>
        <button
          type="button"
          onClick={() => void onSave(grant.userId, [], null)}
          className="cursor-pointer rounded px-2 py-1 text-xs text-red-300 transition-colors duration-200 hover:bg-red-500/10"
        >
          Revoke
        </button>
      </div>

      <div className="mt-3 space-y-1.5">
        {PERMISSION_LABELS.map((permission) => (
          <label
            key={permission.id}
            className="flex cursor-pointer items-start gap-2 text-sm text-slate-300"
          >
            <input
              type="checkbox"
              checked={grant.permissions.includes(permission.id)}
              onChange={() => toggle(permission.id)}
              className="mt-1 cursor-pointer accent-[color:var(--accent,#5865f2)]"
            />
            <span>
              {permission.label}
              <span className="block text-xs text-slate-500">{permission.hint}</span>
            </span>
          </label>
        ))}
      </div>

      <label className="mt-3 block text-xs text-slate-400">
        Access until
        <input
          type="datetime-local"
          defaultValue={toLocalInput(grant.expiresAt)}
          onChange={(event) =>
            void onSave(
              grant.userId,
              grant.permissions,
              event.target.value ? new Date(event.target.value).toISOString() : null,
            )
          }
          className="mt-1 block w-full rounded-md border border-surface-700 bg-surface-900 px-3 py-1.5 text-sm text-slate-100"
        />
        <span className="mt-1 block text-slate-500">Empty means it does not expire.</span>
      </label>
    </div>
  );
}

function lastSeen(iso: string | null): string {
  if (!iso) return ' · never connected';
  return ` · last seen ${formatWhen(iso)}`;
}

function formatWhen(iso: string): string {
  return new Date(iso).toLocaleString(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  });
}

/** `datetime-local` wants a local, second-less ISO string, or nothing at all. */
function toLocalInput(iso: string | null): string {
  if (!iso) return '';
  const date = new Date(iso);
  const offset = date.getTimezoneOffset() * 60_000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 16);
}

/**
 * What is behind an invite, before anyone accepts it.
 *
 * A link used to join the moment it was opened: the window came up, the server
 * was already in the rail, and nobody had been asked anything. That is wrong in
 * both directions - the person following the link had no idea whose server it
 * was until they were in it, and the server got a member who never agreed to
 * join. So the code is looked up first and answered with a card: whose server,
 * how many people are in it, how many of them are here now.
 *
 * Both ways in land here - a link the app was opened by, and a code somebody
 * pasted into the rail - because there is one decision and it should be made
 * against one screen.
 */
import { useEffect, useState } from 'react';
import type { InvitePreview } from '@betweenus/shared-types';
import { api } from '../../services/api';
import { useChatStore } from '../../stores/chat';
import { ServerIcon } from '../../components/ServerIcon';
import { useFocusTrap } from '../../services/focus-trap';

export function InviteDialog({ code, onClose }: { code: string; onClose: () => void }): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const [preview, setPreview] = useState<InvitePreview | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let live = true;
    setPreview(null);
    setFailure(null);
    void api
      .invitePreview(code)
      .then((found) => {
        if (live) setPreview(found);
      })
      .catch((error: unknown) => {
        if (live) setFailure(error instanceof Error ? error.message : 'That invite is not valid');
      });
    return () => {
      live = false;
    };
  }, [code]);

  const accept = async (): Promise<void> => {
    if (!preview || busy) return;
    setBusy(true);
    setFailure(null);
    try {
      // Already a member: the link opens the server rather than joining it
      // again. The server would have said the same thing, without spending a
      // use - this just says it before asking.
      if (preview.member) await useChatStore.getState().selectServer(preview.serverId);
      else await useChatStore.getState().joinServer(preview.code);
      onClose();
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'That did not work');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label="Invitation"
      className="fixed inset-0 z-50 flex animate-fade items-center justify-center bg-black/60 px-4"
      onClick={onClose}
    >
      <div
        className="w-full max-w-sm animate-pop overflow-hidden rounded-xl border border-edge bg-surface-900 text-start shadow-pop"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="flex flex-col items-center gap-3 px-6 pb-6 pt-8 text-center">
          <p className="text-xs font-bold uppercase tracking-wide text-slate-400">
            You have been invited to join
          </p>

          {preview ? (
            <>
              <div className="overflow-hidden rounded-2xl">
                <ServerIcon server={preview} size="lg" />
              </div>
              <h2 className="text-xl font-semibold text-slate-50">{preview.name}</h2>
              <Counts preview={preview} />
            </>
          ) : failure ? (
            <p role="alert" className="py-6 text-sm text-danger">
              {failure}
            </p>
          ) : (
            <>
              <div className="h-20 w-20 animate-pulse rounded-2xl bg-surface-800" />
              <div className="h-5 w-40 animate-pulse rounded bg-surface-800" />
            </>
          )}
        </div>

        {preview && failure && (
          <p role="alert" className="px-6 pb-3 text-center text-sm text-danger">
            {failure}
          </p>
        )}

        <div className="flex justify-end gap-3 border-t border-edge bg-black/20 px-6 py-4">
          <button
            type="button"
            onClick={onClose}
            className="cursor-pointer px-4 py-2 text-sm text-slate-200 hover:underline"
          >
            {preview ? 'No thanks' : 'Close'}
          </button>
          {preview && (
            <button
              type="button"
              autoFocus
              disabled={busy}
              onClick={() => void accept()}
              className="cursor-pointer rounded-lg bg-accent px-6 py-2 text-sm font-medium text-white transition-colors duration-150 hover:bg-accent-hover active:scale-[0.98] disabled:opacity-60"
            >
              {busy ? 'Working…' : preview.member ? 'Open server' : 'Accept invite'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * "12 members, 3 online", the way every invite card has said it since Discord's.
 *
 * The online half is dropped entirely when presence could not be reached, which
 * is what a null means. Showing it as "0 online" would describe a busy server
 * as an empty one on the strength of a service being restarted.
 */
function Counts({ preview }: { preview: InvitePreview }): JSX.Element {
  return (
    <p className="flex items-center gap-3 text-sm text-slate-400">
      {preview.onlineCount !== null && (
        <span className="flex items-center gap-1.5">
          <span aria-hidden="true" className="h-2 w-2 rounded-full bg-status-online" />
          {preview.onlineCount} online
        </span>
      )}
      <span className="flex items-center gap-1.5">
        <span aria-hidden="true" className="h-2 w-2 rounded-full bg-status-offline" />
        {preview.memberCount} {preview.memberCount === 1 ? 'member' : 'members'}
      </span>
    </p>
  );
}

import { useEffect, useState } from 'react';
import { useChatStore } from '../../stores/chat';
import {
  clearPendingInvite,
  inviteCodeFrom,
  pendingInvite,
} from '../../services/invite-link';
import { InviteDialog } from './InviteDialog';
import { CompassIcon, MessageIcon, PlusIcon } from '../../components/icons';
import { ServerIcon } from '../../components/ServerIcon';
import { useFocusTrap } from '../../services/focus-trap';

/**
 * The left rail: direct messages at the top, then one tile per server, and the
 * two ways to get another one at the bottom.
 *
 * It is the one region that is not a panel - it sits directly on the ground, so
 * the workbench reads as panels arranged beside a column of controls rather
 * than as one more grey stripe. Where you are is a short bar against the left
 * edge, the way an editor marks its active activity-bar item: it costs no
 * horizontal space and it does not turn the tile into a different shape.
 */
export function ServerRail({ className }: { className?: string } = {}): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const { servers, view, activeServerId, selectServer, showHome, createServer } = useChatStore();
  const [dialog, setDialog] = useState<'none' | 'create' | 'join'>('none');
  const [value, setValue] = useState('');
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  /** The code a card is being shown for, from a link or from the field below. */
  const [invited, setInvited] = useState<string | null>(null);

  /**
   * A window opened by an invite link.
   *
   * The code was taken off the address bar before the first render, because a
   * sign-in reloads the page and would otherwise lose it. It is picked up here,
   * once there is a session to use it with - this rail only exists when there
   * is one - and it opens the card rather than joining anything.
   *
   * Cleared on the way in whatever happens next. A code that is refused is not
   * going to start working, and one retried on every launch is a link that
   * rejoins a server somebody deliberately left.
   */
  useEffect(() => {
    const code = pendingInvite();
    if (!code) return;
    clearPendingInvite();
    setInvited(code);
  }, []);

  const submit = async (): Promise<void> => {
    const trimmed = value.trim();
    if (!trimmed || busy) return;
    setBusy(true);
    setFailure(null);
    try {
      if (dialog === 'create') {
        await createServer(trimmed);
      } else {
        // A link or a bare code: what somebody pastes is a link about half the
        // time, and a field that silently ignores one of the two is a field
        // people report as broken.
        const code = inviteCodeFrom(trimmed);
        if (!code) throw new Error('That is not an invite link or code');
        // Not joined here. The card says whose server this is first, and the
        // pasted code deserves that answer as much as a clicked link does.
        setInvited(code);
      }
      setDialog('none');
      setValue('');
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'That did not work');
    } finally {
      setBusy(false);
    }
  };

  return (
    <nav
      aria-label="Servers"
      className={`flex w-14 shrink-0 flex-col items-center gap-1 overflow-y-auto overflow-x-hidden py-0.5 ${className ?? ''}`}
    >
      {/* Not the BetweenUs mark: that is in the top bar, and a second copy of it
          one row below reads as branding rather than as the button it is. A
          rail tile has to say where it goes. */}
      <RailButton
        label="Direct messages"
        active={view === 'home'}
        onClick={showHome}
        activeClasses="bg-accent/20 text-accent"
      >
        <MessageIcon className="h-[22px] w-[22px]" />
      </RailButton>

      <hr className="my-1 w-6 border-t border-edge" />

      {servers.map((server) => (
        <RailButton
          key={server.id}
          label={server.name}
          active={view === 'server' && server.id === activeServerId}
          onClick={() => void selectServer(server.id)}
          activeClasses="bg-accent text-white"
        >
          <ServerIcon server={server} size="rail" />
        </RailButton>
      ))}

      <RailButton
        label="Create a server"
        active={false}
        onClick={() => setDialog('create')}
        idleTextClasses="text-slate-500"
        activeClasses="bg-white/[0.07] text-slate-100"
      >
        <PlusIcon className="h-6 w-6" />
      </RailButton>

      <RailButton
        label="Join a server"
        active={false}
        onClick={() => setDialog('join')}
        idleTextClasses="text-slate-500"
        activeClasses="bg-white/[0.07] text-slate-100"
      >
        <CompassIcon className="h-6 w-6" />
      </RailButton>

      {invited && <InviteDialog code={invited} onClose={() => setInvited(null)} />}

      {dialog !== 'none' && (
        <div
          ref={trap}
          role="dialog"
          aria-modal="true"
          aria-label={dialog === 'create' ? 'Create a server' : 'Join a server'}
          className="fixed inset-0 z-50 flex animate-fade items-center justify-center bg-black/60 px-4"
          onClick={() => setDialog('none')}
        >
          <div
            className="w-full max-w-md animate-pop overflow-hidden rounded-xl border border-edge bg-surface-900 p-6 text-start shadow-pop"
            onClick={(event) => event.stopPropagation()}
          >
            <h2 className="text-xl font-semibold text-slate-50">
              {dialog === 'create' ? 'Create a server' : 'Join a server'}
            </h2>
            <p className="mt-2 text-sm text-slate-400">
              {dialog === 'create'
                ? 'Your server is where you and your people hang out. Make one and start talking.'
                : 'Paste the invite code someone sent you.'}
            </p>

            <label
              htmlFor="server-input"
              className="mt-5 block text-xs font-bold uppercase tracking-wide text-slate-300"
            >
              {dialog === 'create' ? 'Server name' : 'Invite code'}
            </label>
            <input
              id="server-input"
              autoFocus
              value={value}
              onChange={(event) => setValue(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter') void submit();
                if (event.key === 'Escape') setDialog('none');
              }}
              className="mt-2 w-full rounded-lg border border-edge bg-surface-950 px-3 py-2.5 text-slate-100 outline-none ring-0 transition-colors focus:border-accent/60"
              placeholder={dialog === 'create' ? "Ayaan's server" : 'betweenus-team'}
            />

            {failure && (
              <p role="alert" className="mt-2 text-sm text-danger">
                {failure}
              </p>
            )}

            <div className="-mx-6 -mb-6 mt-6 flex justify-end gap-3 border-t border-edge bg-black/20 px-6 py-4">
              <button
                type="button"
                onClick={() => setDialog('none')}
                className="cursor-pointer px-4 py-2 text-sm text-slate-200 hover:underline"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={busy}
                onClick={() => void submit()}
                className="cursor-pointer rounded-lg bg-accent px-6 py-2 text-sm font-medium text-white transition-colors duration-150 hover:bg-accent-hover active:scale-[0.98] disabled:opacity-60"
              >
                {busy ? 'Working…' : dialog === 'create' ? 'Create' : 'Join'}
              </button>
            </div>
          </div>
        </div>
      )}
    </nav>
  );
}

function RailButton({
  label,
  active,
  onClick,
  children,
  activeClasses,
  idleTextClasses = 'text-slate-200',
}: {
  label: string;
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
  activeClasses: string;
  idleTextClasses?: string;
}): JSX.Element {
  return (
    <div className="group relative flex w-full justify-center">
      {/* The marker is the only thing that moves, and it grows out of the edge
          rather than sliding in from nowhere: a hover shows a stub of it, so
          the active state and the "you could be here" state are visibly the
          same object at two lengths. */}
      <span
        aria-hidden="true"
        className={`absolute -start-0.5 top-1/2 w-[3px] -translate-y-1/2 rounded-full bg-accent transition-[height,opacity] duration-200 ease-out ${
          active ? 'h-5 opacity-100' : 'h-2 opacity-0 group-hover:opacity-60'
        }`}
      />
      <button
        type="button"
        onClick={onClick}
        title={label}
        aria-label={label}
        aria-current={active ? 'true' : undefined}
        // No focus ring here: the marker on the left edge already says where
        // you are, and a second ring around a 40px tile is all noise.
        className={`flex h-10 w-10 cursor-pointer items-center justify-center overflow-hidden rounded-lg outline-none ring-0 transition-colors duration-150 focus:ring-0 focus-visible:ring-0 active:scale-[0.96] ${
          active
            ? activeClasses
            : `hover:bg-white/[0.07] hover:text-slate-100 ${idleTextClasses}`
        }`}
      >
        {children}
      </button>
    </div>
  );
}

