/**
 * Who may see a private channel.
 *
 * The endpoint has always existed and only the create dialog used it, so a
 * private channel's allowlist was decided once and never again - somebody left
 * off it stayed off it, and somebody who should not have been on it stayed on.
 *
 * Removing somebody takes the future away as well as the listing: the channel's
 * key rotates the next time a holder syncs it, so what is sent after this is
 * sealed with a key they do not have. What they already downloaded is theirs
 * and no design takes that back.
 */
function ChannelAccess({
  channel,
  onClose,
}: {
  channel: Channel;
  onClose: () => void;
}): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const members = useChatStore((state) => state.members);
  const [allowed, setAllowed] = useState<string[] | null>(null);
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState<string | null>(null);

  useEffect(() => {
    let live = true;
    void api
      .channelMembers(channel.id)
      .then((rows) => {
        if (live) setAllowed(rows.map((row) => row.userId));
      })
      .catch((error: unknown) =>
        setNote(error instanceof Error ? error.message : 'Could not read who is on it'),
      );
    return () => {
      live = false;
    };
  }, [channel.id]);

  const toggle = (userId: string): void =>
    setAllowed((current) =>
      current === null
        ? current
        : current.includes(userId)
          ? current.filter((id) => id !== userId)
          : [...current, userId],
    );

  const save = async (): Promise<void> => {
    if (allowed === null) return;
    setBusy(true);
    setNote(null);
    try {
      await api.setChannelMembers(channel.id, allowed);
      // Re-key now rather than whenever somebody next opens the channel. This
      // client is a holder - it is in the channel - and the person who just
      // removed somebody is the person least willing to wait for it.
      await syncChannelKeys(channel.id).catch(() => undefined);
      onClose();
    } catch (error) {
      setNote(error instanceof Error ? error.message : 'That could not be saved');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label={`Who is on ${channel.name}`}
      className="fixed inset-0 z-[60] flex animate-fade items-center justify-center bg-black/70 px-4"
    >
      <div className="w-full max-w-md animate-pop rounded-xl border border-edge bg-surface-900 p-6 shadow-pop">
        <h2 className="text-lg font-semibold text-slate-50">Who is on #{channel.name}</h2>
        <p className="mt-2 text-sm text-slate-400">
          Only these people see the channel at all. Taking somebody off re-keys it, so what is
          said afterwards is sealed with a key they do not have - what they already read stays
          read.
        </p>

        {note && <p className="mt-3 text-sm text-danger">{note}</p>}

        {allowed === null ? (
          <p className="mt-4 text-sm text-slate-400">Reading the list…</p>
        ) : (
          <ul className="mt-4 max-h-[320px] space-y-1 overflow-y-auto">
            {members.map((member) => (
              <li key={member.userId}>
                <label className="flex cursor-pointer items-center gap-3 rounded px-2 py-1.5 hover:bg-white/[0.05]">
                  <input
                    type="checkbox"
                    checked={allowed.includes(member.userId)}
                    onChange={() => toggle(member.userId)}
                    className="h-4 w-4 cursor-pointer accent-accent"
                  />
                  <span className="truncate text-slate-100">{member.displayName}</span>
                  <span className="ms-auto shrink-0 text-xs text-slate-500">{member.role}</span>
                </label>
              </li>
            ))}
          </ul>
        )}

        <div className="mt-5 flex gap-3">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 cursor-pointer rounded-md bg-white/[0.07] px-4 py-2.5 font-medium text-slate-100 transition-colors duration-150 hover:bg-white/[0.12]"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={() => void save()}
            disabled={busy || allowed === null}
            className="flex-1 cursor-pointer rounded-md bg-accent px-4 py-2.5 font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:opacity-50"
          >
            {busy ? 'Saving…' : 'Save'}
          </button>
        </div>
      </div>
    </div>
  );
}

function Invites(): JSX.Element {
  const servers = useChatStore((state) => state.servers);
  const activeServerId = useChatStore((state) => state.activeServerId);
  const server = servers.find((item) => item.id === activeServerId);

  const [invites, setInvites] = useState<ServerInvite[]>([]);
  const [expiresInHours, setExpiresInHours] = useState<number | null>(24);
  const [maxUses, setMaxUses] = useState<number | null>(null);
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  const [copied, setCopied] = useState<string | null>(null);

  useEffect(() => {
    if (!server) return;
    let live = true;
    void api
      .serverInvites(server.id)
      .then((rows) => {
        if (live) setInvites(rows);
      })
      .catch((error: unknown) =>
        setFailure(error instanceof Error ? error.message : 'Could not read the invites'),
      );
    return () => {
      live = false;
    };
  }, [server?.id]);

  if (!server) return <></>;

  const create = async (): Promise<void> => {
    setBusy(true);
    setFailure(null);
    try {
      const invite = await api.createServerInvite(server.id, { expiresInHours, maxUses });
      setInvites((current) => [invite, ...current]);
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'Could not make an invite');
    } finally {
      setBusy(false);
    }
  };

  const revoke = async (code: string): Promise<void> => {
    try {
      const invite = await api.revokeServerInvite(server.id, code);
      setInvites((current) => current.map((row) => (row.code === code ? invite : row)));
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'Could not revoke it');
    }
  };

  /**
   * Copies the link rather than the code by default.
   *
   * A code is eight characters that look like a typo when they arrive in
   * somebody's chat, and it does not say which deployment it belongs to - two
   * BetweenUs servers can both have `k3m9x2qp` and neither is wrong. The code
   * itself is still one click away for anywhere a link will not travel.
   */
  const copy = (code: string, what: 'link' | 'code'): void => {
    const text = what === 'link' ? inviteLink(serverUrl(), code) : code;
    void navigator.clipboard?.writeText(text).then(() => {
      const mark = `${code}:${what}`;
      setCopied(mark);
      window.setTimeout(() => setCopied((current) => (current === mark ? null : current)), 2000);
    });
  };

  return (
    <>
      <h1 className="text-xl font-semibold text-slate-50">Invites</h1>
      <p className="mt-2 text-sm text-slate-400">
        An invite is how somebody gets in - anybody, friend or not: they follow the link and
        choose to join, which is why adding a stranger from the members screen is refused and
        this is not. Each one can expire, can be limited to a number of people, and can be taken
        back - which is what the server&apos;s name never could be.
      </p>

      <div className="mt-5 rounded-lg bg-surface-800 p-4">
        <div className="flex flex-wrap items-end gap-4">
          <label className="text-sm text-slate-300">
            Expires after
            <select
              value={expiresInHours ?? 'never'}
              onChange={(event) =>
                setExpiresInHours(
                  event.target.value === 'never' ? null : Number(event.target.value),
                )
              }
              className="mt-1 block cursor-pointer rounded-md bg-surface-900 px-3 py-2 text-slate-100"
            >
              <option value={1}>1 hour</option>
              <option value={24}>1 day</option>
              <option value={24 * 7}>7 days</option>
              <option value={24 * 30}>30 days</option>
              <option value="never">Never</option>
            </select>
          </label>

          <label className="text-sm text-slate-300">
            Number of uses
            <select
              value={maxUses ?? 'any'}
              onChange={(event) =>
                setMaxUses(event.target.value === 'any' ? null : Number(event.target.value))
              }
              className="mt-1 block cursor-pointer rounded-md bg-surface-900 px-3 py-2 text-slate-100"
            >
              <option value={1}>1</option>
              <option value={5}>5</option>
              <option value={25}>25</option>
              <option value={100}>100</option>
              <option value="any">Any number</option>
            </select>
          </label>

          <button
            type="button"
            onClick={() => void create()}
            disabled={busy}
            className="cursor-pointer rounded-md bg-accent px-4 py-2 font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:opacity-50"
          >
            {busy ? 'Making…' : 'New invite'}
          </button>
        </div>
      </div>

      {failure && <p className="mt-3 text-sm text-danger">{failure}</p>}

      {invites.length === 0 ? (
        <p className="mt-5 text-sm text-slate-400">
          No invites yet. Nobody can join until there is one.
        </p>
      ) : (
        <ul className="mt-5 divide-y divide-surface-700 rounded-lg bg-surface-800">
          {invites.map((invite) => (
            <li key={invite.code} className="flex items-center justify-between gap-4 px-4 py-3">
              <div className="min-w-0">
                <p
                  className={`select-all font-mono text-sm ${
                    invite.active ? 'text-slate-100' : 'text-slate-500 line-through'
                  }`}
                >
                  {invite.code}
                </p>
                <p className="mt-1 text-xs text-slate-400">{describeInvite(invite)}</p>
              </div>
              <div className="flex shrink-0 gap-2">
                <button
                  type="button"
                  onClick={() => copy(invite.code, 'link')}
                  title={inviteLink(serverUrl(), invite.code)}
                  className="cursor-pointer rounded bg-white/[0.07] px-3 py-1.5 text-sm text-slate-100 transition-colors duration-200 hover:bg-white/[0.1]"
                >
                  {copied === `${invite.code}:link` ? 'Copied' : 'Copy link'}
                </button>
                <button
                  type="button"
                  onClick={() => copy(invite.code, 'code')}
                  title="The code on its own, for anywhere a link will not travel"
                  className="cursor-pointer rounded bg-white/[0.07] px-3 py-1.5 text-sm text-slate-300 transition-colors duration-200 hover:bg-white/[0.1]"
                >
                  {copied === `${invite.code}:code` ? 'Copied' : 'Code'}
                </button>
                {invite.active && (
                  <button
                    type="button"
                    onClick={() => void revoke(invite.code)}
                    className="cursor-pointer rounded bg-white/[0.07] px-3 py-1.5 text-sm text-danger transition-colors duration-200 hover:bg-white/[0.1]"
                  >
                    Revoke
                  </button>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
    </>
  );
}

/** One line saying what is left of an invite, or what happened to it. */
function describeInvite(invite: ServerInvite): string {
  if (invite.revokedAt) return 'Revoked';
  // The server's clock, not this machine's: the deployment is what refuses an
  // expired invite, so the label must agree with it rather than with a laptop
  // whose clock is out. See services/server-clock.ts.
  if (invite.expiresAt && new Date(invite.expiresAt).getTime() <= serverNow()) return 'Expired';
  if (invite.maxUses !== null && invite.uses >= invite.maxUses) return 'All uses spent';

  const used =
    invite.maxUses === null
      ? `${invite.uses} used`
      : `${invite.uses} of ${invite.maxUses} used`;
  const until = invite.expiresAt
    ? `expires ${new Date(invite.expiresAt).toLocaleString()}`
    : 'never expires';
  return `${used}, ${until}`;
}

/**
 * A server's own emoji: upload a picture, give it a name, type `:name:`.
 *
 * The picture goes through the ordinary picture route, which is where the image
 * allowlist and the size cap already live. Two things it does *not* do to an
 * animated file, and both matter: it does not re-encode it, because that is how
 * an animated GIF becomes a still frame, and it does not square it off in a
 * canvas for the same reason. A still picture is downscaled, since a 4000px PNG
 * drawn at 22 is bytes nobody asked for.
 */
function EmojiSection(): JSX.Element {
  const server = useChatStore((state) => state.servers.find((item) => item.id === state.activeServerId));
  const mayManage = server?.permissions.includes(PERMISSIONS.MANAGE_EMOJI) ?? false;

  const [emoji, setEmoji] = useState<ServerEmoji[]>([]);
  const [name, setName] = useState('');
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState<string | null>(null);
  const picker = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!server) return;
    void loadEmoji(server.id).then(() => setEmoji(emojiFor(server.id)));
    return onEmojiChanged(() => setEmoji(emojiFor(server.id)));
  }, [server?.id]);

  const upload = async (file: File | undefined): Promise<void> => {
    if (!file || !server) return;
    setBusy(true);
    setNote(null);
    try {
      const suggested = name.trim() || fileStem(file.name);
      if (!EMOJI_NAME_PATTERN.test(suggested)) {
        throw new Error('A name is two to thirty-two lowercase letters, digits or underscores');
      }

      const animated = isAnimatedType(file.type);
      // Animated files are uploaded exactly as they are - re-encoding one
      // through a canvas keeps the first frame and throws the rest away, which
      // is the whole of what people are asking for when they ask for this.
      const picture = animated ? file : await preparePicture(file);
      if (picture.size > MAX_EMOJI_BYTES) {
        throw new Error(
          `That is ${Math.round(picture.size / 1024)} KB. An emoji has to be under ` +
            `${Math.round(MAX_EMOJI_BYTES / 1024)} KB - it is drawn at 22 pixels.`,
        );
      }

      const stored = await api.uploadPicture(picture, file.name);
      await addEmoji(server.id, suggested, stored.url, animated);
      setName('');
      setNote(`:${suggested}: is ready to type.`);
    } catch (error) {
      setNote(error instanceof Error ? error.message : 'That could not be uploaded');
    } finally {
      setBusy(false);
      if (picker.current) picker.current.value = '';
    }
  };

  if (!server) return <p className="text-sm text-slate-400">No server open.</p>;

  return (
    <>
      <h1 className="text-xl font-semibold text-slate-50">Emoji</h1>
      <p className="mt-2 text-sm text-slate-400">
        Pictures this server can type by name. A GIF or an animated WebP stays animated - it is
        stored exactly as uploaded. They are public, like avatars: an emoji is drawn by an image
        tag a hundred times a screen, and an image tag cannot carry a password.
      </p>

      {mayManage ? (
        <div className="mt-5 space-y-3 rounded-lg bg-surface-800 p-4">
          <label className="block text-sm text-slate-300">
            Name
            <input
              value={name}
              onChange={(event) => setName(event.target.value.toLowerCase())}
              placeholder="party_parrot"
              className="mt-1 block w-full max-w-xs rounded-md border border-edge bg-surface-950 px-3 py-2 text-slate-100 placeholder-slate-500 outline-none focus:border-accent/60"
            />
            <span className="mt-1 block text-xs text-slate-500">
              Two to thirty-two lowercase letters, digits or underscores. Left empty, the file
              name is used.
            </span>
          </label>

          <input
            ref={picker}
            type="file"
            hidden
            accept="image/png,image/jpeg,image/gif,image/webp"
            onChange={(event) => void upload(event.target.files?.[0])}
          />
          <button
            type="button"
            disabled={busy || emoji.length >= MAX_SERVER_EMOJI}
            onClick={() => picker.current?.click()}
            className="cursor-pointer rounded-md bg-accent px-4 py-2 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:opacity-50"
          >
            {busy ? 'Uploading…' : 'Upload a picture'}
          </button>
          <p className="text-xs text-slate-500">
            {emoji.length} of {MAX_SERVER_EMOJI} used · under {Math.round(MAX_EMOJI_BYTES / 1024)} KB
            each
          </p>
        </div>
      ) : (
        <p className="mt-5 text-sm text-slate-400">
          You can use these; adding one needs the “Manage emoji” permission.
        </p>
      )}

      {note && <p className="mt-3 text-sm text-slate-300">{note}</p>}

      {emoji.length === 0 ? (
        <p className="mt-5 text-sm text-slate-400">None yet.</p>
      ) : (
        <ul className="mt-5 grid grid-cols-[repeat(auto-fill,minmax(180px,1fr))] gap-2">
          {emoji.map((item) => (
            <li
              key={item.id}
              className="flex items-center gap-3 rounded-lg bg-surface-800 px-3 py-2"
            >
              <img
                src={absoluteUrl(item.url)}
                alt={`:${item.name}:`}
                className="h-8 w-8 shrink-0 object-contain"
              />
              <span className="min-w-0 flex-1">
                <span className="block truncate text-sm text-slate-100">:{item.name}:</span>
                {item.animated && <span className="block text-xs text-slate-500">animated</span>}
              </span>
              {mayManage && (
                <button
                  type="button"
                  aria-label={`Remove :${item.name}:`}
                  title="Remove. Messages that used it keep their picture."
                  onClick={() => {
                    void removeEmoji(server.id, item.id).catch(() =>
                      setNote('That could not be removed'),
                    );
                  }}
                  className="cursor-pointer rounded p-1 text-slate-500 transition-colors duration-150 hover:text-danger"
                >
                  <XIcon className="h-4 w-4" />
                </button>
              )}
            </li>
          ))}
        </ul>
      )}
    </>
  );
}

/** A file name with its extension and anything unusable taken off. */
function fileStem(fileName: string): string {
  return fileName
    .replace(/\.[^.]+$/, '')
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 32);
}

/**
 * A server's webhooks: the URLs outside systems post into its channels with.
 *
 * One list across every channel rather than a panel buried inside each one.
 * "Which robots can write in this server, and where" is one question, and it is
 * the question somebody arrives here holding - a per-channel panel makes them
 * open eleven channels to answer it.
 *
 * Two things on this screen are unusual and both are deliberate.
 *
 * The URL is shown **once**, when it is created or rotated, because the server
 * keeps only a hash of the token. That is a worse first-run experience than
 * Discord's re-readable URLs and a much better one than a database dump handing
 * over every integration this deployment has. The way back from losing one is
 * the Rotate button, which is why it is not tucked away.
 *
 * And the panel says, in as many words, that a webhook's messages are not
 * encrypted. Everything else in this app is sealed on the client; a webhook
 * cannot be, because the sender holds no key. Somebody adding one is spending
 * that guarantee for that channel, and they should be told before they press
 * the button rather than by noticing a badge later.
 */
import { useEffect, useState } from 'react';
import {
  WEBHOOK_NAME_MAX_LENGTH,
  type Channel,
  type WebhookSummary,
  type WebhookWithToken,
} from '@betweenus/shared-types';
import { api } from '../../services/api';
import { useChatStore } from '../../stores/chat';
import { Avatar } from '../../components/Avatar';
import { PicturePicker } from '../../components/PicturePicker';
import { HashIcon, TrashIcon } from '../../components/icons';

export function Webhooks(): JSX.Element {
  const channels = useChatStore((state) => state.channels);
  // A voice channel has no message history to post into.
  const textChannels = channels.filter((channel) => channel.type === 'TEXT');

  const [hooks, setHooks] = useState<WebhookSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  /** The URL of whatever was just created or rotated. Shown once, then gone. */
  const [minted, setMinted] = useState<WebhookWithToken | null>(null);
  const [copied, setCopied] = useState(false);

  const [name, setName] = useState('');
  const [target, setTarget] = useState('');
  const [busy, setBusy] = useState(false);

  const load = async (): Promise<void> => {
    setLoading(true);
    setError(null);
    try {
      // One request per channel: there is no server-wide list endpoint, because
      // the permission that guards this is a channel permission and a
      // server-wide answer would have to be filtered back down to exactly this.
      const lists = await Promise.all(
        textChannels.map((channel) =>
          // A channel this account cannot manage answers 403; that is not an
          // error on this screen, it is a channel that contributes nothing to
          // the list.
          api.webhooks(channel.id).catch(() => [] as WebhookSummary[]),
        ),
      );
      setHooks(lists.flat());
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : 'Webhooks could not be loaded');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
    // Keyed on the ids rather than the array, which is a new reference on every
    // store update and would refetch the whole list on every keystroke
    // elsewhere in the app.
  }, [textChannels.map((channel) => channel.id).join(',')]);

  useEffect(() => {
    if (!target && textChannels[0]) setTarget(textChannels[0].id);
  }, [textChannels, target]);

  const create = async (): Promise<void> => {
    if (!name.trim() || !target) return;
    setBusy(true);
    setError(null);
    try {
      const made = await api.createWebhook({ channelId: target, name: name.trim() });
      setMinted(made);
      setCopied(false);
      setName('');
      await load();
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : 'That webhook could not be created');
    } finally {
      setBusy(false);
    }
  };

  const rotate = async (webhookId: string): Promise<void> => {
    setError(null);
    try {
      const rotated = await api.rotateWebhook(webhookId);
      setMinted(rotated);
      setCopied(false);
      await load();
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : 'That URL could not be replaced');
    }
  };

  const remove = async (webhookId: string): Promise<void> => {
    setError(null);
    try {
      await api.deleteWebhook(webhookId);
      setHooks((current) => current.filter((hook) => hook.id !== webhookId));
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : 'That webhook could not be removed');
    }
  };

  return (
    <>
      <h1 className="text-xl font-semibold text-slate-50">Webhooks</h1>
      <p className="mt-1 text-sm text-slate-400">
        A URL another system can post into a channel with — a build server, an alerting stack,
        anything that can make an HTTP request. It uses the same request shape Discord does, so an
        integration already pointed at Discord works by changing only the URL.
      </p>

      {/* Said before the button rather than discovered afterwards. */}
      {/* Amber, which is what every other notice in this app that says "this is
          not what you assume" already uses - BackupNotice, ClockNotice,
          VersionNotice. There is no `warning` colour token; those all reach
          for Tailwind's amber directly, so this does too rather than
          inventing a fifth spelling. */}
      <div className="mt-4 rounded-lg bg-amber-500/[0.12] p-4 text-amber-100">
        <p className="text-sm font-semibold">Webhook messages are not encrypted</p>
        <p className="mt-1 text-sm text-amber-200/90">
          Everything people write here is sealed on their own device, and this deployment cannot
          read it. A webhook has no key and cannot be given one — handing a channel key to a script
          would hand away the channel — so what it posts is stored in the clear and this deployment
          can read it. Every client marks those messages so nobody has to guess which is which.
        </p>
      </div>

      {minted && (
        <div className="mt-4 rounded-lg border border-accent/40 bg-accent/[0.08] p-4">
          <p className="text-sm font-semibold text-slate-100">
            Copy this URL now — it is not shown again
          </p>
          <p className="mt-1 text-xs text-slate-400">
            Only a hash of it is kept, so nobody, including this deployment, can read it back. If
            you lose it, rotate the webhook for a new one.
          </p>
          <div className="mt-3 flex flex-wrap items-center gap-2">
            <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap rounded bg-surface-900 px-3 py-2 text-xs text-slate-200">
              {minted.url}
            </code>
            <button
              type="button"
              onClick={() => {
                void navigator.clipboard.writeText(minted.url).then(() => setCopied(true));
              }}
              className="cursor-pointer rounded bg-accent px-4 py-2 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98]"
            >
              {copied ? 'Copied' : 'Copy'}
            </button>
            <button
              type="button"
              onClick={() => setMinted(null)}
              className="cursor-pointer rounded px-3 py-2 text-sm text-slate-400 transition-colors duration-200 hover:text-slate-200"
            >
              Done
            </button>
          </div>
        </div>
      )}

      <h2 className="mt-8 text-base font-semibold text-slate-50">New webhook</h2>
      <div className="mt-3 flex flex-wrap items-end gap-3">
        <label className="min-w-[180px] flex-1">
          <span className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-400">
            Name
          </span>
          <input
            value={name}
            maxLength={WEBHOOK_NAME_MAX_LENGTH}
            placeholder="Deploys"
            onChange={(event) => setName(event.target.value)}
            className="w-full rounded bg-surface-900 px-3 py-2 text-sm text-slate-100 outline-none ring-1 ring-edge transition-shadow duration-200 focus:ring-2 focus:ring-accent"
          />
        </label>
        <label className="min-w-[180px] flex-1">
          <span className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-400">
            Channel
          </span>
          <select
            value={target}
            onChange={(event) => setTarget(event.target.value)}
            className="w-full cursor-pointer rounded bg-surface-900 px-3 py-2 text-sm text-slate-100 outline-none ring-1 ring-edge transition-shadow duration-200 focus:ring-2 focus:ring-accent"
          >
            {textChannels.map((channel) => (
              <option key={channel.id} value={channel.id}>
                #{channel.name}
              </option>
            ))}
          </select>
        </label>
        <button
          type="button"
          disabled={busy || !name.trim() || !target}
          onClick={() => void create()}
          className="cursor-pointer rounded bg-accent px-5 py-2 text-sm font-medium text-white transition-colors duration-200 hover:bg-accent-hover active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50"
        >
          {busy ? 'Creating…' : 'Create'}
        </button>
      </div>

      {error && <p className="mt-3 text-sm text-danger">{error}</p>}

      <h2 className="mt-8 text-base font-semibold text-slate-50">
        {hooks.length === 1 ? '1 webhook' : `${hooks.length} webhooks`}
      </h2>
      {loading ? (
        <p className="mt-3 text-sm text-slate-400">Loading…</p>
      ) : hooks.length === 0 ? (
        <p className="mt-3 text-sm text-slate-400">
          Nothing posts into this server from outside it.
        </p>
      ) : (
        <ul className="mt-3 space-y-2">
          {hooks.map((hook) => (
            <WebhookRow
              key={hook.id}
              hook={hook}
              channel={textChannels.find((channel) => channel.id === hook.channelId)}
              onRotate={() => void rotate(hook.id)}
              onRemove={() => void remove(hook.id)}
              onChanged={(next) =>
                setHooks((current) =>
                  current.map((item) => (item.id === next.id ? next : item)),
                )
              }
            />
          ))}
        </ul>
      )}
    </>
  );
}

function WebhookRow({
  hook,
  channel,
  onRotate,
  onRemove,
  onChanged,
}: {
  hook: WebhookSummary;
  channel: Channel | undefined;
  onRotate: () => void;
  onRemove: () => void;
  onChanged: (next: WebhookSummary) => void;
}): JSX.Element {
  // Two presses to delete, in place, rather than a confirmation dialog: a
  // webhook that vanishes on one press takes a deploy pipeline with it, and
  // whoever set that pipeline up is not the person clicking.
  const [armed, setArmed] = useState(false);

  return (
    <li className="rounded-lg bg-surface-800 p-4">
      <div className="flex items-start gap-3">
        <Avatar name={hook.name} avatarUrl={hook.avatarUrl} size="md" ringColour="border-surface-800" />
        <div className="min-w-0 flex-1">
          <p className="truncate text-[15px] font-semibold text-slate-100">{hook.name}</p>
          <p className="flex items-center gap-1 truncate text-xs text-slate-400">
            <HashIcon className="h-3 w-3 shrink-0" />
            {channel?.name ?? 'a channel you cannot see'}
          </p>
          <p className="mt-1 text-xs text-slate-500">
            Opened by {hook.createdBy.displayName} ·{' '}
            {/* The first thing anybody asks about a webhook that "isn't
                working": has it ever actually delivered anything. */}
            {hook.lastUsedAt
              ? `last used ${new Date(hook.lastUsedAt).toLocaleString()}`
              : 'never used'}
          </p>
        </div>
        <div className="flex shrink-0 flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={onRotate}
            title="Issue a new URL and invalidate the current one"
            className="cursor-pointer rounded bg-surface-700 px-3 py-1.5 text-xs font-medium text-slate-200 transition-colors duration-200 hover:bg-white/[0.08]"
          >
            Rotate URL
          </button>
          <button
            type="button"
            onClick={() => (armed ? onRemove() : setArmed(true))}
            onBlur={() => setArmed(false)}
            className={`flex cursor-pointer items-center gap-1 rounded px-3 py-1.5 text-xs font-medium transition-colors duration-200 ${
              armed
                ? 'bg-danger text-white'
                : 'bg-surface-700 text-slate-300 hover:bg-danger hover:text-white'
            }`}
          >
            <TrashIcon className="h-3 w-3" />
            {armed ? 'Really delete' : 'Delete'}
          </button>
        </div>
      </div>

      <div className="mt-3 border-t border-edge pt-3">
        <PicturePicker
          label="webhook picture"
          onChange={async (avatarUrl) => {
            onChanged(await api.updateWebhook(hook.id, { avatarUrl }));
          }}
          onClear={
            hook.avatarUrl
              ? async () => {
                  onChanged(await api.updateWebhook(hook.id, { avatarUrl: null }));
                }
              : undefined
          }
        />
      </div>
    </li>
  );
}

/**
 * Calls & Data: what this account's calls have cost, and what each one did.
 *
 * The page a call log hangs under. The log alone answers "when did I talk to
 * them"; it cannot answer "why was my month 12 GB", because a mesh call is not
 * one connection but one per other person and they do not behave alike - the
 * one that went through a relay is usually the whole answer.
 *
 * Everything drawn here is measured by the clients, not by any server: media
 * goes directly between the people in a call, so nothing in the backend is in
 * the path to count a byte. That is also why a call the app was killed in
 * reports nothing at all, which is said on the page rather than hidden.
 *
 * ponytail: the chart is a row of divs rather than a charting library. It is
 * one stacked series over one bounded window; a dependency for that is a
 * megabyte to draw thirty rectangles.
 */
import { useEffect, useMemo, useState } from 'react';
import type { CallAnalytics, CallHistoryEntry, CallLinkReport } from '@betweenus/shared-types';
import { api } from '../../services/api';
import { formatBytes } from '../../services/attachments';
import { formatCallDuration } from '../../services/call-stats';

/** What the server sends back for the log, said here so the page is not a guess. */
const HISTORY_SHOWN = 50;

/** The windows worth offering: a week, a month, a quarter. */
const RANGES = [7, 30, 90] as const;

export function CallUsageSection(): JSX.Element {
  const [days, setDays] = useState<number>(30);
  const [analytics, setAnalytics] = useState<CallAnalytics | null>(null);
  const [entries, setEntries] = useState<CallHistoryEntry[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [open, setOpen] = useState<string | null>(null);

  useEffect(() => {
    let live = true;
    setAnalytics(null);
    Promise.all([api.callAnalytics(days), api.callHistory()])
      .then(([usage, history]) => {
        if (!live) return;
        setAnalytics(usage);
        setEntries(history);
        setError(null);
      })
      .catch((cause: unknown) => {
        if (live) setError(cause instanceof Error ? cause.message : 'Could not load your calls');
      });
    return () => {
      live = false;
    };
  }, [days]);

  const totals = analytics?.totals;
  const totalBytes = totals ? totals.bytesSent + totals.bytesReceived : 0;

  return (
    <>
      <h1 className="text-xl font-semibold text-slate-50">Calls &amp; Data</h1>
      <p className="mt-2 text-sm text-slate-400">
        Every call this account has been in, and what it moved. Media goes directly between the
        people in a call, so these are your own machine&apos;s numbers rather than a server&apos;s -
        a call the app was killed in has none to report.
      </p>

      {error && (
        <p role="alert" className="mt-4 rounded-md bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {error}
        </p>
      )}

      <div className="mt-5 flex gap-1.5" role="group" aria-label="How far back to look">
        {RANGES.map((range) => (
          <button
            key={range}
            type="button"
            onClick={() => setDays(range)}
            aria-pressed={days === range}
            className={`rounded-md px-3 py-1.5 text-xs font-medium transition ${
              days === range
                ? 'bg-accent text-white'
                : 'bg-surface-800 text-slate-400 hover:text-slate-200'
            }`}
          >
            {range} days
          </button>
        ))}
      </div>

      {analytics === null && !error && <p className="mt-5 text-sm text-slate-500">Loading…</p>}

      {analytics && totals && (
        <>
          <div className="mt-4 grid grid-cols-3 gap-3">
            <Total label="Data used" value={formatBytes(totalBytes)}>
              {formatBytes(totals.bytesSent)} up · {formatBytes(totals.bytesReceived)} down
            </Total>
            <Total label="Time in calls" value={formatCallDuration(totals.seconds)}>
              across {totals.calls} {totals.calls === 1 ? 'call' : 'calls'}
            </Total>
            <Total label="How it connected" value={describeTransport(analytics.transport)}>
              {analytics.transport.relay > 0
                ? `${analytics.transport.relay} of ${linkCount(analytics)} links went through a relay`
                : 'nothing needed a relay'}
            </Total>
          </div>

          <UsageChart daily={analytics.daily} />

          <div className="mt-6 grid grid-cols-2 gap-3">
            <Ranked
              title="Busiest channels"
              empty="No calls in this window."
              rows={analytics.channels.map((channel) => ({
                key: channel.channelId,
                label: channel.serverName
                  ? `${channel.serverName} · ${channel.channelName}`
                  : channel.channelName,
                value: formatCallDuration(channel.seconds),
                sub: formatBytes(channel.bytesSent + channel.bytesReceived),
              }))}
            />
            <Ranked
              title="Most time with"
              empty="Nobody else was in them."
              rows={analytics.peers.map((peer) => ({
                key: peer.id,
                label: peer.displayName || peer.username,
                value: formatCallDuration(peer.seconds),
                sub: `${peer.calls} ${peer.calls === 1 ? 'call' : 'calls'}`,
              }))}
            />
          </div>
        </>
      )}

      <h2 className="mt-8 text-sm font-semibold uppercase tracking-wide text-slate-400">
        Call history
      </h2>
      <p className="mt-1 text-xs text-slate-500">
        Your last {HISTORY_SHOWN} calls, newest first. Open one for what each connection in it did.
      </p>

      {entries?.length === 0 && (
        <p className="mt-4 text-sm text-slate-500">
          No calls yet. Join a voice channel and this fills itself in.
        </p>
      )}

      <ul className="mt-3 space-y-2">
        {(entries ?? []).map((entry) => (
          <li key={entry.id} className="overflow-hidden rounded-lg bg-surface-800">
            <button
              type="button"
              onClick={() => setOpen(open === entry.id ? null : entry.id)}
              aria-expanded={open === entry.id}
              className="w-full px-4 py-3 text-start transition hover:bg-surface-700/60"
            >
              <div className="flex items-baseline justify-between gap-3">
                <p className="truncate text-sm font-medium text-slate-100">
                  {entry.serverName ? `${entry.serverName} · ` : ''}
                  {entry.channelName}
                </p>
                <span className="shrink-0 text-xs tabular-nums text-slate-400">
                  {entry.durationSeconds === null
                    ? 'no ending recorded'
                    : formatCallDuration(entry.durationSeconds)}
                </span>
              </div>
              <p className="mt-1 text-xs text-slate-400">
                {describeWhen(entry.joinedAt)} · {describeWho(entry.peers)} ·{' '}
                {entry.bytes > 0 ? formatBytes(entry.bytes) : 'no data recorded'}
              </p>
            </button>

            {open === entry.id && <CallDetail entry={entry} />}
          </li>
        ))}
      </ul>
    </>
  );
}

/**
 * One call, opened up: when it ran, and one row per connection it held.
 *
 * The per-link rows are the part worth having. Two people in the same call can
 * have completely different answers about whether it went direct, and an
 * expensive call is nearly always one link doing something the others were not.
 */
function CallDetail({ entry }: { entry: CallHistoryEntry }): JSX.Element {
  return (
    <div className="border-t border-white/5 bg-surface-900/40 px-4 py-3">
      <dl className="grid grid-cols-3 gap-3 text-xs">
        <Fact label="Started">{new Date(entry.joinedAt).toLocaleString()}</Fact>
        <Fact label="Ended">
          {entry.endedAt ? new Date(entry.endedAt).toLocaleString() : 'never recorded'}
        </Fact>
        <Fact label="Data">
          {entry.bytesSent + entry.bytesReceived > 0
            ? `${formatBytes(entry.bytesSent)} up · ${formatBytes(entry.bytesReceived)} down`
            : 'nothing reported'}
        </Fact>
      </dl>

      {entry.links.length === 0 ? (
        <p className="mt-3 text-xs text-slate-500">
          No connection detail for this call. The client reports it on the way out, so a call the
          app was killed in - or one from an older build - has none.
        </p>
      ) : (
        <table className="mt-3 w-full text-start text-xs">
          <thead className="text-slate-500">
            <tr>
              <th className="py-1 font-medium">Connection</th>
              <th className="py-1 font-medium">Path</th>
              <th className="py-1 text-end font-medium">Up</th>
              <th className="py-1 text-end font-medium">Down</th>
              <th className="py-1 text-end font-medium">Ping</th>
              <th className="py-1 text-end font-medium">Loss</th>
            </tr>
          </thead>
          <tbody className="text-slate-300">
            {entry.links.map((link) => (
              <tr key={`${link.userId}-${link.username}`} className="border-t border-white/5">
                <td className="py-1.5 pe-2 truncate">{link.username || link.userId}</td>
                <td className="py-1.5 pe-2">
                  <span className={link.transport === 'relay' ? 'text-amber-300' : 'text-slate-400'}>
                    {link.transport === 'relay'
                      ? 'relayed'
                      : link.transport === 'direct'
                        ? 'direct'
                        : 'unknown'}
                  </span>
                </td>
                <td className="py-1.5 text-end tabular-nums">{formatBytes(link.bytesSent)}</td>
                <td className="py-1.5 text-end tabular-nums">{formatBytes(link.bytesReceived)}</td>
                <td className="py-1.5 text-end tabular-nums">
                  {link.roundTripMs === null ? '—' : `${link.roundTripMs} ms`}
                </td>
                <td className="py-1.5 text-end tabular-nums">{describeLoss(link)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

/**
 * A day per bar, sent stacked on received.
 *
 * Drawn against the busiest day in the window rather than a fixed ceiling: what
 * a person reads off this is the shape of their month, and a scale that never
 * moves turns every ordinary week into a flat line at the bottom.
 */
function UsageChart({ daily }: { daily: CallAnalytics['daily'] }): JSX.Element {
  const peak = useMemo(
    () => Math.max(1, ...daily.map((day) => day.bytesSent + day.bytesReceived)),
    [daily],
  );

  return (
    <div className="mt-4 rounded-lg bg-surface-800 p-4">
      <div className="flex items-baseline justify-between">
        <p className="text-xs text-slate-400">Data per day</p>
        <p className="text-xs tabular-nums text-slate-500">busiest day {formatBytes(peak)}</p>
      </div>

      <div className="mt-3 flex h-28 items-end gap-[2px]">
        {daily.map((day) => {
          const total = day.bytesSent + day.bytesReceived;
          const height = (total / peak) * 100;
          return (
            <div
              key={day.date}
              title={`${day.date}: ${formatBytes(total)} · ${formatCallDuration(day.seconds)}`}
              className="flex h-full flex-1 flex-col justify-end"
            >
              {/* Two stacked pieces rather than two charts: the question is how
                  much of a day's total was upload, which a stack answers. */}
              <div
                className="w-full rounded-t-sm bg-accent"
                style={{ height: `${(day.bytesSent / peak) * 100}%` }}
              />
              <div
                className="w-full bg-accent/40"
                style={{ height: `${(day.bytesReceived / peak) * 100}%` }}
              />
              {/* A day with nothing in it still gets a floor, so the axis reads
                  as a row of days rather than as a gap. */}
              {height === 0 && <div className="h-[2px] w-full rounded-sm bg-white/5" />}
            </div>
          );
        })}
      </div>

      <div className="mt-2 flex items-center justify-between text-[11px] text-slate-500">
        <span>{daily[0]?.date ?? ''}</span>
        <span className="flex items-center gap-3">
          <Key className="bg-accent">sent</Key>
          <Key className="bg-accent/40">received</Key>
        </span>
        <span>{daily[daily.length - 1]?.date ?? ''}</span>
      </div>
    </div>
  );
}

function Key({ className, children }: { className: string; children: string }): JSX.Element {
  return (
    <span className="flex items-center gap-1">
      <span className={`h-2 w-2 rounded-sm ${className}`} />
      {children}
    </span>
  );
}

function Ranked({
  title,
  empty,
  rows,
}: {
  title: string;
  empty: string;
  rows: Array<{ key: string; label: string; value: string; sub: string }>;
}): JSX.Element {
  return (
    <div className="rounded-lg bg-surface-800 p-4">
      <p className="text-xs text-slate-400">{title}</p>
      {rows.length === 0 ? (
        <p className="mt-2 text-xs text-slate-500">{empty}</p>
      ) : (
        <ul className="mt-2 space-y-1.5">
          {rows.map((row) => (
            <li key={row.key} className="flex items-baseline justify-between gap-2 text-xs">
              <span className="truncate text-slate-200">{row.label}</span>
              <span className="shrink-0 tabular-nums text-slate-400">
                {row.value} · {row.sub}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function Total({
  label,
  value,
  children,
}: {
  label: string;
  value: string;
  children?: React.ReactNode;
}): JSX.Element {
  return (
    <div className="rounded-lg bg-surface-800 px-4 py-3">
      <p className="text-xs text-slate-400">{label}</p>
      <p className="mt-0.5 text-lg font-semibold tabular-nums text-slate-100">{value}</p>
      {children && <p className="mt-0.5 text-[11px] text-slate-500">{children}</p>}
    </div>
  );
}

function Fact({ label, children }: { label: string; children: React.ReactNode }): JSX.Element {
  return (
    <div>
      <dt className="text-slate-500">{label}</dt>
      <dd className="mt-0.5 text-slate-300">{children}</dd>
    </div>
  );
}

function linkCount(analytics: CallAnalytics): number {
  const { direct, relay, unknown } = analytics.transport;
  return direct + relay + unknown;
}

/** The headline answer: relayed at all, all direct, or nothing measured yet. */
function describeTransport(transport: CallAnalytics['transport']): string {
  if (transport.direct + transport.relay === 0) return 'not measured';
  if (transport.relay === 0) return 'all direct';
  const share = Math.round((transport.relay / (transport.direct + transport.relay)) * 100);
  return `${share}% relayed`;
}

function describeLoss(link: CallLinkReport): string {
  const total = link.packetsLost + link.packetsReceived;
  if (total === 0) return '—';
  return `${Math.round((link.packetsLost / total) * 1000) / 10}%`;
}

function describeWhen(iso: string): string {
  const at = new Date(iso);
  const sameDay = new Date().toDateString() === at.toDateString();
  return sameDay
    ? at.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
    : at.toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
}

/**
 * Who else was there, by name up to three of them.
 *
 * "Alone" is a real answer and worth saying: a call somebody sat in by
 * themselves waiting for anybody to join is the entry they are most likely to
 * be looking for when they ask why nothing happened.
 */
function describeWho(peers: CallHistoryEntry['peers']): string {
  if (peers.length === 0) return 'alone';
  const names = peers.map((peer) => peer.displayName || peer.username);
  if (names.length <= 3) return `with ${names.join(', ')}`;
  return `with ${names.slice(0, 3).join(', ')} and ${names.length - 3} more`;
}

