/** Self-check for `statusAge`: the boundaries, and the clock that runs fast. */
import assert from 'node:assert/strict';
import { statusAge } from './age';

const now = new Date('2026-09-03T12:00:00.000Z');
const at = (ms: number): string => new Date(now.getTime() - ms).toISOString();

assert.equal(statusAge(at(0), now), 'just now');
assert.equal(statusAge(at(59_000), now), 'just now');
// The first minute is the boundary everything else hangs off.
assert.equal(statusAge(at(60_000), now), '1m ago');
assert.equal(statusAge(at(59 * 60_000), now), '59m ago');
assert.equal(statusAge(at(60 * 60_000), now), '1h ago');
assert.equal(statusAge(at(23 * 3_600_000), now), '23h ago');

// A client clock a few seconds behind the server's makes a fresh post look
// like it was written in the future. It reads as "just now", not "-1m ago".
assert.equal(statusAge(at(-5_000), now), 'just now');

// Nothing renders for a timestamp that is not one.
assert.equal(statusAge('not a date', now), '');

console.log('status age check ok');

/**
 * How long ago a status was posted, in words.
 *
 * Its own function rather than `lastSeenLabel`: a status is never more than a
 * day old, so every branch that one has for weekdays and dates is unreachable
 * here, and the branches this one needs - minutes, then hours - are the ones
 * that reduce to "today at 7:07 PM" there. A reader glancing at a story tray
 * wants "12m ago", not the clock.
 *
 * `Android`'s `StatusAge.kt` is the same rule; if one changes, so does the
 * other.
 */
const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;

export function statusAge(iso: string, now: Date = new Date()): string {
  const posted = new Date(iso).getTime();
  if (Number.isNaN(posted)) return '';

  const elapsed = now.getTime() - posted;
  // A clock that is a little behind the server's puts a fresh post in the
  // future. "just now" is the honest answer; "-1m ago" is not.
  if (elapsed < MINUTE_MS) return 'just now';
  if (elapsed < HOUR_MS) return `${Math.floor(elapsed / MINUTE_MS)}m ago`;

  const hours = Math.floor(elapsed / HOUR_MS);
  // Nothing here lives past 24 hours, so hours is where it stops. A post that
  // is somehow older is expired and about to be swept; saying "24h ago" is
  // better than a "1d ago" branch that exists for rows nobody can see.
  return `${hours}h ago`;
}

/**
 * The circle at the start of a moments row: what somebody posted, not who
 * they are.
 *
 * A face is the right thing in every other list in the app, because every
 * other list is about people. This one is about posts - the row already says
 * whose they are - so the circle shows the newest one, which is what the tap
 * is about to open. It keeps the ring, so the count and the unopened state
 * still read exactly as they do on an avatar.
 *
 * The bytes come through the same cache the player uses, so opening a run
 * after seeing it here is not a second download.
 *
 * ponytail: a video draws its ring and a play mark rather than a poster
 * frame - a frame means fetching and decrypting the whole clip for a 40px
 * circle. Server-side thumbnails are the upgrade if that ever matters.
 */
import { useEffect, useState } from 'react';
import type { StatusEntry } from '@betweenus/shared-types';
import { statusMedia } from '../../services/status-media';
import { StatusRing } from '../../components/StatusRing';
import { PlayIcon } from '../../components/icons';

export function MomentThumb({
  posts,
  unseen = false,
}: {
  /** One person's run, oldest first. The newest is what gets drawn. */
  posts: StatusEntry[];
  unseen?: boolean;
}): JSX.Element {
  const newest = posts[posts.length - 1];
  const [url, setUrl] = useState<string | null>(null);

  const id = newest?.id;
  const kind = newest?.kind;
  useEffect(() => {
    setUrl(null);
    if (!newest || newest.kind !== 'PHOTO') return undefined;
    let alive = true;
    void statusMedia(newest)
      .then((made) => {
        if (alive) setUrl(made);
      })
      // A post this device holds no key for draws as a blank circle rather
      // than as an error, the same way the player draws it.
      .catch(() => undefined);
    return () => {
      alive = false;
    };
    // Keyed on the post rather than on the object: the tray re-derives its
    // runs on every look, and a new object for the same post is not a reason
    // to fetch it again.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, kind]);

  return (
    <div className="relative h-10 w-10 shrink-0">
      {posts.length > 0 && <StatusRing count={posts.length} unseen={unseen} />}
      <div
        className="flex h-full w-full items-center justify-center overflow-hidden rounded-full bg-surface-700"
        style={newest?.kind === 'TEXT' && newest.background ? { backgroundColor: newest.background } : undefined}
      >
        {url ? (
          <img src={url} alt="" className="h-full w-full object-cover" />
        ) : newest?.kind === 'VIDEO' ? (
          <PlayIcon className="h-4 w-4 text-slate-300" />
        ) : newest?.kind === 'TEXT' ? (
          <span aria-hidden="true" className="text-sm font-semibold uppercase text-white">
            {newest.caption?.trim().charAt(0) ?? ''}
          </span>
        ) : null}
      </div>
    </div>
  );
}

/**
 * Posting a status: pictures, a video, or words on a colour, full screen.
 *
 * Two kinds behind one screen rather than two screens, because they are the
 * same act - the only thing that differs is what gets attached. The text kind
 * exists precisely because it needs no camera and no file: it is the one
 * people use most, and making it a mode of the picture composer would bury it.
 *
 * One picker for both pictures and clips, because "photo or video" is a
 * question about the file rather than about the person: they reach for a
 * moment, not for a format, and the kind is read off `file.type`. Several at a
 * time, because a moment is usually more than one frame - each becomes its own
 * post, unless Layout is on and they are drawn onto a single one.
 *
 * Nothing is uploaded until Post: the preview is a local object URL, so
 * choosing files and changing your mind costs nothing and leaves nothing on
 * the server. That is also why posting sends the bytes and the caption in one
 * request - see `api.postStatus`.
 */
import { useEffect, useRef, useState } from 'react';
import { create } from 'zustand';
import {
  STATUS_BACKGROUNDS,
  STATUS_CAPTION_MAX_LENGTH,
  STATUS_VIDEO_MAX_MS,
  type StatusKind,
} from '@betweenus/shared-types';
import { useStatusStore, type StatusDraft } from '../../stores/status';
import { shrinkImage } from '../../services/attachments';
import { useFocusTrap } from '../../services/focus-trap';
import { ImageIcon, LayoutSidebarIcon, PencilIcon, XIcon } from '../../components/icons';

const useComposer = create<{ open: boolean }>(() => ({ open: false }));

export function openStatusComposer(): void {
  useComposer.setState({ open: true });
}

export function StatusComposer(): JSX.Element | null {
  const open = useComposer((state) => state.open);
  return open ? <Composer /> : null;
}

interface Draft {
  kind: StatusKind;
  /** What will be uploaded: the shrunk picture, or the video as it was picked. */
  blob: Blob;
  /** A local object URL for the preview. Revoked when the draft is dropped. */
  preview: string;
  /** Measured from the file itself, for a video. */
  durationMs?: number;
}

function Composer(): JSX.Element {
  const trap = useFocusTrap<HTMLDivElement>();
  const post = useStatusStore((state) => state.post);

  const [drafts, setDrafts] = useState<Draft[]>([]);
  const [layout, setLayout] = useState(false);
  const [text, setText] = useState('');
  const [caption, setCaption] = useState('');
  const [background, setBackground] = useState<string>(STATUS_BACKGROUNDS[0]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const media = useRef<HTMLInputElement>(null);

  // Layout draws pictures onto one picture, and a video is not a picture. It
  // is offered on two or more, and only when every one of them is one.
  const layoutable = drafts.length > 1 && drafts.every((draft) => draft.kind === 'PHOTO');
  const collaging = layout && layoutable;

  const close = (): void => {
    drafts.forEach((draft) => URL.revokeObjectURL(draft.preview));
    useComposer.setState({ open: false });
  };

  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape' && !busy) close();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  });

  const choose = async (files: FileList | null): Promise<void> => {
    if (!files || files.length === 0) return;
    setError(null);
    const picked: Draft[] = [];
    for (const file of Array.from(files)) {
      try {
        if (file.type.startsWith('video/')) {
          const preview = URL.createObjectURL(file);
          const durationMs = await videoDuration(preview);
          picked.push({
            kind: 'VIDEO',
            blob: file,
            preview,
            // Clamped, not cut: the file goes up whole and the viewer stops at
            // the cap. See STATUS_VIDEO_MAX_MS.
            durationMs: Math.min(durationMs, STATUS_VIDEO_MAX_MS),
          });
          continue;
        }
        // The same shrink an attached photo gets: a status is looked at on a
        // phone for five seconds, and a 12-megapixel original is bytes nobody
        // sees. It also settles the format - the server takes the bytes it can
        // recognise, and this hands it a JPEG.
        const shrunk = await shrinkImage(file);
        const blob = shrunk?.blob ?? file;
        picked.push({ kind: 'PHOTO', blob, preview: URL.createObjectURL(blob) });
      } catch {
        setError('That file could not be read');
      }
    }
    setDrafts((was) => [...was, ...picked]);
  };

  const drop = (at: number): void => {
    setDrafts((was) => {
      const going = was[at];
      if (going) URL.revokeObjectURL(going.preview);
      return was.filter((_, index) => index !== at);
    });
  };

  const submit = async (): Promise<void> => {
    setBusy(true);
    setError(null);
    const words = caption.trim();
    try {
      if (drafts.length === 0) {
        await post({ kind: 'TEXT', caption: text.trim(), background });
      } else if (collaging) {
        const drawn = await collage(drafts.map((draft) => draft.blob));
        await post({ kind: 'PHOTO', ...(words ? { caption: words } : {}) }, drawn);
      } else {
        // One post each, in the order they were picked, so the run reads the
        // way the roll did. Sequential rather than parallel: each seals against
        // the audience and appends to the tray, and the tray is one list.
        for (const draft of drafts) {
          const request: StatusDraft = {
            kind: draft.kind,
            ...(words ? { caption: words } : {}),
            ...(draft.durationMs ? { durationMs: Math.round(draft.durationMs) } : {}),
          };
          await post(request, draft.blob);
        }
      }
      close();
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : 'That could not be posted');
      setBusy(false);
    }
  };

  const ready = drafts.length > 0 ? true : text.trim().length > 0;

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label="Add a moment"
      className="fixed inset-0 z-[70] flex animate-fade flex-col bg-black/95"
    >
      <header className="flex items-center gap-3 px-4 py-3 text-white">
        <button
          type="button"
          onClick={close}
          disabled={busy}
          aria-label="Cancel"
          className="flex h-8 w-8 cursor-pointer items-center justify-center rounded-full text-white/80 transition-colors hover:bg-white/10 hover:text-white"
        >
          <XIcon className="h-5 w-5" />
        </button>
        <h1 className="flex-1 text-sm font-semibold">Add a moment</h1>
        <button
          type="button"
          onClick={() => void submit()}
          disabled={!ready || busy}
          className="cursor-pointer rounded-full bg-accent px-5 py-1.5 text-sm font-semibold text-white transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-40"
        >
          {busy ? 'Posting…' : 'Post'}
        </button>
      </header>

      <div className="mx-auto flex min-h-0 w-full max-w-md flex-1 flex-col px-4 pb-4">
        {drafts.length > 0 ? (
          <>
            <div className="min-h-0 flex-1 overflow-hidden rounded-xl bg-black">
              {collaging ? (
                // What the drawn picture will look like, laid out the way
                // `collage` lays it out: a square grid, cover-cropped.
                <div
                  className="grid h-full w-full gap-0.5"
                  style={{
                    gridTemplateColumns: `repeat(${Math.ceil(Math.sqrt(drafts.length))}, minmax(0, 1fr))`,
                  }}
                >
                  {drafts.map((draft) => (
                    <img
                      key={draft.preview}
                      src={draft.preview}
                      alt=""
                      className="h-full w-full object-cover"
                    />
                  ))}
                </div>
              ) : drafts[0]?.kind === 'PHOTO' ? (
                <img src={drafts[0].preview} alt="" className="h-full w-full object-contain" />
              ) : (
                <video
                  src={drafts[0]?.preview}
                  controls
                  playsInline
                  className="h-full w-full object-contain"
                />
              )}
            </div>

            {drafts.length > 1 && !collaging && (
              <div className="mt-2 flex gap-2 overflow-x-auto pb-1">
                {drafts.map((draft, at) => (
                  <button
                    key={draft.preview}
                    type="button"
                    onClick={() => drop(at)}
                    aria-label={`Remove item ${at + 1}`}
                    title="Remove"
                    className="relative h-14 w-14 shrink-0 cursor-pointer overflow-hidden rounded-lg border border-white/15"
                  >
                    <img src={draft.preview} alt="" className="h-full w-full object-cover" />
                    <span className="absolute right-0.5 top-0.5 rounded-full bg-black/70 px-1 text-[10px] text-white">
                      ✕
                    </span>
                  </button>
                ))}
              </div>
            )}

            <input
              value={caption}
              onChange={(event) => setCaption(event.target.value)}
              maxLength={STATUS_CAPTION_MAX_LENGTH}
              placeholder="Add a caption…"
              className="mt-3 w-full rounded-full border border-white/15 bg-white/10 px-4 py-2.5 text-sm text-white placeholder:text-white/40 focus:border-accent focus:outline-none"
            />
          </>
        ) : (
          <>
            {/* The text status is the default, not a second tab: it is the one
                that needs nothing but the keyboard already on screen. */}
            <div
              className="flex min-h-0 flex-1 items-center justify-center rounded-xl px-6 transition-colors"
              style={{ backgroundColor: background }}
            >
              {/* Not `h-full`: a box that fills the panel puts its first line,
                  and the placeholder with it, hard against the top edge. Sized
                  to its rows and centred by the flex box around it, which is
                  where a moment of words belongs. */}
              <textarea
                value={text}
                onChange={(event) => setText(event.target.value)}
                maxLength={STATUS_CAPTION_MAX_LENGTH}
                rows={4}
                placeholder="Type a moment"
                aria-label="Moment text"
                className="max-h-full w-full resize-none bg-transparent py-6 text-center text-2xl font-semibold leading-snug text-white placeholder:text-white/50 focus:outline-none"
              />
            </div>

            <div className="mt-3 flex items-center justify-center gap-2">
              {STATUS_BACKGROUNDS.map((colour) => (
                <button
                  key={colour}
                  type="button"
                  onClick={() => setBackground(colour)}
                  aria-label={`Background ${colour}`}
                  aria-pressed={background === colour}
                  style={{ backgroundColor: colour }}
                  className={`h-7 w-7 cursor-pointer rounded-full border-2 transition-transform ${
                    background === colour ? 'scale-110 border-white' : 'border-transparent'
                  }`}
                />
              ))}
            </div>
          </>
        )}

        <div className="mt-4 flex items-center justify-center gap-3">
          <Pick
            label="Media"
            icon={<ImageIcon className="h-5 w-5" />}
            onClick={() => media.current?.click()}
          />
          {layoutable && (
            <Pick
              label="Layout"
              icon={<LayoutSidebarIcon className="h-5 w-5" />}
              active={layout}
              onClick={() => setLayout((was) => !was)}
            />
          )}
          <Pick
            label="Text"
            icon={<PencilIcon className="h-5 w-5" />}
            active={drafts.length === 0}
            onClick={() => {
              drafts.forEach((draft) => URL.revokeObjectURL(draft.preview));
              setDrafts([]);
              setLayout(false);
              setCaption('');
            }}
          />
        </div>

        {error && (
          <p role="alert" className="mt-3 text-center text-sm text-danger">
            {error}
          </p>
        )}
      </div>

      <input
        ref={media}
        type="file"
        accept="image/*,video/*"
        multiple
        hidden
        onChange={(event) => {
          void choose(event.target.files);
          event.target.value = '';
        }}
      />
    </div>
  );
}

function Pick({
  label,
  icon,
  onClick,
  active = false,
}: {
  label: string;
  icon: JSX.Element;
  onClick?: () => void;
  active?: boolean;
}): JSX.Element {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-current={active ? 'true' : undefined}
      className={`flex cursor-pointer items-center gap-2 rounded-full px-4 py-2 text-sm transition-colors ${
        active ? 'bg-white/20 text-white' : 'bg-white/10 text-white/80 hover:bg-white/20'
      }`}
    >
      {icon}
      {label}
    </button>
  );
}

/**
 * Several pictures drawn onto one, as a square grid.
 *
 * A grid rather than a designed collage: the point is that four photos of one
 * afternoon post as one moment, and a layout engine to arrange them is a
 * feature nobody asked for. Each cell is cover-cropped and clipped to itself,
 * so a portrait beside a landscape fills its square rather than spilling into
 * the next one.
 *
 * ponytail: fixed 512px cells and one grid shape. Per-count layouts - the big
 * one on the left, two stacked beside it - are the upgrade if the grid ever
 * looks wrong for three.
 */
async function collage(blobs: Blob[]): Promise<Blob> {
  const images = await Promise.all(blobs.map((blob) => createImageBitmap(blob)));
  const columns = Math.ceil(Math.sqrt(images.length));
  const rows = Math.ceil(images.length / columns);
  const cell = 512;

  const canvas = document.createElement('canvas');
  canvas.width = columns * cell;
  canvas.height = rows * cell;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('That layout could not be drawn');
  context.fillStyle = '#000000';
  context.fillRect(0, 0, canvas.width, canvas.height);

  images.forEach((image, at) => {
    const left = (at % columns) * cell;
    const top = Math.floor(at / columns) * cell;
    const scale = Math.max(cell / image.width, cell / image.height);
    const width = image.width * scale;
    const height = image.height * scale;
    context.save();
    context.beginPath();
    context.rect(left, top, cell, cell);
    context.clip();
    context.drawImage(image, left + (cell - width) / 2, top + (cell - height) / 2, width, height);
    context.restore();
    image.close();
  });

  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => (blob ? resolve(blob) : reject(new Error('That layout could not be drawn'))),
      'image/jpeg',
      0.9,
    );
  });
}

/**
 * How long a picked video runs.
 *
 * Read from a detached `<video>` because that is the only thing in a browser
 * that can answer it, and the answer can be `Infinity` for a stream-shaped
 * file - which is treated as the cap rather than as a failure, so a clip that
 * will not report its length still posts.
 */
function videoDuration(url: string): Promise<number> {
  return new Promise((resolve) => {
    const element = document.createElement('video');
    element.preload = 'metadata';
    element.onloadedmetadata = () => {
      const seconds = element.duration;
      resolve(Number.isFinite(seconds) ? seconds * 1000 : STATUS_VIDEO_MAX_MS);
    };
    element.onerror = () => resolve(STATUS_VIDEO_MAX_MS);
    element.src = url;
  });
}

/**
 * The status tray: your own run at the top, then everybody else's.
 *
 * Split into "Recent moments" and "Viewed moments" rather than one list sorted
 * by time, for the same reason the ring has two colours - the useful question
 * is not when somebody posted, it is whether there is anything left to watch.
 * A single list buries the one unwatched run under four you finished an hour
 * ago.
 *
 * Nothing here plays anything: a row opens `StatusViewer`, which is the one
 * player in the app.
 */
import { useEffect } from 'react';
import type { StatusFeedEntry } from '@betweenus/shared-types';
import { useAuthStore } from '../../stores/auth';
import { runsOf, useStatusStore } from '../../stores/status';
import { listState } from '../../services/list-state';
import { Avatar } from '../../components/Avatar';
import { MenuIcon, PlusIcon } from '../../components/icons';
import { SkeletonRows } from '../../components/Skeleton';
import { statusAge } from './age';
import { MomentsEmptyArt } from './MomentsEmptyArt';
import { openStatus } from './StatusViewer';
import { openStatusComposer } from './StatusComposer';
import { MomentThumb } from './MomentThumb';

export function StatusScreen({ onOpenMenu }: { onOpenMenu?: () => void }): JSX.Element {
  const me = useAuthStore((state) => state.user);
  const mine = useStatusStore((state) => state.mine);
  const runs = useStatusStore(runsOf);
  const load = useStatusStore((state) => state.load);
  const loading = useStatusStore((state) => state.loading);
  const loaded = useStatusStore((state) => state.loaded);
  const error = useStatusStore((state) => state.error);

  // Read on arrival as well as on the socket's announcement: a window that was
  // asleep while somebody posted has a stale tray and no event coming.
  useEffect(() => {
    void load();
  }, [load]);

  const recent = runs.filter((run) => run.unseen);
  const viewed = runs.filter((run) => !run.unseen);
  const state = listState(runs.length, loading && !loaded);

  return (
    <main className="panel flex min-w-0 flex-1 flex-col bg-surface-900">
      <header className="flex h-11 shrink-0 items-center gap-2 border-b border-edge px-3">
        {onOpenMenu && (
          <button
            type="button"
            onClick={onOpenMenu}
            aria-label="Open menu"
            className="flex h-8 w-8 cursor-pointer items-center justify-center rounded-md text-slate-400 hover:bg-white/[0.06] hover:text-slate-200 md:hidden"
          >
            <MenuIcon className="h-5 w-5" />
          </button>
        )}
        <h1 className="text-sm font-semibold text-slate-200">Moments</h1>
        <p className="ms-auto text-xs text-slate-500">Posts disappear after 24 hours</p>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto px-2 py-3">
        {/* Your own row is both the way in to the composer and the way back to
            what you have already posted, which is why the plus badge sits on
            the avatar rather than being a second button beside it. */}
        <button
          type="button"
          onClick={() => (mine.length > 0 ? openStatus(me?.id ?? '') : openStatusComposer())}
          className="flex w-full cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-start transition-colors duration-200 row-idle"
        >
          <span className="relative shrink-0">
            {/* What you posted once there is something to show, and your own
                face while there is not - an empty circle with a plus on it is
                the invitation, and it needs to look like you. */}
            {mine.length > 0 ? (
              <MomentThumb posts={mine} />
            ) : (
              <Avatar
                userId={me?.id ?? ''}
                name={me?.displayName ?? 'You'}
                avatarUrl={me?.avatarUrl ?? null}
                viewable={false}
              />
            )}
            {mine.length === 0 && (
              <span className="absolute -bottom-0.5 -end-0.5 flex h-4 w-4 items-center justify-center rounded-full border-2 border-surface-900 bg-accent text-white">
                <PlusIcon className="h-2.5 w-2.5" />
              </span>
            )}
          </span>
          <span className="min-w-0 flex-1">
            <span className="block truncate font-medium text-slate-100">My moments</span>
            <span className="block truncate text-xs text-slate-500">
              {mine.length === 0
                ? 'Tap to add a moment'
                : `${countLabel(mine.length)} · ${statusAge(mine[mine.length - 1]!.createdAt)}`}
            </span>
          </span>
          {mine.length > 0 && (
            <span
              onClick={(event) => {
                // The row opens what is there; the plus adds to it. Two acts,
                // one row - so this one has to keep the row from also firing.
                event.preventDefault();
                event.stopPropagation();
                openStatusComposer();
              }}
              role="button"
              tabIndex={0}
              aria-label="Add a moment"
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  openStatusComposer();
                }
              }}
              className="flex h-8 w-8 shrink-0 cursor-pointer items-center justify-center rounded-full text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-100"
            >
              <PlusIcon className="h-4 w-4" />
            </span>
          )}
        </button>

        {error && (
          <p role="alert" className="px-2 py-2 text-sm text-danger">
            {error}
          </p>
        )}

        {state === 'loading' && (
          <SkeletonRows rows={3} label="Loading moments" className="px-2 py-2" />
        )}

        {state === 'empty' && !error && (
          <div className="flex flex-col items-center px-6 py-10 text-center">
            <MomentsEmptyArt className="h-28 w-36 text-slate-500" />
            <p className="mt-4 text-sm font-semibold text-slate-200">No moments yet</p>
            <p className="mt-1.5 max-w-xs text-sm text-slate-400">
              Moments from your friends appear here, and disappear a day later.
            </p>
          </div>
        )}

        {recent.length > 0 && <Heading>Recent moments</Heading>}
        {recent.map((run) => (
          <Row key={run.author.id} run={run} />
        ))}

        {viewed.length > 0 && <Heading>Viewed moments</Heading>}
        {viewed.map((run) => (
          <Row key={run.author.id} run={run} />
        ))}
      </div>
    </main>
  );
}

function Heading({ children }: { children: string }): JSX.Element {
  return (
    <p className="px-2 pb-1 pt-5 text-xs font-bold uppercase tracking-wide text-slate-400">
      {children}
    </p>
  );
}

function Row({ run }: { run: StatusFeedEntry }): JSX.Element {
  const newest = run.statuses[run.statuses.length - 1];
  return (
    <button
      type="button"
      onClick={() => openStatus(run.author.id)}
      className="flex w-full cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-start transition-colors duration-200 row-idle"
    >
      {/* The newest post rather than the face: the name beside it already says
          whose run this is, and the circle is what the tap opens. */}
      <MomentThumb posts={run.statuses} unseen={run.unseen} />
      <span className="min-w-0 flex-1">
        <span className="block truncate font-medium text-slate-100">{run.author.displayName}</span>
        <span className="block truncate text-xs text-slate-500">
          {countLabel(run.statuses.length)}
          {newest ? ` · ${statusAge(newest.createdAt)}` : ''}
        </span>
      </span>
    </button>
  );
}

function countLabel(count: number): string {
  return count === 1 ? '1 moment' : `${count} moments`;
}

/**
 * Somebody's statuses, full screen, one after another.
 *
 * The shape is the one everybody already knows: a bar per post along the top
 * that fills while the post is up, a tap on the left for the previous and on
 * the right for the next, a press-and-hold to stop the clock. Getting that
 * right matters more than anything visual here - it is the only interface in
 * this app people arrive already knowing, and every deviation from it reads as
 * a bug rather than a choice.
 *
 * Runs are chained: reaching the end of one person's posts moves on to the
 * next person who has some, which is what makes the tray a queue rather than a
 * list of things to open one at a time. `openStatus` decides where in that
 * queue to start.
 *
 * One overlay for the whole app, mounted at the root, the same as
 * `ProfileScreen` - so a ring in a sidebar, a row in the tray and an avatar in
 * a conversation all open the same thing rather than three of them.
 */
import { useEffect, useRef, useState } from 'react';
import { create } from 'zustand';
import type { StatusEntry, StatusViewer as Viewer } from '@betweenus/shared-types';
import { STATUS_PHOTO_MS } from '@betweenus/shared-types';
import { useAuthStore } from '../../stores/auth';
import { runsOf, useStatusStore } from '../../stores/status';
import { statusMedia } from '../../services/status-media';
import { useFocusTrap } from '../../services/focus-trap';
import { Avatar } from '../../components/Avatar';
import { ChevronLeftIcon, ChevronRightIcon, EyeIcon, TrashIcon, XIcon } from '../../components/icons';
import { statusAge } from './age';

interface Opened {
  /** Whose run is on screen. */
  authorId: string;
  /** Which post in that run, from 0. */
  index: number;
}

const useViewer = create<{ open: Opened | null }>(() => ({ open: null }));

/**
 * Opens somebody's statuses.
 *
 * Starts at their first unopened post rather than at the beginning, because
 * the beginning is where somebody who has already watched half a run does not
 * want to be. A run that has been watched through opens at the start again -
 * there is nothing unseen to resume to.
 */
export function openStatus(authorId: string, index?: number): void {
  useViewer.setState({ open: { authorId, index: index ?? firstUnseen(authorId) } });
}

export function closeStatus(): void {
  useViewer.setState({ open: null });
}

function firstUnseen(authorId: string): number {
  const state = useStatusStore.getState();
  const posts =
    authorId === useAuthStore.getState().user?.id
      ? state.mine
      : (runsOf(state).find((run) => run.author.id === authorId)?.statuses ?? []);
  const at = posts.findIndex((post) => !post.seen);
  return at === -1 ? 0 : at;
}

export function StatusViewer(): JSX.Element | null {
  const open = useViewer((state) => state.open);
  if (!open) return null;
  // Keyed on the person, so moving from one run to the next remounts the
  // player rather than carrying the previous run's timer and blob into it.
  return <Player key={open.authorId} open={open} />;
}

function Player({ open }: { open: Opened }): JSX.Element | null {
  const trap = useFocusTrap<HTMLDivElement>();
  const selfId = useAuthStore((state) => state.user?.id ?? null);
  const me = useAuthStore((state) => state.user);
  const mine = useStatusStore((state) => state.mine);
  const runs = useStatusStore(runsOf);
  const markSeen = useStatusStore((state) => state.markSeen);
  const removeStatus = useStatusStore((state) => state.remove);

  const isSelf = open.authorId === selfId;
  const run = runs.find((entry) => entry.author.id === open.authorId);
  const posts = isSelf ? mine : (run?.statuses ?? []);
  const author = isSelf
    ? me && {
        id: me.id,
        displayName: me.displayName,
        avatarUrl: me.avatarUrl,
      }
    : run?.author;

  const post = posts[open.index];

  const [paused, setPaused] = useState(false);
  const [viewers, setViewers] = useState<Viewer[] | null>(null);

  // The clock is restarted by identity of the post, not by index: a tray that
  // reloads underneath the viewer must not rewind the post being watched.
  const postId = post?.id;

  /** Moves on, and off the end of a run onto the next person's. */
  const next = (): void => {
    if (open.index + 1 < posts.length) {
      useViewer.setState({ open: { authorId: open.authorId, index: open.index + 1 } });
      return;
    }
    // Own posts are not part of the queue: they are opened deliberately, and
    // finishing them lands nowhere rather than in somebody else's run.
    const queue = isSelf ? [] : runs;
    const at = queue.findIndex((entry) => entry.author.id === open.authorId);
    const following = at === -1 ? undefined : queue[at + 1];
    if (following) {
      useViewer.setState({ open: { authorId: following.author.id, index: 0 } });
      return;
    }
    closeStatus();
  };

  const previous = (): void => {
    if (open.index > 0) {
      useViewer.setState({ open: { authorId: open.authorId, index: open.index - 1 } });
    }
  };

  // A post that is on screen has been looked at. Recorded on arrival rather
  // than on completion: opening it is the look, and a viewer list that only
  // counted people who watched to the end would be a different feature.
  useEffect(() => {
    if (postId && !isSelf) markSeen(postId);
  }, [postId, isSelf, markSeen]);

  // The run emptied underneath the viewer - the post expired, or it was
  // deleted on another device. There is nothing left to draw.
  useEffect(() => {
    if (posts.length === 0) closeStatus();
    else if (open.index >= posts.length) {
      useViewer.setState({ open: { authorId: open.authorId, index: posts.length - 1 } });
    }
  }, [posts.length, open.index, open.authorId]);

  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') closeStatus();
      else if (event.key === 'ArrowRight') next();
      else if (event.key === 'ArrowLeft') previous();
      else if (event.key === ' ') {
        event.preventDefault();
        setPaused((was) => !was);
      }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  });

  // Opening the viewer list stops the clock: reading who watched is not
  // something to do against a five-second timer.
  useEffect(() => {
    if (viewers) setPaused(true);
  }, [viewers]);

  if (!post || !author) return null;

  return (
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label={`${author.displayName}'s moments`}
      className="fixed inset-0 z-[70] flex animate-fade flex-col bg-black/95"
    >
      <div className="mx-auto flex h-full w-full max-w-md flex-col">
        {/* The bars, one per post. The one playing animates; the ones before
            it are full and the ones after are empty, which is the whole of
            "how many are there and where am I". */}
        <div className="flex gap-1 px-3 pt-3">
          {posts.map((entry, at) => (
            <Bar
              key={entry.id}
              state={at < open.index ? 'done' : at > open.index ? 'todo' : 'playing'}
              durationMs={durationOf(post)}
              paused={paused}
              onDone={next}
            />
          ))}
        </div>

        <header className="flex items-center gap-3 px-3 py-3 text-white">
          <Avatar name={author.displayName} avatarUrl={author.avatarUrl} size="sm" viewable={false} />
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm font-semibold">
              {isSelf ? 'My moments' : author.displayName}
            </p>
            <p className="text-xs text-white/60">{statusAge(post.createdAt)}</p>
          </div>
          <button
            type="button"
            onClick={closeStatus}
            aria-label="Close moments"
            className="flex h-8 w-8 cursor-pointer items-center justify-center rounded-full text-white/80 transition-colors hover:bg-white/10 hover:text-white"
          >
            <XIcon className="h-5 w-5" />
          </button>
        </header>

        {/* The post itself, with the two tap targets over it. They are buttons
            rather than one region with coordinate maths, so a keyboard and a
            screen reader get the same two moves a thumb does. */}
        <div className="relative min-h-0 flex-1">
          <Slide post={post} paused={paused} />

          <div className="absolute inset-0 flex">
            <TapZone
              label="Previous moment"
              onClick={previous}
              onHold={setPaused}
              disabled={open.index === 0}
              className="w-1/3"
              icon={<ChevronLeftIcon className="h-6 w-6" />}
            />
            <TapZone
              label="Next moment"
              onClick={next}
              onHold={setPaused}
              className="flex-1"
              icon={<ChevronRightIcon className="h-6 w-6" />}
            />
          </div>
        </div>

        {post.caption && post.kind !== 'TEXT' && (
          <p className="px-4 pb-3 text-center text-sm text-white/90">{post.caption}</p>
        )}

        {/* Your own post gets the two things nobody else may have: who saw it,
            and the way to take it down. */}
        {isSelf && (
          <footer className="flex items-center justify-center gap-2 px-4 pb-4">
            <button
              type="button"
              onClick={() => {
                void useStatusStore
                  .getState()
                  .viewersOf(post.id)
                  .then(setViewers)
                  .catch(() => setViewers([]));
              }}
              className="flex cursor-pointer items-center gap-2 rounded-full bg-white/10 px-4 py-2 text-sm text-white transition-colors hover:bg-white/20"
            >
              <EyeIcon className="h-4 w-4" />
              {post.viewCount ?? 0}
              <span className="sr-only"> people have seen this</span>
            </button>
            <button
              type="button"
              onClick={() => {
                void removeStatus(post.id).catch(() => undefined);
              }}
              className="flex cursor-pointer items-center gap-2 rounded-full bg-white/10 px-4 py-2 text-sm text-white transition-colors hover:bg-danger hover:text-white"
            >
              <TrashIcon className="h-4 w-4" />
              Delete
            </button>
          </footer>
        )}
      </div>

      {viewers && (
        <ViewerList
          viewers={viewers}
          onClose={() => {
            setViewers(null);
            setPaused(false);
          }}
        />
      )}
    </div>
  );
}

/** How long this post holds the screen. A video runs for its own length. */
function durationOf(post: StatusEntry): number {
  return post.kind === 'VIDEO' && post.durationMs ? post.durationMs : STATUS_PHOTO_MS;
}

/**
 * One segment of the progress row.
 *
 * The fill is a CSS transition rather than a timer painting a width, and the
 * move to the next post is a `setTimeout` beside it. Two mechanisms for one
 * thing looks wrong until you try the alternatives: a `requestAnimationFrame`
 * loop repaints React sixty times a second for a bar, and a transition with no
 * timer behind it cannot tell anybody it finished when the tab was hidden.
 */
function Bar({
  state,
  durationMs,
  paused,
  onDone,
}: {
  state: 'done' | 'playing' | 'todo';
  durationMs: number;
  paused: boolean;
  onDone: () => void;
}): JSX.Element {
  const [width, setWidth] = useState(0);
  const started = useRef<number>(Date.now());
  const spent = useRef(0);

  // `onDone` is a new function on every render of the player, and the player
  // re-renders whenever the store moves - which the view marker does, a moment
  // after a post opens. Left in the dependency list it would clear and restart
  // the timer each time, so a post could outstay its five seconds for as long
  // as anything kept changing. The ref is what makes the effect depend on the
  // post rather than on the identity of a callback.
  const done = useRef(onDone);
  done.current = onDone;

  useEffect(() => {
    if (state !== 'playing') return;
    if (paused) {
      // Freeze where it is: read the painted width back rather than guessing,
      // and hold the elapsed time so resuming does not restart the post.
      spent.current += Date.now() - started.current;
      setWidth((Math.min(spent.current / durationMs, 1)) * 100);
      return;
    }
    started.current = Date.now();
    const left = Math.max(durationMs - spent.current, 0);
    // Two frames, not one: the browser has to paint the starting width before
    // the transition to 100% means anything, and one frame is not always
    // enough for the element that has just been mounted.
    const raf = requestAnimationFrame(() => requestAnimationFrame(() => setWidth(100)));
    const timer = window.setTimeout(() => done.current(), left);
    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(timer);
    };
  }, [state, paused, durationMs]);

  const filled = state === 'done' ? 100 : state === 'todo' ? 0 : width;
  const seconds = state === 'playing' && !paused ? Math.max(durationMs - spent.current, 0) : 0;

  return (
    <div className="h-0.5 flex-1 overflow-hidden rounded-full bg-white/25">
      <div
        className="h-full rounded-full bg-white"
        style={{
          width: `${filled}%`,
          transition: seconds ? `width ${seconds}ms linear` : 'none',
        }}
      />
    </div>
  );
}

/** The post's content: a picture, a video, or words on a colour. */
function Slide({ post, paused }: { post: StatusEntry; paused: boolean }): JSX.Element {
  const [url, setUrl] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const video = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    if (!post.mediaUrl) return;
    let live = true;
    setFailed(false);
    void statusMedia(post)
      .then((resolved) => {
        if (live) setUrl(resolved);
      })
      .catch(() => {
        if (live) setFailed(true);
      });
    return () => {
      live = false;
    };
  }, [post.id, post.mediaUrl]);

  // A held finger stops the video as well as the bar; the two running out of
  // step is the thing people notice immediately.
  useEffect(() => {
    const element = video.current;
    if (!element) return;
    if (paused) element.pause();
    else void element.play().catch(() => undefined);
  }, [paused, url]);

  if (post.kind === 'TEXT') {
    return (
      <div
        className="flex h-full w-full items-center justify-center px-8"
        style={{ backgroundColor: post.background ?? '#0F172A' }}
      >
        <p className="max-h-full overflow-y-auto whitespace-pre-wrap break-words text-center text-2xl font-semibold leading-snug text-white">
          {post.caption}
        </p>
      </div>
    );
  }

  if (failed) {
    return (
      <div className="flex h-full items-center justify-center px-8 text-center text-sm text-white/70">
        This status could not be loaded. It may have expired.
      </div>
    );
  }

  if (!url) {
    return (
      <div className="flex h-full items-center justify-center" aria-busy="true">
        <div className="h-8 w-8 animate-pulse rounded-full bg-white/20" />
      </div>
    );
  }

  if (post.kind === 'VIDEO') {
    return (
      <video
        ref={video}
        src={url}
        autoPlay
        playsInline
        // Muted, because a story that starts shouting is the behaviour every
        // one of these has and every one of them is wrong about. The control
        // strip lets it be turned up.
        muted={false}
        controls={false}
        className="h-full w-full object-contain"
      />
    );
  }

  return <img src={url} alt={post.caption ?? 'Moment'} className="h-full w-full object-contain" />;
}

/**
 * One half of the screen: a click moves, a press-and-hold pauses.
 *
 * The hold is a timer rather than "mouse down means paused", because a click
 * is also a mouse down - and pausing on every tap makes the bar stutter on its
 * way to the next post.
 */
function TapZone({
  label,
  onClick,
  onHold,
  disabled = false,
  className,
  icon,
}: {
  label: string;
  onClick: () => void;
  onHold: (paused: boolean) => void;
  disabled?: boolean;
  className: string;
  icon: JSX.Element;
}): JSX.Element {
  const holding = useRef<number | null>(null);
  const held = useRef(false);

  const down = (): void => {
    held.current = false;
    holding.current = window.setTimeout(() => {
      held.current = true;
      onHold(true);
    }, 200);
  };

  const up = (): void => {
    if (holding.current) window.clearTimeout(holding.current);
    holding.current = null;
    if (held.current) {
      onHold(false);
      return;
    }
    if (!disabled) onClick();
  };

  return (
    <button
      type="button"
      aria-label={label}
      disabled={disabled}
      onPointerDown={down}
      onPointerUp={up}
      onPointerLeave={() => {
        if (holding.current) window.clearTimeout(holding.current);
        if (held.current) onHold(false);
        holding.current = null;
        held.current = false;
      }}
      className={`group flex cursor-pointer items-center justify-center text-white/0 transition-colors hover:text-white/40 disabled:cursor-default ${className}`}
    >
      {icon}
    </button>
  );
}

/** Who watched one of your posts. */
function ViewerList({ viewers, onClose }: { viewers: Viewer[]; onClose: () => void }): JSX.Element {
  return (
    <div
      onClick={onClose}
      className="absolute inset-0 z-10 flex items-end justify-center bg-black/60 px-4 pb-4"
    >
      <div
        onClick={(event) => event.stopPropagation()}
        className="max-h-[60%] w-full max-w-md animate-pop overflow-y-auto rounded-xl border border-edge bg-surface-900 p-4"
      >
        <div className="mb-3 flex items-center justify-between">
          <h2 className="text-sm font-semibold text-slate-200">
            Viewed by {viewers.length}
          </h2>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close viewers"
            className="flex h-7 w-7 cursor-pointer items-center justify-center rounded-full text-slate-400 hover:bg-white/10 hover:text-slate-100"
          >
            <XIcon className="h-4 w-4" />
          </button>
        </div>
        {viewers.length === 0 ? (
          <p className="py-6 text-center text-sm text-slate-500">Nobody has seen this yet.</p>
        ) : (
          <ul className="space-y-1">
            {viewers.map((viewer) => (
              <li key={viewer.user.id} className="flex items-center gap-3 rounded-md px-1 py-1.5">
                <Avatar
                  name={viewer.user.displayName}
                  avatarUrl={viewer.user.avatarUrl}
                  size="sm"
                  viewable={false}
                />
                <span className="min-w-0 flex-1 truncate text-sm text-slate-200">
                  {viewer.user.displayName}
                </span>
                <span className="shrink-0 text-xs text-slate-500">
                  {statusAge(viewer.viewedAt)}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

/**
 * Apps, as one screen on the voice stage.
 *
 * The stage is where everything shared in a call is drawn - the tiles, a shared
 * video, a board - and this is the screen in front of all of it: what is there
 * to do together, and which of it is already happening.
 *
 * It replaced a popover, and the popover was wrong for the ordinary reasons a
 * popover usually is. A six-game library in a 17rem box is a list with three
 * rows visible and a scrollbar. A menu floating over a call covers the faces it
 * is meant to sit beside. And it needed portalling out of the sidebar, flipping
 * above or below the button, and re-measuring on every scroll - a page of
 * machinery to put a list somewhere the app already has a place for.
 *
 * Each card says whether that activity is already running, because the
 * commonest reason to open this is to get back to a game or a queue somebody
 * else started rather than to start one.
 */
import { GAMES, type GameSession, type ListenSession } from '@betweenus/shared-types';
import { useAppsStore } from '../../stores/apps';
import { useGameStore } from '../../stores/game';
import { useListenStore } from '../../stores/listen';
import { ChevronRightIcon, GamepadIcon, MusicIcon, XIcon } from '../../components/icons';

export function AppsPanel(): JSX.Element {
  const listen = useListenStore((state) => state.session);
  const game = useGameStore((state) => state.session);

  const openListen = (): void => {
    useAppsStore.getState().setOpen(false);
    useListenStore.getState().setOpen(true);
  };

  const openGame = (): void => {
    useAppsStore.getState().setOpen(false);
    useGameStore.getState().setOpen(true);
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-3">
      <div className="flex shrink-0 items-center gap-2">
        <span className="text-sm font-medium text-slate-200">Apps</span>
        <span className="text-[11px] text-slate-500">Things to do together in this call</span>
        <button
          type="button"
          onClick={() => useAppsStore.getState().setOpen(false)}
          aria-label="Close apps"
          title="Back to the call"
          className="ms-auto cursor-pointer rounded p-1 text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200"
        >
          <XIcon className="h-4 w-4" />
        </button>
      </div>

      <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-y-auto md:grid-cols-2">
        <AppCard
          icon={<MusicIcon className="h-5 w-5 text-amber-300" />}
          name="Listen together"
          blurb="One queue, in step, playing from everybody's own connection - so it stays at full quality and costs nobody any upload. Anybody here can change what is on."
          status={listenStatus(listen)}
          accent="amber"
          onClick={openListen}
        />
        <AppCard
          icon={<GamepadIcon className="h-5 w-5 text-emerald-300" />}
          name="Play together"
          blurb="Six board games on one board everybody sees - two of you play, the rest watch. The server referees the moves, so nothing is played on trust."
          status={gameStatus(game)}
          accent="emerald"
          onClick={openGame}
        />
      </div>
    </div>
  );
}

function listenStatus(session: ListenSession | null): string | null {
  if (!session) return null;
  const track = session.queue[session.index];
  if (!track) return null;
  return `${session.paused ? 'Paused' : 'Playing'} · ${track.title || track.ref}`;
}

function gameStatus(session: GameSession | null): string | null {
  if (!session) return null;
  const seated = session.seats.filter((seat) => seat !== null).length;
  return `${GAMES[session.gameId].definition.name} · round ${session.round} · ${seated} of ${session.seats.length} seated`;
}

function AppCard({
  icon,
  name,
  blurb,
  status,
  accent,
  onClick,
}: {
  icon: JSX.Element;
  name: string;
  blurb: string;
  /** What it is doing right now, or null when it is not doing anything. */
  status: string | null;
  accent: 'amber' | 'emerald';
  onClick: () => void;
}): JSX.Element {
  const ring =
    accent === 'amber'
      ? 'border-amber-400/40 hover:border-amber-400/60'
      : 'border-emerald-400/40 hover:border-emerald-400/60';

  return (
    <button
      type="button"
      onClick={onClick}
      className={`flex cursor-pointer flex-col gap-2 rounded-xl border p-4 text-start transition-colors ${
        status ? ring : 'border-white/10 hover:border-white/20'
      } bg-surface-900 hover:bg-white/[0.04]`}
    >
      <span className="flex items-center gap-2">
        {icon}
        <span className="text-sm font-medium text-slate-100">{name}</span>
        {status && (
          <span
            className={`rounded px-1.5 py-0.5 text-[9px] uppercase tracking-wide ${
              accent === 'amber'
                ? 'bg-amber-500/20 text-amber-200'
                : 'bg-emerald-500/20 text-emerald-200'
            }`}
          >
            on
          </span>
        )}
        <ChevronRightIcon className="ms-auto h-4 w-4 text-slate-600" />
      </span>

      {status && (
        <span
          className={`truncate text-xs ${accent === 'amber' ? 'text-amber-200' : 'text-emerald-200'}`}
        >
          {status}
        </span>
      )}

      <span className="text-[11px] leading-relaxed text-slate-400">{blurb}</span>
    </button>
  );
}

/**
 * Every remote voice track in the call, playing, for as long as the call lasts.
 *
 * Mounted once at the root of the workbench and never unmounted, which is the
 * whole point of it: the sinks used to live in the sidebar panel, so switching
 * to another server - or to the home screen, which swaps the sidebar entirely -
 * tore down every `<audio>` element and the call went silent while it was
 * still, by every other measure, connected.
 *
 * It renders nothing. The panel says who is here; this makes them audible.
 */
import { useVoiceStore } from '../../stores/voice';
import { AudioSink } from './MediaSink';

export function CallAudio(): JSX.Element | null {
  const status = useVoiceStore((state) => state.status);
  const tiles = useVoiceStore((state) => state.tiles);
  const watching = useVoiceStore((state) => state.watching);

  if (status === 'idle') return null;

  return (
    <>
      {tiles.map((tile) => (
        <span key={tile.identity}>
          {tile.audioTrack && <AudioSink track={tile.audioTrack} userId={tile.userId} />}
          {/* A shared screen brings its sound only to whoever is watching it,
              and at whatever volume that person is set to: turning somebody
              down and then being blasted by their film would be a lie. */}
          {tile.screenAudioTrack && watching === tile.identity && (
            <AudioSink track={tile.screenAudioTrack} userId={tile.userId} />
          )}
        </span>
      ))}
    </>
  );
}

import { useEffect, useState } from 'react';
import { useVoiceStore } from '../../stores/voice';
import { formatCallDuration } from '../../services/call-stats';

/**
 * How long the call has been running.
 *
 * The phone has had this from the beginning and neither of the other two
 * clients did, which was not a decision: on Android an ongoing-call
 * notification counts itself, and a desktop window or a browser tab has no
 * notification to hang that on. So it is drawn here.
 *
 * The clock is ticked rather than stored. Keeping a running count in the store
 * would be a state write a second for the length of every call, waking every
 * subscriber to the voice store each time - the participants list, the
 * controls, the tiles - to redraw one line of text. A local tick redraws
 * exactly this.
 *
 * It reads the wall clock on every tick rather than counting its own ticks,
 * because a timer that is throttled - which a background window's is,
 * aggressively - loses time, and a call clock that runs slow while the window
 * is behind another one is worse than no clock.
 */
export function CallDuration(): JSX.Element | null {
  const connectedAt = useVoiceStore((state) => state.connectedAt);
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    if (connectedAt === null) return;
    // Set immediately as well as on the interval: mounting this a second into
    // a call should not show 00:00 for a second.
    setNow(Date.now());
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, [connectedAt]);

  if (connectedAt === null) return null;

  return (
    <span
      // A live region would announce every second, which is a screen reader
      // reading a clock aloud for the length of a call. The duration is
      // available on demand, like a clock on a wall.
      aria-label="Call duration"
      className="shrink-0 font-mono text-slate-400 tabular-nums"
    >
      {formatCallDuration((now - connectedAt) / 1000)}
    </span>
  );
}

/**
 * The carrom board: nineteen men, four pockets, and an aim.
 *
 * Two things here are worth reading before the code.
 *
 * **The animation is the physics, not an impression of it.** When a shot comes
 * back from the gateway, this does not tween the coins from where they were to
 * where they ended up. It takes the board as it was *before* the shot, runs the
 * same simulation the gateway ran with the same three numbers, and draws the
 * frames that come out. The last of those frames is the board the gateway
 * already sent, because the simulation is deterministic - so the animation
 * cannot end anywhere except the truth.
 *
 * **You point at where it should go.** Press on the board and the striker aims
 * at your pointer; drag further out for more power and let go to flick it,
 * which is what a finger does to a striker on a real board. The first version
 * had it backwards - pull away from the striker like a catapult, the way a pool
 * game does - and a catapult is not the gesture anybody has for carrom.
 *
 * The striker itself slides along your own baseline, dragged left and right,
 * which is the other half of a carrom shot and the half a board without it
 * makes impossible.
 */
import { useEffect, useRef, useState } from 'react';
import {
  BASELINE_HALF_WIDTH,
  BOARD,
  COIN_RADIUS,
  POCKETS,
  POCKET_RADIUS,
  QUEEN,
  STRIKER,
  STRIKER_RADIUS,
  baselineY,
  carromPieces,
  carromShot,
  coinsOf,
  lastShot,
  placeStriker,
  queenPending,
  type GameSession,
  type GameState,
} from '@betweenus/shared-types';
import { canPlay, mySeat } from '../../stores/game';

/** Frames arrive at 60 a second, which is what the simulation samples at. */
const FRAME_MS = 1000 / 60;

/** Under this, a drag is a tap and not a shot. In board widths. */
const MIN_DRAG = 0.04;
/** A pull this long is full power. Longer is still full power. */
const MAX_DRAG = 0.42;

interface Props {
  session: GameSession;
  onMove: (move: number, params?: number[]) => void;
}

interface Aim {
  /** Where along the baseline the striker is, -1 to 1. */
  x: number;
  /** Where the pointer is, in board coordinates, while dragging. */
  pullX: number | null;
  pullY: number | null;
}

export function CarromBoard({ session, onMove }: Props): JSX.Element {
  const seat = mySeat(session);
  const mine = canPlay(session, 0);
  const [aim, setAim] = useState<Aim>({ x: 0, pullX: null, pullY: null });
  /** The frames of the shot being replayed, or null when the board is at rest. */
  const [frame, setFrame] = useState<number[] | null>(null);
  const before = useRef<GameState | null>(null);
  const svg = useRef<SVGSVGElement>(null);

  // Replay whatever the gateway just refereed. `before` is this window's own
  // copy of the board as it was, which is the one thing needed to reproduce a
  // shot from the three numbers that describe it.
  useEffect(() => {
    const previous = before.current;
    before.current = session.state;
    const shot = lastShot(session.state);
    if (!previous || !shot) return undefined;
    if (session.state.moveCount <= previous.moveCount) return undefined;

    const result = carromShot(previous, shot.seat, [shot.x, shot.angle, shot.power]);
    let index = 0;
    const timer = window.setInterval(() => {
      const next = result.frames[index];
      index += 1;
      if (!next) {
        window.clearInterval(timer);
        // Back to drawing the state itself. The last frame and the state are
        // the same board, so nothing jumps - but the state is the one that
        // carries a coin returned to the centre after a foul.
        setFrame(null);
        return;
      }
      setFrame(next);
    }, FRAME_MS);

    return () => {
      window.clearInterval(timer);
      setFrame(null);
    };
  }, [session.state]);

  const pieces = carromPieces(session.state);
  const shooting = mine && frame === null;
  const strikerAt = placeStriker(session.state, seat === -1 ? 0 : seat, aim.x);

  const toBoard = (event: React.PointerEvent<SVGSVGElement>): { x: number; y: number } => {
    const box = svg.current?.getBoundingClientRect();
    if (!box) return { x: 0, y: 0 };
    return {
      x: ((event.clientX - box.left) / box.width) * BOARD,
      y: ((event.clientY - box.top) / box.height) * BOARD,
    };
  };

  const release = (): void => {
    if (aim.pullX === null || aim.pullY === null) {
      setAim((current) => ({ ...current, pullX: null, pullY: null }));
      return;
    }
    // Towards the pointer, not away from it: the striker goes where you are
    // pointing, and how far out you are pointing is how hard it is hit.
    const dx = aim.pullX - strikerAt.x;
    const dy = aim.pullY - strikerAt.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    setAim((current) => ({ ...current, pullX: null, pullY: null }));
    // A tap is not a shot. Somebody who clicked the board to see what happens
    // should not lose a turn to a striker that dribbles two inches.
    if (distance < MIN_DRAG) return;
    onMove(0, [aim.x, Math.atan2(dy, dx), powerFrom(distance)]);
  };

  const power = pullPower(strikerAt, aim);

  const pull =
    aim.pullX !== null && aim.pullY !== null
      ? { x: aim.pullX, y: aim.pullY }
      : null;

  return (
    <div className="m-auto w-full max-w-[34rem]">
      <svg
        ref={svg}
        viewBox={`0 0 ${BOARD} ${BOARD}`}
        role="group"
        aria-label="Carrom board"
        className={`aspect-square w-full rounded-lg ${shooting ? 'cursor-crosshair' : ''}`}
        onPointerDown={(event) => {
          if (!shooting) return;
          const at = toBoard(event);
          event.currentTarget.setPointerCapture(event.pointerId);
          // Near your own line, a press means "move the striker". Anywhere else
          // it means "aim". One gesture each, decided by where it started, so
          // neither can steal the other.
          const onBaseline = Math.abs(at.y - baselineY(seat === -1 ? 0 : seat)) < 0.09;
          if (onBaseline) {
            setAim({ x: strikerXFrom(at.x), pullX: null, pullY: null });
            return;
          }
          setAim((current) => ({ ...current, pullX: at.x, pullY: at.y }));
        }}
        onPointerMove={(event) => {
          if (!shooting) return;
          if (aim.pullX === null) return;
          const at = toBoard(event);
          setAim((current) => ({ ...current, pullX: at.x, pullY: at.y }));
        }}
        onPointerUp={release}
        onPointerCancel={() => setAim((current) => ({ ...current, pullX: null, pullY: null }))}
      >
        <rect x={0} y={0} width={BOARD} height={BOARD} fill="#3b2a17" />
        <rect
          x={0.02}
          y={0.02}
          width={BOARD - 0.04}
          height={BOARD - 0.04}
          fill="#c99a5b"
          stroke="#7a4f22"
          strokeWidth={0.012}
        />

        {/* The printed circle in the middle, and the two rings around it. */}
        <circle cx={0.5} cy={0.5} r={0.085} fill="none" stroke="#8a5a28" strokeWidth={0.006} />
        <circle cx={0.5} cy={0.5} r={0.16} fill="none" stroke="#8a5a28" strokeWidth={0.004} />

        {/* Both baselines, with the shooter's own picked out. */}
        {[0, 1].map((line) => (
          <g key={line}>
            <line
              x1={0.5 - BASELINE_HALF_WIDTH - 0.02}
              y1={baselineY(line)}
              x2={0.5 + BASELINE_HALF_WIDTH + 0.02}
              y2={baselineY(line)}
              stroke={line === seat && shooting ? '#f8fafc' : '#8a5a28'}
              strokeWidth={line === seat && shooting ? 0.008 : 0.005}
            />
            <line
              x1={0.5 - BASELINE_HALF_WIDTH - 0.02}
              y1={baselineY(line) + (line === 0 ? 0.03 : -0.03)}
              x2={0.5 + BASELINE_HALF_WIDTH + 0.02}
              y2={baselineY(line) + (line === 0 ? 0.03 : -0.03)}
              stroke="#8a5a28"
              strokeWidth={0.005}
            />
          </g>
        ))}

        {POCKETS.map((pocket, index) => (
          <circle
            key={index}
            cx={pocket.x}
            cy={pocket.y}
            r={POCKET_RADIUS}
            fill="#160d05"
            stroke="#7a4f22"
            strokeWidth={0.006}
          />
        ))}

        {/* The men. During a replay these come from the frame that is being
            drawn; the rest of the time from the state itself. */}
        {pieces.map((piece, index) => {
          const x = frame ? frame[index * 3]! : piece.x;
          const y = frame ? frame[index * 3 + 1]! : piece.y;
          const onBoard = frame ? frame[index * 3 + 2] === 1 : piece.onBoard;
          if (!onBoard) return null;
          if (index === STRIKER) {
            return (
              <circle
                key={index}
                cx={x}
                cy={y}
                r={STRIKER_RADIUS}
                fill="#fef3c7"
                stroke="#92400e"
                strokeWidth={0.005}
              />
            );
          }
          return (
            <circle
              key={index}
              cx={x}
              cy={y}
              r={COIN_RADIUS}
              fill={index === QUEEN ? '#dc2626' : coinsOf(0).includes(index) ? '#f8fafc' : '#1e293b'}
              stroke="#00000055"
              strokeWidth={0.003}
            />
          );
        })}

        {/* The striker waiting to be hit, and the line it will go along. Drawn
            only for whoever is shooting: everybody else is watching a board
            with no striker on it, which is what a real one looks like between
            shots. */}
        {shooting && (
          <>
            <circle
              cx={strikerAt.x}
              cy={strikerAt.y}
              r={STRIKER_RADIUS}
              fill="#fef3c7"
              stroke="#f59e0b"
              strokeWidth={0.007}
            />
            {pull && (
              <>
                {/* Where it is going: from the striker, through the pointer,
                    on into the board. It is drawn past the pointer because the
                    striker does not stop there - the line is the shot, not the
                    drag. */}
                <line
                  x1={strikerAt.x}
                  y1={strikerAt.y}
                  x2={strikerAt.x + (pull.x - strikerAt.x) * 4}
                  y2={strikerAt.y + (pull.y - strikerAt.y) * 4}
                  stroke="#fbbf24"
                  strokeWidth={0.006}
                  strokeDasharray="0.02 0.015"
                />
                <circle cx={pull.x} cy={pull.y} r={0.012} fill="#fbbf24" />
                {/* How hard, as a bar that fills along the line of the shot.
                    Power is a distance, and a number nobody can see is a number
                    nobody can aim with. */}
                <line
                  x1={strikerAt.x}
                  y1={strikerAt.y}
                  x2={strikerAt.x + (pull.x - strikerAt.x) * Math.min(1, power)}
                  y2={strikerAt.y + (pull.y - strikerAt.y) * Math.min(1, power)}
                  stroke={power > 0.85 ? '#f87171' : '#fde68a'}
                  strokeWidth={0.014}
                  strokeLinecap="round"
                />
              </>
            )}
          </>
        )}
      </svg>

      <p className="mt-1.5 text-center text-[11px] text-slate-500">
        {frame !== null
          ? 'Playing the shot…'
          : shooting
            ? 'Slide the striker along your line to place it. Then press where you want it to go - further out is harder - and let go.'
            : queenPending(session.state) !== -1
              ? 'The queen is uncovered - whoever took her must pocket one of their own next.'
              : 'Watching.'}
      </p>
    </div>
  );
}

/** How hard a drag of this length hits, 0 to 1. */
function powerFrom(distance: number): number {
  return Math.min(1, (distance - MIN_DRAG) / (MAX_DRAG - MIN_DRAG) + 0.08);
}

/** The power of the drag in progress, for the bar that shows it. */
function pullPower(striker: { x: number; y: number }, aim: Aim): number {
  if (aim.pullX === null || aim.pullY === null) return 0;
  const dx = aim.pullX - striker.x;
  const dy = aim.pullY - striker.y;
  return powerFrom(Math.sqrt(dx * dx + dy * dy));
}

/** A board x, turned into the -1..1 the rules take. */
function strikerXFrom(x: number): number {
  const offset = (x - BOARD / 2) / BASELINE_HALF_WIDTH;
  return Math.max(-1, Math.min(1, offset));
}

/**
 * What the call is doing, in numbers, for the person in it.
 *
 * "It looks bad" and "the link is bad" were the same sentence until this
 * existed, and telling them apart meant opening `chrome://webrtc-internals` -
 * which is not something to ask of somebody mid-meeting. One row per person,
 * the four numbers that decide how a call feels, and nothing else.
 */
import { useVoiceStore } from '../../stores/voice';
import {
  echoAdvice,
  echoCancellerFailing,
  healthWarning,
  type LinkStats,
  type QualityLimit,
} from '../../services/call-stats';
import { useAudioSettings } from '../../stores/audioSettings';

/** `qualityLimitationReason`, said the way somebody in a call would say it. */
const LIMIT_REASON: Record<QualityLimit, string> = {
  bandwidth: 'the link',
  cpu: 'this PC',
  other: 'the encoder',
};

export function ConnectionPanel({ onClose }: { onClose: () => void }): JSX.Element {
  const stats = useVoiceStore((state) => state.stats);
  const echoErleDb = useVoiceStore((state) => state.echoErleDb);
  const settings = useAudioSettings((state) => state.settings);
  const warning = healthWarning(stats);

  // Separate from `healthWarning`, which reads the link. Echo is not a property
  // of any link - it is this machine playing the call back into its own
  // microphone - so it survives a connection that is otherwise perfect, and
  // reporting it alongside packet loss would say the network is at fault.
  const echoFailing = echoCancellerFailing(
    settings.echoCancellation && settings.mode !== 'hifi',
    echoErleDb,
  );

  return (
    <div className="absolute bottom-full left-1/2 z-40 mb-2 w-[320px] -translate-x-1/2 animate-pop rounded-xl border border-edge bg-surface-900 p-3 shadow-pop">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-semibold text-slate-100">Connection</h2>
        <button
          type="button"
          onClick={onClose}
          className="cursor-pointer rounded px-2 py-0.5 text-xs text-slate-400 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100"
        >
          Close
        </button>
      </div>

      {warning && <p className="mt-2 rounded bg-danger/10 px-2 py-1 text-xs text-danger">{warning}</p>}

      {echoFailing && (
        <p role="status" className="mt-2 rounded bg-amber-500/10 px-2 py-1 text-xs text-amber-200">
          {echoAdvice(settings.outputDeviceId !== null)}
        </p>
      )}

      {stats.length === 0 ? (
        <p className="mt-3 text-xs text-slate-400">
          Nobody else is connected yet, so there is nothing to measure.
        </p>
      ) : (
        <ul className="mt-2 space-y-2">
          {stats.map((link) => (
            <PeerRow key={link.peerId} link={link} />
          ))}
        </ul>
      )}

      <p className="mt-3 text-[11px] leading-snug text-slate-500">
        Media goes straight between the two machines, so these are the two of you and whatever is
        between - no server is in this path to blame.
      </p>
    </div>
  );
}

function PeerRow({ link }: { link: LinkStats }): JSX.Element {
  const loss = link.lossPercent ?? 0;
  const rtt = link.roundTripMs ?? 0;

  return (
    <li className="rounded-lg bg-surface-800 px-3 py-2">
      <p className="truncate text-sm text-slate-100">{link.name}</p>
      <dl className="mt-1 grid grid-cols-2 gap-x-3 gap-y-0.5 text-xs">
        <Stat label="Down" value={rate(link.downKbps)} />
        <Stat label="Up" value={rate(link.upKbps)} />
        <Stat
          label="Loss"
          value={link.lossPercent === null ? '—' : `${link.lossPercent}%`}
          tone={loss >= 5 ? 'bad' : loss >= 1 ? 'warn' : 'plain'}
        />
        <Stat
          label="Round trip"
          value={link.roundTripMs === null ? '—' : `${link.roundTripMs} ms`}
          tone={rtt >= 300 ? 'bad' : rtt >= 150 ? 'warn' : 'plain'}
        />
        {link.frameWidth && link.frameHeight && (
          <Stat
            label="In"
            value={`${link.frameWidth}×${link.frameHeight}${
              link.framesPerSecond ? ` @ ${link.framesPerSecond}` : ''
            }`}
          />
        )}
        {link.sendWidth && link.sendHeight && (
          <Stat label="Out" value={`${link.sendWidth}×${link.sendHeight}`} />
        )}
        {/*
          Only when something is actually holding the picture down, and it is
          the whole answer to "why did my share go soft": the link, this
          machine's encoder, or neither.
        */}
        {link.sendLimitedBy && (
          <Stat label="Held by" value={LIMIT_REASON[link.sendLimitedBy]} tone="warn" />
        )}
      </dl>
    </li>
  );
}

function Stat({
  label,
  value,
  tone = 'plain',
}: {
  label: string;
  value: string;
  tone?: 'plain' | 'warn' | 'bad';
}): JSX.Element {
  const colour =
    tone === 'bad' ? 'text-danger' : tone === 'warn' ? 'text-amber-300' : 'text-slate-200';
  return (
    <div className="flex items-baseline justify-between gap-2">
      <dt className="text-slate-500">{label}</dt>
      <dd className={`tabular-nums ${colour}`}>{value}</dd>
    </div>
  );
}

/** Kilobits until it is silly, then megabits. A share is megabits. */
function rate(kbps: number | null): string {
  if (kbps === null) return '—';
  if (kbps < 1000) return `${kbps} kbps`;
  return `${(kbps / 1000).toFixed(1)} Mbps`;
}

/**
 * Microphone and speakers, changed from inside the call.
 *
 * The full set of controls lives in Settings → Voice & Video, but the moment
 * somebody wants their devices is the moment they cannot be heard - which is a
 * bad time to go looking through a settings screen. Discord puts the same two
 * lists behind the arrow on the mute button for the same reason.
 *
 * It writes to the same store the settings screen does, so a change here is
 * remembered and applied to the running call by the voice store.
 */
import { useEffect, useRef } from 'react';
import { DeviceSelect, useDevices } from '../../components/DeviceSelect';
import { useAudioSettings } from '../../stores/audioSettings';

export function DevicePicker({ onClose }: { onClose: () => void }): JSX.Element {
  const [devices] = useDevices();
  const settings = useAudioSettings((state) => state.settings);
  const update = useAudioSettings((state) => state.update);
  const panel = useRef<HTMLDivElement>(null);

  // A popover closes when it is clicked away from or Escape is pressed; a
  // pointerdown rather than a click, so a drag that starts outside counts.
  useEffect(() => {
    const away = (event: PointerEvent): void => {
      if (!panel.current?.contains(event.target as Node)) onClose();
    };
    const key = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    document.addEventListener('pointerdown', away);
    document.addEventListener('keydown', key);
    return () => {
      document.removeEventListener('pointerdown', away);
      document.removeEventListener('keydown', key);
    };
  }, [onClose]);

  return (
    <div
      ref={panel}
      className="absolute bottom-full start-0 z-30 mb-2 w-72 space-y-4 rounded-lg bg-surface-800 p-4 shadow-lg"
    >
      <DeviceSelect
        label="Input device"
        kind="audioinput"
        devices={devices}
        value={settings.inputDeviceId}
        onChange={(inputDeviceId) => update({ inputDeviceId })}
      />
      <DeviceSelect
        label="Output device"
        kind="audiooutput"
        devices={devices}
        value={settings.outputDeviceId}
        onChange={(outputDeviceId) => update({ outputDeviceId })}
      />
      <p className="text-xs text-slate-400">
        Sensitivity and processing are in Settings → Voice &amp; Video.
      </p>
    </div>
  );
}

/**
 * The boards.
 *
 * One component per game, and each of them draws `session.state` and nothing
 * else: there is no local board here, no optimistic placement and no animation
 * that outlives a message. A move goes to the gateway, the gateway referees it,
 * and the state that comes back is what is on screen. That is a round trip of
 * latency on every click, and it is the right trade - a board that showed a
 * disc before it was agreed would show a different game to the person who
 * played it, which is the one thing a shared board must never do.
 *
 * What each of them *does* do locally is refuse a click that cannot be played,
 * using the same rules the gateway will use. That is not a permission check -
 * the gateway's is - it is so a square that is going to be ignored looks like
 * one before it is pressed.
 */
import {
  CELLS as DOTS_CELLS,
  COLUMNS,
  DOTS,
  GAMES,
  REVERSI_SIZE,
  ROWS,
  connectFourAt,
  horizontal,
  landing,
  vertical,
  winningLine,
  type GameSession,
} from '@betweenus/shared-types';
import { canPlay } from '../../stores/game';
import { CarromBoard } from './CarromBoard';
import { LudoBoard } from './LudoBoard';

interface BoardProps {
  session: GameSession;
  /**
   * `params` completes a move an index cannot express - a carrom shot's
   * placement, aim and power. Every other board ignores it.
   */
  onMove: (move: number, params?: number[]) => void;
}

/** The board for whichever game is on the table. */
export function GameBoard({ session, onMove }: BoardProps): JSX.Element {
  switch (session.gameId) {
    case 'tic-tac-toe':
      return <TicTacToeBoard session={session} onMove={onMove} />;
    case 'connect-four':
      return <ConnectFourBoard session={session} onMove={onMove} />;
    case 'reversi':
      return <ReversiBoard session={session} onMove={onMove} />;
    case 'dots-and-boxes':
      return <DotsAndBoxesBoard session={session} onMove={onMove} />;
    case 'ludo':
      return <LudoBoard session={session} onMove={onMove} />;
    case 'carrom':
      return <CarromBoard session={session} onMove={onMove} />;
    default:
      // A game this build has never heard of, which is what an older client
      // looking at a newer call looks like. Saying so beats an empty rectangle.
      return (
        <p className="m-auto max-w-xs text-center text-xs text-slate-500">
          Somebody started a game this version does not know how to draw. Update
          to join in.
        </p>
      );
  }
}

/** The colour a seat plays in, from the rules rather than from each board. */
function colourOf(session: GameSession, seat: number): string {
  return GAMES[session.gameId].definition.seatColours[seat] ?? '#94a3b8';
}

function TicTacToeBoard({ session, onMove }: BoardProps): JSX.Element {
  const { cells, lastMove } = session.state;
  const line = winningLine(cells);

  return (
    <div className="m-auto grid aspect-square w-full max-w-[22rem] grid-cols-3 gap-1.5">
      {cells.map((owner, index) => {
        const playable = canPlay(session, index);
        return (
          <button
            key={index}
            type="button"
            disabled={!playable}
            onClick={() => onMove(index)}
            aria-label={`Square ${index + 1}`}
            className={`flex items-center justify-center rounded-lg border text-4xl font-semibold transition-colors ${
              line?.includes(index)
                ? 'border-white/30 bg-white/[0.10]'
                : 'border-white/10 bg-surface-900'
            } ${playable ? 'cursor-pointer hover:bg-white/[0.06]' : 'cursor-default'} ${
              lastMove === index ? 'ring-1 ring-white/25' : ''
            }`}
            style={{ color: owner === -1 ? undefined : colourOf(session, owner) }}
          >
            {owner === -1 ? '' : GAMES['tic-tac-toe'].definition.seatNames[owner]}
          </button>
        );
      })}
    </div>
  );
}

function ConnectFourBoard({ session, onMove }: BoardProps): JSX.Element {
  const { cells, lastMove } = session.state;

  return (
    <div className="m-auto flex w-full max-w-[30rem] flex-col gap-1">
      {/* Whole columns, not squares: a click means "drop one in here", which is
          what the move on the wire says as well. Two people pressing the same
          column stack rather than racing for one hole. */}
      <div className="grid grid-cols-7 gap-1 rounded-lg bg-sky-950/60 p-2">
        {Array.from({ length: COLUMNS }, (_, column) => {
          const playable = canPlay(session, column);
          const next = landing(cells, column);
          return (
            <button
              key={column}
              type="button"
              disabled={!playable}
              onClick={() => onMove(column)}
              aria-label={`Drop a disc in column ${column + 1}`}
              className={`group flex flex-col gap-1 rounded ${
                playable ? 'cursor-pointer hover:bg-white/[0.06]' : 'cursor-default'
              }`}
            >
              {Array.from({ length: ROWS }, (_, row) => {
                const index = connectFourAt(row, column);
                const owner = cells[index] ?? -1;
                return (
                  <span
                    key={row}
                    className={`aspect-square w-full rounded-full ${
                      owner === -1 ? 'bg-surface-950' : ''
                    } ${lastMove === index ? 'ring-2 ring-white/40' : ''}`}
                    style={{
                      background: owner === -1 ? undefined : colourOf(session, owner),
                      // A ghost of the disc that would land, so a column reads
                      // as a move before it is one.
                      boxShadow:
                        playable && row === next
                          ? `inset 0 0 0 2px ${colourOf(session, session.state.turn)}55`
                          : undefined,
                    }}
                  />
                );
              })}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ReversiBoard({ session, onMove }: BoardProps): JSX.Element {
  const { cells, lastMove } = session.state;
  // The legal squares, drawn as faint spots. Reversi is the one game here where
  // "what may I play" is not obvious from looking, and a beginner who cannot
  // see it plays three illegal moves and assumes the board is broken.
  const legal = new Set(GAMES.reversi.moves(session.state));
  const mine = legal.size > 0 && canPlay(session, [...legal][0]!);

  return (
    <div className="m-auto grid aspect-square w-full max-w-[30rem] grid-cols-8 gap-px rounded-lg bg-emerald-950 p-1">
      {cells.map((owner, index) => (
        <button
          key={index}
          type="button"
          disabled={!canPlay(session, index)}
          onClick={() => onMove(index)}
          aria-label={`Square ${Math.floor(index / REVERSI_SIZE) + 1}, ${(index % REVERSI_SIZE) + 1}`}
          className={`flex items-center justify-center bg-emerald-900/70 transition-colors ${
            canPlay(session, index) ? 'cursor-pointer hover:bg-emerald-800' : 'cursor-default'
          }`}
        >
          {owner !== -1 ? (
            <span
              className={`h-[78%] w-[78%] rounded-full ${
                lastMove === index ? 'ring-2 ring-amber-300/70' : ''
              }`}
              style={{ background: colourOf(session, owner) }}
            />
          ) : mine && legal.has(index) ? (
            <span className="h-[26%] w-[26%] rounded-full bg-white/25" />
          ) : null}
        </button>
      ))}
    </div>
  );
}

function DotsAndBoxesBoard({ session, onMove }: BoardProps): JSX.Element {
  const { cells, boxes, lastMove } = session.state;
  // One SVG unit per box, plus a margin, so the whole board scales with the
  // stage and the click targets scale with it - a line drawn at a fixed pixel
  // width is unhittable on a laptop and enormous on a monitor.
  const step = 10;
  const pad = 5;
  const size = pad * 2 + step * DOTS_CELLS;

  const line = (index: number, x: number, y: number, w: number, h: number): JSX.Element => {
    const owner = cells[index] ?? -1;
    const playable = canPlay(session, index);
    return (
      <rect
        key={index}
        x={x - 1.2}
        y={y - 1.2}
        width={w + 2.4}
        height={h + 2.4}
        rx={1.2}
        fill={owner === -1 ? (playable ? '#ffffff14' : 'transparent') : colourOf(session, owner)}
        stroke={lastMove === index ? '#fff' : 'none'}
        strokeWidth={0.4}
        className={playable ? 'cursor-pointer' : ''}
        onClick={playable ? () => onMove(index) : undefined}
      >
        <title>{owner === -1 ? 'Draw this line' : 'Drawn'}</title>
      </rect>
    );
  };

  return (
    <svg
      viewBox={`0 0 ${size} ${size}`}
      role="group"
      aria-label="Dots and boxes"
      className="m-auto aspect-square w-full max-w-[28rem]"
    >
      {boxes.map((owner, index) =>
        owner === -1 ? null : (
          <rect
            key={`box-${index}`}
            x={pad + (index % DOTS_CELLS) * step}
            y={pad + Math.floor(index / DOTS_CELLS) * step}
            width={step}
            height={step}
            fill={`${colourOf(session, owner)}33`}
          />
        ),
      )}

      {Array.from({ length: DOTS }, (_, r) =>
        Array.from({ length: DOTS_CELLS }, (_, c) =>
          line(horizontal(r, c), pad + c * step, pad + r * step, step, 0),
        ),
      )}
      {Array.from({ length: DOTS_CELLS }, (_, r) =>
        Array.from({ length: DOTS }, (_, c) =>
          line(vertical(r, c), pad + c * step, pad + r * step, 0, step),
        ),
      )}

      {Array.from({ length: DOTS }, (_, r) =>
        Array.from({ length: DOTS }, (_, c) => (
          <circle
            key={`dot-${r}-${c}`}
            cx={pad + c * step}
            cy={pad + r * step}
            r={0.9}
            fill="#94a3b8"
          />
        )),
      )}

      {/* The initial of whoever closed each box, because two pale fills are
          hard to tell apart at a glance and the score is the whole game. */}
      {boxes.map((owner, index) =>
        owner === -1 ? null : (
          <text
            key={`mark-${index}`}
            x={pad + (index % DOTS_CELLS) * step + step / 2}
            y={pad + Math.floor(index / DOTS_CELLS) * step + step / 2 + 1.6}
            textAnchor="middle"
            fontSize={4}
            fill={colourOf(session, owner)}
          >
            {GAMES['dots-and-boxes'].definition.seatNames[owner]?.[0] ?? ''}
          </text>
        ),
      )}
    </svg>
  );
}

/**
 * Play Together, as one panel that takes the voice stage.
 *
 * The same shape as the listening panel, and for the same reasons: a board is
 * a thing people look at with their whole attention for a minute at a time, so
 * it takes the stage rather than living in a popover, and it is drawn in
 * exactly one place - `VoiceChannelView` - because `VoiceControls` is rendered
 * twice and anything it drew from shared state would be drawn twice.
 *
 * Two states, not two tabs. With nothing on the table this is the library;
 * with a game on it, it is the board and the chairs. There is no "back to the
 * library" that abandons a game by accident - changing the game is a deliberate
 * thing, and it is behind the same button that started this one.
 */
import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import {
  GAMES,
  GAME_LIBRARY,
  gameReady,
  gameScore,
  type GameId,
  type GameSession,
} from '@betweenus/shared-types';
import { mySeat, turnLine, useGameStore } from '../../stores/game';
import { useAppsStore } from '../../stores/apps';
import { GameBoard } from './GameBoards';
import {
  ChevronLeftIcon,
  GamepadIcon,
  MaximizeIcon,
  MinimizeIcon,
  RotateIcon,
  TrophyIcon,
  UserIcon,
  XIcon,
} from '../../components/icons';

export function GamePanel(): JSX.Element {
  const fullscreen = useGameStore((state) => state.fullscreen);

  // Fullscreen is a portal rather than a class on the panel, because the panel
  // lives inside the voice stage, which is inside a column, inside a `.panel`
  // that is `overflow-hidden`. A `fixed inset-0` element inside all of that is
  // still laid out by its ancestors' stacking contexts, and it was clipped.
  // Attached to the body, it is the window.
  const panel = <Board />;
  if (!fullscreen) return panel;

  return createPortal(
    <div className="fixed inset-0 z-50 flex flex-col gap-2 bg-surface-950 p-4">{panel}</div>,
    document.body,
  );
}

function Board(): JSX.Element {
  const session = useGameStore((state) => state.session);
  const fullscreen = useGameStore((state) => state.fullscreen);
  const [choosing, setChoosing] = useState(false);

  // Escape leaves fullscreen rather than closing the panel, which is what
  // Escape means everywhere a thing has taken over a screen. It is only bound
  // while it has, so it cannot quietly eat the key anywhere else.
  useEffect(() => {
    if (!fullscreen) return undefined;
    const key = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') useGameStore.getState().setFullscreen(false);
    };
    window.addEventListener('keydown', key);
    return () => window.removeEventListener('keydown', key);
  }, [fullscreen]);

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-2">
      <div className="flex shrink-0 items-center gap-2">
        {/* Back to the chooser, not out of the call: this screen was reached
            from Apps, and the way back is where you came from. Hidden in
            fullscreen, where there is nothing to go back to on screen. */}
        {!fullscreen && (
          <button
            type="button"
            onClick={() => {
              useGameStore.getState().setOpen(false);
              useAppsStore.getState().setOpen(true);
            }}
            aria-label="Back to apps"
            title="Apps"
            className="-ms-1 cursor-pointer rounded p-1 text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200"
          >
            <ChevronLeftIcon className="h-4 w-4" />
          </button>
        )}
        <GamepadIcon className="h-4 w-4 shrink-0 text-emerald-300" />
        <span className="text-sm font-medium text-slate-200">
          {session ? GAMES[session.gameId].definition.name : 'Play together'}
        </span>
        {session && (
          <span className="rounded bg-surface-800 px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-slate-400">
            round {session.round}
          </span>
        )}

        {session && (
          <button
            type="button"
            onClick={() => setChoosing((open) => !open)}
            className="ms-2 cursor-pointer rounded px-2 py-1 text-[11px] text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200"
          >
            {choosing ? 'Back to the board' : 'Change game'}
          </button>
        )}

        {/* The board is the one thing in the call that wants the whole window.
            Carrom's coins are a fiftieth of the board across, so the difference
            between a thin cut and a miss is a few pixels on a shared stage. */}
        <button
          type="button"
          onClick={() => useGameStore.getState().setFullscreen(!fullscreen)}
          aria-label={fullscreen ? 'Leave fullscreen' : 'Fullscreen'}
          title={fullscreen ? 'Leave fullscreen - Esc' : 'Fullscreen'}
          className="ms-auto cursor-pointer rounded p-1 text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200"
        >
          {fullscreen ? (
            <MinimizeIcon className="h-4 w-4" />
          ) : (
            <MaximizeIcon className="h-4 w-4" />
          )}
        </button>

        <button
          type="button"
          onClick={() => useGameStore.getState().setOpen(false)}
          aria-label="Close play together"
          title="Close - the game stays on the table"
          className="cursor-pointer rounded p-1 text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200"
        >
          <XIcon className="h-4 w-4" />
        </button>
      </div>

      {!session || choosing ? (
        <Library
          onPick={(gameId) => {
            useGameStore.getState().openGame(gameId);
            setChoosing(false);
          }}
        />
      ) : (
        <div className="flex min-h-0 flex-1 flex-col gap-2 lg:flex-row lg:gap-3">
          <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-2">
            {/* The chairs, above the board, on any window too narrow for the
                rail beside it. This is the whole of the "the game is not
                clickable" bug: the rail was `lg:` only, so on an ordinary
                window nobody could see an empty chair, let alone take one - and
                a board with an empty chair takes no moves, correctly and
                silently. A control that decides whether the thing works may not
                be the first thing a breakpoint hides. */}
            <SeatStrip session={session} />
            <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
              <GameBoard session={session} onMove={(move, params) => useGameStore.getState().move(move, params)} />
              <WaitingOverlay session={session} />
            </div>
          </div>
          <Table session={session} />
        </div>
      )}

      {session && !choosing && <Status session={session} />}
    </div>
  );
}

/**
 * The library.
 *
 * Six games, each a card that starts one. Everything here is playable by two
 * people with the same board in front of them and nothing hidden, which is not
 * a taste in games: the session is broadcast whole to the whole call, so a game
 * needing a secret hand would be one with everybody's hand in the message.
 */
function Library({ onPick }: { onPick: (gameId: GameId) => void }): JSX.Element {
  return (
    <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto">
      <p className="shrink-0 text-xs leading-relaxed text-slate-400">
        Pick something and take a chair. Everybody in the call sees the same
        board - two of you play it, the rest watch - and a move is a few bytes,
        so it costs nobody any upload and works wherever the call does.
      </p>

      <div className="grid grid-cols-1 gap-2 sm:grid-cols-2 xl:grid-cols-3">
        {GAME_LIBRARY.map((gameId) => {
          const { name, blurb, seats, length, seatColours } = GAMES[gameId].definition;
          return (
            <button
              key={gameId}
              type="button"
              onClick={() => onPick(gameId)}
              className="flex cursor-pointer flex-col gap-2 rounded-lg border border-white/10 bg-surface-900 p-3 text-start transition-colors hover:border-white/20 hover:bg-white/[0.04]"
            >
              <div className="flex items-center gap-1.5">
                {seatColours.map((colour) => (
                  <span
                    key={colour}
                    className="h-2.5 w-2.5 rounded-full"
                    style={{ background: colour }}
                  />
                ))}
                <span className="ms-auto text-[10px] uppercase tracking-wide text-slate-600">
                  {seats} players · {length}
                </span>
              </div>
              <span className="text-sm font-medium text-slate-100">{name}</span>
              <span className="text-[11px] leading-relaxed text-slate-400">{blurb}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

/**
 * The chairs, on one line, for a window that has no room for the rail.
 *
 * Hidden on `lg` and up, where `Table` says the same things with space for the
 * tally. Below that this is the only way to sit down, so it is not decoration.
 */
function SeatStrip({ session }: { session: GameSession }): JSX.Element {
  const { definition } = GAMES[session.gameId];
  const seat = mySeat(session);

  return (
    <div className="flex shrink-0 flex-wrap items-center gap-1.5 lg:hidden">
      {session.seats.map((who, index) => {
        const theirTurn = session.state.winner === null && session.state.turn === index;
        return (
          <button
            key={index}
            type="button"
            disabled={Boolean(who) && index !== seat}
            onClick={() =>
              index === seat
                ? useGameStore.getState().stand()
                : useGameStore.getState().sit(index)
            }
            title={
              who
                ? index === seat
                  ? 'Stand up - the chair is freed for somebody else'
                  : `${who.username} is playing here`
                : 'Take this chair'
            }
            className={`flex items-center gap-1.5 rounded-md border px-2 py-1 text-[11px] transition-colors ${
              theirTurn && gameReady(session)
                ? 'border-white/25 bg-white/[0.08] text-slate-100'
                : 'border-white/10 bg-surface-900 text-slate-300'
            } ${who && index !== seat ? 'cursor-default' : 'cursor-pointer hover:bg-white/[0.06]'}`}
          >
            <span
              className="h-2.5 w-2.5 shrink-0 rounded-full"
              style={{ background: definition.seatColours[index] }}
            />
            <span className="max-w-[9rem] truncate">
              {who ? who.username : 'Sit here'}
            </span>
            <span className="text-slate-600">{definition.seatNames[index]}</span>
            {session.wins[index]! > 0 && (
              <span className="text-amber-300">{session.wins[index]}</span>
            )}
          </button>
        );
      })}
    </div>
  );
}

/**
 * Why the board is not taking clicks.
 *
 * A board waiting for a second player is a board where every square is
 * correctly refused, and the first version said so only in a status line at
 * the bottom - which reads exactly like a game that is broken. It says it over
 * the board instead, with the chair to take right there.
 */
function WaitingOverlay({ session }: { session: GameSession }): JSX.Element | null {
  if (gameReady(session)) return null;
  const empty = session.seats.findIndex((seat) => seat === null);
  const watching = mySeat(session) === -1;

  return (
    <div className="pointer-events-none absolute inset-0 flex items-center justify-center p-4">
      <div className="pointer-events-auto flex max-w-xs flex-col items-center gap-2 rounded-xl border border-white/10 bg-surface-950/90 px-4 py-3 text-center backdrop-blur-sm">
        <p className="text-xs text-slate-300">
          {watching
            ? 'There is an empty chair. Take it and the game starts.'
            : 'Waiting for somebody else in the call to take the other chair.'}
        </p>
        {watching && empty !== -1 && (
          <button
            type="button"
            onClick={() => useGameStore.getState().sit(empty)}
            className="flex cursor-pointer items-center gap-1.5 rounded-md bg-emerald-500/20 px-3 py-1.5 text-xs font-medium text-emerald-100 transition-colors hover:bg-emerald-500/30"
          >
            <UserIcon className="h-3.5 w-3.5" />
            Sit down as {GAMES[session.gameId].definition.seatNames[empty]}
          </button>
        )}
      </div>
    </div>
  );
}

/**
 * The chairs, and what each of them has won.
 *
 * An empty chair is a button, because that is the whole of joining a game: the
 * person who opened it is already sitting down, and the second player is one
 * click away from being in it.
 */
function Table({ session }: { session: GameSession }): JSX.Element {
  const { definition } = GAMES[session.gameId];
  const score = gameScore(session.state);
  const seat = mySeat(session);

  return (
    <aside className="hidden w-52 shrink-0 flex-col gap-2 lg:flex">
      {session.seats.map((who, index) => {
        const playing = session.state.winner === null && session.state.turn === index;
        return (
          <div
            key={index}
            className={`rounded-lg border p-2.5 transition-colors ${
              playing && gameReady(session)
                ? 'border-white/25 bg-white/[0.06]'
                : 'border-white/10 bg-surface-900'
            }`}
          >
            <div className="flex items-center gap-2">
              <span
                className="h-3 w-3 shrink-0 rounded-full"
                style={{ background: definition.seatColours[index] }}
              />
              <span className="truncate text-xs text-slate-200">
                {who ? who.username : 'Empty chair'}
              </span>
              {session.wins[index]! > 0 && (
                <span className="ms-auto flex shrink-0 items-center gap-1 text-[10px] text-amber-300">
                  <TrophyIcon className="h-3 w-3" />
                  {session.wins[index]}
                </span>
              )}
            </div>
            <div className="mt-1 flex items-center gap-2">
              <span className="text-[10px] uppercase tracking-wide text-slate-600">
                {definition.seatNames[index]}
              </span>
              {score[index] !== undefined && (
                <span className="text-[10px] tabular-nums text-slate-500">{score[index]}</span>
              )}
              {!who && (
                <button
                  type="button"
                  onClick={() => useGameStore.getState().sit(index)}
                  className="ms-auto flex cursor-pointer items-center gap-1 rounded bg-emerald-500/15 px-2 py-0.5 text-[10px] font-medium text-emerald-200 transition-colors hover:bg-emerald-500/25"
                >
                  <UserIcon className="h-3 w-3" />
                  Sit here
                </button>
              )}
              {who && index === seat && (
                <button
                  type="button"
                  onClick={() => useGameStore.getState().stand()}
                  className="ms-auto cursor-pointer rounded px-2 py-0.5 text-[10px] text-slate-500 transition-colors hover:bg-white/[0.06] hover:text-slate-300"
                >
                  Stand up
                </button>
              )}
            </div>
          </div>
        );
      })}

      <p className="text-[10px] leading-relaxed text-slate-600">
        Anybody in the call can take an empty chair. Leave the call and yours is
        freed - the board stays exactly as it is.
      </p>
    </aside>
  );
}

/** Whose move it is, and the two buttons that end a game. */
function Status({ session }: { session: GameSession }): JSX.Element {
  const seat = mySeat(session);
  const over = session.state.winner !== null;

  return (
    <div className="flex shrink-0 items-center gap-2 rounded-lg bg-surface-900 px-3 py-2">
      <GamepadIcon
        className={`h-4 w-4 shrink-0 ${over ? 'text-amber-300' : 'text-emerald-300'}`}
      />
      <span className="truncate text-xs text-slate-200">{turnLine(session)}</span>

      {/* The score, spelled out for whoever is watching rather than playing -
          they have no chair to read it off. */}
      <span className="hidden truncate text-[11px] text-slate-500 sm:inline">
        {session.seats
          .map(
            (who, index) =>
              `${who?.username ?? GAMES[session.gameId].definition.seatNames[index]} ${session.wins[index] ?? 0}`,
          )
          .join(' · ')}
      </span>

      {over && seat !== -1 && (
        <button
          type="button"
          onClick={() => useGameStore.getState().rematch()}
          className="ms-auto flex cursor-pointer items-center gap-1.5 rounded-md bg-emerald-500/15 px-2.5 py-1 text-[11px] font-medium text-emerald-200 transition-colors hover:bg-emerald-500/25"
        >
          <RotateIcon className="h-3.5 w-3.5" />
          Play again
        </button>
      )}

      <button
        type="button"
        onClick={() => useGameStore.getState().close()}
        title="Take the board away for everybody"
        className={`${over && seat !== -1 ? '' : 'ms-auto'} shrink-0 cursor-pointer rounded px-2 py-1 text-[11px] text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200`}
      >
        End game
      </button>
    </div>
  );
}

/**
 * What is on the table, while the panel is closed.
 *
 * One line above the tiles, so the call goes back to being a call and the game
 * is still visibly a thing that is happening - and it says "your move", which
 * is the only part of it anybody needs while they are looking at faces.
 */
export function GameBar(): JSX.Element | null {
  const session = useGameStore((state) => state.session);
  const open = useGameStore((state) => state.open);
  if (!session || open) return null;

  const yours = mySeat(session) === session.state.turn && session.state.winner === null;
  return (
    <button
      type="button"
      onClick={() => useGameStore.getState().setOpen(true)}
      className={`flex shrink-0 cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-start transition-colors ${
        yours && gameReady(session)
          ? 'bg-emerald-500/15 hover:bg-emerald-500/25'
          : 'bg-surface-900 hover:bg-white/[0.06]'
      }`}
    >
      <GamepadIcon className="h-4 w-4 shrink-0 text-emerald-300" />
      <span className="truncate text-xs text-slate-200">
        {GAMES[session.gameId].definition.name}
      </span>
      <span className="truncate text-[11px] text-slate-400">{turnLine(session)}</span>
      <span className="ms-auto shrink-0 text-[11px] text-slate-500">Open</span>
    </button>
  );
}

/**
 * The ringer: somebody is calling, and this window has to interrupt.
 *
 * A modal rather than a toast, and deliberately. Everything else this app
 * raises can be caught up with - a message waits, a roster is still true in ten
 * minutes - but a ring is a person waiting for an answer right now, and a
 * notification that scrolls away with the others is a call that goes
 * unanswered while its owner is looking at the screen.
 *
 * Two buttons and nothing else. The decision is Answer or not, and every
 * control that is not one of those two is one somebody has to read past while
 * a phone is ringing at them.
 */
import { useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Avatar } from '../../components/Avatar';
import { PhoneIcon, PhoneOffIcon } from '../../components/icons';
import { absoluteUrl } from '../../services/endpoint';
import { useRingStore } from '../../stores/ring';
import { useFocusTrap } from '../../services/focus-trap';

export function IncomingCall(): JSX.Element | null {
  const trap = useFocusTrap<HTMLDivElement>();
  const incoming = useRingStore((state) => state.incoming);
  const answer = useRingStore((state) => state.answer);
  const decline = useRingStore((state) => state.decline);

  // Escape declines. Nothing else is bound: Enter is not, because a window
  // that gets focus mid-keystroke would answer a call on a keypress meant for
  // whatever was on screen a moment ago.
  useEffect(() => {
    if (!incoming) return;
    const key = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') decline();
    };
    document.addEventListener('keydown', key);
    return () => document.removeEventListener('keydown', key);
  }, [incoming, decline]);

  if (!incoming) return null;

  return createPortal(
    <div
      ref={trap}
      role="dialog"
      aria-modal="true"
      aria-label={`${incoming.callerName} is calling`}
      className="fixed inset-0 z-[60] flex animate-fade items-center justify-center bg-black/70 p-6"
    >
      <div className="flex w-full max-w-sm animate-pop flex-col items-center gap-5 rounded-2xl border border-edge bg-surface-900 px-8 py-9 text-center shadow-pop">
        {/* The ring animation is the only decoration here, and it earns its
            place: it is what tells somebody glancing over that the window is
            asking rather than telling. */}
        <span className="relative flex">
          <span className="absolute inset-0 animate-ping rounded-full bg-accent/25" />
          <Avatar
            name={incoming.callerName}
            avatarUrl={incoming.callerAvatarUrl ? absoluteUrl(incoming.callerAvatarUrl) : null}
            size="lg"
          />
        </span>

        <div>
          <p className="text-lg font-semibold text-slate-100">{incoming.callerName}</p>
          <p className="mt-1 text-sm text-slate-400">
            is calling you into <span className="text-slate-300">{incoming.channelName}</span>
          </p>
        </div>

        <div className="mt-2 flex items-center gap-10">
          <CallButton
            label="Decline"
            className="bg-danger hover:bg-danger-hover"
            onClick={decline}
            icon={<PhoneOffIcon className="h-6 w-6" />}
          />
          <CallButton
            label="Answer"
            className="bg-status-online hover:bg-status-online/90"
            onClick={answer}
            icon={<PhoneIcon className="h-6 w-6" />}
          />
        </div>
      </div>
    </div>,
    document.body,
  );
}

function CallButton({
  label,
  icon,
  className,
  onClick,
}: {
  label: string;
  icon: JSX.Element;
  className: string;
  onClick: () => void;
}): JSX.Element {
  return (
    <div className="flex flex-col items-center gap-2">
      <button
        type="button"
        aria-label={label}
        onClick={onClick}
        className={`flex h-14 w-14 items-center justify-center rounded-full text-white transition-transform duration-150 hover:scale-105 ${className}`}
      >
        {icon}
      </button>
      <span className="text-xs text-slate-400">{label}</span>
    </div>
  );
}

/**
 * "Come into this call", from inside the call.
 *
 * The ring already existed in the member list, which is the wrong place to
 * reach for it: "who else should be here" is a thought somebody has while
 * looking at a call with two people in it, and in the full-screen voice view
 * there is no member list on screen to go through. The phone put it in the
 * call dock for the same reason; this is the same button.
 *
 * The roster announcement tells a channel a call is happening and deliberately
 * rings nobody - a client that buzzed every time anybody joined any voice
 * channel is a client with notifications turned off. This is the aimed half, so
 * it may ring wherever they are signed in.
 */
import { useEffect, useRef, useState } from 'react';
import { api } from '../../services/api';
import { useAuthStore } from '../../stores/auth';
import { useChatStore } from '../../stores/chat';
import { useStatusOf } from '../../stores/presence';
import { useVoiceStore } from '../../stores/voice';
import { Avatar } from '../../components/Avatar';

export function InvitePicker({ onClose }: { onClose: () => void }): JSX.Element {
  const panel = useRef<HTMLDivElement>(null);
  const channelId = useVoiceStore((state) => state.channelId);
  const tiles = useVoiceStore((state) => state.tiles);
  const members = useChatStore((state) => state.members);
  const statusOf = useStatusOf();
  const selfId = useAuthStore((state) => state.user?.id);

  /** Per person: 'ringing', 'rang', or why it failed. Untouched people absent. */
  const [rung, setRung] = useState<Record<string, string>>({});

  // Same popover rules as the device picker: a pointerdown outside, or Escape.
  useEffect(() => {
    const away = (event: PointerEvent): void => {
      if (!panel.current?.contains(event.target as Node)) onClose();
    };
    const key = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onClose();
    };
    document.addEventListener('pointerdown', away);
    document.addEventListener('keydown', key);
    return () => {
      document.removeEventListener('pointerdown', away);
      document.removeEventListener('keydown', key);
    };
  }, [onClose]);

  // Somebody already in the call is left out rather than listed and disabled:
  // this list is what a cursor reaches into, and a row that does nothing is a
  // row in the way. Online first, because the person to ring is usually one of
  // them - but the offline ones stay, since ringing reaches a phone.
  const inCall = new Set(tiles.map((tile) => tile.userId));
  const candidates = members
    .filter((member) => member.userId !== selfId && !inCall.has(member.userId))
    .sort((a, b) => {
      const away = Number(statusOf(a.userId) === 'offline') - Number(statusOf(b.userId) === 'offline');
      return away !== 0 ? away : a.displayName.localeCompare(b.displayName);
    });

  const ring = (userId: string): void => {
    if (!channelId) return;
    setRung((state) => ({ ...state, [userId]: 'Ringing…' }));
    api
      .callRing(channelId, userId)
      .then(() => setRung((state) => ({ ...state, [userId]: 'Rung' })))
      .catch((cause: unknown) =>
        setRung((state) => ({
          ...state,
          [userId]: cause instanceof Error ? cause.message : 'Could not ring them',
        })),
      );
  };

  return (
    <div
      ref={panel}
      className="absolute bottom-full start-0 z-30 mb-2 w-72 rounded-lg bg-surface-800 p-3 shadow-lg"
    >
      <p className="text-sm font-semibold text-slate-100">Add to the call</p>
      <p className="mt-0.5 text-xs text-slate-400">
        Rings them wherever they are signed in.
      </p>

      {candidates.length === 0 ? (
        <p className="mt-3 text-xs text-slate-500">Everybody here is already in the call.</p>
      ) : (
        <ul className="mt-2 max-h-64 space-y-0.5 overflow-y-auto">
          {candidates.map((member) => {
            const state = rung[member.userId];
            return (
              <li key={member.userId}>
                <button
                  type="button"
                  // A person already rung is not clickable again: the service
                  // holds a cooldown per pair, so a second click earns a 403
                  // rather than a second ring.
                  disabled={state !== undefined}
                  onClick={() => ring(member.userId)}
                  className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-start transition-colors hover:bg-white/[0.06] disabled:cursor-default disabled:hover:bg-transparent"
                >
                  <Avatar
                    name={member.displayName || member.username}
                    avatarUrl={member.avatarUrl}
                    size="sm"
                    status={statusOf(member.userId)}
                    ringColour="border-surface-800"
                    viewable={false}
                  />
                  <span className="min-w-0 flex-1 truncate text-sm text-slate-200">
                    {member.displayName || member.username}
                  </span>
                  <span
                    className={`shrink-0 text-xs ${
                      state === undefined
                        ? 'text-accent'
                        : state === 'Rung'
                          ? 'text-status-online'
                          : state === 'Ringing…'
                            ? 'text-slate-400'
                            : 'text-red-300'
                    }`}
                  >
                    {state ?? 'Ring'}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

/**
 * YouTube itself, inside the call. Press a video; the whole call watches it.
 *
 * The paste box was the first version and it was the wrong shape. Nobody keeps
 * a list of video ids; they search for a half-remembered chorus, or open the
 * playlist they made, or look at what their subscriptions posted this morning -
 * and every one of those needs the actual site and, for two of them, a signed-in
 * account.
 *
 * The second version was the right site with the wrong control: a button that
 * queued whatever page you were on. That is still a paste box - it just moved
 * the copying inside the app. Pressing play is the gesture people already have
 * for "play this", so that is the gesture that plays it: a thumbnail, the
 * player's own play button, whatever the page runs next. The page is stopped
 * and the call plays the same video where everybody can see it. The queue
 * button stays for the other thing, which is choosing what comes *after* what
 * is on.
 *
 * Like the player slot in `ListenPanel`, this component draws nothing. The page is a
 * `WebContentsView` the main process owns, and this hands it a rectangle to sit
 * over. That is not an implementation detail worth hiding: a view destroyed and
 * rebuilt on every React unmount would throw away the sign-in, the scroll
 * position and the search on every re-render, so the rule is that the view
 * outlives the component and the component only says where to put it.
 *
 * **Desktop only.** youtube.com sends `X-Frame-Options` and a `frame-ancestors`
 * policy, so no browser tab can ever show the site inside another page. The web
 * client gets the paste box, which is the honest version of that limit rather
 * than a broken frame.
 */
import { useEffect, useRef, useState } from 'react';
import { useListenStore } from '../../stores/listen';
import { isDesktopRuntime } from '../../services/platform';
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  CompassIcon,
  PlusIcon,
  SearchIcon,
} from '../../components/icons';

interface Navigation {
  url: string;
  title: string;
  videoId: string | null;
  canGoBack: boolean;
  canGoForward: boolean;
  loading: boolean;
}

export function ListenBrowser(): JSX.Element {
  const slot = useRef<HTMLDivElement>(null);
  const [nav, setNav] = useState<Navigation | null>(null);
  const [query, setQuery] = useState('');
  const [added, setAdded] = useState<string | null>(null);

  const bridge = window.betweenus;

  // The rectangle, tracked the same way the player's frame is: on a frame loop,
  // because the box moves for reasons no observer reports - a sidebar opening,
  // a banner appearing above it, the window crossing to another monitor.
  useEffect(() => {
    if (!bridge?.youtubeOpen || !bridge.youtubeBounds) return undefined;
    let raf = 0;
    let last = '';

    const push = (): void => {
      const box = slot.current?.getBoundingClientRect();
      if (box && box.width > 0 && box.height > 0) {
        const key = `${box.left}:${box.top}:${box.width}:${box.height}`;
        // Only when it has moved: this runs sixty times a second and each call
        // is an IPC round trip into the main process.
        if (key !== last) {
          last = key;
          void bridge.youtubeBounds?.({ x: box.left, y: box.top, width: box.width, height: box.height });
        }
      }
      raf = requestAnimationFrame(push);
    };

    const box = slot.current?.getBoundingClientRect();
    void bridge.youtubeOpen({
      x: box?.left ?? 0,
      y: box?.top ?? 0,
      width: box?.width ?? 0,
      height: box?.height ?? 0,
    });
    raf = requestAnimationFrame(push);

    const stop = bridge.onYouTubeNavigated?.((state) => setNav(state));

    return () => {
      cancelAnimationFrame(raf);
      stop?.();
      // Hidden rather than closed: collapsing the panel must not cost the
      // sign-in, the search that was typed or the video half watched. The store
      // closes it for real when the call ends.
      void bridge.youtubeHide?.();
    };
  }, [bridge]);

  // Pressing play *is* the control - on a thumbnail, on the player's own play
  // button, on whatever the page decided to run next. The main process stops
  // the page and says which video was asked for; this plays it where the whole
  // call can see it and hands the panel back to the player.
  //
  // This used to watch for navigations instead, which is a proxy for the intent
  // and a poor one: it fired for a page opened to read the description, and
  // missed a play pressed on a page that was already open - which is exactly
  // the case that looked broken.
  useEffect(() => {
    if (!bridge?.onYouTubePlay) return undefined;
    return bridge.onYouTubePlay((videoId) => {
      const store = useListenStore.getState();
      const playing = store.session?.queue[store.session.index];
      // Already what the call is watching: show it rather than queueing a
      // second copy of the same video behind itself.
      if (playing?.ref !== videoId) store.add(videoId, true);
      store.setTab('playing');
    });
  }, [bridge]);

  if (!isDesktopRuntime() || !bridge?.youtubeOpen) {
    return (
      <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-white/10 p-6 text-center">
        <CompassIcon className="h-6 w-6 text-slate-700" />
        <p className="max-w-sm text-xs leading-relaxed text-slate-400">
          Browsing YouTube inside the app is desktop-only. youtube.com refuses to
          be shown inside another page - a rule the site sets, which a browser
          tab cannot get around - so paste a link instead. Everything else about
          listening together works exactly the same.
        </p>
      </div>
    );
  }

  const queue = (): void => {
    if (!nav?.videoId) return;
    useListenStore.getState().add(nav.videoId);
    setAdded(nav.videoId);
    window.setTimeout(() => setAdded(null), 1500);
    // Deliberately stays on the site: adding a second track while looking for a
    // third is the normal case, and being thrown back to the player every time
    // is what made queueing four songs annoying.
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-2">
      <div className="flex shrink-0 flex-wrap items-center gap-1">
        <ToolbarButton
          label="Back"
          disabled={!nav?.canGoBack}
          onClick={() => void bridge.youtubeBack?.()}
        >
          <ChevronLeftIcon className="h-4 w-4" />
        </ToolbarButton>
        <ToolbarButton
          label="Forward"
          disabled={!nav?.canGoForward}
          onClick={() => void bridge.youtubeForward?.()}
        >
          <ChevronRightIcon className="h-4 w-4" />
        </ToolbarButton>
        <ToolbarButton label="YouTube home" onClick={() => void bridge.youtubeHome?.()}>
          <CompassIcon className="h-4 w-4" />
        </ToolbarButton>

        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          onKeyDown={(event) => {
            if (event.key !== 'Enter' || !query.trim()) return;
            void bridge.youtubeSearch?.(query);
          }}
          placeholder="Search YouTube"
          aria-label="Search YouTube"
          className="min-w-0 flex-1 rounded-md border border-white/10 bg-surface-800 px-2 py-1.5 text-sm text-slate-200 placeholder:text-slate-500 focus:border-white/20 focus:outline-none"
        />
        <ToolbarButton
          label="Search"
          disabled={!query.trim()}
          onClick={() => void bridge.youtubeSearch?.(query)}
        >
          <SearchIcon className="h-4 w-4" />
        </ToolbarButton>

        {/* Not "play this" - pressing it on the site already did that. This is
            for building a queue *behind* what is on, which is the one thing
            clicking a thumbnail cannot say. Live only on a video page, because
            queueing "the YouTube home page" is not a thing. */}
        <button
          type="button"
          onClick={queue}
          disabled={!nav?.videoId}
          title={nav?.videoId ? 'Add this to the shared queue' : 'Open a video first'}
          className="flex shrink-0 cursor-pointer items-center gap-1.5 rounded-md bg-amber-500/15 px-2.5 py-1.5 text-xs font-medium text-amber-200 transition-colors hover:bg-amber-500/25 disabled:cursor-not-allowed disabled:bg-surface-800 disabled:text-slate-600"
        >
          <PlusIcon className="h-3.5 w-3.5" />
          {added && added === nav?.videoId ? 'Added' : 'Add to queue'}
        </button>

      </div>

      {/* The slot. Empty on purpose - the page is a view the main process owns
          and positions over this rectangle, so unmounting cannot destroy it. */}
      <div ref={slot} className="min-h-0 flex-1 overflow-hidden rounded-lg bg-black" />

      <p className="shrink-0 truncate text-[11px] text-slate-600" title={nav?.url}>
        {nav?.loading ? 'Loading…' : (nav?.title ?? 'youtube.com')}
        {' · press play on anything and the whole call watches it. Nothing '}
        {'plays in here; the picture is the shared player’s. Signed in with '}
        {'your own Google account, kept apart from BetweenUs'}
      </p>
    </div>
  );
}

function ToolbarButton({
  label,
  disabled,
  onClick,
  children,
}: {
  label: string;
  disabled?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}): JSX.Element {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      aria-label={label}
      title={label}
      className="flex shrink-0 items-center justify-center rounded-md bg-surface-800 p-1.5 text-slate-300 transition-colors hover:bg-white/[0.06] hover:text-slate-100 disabled:cursor-not-allowed disabled:text-slate-600 disabled:opacity-50"
    >
      {children}
    </button>
  );
}

/**
 * Listen Together, as one panel that takes the voice stage.
 *
 * It was a popover on the call controls and that was wrong twice over.
 *
 * **It drew itself twice.** `VoiceControls` is rendered in two places - the
 * sidebar and the channel view - so a single `open` flag in the store produced
 * two live panels side by side, each with its own seek bar, arguing. Shared
 * state may only have one render site, and this is it.
 *
 * **It was the wrong size for the job.** Picking the next thing to play is not
 * a thing anybody does in a 22rem popover: it wants the site, and the site
 * wants the screen. So the panel takes the stage the way a shared screen does,
 * and the tiles come straight back when it closes.
 *
 * Two tabs, because only one of them can have the space and because a native
 * browser view and an embedded player must never be on screen together - a
 * `WebContentsView` paints above every pixel of the DOM whatever any `z-index`
 * says, so "both at once" means "the player is invisible and nobody knows why".
 *
 *   Browse   - the real youtube.com, signed in as you, on desktop; search
 *              results in a browser tab, which is as close as a web page is
 *              allowed to get. The default, because looking for something to
 *              play is what opening this means.
 *   Playing  - the video everybody in the call is watching.
 *
 * Neither tab draws anything itself. Both offer an empty rectangle and
 * something the store owns is positioned over it, so that switching tabs,
 * closing the panel or leaving the screen cannot destroy what is playing. See
 * `stores/listen.ts`.
 */
import { useEffect, useRef, useState } from 'react';
import { listenPositionAt } from '@betweenus/shared-types';
import { claimListenSlot, useListenStore } from '../../stores/listen';
import { useAppsStore } from '../../stores/apps';
import { formatPosition } from '../../services/listen-sync';
import { isDesktopRuntime } from '../../services/platform';
import { ListenBrowser } from './ListenBrowser';
import { ListenSearch } from './ListenSearch';
import {
  ChevronLeftIcon,
  CompassIcon,
  MusicIcon,
  PauseIcon,
  PlayIcon,
  PlusIcon,
  SkipBackIcon,
  SkipForwardIcon,
  SpeakerIcon,
  TrashIcon,
  XIcon,
} from '../../components/icons';

export function ListenPanel(): JSX.Element {
  const session = useListenStore((state) => state.session);
  const tab = useListenStore((state) => state.tab);
  const error = useListenStore((state) => state.error);
  const currentTrack = session ? session.queue[session.index] : undefined;

  const playerSlot = useRef<HTMLDivElement>(null);
  /**
   * The desktop app frames youtube.com itself; a browser tab cannot, and gets
   * search results instead. Both are the same gesture - find something, press
   * it, the call watches it - so both live on the same Browse tab rather than
   * one of them being a lesser thing hidden somewhere else.
   */
  const native = isDesktopRuntime() && Boolean(window.betweenus?.youtubeOpen);

  // The picture is handed this rectangle only while the player tab has the
  // space. On the browser tab it is released, which parks it - still playing,
  // and no longer sitting invisibly underneath a native view.
  useEffect(() => {
    if (tab !== 'playing' || !session) {
      claimListenSlot(null);
      return undefined;
    }
    claimListenSlot(playerSlot.current);
    return () => claimListenSlot(null);
  }, [tab, session]);

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-2">
      <div className="flex shrink-0 items-center gap-2">
        {/* Back to the chooser rather than out of the call - this screen was
            reached from Apps, and the music carries on either way. */}
        <button
          type="button"
          onClick={() => {
            useListenStore.getState().setOpen(false);
            useAppsStore.getState().setOpen(true);
          }}
          aria-label="Back to apps"
          title="Apps"
          className="-ms-1 cursor-pointer rounded p-1 text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200"
        >
          <ChevronLeftIcon className="h-4 w-4" />
        </button>
        <MusicIcon className="h-4 w-4 shrink-0 text-amber-300" />
        <span className="text-sm font-medium text-slate-200">Listen together</span>

        <div className="ms-2 flex items-center gap-0.5 rounded-md bg-surface-900 p-0.5">
          <Tab active={tab === 'browse'} onClick={() => useListenStore.getState().setTab('browse')}>
            <CompassIcon className="h-3.5 w-3.5" />
            Browse
          </Tab>
          <Tab
            active={tab === 'playing'}
            disabled={!session}
            onClick={() => useListenStore.getState().setTab('playing')}
          >
            <PlayIcon className="h-3.5 w-3.5" />
            Playing
          </Tab>
        </div>

        <button
          type="button"
          onClick={() => useListenStore.getState().setOpen(false)}
          aria-label="Close listen together"
          title="Close - the music keeps playing"
          className="ms-auto cursor-pointer rounded p-1 text-slate-400 transition-colors hover:bg-white/[0.06] hover:text-slate-200"
        >
          <XIcon className="h-4 w-4" />
        </button>
      </div>

      {error && (
        <div className="flex shrink-0 items-center justify-between gap-3 rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
          <div className="flex items-center gap-2 min-w-0">
            <span className="shrink-0 font-medium text-amber-400">Notice:</span>
            <span className="truncate">{error}</span>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {currentTrack && (
              <a
                href={`https://www.youtube.com/watch?v=${currentTrack.ref}`}
                target="_blank"
                rel="noreferrer noopener"
                className="rounded bg-white/10 px-2 py-1 text-[11px] font-medium text-slate-200 transition-colors hover:bg-white/20"
              >
                Watch on YouTube
              </a>
            )}
            <button
              type="button"
              onClick={() => useListenStore.getState().skip(1)}
              className="cursor-pointer rounded bg-amber-500/20 px-2 py-1 text-[11px] font-medium text-amber-200 transition-colors hover:bg-amber-500/30"
            >
              Skip Track
            </button>
          </div>
        </div>
      )}

      <div className="flex min-h-0 flex-1 gap-3">
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {tab === 'browse' ? (
            native ? <ListenBrowser /> : <ListenSearch />
          ) : session ? (
            /* Bounded on both axes, which is the whole of the "it filled the
               entire screen and ran off the bottom" bug.

               It was `aspect-video w-full`: at a 1750px stage that is a 984px
               tall box, and nothing above it was `min-h-0`, so flexbox let it
               push straight past the window. `flex-1 min-h-0` caps the height
               against the stage and `max-w-5xl` stops it spanning an ultrawide
               monitor.

               No aspect ratio here on purpose. Constraining a 16:9 box by both
               a max width and a max height cannot be done with `aspect-ratio`
               alone - whichever axis is definite wins and the other one breaks
               the shape. The player letterboxes inside whatever box it is
               given, exactly as it does on YouTube itself, so a black surround
               is both free and correct. */
            <div
              ref={playerSlot}
              aria-label="Shared video"
              className="mx-auto min-h-0 w-full max-w-5xl flex-1 rounded-lg bg-black"
            />
          ) : (
            <Empty />
          )}
        </div>

        <Queue />
      </div>

      {session && <Transport />}
    </div>
  );
}

function Empty(): JSX.Element {
  return (
    <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-white/10 p-6 text-center">
      <MusicIcon className="h-8 w-8 text-slate-700" />
      <p className="max-w-sm text-xs leading-relaxed text-slate-400">
