/**
 * A shared screen, everybody's cursor on top of it, and the mouse if you were
 * given it.
 *
 * The picture has its own element here rather than going through `VideoSink`
 * because everything else on this component is measured against it. A screen is
 * letterboxed inside its box - `object-contain`, because a desktop must not be
 * cropped - so the picture is not the element, and a cursor placed at the
 * element's coordinates would drift further from the truth the worse the aspect
 * ratio mismatch got. `contentBox` is where the pixels actually are, and every
 * fraction on the wire is a fraction of that.
 *
 * Cursors carry names because a call has more than two people in it. Whoever is
 * driving is the only one whose pointer does anything, but anybody watching can
 * point at the thing they are talking about, which is most of what pointing at
 * a screen share is for. Teams draws them the same way.
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import { useShareControlStore } from '../../stores/shareControl';
import { modifiersOf } from '../../services/keyboard';
import type { VoiceShare } from '../../stores/voice';
import { contentBox, fractionIn, EMPTY_BOX, type Box } from './stage-geometry';

export function ShareStage({ share }: { share: VoiceShare }): JSX.Element {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [content, setContent] = useState<Box>(EMPTY_BOX);

  const pointers = useShareControlStore((state) => state.pointers);
  const driving = useShareControlStore((state) => state.driving);
  const sendPointer = useShareControlStore((state) => state.sendPointer);
  const clearPointer = useShareControlStore((state) => state.clearPointer);
  const sendMouse = useShareControlStore((state) => state.sendMouse);
  const sendKey = useShareControlStore((state) => state.sendKey);
  const stop = useShareControlStore((state) => state.stop);

  const controlling = driving === share.identity;

  useEffect(() => attachTrack(videoRef.current, share.track), [share.track]);

  // Where the picture is inside the element. Recomputed when the window
  // changes and when the far end changes what it is sending - switching monitor
  // mid-call changes the aspect ratio under us.
  const measure = useCallback((): void => {
    const element = videoRef.current;
    if (!element) return setContent(EMPTY_BOX);
    const rect = element.getBoundingClientRect();
    setContent(contentBox(rect.width, rect.height, element.videoWidth, element.videoHeight));
  }, []);

  useEffect(() => {
    const element = videoRef.current;
    if (!element) return;
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    element.addEventListener('loadedmetadata', measure);
    element.addEventListener('resize', measure);
    return () => {
      observer.disconnect();
      element.removeEventListener('loadedmetadata', measure);
      element.removeEventListener('resize', measure);
    };
  }, [measure, share.track]);

  // Escape hands the mouse back and never travels: without one key that always
  // stays local, a share that stops responding traps the keyboard.
  useEffect(() => {
    if (!controlling) return;
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        stop();
        return;
      }
      event.preventDefault();
      // The modifiers ride along with every key: the far side reconstructs the
      // chord from them rather than from the order three events arrived in.
      sendKey(
        event.type === 'keydown' ? 'down' : 'up',
        event.key,
        event.code,
        modifiersOf(event),
      );
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('keyup', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('keyup', onKey);
    };
  }, [controlling, sendKey, stop]);

  // Leaving the call, or the stage, must not leave a cursor behind on
  // everybody else's screen.
  useEffect(() => () => clearPointer(), [clearPointer]);

  /** Pointer position as a fraction of the picture, or null when outside it. */
  const pointFrom = (event: React.MouseEvent): { x: number; y: number } | null => {
    const rect = event.currentTarget.getBoundingClientRect();
    return fractionIn(content, event.clientX - rect.left, event.clientY - rect.top);
  };

  const buttonOf = (button: number): 'left' | 'right' | 'middle' =>
    button === 2 ? 'right' : button === 1 ? 'middle' : 'left';

  // Only what arrived over the wire, so this is everybody else by construction:
  // a client never records its own pointer, it has a real one.
  const others = Object.values(pointers);

  return (
    <div
      className={`relative h-full w-full ${controlling ? 'cursor-crosshair' : ''}`}
      onMouseMove={(event) => {
        const point = pointFrom(event);
        if (!point) return;
        sendPointer(point.x, point.y);
        if (controlling) sendMouse('move', point.x, point.y);
      }}
      onMouseLeave={clearPointer}
      onMouseDown={(event) => {
        const point = pointFrom(event);
        if (point && controlling) sendMouse('down', point.x, point.y, buttonOf(event.button));
      }}
      onMouseUp={(event) => {
        const point = pointFrom(event);
        if (point && controlling) sendMouse('up', point.x, point.y, buttonOf(event.button));
      }}
      onWheel={(event) => {
        if (controlling) sendMouse('wheel', 0, 0, undefined, Math.sign(event.deltaY) * 120);
      }}
      // The other machine's own context menu is what a right-click is for.
      onContextMenu={(event) => event.preventDefault()}
    >
      <video ref={videoRef} autoPlay playsInline muted className="h-full w-full object-contain" />

      {/* Cursors sit in the picture, not in the element: the black bars either
          side of a 16:10 desktop in a 16:9 box are not part of the screen. */}
      {others.map((pointer) => (
        <span
          key={pointer.identity}
          aria-hidden="true"
          className="pointer-events-none absolute z-10 -translate-y-0.5"
          style={{
            left: content.left + pointer.x * content.width,
            top: content.top + pointer.y * content.height,
          }}
        >
          <CursorMark />
          <span className="ms-3 rounded bg-accent px-1.5 py-0.5 text-[11px] font-medium text-white shadow">
            {pointer.name}
          </span>
        </span>
      ))}
    </div>
  );
}

/** Puts a track on an element and takes it off again. */
function attachTrack(
  element: HTMLVideoElement | null,
  track: MediaStreamTrack | null,
): () => void {
  if (!element || !track) return () => undefined;
  element.srcObject = new MediaStream([track]);
  return () => {
    element.srcObject = null;
  };
}

function CursorMark(): JSX.Element {
  return (
    <svg viewBox="0 0 12 18" className="absolute h-4 w-3 drop-shadow" fill="currentColor">
      <path
        d="M0 0l11 11H5.5l-1.5 6z"
        className="text-accent"
        fill="currentColor"
        stroke="white"
        strokeWidth="1"
      />
    </svg>
  );
}

/**
 * Self-check for the letterbox arithmetic behind pointer and click mapping.
 *
 * Run with `pnpm --filter @betweenus/desktop check`. Every named cursor and every
 * click handed to somebody else's machine goes through these two functions, so
 * an off-by-a-black-bar here is visible on the far end.
 */
import assert from 'node:assert/strict';
import { contentBox, fractionIn, EMPTY_BOX } from './stage-geometry';

// Same aspect ratio: the picture is the whole box.
assert.deepEqual(contentBox(1600, 900, 1920, 1080), {
  left: 0,
  top: 0,
  width: 1600,
  height: 900,
});

// A 16:10 desktop in a 16:9 box: bars down the sides, none top or bottom.
const wide = contentBox(1600, 900, 1920, 1200);
assert.equal(wide.height, 900);
assert.equal(wide.width, 1440);
assert.equal(wide.left, 80);
assert.equal(wide.top, 0);

// A 4:3 desktop in a wide box: the same, more so.
const tall = contentBox(1600, 900, 1024, 768);
assert.equal(tall.height, 900);
assert.equal(tall.width, 1200);
assert.equal(tall.left, 200);

// Nothing measured yet, and a track with no dimensions, are both "no picture".
assert.deepEqual(contentBox(0, 0, 1920, 1080), EMPTY_BOX);
assert.deepEqual(contentBox(1600, 900, 0, 0), EMPTY_BOX);

// The middle of the picture is the middle of the screen, bars or no bars.
assert.deepEqual(fractionIn(wide, 80 + 720, 450), { x: 0.5, y: 0.5 });
// The corners are exactly the corners.
assert.deepEqual(fractionIn(wide, 80, 0), { x: 0, y: 0 });
assert.deepEqual(fractionIn(wide, 1520, 900), { x: 1, y: 1 });
// On the black bar: not a point on anybody's screen, so nothing is sent.
assert.equal(fractionIn(wide, 40, 450), null);
assert.equal(fractionIn(wide, 1560, 450), null);
assert.equal(fractionIn(EMPTY_BOX, 10, 10), null);

console.log('stage-geometry self-check passed');

/**
 * Where the picture actually is inside the box it is drawn in.
 *
 * A shared desktop is letterboxed rather than cropped, so the element and the
 * picture are two different rectangles whenever their aspect ratios differ -
 * a 16:10 screen in a 16:9 box has a black bar down each side. Every cursor
 * position and every click is a fraction of the *picture*, and treating the
 * element as the picture puts them further out the worse the mismatch is.
 *
 * Pure, and separated from the component, so the arithmetic can be checked
 * without a browser: `stage-geometry.check.ts`.
 */

export interface Box {
  left: number;
  top: number;
  width: number;
  height: number;
}

export const EMPTY_BOX: Box = { left: 0, top: 0, width: 0, height: 0 };

/** The `object-contain` rectangle of `video` inside an `element`-sized box. */
export function contentBox(
  elementWidth: number,
  elementHeight: number,
  videoWidth: number,
  videoHeight: number,
): Box {
  if (elementWidth <= 0 || elementHeight <= 0 || videoWidth <= 0 || videoHeight <= 0) {
    return EMPTY_BOX;
  }
  const scale = Math.min(elementWidth / videoWidth, elementHeight / videoHeight);
  const width = videoWidth * scale;
  const height = videoHeight * scale;
  return {
    left: (elementWidth - width) / 2,
    top: (elementHeight - height) / 2,
    width,
    height,
  };
}

/**
 * A point in the element, as a fraction of the picture - or null when it is on
 * the black bars, which are not part of anybody's screen.
 */
export function fractionIn(box: Box, x: number, y: number): { x: number; y: number } | null {
  if (box.width <= 0 || box.height <= 0) return null;
  const fx = (x - box.left) / box.width;
  const fy = (y - box.top) / box.height;
  if (fx < 0 || fx > 1 || fy < 0 || fy > 1) return null;
  return { x: fx, y: fy };
}

/**
 * Self-check for the two rules that decide where a face sits on the call stage.
 *
 * Run with `pnpm --filter @betweenus/desktop check`. The complaint these rules
 * answer - "it keeps swapping the person who is talking" - is invisible in a
 * screenshot and obvious in a call, so it is pinned down here instead.
 */
import assert from 'node:assert/strict';
import { PAGE_SIZE, PROMOTION_MS, orderStage, splitStage } from './stage-order';

const NOW = 1_000_000;

const tile = (key: string, spokeAgo: number, isLocal = false): {
  key: string;
  isLocal: boolean;
  lastSpokeAt: number;
} => ({ key, isLocal, lastSpokeAt: spokeAgo === Infinity ? 0 : NOW - spokeAgo });

// Two people, the other one talking: the order is the order it arrived in, and
// stays that way. This is the reported bug.
const pair = [tile('me', 0, true), tile('them', 200)];
assert.deepEqual(orderStage(pair, NOW), pair);

// Still one page with nine other people on it - nobody moves.
const roomful = [tile('me', Infinity, true), ...Array.from({ length: PAGE_SIZE }, (_, i) => tile(`p${i}`, i * 100))];
assert.deepEqual(orderStage(roomful, NOW), roomful);

// One person past a full page: now a promotion has somewhere to promote to, so
// the recent speaker leads and a stale one does not.
const crowd = [
  ...Array.from({ length: PAGE_SIZE }, (_, i) => tile(`p${i}`, PROMOTION_MS * 2)),
  tile('late', 500),
];
assert.equal(orderStage(crowd, NOW)[0]?.key, 'late');
// A promotion that has lapsed leaves the order alone.
const lapsed = [
  ...Array.from({ length: PAGE_SIZE }, (_, i) => tile(`p${i}`, PROMOTION_MS * 2)),
  tile('quiet', PROMOTION_MS + 1),
];
assert.deepEqual(orderStage(lapsed, NOW), lapsed);

// The grid is the other people; you are the floating window.
const split = splitStage(pair, null);
assert.equal(split.self?.key, 'me');
assert.deepEqual(split.grid.map((t) => t.key), ['them']);
assert.equal(split.hero, null);
assert.deepEqual(split.strip, []);

// Alone: your own camera is all there is, so it takes the stage rather than
// leaving an empty grid with a thumbnail over it.
const alone = splitStage([tile('me', 0, true)], null);
assert.deepEqual(alone.grid.map((t) => t.key), ['me']);
assert.equal(alone.self?.key, 'me');

// A pin puts one face on the stage and everybody else in the strip - and the
// pinned person is not also in the strip.
const trio = [tile('me', 0, true), tile('a', 100), tile('b', 100)];
const pinnedOther = splitStage(trio, 'b');
assert.equal(pinnedOther.hero?.key, 'b');
assert.deepEqual(pinnedOther.strip.map((t) => t.key), ['a']);

// Pinning yourself works too, and does not put you in the strip either.
const pinnedSelf = splitStage(trio, 'me');
assert.equal(pinnedSelf.hero?.key, 'me');
assert.deepEqual(pinnedSelf.strip.map((t) => t.key), ['a', 'b']);

// A pin on somebody who has left is no pin at all - the stage falls back to the
// grid instead of holding an empty hero.
assert.equal(splitStage(trio, 'gone').hero, null);

console.log('stage-order self-check passed');

/**
 * Who goes where on the call stage, decided without React so it can be checked.
 *
 * Two rules, and both exist because a call grid that rearranges itself is the
 * thing people notice and hate:
 *
 * - **Order** only moves for a speaker when there is a page two to move them
 *   onto. A stage everybody already fits on is left exactly as it arrived.
 * - **The stage is other people.** The local tile comes out of the grid and is
 *   drawn small over the corner of it, unless there is nobody else in the call,
 *   in which case it is all there is to show.
 *
 * Pinning overrides the grid entirely: one face big, the rest in a strip.
 */

/** Tiles per page. Nine keeps every face big enough to read on a laptop. */
export const PAGE_SIZE = 9;

/** How long after speaking someone keeps their place at the front. */
export const PROMOTION_MS = 60_000;

export interface OrderableTile {
  key: string;
  isLocal: boolean;
  lastSpokeAt: number;
}

/**
 * Recent speakers first - but only when somebody would otherwise be off-screen.
 *
 * The promotion exists to keep an active speaker on page one. With everybody
 * already on page one it has nothing left to do but shuffle faces mid-sentence,
 * so the list is returned untouched. The local tile is not counted: it is a
 * floating window, not a grid cell.
 */
export function orderStage<T extends OrderableTile>(tiles: T[], now: number): T[] {
  if (tiles.filter((tile) => !tile.isLocal).length <= PAGE_SIZE) return tiles;

  const recent = (tile: T): number => (now - tile.lastSpokeAt < PROMOTION_MS ? tile.lastSpokeAt : 0);
  return [...tiles].sort((left, right) => recent(right) - recent(left));
}

export interface StageSplit<T> {
  /** Your own tile, if you are in the call. Drawn small, never in the grid. */
  self: T | null;
  /** What the grid pages through: the other people, or you if you are alone. */
  grid: T[];
  /** Pinned to fill the stage, if anybody is - the local tile included. */
  hero: T | null;
  /** Everyone else, as thumbnails under a hero. Empty when nothing is pinned. */
  strip: T[];
}

export function splitStage<T extends OrderableTile>(
  tiles: T[],
  pinned: string | null,
): StageSplit<T> {
  const self = tiles.find((tile) => tile.isLocal) ?? null;
  const others = tiles.filter((tile) => !tile.isLocal);
  // Alone in the call there is nobody else to look at, so your own camera takes
  // the stage rather than hiding in a thumbnail of an empty room.
  const grid = others.length > 0 ? others : tiles;
  const hero = pinned === null ? null : (tiles.find((tile) => tile.key === pinned) ?? null);
  const strip = hero ? grid.filter((tile) => tile.key !== hero.key) : [];

  return { self, grid, hero, strip };
}

/**
 * The main-content screen for a voice channel.
 *
 * Selecting a voice channel opens this instead of the chat view: the first
 * click also joins the call, and every click after that just brings the screen
 * back up.
 *
 * Two layouts, because two things happen in a voice channel:
 *
 * - **Grid** - everybody's camera, paged. A share is announced by a banner but
 *   nobody is dragged into it, the way Discord announces a stream.
 * - **Theatre** - one shared screen fills the stage with the people along the
 *   bottom, which is what a group watching something together wants. Entered by
 *   choosing to watch a share, left by closing it.
 *
 * Cameras and a shared screen can be on at once, so a share is its own thing
 * and never replaces the sharer's tile.
 *
 * The grid pages at nine tiles rather than shrinking forever. Whoever spoke
 * most recently is pulled to the front only when there is a page two to be
 * pulled onto: while everybody fits on one page, moving faces around buys
 * nothing and costs the reader their place, so the order stays put.
 *
 * The grid is the *other* people. Your own camera is a small floating window
 * over the corner of it - you are not in the call to watch yourself - and any
 * one person can be pinned to fill the stage with everybody else in a strip
 * underneath.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { Channel } from '@betweenus/shared-types';
import { useChatStore } from '../../stores/chat';
import { usePresenceStore } from '../../stores/presence';
import { useRemoteStore } from '../../stores/remote';
import { isDesktopRuntime } from '../../services/platform';
import { useShareControlStore } from '../../stores/shareControl';
import { useVoiceStore, type VoiceShare, type VoiceTile } from '../../stores/voice';
import { CallDuration } from './CallDuration';
import { VoiceControls } from './VoiceControls';
import { NotHeardNotice } from './NotHeardNotice';
import { VideoSink } from './MediaSink';
import { ShareStage } from './ShareStage';
import { PAGE_SIZE, orderStage, splitStage } from './stage-order';
import { ListenBar, ListenPanel } from './ListenPanel';
import { GameBar, GamePanel } from './GamePanel';
import { AppsPanel } from './AppsPanel';
import { useAppsStore } from '../../stores/apps';
import { useListenStore } from '../../stores/listen';
import { useGameStore } from '../../stores/game';
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  HashIcon,
  LayoutBottomIcon,
  LayoutSidebarIcon,
  LockIcon,
  MaximizeIcon,
  MenuIcon,
  MicOffIcon,
  MinimizeIcon,
  PinIcon,
  ScreenShareIcon,
  SpeakerIcon,
  UsersIcon,
  XIcon,
} from '../../components/icons';

interface Stage {
  key: string;
  name: string;
  isLocal: boolean;
  speaking: boolean;
  micEnabled: boolean;
  /** Pulled off the call by another one - see `VoiceTile.held`. */
  held: boolean;
  videoTrack: MediaStreamTrack | null;
  lastSpokeAt: number;
}

/**
 * Full screen here is the app's own overlay, not the operating system's, so the
 * window buttons stay where they are and anything drawn into that corner ends up
 * underneath them. The overlay header keeps the same corner clear that
 * {@link TopBar} does: Windows and Linux paint minimise/maximise/close on the
 * right, macOS puts its traffic lights on the left. A browser tab has neither, so
 * there the corner is the page's to use.
 */
const captionInset = !isDesktopRuntime()
  ? ''
  : window.betweenus?.platform === 'darwin'
    ? 'ps-[86px]'
    : 'pe-[146px]';

export function VoiceChannelView({
  channel,
  onOpenMenu,
}: {
  channel: Channel;
  onOpenMenu?: () => void;
}): JSX.Element {
  const members = useChatStore((state) => state.members);
  const occupants = usePresenceStore((state) => state.voice.get(channel.id) ?? []);

  const status = useVoiceStore((state) => state.status);
  const connectedTo = useVoiceStore((state) => state.channelId);
  const tiles = useVoiceStore((state) => state.tiles);
  const shares = useVoiceStore((state) => state.shares);
  const watching = useVoiceStore((state) => state.watching);
  const encrypted = useVoiceStore((state) => state.encrypted);
  const error = useVoiceStore((state) => state.error);
  const join = useVoiceStore((state) => state.join);
  const notHeard = useVoiceStore((state) => state.notHeard);

  const inThisChannel = connectedTo === channel.id;
  const connected = inThisChannel && status === 'connected';
  const connecting = inThisChannel && status === 'connecting';

  // Connected: the mesh knows who is really in the call, because it holds a
  // connection to each of them. Otherwise fall back to the presence roster,
  // which has names but no tracks.
  const stage: Stage[] = connected
    ? tiles.map(toStage)
    : occupants.map((userId) => ({
        key: userId,
        name: members.find((member) => member.userId === userId)?.displayName ?? 'Someone',
        isLocal: false,
        speaking: false,
        micEnabled: true,
        held: false,
        videoTrack: null,
        lastSpokeAt: 0,
      }));

  const ordered = useOrderedStage(stage);

  // Pinned by hand, and only for as long as they are in the call - a pin left
  // on somebody who hung up would hold an empty stage.
  const [pinned, setPinned] = useState<string | null>(null);
  const present = stage.map((tile) => tile.key).join(',');
  useEffect(() => {
    if (pinned !== null && !present.split(',').includes(pinned)) setPinned(null);
  }, [pinned, present]);

  const listenOpen = useListenStore((state) => state.open);
  const gameOpen = useGameStore((state) => state.open);
  const gameFullscreen = useGameStore((state) => state.fullscreen);
  const appsOpen = useAppsStore((state) => state.open);
  const watched = connected ? (shares.find((share) => share.identity === watching) ?? null) : null;

  return (
    <section className="panel flex min-w-0 flex-1 flex-col bg-surface-950">
      <header className="flex h-12 shrink-0 items-center gap-2 border-b border-edge px-2.5 md:px-4">
        {onOpenMenu && (
          <button
            type="button"
            onClick={onOpenMenu}
            aria-label="Open navigation menu"
            title="Open menu"
            className="flex h-9 w-9 min-h-[44px] min-w-[44px] cursor-pointer items-center justify-center rounded-md text-slate-300 transition-colors duration-150 hover:bg-white/[0.07] hover:text-slate-100 md:hidden"
          >
            <MenuIcon className="h-5 w-5" />
          </button>
        )}
        <SpeakerIcon className="h-5 w-5 text-slate-400 shrink-0" />
        <h1 className="truncate font-semibold text-slate-100">{channel.name}</h1>
        {stage.length > 0 && <span className="hidden sm:inline text-sm text-slate-400">- {stage.length} in voice</span>}
        {/* Only while *this* client is in the call: a clock counting somebody
            else's call, in a channel being looked at from outside it, would be
            a number with no meaning to whoever is reading it. */}
        {connected && (
          <span className="ms-auto text-xs">
            <CallDuration />
          </span>
        )}
        {connected && encrypted && (
          <span
            title="Voice media is encrypted on this device"
            className="flex items-center gap-1 text-xs text-emerald-300"
          >
            <LockIcon className="h-3.5 w-3.5" />
            E2EE
          </span>
        )}

        <button
          type="button"
          onClick={() => {
            const channels = useChatStore.getState().channels;
            const textChannel = channels.find(
              (c) => c.serverId === channel.serverId && c.type === 'TEXT',
            );
            if (textChannel) {
              void useChatStore.getState().selectChannel(textChannel.id);
            }
          }}
          className={`${connected ? 'ms-2' : 'ms-auto'} flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-medium text-slate-300 transition-colors hover:bg-white/[0.08] hover:text-white min-h-[36px] cursor-pointer`}
          title="Back to text channel"
        >
          <HashIcon className="h-3.5 w-3.5 text-slate-400" />
          <span className="hidden sm:inline">Text chat</span>
        </button>
      </header>

      <div className="flex min-h-0 flex-1 flex-col gap-3 p-4">
        {error && (
          <div
            role="alert"
            className="flex items-center justify-between gap-3 rounded bg-red-500/10 px-3 py-2 text-sm text-red-300"
          >
            <span className="min-w-0 flex-1 text-center">{error}</span>
            <button
              type="button"
              onClick={() => useVoiceStore.getState().dismissError()}
              className="inline-flex h-5 w-5 shrink-0 cursor-pointer items-center justify-center rounded text-red-300/70 transition-colors hover:bg-red-500/20 hover:text-red-100"
              title="Dismiss error"
              aria-label="Dismiss error"
            >
              <XIcon className="h-3.5 w-3.5" />
            </button>
          </div>
        )}

        {notHeard && (
          <div className="mx-auto w-full max-w-sm">
            <NotHeardNotice />
          </div>
        )}

        <ShareBanners shares={shares} watching={watching} />

        {/* Above the tiles rather than replacing them: a shared video and the
            faces watching it are the same activity, and hiding one to show the
            other is what makes a group watch feel like a broadcast. It draws
            nothing when nobody has started a queue. */}
        {/* One line saying what is playing, while the panel is closed - so the
            call goes back to being a call and the music is still visibly a
            thing that is happening. Draws nothing when nothing is. */}
        <ListenBar />

        {/* And one line saying what is on the table, on the same terms. It says
            whose move it is, which is the only part of a game anybody needs
            while they are looking at faces. */}
        <GameBar />

        {/* Listening takes the stage while it is open. Picking the next track
            is a thing somebody does with their whole attention for twenty
            seconds, and shrinking YouTube into a corner to keep nine faces on
            screen serves neither; the tiles come straight back on closing it.
            It is also the *only* place this panel is drawn - see the note on
            the button in VoiceControls. */}
        {appsOpen && connected ? (
          /* The chooser, on the stage rather than in a popover: a six-game
             library does not fit in one, and a menu over a call covers the
             faces it is supposed to sit beside. */
          <AppsPanel />
        ) : listenOpen && connected ? (
          <ListenPanel />
        ) : gameOpen && connected && !gameFullscreen ? (
          /* One stage, one thing on it - opening either panel closes the other.
             See `useGameStore.setOpen`, which is where that is decided rather
             than here, so the sidebar button obeys the same rule.

             In fullscreen the panel portals itself to the body and this slot
             draws nothing, so the stage is not laying out a board nobody can
             see behind the one that has the window. */
          <GamePanel />
        ) : stage.length === 0 ? (
          <EmptyStage />
        ) : watched ? (
          <Theatre share={watched} tiles={ordered} />
        ) : (
          <PagedGrid
            tiles={ordered}
            pinned={pinned}
            onTogglePin={(key) => setPinned((current) => (current === key ? null : key))}
          />
        )}

        {/* In fullscreen the panel portals itself to the body, so it is mounted
            here and drawn nowhere: the stage underneath goes back to being the
            call rather than laying out a board nobody can see behind the one
            that has the window. */}
        {gameOpen && connected && gameFullscreen && <GamePanel />}

        {!connected && (
          <div className="flex shrink-0 justify-center">
            <button
              type="button"
              disabled={connecting}
              onClick={() => void join(channel.id)}
              className="cursor-pointer rounded-full bg-slate-100 px-6 py-2.5 font-semibold text-slate-900 transition-colors duration-200 hover:bg-white disabled:cursor-wait disabled:opacity-60"
            >
              {connecting ? 'Connecting…' : 'Join Voice'}
            </button>
          </div>
        )}
      </div>

      {connected && (
        <footer className="flex shrink-0 justify-center px-4 py-3 z-20">
          <div className="rounded-2xl border border-white/10 bg-surface-950/90 px-4 py-2 backdrop-blur-xl shadow-2xl">
            <VoiceControls size="lg" />
          </div>
        </footer>
      )}
    </section>
  );
}

function toStage(tile: VoiceTile): Stage {
  return {
    key: tile.identity,
    name: tile.name,
    isLocal: tile.isLocal,
    speaking: tile.speaking,
    micEnabled: tile.micEnabled,
    held: tile.held,
    videoTrack: tile.videoTrack,
    lastSpokeAt: tile.lastSpokeAt,
  };
}

/** `orderStage` on a clock - see stage-order.ts for the rule itself. */
function useOrderedStage(stage: Stage[]): Stage[] {
  // Promotions expire on a timer, so a room that goes quiet re-settles without
  // needing an event to arrive first.
  const [, setTick] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setTick((value) => value + 1), 10_000);
    return () => clearInterval(timer);
  }, []);

  return useMemo(() => orderStage(stage, Date.now()), [stage]);
}

function EmptyStage(): JSX.Element {
  return (
    <div className="flex flex-1 flex-col items-center justify-center text-center">
      <SpeakerIcon className="h-12 w-12 text-slate-600" />
      <p className="mt-4 text-slate-400">No one is currently in voice</p>
    </div>
  );
}

/**
 * "bob is sharing their screen" with a way in - a share never hijacks anyone's
 * view, they opt into it.
 */
function ShareBanners({
  shares,
  watching,
}: {
  shares: VoiceShare[];
  watching: string | null;
}): JSX.Element | null {
  const watch = useVoiceStore((state) => state.watch);
  const stopScreenShare = useVoiceStore((state) => state.stopScreenShare);

  const unwatched = shares.filter((share) => share.identity !== watching);
  if (unwatched.length === 0) return null;

  return (
    <ul className="flex shrink-0 flex-col gap-2">
      {unwatched.map((share) => (
        <li
          key={share.identity}
          className="flex items-center gap-3 rounded-lg border border-accent/40 bg-accent/10 px-3 py-2"
        >
          <ScreenShareIcon className="h-4 w-4 shrink-0 text-accent" />
          <p className="min-w-0 truncate text-sm text-slate-200">
            <span className="font-semibold">{share.isLocal ? 'You are' : `${share.name} is`}</span>{' '}
            sharing a screen
          </p>
          <button
            type="button"
            onClick={() => watch(share.identity)}
            className="ms-auto shrink-0 cursor-pointer rounded-md bg-accent px-3 py-1 text-xs font-semibold text-white transition-colors duration-200 hover:brightness-110"
          >
            {share.isLocal ? 'Preview' : 'Join stream'}
          </button>
          {share.isLocal && (
            <button
              type="button"
              onClick={() => void stopScreenShare()}
              className="shrink-0 cursor-pointer rounded-md px-3 py-1 text-xs text-slate-300 transition-colors duration-200 hover:bg-white/[0.06]"
            >
              Stop
            </button>
          )}
        </li>
      ))}
    </ul>
  );
}

type LayoutMode = 'side-left' | 'side-right' | 'bottom';

/** One shared screen big, everyone else small underneath or in a side rail. Movie night. */
function Theatre({ share, tiles }: { share: VoiceShare; tiles: Stage[] }): JSX.Element {
  const watch = useVoiceStore((state) => state.watch);
  const stopScreenShare = useVoiceStore((state) => state.stopScreenShare);
  const [fullscreen, setFullscreen] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [showParticipants, setShowParticipants] = useState(true);
  const [layout, setLayout] = useState<LayoutMode>('side-left');
  const hideTimerRef = useRef<number | null>(null);

  const resetHideTimer = useCallback(() => {
    setShowControls(true);
    if (hideTimerRef.current !== null) {
      window.clearTimeout(hideTimerRef.current);
    }
    if (fullscreen) {
      hideTimerRef.current = window.setTimeout(() => {
        setShowControls(false);
      }, 2500);
    }
  }, [fullscreen]);

  useEffect(() => {
    if (fullscreen) {
      resetHideTimer();
    } else {
      setShowControls(true);
      if (hideTimerRef.current !== null) {
        window.clearTimeout(hideTimerRef.current);
        hideTimerRef.current = null;
      }
    }
    return () => {
      if (hideTimerRef.current !== null) {
        window.clearTimeout(hideTimerRef.current);
      }
    };
  }, [fullscreen, resetHideTimer]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent): void => {
      if (e.key === 'Escape' && fullscreen) {
        setFullscreen(false);
      } else if (
        (e.key === 'f' || e.key === 'F') &&
        !['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)
      ) {
        setFullscreen((prev) => !prev);
      }
      resetHideTimer();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [fullscreen, resetHideTimer]);

  const toggleFullscreen = (): void => {
    setFullscreen((prev) => !prev);
  };

  const cycleLayout = (): void => {
    setLayout((curr) =>
      curr === 'side-left' ? 'side-right' : curr === 'side-right' ? 'bottom' : 'side-left',
    );
  };

  if (fullscreen) {
    return (
      <div
        onMouseMove={resetHideTimer}
        onTouchStart={resetHideTimer}
        className={`fixed inset-0 z-50 flex flex-col bg-black select-none ${
          !showControls ? 'cursor-none' : ''
        }`}
      >
        {/* Fullscreen top header overlay (Auto-hiding) */}
        <div
          className={`absolute inset-x-0 top-0 z-30 flex items-center justify-between gap-3 bg-gradient-to-b from-black/90 via-black/50 to-transparent p-4 transition-all duration-300 ease-out ${
            captionInset
          } ${
            showControls
              ? 'opacity-100 translate-y-0 pointer-events-auto'
              : 'opacity-0 -translate-y-6 pointer-events-none'
          }`}
        >
          {/* Live badge & Stream name */}
          <div className="flex items-center gap-2 rounded-full border border-white/10 bg-black/60 px-3.5 py-1.5 backdrop-blur-md shadow-lg">
            <span className="relative flex h-2 w-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-red-400 opacity-75"></span>
              <span className="relative inline-flex h-2 w-2 rounded-full bg-red-500"></span>
            </span>
            <span className="text-xs font-semibold text-slate-100 tracking-wide">
              {share.isLocal ? 'Your screen' : `${share.name}'s screen`}
            </span>
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-2">
            {!share.isLocal && <ControlButtons share={share} />}
            {share.isLocal && (
              <button
                type="button"
                onClick={() => void stopScreenShare()}
                className="cursor-pointer rounded-md bg-red-500/90 px-3.5 py-1.5 text-xs font-semibold text-white shadow-md backdrop-blur transition-all duration-200 hover:bg-red-500 hover:shadow-red-500/20 active:scale-95"
              >
                Stop sharing
              </button>
            )}
            <button
              type="button"
              onClick={cycleLayout}
              title={`Layout: ${
                layout === 'side-left'
                  ? 'Left Side Gallery'
                  : layout === 'side-right'
                    ? 'Right Side Gallery'
                    : 'Bottom Dock'
              } (Click to switch)`}
              className="flex cursor-pointer items-center gap-1.5 rounded-md border border-white/10 bg-black/60 px-3 py-1.5 text-xs font-medium text-slate-200 backdrop-blur-md shadow-md transition-all duration-200 hover:bg-white/10 active:scale-95"
            >
              {layout === 'side-left' ? (
                <LayoutSidebarIcon className="h-3.5 w-3.5" />
              ) : layout === 'side-right' ? (
                <LayoutSidebarIcon className="h-3.5 w-3.5 scale-x-[-1]" />
              ) : (
                <LayoutBottomIcon className="h-3.5 w-3.5" />
              )}
              <span className="hidden sm:inline">
                {layout === 'side-left' ? 'Left' : layout === 'side-right' ? 'Right' : 'Bottom'}
              </span>
            </button>
            <button
              type="button"
              onClick={() => setShowParticipants((prev) => !prev)}
              aria-label={showParticipants ? 'Hide participants' : 'Show participants'}
              title={showParticipants ? 'Hide participants' : 'Show participants'}
              className={`flex cursor-pointer items-center gap-1.5 rounded-md border border-white/10 px-3 py-1.5 text-xs font-medium backdrop-blur-md shadow-md transition-all duration-200 active:scale-95 ${
                showParticipants
                  ? 'bg-white/15 text-white'
                  : 'bg-black/60 text-slate-400 hover:text-slate-200'
              }`}
            >
              <UsersIcon className="h-3.5 w-3.5" />
              <span>{tiles.length}</span>
            </button>
            <button
              type="button"
              onClick={toggleFullscreen}
              aria-label="Exit full screen"
              title="Exit full screen (Esc or F)"
              className="flex cursor-pointer items-center gap-1.5 rounded-md border border-white/10 bg-white/10 px-3.5 py-1.5 text-xs font-semibold text-white backdrop-blur-md shadow-md transition-all duration-200 hover:bg-white/20 active:scale-95"
            >
              <MinimizeIcon className="h-4 w-4" />
              Exit full screen
            </button>
            <button
              type="button"
              onClick={() => {
                setFullscreen(false);
                watch(null);
              }}
              className="cursor-pointer rounded-md border border-white/10 bg-black/60 px-3.5 py-1.5 text-xs font-medium text-slate-200 backdrop-blur-md shadow-md transition-all duration-200 hover:bg-white/10 active:scale-95"
            >
              Back to grid
            </button>
          </div>
        </div>

        {/* Fullscreen Main Content Area (Side Gallery and Center Stage) */}
        <div className="relative flex min-h-0 flex-1 flex-row items-center justify-center overflow-hidden bg-black w-full h-full">
          {/* Floating Show Cameras pill when hidden */}
          {!showParticipants && (
            <button
              type="button"
              onClick={() => setShowParticipants(true)}
              title="Show cameras alongside stream"
              className={`absolute start-4 top-20 z-20 flex items-center gap-1.5 rounded-full border border-white/10 bg-black/70 px-3.5 py-1.5 text-xs font-semibold text-slate-200 backdrop-blur-md shadow-xl transition-all duration-300 hover:bg-white/20 hover:text-white active:scale-95 ${
                showControls ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'
              }`}
            >
              <UsersIcon className="h-3.5 w-3.5" />
              <span>Show cameras ({tiles.length})</span>
            </button>
          )}

          {layout === 'side-left' && showParticipants && (
            <div className="z-20 h-full p-4 flex flex-col justify-center">
              <SideGallery
                tiles={tiles}
                isFullscreen
                onClose={() => setShowParticipants(false)}
              />
            </div>
          )}

          <div className="relative flex min-h-0 flex-1 items-center justify-center overflow-hidden bg-black h-full w-full">
            {share.track ? (
              <ShareStage share={share} />
            ) : (
              <p className="flex h-full items-center justify-center text-sm text-slate-400">
                Waiting for {share.isLocal ? 'your' : `${share.name}'s`} screen…
              </p>
            )}
          </div>

          {layout === 'side-right' && showParticipants && (
            <div className="z-20 h-full p-4 flex flex-col justify-center">
              <SideGallery
                tiles={tiles}
                isFullscreen
                onClose={() => setShowParticipants(false)}
              />
            </div>
          )}
        </div>

        {/* Fullscreen Bottom Overlay: Floating Voice Controls (Auto-Hiding) & optional Bottom filmstrip */}
        <div className="absolute inset-x-0 bottom-0 z-30 flex flex-col items-center gap-3 bg-gradient-to-t from-black/95 via-black/60 to-transparent px-6 pb-5 pt-8 pointer-events-none">
          {layout === 'bottom' && showParticipants && (
            <ul className="flex shrink-0 justify-center gap-2.5 overflow-x-auto max-w-full pb-1 pointer-events-auto">
              {tiles.map((tile) => (
                <li key={tile.key} className="w-36 shrink-0">
                  <StageTile tile={tile} />
                </li>
              ))}
            </ul>
          )}
          <div
            className={`flex items-center justify-center rounded-2xl border border-white/10 bg-black/70 px-4 py-2 backdrop-blur-md shadow-pop transition-all duration-300 ease-out ${
              showControls
                ? 'opacity-100 translate-y-0 pointer-events-auto'
                : 'opacity-0 translate-y-6 pointer-events-none'
            }`}
          >
            <VoiceControls size="sm" />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-3">
      <div className="flex min-h-0 flex-1 flex-row gap-3">
        {/* Left Side Gallery (Teams / Meet style) */}
        {layout === 'side-left' && showParticipants && (
          <SideGallery tiles={tiles} onClose={() => setShowParticipants(false)} />
        )}

        {/* Center Screen Share Stage */}
        <div className="relative min-h-0 flex-1 overflow-hidden rounded-lg bg-black">
          {share.track ? (
            <ShareStage share={share} />
          ) : (
            <p className="flex h-full items-center justify-center text-sm text-slate-400">
              Waiting for {share.isLocal ? 'your' : `${share.name}'s`} screen…
            </p>
          )}

          <p className="pointer-events-none absolute start-2 top-2 rounded bg-black/70 px-2 py-1 text-xs text-slate-200">
            {share.isLocal ? 'Your screen' : `${share.name}'s screen`}
          </p>

          {/* Floating Show Cameras pill in normal view when hidden */}
          {!showParticipants && (
            <button
              type="button"
              onClick={() => setShowParticipants(true)}
              title="Show cameras alongside stream"
              className="absolute start-2 top-10 z-10 flex items-center gap-1.5 rounded-full border border-white/10 bg-black/70 px-3 py-1 text-xs font-medium text-slate-200 backdrop-blur-md shadow-lg transition-all duration-200 hover:bg-white/20 hover:text-white"
            >
              <UsersIcon className="h-3.5 w-3.5" />
              <span>Show cameras ({tiles.length})</span>
            </button>
          )}

          <div className="absolute end-2 top-2 flex gap-2">
            {!share.isLocal && <ControlButtons share={share} />}
            {share.isLocal && (
              <button
                type="button"
                onClick={() => void stopScreenShare()}
                className="cursor-pointer rounded-md bg-red-500/90 px-3 py-1 text-xs font-semibold text-white transition-colors duration-200 hover:bg-red-500"
              >
                Stop sharing
              </button>
            )}
            <button
              type="button"
              onClick={() => setShowParticipants((prev) => !prev)}
              aria-label={showParticipants ? 'Hide cameras' : 'Show cameras'}
              title={showParticipants ? 'Hide cameras' : 'Show cameras'}
              className={`flex cursor-pointer items-center gap-1.5 rounded-md border border-white/10 px-2.5 py-1 text-xs font-medium backdrop-blur-md shadow-md transition-all duration-200 active:scale-95 ${
                showParticipants
                  ? 'bg-white/15 text-white'
                  : 'bg-black/60 text-slate-400 hover:text-slate-200'
              }`}
            >
              <UsersIcon className="h-3.5 w-3.5" />
              <span className="hidden sm:inline">
                {showParticipants ? 'Hide cameras' : 'Cameras'}
              </span>
              <span>({tiles.length})</span>
            </button>
            <button
              type="button"
              onClick={cycleLayout}
              title={`Layout: ${
                layout === 'side-left'
                  ? 'Left Side Gallery'
                  : layout === 'side-right'
                    ? 'Right Side Gallery'
                    : 'Bottom Dock'
              } (Click to switch)`}
              className="flex cursor-pointer items-center gap-1 rounded-md bg-black/70 px-2.5 py-1 text-xs text-slate-200 transition-colors duration-200 hover:bg-black"
            >
              {layout === 'side-left' ? (
                <LayoutSidebarIcon className="h-3.5 w-3.5" />
              ) : layout === 'side-right' ? (
                <LayoutSidebarIcon className="h-3.5 w-3.5 scale-x-[-1]" />
              ) : (
                <LayoutBottomIcon className="h-3.5 w-3.5" />
              )}
              <span className="hidden sm:inline">
                {layout === 'side-left' ? 'Left' : layout === 'side-right' ? 'Right' : 'Bottom'}
              </span>
            </button>
            <button
              type="button"
              onClick={toggleFullscreen}
              aria-label="Full screen"
              title="Full screen (F)"
              className="flex cursor-pointer items-center gap-1 rounded-md bg-black/70 px-3 py-1 text-xs text-slate-200 transition-colors duration-200 hover:bg-black"
            >
              <MaximizeIcon className="h-3.5 w-3.5" />
              Full screen
            </button>
            <button
              type="button"
              onClick={() => watch(null)}
              className="cursor-pointer rounded-md bg-black/70 px-3 py-1 text-xs text-slate-200 transition-colors duration-200 hover:bg-black"
            >
              Back to grid
            </button>
          </div>
        </div>

        {/* Right Side Gallery */}
        {layout === 'side-right' && showParticipants && (
          <SideGallery tiles={tiles} onClose={() => setShowParticipants(false)} />
        )}
      </div>

      {/* Bottom Filmstrip (when layout is set to 'bottom') */}
      {layout === 'bottom' && showParticipants && (
        <ul className="flex shrink-0 gap-2 overflow-x-auto pb-1">
          {tiles.map((tile) => (
            <li key={tile.key} className="w-40 shrink-0">
              <StageTile tile={tile} />
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

