   */
  callIce: (channelId: string): Promise<CallIceResponse> =>
    request('/api/v1/calls/ice', { method: 'POST', body: JSON.stringify({ channelId }) }),

  /**
   * "Come into this call." Answers 204, or a 403 saying why not - they are not
   * in this channel, or they were rung a moment ago and the cooldown holds.
   */
  /**
   * This account's own call log, newest first. The server decides whose, so
   * there is nothing to pass and nothing to get wrong.
   */
  callHistory: (): Promise<CallHistoryEntry[]> => request('/api/v1/calls/history'),

  /**
   * The same calls added up over a window of days. Read separately from the log
   * because the log is the last 50 calls and this is the last 30 days, and one
   * is not a slice of the other.
   */
  callAnalytics: (days = 30): Promise<CallAnalytics> =>
    request(`/api/v1/calls/analytics?days=${days}`),

  callRing: (channelId: string, userId: string): Promise<void> =>
    request('/api/v1/calls/ring', {
      method: 'POST',
      body: JSON.stringify({ channelId, userId }),
    }),

  /**
   * "I said no to that, here."
   *
   * Reaches this account's own other devices and nobody else - the caller is
   * deliberately not told. See `CallsService.decline`.
   */
  callDecline: (channelId: string): Promise<void> =>
    request('/api/v1/calls/decline', {
      method: 'POST',
      body: JSON.stringify({ channelId }),
    }),
};

/**
 * Files in a channel.
 *
 * A message body is still just text when it carries no files, so everything
 * written before this existed keeps rendering. The moment a file is attached,
 * the body becomes a small JSON document behind a marker no keyboard can type,
 * and that document - names, types, sizes, nonces - is what gets encrypted
 * along with the text. The server sees a ciphertext and an opaque blob.
 *
 * The order on the way out is: shrink, compress, encrypt, upload. Encryption
 * has to be last, because ciphertext does not compress, and shrinking is
 * first because there is no point compressing pixels nobody will look at.
 */
import type { MessageAttachment, UploadedPart } from '@betweenus/shared-types';
import { api } from './api';
import { decryptFileForChannel, encryptFileForChannel } from './e2ee';

/** Matches MAX_ATTACHMENT_BYTES on the server. See the note in e2ee-crypto. */
export const MAX_ATTACHMENT_BYTES = 100 * 1024 * 1024;

/**
 * One part of a large upload. Comfortably over S3's 5 MiB minimum and under
 * the gateway's 32 MB body cap, with room for the multipart form framing.
 */
const PART_BYTES = 8 * 1024 * 1024;

// --- Uploading --------------------------------------------------------------

export interface UploadProgress {
  /** 0 to 1 across the whole file, counted in parts. */
  (fraction: number): void;
}

/**
 * Shrinks, compresses, encrypts and uploads one file, and returns what the
 * message body has to carry to get it back.
 */
export async function uploadAttachment(
  channelId: string,
  file: File,
  onProgress?: UploadProgress,
  options: {
    overflow?: boolean;
    /**
     * Measured while this was being recorded. Rides inside the encrypted
     * manifest with everything else about the file, so the server learns
     * nothing from it - and every client draws the same shape.
     */
    voice?: { duration: number; waveform: number[] };
  } = {},
): Promise<MessageAttachment> {
  if (file.size > MAX_ATTACHMENT_BYTES) {
    throw new Error(`${file.name} is larger than ${formatBytes(MAX_ATTACHMENT_BYTES)}`);
  }

  const shrunk = await shrinkImage(file);
  const source = shrunk?.blob ?? file;
  const name = shrunk ? withExtension(file.name, 'jpg') : file.name;
  const contentType = shrunk ? JPEG : file.type || 'application/octet-stream';

  const gzip = shouldGzip(contentType, source.size);
  const packed = gzip ? await gzipBlob(source) : source;
  const plaintext = new Uint8Array(await packed.arrayBuffer());

  const { ciphertext, iv, epoch } = await encryptFileForChannel(channelId, plaintext);
  const stored = await putBytes(ciphertext, onProgress);

  return {
    key: stored.key,
    url: stored.url,
    name,
    contentType,
    // The size a person is shown is the size of the file they picked, not of
    // whatever the compressor and the cipher made of it.
    size: source.size,
    iv,
    epoch,
    ...(gzip ? { gzip: true } : {}),
    ...(shrunk ? { width: shrunk.width, height: shrunk.height } : {}),
    ...(options.overflow ? { overflow: true } : {}),
    ...(options.voice
      ? { duration: options.voice.duration, waveform: options.voice.waveform }
      : {}),
  };
}

/**
 * How many parts are in flight at once.
 *
 * Three rather than one, and not many more: past this the parts start
 * competing for the same uplink instead of covering each other's latency, and
 * the object store is being asked to hold more of one file open at a time for
 * no gain.
 */
const UPLOAD_LANES = 3;

/** One request when it fits in one; otherwise a few parts at a time. */
async function putBytes(
  bytes: Uint8Array<ArrayBuffer>,
  onProgress?: UploadProgress,
): Promise<{ key: string; url: string }> {
  const blob = new Blob([bytes]);

  if (blob.size <= PART_BYTES) {
    const stored = await api.uploadAttachment(blob);
    onProgress?.(1);
    return stored;
  }

  const { ticket, maxPartBytes } = await api.startMultipart(blob.size);
  const partSize = Math.min(PART_BYTES, maxPartBytes);
  const total = Math.ceil(blob.size / partSize);

  try {
    // A few parts at a time. One at a time was the old answer and it was the
    // wrong one: a single request spends most of its life waiting - the round
    // trip to the gateway, the tunnel, the store's own acknowledgement - and
    // none of that is uplink. A `Blob.slice` is a view rather than a copy, so
    // the parts in flight cost no extra memory to hold.
    const parts: UploadedPart[] = new Array(total);
    let next = 0;
    let done = 0;

    const worker = async (): Promise<void> => {
      for (let index = next; index < total; index = next) {
        next = index + 1;
        const slice = blob.slice(index * partSize, (index + 1) * partSize);
        parts[index] = await api.uploadPart(ticket, index + 1, slice);
        done += 1;
        onProgress?.(done / total);
      }
    };

    await Promise.all(
      Array.from({ length: Math.min(UPLOAD_LANES, total) }, () => worker()),
    );
    return await api.completeMultipart(ticket, parts);
  } catch (error) {
    // Leave no half-uploaded parts behind for a file nobody will ever send.
    await api.abortMultipart(ticket).catch(() => undefined);
    throw error;
  }
}

// --- Downloading ------------------------------------------------------------

const cache = new Map<string, Blob>();

/** Fetches, decrypts and un-gzips an attachment. Cached: opening it twice is one download. */
export async function openAttachment(
  channelId: string,
  attachment: MessageAttachment,
): Promise<Blob> {
  const cached = cache.get(attachment.key);
  if (cached) return cached;

  const ciphertext = await api.fetchObject(attachment.url);
  const plaintext = await decryptFileForChannel(
    channelId,
    ciphertext,
    attachment.iv,
    attachment.epoch,
  );

  const sealed = new Blob([plaintext], { type: attachment.contentType });
  const unpacked = attachment.gzip ? await gunzipBlob(sealed, attachment.contentType) : sealed;
  // A HEIC sent from a phone before its client learned to convert them. The
  // DOM cannot draw one, so it becomes a JPEG here, once, on the way into the
  // cache - every screen that asks for this attachment gets the JPEG.
  const blob = isHeic(attachment.name, attachment.contentType)
    ? await heicToJpeg(unpacked)
    : unpacked;

  // Bounded so a long scroll through an image channel does not grow forever.
  if (cache.size > 40) cache.delete(cache.keys().next().value as string);
  cache.set(attachment.key, blob);
  return blob;
}

/**
 * Drops the decrypted copies of these attachments.
 *
 * The cache above is the whole reason this has to exist. It holds plaintext -
 * the actual picture, decoded and ready to draw - and it is keyed on the
 * storage key rather than on the message, so nothing about a message being
 * deleted reaches it on its own. Without this, deleting a photo removed it
 * from the channel, from the database and from the object store, and left the
 * decrypted bytes sitting in this map for the rest of the session, drawable by
 * any screen that still had the manifest.
 *
 * Called whenever a message goes: a delete, a one-time message that was
 * opened, a disappearing window that closed.
 */
export function forgetAttachments(keys: string[]): void {
  for (const key of keys) cache.delete(key);
}

/** For the preview: an attachment's text, capped so a huge file cannot lock the UI. */
export async function readAttachmentText(
  channelId: string,
  attachment: MessageAttachment,
  maxChars = 200_000,
): Promise<string> {
  const blob = await openAttachment(channelId, attachment);
  const text = await blob.text();
  return text.length > maxChars ? `${text.slice(0, maxChars)}\n…` : text;
}

/** Saves an attachment through the browser's own download path. */
export async function saveAttachment(
  channelId: string,
  attachment: MessageAttachment,
): Promise<void> {
  const blob = await openAttachment(channelId, attachment);
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  // A converted HEIC is JPEG bytes now; saving them under a .heic name would
  // hand the operating system a file that lies about itself.
  const isMedia = attachment.contentType.startsWith('image/') || attachment.contentType.startsWith('video/');
  if (isMedia) {
    const now = new Date();
    const pad = (n: number) => n.toString().padStart(2, '0');
    const dateStr = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
    const ext = (blob.type === attachment.contentType ? attachment.name.split('.').pop() : 'jpg') || 'jpg';
    link.download = `bu_${dateStr}.${ext}`;
  } else {
    link.download =
      blob.type === attachment.contentType ? attachment.name : withExtension(attachment.name, 'jpg');
  }
  link.click();
  // Revoked on the next tick: the click has to have read it first.
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

// --- Pictures ---------------------------------------------------------------

/**
 * An avatar, a server icon or a profile cover. These are stored in the clear,
 * so the client hands over exactly what it wants every other client to fetch:
 * a fixed shape, cropped from the centre, small enough that a member list of
 * them is cheap.
 *
 * `aspect` is width over height - 1 for the square things, `COVER_ASPECT` for
 * the band behind a name. A parameter rather than two functions because the
 * only difference between the two cases is which edge runs out first, and
 * `cropBox` below is that sentence written down.
 */
export async function preparePicture(file: File, edge = 512, aspect = 1): Promise<Blob> {
  const bitmap = await decodeImage(file);
  try {
    const crop = cropBox(bitmap.width, bitmap.height, aspect);
    // Never upscaled: enlarging a small picture to hit the cap spends bytes
    // inventing detail that is not in the file.
    const width = Math.min(edge, crop.width);
    const canvas = new OffscreenCanvas(Math.round(width), Math.round(width / aspect));
    const context = canvas.getContext('2d');
    if (!context) throw new Error('This device cannot process images');

    context.drawImage(
      bitmap,
      crop.x,
      crop.y,
      crop.width,
      crop.height,
      0,
      0,
      canvas.width,
      canvas.height,
    );
    return await canvas.convertToBlob({ type: 'image/webp', quality: 0.9 });
  } finally {
    bitmap.close();
  }
}

/**
 * The largest `aspect`-shaped rectangle inside `width` x `height`, centred.
 *
 * Exported for `image-edit.check.ts`: the cases worth pinning are a portrait
 * photograph cropped to a wide band and a wide one cropped to a square, and
 * both are arithmetic rather than anything a browser has to be present for.
 */
export function cropBox(
  width: number,
  height: number,
  aspect: number,
): { x: number; y: number; width: number; height: number } {
  // Wider than the shape it is going into, so height is the constraint.
  const tooWide = width / height > aspect;
  const cropWidth = tooWide ? height * aspect : width;
  const cropHeight = tooWide ? height : width / aspect;
  return {
    x: (width - cropWidth) / 2,
    y: (height - cropHeight) / 2,
    width: cropWidth,
    height: cropHeight,
  };
}

/** Above this a photo is worth re-encoding; below it the saving is noise. */
const SHRINK_ABOVE_BYTES = 512 * 1024;
const MAX_IMAGE_EDGE = 1920;
const JPEG = 'image/jpeg';

/**
 * Downscales an oversized photo, and re-encodes every photo as JPEG. Returns
 * null when the file is not an image, is already small, or came out no smaller
 * - the original wins those.
 *
 * GIF and SVG are left alone: a canvas would flatten an animation to its first
 * frame, and would rasterise a drawing that was meant to scale.
 *
 * HEIC is the exception to every "already small" rule below. It is converted
 * whatever its size, because the point of converting it is not its size - it is
 * that no browser engine can draw one, so an unconverted HEIC is a broken
 * image on every client except the phone it came from.
 */
export async function shrinkImage(
  file: File,
): Promise<{ blob: Blob; width: number; height: number } | null> {
  const type = file.type.toLowerCase();
  const heic = isHeic(file.name, type);
  if (!heic && (!type.startsWith('image/') || type === 'image/gif' || type === 'image/svg+xml')) {
    return null;
  }

  try {
    const bitmap = await decodeImage(file);
    try {
      const scale = Math.min(1, MAX_IMAGE_EDGE / Math.max(bitmap.width, bitmap.height));
      if (!heic && scale === 1 && file.size <= SHRINK_ABOVE_BYTES) return null;

      const width = Math.max(1, Math.round(bitmap.width * scale));
      const height = Math.max(1, Math.round(bitmap.height * scale));
      const blob = await toJpeg(bitmap, width, height);
      return !heic && blob.size >= file.size ? null : { blob, width, height };
    } finally {
      bitmap.close();
    }
  } catch {
    // Not decodable as an image after all - send it as the file it is.
    return null;
  }
}

/** Draws a bitmap at the given size and encodes it as JPEG. */
async function toJpeg(bitmap: ImageBitmap, width: number, height: number): Promise<Blob> {
  const canvas = new OffscreenCanvas(width, height);
  const context = canvas.getContext('2d');
  if (!context) throw new Error('This device cannot process images');

  // JPEG has no alpha channel, and a canvas starts out transparent black. A
  // screenshot with a transparent corner would come out with a black one, so
  // the ground is painted white first - the same thing every other messenger
  // does with a transparent picture.
  context.fillStyle = '#ffffff';
  context.fillRect(0, 0, width, height);
  context.drawImage(bitmap, 0, 0, width, height);
  return canvas.convertToBlob({ type: JPEG, quality: 0.85 });
}

// --- HEIC -------------------------------------------------------------------

/**
 * What a phone camera writes by default, and what no browser can read.
 *
 * Chromium has never shipped a HEIF decoder, so `<img>` and `createImageBitmap`
 * both fail on one. That is the whole of the bug this exists for: a photo sent
 * from the Android client - whose platform decodes HEIC natively, so it looked
 * fine there - arrived on the desktop and the web as a broken image.
 *
 * So the format is decoded here instead, by libheif compiled to WebAssembly,
 * and turned into a JPEG. Both ends run through this: a HEIC picked on this
 * machine is converted before it is sent, and one that was already sent from a
 * phone is converted after it is decrypted.
 */
function isHeic(name: string, contentType: string): boolean {
  // The type can be missing or wrong - a file dragged in from a folder often
  // has neither - so the name gets a vote.
  return /^image\/hei[cf]/.test(contentType.toLowerCase()) || /\.hei[cf]$/i.test(name);
}

/** Anything the platform can decode, plus the one thing it cannot. */
export async function decodeImage(file: File): Promise<ImageBitmap> {
  return isHeic(file.name, file.type) ? decodeHeic(file) : createImageBitmap(file);
}

/**
 * A megabyte of WebAssembly, imported the first time a HEIC actually turns up
 * and never in a session that has none. Held afterwards: a channel full of
 * phone photos should instantiate one decoder, not one per picture.
 */
let libheif: Promise<typeof import('libheif-js/wasm-bundle')> | null = null;

async function decodeHeic(blob: Blob): Promise<ImageBitmap> {
  libheif ??= import('libheif-js/wasm-bundle');
  const { HeifDecoder } = await libheif;

  const images = new HeifDecoder().decode(new Uint8Array(await blob.arrayBuffer()));
  const image = images[0];
  if (!image) throw new Error('That HEIC file holds no picture');

  const width = image.get_width();
  const height = image.get_height();
  const pixels = new ImageData(width, height);
  await new Promise<void>((resolve, reject) => {
    // libheif fills the buffer in place and reports success by handing it back.
    image.display(pixels, (filled) =>
      filled ? resolve() : reject(new Error('That HEIC file could not be read')),
    );
  });
  return createImageBitmap(pixels);
}

/** A stored HEIC, made viewable. The original on failure: a file card beats nothing. */
async function heicToJpeg(blob: Blob): Promise<Blob> {
  try {
    const bitmap = await decodeHeic(blob);
    try {
      return await toJpeg(bitmap, bitmap.width, bitmap.height);
    } finally {
      bitmap.close();
    }
  } catch {
    return blob;
  }
}

// --- Compression ------------------------------------------------------------

const GZIP_TYPES = /^(text\/|application\/(json|xml|javascript|x-ndjson)|image\/svg\+xml)/;
const GZIP_ABOVE_BYTES = 4 * 1024;

/**
 * Text-shaped files compress to a fraction of their size and cost nothing to
 * unpack. Everything else is either already compressed (photos, video,
 * archives) or too small to be worth a header.
 */
function shouldGzip(contentType: string, size: number): boolean {
  return size > GZIP_ABOVE_BYTES && GZIP_TYPES.test(contentType.toLowerCase());
}

async function gzipBlob(blob: Blob): Promise<Blob> {
  return new Response(blob.stream().pipeThrough(new CompressionStream('gzip'))).blob();
}

async function gunzipBlob(blob: Blob, contentType: string): Promise<Blob> {
  const stream = blob.stream().pipeThrough(new DecompressionStream('gzip'));
  return new Blob([await new Response(stream).arrayBuffer()], { type: contentType });
}

// --- Odds and ends ----------------------------------------------------------

function withExtension(name: string, extension: string): string {
  const dot = name.lastIndexOf('.');
  return `${dot > 0 ? name.slice(0, dot) : name}.${extension}`;
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const units = ['KB', 'MB', 'GB'];
  let value = bytes / 1024;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${units[unit]}`;
}

/**
 * Run with `tsx src/services/audio-devices.check.ts`.
 *
 * The two pure decisions - whether a chosen device has gone, and whether a live
 * capture is now on the wrong one - and the one branch that is not pure but is
 * worth faking three lines for: the retry that opens the system default when
 * the device somebody chose is not there. Enumeration itself needs a browser.
 */
import assert from 'node:assert/strict';
import {
  captureIsStale,
  chosenIsMissing,
  openAudioCapture,
  realDevices,
} from './audio-devices';

const device = (deviceId: string, kind: MediaDeviceKind): MediaDeviceInfo =>
  ({ deviceId, kind, label: deviceId, groupId: '' }) as MediaDeviceInfo;

const headset = device('headset', 'audioinput');
const webcamMic = device('webcam', 'audioinput');
const speakers = device('speakers', 'audiooutput');

// Nothing chosen is never missing: the system default is always something.
assert.equal(chosenIsMissing([headset], 'audioinput', null), false);
assert.equal(chosenIsMissing([headset, webcamMic], 'audioinput', 'headset'), false);
assert.equal(chosenIsMissing([webcamMic], 'audioinput', 'headset'), true);

// An empty list is "not enumerated yet", not "your microphone is gone".
assert.equal(chosenIsMissing([], 'audioinput', 'headset'), false);
// Kinds do not answer for each other: a speaker list says nothing about a mic.
assert.equal(chosenIsMissing([speakers], 'audioinput', 'headset'), false);

// Following the system default means every change is worth recapturing for.
assert.equal(captureIsStale(null, 'webcam', [headset, webcamMic]), true);
// On the device that was asked for: nothing to do.
assert.equal(captureIsStale('headset', 'headset', [headset, webcamMic]), false);
// The chosen device came back and the capture is still on the fallback.
assert.equal(captureIsStale('headset', 'webcam', [headset, webcamMic]), true);
// Chosen and still absent: recapturing would land on the same fallback.
assert.equal(captureIsStale('headset', 'webcam', [webcamMic]), false);

// Before the microphone is granted, `enumerateDevices` answers with one empty
// entry per kind rather than with nothing. Left in, it is a list of one that is
// not your device, so every chosen device reads as unplugged - which is the
// spurious "the device you chose is not connected" and the fallback behind it.
const unasked = [device('', 'audioinput'), device('', 'audiooutput')];
assert.deepEqual(realDevices(unasked), []);
assert.equal(chosenIsMissing(unasked, 'audioinput', 'headset'), true, 'the bug this guards');
assert.equal(chosenIsMissing(realDevices(unasked), 'audioinput', 'headset'), false);

// A real list is passed through untouched.
assert.deepEqual(realDevices([headset, webcamMic]), [headset, webcamMic]);

// --- The fallback `exact` bought -------------------------------------------
//
// Naming the device with `exact` is what makes choosing one work at all, and it
// is also what turns an unplugged device into a refusal. The retry is the whole
// of that trade, so it is checked here rather than trusted: a fake
// `getUserMedia` is three lines, and the alternative is finding out in a call.

const asked: MediaTrackConstraints[] = [];

function fakeGetUserMedia(fail: (attempt: number) => Error | null): void {
  Object.defineProperty(globalThis, 'navigator', {
    configurable: true,
    value: {
      mediaDevices: {
        getUserMedia: (constraints: MediaStreamConstraints) => {
          asked.push(constraints.audio as MediaTrackConstraints);
          const error = fail(asked.length);
          return error ? Promise.reject(error) : Promise.resolve('stream' as unknown as MediaStream);
        },
      },
    },
  });
}

const named = (name: string): Error => Object.assign(new Error(name), { name });

// The chosen device is gone: refused once, then opened on the system default
// with every other constraint intact.
asked.length = 0;
fakeGetUserMedia((attempt) => (attempt === 1 ? named('OverconstrainedError') : null));
await openAudioCapture({ deviceId: { exact: 'headset' }, noiseSuppression: true });
assert.equal(asked.length, 2);
assert.deepEqual(asked[1], { noiseSuppression: true }, 'the retry drops only the device');

// A browser that checked the hardware first says the same thing differently.
asked.length = 0;
fakeGetUserMedia((attempt) => (attempt === 1 ? named('NotFoundError') : null));
await openAudioCapture({ deviceId: { exact: 'headset' } });
assert.equal(asked.length, 2);

// A refused permission is not a missing device. Retrying it would be denied
// again and would report the wrong failure, so it is re-thrown untouched.
asked.length = 0;
fakeGetUserMedia(() => named('NotAllowedError'));
await assert.rejects(openAudioCapture({ deviceId: { exact: 'headset' } }), /NotAllowedError/);
assert.equal(asked.length, 1, 'a denied permission is asked once');

// Nothing chosen, nothing to fall back to: one attempt, and its failure stands.
asked.length = 0;
fakeGetUserMedia(() => named('NotFoundError'));
await assert.rejects(openAudioCapture({ noiseSuppression: true }), /NotFoundError/);
assert.equal(asked.length, 1, 'no device named means no second attempt');

console.log('audio-devices.check.ts ok');

/**
 * What this machine has plugged in, in one place.
 *
 * Every picker used to enumerate the hardware for itself, which meant two lists
 * that could disagree and a stale one behind any popover that happened to be
 * mounted before a headset arrived. There is one list here, one `devicechange`
 * listener behind it, and everything that draws or decides reads it.
 *
 * The pure parts - which device a setting resolves to, and whether it is still
 * there - are exported separately so they can be tested under Node.
 */

let devices: MediaDeviceInfo[] = [];
const listeners = new Set<(devices: MediaDeviceInfo[]) => void>();

/** The list as last read. Empty before the first enumeration. */
export function readDevices(): MediaDeviceInfo[] {
  return devices;
}

/** Re-reads the hardware. Cheap, and idempotent. */
export function refreshDevices(): void {
  if (typeof navigator === 'undefined' || !navigator.mediaDevices) return;
  void navigator.mediaDevices
    .enumerateDevices()
    .then((found) => {
      devices = realDevices(found);
      for (const listener of listeners) listener(devices);
    })
    .catch(() => undefined);
}

/**
 * The hardware, with the stand-in for "you have not been asked yet" removed.
 *
 * Before the microphone has ever been granted, `enumerateDevices` does not
 * return nothing - it returns one entry per kind with an empty id and an empty
 * label, which is the browser saying a device of that kind exists and declining
 * to say which. Kept, that placeholder is indistinguishable from a real list of
 * one, and every question asked of the list gets the wrong answer from it: a
 * chosen microphone is reported missing because the placeholder is not it, the
 * picker falls back to showing "System default" over a choice that is still
 * there, and the warning about an unplugged device appears on a machine with
 * nothing unplugged.
 *
 * Dropped, the list is empty until permission - and empty already means "not
 * enumerated yet" everywhere below, which is the truth.
 */
export function realDevices(found: MediaDeviceInfo[]): MediaDeviceInfo[] {
  return found.filter((device) => device.deviceId !== '');
}

/** Calls back on every change, and returns the unsubscribe. */
export function onDevicesChanged(listener: (devices: MediaDeviceInfo[]) => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

if (typeof navigator !== 'undefined' && navigator.mediaDevices) {
  navigator.mediaDevices.addEventListener('devicechange', refreshDevices);
  // The labels are blank until a capture has been granted once, and a granted
  // permission is not an event - so the list is also re-read when the window
  // comes back, which is after the permission prompt and after the operating
  // system's own sound settings have been visited.
  window.addEventListener('focus', refreshDevices);
  refreshDevices();
}

/**
 * True when a device has been chosen and is no longer connected.
 *
 * This is the state behind "it picked the wrong microphone": the capture
 * constraint is deliberately not `exact`, so an absent device is not an error -
 * it is a silent fallback to whatever the operating system calls the default.
 *
 * An empty list is not an answer: it means nothing has been enumerated yet, and
 * warning about a device that has simply not been looked for is worse than
 * saying nothing.
 */
export function chosenIsMissing(
  devices: MediaDeviceInfo[],
  kind: MediaDeviceKind,
  chosen: string | null,
): boolean {
  if (!chosen) return false;
  const ofKind = devices.filter((device) => device.kind === kind);
  if (ofKind.length === 0) return false;
  return !ofKind.some((device) => device.deviceId === chosen);
}

/**
 * Whether a device change means the live capture is now on the wrong device.
 *
 * Two cases, and they are different questions. With a device chosen, the
 * capture is wrong when it is not on that device - which happens when the
 * device was unplugged and has come back, since the fallback capture does not
 * follow it home. With nothing chosen the capture follows the system default,
 * and the default is exactly what changes when somebody plugs in a headset -
 * so any change at all is worth recapturing for.
 */
export function captureIsStale(
  chosen: string | null,
  capturedDeviceId: string | null,
  devices: MediaDeviceInfo[],
): boolean {
  if (!chosen) return true;
  // Chosen but absent: the fallback is the best that can be done, and
  // recapturing would only pick the same fallback again.
  if (chosenIsMissing(devices, 'audioinput', chosen)) return false;
  return capturedDeviceId !== chosen;
}

/**
 * Whether a `getUserMedia` failure is "that device is not there", as opposed to
 * a refused permission or a machine with no microphone at all.
 *
 * `OverconstrainedError` is the spec's answer and what Chromium raises for an
 * `exact` device id it cannot satisfy. `NotFoundError` is the same sentence
 * from a browser that checked the hardware first, so both are treated as the
 * device having gone - and a machine with genuinely nothing plugged in still
 * fails, on the retry, which is the truthful failure.
 */
function deviceIsGone(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  return error.name === 'OverconstrainedError' || error.name === 'NotFoundError';
}

/**
 * Opens a microphone, falling back to the system default when the chosen device
 * has gone.
 *
 * Every audio constraint in this app names its device with `exact`, because
 * nothing weaker is honoured - see `deviceConstraint`. `exact` is also what
 * turns an unplugged headset from a silent substitution into a refusal, so the
 * substitution is made here instead: deliberately, in one place, and only for
 * the failure that actually means the device is missing. A denied permission is
 * re-thrown, because retrying it would only be denied again while making the
 * error say something else.
 */
export async function openAudioCapture(constraints: MediaTrackConstraints): Promise<MediaStream> {
  try {
    return await navigator.mediaDevices.getUserMedia({ audio: constraints });
  } catch (error) {
    if (constraints.deviceId === undefined || !deviceIsGone(error)) throw error;
    const { deviceId: _gone, ...withoutDevice } = constraints;
    return navigator.mediaDevices.getUserMedia({ audio: withoutDevice });
  }
}

import assert from 'node:assert/strict';
import {
  readDismissedUntil,
  shouldWarnAboutBackup,
  SNOOZE_KEY,
  SNOOZE_MS,
  type IdentityLike,
} from './backup-warning';

const ready = (backedUp: boolean): IdentityLike => ({ status: 'ready', backedUp });

// --- the case the notice exists for -----------------------------------------

// A key this machine holds and nothing else has a copy of. Lose the machine,
// lose every conversation it could read - and no support route recovers it,
// because the server holds ciphertext and no key.
assert.equal(shouldWarnAboutBackup(ready(false), null), true);

// --- and everybody it must not interrupt ------------------------------------

// The common case by far: a password sign-in seals a backup on its own. A
// warning shown to people who are already safe is one everybody learns to
// scroll past, which costs the people who are not.
assert.equal(shouldWarnAboutBackup(ready(true), null), false);

// No identity unlocked yet - that has its own screen, and there is nothing to
// have lost.
assert.equal(shouldWarnAboutBackup({ status: 'absent' }, null), false);
assert.equal(shouldWarnAboutBackup({ status: 'absent', backedUp: false }, null), false);

// A machine shut out on purpose. Telling it to make a backup is advice about a
// key it is not allowed to use.
assert.equal(shouldWarnAboutBackup({ status: 'revoked' }, null), false);
assert.equal(shouldWarnAboutBackup({ status: 'revoked', backedUp: false }, null), false);

// An identity that never said either way is not assumed to be safe. `backedUp`
// missing means unknown, and unknown here has to read as at-risk: the failure
// of warning somebody unnecessarily is an ignored banner, and the failure of
// staying quiet is somebody losing everything.
assert.equal(shouldWarnAboutBackup({ status: 'ready' }, null), true);

// --- dismissal, which now survives a restart ---------------------------------

const now = 1_800_000_000_000;

// "Not now" hides it, and keeps hiding it across launches for SNOOZE_MS. It
// used to be one session, so it came back on every single start - a warning
// that returns that often is a nag, and a nag gets ignored in place, which is
// the failure per-session dismissal was written to avoid.
assert.equal(shouldWarnAboutBackup(ready(false), now + SNOOZE_MS, now), false);
assert.equal(shouldWarnAboutBackup(ready(false), now + 1, now), false, 'still snoozed');

// And it comes back when the snooze runs out, because the account is still
// unrecoverable and that has not stopped being true.
assert.equal(shouldWarnAboutBackup(ready(false), now, now), true, 'due exactly on the stamp');
assert.equal(shouldWarnAboutBackup(ready(false), now - 1, now), true, 'and after it');

// Dismissal never outranks the fact. Once a backup exists the notice is gone
// whether or not it was ever dismissed - so setting up recovery removes it
// immediately rather than in thirty days.
assert.equal(shouldWarnAboutBackup(ready(true), now + SNOOZE_MS, now), false);

// --- reading the stamp back --------------------------------------------------

// Storage holding junk, or throwing outright, must not stop a warning being
// drawn: unreadable reads as "never dismissed", which errs towards showing it.
const store = (value: string | null): Pick<Storage, 'getItem'> => ({ getItem: () => value });
assert.equal(readDismissedUntil(store(String(now))), now);
assert.equal(readDismissedUntil(store(null)), null, 'never dismissed');
assert.equal(readDismissedUntil(store('later')), null, 'junk reads as never dismissed');
assert.equal(
  readDismissedUntil({
    getItem: () => {
      throw new Error('storage is disabled');
    },
  }),
  null,
  'a throwing store never hides the warning',
);
assert.equal(typeof SNOOZE_KEY, 'string');

console.log('backup-warning.check.ts ok');

/**
 * Whether to tell somebody their account cannot be recovered.
 *
 * `ensureBackup` in `e2ee.ts` ends with a comment that is exactly right and
 * exactly the problem: *"an account without a backup still works, it is only
 * unrecoverable, and the settings panel says so."* The settings panel does say
 * so. Nothing brings anybody to the settings panel.
 *
 * So this is the rule for the one notice that does. It is deliberately narrow -
 * it fires for the accounts that genuinely have no way back in, and for nobody
 * else, because a warning shown to people who are already safe is a warning
 * everybody learns to scroll past.
 *
 * ## Who is actually at risk
 *
 * Signing in with a password seals a backup on its own, so most accounts are
 * covered without anybody doing anything. The accounts that are not are the
 * ones with no password to derive from - a Google or GitHub sign-in - and they
 * are never told. If that machine is lost, every conversation it could read
 * goes with it, and there is no support route that recovers it: the server
 * holds ciphertext and no key.
 *
 * That is the whole justification for interrupting somebody at all.
 */

/** The shape this needs of the identity store. */
export interface IdentityLike {
  status: 'absent' | 'ready' | 'revoked';
  /** Whether *this machine's* key is in a backup the account can restore from. */
  backedUp?: boolean;
}

export function shouldWarnAboutBackup(
  identity: IdentityLike,
  /**
   * When the last dismissal runs out, in epoch milliseconds, or null for "never
   * dismissed". See `SNOOZE_MS`.
   */
  dismissedUntil: number | null,
  now: number = Date.now(),
): boolean {
  // Nothing to lose yet, or nothing this notice can help with. `absent` is a
  // client that has not unlocked an identity - it has its own screen - and
  // `revoked` is a machine that has been shut out deliberately.
  if (identity.status !== 'ready') return false;
  if (identity.backedUp) return false;
  // A stamp in the future is a dismissal that has not run out. A stamp in the
  // past, or none, is a notice that is due.
  return dismissedUntil === null || now >= dismissedUntil;
}

/**
 * How long "Not now" lasts.
 *
 * This used to be one session, and the reasoning was sound in one direction
 * only: a permanently dismissible warning about unrecoverable data loss is one
 * somebody clicks away on their first day while the risk stays exactly as it
 * was. What that missed is that a warning returning on every single launch is a
 * nag, and a nag gets ignored *in place* - still on screen, no longer read - so
 * per-session dismissal produced the failure it was trying to avoid, and made
 * the app feel broken while doing it.
 *
 * Thirty days is the honest middle. It goes away properly when asked, it comes
 * back long enough later that it reads as a fresh warning rather than as the
 * same one again, and it stops for good the moment a backup exists - which is
 * the only thing that actually changes the fact it is describing.
 *
 * Nothing here overrides that last part: `backedUp` short-circuits above the
 * snooze, so setting up recovery removes the notice immediately whatever is
 * stored.
 */
export const SNOOZE_MS = 30 * 24 * 60 * 60 * 1000;

/** Where the stamp lives. Per machine, because the risk is about this machine. */
export const SNOOZE_KEY = 'betweenus.backupNotice.dismissedUntil';

/**
 * Reads the stored stamp. Never throws: storage can be unavailable or hold
 * junk, and neither is a reason to fail to draw a warning - an unreadable
 * value reads as "never dismissed", which errs towards showing it.
 */
export function readDismissedUntil(store: Pick<Storage, 'getItem'>): number | null {
  try {
    const raw = store.getItem(SNOOZE_KEY);
    if (raw === null) return null;
    const parsed = Number(raw);
    return Number.isFinite(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * What this device already knows, so opening the app is not a spinner.
 *
 * The port of `apps/android/core/src/main/java/com/aatech/betweenus/core/store/Cache.kt`,
 * and it keeps that file's one rule: **nothing in here is plaintext**. Messages
 * are stored exactly as the server sent them - a sealed envelope this client
 * happens to hold the key for - and the lists are things the server would hand
 * to anyone who asked with this account's token. Writing decrypted bodies to
 * disk would undo what the encryption is for, which is why the decrypted
 * history in `stores/chat.ts` stays in memory and dies with the window.
 *
 * A cache has nothing in it that cannot be fetched again, so every failure path
 * here is "carry on without it". Nothing throws into a caller.
 */
import type { Channel, DirectChannel, Message, ServerWithRole } from '@betweenus/shared-types';

const DB_NAME = 'betweenus-cache';
const DB_VERSION = 1;
const LISTS = 'lists';
const MESSAGES = 'messages';
const OWNER_KEY = 'owner';

/** Messages kept per channel. Fifty is the server's page; this holds ten of them. */
const MESSAGES_PER_CHANNEL = 500;

let open: Promise<IDBDatabase | null> | null = null;

function database(): Promise<IDBDatabase | null> {
  if (open) return open;

  open = new Promise((resolve) => {
    if (typeof indexedDB === 'undefined') {
      resolve(null);
      return;
    }
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(LISTS)) db.createObjectStore(LISTS);
      if (!db.objectStoreNames.contains(MESSAGES)) {
        const store = db.createObjectStore(MESSAGES, { keyPath: 'id' });
        // Read by channel, ordered by time - which is the only read there is.
        store.createIndex('channel', ['channelId', 'createdAt']);
      }
    };
    request.onsuccess = () => resolve(request.result);
    // A browser with storage denied, a private window, a corrupt database: all
    // of them are an app that works and does not open instantly.
    request.onerror = () => resolve(null);
  });

  return open;
}

function done(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => resolve();
    transaction.onabort = () => resolve();
  });
}

function ask<T>(request: IDBRequest<T>): Promise<T | null> {
  return new Promise((resolve) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => resolve(null);
  });
}

// --- Lists ------------------------------------------------------------------

async function readList<T>(key: string): Promise<T | null> {
  const db = await database();
  if (!db) return null;
  const store = db.transaction(LISTS, 'readonly').objectStore(LISTS);
  return (await ask<T>(store.get(key) as IDBRequest<T>)) ?? null;
}

async function writeList(key: string, value: unknown): Promise<void> {
  const db = await database();
  if (!db) return;
  const transaction = db.transaction(LISTS, 'readwrite');
  transaction.objectStore(LISTS).put(value, key);
  await done(transaction);
}

export const cache = {
  /**
   * Binds the cache to an account. A different one than last time means
   * everything here belongs to somebody else and goes.
   *
   * Called before either store reads from it, so a cache belonging to another
   * account is gone rather than merely about to be.
   */
  async claim(userId: string): Promise<void> {
    const owner = await readList<string>(OWNER_KEY);
    if (owner === userId) return;
    await cache.clear();
    await writeList(OWNER_KEY, userId);
  },

  /**
   * Forgets everything. Signing out is the one moment somebody has said they
   * are done with this device - a session that merely expired keeps its cache,
   * so signing back in is still instant.
   */
  async clear(): Promise<void> {
    const db = await database();
    if (!db) return;
    const transaction = db.transaction([LISTS, MESSAGES], 'readwrite');
    transaction.objectStore(LISTS).clear();
    transaction.objectStore(MESSAGES).clear();
    await done(transaction);
  },

  /**
   * Forgets one channel's messages and nothing else.
   *
   * What "clear this chat" needs. `clear()` would work and is one line shorter,
   * but it throws away every other conversation this device has cached - so
   * clearing one chat would turn the next four things the person opens into
   * spinners, for no reason they could connect to what they just did.
   */
  async forgetChannel(channelId: string): Promise<void> {
    const db = await database();
    if (!db) return;

    const transaction = db.transaction(MESSAGES, 'readwrite');
    const index = transaction.objectStore(MESSAGES).index('channel');
    const range = IDBKeyRange.bound([channelId, ''], [channelId, '\uffff']);

    await new Promise<void>((resolve) => {
      const cursor = index.openCursor(range);
      cursor.onsuccess = () => {
        const at = cursor.result;
        if (!at) {
          resolve();
          return;
        }
        at.delete();
        at.continue();
      };
      cursor.onerror = () => resolve();
    });
    await done(transaction);
  },

  servers: (): Promise<ServerWithRole[] | null> => readList('servers'),
  putServers: (servers: ServerWithRole[]): Promise<void> => writeList('servers', servers),

  channels: (serverId: string): Promise<Channel[] | null> => readList(`channels:${serverId}`),
  putChannels: (serverId: string, channels: Channel[]): Promise<void> =>
    writeList(`channels:${serverId}`, channels),

  directs: (): Promise<DirectChannel[] | null> => readList('directs'),
  putDirects: (directs: DirectChannel[]): Promise<void> => writeList('directs', directs),

  /**
   * Where each channel had been read up to. Cached because the unread line is
   * drawn from it the moment a channel opens, and on a cold start that is well
   * before the network has answered - which is how a restart used to lose the
   * line entirely.
   */
  readMarkers: (): Promise<Record<string, string | null> | null> => readList('readMarkers'),
  putReadMarkers: (markers: Record<string, string | null>): Promise<void> =>
    writeList('readMarkers', markers),

  // --- Messages -------------------------------------------------------------

  /** The newest page of a channel, oldest first, as the screen wants it. */
  async messages(channelId: string, limit = 50): Promise<Message[]> {
    const db = await database();
    if (!db) return [];

    const index = db.transaction(MESSAGES, 'readonly').objectStore(MESSAGES).index('channel');
    const range = IDBKeyRange.bound([channelId, ''], [channelId, '￿']);
    const newest: Message[] = [];

    await new Promise<void>((resolve) => {
      // Backwards from the newest, because "the last fifty" is the question -
      // walking forwards would read the whole channel to answer it.
      const cursor = index.openCursor(range, 'prev');
      cursor.onsuccess = () => {
        const at = cursor.result;
        if (!at || newest.length >= limit) {
          resolve();
          return;
        }
        newest.push(at.value as Message);
        at.continue();
      };
      cursor.onerror = () => resolve();
    });

    return newest.reverse();
  },

  /**
   * Keeps the last few hundred per channel. History fetched once should not
   * need fetching again, and a few thousand rows of ciphertext is not a size
   * worth worrying about - but a channel read back to its first message is,
   * so the oldest are dropped rather than kept forever.
   */
  /**
   * Forgets specific messages, by id.
   *
   * For the two deletions that leave no tombstone - a one-time message that
   * was opened, and one whose disappearing window closed. An ordinary delete
   * does not come through here: its tombstone is written over the old row by
   * `putMessages`, which is what makes the channel say "this was here and is
   * gone" after a restart.
   */
  async forgetMessages(messageIds: string[]): Promise<void> {
    if (messageIds.length === 0) return;
    const db = await database();
    if (!db) return;

    const transaction = db.transaction(MESSAGES, 'readwrite');
    const store = transaction.objectStore(MESSAGES);
    for (const id of messageIds) store.delete(id);
    await done(transaction);
  },

  async putMessages(messages: Message[]): Promise<void> {
    if (messages.length === 0) return;
    const db = await database();
    if (!db) return;

    const transaction = db.transaction(MESSAGES, 'readwrite');
    const store = transaction.objectStore(MESSAGES);
    for (const message of messages) store.put(message);
    await done(transaction);

    for (const channelId of new Set(messages.map((message) => message.channelId))) {
      await prune(channelId);
    }
  },
};

/** Drops everything past the ceiling in one channel, oldest first. */
async function prune(channelId: string): Promise<void> {
  const db = await database();
  if (!db) return;

  const transaction = db.transaction(MESSAGES, 'readwrite');
  const index = transaction.objectStore(MESSAGES).index('channel');
  const range = IDBKeyRange.bound([channelId, ''], [channelId, '￿']);
  let seen = 0;

  await new Promise<void>((resolve) => {
    const cursor = index.openCursor(range, 'prev');
    cursor.onsuccess = () => {
      const at = cursor.result;
      if (!at) {
        resolve();
        return;
      }
      seen += 1;
      if (seen > MESSAGES_PER_CHANNEL) at.delete();
      at.continue();
    };
    cursor.onerror = () => resolve();
  });

  await done(transaction);
}

/**
 * Self-check for the recovery policy: `tsx src/services/call-recovery.check.ts`.
 *
 * The numbers are a policy, not arithmetic, so what is checked here is the
 * relationships between them - the ones that are silently load-bearing and that
 * a well-meaning tweak to one constant would break:
 *
 *  - every attempt has to fit inside the deadline, or the attempt budget is a
 *    fiction and the deadline is the only thing that ever fires;
 *  - one side and only one side restarts, or two renegotiations race;
 *  - a call outlives one of its links, or a blip on one tile ends the call.
 *
 * It also pins the Android policy in `CallRecovery.kt`. The two clients must
 * agree: a phone that waits four seconds and a laptop that waits one restart on
 * top of each other.
 */
import assert from 'node:assert/strict';
import {
  DEADLINE_MS,
  GRACE_MS,
  MAX_ATTEMPTS,
  SIGNALLING_DEADLINE_MS,
  backoffMs,
  restarts,
  signallingBackoffMs,
  spent,
} from './call-recovery';

// --- the numbers Android holds, which this must not drift from ---

assert.equal(GRACE_MS, 4_000, 'CallRecovery.kt says 4s; both clients must wait the same');
assert.equal(MAX_ATTEMPTS, 4);
assert.equal(DEADLINE_MS, 30_000);
assert.equal(SIGNALLING_DEADLINE_MS, 45_000);
assert.deepEqual([1, 2, 3, 4, 5].map(backoffMs), [0, 2_000, 4_000, 8_000, 8_000]);

// --- one side restarts, and it is the impolite one ---

assert.equal(restarts(false), true, 'the impolite side offers, so it is the one that restarts');
assert.equal(restarts(true), false, 'a polite restart is an offer the far end discards as glare');

// --- the attempt budget actually fits inside the deadline ---

// Each pass through the loop is a backoff, a restart, and a grace period spent
// waiting to see whether it took.
const budget = Array.from({ length: MAX_ATTEMPTS }, (_, index) => backoffMs(index + 1) + GRACE_MS)
  .reduce((total, cost) => total + cost, 0);
assert.ok(
  budget <= DEADLINE_MS,
  `all ${MAX_ATTEMPTS} attempts must fit in the deadline: ${budget}ms of ${DEADLINE_MS}ms`,
);

// --- giving up needs either bound, not both ---

assert.equal(spent(0, 0), false, 'a link that just went down is not spent');
assert.equal(spent(MAX_ATTEMPTS - 1, DEADLINE_MS - 1), false, 'neither bound reached');
assert.equal(spent(MAX_ATTEMPTS, 0), true, 'out of attempts, however quickly');
assert.equal(spent(0, DEADLINE_MS), true, 'out of time, even having never managed an attempt');

// --- a call outlives one of its links ---

assert.ok(
  SIGNALLING_DEADLINE_MS > DEADLINE_MS,
  'the socket reconnects itself; one dead link must not be the end of the call',
);

// --- signalling retries race the gateway's seat-holding window ---

assert.equal(signallingBackoffMs(1), 0, 'the first retry races the held seat, so it is immediate');
assert.deepEqual([2, 3, 4, 5, 9].map(signallingBackoffMs), [1_000, 2_000, 4_000, 8_000, 8_000]);
assert.ok(
  signallingBackoffMs(99) < SIGNALLING_DEADLINE_MS,
  'a single wait must never exceed the whole call deadline',
);

console.log('call-recovery.check.ts: ok');

/**
 * Self-check for the call statistics: `tsx src/services/call-stats.check.ts`.
 *
 * Everything here is arithmetic over counters, and counters have three edges
 * that all look like a working call until somebody reads the screen: the first
 * sample has nothing to compare against, a rebuilt connection resets the totals
 * to zero, and a division by an elapsed time of zero produces Infinity.
 */
import assert from 'node:assert/strict';
import {
  MIN_HEALTHY_ERLE_DB,
  echoAdvice,
  echoCancellerFailing,
} from './call-stats';
import {
  formatCallDuration,
  healthWarning,
  kbpsBetween,
  lossPercent,
  notBeingHeard,
  toStats,
  type LinkSample,
  type LinkStats,
} from './call-stats';

// 128 kilobytes in two seconds is 512 kbps.
assert.equal(kbpsBetween(128_000, 0, 2_000), 512);
// Nothing moved.
assert.equal(kbpsBetween(1_000, 1_000, 1_000), 0);
// No time between the samples: no answer, rather than Infinity on screen.
assert.equal(kbpsBetween(1_000, 0, 0), null);
// A counter that went backwards is a connection rebuilt underneath us.
assert.equal(kbpsBetween(10, 5_000, 1_000), null);

assert.equal(lossPercent(5, 95), 5);
assert.equal(lossPercent(0, 100), 0);
// Nothing has arrived yet, so the loss rate is not 100% - it is unknown.
assert.equal(lossPercent(0, 0), null);
// One decimal place, so a fifth of a percent does not read as zero.
assert.equal(lossPercent(1, 799), 0.1);

const sample = (patch: Partial<LinkSample>): LinkSample => ({
  at: 0,
  echoReturnLossEnhancementDb: null,
  inboundAudioBytes: 0,
  inboundVideoBytes: 0,
  outboundAudioBytes: 0,
  outboundVideoBytes: 0,
  packetsLost: 0,
  packetsReceived: 0,
  roundTripSeconds: null,
  frameWidth: null,
  frameHeight: null,
  framesPerSecond: null,
  sendWidth: null,
  sendHeight: null,
  sendLimitedBy: null,
  connected: true,
  transport: null,
  ...patch,
});

// The first sample of a call: rates are unknown rather than zero, and the peer
// is assumed to be hearing us until there is evidence otherwise. Reporting "you
// are not being heard" for the first second of every call would train everyone
// to ignore it.
const first = toStats('p1', 'Ann', sample({ at: 1_000 }), undefined);
assert.equal(first.downKbps, null);
assert.equal(first.upKbps, null);
assert.equal(first.sendingAudio, true);

// A second sample a second later, with audio and video both flowing.
const second = toStats(
  'p1',
  'Ann',
  sample({
    at: 2_000,
    inboundAudioBytes: 4_000,
    inboundVideoBytes: 121_000,
    outboundAudioBytes: 4_000,
    packetsLost: 2,
    packetsReceived: 198,
    roundTripSeconds: 0.042,
    frameWidth: 1920,
    frameHeight: 1080,
    framesPerSecond: 29.6,
  }),
  sample({ at: 1_000 }),
);
assert.equal(second.downKbps, 1_000);
assert.equal(second.upKbps, 32);
assert.equal(second.lossPercent, 1);
assert.equal(second.roundTripMs, 42);
assert.equal(second.framesPerSecond, 30);
assert.equal(second.sendingAudio, true);

// Nothing is holding the send side down, which is not the same as "there is no
// send side": both read as null and the panel shows neither.
assert.equal(second.sendLimitedBy, null);

// A share being shrunk before it leaves. The picture on the wire is a quarter
// of the one being captured, and the reason is the whole point of the reading.
const throttled = toStats(
  'p1',
  'Ann',
  sample({ at: 2_000, sendWidth: 960, sendHeight: 540, sendLimitedBy: 'bandwidth' }),
  sample({ at: 1_000 }),
);
assert.equal(throttled.sendWidth, 960);
assert.equal(throttled.sendHeight, 540);
assert.equal(throttled.sendLimitedBy, 'bandwidth');

// Outbound audio that has not moved between two samples is a microphone that
// is not on the wire, whatever the level meter says.
const silent = toStats(
  'p1',
  'Ann',
  sample({ at: 3_000, outboundAudioBytes: 4_000 }),
  sample({ at: 2_000, outboundAudioBytes: 4_000 }),
);
assert.equal(silent.sendingAudio, false);

const quiet: LinkStats[] = [silent];
const heard: LinkStats[] = [second];

// The warning needs three things at once: an intent to send, somebody to send
// to, and several samples of nothing. One quiet sample is a scheduling hiccup.
assert.equal(notBeingHeard(true, quiet, 3), true);
assert.equal(notBeingHeard(true, quiet, 1), false);
assert.equal(notBeingHeard(false, quiet, 9), false, 'a muted microphone is not a fault');
assert.equal(notBeingHeard(true, heard, 9), false);
assert.equal(notBeingHeard(true, [], 9), false, 'nobody to be heard by is not a fault');
// One peer hearing us and another not is that peer's problem, not the
// microphone's - and the microphone is what this warning is about.
assert.equal(notBeingHeard(true, [silent, second], 9), false);
// A link with no path carries nothing whatever the microphone does, so it is
// no evidence about the microphone. This is the pair of contradictory notices:
// "could not be reached" and "nobody can hear you, try another input" on screen
// at once, where only the first is true and only the second looks fixable.
const unreachable: LinkStats[] = [{ ...silent, connected: false }];
assert.equal(notBeingHeard(true, unreachable, 9), false);
// One live link that is not hearing us still fires, even next to a dead one:
// the dead link is ignored, not counted as a vote either way.
assert.equal(notBeingHeard(true, [...unreachable, silent], 9), true);
// ... and a live link that is hearing us still settles it.
assert.equal(notBeingHeard(true, [...unreachable, second], 9), false);

// Health warnings fire where a person would notice, and not before.
assert.equal(healthWarning([second]), null);
const lossy = { ...second, lossPercent: 12 };
assert.match(healthWarning([lossy]) ?? '', /12%/);
assert.match(healthWarning([lossy]) ?? '', /Ann/);
const slow = { ...second, roundTripMs: 420 };
assert.match(healthWarning([slow]) ?? '', /420 ms/);
// Loss is the louder complaint when both are true: it is what breaks speech.
assert.match(healthWarning([{ ...lossy, roundTripMs: 420 }]) ?? '', /%/);

// --- The call clock --------------------------------------------------------

assert.equal(formatCallDuration(0), '00:00');
assert.equal(formatCallDuration(9), '00:09');
assert.equal(formatCallDuration(59), '00:59');
// The minute rolls over, which is the boundary a modulo gets wrong.
assert.equal(formatCallDuration(60), '01:00');
assert.equal(formatCallDuration(61), '01:01');
assert.equal(formatCallDuration(599), '09:59');
assert.equal(formatCallDuration(3599), '59:59');
// The hour appears and the minutes keep their padding; the hour does not get
// any, because "01:02:03" on a two-hour call is a leading zero for nothing.
assert.equal(formatCallDuration(3600), '1:00:00');
assert.equal(formatCallDuration(3661), '1:01:01');
assert.equal(formatCallDuration(36000), '10:00:00');
// A fraction of a second is not a second yet.
assert.equal(formatCallDuration(0.9), '00:00');
assert.equal(formatCallDuration(59.99), '00:59');
// A clock that ran backwards, and a number that is not one. Both read as zero
// rather than as "-1:-1" on somebody's screen.
assert.equal(formatCallDuration(-5), '00:00');
assert.equal(formatCallDuration(Number.NaN), '00:00');

console.log('call-stats check ok');


// --- Is echo cancellation actually working? --------------------------------
//
// The one reading that separates "there is echo" from "the canceller is
// subtracting the wrong signal". Before this existed the only way to tell was
// to ask somebody on the call whether they could hear themselves.

// A converged canceller removes 20-40 dB; single digits mean it is running and
// subtracting the wrong signal, which is what a non-default output device does.
assert.equal(echoCancellerFailing(true, 30), false);
assert.equal(echoCancellerFailing(true, 0), true);
assert.equal(echoCancellerFailing(true, MIN_HEALTHY_ERLE_DB - 0.1), true);
assert.equal(echoCancellerFailing(true, MIN_HEALTHY_ERLE_DB), false);

// Echo cancellation switched off is a choice, not a fault - hi-fi mode turns it
// off deliberately - so it must never raise the warning.
assert.equal(echoCancellerFailing(false, 0), false);

// A browser that does not report the statistic must not produce a permanent
// warning on a machine that has no echo at all.
assert.equal(echoCancellerFailing(true, null), false);

// The advice names the output device when that is the likely cause, because
// "switch your speakers back" is the only version of this a person can act on.
assert.match(echoAdvice(true), /output device/i);
assert.match(echoAdvice(false), /[Hh]eadphones/);

/**
 * What the call is actually doing, in numbers.
 *
 * Until now nothing measured anything: "it looks bad" and "the link is bad"
 * were the same sentence, and the only way to tell them apart was to open
 * `chrome://webrtc-internals`, which is not a thing to ask of somebody in a
 * meeting. Worse, the most common failure in any voice app - a microphone that
 * is sending nothing at all while its owner talks happily into it - is silent
 * on both sides.
 *
 * The arithmetic is here and pure; the sampling is in `mesh.ts`, which is the
 * only thing holding a peer connection to ask.
 */

import type { CallTransport } from '@betweenus/shared-types';

/**
 * Why the picture leaving this machine is smaller or slower than it was asked
 * to be, straight from `qualityLimitationReason` on the outbound stream.
 *
 * The one number that separates "the link cannot carry it" from "this machine
 * cannot encode it" from "nothing is holding it back and it still looks like
 * that". Without it a soft share is a guess, and the guess is usually wrong:
 * `bandwidth` and `cpu` want opposite fixes.
 */
export type QualityLimit = 'bandwidth' | 'cpu' | 'other';

/** One `getStats` sample of one peer connection, already reduced to numbers. */
export interface LinkSample {
  at: number;
  /** Bytes this peer has sent us, ever, per kind. */
  inboundAudioBytes: number;
  inboundVideoBytes: number;
  /** Bytes we have sent them, ever. */
  outboundAudioBytes: number;
  outboundVideoBytes: number;
  /** Packets they sent that never arrived, and the ones that did. */
  packetsLost: number;
  packetsReceived: number;
  /** Round trip on the selected candidate pair, in seconds, when known. */
  roundTripSeconds: number | null;
  /** The screen or camera as it arrives, when one does. */
  frameWidth: number | null;
  frameHeight: number | null;
  framesPerSecond: number | null;
  /** The same, for the biggest picture leaving this machine. */
  sendWidth: number | null;
  sendHeight: number | null;
  sendLimitedBy: QualityLimit | null;
  /**
   * Whether this link has a path at all: ICE settled and DTLS came up.
   *
   * Distinct from every byte counter above, which cannot tell "connected and
   * saying nothing" from "never connected" - both read as a still counter.
   */
  connected: boolean;
  /**
   * Whether the media went straight to the other machine or through a relay.
   *
   * Null until ICE has settled on a pair. It costs an operator nothing when it
   * is direct and relay bandwidth when it is not, and there is no way to see
   * which from anywhere else - the server is not in the path to look.
   */
  transport: CallTransport | null;
  /**
   * How many dB of echo the canceller is actually removing, from the local
   * audio source. Null when the browser does not report it.
   *
   * This is the only number that answers "is echo cancellation working", and
   * without it echo is diagnosed by asking somebody on the call whether they
   * can hear themselves - which is why it went unfixed for so long. It is a
   * property of this machine rather than of a link, but it is read here because
   * this is where `getStats` is already being called.
   */
  echoReturnLossEnhancementDb: number | null;
}

/** What a person is shown about one other person in the call. */
export interface LinkStats {
  peerId: string;
  name: string;
  /** Null until there are two samples to compare. */
  downKbps: number | null;
  upKbps: number | null;
  /** Percentage of their packets that never arrived, over the whole call. */
  lossPercent: number | null;
  roundTripMs: number | null;
  frameWidth: number | null;
  frameHeight: number | null;
  framesPerSecond: number | null;
  /** What is leaving this machine, and what is holding it down. */
  sendWidth: number | null;
  sendHeight: number | null;
  sendLimitedBy: QualityLimit | null;
  /** False when we are sending them no audio at all - see `notBeingHeard`. */
  sendingAudio: boolean;
  /** False while this link has no path at all - see `notBeingHeard`. */
  connected: boolean;
}

/**
 * Kilobits per second between two samples.
 *
 * Null rather than zero when there is nothing to compare, because "no reading
 * yet" and "nothing is flowing" are the two answers this is asked for and
 * showing 0 kbps for the first second of every call is how a healthy call gets
 * reported as broken.
 */
export function kbpsBetween(
  bytesNow: number,
  bytesBefore: number,
  msElapsed: number,
): number | null {
  if (msElapsed <= 0) return null;
  const bytes = bytesNow - bytesBefore;
  // A counter that went backwards is a connection that was rebuilt underneath
  // us; the next sample will be right and this one is not worth guessing at.
  if (bytes < 0) return null;
  return Math.round((bytes * 8) / msElapsed);
}

/** Share of their packets that never arrived, as a percentage. */
export function lossPercent(lost: number, received: number): number | null {
  const total = lost + received;
  if (total <= 0) return null;
  return Math.round((lost / total) * 1000) / 10;
}

/**
 * Below this many dB of enhancement, the canceller is not doing its job.
 *
 * A converged AEC3 removes 20-40 dB. Single digits mean it is running but
 * cancelling against the wrong reference, which is the signature of audio being
 * played to a device other than the one the canceller is listening to. Zero or
 * near it means it is not running at all.
 *
 * Six is deliberately generous: the number swings while the canceller converges
 * at the top of a call, and a warning that fires on every call start is a
 * warning people learn to ignore.
 */
export const MIN_HEALTHY_ERLE_DB = 6;

/**
 * Whether the far end is hearing themselves come back.
 *
 * Two conditions, and both matter. Echo cancellation being *off* is not a
 * fault - hi-fi mode turns it off deliberately, because it chews holes in
 * anything that correlates with what the speakers are playing - so it is only
 * worth reporting when the setting says it should be working. And a null
 * reading is not a failure: plenty of builds do not report the statistic, and
 * warning on its absence would put a permanent notice on machines with no echo.
 */
export function echoCancellerFailing(
  echoCancellationEnabled: boolean,
  erleDb: number | null,
): boolean {
  if (!echoCancellationEnabled) return false;
  if (erleDb === null) return false;
  return erleDb < MIN_HEALTHY_ERLE_DB;
}

/**
 * Why the canceller is failing, when it is, in a sentence somebody can act on.
 *
 * The output device is the whole reason this exists. Chromium builds its echo
 * reference from the *default* render device, so playing a call to a device
 * chosen in this app's own settings hands the canceller the wrong signal to
 * subtract - and the symptom is a call that echoes only for people who changed
 * their speakers, which is indistinguishable from bad luck until this is
 * measured.
 */
export function echoAdvice(usingNonDefaultOutput: boolean): string {
  return usingNonDefaultOutput
    ? 'Echo cancellation is not working on this output device. Switch the call output back to System default, or change your default device in Windows sound settings.'
    : 'Echo cancellation is not working - other people may hear themselves. Headphones will stop it.';
}

/**
 * "Your microphone is not being heard."
 *
 * The one warning worth interrupting somebody for, and the reason this file
 * exists. It is true when this client believes it is sending audio - the mic is
 * on, the key is down if push to talk is on - and the bytes on the wire say
 * otherwise for long enough that it cannot be a pause.
 *
 * Deliberately not derived from "am I speaking": somebody silent for ten
 * seconds is still being heard, and a microphone that is muted at the OS level
 * sends comfort noise rather than nothing at all. What this catches is the
 * capture that failed, the device that was unplugged, and the sender that was
 * never attached.
 *
 * And deliberately only over links that have a path. A connection that never
 * came up carries nothing in either direction, so the best microphone in the
 * world reads as silent on it - which is how "nobody can hear you, try another
 * input" came to be the message on screen during a call that had simply failed
 * to connect, sitting directly under the mesh's own "could not be reached".
 * That is the worst kind of wrong answer: prominent, actionable, and impossible
 * to act on successfully, because no input device on the machine is the
 * problem. The two notices contradicted each other and the wrong one was the
 * one with a dropdown, so it was the one people spent the call on.
 */
export function notBeingHeard(
  intendsToSend: boolean,
  stats: LinkStats[],
  quietSamples: number,
  requiredSamples = 3,
): boolean {
  if (!intendsToSend) return false;
  if (quietSamples < requiredSamples) return false;
  // Nobody to be heard by: an empty call, or one where no link has a path.
  // Neither is evidence about the microphone.
  const reachable = stats.filter((link) => link.connected);
  if (reachable.length === 0) return false;
  return reachable.every((link) => !link.sendingAudio);
}

/**
 * A short sentence about the link, or null when there is nothing worth saying.
 *
 * One threshold per problem, chosen where a person would notice: 5% loss is
 * where speech starts breaking up, and 300 ms round trip is where a
 * conversation starts talking over itself.
 */
export function healthWarning(stats: LinkStats[]): string | null {
  const lossy = stats.filter((link) => (link.lossPercent ?? 0) >= 5);
  if (lossy.length > 0) {
    const worst = Math.max(...lossy.map((link) => link.lossPercent ?? 0));
    return lossy.length === 1
      ? `Losing ${worst}% of the packets from ${lossy[0]!.name}`
      : `Losing packets from ${lossy.length} people - up to ${worst}%`;
  }

  const slow = stats.filter((link) => (link.roundTripMs ?? 0) >= 300);
  if (slow.length > 0) {
    const worst = Math.max(...slow.map((link) => link.roundTripMs ?? 0));
    return `Round trip of ${worst} ms - expect to talk over each other`;
  }

  return null;
}

/** Turns two samples into what the panel shows. */
export function toStats(
  peerId: string,
  name: string,
  now: LinkSample,
  before: LinkSample | undefined,
): LinkStats {
  const elapsed = before ? now.at - before.at : 0;

  return {
    peerId,
    name,
    downKbps: before
      ? kbpsBetween(
          now.inboundAudioBytes + now.inboundVideoBytes,
          before.inboundAudioBytes + before.inboundVideoBytes,
          elapsed,
        )
      : null,
    upKbps: before
      ? kbpsBetween(
          now.outboundAudioBytes + now.outboundVideoBytes,
          before.outboundAudioBytes + before.outboundVideoBytes,
          elapsed,
        )
      : null,
    lossPercent: lossPercent(now.packetsLost, now.packetsReceived),
    roundTripMs:
      now.roundTripSeconds === null ? null : Math.round(now.roundTripSeconds * 1000),
    frameWidth: now.frameWidth,
    frameHeight: now.frameHeight,
    framesPerSecond: now.framesPerSecond === null ? null : Math.round(now.framesPerSecond),
    sendWidth: now.sendWidth,
    sendHeight: now.sendHeight,
    sendLimitedBy: now.sendLimitedBy,
    // Any movement at all counts. Opus sends a few hundred bytes a second even
    // through silence, so a sender that is attached and working is never still.
    sendingAudio: before ? now.outboundAudioBytes > before.outboundAudioBytes : true,
    connected: now.connected,
  };
}

/**
 * How long the call has been running, as a clock.
 *
 * The phone has had this since the beginning and neither of the other two
 * clients did - not because anybody chose that, but because on Android it is
 * free: an ongoing-call notification with `setUsesChronometer` is counted by
 * the system. A desktop window and a browser tab have no notification to hang
 * it on, so the number has to be drawn.
 *
 * `mm:ss` until an hour, `h:mm:ss` after it. Never `00:` hours, because a
 * leading pair of zeroes on every call is two characters that only ever say
 * "this is not a long call".
 */
export function formatCallDuration(seconds: number): string {
  // A clock that has not started, or one whose start is somehow in the future -
  // a machine's clock moving backwards is a thing that happens - reads as zero
  // rather than as a negative duration.
  const total = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total % 60;

  const mmss = `${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  return hours > 0 ? `${hours}:${mmss}` : mmss;
}

/**
 * Run with `tsx src/services/call-tones.check.ts`.
 *
 * Only the roster arithmetic is checked: the synthesis needs an AudioContext
 * and the only assertion worth making about it is whether it sounds right,
 * which no test makes. What can be wrong here silently is the set difference -
 * a roster arrives as a whole list, so "somebody joined" is not an event.
 */
import assert from 'node:assert/strict';
import { rosterChange } from './call-tones';

// Nothing happened.
assert.deepEqual(rosterChange(['a'], ['a']), { joined: false, left: false });

// One each way.
assert.deepEqual(rosterChange(['a'], ['a', 'b']), { joined: true, left: false });
assert.deepEqual(rosterChange(['a', 'b'], ['a']), { joined: false, left: true });

// Four people arriving at once is an arrival, not four of them.
assert.deepEqual(rosterChange([], ['a', 'b', 'c', 'd']), { joined: true, left: false });

// One in, one out, in the same roster: both are true, and both are worth
// hearing - the alternative is a swap that sounds like nothing changed.
assert.deepEqual(rosterChange(['a'], ['b']), { joined: true, left: true });

// Order is not a change. A roster is a set; the server does not promise one.
assert.deepEqual(rosterChange(['a', 'b'], ['b', 'a']), { joined: false, left: false });

console.log('call-tones.check.ts ok');

/**
 * The two notes that say somebody arrived, and the two that say they left.
 *
 * A voice channel with no sound of its own is one where you have to be looking
 * at the tile list to know who is in it - which is exactly when nobody is
 * looking at it, because the whole point of a voice channel is that the window
 * is behind something else. Discord answers this with a short rising chirp on
 * join and a falling one on leave, and the direction is the entire message: you
 * do not have to learn what the sound means to know which way it went.
 *
 * Synthesised rather than shipped. Two sine notes with a soft envelope is what
 * the file would have contained, an oscillator is ten lines, and this way there
 * is no asset to bundle, no fetch to fail, and nothing that can go missing from
 * an Electron package. It also means the tone can be built at the volume and
 * pitch chosen here rather than at whatever a downloaded file was mastered to.
 *
 * The envelope matters more than the notes. A sine that starts and stops
 * abruptly is a click at each end - the discontinuity is a broadband transient,
 * which is a worse sound than the tone itself - so every note fades in and out
 * over a few milliseconds.
 */

/** What happened, and therefore which way the two notes go. */
export type CallTone = 'join' | 'leave';

/**
 * A perfect fourth, up or down. Not a chord and not a tune: two notes far
 * enough apart to be told apart through a game, a film, or a laptop speaker,
 * and low enough not to be shrill on a headset.
 */
const NOTES: Record<CallTone, [number, number]> = {
  // Up: somebody is here.
  join: [523.25, 698.46],
  // Down: somebody is gone. The same two notes the other way round, so the pair
  // is recognisably one pair rather than two unrelated sounds.
  leave: [698.46, 523.25],
};

/** Seconds. Long enough to have a pitch, short enough not to be a ringtone. */
const NOTE_SECONDS = 0.09;
/** The fade at each end of a note, which is what stops it clicking. */
const FADE_SECONDS = 0.012;
/** Quiet on purpose: this plays over a conversation, not instead of one. */
const PEAK_GAIN = 0.14;

/**
 * One context for the life of the window, created on the first tone rather than
 * at import. A browser refuses to start an AudioContext before the page has been
 * interacted with, and one created too early is stuck suspended.
 */
let context: AudioContext | null = null;

function audio(): AudioContext | null {
  if (typeof AudioContext === 'undefined') return null;
  context ??= new AudioContext();
  // Suspended is the normal state after a tab has been in the background.
  void context.resume().catch(() => undefined);
  return context;
}

/**
 * Sends the tones to a chosen output device.
 *
 * Called when the setting changes, and ignored where the runtime has no
 * `setSinkId` on a context - in which case the tone plays on the system default,
 * which is the same place it played before this existed.
 */
export function setToneOutput(deviceId: string | null): void {
  const target = context as (AudioContext & { setSinkId?: (id: string) => Promise<void> }) | null;
  if (!target?.setSinkId) return;
  void target.setSinkId(deviceId ?? '').catch(() => undefined);
}

/**
 * Plays one of the two tones. Never throws and never awaits: a call is not
 * worth failing over a sound, and nothing downstream cares when it finishes.
 */
export function playCallTone(tone: CallTone): void {
  const ctx = audio();
  if (!ctx) return;

  try {
    const [first, second] = NOTES[tone];
    // The second note starts where the first ends - overlapping them would beat
    // against each other, and a gap would make it two sounds rather than one.
    note(ctx, first, ctx.currentTime);
    note(ctx, second, ctx.currentTime + NOTE_SECONDS);
  } catch {
    // A context that was closed, a device that went away mid-call: silence is
    // the correct failure here.
  }
}

// --- The ringtone -----------------------------------------------------------

/**
 * A ring is a different sound from a tone, and not because it is louder.
 *
 * The join and leave tones are told after the fact: they say something has
 * happened, once, and then stop. A ring is a question - somebody is waiting
 * for an answer - so it has to repeat until it is answered or given up on, and
 * it has to be audible from another room, which is the whole reason anybody
 * rings anybody.
 *
 * The same two-note shape as a join, an octave of separation, three times per
 * burst, and a burst every few seconds. It stays synthesised for the same
 * reasons the tones are: nothing to bundle, nothing to fetch, nothing to go
 * missing from an Electron package.
 */
const RING_NOTES = [880, 1174.66] as const;
/** Seconds between the start of one burst and the next. A telephone's cadence. */
const RING_PERIOD_SECONDS = 3;
const RING_NOTE_SECONDS = 0.18;
/** Louder than a join tone. This one has to carry across a room. */
const RING_GAIN = 0.3;

let ringTimer: number | null = null;

/**
 * Starts ringing, and keeps ringing until [stopRinging].
 *
 * Idempotent: a second ring arriving while one is already sounding is one
 * ringtone, not two overlapping ones an octave apart.
 */
export function startRinging(): void {
  if (ringTimer !== null) return;

  const burst = (): void => {
    const ctx = audio();
    if (!ctx) return;
    try {
      // Three rises, then silence until the next burst. A continuous tone is
      // an alarm; the gap is what makes this a telephone.
      for (let index = 0; index < 3; index += 1) {
        const at = ctx.currentTime + index * RING_NOTE_SECONDS * 2;
        note(ctx, RING_NOTES[0], at, RING_NOTE_SECONDS, RING_GAIN);
        note(ctx, RING_NOTES[1], at + RING_NOTE_SECONDS, RING_NOTE_SECONDS, RING_GAIN);
      }
    } catch {
      // A closed context or a device that went away: silence is the correct
      // failure, exactly as it is for the tones.
    }
  };

  burst();
  ringTimer = window.setInterval(burst, RING_PERIOD_SECONDS * 1000);
}

/** Answered, declined, or given up on. Safe to call when nothing is ringing. */
export function stopRinging(): void {
  if (ringTimer !== null) window.clearInterval(ringTimer);
  ringTimer = null;
}

function note(
  ctx: AudioContext,
  frequency: number,
  at: number,
  seconds: number = NOTE_SECONDS,
  peak: number = PEAK_GAIN,
): void {
  const oscillator = ctx.createOscillator();
  const gain = ctx.createGain();

  oscillator.type = 'sine';
  oscillator.frequency.setValueAtTime(frequency, at);

  // Ramped rather than set: see the note about clicks at the top.
  gain.gain.setValueAtTime(0, at);
  gain.gain.linearRampToValueAtTime(peak, at + FADE_SECONDS);
  gain.gain.setValueAtTime(peak, at + seconds - FADE_SECONDS);
  gain.gain.linearRampToValueAtTime(0, at + seconds);

  oscillator.connect(gain).connect(ctx.destination);
  oscillator.start(at);
  oscillator.stop(at + seconds);
  // Nodes are one-shot; letting them go is what keeps a long call from
  // accumulating one oscillator per arrival.
  oscillator.onended = () => {
    oscillator.disconnect();
    gain.disconnect();
  };
}

/**
 * Who arrived and who left, between two rosters.
 *
 * Pulled out of the store because it is the part that can be wrong in a way
 * nobody hears until there are three people in a call: a roster is a whole list
 * on every change, so "somebody joined" is a set difference and not an event.
 * One tone per change, not one per person - four people arriving together is an
 * arrival, not a fanfare.
 */
export function rosterChange(
  before: readonly string[],
  after: readonly string[],
): { joined: boolean; left: boolean } {
  const was = new Set(before);
  const is = new Set(after);
  return {
    joined: after.some((id) => !was.has(id)),
    left: before.some((id) => !is.has(id)),
  };
}

/**
 * Telling the server which conversation is in front of this person.
 *
 * It exists for one thing: so a phone is not woken for a message its owner is
 * reading on this screen. `notification-service` asks presence-service who has
 * a channel focused before it fans a push out, and drops them - see
 * `docs/docs/architecture/push-suppression.md`.
 *
 * "Focused" is deliberately strict. A channel is reported only while it is the
 * open one *and* this window has the operating system's focus. A desktop left
 * open on #general behind a browser is not somebody reading #general, and
 * treating it as one would silently swallow their notifications for the rest of
 * the day - which is a far worse failure than one redundant buzz.
 *
 * The same module serves the browser build, because it is the same app. A tab
 * gets `visibilitychange` as well, which is the closer thing a tab has to being
 * looked at.
 */
import { useChatStore } from '../stores/chat';
import { presenceSocket } from './socket';

/**
 * Well inside presence-service's 90-second staleness window, so a focus that
 * is still true is never allowed to age out of Redis. The socket's own
 * heartbeat refreshes it too; this covers a client that reconnected onto a
 * different presence instance.
 */
const HEARTBEAT_MS = 60_000;

export function startChannelFocus(): () => void {
  /** What the server has been told, so nothing is said twice. */
  let reported: string | null = null;
  let timer: ReturnType<typeof setInterval> | null = null;

  const focused = (): boolean => document.hasFocus() && !document.hidden;

  const current = (): string | null => {
    if (!focused()) return null;
    return useChatStore.getState().activeChannelId;
  };

  const apply = (): void => {
    const next = current();
    if (next === reported) return;

    // Blur the old one explicitly rather than letting it expire. Ninety
    // seconds of a stale focus is ninety seconds of missed notifications for a
    // channel this window has already left.
    if (reported) presenceSocket.send({ type: 'channel.blur', channelId: reported });
    if (next) presenceSocket.send({ type: 'channel.focus', channelId: next });
    reported = next;
  };

  const unsubscribe = useChatStore.subscribe(apply);
  window.addEventListener('focus', apply);
  window.addEventListener('blur', apply);
  document.addEventListener('visibilitychange', apply);

  timer = setInterval(() => {
    // Re-sent rather than skipped when nothing has changed: this is the
    // heartbeat, and its whole job is to say the same thing again.
    if (reported) presenceSocket.send({ type: 'channel.focus', channelId: reported });
  }, HEARTBEAT_MS);

  apply();

  return () => {
    if (timer) clearInterval(timer);
    unsubscribe();
    window.removeEventListener('focus', apply);
    window.removeEventListener('blur', apply);
    document.removeEventListener('visibilitychange', apply);
    if (reported) presenceSocket.send({ type: 'channel.blur', channelId: reported });
    reported = null;
  };
}

