/**
 * Where somebody goes to get the app.
 *
 * One constant, because two screens want it for opposite reasons and both have
 * to point at the same place: the sidebar offers it to anybody running in a
 * browser, and the one-time viewer sends people there when a browser cannot do
 * what the message needs.
 *
 * The repository is the same one the desktop and Android updaters already
 * check - `electron/updates.ts` and `Releases.kt` - but it is spelled out here
 * rather than imported from either. The updater constants live in the Electron
 * main process and in Kotlin; neither is reachable from the browser bundle,
 * which is precisely the build that needs this link.
 */
const REPOSITORY = 'aiyu-ayaan/BetweenUs';

/**
 * The releases page, not a file.
 *
 * A direct link to an installer would have to know the platform, the
 * architecture and the current version, and would rot the moment a release is
 * cut. The releases page shows every build for every platform and is the one
 * URL that is still right in a year.
 */
export const DOWNLOAD_URL = `https://github.com/${REPOSITORY}/releases/latest`;

/**
 * What to call the download for whoever is looking at it.
 *
 * The platform is a guess from the user agent and is only ever a label - the
 * link goes to the same page whatever it says, so a wrong guess costs a word
 * and never a broken download. `userAgentData` where a browser has it, the
 * user-agent string where it does not.
 */
export function downloadLabel(agent: string = navigator.userAgent): string {
  const platform = agent.toLowerCase();
  if (/android/.test(platform)) return 'Get the Android app';
  if (/iphone|ipad|ipod/.test(platform)) return 'Get the app';
  if (/mac os|macintosh/.test(platform)) return 'Get the Mac app';
  if (/linux/.test(platform)) return 'Get the Linux app';
  if (/windows/.test(platform)) return 'Get the Windows app';
  return 'Get the app';
}

/** Self-check: `pnpm --filter @betweenus/desktop check`. Wrap/unwrap + message round-trip. */
import assert from 'node:assert/strict';
import {
  decryptMessage,
  encryptMessage,
  generateChannelKey,
  generateIdentity,
  openIdentity,
  parseEnvelope,
  sealIdentity,
  unwrapChannelKey,
  wrapChannelKey,
} from './e2ee-crypto';

function flipLastChar(value: string): string {
  const last = value.at(-1) === 'A' ? 'B' : 'A';
  return value.slice(0, -1) + last;
}

async function main(): Promise<void> {
  const alice = await generateIdentity();
  const bob = await generateIdentity();
  const mallory = await generateIdentity();

  const channelKey = generateChannelKey();

  // Alice seals the channel key for Bob; only Bob's private key opens it.
  const forBob = await wrapChannelKey(channelKey, alice.privateKey, bob.publicKey);
  assert.equal(await unwrapChannelKey(forBob, bob.privateKey, alice.publicKey), channelKey);

  await assert.rejects(() => unwrapChannelKey(forBob, mallory.privateKey, alice.publicKey));

  // A sender also needs the key back on their own device.
  const forSelf = await wrapChannelKey(channelKey, alice.privateKey, alice.publicKey);
  assert.equal(await unwrapChannelKey(forSelf, alice.privateKey, alice.publicKey), channelKey);

  // Message round-trip through the wire format.
  const envelope = await encryptMessage('gm, encrypted', channelKey, 1);
  const serialised = JSON.stringify(envelope);
  assert.ok(!serialised.includes('gm, encrypted'), 'plaintext must not survive serialisation');

  const parsed = parseEnvelope(serialised);
  if (!parsed) throw new Error('envelope must parse back');
  assert.equal(parsed.epoch, 1);
  assert.equal(await decryptMessage(parsed, channelKey), 'gm, encrypted');

  // The wrong channel key must fail loudly rather than return garbage.
  await assert.rejects(() => decryptMessage(parsed, generateChannelKey()));

  // A tampered ciphertext must fail the GCM tag check.
  await assert.rejects(() => decryptMessage({ ...envelope, ct: flipLastChar(envelope.ct) }, channelKey));

  // Plaintext rows from before E2EE stay renderable instead of throwing.
  assert.equal(parseEnvelope('hello world'), null);
  assert.equal(parseEnvelope('{"v":2,"epoch":1,"iv":"a","ct":"b"}'), null);

  // Identity backup: the same key comes back on another machine, and only with
  // the right secret. This is what stops "reinstall" meaning "lose everything".
  const backup = await sealIdentity(alice, 'correct horse battery staple', 'password');
  assert.equal(backup.publicKey, alice.publicKey, 'the public half is not a secret');
  assert.ok(!backup.ct.includes(alice.privateKey), 'the private half must be sealed');

  const restored = await openIdentity({ ...backup }, 'correct horse battery staple');
  assert.equal(restored.privateKey, alice.privateKey);

  // A restored identity opens keys sealed for the original - the whole point.
  assert.equal(await unwrapChannelKey(forSelf, restored.privateKey, alice.publicKey), channelKey);

  await assert.rejects(() => openIdentity({ ...backup }, 'correct horse battery stapl'));
  await assert.rejects(() => openIdentity({ ...backup, ct: flipLastChar(backup.ct) }, 'correct horse battery staple'));

  console.log('desktop e2ee-crypto check ok');
}

void main();

/**
 * End-to-end encryption primitives. WebCrypto only, no app imports, so this
 * module also runs under Node for `pnpm --filter @betweenus/desktop check`.
 *
 * Scheme (see development/E2EE.md):
 *   - identity: ECDH P-256 key pair per device, private half never leaves it
 *   - channel key: random AES-256-GCM key per channel, per epoch
 *   - distribution: ECDH(sender, recipient) -> HKDF-SHA256 -> AES-GCM wrap
 *   - messages and call media: AES-256-GCM under the channel key
 */
import type { BackupSecretKind, IdentityBackup, EncryptedEnvelope } from '@betweenus/shared-types';

const subtle = globalThis.crypto.subtle;
const encoder = new TextEncoder();
const decoder = new TextDecoder();

const IDENTITY_ALGORITHM = { name: 'ECDH', namedCurve: 'P-256' } as const;
const WRAP_INFO = 'betweenus/e2ee/v1/channel-key-wrap';
const IV_BYTES = 12;
const CHANNEL_KEY_BYTES = 32;
const BACKUP_SALT_BYTES = 16;
/**
 * PBKDF2 rounds for the identity backup. OWASP's 2023 floor for
 * PBKDF2-HMAC-SHA256 is 600k, and this runs once per sign-in on a machine that
 * has no identity yet - roughly a quarter-second, paid once, against a table
 * whose theft is the whole reason the blob is sealed.
 */
const BACKUP_ITERATIONS = 600_000;

export interface IdentityKeyPair {
  /** JWK JSON. Published to the server. */
  publicKey: string;
  /** JWK JSON. Stays on the device, encrypted at rest by the main process. */
  privateKey: string;
}

export interface WrappedChannelKey {
  wrappedKey: string;
  iv: string;
}

export async function generateIdentity(): Promise<IdentityKeyPair> {
  const pair = await subtle.generateKey(IDENTITY_ALGORITHM, true, ['deriveBits']);
  const [publicKey, privateKey] = await Promise.all([
    subtle.exportKey('jwk', pair.publicKey),
    subtle.exportKey('jwk', pair.privateKey),
  ]);
  return { publicKey: JSON.stringify(publicKey), privateKey: JSON.stringify(privateKey) };
}

/**
 * Seals the identity key pair so the server can hold it without being able to
 * open it. This is what makes an account portable: the same identity comes
 * back on any machine that can supply the secret, so channel keys already
 * sealed for it keep opening.
 *
 * The secret is stretched with PBKDF2 rather than used directly, because it is
 * a human-chosen string and the resulting blob is stored somewhere a thief can
 * reach offline.
 */
export async function sealIdentity(
  pair: IdentityKeyPair,
  secret: string,
  kind: BackupSecretKind,
): Promise<Omit<IdentityBackup, 'updatedAt'>> {
  const salt = randomBytes(BACKUP_SALT_BYTES);
  const key = await deriveBackupKey(secret, salt, BACKUP_ITERATIONS);
  const iv = randomIv();
  const sealed = await subtle.encrypt(
    { name: 'AES-GCM', iv },
    key,
    encoder.encode(JSON.stringify(pair)),
  );

  return {
    v: 1,
    kind,
    kdf: 'PBKDF2-SHA256',
    iterations: BACKUP_ITERATIONS,
    salt: toBase64(salt),
    iv: toBase64(iv),
    ct: toBase64(new Uint8Array(sealed)),
    publicKey: pair.publicKey,
  };
}

/** Throws if the secret is wrong - AES-GCM's tag is the only check needed. */
export async function openIdentity(
  backup: IdentityBackup,
  secret: string,
): Promise<IdentityKeyPair> {
  const key = await deriveBackupKey(secret, fromBase64(backup.salt), backup.iterations);
  const opened = await subtle.decrypt(
    { name: 'AES-GCM', iv: fromBase64(backup.iv) },
    key,
    fromBase64(backup.ct),
  );

  const pair = JSON.parse(decoder.decode(opened)) as IdentityKeyPair;
  if (typeof pair.publicKey !== 'string' || typeof pair.privateKey !== 'string') {
    throw new Error('Backup did not contain an identity key pair');
  }
  return pair;
}

async function deriveBackupKey(
  secret: string,
  salt: Uint8Array<ArrayBuffer>,
  iterations: number,
): Promise<CryptoKey> {
  const material = await subtle.importKey('raw', encoder.encode(secret), 'PBKDF2', false, [
    'deriveKey',
  ]);
  return subtle.deriveKey(
    { name: 'PBKDF2', hash: 'SHA-256', salt, iterations },
    material,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

export function generateChannelKey(): string {
  const bytes = new Uint8Array(CHANNEL_KEY_BYTES);
  globalThis.crypto.getRandomValues(bytes);
  return toBase64(bytes);
}

export async function wrapChannelKey(
  channelKey: string,
  privateJwk: string,
  peerPublicJwk: string,
): Promise<WrappedChannelKey> {
  const key = await deriveWrappingKey(privateJwk, peerPublicJwk);
  const iv = randomIv();
  const sealed = await subtle.encrypt({ name: 'AES-GCM', iv }, key, fromBase64(channelKey));
  return { wrappedKey: toBase64(new Uint8Array(sealed)), iv: toBase64(iv) };
}

export async function unwrapChannelKey(
  wrapped: WrappedChannelKey,
  privateJwk: string,
  peerPublicJwk: string,
): Promise<string> {
  const key = await deriveWrappingKey(privateJwk, peerPublicJwk);
  const opened = await subtle.decrypt(
    { name: 'AES-GCM', iv: fromBase64(wrapped.iv) },
    key,
    fromBase64(wrapped.wrappedKey),
  );
  return toBase64(new Uint8Array(opened));
}

export async function encryptMessage(
  plaintext: string,
  channelKey: string,
  epoch: number,
): Promise<EncryptedEnvelope> {
  const key = await importContentKey(channelKey);
  const iv = randomIv();
  const sealed = await subtle.encrypt({ name: 'AES-GCM', iv }, key, encoder.encode(plaintext));
  return { v: 1, epoch, iv: toBase64(iv), ct: toBase64(new Uint8Array(sealed)) };
}

export async function decryptMessage(
  envelope: EncryptedEnvelope,
  channelKey: string,
): Promise<string> {
  const key = await importContentKey(channelKey);
  const opened = await subtle.decrypt(
    { name: 'AES-GCM', iv: fromBase64(envelope.iv) },
    key,
    fromBase64(envelope.ct),
  );
  return decoder.decode(opened);
}

/**
 * Seals raw bytes - a file - under the channel key. Separate from
 * `encryptMessage` because the result is uploaded as a blob rather than
 * stored in a message, so it stays binary instead of becoming base64.
 *
 * ponytail: the whole file is sealed in one AES-GCM operation, which means it
 * is held in memory twice while that happens. That is why the client refuses
 * attachments over MAX_ATTACHMENT_BYTES. Chunked AEAD - one sealed frame per
 * upload part, each with its own nonce - is the upgrade if larger files matter.
 */
export async function encryptBytes(
  plaintext: Uint8Array<ArrayBuffer>,
  channelKey: string,
): Promise<{ iv: string; ciphertext: Uint8Array<ArrayBuffer> }> {
  const key = await importContentKey(channelKey);
  const iv = randomIv();
  const sealed = await subtle.encrypt({ name: 'AES-GCM', iv }, key, plaintext);
  return { iv: toBase64(iv), ciphertext: new Uint8Array(sealed) };
}

export async function decryptBytes(
  ciphertext: Uint8Array<ArrayBuffer>,
  iv: string,
  channelKey: string,
): Promise<Uint8Array<ArrayBuffer>> {
  const key = await importContentKey(channelKey);
  const opened = await subtle.decrypt({ name: 'AES-GCM', iv: fromBase64(iv) }, key, ciphertext);
  return new Uint8Array(opened);
}

/**
 * Reads a stored message body. Returns null for anything that is not an
 * envelope, so plaintext rows written before E2EE still render.
 */
export function parseEnvelope(content: string): EncryptedEnvelope | null {
  if (!content.startsWith('{')) return null;
  try {
    const parsed = JSON.parse(content) as Partial<EncryptedEnvelope>;
    if (parsed.v !== 1) return null;
    if (typeof parsed.iv !== 'string' || typeof parsed.ct !== 'string') return null;
    if (typeof parsed.epoch !== 'number') return null;
    return { v: 1, epoch: parsed.epoch, iv: parsed.iv, ct: parsed.ct };
  } catch {
    return null;
  }
}

async function deriveWrappingKey(privateJwk: string, peerPublicJwk: string): Promise<CryptoKey> {
  const [privateKey, publicKey] = await Promise.all([
    subtle.importKey('jwk', JSON.parse(privateJwk) as JsonWebKey, IDENTITY_ALGORITHM, false, [
      'deriveBits',
    ]),
    subtle.importKey('jwk', JSON.parse(peerPublicJwk) as JsonWebKey, IDENTITY_ALGORITHM, false, []),
  ]);

  // The raw ECDH output is a curve point, not a uniform key: run it through
  // HKDF before it is used as an AES key.
  const shared = await subtle.deriveBits({ name: 'ECDH', public: publicKey }, privateKey, 256);
  const material = await subtle.importKey('raw', shared, 'HKDF', false, ['deriveKey']);

  return subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      // A fixed salt is safe here: the pair is static and every wrap uses a
      // fresh random IV. `info` domain-separates this use of the secret.
      salt: new Uint8Array(new ArrayBuffer(32)),
      info: encoder.encode(WRAP_INFO),
    },
    material,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

function importContentKey(channelKey: string): Promise<CryptoKey> {
  return subtle.importKey('raw', fromBase64(channelKey), { name: 'AES-GCM' }, false, [
    'encrypt',
    'decrypt',
  ]);
}

// The typed arrays below are built on an explicit ArrayBuffer: WebCrypto's
// BufferSource excludes SharedArrayBuffer-backed views.
function randomIv() {
  return randomBytes(IV_BYTES);
}

function randomBytes(length: number) {
  const bytes = new Uint8Array(new ArrayBuffer(length));
  globalThis.crypto.getRandomValues(bytes);
  return bytes;
}

export function toBase64(bytes: Uint8Array): string {
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

export function fromBase64(value: string) {
  const binary = atob(value);
  const bytes = new Uint8Array(new ArrayBuffer(binary.length));
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

/**
 * Channel-key distribution, checked against a stand-in key directory that
 * enforces the same publish rules the chat service does.
 *
 * The bug this pins down: the owner creates a server, keys #general for the one
 * member that exists (themselves), invites somebody and closes the app. The
 * invitee holds no key, nobody is online to wrap one for them, and every
 * message they try to send comes back "No channel key on this device yet".
 *
 * Run with: pnpm --filter @betweenus/desktop check
 */
import assert from 'node:assert/strict';
import type { ChannelKeyEntry, DeviceKey, PublishChannelKeysRequest } from '@betweenus/shared-types';
import { configureApi } from './api';
import {
  UNDECRYPTABLE,
  backupIdentity,
  decryptForChannel,
  encryptForChannel,
  initIdentity,
  resetE2ee,
  syncChannelKeys,
  type BackupSecret,
} from './e2ee';

const CHANNEL = 'channel-general';

/**
 * Members of the channel, whether or not they have signed in anywhere yet.
 *
 * Mutable, because losing a member is half of what is checked here: the server
 * decides who a key may be wrapped for by asking who is a member *now*.
 */
let MEMBERS = ['alice', 'bob'];

type StoredKey = ChannelKeyEntry & { epoch: number; createdAt: number };

/**
 * Public keys, wrapped keys, and who is making the call.
 *
 * Keyed by `userId:deviceId` since the directory became a list per user: one
 * person signed in on a laptop and a phone is two rows, two public keys and two
 * wraps of every channel key.
 */
const devices = new Map<string, { userId: string; deviceId: string; publicKey: string }>();
/**
 * Devices whose owner has revoked them, and when.
 *
 * The clock is a counter rather than a date: what matters is only whether a
 * revocation came after the epoch was minted, and two real timestamps a
 * millisecond apart would make that a flaky assertion rather than a clear one.
 */
const revoked = new Map<string, number>();
/**
 * Sealed identities, keyed `userId:kind`.
 *
 * Per kind rather than per account, the way the table is: a recovery passphrase
 * used to overwrite the password-sealed blob, and the password blob is the only
 * one a fresh sign-in holds the secret for.
 */
const backups = new Map<string, Record<string, unknown>>();

/** Every backup an account holds, as `GET /e2ee/backup` returns them. */
function backupsFor(userId: string): Record<string, unknown>[] {
  return [...backups.entries()]
    .filter(([key]) => key.startsWith(`${userId}:`))
    .map(([, value]) => value);
}
let tick = 0;
let stored: StoredKey[] = [];
let caller = 'alice';
/** Every epoch that was published, in order, so a re-key loop is visible. */
let published: number[] = [];
/** One-shot fault: the next publish behaves like a dropped request. */
let failNextPublish = false;

function latestEpoch(): number {
  return stored.reduce((max, row) => Math.max(max, row.epoch), 0);
}

function knownDevices(): DeviceKey[] {
  return [...devices.values()]
    .filter(
      (device) =>
        MEMBERS.includes(device.userId) && !revoked.has(`${device.userId}:${device.deviceId}`),
    )
    .map((device) => ({
      userId: device.userId,
      deviceId: device.deviceId,
      publicKey: device.publicKey,
      label: null,
      revokedAt: null,
      lastSeenAt: '2026-08-18T00:00:00.000Z',
      createdAt: '2026-08-18T00:00:00.000Z',
    }));
}

/** Mirrors E2eeService.publishKeys, including the two rules that guard it. */
function publish(dto: PublishChannelKeysRequest): Response {
  const current = latestEpoch();

  if (dto.epoch > current) {
    if (dto.epoch !== current + 1) return forbidden('EPOCH_OUT_OF_ORDER');
  } else if (!stored.some((row) => row.epoch === dto.epoch && row.recipientUserId === caller)) {
    return forbidden('EPOCH_NOT_HELD');
  }

  // Every entry is checked before any of them is written, which is what the
  // service does - it validates, then `createMany`. Storing as it went left a
  // half-published epoch behind on a rejected bundle, and a half-published
  // epoch is a channel key nobody can open and an epoch number nobody minted.
  for (const entry of dto.entries) {
    if (!MEMBERS.includes(entry.recipientUserId)) return forbidden('RECIPIENT_NOT_MEMBER');
    if (revoked.has(`${entry.recipientUserId}:${entry.recipientDeviceId}`)) {
      return forbidden('DEVICE_REVOKED');
    }
  }

  for (const entry of dto.entries) {
    const duplicate = stored.some(
      (row) =>
        row.epoch === dto.epoch &&
        row.recipientUserId === entry.recipientUserId &&
        row.recipientDeviceId === entry.recipientDeviceId,
    );
    if (duplicate) continue;
    stored.push({
      ...entry,
      epoch: dto.epoch,
      senderUserId: caller,
      senderDeviceId: dto.senderDeviceId,
      createdAt: (tick += 1),
    });
  }

  published.push(dto.epoch);
  return json({ epoch: dto.epoch, stored: dto.entries.length });
}

/**
 * Machines missing an epoch their owner already holds somewhere else, over
 * every epoch that exists. Mirrors `E2eeService.gaps`, including the condition
 * that makes it safe: a person's second machine is repaired, and a member who
 * joined last week is still not handed the year before that.
 */
function gapsNow(): Array<{ epoch: number; devices: DeviceKey[] }> {
  const held = new Set(
    stored.map((row) => `${row.epoch}:${row.recipientUserId}:${row.recipientDeviceId}`),
  );
  const owners = new Set(stored.map((row) => `${row.epoch}:${row.recipientUserId}`));
  const epochs = [...new Set(stored.map((row) => row.epoch))].sort((a, b) => b - a);
  return epochs
    .map((epoch) => ({
      epoch,
      devices: knownDevices().filter(
        (device) =>
          owners.has(`${epoch}:${device.userId}`) &&
          !held.has(`${epoch}:${device.userId}:${device.deviceId}`),
      ),
    }))
    .filter((gap) => gap.devices.length > 0);
}

/** Is the current epoch on a machine that should not have it? */
function staleNow(epoch: number): boolean {
  const rows = stored.filter((row) => row.epoch === epoch);
  if (rows.length === 0) return false;
  if (rows.some((row) => !MEMBERS.includes(row.recipientUserId))) return true;

  const mintedAt = Math.min(...rows.map((row) => row.createdAt));
  return [...revoked.entries()].some(
    ([key, at]) => MEMBERS.includes(key.split(':')[0] ?? '') && at > mintedAt,
  );
}

function json(body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  });
}

function forbidden(code: string): Response {
  return new Response(JSON.stringify({ error: { code, message: code } }), {
    status: 403,
    headers: { 'Content-Type': 'application/json' },
  });
}

function stubDirectory(): void {
  globalThis.fetch = ((input: string, init?: RequestInit) => {
    const url = new URL(String(input));
    const method = init?.method ?? 'GET';
    const body: unknown = init?.body ? JSON.parse(String(init.body)) : null;

    if (url.pathname === '/api/v1/e2ee/devices' && method === 'POST') {
      const { publicKey, deviceId } = body as { publicKey: string; deviceId: string };
      // A revoked id stays revoked: a machine that could un-revoke itself makes
      // revocation a suggestion, and the machine in question runs this code.
      if (revoked.has(`${caller}:${deviceId}`)) return Promise.resolve(forbidden('DEVICE_REVOKED'));
      devices.set(`${caller}:${deviceId}`, { userId: caller, deviceId, publicKey });
      return Promise.resolve(json({ userId: caller, deviceId, publicKey }));
    }
    if (url.pathname === '/api/v1/e2ee/devices') return Promise.resolve(json(knownDevices()));

    // Sealed identities, so a machine that cannot open the one that is there
    // can be told apart from an account that has none.
    if (url.pathname === '/api/v1/e2ee/backup') {
      if (method === 'GET') {
        const held = backupsFor(caller);
        return Promise.resolve(
          json({ backups: held, backup: held.find((it) => it.kind === 'password') ?? held[0] ?? null }),
        );
      }
      const blob = body as Record<string, unknown>;
      backups.set(`${caller}:${String(blob.kind)}`, blob);
      return Promise.resolve(json({ ok: true }));
    }
    if (url.pathname.startsWith('/api/v1/e2ee/backup/')) {
      backups.delete(`${caller}:${url.pathname.split('/').pop() ?? ''}`);
      return Promise.resolve(json({ ok: true }));
    }

    if (url.pathname.startsWith('/api/v1/e2ee/keys/')) {
      const epoch = latestEpoch();
      const covered = new Set(
        stored
          .filter((row) => row.epoch === epoch)
          .map((row) => `${row.recipientUserId}:${row.recipientDeviceId}`),
      );
      return Promise.resolve(
        json({
          channelId: CHANNEL,
          epoch,
          keys: stored.filter((row) => row.recipientUserId === caller),
          missingRecipients:
            epoch === 0
              ? []
              : knownDevices().filter(
                  (device) => !covered.has(`${device.userId}:${device.deviceId}`),
                ),
          // The same derivation the service does, and the same two reasons: a
          // holder who is no longer a member, or a machine revoked since this
          // epoch was minted. The second cannot be found by looking for its
          // wraps - revoking deletes them - so it is found by the clock.
          rekeyNeeded: staleNow(epoch),
          // The same question asked of every epoch, which is what lets a
          // machine that signed in today be handed the history.
          gaps: gapsNow(),
        }),
      );
    }

    if (url.pathname === '/api/v1/e2ee/keys' && method === 'POST') {
      if (failNextPublish) {
        failNextPublish = false;
        return Promise.reject(new Error('network down'));
      }
      return Promise.resolve(publish(body as PublishChannelKeysRequest));
    }

    throw new Error(`unexpected call: ${method} ${url.pathname}`);
  }) as typeof fetch;
}

/**
 * `secureGet`/`secureSet` fall back to localStorage, which Node has not got.
 *
 * One store, with the sealed identity partitioned by device id. Two machines
 * are two keychains, and sharing one here would have made every "different
 * laptop" in this file the same laptop under another name - it would open every
 * wrap addressed to the other one and prove nothing. The device id is the same
 * value the client reads, so switching machines switches keychains without
 * anything else having to know.
 */
function stubBrowserGlobals(): void {
  const store = new Map<string, string>();
  const partition = (key: string): string =>
    key.startsWith('betweenus.secure.')
      ? `${store.get('betweenus.deviceId') ?? 'unknown'}/${key}`
      : key;
  Object.assign(globalThis, {
    window: { location: { origin: 'http://localhost:8080' } },
    localStorage: {
      getItem: (key: string) => store.get(partition(key)) ?? null,
      setItem: (key: string, value: string) => store.set(partition(key), value),
      removeItem: (key: string) => store.delete(partition(key)),
    },
  });
}

/**
 * Signs an account in on one machine.
 *
 * `deviceId` is read out of localStorage by the client, so putting a value
 * there is how this stand-in says "a different laptop". Clearing the identity
 * store alongside it is what makes it a different laptop rather than the same
 * one with a new name: a machine that kept the private half would open every
 * wrap addressed to the other one and prove nothing.
 */
/**
 * Lets the work a sign-in started but did not wait for finish.
 *
 * Generous, because the slowest of it is a 600k-round PBKDF2 seal. A shorter
 * wait does not make the check faster, it makes it pass for the wrong reason.
 */
function settle(): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, 2000));
}

/** Wipes the key a machine holds, so the next sign-in is a machine without one. */
function forgetIdentity(userId: string): void {
  localStorage.removeItem(`betweenus.secure.identity:${userId}`);
}

async function signIn(
  userId: string,
  device = 'device-1',
  secret?: BackupSecret,
): Promise<void> {
  resetE2ee();
  caller = userId;
  localStorage.setItem('betweenus.deviceId', `${userId}-${device}`);
  await initIdentity(userId, secret);
}

async function main(): Promise<void> {
  stubBrowserGlobals();
  stubDirectory();
  configureApi(
    () => 'test-token',
    async () => 'test-token',
  );

  // Alice creates the server and keys #general while she is its only member.
  await signIn('alice');
  const beforeBob = await encryptForChannel(CHANNEL, 'before bob arrived');
  assert.deepEqual(published, [1], 'alice should have minted exactly the first epoch');
  assert.equal(stored.length, 1, 'the first key is wrapped for alice alone');

  // Bob is invited and opens the channel with alice long since offline.
  await signIn('bob');
  const fromBob = await encryptForChannel(CHANNEL, 'hi');
  assert.deepEqual(published, [1, 2], 'bob should have minted the next epoch, once');
  assert.deepEqual(
    stored
      .filter((row) => row.epoch === 2)
      .map((row) => row.recipientUserId)
      .sort(),
    ['alice', 'bob'],
    'the new epoch must be wrapped for every member, not just its author',
  );

  // Opening the channel again must not walk the epoch forward every time.
  resetE2ee();
  await initIdentity('bob');
  await encryptForChannel(CHANNEL, 'again');
  assert.deepEqual(published, [1, 2], 'a device that holds the key must not re-key');

  // What alice wrote before bob was a member stays closed to him.
  assert.equal(
    await decryptForChannel(CHANNEL, beforeBob),
    UNDECRYPTABLE,
    'history from before the join must not become readable',
  );

  // And alice, back online, reads bob without either of them doing anything.
  await signIn('alice');
  assert.equal(await decryptForChannel(CHANNEL, fromBob), 'hi');
  assert.equal(await decryptForChannel(CHANNEL, beforeBob), 'before bob arrived');

  // Bob is dropped from the channel. His key still opens everything sent up to
  // now - a key on somebody's machine cannot be taken back - but the channel
  // has to stop using it, and only a holder can arrange that.
  MEMBERS = ['alice'];
  await syncChannelKeys(CHANNEL);
  assert.deepEqual(published, [1, 2, 3], 'a stale holder must produce exactly one re-key');
  assert.deepEqual(
    stored
      .filter((row) => row.epoch === 3)
      .map((row) => row.recipientUserId)
      .sort(),
    ['alice'],
    'the new epoch is wrapped for the members who remain, and nobody else',
  );

  const afterBob = await encryptForChannel(CHANNEL, 'after bob left');
  assert.ok(
    JSON.parse(afterBob).epoch === 3,
    'the next message must be sealed under the new epoch',
  );

  // Nothing to re-key now, so opening the channel again is quiet.
  await syncChannelKeys(CHANNEL);
  assert.deepEqual(published, [1, 2, 3], 'a channel with no stale holder must not re-key');

  // And bob gets nothing newer. A device that signs in again after being
  // removed cannot even reach the directory in the real service - the keys
  // endpoint checks channel access first - so what is asserted here is the part
  // that survives either way: the message written after he left does not open
  // with anything he has.
  await signIn('bob');
  assert.equal(
    await decryptForChannel(CHANNEL, afterBob),
    UNDECRYPTABLE,
    'what was sent after he left must not open',
  );

  // --- A second machine, and taking one away -------------------------------

  // Alice signs in on a phone. It is a different device id and a different key
  // pair, so it holds nothing yet: the phone must be wrapped for rather than
  // assumed covered because "alice" already had a key. That assumption is what
  // the per-account directory made, and it is why a second machine used to
  // read nothing until the channel happened to re-key.
  MEMBERS = ['alice'];
  await signIn('alice', 'phone');
  await syncChannelKeys(CHANNEL);

  const phoneWraps = stored.filter(
    (row) => row.epoch === latestEpoch() && row.recipientDeviceId === 'alice-phone',
  );
  assert.equal(phoneWraps.length, 1, 'a new machine must be wrapped for, once');

  // And it reads nothing yet. The phone holds one epoch - the one it had to
  // mint for itself, because no machine holding the older ones was online to
  // wrap them for it - so the whole conversation up to this moment is a
  // padlock. That is the wall of them a second device opens on, and what the
  // next few lines exist to repair.
  assert.equal(
    await decryptForChannel(CHANNEL, afterBob),
    UNDECRYPTABLE,
    'a brand new machine starts with no history, before anyone repairs it',
  );
  assert.equal(await decryptForChannel(CHANNEL, beforeBob), UNDECRYPTABLE);

  // The laptop still reads its own history.
  await signIn('alice', 'device-1');
  assert.equal(await decryptForChannel(CHANNEL, afterBob), 'after bob left');

  // And opening the channel on the laptop hands the phone every epoch the
  // laptop holds. This is the repair: it is the same person, who can read
  // those messages on the machine in front of them, and the server offers the
  // gap only for a machine whose *owner* already holds that epoch.
  const epochBeforeRepair = latestEpoch();
  await syncChannelKeys(CHANNEL);
  assert.equal(
    latestEpoch(),
    epochBeforeRepair,
    'every device is covered, so nothing needs re-keying',
  );
  assert.deepEqual(
    stored
      .filter((row) => row.recipientDeviceId === 'alice-phone')
      .map((row) => row.epoch)
      .sort((a, b) => a - b),
    [1, 2, 3, 4],
    'the phone is handed every epoch the laptop holds, not only the newest',
  );

  // So the phone now reads the whole conversation, including what was written
  // three epochs before it existed.
  await signIn('alice', 'phone');
  assert.equal(
    await decryptForChannel(CHANNEL, beforeBob),
    'before bob arrived',
    'the second machine reads history once a machine that holds it has been online',
  );
  assert.equal(await decryptForChannel(CHANNEL, afterBob), 'after bob left');

  // And bob, who was never a member when that was written, is still not handed
  // it. The repair is one person's own second machine and nothing wider: the
  // gap list names a device only when its owner already holds that epoch.
  const bobDevices = new Set(
    stored.filter((row) => row.recipientUserId === 'bob').map((row) => row.epoch),
  );
  assert.equal(bobDevices.has(3), false, 'a former member gains nothing from a repair');
  assert.equal(bobDevices.has(4), false, 'a former member gains nothing from a repair');

  await signIn('alice', 'device-1');
  const beforeRevoke = latestEpoch();

  // Alice loses the phone and revokes it. Its wraps go with it, and the channel
  // has to move past the key it was holding - the same rule as a member who
  // left, for the same reason: what it already decrypted is on a machine
  // nobody trusts any more.
  revoked.set('alice:alice-phone', (tick += 1));
  // Revoking deletes the wraps addressed to it, which is most of what revoking
  // is - and is exactly why the staleness of the epoch cannot be derived from
  // them afterwards.
  stored = stored.filter((row) => row.recipientDeviceId !== 'alice-phone');

  await syncChannelKeys(CHANNEL);
  assert.equal(latestEpoch(), beforeRevoke + 1, 'a revoked device forces exactly one re-key');

  const newest = latestEpoch();
  assert.deepEqual(
    stored
      .filter((row) => row.epoch === newest)
      .map((row) => row.recipientDeviceId)
      .sort(),
    ['alice-device-1'],
    'the new epoch is wrapped for the machines that remain, and not the revoked one',
  );

  const afterRevoke = await encryptForChannel(CHANNEL, 'after the phone was lost');
  assert.equal(JSON.parse(afterRevoke).epoch, newest);

  // And the phone, when it comes back, is turned away at the directory rather
  // than quietly re-admitted - then reads nothing written since.
  resetE2ee();
  caller = 'alice';
  localStorage.setItem('betweenus.deviceId', 'alice-phone');
  await assert.rejects(initIdentity('alice'), /DEVICE_REVOKED/);
  assert.equal(
    await decryptForChannel(CHANNEL, afterRevoke),
    UNDECRYPTABLE,
    'a revoked machine must not read what was sent after it was revoked',
  );

  // --- A dropped request during self-heal must not brick the channel -------
  //
  // Dave joins a channel alice already keyed, offline. Opening it makes his
  // client mint its own epoch the same way bob's did above - but this time the
  // publish call itself fails (a network blip), not a race another member won.
  // The old code marked the channel "already tried" before that call returned,
  // so every later attempt this session skipped straight to "no key" instead
  // of trying again. It must retry instead.
  const CHANNEL_2 = 'channel-random';
  MEMBERS = ['alice', 'dave'];
  await signIn('alice');
  const beforeDave = await encryptForChannel(CHANNEL_2, 'hello before dave');

  await signIn('dave');
  failNextPublish = true;
  assert.equal(
    await decryptForChannel(CHANNEL_2, beforeDave),
    UNDECRYPTABLE,
    'a dropped request during self-heal still renders as undecryptable, not a crash',
  );
  assert.equal(
    await decryptForChannel(CHANNEL_2, beforeDave),
    UNDECRYPTABLE,
    'the message dave was never sealed for stays closed - that part is by design',
  );
  const fromDave = await encryptForChannel(CHANNEL_2, 'hi from dave');
  assert.notEqual(
    fromDave,
    undefined,
    'a retry after the dropped request must mint dave a working epoch, not stay locked out',
  );

  await signIn('alice');
  assert.equal(
    await decryptForChannel(CHANNEL_2, fromDave),
    'hi from dave',
    'alice must read what dave sent once his self-heal succeeded on retry',
  );

  // A sign-in that cannot open the account backup must still sign in.
  //
  // This is the GitHub case: the account has a backup sealed under a password,
  // the provider sign-in has no password to offer, and there is nothing on
  // screen to ask with. It mints a key of its own and carries on - and it must
  // not seal that key over the backup the other machines restore from.
  MEMBERS = [...MEMBERS, 'erin'];
  await signIn('erin');
  await backupIdentity({ value: 'erin-account-password', kind: 'password' });
  const erinsBackup = backups.get('erin:password');
  assert.notEqual(erinsBackup, undefined, 'erin has an account backup to be locked out of');

  // A machine with nothing of its own on it, which is what a new one is. The
  // identity is stored per account rather than per device id, so it has to go
  // for this to be a second laptop rather than the first one renamed.
  forgetIdentity('erin');
  await signIn('erin', 'device-2');
  assert.deepEqual(
    backups.get('erin:password'),
    erinsBackup,
    'a machine that could not open the backup must never replace it',
  );
  const fromErin = await encryptForChannel(CHANNEL_2, 'sent from the new laptop');
  assert.notEqual(
    fromErin,
    undefined,
    'a provider sign-in with no secret must reach a usable key rather than stop and ask',
  );

  const forkedKey = devices.get('erin:erin-device-2')?.publicKey;
  assert.notEqual(
    forkedKey,
    erinsBackup?.publicKey,
    'a machine that could not open the backup is on a key of its own - that is the fork',
  );

  // The same laptop, signed in later with the account password. Two things at
  // once, and both are the reported bug.
  //
  // It must *recover*: the fork was permanent, because the minted key sat in
  // the keychain and every later launch short-circuited on it without ever
  // asking for the backup again. A phone signed in with the right password read
  // every message it had ever been sent as a padlock, for the life of the
  // install, with no way back and nothing on screen to say so.
  //
  // And the password must still not quietly promote the minted key to the
  // account's backup: every machine still restoring from the real one would be
  // locked out of everything, and nothing would say so.
  await signIn('erin', 'device-2', { value: 'erin-account-password', kind: 'password' });
  await settle();
  assert.equal(
    devices.get('erin:erin-device-2')?.publicKey,
    erinsBackup?.publicKey,
    'a forked machine must take the account key back on the next sign-in that can open the backup',
  );

  // And the secret, when there is one, still puts the account key on the
  // machine that asks with it.
  forgetIdentity('erin');
  await signIn('erin', 'device-3', { value: 'erin-account-password', kind: 'password' });
  const fromErinsThird = await encryptForChannel(CHANNEL_2, 'sent from the third');
  assert.equal(
    await decryptForChannel(CHANNEL_2, fromErin),
    'sent from the new laptop',
    'a machine restored from the backup reads what the account key already opened',
  );

  // The backup is still the one erin sealed, byte for byte. `ensureBackup` runs
  // on every sign-in and is not awaited by any of them, so this is checked last,
  // once all of them have had their chance to overwrite it: the laptop holding a
  // key of its own must not promote that key to the account's, or every machine
  // restoring from the real one is locked out of everything and nothing says so.
  await settle();
  assert.deepEqual(
    backups.get('erin:password'),
    erinsBackup,
    'no sign-in may replace the account backup with a key of its own',
  );
  assert.notEqual(fromErinsThird, undefined, 'the restored machine can seal too');

  // A recovery passphrase must not take the password path away.
  //
  // The table was keyed on the account, so setting one overwrote the
  // password-sealed blob - and that blob is the only thing a fresh sign-in
  // holds the secret for. Losing it turned every later "sign in on a new
  // device" into the fork above, which is a padlock on the whole account.
  await backupIdentity({ value: 'erin-recovery-passphrase', kind: 'passphrase' });
  assert.deepEqual(
    backups.get('erin:password'),
    erinsBackup,
    'setting a recovery passphrase must leave the password backup standing',
  );
  assert.notEqual(
    backups.get('erin:passphrase'),
    undefined,
    'the passphrase backup is stored alongside it, not instead of it',
  );

  // And a new machine still recovers with the password alone, which is the
  // whole promise: sign in anywhere, read everything, type nothing extra.
  forgetIdentity('erin');
  await signIn('erin', 'device-4', { value: 'erin-account-password', kind: 'password' });
  await settle();
  assert.equal(
    devices.get('erin:erin-device-4')?.publicKey,
    erinsBackup?.publicKey,
    'the account password must still restore the account key after a passphrase was set',
  );

  console.log('e2ee.check.ts: ok');
}

void main();

/**
 * Client side of end-to-end encryption: device identity, channel-key exchange,
 * and the encrypt/decrypt calls the chat and call features use.
 *
 * The server is a courier here. It stores public keys and sealed blobs, decides
 * who may publish them, and never holds anything that opens a message.
 */
import type {
  BackupSecretKind,
  ChannelKeyEntry,
  ChannelKeysResponse,
  DeviceKey,
  EncryptedEnvelope,
  IdentityBackup,
  StatusEntry,
  StatusKeyEntry,
} from '@betweenus/shared-types';
import { ApiError, api } from './api';
import { setIdentityStatus } from '../stores/identity';
import {
  decryptBytes,
  decryptMessage,
  encryptBytes,
  encryptMessage,
  generateChannelKey,
  generateIdentity,
  openIdentity,
  parseEnvelope,
  sealIdentity,
  unwrapChannelKey,
  wrapChannelKey,
  type IdentityKeyPair,
} from './e2ee-crypto';

/**
 * Shown instead of a message we hold no key for. Never throws into the UI.
 *
 * Two words, because it is drawn once per message and a sentence repeated down
 * a whole screen is not eight times as informative as one - the explanation and
 * what to do about it belong in the single line the channel draws above them.
 */
export const UNDECRYPTABLE = '\u{1F512} Encrypted';

export class MissingChannelKeyError extends Error {
  constructor() {
    super('No channel key on this device yet');
    this.name = 'MissingChannelKeyError';
  }
}


/** What opens the backup. Held only for the moment a sign-in needs it. */
export interface BackupSecret {
  value: string;
  kind: BackupSecretKind;
}

interface ChannelKeyState {
  epoch: number;
  /** Every epoch this device can open, so old history stays readable. */
  keys: Map<number, string>;
}

let identity: IdentityKeyPair | null = null;
let identityUserId: string | null = null;
/** Set by initIdentity; everything that needs a key awaits it. */
let identityReady: Promise<IdentityKeyPair> | null = null;
const channels = new Map<string, ChannelKeyState>();
const inFlight = new Map<string, Promise<ChannelKeyState>>();
/**
 * Channels this session has already tried to re-key for itself. Without it, a
 * device that cannot open its own wrapped keys - a corrupt identity, a public
 * key in the directory that is not ours - would mint a fresh epoch every time
 * the channel is opened and drag the whole channel along with it.
 */
const rekeyed = new Set<string>();

/**
 * The secret this session signed in with, kept for the length of the session.
 *
 * It used to be an argument and nothing else, so a sign-in whose identity setup
 * failed once - the network dropped, the token was a moment late - lost it. The
 * retry then ran with no secret at all, could not open the account backup, and
 * minted a machine-local key instead, which is permanent (see `loadIdentity`).
 * A password typed into a login form is dropped when the session ends, and that
 * is the only thing keeping it here has to guarantee.
 */
let signInSecret: BackupSecret | null = null;

/**
 * What the keychain holds. `provisional` marks a key this machine minted for
 * itself *while the account had a backup it could not open* - the fork
 * described in `loadIdentity`. It is the flag that makes the fork recoverable:
 * without it the stored key short-circuits every later launch and the backup is
 * never tried again, on any sign-in, ever.
 */
interface StoredIdentity extends IdentityKeyPair {
  provisional?: boolean;
}

/**
 * Loads this device's identity key and publishes the public half. Called once
 * per sign-in, with the password when there is one to hand.
 *
 * It never fails for want of a secret, and it never asks for one. See
 * `loadIdentity` for why a machine that cannot open the account backup mints
 * its own key rather than stopping to ask.
 */
export function initIdentity(userId: string, secret?: BackupSecret): Promise<IdentityKeyPair> {
  if (identityReady && identityUserId === userId) return identityReady;

  identityUserId = userId;
  // Held past this call on purpose: the retry below has no secret of its own,
  // and a retry without one forks the identity permanently.
  if (secret) signInSecret = secret;
  // A failure here - the network was down, the token had not been minted yet -
  // must not be remembered. Keeping the rejected promise left the device
  // unregistered for the whole session, and every channel it tried to key
  // afterwards ended in "No channel key on this device yet".
  identityReady = loadIdentity(userId, secret ?? signInSecret ?? undefined).catch((error: unknown) => {
    if (identityUserId === userId) identityReady = null;
    throw error;
  });
  return identityReady;
}

async function loadIdentity(userId: string, secret?: BackupSecret): Promise<IdentityKeyPair> {
  const storageKey = `identity:${userId}`;
  const stored = await secureGet(storageKey);

  if (stored) {
    const saved = JSON.parse(stored) as StoredIdentity;
    const pair: IdentityKeyPair = { publicKey: saved.publicKey, privateKey: saved.privateKey };

    // A machine that forked gets another go, every time a secret is at hand.
    // This is the whole of "sign in on a new phone and your messages are
    // there": the fork below is silent and one-way, so the only thing that
    // makes it recoverable is trying the backup again on the next sign-in
    // rather than short-circuiting on the key the fork left behind.
    if (saved.provisional && secret) {
      const recovered = await restoreFromBackup(storageKey, secret);
      if (recovered) return recovered;
    }

    await adopt(pair, false, saved.provisional === true);
    // A machine that already worked may still have no backup - it predates
    // this, or nobody could supply a secret at the time. Fix it quietly when a
    // secret is at hand rather than waiting for the next reinstall to notice.
    void ensureBackup(pair, secret);
    return pair;
  }

  // A failed fetch must not be read as "there is no backup": that would seal a
  // fresh key over one that exists. It throws, and the sign-in retries.
  const { backups } = await identityBackups();

  // The account's own key, when the secret that opens it is at hand. This is
  // the good path and the only instant one: every epoch already sealed for
  // that identity opens the moment it lands, with nothing to wait for.
  if (secret) {
    const recovered = await restoreFromBackup(storageKey, secret, backups);
    if (recovered) return recovered;
  }

  // Otherwise this machine gets a key of its own, and the sign-in carries on.
  //
  // It used to stop here and ask - and asking is not something every sign-in
  // can answer. A GitHub sign-in has no account password to offer, and an
  // account that has only ever signed in that way has no password at all, so
  // the question had no answer and the app sat behind a box nobody could fill.
  //
  // Minting is safe because a channel key is wrapped per *device*, not per
  // account: this machine publishes its own public key under its own device id
  // and takes nothing away from the machines already in the directory. History
  // arrives from them - `fillGaps` hands every epoch a machine holds to the
  // owner's machines that are missing it - so the account converges without
  // anyone typing anything.
  //
  // What it costs: history is not instant. It appears as the other machines
  // open those channels. An account whose only other machine is offline, or
  // which has none, reads what arrives from now on until one of them is back.
  // Settings -> Encryption is where somebody who wants it sooner can say so.
  //
  // The fork is marked when the account *had* a backup this machine could not
  // open, and that mark is what lets the next sign-in undo it. Unmarked means
  // there was nothing to restore from, so this key is the account's own.
  const provisional = backups.length > 0;
  const pair = await generateIdentity();
  await secureSet(storageKey, JSON.stringify({ ...pair, provisional } satisfies StoredIdentity));
  await adopt(pair, false, provisional);
  await ensureBackup(pair, secret);
  return pair;
}

/**
 * Opens whichever backup `secret` fits and makes it this machine's identity.
 *
 * Null means "not this secret" - a wrong password, or a passphrase-only account
 * signing in with a password - which is an ordinary outcome, not a failure.
 *
 * Every channel key held on this machine is dropped on the way out. They are
 * still valid, but they are the *subset* a forked identity could reach, and the
 * caches in front of them would keep serving that subset while the wraps this
 * identity can now open sat unread in the directory. Dropping them costs one
 * re-read of a directory we have just been talking to.
 */
async function restoreFromBackup(
  storageKey: string,
  secret: BackupSecret,
  known?: IdentityBackup[],
): Promise<IdentityKeyPair | null> {
  const backups = known ?? (await identityBackups()).backups;
  const sealed = backups.find((it) => it.kind === secret.kind);
  if (!sealed) return null;

  const pair = await openBackup(sealed, secret);
  if (!pair) return null;

  await secureSet(storageKey, JSON.stringify({ ...pair } satisfies StoredIdentity));
  channels.clear();
  inFlight.clear();
  rekeyed.clear();
  missedEpochs.clear();
  await adopt(pair, true);
  return pair;
}

/**
 * The account's sealed identities. Reads the list, falling back to the single
 * blob a server older than per-kind backups sends.
 */
async function identityBackups(): Promise<{ backups: IdentityBackup[] }> {
  const response = await api.identityBackup();
  if (response.backups) return { backups: response.backups };
  return { backups: response.backup ? [response.backup] : [] };
}

/** The wrong secret is an ordinary outcome here, not an error: null, and on. */
async function openBackup(
  backup: IdentityBackup,
  secret: BackupSecret,
): Promise<IdentityKeyPair | null> {
  try {
    return await openIdentity(backup, secret.value);
  } catch {
    return null;
  }
}

/** Publishes the public half and marks this machine ready. */
async function adopt(
  pair: IdentityKeyPair,
  backedUp = false,
  provisional = false,
): Promise<void> {
  identity = pair;
  try {
    // Idempotent: re-publishing keeps the directory correct if the row was
    // lost, and refreshes when this machine was last seen.
    await api.registerDeviceKey({
      deviceId: deviceId(),
      publicKey: pair.publicKey,
      label: deviceLabel(),
    });
  } catch (error) {
    // Revoked from another machine. Not an error to retry and not a reason to
    // mint a new id - minting one is how a revoked machine would walk straight
    // back into the directory, which would make revoking it meaningless.
    if (error instanceof ApiError && error.code === 'DEVICE_REVOKED') {
      setIdentityStatus({ status: 'revoked' });
      throw error;
    }
    throw error;
  }
  setIdentityStatus({ status: 'ready', backedUp, provisional });
}

const DEVICE_ID_KEY = 'betweenus.deviceId';

/**
 * Which machine this is, as far as the key directory is concerned.
 *
 * Minted here and never by the server: it identifies an installation, and an
 * installation is the only thing that knows it is one. It survives sign-out and
 * a change of account on purpose - the machine has not changed - and it is not
 * a secret: it is published beside a public key.
 *
 * Losing it (a cleared profile, a fresh container) means the next launch looks
 * like a new device and gets wrapped for as one, which is the correct answer
 * rather than a failure.
 */
export function deviceId(): string {
  try {
    const stored = localStorage.getItem(DEVICE_ID_KEY);
    if (stored) return stored;
    const minted = crypto.randomUUID();
    localStorage.setItem(DEVICE_ID_KEY, minted);
    return minted;
  } catch {
    // No storage at all: a per-session id, which is worse than a stable one and
    // far better than refusing to publish a key.
    return `session-${crypto.randomUUID()}`;
  }
}

/**
 * What to call this machine in a list of them. A guess from the user agent, and
 * deliberately a rough one: it is a label to recognise a row by, not identity,
 * and the server treats it as the untrusted string it is.
 */
function deviceLabel(): string {
  const agent = typeof navigator === 'undefined' ? '' : navigator.userAgent;
  const platform =
    /Windows/i.test(agent) ? 'Windows'
    : /Mac OS X|Macintosh/i.test(agent) ? 'macOS'
    : /Android/i.test(agent) ? 'Android'
    : /Linux/i.test(agent) ? 'Linux'
    : 'Unknown';
  // Electron's user agent says Chrome too, so the runtime is asked separately.
  const shell = typeof window !== 'undefined' && window.betweenus ? 'BetweenUs' : 'Browser';
  return `${shell} on ${platform}`;
}

/**
 * Uploads a backup when the account has none for this identity and a secret is
 * available to seal it with. Never throws into a sign-in: an account without a
 * backup still works, it is only unrecoverable, and the settings panel says so.
 */
async function ensureBackup(pair: IdentityKeyPair, secret?: BackupSecret): Promise<void> {
  try {
    const { backups } = await identityBackups();
    const backedUp = backups.some((it) => it.publicKey === pair.publicKey);

    // A backup that already stands is not this machine's to replace unless it
    // is this machine's key in it. Since a machine that could not open one
    // mints its own, sealing over it here would take the account's recoverable
    // identity away from every machine still restoring from it - quietly, and
    // for good. Deliberately re-sealing is `backupIdentity`'s job, not this.
    //
    // Scoped to the *kind* now. An account that has a passphrase backup and no
    // password one is exactly the account that cannot recover on a fresh
    // sign-in, so filling that gap when the password is at hand is the point
    // rather than an overreach - and it only ever seals the key this machine
    // already holds, which is the identity the other machines restore from
    // whenever `backedUp` says so.
    if (!secret || backups.some((it) => it.kind === secret.kind) || !backedUp) {
      setIdentityStatus({
        status: 'ready',
        backedUp,
        provisional: backups.length > 0 && !backedUp,
      });
      return;
    }
    await api.putIdentityBackup(await sealIdentity(pair, secret.value, secret.kind));
    setIdentityStatus({ status: 'ready', backedUp: true });
  } catch {
    // Offline, or the server is older than this client. Nothing is lost that
    // was not already missing.
  }
}

/**
 * Seals the current identity under a secret the user chose, for an account that
 * has no password to derive from - a provider sign-in - or for anyone who would
 * rather not tie the two together.
 */
export async function backupIdentity(secret: BackupSecret): Promise<void> {
  const pair = await currentIdentity();
  await api.putIdentityBackup(await sealIdentity(pair, secret.value, secret.kind));
  setIdentityStatus({ status: 'ready', backedUp: true });
}

/**
 * Whether the account password can still recover this identity on a machine
 * that has never seen it.
 *
 * The one thing a settings panel has to be able to say plainly, because it is
 * the difference between "sign in anywhere" and "sign in anywhere and type a
 * passphrase you wrote down once".
 */
export async function passwordRecoveryEnabled(): Promise<boolean> {
  const { backups } = await identityBackups();
  return backups.some((it) => it.kind === 'password');
}

/**
 * Turns the password path off, for somebody who set a recovery passphrase
 * *because* a live server sees the password at sign-in and they would rather it
 * could not open anything.
 *
 * Refuses when it would leave the account with no backup at all, which is not a
 * security setting - it is losing every message on the next reinstall.
 */
export async function setPasswordRecovery(
  enabled: boolean,
  password?: string,
): Promise<void> {
  if (enabled) {
    if (!password) throw new Error('The account password is needed to seal a backup with it');
    await backupIdentity({ value: password, kind: 'password' });
    return;
  }
  const { backups } = await identityBackups();
  if (!backups.some((it) => it.kind === 'passphrase')) {
    throw new Error('Set a recovery passphrase first, or this account has no way back at all');
  }
  await api.deleteIdentityBackup('password');
}

/**
 * Re-seals the backup after a password change. Skipped silently when the backup
 * is keyed to a passphrase instead, which a password change does not touch.
 */
export async function rewrapBackupForPassword(newPassword: string): Promise<void> {
  const { backups } = await identityBackups();
  if (!backups.some((it) => it.kind === 'password')) return;
  await backupIdentity({ value: newPassword, kind: 'password' });
  // The secret this session holds is now the old one, and a retry that used it
  // would fail to open the blob it just re-sealed.
  signInSecret = { value: newPassword, kind: 'password' };
}

export function resetE2ee(): void {
  // Key material is per-user; a sign-out must not leak it into the next session.
  identity = null;
  identityUserId = null;
  identityReady = null;
  signInSecret = null;
  channels.clear();
  inFlight.clear();
  rekeyed.clear();
  missedEpochs.clear();
  setIdentityStatus({ status: 'absent' });
}

export async function encryptForChannel(channelId: string, plaintext: string): Promise<string> {
  const state = await ensureChannelKey(channelId);
  const key = state.keys.get(state.epoch);
  if (!key) throw new MissingChannelKeyError();
  const envelope = await encryptMessage(plaintext, key, state.epoch);
  return JSON.stringify(envelope);
}

/** Never throws: undecryptable content renders as a placeholder. */
export async function decryptForChannel(channelId: string, content: string): Promise<string> {
  const envelope = parseEnvelope(content);
  // Messages written before E2EE (and any future plaintext system message).
  if (!envelope) return content;

  try {
    const key = await keyForEpoch(channelId, envelope.epoch);
    return await decryptMessage(envelope, key);
  } catch {
    return UNDECRYPTABLE;
  }
}

/**
 * Seals a file under the channel's current key. The epoch comes back with it,
 * because the recipient has to know which generation opens it - the same
 * bookkeeping `EncryptedEnvelope` does for a message.
 */
export async function encryptFileForChannel(
  channelId: string,
  bytes: Uint8Array<ArrayBuffer>,
): Promise<{ ciphertext: Uint8Array<ArrayBuffer>; iv: string; epoch: number }> {
  const state = await ensureChannelKey(channelId);
  const key = state.keys.get(state.epoch);
  if (!key) throw new MissingChannelKeyError();
  const { iv, ciphertext } = await encryptBytes(bytes, key);
  return { ciphertext, iv, epoch: state.epoch };
}

/** Throws rather than returning a placeholder: a file either opens or it does not. */
export async function decryptFileForChannel(
  channelId: string,
  ciphertext: Uint8Array<ArrayBuffer>,
  iv: string,
  epoch: number,
): Promise<Uint8Array<ArrayBuffer>> {
  return decryptBytes(ciphertext, iv, await keyForEpoch(channelId, epoch));
}

/**
 * The channel key, for the one thing a call still needs it for: signing this
 * client's DTLS fingerprint so the signalling server cannot substitute one of
 * its own and stand in the middle of a peer connection. The media itself is
 * encrypted by DTLS-SRTP between the two peers, with no server in between to
 * keep it from - see `mesh.ts`.
 */
export async function callKeyForChannel(channelId: string, refresh = false): Promise<string> {
  // `refresh` is what a call asks for when somebody new arrives: joining a
  // channel you hold no key for mints the next epoch, so the newcomer's key is
  // a generation ahead of the one everybody in the call snapshotted. Without
  // the re-read the two sides sign with different keys and refuse each other.
  if (refresh) channels.delete(channelId);
  const state = await ensureChannelKey(channelId);
  const key = state.keys.get(state.epoch);
  if (!key) throw new MissingChannelKeyError();
  return key;
}

/**
 * Re-wraps the keys this machine holds for the machines that hold none. Called
 * when a channel is opened, so a member who joined after a key was minted -
 * and a second machine somebody signed in on yesterday - becomes able to read
 * without anyone restarting anything.
 */
export async function syncChannelKeys(channelId: string): Promise<void> {
  const state = await ensureChannelKey(channelId);
  const key = state.keys.get(state.epoch);
  if (!key) return;

  const latest = await api.channelKeys(channelId);
  if (latest.epoch !== state.epoch) return;

  // Somebody who is no longer a member holds this key, so everything sent from
  // now on has to be sealed with a different one. Rotating is a job for a
  // holder, which is us: the server has no key and could not mint one that
  // meant anything.
  if (latest.rekeyNeeded) {
    await rekeyChannel(channelId, state.epoch);
    return;
  }

  await fillGaps(channelId, state, latest);
}

/**
 * Hands every epoch this machine holds to the machines that are missing it.
 *
 * This is what makes a second device able to read *history* rather than only
 * what is written after it arrives. The old answer re-wrapped the current epoch
 * and nothing else, so a machine signing in today was missing every epoch
 * before today, could not re-wrap them for itself (it holds none of them), and
 * had nobody looking on its behalf - it minted a fresh epoch and the whole
 * conversation before that moment stayed a padlock for good.
 *
 * Failures are per epoch and never fatal. A racing rotation, a device revoked
 * between the read and the write, a member removed - each of them fails one
 * wrap, and none of them is a reason to stop opening the channel.
 */
async function fillGaps(
  channelId: string,
  state: ChannelKeyState,
  latest: ChannelKeysResponse,
): Promise<void> {
  for (const gap of latest.gaps) {
    const key = state.keys.get(gap.epoch);
    // An epoch we cannot open is not ours to hand out, and the server would
    // refuse it anyway: only a holder may add to an existing epoch.
    if (!key || gap.devices.length === 0) continue;
    try {
      await shareKey(channelId, gap.epoch, key, gap.devices);
    } catch {
      // Somebody else got there first, or one of those devices has just been
      // revoked. Either way the next open asks again.
    }
  }
}

/**
 * Mints the next epoch and seals it for the people who are members *now*.
 *
 * This is what makes removing somebody from a private channel mean anything.
 * Their key still opens every message sent before this moment - there is no
 * taking a key back off a machine, and any design that claims otherwise is
 * lying - but it opens nothing after it.
 *
 * The local state is dropped rather than extended, so the next send goes out
 * under the new epoch even if the publish raced somebody else's: whoever won,
 * the re-read finds the epoch that counts.
 */
export async function rekeyChannel(channelId: string, currentEpoch: number): Promise<void> {
  try {
    await createChannelKey(channelId, currentEpoch + 1);
  } finally {
    channels.delete(channelId);
    for (const seen of [...missedEpochs]) {
      if (seen.startsWith(`${channelId}#`)) missedEpochs.delete(seen);
    }
  }
  await ensureChannelKey(channelId);
}

/**
 * Epochs this client has already gone back to the directory for and still not
 * found. Without it, a channel with one genuinely unreadable message would
 * re-read the key directory on every render of that message.
 */
const missedEpochs = new Set<string>();

async function keyForEpoch(channelId: string, epoch: number): Promise<string> {
  const cached = channels.get(channelId)?.keys.get(epoch);
  if (cached) return cached;

  const state = await ensureChannelKey(channelId);
  const key = state.keys.get(epoch);
  if (key) return key;

  // An epoch we hold nothing for, on a channel we already loaded. Somebody
  // re-keyed it while we were holding the old one - a member who joined after
  // it was minted and could not wait for a re-wrap does exactly that - and our
  // cached state is now behind. Re-read once.
  //
  // Without this the two clients sit on different epochs until one of them is
  // restarted, each rendering the other's messages as "no key on this device",
  // and each *sending* under its own stale epoch so the other cannot read the
  // reply either. Reloading also moves this client onto the newer epoch, which
  // is what makes the next message readable in both directions.
  const seen = `${channelId}#${epoch}`;
  if (missedEpochs.has(seen)) throw new MissingChannelKeyError();
  missedEpochs.add(seen);

  channels.delete(channelId);
  const reloaded = await ensureChannelKey(channelId);
  const fresh = reloaded.keys.get(epoch);
  if (!fresh) throw new MissingChannelKeyError();

  // It was there after all, so anything else we gave up on for this channel
  // deserves another go.
  for (const key of [...missedEpochs]) {
    if (key.startsWith(`${channelId}#`)) missedEpochs.delete(key);
  }
  return fresh;
}

/**
 * Keys a channel that was just created, so it is usable by whoever opens it
 * first rather than by whoever happens to type in it first.
 */
export async function keyChannel(channelId: string): Promise<void> {
  await ensureChannelKey(channelId);
}

/**
 * Resolves the channel's key, creating and distributing one if the channel has
 * never been keyed. Concurrent callers share one round-trip.
 */
function ensureChannelKey(channelId: string): Promise<ChannelKeyState> {
  const cached = channels.get(channelId);
  if (cached) return Promise.resolve(cached);

  const existing = inFlight.get(channelId);
  if (existing) return existing;

  const pending = loadChannelKey(channelId).finally(() => inFlight.delete(channelId));
  inFlight.set(channelId, pending);
  return pending;
}

async function loadChannelKey(channelId: string): Promise<ChannelKeyState> {
  const self = await currentIdentity();
  let response = await api.channelKeys(channelId);
  let keys = await openKeys(response.keys, self);

  // We hold nothing for the current epoch. Either nobody has keyed the channel
  // yet, or - the case that used to leave a member stuck on "no channel key on
  // this device yet" - it was keyed before we joined, and every holder who
  // could re-wrap it for us is offline. Waiting on them is not a fix, so mint
  // the next epoch and wrap it for everybody, which is exactly what the server
  // lets any member with SEND_MESSAGE do. Earlier epochs are untouched, so the
  // history from before we were a member stays closed to us.
  if (!keys.has(response.epoch) && !rekeyed.has(channelId)) {
    // Marked only after the mint succeeds. Marking it first meant a transient
    // failure here - a dropped request, a moment offline - poisoned the guard
    // for the rest of the session: every later message in this channel skipped
    // straight to "no key" instead of trying again next time it was opened.
    await createChannelKey(channelId, response.epoch + 1);
    rekeyed.add(channelId);
    // Re-read rather than trusting our own write: another member may have won
    // the race, and then theirs is the epoch that counts.
    response = await api.channelKeys(channelId);
    keys = await openKeys(response.keys, self);
  }

  const state: ChannelKeyState = { epoch: response.epoch, keys };
  if (!keys.has(response.epoch)) throw new MissingChannelKeyError();

  channels.set(channelId, state);

  // Members who joined after the key was minted cannot read anything until a
  // holder re-wraps it for them. We hold it, so we do it. Older epochs are
  // `syncChannelKeys`' job - opening a channel is where that belongs, and
  // doing it here as well would publish every gap twice.
  if (response.missingRecipients.length > 0) {
    const key = keys.get(response.epoch);
    if (key) void shareKey(channelId, response.epoch, key, response.missingRecipients);
  }

  return state;
}

/** Opens every entry sealed for us, keyed by epoch. */
async function openKeys(
  entries: Array<ChannelKeyEntry & { epoch: number }>,
  self: IdentityKeyPair,
): Promise<Map<number, string>> {
  const keys = new Map<number, string>();
  for (const entry of entries) {
    try {
      keys.set(
        entry.epoch,
        await unwrapChannelKey(
          { wrappedKey: entry.wrappedKey, iv: entry.iv },
          self.privateKey,
          entry.senderPublicKey,
        ),
      );
    } catch {
      // A key sealed for another of our machines, or for an identity we have
      // since replaced. Both are rows this private half cannot open, and both
      // are ordinary: skip it, keep the rest.
    }
  }
  return keys;
}

/**
 * Mints an epoch for a channel this device holds no key for - a channel nobody
 * has keyed, or one that was keyed before we were a member.
 *
 * Any member who may send a message may do this - waiting for an admin to open
 * the channel is not a rule the server has, and pretending otherwise is what
 * made an empty channel unusable until its owner typed into it first.
 */
async function createChannelKey(channelId: string, epoch: number): Promise<void> {
  const self = await currentIdentity();
  const key = generateChannelKey();
  const devices = await api.channelDevices(channelId);

  // Our own row may not be in the directory yet on a device that signed in a
  // moment ago. Minting a key we cannot open (or, with an empty directory,
  // publishing nothing at all) leaves the channel unkeyed and the sender told
  // there is no key - so we always seal one for ourselves.
  // Our own row may not be in the directory yet on a machine that signed in a
  // moment ago, and it is now a row per *device* - being listed under our user
  // id is no longer enough, because that may be the other laptop.
  const mine = deviceId();
  const recipients = devices.some(
    (device) => device.userId === identityUserId && device.deviceId === mine,
  )
    ? devices
    : [
        ...devices,
        { userId: identityUserId ?? '', deviceId: mine, publicKey: self.publicKey },
      ];

  try {
    await shareKey(channelId, epoch, key, recipients);
  } catch (error) {
    // Another member keyed it first: harmless, loadChannelKey re-reads and
    // finds theirs. Which of the two codes comes back depends on whether they
    // landed on the epoch we wanted or ran past it. Anything else is a real
    // failure and must not be mistaken for "this device has no key".
    const raced =
      error instanceof ApiError &&
      (error.code === 'EPOCH_OUT_OF_ORDER' || error.code === 'EPOCH_NOT_HELD');
    if (!raced) throw error;
  }
}

/**
 * Seals one channel key for every device that should hold it.
 *
 * One wrap per machine rather than per person. Somebody signed in on a laptop
 * and a phone gets two entries, each sealed to that machine's own key, which is
 * what makes revoking one of them mean anything: the wraps addressed to it are
 * deleted, and it is never sealed for again.
 */
async function shareKey(
  channelId: string,
  epoch: number,
  key: string,
  recipients: Array<{ userId: string; deviceId: string; publicKey: string }>,
): Promise<void> {
  const self = await currentIdentity();

  const entries = await Promise.all(
    recipients.map(async (recipient) => {
      const wrapped = await wrapChannelKey(key, self.privateKey, recipient.publicKey);
      return {
        recipientUserId: recipient.userId,
        recipientDeviceId: recipient.deviceId,
        senderPublicKey: self.publicKey,
        wrappedKey: wrapped.wrappedKey,
        iv: wrapped.iv,
      };
    }),
  );

  if (entries.length === 0) return;
  await api.publishChannelKeys({ channelId, epoch, senderDeviceId: deviceId(), entries });
}


// --- Statuses ---------------------------------------------------------------
//
// A status has no channel, so it has no epoch and nothing to rotate: one key
// per post, wrapped once per device that may read it, and gone in a day. That
// is why none of the machinery above applies - there is no `ChannelKeyState`
// to load, no gap to fill, and no rekey.
//
// The wrap list is the audience. It is built from the directory *at the moment
// of posting*, so a friendship made afterwards adds nothing to a post already
// written, and the person who made friends today cannot open yesterday's - the
// same rule every app with this feature has, kept here by arithmetic rather
// than by trusting a server to filter.

/** A post, sealed and ready to send. */
export interface SealedStatus {
  /** The caption as an envelope, absent when there was none. */
  caption?: string;
  media?: { ciphertext: Uint8Array<ArrayBuffer>; iv: string };
  keys: StatusKeyEntry[];
  senderDeviceId: string;
}

/**
 * Seals one post for one audience.
 *
 * Our own devices are included by the server's directory, but this machine may
 * not be in it yet - a laptop that signed in a moment ago has not been listed -
 * so we always wrap for ourselves. Posting something we cannot open is the one
 * failure with no way back.
 */
export async function sealStatus(
  plain: { caption?: string; media?: Uint8Array<ArrayBuffer> },
  devices: DeviceKey[],
): Promise<SealedStatus> {
  const self = await currentIdentity();
  const key = generateChannelKey();
  const mine = deviceId();
  const recipients = devices.some(
    (device) => device.userId === identityUserId && device.deviceId === mine,
  )
    ? devices
    : [
        ...devices,
        {
          userId: identityUserId ?? '',
          deviceId: mine,
          publicKey: self.publicKey,
        } as DeviceKey,
      ];

  const keys = await Promise.all(
    recipients.map(async (device) => {
      const wrapped = await wrapChannelKey(key, self.privateKey, device.publicKey);
      return {
        recipientUserId: device.userId,
        recipientDeviceId: device.deviceId,
        senderPublicKey: self.publicKey,
        wrappedKey: wrapped.wrappedKey,
        iv: wrapped.iv,
      };
    }),
  );

  // Epoch 0 in the envelope: a status has no generations, and the field is
  // there because the envelope shape is shared with messages.
  const caption = plain.caption ? JSON.stringify(await encryptMessage(plain.caption, key, 0)) : undefined;
  const media = plain.media ? await encryptBytes(plain.media, key) : undefined;

  return {
    ...(caption ? { caption } : {}),
    ...(media ? { media: { ciphertext: media.ciphertext, iv: media.iv } } : {}),
    keys,
    senderDeviceId: mine,
  };
}

/**
 * The key to one post, from whichever wrap this machine's private half opens.
 *
 * Null rather than a throw for the ordinary cases: a post written before this
 * device existed, or before the friendship did, carries no wrap for us. Both
 * are things that happen, not errors.
 */
export async function statusKey(entry: StatusEntry): Promise<string | null> {
  if (entry.keys.length === 0) return null;
  const self = await currentIdentity();
  for (const wrap of entry.keys) {
    try {
      return await unwrapChannelKey(
        { wrappedKey: wrap.wrappedKey, iv: wrap.iv },
        self.privateKey,
        wrap.senderPublicKey,
      );
    } catch {
      // Sealed for another of our machines, or for an identity we have since
      // replaced. Ordinary: try the next.
    }
  }
  return null;
}

/** A post's caption in the clear, or the placeholder. Never throws. */
export async function openStatusCaption(entry: StatusEntry): Promise<string | null> {
  if (!entry.caption) return null;
  const envelope = parseEnvelope(entry.caption);
  // Written before statuses were sealed. It expires within the day.
  if (!envelope) return entry.caption;
  try {
    const key = await statusKey(entry);
    return key ? await decryptMessage(envelope, key) : UNDECRYPTABLE;
  } catch {
    return UNDECRYPTABLE;
  }
}

/** A post's media in the clear. Throws: a picture either opens or it does not. */
export async function openStatusMedia(
  entry: StatusEntry,
  ciphertext: Uint8Array<ArrayBuffer>,
): Promise<Uint8Array<ArrayBuffer>> {
  // No IV means it was stored in the clear, before this. Hand it back as it is.
  if (!entry.mediaIv) return ciphertext;
  const key = await statusKey(entry);
  if (!key) throw new MissingChannelKeyError();
  return decryptBytes(ciphertext, entry.mediaIv, key);
}

/** Waits for sign-in key setup instead of racing it, and retries a failed one. */
async function currentIdentity(): Promise<IdentityKeyPair> {
  if (identityReady) return identityReady;
  // With the session's secret, not without it. A retry that dropped it opened
  // no backup, minted a machine-local key, and forked the account for good.
  if (identityUserId) return initIdentity(identityUserId, signInSecret ?? undefined);
  if (identity) return identity;
  throw new MissingChannelKeyError();
}

/**
 * Private keys go through the main process, which seals them with the OS
 * keychain (Electron `safeStorage`). Outside Electron - a browser opened on the
 * Vite dev server - there is no keychain, so localStorage is the fallback.
 */
export async function secureGet(key: string): Promise<string | null> {
  const bridge = window.betweenus?.secureGet;
  if (bridge) return bridge(key);
  return localStorage.getItem(`betweenus.secure.${key}`);
}

export async function secureSet(key: string, value: string): Promise<void> {
  const bridge = window.betweenus?.secureSet;
  if (bridge) {
    await bridge(key, value);
    return;
  }
  localStorage.setItem(`betweenus.secure.${key}`, value);
}

export type { EncryptedEnvelope };

/**
 * Self-check for the address parsing behind the server picker.
 *
 * Run with `pnpm --filter @betweenus/desktop check`. Only the pure functions are
 * exercised here: everything else in endpoint.ts is localStorage and fetch.
 */
import assert from 'node:assert/strict';
import {
  MAX_RECENT_SERVERS,
  baseFromProbeUrl,
  defaultServerUrl,
  normalizeServerUrl,
  toWebSocketUrl,
  versionVerdict,
  withRecent,
} from './endpoint';

// Served over http(s) - a dev server, or the web client behind Nginx - means the
// origin is the gateway. A packaged renderer loads from file:// and falls back
// to what the build shipped with.
const asWindow = (href: string): void => {
  (globalThis as { window?: unknown }).window = { location: { origin: new URL(href).origin } };
};
asWindow('https://betweenus.example.com/');
assert.equal(defaultServerUrl(), 'https://betweenus.example.com');
asWindow('http://localhost:5173/');
assert.equal(defaultServerUrl(), 'http://localhost:5173');
(globalThis as { window?: unknown }).window = { location: { origin: 'null' } };
assert.equal(defaultServerUrl(), 'http://localhost:8080');
delete (globalThis as { window?: unknown }).window;
assert.equal(defaultServerUrl(), 'http://localhost:8080');


// What a person types, and what it has to become.
assert.equal(normalizeServerUrl('betweenus.example.com'), 'https://betweenus.example.com');
assert.equal(normalizeServerUrl('  betweenus.example.com/  '), 'https://betweenus.example.com');
assert.equal(normalizeServerUrl('http://192.168.1.4:8080'), 'http://192.168.1.4:8080');
assert.equal(normalizeServerUrl('https://example.com:8443///'), 'https://example.com:8443');
// A deployment under a path keeps it; a query or fragment is not part of a base.
assert.equal(normalizeServerUrl('https://example.com/betweenus'), 'https://example.com/betweenus');
assert.equal(normalizeServerUrl('https://example.com/betweenus/?a=1#b'), 'https://example.com/betweenus');

for (const bad of ['', '   ', 'ftp://example.com', 'https://']) {
  assert.throws(() => normalizeServerUrl(bad), Error, `should refuse ${JSON.stringify(bad)}`);
}

assert.equal(toWebSocketUrl('https://betweenus.example.com'), 'wss://betweenus.example.com');
assert.equal(toWebSocketUrl('http://127.0.0.1:8080'), 'ws://127.0.0.1:8080');
// Only the scheme changes - a host with "http" in its name is left alone.
assert.equal(toWebSocketUrl('https://http-relay.example.com'), 'wss://http-relay.example.com');

// Where the probe ended is what gets stored: a redirect to another origin would
// otherwise strip the Authorization header off every authenticated request.
const probe = '/api/v1/auth/oauth/providers';
assert.equal(
  baseFromProbeUrl(`https://betweenus.example.com${probe}`, 'http://betweenus.example.com'),
  'https://betweenus.example.com',
);
assert.equal(
  baseFromProbeUrl(`https://example.com/betweenus${probe}`, 'https://example.com/betweenus'),
  'https://example.com/betweenus',
);
// Redirected somewhere that is not the probe path: keep what was asked for.
assert.equal(baseFromProbeUrl('https://example.com/login', 'https://example.com/'), 'https://example.com');

console.log('endpoint self-check passed');

// --- The recent list --------------------------------------------------------

const A = 'https://a.example.com';
const B = 'https://b.example.com';

assert.deepEqual(withRecent([], A), [A]);
// Newest first, and connecting to one already in the list moves it rather than
// adding a second copy of it.
assert.deepEqual(withRecent([A], B), [B, A]);
assert.deepEqual(withRecent([B, A], A), [A, B]);
assert.deepEqual(withRecent([A, B], A), [A, B]);

// It does not grow without bound: the oldest falls off the end.
const many = Array.from({ length: MAX_RECENT_SERVERS }, (_, at) => `https://${at}.example.com`);
const grown = withRecent(many, 'https://new.example.com');
assert.equal(grown.length, MAX_RECENT_SERVERS);
assert.equal(grown[0], 'https://new.example.com');
assert.equal(grown.includes(many[MAX_RECENT_SERVERS - 1]!), false);

// --- Contract mismatch ------------------------------------------------------

assert.equal(versionVerdict(1, 1), null);
assert.equal(versionVerdict(2, 1), 'client-too-old');
assert.equal(versionVerdict(1, 2), 'server-too-old');
// A deployment from before this route existed says nothing, and a client that
// shouted about that would make every existing install look broken.
assert.equal(versionVerdict(null, 1), null);

/**
 * Which deployment this client talks to.
 *
 * One address is all a client needs. REST, `/ws/chat`, `/ws/presence`,
 * `/ws/call`, `/ws/remote` and the stored files are all behind the same
 * gateway, and media does not have an address at all - it goes directly to the
 * other participants. So a deployment is one URL, not a list of them.
 *
 * That address comes from `VITE_API_URL` at build time, and the login screen
 * can point this window at a different one at any time (the choice is kept in
 * localStorage, per profile). Nothing else in the client is allowed to know a
 * host: everything goes through `serverUrl`, `wsUrl` or `absoluteUrl`.
 */

const KEY = 'betweenus.serverUrl';

/** Trailing slashes make `${base}${path}` produce `//api`, which Nginx 404s. */
function trimTrailingSlash(url: string): string {
  return url.replace(/\/+$/, '');
}

/**
 * Accepts what a person types - `betweenus.example.com`, `http://192.168.1.4:8080`,
 * a pasted URL with a path and a trailing slash - and returns the base every
 * request is built on. Throws when it is not an address at all.
 */
export function normalizeServerUrl(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error('Enter a server address');

  // No scheme means https: a self-hosted instance on the public internet is the
  // common case, and http has to be asked for deliberately.
  const withScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;

  let url: URL;
  try {
    url = new URL(withScheme);
  } catch {
    throw new Error('That is not a valid address');
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new Error('The address must start with http:// or https://');
  }

  // A path is kept - a deployment may live under /betweenus behind someone's
  // existing reverse proxy - but a query or a fragment is not part of a base.
  return trimTrailingSlash(`${url.origin}${url.pathname}`);
}

/** `https://host` -> `wss://host`, which is the same gateway over a socket. */
export function toWebSocketUrl(base: string): string {
  return base.replace(/^http/i, (match) => (match === 'HTTP' ? 'WS' : 'ws'));
}

/**
 * Where this build points when nobody has chosen otherwise.
 *
 * Anything loaded over http(s) was served *by* a gateway, so that origin is the
 * answer: under `pnpm dev` the Vite dev server proxies /api and /ws straight to
 * the services (see vite.config.ts), and the web client in `apps/web` is a
 * static bundle behind the real Nginx. Both would be wrong to send elsewhere.
 *
 * Only a packaged renderer, which loads from `file://`, has no origin to go on -
 * and `VITE_API_URL` is the default it ships with. Pointing any window at a
 * different deployment is what the login screen's server picker is for.
 */
export function defaultServerUrl(): string {
  const origin = typeof window === 'undefined' ? '' : window.location.origin;
  if (/^https?:/i.test(origin)) return origin;
  const configured = import.meta.env?.VITE_API_URL?.trim();
  if (configured) return trimTrailingSlash(configured);
  return 'http://localhost:8080';
}

let cached: string | null = null;

/** The gateway base for every request this window makes. Never ends in `/`. */
export function serverUrl(): string {
  if (cached !== null) return cached;
  let stored: string | null = null;
  try {
    stored = localStorage.getItem(KEY);
  } catch {
    stored = null;
  }
  cached = stored ? trimTrailingSlash(stored) : defaultServerUrl();
  return cached;
}

/** True while this window is on the address the build shipped with. */
export function isDefaultServer(): boolean {
  return serverUrl() === defaultServerUrl();
}

/** Stores a chosen address; `null` goes back to the one the build shipped. */
export function setServerUrl(url: string | null): void {
  if (url === null) localStorage.removeItem(KEY);
  else localStorage.setItem(KEY, trimTrailingSlash(url));
  cached = null;
  rememberServer(url ?? defaultServerUrl());
}

// --- Where this client has been ---------------------------------------------

const RECENT_KEY = 'betweenus.recentServers';

/**
 * How many addresses are worth keeping.
 *
 * Long enough for the machines somebody actually has - a home server, a work
 * one, a laptop on the LAN, a staging box - and short enough that the list is
 * still something you can point at rather than search.
 */
export const MAX_RECENT_SERVERS = 6;

/**
 * Addresses this client has connected to, most recent first.
 *
 * Only one address was ever remembered, which made every other deployment a
 * thing to be typed from memory - and a self-hosted address is exactly the kind
 * of string nobody has memorised. Nothing secret is in here: an address is
 * public by the time anybody can connect to it.
 */
export function recentServers(): string[] {
  try {
    const stored: unknown = JSON.parse(localStorage.getItem(RECENT_KEY) ?? '[]');
    if (!Array.isArray(stored)) return [];
    return stored.filter((item): item is string => typeof item === 'string');
  } catch {
    return [];
  }
}

/** Puts an address at the top of the list, without duplicating it. */
export function rememberServer(url: string): void {
  const next = withRecent(recentServers(), trimTrailingSlash(url));
  try {
    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  } catch {
    // A profile with no storage keeps working; it just has no history.
  }
}

/** Drops one, for an address that has gone away or was a typo worth burying. */
export function forgetServer(url: string): void {
  const next = recentServers().filter((item) => item !== trimTrailingSlash(url));
  try {
    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  } catch {
    // As above.
  }
}

/**
 * The list with `url` at the front. Pure, because the ordering is the part with
 * a bug in it: an address connected to twice must move rather than appear
 * twice, and the list must not grow without bound.
 */
export function withRecent(existing: readonly string[], url: string): string[] {
  return [url, ...existing.filter((item) => item !== url)].slice(0, MAX_RECENT_SERVERS);
}

/** Base for the two WebSockets. Same host, same path, ws scheme. */
export function wsUrl(): string {
  return toWebSocketUrl(serverUrl());
}

/**
 * Resolves a URL the server handed back - an avatar, a server icon - against
 * the current deployment. They come back rooted at `/api/v1/uploads/...`, which
 * a packaged renderer would otherwise resolve against `file://`.
 */
export function absoluteUrl(url: string): string {
  if (/^(https?:|blob:|data:)/i.test(url)) return url;
  return `${serverUrl()}${url.startsWith('/') ? '' : '/'}${url}`;
}

/**
 * Checks an address before this window commits to it, so a typo is a message
 * under the field rather than an app that no longer starts.
 *
 * The provider list is the probe because it is the one route that is public,
 * always present, and answers with something recognisably BetweenUs.
 */
const PROBE_PATH = '/api/v1/auth/oauth/providers';

/**
 * The base a request actually landed on, given the URL the probe ended at.
 *
 * `http://host` that redirects to `https://host`, or `www.host` that redirects
 * to the apex, is a *different origin*: Chromium drops the Authorization header
 * across an origin change, so every authenticated call arrives anonymous and
 * the server answers "Missing bearer token". Storing where the probe ended
 * means nothing is ever redirected again.
 */
export function baseFromProbeUrl(probeUrl: string, fallback: string): string {
  if (!probeUrl.endsWith(PROBE_PATH)) return trimTrailingSlash(fallback);
  return trimTrailingSlash(probeUrl.slice(0, -PROBE_PATH.length));
}

// --- Whether this client and that deployment still agree ---------------------

const VERSION_PATH = '/api/v1/auth/version';

/**
 * What a client should say about a deployment it does not match.
 *
 * Null for the ordinary case, which is both ends on the same contract, and for
 * a deployment too old to answer at all - one that has never heard of the route
 * is one from before this existed, and shouting about it would make every
 * existing install look broken.
 */
export type VersionVerdict = 'client-too-old' | 'server-too-old' | null;

export function versionVerdict(server: number | null, client: number): VersionVerdict {
  if (server === null) return null;
  if (server > client) return 'client-too-old';
  if (server < client) return 'server-too-old';
  return null;
}

/**
 * Asks a deployment what it speaks. Null when it will not say - an older
 * deployment, or one that is simply unreachable, and neither is a thing to
 * refuse to start over.
 */
export async function fetchServerContract(base: string = serverUrl()): Promise<number | null> {
  try {
    const response = await fetch(`${base}${VERSION_PATH}`, {
      headers: { Accept: 'application/json' },
    });
    if (!response.ok) return null;
    const body: unknown = await response.json();
    const contract = (body as { contract?: unknown } | null)?.contract;
    return typeof contract === 'number' ? contract : null;
  } catch {
    return null;
  }
}

/** Returns the address to store, which is where the probe ended up. */
export async function probeServer(base: string): Promise<string> {
  let response: Response;
  try {
    response = await fetch(`${base}${PROBE_PATH}`, {
      headers: { Accept: 'application/json' },
    });
  } catch {
    throw new Error('Could not reach that address');
  }

  if (!response.ok) throw new Error(`That address answered ${response.status}`);

  const body: unknown = await response.json().catch(() => null);
  if (!Array.isArray(body)) throw new Error('That address is not a BetweenUs server');

  return baseFromProbeUrl(response.url, base);
}

/**
 * Keeping the keyboard inside a dialog, and putting it back afterwards.
 *
 * Twenty-two things in this client say `aria-modal="true"`, which is a promise
 * that everything behind them is inert. Nothing was enforcing it. Tab walked
 * straight out of an open dialog into the conversation underneath, focus was
 * never moved *into* the dialog when it opened, and closing one left the
 * keyboard wherever it happened to be rather than on the control that opened
 * it. Somebody using a mouse sees none of this; somebody using a screen reader
 * is told the page is blocked and then handed the page.
 *
 * ## The three things, and why each is separate
 *
 * **In on open.** A dialog nobody's focus is in is a dialog a screen reader
 * does not announce, and one Escape cannot reach if the handler is scoped.
 *
 * **Held while open.** This is the half `aria-modal` claims and cannot deliver;
 * the attribute is a hint to assistive technology and does nothing to the Tab
 * key.
 *
 * **Back on close.** The most-skipped of the three and the most disorienting
 * without: closing a dialog opened from a toolbar drops the keyboard at the top
 * of the document, so the next Tab starts the journey again.
 *
 * ## What this deliberately is not
 *
 * Not `inert` on the rest of the document, and not a rewrite onto the native
 * `<dialog showModal()>`, which would give all of this for free. Both are the
 * right answer for a client being written now; both are a change to
 * twenty-two components rather than one line added to each, and the trap is
 * what makes the claim already on those components true.
 */
import { useEffect, useRef, type RefObject } from 'react';

/**
 * Everything the Tab key can land on, in the order it would.
 *
 * `disabled` is excluded by the selector; `tabindex="-1"` is excluded because
 * it means "focusable but not tabbable", which is precisely the set Tab skips.
 * Anything not being rendered is dropped by the size test - a hidden panel
 * inside an open dialog would otherwise be a stop on a tour of nothing.
 */
const FOCUSABLE = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
  '[contenteditable="true"]',
].join(',');

function focusable(container: HTMLElement): HTMLElement[] {
  return [...container.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(
    (element) => element.offsetWidth > 0 || element.offsetHeight > 0 || element === document.activeElement,
  );
}

/**
 * Attach the returned ref to the element carrying `aria-modal="true"`.
 *
 * One hook and one `ref=` per dialog, which is the whole cost. `a11y.check.ts`
 * holds the pairing, because a dialog added next month with the attribute and
 * without the ref makes exactly the same silent promise these did.
 *
 * `active` is for the two panels that stay mounted while they are shut - the
 * mobile navigation drawer and the details sheet, which slide rather than
 * unmount. A trap that ran on those would hold the keyboard inside a drawer
 * nobody has opened. They also need `closedPanelProps`; the trap is only half
 * of what a still-mounted dialog gets wrong.
 */
export function useFocusTrap<T extends HTMLElement>(active = true): RefObject<T> {
  const ref = useRef<T>(null);

  useEffect(() => {
    const container = ref.current;
    if (!container || !active) return;

    // Where the keyboard was, so it can be put back. Read before anything is
    // focused, or the answer is the dialog itself.
    const returnTo = document.activeElement as HTMLElement | null;

    // A dialog with nothing focusable in it still has to be able to hold the
    // keyboard, or the trap has nowhere to send it.
    if (!container.hasAttribute('tabindex')) container.tabIndex = -1;

    if (!container.contains(document.activeElement)) {
      (focusable(container)[0] ?? container).focus();
    }

    /**
     * On the document and in the capture phase, not on the container: focus
     * that has already escaped - by a click on the page behind, or by a Tab
     * that got out before this mounted - would never reach a listener scoped to
     * the container, which is the one case the trap exists for.
     */
    const onKey = (event: KeyboardEvent): void => {
      if (event.key !== 'Tab') return;
      const items = focusable(container);
      if (items.length === 0) {
        event.preventDefault();
        container.focus();
        return;
      }
      const first = items[0]!;
      const last = items[items.length - 1]!;
      const focused = document.activeElement;
      const outside = !container.contains(focused);

      if (event.shiftKey ? focused === first || outside : focused === last || outside) {
        event.preventDefault();
        (event.shiftKey ? last : first).focus();
      }
    };

    document.addEventListener('keydown', onKey, true);
    return () => {
      document.removeEventListener('keydown', onKey, true);
      // Only if it is still on the page. A dialog that closed because the row
      // that opened it was deleted has nothing to go back to, and focusing a
      // detached element silently drops the keyboard on `<body>`.
      if (returnTo?.isConnected) returnTo.focus();
    };
  }, [active]);

  return ref;
}

/**
 * What a dialog that stays in the DOM while it is shut has to say about itself.
 *
 * Two panels here slide off screen with `translate-x-full pointer-events-none`
 * rather than unmounting, and both kept `role="dialog"` and
 * `aria-modal="true"` the whole time - so a screen reader on a phone was told a
 * modal dialog was open, always, and every control inside a closed drawer was
 * still a Tab stop. `pointer-events-none` stops a mouse; it does nothing to a
 * keyboard.
 *
 * `inert` is the attribute that means both at once: out of the accessibility
 * tree and out of the focus order. It is not in React 18's typings, which is
 * why this is spread rather than written inline, and it is passed as `''`
 * because that is how a bare HTML boolean attribute is written.
 */
export function closedPanelProps(open: boolean): Record<string, unknown> {
  return open ? {} : { inert: '', 'aria-hidden': true };
}

/**
 * Self-check for the player's-eye view of a game session.
 *
 * These are the sentences and the greyed-out squares, and every failure here is
 * one nobody reports as a bug: a "Your move" shown to the person who is not to
 * move reads as latency, a square that looks playable and is refused reads as a
 * broken board, and a game that accepts a move with one chair empty is somebody
 * playing themselves without noticing.
 *
 * Run with `pnpm --filter @betweenus/desktop check`.
 */
import assert from 'node:assert/strict';
import { GAMES, type GameSession } from '@betweenus/shared-types';
import { canPlayMove, seatFor, turnLineFor } from './game-view';

function session(overrides: Partial<GameSession> = {}): GameSession {
  return {
    rev: 3,
    gameId: 'tic-tac-toe',
    seats: [
      { userId: 'ana', username: 'ana' },
      { userId: 'bo', username: 'bo' },
    ],
    state: GAMES['tic-tac-toe'].create(),
    round: 1,
    wins: [0, 0],
    byUserId: 'ana',
    ...overrides,
  };
}

// --- Who am I here ----------------------------------------------------------

assert.equal(seatFor(session(), 'ana'), 0);
assert.equal(seatFor(session(), 'bo'), 1);
// Watching. Most people in a call are, so this is the ordinary answer.
assert.equal(seatFor(session(), 'cai'), -1);
assert.equal(seatFor(null, 'ana'), -1);
// Signed out, or a store that has not loaded the account yet: no seat, and no
// crash on the way to finding that out.
assert.equal(seatFor(session(), null), -1);

// --- What may be clicked ----------------------------------------------------

const fresh = session();
assert.equal(canPlayMove(fresh, 'ana', 4), true);
// Not your turn.
assert.equal(canPlayMove(fresh, 'bo', 4), false);
// Not at the table.
assert.equal(canPlayMove(fresh, 'cai', 4), false);
// Not a square.
assert.equal(canPlayMove(fresh, 'ana', 42), false);

// An empty chair is not an opponent. The gateway refuses this too; refusing it
// here is what stops the board from looking playable while it waits.
const waiting = session({ seats: [{ userId: 'ana', username: 'ana' }, null] });
assert.equal(canPlayMove(waiting, 'ana', 0), false);

// A taken square, and a finished game, are both simply not moves.
const taken = session({
  state: { ...GAMES['tic-tac-toe'].create(), cells: [0, ...Array<number>(8).fill(-1)] },
});
assert.equal(canPlayMove(taken, 'ana', 0), false);
assert.equal(canPlayMove(taken, 'ana', 1), true);

const won = session({ state: { ...GAMES['tic-tac-toe'].create(), winner: 0 } });
assert.equal(canPlayMove(won, 'ana', 0), false);

// --- What it says -----------------------------------------------------------

// Second person for the one to move, third for everybody else - the same line
// has to work for the two people playing and the four watching them.
assert.equal(turnLineFor(fresh, 'ana'), 'Your move');
assert.equal(turnLineFor(fresh, 'bo'), 'ana to move');
assert.equal(turnLineFor(fresh, 'cai'), 'ana to move');

// A chair short: nobody is to move, and saying "ana to move" there is the line
// that makes a waiting board look broken.
assert.equal(turnLineFor(waiting, 'ana'), 'Waiting for one more player');

assert.equal(turnLineFor(won, 'bo'), 'ana wins.');
// A draw belongs to nobody. `-1` next to seat 0 is exactly the confusion this
// asserts against.
const drawn = session({ state: { ...GAMES['tic-tac-toe'].create(), winner: -1 } });
assert.equal(turnLineFor(drawn, 'ana'), 'A draw.');

assert.equal(turnLineFor(null, 'ana'), '');

// A game this build has never heard of says nothing rather than guessing at a
// name for it - the panel draws its own "update to join in" instead.
assert.equal(turnLineFor(session({ gameId: 'chess' as never }), 'ana'), '');

console.log('game-view.check.ts: ok');

/**
 * What a game session looks like to one particular person.
 *
 * The board is the same for everybody; "your move", "sit here" and a greyed-out
 * square are not. All of that is a function of the session and one user id, so
 * it lives here rather than in the store: nothing in this file touches zustand,
 * the auth store or the DOM, which is what makes it checkable without a call.
 *
 * None of it is a permission check. The gateway refuses an illegal move using
 * the same rules from `@betweenus/shared-types`, and its answer is the one that
 * counts. This is so a click that is going to be ignored never leaves the
 * window - and so nobody stares at a board wondering why it will not take a
 * disc, when the real answer is that the other chair is still empty.
 */
import {
  GAMES,
  gameReady,
  gameRules,
  seatOf,
  type GameSession,
} from '@betweenus/shared-types';

/** Which seat this person is in, or -1 while they are watching. */
export function seatFor(session: GameSession | null, userId: string | null): number {
  if (!session || !userId) return -1;
  return seatOf(session, userId);
}

/** Whether this person may play `move` right now. */
export function canPlayMove(
  session: GameSession | null,
  userId: string | null,
  move: number,
): boolean {
  if (!session) return false;
  // An empty chair is not an opponent, and the gateway says so too. Without
  // this the person who opened a game could play both sides while they waited.
  if (!gameReady(session)) return false;
  const seat = seatFor(session, userId);
  if (seat === -1 || seat !== session.state.turn) return false;
  return GAMES[session.gameId].moves(session.state).includes(move);
}

/**
 * One line saying where the game is, in the words the reader needs.
 *
 * Second person for the player whose move it is and third for everybody else,
 * because the same sentence has to work for the two people playing and for the
 * four watching them.
 */
export function turnLineFor(session: GameSession | null, userId: string | null): string {
  if (!session) return '';
  const rules = gameRules(session.gameId);
  if (!rules) return '';

  if (session.state.winner !== null) {
    if (session.state.winner === -1) return 'A draw.';
    const winner = session.seats[session.state.winner];
    const name = winner?.username ?? rules.definition.seatNames[session.state.winner];
    return `${name} wins.`;
  }

  if (!gameReady(session)) {
    const empty = session.seats.filter((seat) => seat === null).length;
    return empty === 1 ? 'Waiting for one more player' : `Waiting for ${empty} players`;
  }

  const seat = seatFor(session, userId);
  if (seat === session.state.turn) return 'Your move';
  const them = session.seats[session.state.turn];
  return `${them?.username ?? rules.definition.seatNames[session.state.turn]} to move`;
}

import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  LOCALES,
  asLocale,
  direction,
  loadCatalogue,
  locale,
  preferredLocale,
  setLocale,
  t,
} from './i18n';

// --- which way a locale runs -------------------------------------------------

assert.equal(direction('en'), 'ltr');
assert.equal(direction('ar'), 'rtl');
assert.equal(direction('he'), 'rtl');

// A locale from a newer build, or a corrupted preference, is left-to-right
// rather than an exception. Nothing about a language is worth failing to draw
// the app over.
assert.equal(direction('kl'), 'ltr');
assert.equal(direction(''), 'ltr');

assert.equal(asLocale('ar'), 'ar');
assert.equal(asLocale('kl'), 'en');
assert.equal(asLocale(undefined), 'en');
assert.equal(asLocale(7), 'en');

// Every entry declares a direction, and at least one of each exists - a table
// where everything is `ltr` is one where the rtl half was never filled in.
assert.ok(LOCALES.some((entry) => entry.direction === 'rtl'));
assert.ok(LOCALES.some((entry) => entry.direction === 'ltr'));
for (const entry of LOCALES) {
  assert.equal(entry.direction, direction(entry.id), `${entry.id} agrees with direction()`);
  assert.ok(entry.label.length > 0, `${entry.id} is called something`);
}

// --- what the machine asks for ----------------------------------------------

// The primary subtag, not the whole tag: a client that ignored `ar-EG` because
// it only knows `ar` would be ignoring the point of the tag.
assert.equal(preferredLocale(['ar-EG', 'en-US']), 'ar');
assert.equal(preferredLocale(['AR']), 'ar');
assert.equal(preferredLocale(['fr-CA', 'he-IL']), 'he', 'the first *known* one wins');
assert.equal(preferredLocale(['fr-CA']), 'en');
assert.equal(preferredLocale([]), 'en');

// --- the document is pointed, and told what language it is -------------------

{
  const root = { lang: '', dir: '' };
  setLocale('ar', root);
  assert.equal(root.dir, 'rtl');
  // `lang` as well as `dir`. A screen reader picks its voice from `lang`, so an
  // Arabic interface tagged `en` is read aloud by an English synthesiser.
  assert.equal(root.lang, 'ar');
  assert.equal(locale(), 'ar');

  setLocale('en', root);
  assert.equal(root.dir, 'ltr');
  assert.equal(root.lang, 'en');
}

// --- the words ---------------------------------------------------------------

// English is the argument, not a lookup: a catalogue nobody has written yet
// renders exactly what the component would have rendered anyway. This is the
// property that makes extracting fifty screens survivable - no step of it can
// put a bare key on somebody's screen.
assert.equal(t('members.empty.title', 'Nobody here yet'), 'Nobody here yet');

loadCatalogue('ar', { 'members.empty.title': 'لا أحد هنا بعد' });
setLocale('ar');
assert.equal(t('members.empty.title', 'Nobody here yet'), 'لا أحد هنا بعد');
assert.equal(t('members.empty.hint', 'Invite somebody'), 'Invite somebody', 'untranslated falls back');
setLocale('en');
assert.equal(t('members.empty.title', 'Nobody here yet'), 'Nobody here yet');

// Named placeholders, because a translator reorders a sentence and cannot
// reorder `%s`.
assert.equal(t('x', 'Members — {count}', { count: 12 }), 'Members — 12');
assert.equal(t('x', '{a} and {b}', { a: 'one', b: 'two' }), 'one and two');
assert.equal(t('x', '{a} then {a}', { a: 'again' }), 'again then again');

// A placeholder with no variable is left standing rather than blanked. An empty
// gap says nothing about what went wrong; a literal `{count}` names it.
assert.equal(t('x', 'Members — {count}', {}), 'Members — {count}');
assert.equal(t('x', 'Members — {count}'), 'Members — {count}');

// --- the layout is written in logical properties -----------------------------

/**
 * `dir="rtl"` flips a layout only if the layout was written in terms of start
 * and end. One physical margin added later is a row that stays put inside a
 * right-to-left screen, and nothing warns anybody - so this is the half of the
 * groundwork that has to be held by a check rather than by a memory.
 *
 * Tokens rather than a parse, and the value pattern is what makes that safe: a
 * Tailwind scale value starts with a digit or a bracket, or is one of a short
 * list of words. The first version of this matched any word after the dash and
 * reported seventeen offences, every one of them the word "right-hand" or
 * "right-click" in a sentence.
 */
const VALUE = String.raw`(?:\d[\w./]*|\[[^\]\s]+\]|auto|full|px|screen|min|max|fit)(?![\w-])`;
const BEFORE = String.raw`(?<=[\s"'\`{])`;

function utility(prefix: string): RegExp {
  return new RegExp(`${BEFORE}-?${prefix}-${VALUE}`, 'g');
}

const FORBIDDEN: Array<{ pattern: RegExp; instead: string }> = [
  { pattern: utility('ml'), instead: 'ms-' },
  { pattern: utility('mr'), instead: 'me-' },
  { pattern: utility('pl'), instead: 'ps-' },
  { pattern: utility('pr'), instead: 'pe-' },
  { pattern: /(?<=[\s"'`{])text-left(?![\w-])/g, instead: 'text-start' },
  { pattern: /(?<=[\s"'`{])text-right(?![\w-])/g, instead: 'text-end' },
  { pattern: /(?<=[\s"'`{])border-l(?![\w-])/g, instead: 'border-s' },
  { pattern: /(?<=[\s"'`{])border-r(?![\w-])/g, instead: 'border-e' },
  { pattern: utility('border-l'), instead: 'border-s-' },
  { pattern: utility('border-r'), instead: 'border-e-' },
  { pattern: utility('rounded-tl'), instead: 'rounded-ss-' },
  { pattern: utility('rounded-tr'), instead: 'rounded-se-' },
  { pattern: utility('rounded-bl'), instead: 'rounded-es-' },
  { pattern: utility('rounded-br'), instead: 'rounded-ee-' },
  { pattern: utility('rounded-l'), instead: 'rounded-s-' },
  { pattern: utility('rounded-r'), instead: 'rounded-e-' },
  // Positional. `left-1/2` and `right-1/2` are exempt below.
  { pattern: utility('left'), instead: 'start-' },
  { pattern: utility('right'), instead: 'end-' },
];

/**
 * `left-1/2` paired with `-translate-x-1/2` is how a thing is centred, and it
 * is direction-neutral: `start-1/2` would move with the flip while the
 * translate did not, so the exemption is the correct answer rather than a
 * grandfathered one.
 */
const EXEMPT = new Set(['left-1/2', 'right-1/2']);

const here = fileURLToPath(new URL('.', import.meta.url));
const src = join(here, '..');

function walk(directory: string): string[] {
  return readdirSync(directory).flatMap((entry) => {
    const path = join(directory, entry);
    if (entry === 'node_modules') return [];
    if (statSync(path).isDirectory()) return walk(path);
    return /\.tsx?$/.test(entry) ? [path] : [];
  });
}

const offences: string[] = [];
for (const path of walk(src)) {
  // Both of these files discuss the patterns in prose, in backticks, which is
  // the one place a physical class name is the correct thing to write.
  if (path.endsWith('i18n.check.ts') || path.endsWith('i18n.ts')) continue;
  const lines = readFileSync(path, 'utf8').split('\n');
  lines.forEach((line, index) => {
    for (const { pattern, instead } of FORBIDDEN) {
      for (const match of line.match(pattern) ?? []) {
        if (EXEMPT.has(match)) continue;
        offences.push(`${path.slice(src.length + 1)}:${index + 1}  ${match}  ->  ${instead}`);
      }
    }
  });
}

assert.deepEqual(
  offences,
  [],
  `physical direction utilities do not flip under dir="rtl":\n  ${offences.join('\n  ')}`,
);

console.log('i18n.check.ts ok');

/**
 * Where the words live, and which way the layout runs.
 *
 * Groundwork rather than translations: nothing here ships a second language,
 * and the phase that adds one does not have to touch a single component to do
 * it. Extracting strings after another fifty screens is the expensive version
 * of this, which is why it is here now, with one language in it.
 *
 * ## Why `t(key, fallback)` and not `t(key)`
 *
 * The usual shape makes English a *lookup*, so a missing entry renders a key
 * — `chat.empty.title` on somebody's screen — and every extraction is a chance
 * to ship one. Here English is the argument: the fallback **is** the string,
 * the key names it for a translator, and a catalogue that has never been
 * written renders exactly what the component would have rendered anyway. The
 * extraction becomes incremental and cannot regress the shipping language,
 * which is the only property that makes doing it over fifty screens survivable.
 *
 * The catalogue is `Record<key, string>` per locale, and `en` is deliberately
 * empty: English is already at the call sites, and a second copy of it here is
 * a second thing to keep in step.
 *
 * ## Direction
 *
 * `dir` on `<html>` is what actually flips a layout, and it flips it only if
 * the layout was written in logical properties - `ms-2` rather than `ml-2`,
 * `text-start` rather than `text-left`, `end-0` rather than `right-0`. That
 * sweep has been done and `i18n.check.ts` holds it, because one `ml-2` added
 * later is a component that stays left-aligned inside a right-to-left screen
 * and nothing warns anybody.
 */

export type Locale = 'en' | 'ar' | 'he' | 'fa' | 'ur';

export type Direction = 'ltr' | 'rtl';

/**
 * The locales the client knows the *shape* of. Being here is not a claim that
 * anything is translated - it is a claim about which way the screen runs and
 * what the language is called, both of which are needed before a single string
 * exists.
 */
export const LOCALES: Array<{ id: Locale; label: string; direction: Direction }> = [
  { id: 'en', label: 'English', direction: 'ltr' },
  { id: 'ar', label: 'العربية', direction: 'rtl' },
  { id: 'he', label: 'עברית', direction: 'rtl' },
  { id: 'fa', label: 'فارسی', direction: 'rtl' },
  { id: 'ur', label: 'اردو', direction: 'rtl' },
];

const RTL = new Set<Locale>(['ar', 'he', 'fa', 'ur']);

/**
 * Which way this locale runs.
 *
 * Unknown reads as `ltr` rather than throwing: a locale from a newer build, or
 * a corrupted preference, is never worth failing to draw the app over - the
 * same rule `asDensity` follows.
 */
export function direction(locale: string): Direction {
  return RTL.has(locale as Locale) ? 'rtl' : 'ltr';
}

/** Whatever came out of storage, as a locale this build knows. */
export function asLocale(value: unknown): Locale {
  return LOCALES.some((entry) => entry.id === value) ? (value as Locale) : 'en';
}

/**
 * The locale the machine asks for, narrowed to one this build knows.
 *
 * `navigator.language` is a tag like `ar-EG`, so only the primary subtag is
 * looked at - a client that ignored `ar-EG` because it only knows `ar` would be
 * ignoring the whole point of the tag.
 */
export function preferredLocale(languages: readonly string[]): Locale {
  for (const tag of languages) {
    const primary = tag.toLowerCase().split('-')[0];
    const known = LOCALES.find((entry) => entry.id === primary);
    if (known) return known.id;
  }
  return 'en';
}

/**
 * A catalogue per locale: the key a component asked for, mapped to the words in
 * that language. `en` is empty on purpose - see the note at the top.
 */
export type Catalogue = Partial<Record<Locale, Record<string, string>>>;

const catalogues: Catalogue = { en: {} };

let current: Locale = 'en';

/** The locale in force. */
export function locale(): Locale {
  return current;
}

/**
 * Sets the locale and points the document the right way.
 *
 * `lang` as well as `dir`, and not as a nicety: a screen reader picks its voice
 * and its pronunciation rules from `lang`, so an Arabic interface tagged `en`
 * is read aloud by an English synthesiser. It is the cheapest accessibility
 * line in this file and the easiest one to leave out.
 */
export function setLocale(next: Locale, root?: { lang: string; dir: string }): void {
  current = next;
  const element = root ?? (typeof document === 'undefined' ? undefined : document.documentElement);
  if (!element) return;
  element.lang = next;
  element.dir = direction(next);
}

/** Adds or replaces one locale's words. The shape a translation file arrives in. */
export function loadCatalogue(target: Locale, entries: Record<string, string>): void {
  catalogues[target] = { ...catalogues[target], ...entries };
}

/**
 * The words for `key`, or `fallback` when this locale has none.
 *
 * `vars` fills `{name}` placeholders. Named rather than positional because a
 * translator reorders a sentence and cannot reorder `%s` - which is the bug
 * that positional formatting exists to produce.
 *
 * A placeholder with no matching variable is **left as it was written** rather
 * than blanked. An empty gap in a sentence says nothing about what went wrong;
 * a literal `{count}` on screen names the missing variable.
 */
export function t(key: string, fallback: string, vars?: Record<string, string | number>): string {
  const template = catalogues[current]?.[key] ?? fallback;
  if (!vars) return template;
  return template.replace(/\{(\w+)\}/g, (whole, name: string) =>
    name in vars ? String(vars[name]) : whole,
  );
}

/**
 * Self-check for the automatic idle status: `tsx src/services/idle.check.ts`.
 *
 * The decision is four lines and every way of getting it wrong is silent - a
 * status that never comes back, or one that overwrites what somebody chose - so
 * the cases are here rather than being noticed by a person wondering why their
 * dot is the wrong colour.
 */
import assert from 'node:assert/strict';
import { autoStatus, IDLE_AFTER_SECONDS } from './idle';

const T = IDLE_AFTER_SECONDS;

// Online is the one status that moves on its own.
assert.equal(autoStatus('online', 0, false), 'online');
assert.equal(autoStatus('online', T - 1, false), 'online');
assert.equal(autoStatus('online', T, false), 'idle');
assert.equal(autoStatus('online', T * 10, false), 'idle');

// ...and it comes back. A watcher that only ever goes one way is the classic
// version of this bug.
assert.equal(autoStatus('online', 0, false), 'online');

// A chosen status is never touched, in either direction: do-not-disturb does
// not decay into idle, and an idle somebody picked deliberately is not
// "corrected" back to online the moment they move the mouse.
for (const seconds of [0, T, T * 10]) {
  assert.equal(autoStatus('dnd', seconds, false), 'dnd');
  assert.equal(autoStatus('invisible', seconds, false), 'invisible');
  assert.equal(autoStatus('idle', seconds, false), 'idle');
}

// A call is presence. Twenty minutes of listening to somebody talk without
// touching the keyboard is not being away.
assert.equal(autoStatus('online', T * 10, true), 'online');
// And it does not resurrect a chosen status either.
assert.equal(autoStatus('dnd', T * 10, true), 'dnd');

// The threshold is a parameter, so a shorter one behaves the same way.
assert.equal(autoStatus('online', 30, false, 60), 'online');
assert.equal(autoStatus('online', 60, false, 60), 'idle');

console.log('idle check ok');

/**
 * Away-from-keyboard, decided by the client.
 *
 * A status was only ever what somebody picked, so "online" meant "signed in at
 * some point today" and the dot said nothing. Every other chat app answers this
 * the same way: after a while with no input, the person is idle, and the moment
 * they touch anything they are not.
 *
 * The decision is a pure function and the plumbing around it is deliberately
 * dull, because the two ways of getting it wrong are both quiet - a status that
 * never comes back from idle, and a chosen status that the client overwrites.
 */
import type { ActiveStatus } from '@betweenus/shared-types';

/**
 * Ten minutes, which is what Discord and Slack use. Long enough that reading a
 * long message does not make you disappear, short enough to mean something.
 */
export const IDLE_AFTER_SECONDS = 600;

/** How often the idle source is asked. A poll is cheap; an event does not exist. */
const POLL_MS = 30_000;

/** A browser tab counts these as somebody being there. */
const ACTIVITY_EVENTS = [
  'pointerdown',
  'pointermove',
  'keydown',
  'wheel',
  'touchstart',
  'focus',
] as const;

/**
 * What to report, given what the person chose and how long the machine has been
 * untouched.
 *
 * Only `online` is ever changed automatically. Someone who picked do-not-disturb
 * or invisible said something deliberate about how they want to appear, and an
 * idle timer is not entitled to an opinion about it - which is also why idle
 * cannot be "corrected" back to online for them.
 *
 * Being in a call counts as being there whatever the keyboard says: listening
 * to somebody talk for twenty minutes is the most present a person gets, and
 * going idle in the middle of it is the bug every version of this feature
 * ships with first.
 */
export function autoStatus(
  chosen: ActiveStatus,
  idleSeconds: number,
  inCall: boolean,
  threshold: number = IDLE_AFTER_SECONDS,
): ActiveStatus {
  if (chosen !== 'online') return chosen;
  if (inCall) return 'online';
  return idleSeconds >= threshold ? 'idle' : 'online';
}

/**
 * Seconds since this machine was last touched.
 *
 * The desktop asks the operating system, which is the only source that knows
 * about the window the person is actually working in. A browser tab has no
 * such thing and falls back to its own events, which is weaker in one specific
 * way - a tab left open while its user works in another *application* looks
 * idle - and that is the honest answer a tab can give.
 */
export function createIdleSource(): { seconds: () => Promise<number>; stop: () => void } {
  const bridge = window.betweenus;
  if (bridge?.systemIdleSeconds) {
    return { seconds: () => bridge.systemIdleSeconds().catch(() => 0), stop: () => undefined };
  }

  let lastActivity = Date.now();
  const touched = (): void => {
    lastActivity = Date.now();
  };
  const visibility = (): void => {
    if (document.visibilityState === 'visible') touched();
  };

  for (const name of ACTIVITY_EVENTS) {
    window.addEventListener(name, touched, { passive: true });
  }
  document.addEventListener('visibilitychange', visibility);

  return {
    seconds: () => Promise.resolve(Math.floor((Date.now() - lastActivity) / 1000)),
    stop: () => {
      for (const name of ACTIVITY_EVENTS) window.removeEventListener(name, touched);
      document.removeEventListener('visibilitychange', visibility);
    },
  };
}

let timer: number | null = null;
let source: ReturnType<typeof createIdleSource> | null = null;

/**
 * Starts watching, and keeps watching until `stopIdleWatch`. Safe to call twice;
 * the second call is a no-op rather than a second timer.
 *
 * `report` is handed the status to appear as, every poll. It is the store's job
 * to notice that nothing changed and send nothing, so that this stays a
 * function about time and not about sockets.
 */
export function startIdleWatch(
  report: (status: ActiveStatus) => void,
  chosen: () => ActiveStatus,
  inCall: () => boolean,
): void {
  if (timer !== null) return;
  source = createIdleSource();

  const tick = (): void => {
    void source?.seconds().then((seconds) => {
      report(autoStatus(chosen(), seconds, inCall()));
    });
  };

  timer = window.setInterval(tick, POLL_MS);
  tick();
}

export function stopIdleWatch(): void {
  if (timer !== null) window.clearInterval(timer);
  timer = null;
  source?.stop();
  source = null;
}

/**
 * Self-check for the crop-and-rotate geometry.
 *
 * Run with `pnpm --filter @betweenus/desktop check`. The property worth
 * guarding is that the frame is always covered: a scale or a clamp that is
 * wrong by a pixel is an avatar with a sliver of nothing down one side, and it
 * only shows on the pictures whose aspect ratio happens to hit it.
 */
import assert from 'node:assert/strict';
import {
  MAX_ZOOM,
  NO_EDIT,
  clampEdit,
  coverScale,
  cssTransform,
  isSideways,
  isUnedited,
  panRange,
  rotate,
  turned,
} from './image-edit';

const SQUARE = { width: 512, height: 512 };
const WIDE = { width: 4000, height: 3000 };
const TALL = { width: 1080, height: 1920 };
const FRAME = { width: 300, height: 300 };
const BANNER = { width: 320, height: 180 };

// Quarter turns wrap in both directions.
assert.equal(rotate(0, 1), 90);
assert.equal(rotate(270, 1), 0);
assert.equal(rotate(0, -1), 270);
assert.equal(rotate(180, 2), 0);

assert.equal(isSideways(90), true);
assert.equal(isSideways(270), true);
assert.equal(isSideways(0), false);
assert.deepEqual(turned(WIDE, 90), { width: 3000, height: 4000 });
assert.deepEqual(turned(WIDE, 180), { width: 4000, height: 3000 });

// Cover, never contain: at zoom 1 the picture is at least as big as the frame
// on both axes, for every picture, every frame and every turn.
for (const image of [SQUARE, WIDE, TALL, { width: 40, height: 900 }]) {
  for (const frame of [FRAME, BANNER, { width: 200, height: 400 }]) {
    for (const rotation of [0, 90, 180, 270] as const) {
      const scale = coverScale(image, frame, rotation);
      const shown = turned(image, rotation);
      assert.ok(shown.width * scale >= frame.width - 1e-9, 'covers width');
      assert.ok(shown.height * scale >= frame.height - 1e-9, 'covers height');
      // And it is the *smallest* such scale: one axis fits exactly.
      const slackX = shown.width * scale - frame.width;
      const slackY = shown.height * scale - frame.height;
      assert.ok(Math.min(slackX, slackY) < 1e-6, 'no scale to spare');
    }
  }
}

// A square picture in a square frame at zoom 1 has nowhere to go, so a drag
// does nothing rather than sliding the picture off its own frame.
assert.deepEqual(panRange(SQUARE, FRAME, NO_EDIT), { width: 0, height: 0 });
assert.deepEqual(clampEdit(SQUARE, FRAME, { ...NO_EDIT, offsetX: 90, offsetY: -90 }), NO_EDIT);

// A wide picture in a square frame slides sideways and not up.
const wideRange = panRange(WIDE, FRAME, NO_EDIT);
assert.ok(wideRange.width > 0);
assert.equal(wideRange.height, 0);

// Turned a quarter, the same picture slides up and not sideways.
const turnedRange = panRange(WIDE, FRAME, { ...NO_EDIT, rotation: 90 });
assert.equal(turnedRange.width, 0);
assert.ok(turnedRange.height > 0);

// Zoom is clamped at both ends: never below "covers the frame", never past the
// point where a photo is showing its own pixels.
assert.equal(clampEdit(SQUARE, FRAME, { ...NO_EDIT, zoom: 0.2 }).zoom, 1);
assert.equal(clampEdit(SQUARE, FRAME, { ...NO_EDIT, zoom: 99 }).zoom, MAX_ZOOM);

// Zooming in gives the picture somewhere to go, and the clamp keeps it there.
const zoomed = clampEdit(SQUARE, FRAME, { ...NO_EDIT, zoom: 2, offsetX: 10_000 });
assert.equal(zoomed.zoom, 2);
assert.ok(zoomed.offsetX > 0);
assert.equal(zoomed.offsetX, panRange(SQUARE, FRAME, zoomed).width);

// A degenerate picture must not produce NaN, which would silently blank a canvas.
assert.equal(coverScale({ width: 0, height: 0 }, FRAME, 0), 1);

// The preview's transform is the one the canvas replays, in that order.
assert.equal(
  cssTransform(SQUARE, FRAME, NO_EDIT),
  `translate(0px, 0px) scale(${300 / 512}) rotate(0deg)`,
);

assert.equal(isUnedited(NO_EDIT), true);
assert.equal(isUnedited({ ...NO_EDIT, rotation: 90 }), false);
assert.equal(isUnedited({ ...NO_EDIT, offsetX: 1 }), false);

console.log('image-edit.check.ts: ok');

/**
 * The geometry behind the crop-and-rotate screen.
 *
 * The editor draws the picture with a CSS transform and then has to reproduce
 * exactly that drawing on a canvas, or what is sent is not what was framed. So
 * the arithmetic lives here on its own, in the one form both of them use:
 *
 *     translate(offsetX, offsetY)  scale(coverScale * zoom)  rotate(rotation)
 *
 * applied about the centre of a frame the picture is centred in. CSS applies a
 * transform list right to left about the element's centre, and a canvas applies
 * `translate`/`scale`/`rotate` in call order about the current origin, so the
 * same three numbers in the same order mean the same thing to both.
 *
 * Everything here is pure. `image-edit.check.ts` is what proves the frame is
 * always covered, which is the property that decides whether a crop can show
 * blank paper down one edge.
 */

/** Quarter turns only. A free angle would need a crop box that is not the frame. */
export type Rotation = 0 | 90 | 180 | 270;

export interface Size {
  width: number;
  height: number;
}

export interface Edit {
  rotation: Rotation;
  /** Multiplies [coverScale]. 1 is "just covers the frame". */
  zoom: number;
  /** Where the picture's centre sits, in frame pixels, relative to the frame's. */
  offsetX: number;
  offsetY: number;
}

export const NO_EDIT: Edit = { rotation: 0, zoom: 1, offsetX: 0, offsetY: 0 };

/** How far a picture may be zoomed in. Past this a photo is showing its pixels. */
export const MAX_ZOOM = 5;

export function rotate(rotation: Rotation, quarterTurns: number): Rotation {
  const turns = (((rotation / 90 + quarterTurns) % 4) + 4) % 4;
  return (turns * 90) as Rotation;
}

/** True when the picture's width and height swap places on screen. */
export function isSideways(rotation: Rotation): boolean {
  return rotation === 90 || rotation === 270;
}

/** The picture's size once it has been turned, before any scaling. */
export function turned(image: Size, rotation: Rotation): Size {
  return isSideways(rotation)
    ? { width: image.height, height: image.width }
    : { width: image.width, height: image.height };
}

/**
 * The smallest scale that leaves no gap between the picture and the frame.
 *
 * `cover`, not `contain`: a crop that can show the page behind it is a crop
 * that will, and letterboxing an avatar is not something anybody asked for.
 */
export function coverScale(image: Size, frame: Size, rotation: Rotation): number {
  const shown = turned(image, rotation);
  if (shown.width <= 0 || shown.height <= 0) return 1;
  return Math.max(frame.width / shown.width, frame.height / shown.height);
}

/**
 * How far the centre may travel before an edge comes into the frame.
 *
 * Zero when the picture is exactly the size of the frame, which is the normal
 * case at zoom 1 on one of the two axes - so a picture at zoom 1 is not
 * draggable in the direction it already fits, and that is correct rather than
 * a stuck gesture.
 */
export function panRange(image: Size, frame: Size, edit: Edit): Size {
  const shown = turned(image, edit.rotation);
  const scale = coverScale(image, frame, edit.rotation) * edit.zoom;
  return {
    width: Math.max(0, (shown.width * scale - frame.width) / 2),
    height: Math.max(0, (shown.height * scale - frame.height) / 2),
  };
}

/** Holds the picture against the frame, whatever the gesture asked for. */
export function clampEdit(image: Size, frame: Size, edit: Edit): Edit {
  const zoom = Math.min(MAX_ZOOM, Math.max(1, edit.zoom));
  const range = panRange(image, frame, { ...edit, zoom });
  return {
    rotation: edit.rotation,
    zoom,
    // `+ 0` normalises the negative zero a clamp against a zero range
    // produces. It draws identically and compares as equal, but it reads as
    // "-0" everywhere it is printed, which is a confusing thing to find.
    offsetX: Math.min(range.width, Math.max(-range.width, edit.offsetX)) + 0,
    offsetY: Math.min(range.height, Math.max(-range.height, edit.offsetY)) + 0,
  };
}

/** The `transform` the preview element wears. Frame pixels throughout. */
export function cssTransform(image: Size, frame: Size, edit: Edit): string {
  const scale = coverScale(image, frame, edit.rotation) * edit.zoom;
  return (
    `translate(${edit.offsetX}px, ${edit.offsetY}px) ` +
    `scale(${scale}) rotate(${edit.rotation}deg)`
  );
}

/** True when the edit would change nothing, so the original file can be kept. */
export function isUnedited(edit: Edit): boolean {
  return edit.rotation === 0 && edit.zoom === 1 && edit.offsetX === 0 && edit.offsetY === 0;
}

/**
 * Renders the framed part of [source] at [output] pixels.
 *
 * The transform is the preview's, with one extra scale in front of it that
 * turns frame pixels into output pixels - so a 300px preview and a 1024px
 * result are the same picture, and the person who framed it is not surprised.
 */
export function drawEdit(
  context: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D,
  source: CanvasImageSource & Size,
  frame: Size,
  output: Size,
  edit: Edit,
): void {
  const scale = coverScale(source, frame, edit.rotation) * edit.zoom;
  context.save();
  context.translate(output.width / 2, output.height / 2);
  context.scale(output.width / frame.width, output.height / frame.height);
  context.translate(edit.offsetX, edit.offsetY);
  context.scale(scale, scale);
  context.rotate((edit.rotation * Math.PI) / 180);
  context.drawImage(source, -source.width / 2, -source.height / 2);
  context.restore();
}

/** Run with `tsx src/services/invite-link.check.ts`. Invite links, both ways. */
