/**
 * The markdown-ish shape of a message body.
 *
 * `message-body.ts` decides what a message *is* - words, attachments and the
 * quote above a reply. This decides how the words read: the small set of marks
 * every chat app has trained people to type, and nothing else. There is no link
 * syntax, because a bare URL is already a link on every client, and no images,
 * because an attachment is not a body.
 *
 * Headings are the one thing that depends on what is being read. A heading in a
 * chat line is shouting, so `parse` does not have them; release notes are a
 * document and are nothing but headings, so `parseNotes` does. It is the same
 * parser with one rule switched on - see the bottom of this file.
 *
 * Pure and offset-exact, which is the whole reason it is here rather than in
 * the renderer: the marks are *removed* from the text, so every span is an
 * index into the text that comes out, and the emoji splitter runs over that
 * same string afterwards. A parser that left the asterisks in would need no
 * offsets at all - and would draw them.
 *
 * Line for line the android client's `Markup.kt`. Changing one changes both,
 * or the same message reads differently on two screens.
 */

export type Style = 'bold' | 'italic' | 'strike' | 'code';

/** A style over `[start, end)` of the block's own text. */
export interface Span {
  start: number;
  end: number;
  style: Style;
}

export type Kind = 'body' | 'quote' | 'code' | 'bullet' | 'number' | 'heading';

/**
 * One block of a message.
 *
 * A list is not a block: every item is its own, and a run of them next to each
 * other is what a list *is*. That keeps this list flat - no tree, no nesting -
 * which is the whole of what a chat line needs and a fraction of what a
 * document parser would cost.
 *
 * `ordinal` is the number a `number` item is drawn with, and the level of a
 * `heading` - `## Install` is 2. Zero for everything else.
 */
export interface Block {
  kind: Kind;
  text: string;
  spans: Span[];
  ordinal: number;
}

interface Delimiter {
  token: string;
  style: Style;
}

// Longest first: `**` has to be tried before `*` or every bold is two italics
// with nothing between them.
const DELIMITERS: Delimiter[] = [
  { token: '**', style: 'bold' },
  { token: '~~', style: 'strike' },
  { token: '*', style: 'italic' },
  { token: '_', style: 'italic' },
  { token: '`', style: 'code' },
];

const ESCAPABLE = '*_~`\\>';

/**
 * A list marker, and the space after it.
 *
 * The space is what keeps `*bold*` from being a bullet: a marker glued to its
 * word is a mark, and a marker standing off from it is a list. The indent is
 * bounded at three so a deliberately indented line stays prose.
 */
const BULLET = /^ {0,3}[-*+] +(.*)$/;
const NUMBER = /^ {0,3}(\d{1,9})[.)] +(.*)$/;

/** `### Features`. The space is what keeps a `#channel` mention from being one. */
const HEADING = /^ {0,3}(#{1,6}) +(.*?)\s*#*\s*$/;

/**
 * The `| --- | --- |` under a table's header row.
 *
 * ponytail: tables are not parsed, only this line is swallowed - the rows draw
 * as the pipes they are, which is legible for the three-row table a release
 * note carries. A real table block if one ever gets wide enough to need it.
 */
const TABLE_RULE = /^ {0,3}\|[\s:|-]*-[\s:|-]*\|\s*$/;

export function parse(text: string, headings = false): Block[] {
  const blocks: Block[] = [];
  const lines = text.split('\n');
  let i = 0;

  let pending: string[] = [];
  let pendingQuote = false;

  const flush = (): void => {
    if (pending.length === 0) return;
    blocks.push(inline(pending.join('\n'), pendingQuote ? 'quote' : 'body'));
    pending = [];
    pendingQuote = false;
  };

  while (i < lines.length) {
    const line = lines[i] ?? '';

    if (line.trimStart().startsWith('```')) {
      flush();
      const fence: string[] = [];
      i++;
      while (i < lines.length && !(lines[i] ?? '').trimStart().startsWith('```')) {
        fence.push(lines[i] ?? '');
        i++;
      }
      // An unclosed fence is still a code block. Somebody who opened one and
      // hit send meant the rest to be code; drawing it as prose with three
      // backticks in front of it helps nobody.
      if (i < lines.length) i++;
      blocks.push({ kind: 'code', text: trimNewlines(fence.join('\n')), spans: [], ordinal: 0 });
      continue;
    }

    if (headings) {
      // A blank line ends a paragraph rather than sitting inside one. In a
      // message the gap is deliberate - somebody pressed return twice - but a
      // document is separated by them, and keeping them would hand every
      // paragraph a leading and trailing newline to draw.
      if (line.trim() === '') {
        flush();
        i++;
        continue;
      }
      if (TABLE_RULE.test(line)) {
        i++;
        continue;
      }
      const heading = HEADING.exec(line);
      if (heading) {
        flush();
        blocks.push(inline(heading[2] ?? '', 'heading', (heading[1] ?? '#').length));
        i++;
        continue;
      }
    }

    // A list item is its own block, so it ends whatever paragraph was being
    // gathered. Bullets first: `1.` cannot start with `-`, but a bullet line
    // can perfectly well contain a number.
    const bullet = BULLET.exec(line);
    if (bullet) {
      flush();
      blocks.push(inline(bullet[1] ?? '', 'bullet'));
      i++;
      continue;
    }

    const numbered = NUMBER.exec(line);
    if (numbered) {
      flush();
      // The run is renumbered from whatever the first item said, so the
      // `1. 1. 1.` everybody types comes out 1, 2, 3 - and a list that
      // deliberately starts at 5 still starts at 5.
      const previous = blocks[blocks.length - 1];
      const ordinal =
        previous && previous.kind === 'number'
          ? previous.ordinal + 1
          : Number.parseInt(numbered[1] ?? '1', 10) || 1;
      blocks.push(inline(numbered[2] ?? '', 'number', ordinal));
      i++;
      continue;
    }

    const quoted = line.startsWith('> ') || line === '>';
    const body = quoted ? line.replace(/^>( )?/, '') : line;

    // A run of lines is one block only while they agree about being quoted;
    // the marker changing is a new block.
    if (pending.length > 0 && quoted !== pendingQuote) flush();
    pendingQuote = quoted;
    pending.push(body);
    i++;
  }
  flush();

  return blocks;
}

/** `trim('\n')`, which JavaScript has no single call for. */
function trimNewlines(text: string): string {
  return text.replace(/^\n+/, '').replace(/\n+$/, '');
}

function inline(source: string, kind: Kind, ordinal = 0): Block {
  const out = { text: '' };
  const spans: Span[] = [];
  scan(source, out, spans);
  return { kind, text: out.text, spans, ordinal };
}

/**
 * `out` is a holder rather than a plain string because a span's offsets are
 * measured against everything written so far, including by the recursive call
 * that handles a nested style - so the writer has to be shared, not copied.
 */
function scan(source: string, out: { text: string }, spans: Span[]): void {
  let i = 0;

  while (i < source.length) {
    const c = source[i] ?? '';

    if (c === '\\' && i + 1 < source.length && ESCAPABLE.includes(source[i + 1] ?? '')) {
      out.text += source[i + 1] ?? '';
      i += 2;
      continue;
    }

    const opener = openerAt(source, i);
    if (opener) {
      const from = i + opener.token.length;
      const close = source.indexOf(opener.token, from);
      if (close > from) {
        const start = out.text.length;
        const content = source.slice(from, close);
        // Code is literal: a backtick span is where somebody puts the
        // asterisks they do not want eaten.
        if (opener.style === 'code') out.text += content;
        else scan(content, out, spans);
        spans.push({ start, end: out.text.length, style: opener.style });
        i = close + opener.token.length;
        continue;
      }
    }

    out.text += c;
    i++;
  }
}

function openerAt(source: string, at: number): Delimiter | null {
  for (const delimiter of DELIMITERS) {
    if (!source.startsWith(delimiter.token, at)) continue;
    // `snake_case_names` are not two italics. An underscore only opens when it
    // is not glued to a word on its left, which is the rule that keeps
    // identifiers readable without a backtick round them.
    if (delimiter.token === '_' && at > 0 && /[\p{L}\p{N}]/u.test(source[at - 1] ?? '')) continue;
    return delimiter;
  }
  return null;
}

/**
 * A style over `[start, end)` of the text exactly as it was typed, marks and
 * all. `mark` is the delimiter itself - the asterisks, the bullet, the fence.
 */
export type HighlightStyle = Style | 'mark';

export interface Highlight {
  start: number;
  end: number;
  style: HighlightStyle;
}

/**
 * The same marks, found in the text somebody is still typing.
 *
 * Separate from `parse`, and deliberately so. `parse` takes the marks *out*,
 * which is right for drawing a message that has been sent and wrong for a box
 * somebody is typing in: text that reflows out from under the caret as a
 * second asterisk lands is unusable. So these offsets are into the original
 * string, nothing is removed, and the marks are reported as spans of their own
 * for the composer to draw quietly rather than hide.
 *
 * That also means the caret never has to be mapped between two strings, which
 * is the bug this shape exists to avoid.
 */
export function highlight(text: string): Highlight[] {
  const out: Highlight[] = [];
  let at = 0;
  let fenced = false;

  for (const line of text.split('\n')) {
    const end = at + line.length;

    if (line.trimStart().startsWith('```')) {
      out.push({ start: at, end, style: 'mark' });
      fenced = !fenced;
    } else if (fenced) {
      out.push({ start: at, end, style: 'code' });
    } else {
      // Everything in front of the content is the marker, whichever kind it
      // is - the same rule `continueList` rebuilds a marker with.
      let prefix = 0;
      if (line === '>') {
        prefix = 1;
      } else if (line.startsWith('> ')) {
        prefix = 2;
      } else {
        const bullet = BULLET.exec(line);
        const numbered = bullet ? null : NUMBER.exec(line);
        const content = bullet ? bullet[1] : numbered ? numbered[2] : undefined;
        if (content !== undefined) prefix = line.length - content.length;
      }
      if (prefix > 0) out.push({ start: at, end: at + prefix, style: 'mark' });
      scanSource(text, at + prefix, end, out);
    }

    at = end + 1;
  }

  return out;
}

/** `scan`, but reporting where it looked rather than what it produced. */
function scanSource(text: string, from: number, to: number, out: Highlight[]): void {
  let i = from;
  while (i < to) {
    if (text[i] === '\\' && i + 1 < to && ESCAPABLE.includes(text[i + 1] ?? '')) {
      out.push({ start: i, end: i + 2, style: 'mark' });
      i += 2;
      continue;
    }

    const opener = openerAt(text, i);
    if (opener) {
      const contentFrom = i + opener.token.length;
      const close = text.indexOf(opener.token, contentFrom);
      // Bounded by the line: a mark does not reach across a newline, and
      // without this an unclosed `*` would style the rest of the message.
      if (close > contentFrom && close + opener.token.length <= to) {
        out.push({ start: i, end: contentFrom, style: 'mark' });
        out.push({ start: contentFrom, end: close, style: opener.style });
        if (opener.style !== 'code') scanSource(text, contentFrom, close, out);
        out.push({ start: close, end: close + opener.token.length, style: 'mark' });
        i = close + opener.token.length;
        continue;
      }
    }

    i++;
  }
}

/**
 * Whether return should make a newline here rather than send the message.
 *
 * True inside the three things that are written across more than one line: an
 * open fence, a list, a quote. Sending a code block one line at a time is not
 * something anybody wants, and neither is reaching for shift on every item of
 * a list they are plainly in the middle of writing.
 *
 * Desktop only, unlike the rest of this module: on android return already
 * makes a newline and the button is what sends, so there is no decision to
 * make.
 */
export function wantsNewline(text: string, caret: number): boolean {
  // An odd number of fences behind the caret means the last one is still open.
  const fences = text
    .slice(0, caret)
    .split('\n')
    .filter((line) => line.trimStart().startsWith('```')).length;
  if (fences % 2 === 1) return true;

  const line = text.slice(text.lastIndexOf('\n', caret - 1) + 1, caret);
  return BULLET.test(line) || NUMBER.test(line) || line.startsWith('> ') || line === '>';
}

/** The box's text and where the caret sits in it, after a newline was typed. */
export interface Continuation {
  text: string;
  caret: number;
}

/**
 * What a newline typed inside a list should do.
 *
 * Null for an ordinary newline anywhere else - the caller then does nothing
 * and the box behaves as it always did. This is what makes a list feel like a
 * list while it is being written rather than only once it has been sent:
 * typing `- eggs` and pressing return offers the next bullet, the way every
 * editor anybody has used does.
 *
 * An empty item ends the list instead of offering another one. Without that,
 * the only way out of a list is to delete a marker somebody never typed, which
 * is the single thing that makes auto-continuation infuriating rather than
 * helpful.
 *
 * Pure, and separate from the two composers that call it, because the rule is
 * fiddly and identical on both.
 */
export function continueList(text: string, caret: number): Continuation | null {
  const from = text.lastIndexOf('\n', caret - 1) + 1;
  const line = text.slice(from, caret);

  const bullet = BULLET.exec(line);
  const numbered = bullet ? null : NUMBER.exec(line);
  if (!bullet && !numbered) return null;

  // An empty item is somebody asking to stop. The marker goes, and with it
  // the item they were about to write.
  const content = bullet ? bullet[1] : numbered![2];
  if ((content ?? '').trim().length === 0) {
    const without = text.slice(0, from) + text.slice(caret);
    return { text: without, caret: from };
  }

  // The content is the tail of the line by construction, so whatever is in
  // front of it is exactly the marker - indent, bullet character and spacing
  // included. Rebuilding it from the parts would quietly normalise all three.
  const prefix = line.slice(0, line.length - (content ?? '').length);
  const marker = bullet
    ? prefix
    : prefix.replace(/\d{1,9}/, String((Number.parseInt(numbered![1] ?? '1', 10) || 1) + 1));
  const inserted = `\n${marker}`;
  return {
    text: text.slice(0, caret) + inserted + text.slice(caret),
    caret: caret + inserted.length,
  };
}

/** Whether anything at all would be drawn differently. Saves a rebuild. */
export function isPlain(text: string): boolean {
  if (/[*_~`\\]/.test(text)) return false;
  return text
    .split('\n')
    .every((line) => !(line.startsWith('> ') || line === '>' || BULLET.test(line) || NUMBER.test(line)));
}

/**
 * The same parser, reading a document rather than a chat line.
 *
 * Release notes are `### Features` and a list under it, which `parse` would
 * draw as a line beginning with three hashes. This is the only caller that
 * wants headings, and chat is the only one that must not have them.
 */
export function parseNotes(text: string): Block[] {
  return parse(text, true);
}

/** A stretch of text over which exactly the same set of styles is active. */
export interface Run {
  text: string;
  styles: Style[];
}

/**
 * Cuts a block's text into runs of uniform styling.
 *
 * Spans nest - bold around italic is two spans over overlapping ranges - so
 * this cannot walk them one at a time. It asks each character which styles
 * cover it and groups the neighbours that agree, which is the one approach
 * that handles nesting without building a tree.
 *
 * Here rather than in a renderer because both of them need it: the message
 * list lays emoji and link previews over these runs, and the release notes
 * draw them plain.
 */
export function styleRuns(text: string, spans: Span[]): Run[] {
  if (spans.length === 0) return text ? [{ text, styles: [] }] : [];

  const runs: Run[] = [];
  let current: Run | null = null;

  for (let at = 0; at < text.length; at++) {
    const styles = spans.filter((span) => at >= span.start && at < span.end).map((span) => span.style);
    const key = styles.join(',');
    if (current && current.styles.join(',') === key) {
      current.text += text[at];
    } else {
      current = { text: text[at] ?? '', styles };
      runs.push(current);
    }
  }
  return runs;
}

/**
 * Self-check for "is that peer still sharing".
 *
 * The first case is the bug this was written for: a share of a screen nobody
 * is touching decodes no frames, and answering "still sharing?" from frames
 * closed the stage under whoever was watching it.
 *
 * Run with `pnpm --filter @betweenus/desktop check`.
 */
import assert from 'node:assert/strict';
import { visibleVideo } from './media-presence';

const track = { id: 'a screen' };

// Still share, owner says it is on: it stays on screen however long it has
// been since a frame.
assert.equal(visibleVideo(true, track), track);

// They stopped sharing. The track object can outlive that - nothing removes it
// from the slot - so the declared state is what has to take it down.
assert.equal(visibleVideo(false, track), null);

// Their first media state has not landed yet. What arrived is the best answer
// there is, and it is the one the old behaviour gave.
assert.equal(visibleVideo(undefined, track), track);

// Nothing has ever arrived on the slot: there is nothing to show, whatever
// anybody says about it.
assert.equal(visibleVideo(true, null), null);
assert.equal(visibleVideo(undefined, null), null);

console.log('media-presence check ok');

/**
 * Self-check for mention detection: `tsx src/services/mentions.check.ts`.
 *
 * The failure that matters is a prefix match - `@ann` firing for `@anna` - a
 * mentions-only channel then being noisier than the channel it was meant to
 * quieten, which is a bug nobody reports because it looks like the feature not
 * working rather than a rule being wrong.
 */
import assert from 'node:assert/strict';
import { mentionsMe } from './mentions';

const me = { username: 'ann', displayName: 'Ann Wexford' };

// The plain cases.
assert.equal(mentionsMe('@ann can you look at this', me), true);
assert.equal(mentionsMe('hey @ann', me), true);
assert.equal(mentionsMe('(@ann)', me), true);
assert.equal(mentionsMe('@ann, when you have a minute', me), true);
assert.equal(mentionsMe('nothing to do with you', me), false);

// Case does not matter.
assert.equal(mentionsMe('@ANN look', me), true);
assert.equal(mentionsMe('@Ann Wexford please', me), true);

// A longer name that starts with mine is somebody else.
assert.equal(mentionsMe('@anna said no', me), false);
assert.equal(mentionsMe('@annie is here', me), false);

// The name without the @ is just a word.
assert.equal(mentionsMe('ann said no', me), false);

// An email address is not a mention, and neither is a run-together pair.
assert.equal(mentionsMe('write to bob@ann.example', me), false);

// Broadcasts address everybody, including me.
assert.equal(mentionsMe('@everyone standup in five', me), true);
assert.equal(mentionsMe('@here quick question', me), true);
assert.equal(mentionsMe('@everyones problem', me), false);

// Nothing to read is not a mention: an undecryptable message and an empty one
// both arrive here.
assert.equal(mentionsMe(null, me), false);
assert.equal(mentionsMe('', me), false);

// An account with no display name still matches on its username, and an empty
// display name is not a name that matches everything.
assert.equal(mentionsMe('@ann hello', { username: 'ann' }), true);
assert.equal(mentionsMe('@ hello', { username: 'ann', displayName: '' }), false);

console.log('mentions check ok');

/**
 * Whether a message is addressed at you.
 *
 * This has to live in the client, and that is not a shortcut: a message body is
 * sealed with the channel key, so no service can read one and none of them can
 * be asked "was I mentioned". The window that decrypted the message is the only
 * thing in the system able to answer, so it answers, and the preference it
 * checks the answer against is all the server stores.
 *
 * The rules are Discord's, minus the ids: a mention is `@` followed by a
 * username or a display name, or one of the two broadcasts.
 */

/** `@everyone` and `@here` both address the room. */
const BROADCASTS = ['everyone', 'here'];

/** Characters that may sit either side of a name without breaking the mention. */
const BOUNDARY = /[\s.,:;!?'"()[\]{}<>@-]/;

export interface MentionTarget {
  username: string;
  displayName?: string | null;
}

/**
 * True when `text` mentions `me`.
 *
 * Names are matched case-insensitively and have to end on a boundary, so
 * `@ann` does not fire for `@anna` - the failure that makes a mentions-only
 * channel noisier than the channel it was supposed to quieten.
 *
 * A display name may contain spaces and is matched as written; Discord solves
 * this with ids in the wire format, which is the better answer and needs a
 * message format change on every client to get.
 */
export function mentionsMe(text: string | null | undefined, me: MentionTarget): boolean {
  if (!text) return false;
  const haystack = text.toLowerCase();

  const names = [me.username, me.displayName, ...BROADCASTS]
    .filter((name): name is string => typeof name === 'string' && name.trim().length > 0)
    .map((name) => name.trim().toLowerCase());

  return names.some((name) => hasMention(haystack, name));
}

function hasMention(haystack: string, name: string): boolean {
  const needle = `@${name}`;
  let from = 0;

  for (;;) {
    const at = haystack.indexOf(needle, from);
    if (at === -1) return false;

    const before = at === 0 ? '' : haystack[at - 1]!;
    const after = haystack[at + needle.length] ?? '';

    // An `@` immediately before is an email address or a second mention run
    // together; either way this is not the name being addressed.
    const openedCleanly = before === '' || (BOUNDARY.test(before) && before !== '@');
    const closedCleanly = after === '' || BOUNDARY.test(after);
    if (openedCleanly && closedCleanly) return true;

    from = at + 1;
  }
}

/**
 * Self-check for the pure parts of the mesh.
 *
 * Three things here fail silently in the worst possible way, which is why they
 * are the ones pinned down:
 *
 * - **The fingerprint signature.** If `fingerprintOf` stops matching what
 *   Chromium emits, `verifyFingerprint` refuses every peer and nobody can call
 *   anybody. If it matches too loosely - the wrong line, a partial hash - it
 *   accepts a fingerprint the channel key never signed, which is the whole
 *   attack it exists to stop, and a working call looks identical either way.
 * - **The Opus patch.** A missing `stereo=1` is a mono call that nobody can
 *   tell is wrong except by listening to music on it.
 * - **Politeness.** Two peers that agree on who is polite deadlock or glare.
 *   The rule has to be antisymmetric, and it is one comparison, so it is easy
 *   to get backwards and impossible to notice until two people call at once.
 * - **The re-read on a rotated key.** A member joining a channel it holds no
 *   key for mints the next epoch, so everybody already in the call is one
 *   generation behind. Without the re-read every fingerprint is refused and
 *   the call never connects - which is the bug this was written for.
 *
 * Run with `pnpm --filter @betweenus/desktop check`.
 */
import assert from 'node:assert/strict';
import { webcrypto } from 'node:crypto';
import {
  fingerprintOf,
  patchOpus,
  signFingerprint,
  verifyFingerprint,
  verifyFingerprintWithRefresh,
} from './mesh';

// The module reaches for the browser's crypto and btoa; Node has both, under
// slightly different names.
if (!globalThis.crypto) {
  Object.defineProperty(globalThis, 'crypto', { value: webcrypto });
}

/** A trimmed but structurally real offer, of the shape Chromium produces. */
const SDP = [
  'v=0',
  'o=- 4611731400430051336 2 IN IP4 127.0.0.1',
  's=-',
  't=0 0',
  'a=group:BUNDLE 0 1 2 3',
  'm=audio 9 UDP/TLS/RTP/SAVPF 111',
  'c=IN IP4 0.0.0.0',
  'a=ice-ufrag:4ZcD',
  'a=ice-pwd:2/1muCWoOi3uLifh0NuRHlZw',
  'a=fingerprint:sha-256 D2:FA:0E:C3:22:59:5E:14:95:69:92:3D:13:B4:84:1A:AA:BB:CC:DD:EE:FF:00:11:22:33:44:55:66:77:88:99',
  'a=setup:actpass',
  'a=mid:0',
  'a=rtpmap:111 opus/48000/2',
  'a=fmtp:111 minptime=10;useinbandfec=1',
  '',
].join('\r\n');

const KEY = 'a-channel-key-nobody-else-holds';

async function theFingerprintIsFoundAndSigned(): Promise<void> {
  const fingerprint = fingerprintOf(SDP);
  assert.equal(
    fingerprint,
    'sha-256 D2:FA:0E:C3:22:59:5E:14:95:69:92:3D:13:B4:84:1A:AA:BB:CC:DD:EE:FF:00:11:22:33:44:55:66:77:88:99',
    'the hash algorithm and the whole hash, or a substituted one could match a prefix',
  );

  assert.equal(fingerprintOf('v=0\r\ns=-\r\n'), null, 'no fingerprint is not an empty string');

  assert.equal(await verifyFingerprint(KEY, SDP, await signFingerprint(KEY, fingerprint!)), true);
}

/** The attack, spelled out: the relay swaps the fingerprint and keeps the proof. */
async function aSubstitutedFingerprintIsRefused(): Promise<void> {
  const proof = await signFingerprint(KEY, fingerprintOf(SDP)!);
  const tampered = SDP.replace('D2:FA', 'FF:EE');

  assert.notEqual(fingerprintOf(tampered), fingerprintOf(SDP), 'the test would prove nothing');
  assert.equal(
    await verifyFingerprint(KEY, tampered, proof),
    false,
    'a fingerprint the channel key did not sign must never be connected to',
  );
}

async function anotherChannelsKeyDoesNotOpenThisCall(): Promise<void> {
  const proof = await signFingerprint('some-other-channels-key', fingerprintOf(SDP)!);
  assert.equal(await verifyFingerprint(KEY, SDP, proof), false);
}

async function nothingVerifiableIsNeverAccepted(): Promise<void> {
  // No fingerprint line at all, and an empty proof: the two ways a peer could
  // try to skip the check rather than fail it.
  assert.equal(await verifyFingerprint(KEY, 'v=0\r\n', ''), false);
  assert.equal(await verifyFingerprint(KEY, SDP, ''), false);
}

function opusOptionsLandOnTheRightPayload(): void {
  const stereo = patchOpus(SDP, { maxBitrate: 128_000, stereo: true, dtx: false, red: true });
  assert.match(stereo, /a=fmtp:111 minptime=10;useinbandfec=1;stereo=1;sprop-stereo=1;usedtx=0/);
  assert.match(stereo, /maxaveragebitrate=128000/);
  // The existing options survive: dropping `useinbandfec` would cost error
  // concealment on every call.
  assert.match(stereo, /useinbandfec=1/);

  const speech = patchOpus(SDP, { maxBitrate: 64_000, stereo: false, dtx: true, red: true });
  assert.match(speech, /stereo=0;sprop-stereo=0;usedtx=1/);
}

function anSdpWithNoOpusIsLeftAlone(): void {
  const videoOnly = 'v=0\r\nm=video 9 UDP/TLS/RTP/SAVPF 96\r\na=rtpmap:96 VP8/90000\r\n';
  assert.equal(
    patchOpus(videoOnly, { maxBitrate: 64_000, stereo: false, dtx: true, red: true }),
    videoOnly,
    'a screen-only connection must not be corrupted by an audio patch',
  );
}

/**
 * The politeness rule, which lives in the PeerLink constructor as
 * `selfPeerId > peer.peerId`. Restated here because what matters is not the
 * comparison but that the two ends always disagree about it.
 */
function politenessIsAntisymmetric(): void {
  const polite = (self: string, other: string): boolean => self > other;

  const a = '0f1c2d3e-aaaa-4bbb-8ccc-111111111111';
  const b = '9a8b7c6d-eeee-4fff-8000-222222222222';

  assert.notEqual(polite(a, b), polite(b, a), 'exactly one of the two yields, or they deadlock');
  assert.equal(polite(a, a), false, 'a peer never connects to itself, but the rule stays total');
}

/**
 * The newcomer's rotation: they arrive holding the epoch they just minted, and
 * this client is still on the one before it. The first check fails, the
 * re-read hands over the epoch they signed with, and the peer connects.
 */
async function aRotatedChannelKeyIsPickedUpOnce(): Promise<void> {
  const rotated = 'the-epoch-the-newcomer-just-minted';
  const proof = await signFingerprint(rotated, fingerprintOf(SDP)!);

  let reads = 0;
  const channelKey = async (refresh?: boolean): Promise<string> => {
    reads += 1;
    return refresh ? rotated : KEY;
  };

  assert.equal(await verifyFingerprintWithRefresh(channelKey, SDP, proof), true);
  assert.equal(reads, 2, 'the stale key is tried first, then exactly one re-read');

  // And the re-read is not a way in: a proof signed with no key of this
  // channel's stays refused however many epochs are fetched.
  reads = 0;
  const forged = await signFingerprint('some-other-channels-key', fingerprintOf(SDP)!);
  assert.equal(await verifyFingerprintWithRefresh(channelKey, SDP, forged), false);
  assert.equal(reads, 2, 'and it never re-reads more than once');
}

async function main(): Promise<void> {
  await theFingerprintIsFoundAndSigned();
  await aSubstitutedFingerprintIsRefused();
  await anotherChannelsKeyDoesNotOpenThisCall();
  await nothingVerifiableIsNeverAccepted();
  opusOptionsLandOnTheRightPayload();
  anSdpWithNoOpusIsLeftAlone();
  politenessIsAntisymmetric();
  await aRotatedChannelKeyIsPickedUpOnce();
  console.log('mesh self-check passed');
}

void main();

/**
 * The peer connections a call is made of.
 *
 * There is no media server. Everyone in a call holds one `RTCPeerConnection`
 * per other participant - a full mesh - and voice, video and screen share go
 * directly between the two machines. `call-service` introduces the peers over
 * `/ws/call` and then has nothing further to do with the call; see
 * `call.gateway.ts` for the other half.
 *
 * Five things here are worth understanding before changing any of it.
 *
 * ## Fixed transceiver slots
 *
 * Every connection is built with exactly four transceivers, always in the same
 * order: microphone, camera, screen, screen audio. They are created empty and
 * stay for the life of the connection; turning a device on is `replaceTrack` on
 * a sender that already exists.
 *
 * That buys two things. Media that arrives can be identified by which slot it
 * came in on, with no side-channel to race against - the alternative is
 * announcing "the track you are about to receive is my screen" over the data
 * channel and hoping it lands first. And toggling a microphone, a camera or a
 * share never renegotiates: after the initial exchange, a call this size
 * usually never sends another offer.
 *
 * Only one side creates them: the impolite one. The other adopts the four the
 * offer brings with it - see `adopt`. Both sides creating their own is the
 * shape this file had when a call connected, showed everybody, and carried no
 * media at all: two sets of four m-lines that no offer could pair up, so every
 * arriving track landed on a transceiver the receiving side did not recognise
 * and was thrown away.
 *
 * ## Perfect negotiation
 *
 * Either side may find it needs to offer, and if both do at once the connection
 * would break. The standard answer is that one peer is "polite": it rolls back
 * its own offer when one arrives mid-flight, and the impolite peer's offer
 * wins. Politeness is decided by comparing peer ids, which both sides can do
 * without agreeing anything.
 *
 * ## The fingerprint signature
 *
 * An offer carries the DTLS fingerprint the far side will trust, and the offer
 * travels through `call-service`. A malicious signalling server could put its
 * own fingerprint in each direction and sit in the middle of a connection both
 * ends believe is direct - which would undo the whole point of not having a
 * server in the path.
 *
 * So each peer sends `HMAC-SHA256(channel key, its own fingerprint)` beside the
 * SDP, and the receiver recomputes it before accepting. The channel key is the
 * one the channel's messages are encrypted with; the server has never held it
 * and cannot produce the signature for a fingerprint of its own. A signal that
 * does not verify is dropped, and the peer connection is never established.
 *
 * ## Nothing is given up on quickly
 *
 * A link that stops carrying media is not a link that is over. It gets a grace
 * period, then backed-off ICE restarts under the policy in `call-recovery.ts`,
 * and if those are spent it is *still* left in the mesh - because nothing here
 * ever re-adds a link, so removing one is permanent, and a pair that ends up
 * unrecoverable from this side may be perfectly fine from every other. Who is
 * in a call is the roster's answer, never a link's guess.
 *
 * The signalling socket gets the same treatment. It is not in the media path,
 * so losing it stops nothing that is already connected; it reconnects quietly
 * and resumes the seat the gateway held for it, and only a loss that outlasts
 * `SIGNALLING_DEADLINE_MS` ends the call.
 *
 * ## Nothing here throws into the UI
 *
 * A peer in trouble is one tile, not the call. Trouble is reported through
 * `onProblem` and the rest of the mesh carries on.
 */
import type {
  CallLinkReport,
  CallPeer,
  CallSignal,
  ClientCallEvent,
  IceCandidatePayload,
  GameSession,
  IceServer,
  ListenSession,
  ServerCallEvent,
} from '@betweenus/shared-types';
import type { ClockSample } from './listen-sync';
import { serialize } from './signal-queue';
import { wsUrl } from './endpoint';
import { deviceId } from './e2ee';
import {
  PLAYOUT_DELAY,
  patchVideoBandwidth,
  sortPreferredVideoCodecs,
  type SharePublish,
} from './share-quality';
import type { MicEncoding } from './voice-quality';
import { toStats, type LinkSample, type LinkStats } from './call-stats';
import {
  GRACE_MS,
  SIGNALLING_DEADLINE_MS,
  backoffMs,
  restarts,
  signallingBackoffMs,
  spent,
} from './call-recovery';

/** The Listen Together half of the client protocol, so the store cannot send anything else. */
export type ListenClientEvent = Extract<ClientCallEvent, { type: `listen.${string}` }>;

/** The Play Together half, on the same terms. */
export type GameClientEvent = Extract<ClientCallEvent, { type: `game.${string}` }>;

/** What a slot carries. The order is the transceiver order and is load-bearing. */
export const SLOTS = ['mic', 'camera', 'screen', 'screenAudio'] as const;
export type Slot = (typeof SLOTS)[number];

const SLOT_KIND: Record<Slot, 'audio' | 'video'> = {
  mic: 'audio',
  camera: 'video',
  screen: 'video',
  screenAudio: 'audio',
};

/** How often remote audio levels are read, for the speaking ring. */
const SPEAKING_POLL_MS = 200;

/**
 * How long an offer may go unanswered before it is sent again. See `chase`.
 *
 * Long enough that a slow answer is not chased - the far end has a key read and
 * an `adopt` to do first - and short enough that nobody sits looking at
 * "Connecting…" wondering whether to leave.
 */
const CONNECT_DEADLINE_MS = 8_000;

/** How many times an unanswered offer is sent again before giving up. */
const CONNECT_ATTEMPTS = 4;

/**
 * How many times one link is torn down and built again from nothing.
 *
 * This is the thing people were doing by hand. Without a relay there are pairs
 * of networks that cannot form a direct path at all, and there are pairs that
 * merely *did not* - a candidate that lost a race, a NAT binding that landed on
 * a port the far end had already given up on. The two are indistinguishable
 * from in here, and the only move that separates them is trying again with
 * fresh ports, which is exactly what leaving the call and rejoining did.
 *
 * An ICE restart is not that move. It reuses the connection, and a connection
 * whose ports are the problem restarts onto the same problem. Only a new
 * `RTCPeerConnection` gathers genuinely new candidates.
 *
 * Three, because each one is only reached after a whole recovery budget has
 * been spent - four ICE restarts and thirty seconds - so three rebuilds is
 * three complete, independent failures. A pair that cannot manage it in three
 * is a pair with no path, and going round again would be a spinner pretending
 * otherwise.
 *
 * ponytail: a flat cap for the life of the call rather than one that resets on
 * a good stretch. A four-hour call on a train could spend it and then have
 * nothing left; reset it from a `connected` transition if that ever happens to
 * somebody.
 */
const REBUILD_ATTEMPTS = 3;

/**
 * How long after a spent link before it is rebuilt.
 *
 * Long enough that a far end doing the same arithmetic has finished its own
 * teardown - two peers rebuilding into each other's closing connections is a
 * pair that never settles - and short enough to be over before anybody has
 * decided to leave and do it themselves.
 */
const REBUILD_DELAY_MS = 2_000;

/**
 * The shortest gap between two re-reads of the channel key for one peer.
 *
 * The re-read exists for an epoch that changed under a live call. The cooldown
 * exists so a proof that is simply wrong cannot turn every arriving description
 * into a request to the key directory.
 */
const KEY_REREAD_COOLDOWN_MS = 5_000;

/** Speaking polls per check of whether video is really arriving - so, a second. */
const VIDEO_POLL_EVERY = 5;

/**
 * Audio level above which somebody counts as speaking.
 *
 * `getSynchronizationSources` reports 0..1, roughly linear in amplitude. This
 * is about -40 dBFS: below a voice, above the residue a suppressor leaves.
 */
const SPEAKING_LEVEL = 0.01;

export interface MeshEvents {
  /** A track arrived, or went away (`track: null`), on one peer's slot. */
  onTrack: (peerId: string, slot: Slot, track: MediaStreamTrack | null) => void;
  /** The roster changed. Always the full list, so a consumer needs no diffing. */
  onPeers: (peers: CallPeer[]) => void;
  /** Identities currently speaking, local included. */
  onSpeaking: (speaking: Set<string>) => void;
  /** A message on a peer's data channel. */
  onData: (peer: CallPeer, payload: unknown) => void;
  /** A peer's data channel can send reliable application state. */
  onDataOpen?: (peer: CallPeer) => void;
  /**
   * One peer is in trouble, but the call is not over.
   *
   * This exists because the first version of this file logged every negotiation
   * failure to the console and nowhere else, so a call where nothing connected
   * looked exactly like a call that was working - two tiles, no media, no
   * message. A failure the person in the call cannot see is a failure nobody
   * can report.
   */
  onProblem: (message: string) => void;
  /** The call cannot continue - the socket died, or the server refused. */
  onFatal: (message: string) => void;
  /**
   * Who is sharing their screen, as the gateway sees it, or null for nobody.
   *
   * One share per call: a second one replaces the first rather than joining it,
   * so the peer that was sharing hears this with somebody else's id in it and
   * stops. Arbitrated at the gateway because two people pressing the button at
   * the same moment need one answer, and a mesh has no ordering to give one.
   */
  onScreenHolder?: (peerId: string | null) => void;
  /**
   * The call's Listen Together session, or null when there is not one.
   *
   * Whole state rather than a delta, and it arrives here rather than on a data
   * channel deliberately: a data channel is per peer, so a queue sent over one
   * would be as many queues as there are peers, each with its own idea of what
   * happened first. The gateway is the only thing in a mesh that can order two
   * people pressing pause at the same moment.
   */
  onListen?: (session: ListenSession | null) => void;
  /**
   * The game being played in this call, or null when there is not one.
   *
   * Here rather than on a data channel for the reason the listening session is:
   * a data channel is per peer, so a board sent over one would be as many
   * boards as there are peers, each with its own idea of which click came
   * first. The gateway referees, and this is what it says came of a move.
   */
  onGame?: (session: GameSession | null) => void;
  /**
   * One measurement of the gateway's clock against this machine's.
   *
   * Listening together means agreeing on a position, and a position is only
   * meaningful on a clock both ends share - two laptops disagree about the time
   * by whatever their NTP daemons last settled on. See `listen-sync.ts`.
   */
  onServerTime?: (sample: ClockSample) => void;
}

interface MeshOptions extends MeshEvents {
  channelId: string;
  token: string;
  iceServers: IceServer[];
  /**
   * The channel key, used only to sign and verify DTLS fingerprints.
   *
   * A function rather than a value because the key rotates *during* a call: a
   * member who joins a channel holding none of its keys mints the next epoch
   * to get one at all, so the moment somebody new arrives everybody already in
   * the call is a generation behind them. `refresh` re-reads the directory.
   */
  channelKey: (refresh?: boolean) => Promise<string>;
}

/** Waits. The recovery loop is a sequence of waits and the WebRTC API is not. */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

/**
 * The DTLS fingerprint out of an SDP blob.
 *
 * There is one per session in everything Chromium produces. Taking the first
 * and requiring it to exist is deliberate: an SDP with no fingerprint cannot be
 * verified, and accepting it unverified would be the hole this closes.
 */
export function fingerprintOf(sdp: string): string | null {
  const match = /^a=fingerprint:(\S+)\s+(\S+)/m.exec(sdp);
  return match ? `${match[1]} ${match[2]}` : null;
}

/** `HMAC-SHA256(channel key, fingerprint)`, base64. */
export async function signFingerprint(channelKey: string, fingerprint: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(channelKey),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const signature = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(fingerprint));
  return btoa(String.fromCharCode(...new Uint8Array(signature)));
}

/**
 * Whether `proof` is the signature of this SDP's fingerprint.
 *
 * Never throws: a malformed SDP, a missing fingerprint and a wrong signature
 * are all the same answer - do not connect to this.
 */
export async function verifyFingerprint(
  channelKey: string,
  sdp: string,
  proof: string,
): Promise<boolean> {
  try {
    const fingerprint = fingerprintOf(sdp);
    if (!fingerprint) return false;
    const expected = await signFingerprint(channelKey, fingerprint);
    // Both are base64 of the same length, so a plain comparison leaks only
    // whether they matched - which the caller is about to act on anyway.
    return expected === proof;
  } catch {
    return false;
  }
}

/**
 * Verifies, re-reading the channel key once when the first try fails.
 *
 * The re-read is the whole point. Two people joining at the same moment, or a
 * member removed mid-call, rotate the channel's epoch underneath a connection
 * that is already open, and without this the peer holding the *newer* key is
 * refused as though it were the relay standing in the middle. Once only,
 * though: a proof that is simply wrong must not become a way to make this
 * client hammer the key directory.
 */
export async function verifyFingerprintWithRefresh(
  channelKey: (refresh?: boolean) => Promise<string>,
  sdp: string,
  proof: string,
): Promise<boolean> {
  if (await verifyFingerprint(await channelKey(), sdp, proof)) return true;
  return verifyFingerprint(await channelKey(true), sdp, proof);
}

/**
 * Opus options live in the SDP's `fmtp` line and cannot be changed on a live
 * sender, so they are patched into the local description before it is set.
 *
 * `stereo`/`sprop-stereo` are what make a music-mode microphone or a film's
 * soundtrack arrive in two channels at all - without them the far end decodes
 * mono however many channels were captured. `usedtx` is the opposite: it saves
 * bandwidth in a conversation and deletes the quiet parts of music.
 */
export function patchOpus(sdp: string, options: MicEncoding): string {
  const payload = /^a=rtpmap:(\d+)\s+opus\/48000/im.exec(sdp)?.[1];
  if (!payload) return sdp;

  const wanted = [
    `stereo=${options.stereo ? 1 : 0}`,
    `sprop-stereo=${options.stereo ? 1 : 0}`,
    `usedtx=${options.dtx ? 1 : 0}`,
    `maxaveragebitrate=${options.maxBitrate}`,
  ].join(';');

  const line = new RegExp(`^a=fmtp:${payload} (.*)$`, 'm');
  return line.test(sdp)
    ? sdp.replace(line, (_match, existing: string) => `a=fmtp:${payload} ${existing};${wanted}`)
    : sdp.replace(
        new RegExp(`^(a=rtpmap:${payload} opus/48000.*)$`, 'im'),
        `$1\r\na=fmtp:${payload} ${wanted}`,
      );
}

/**
 * One peer connection, and everything that hangs off it.
 *
 * `ponytail`: the four slots are hard-coded rather than negotiated. A fifth
 * kind of media means adding a slot here and shipping both sides together;
 * per-connection negotiation is the upgrade path if that ever stops being
 * acceptable.
 */
class PeerLink {
  readonly pc: RTCPeerConnection;
  readonly channel: RTCDataChannel;

  private readonly senders = new Map<Slot, RTCRtpSender>();
  private readonly transceivers = new Map<Slot, RTCRtpTransceiver>();
  /** Perfect negotiation bookkeeping. */
  private makingOffer = false;
  private ignoreOffer = false;
  /**
   * Signals from this peer, applied strictly one at a time.
   *
   * `accept` is async and the socket dispatches into it without waiting, so two
   * descriptions arriving close together used to run *concurrently* and
   * interleave at every `await` inside. The state checks below read
   * `signalingState` before `verify`, which can go to the network for a fresh
   * channel key, so the second run acted on a reading the first had already
   * invalidated. See `signal-queue.ts` for the failure it produced.
   */
  private readonly queue = serialize();
  /** When the channel key was last re-read for this peer. See `verify`. */
  private keyReadAt = 0;
  /** Offers sent for a link that never got an answer. See `chase`. */
  private connectAttempts = 0;
  private connectTimer: number | null = null;
  /** Whether a recovery loop is running, so a flapping link starts only one. */
  private recovering = false;
  /** When the media stopped, so the deadline is measured from the fault. */
  private downSince: number | null = null;
  /** ICE restarts spent on this link since it last carried media. */
  private recoveryAttempts = 0;
  private readonly polite: boolean;
  private micEncoding: MicEncoding | null = null;
  private sharePublish: SharePublish | null = null;
  private closed = false;
  /**
   * What this client wants to be sending, held for the answering side: it has
   * no senders until the offer arrives, and a microphone opened before that
   * would otherwise be asked for once and never sent.
   */
  private readonly wanted = new Map<Slot, MediaStreamTrack | null>();
  /** Remembered for the same reason: the screen slot may not exist yet. */
  private shareCodec: SharePublish['videoCodec'] | null = null;
  /** Video slots that have decoded at least one frame. See `pollVideo`. */
  private readonly liveVideo = new Set<Slot>();
  /** How loud this peer is, 0..1. See `pollAudioLevel`. */
  private level = 0;
  /**
   * Candidates that arrived before there was a remote description to attach
   * them to.
   *
   * This is not an edge case, it is the normal path: both peers offer at once,
   * so each one's candidates start arriving while the other is still resolving
   * the glare. `addIceCandidate` rejects with `InvalidStateError` until
   * `setRemoteDescription` has run, and a candidate dropped there is dropped
   * for good - which is a connection that negotiates fine and then never
   * carries a packet.
   */
  private readonly pendingCandidates: IceCandidatePayload[] = [];

  constructor(
    readonly peer: CallPeer,
    selfPeerId: string,
    iceServers: IceServer[],
    private readonly channelKey: (refresh?: boolean) => Promise<string>,
    private readonly send: (signal: CallSignal) => void,
    private readonly events: {
      onTrack: (slot: Slot, track: MediaStreamTrack | null) => void;
      onData: (payload: unknown) => void;
      onDataOpen: () => void;
      /**
       * Everything this link can do by itself has been done and none of it
       * worked. Only the mesh can act on it: what is left to try is a new
       * connection, and a link cannot replace itself.
       */
      onExhausted: () => void;
      /** Something went wrong that the person in the call should be told about. */
      onProblem: (message: string) => void;
    },
  ) {
    // Whoever has the larger peer id yields. Both sides compute this from the
    // same two strings, so they always disagree - which is the point.
    this.polite = selfPeerId > peer.peerId;

    this.pc = new RTCPeerConnection({
      iceServers,
      // A direct path whenever there is one. Never 'relay': forcing everybody
      // through a TURN server would spend bandwidth on the calls that were
      // going to work anyway, which is most of them.
      iceTransportPolicy: 'all',
      bundlePolicy: 'max-bundle',
      // Start gathering before there is anything to gather for, so the first
      // offer already carries candidates instead of trickling them behind
      // itself. One is enough with `max-bundle`: there is a single transport.
      iceCandidatePoolSize: 1,
    });

    // The four slots, in order - created by the offering side only. See
    // `adopt`: creating them on both sides is what produced nine m-lines and a
    // call where no media was ever received.
    if (!this.polite) {
      for (const slot of SLOTS) {
        const encodings: RTCRtpEncodingParameters[] =
          slot === 'screen'
            ? [
                {
                  maxBitrate: 50_000_000,
                  maxFramerate: 60,
                  priority: 'high',
                  networkPriority: 'high',
                },
              ]
            : [];
        const transceiver = this.pc.addTransceiver(SLOT_KIND[slot], {
          direction: 'sendrecv',
          sendEncodings: encodings.length > 0 ? encodings : undefined,
        });
        this.transceivers.set(slot, transceiver);
        this.senders.set(slot, transceiver.sender);
      }
      this.preferShareCodec('H264');
    }

    // Negotiated on both sides with a fixed id, so neither has to wait for the
    // other's `ondatachannel` and there is no race about who opens it.
    this.channel = this.pc.createDataChannel('betweenus.share', { negotiated: true, id: 0 });
    this.channel.onmessage = (event) => {
      try {
        this.events.onData(JSON.parse(String(event.data)));
      } catch {
        // A peer sending something unparseable is not this call's problem.
      }
    };
    this.channel.onopen = () => this.events.onDataOpen();

    this.pc.ontrack = (event) => {
      const slot = this.slotOf(event.transceiver);
      if (!slot) return;

      if (slot === 'screen') {
        // A jitter buffer left alone is a third of a second between moving the
        // mouse and seeing it move.
        this.setPlayoutDelay(event.receiver, PLAYOUT_DELAY.watching);
      }

      // Every slot produces a track whether or not anybody is sending on it,
      // so a slot is empty until something actually arrives on it - otherwise
      // a camera nobody turned on is a black rectangle where an avatar goes,
      // and a screen nobody shared is announced to the whole call.
      //
      // What "actually arrives" means differs by kind. Audio is honest: the
      // track is muted until packets come and `unmute` says when they do.
      // Video is not - a receiver unmutes on the padding Chromium sends to
      // probe for bandwidth, which is a screen share that never happened - so
      // a video slot waits for a frame to be decoded before it counts as
      // arrived (`pollVideo`), and whether it is still *on* is the peer's own
      // declared media state (`media-presence.ts`).
      if (SLOT_KIND[slot] === 'audio') {
        this.events.onTrack(slot, event.track.muted ? null : event.track);
        event.track.onmute = () => this.events.onTrack(slot, null);
        event.track.onunmute = () => this.events.onTrack(slot, event.track);
      }
      // A remote track that ends is a device switched off at the far end. The
      // slot stays; what was in it does not.
      event.track.onended = () => this.events.onTrack(slot, null);
    };

    this.pc.onicecandidate = ({ candidate }) => {
      if (!candidate) return;
      this.send({
        kind: 'ice',
        candidate: {
          candidate: candidate.candidate,
          sdpMid: candidate.sdpMid,
          sdpMLineIndex: candidate.sdpMLineIndex,
          usernameFragment: candidate.usernameFragment,
        },
      });
    };

    this.pc.onnegotiationneeded = () => {
      // The first offer is the impolite side's, always. The polite side has
      // nothing to describe yet - its transceivers come from that offer - and
      // an offer from here before one has arrived is the glare that used to
      // leave both ends with two sets of m-lines that never paired up.
      if (this.polite && !this.pc.remoteDescription) return;
      void this.offer();
    };

    // Recovery is driven from `connectionState` alone.
    //
    // `iceConnectionState` says nearly the same thing a beat earlier and less
    // reliably - it reaches `failed` on one transport rather than on the
    // connection - and two callbacks both starting restarts is a link
    // renegotiating on top of itself. This used to be both: a bare
    // `restartIce()` from the ICE callback that the polite side could never
    // act on, and a drop out of the mesh from this one.
    this.pc.onconnectionstatechange = () => {
      if (this.closed) return;
      switch (this.pc.connectionState) {
        case 'connected':
          this.stopChasing();
          this.recovered();
          return;
        // Both mean media has stopped. They differ only in how likely it is to
        // come back unaided, which is what the grace period is for:
        // `disconnected` climbs out on its own often enough to be worth
        // waiting on, `failed` never does.
        case 'disconnected':
          this.startRecovery(GRACE_MS);
          return;
        case 'failed':
          this.startRecovery(0);
          return;
        default:
          return;
      }
    };

    // An offer that is never answered fires no event at all. See `chase`.
    this.chase();
  }

  /**
   * Applies everything that arrived too early. Called immediately after a
   * remote description lands, which is the first moment these are legal.
   */
  private async flushCandidates(): Promise<void> {
    const queued = this.pendingCandidates.splice(0);
    for (const candidate of queued) {
      try {
        await this.pc.addIceCandidate(candidate);
      } catch (error) {
        console.warn('[mesh] queued ICE candidate rejected', error);
      }
    }
  }

  /**
   * Which slot a transceiver is, by position.
   *
   * Position rather than object identity because `ontrack` fires *during*
   * `setRemoteDescription`, before the answering side has had a chance to write
   * anything down - and on that side the transceivers were created by the
   * description itself, in m-line order, which is the same order as `SLOTS`.
   */
  private slotOf(transceiver: RTCRtpTransceiver): Slot | null {
    return SLOTS[this.pc.getTransceivers().indexOf(transceiver)] ?? null;
  }

  /**
   * The answering side takes ownership of the transceivers the offer created.
   *
   * Both sides used to create their own four, and then neither offer could be
   * matched to the other's: each connection ended up with eight transceivers
   * and nine m-lines, every one of them one-directional, and every arriving
   * track on a transceiver this side had never heard of. Media was negotiated
   * and then dropped on the floor - a call that connects, shows everybody, and
   * carries nothing.
   *
   * So only the impolite side creates them, and the polite side adopts what the
   * offer brought. They arrive `recvonly`, which is the direction that would
   * make this end permanently silent, so they are flipped before the answer is
   * written - and whatever this client is already capturing goes on immediately,
   * because it was asked for while there was no sender to put it on.
   */
  private async adopt(): Promise<void> {
    if (this.transceivers.size > 0) return;

    const found = this.pc.getTransceivers();
    for (const [index, slot] of SLOTS.entries()) {
      const transceiver = found[index];
      if (!transceiver || transceiver.receiver.track?.kind !== SLOT_KIND[slot]) return;
    }

    for (const [index, slot] of SLOTS.entries()) {
      const transceiver = found[index] as RTCRtpTransceiver;
      transceiver.direction = 'sendrecv';
      this.transceivers.set(slot, transceiver);
      this.senders.set(slot, transceiver.sender);
    }

    this.preferShareCodec(this.shareCodec ?? 'H264');
    for (const [slot, track] of this.wanted) await this.setTrack(slot, track);
    if (this.micEncoding) await this.tune('mic', { maxBitrate: this.micEncoding.maxBitrate });
    if (this.sharePublish) {
      await this.tune(
        'screen',
        {
          maxBitrate: this.sharePublish.maxBitrate,
          maxFramerate: this.sharePublish.maxFramerate,
          scaleResolutionDownBy: this.sharePublish.scaleResolutionDownBy,
          priority: this.sharePublish.priority,
        },
        this.sharePublish.degradationPreference,
      );
      if (this.sharePublish.audio) {
        await this.tune('screenAudio', { maxBitrate: this.sharePublish.audio.maxBitrate });
      }
    }
  }

  /**
   * `playoutDelayHint` is Chromium's and is not in the DOM types. Absent
   * elsewhere, where the default buffer is what a viewer gets.
   */
  private setPlayoutDelay(receiver: RTCRtpReceiver, seconds: number): void {
    (receiver as RTCRtpReceiver & { playoutDelayHint?: number }).playoutDelayHint = seconds;
  }

  /** Asks for less buffering on the screen, for whoever is driving it. */
  setDriving(driving: boolean): void {
    const receiver = this.transceivers.get('screen')?.receiver;
    if (receiver) {
      this.setPlayoutDelay(receiver, driving ? PLAYOUT_DELAY.driving : PLAYOUT_DELAY.watching);
    }
  }

  private async offer(): Promise<void> {
    if (this.closed) return;
    try {
      this.makingOffer = true;
      await this.setLocalDescription('offer');
      await this.sendDescription();
    } catch (error) {
      this.fail('could not offer', error);
    } finally {
      this.makingOffer = false;
    }
  }

  /**
   * Sets the local description, with the Opus and Video bandwidth options patched in
   * when they will be accepted.
   *
   * The patch is a preference, not a requirement: `stereo`, `usedtx` and video
   * bandwidth hints are settable in the SDP. So the munged one is tried first
   * and the untouched one is the fallback.
   */
  private async setLocalDescription(type: 'offer' | 'answer'): Promise<void> {
    const description =
      type === 'offer' ? await this.pc.createOffer() : await this.pc.createAnswer();

    if (description.sdp) {
      let patched = description.sdp;
      if (this.micEncoding) {
        patched = patchOpus(patched, this.micEncoding);
      }
      patched = patchVideoBandwidth(patched, this.sharePublish);

      if (patched !== description.sdp) {
        try {
          await this.pc.setLocalDescription({
            type: description.type,
            sdp: patched,
          });
          return;
        } catch (error) {
          console.warn('[mesh] Patched SDP options refused, continuing without them', error);
        }
      }
    }

    await this.pc.setLocalDescription(description);
  }

  /** One place for "this peer is not going to work, and here is why". */
  private fail(what: string, error: unknown): void {
    const reason = error instanceof Error ? error.message : String(error);
    console.error(`[mesh] ${what} (${this.peer.username}/${this.peer.peerId}):`, error);
    this.events.onProblem(`${this.peer.username}: ${what} - ${reason}`);
  }

  /**
   * Verifies, re-reading the channel key when it has not just been read.
   *
   * The re-read used to be allowed once per peer and then never again, which is
   * a link that can only survive one epoch change and is the likeliest way a
   * tile ends up on "Connecting…" for good. One key change is normal - somebody
   * joining a channel they hold no key for mints the next epoch - and burning
   * the only re-read on the first description means every description after it
   * is refused against a key that is known to be stale, with nothing left that
   * would ever look again.
   *
   * A cooldown keeps the property the latch was there for: a proof that is
   * simply wrong still cannot make this client hammer the key directory,
   * because a wrong proof arriving twice a second re-reads once.
   */
  private async verify(sdp: string, proof: string): Promise<boolean> {
    if (await verifyFingerprint(await this.channelKey(), sdp, proof)) return true;
    if (Date.now() - this.keyReadAt < KEY_REREAD_COOLDOWN_MS) return false;
    this.keyReadAt = Date.now();
    return verifyFingerprint(await this.channelKey(true), sdp, proof);
  }

  /**
   * Offers again when an offer was never answered.
   *
   * Nothing else does. `connectionState` only reaches `failed` once ICE has had
   * a remote description to fail against, so an offer that the far end refused
   * - a fingerprint signed with an epoch it had not caught up to, most often -
   * leaves this connection sitting in `new` with no event ever fired and no
   * recovery path to enter. That is the whole of a tile that says "Connecting…"
   * until somebody leaves the call.
   *
   * Only the impolite side, because only it may offer, and only from `new`: a
   * link that has a remote description is negotiating, and offering over the
   * top of a slow network would break the calls that were about to work.
   * Re-reading the key first is not incidental - it is the fix for the case
   * this is most often chasing.
   */
  private chase(): void {
    if (this.closed || this.polite) return;

    this.connectTimer = window.setTimeout(() => {
      this.connectTimer = null;
      if (this.closed) return;
      if (this.pc.connectionState !== 'new') return;

      if (++this.connectAttempts > CONNECT_ATTEMPTS) {
        // Not the end. An offer that was never answered leaves this connection
        // in `new`, where no state change ever fires again - so without this
        // the link sat silent for the rest of the call and the only cure was a
        // human leaving and rejoining. That is what `onExhausted` automates.
        this.events.onExhausted();
        return;
      }

      void (async () => {
        await this.channelKey(true).catch(() => undefined);
        await this.offer();
        this.chase();
      })();
    }, CONNECT_DEADLINE_MS);
  }

  private stopChasing(): void {
    if (this.connectTimer !== null) window.clearTimeout(this.connectTimer);
    this.connectTimer = null;
    this.connectAttempts = 0;
  }

  // --- recovery ---

  private connectedNow(): boolean {
    return this.pc.connectionState === 'connected';
  }

  /**
   * Media is flowing again - either it never really stopped, or a restart
   * worked.
   *
   * The counters reset, so a link that drops once an hour on a train gets the
   * full budget each time rather than spending its way to "lost" over an
   * afternoon.
   */
  private recovered(): void {
    this.downSince = null;
    this.recoveryAttempts = 0;
  }

  /**
   * Start trying, after `initialDelay`.
   *
   * Idempotent: a connection flapping between `disconnected` and `failed` calls
   * this repeatedly, and each call must not start a second loop racing the
   * first. `downSince` is set on the first call and not on the later ones, so
   * the deadline is measured from when the media stopped rather than from the
   * most recent flap - a link that flaps forever would otherwise never reach
   * it.
   */
  private startRecovery(initialDelay: number): void {
    if (this.closed || this.recovering) return;
    this.downSince ??= Date.now();
    this.recovering = true;
    void this.recover(initialDelay).finally(() => {
      this.recovering = false;
    });
  }

  private async recover(initialDelay: number): Promise<void> {
    await sleep(initialDelay);
    // The grace period is exactly the case where nothing more is needed: ICE
    // climbed out on its own while we waited.
    if (this.closed || this.connectedNow()) return;

    while (!this.closed && !this.connectedNow()) {
      if (spent(this.recoveryAttempts, Date.now() - (this.downSince ?? Date.now()))) {
        this.giveUp();
        return;
      }

      this.recoveryAttempts += 1;
      await sleep(backoffMs(this.recoveryAttempts));
      if (this.closed || this.connectedNow()) return;

      // Both halves are needed, and this is the part the old code got wrong.
      // `restartIce()` only marks the connection as wanting fresh candidates;
      // the offer is what actually asks for them. On its own it fires
      // `onnegotiationneeded`, which is exactly what the polite side is
      // written to ignore - so on that side it did nothing whatsoever.
      if (restarts(this.polite)) {
        try {
          this.pc.restartIce();
        } catch {
          // A connection closed underneath us. The loop's own guard catches it.
        }
        await this.offer();
      }

      // Long enough for a restart to have landed, short enough that every
      // attempt fits inside the deadline. See `call-recovery.check.ts`.
      await sleep(GRACE_MS);
    }
  }

  /**
   * Out of attempts, or out of time.
   *
   * The connection is left open, and the peer stays in the mesh. Who is in a
   * call is the roster's answer and never this side's guess: a peer whose
   * laptop really has gone is removed by `peer.left` a moment later, and one
   * whose link is merely unrecoverable *from here* may be perfectly present to
   * everybody else.
   *
   * Dropping the link instead - which is what this used to do the first time
   * `connectionState` reached `failed` - was permanent, because nothing in a
   * mesh ever re-adds a link. One bad moment on one pair therefore needed a
   * rejoin to clear, which is the whole of the "leave and come back a few
   * times until it works" this call had become.
   */
  private giveUp(): void {
    this.events.onExhausted();
  }

  private async sendDescription(): Promise<void> {
    const description = this.pc.localDescription;
    if (!description?.sdp) return;

    const fingerprint = fingerprintOf(description.sdp);
    if (!fingerprint) {
      // Nothing to sign means nothing the far end can verify. Sending it anyway
      // would be handing them a connection they have to trust blindly.
      this.fail('no DTLS fingerprint to sign, so nothing was sent', new Error('no fingerprint'));
      return;
    }

    this.send({
      kind: description.type === 'offer' ? 'offer' : 'answer',
      sdp: description.sdp,
      fingerprintProof: await signFingerprint(await this.channelKey(), fingerprint),
    });
  }

  /**
   * Queues one signal behind the ones already being applied to this peer.
   *
   * The whole body of `apply` is a critical section over `this.pc`: every check
   * it makes about `signalingState` is invalidated by another run touching the
   * connection, and every `await` in it is a chance for that to happen.
   */
  accept(signal: CallSignal): Promise<void> {
    return this.queue(() => this.apply(signal));
  }

  /** The perfect-negotiation receive path, verbatim from the WebRTC spec's shape. */
  private async apply(signal: CallSignal): Promise<void> {
    if (this.closed) return;

    try {
      if (signal.kind === 'ice') {
        // Held rather than applied when there is nothing to apply them to yet.
        // See `pendingCandidates`: dropping these is a call that connects and
        // then stays silent.
        if (!this.pc.remoteDescription) {
          this.pendingCandidates.push(signal.candidate);
          return;
        }
        try {
          await this.pc.addIceCandidate(signal.candidate);
        } catch (error) {
          // A candidate arriving during a rolled-back offer is expected and
          // harmless; anything else is worth a line but not the call.
          if (!this.ignoreOffer) console.warn('[mesh] ICE candidate rejected', error);
        }
        return;
      }

      // The check that makes the relay untrusted. A server that swapped the
      // fingerprint cannot produce this, so the connection is never made.
      if (!(await this.verify(signal.sdp, signal.fingerprintProof))) {
        console.error(
          '[mesh] refusing a peer whose DTLS fingerprint is not signed with the channel key',
          this.peer.peerId,
        );
        // Said out loud rather than left as a tile that never carries anything.
        // The honest cause is almost always the two devices holding different
        // channel-key epochs, not an attack - but the connection is refused
        // either way, because the two cases look identical from here.
        //
        // The link is kept. Dropping it used to be permanent: nothing re-adds a
        // link, and the far end's next offer would then arrive for a peer this
        // client no longer has - so one refusal, which an epoch change makes
        // ordinary, ended that pair for the life of the call. Refusing this
        // description is all that is meant; the next one is verified afresh
        // against a key that may by then have been re-read.
        this.events.onProblem(
          `${this.peer.username}: refused - their media key does not match this channel's`,
        );
        return;
      }

      // An answer is the reply to one offer, and only the side with that offer
      // still outstanding can apply it. A second answer - which a re-offer
      // chasing a connection that never came up will produce, since each offer
      // is answered - arrives when this side is already `stable`, and applying
      // it throws "Called in wrong state: stable" at somebody who is looking at
      // a call, not at a state machine. Dropping it is right: the description
      // that settled the connection is already in place.
      if (signal.kind === 'answer' && this.pc.signalingState !== 'have-local-offer') return;

      const offerCollision =
        signal.kind === 'offer' &&
        (this.makingOffer || this.pc.signalingState !== 'stable');

      this.ignoreOffer = !this.polite && offerCollision;
      if (this.ignoreOffer) return;

      await this.pc.setRemoteDescription({ type: signal.kind, sdp: signal.sdp });
      await this.flushCandidates();

      if (signal.kind === 'offer') {
        // Before the answer is written: the directions it carries are the ones
        // decided here.
        await this.adopt();
        await this.setLocalDescription('answer');
        await this.sendDescription();
      }
    } catch (error) {
      this.fail(`could not accept an ${signal.kind}`, error);
    }
  }

  /**
   * Puts a track on a slot, or takes it off with `null`.
   *
   * `replaceTrack` on an existing sender does not renegotiate, which is what
   * makes toggling a microphone free.
   */
  async setTrack(slot: Slot, track: MediaStreamTrack | null): Promise<void> {
    this.wanted.set(slot, track);
    const sender = this.senders.get(slot);
    // No sender yet means this side is still waiting for the offer that makes
    // one. `adopt` plays this back.
    if (!sender) return;
    await sender.replaceTrack(track).catch(() => undefined);
  }

  /** Bitrate and degradation on a live sender; no renegotiation. */
  async tune(
    slot: Slot,
    encoding: {
      maxBitrate?: number;
      maxFramerate?: number;
      scaleResolutionDownBy?: number;
      priority?: RTCPriorityType;
    },
    degradation?: RTCDegradationPreference,
  ): Promise<void> {
    const sender = this.senders.get(slot);
    if (!sender) return;

    try {
      const parameters = sender.getParameters();
      // A sender that has not negotiated yet has no encodings to change.
      if (!parameters.encodings || parameters.encodings.length === 0) {
        parameters.encodings = [{}];
      }
      const first = parameters.encodings[0];
      if (first) {
        if (encoding.maxBitrate !== undefined) first.maxBitrate = encoding.maxBitrate;
        if (encoding.maxFramerate !== undefined) first.maxFramerate = encoding.maxFramerate;
        if (encoding.scaleResolutionDownBy !== undefined) {
          first.scaleResolutionDownBy = encoding.scaleResolutionDownBy;
        }
        if (encoding.priority !== undefined) first.priority = encoding.priority;
      }
      if (degradation) parameters.degradationPreference = degradation;
      await sender.setParameters(parameters);
    } catch (error) {
      // Losing a bitrate ceiling is a worse picture, not a broken call.
      console.warn('[mesh] could not tune', slot, error);
    }
  }

  /** Remembered so every future offer and answer carries the same Opus options. */
  setMicEncoding(encoding: MicEncoding): void {
    this.micEncoding = encoding;
  }

  /** Remembered so every future offer and answer carries the screen bitrate options. */
  setSharePublish(publish: SharePublish | null): void {
    this.sharePublish = publish;
  }

  /**
   * Asks for High Profile H.264 on the screen slot, where hardware encoding is what makes
   * 1080p60/4K60 possible with pristine clarity. Ignored where the codec is unavailable.
   */
  preferShareCodec(codec: SharePublish['videoCodec']): void {
    this.shareCodec = codec;
    const transceiver = this.transceivers.get('screen');
    if (!transceiver?.setCodecPreferences) return;

    try {
      const supported = RTCRtpSender.getCapabilities('video')?.codecs ?? [];
      const sorted = sortPreferredVideoCodecs(supported, codec);
      transceiver.setCodecPreferences(sorted);
    } catch {
      // Codec preferences are an optimisation; the call works without them.
    }
  }

  /**
   * Whether a camera or a screen has ever really carried a picture.
   *
   * Nothing a video receiver *says* is trustworthy here: it unmutes on padding
   * packets, so a slot that has never carried anything looks live, and a camera
   * nobody turned on becomes a black rectangle where an avatar goes. A frame
   * decoded is proof, and that is all this decides.
   *
   * It deliberately does not decide the *other* direction. Frames stopping is
   * not sharing stopping: a screen share of a document nobody is typing in
   * decodes nothing for minutes, and treating that as the end took the stage
   * down under whoever was watching it and offered them the share again. Who is
   * still sharing is the peer's own declared media state, which arrives on the
   * data channel - see `media-presence.ts`.
   */
  async pollVideo(): Promise<void> {
    if (this.closed) return;

    const decoded = new Map<string, number>();
    (await this.pc.getStats()).forEach((report) => {
      const entry = report as RTCInboundRtpStreamStats & { mid?: string; framesDecoded?: number };
      if (entry.type === 'inbound-rtp' && entry.kind === 'video' && entry.mid) {
        decoded.set(entry.mid, entry.framesDecoded ?? 0);
      }
    });

    for (const slot of ['camera', 'screen'] as const) {
      const transceiver = this.transceivers.get(slot);
      const track = transceiver?.receiver.track;
      if (!transceiver?.mid || !track) continue;

      // Cumulative, so this only ever goes from false to true: the first frame
      // is the moment the slot is known to be real, and nothing after it is
      // evidence of an ending.
      if ((decoded.get(transceiver.mid) ?? 0) === 0) continue;
      if (this.liveVideo.has(slot)) continue;

      this.liveVideo.add(slot);
      this.events.onTrack(slot, track);
    }
  }

  /**
   * One `getStats` reduced to the numbers a person is shown.
   *
   * Everything is a running total except the frame size and rate, so the
   * arithmetic of turning it into a rate belongs to whoever holds the previous
   * sample - `call-stats.ts` - and this is only the reading.
   */
  async sample(): Promise<LinkSample> {
    const now: LinkSample = {
      at: Date.now(),
      inboundAudioBytes: 0,
      inboundVideoBytes: 0,
      outboundAudioBytes: 0,
      outboundVideoBytes: 0,
      packetsLost: 0,
      packetsReceived: 0,
      roundTripSeconds: null,
      frameWidth: null,
      frameHeight: null,
      framesPerSecond: null,
      sendWidth: null,
      sendHeight: null,
      sendLimitedBy: null,
      // Asked here rather than inferred from the counters below, because a
      // link that is up and quiet and a link that never came up produce the
      // same still counters, and only one of them is a microphone fault.
      connected: this.connectedNow(),
      transport: null,
      echoReturnLossEnhancementDb: null,
    };
    if (this.closed) return now;

    const reports = await this.pc.getStats().catch(() => null);
    if (!reports) return now;

    // The candidate pair carrying the call, and every candidate by id, so
    // "direct or relayed" can be answered after the whole report is walked.
    let nominated: Record<string, unknown> | null = null;
    const candidates = new Map<string, string>();

    reports.forEach((report) => {
      const entry = report as RTCStats & Record<string, number | string | undefined>;

      if (entry.type === 'inbound-rtp') {
        const bytes = Number(entry.bytesReceived ?? 0);
        if (entry.kind === 'audio') now.inboundAudioBytes += bytes;
        else now.inboundVideoBytes += bytes;
        now.packetsLost += Number(entry.packetsLost ?? 0);
        now.packetsReceived += Number(entry.packetsReceived ?? 0);

        // The biggest picture arriving, which is the share when there is one
        // and the camera otherwise - the number somebody actually wants when
        // they ask why it looks soft.
        if (entry.kind === 'video') {
          const width = Number(entry.frameWidth ?? 0);
          const height = Number(entry.frameHeight ?? 0);
          if (width * height > (now.frameWidth ?? 0) * (now.frameHeight ?? 0)) {
            now.frameWidth = width || null;
            now.frameHeight = height || null;
            now.framesPerSecond = Number(entry.framesPerSecond ?? 0) || null;
          }
        }
        return;
      }

      if (entry.type === 'outbound-rtp') {
        const bytes = Number(entry.bytesSent ?? 0);
        if (entry.kind === 'audio') now.outboundAudioBytes += bytes;
        else now.outboundVideoBytes += bytes;

        // The send side of the same question. A share that arrives soft was
        // either shrunk here before it left or damaged on the way, and the two
        // look identical from the far end - so what left, and what stopped it
        // leaving bigger, is read at the source. `none` is not a limit and is
        // dropped: a row saying "Limited by: none" is a row that trains people
        // to stop reading the panel.
        if (entry.kind === 'video') {
          const width = Number(entry.frameWidth ?? 0);
          const height = Number(entry.frameHeight ?? 0);
          if (width * height > (now.sendWidth ?? 0) * (now.sendHeight ?? 0)) {
            now.sendWidth = width || null;
            now.sendHeight = height || null;
          }
          const reason = entry.qualityLimitationReason;
          if (reason === 'bandwidth' || reason === 'cpu' || reason === 'other') {
            now.sendLimitedBy = reason;
          }
        }
        return;
      }

      // Only the pair actually carrying the call. Chromium keeps the losers of
      // the ICE race in the report, and their round trip means nothing.
      if (entry.type === 'candidate-pair' && entry.state === 'succeeded' && entry.nominated) {
        const rtt = Number(entry.currentRoundTripTime ?? Number.NaN);
        if (Number.isFinite(rtt)) now.roundTripSeconds = rtt;
        nominated = entry as Record<string, unknown>;
        return;
      }

      // Kept whatever they are, because the pair that names them is not
      // guaranteed to have been walked yet - `getStats` has no order.
      if (entry.type === 'local-candidate' || entry.type === 'remote-candidate') {
        candidates.set(String(entry.id), String(entry.candidateType ?? ''));
        return;
      }

      // How much echo the canceller is removing, reported against the local
      // microphone. It is the same source on every peer connection, so whoever
      // reads this last wins and they all agree; it is read per link only
      // because this is the loop that already has the report open.
      if (entry.type === 'media-source' && entry.kind === 'audio') {
        const erle = Number(entry.echoReturnLossEnhancement ?? Number.NaN);
        if (Number.isFinite(erle)) now.echoReturnLossEnhancementDb = erle;
      }
    });

    if (nominated) {
      // Either end being a relay candidate means the media is relayed: TURN is
      // in the path once, whichever side put it there.
      const pair = nominated as Record<string, unknown>;
      const local = candidates.get(String(pair.localCandidateId ?? ''));
      const remote = candidates.get(String(pair.remoteCandidateId ?? ''));
      if (local && remote) now.transport = local === 'relay' || remote === 'relay' ? 'relay' : 'direct';
    }

    return now;
  }

  /** How loud this peer is, 0..1, as of the last `pollAudioLevel`. */
  audioLevel(): number {
    return this.level;
  }

  /**
   * Reads how loud this peer is.
   *
   * `getSynchronizationSources()` is the obvious way to ask and is why nobody
   * ever saw a speaking ring on desktop or the web: it reports a level only for
   * sources it considers current, and in Chromium it is routinely empty on a
   * connection carrying perfectly good audio - so the ring was driven by a
   * number that was almost always zero. `inbound-rtp` carries the same reading
   * and is always there; it is what the Android client has been reading, which
   * is why the ring works there and only there.
   *
   * Asynchronous, so the poll reads the previous tick's answer. 200 ms behind a
   * syllable is not something a person can see.
   */
  async pollAudioLevel(): Promise<void> {
    const receiver = this.transceivers.get('mic')?.receiver;
    if (!receiver) {
      this.level = 0;
      return;
    }

    let loudest = 0;
    for (const source of receiver.getSynchronizationSources?.() ?? []) {
      loudest = Math.max(loudest, source.audioLevel ?? 0);
    }

    if (loudest === 0) {
      const report = await receiver.getStats().catch(() => null);
      report?.forEach((entry) => {
        const stat = entry as { type?: string; kind?: string; audioLevel?: number };
        if (stat.type !== 'inbound-rtp' || stat.kind !== 'audio') return;
        loudest = Math.max(loudest, Number(stat.audioLevel ?? 0));
      });
    }

    this.level = Number.isFinite(loudest) ? loudest : 0;
  }

  send_(payload: unknown): void {
    if (this.channel.readyState !== 'open') return;
    try {
      this.channel.send(JSON.stringify(payload));
    } catch {
      // A full or closing channel drops a pointer update. Nothing to do.
    }
  }

  close(): void {
    this.closed = true;
    this.stopChasing();
    this.channel.onmessage = null;
    this.channel.onopen = null;
    this.pc.ontrack = null;
    this.pc.onicecandidate = null;
    this.pc.onnegotiationneeded = null;
    this.pc.onconnectionstatechange = null;
    this.pc.oniceconnectionstatechange = null;
    try {
      this.channel.close();
    } catch {
      // Already gone.
    }
    this.pc.close();
  }
}

/**
 * A call: the signalling socket, the peers, and the local tracks sent to all of
 * them.
 *
 * One instance per call. `close()` ends it and releases nothing else - the
 * tracks belong to whoever captured them.
 */
export class Mesh {
  private socket: WebSocket | null = null;
  private selfPeerId: string | null = null;
  private readonly links = new Map<string, PeerLink>();
  private readonly local = new Map<Slot, MediaStreamTrack | null>();
  private micEncoding: MicEncoding | null = null;
  private sharePublish: SharePublish | null = null;
  private speakingTimer: number | null = null;
  /** Local speaking, fed by the microphone gate rather than by statistics. */
  private localSpeaking = false;
  private lastSpeaking = '';
  /** The previous reading per peer, so a rate can be worked out from a total. */
  private readonly lastSamples = new Map<string, LinkSample>();
  /**
   * What the peers who have already left moved, kept because their counters go
   * with them: a closed `RTCPeerConnection` answers `getStats` with nothing, so
   * the last reading has to be taken before it is closed rather than asked for
   * at the end of the call. See `drop`.
   *
   * One entry per person rather than a running total, because the log's whole
   * point is that a mesh call is several connections and they do not behave
   * alike - the one that went through a relay is the one worth finding.
   */
  private readonly retiredLinks: CallLinkReport[] = [];
  private closed = false;
  /** The channel key as last read, shared by every link. See `channelKey`. */
  private key: Promise<string> | null = null;
  /** When the outstanding clock ping went out, or null when none is. */
  private pingSentAt: number | null = null;
  /** Whether a signalling reconnect is in flight, so a flap starts only one. */
  private reconnecting = false;
  /** Rebuilds spent per peer. See `rebuild` and `REBUILD_ATTEMPTS`. */
  private readonly rebuilds = new Map<string, number>();
  /**
   * Who the gateway last said is in this call.
   *
   * Kept apart from `links` because during a rebuild there is deliberately no
   * link for somebody who is still very much present, and that gap is exactly
   * when a `peer.left` is most likely to arrive.
   */
  private readonly peerIsExpected = new Set<string>();

  constructor(private readonly options: MeshOptions) {}

  /**
   * The key every link signs and verifies fingerprints with, read once and
   * re-read whenever somebody joins.
   *
   * This is the fix for a call that refused a newcomer with "their media key
   * does not match this channel's" and then sat on "connecting". A member who
   * joins a channel holding none of its keys mints the next epoch for itself -
   * that is the only way it gets one - and everybody already in the call is
   * still signing with the epoch they snapshotted when *they* joined. One
   * generation apart, so every fingerprint is refused, and because only the
   * impolite side offers, whichever way the refusal falls the connection is
   * never made. Re-reading the moment a peer appears puts both sides on the
   * epoch the newcomer minted, before the first offer is written.
   */
  private channelKey(refresh = false): Promise<string> {
    if (refresh || !this.key) {
      this.key = this.options.channelKey(refresh).catch((error: unknown) => {
        // Never remember a failure: the next signal asks again rather than
        // being stuck with a rejection for the rest of the call.
        this.key = null;
        throw error;
      });
    }
    return this.key;
  }

  /** Opens the socket and joins. Resolves once the server has answered. */
  async join(): Promise<void> {
    await this.openSocket();
    this.startSpeakingPoll();
  }

  /**
   * One attempt at a socket and a join. Resolves once the server has answered.
   *
   * Used for the first join and for every reconnect, because they are the same
   * thing: `call-service` issues a peer id per *device* rather than per socket,
   * so a socket that comes back inside the gateway's grace window resumes the
   * seat it had - see `resumeHeldSeat` in `call.gateway.ts`. Nobody else in the
   * call is told anything happened, and every peer connection stays up, because
   * media does not go through here.
   */
  private openSocket(): Promise<void> {
    const { channelId, token } = this.options;
    // The device goes with the token. `call-service` hangs this window's peer
    // id on it, so a signalling reconnect comes back as the same peer rather
    // than as a stranger everybody has to rebuild a connection to.
    const socket = new WebSocket(
      `${wsUrl()}/ws/call?token=${encodeURIComponent(token)}&device=${encodeURIComponent(deviceId())}`,
    );
    this.socket = socket;

    return new Promise<void>((resolve, reject) => {
      const timeout = window.setTimeout(
        () => reject(new Error('The call server did not answer')),
        15_000,
      );

      socket.onopen = () => this.send({ type: 'join', channelId });

      socket.onmessage = (raw) => {
        let event: ServerCallEvent;
        try {
          event = JSON.parse(String(raw.data)) as ServerCallEvent;
        } catch {
          return;
        }

        if (event.type === 'joined') {
          window.clearTimeout(timeout);
          resolve();
        }
        if (event.type === 'error') {
          window.clearTimeout(timeout);
          reject(new Error(event.message));
        }
        void this.handle(event);
      };

      socket.onerror = () => {
        window.clearTimeout(timeout);
        reject(new Error('Could not reach the call server'));
      };

      socket.onclose = () => {
        window.clearTimeout(timeout);
        reject(new Error('The connection to the call server was lost'));
        // A socket this mesh has already replaced is a previous attempt
        // finishing late; its death says nothing about the live one.
        if (this.socket !== socket) return;
        if (this.closed) return;
        // `superseded` sets `closed` before the socket shuts, so reaching here
        // means the connection was lost rather than given away.
        void this.reconnect();
      };
    });
  }

  /**
   * Gets the signalling back, or ends the call saying so.
   *
   * This used to be a straight `onFatal`: the socket dropped and the call was
   * over, on a laptop that had merely changed wifi. That is the worst possible
   * reading of a lost signalling socket, because signalling is not in the media
   * path - every peer connection carries on regardless, and the only thing
   * actually missing while it is gone is the ability to admit somebody new.
   *
   * So it reconnects, quietly, for as long as `SIGNALLING_DEADLINE_MS` allows.
   * Past that the roster has long since dropped this device, so nobody else can
   * see it in the call and holding the microphone open is a lie told to its
   * owner - and then, and only then, it is fatal.
   */
  private async reconnect(): Promise<void> {
    if (this.closed || this.reconnecting) return;
    this.reconnecting = true;
    const lostAt = Date.now();
    let attempt = 0;

    try {
      while (!this.closed && Date.now() - lostAt < SIGNALLING_DEADLINE_MS) {
        attempt += 1;
        await sleep(signallingBackoffMs(attempt));
        if (this.closed) return;
        try {
          await this.openSocket();
          return;
        } catch {
          // Whatever it was, the answer is the same: try again until the
          // deadline says the seat is gone.
        }
      }
      if (!this.closed) {
        this.options.onFatal('The connection to the call server was lost');
      }
    } finally {
      this.reconnecting = false;
    }
  }

  private async handle(event: ServerCallEvent): Promise<void> {
    switch (event.type) {
      case 'ready':
        this.selfPeerId = event.peerId;
        return;

      case 'joined': {
        // Everyone already here. We arrived last, so we connect outward to all
        // of them; each of them sees a `peer.joined` for us at the same moment
        // and perfect negotiation settles who actually offers.
        for (const peer of event.peers) this.link(peer);
        // On a reconnect this roster is also the correction: somebody who left
        // while the socket was down sent a `peer.left` into a socket that was
        // not there to hear it, and would otherwise stay on screen as a tile
        // that never comes back. Empty on a first join, so this costs nothing.
        const present = new Set(event.peers.map((peer) => peer.peerId));
        for (const peerId of [...this.links.keys()]) {
          if (!present.has(peerId)) this.drop(peerId);
        }
        this.announcePeers();
        return;
      }

      case 'peer.joined':
        // Before the link, because the link starts negotiating immediately.
        // Somebody arriving may have just minted the epoch everyone else is
        // now behind - see `channelKey`.
        void this.channelKey(true).catch(() => {});
        this.link(event.peer);
        this.announcePeers();
        return;

      case 'peer.left':
        this.drop(event.peerId);
        return;

      case 'signal': {
        await this.links.get(event.from)?.accept(event.data);
        return;
      }

      case 'screen.holder':
        this.options.onScreenHolder?.(event.peerId);
        return;

      case 'listen.state':
        this.options.onListen?.(event.session);
        return;

      case 'game.state':
        this.options.onGame?.(event.session);
        return;

      case 'pong':
        // Only useful against the ping that asked for it: an unsolicited pong
        // has no send time to measure the round trip from, and half of an
        // unknown round trip is not an offset.
        if (typeof event.serverMs === 'number' && this.pingSentAt !== null) {
          this.options.onServerTime?.({
            sentAtMs: this.pingSentAt,
            receivedAtMs: Date.now(),
            serverMs: event.serverMs,
          });
          this.pingSentAt = null;
        }
        return;

      case 'superseded':
        // The same account joined this call somewhere else, so the server has
        // already taken this connection off the roster. Marking the mesh closed
        // first is what keeps the reason: the socket shuts straight after, and
        // `onclose` would otherwise report a lost connection over the top of it.
        this.closed = true;
        this.options.onFatal(
          'This call moved to another device - you joined it there. Rejoin here to bring it back.',
        );
        return;

      case 'error':
        console.warn('[mesh] signalling error', event.code, event.message);
        return;

      default:
        return;
    }
  }

  /**
   * Asks the gateway what time it is.
   *
   * Sent only while somebody is listening together, because that is the only
   * thing that needs a shared clock - a call has no opinion about the time, and
   * a measurement nobody reads is a message not worth sending.
   */
  sampleServerTime(): void {
    this.pingSentAt = Date.now();
    this.send({ type: 'ping' });
  }

  /** One Listen Together action, straight through. The gateway decides. */
  sendListen(event: ListenClientEvent): void {
    this.send(event);
  }

  /** One Play Together action. The gateway referees it and tells everybody. */
  sendGame(event: GameClientEvent): void {
    this.send(event);
  }

  /** This client's own peer id, once the gateway has issued one. */
  peerId(): string | null {
    return this.selfPeerId;
  }

  /** "I am about to share." The gateway decides, and tells everybody. */
  claimScreen(): void {
    this.send({ type: 'screen.claim' });
  }

  /** "I have stopped." Ignored by the gateway unless this peer is the holder. */
  releaseScreen(): void {
    this.send({ type: 'screen.release' });
  }

  private link(peer: CallPeer): PeerLink {
    this.peerIsExpected.add(peer.peerId);
    const existing = this.links.get(peer.peerId);
    if (existing) return existing;

    const link = new PeerLink(
      peer,
      this.selfPeerId ?? '',
      this.options.iceServers,
      (refresh) => this.channelKey(refresh),
      (signal) => this.send({ type: 'signal', to: peer.peerId, data: signal }),
      {
        onTrack: (slot, track) => this.options.onTrack(peer.peerId, slot, track),
        onData: (payload) => this.options.onData(peer, payload),
        onDataOpen: () => this.options.onDataOpen?.(peer),
        onExhausted: () => this.rebuild(peer),
        onProblem: (message) => this.options.onProblem(message),
      },
    );

    if (this.micEncoding) link.setMicEncoding(this.micEncoding);
    if (this.sharePublish) {
      link.setSharePublish(this.sharePublish);
      link.preferShareCodec(this.sharePublish.videoCodec);
    }
    this.links.set(peer.peerId, link);

    // Whatever this client is already sending goes onto the new connection
    // before it negotiates, so a peer joining mid-call sees the share that
    // started before they arrived.
    for (const [slot, track] of this.local) {
      if (track) void link.setTrack(slot, track);
    }
    void this.applyTuning(link);

    return link;
  }

  /**
   * Throws one link away and builds it again from nothing.
   *
   * The automated version of what everybody was doing by hand: leaving the call
   * and rejoining until it worked. That worked because a new connection gathers
   * new candidates - new local ports, a new NAT binding, a new race to lose or
   * win - and it is the only move left once ICE restarts are spent, because a
   * restart reuses the connection whose ports were the problem.
   *
   * Only the impolite side does it, for the same reason only it offers. The
   * polite side needs no rebuild of its own: the fresh offer arrives carrying a
   * new ICE ufrag and a new DTLS fingerprint, which its existing connection
   * takes as a restart and answers. Both sides tearing down at once would be
   * two peers rebuilding into each other's closing connections.
   *
   * The peer stays in the roster throughout. Who is in a call is the gateway's
   * answer, and a link this client cannot make work says nothing about whether
   * the person is there.
   */
  private rebuild(peer: CallPeer): void {
    if (this.closed) return;

    const old = this.links.get(peer.peerId);
    // Politeness is the same comparison the link made, and it is stable for as
    // long as both peer ids are.
    if (!old || (this.selfPeerId ?? '') > peer.peerId) {
      this.options.onProblem(
        `${peer.username}: could not be reached. Your networks may not be able to connect directly.`,
      );
      return;
    }

    const spentSoFar = this.rebuilds.get(peer.peerId) ?? 0;
    if (spentSoFar >= REBUILD_ATTEMPTS) {
      this.options.onProblem(
        `${peer.username}: could not be reached after ${REBUILD_ATTEMPTS} attempts. Your networks may not be able to connect directly.`,
      );
      return;
    }
    this.rebuilds.set(peer.peerId, spentSoFar + 1);

    this.links.delete(peer.peerId);
    old.close();
    // Whatever was last received on the dead connection is gone with it, and a
    // frozen final frame left on screen is worse than an empty tile: it is the
    // call looking like it works.
    for (const slot of SLOTS) this.options.onTrack(peer.peerId, slot, null);

    window.setTimeout(() => {
      // The roster may have settled the question while this was waiting - the
      // person really did leave - and re-adding them then would put a tile back
      // for somebody who is gone.
      if (this.closed || this.links.has(peer.peerId)) return;
      if (!this.peerIsExpected.has(peer.peerId)) return;
      this.link(peer);
      this.announcePeers();
    }, REBUILD_DELAY_MS);
  }

  private announcePeers(): void {
    this.options.onPeers([...this.links.values()].map((link) => link.peer));
  }

  /** Sends (or stops sending) one kind of media to everybody. */
  async setTrack(slot: Slot, track: MediaStreamTrack | null): Promise<void> {
    this.local.set(slot, track);
    await Promise.all([...this.links.values()].map((link) => link.setTrack(slot, track)));
    if (track) await Promise.all([...this.links.values()].map((link) => this.applyTuning(link)));
  }

  private async applyTuning(link: PeerLink): Promise<void> {
    if (this.micEncoding) {
      await link.tune('mic', { maxBitrate: this.micEncoding.maxBitrate });
    }
    if (this.sharePublish) {
      link.setSharePublish(this.sharePublish);
      await link.tune(
        'screen',
        {
          maxBitrate: this.sharePublish.maxBitrate,
          maxFramerate: this.sharePublish.maxFramerate,
          scaleResolutionDownBy: this.sharePublish.scaleResolutionDownBy,
          priority: this.sharePublish.priority,
        },
        this.sharePublish.degradationPreference,
      );
      if (this.sharePublish.audio) {
        await link.tune('screenAudio', { maxBitrate: this.sharePublish.audio.maxBitrate });
      }
    }
  }

  async setMicEncoding(encoding: MicEncoding): Promise<void> {
    this.micEncoding = encoding;
    for (const link of this.links.values()) link.setMicEncoding(encoding);
    await Promise.all(
      [...this.links.values()].map((link) => link.tune('mic', { maxBitrate: encoding.maxBitrate })),
    );
  }

  async setSharePublish(publish: SharePublish | null): Promise<void> {
    this.sharePublish = publish;
    for (const link of this.links.values()) {
      link.setSharePublish(publish);
      if (publish) link.preferShareCodec(publish.videoCodec);
    }
    if (!publish) return;
    await Promise.all([...this.links.values()].map((link) => this.applyTuning(link)));
  }

  /** Whether this client is driving somebody's share, which changes buffering. */
  setDriving(driving: boolean): void {
    for (const link of this.links.values()) link.setDriving(driving);
  }

  /** Fed by the microphone gate: it already measures the level on the audio thread. */
  setLocalSpeaking(speaking: boolean): void {
    this.localSpeaking = speaking;
  }

  /**
   * A reading per peer, turned into rates against the previous one.
   *
   * Called only while somebody is looking at the connection panel: `getStats`
   * is not free, and a number nobody is reading is a number not worth taking.
   */
  async stats(): Promise<LinkStats[]> {
    const links = [...this.links.values()];
    const samples = await Promise.all(links.map((link) => link.sample()));

    // The echo canceller is one per machine, not one per link, so the reading
    // is kept here rather than on any of the rows below. Every link reports the
    // same local source; the first one that has a number is as good as any.
    const erle = samples.find(
      (sample) => sample.echoReturnLossEnhancementDb !== null,
    );
    this.echoReturnLossEnhancementDb = erle?.echoReturnLossEnhancementDb ?? null;

    return links.map((link, index) => {
      const now = samples[index]!;
      const before = this.lastSamples.get(link.peer.peerId);
      this.lastSamples.set(link.peer.peerId, now);
      return toStats(link.peer.peerId, link.peer.username, now, before);
    });
  }

  /**
   * How many dB of echo the canceller removed as of the last `stats()` call.
   *
   * Null before the first sample, and on any build that does not report the
   * statistic. Read by the voice store, which is what the settings screen
   * watches - see `echoCancellerFailing`.
   */
  echoReturnLossEnhancementDb: number | null = null;

  /** Broadcasts on every peer's data channel, or to one peer. */
  sendData(payload: unknown, to?: string[]): void {
    if (to) {
      for (const peerId of to) this.links.get(peerId)?.send_(payload);
      return;
    }
    for (const link of this.links.values()) link.send_(payload);
  }

  get peers(): CallPeer[] {
    return [...this.links.values()].map((link) => link.peer);
  }

  get selfId(): string | null {
    return this.selfPeerId;
  }

  /**
   * Who is talking.
   *
   * Polled rather than event-driven because WebRTC has no "somebody started
   * speaking" event: the level is a statistic, and reading it ten times a
   * second is both cheap and faster than a person notices.
   */
  private startSpeakingPoll(): void {
    let tick = 0;
    this.speakingTimer = window.setInterval(() => {
      // A fifth as often as the speaking ring: a share appearing a beat late is
      // invisible next to the second it takes to pick a window, and `getStats`
      // is not free.
      if (++tick % VIDEO_POLL_EVERY === 0) {
        for (const link of this.links.values()) void link.pollVideo();
      }

      const speaking = new Set<string>();
      if (this.localSpeaking) speaking.add('local');
      for (const link of this.links.values()) {
        // Started here, read next tick: the level comes from `getStats`, which
        // is a promise. See `pollAudioLevel`.
        void link.pollAudioLevel();
        if (link.audioLevel() >= SPEAKING_LEVEL) speaking.add(link.peer.peerId);
      }

      // Only when it changes: this runs five times a second and every call
      // re-renders the whole grid.
      const key = [...speaking].sort().join(',');
      if (key === this.lastSpeaking) return;
      this.lastSpeaking = key;
      this.options.onSpeaking(speaking);
    }, SPEAKING_POLL_MS);
  }

  /**
   * Takes one peer out of the mesh: their tracks, their link and their meter.
   *
   * The reading is taken before the connection is closed, because after it is
   * closed there is nothing left to read - which is how a call that lost four
   * people one at a time used to report the traffic of only the last one.
   */
  private drop(peerId: string): void {
    const link = this.links.get(peerId);
    this.links.delete(peerId);
    // Before the early return below: a peer who leaves mid-rebuild has no link
    // to find here, and must still not have one built for them afterwards.
    this.peerIsExpected.delete(peerId);
    this.rebuilds.delete(peerId);
    for (const slot of SLOTS) this.options.onTrack(peerId, slot, null);
    this.announcePeers();
    if (!link) return;

    void link
      .sample()
      .then((sample) => {
        this.retiredLinks.push(reportOf(link.peer, sample));
      })
      .catch(() => undefined)
      .finally(() => {
        this.lastSamples.delete(peerId);
        link.close();
      });
  }

  private send(event: ClientCallEvent): void {
    if (this.socket?.readyState === WebSocket.OPEN) this.socket.send(JSON.stringify(event));
  }

  close(): void {
    this.closed = true;
    if (this.speakingTimer !== null) window.clearInterval(this.speakingTimer);
    this.speakingTimer = null;

    // The last reading of every live link, taken before it is closed and before
    // the socket goes, because both of those destroy the only counters there
    // are: the gateway is not in the media path and has nothing of its own to
    // count. Everything else about the call is torn down now; only the goodbye
    // waits, and `closed` already stops anything else being sent.
    const live = [...this.links.values()];
    this.links.clear();
    this.lastSamples.clear();
    this.local.clear();

    void Promise.all(
      live.map((link) =>
        link
          .sample()
          .then((sample) => reportOf(link.peer, sample))
          .catch(() => null),
      ),
    )
      .catch(() => [])
      .then((reports) => {
        const links = [...this.retiredLinks, ...reports.flatMap((report) => (report ? [report] : []))];
        const bytesSent = links.reduce((total, link) => total + link.bytesSent, 0);
        const bytesReceived = links.reduce((total, link) => total + link.bytesReceived, 0);

        this.send({ type: 'leave', bytes: bytesSent + bytesReceived, bytesSent, bytesReceived, links });
        for (const link of live) link.close();
        this.socket?.close();
        this.socket = null;
      });
  }
}

/**
 * One link's last reading, as the log stores it.
 *
 * By `userId` rather than by peer id: a peer id lives as long as a socket and
 * means nothing a month later, and the question the log answers is who the call
 * was with.
 */
function reportOf(peer: CallPeer, sample: LinkSample): CallLinkReport {
  return {
    userId: peer.userId,
    username: peer.username,
    bytesSent: sample.outboundAudioBytes + sample.outboundVideoBytes,
    bytesReceived: sample.inboundAudioBytes + sample.inboundVideoBytes,
    roundTripMs:
      sample.roundTripSeconds === null ? null : Math.round(sample.roundTripSeconds * 1000),
    packetsLost: sample.packetsLost,
    packetsReceived: sample.packetsReceived,
    transport: sample.transport,
  };
}

/** Self-check: `pnpm --filter @betweenus/desktop check`. Message body encoding. */
import assert from 'node:assert/strict';
import type { MessageAttachment } from '@betweenus/shared-types';
import {
  OVERFLOW_CHARS,
  REPLY_PREVIEW_CHARS,
  decodeBody,
  encodeBody,
  overflowFile,
  replyPreview,
} from './message-body';

const file: MessageAttachment = {
  key: 'attachments/u1/2026-08/abc',
  url: '/api/v1/uploads/attachments/u1/2026-08/abc',
  name: 'holiday.webp',
  contentType: 'image/webp',
  size: 1234,
  iv: 'aXYtaXMtYmFzZTY0',
  epoch: 3,
  width: 1920,
  height: 1080,
};

async function main(): Promise<void> {
  // A message with no files stays the bare text it always was, so history
  // written before attachments existed still reads back unchanged.
  assert.equal(encodeBody({ text: 'hello', attachments: [] }), 'hello');
  assert.deepEqual(decodeBody('hello'), { text: 'hello', attachments: [] });

  // Including text that looks like an encoded body but was merely typed.
  const impostor = 'betweenus-body:1\n{"text":"nope","attachments":[]}';
  assert.deepEqual(decodeBody(impostor), { text: impostor, attachments: [] });
  assert.deepEqual(decodeBody('{"text":"nope"}'), {
    text: '{"text":"nope"}',
    attachments: [],
  });

  // With files it round-trips whole.
  const body = { text: 'look at this', attachments: [file] };
  const encoded = encodeBody(body);
  assert.equal(encoded.startsWith('\u0000'), true);
  assert.deepEqual(decodeBody(encoded), body);

  // A body damaged in transit renders as text instead of throwing into the UI.
  assert.deepEqual(decodeBody('\u0000betweenus-body:1\nnot json'), {
    text: '\u0000betweenus-body:1\nnot json',
    attachments: [],
  });

  // A reply carries no files and is still a document, because the quote has to
  // survive the round trip.
  const reply = {
    text: 'agreed',
    attachments: [],
    replyTo: { id: 'm-1', author: 'Ada', preview: 'shall we ship it' },
  };
  assert.deepEqual(decodeBody(encodeBody(reply)), reply);

  // A quote with no id is dropped rather than rendered as an unclickable block.
  assert.deepEqual(
    decodeBody('\u0000betweenus-body:1\n{"text":"hi","attachments":[],"replyTo":{"author":"Ada"}}'),
    { text: 'hi', attachments: [] },
  );

  // A forward is a document too: text alone would lose the tag that says the
  // words are somebody else's, which is the only thing marking it as a forward.
  const forwarded = {
    text: 'worth reading',
    attachments: [],
    forwardedFrom: { author: 'Ada', channel: 'general' },
  };
  assert.deepEqual(decodeBody(encodeBody(forwarded)), forwarded);

  // Without an author there is nothing for the tag to say, so it is not a forward.
  assert.deepEqual(
    decodeBody('\u0000betweenus-body:1\n{"text":"hi","attachments":[],"forwardedFrom":{"channel":"general"}}'),
    { text: 'hi', attachments: [] },
  );

  // Quotes are one line, however many the original had.
  assert.equal(replyPreview('  two\n\nlines  '), 'two lines');
  assert.equal(replyPreview('x'.repeat(500)).length, REPLY_PREVIEW_CHARS);
  assert.equal(replyPreview('x'.repeat(500)).endsWith('…'), true);

  // Custom emoji: no files, no quote, and still a document, because the
  // pictures have to travel with the text.
  const withEmoji = {
    text: 'ship it :shipit:',
    attachments: [],
    emoji: [
      { name: 'shipit', url: '/api/v1/uploads/pictures/u1/2026-08/a.webp', animated: false },
    ],
  };
  assert.deepEqual(decodeBody(encodeBody(withEmoji)), withEmoji);

  // An over-long message becomes a text file that keeps every character.
  const long = 'x'.repeat(OVERFLOW_CHARS + 500);
  const overflow = overflowFile(long);
  assert.equal(overflow.name, 'message.txt');
  assert.equal(overflow.type, 'text/plain');
  assert.equal(await overflow.text(), long);

  console.log('message body check ok');
}

void main();

/**
 * How a message body is written down once it can carry more than text.
 *
 * No imports on purpose: the encoding is the contract between two clients, and
 * keeping it free of app wiring means it also runs under Node for
 * `pnpm --filter @betweenus/desktop check`.
 *
 * A message with no files is still stored as the bare text a person typed, so
 * every row written before attachments existed keeps rendering exactly as it
 * did. Only a message that carries files becomes a JSON document, and it is
 * hidden behind a marker starting with a NUL - a character a textarea cannot
 * produce, so nobody can type a message that pretends to be one.
 */
import type { MessageBody } from '@betweenus/shared-types';

/** Longer than this and a message is sent as a text file, the way Discord does. */
export const OVERFLOW_CHARS = 2000;

const BODY_MARKER = '\u0000betweenus-body:1\n';

export function encodeBody(body: MessageBody): string {
  const plain =
    body.attachments.length === 0 &&
    !body.replyTo &&
    !body.forwardedFrom &&
    (body.emoji?.length ?? 0) === 0;
  if (plain) return body.text;
  return BODY_MARKER + JSON.stringify(body);
}

export function decodeBody(content: string): MessageBody {
  if (!content.startsWith(BODY_MARKER)) return { text: content, attachments: [] };

  try {
    const parsed = JSON.parse(content.slice(BODY_MARKER.length)) as MessageBody;
    const reply = parsed.replyTo;
    const forwarded = parsed.forwardedFrom;
    return {
      text: typeof parsed.text === 'string' ? parsed.text : '',
      attachments: Array.isArray(parsed.attachments) ? parsed.attachments : [],
      // The pictures for whatever `:name:` the text contains. A body without
      // them renders the shortcodes as the words they are, which is what every
      // client written before this did.
      ...(Array.isArray(parsed.emoji) ? { emoji: parsed.emoji } : {}),
      // A quote with no id is not a quote: it would render as a block nothing
      // can be clicked through to.
      ...(reply && typeof reply.id === 'string' && reply.id.length > 0
        ? {
            replyTo: {
              id: reply.id,
              author: typeof reply.author === 'string' ? reply.author : '',
              preview: typeof reply.preview === 'string' ? reply.preview : '',
            },
          }
        : {}),
      // Who the words belonged to before somebody carried them here. Without
      // an author there is nothing for the tag to say, so it is not a forward.
      ...(forwarded && typeof forwarded.author === 'string' && forwarded.author.length > 0
        ? {
            forwardedFrom: {
              author: forwarded.author,
              channel: typeof forwarded.channel === 'string' ? forwarded.channel : '',
            },
          }
        : {}),
    };
  } catch {
    // A body we cannot read is still a message; show it rather than nothing.
    return { text: content, attachments: [] };
  }
}

/** How much of the quoted message a reply carries with it. */
export const REPLY_PREVIEW_CHARS = 140;

/**
 * The snippet a reply quotes. One line: a quote that reflows to six defeats
 * the point of a quote.
 */
export function replyPreview(text: string): string {
  const line = text.replace(/\s+/g, ' ').trim();
  return line.length > REPLY_PREVIEW_CHARS
    ? `${line.slice(0, REPLY_PREVIEW_CHARS - 1)}…`
    : line;
}

/**
 * The file an over-long message becomes. Sent as text it would be truncated by
 * the server's length cap and would bury the channel; as a file it keeps every
 * character and gets a preview instead.
 */
export function overflowFile(text: string): File {
  return new File([text], 'message.txt', { type: 'text/plain' });
}

/**
 * The noise gate, and the level meter that shares its arithmetic.
 *
 * Noise suppression cleans up a signal. It does not decide that nobody is
 * talking - so a suppressed fan is a quieter fan, still in the call. What makes
 * a Discord call silent between sentences is a gate: below a threshold the
 * microphone is simply closed. Discord calls the threshold input sensitivity,
 * and it is the single control that most changes what other people hear.
 *
 * It runs in an AudioWorklet, which matters for two reasons that are not
 * obvious:
 *
 * - **The audio thread does not get throttled.** A gate driven from the main
 *   thread by a timer stops running when Electron backgrounds the window, which
 *   is exactly when somebody is not looking at the call and most needs it to
 *   behave.
 * - **It can act between samples.** The decision has to be made at the top of a
 *   word, not 100 ms later; a gate on a 100 ms poll clips every sentence's first
 *   consonant.
 *
 * The worklet is assembled from `stepGate`'s own source rather than a copy of
 * it, so the logic under the self-check is the logic on the audio thread. That
 * is why `stepGate` and `amplitudeToDb` close over nothing: a worklet is a
 * separate global scope and anything they referenced would be undefined there.
 *
 * ponytail: no gate where AudioWorklet is missing - the track is passed straight
 * through, which is what the microphone did before this existed. Electron has
 * had worklets since long before the version this app runs on.
 */
import { amplitudeToDb, deviceConstraint, stepGate, type AudioProcessor } from './voice-quality';
import { openAudioCapture } from './audio-devices';

/** How often the worklet reports the level back, in seconds. */
const REPORT_INTERVAL = 0.05;

/**
 * A function's compiled name is not its source name after a production build,
 * and a build is free to emit it as an arrow. Binding the source to a name here
 * survives both: a named function expression and an arrow are both expressions.
 */
function named(fn: { toString(): string }, name: string): string {
  return `const ${name} = ${fn.toString()};`;
}

const WORKLET_SOURCE = `
${named(amplitudeToDb, 'amplitudeToDb')}
${named(stepGate, 'stepGate')}

class BetweenUsGate extends AudioWorkletProcessor {
  constructor() {
    super();
    this.thresholdDb = null;
    this.state = { open: false, heldUntil: 0 };
    this.gain = 1;
    this.reportedAt = 0;
    this.port.onmessage = (event) => {
      this.thresholdDb = event.data.thresholdDb;
    };
  }

  process(inputs, outputs) {
    const input = inputs[0];
    const output = outputs[0];
    if (!input || input.length === 0) return true;

    let sum = 0;
    let count = 0;
    for (const channel of input) {
      for (let i = 0; i < channel.length; i += 1) sum += channel[i] * channel[i];
      count += channel.length;
    }
    const db = amplitudeToDb(count > 0 ? Math.sqrt(sum / count) : 0);

    if (this.thresholdDb === null) {
      this.state = { open: true, heldUntil: 0 };
    } else {
      this.state = stepGate(this.state, db, this.thresholdDb, currentTime);
    }

    // Ramped per sample: 5 ms to open, 150 ms to close. Opening any slower eats
    // the start of a word; closing any faster is an audible click.
    const target = this.state.open ? 1 : 0;
    const step = (target > this.gain ? 1 / 0.005 : -1 / 0.15) / sampleRate;

    for (let channel = 0; channel < output.length; channel += 1) {
      const from = input[Math.min(channel, input.length - 1)];
      const to = output[channel];
      let gain = this.gain;
      for (let i = 0; i < to.length; i += 1) {
        gain = Math.min(1, Math.max(0, gain + step));
        to[i] = from[i] * gain;
      }
      if (channel === output.length - 1) this.gain = gain;
    }

    if (currentTime - this.reportedAt >= ${REPORT_INTERVAL}) {
      this.reportedAt = currentTime;
      this.port.postMessage({ db, open: this.state.open });
    }

    return true;
  }
}

registerProcessor('betweenus-gate', BetweenUsGate);
`;

let moduleUrl: string | null = null;
/** Registering the same processor name twice in one context throws. */
const registered = new WeakSet<AudioContext>();

async function addWorklet(context: AudioContext): Promise<boolean> {
  if (registered.has(context)) return true;
  try {
    moduleUrl ??= URL.createObjectURL(new Blob([WORKLET_SOURCE], { type: 'text/javascript' }));
    await context.audioWorklet.addModule(moduleUrl);
    registered.add(context);
    return true;
  } catch (error) {
    console.warn('[mic-gate] no worklet, microphone passes through ungated:', error);
    return false;
  }
}

export interface MicLevel {
  /** Loudness of the last block, in dBFS. -100 is silence. */
  db: number;
  /** Whether the gate is letting it through. */
  open: boolean;
}

/**
 * The gate as an audio processor: it sits between the captured microphone and
 * the track that is actually sent, so what the gate closes never reaches
 * anybody. The voice store puts `processedTrack` on the senders rather than the
 * raw capture, which is the whole point of it.
 */
export class NoiseGate implements AudioProcessor {
  readonly name = 'betweenus-noise-gate';

  processedTrack?: MediaStreamTrack;

  private thresholdDb: number | null = null;
  private node: AudioWorkletNode | null = null;
  private source: MediaStreamAudioSourceNode | null = null;
  private destination: MediaStreamAudioDestinationNode | null = null;
  private listener: ((level: MicLevel) => void) | null = null;

  constructor(thresholdDb: number | null) {
    this.thresholdDb = thresholdDb;
  }

  async init(options: { track: MediaStreamTrack; audioContext: AudioContext }): Promise<void> {
    const context = options.audioContext;
    this.source = context.createMediaStreamSource(new MediaStream([options.track]));
    this.destination = context.createMediaStreamDestination();

    if (await addWorklet(context)) {
      this.node = new AudioWorkletNode(context, 'betweenus-gate');
      this.node.port.onmessage = (event: MessageEvent<MicLevel>) => this.listener?.(event.data);
      this.source.connect(this.node).connect(this.destination);
      this.setThreshold(this.thresholdDb);
    } else {
      this.source.connect(this.destination);
    }

    this.processedTrack = this.destination.stream.getAudioTracks()[0];
  }

  async restart(options: { track: MediaStreamTrack; audioContext: AudioContext }): Promise<void> {
    await this.destroy();
    await this.init(options);
  }

  async destroy(): Promise<void> {
    this.source?.disconnect();
    this.node?.disconnect();
    this.destination?.disconnect();
    this.source = null;
    this.node = null;
    this.destination = null;
    this.processedTrack = undefined;
  }

  /** `null` is an open mic. Takes effect on the next block, without republishing. */
  setThreshold(thresholdDb: number | null): void {
    this.thresholdDb = thresholdDb;
    this.node?.port.postMessage({ thresholdDb });
  }

  /** For a meter. One listener - there is one settings screen. */
  onLevel(listener: ((level: MicLevel) => void) | null): void {
    this.listener = listener;
  }
}

/**
 * Opens the microphone on its own to drive the meter in settings, so the
 * threshold can be set without being in a call. Returns a stop function.
 *
 * Deliberately a second capture rather than a tap on the live one: the settings
 * screen is opened while a call is running as often as not, and Windows is
 * perfectly happy to hand the same microphone to two capturers.
 */
export async function monitorMic(
  deviceId: string | null,
  thresholdDb: number | null,
  onLevel: (level: MicLevel) => void,
): Promise<() => void> {
  // The same `exact` constraint the call itself captures with, or the meter
  // would sit there measuring the default microphone while somebody adjusts the
  // sensitivity of a different one.
  const stream = await openAudioCapture(deviceConstraint(deviceId));
  const track = stream.getAudioTracks()[0];
  if (!track) throw new Error('That microphone handed back no audio');
  const context = new AudioContext();
  const gate = new NoiseGate(thresholdDb);

  gate.onLevel(onLevel);
  await gate.init({ track, audioContext: context });

  return () => {
    gate.onLevel(null);
    void gate.destroy();
    track.stop();
    void context.close().catch(() => undefined);
  };
}

/**
 * Exported for the self-check. Splicing one function's source into another
 * program is the kind of thing that works until a build renames something, so
 * the check compiles this string and fails if it is not valid JavaScript.
 */
export const workletSource = WORKLET_SOURCE;

/**
 * The half of `prefers-reduced-motion` that CSS cannot reach.
 *
 * `index.css` flattens every animation and transition under the media query,
 * which covers everything the stylesheet starts. It does not cover a scroll
 * this app starts itself: `scrollTo({ behavior: 'smooth' })` and
 * `scrollIntoView({ behavior: 'smooth' })` take the behaviour as an argument
 * and consult nothing. So the conversation kept gliding for somebody who had
 * asked the whole machine to stop moving - and gliding a full message list is
 * the largest single movement in the client, which makes it the one worth
 * having asked about.
 *
 * `'auto'` in `scrollBehavior` means *jump*, which is the browser's word for it
 * rather than a choice made here. The message still arrives at the same place;
 * it arrives without travelling there.
 */

/**
 * Read live rather than cached. The setting is changed in the OS while the app
 * is running, and a value read once at import is one that is wrong for the rest
 * of the session - the failure this would otherwise have is invisible, because
 * it only shows up for the people who changed the setting.
 *
 * `false` where `matchMedia` does not exist: an environment that cannot be
 * asked has not asked for less motion.
 */
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined' || !window.matchMedia) return false;
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

/** What to pass as `behavior` to a scroll this app starts. */
export function scrollBehavior(): ScrollBehavior {
  return prefersReducedMotion() ? 'auto' : 'smooth';
}

/**
 * Desktop notifications.
 *
 * The rule lives here rather than in the stores: notify when the user cannot
 * already see the thing, and when they have not said otherwise. "Otherwise" is
 * four things - the account's own switch, the channel's own level (everything,
 * mentions only, or nothing), its quiet hours, and a Do Not Disturb status. The first three come from notification-service,
 * so they follow the account to another machine; the fourth is live presence.
 *
 * The OS half - the notification itself, the taskbar flash, the tray, restoring
 * the window on a click - belongs to the Electron main process. In a plain
 * browser (`pnpm --filter @betweenus/desktop dev` in a tab) the bridge is absent
 * and every call here is a no-op.
 */
import type {
  ChannelNotificationLevel,
  NotificationPreferences,
} from '@betweenus/shared-types';
import { api } from './api';
import { usePresenceStore } from '../stores/presence';

/** True when this window is on screen and has keyboard focus. */
export function windowIsFocused(): boolean {
  return typeof document !== 'undefined' && !document.hidden && document.hasFocus();
}

const DEFAULTS: NotificationPreferences = {
  enabled: true,
  quietStartMinute: null,
  quietEndMinute: null,
  mutedChannelIds: [],
  mentionOnlyChannelIds: [],
  mutedUserIds: [],
};

// Held in a module rather than a store: the decision is taken inside a socket
// callback, where a hook cannot be read, and every component that needs the
// values reads them through `notificationPreferences()`.
let preferences: NotificationPreferences = DEFAULTS;
const listeners = new Set<(preferences: NotificationPreferences) => void>();

function publish(next: NotificationPreferences): NotificationPreferences {
  preferences = next;
  for (const listener of listeners) listener(next);
  return next;
}

export function notificationPreferences(): NotificationPreferences {
  return preferences;
}

/** Fires whenever preferences change, from this window or from a reload. */
export function onPreferencesChanged(
  listener: (preferences: NotificationPreferences) => void,
): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Loaded once a session is up. A failure leaves the defaults in place. */
export async function loadNotificationPreferences(): Promise<NotificationPreferences> {
  try {
    return publish(await api.notificationPreferences());
  } catch {
    return preferences;
  }
}

export async function updateNotificationPreferences(
  patch: Partial<NotificationPreferences>,
): Promise<NotificationPreferences> {
  return publish(await api.updateNotificationPreferences(patch));
}

export function resetNotificationPreferences(): void {
  publish(DEFAULTS);
}

/** True when this account has muted that person, wherever they write. */
export function isUserMuted(userId: string): boolean {
  return preferences.mutedUserIds.includes(userId);
}

/**
 * Mutes or unmutes one person.
 *
 * A person rather than a place: muting five channels because one of them is
 * loud takes four channels away that were not the problem, and leaving is not
 * an option for a colleague. It follows the account, like every other
 * preference here, so it holds on the next machine.
 */
export async function setUserMuted(userId: string, muted: boolean): Promise<void> {
  const next = muted
    ? [...new Set([...preferences.mutedUserIds, userId])]
    : preferences.mutedUserIds.filter((id) => id !== userId);

  publish(await api.updateNotificationPreferences({ mutedUserIds: next }));
}

export function isChannelMuted(channelId: string): boolean {
  return preferences.mutedChannelIds.includes(channelId);
}

/**
 * What this channel's bell is set to.
 *
 * A mute wins over mentions-only, so the two lists cannot contradict each other
 * however they were written - a client that only knows about muting can add a
 * channel to that list and the answer is still "none".
 */
export function channelLevel(channelId: string): ChannelNotificationLevel {
  if (preferences.mutedChannelIds.includes(channelId)) return 'none';
  if (preferences.mentionOnlyChannelIds.includes(channelId)) return 'mentions';
  return 'all';
}

/** The order the bell cycles through, which is loudest to quietest. */
export const CHANNEL_LEVELS: ChannelNotificationLevel[] = ['all', 'mentions', 'none'];

export async function setChannelLevel(
  channelId: string,
  level: ChannelNotificationLevel,
): Promise<void> {
  const without = (list: string[]): string[] => list.filter((id) => id !== channelId);
  // Both lists are sent every time, so a channel is in exactly one of them and
  // a level that moved cannot leave its old entry behind.
  await updateNotificationPreferences({
    mutedChannelIds:
      level === 'none'
        ? [...new Set([...preferences.mutedChannelIds, channelId])]
        : without(preferences.mutedChannelIds),
    mentionOnlyChannelIds:
      level === 'mentions'
        ? [...new Set([...preferences.mentionOnlyChannelIds, channelId])]
        : without(preferences.mentionOnlyChannelIds),
  });
}

export async function setChannelMuted(channelId: string, muted: boolean): Promise<void> {
  await setChannelLevel(channelId, muted ? 'none' : 'all');
}

/**
 * Quiet hours are minutes on the user's own clock, and a window is allowed to
 * wrap midnight - 22:00 to 08:00 is start 1320, end 480, which is "outside the
 * ordinary comparison" rather than an empty range.
 */
export function inQuietHours(now = new Date()): boolean {
  const { quietStartMinute: start, quietEndMinute: end } = preferences;
  if (start === null || end === null || start === end) return false;

  const minute = now.getHours() * 60 + now.getMinutes();
  return start < end ? minute >= start && minute < end : minute >= start || minute < end;
}

/**
 * Everything that silences a notification, whatever it is about.
 *
 * `mentioned` is what the middle level turns on: a channel set to mentions-only
 * is silent for everything else, and anything that is not a message at all -
 * somebody joining a voice channel - is never a mention and so is silent there
 * too, which is the point of setting a busy channel to mentions.
 */
function silenced(channelId: string, mentioned = false): boolean {
  if (
    !preferences.enabled ||
    inQuietHours() ||
    usePresenceStore.getState().selfStatus === 'dnd'
  ) {
    return true;
  }

  const level = channelLevel(channelId);
  if (level === 'none') return true;
  return level === 'mentions' && !mentioned;
}

interface MessageNotification {
  channelId: string;
  channelName: string;
  author: string;
  /** Who wrote it, for the per-person mute. The envelope carries this. */
  authorId?: string;
  /** Decrypted body, or null when this device holds no key for the channel. */
  text: string | null;
  /** Is this the channel currently open? */
  active: boolean;
  /** Decided by the window that decrypted it - see `mentions.ts`. */
  mentioned?: boolean;
}

export function notifyMessage(message: MessageNotification): void {
  // A muted person is silent even when they mention you: "wherever they write"
  // includes writing your name, and a mute that any mention could bypass would
  // be a mute the loud person controls.
  if (message.authorId && isUserMuted(message.authorId)) return;
  if (silenced(message.channelId, message.mentioned ?? false)) return;

  // Whether the window is really focused is the main process's answer, not
  // this one's - so `active` is passed along rather than resolved here.
  raise(
    `${message.author} in #${message.channelName}`,
    message.text ?? 'Sent an encrypted message',
    message.channelId,
    message.active,
  );
}

/** Someone joined a voice channel this user is not in - the "call" case. */
export function notifyVoiceJoin(channelId: string, channelName: string, who: string): void {
  if (silenced(channelId)) return;
  raise(`${who} joined ${channelName}`, 'Voice channel', channelId);
}

/**
 * Somebody is ringing this account into a call.
 *
 * Whether the ring itself is *allowed* is not decided here - the server has
 * already dropped it for an account with notifications off or with this person
 * muted, and `useRingStore` decides whether it is worth showing at all. This
 * only raises the operating system's half of it, for the window that is behind
 * something else, which is most of the windows a ring arrives at.
 *
 * The channel's own notification level is deliberately not consulted. Muting a
 * room is saying you do not want to hear about the room, not that a colleague
 * may never call you from it - the same rule the server and the phone apply.
 * Quiet hours and Do Not Disturb still hold: those are "not now", not "not
 * this channel", and they are the two settings a person sets about themselves.
 */
export function notifyRing(channelId: string, channelName: string, caller: string): void {
  if (!preferences.enabled) return;
  if (inQuietHours()) return;
  if (usePresenceStore.getState().selfStatus === 'dnd') return;
  raise(`${caller} is calling`, `Ringing you into ${channelName}`, channelId);
}

/** Handlers waiting on a click, in the web client. Electron keeps its own. */
const clickHandlers = new Set<(channelId: string) => void>();

/**
 * One notification, however this runtime raises one.
 *
 * Electron's main process owns it: only that side knows whether the window is
 * really focused, and only that side can flash a taskbar entry. A browser tab
 * has the Notifications API and nothing else - so it has to answer the focus
 * question itself, which it can, because a visible tab showing the channel the
 * message arrived in is exactly the case not worth interrupting.
 */
function raise(title: string, body: string, channelId?: string, active = false): void {
  const bridge = window.betweenus;
  if (bridge) {
    bridge.notify(title, body, channelId, active);
    return;
  }

  if (typeof Notification === 'undefined') return;
  if (active && document.visibilityState === 'visible') return;

  // Asked for at the first notification worth raising rather than at sign-in:
  // a permission prompt on the way into the app is the one people refuse.
  //
  // The notification it was asked for is then shown, rather than dropped. It
  // used to return here, so the first message after granting produced nothing
  // and every message before the prompt was answered produced nothing either -
  // which, on a deployment with no VAPID keys (the only other thing that ever
  // prompts), is every message until somebody granted it from the URL bar.
  if (Notification.permission === 'default') {
    void Notification.requestPermission().then((permission) => {
      if (permission === 'granted') show(title, body, channelId);
    });
    return;
  }
  if (Notification.permission !== 'granted') return;

  show(title, body, channelId);
}

/**
 * The toast standing for each channel, in a browser tab.
 *
 * `tag` already collapses a run of messages into one toast, but it gives no
 * handle on the toast it collapsed onto - and a handle is exactly what is
 * needed to take one away again. Electron keeps the same map on its own side,
 * for its own notifications.
 */
const standing = new Map<string, Notification>();

/** The toast itself, once permission is known to be granted. */
function show(title: string, body: string, channelId?: string): void {
  // `tag` collapses a run of messages in one channel into a single toast,
  // which is what the main process does with its own notifications.
  const note = new Notification(title, { body, tag: channelId });
  note.onclick = () => {
    window.focus();
    if (channelId) for (const handler of clickHandlers) handler(channelId);
    note.close();
  };
  if (!channelId) return;
  standing.set(channelId, note);
  // A toast the person dismissed themselves is not one to hold a handle on.
  note.onclose = () => {
    if (standing.get(channelId) === note) standing.delete(channelId);
  };
}

/**
 * Take away the notification for a conversation that has been read elsewhere.
 *
 * The other half of push suppression, and the half that was missing here. Not
 * being woken for a channel open on another device stops a *new* notification;
 * this is what happens to one that is already standing when somebody answers it
 * from a laptop. A notification for something already dealt with is a request
 * to check the same thing twice.
 *
 * Safe to call for a channel with nothing showing, which is most calls: the
 * read marker moves every time anybody reads anything.
 */
export function dismissChannelNotification(channelId: string): void {
  const bridge = window.betweenus;
  if (bridge) {
    bridge.dismissNotification(channelId);
    return;
  }
  const note = standing.get(channelId);
  if (!note) return;
  standing.delete(channelId);
  note.close();
}

/** Runs `handler` when the user clicks a notification. */
export function onNotificationActivate(handler: (channelId: string) => void): () => void {
  const unsubscribe = window.betweenus?.onNotificationActivate(handler);
  if (unsubscribe) return unsubscribe;
  clickHandlers.add(handler);
  return () => clickHandlers.delete(handler);
}

/** Total unread, for the tray tooltip and the dock badge. */
export function publishUnreadCount(count: number): void {
  const bridge = window.betweenus;
  if (bridge) {
    bridge.setUnreadCount(count);
    return;
  }
  // A tab has no tray and no dock; the title is the only badge it owns.
  document.title = count > 0 ? `(${count}) BetweenUs` : 'BetweenUs';
}

/**
 * Self-check for the centre crop a stored picture is framed to.
 *
 * Run with `pnpm --filter @betweenus/desktop check`. Worth pinning because the
 * two cases that go wrong are the two nobody has to hand while writing it: a
 * portrait photograph cropped down to a 4:1 band, and a panorama cropped up to
 * a square. Both are arithmetic, so neither needs a browser to test.
 */
import assert from 'node:assert/strict';
import { COVER_ASPECT } from '@betweenus/shared-types';
import { cropBox } from './attachments';

// --- a square out of a landscape photograph ----------------------------------

const wideToSquare = cropBox(1600, 900, 1);
assert.equal(wideToSquare.width, 900, 'the short edge is what a square is limited by');
assert.equal(wideToSquare.height, 900);
assert.equal(wideToSquare.x, 350, 'and it is taken from the middle');
assert.equal(wideToSquare.y, 0, 'with nothing to trim vertically');

// --- a square out of a portrait photograph -----------------------------------

const tallToSquare = cropBox(900, 1600, 1);
assert.equal(tallToSquare.width, 900);
assert.equal(tallToSquare.height, 900);
assert.equal(tallToSquare.x, 0);
assert.equal(tallToSquare.y, 350);

// --- a cover band out of an ordinary photograph ------------------------------

// 4:3 is far taller than 4:1, so the full width is kept and the height is cut.
const band = cropBox(4000, 3000, COVER_ASPECT);
assert.equal(band.width, 4000, 'a photograph narrower than the band keeps its width');
assert.equal(band.height, 1000, 'and gives up height until it is the right shape');
assert.equal(band.x, 0);
assert.equal(band.y, 1000, 'taken from the middle, so a horizon stays near the centre');

// --- a cover band out of something already wider than the band ---------------

// 8:1 is flatter than 4:1, so this time width is what runs out.
const flat = cropBox(8000, 1000, COVER_ASPECT);
assert.equal(flat.height, 1000, 'a panorama keeps its full height');
assert.equal(flat.width, 4000);
assert.equal(flat.y, 0);
assert.equal(flat.x, 2000);

// --- the shape is always what was asked for ----------------------------------

// The property that actually matters, over a spread of shapes: whatever goes
// in, the box that comes out is the requested aspect and fits inside the
// source. A crop that escaped the source draws transparent pixels down one
// edge, which is the bug this whole function exists to not have.
for (const [width, height] of [
  [100, 100],
  [1920, 1080],
  [1080, 1920],
  [3000, 401],
  [17, 4001],
] as const) {
  for (const aspect of [1, COVER_ASPECT, 16 / 9]) {
    const box = cropBox(width, height, aspect);
    assert.ok(
      Math.abs(box.width / box.height - aspect) < 1e-9,
      `${width}x${height} at ${aspect}: the crop is the requested shape`,
    );
    assert.ok(box.x >= 0 && box.y >= 0, 'the crop starts inside the picture');
    assert.ok(
      box.x + box.width <= width + 1e-9 && box.y + box.height <= height + 1e-9,
      'and ends inside it',
    );
  }
}

console.log('picture-crop: ok');

/**
 * Self-check for push to talk: `tsx src/services/push-to-talk.check.ts`.
 *
 * Against `talk-key.ts` rather than the listener, which imports the voice store
 * and everything behind it.
 *
 * Two rules decide whether a key press opens the microphone, and both fail in
 * ways nobody would report as a bug in push to talk: a key that also types
 * broadcasts whatever is being written into the composer, and an auto-repeating
 * key held down would re-open a microphone the release already closed.
 */
import assert from 'node:assert/strict';
import { describeKey, isTalkKey } from './talk-key';

const field = (tagName: string): EventTarget =>
  ({ tagName, isContentEditable: false }) as unknown as EventTarget;

const editable = { tagName: 'DIV', isContentEditable: true } as unknown as EventTarget;

// The configured key, pressed nowhere in particular.
assert.equal(isTalkKey({ code: 'AltRight' }, 'AltRight'), true);
assert.equal(isTalkKey({ code: 'AltLeft' }, 'AltRight'), false);

// Auto-repeat while the key is held is not a second press.
assert.equal(isTalkKey({ code: 'AltRight', repeat: true }, 'AltRight'), false);

// Typing is not talking. This is the whole reason the default key types
// nothing - somebody who binds Space still gets to write a message.
assert.equal(isTalkKey({ code: 'Space', target: field('INPUT') }, 'Space'), false);
assert.equal(isTalkKey({ code: 'Space', target: field('TEXTAREA') }, 'Space'), false);
assert.equal(isTalkKey({ code: 'Space', target: editable }, 'Space'), false);
assert.equal(isTalkKey({ code: 'Space', target: field('DIV') }, 'Space'), true);

// A key with nothing focused at all is still a key.
assert.equal(isTalkKey({ code: 'Space', target: null }, 'Space'), true);

// Labels a person can read, for the settings screen.
assert.equal(describeKey('AltRight'), 'Right Alt');
assert.equal(describeKey('KeyV'), 'V');
assert.equal(describeKey('Digit4'), '4');
assert.equal(describeKey('Numpad0'), 'Numpad 0');
// Anything unmapped reads as itself rather than as an empty button.
assert.equal(describeKey('F13'), 'F13');

console.log('push-to-talk check ok');

/**
 * Talk while a key is held.
 *
 * The gate answers "is somebody making a noise". This answers a different
 * question - "do you mean to be heard" - and no amount of tuning a threshold
 * gets there: a shared room, a mechanical keyboard and somebody else's phone
 * call are all above any threshold that still passes a quiet voice.
 *
 * ## What this is not
 *
 * It listens to the *window*, so it works while BetweenUs is focused and not while
 * it is behind something else. Discord's is global because it installs a
 * low-level keyboard hook; Electron's `globalShortcut` cannot stand in for one,
 * because it delivers a press and never a release - a push-to-talk that opens
 * the microphone and cannot be told when the key came back up is worse than
 * none at all.
 *
 * ponytail: a native hook per platform is the upgrade, and it is the whole of
 * the remaining work - everything below stays as it is.
 */
import { useAudioSettings } from '../stores/audioSettings';
import { useVoiceStore } from '../stores/voice';
import { isTalkKey } from './talk-key';

let attached = false;
let held = false;

function talk(talking: boolean): void {
  if (held === talking) return;
  held = talking;
  void useVoiceStore.getState().setTalking(talking);
}

function onKeyDown(event: KeyboardEvent): void {
  const settings = useAudioSettings.getState().settings;
  if (!settings.pushToTalk) return;
  if (!isTalkKey(event, settings.pushToTalkKey)) return;
  talk(true);
}

function onKeyUp(event: KeyboardEvent): void {
  const settings = useAudioSettings.getState().settings;
  if (event.code !== settings.pushToTalkKey) return;
  talk(false);
}

/**
 * A key released while another window has focus never arrives here, so losing
 * focus closes the microphone. The alternative is a key that got stuck down
 * because somebody alt-tabbed mid-sentence, which is the failure that makes
 * people stop trusting push to talk.
 */
function onBlur(): void {
  talk(false);
}

/** Starts listening. Safe to call twice; the second call does nothing. */
export function startPushToTalk(): void {
  if (attached) return;
  attached = true;
  window.addEventListener('keydown', onKeyDown);
  window.addEventListener('keyup', onKeyUp);
  window.addEventListener('blur', onBlur);
}

export function stopPushToTalk(): void {
  if (!attached) return;
  attached = false;
  window.removeEventListener('keydown', onKeyDown);
  window.removeEventListener('keyup', onKeyUp);
  window.removeEventListener('blur', onBlur);
  talk(false);
}

/** Run with `tsx src/services/reactions.check.ts`. Who reacted, as a sentence. */
import assert from 'node:assert/strict';
import { reactorNames, type Reactor } from './reactions';

const members: Reactor[] = [
  { userId: 'u1', username: 'ada', displayName: 'Ada Lovelace' },
  { userId: 'u2', username: 'bob', displayName: '' },
];

assert.equal(reactorNames([], members, 'me'), '');
assert.equal(reactorNames(['u1'], members, 'me'), 'Ada Lovelace');
// No display name falls back to the username rather than to nothing.
assert.equal(reactorNames(['u2'], members, 'me'), 'bob');
assert.equal(reactorNames(['u1', 'u2'], members, 'me'), 'Ada Lovelace and bob');

// "You" is always first, wherever the server put it in the list.
assert.equal(reactorNames(['u1', 'me'], members, 'me'), 'You and Ada Lovelace');
assert.equal(reactorNames(['u1', 'me', 'u2'], members, 'me'), 'You, Ada Lovelace and bob');

// A member who has left, and a direct message, where there is no member list at
// all: counted rather than named.
assert.equal(reactorNames(['gone'], members, 'me'), '1 other');
assert.equal(reactorNames(['gone', 'also-gone'], [], undefined), '2 others');
assert.equal(reactorNames(['u1', 'gone'], members, 'me'), 'Ada Lovelace and 1 other');
assert.equal(reactorNames(['me', 'gone'], members, 'me'), 'You and 1 other');

console.log('reactions.check.ts ok');

/**
 * Who reacted, as a sentence.
 *
 * A reaction summary carries user ids rather than names, because the same
 * object is broadcast to everybody and a name resolved on the server would be
 * one round trip per emoji per message. The names are looked up here, against
 * the member list the client already holds.
 *
 * Pure and on its own so it can be checked under Node: the joining is the part
 * with a bug in it - an empty list, a list of one, and "you" belonging at the
 * front rather than wherever the server happened to put it.
 */

/** Just enough of a member to name them. */
export interface Reactor {
  userId: string;
  username: string;
  displayName: string;
}

export function reactorNames(
  userIds: readonly string[],
  members: readonly Reactor[],
  meId: string | undefined,
): string {
  const named: string[] = [];
  let unknown = 0;

  for (const id of userIds) {
    if (id === meId) {
      // Always first. "Ada, you and Bob" is not how anybody says it.
      named.unshift('You');
      continue;
    }
    const member = members.find((item) => item.userId === id);
    if (member) named.push(member.displayName || member.username);
    // Somebody who has left, or anybody at all in a direct message - there is
    // no member list there. Counted rather than named: "and 2 others" is
    // honest, and inventing a name for an id is not.
    else unknown += 1;
  }

  if (unknown > 0) named.push(`${unknown} other${unknown === 1 ? '' : 's'}`);
  if (named.length === 0) return '';
  if (named.length === 1) return named[0]!;
  return `${named.slice(0, -1).join(', ')} and ${named[named.length - 1]}`;
}

/**
 * The agent: this machine, offering itself for remote access.
 *
 * It is part of the desktop app rather than a service of its own, because the
 * app is already on the machine and already has everything an agent needs -
 * screen capture, a WebRTC stack, and an OS keychain to keep a credential
 * in. `apps/services/remote-agent` stays reserved for a headless server that
 * has no BetweenUs window to run inside.
 *
 * Nothing here decides what a controller may do. The gateway checked the grant
 * before the session existed and refuses every event the session was not
 * granted; by the time an input event arrives here it has already been allowed.
 * The one decision this side makes is whether to accept the session at all.
 */
import { create } from 'zustand';
import type {
  AgentRemoteEvent,
  IceServer,
  RemotePermission,
  ServerRemoteEvent,
} from '@betweenus/shared-types';
import { api } from './api';
import { wsUrl } from './endpoint';
import { secureGet, secureSet } from './e2ee';
import { ScreenLink } from './remote-peer';
import { TransferSink, safeFileName } from './remote-transfer';
import { shareOptions } from './share-quality';
import { useAudioSettings } from '../stores/audioSettings';

const TOKEN_KEY = 'remote.agentToken';
const MACHINE_KEY = 'remote.machineId';
/** Machine-local, not per account: enabling remote access is a machine decision. */
const ENABLED_KEY = 'betweenus.remote.enabled';

/** A request from someone who is not the owner is refused if nobody answers. */
const CONSENT_TIMEOUT_MS = 30_000;

interface PendingSession {
  sessionId: string;
  controllerName: string;
  permissions: RemotePermission[];
}

interface ActiveSession {
  sessionId: string;
  controllerName: string;
  permissions: RemotePermission[];
}

/** Somebody asking for the mouse and keyboard part way through a session. */
interface ControlRequest {
  sessionId: string;
  controllerName: string;
}

interface AgentState {
  /** The switch in settings. Off is off: no socket, no enrolment, nothing. */
  enabled: boolean;
  machineId: string | null;
  machineName: string;
  status: 'off' | 'connecting' | 'online' | 'error';
  error: string | null;
  /** True on a platform where a controller can actually type; view-only elsewhere. */
  controlSupported: boolean;
  /** Waiting for the person at this machine to say yes. */
  pending: PendingSession | null;
  /** A live session where the controller has asked for control. */
  controlRequest: ControlRequest | null;
  session: ActiveSession | null;
  enable: () => Promise<void>;
  disable: () => Promise<void>;
  accept: () => void;
  refuse: (reason?: string) => void;
  /** Answers a request for the mouse and keyboard on a session already running. */
  answerControl: (granted: boolean) => void;
  /** Ends the session from this side - the machine's owner pulling the plug. */
  endSession: () => void;
  /** Called at sign-in; reconnects if the switch was left on. */
  restore: (ownerId: string) => Promise<void>;
}

let socket: WebSocket | null = null;
/** Unsubscribes the display watcher while a session is running. */
let unwatchDisplays: (() => void) | null = null;
/** The connection carrying this machine's screen to whoever is watching it. */
let link: ScreenLink | null = null;
/** The capture behind it, so switching monitors can stop the old one. */
let captured: MediaStreamTrack | null = null;
/** This machine's own sound, when the session was granted `REMOTE_AUDIO`. */
let capturedAudio: MediaStreamTrack | null = null;
let reconnectTimer: number | null = null;
let reconnectAttempt = 0;
let consentTimer: number | null = null;
/** The account signed in here; a session from them needs no prompt. */
let selfUserId: string | null = null;
let closedByUs = false;

export const useAgentStore = create<AgentState>((set, get) => ({
  enabled: localStorage.getItem(ENABLED_KEY) === '1',
  machineId: null,
  machineName: 'This machine',
  status: 'off',
  error: null,
  controlSupported: false,
  pending: null,
  controlRequest: null,
  session: null,

  enable: async () => {
    localStorage.setItem(ENABLED_KEY, '1');
    set({ enabled: true, error: null });
    await connect();
  },

  disable: async () => {
    localStorage.removeItem(ENABLED_KEY);
    set({ enabled: false, status: 'off', pending: null, session: null });
    await teardown('disabled');
    closedByUs = true;
    socket?.close();
    socket = null;
  },

  accept: () => {
    const pending = get().pending;
    if (!pending) return;
    clearConsentTimer();
    set({ pending: null });
    void startPublishing(pending);
  },

  refuse: (reason = 'declined') => {
    const pending = get().pending;
    if (!pending) return;
    clearConsentTimer();
    set({ pending: null });
    send({ type: 'session.refused', sessionId: pending.sessionId, reason });
  },

  answerControl: (granted) => {
    const request = get().controlRequest;
    if (!request) return;
    set({ controlRequest: null });
    send(
      granted
        ? { type: 'control.granted', sessionId: request.sessionId }
        : { type: 'control.denied', sessionId: request.sessionId, reason: 'declined' },
    );
    if (granted) {
      const session = get().session;
      if (session) {
        set({
          session: {
            ...session,
            permissions: [...session.permissions, 'REMOTE_CONTROL'],
          },
        });
      }
    }
  },

  endSession: () => {
    const session = get().session;
    if (!session) return;
    send({ type: 'session.ended', sessionId: session.sessionId });
    void teardown('agent');
  },

  restore: async (ownerId) => {
    selfUserId = ownerId;
    set({
      machineName: (await window.betweenus?.machineName()) ?? 'This machine',
      controlSupported: (await window.betweenus?.remoteInputSupported()) ?? false,
      machineId: await secureGet(MACHINE_KEY),
    });
    if (get().enabled) await connect();
  },
}));

/**
 * Enrols if this machine has never enrolled, then opens the outbound socket.
 *
 * Enrolment needs the signed-in account, because the person enrolling is the
 * person who will own the machine. The token that comes back is what the socket
 * uses afterwards, so a session survives the access token expiring.
 */
async function connect(): Promise<void> {
  useAgentStore.setState({ status: 'connecting', error: null });
  closedByUs = false;

  let token = await secureGet(TOKEN_KEY);
  let machineId = await secureGet(MACHINE_KEY);

  if (!token) {
    try {
      const name = (await window.betweenus?.machineName()) ?? 'This machine';
      const result = await api.enrolMachine(name, window.betweenus?.platform ?? 'unknown', machineId ?? undefined);
      token = result.agentToken;
      machineId = result.machine.id;
      await secureSet(TOKEN_KEY, token);
      await secureSet(MACHINE_KEY, machineId);
      useAgentStore.setState({ machineId, machineName: result.machine.name });
    } catch (error) {
      useAgentStore.setState({
        status: 'error',
        error: error instanceof Error ? error.message : 'Could not enrol this machine',
      });
      return;
    }
  }

  openSocket(token);
}

function openSocket(token: string): void {
  if (socket && socket.readyState <= WebSocket.OPEN) return;

  const next = new WebSocket(`${wsUrl()}/ws/remote?agent=${encodeURIComponent(token)}`);
  socket = next;

  next.onopen = () => {
    reconnectAttempt = 0;
    useAgentStore.setState({ status: 'online', error: null });
    send({ type: 'agent.ready', screens: 1 });
  };

  next.onmessage = (raw) => {
    let event: ServerRemoteEvent;
    try {
      event = JSON.parse(String(raw.data)) as ServerRemoteEvent;
    } catch {
      return;
    }
    void onEvent(event);
  };

  next.onclose = (event) => {
    socket = null;
    useAgentStore.setState({ status: closedByUs ? 'off' : 'connecting' });
    // 4401 is a token this gateway does not know: the machine was removed, or
    // it was re-enrolled somewhere else. Reconnecting would loop forever, so
    // the stored credential is dropped and the switch reports it.
    if (event.code === 4401) {
      void secureSet(TOKEN_KEY, '');
      useAgentStore.setState({
        status: 'error',
        error: 'This machine is no longer enrolled. Turn remote access off and on to enrol again.',
      });
      return;
    }
    if (closedByUs || !useAgentStore.getState().enabled) return;
    scheduleReconnect(token);
  };

  next.onerror = () => next.close();
}

function scheduleReconnect(token: string): void {
  if (reconnectTimer !== null) return;
  const delay = Math.min(1000 * 2 ** reconnectAttempt, 30_000);
  reconnectAttempt += 1;
  reconnectTimer = window.setTimeout(() => {
    reconnectTimer = null;
    openSocket(token);
  }, delay);
}

async function onEvent(event: ServerRemoteEvent): Promise<void> {
  switch (event.type) {
    case 'session.start': {
      const pending: PendingSession & { iceServers: IceServer[] } = {
        sessionId: event.sessionId,
        controllerName: event.controllerName,
        permissions: event.permissions,
        iceServers: event.iceServers,
      };
      media.set(event.sessionId, pending);

      // The owner reaching their own machine from another device is the case
      // remote access exists for; asking them to walk over and click yes would
      // defeat it. Anyone else has to be let in by whoever is sitting here.
      if (event.controllerId === selfUserId) {
        void startPublishing(pending);
        return;
      }

      useAgentStore.setState({ pending });
      clearConsentTimer();
      consentTimer = window.setTimeout(() => {
        useAgentStore.getState().refuse('nobody answered');
      }, CONSENT_TIMEOUT_MS);
      return;
    }

    case 'session.ended':
      clearConsentTimer();
      media.delete(event.sessionId);
      useAgentStore.setState({ pending: null, controlRequest: null });
      await teardown(event.reason);
      return;

    case 'screen.select':
      await switchScreen(event.sessionId, event.screenId);
      return;

    case 'control.requested':
      useAgentStore.setState({
        controlRequest: {
          sessionId: event.sessionId,
          controllerName: event.controllerName,
        },
      });
      return;

    // Control handed back, or taken away. The banner reads from this, so it
    // stops claiming somebody can type when they no longer can.
    case 'control.changed': {
      const session = useAgentStore.getState().session;
      if (session && session.sessionId === event.sessionId) {
        useAgentStore.setState({ session: { ...session, permissions: event.permissions } });
      }
      return;
    }

    // Input has already been checked against the session's permissions by the
    // gateway; this side only applies it.
    case 'input.mouse':
      window.betweenus?.remoteMouse({ ...event, source: 'session' });
      return;

    case 'input.key':
      window.betweenus?.remoteKey({ ...event, source: 'session' });
      return;

    case 'clipboard.set':
      // Remembered before writing, so the poller below does not read it back
      // out and send it straight to the other end again.
      lastClipboard = event.text;
      window.betweenus?.clipboardWrite(event.text);
      return;

    // A file on its way here. The gateway has already checked the permission
    // and written the attempt down; this decides whether the machine can take
    // it right now, and where it lands.
    case 'file.offer': {
      const session = useAgentStore.getState().session;
      if (session) await onFileOffer(session.sessionId, event);
      return;
    }

    case 'file.cancel':
      if (incoming && incoming.transferId === event.transferId) {
        await finishIncoming(false);
      }
      return;

    // The controller's answer, and its ICE candidates. Relayed by the gateway,
    // which reads none of it.
    case 'rtc.signal':
      await link?.accept(event.data);
      return;

    default:
      return;
  }
}

/** What the live session may do right now, for the paths that re-capture. */
function sessionPermissions(): RemotePermission[] {
  return useAgentStore.getState().session?.permissions ?? [];
}

/** Session id -> how to reach the controller that opened it. */
const media = new Map<string, PendingSession & { iceServers: IceServer[] }>();

/** The displays this machine offers, and the one currently on the wire. */
let displays: DisplayInfo[] = [];
let activeDisplayId: string | null = null;

/**
 * Publishes one of this machine's screens into the session's room.
 *
 * The picker is bypassed on purpose: a controller asked for this machine, not
 * for a window, and there is nobody to choose in an unattended session. Which
 * *monitor* is a different question, and one the controller is the right side
 * to answer - it is looking at the thing. The primary display starts, the list
 * travels with the session, and `screen.select` swaps it.
 *
 * Resolution follows the display rather than a fixed preset, which is what
 * makes text on the far end readable. A capture left to its default is 1080p,
 * so a 1440p or a scaled display arrived soft; asking for the display's real
 * pixel size and telling the encoder to keep resolution over frame rate is the
 * same bargain RustDesk makes - a remote desktop that is sharp at 10fps beats a
 * blurry one at 30. The bitrate is derived from the pixel count rather than
 * fixed, so a 4K machine is not sent through a 1080p-sized pipe, and congestion
 * control still lowers it when the link cannot carry it.
 */
async function startPublishing(pending: PendingSession): Promise<void> {
  const credentials = media.get(pending.sessionId);
  if (!credentials) return;

  try {
    displays = (await window.betweenus?.screenDisplays()) ?? [];
    const display = displays.find((entry) => entry.primary) ?? displays[0];
    if (!display) throw new Error('no display to share');

    // The agent offers, because the agent is the one with a screen to send.
    const next = new ScreenLink(true, {
      iceServers: credentials.iceServers,
      send: (data) => send({ type: 'rtc.signal', sessionId: pending.sessionId, data }),
      onData: onFileChunk,
      onFailed: (reason) => {
        send({ type: 'session.ended', sessionId: pending.sessionId });
        void teardown(reason);
      },
    });
    link = next;

    await publishDisplay(next, display, pending.permissions);

    useAgentStore.setState({
      session: {
        sessionId: pending.sessionId,
        controllerName: pending.controllerName,
        permissions: pending.permissions,
      },
    });
    send({ type: 'session.accepted', sessionId: pending.sessionId });
    sendScreens(pending.sessionId);
    watchDisplays(pending.sessionId);
    startClipboardSync(pending.sessionId);
  } catch (error) {
    send({
      type: 'session.refused',
      sessionId: pending.sessionId,
      reason: error instanceof Error ? error.message : 'capture failed',
    });
    await teardown('capture-failed');
  }
}

/**
 * Ends the running capture, if there is one.
 *
 * Two things hang off it. The capture keeps the OS "being shared" indicator up
 * until it is stopped, which on a machine nobody is sitting at is the one
 * visible sign left that anything is happening. And a running capture holds
 * the desktop in composed flip, without which a video on the target machine is
 * handed straight to its display and reaches the controller as a black
 * rectangle - so exactly one release has to follow every capture that started.
 */
function stopCapture(): void {
  // The sound is stopped whether or not there is a picture: they come from one
  // capture, and an audio track left running is a machine that is still being
  // listened to after the screen went dark.
  capturedAudio?.stop();
  capturedAudio = null;
  if (!captured) return;
  captured.stop();
  captured = null;
  void window.betweenus?.releaseScreenCapture();
}

/**
 * Puts one display on the wire, and points input injection at the same one.
 *
 * Those two have to move together or a controller watching the second monitor
 * clicks on the first, which is the multi-monitor version of the bug that made
 * clicks land short on a scaled display.
 */
async function publishDisplay(
  target: ScreenLink,
  display: DisplayInfo,
  permissions: RemotePermission[],
): Promise<void> {
  // `REMOTE_AUDIO` is asked for at the capture, because that is the only place
  // it can be: Electron's loopback is a property of the display capture and
  // there is no separate device to open. A machine without loopback - which is
  // everything that is not Windows today - simply hands back no audio track,
  // and the session is a silent one rather than a failed one.
  const wantAudio = permissions.includes('REMOTE_AUDIO');
  await window.betweenus?.selectScreenSource(display.sourceId, wantAudio);
  // The same encoder settings a screen share in a call uses - a remote desktop
  // is the 'detail' case of the same problem, and there is no reason for two
  // sets of numbers. `share-quality.ts` says why they are what they are.
  const options = shareOptions(
    'detail',
    { width: display.width, height: display.height },
    false,
    // And the same manual override, for the same reason: a LAN that has been
    // told it is a LAN is a LAN for a remote session too.
    useAudioSettings.getState().settings.share,
  );

  const stream = await navigator.mediaDevices.getDisplayMedia({
    video: {
      width: { ideal: options.capture.video.width, max: Math.max(3840, options.capture.video.width) },
      height: { ideal: options.capture.video.height, max: Math.max(2160, options.capture.video.height) },
      frameRate: { ideal: options.capture.video.frameRate, max: 60 },
    },
    audio: wantAudio,
  });

  const track = stream.getVideoTracks()[0];
  if (!track) throw new Error('the capture handed back no video');
  track.contentHint = options.capture.contentHint;

  const audio = stream.getAudioTracks()[0] ?? null;

  stopCapture();
  captured = track;
  capturedAudio = audio;
  await target.setDisplay(track, options.publish);
  await target.setAudio(audio);

  activeDisplayId = display.id;
  window.betweenus?.remoteTarget(display.id, 'session');
}

/**
 * Switches which monitor the session is watching.
 *
 * A fresh capture is taken: Chromium's capture is bound to the source it was
 * started with, so there is no way to redirect it in place. What does not
 * change is the connection - `replaceTrack` swaps the track under it, so the
 * controller's picture changes rather than going black while a new connection
 * is negotiated. The controller finds out it worked from the `screens` that
 * follows, never from having asked.
 */
async function switchScreen(sessionId: string, screenId: string): Promise<void> {
  const current = link;
  const display = displays.find((entry) => entry.id === screenId);
  if (!current || !display || display.id === activeDisplayId) return;

  try {
    await publishDisplay(current, display, sessionPermissions());
  } catch {
    // The old screen is gone and the new one did not start. Say what is true
    // rather than leaving the controller looking at a stale label.
    activeDisplayId = null;
  }
  sendScreens(sessionId);
}

/**
 * Keeps the screen list, and the screen being sent, true for the whole session.
 *
 * The list used to be read once when the session opened: a monitor plugged in
 * afterwards never appeared, and one unplugged left the controller with a
 * chooser full of screens that no longer existed - and, if it was the screen
 * being sent, a picture that had stopped.
 *
 * A display that goes while it is the one on the wire is the case that has to
 * do something rather than just re-announce: the session falls back to the
 * primary display, which is what somebody sitting at the machine would now be
 * looking at.
 */
function watchDisplays(sessionId: string): void {
  stopWatchingDisplays();
  unwatchDisplays =
    window.betweenus?.onDisplaysChanged(() => {
      void refreshDisplays(sessionId);
    }) ?? null;
}

function stopWatchingDisplays(): void {
  unwatchDisplays?.();
  unwatchDisplays = null;
}

async function refreshDisplays(sessionId: string): Promise<void> {
  const current = link;
  if (!current) return;

  displays = (await window.betweenus?.screenDisplays()) ?? [];
  if (displays.length === 0) return;

  const stillThere = displays.some((entry) => entry.id === activeDisplayId);
  if (!stillThere) {
    const fallback = displays.find((entry) => entry.primary) ?? displays[0];
    if (fallback) {
      try {
        await publishDisplay(current, fallback, sessionPermissions());
      } catch {
        // Nothing to send. The controller is told what is true rather than
        // being left with a label for a monitor that has gone.
        activeDisplayId = null;
      }
    }
  }

  sendScreens(sessionId);
}

function sendScreens(sessionId: string): void {
  if (displays.length === 0) return;
  send({
    type: 'screens',
    sessionId,
    activeId: activeDisplayId ?? '',
    screens: displays.map((display) => ({
      id: display.id,
      label: display.label,
      width: display.width,
      height: display.height,
      primary: display.primary,
    })),
  });
}

/**
 * Clipboard sync, machine side.
 *
 * Polled rather than evented, because no platform offers a reliable clipboard
 * change event and Electron does not expose one. A second is fast enough for
 * copy-then-paste and cheap enough to ignore.
 *
 * ponytail: text only. Files and images through a clipboard are a transfer
 * mechanism, and that is REMOTE_FILE_TRANSFER's job rather than this one's.
 */
let clipboardTimer: number | null = null;
let lastClipboard = '';

function startClipboardSync(sessionId: string): void {
  stopClipboardSync();
  const bridge = window.betweenus;
  if (!bridge) return;

  clipboardTimer = window.setInterval(() => {
    const session = useAgentStore.getState().session;
    if (!session || !session.permissions.includes('REMOTE_CLIPBOARD')) return;
    void bridge.clipboardRead().then((text) => {
      if (!text || text === lastClipboard) return;
      lastClipboard = text;
      send({ type: 'clipboard.text', sessionId, text });
    });
  }, 1000);
}

function stopClipboardSync(): void {
  if (clipboardTimer !== null) window.clearInterval(clipboardTimer);
  clipboardTimer = null;
  lastClipboard = '';
}

/**
 * Files arriving on this machine.
 *
 * The offer came over the gateway, which checked `REMOTE_FILE_TRANSFER` and
 * wrote it down; the bytes come off the data channel and are handed to the main
 * process a chunk at a time, so a four-gigabyte file never exists in this
 * renderer. Nothing here decides whether the transfer is allowed - it re-checks
 * the permission anyway, because the agent knows what the session was granted
 * and a second look costs one line.
 *
 * One at a time. A second offer while one is running is refused rather than
 * queued: the channel carries bare bytes and two files on it at once would be
 * indistinguishable. See `remote-transfer.ts`.
 */
interface Incoming {
  transferId: string;
  sessionId: string;
  sink: TransferSink;
  /** Writes are chained so chunks reach the disk in the order they arrived. */
  writes: Promise<unknown>;
}

let incoming: Incoming | null = null;

async function onFileOffer(
  sessionId: string,
  offer: { transferId: string; name: string; size: number },
): Promise<void> {
  const refuse = (reason: string): void => {
    send({ type: 'file.refused', sessionId, transferId: offer.transferId, reason });
  };

  if (!sessionPermissions().includes('REMOTE_FILE_TRANSFER')) {
    refuse('This session may not send files');
    return;
  }
  if (incoming) {
    refuse('Another file is already arriving');
    return;
  }

  const path = await window.betweenus?.remoteFileOpen(
    offer.transferId,
    safeFileName(offer.name),
  );
  if (!path) {
    refuse('This machine could not open the file');
    return;
  }

  incoming = {
    transferId: offer.transferId,
    sessionId,
    sink: new TransferSink(offer.size),
    writes: Promise.resolve(),
  };

  // A file of no bytes never gets a chunk, so it has to be finished here or it
  // would sit open until the session ended.
  if (incoming.sink.complete) {
    await finishIncoming(true);
    return;
  }
  send({ type: 'file.accepted', sessionId, transferId: offer.transferId });
}

function onFileChunk(data: ArrayBuffer): void {
  const current = incoming;
  if (!current) return;

  const verdict = current.sink.accept(data.byteLength);
  if (verdict === 'overflow') {
    // The far end is sending more than it declared. Nothing good comes of
    // writing it: the file is thrown away and the controller is told.
    send({
      type: 'file.refused',
      sessionId: current.sessionId,
      transferId: current.transferId,
      reason: 'More bytes arrived than the file said it had',
    });
    void finishIncoming(false);
    return;
  }

  const chunk = new Uint8Array(data);
  current.writes = current.writes.then(() =>
    window.betweenus?.remoteFileWrite(current.transferId, chunk),
  );

  if (verdict === 'done') void finishIncoming(true);
}

/** Closes the file, keeping it only when every byte arrived. */
async function finishIncoming(keep: boolean): Promise<void> {
  const current = incoming;
  if (!current) return;
  incoming = null;

  // The queued writes have to land before the stream is closed, or the last
  // chunk is written to a file that is already gone.
  await current.writes.catch(() => undefined);
  const path = await window.betweenus?.remoteFileClose(current.transferId, keep);
  if (keep && path) {
    send({
      type: 'file.done',
      sessionId: current.sessionId,
      transferId: current.transferId,
      path,
    });
  }
}

async function teardown(_reason: string): Promise<void> {
  clearConsentTimer();
  stopClipboardSync();
  // A transfer that was in flight leaves no part file behind: the session is
  // over and nothing is going to finish it.
  await finishIncoming(false);
  stopWatchingDisplays();
  link?.close();
  link = null;
  stopCapture();
  displays = [];
  activeDisplayId = null;
  useAgentStore.setState({ session: null });
  window.betweenus?.remoteInputStop();
}

function clearConsentTimer(): void {
  if (consentTimer !== null) window.clearTimeout(consentTimer);
  consentTimer = null;
}

function send(event: AgentRemoteEvent): void {
  if (socket?.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
}

/** Called on sign-out: the machine stops offering itself with nobody signed in. */
export async function stopAgent(): Promise<void> {
  closedByUs = true;
  selfUserId = null;
  await teardown('signed-out');
  socket?.close();
  socket = null;
  useAgentStore.setState({
    status: 'off',
    pending: null,
    controlRequest: null,
    session: null,
    machineId: null,
  });
}

/**
 * The peer connection a remote-desktop session's screen travels over.
 *
 * One connection, one direction: the agent sends a display, the controller
 * watches it. That is simpler than a call's mesh and is treated as such - there
 * is no perfect negotiation here, because the agent is always the one with
 * something to send and therefore always the one that offers.
 *
 * Three things travel on it, and they were three separate features until they
 * turned out to be one: the screen, the machine's own sound
 * (`REMOTE_AUDIO`), and files (`REMOTE_FILE_TRANSFER`). All three go
 * peer to peer for the same reason - a Cloudflare Tunnel carries neither UDP
 * nor a gigabyte, and a gateway that relayed either would be a hop in a path
 * that is not supposed to have one. The messages that *ask* for a file still go
 * through the gateway, because a permission nothing checks is not a permission.
 *
 * `remote-gateway` relays the offer, the answer and the ICE candidates over the
 * `/ws/remote` socket both ends already hold, so this needs no signalling of
 * its own. The picture then goes directly between the two machines and never
 * touches the gateway or the tunnel in front of it - which is the only shape
 * that works through a Cloudflare Tunnel without opening a port.
 *
 * What this does NOT have, and a call does: a fingerprint signed with a key the
 * server has never seen. The two machines in a remote session share no such
 * secret, so the gateway relays their fingerprints unverified. The screen is
 * still end-to-end encrypted - DTLS-SRTP between the two of them, with no
 * server holding a decodable frame, which is better than the SFU design managed
 * - but a *malicious* gateway could substitute a fingerprint and sit in the
 * middle. Closing that needs a key agreed between agent and controller without
 * the gateway learning it; see "Known limits" in development/E2EE.md.
 */
import type { IceServer, RemoteSignal } from '@betweenus/shared-types';
import { serialize } from './signal-queue';
import {
  PLAYOUT_DELAY,
  patchVideoBandwidth,
  sortPreferredVideoCodecs,
  type SharePublish,
} from './share-quality';

export interface ScreenLinkOptions {
  iceServers: IceServer[];
  /** Handed to the gateway, which relays it to the other end of this session. */
  send: (signal: RemoteSignal) => void;
  /** Controller side only: the agent's screen has arrived. */
  onTrack?: (track: MediaStreamTrack | null) => void;
  /** Controller side only: the machine's own sound, when the session may hear it. */
  onAudio?: (track: MediaStreamTrack | null) => void;
  /** A chunk of a file arriving on the data channel. Bytes and nothing else. */
  onData?: (data: ArrayBuffer) => void;
  /** Either side: the connection is not coming back. */
  onFailed?: (reason: string) => void;
}

/**
 * How much may sit in the data channel's send buffer before the sender waits.
 *
 * A `send` that is never checked buffers the whole file in the browser and then
 * dies, because a data channel accepts writes far faster than the network
 * drains them. Eight megabytes is enough to keep a fast link saturated and
 * small enough that a cancel is felt within a second on a slow one.
 */
const SEND_BUFFER_HIGH = 8 * 1024 * 1024;
const SEND_BUFFER_LOW = 1 * 1024 * 1024;

export class ScreenLink {
  private readonly pc: RTCPeerConnection;
  private sender: RTCRtpSender | null = null;
  private transceiver: RTCRtpTransceiver | null = null;
  /** The machine's own sound. One transceiver whether or not anything is on it. */
  private audioSender: RTCRtpSender | null = null;
  /** Files, and only files. See `remote-transfer.ts` for what travels on it. */
  private channel: RTCDataChannel | null = null;
  private closed = false;
  /** Signals from the far end, applied strictly one at a time. See `accept`. */
  private readonly queue = serialize();

  /**
   * `sending` is what makes this the agent's end. It decides who offers and
   * which direction the one video transceiver points, and both ends have to
   * agree - which they do, because only one of them has a screen.
   */
  constructor(
    private readonly sending: boolean,
    private readonly options: ScreenLinkOptions,
  ) {
    this.pc = new RTCPeerConnection({
      iceServers: options.iceServers,
      iceTransportPolicy: 'all',
      bundlePolicy: 'max-bundle',
    });

    // One transceiver, created up front on both sides so the m-lines match
    // without either end waiting for the other.
    this.transceiver = this.pc.addTransceiver('video', {
      direction: sending ? 'sendonly' : 'recvonly',
    });
    if (sending) this.sender = this.transceiver.sender;

    // An audio transceiver and a data channel exist for every session, whether
    // or not this one may use them. Both are cheap when empty and neither can
    // be added later without renegotiating, and a renegotiation part way
    // through a session is a black picture on the controller's screen for as
    // long as it takes. Permission decides what is *put* on them, which is
    // checked on the machine and again at the gateway - not whether they are
    // there.
    const audio = this.pc.addTransceiver('audio', {
      direction: sending ? 'sendonly' : 'recvonly',
    });
    if (sending) this.audioSender = audio.sender;

    // Negotiated, with an id both ends agree on up front, so neither has to
    // wait for `ondatachannel` and no second offer is needed to open it.
    this.channel = this.pc.createDataChannel('remote', {
      negotiated: true,
      id: 0,
      ordered: true,
    });
    this.channel.binaryType = 'arraybuffer';
    this.channel.bufferedAmountLowThreshold = SEND_BUFFER_LOW;
    this.channel.onmessage = (event) => {
      if (event.data instanceof ArrayBuffer) this.options.onData?.(event.data);
    };

    this.pc.ontrack = (event) => {
      if (event.track.kind === 'audio') {
        this.options.onAudio?.(event.track);
        event.track.onended = () => this.options.onAudio?.(null);
        return;
      }
      // A desktop somebody is driving gets the smallest jitter buffer that
      // Chromium will accept. The default third of a second is the difference
      // between a usable session and an unusable one.
      (event.receiver as RTCRtpReceiver & { playoutDelayHint?: number }).playoutDelayHint =
        PLAYOUT_DELAY.driving;
      this.options.onTrack?.(event.track);
      event.track.onended = () => this.options.onTrack?.(null);
    };

    this.pc.onicecandidate = ({ candidate }) => {
      if (!candidate) return;
      this.options.send({
        kind: 'ice',
        candidate: {
          candidate: candidate.candidate,
          sdpMid: candidate.sdpMid,
          sdpMLineIndex: candidate.sdpMLineIndex,
          usernameFragment: candidate.usernameFragment,
        },
      });
    };

    // Only the sending end offers, so there is no glare to resolve. This still
    // fires on the receiving end when the remote description arrives; ignoring
    // it there is deliberate.
    this.pc.onnegotiationneeded = () => {
      if (this.sending) void this.offer();
    };

    this.pc.oniceconnectionstatechange = () => {
      if (this.pc.iceConnectionState === 'failed') this.pc.restartIce();
    };

    this.pc.onconnectionstatechange = () => {
      if (this.pc.connectionState === 'failed' && !this.closed) {
        this.options.onFailed?.('The connection to the other machine failed');
      }
    };
  }

  private publish: SharePublish | null = null;

  /**
   * Puts a display on the wire, or swaps the one already there.
   *
   * `replaceTrack` rather than a new transceiver, so switching monitors does
   * not renegotiate and the controller's picture does not go black while it
   * does.
   */
  async setDisplay(track: MediaStreamTrack | null, publish?: SharePublish): Promise<void> {
    if (!this.sender) return;
    this.publish = publish ?? null;
    await this.sender.replaceTrack(track).catch(() => undefined);
    if (!track || !publish) return;

    // The same encoder settings a screen share in a call uses: a remote desktop
    // is the 'detail' case of the same problem. `share-quality.ts` says why.
    try {
      const parameters = this.sender.getParameters();
      if (!parameters.encodings || parameters.encodings.length === 0) {
        parameters.encodings = [{}];
      }
      const first = parameters.encodings[0];
      if (first) {
        first.maxBitrate = publish.maxBitrate;
        first.maxFramerate = publish.maxFramerate;
      }
      parameters.degradationPreference = publish.degradationPreference;
      await this.sender.setParameters(parameters);
    } catch {
      // A missing ceiling is a worse picture, not a dead session.
    }

    this.preferCodec(publish.videoCodec);
  }

  /**
   * Puts the machine's own sound on the wire, or takes it off.
   *
   * `replaceTrack` on a transceiver that has been there since the connection
   * was built, so turning audio on part way through a session costs nothing and
   * renegotiates nothing.
   */
  async setAudio(track: MediaStreamTrack | null): Promise<void> {
    if (!this.audioSender) return;
    await this.audioSender.replaceTrack(track).catch(() => undefined);
  }

  /** True once the data channel will accept a write. */
  get dataReady(): boolean {
    return this.channel?.readyState === 'open';
  }

  /**
   * Writes one chunk of a file, waiting when the buffer is full.
   *
   * The wait is the whole point: `send` never blocks and never fails on a slow
   * link, it just grows a buffer inside the browser until the tab dies. This
   * resolves when the chunk is queued and the queue is short enough to queue
   * another - so a caller that awaits it in a loop is paced by the network.
   */
  async sendBytes(chunk: Uint8Array<ArrayBuffer>): Promise<void> {
    const channel = this.channel;
    if (!channel || channel.readyState !== 'open') {
      throw new Error('The link to the machine is not open');
    }

    channel.send(chunk);
    if (channel.bufferedAmount < SEND_BUFFER_HIGH) return;

    await new Promise<void>((resolve, reject) => {
      const done = (): void => {
        channel.removeEventListener('bufferedamountlow', onLow);
        channel.removeEventListener('close', onClose);
      };
      const onLow = (): void => {
        done();
        resolve();
      };
      const onClose = (): void => {
        done();
        reject(new Error('The link to the machine closed'));
      };
      channel.addEventListener('bufferedamountlow', onLow);
      channel.addEventListener('close', onClose);
    });
  }

  /** Hardware H.264 where it exists, which is what makes 1080p60/4K affordable. */
  private preferCodec(codec: SharePublish['videoCodec']): void {
    if (!this.transceiver?.setCodecPreferences) return;
    try {
      const supported = RTCRtpSender.getCapabilities('video')?.codecs ?? [];
      const sorted = sortPreferredVideoCodecs(supported, codec);
      this.transceiver.setCodecPreferences(sorted);
    } catch {
      // An optimisation; the session works without it.
    }
  }

  private async offer(): Promise<void> {
    if (this.closed) return;
    try {
      const offer = await this.pc.createOffer();
      let sdp = offer.sdp;
      if (sdp && this.publish) {
        sdp = patchVideoBandwidth(sdp, this.publish);
      }
      await this.pc.setLocalDescription({ type: 'offer', sdp: sdp ?? offer.sdp });
      const localSdp = this.pc.localDescription?.sdp;
      if (localSdp) this.options.send({ kind: 'offer', sdp: localSdp });
    } catch (error) {
      console.warn('[remote-peer] could not offer the screen', error);
    }
  }

  /**
   * A signal relayed from the other end of this session, queued behind the ones
   * already being applied.
   *
   * Same reason as `mesh.ts`: `accept` is async, the socket does not wait for
   * it, and the body is a critical section over `this.pc`. Two descriptions
   * arriving together - which switching the shared screen produces, since it
   * renegotiates - interleaved at the awaits, and the second reached
   * `setLocalDescription` after the first had already driven the connection to
   * `stable`, which throws.
   */
  accept(signal: RemoteSignal): Promise<void> {
    return this.queue(() => this.apply(signal));
  }

  private async apply(signal: RemoteSignal): Promise<void> {
    if (this.closed) return;
    try {
      if (signal.kind === 'ice') {
        await this.pc.addIceCandidate(signal.candidate).catch(() => undefined);
        return;
      }

      await this.pc.setRemoteDescription({ type: signal.kind, sdp: signal.sdp });

      if (signal.kind === 'offer') {
        const answer = await this.pc.createAnswer();
        let sdp = answer.sdp;
        if (sdp && this.publish) {
          sdp = patchVideoBandwidth(sdp, this.publish);
        }
        await this.pc.setLocalDescription({ type: 'answer', sdp: sdp ?? answer.sdp });
        const localSdp = this.pc.localDescription?.sdp;
        if (localSdp) this.options.send({ kind: 'answer', sdp: localSdp });
      }
    } catch (error) {
      console.warn('[remote-peer] could not accept a signal', error);
    }
  }

  close(): void {
    this.closed = true;
    this.pc.ontrack = null;
    this.pc.onicecandidate = null;
    this.pc.onnegotiationneeded = null;
    this.pc.onconnectionstatechange = null;
    this.pc.oniceconnectionstatechange = null;
    if (this.channel) {
      this.channel.onmessage = null;
      this.channel.close();
      this.channel = null;
    }
    this.sender = null;
    this.audioSender = null;
    this.transceiver = null;
    this.pc.close();
  }
}

