/**
 * Safety numbers: the thing that makes the key directory checkable.
 *
 * Everything else in `E2EE.md` protects a message from whoever reads the
 * database. None of it protects against the *server handing out the wrong
 * public key*, because a client has no way to tell a stranger's key from a
 * substituted one - it asked the server, and the server answered. A safety
 * number is the answer: two people compare a short string over a channel the
 * server does not control, and if it matches, they know they hold each other's
 * real keys.
 *
 * This is the last of the three E2EE items and the one with the most UI in it,
 * because the cryptography is the easy half. Nobody is protected by a
 * fingerprint they never look at.
 *
 * ## Why a whole user rather than a device
 *
 * The directory is one key per machine, so a per-device number would mean
 * comparing n by m strings with somebody who owns a laptop and a phone, which
 * is a feature people would stop using rather than report. The number is over
 * the user's *whole* active device set instead: every machine they have, in a
 * canonical order.
 *
 * That has the property that matters. A server that adds a device to somebody's
 * directory - which is exactly how it would read their messages - changes their
 * safety number, and a number that was verified stops matching. So does
 * genuinely adding a phone, and that is correct rather than unfortunate: the
 * client cannot tell those apart, and neither can the person, which is the
 * whole reason they are asked to look.
 *
 * ## The algorithm
 *
 * Signal's numeric fingerprint, and deliberately not something invented here.
 * Iterated SHA-512 over the key material, truncated to 30 bytes, read as six
 * groups of five decimal digits. The iteration count is the point of it: a
 * 30-digit truncation is short enough to read aloud, so making each guess cost
 * 5200 hashes is what keeps somebody from grinding out a key that collides with
 * a number you already trust.
 *
 * The two halves are sorted before being joined, so both people see the same
 * string without either being "first".
 */

const subtle = globalThis.crypto.subtle;
const encoder = new TextEncoder();

/**
 * Signal's count, kept rather than tuned. It is the only thing standing between
 * a 30-digit fingerprint and somebody who wants to find a second key that
 * produces it, so it is not the number to shave for a faster dialog.
 */
const FINGERPRINT_ITERATIONS = 5200;

/** Two bytes of version, so a later scheme cannot be confused with this one. */
const FINGERPRINT_VERSION = new Uint8Array([0x00, 0x00]);

/** Six groups of five digits: 30 digits per person, 60 in a displayed pair. */
const GROUP_BYTES = 5;
const GROUPS = 6;

/** A device as far as this file cares: an id to sort by and a key to hash. */
export interface FingerprintDevice {
  deviceId: string;
  /** The ECDH P-256 public half, as the JWK the directory stores. */
  publicKey: string;
}

/**
 * The bytes that stand for one person's identity.
 *
 * Every active device's public key, in device-id order, as raw uncompressed
 * curve points rather than as JWK text. The raw form is what makes this
 * canonical: two clients that serialise the same key with their JSON fields in
 * a different order would otherwise compute different numbers for the same
 * person, and the failure would look exactly like an attack.
 *
 * Sorting is by device id and not by key, because the id is what the person
 * sees in their own device list - an ordering somebody can check by hand is
 * worth more than one that is marginally cheaper.
 */
export async function identityMaterial(devices: FingerprintDevice[]): Promise<Uint8Array<ArrayBuffer>> {
  const sorted = [...devices].sort((a, b) => (a.deviceId < b.deviceId ? -1 : a.deviceId > b.deviceId ? 1 : 0));

  const points = await Promise.all(
    sorted.map(async (device) => {
      const key = await subtle.importKey(
        'jwk',
        JSON.parse(device.publicKey) as JsonWebKey,
        { name: 'ECDH', namedCurve: 'P-256' },
        true,
        [],
      );
      return new Uint8Array(await subtle.exportKey('raw', key));
    }),
  );

  const total = points.reduce((sum, point) => sum + point.byteLength, 0);
  const material = new Uint8Array(new ArrayBuffer(total));
  let offset = 0;
  for (const point of points) {
    material.set(point, offset);
    offset += point.byteLength;
  }
  return material;
}

/**
 * One person's half of a safety number: thirty digits.
 *
 * The user id is hashed in alongside the keys so that moving a key to another
 * account does not carry its fingerprint with it. It is a stable identifier
 * rather than a display name for the same reason a username is not used: a
 * name can be changed by whoever runs the deployment.
 */
export async function userFingerprint(
  userId: string,
  material: Uint8Array<ArrayBuffer>,
): Promise<string> {
  if (material.byteLength === 0) return '';

  const identifier = encoder.encode(userId);
  let hash = new Uint8Array(
    await subtle.digest('SHA-512', concat(FINGERPRINT_VERSION, material, identifier)),
  );

  // Sequential on purpose - each round takes the last one's output, which is
  // what makes the work impossible to skip.
  for (let round = 1; round < FINGERPRINT_ITERATIONS; round += 1) {
    hash = new Uint8Array(await subtle.digest('SHA-512', concat(hash, material)));
  }

  let digits = '';
  for (let group = 0; group < GROUPS; group += 1) {
    digits += chunkToDigits(hash.subarray(group * GROUP_BYTES, (group + 1) * GROUP_BYTES));
  }
  return digits;
}

/**
 * The number the two people compare.
 *
 * Sorted, so both ends print the same sixty digits and neither has to be told
 * which of them goes first. An empty half - somebody with no devices at all -
 * gives an empty number rather than half of one, because half a safety number
 * is something that can be read aloud and matched, and it would mean nothing.
 */
export function safetyNumber(mine: string, theirs: string): string {
  if (!mine || !theirs) return '';
  return mine < theirs ? mine + theirs : theirs + mine;
}

/** Sixty digits in twelve groups of five, which is how they are read aloud. */
export function formatSafetyNumber(digits: string): string {
  const groups = digits.match(/.{1,5}/g) ?? [];
  const lines: string[] = [];
  for (let index = 0; index < groups.length; index += 4) {
    lines.push(groups.slice(index, index + 4).join(' '));
  }
  return lines.join('\n');
}

function chunkToDigits(chunk: Uint8Array): string {
  // Five bytes is forty bits, which exceeds what a 32-bit shift can hold, so
  // this accumulates in a float - exact up to 2^53 and therefore exact here.
  let value = 0;
  for (const byte of chunk) value = value * 256 + byte;
  return String(value % 100_000).padStart(5, '0');
}

function concat(...parts: Uint8Array[]): Uint8Array<ArrayBuffer> {
  const total = parts.reduce((sum, part) => sum + part.byteLength, 0);
  const out = new Uint8Array(new ArrayBuffer(total));
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.byteLength;
  }
  return out;
}

/**
 * Who this machine has checked a safety number with, and what it was.
 *
 * Local, and deliberately so. Verification is the one piece of state in the
 * whole E2EE design that the server must not be able to set: a server that
 * could mark somebody verified could substitute their key and then reassure
 * the person about it, which is the exact attack safety numbers exist to
 * catch. So this never leaves the machine, never syncs, and a second device
 * verifies for itself.
 *
 * What is stored is the *number*, not a boolean. That is what turns this from a
 * checkbox into a warning: on the next look the current fingerprint is compared
 * with the one that was checked, and a person whose key set has changed since
 * reads as changed rather than as verified. Adding a phone does that as well as
 * an attack does, and the client cannot tell them apart - which is why the
 * wording says what happened rather than what it means.
 */
const STORAGE_KEY = 'betweenus.safety.verified';

export type VerificationState = 'unverified' | 'verified' | 'changed';

/** userId -> the thirty digits that were checked. */
type Verified = Record<string, string>;

function read(): Verified {
  try {
    const raw = globalThis.localStorage?.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    // Values that are not strings are dropped rather than trusted: this file is
    // editable by anybody with the machine, and a non-string here would flow
    // into a comparison that then never matches anything.
    return Object.fromEntries(
      Object.entries(parsed as Record<string, unknown>).filter(
        (entry): entry is [string, string] => typeof entry[1] === 'string',
      ),
    );
  } catch {
    return {};
  }
}

function write(value: Verified): void {
  try {
    globalThis.localStorage?.setItem(STORAGE_KEY, JSON.stringify(value));
  } catch {
    // A machine that cannot store this is a machine that verifies afresh each
    // time, which is worse but not broken.
  }
}

/**
 * Where this person stands, given the fingerprint they have right now.
 *
 * An empty current fingerprint - somebody with no published device at all -
 * reads as unverified rather than as changed. There is nothing to compare, and
 * telling somebody their contact's key changed because the directory was empty
 * would be a false alarm that teaches them to ignore the real one.
 */
export function verificationOf(userId: string, fingerprint: string): VerificationState {
  const stored = read()[userId];
  if (!stored) return 'unverified';
  if (!fingerprint) return 'unverified';
  return stored === fingerprint ? 'verified' : 'changed';
}

/** Records that this machine's owner looked at that number and said yes. */
export function markVerified(userId: string, fingerprint: string): void {
  if (!fingerprint) return;
  write({ ...read(), [userId]: fingerprint });
}

/** Takes it back, which is what somebody does when the number stopped matching. */
export function clearVerified(userId: string): void {
  const next = read();
  delete next[userId];
  write(next);
}

/** Run with `tsx src/services/server-clock.check.ts`. The clock the client trusts. */
import assert from 'node:assert/strict';
import {
  CLOCK_SAMPLES,
  CLOCK_WARNING_MS,
  clockIsWrong,
  deviceSkewMs,
  sampleServerClock,
  serverNow,
  skewWording,
  useServerClock,
} from './server-clock';

const reset = (): void => useServerClock.getState().reset();

// --- an unmeasured clock -----------------------------------------------------

reset();
// Zero offset is what an unmeasured clock is worth, and is also the right
// answer for the overwhelming majority of machines, which keep time.
assert.equal(useServerClock.getState().offsetMs, 0);
assert.ok(Math.abs(serverNow() - Date.now()) < 50);
assert.equal(clockIsWrong(0), false);

// A reply with no usable `Date` header teaches nothing rather than something
// wrong: a proxy that strips it, or writes nonsense into it, must not be able
// to move this client's idea of the time.
sampleServerClock(Date.now(), Date.now(), null);
sampleServerClock(Date.now(), Date.now(), 'not a date');
assert.equal(useServerClock.getState().offsetMs, 0);

// --- a device an hour behind -------------------------------------------------

reset();
const hour = 60 * 60 * 1000;
const sent = 1_000_000;
// The reply came back 200ms later, and the server stamped it an hour ahead of
// this machine: the estimate is the midpoint of the round trip, so the offset
// is the hour plus the 100ms the reply spent in flight.
sampleServerClock(sent, sent + 200, new Date(sent + hour + 100).toUTCString());
const offset = useServerClock.getState().offsetMs;
assert.ok(Math.abs(offset - hour) < 1000, `expected about an hour, got ${offset}`);
// Positive skew means this machine is *behind*; the wording has to agree.
assert.equal(deviceSkewMs() < 0, true);
assert.equal(clockIsWrong(offset), true);
assert.match(skewWording(offset), /behind/);
assert.match(skewWording(-offset), /ahead of/);

// --- which sample wins -------------------------------------------------------

reset();
// A slow round trip is slow because something queued, and a queue is rarely
// symmetric - so a delayed sample is biased, not merely noisy, and the
// least-delayed one is the one to believe.
sampleServerClock(0, 8_000, new Date(2_000).toUTCString());
sampleServerClock(0, 100, new Date(1_000_050).toUTCString());
assert.ok(
  Math.abs(useServerClock.getState().offsetMs - 1_000_000) < 200,
  'the fastest round trip decides',
);

// Only the last few measurements are kept, so a clock corrected an hour ago
// stops being held against the machine.
reset();
for (let i = 0; i < CLOCK_SAMPLES + 4; i += 1) sampleServerClock(0, 100, new Date(50).toUTCString());
assert.equal(useServerClock.getState().samples.length, CLOCK_SAMPLES);

// --- the threshold -----------------------------------------------------------

// Under five minutes nothing on screen is misleading, and a laptop with a lazy
// NTP daemon must not be nagged about it.
assert.equal(clockIsWrong(CLOCK_WARNING_MS - 1), false);
assert.equal(clockIsWrong(-(CLOCK_WARNING_MS - 1)), false);
assert.equal(clockIsWrong(CLOCK_WARNING_MS), true);
assert.equal(clockIsWrong(-CLOCK_WARNING_MS), true);

// The wording scales, because "about 4320 minutes" is not a sentence.
assert.match(skewWording(10 * 60 * 1000), /10 minutes/);
assert.match(skewWording(5 * hour), /5 hours/);
assert.match(skewWording(3 * 24 * hour), /3 days/);

reset();
console.log('server-clock.check.ts ok');

/**
 * What time the *server* thinks it is, and what to do when this machine
 * disagrees.
 *
 * A device clock belongs to whoever holds the device. It drifts on its own, it
 * is wrong outright on a machine that woke from sleep or lost its battery, and
 * it can be set to any value at all by the person using it - which is the part
 * that matters. Anything that expires (a one-time message, an invite, a grant,
 * a session) must therefore be decided by a clock that person does not own:
 *
 * - **Enforcement is the server's, always.** Nothing a client believes about
 *   the time is allowed to grant access to anything. The services already work
 *   this way - `resolveRemoteAccess` compares a grant's `expiresAt` to the
 *   database's own clock, refresh tokens and password resets to the auth
 *   service's - and any expiry added later belongs there too, not here. Winding
 *   a phone forward or back must not change what the server hands over.
 * - **What a client shows is the server's clock too.** That is what this is
 *   for: a countdown, an "Expired" label, a "Today" divider on yesterday's
 *   messages. A wrong device clock cannot open anything, but it can quietly
 *   lie to the person reading, and a chat that says a message arrived tomorrow
 *   reads as broken software rather than as a wrong clock.
 *
 * The offset is learned for free. Every HTTP response carries a `Date` header,
 * so `services/api.ts` hands one sample per request to `sampleServerClock` and
 * the estimate is NTP's: the server stamped that header somewhere between the
 * request leaving and the response arriving, so the midpoint of the round trip
 * is the best guess available, and the least-delayed sample is the one to
 * believe. `listen-sync.ts` already worked this out for keeping two players in
 * step, and `offsetOf`/`bestOffset` are that arithmetic - the same rule against
 * a different measurement, so it is imported rather than written twice.
 *
 * Android's `ServerClock.kt` is this file, case for case.
 */
import { create } from 'zustand';
import { bestOffset, type ClockSample } from './listen-sync';

/**
 * How wrong a device clock has to be before the person is told.
 *
 * Five minutes. Below it nothing on screen is misleading - a bubble a few
 * seconds out is still under the right day, and a countdown is still honest to
 * the minute - and a message about it would be noise on every laptop with a
 * lazy NTP daemon. Above it, the day dividers start naming the wrong day and
 * anything with a deadline reads wrongly, which is worth one line at the top of
 * the window.
 */
export const CLOCK_WARNING_MS = 5 * 60 * 1000;

/** How many measurements are kept when picking the least-delayed one. */
export const CLOCK_SAMPLES = 8;

interface ServerClockState {
  /** Server time minus device time, in milliseconds. Zero until measured. */
  offsetMs: number;
  samples: ClockSample[];
  sample: (sample: ClockSample) => void;
  reset: () => void;
}

export const useServerClock = create<ServerClockState>((set, get) => ({
  offsetMs: 0,
  samples: [],
  sample: (sample) => {
    const samples = [...get().samples, sample].slice(-CLOCK_SAMPLES);
    set({ samples, offsetMs: bestOffset(samples) });
  },
  reset: () => set({ samples: [], offsetMs: 0 }),
}));

/**
 * One measurement, from a response that has already arrived.
 *
 * `Date` is written to the second, so an offset read from it is quantised to
 * about half a second. That is uselessly coarse for lining up two music players
 * and entirely sufficient here, where the question is whether a clock is out by
 * minutes.
 */
export function sampleServerClock(sentAtMs: number, receivedAtMs: number, header: string | null): void {
  if (!header) return;
  const serverMs = Date.parse(header);
  if (Number.isNaN(serverMs)) return;
  useServerClock.getState().sample({ sentAtMs, receivedAtMs, serverMs });
}

/** The server's clock, as best this machine can tell. Never used to *decide*. */
export function serverNow(): number {
  return Date.now() + useServerClock.getState().offsetMs;
}

/** How far this machine's clock is from the server's; positive means ahead. */
export function deviceSkewMs(): number {
  return -useServerClock.getState().offsetMs;
}

/** Whether the device clock is wrong enough to say so. */
export function clockIsWrong(offsetMs: number): boolean {
  return Math.abs(offsetMs) >= CLOCK_WARNING_MS;
}

/** The wording for a clock that is out: which way, and roughly how far. */
export function skewWording(offsetMs: number): string {
  const minutes = Math.round(Math.abs(offsetMs) / 60_000);
  const amount =
    minutes >= 2880
      ? `${Math.round(minutes / 1440)} days`
      : minutes >= 120
        ? `${Math.round(minutes / 60)} hours`
        : `${minutes} minutes`;
  const direction = offsetMs < 0 ? 'ahead of' : 'behind';
  return `This device's clock is about ${amount} ${direction} the server's. Times and dates on messages will look wrong until it is corrected.`;
}

