/**
 * The keyboard shortcuts this client actually has.
 *
 * One list, in one place, for two readers: the sheet that shows them to a
 * person, and whoever adds the next one. A shortcut whose only record is the
 * `keydown` handler that implements it is a shortcut nobody finds - which is
 * how a desktop app ends up with bindings its own users have never pressed.
 *
 * The list is deliberately honest about how short it is. `Ctrl+K` was for a
 * long time the only global binding in the app, on the reasoning that
 * everything else is reachable from it; that is a defensible position for
 * navigation and not one for the rest, and this file is where the argument gets
 * had from now on rather than in a component.
 */

export interface Shortcut {
  /** The keys, already written the way they are read: `Ctrl K`, `Shift ?`. */
  keys: string[];
  what: string;
  /** Where it works. Shown so a binding that is not global does not look broken. */
  where: 'Anywhere' | 'In a conversation' | 'In a call';
}

/**
 * `Ctrl` on Windows and Linux, `⌘` on a Mac.
 *
 * Both are accepted by every handler - the check is `ctrlKey || metaKey` - so
 * this only decides which one to *print*. Getting it backwards is the kind of
 * detail that makes a shortcut sheet feel written by somebody who does not use
 * the platform.
 */
export function commandKey(platform: string = navigator?.platform ?? ''): string {
  return /mac|iphone|ipad/i.test(platform) ? '⌘' : 'Ctrl';
}

export function shortcuts(command: string = commandKey()): Shortcut[] {
  return [
    {
      keys: [command, 'K'],
      what: 'Go to a server, channel or conversation',
      where: 'Anywhere',
    },
    {
      keys: ['?'],
      what: 'Show this list',
      where: 'Anywhere',
    },
    {
      keys: [command, 'F'],
      what: 'Search this conversation',
      where: 'In a conversation',
    },
    {
      keys: ['Enter'],
      what: 'Send',
      where: 'In a conversation',
    },
    {
      keys: ['Shift', 'Enter'],
      what: 'A new line, without sending',
      where: 'In a conversation',
    },
    {
      keys: ['F'],
      what: 'Full screen, and back',
      where: 'In a call',
    },
    {
      keys: ['Esc'],
      what: 'Close whatever is open',
      where: 'Anywhere',
    },
  ];
}

/**
 * Whether a keystroke is somebody typing rather than reaching for a shortcut.
 *
 * The rule every unmodified binding needs and the one that is easy to get
 * wrong: `F` toggles full screen in a call, and without this it also does so
 * in the middle of a word. `contentEditable` counts, because a rich composer is
 * not an `<input>`.
 *
 * A binding with a modifier does not ask - `Ctrl+K` while typing is a person
 * who wants the switcher - which is why this takes the event rather than only
 * the target.
 */
export function isTyping(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null;
  if (!element) return false;
  if (element.isContentEditable) return true;
  return ['INPUT', 'TEXTAREA', 'SELECT'].includes(element.tagName);
}

/**
 * Whether this event should open the shortcut sheet.
 *
 * `?` is `Shift+/` on most layouts and its own key on others, so the character
 * is what is read rather than a key code. Never while typing: a question mark
 * in a message is a question mark.
 */
export function opensShortcutSheet(event: KeyboardEvent): boolean {
  if (event.ctrlKey || event.metaKey || event.altKey) return false;
  if (isTyping(event.target)) return false;
  return event.key === '?';
}

/**
 * The ordering guarantee `mesh.ts` and `remote-peer.ts` negotiate under.
 *
 * The bug this pins down: two WebRTC descriptions arrive a moment apart, the
 * socket does not wait for the first to be applied, and the two runs interleave
 * at their awaits. The second reaches `setLocalDescription('answer')` after the
 * first has already driven the connection to `stable`, and the call shows
 * "Failed to set local answer sdp: Called in wrong state: stable".
 *
 * Run with: pnpm --filter @betweenus/desktop check
 */
import assert from 'node:assert/strict';
import { serialize } from './signal-queue';

const tick = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 0));

async function main(): Promise<void> {
  // Two tasks that suspend in the middle, started without awaiting the first -
  // exactly how the socket dispatches a signal.
  const queue = serialize();
  const events: string[] = [];

  const step = (name: string) => async (): Promise<void> => {
    events.push(`${name}:start`);
    await tick();
    await tick();
    events.push(`${name}:end`);
  };

  const first = queue(step('a'));
  const second = queue(step('b'));
  await Promise.all([first, second]);

  assert.deepEqual(
    events,
    ['a:start', 'a:end', 'b:start', 'b:end'],
    'a signal must be applied to completion before the next one starts',
  );

  // A signal that throws must not take the rest of the call with it. Without
  // this, one refused description ends negotiation for good: nothing after it
  // ever runs, and the peer sits on "Connecting…" until somebody rejoins.
  const afterFailure = serialize();
  const seen: string[] = [];
  const failed = afterFailure(async () => {
    await tick();
    throw new Error('a description that could not be applied');
  });
  const next = afterFailure(async () => {
    seen.push('ran');
  });

  await assert.doesNotReject(failed, 'the queue absorbs the rejection rather than surfacing it');
  await next;
  assert.deepEqual(seen, ['ran'], 'a failed signal must not poison the queue behind it');

  // A task queued after the chain has drained still runs, rather than being
  // chained onto a promise that settled long ago and quietly never starting.
  const later: string[] = [];
  await afterFailure(async () => {
    later.push('late');
  });
  assert.deepEqual(later, ['late'], 'the queue keeps working once it has gone idle');

  console.log('signal-queue.check.ts: ok');
}

void main();

import type {
  ClientChatEvent,
  ClientPresenceEvent,
  ServerChatEvent,
  ServerPresenceEvent,
} from '@betweenus/shared-types';

import { wsUrl } from './endpoint';

/**
 * Mints a fresh access token, set by the auth store on startup.
 *
 * A socket carries the access token in its URL, so the token it opened with
 * expires while it is open - fifteen minutes in, or over any sleep longer than
 * that. The next reconnect is then refused with 4401, and a socket that gave up
 * there stayed down until the app was restarted: no messages, no presence, an
 * app that looks signed out while the session behind it is fine. Refreshing is
 * what fixes it, and nothing else was going to ask.
 */
let renewToken: (() => Promise<unknown>) | null = null;

export function onSocketTokenRejected(renew: () => Promise<unknown>): void {
  renewToken = renew;
}

// Same host as the REST base, ws scheme: both sockets are behind the gateway
// this window is pointed at, so there is no second address to configure.


/**
 * Whether this window can reach the backend, for the reconnecting banner.
 *
 * Both sockets report into it and the worst answer wins: presence being down
 * with chat up is still a window that is missing events, and saying so is the
 * whole point. `offline` is a deliberate stop rather than a slower retry - see
 * `RECONNECT_DEADLINE_MS`.
 */
export type ConnectionState = 'online' | 'reconnecting' | 'offline';

/**
 * How long a socket is allowed to keep retrying before it is given up on.
 *
 * A backoff that never stops is a spinner that never stops, and thirty seconds
 * of "Reconnecting…" is already longer than anybody waits before deciding the
 * app is broken. Past it the window says so and offers the retry as a button:
 * a person who has just walked back into wifi presses it and is back in a
 * second, which an exponential backoff sitting on its thirty-second step is
 * not.
 */
export const RECONNECT_DEADLINE_MS = 30_000;

const socketStates = new Map<string, ConnectionState>();
const connectionListeners = new Set<(state: ConnectionState) => void>();
let lastPublished: ConnectionState = 'online';

function reportSocket(name: string, state: ConnectionState): void {
  socketStates.set(name, state);
  const states = [...socketStates.values()];
  const next: ConnectionState = states.includes('offline')
    ? 'offline'
    : states.includes('reconnecting')
      ? 'reconnecting'
      : 'online';
  if (next === lastPublished) return;
  lastPublished = next;
  for (const listener of connectionListeners) listener(next);
}

export function connectionState(): ConnectionState {
  return lastPublished;
}

export function onConnectionChange(listener: (state: ConnectionState) => void): () => void {
  connectionListeners.add(listener);
  return () => connectionListeners.delete(listener);
}

/** The button on the banner: start the ladder again, from the bottom. */
export function retryConnection(): void {
  chatSocket.retry();
  presenceSocket.retry();
}

type Listener = (event: ServerChatEvent) => void;

/**
 * Chat socket with reconnect and channel re-subscription.
 *
 * The token rides in the query string because a browser WebSocket cannot set
 * an Authorization header; the gateway treats it as a bearer token.
 */
export class ChatSocket {
  private socket: WebSocket | null = null;
  private token: string | null = null;
  private readonly listeners = new Set<Listener>();
  private readonly channels = new Set<string>();
  /** Servers this client watches for membership changes. */
  private readonly servers = new Set<string>();
  private reconnectAttempt = 0;
  private reconnectTimer: number | null = null;
  private closedByUs = false;
  /** When this socket was last up, which is what the deadline measures from. */
  private downSince: number | null = null;

  connect(token: string): void {
    this.token = token;
    this.closedByUs = false;
    this.downSince ??= Date.now();
    this.open();
  }

  /** Asked for by the banner. A retry starts the backoff ladder again. */
  retry(): void {
    if (!this.token || this.closedByUs) return;
    this.reconnectAttempt = 0;
    this.downSince = Date.now();
    reportSocket('chat', 'reconnecting');
    if (this.reconnectTimer !== null) {
      window.clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.open();
  }

  private open(): void {
    if (!this.token) return;
    if (this.socket && this.socket.readyState <= WebSocket.OPEN) return;

    const socket = new WebSocket(`${wsUrl()}/ws/chat?token=${encodeURIComponent(this.token)}`);
    this.socket = socket;

    socket.onopen = () => {
      this.reconnectAttempt = 0;
      this.downSince = null;
      reportSocket('chat', 'online');
      // Re-subscribe: the server keeps no membership across connections.
      for (const channelId of this.channels) {
        this.send({ type: 'channel.subscribe', channelId });
      }
      for (const serverId of this.servers) {
        this.send({ type: 'server.subscribe', serverId });
      }
    };

    socket.onmessage = (raw) => {
      let event: ServerChatEvent;
      try {
        event = JSON.parse(String(raw.data)) as ServerChatEvent;
      } catch {
        return;
      }
      for (const listener of this.listeners) listener(event);
    };

    socket.onclose = (event) => {
      this.socket = null;
      if (this.closedByUs) return;
      // 4401 is the token being rejected, not the connection failing. Ask for a
      // fresh one - a successful refresh reconnects both sockets itself - and
      // fall through to the backoff so a refresh that cannot happen right now
      // is retried rather than being the end of it.
      if (event.code === 4401) void renewToken?.();
      this.scheduleReconnect();
    };

    socket.onerror = () => socket.close();
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer !== null) return;
    this.downSince ??= Date.now();

    // Given up on rather than retried more slowly: past the deadline the window
    // says it is disconnected and waits to be told to try again.
    if (Date.now() - this.downSince >= RECONNECT_DEADLINE_MS) {
      reportSocket('chat', 'offline');
      return;
    }
    reportSocket('chat', 'reconnecting');

    const delay = Math.min(1000 * 2 ** this.reconnectAttempt, 30_000);
    this.reconnectAttempt += 1;
    this.reconnectTimer = window.setTimeout(() => {
      this.reconnectTimer = null;
      this.open();
    }, delay);
  }

  subscribe(channelId: string): void {
    this.channels.add(channelId);
    this.send({ type: 'channel.subscribe', channelId });
  }

  /**
   * Subscribes to exactly `channelIds`, dropping anything else.
   *
   * The client stays subscribed to every text channel it can read, not only the
   * one on screen - otherwise a message in another channel never arrives and
   * there is nothing to notify about.
   */
  syncSubscriptions(channelIds: string[]): void {
    const wanted = new Set(channelIds);
    for (const channelId of this.channels) {
      if (!wanted.has(channelId)) this.unsubscribe(channelId);
    }
    for (const channelId of wanted) {
      if (!this.channels.has(channelId)) this.subscribe(channelId);
    }
  }

  unsubscribe(channelId: string): void {
    this.channels.delete(channelId);
    this.send({ type: 'channel.unsubscribe', channelId });
  }

  /**
   * Watches exactly these servers. Separate from channel subscriptions because
   * a member joining or leaving is not news about any one channel, and a client
   * has to hear it for every server it is in, not only the one on screen.
   */
  syncServers(serverIds: string[]): void {
    const wanted = new Set(serverIds);
    for (const serverId of this.servers) {
      if (!wanted.has(serverId)) {
        this.servers.delete(serverId);
        this.send({ type: 'server.unsubscribe', serverId });
      }
    }
    for (const serverId of wanted) {
      if (this.servers.has(serverId)) continue;
      this.servers.add(serverId);
      this.send({ type: 'server.subscribe', serverId });
    }
  }

  on(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private send(event: ClientChatEvent): void {
    if (this.socket?.readyState === WebSocket.OPEN) this.socket.send(JSON.stringify(event));
  }

  disconnect(): void {
    this.closedByUs = true;
    this.downSince = null;
    reportSocket('chat', 'online');
    this.channels.clear();
    this.servers.clear();
    if (this.reconnectTimer !== null) {
      window.clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.socket?.close();
    this.socket = null;
  }
}

export const chatSocket = new ChatSocket();

