export const presenceSocket = new PresenceSocket();

/**
 * The bytes behind a status, opened, as something an `<img>` or a `<video>`
 * can take.
 *
 * The object comes down as ciphertext - the server has never held anything
 * else - so this is the attachment path with a different key: fetch, decrypt,
 * and hand back an object URL. The type on the blob comes from the post rather
 * than from the response, because the response says `application/octet-stream`
 * and a `<video>` will not decode a blob with no type on it.
 *
 * Cached by status id, because a story is opened, closed and opened again, and
 * the second look should not be another download and another decryption.
 * Released when the post goes or the window closes; a URL that is revoked
 * while an element still points at it draws nothing, so nothing revokes on
 * unmount.
 */
import type { StatusEntry } from '@betweenus/shared-types';

const urls = new Map<string, Promise<string>>();

/** The object URL for one post's media, fetching and opening it the first time. */
export function statusMedia(post: StatusEntry): Promise<string> {
  const known = urls.get(post.id);
  if (known) return known;

  const pending = fetchBlobUrl(post).catch((error: unknown) => {
    // A failure must not be cached: the next look should try again rather than
    // replay the same error for as long as the window is open.
    urls.delete(post.id);
    throw error;
  });
  urls.set(post.id, pending);
  return pending;
}

/** Frees one post's bytes - it was deleted, or it expired. */
export function releaseStatusMedia(statusId: string): void {
  const pending = urls.get(statusId);
  urls.delete(statusId);
  void pending?.then((url) => URL.revokeObjectURL(url)).catch(() => undefined);
}

/** Frees everything. Called when the session ends. */
export function releaseAllStatusMedia(): void {
  for (const statusId of [...urls.keys()]) releaseStatusMedia(statusId);
}

async function fetchBlobUrl(post: StatusEntry): Promise<string> {
  if (!post.mediaUrl) throw new Error('That post has no media');
  // Imported lazily so this module can be read by a check without pulling the
  // whole API surface - and so the import graph stays one way: the store
  // imports this, this does not import the store.
  const [{ api }, { openStatusMedia }] = await Promise.all([
    import('./api'),
    import('./e2ee'),
  ]);
  const sealed = await api.fetchObject(post.mediaUrl);
  const opened = await openStatusMedia(post, sealed);
  return URL.createObjectURL(new Blob([opened], { type: post.mediaType ?? '' }));
}

/**
 * The two questions push to talk asks of a key press, and the label it shows.
 *
 * Split from the listener itself so they can be checked without dragging the
 * voice store - and every timer, socket and audio context behind it - into a
 * check that only wants to know whether a key counts.
 */

/** A key pressed into one of these means typing, not talking. */
function isTyping(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null;
  if (!element) return false;
  const tag = element.tagName;
  return tag === 'INPUT' || tag === 'TEXTAREA' || element.isContentEditable === true;
}

/**
 * Should this event open the microphone?
 *
 * Two rules, and both fail in ways nobody reports as a push-to-talk bug: a key
 * that also types would broadcast whatever is being written into the composer,
 * and an auto-repeat while the key is held would re-open a microphone that the
 * release already closed.
 */
export function isTalkKey(
  event: { code: string; repeat?: boolean; target?: EventTarget | null },
  configured: string,
): boolean {
  if (event.code !== configured) return false;
  if (event.repeat) return false;
  return !isTyping(event.target ?? null);
}

/** How a key code reads to a person. `AltRight` is not a label. */
export function describeKey(code: string): string {
  const named: Record<string, string> = {
    AltLeft: 'Left Alt',
    AltRight: 'Right Alt',
    ControlLeft: 'Left Ctrl',
    ControlRight: 'Right Ctrl',
    ShiftLeft: 'Left Shift',
    ShiftRight: 'Right Shift',
    Space: 'Space',
    CapsLock: 'Caps Lock',
    Backquote: '`',
  };
  if (named[code]) return named[code];
  if (code.startsWith('Key')) return code.slice(3);
  if (code.startsWith('Digit')) return code.slice(5);
  if (code.startsWith('Numpad')) return `Numpad ${code.slice(6)}`;
  return code;
}

/**
 * The decisions in the recorder that go wrong silently.
 *
 * The file name has to end in an extension that matches the container it was
 * recorded into - a WebM called `.m4a` is a file the operating system refuses
 * to open for a reason nobody can see from inside the app - and the counter on
 * screen has to agree with the minimum length underneath it, or a recording
 * reading 0:01 is rejected as too short.
 */
import assert from 'node:assert/strict';
import { VOICE_WAVEFORM_BARS, isVoiceNote } from '@betweenus/shared-types';
import {
  MAX_SECONDS,
  MIN_SECONDS,
  extensionFor,
  formatDuration,
  toWaveform,
  voiceFileName,
} from './voice-note';

// The extension follows the container, whatever else is in the mime type.
assert.equal(extensionFor('audio/webm;codecs=opus'), 'webm');
assert.equal(extensionFor('audio/mp4;codecs=opus'), 'm4a');
assert.equal(extensionFor('audio/ogg;codecs=opus'), 'ogg');
// Anything unrecognised falls back to WebM, which is what the recorder picked
// first and what every runtime this ships on can play.
assert.equal(extensionFor('audio/something-new'), 'webm');

// A name that sorts by when it was recorded and says what it is.
const name = voiceFileName('audio/webm;codecs=opus', new Date(2026, 7, 29, 9, 5, 3));
assert.equal(name, 'voice_20260829_090503.webm');
assert.ok(/^voice_\d{8}_\d{6}\.[a-z0-9]+$/.test(name), 'every field is padded');
assert.equal(
  voiceFileName('audio/mp4', new Date(2026, 7, 29, 9, 5, 3)),
  'voice_20260829_090503.m4a',
);

// A slip of the finger is not a message; a recording walked away from is not
// an open microphone for ever.
assert.ok(MIN_SECONDS >= 1, 'a quarter-second of room tone is never what anybody meant');
assert.ok(MAX_SECONDS > MIN_SECONDS, 'the ceiling is above the floor');

// The counter, which is read at a glance and so has to be padded.
assert.equal(formatDuration(0), '0:00');
assert.equal(formatDuration(9), '0:09');
assert.equal(formatDuration(69), '1:09');
assert.equal(formatDuration(600), '10:00');
// Part-seconds round down, so the counter never shows 0:01 for a recording the
// minimum above would refuse to send.
assert.equal(formatDuration(0.9), '0:00');
assert.equal(formatDuration(-5), '0:00', 'a clock that ran backwards still reads zero');

// --- The waveform ----------------------------------------------------------
//
// Every one of these fails silently: a wrong bucket count draws a waveform of
// the wrong width, a missing normalise draws a quiet recording as silence, and
// a missing floor draws a pause as a hole that reads as a damaged file.

// Always the same number of bars, whatever it was measured from - which is
// what makes a three-second message and a three-minute one the same shape of
// thing rather than the same shape at two widths.
const short = toWaveform([0.1, 0.9]);
const long = toWaveform(Array.from({ length: 3000 }, (_, at) => (at % 7) / 7));
assert.equal(short.length, VOICE_WAVEFORM_BARS);
assert.equal(long.length, VOICE_WAVEFORM_BARS);
assert.equal(toWaveform([], 12).length, 0, 'nothing measured draws nothing');

// Normalised against the loudest bar, so a quiet recording looks like a
// recording. Microphone levels differ by an order of magnitude between
// devices, and a waveform is read as a shape, never as a measurement.
const quiet = toWaveform([0.001, 0.002, 0.004, 0.002], 4);
const loud = toWaveform([0.25, 0.5, 1, 0.5], 4);
assert.deepEqual(quiet, loud, 'the same shape at any volume is the same waveform');
assert.equal(Math.max(...loud), 1, 'the loudest bar reaches the top');

// A floor under every bar, so a pause is a line rather than a hole.
const gap = toWaveform([1, 0, 0, 1], 4);
assert.ok(Math.min(...gap) > 0, 'silence is still drawn');
assert.ok(Math.min(...gap) < 0.2, 'and is still visibly quieter than speech');

// Silence throughout normalises to nothing to divide by. A flat line is the
// honest answer; NaN is what the arithmetic gives without the guard.
const silent = toWaveform([0, 0, 0], 4);
assert.ok(silent.every((bar) => Number.isFinite(bar) && bar > 0), 'no NaN bars');

// Bars stay inside the range the renderer scales against.
for (const bar of [...short, ...long, ...quiet]) {
  assert.ok(bar > 0 && bar <= 1, `bar ${bar} is outside 0..1`);
}

// --- Which attachments get the voice treatment -----------------------------
//
// A recorded note gets a waveform bubble; a music file somebody shared gets
// its name and a download, because that is what sharing a track means.
const base = { key: 'k', url: 'u', contentType: 'audio/webm', size: 1, iv: 'i', epoch: 1 };
assert.ok(isVoiceNote({ ...base, name: 'voice_20260830_011311.webm', waveform: [0.5] }));
// Recorded before waveforms existed: recognised by the name this client gives.
assert.ok(isVoiceNote({ ...base, name: 'voice_20260830_011311.webm' }));
assert.ok(!isVoiceNote({ ...base, name: 'interview.mp3' }), 'a shared track is not a voice note');
assert.ok(
  !isVoiceNote({ ...base, name: 'voice_20260830_011311.webm', contentType: 'video/mp4' }),
  'the name alone does not make a video into a voice note',
);
// The name check must not match something merely starting with the word.
assert.ok(!isVoiceNote({ ...base, name: 'voice_memo.webm' }));

console.log('voice-note: ok');

import { VOICE_WAVEFORM_BARS } from '@betweenus/shared-types';

/**
 * Recording a voice message.
 *
 * A voice message is not a new kind of message. It is a recording, encrypted
 * and uploaded exactly like a file somebody picked with the paperclip, and it
 * arrives as an audio attachment that the message list already knows how to
 * play. That is the whole design, and it is why this file is short: everything
 * downstream of "here is a File" already existed.
 *
 * What it does own is the awkward half - holding a microphone open, stopping
 * it properly, and handing the track back to the operating system afterwards.
 * A recorder that leaks its stream leaves the recording light on, which is the
 * one bug in this area nobody forgives.
 */

/**
 * What to record into.
 *
 * Opus in a WebM container is the first choice: it is what Chromium encodes
 * natively, it is what the voice call path already uses, and it is roughly a
 * tenth the size of anything uncompressed. The rest is fallback for a runtime
 * that disagrees - Safari answers MP4/AAC - and the empty string at the end is
 * "whatever you would have picked anyway", which is always allowed.
 */
const CANDIDATES = [
  'audio/webm;codecs=opus',
  'audio/webm',
  'audio/mp4;codecs=opus',
  'audio/mp4',
  'audio/ogg;codecs=opus',
  '',
];

/** The first container this runtime will actually record into. */
function pickType(): string {
  if (typeof MediaRecorder === 'undefined') return '';
  return CANDIDATES.find((type) => type === '' || MediaRecorder.isTypeSupported(type)) ?? '';
}

/** Whether this runtime can record at all, asked before a button is drawn. */
export function canRecordVoice(): boolean {
  return (
    typeof MediaRecorder !== 'undefined' &&
    typeof navigator !== 'undefined' &&
    typeof navigator.mediaDevices?.getUserMedia === 'function'
  );
}

/** The file extension that matches a recorder's mime type. */
export function extensionFor(type: string): string {
  if (type.includes('mp4')) return 'm4a';
  if (type.includes('ogg')) return 'ogg';
  return 'webm';
}

/** A finished recording: the file, and what it looked like being made. */
export interface RecordedVoice {
  file: File;
  /** Seconds, rounded to a tenth - the label, not a seek position. */
  duration: number;
  /** Bar heights 0..1, `VOICE_WAVEFORM_BARS` of them. */
  waveform: number[];
}

/**
 * A recording in progress.
 *
 * Two ways out, and they are not the same. `stop` returns the recording;
 * `cancel` throws it away. Both release the microphone, because the only thing
 * worse than a lost recording is a recording light that stays on after it.
 */
export interface VoiceRecording {
  /** Finishes and returns it, or null when nothing worth sending was captured. */
  stop(): Promise<RecordedVoice | null>;
  /** Abandons it. Nothing is returned and nothing is kept. */
  cancel(): void;
  /** Seconds recorded so far, for the counter on screen. */
  elapsed(): number;
  /**
   * The bars measured so far, so the composer can draw the recording as it
   * happens. The same samples that end up in the manifest.
   */
  levels(): number[];
}

/**
 * Longer than this and the recorder stops itself.
 *
 * Five minutes, matched to nothing in particular except that a voice message
 * is a voice message. What it is really guarding is the case where somebody
 * starts a recording and walks away: without a ceiling that is an open
 * microphone and a growing buffer until the window is closed.
 */
export const MAX_SECONDS = 5 * 60;

/**
 * A recording shorter than this is a slip of the finger, not a message.
 *
 * Every messenger has this threshold because every messenger has the same
 * gesture: a tap that was meant to be a hold produces a quarter-second of
 * room tone, and sending it is never what anybody meant.
 */
export const MIN_SECONDS = 1;

/**
 * Opens the microphone and starts recording.
 *
 * Throws if the microphone is refused or missing, which is the caller's to put
 * on screen: it is the one failure here a person can do something about.
 */
export async function startVoiceRecording(): Promise<VoiceRecording> {
  const stream = await navigator.mediaDevices.getUserMedia({
    // The processing a spoken message wants, and the same three the call path
    // asks for in its `clear` mode. A voice note is speech in a room, not a
    // recording session.
    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
  });

  const type = pickType();
  const recorder = new MediaRecorder(stream, type ? { mimeType: type } : undefined);
  const chunks: Blob[] = [];
  recorder.ondataavailable = (event) => {
    if (event.data.size > 0) chunks.push(event.data);
  };

  // The shape of the message, measured while it is being spoken.
  //
  // Taken off the live stream rather than computed from the finished file,
  // because the finished file is compressed Opus - getting samples back out of
  // it means decoding it, and this is a signal already passing through here.
  const meter = openMeter(stream);

  const startedAt = Date.now();
  let released = false;
  const release = (): void => {
    if (released) return;
    released = true;
    meter.close();
    for (const track of stream.getTracks()) track.stop();
  };

  recorder.start();
  // The ceiling, as a timer rather than as a check somewhere: a recorder that
  // has been walked away from is precisely the one nobody is asking anything.
  const ceiling = window.setTimeout(() => {
    if (recorder.state !== 'inactive') recorder.stop();
  }, MAX_SECONDS * 1000);

  const elapsed = (): number => (Date.now() - startedAt) / 1000;

  return {
    elapsed,
    levels: () => meter.levels(),

    cancel(): void {
      window.clearTimeout(ceiling);
      if (recorder.state !== 'inactive') recorder.stop();
      chunks.length = 0;
      release();
    },

    async stop(): Promise<RecordedVoice | null> {
      window.clearTimeout(ceiling);
      const seconds = elapsed();
      // Read before `release`, which closes the meter.
      const measured = meter.levels();

      // The last chunk arrives with `stop`, not before it, so the file cannot
      // be assembled until the recorder says it is done.
      await new Promise<void>((resolve) => {
        if (recorder.state === 'inactive') {
          resolve();
          return;
        }
        recorder.onstop = () => resolve();
        recorder.stop();
      });
      release();

      if (seconds < MIN_SECONDS || chunks.length === 0) return null;

      const recorded = recorder.mimeType || type || 'audio/webm';
      const blob = new Blob(chunks, { type: recorded });
      return {
        file: new File([blob], voiceFileName(recorded), { type: recorded }),
        duration: Math.round(seconds * 10) / 10,
        waveform: toWaveform(measured),
      };
    },
  };
}

/**
 * How often the level is sampled while recording.
 *
 * Ten times a second: fast enough that a syllable registers as its own bar in
 * a short message, slow enough that a five-minute recording is a few thousand
 * numbers rather than a few hundred thousand, all of which are then thrown
 * away by the downsample anyway.
 */
const SAMPLE_MS = 100;

/**
 * A meter on the live microphone.
 *
 * `AnalyserNode` over `ScriptProcessorNode` because the former is a read
 * whenever you want one and the latter is a deprecated callback on the audio
 * thread. Nothing here is in the recording path - the meter is a branch off
 * the same stream, so a failure to open it costs the waveform and never the
 * message.
 */
function openMeter(stream: MediaStream): { levels: () => number[]; close: () => void } {
  const samples: number[] = [];
  let context: AudioContext | null = null;
  let ticker = 0;

  try {
    context = new AudioContext();
    const analyser = context.createAnalyser();
    // Small: this is a loudness reading, not a spectrum. A short window also
    // means the value tracks the syllable rather than averaging over it.
    analyser.fftSize = 512;
    context.createMediaStreamSource(stream).connect(analyser);

    const buffer = new Float32Array(analyser.fftSize);
    ticker = window.setInterval(() => {
      analyser.getFloatTimeDomainData(buffer);
      // Root mean square, which is loudness as an ear hears it. A peak reading
      // makes every bar full height the moment anybody says a hard consonant.
      let sum = 0;
      for (const value of buffer) sum += value * value;
      samples.push(Math.sqrt(sum / buffer.length));
    }, SAMPLE_MS);
  } catch {
    // No meter on this runtime. The recording is unaffected; the message
    // arrives with no waveform and the player draws a flat one.
  }

  return {
    levels: () => [...samples],
    close: () => {
      if (ticker) window.clearInterval(ticker);
      void context?.close().catch(() => undefined);
    },
  };
}

/**
 * Raw amplitude samples, as the bars a player draws.
 *
 * Two steps, and the second is the one that matters. Downsampling to a fixed
 * count makes every message the same width. Normalising against the loudest
 * bar makes a quiet recording look like a recording rather than like silence -
 * absolute levels vary by an order of magnitude between microphones, and a
 * waveform is read as a shape, never as a measurement.
 *
 * A floor under every bar so silence is still a line. A waveform with gaps in
 * it reads as a broken file rather than as a pause for breath.
 */
export function toWaveform(samples: number[], bars = VOICE_WAVEFORM_BARS): number[] {
  if (samples.length === 0) return [];

  const buckets: number[] = [];
  for (let index = 0; index < bars; index += 1) {
    const from = Math.floor((index * samples.length) / bars);
    const to = Math.max(from + 1, Math.floor(((index + 1) * samples.length) / bars));
    let sum = 0;
    for (let at = from; at < to; at += 1) sum += samples[at] ?? 0;
    buckets.push(sum / (to - from));
  }

  const loudest = Math.max(...buckets);
  // Everything was silence: a flat line is honest, and dividing by zero is not.
  if (loudest <= 0) return buckets.map(() => MIN_BAR);
  return buckets.map((value) => Math.max(MIN_BAR, Math.min(1, value / loudest)));
}

/** No bar is ever shorter than this, so a pause is a line and not a hole. */
const MIN_BAR = 0.08;

/**
 * What a recording is called.
 *
 * Named for what it is and when it was, so a channel of them reads as a list
 * rather than as six files called "audio". The stamp is local time, because it
 * is a label for whoever is looking at it and not a timestamp anything parses.
 */
export function voiceFileName(contentType: string, at: Date = new Date()): string {
  const pad = (value: number): string => value.toString().padStart(2, '0');
  const stamp =
    `${at.getFullYear()}${pad(at.getMonth() + 1)}${pad(at.getDate())}` +
    `_${pad(at.getHours())}${pad(at.getMinutes())}${pad(at.getSeconds())}`;
  return `voice_${stamp}.${extensionFor(contentType)}`;
}

/** `m:ss`, which is how long a voice message is ever worth spelling out. */
export function formatDuration(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  return `${Math.floor(whole / 60)}:${(whole % 60).toString().padStart(2, '0')}`;
}

/**
 * Self-check for the microphone capture and encoder settings.
 *
 * Run with `pnpm --filter @betweenus/desktop check`. Two things here are only
 * audible to other people: a constraint object that quietly asks for the wrong
 * processing, and a gate that chatters or eats the start of a word.
 */
import assert from 'node:assert/strict';
import { workletSource } from './mic-gate';
import {
  DEFAULT_VOICE_SETTINGS,
  GATE_CLOSED,
  GATE_RANGE,
  amplitudeToDb,
  deviceConstraint,
  micCapture,
  micEncoding,
  micProcessing,
  migrateVoiceSettings,
  stepGate,
  type VoiceSettings,
} from './voice-quality';

const clear: VoiceSettings = { ...DEFAULT_VOICE_SETTINGS };
const hifi: VoiceSettings = { ...DEFAULT_VOICE_SETTINGS, mode: 'hifi' };

// The default is the ordinary suppressor and *not* the model-based one: it is
// the cheap one that suits a quiet room, and paying for the expensive one on
// every call anybody ever makes is what the three levels exist to stop.
assert.deepEqual(micProcessing(clear), {
  echoCancellation: true,
  noiseSuppression: true,
  autoGainControl: true,
  voiceIsolation: false,
});

// High is the only level that asks for the model.
assert.equal(micProcessing({ ...clear, noiseSuppression: 'high' }).voiceIsolation, true);
assert.equal(micProcessing({ ...clear, noiseSuppression: 'high' }).noiseSuppression, true);

// Off turns both suppressors off, not just the weak one.
assert.deepEqual(micProcessing({ ...clear, noiseSuppression: 'off' }), {
  echoCancellation: true,
  noiseSuppression: false,
  autoGainControl: true,
  voiceIsolation: false,
});

// Music gets none of it, whatever the switches say - every one of them is
// destructive to anything that is not speech.
assert.deepEqual(micProcessing(hifi), {
  echoCancellation: false,
  noiseSuppression: false,
  autoGainControl: false,
  voiceIsolation: false,
});
assert.deepEqual(
  micProcessing({ ...hifi, echoCancellation: true, noiseSuppression: 'high', autoGainControl: true }),
  micProcessing(hifi),
);

// Channel counts follow the mode; a voice in stereo is half the bitrate wasted.
assert.equal(micCapture(clear).channelCount, 1);
assert.equal(micCapture(hifi).channelCount, 2);

// No device chosen means no `deviceId` constraint at all: the system default is
// what most people want.
assert.equal('deviceId' in micCapture(clear), false);
assert.equal('deviceId' in deviceConstraint(null), false);

// A chosen device is named with `exact`, and nothing weaker. The bare string is
// the `ideal` form, which Chromium is free to ignore in favour of the system
// default - and does. That is "changing the input device does not change the
// input device", so it is asserted rather than left to a comment.
assert.deepEqual(micCapture({ ...clear, inputDeviceId: 'usb-mic' }).deviceId, {
  exact: 'usb-mic',
});
assert.deepEqual(deviceConstraint('usb-mic'), { deviceId: { exact: 'usb-mic' } });

// Capture constraints are constraints and nothing else. The gate is applied
// after the capture now rather than passed into it - see voice.ts.
assert.equal('processor' in micCapture(clear), false);

// Speech at Discord's bitrate, silence not transmitted; music at twice that in
// stereo, with every silence sent because a held note is one.
assert.equal(micEncoding(clear).maxBitrate, 64_000);
assert.equal(micEncoding(clear).dtx, true);
assert.equal(micEncoding(clear).stereo, false);
assert.equal(micEncoding(hifi).maxBitrate, 128_000);
assert.equal(micEncoding(hifi).dtx, false);
assert.equal(micEncoding(hifi).stereo, true);
// Loss redundancy on both: a lost packet is inaudible rather than a click.
assert.equal(micEncoding(clear).red, true);
assert.equal(micEncoding(hifi).red, true);

// dBFS: full scale is 0, quiet is negative, silence is floored rather than
// -Infinity (which would take the gate's arithmetic with it).
assert.equal(amplitudeToDb(1), 0);
assert.ok(amplitudeToDb(0.1) < -19 && amplitudeToDb(0.1) > -21);
assert.equal(amplitudeToDb(0), -100);
assert.ok(Number.isFinite(amplitudeToDb(0)));

// The gate opens the instant the level crosses, not a ramp later.
const threshold = -50;
assert.equal(stepGate(GATE_CLOSED, -60, threshold, 0).open, false);
const opened = stepGate(GATE_CLOSED, -40, threshold, 1);
assert.equal(opened.open, true);

// It holds through the gap between two words rather than closing in it.
assert.equal(stepGate(opened, -90, threshold, 1.2).open, true);
assert.equal(stepGate(opened, -90, threshold, 1.4).open, false);

// Hysteresis: a voice sitting on the line keeps it open instead of chattering.
const onTheLine = stepGate(opened, -53, threshold, 1.5);
assert.equal(onTheLine.open, true, 'closed within the hysteresis band');
assert.deepEqual(stepGate(onTheLine, -57, threshold, 2), { open: false, heldUntil: 1.3 });

// A closed gate is not re-opened by the hysteresis band on its own - otherwise
// room tone six decibels under the threshold would hold it open forever.
assert.equal(stepGate(GATE_CLOSED, -53, threshold, 5).open, false);

// The slider covers the useful range and the default sits inside it.
assert.ok(GATE_RANGE.minDb < GATE_RANGE.maxDb);
assert.ok(
  DEFAULT_VOICE_SETTINGS.gateThresholdDb !== null &&
    DEFAULT_VOICE_SETTINGS.gateThresholdDb > GATE_RANGE.minDb &&
    DEFAULT_VOICE_SETTINGS.gateThresholdDb < GATE_RANGE.maxDb,
);

// The worklet is assembled from these two functions' own source so the gate
// under test above is the gate on the audio thread. Compiling it here is what
// catches a build that renamed something out from under the splice.
assert.doesNotThrow(() => new Function(workletSource), 'the gate worklet is not valid JavaScript');
assert.ok(workletSource.includes('const stepGate ='));
assert.ok(workletSource.includes('const amplitudeToDb ='));

console.log('voice-quality self-check passed');


// --- Upgrading from the boolean suppression switch -------------------------

// The whole reason `migrateVoiceSettings` exists: local storage written by an
// older build carries a boolean where a level belongs, and spreading it over
// the defaults would leave `true` sitting in a field typed as three strings.
// Nothing throws - it just behaves as `standard` while the settings screen has
// nothing selected, which is the kind of bug that survives a release.
assert.equal(migrateVoiceSettings({ noiseSuppression: true }).noiseSuppression, 'standard');
assert.equal(migrateVoiceSettings({ noiseSuppression: false }).noiseSuppression, 'off');

// A value already migrated is left exactly as it is.
assert.equal(migrateVoiceSettings({ noiseSuppression: 'high' }).noiseSuppression, 'high');

// A hand-edited or corrupted profile drops the field rather than poisoning it,
// so the default behind it takes over.
assert.equal('noiseSuppression' in migrateVoiceSettings({ noiseSuppression: 'loud' }), false);
assert.equal('noiseSuppression' in migrateVoiceSettings({ noiseSuppression: 3 }), false);

// Everything else on a stored profile survives the migration untouched.
assert.equal(migrateVoiceSettings({ gateThresholdDb: -42 }).gateThresholdDb, -42);

// Garbage in the slot where an object belongs is not a crash on startup.
assert.deepEqual(migrateVoiceSettings(null), {});
assert.deepEqual(migrateVoiceSettings('nonsense'), {});

// A migrated profile produces a constraint object, which is the thing that
// actually had to keep working across the upgrade.
assert.equal(
  micProcessing({ ...clear, ...migrateVoiceSettings({ noiseSuppression: true }) }).voiceIsolation,
  false,
);

/**
 * How a microphone is captured and encoded, and why the defaults are not it.
 *
 * A voice channel used to be published with a media SDK's defaults: 48 kbps,
 * mono, echo cancellation / noise suppression / gain control left at whatever
 * the browser felt like, one device (the system default), and no way
 * for anybody to change any of it. That is fine on a headset in a quiet room and
 * audibly worse than Discord anywhere else - a fan, a mechanical keyboard or a
 * flatmate ends up in the room with you, and somebody with two microphones has
 * no way to say which one.
 *
 * What Discord actually does, and what is reachable from here:
 *
 * - **Ask the platform for its best denoiser.** Discord ships Krisp, an ML model
 *   in a native library. Chromium has grown `voiceIsolation`, which is the same
 *   idea behind a constraint: a stronger, model-based suppressor that keeps a
 *   voice and drops everything else. Where it exists it replaces
 *   `noiseSuppression`; where it does not, it is ignored and the ordinary WebRTC
 *   suppressor still runs. Nothing to ship, nothing to load.
 * - **Gate the quiet.** Suppression cleans up a signal; it does not decide that
 *   nobody is talking. Discord's input sensitivity does, and it is what makes a
 *   Discord call silent between sentences. That is `mic-gate.ts`, driven by the
 *   threshold here.
 * - **Spend a sensible bitrate.** 64 kbps mono is Discord's voice channel and is
 *   transparent for speech; 128 kbps stereo is what a music bot or a "hi-fi"
 *   mode wants. These are the numbers every media SDK's "presets" are made of,
 *   written out here where the reason for them can sit beside them.
 * - **Let the two modes be opposite.** Everything that makes speech clear ruins
 *   music: gain control pumps, suppression eats reverb tails, DTX cuts a quiet
 *   passage out entirely, and mono throws half a recording away. Rather than a
 *   quality slider that means nothing, the mode says what the microphone is
 *   *for*, exactly as the screen-share picker asks what is on the screen
 *   (`share-quality.ts`).
 *
 * The pure part lives here, with a self-check, because a wrong constraint object
 * is inaudible until somebody else is listening to it.
 */

import { NO_OVERRIDE, type QualityOverride } from './share-quality';

/**
 * Something that sits between a captured track and the one that is sent.
 *
 * The gate in `mic-gate.ts` is the only implementation, and the shape is the
 * one a media SDK used to call with. It is kept because it is the right shape
 * independently of who calls it: give it the raw track and an audio context,
 * take `processedTrack` back, send that instead.
 */
export interface AudioProcessor {
  readonly name: string;
  processedTrack?: MediaStreamTrack;
  init(options: { track: MediaStreamTrack; audioContext: AudioContext }): Promise<void>;
  restart(options: { track: MediaStreamTrack; audioContext: AudioContext }): Promise<void>;
  destroy(): Promise<void>;
}

/**
 * The constraints half of `getUserMedia({ audio })`.
 *
 * `voiceIsolation` is not in the DOM types yet, so the extra member is spelled
 * out rather than cast away at every call site.
 */
export type MicConstraints = MediaTrackConstraints & { voiceIsolation?: boolean };

/**
 * How the microphone is encoded once it is on a sender.
 *
 * `maxBitrate` goes on the encoding parameters, which can be changed on a live
 * sender. `stereo`, `dtx` and `red` are Opus payload options and live in the
 * SDP's `fmtp` line, so they are fixed when the connection is negotiated - see
 * `mesh.ts`, which is where both are applied.
 */
export interface MicEncoding {
  maxBitrate: number;
  stereo: boolean;
  dtx: boolean;
  red: boolean;
}

/**
 * What the microphone is for. Not a quality slider - the two want opposite
 * processing, and neither is "better".
 */
export type VoiceMode = 'clear' | 'hifi';

/**
 * How much suppression to ask the platform for. See `VoiceSettings.noiseSuppression`.
 *
 * Deliberately the same three names the Android client uses, so a support
 * conversation about "set it to High" means one thing on both.
 */
export type NoiseSuppression = 'off' | 'standard' | 'high';

export interface VoiceSettings {
  mode: VoiceMode;
  /** `null` means the system default device, which is what most people want. */
  inputDeviceId: string | null;
  outputDeviceId: string | null;
  /**
   * Fall back to the system default when a chosen device is unplugged.
   *
   * A device id is remembered forever and the hardware is not: pick a headset
   * once and every later call is pinned to it, so the call after it is put away
   * opens a microphone that is in a drawer. On by default, because a device
   * that is gone is not a choice.
   *
   * It is only ever the *chosen* device going away that drops the choice. This
   * used to drop it on any device change at all, which made an explicit choice
   * impossible to keep: see `unpinDevices` in stores/voice.ts.
   *
   * Off is for the machine where the fallback is worse than the failure - one
   * whose system default is a microphone that must never be picked.
   */
  followSystemDevices: boolean;
  echoCancellation: boolean;
  /**
   * How hard to work at removing everything that is not a voice.
   *
   * Three levels rather than a switch, because the honest answer to "should
   * noise suppression be on" depends on hardware nobody can see from here.
   * `standard` is the ordinary WebRTC suppressor, which is tuned for
   * *stationary* noise - a fan, a hiss, an air conditioner. `high` additionally
   * asks for `voiceIsolation`, Chromium's model-based suppressor, which is the
   * one that removes a keyboard, a dog and a flatmate; it costs measurably more
   * CPU and it is the wrong default for a laptop on battery in a quiet room.
   *
   * Where `voiceIsolation` is not supported the constraint is ignored and
   * `high` degrades to `standard`, which is why asking for it costs nothing.
   */
  noiseSuppression: NoiseSuppression;
  autoGainControl: boolean;
  /**
   * dBFS below which the microphone is closed, or `null` for an open mic.
   * Discord calls this input sensitivity.
   */
  gateThresholdDb: number | null;
  /**
   * Talk only while a key is held. The gate answers "is somebody speaking";
   * this answers "do you mean to be heard", which is the question a shared room,
   * a mechanical keyboard and a phone call in the background all raise.
   */
  pushToTalk: boolean;
  /**
   * `KeyboardEvent.code` of the key that opens the microphone. A code rather
   * than a key, so it is the same physical key on every layout.
   */
  pushToTalkKey: string;
  /**
   * The two notes when somebody arrives or leaves the call. On by default: a
   * voice channel is the one screen nobody is looking at, so who is in it has
   * to be audible or it is not knowable at all.
   */
  callTones: boolean;
  /**
   * What this machine says the share ladder got wrong - see `QualityOverride`
   * in `share-quality.ts`. It lives here because it is a property of the
   * machine and the network it is on, which is what everything else in this
   * object is; it covers a screen share in a call and a remote session, since
   * both are the same encoder being asked the same question.
   */
  share: QualityOverride;
}

export const DEFAULT_VOICE_SETTINGS: VoiceSettings = {
  mode: 'clear',
  inputDeviceId: null,
  outputDeviceId: null,
  followSystemDevices: true,
  echoCancellation: true,
  noiseSuppression: 'standard',
  autoGainControl: true,
  // Quiet enough that a normal voice is nowhere near it, loud enough to sit
  // above room tone on a cheap microphone.
  gateThresholdDb: -50,
  pushToTalk: false,
  // Not Space: the composer is one keystroke away at all times, and a
  // push-to-talk key that also types is a key nobody can use.
  pushToTalkKey: 'AltRight',
  callTones: true,
  share: NO_OVERRIDE,
};

/**
 * The usable ends of the sensitivity slider. Below -80 dBFS is under the noise
 * floor of every microphone made, and above -20 dBFS a shout would not open it.
 */
export const GATE_RANGE = { minDb: -80, maxDb: -20 } as const;

/** Opus bitrate ceilings, in bits per second. */
const BITRATE = {
  // Discord's voice channel. Transparent for speech; anything more is spent on
  // reproducing a room nobody wants reproduced.
  clear: 64_000,
  // Two channels of music, which is four times the information a voice is.
  hifi: 128_000,
} as const;

/**
 * The three switches, resolved for a mode.
 *
 * `voiceIsolation` is the interesting one: where Chromium supports it, it is a
 * model-based suppressor in the same league as Krisp and it takes over from
 * `noiseSuppression` entirely. Where it does not, an unknown constraint is
 * ignored - so asking costs nothing and never fails a capture.
 */
export function micProcessing(
  settings: VoiceSettings,
): Pick<
  MicConstraints,
  'echoCancellation' | 'noiseSuppression' | 'autoGainControl' | 'voiceIsolation'
> {
  if (settings.mode === 'hifi') {
    // Not a preference: every one of these is destructive to music, and a mode
    // that says "this is an instrument" has already answered the question.
    return {
      echoCancellation: false,
      noiseSuppression: false,
      autoGainControl: false,
      voiceIsolation: false,
    };
  }

  return {
    echoCancellation: settings.echoCancellation,
    noiseSuppression: settings.noiseSuppression !== 'off',
    autoGainControl: settings.autoGainControl,
    // Only `high` asks for the model. This used to be tied to the same boolean
    // as `noiseSuppression`, which meant every call anybody ever made ran the
    // expensive suppressor whether or not their room needed it, and there was
    // no way to ask for the cheap one on its own.
    voiceIsolation: settings.noiseSuppression === 'high',
  };
}

/**
 * Reads a stored settings object written by an older build.
 *
 * `noiseSuppression` was a boolean until the three levels existed, and the
 * settings store spreads whatever is in local storage over the defaults - so
 * without this a profile written last week arrives with `true` where a
 * `NoiseSuppression` belongs. That is not a type error at runtime, it is worse:
 * `true !== 'off'` and `true !== 'high'`, so the setting silently behaves as
 * `standard` while the settings screen has no option matching it and draws
 * nothing as selected.
 *
 * Pure, and exported, because a migration that is only exercised by upgrading
 * users is a migration nobody ever runs before shipping it.
 */
export function migrateVoiceSettings(stored: unknown): Partial<VoiceSettings> {
  if (typeof stored !== 'object' || stored === null) return {};
  const settings = { ...(stored as Record<string, unknown>) };

  // The old switch: on meant the ordinary suppressor, which is `standard`.
  // Anyone who wants the model-based one can now say so explicitly.
  if (typeof settings.noiseSuppression === 'boolean') {
    settings.noiseSuppression = settings.noiseSuppression ? 'standard' : 'off';
  } else if (!isNoiseSuppression(settings.noiseSuppression)) {
    delete settings.noiseSuppression;
  }

  return settings as Partial<VoiceSettings>;
}

/** Narrows an unknown to a level, so a hand-edited profile cannot poison it. */
export function isNoiseSuppression(value: unknown): value is NoiseSuppression {
  return value === 'off' || value === 'standard' || value === 'high';
}

/**
 * The `deviceId` half of an audio constraint, for a chosen device or none.
 *
 * `exact`, and it has to be. A bare `deviceId` string is the `ideal` form,
 * which is advisory: the browser scores every microphone by fitness distance
 * and is free to hand back a different one, and Chromium does - it opens
 * whatever the operating system calls the default. That is the whole of
 * "changing the input device does not change the input device". Every pick
 * reopened the same microphone, and nothing said so, because a capture that
 * ignored the constraint is not an error.
 *
 * Asking properly costs the silent fallback for a device that has been
 * unplugged since it was chosen: `exact` refuses instead of substituting. That
 * fallback is worth having and is now done deliberately, once, by
 * `openAudioCapture` - rather than bought by asking in a form nothing honours.
 */
export function deviceConstraint(deviceId: string | null): Pick<MicConstraints, 'deviceId'> {
  return deviceId ? { deviceId: { exact: deviceId } } : {};
}

/** Capture constraints for the microphone. */
export function micCapture(settings: VoiceSettings): MicConstraints {
  return {
    ...micProcessing(settings),
    channelCount: settings.mode === 'hifi' ? 2 : 1,
    ...deviceConstraint(settings.inputDeviceId),
  };
}

/** How the microphone is encoded on the wire. */
export function micEncoding(settings: VoiceSettings): MicEncoding {
  const hifi = settings.mode === 'hifi';

  return {
    maxBitrate: hifi ? BITRATE.hifi : BITRATE.clear,
    stereo: hifi,
    // DTX stops sending during silence, which is most of a call and none of a
    // recording - a held piano note is exactly what it deletes.
    dtx: !hifi,
    // Redundant audio data: a packet carries the previous one as well, so a
    // single loss is inaudible. Cheap at these bitrates and worth it for both.
    red: true,
  };
}

export interface GateState {
  open: boolean;
  /** Seconds on the audio clock until which the gate stays open regardless. */
  heldUntil: number;
}

export const GATE_CLOSED: GateState = { open: false, heldUntil: 0 };

/**
 * One step of the noise gate.
 *
 * Three behaviours, and all three matter: it opens the instant the level
 * crosses the threshold (a gate that fades in eats the start of a word), it
 * holds open for a moment afterwards (so the gap between two words is not a
 * gap in the call), and it needs the level to fall further than the threshold
 * before it closes (without that, a voice sitting exactly on the line chatters
 * the gate open and shut).
 *
 * `nowSeconds` is the audio clock, not the wall clock.
 *
 * Deliberately self-contained - no module-level constants, no imports. This
 * function's own source is stringified into an AudioWorklet by `mic-gate.ts`,
 * so anything it closes over would not exist on the audio thread.
 */
export function stepGate(
  state: GateState,
  levelDb: number,
  thresholdDb: number,
  nowSeconds: number,
): GateState {
  const HOLD_SECONDS = 0.3;
  const HYSTERESIS_DB = 6;

  const loud = levelDb >= thresholdDb;
  const open = loud || nowSeconds < state.heldUntil || (state.open && levelDb >= thresholdDb - HYSTERESIS_DB);

  return { open, heldUntil: loud ? nowSeconds + HOLD_SECONDS : state.heldUntil };
}

/**
 * RMS amplitude (0..1) as dBFS, floored at -100 so silence is a number rather
 * than `-Infinity`. Self-contained for the same reason `stepGate` is.
 */
export function amplitudeToDb(rms: number): number {
  return rms > 0.00001 ? 20 * Math.log10(rms) : -100;
}

/**
 * Web Push, browser side: staying reachable with the tab closed.
 *
 * The Electron app needs none of this - it is a running process with a tray
 * icon, and it raises its own notifications. A browser tab is not: close it and
 * the account is unreachable until somebody opens it again. That is the gap
 * this closes, and it is the only reason a service worker exists in this repo.
 *
 * No Firebase, and no SDK. `PushManager.subscribe` is a browser API, VAPID is
 * the standard that lets a deployment identify itself to whichever push service
 * that browser uses, and the whole client half is the fifty lines below. The
 * server has the other half in `notification-service/src/push/webpush.ts`.
 *
 * The subscription registers into the same device registry a phone's FCM token
 * does, keyed on the same client-minted device id the key directory uses. One
 * browser profile is one row for as long as its site data lives.
 */
import type { PushData, WebPushSubscription } from '@betweenus/shared-types';
import { api } from './api';
import { deviceId } from './e2ee';
import { isDesktopRuntime } from './platform';

const SERVICE_WORKER_URL = '/sw.js';

/** Where a notification points, as the worker describes it. */
export interface PushRoute {
  kind: 'channel' | 'call' | 'remote' | 'friends' | 'server' | 'home';
  channelId?: string;
  serverId?: string;
  machineId?: string;
  url: string;
}

type WorkerMessage =
  | { betweenus: 'push'; data: PushData }
  | { betweenus: 'open'; route: PushRoute };

/** True where all three pieces exist. Safari before 16.4 has none of them. */
function supported(): boolean {
  return (
    !isDesktopRuntime() &&
    typeof navigator !== 'undefined' &&
    'serviceWorker' in navigator &&
    'PushManager' in window &&
    'Notification' in window
  );
}

/**
 * Registers the worker and subscribes this browser, if it can and may.
 *
 * Called after sign-in, and safe to call again: `subscribe` returns the
 * existing subscription rather than minting a second, and the registry upsert
 * on the other end is keyed on the device id.
 *
 * Every reason to stop is a normal outcome rather than an error. No worker
 * support, no VAPID keys on the deployment, permission not granted - each of
 * those is a browser that gets notifications while its tab is open and nothing
 * when it is closed, which is what this app did before any of this existed.
 */
export async function startWebPush(): Promise<void> {
  if (!supported()) return;

  try {
    // Asked before the permission prompt, so a deployment that cannot push
    // never prompts. A prompt that leads nowhere is a prompt people deny, and
    // a denied prompt is not offered again by the browser.
    const { vapidPublicKey } = await api.pushKey();
    if (!vapidPublicKey) return;

    const registration = await navigator.serviceWorker.register(SERVICE_WORKER_URL);
    await navigator.serviceWorker.ready;

    if (Notification.permission === 'denied') return;
    if (Notification.permission === 'default') {
      const granted = await Notification.requestPermission();
      if (granted !== 'granted') return;
    }

    const subscription =
      (await registration.pushManager.getSubscription()) ??
      (await registration.pushManager.subscribe({
        // Without this every push would be visible to the user or the browser
        // drops the subscription; the spec has no silent option any more.
        userVisibleOnly: true,
        applicationServerKey: fromBase64Url(vapidPublicKey),
      }));

    await api.registerPushDevice({
      token: JSON.stringify(toStored(subscription)),
      platform: 'web',
      deviceId: deviceId(),
      label: browserLabel(),
    });
  } catch {
    // A browser that will not subscribe is a browser without push. It is not a
    // browser that should fail to sign in, which is what throwing here would
    // make it.
  }
}

/**
 * Unsubscribes and forgets the row. Called on sign-out.
 *
 * The registry row goes first, because it is the one that matters: a row left
 * behind pushes this account's messages at whoever uses this browser next.
 * The local subscription is torn down afterwards and its failure is ignored -
 * a subscription nothing will ever send to is harmless.
 */
export async function stopWebPush(): Promise<void> {
  if (!supported()) return;
  try {
    await api.unregisterPushDevice(deviceId());
  } catch {
    // Signed out already, or offline. The next sign-in re-registers.
  }
  try {
    const registration = await navigator.serviceWorker.getRegistration(SERVICE_WORKER_URL);
    const subscription = await registration?.pushManager.getSubscription();
    await subscription?.unsubscribe();
  } catch {
    // Nothing to undo.
  }
}

/**
 * Listens for what the worker hands over: a push while a tab is open, and a
 * notification somebody tapped.
 *
 * Returns an unsubscribe, like every other listener in this app.
 */
export function onPushMessage(handle: (message: WorkerMessage) => void): () => void {
  if (!supported()) return () => undefined;

  const listener = (event: MessageEvent): void => {
    const message = event.data as WorkerMessage | undefined;
    if (!message || typeof message.betweenus !== 'string') return;
    handle(message);
  };
  navigator.serviceWorker.addEventListener('message', listener);
  return () => navigator.serviceWorker.removeEventListener('message', listener);
}

/**
 * The route a cold start was opened with, taken off the URL.
 *
 * A worker that finds no running client opens one with the destination in the
 * query string, because that is the only channel a page which does not exist
 * yet can be told anything on. Read once and cleared, so a refresh does not
 * jump somewhere the person has since navigated away from.
 */
export function takeStartupRoute(): PushRoute | null {
  if (typeof window === 'undefined') return null;
  const params = new URLSearchParams(window.location.search);

  const found: PushRoute | null =
    read(params, 'channel', (id) => ({ kind: 'channel', channelId: id, url: '' })) ??
    read(params, 'call', (id) => ({ kind: 'call', channelId: id, url: '' })) ??
    read(params, 'remote', (id) => ({ kind: 'remote', machineId: id, url: '' })) ??
    read(params, 'server', (id) => ({ kind: 'server', serverId: id, url: '' })) ??
    (params.get('view') === 'friends' ? { kind: 'friends', url: '' } : null);

  if (found) {
    // The query string has done its job. Leaving it there means a reload takes
    // somebody back to a message they read ten minutes ago.
    window.history.replaceState({}, '', window.location.pathname);
  }
  return found;
}

function read(
  params: URLSearchParams,
  name: string,
  build: (id: string) => PushRoute,
): PushRoute | null {
  const value = params.get(name);
  return value ? build(value) : null;
}

/** The shape the registry stores. `toJSON` is the only portable way to get it. */
function toStored(subscription: PushSubscription): WebPushSubscription {
  const raw = subscription.toJSON() as { endpoint?: string; keys?: Record<string, string> };
  return {
    endpoint: raw.endpoint ?? subscription.endpoint,
    keys: { p256dh: raw.keys?.p256dh ?? '', auth: raw.keys?.auth ?? '' },
  };
}

/**
 * A name for the row in somebody's device list. The user agent string is a
 * lie by design, so this only looks for the few names worth telling apart and
 * says "Browser" for everything else rather than guessing wrongly in detail.
 */
function browserLabel(): string {
  const agent = navigator.userAgent;
  if (/Edg\//.test(agent)) return 'Edge';
  if (/OPR\//.test(agent)) return 'Opera';
  if (/Firefox\//.test(agent)) return 'Firefox';
  if (/Chrome\//.test(agent)) return 'Chrome';
  if (/Safari\//.test(agent)) return 'Safari';
  return 'Browser';
}

/**
 * The VAPID key arrives base64url and `subscribe` wants bytes.
 *
 * Padding has to be put back before `atob`, and the two url-safe characters
 * swapped for the standard ones. Getting this wrong produces an
 * `InvalidCharacterError` at subscribe time and nothing else, which is why it
 * is one function with the reason written on it.
 */
function fromBase64Url(value: string): Uint8Array<ArrayBuffer> {
  const padded = value.padEnd(value.length + ((4 - (value.length % 4)) % 4), '=');
  const binary = atob(padded.replace(/-/g, '+').replace(/_/g, '/'));
  const bytes = new Uint8Array(new ArrayBuffer(binary.length));
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

import assert from 'node:assert/strict';
import { assetStamp, currentStamp, fetchServedStamp, isNewBuild } from './web-update';

const BUILT = `<!doctype html>
<html><head>
<link rel="icon" href="/icon.svg" />
<script type="module" crossorigin src="/assets/index-A1B2C3.js"></script>
<link rel="stylesheet" crossorigin href="/assets/index-D4E5F6.css" />
</head><body><div id="root"></div></body></html>`;

const REBUILT = BUILT.replace('A1B2C3', 'ZZZ999');

// --- assetStamp -------------------------------------------------------------

const built = assetStamp(BUILT);
assert.equal(built, '/assets/index-A1B2C3.js|/assets/index-D4E5F6.css', 'sorted, and only assets');
assert.notEqual(assetStamp(REBUILT), built, 'one changed hash is a different build');
assert.equal(
  assetStamp(BUILT.replace(/(<script[^>]*><\/script>)\n(<link rel="stylesheet"[^>]*\/>)/, '$2\n$1')),
  built,
  're-ordered markup loading the same files is the same build',
);
assert.equal(
  assetStamp(`${BUILT}<script src="/assets/index-A1B2C3.js"></script>`),
  built,
  'a name listed twice counts once',
);

// The development server serves no hashed assets at all, and a proxy's holding
// page serves none either. Both are "cannot tell", which must never read as a
// new build - that would be a reload loop.
assert.equal(assetStamp('<html><body><script type="module" src="/src/main.tsx"></script>'), '');
assert.equal(assetStamp('<h1>502 Bad Gateway</h1>'), '');

// --- isNewBuild -------------------------------------------------------------

assert.equal(isNewBuild(built, assetStamp(REBUILT)), true);
assert.equal(isNewBuild(built, built), false);
assert.equal(isNewBuild(built, ''), false, 'a failed fetch is not a new build');
assert.equal(isNewBuild('', built), false, 'a tab that cannot fingerprint itself never prompts');

// --- currentStamp -----------------------------------------------------------

// The one part of the DOM this reads, stood up by hand rather than by pulling
// in a DOM implementation for four elements.
const node = (attribute: string, value: string): HTMLElement =>
  ({ getAttribute: (name: string) => (name === attribute ? value : null) }) as HTMLElement;

const fakeDocument = {
  querySelectorAll: () => {
    const nodes = [
      node('src', '/assets/index-A1B2C3.js'),
      node('href', '/assets/index-D4E5F6.css'),
      // Not a build artefact, and must not be part of the fingerprint: it never
      // changes, so a page of nothing else would look permanently current.
      node('href', '/icon.svg'),
    ];
    return { forEach: (fn: (n: HTMLElement) => void) => nodes.forEach(fn) };
  },
} as unknown as Document;

assert.equal(
  currentStamp(fakeDocument),
  built,
  'what the tab is running fingerprints the same way as what is served',
);

// --- fetchServedStamp -------------------------------------------------------

const served = (body: string, status = 200): typeof fetch =>
  (async () => new Response(body, { status })) as unknown as typeof fetch;

// `location` is what the browser gives this; Node needs it stood up.
(globalThis as unknown as { location: { origin: string } }).location = {
  origin: 'https://betweenus.example.com',
};

assert.equal(await fetchServedStamp(served(BUILT)), built);
assert.equal(await fetchServedStamp(served('gone', 404)), '', 'a 404 says nothing');
assert.equal(
  await fetchServedStamp((() => Promise.reject(new Error('offline'))) as unknown as typeof fetch),
  '',
  'offline says nothing rather than throwing into the poll',
);

console.log('web-update.check.ts: ok');

/**
 * "This tab is running an older build than the one being served."
 *
 * A browser tab cannot install anything, so the whole of a web update is a
 * reload - but nothing tells a long-lived tab that a deployment happened, and
 * this app is one people leave open for days. So it asks.
 *
 * What it asks about is the *asset fingerprint*, not a version number. Vite
 * names every built file `index-<hash>.js`, and the hash changes exactly when
 * the contents do; `index.html` is the one unhashed file and is the list of
 * which hashes are current. So fetching that one small file and comparing the
 * names in it against the names this tab actually loaded answers the question
 * exactly, with nothing to remember to bump at release time.
 *
 * It deliberately does not use the version in `package.json`: the web client is
 * built from the same source as the desktop app but is not versioned with it,
 * and a number nobody moves is a check that never fires.
 *
 * The desktop app does not use any of this - it has a real updater, in
 * services/updates.ts and electron/updates.ts.
 */

/** How often a visible tab asks. Also asked whenever a tab is brought back. */
export const POLL_MS = 5 * 60 * 1000;

const ASSET_PATTERN = /(?:src|href)="([^"]*\/assets\/[^"]+)"/g;

/**
 * The built asset names named by a document, as one comparable string.
 *
 * Sorted and de-duplicated, so re-ordered markup that loads the same files is
 * the same build. An empty string means "no fingerprint here" - a development
 * server, an error page, a proxy's holding page - and is never treated as a
 * difference, because prompting a reload on the strength of a failed fetch
 * would be a reload loop.
 */
export function assetStamp(html: string): string {
  const names = new Set<string>();
  for (const match of html.matchAll(ASSET_PATTERN)) {
    const url = match[1];
    if (url) names.add(url);
  }
  return [...names].sort().join('|');
}

/** The same fingerprint for the build this tab is running. */
export function currentStamp(document: Document): string {
  const nodes = document.querySelectorAll<HTMLElement>('script[src], link[href]');
  const names = new Set<string>();
  nodes.forEach((node) => {
    // The attribute rather than the property: the property is resolved to an
    // absolute URL, and the served HTML has the relative one.
    const url = node.getAttribute('src') ?? node.getAttribute('href') ?? '';
    if (url.includes('/assets/')) names.add(url);
  });
  return [...names].sort().join('|');
}

/**
 * Whether `served` is a different build from `running`.
 *
 * Both have to say something. Either being empty is "cannot tell", which is not
 * the same as "changed".
 */
export function isNewBuild(running: string, served: string): boolean {
  return running !== '' && served !== '' && running !== served;
}

/** What the tab is currently being served, or '' when that could not be found. */
export async function fetchServedStamp(fetchImpl: typeof fetch = fetch): Promise<string> {
  try {
    // `no-store` rather than a cache-busting query string: the query would make
    // every poll a cache miss at the CDN as well, and this one is cheap.
    const response = await fetchImpl(`${location.origin}/index.html`, { cache: 'no-store' });
    if (!response.ok) return '';
    return assetStamp(await response.text());
  } catch {
    // Offline, or the deployment is mid-restart. Nothing to say.
    return '';
  }
}

/**
 * Watches for a new deployment and calls `onAvailable` once. Returns the
 * function that stops watching.
 *
 * Once is enough: the offer stays on screen until it is taken or dismissed, and
 * a second deployment while it is up does not make it any more true.
 */
export function watchForNewBuild(onAvailable: () => void, pollMs = POLL_MS): () => void {
  const running = currentStamp(document);
  let stopped = false;

  const look = async (): Promise<void> => {
    if (stopped || document.hidden) return;
    if (isNewBuild(running, await fetchServedStamp())) {
      stopped = true;
      onAvailable();
    }
  };

  // A tab that has been in the background for a week is the one most likely to
  // be stale, and is also the one whose interval the browser has been
  // throttling. Coming back to it is the moment worth asking.
  const onVisible = (): void => {
    if (!document.hidden) void look();
  };

  const timer = setInterval(() => void look(), pollMs);
  document.addEventListener('visibilitychange', onVisible);

  return () => {
    stopped = true;
    clearInterval(timer);
    document.removeEventListener('visibilitychange', onVisible);
  };
}

/**
 * Self-check for the YouTube search parser.
 *
 * What it guards is a third party's JSON on its way into two `src` attributes.
 * A missing `snippet` must be a row that is skipped or a row with a fallback
 * title, never a thrown TypeError inside a render - and an id that is not
 * YouTube's id shape must never reach an iframe at all, which is the same rule
 * `youtube-relay.check.ts` holds on the other side of the app.
 *
 * Run with `pnpm --filter @betweenus/desktop check`.
 */
import assert from 'node:assert/strict';
import { parseResults, type YouTubeResult } from './youtube-search';

function item(videoId: unknown, snippet: unknown = {}): unknown {
  return { id: { videoId }, snippet };
}

/** The single row an answer was expected to produce. */
function one(payload: unknown): YouTubeResult {
  const results = parseResults(payload);
  assert.equal(results.length, 1);
  const first = results[0];
  assert.ok(first);
  return first;
}

// --- The ordinary answer ----------------------------------------------------

const ordinary = one({
  items: [
    item('dQw4w9WgXcQ', {
      title: 'Never Gonna Give You Up',
      channelTitle: 'Rick Astley',
      thumbnails: {
        default: { url: 'https://i.ytimg.com/vi/dQw4w9WgXcQ/default.jpg' },
        medium: { url: 'https://i.ytimg.com/vi/dQw4w9WgXcQ/mqdefault.jpg' },
      },
    }),
  ],
});
assert.equal(ordinary.videoId, 'dQw4w9WgXcQ');
assert.equal(ordinary.title, 'Never Gonna Give You Up');
assert.equal(ordinary.channel, 'Rick Astley');
// Medium is preferred over default: the 120px one is visibly soft in a grid.
assert.equal(ordinary.thumbnail, 'https://i.ytimg.com/vi/dQw4w9WgXcQ/mqdefault.jpg');

// `high` when there is no `medium`, and nothing at all rather than a crash when
// there are no thumbnails - the row still plays, it just draws a grey box.
assert.equal(
  one({
    items: [item('aaaaaaaaaaa', { thumbnails: { high: { url: 'https://i.ytimg.com/x/hq.jpg' } } })],
  }).thumbnail,
  'https://i.ytimg.com/x/hq.jpg',
);
assert.equal(one({ items: [item('aaaaaaaaaaa')] }).thumbnail, '');

// --- Ids that must not reach a frame ---------------------------------------

// A channel or playlist result has no `videoId`, and the API sends those
// whenever `type=video` is dropped by accident. Skipped, not rendered.
assert.deepEqual(parseResults({ items: [{ id: { channelId: 'UCabc' }, snippet: {} }] }), []);
for (const bad of ['', 'short', 'has space!!', '../../etc/passwd', 12, null, undefined]) {
  assert.deepEqual(parseResults({ items: [item(bad)] }), [], `accepted id ${String(bad)}`);
}

// --- Answers that are not the answer ---------------------------------------

// An error body, an empty body, and a body of the wrong type all mean "no
// results" rather than an exception thrown out of a component.
assert.deepEqual(parseResults({ error: { code: 403 } }), []);
assert.deepEqual(parseResults({}), []);
assert.deepEqual(parseResults({ items: 'nope' }), []);
assert.deepEqual(parseResults([]), []);

// A title that is not a string falls back to the id, because a row with no
// label at all is a row nobody can tell apart from the one above it.
assert.equal(one({ items: [item('bbbbbbbbbbb', { title: 42 })] }).title, 'bbbbbbbbbbb');

