/**
 * A YouTube player driven by `postMessage`, with no YouTube script in this
 * window.
 *
 * The obvious way to embed YouTube is to load `iframe_api.js` and use the
 * object it hands back. That is remote code running in the renderer, and this
 * app's whole CSP argument is one line: `script-src` stays `'self'`, so nothing
 * this window fetches can become code. Loosening it for a music player would
 * trade the strongest security property the client has for a convenience.
 *
 * It is not needed. `iframe_api.js` is a wrapper around a `postMessage`
 * protocol the embed speaks anyway, and that protocol is a hundred lines:
 *
 * - Post `{event: 'listening'}` to the frame and it starts sending state back.
 * - Post `{event: 'command', func, args}` to drive it.
 * - It posts `{event: 'infoDelivery', info: {...}}` with the position, the
 *   player state, the duration and the title.
 *
 * So the frame is a cross-origin iframe pointed at youtube-nocookie.com, and
 * the only thing that changes in the CSP is `frame-src`. YouTube's code runs in
 * YouTube's origin, in a document this one cannot read and which cannot read
 * this one, and the entire surface between them is the message channel below -
 * which is checked for origin on the way in, because a `message` handler that
 * does not check origin is a hole any page in any frame can post through.
 *
 * The frame carries no `sandbox` attribute, and that is the deliberate part.
 * `sandbox` without `allow-same-origin` gives a frame an *opaque* origin, so
 * everything it posts arrives as `event.origin === 'null'` and the origin check
 * refuses all of it - a player that loads, shows a picture and never answers a
 * command. It also buys nothing here: a cross-origin frame is already isolated
 * from this document by the same-origin policy, exactly as hard.
 *
 * ponytail: one provider. Spotify is a second `ListenProvider` and a second
 * class with the same four methods, and it needs things this does not - an
 * OAuth flow, a Premium account per listener, and the Web Playback SDK, which
 * *is* remote code and so needs the CSP conversation this design avoided. It is
 * not modelled ahead of time; the seam is the discriminant on `ListenTrack`.
 */

/** The origin the frame is loaded from. */
export const YOUTUBE_ORIGIN = 'https://www.youtube.com';

/**
 * Origins a message from the player may arrive on.
 *
 * Both, because the embed is served from youtube.com and its player code
 * sometimes posts as youtube-nocookie.com or mobile subdomains. Anything else
 * is another frame on the page pretending, and is dropped.
 */
export const YOUTUBE_ORIGINS = [
  'https://www.youtube.com',
  'https://www.youtube-nocookie.com',
  'https://youtube.com',
  'https://youtube-nocookie.com',
  'https://m.youtube.com',
  'https://music.youtube.com',
];

/**
 * The frame this window actually holds, which is not always the embed.
 *
 * A packaged desktop build serves this document from `file://`, and a YouTube
 * embed framed by a `file://` document is refused outright - error 153, "Video
 * player configuration error", on every track. The player decides that from the
 * page it is embedded in, so neither a `Referer` header nor a custom `app://`
 * scheme moves it; both were measured, and both still refuse.
 *
 * So on desktop the main process serves one page over loopback and this window
 * frames that, and it frames the embed. The protocol is unchanged - the same
 * `listening` handshake and the same commands - it just passes through one more
 * window, which relays in both directions. See electron/youtube-relay.ts.
 *
 * Everywhere with a real origin already - the web client, a dev run over
 * http://localhost - the embed is framed directly, as before.
 */
export function playerSrc(videoId: string, origin: string, relay: string | null): string {
  if (!relay) return embedUrl(videoId, origin);
  const separator = relay.includes('?') ? '&' : '?';
  return `${relay}${separator}v=${encodeURIComponent(videoId)}`;
}

/** The origins a message may legitimately arrive on, relay included. */
export function messageOrigins(relay: string | null): string[] {
  if (!relay) return YOUTUBE_ORIGINS;
  try {
    const origin = new URL(relay).origin;
    const localhostOrigin = origin.replace('127.0.0.1', 'localhost');
    const ipOrigin = origin.replace('localhost', '127.0.0.1');
    return Array.from(new Set([...YOUTUBE_ORIGINS, origin, localhostOrigin, ipOrigin]));
  } catch {
    return YOUTUBE_ORIGINS;
  }
}

/** What the embed reports about itself. */
export interface YouTubeState {
  /** Seconds, as the player reports them. */
  positionMs: number;
  durationMs: number;
  playing: boolean;
  ended: boolean;
  title: string | null;
  error: number | null;
}

/**
 * The player-state numbers the embed sends. Named because `1` and `2` in a
 * comparison are the kind of thing that reads correctly and means the opposite.
 */
const UNSTARTED = -1;
const ENDED = 0;
const PLAYING = 1;

/**
 * Pulls a video id out of whatever somebody pasted.
 *
 * Every shape YouTube itself produces: a watch URL, a share link, a short, an
 * embed, a music.youtube link, and the bare id - which is what somebody who
 * already knows the id will type. Returns null for anything else rather than
 * guessing, because a guess ends up in an iframe `src` in everybody's window.
 */
export function parseYouTube(input: string): string | null {
  const text = input.trim();
  if (!text) return null;

  // The bare id. Eleven characters of YouTube's alphabet, which is specific
  // enough that nothing else a person pastes looks like it.
  if (/^[A-Za-z0-9_-]{11}$/.test(text)) return text;

  let url: URL;
  try {
    url = new URL(text.includes('://') ? text : `https://${text}`);
  } catch {
    return null;
  }

  const host = url.hostname.replace(/^www\./, '');
  const path = url.pathname.split('/').filter(Boolean);

  if (host === 'youtu.be') return valid(path[0]);
  if (host !== 'youtube.com' && host !== 'youtube-nocookie.com' && host !== 'music.youtube.com') {
    return null;
  }
  if (path[0] === 'watch') return valid(url.searchParams.get('v'));
  if (path[0] === 'shorts' || path[0] === 'embed' || path[0] === 'live') return valid(path[1]);
  // `/v=...` without `/watch`, which some share paths still produce.
  return valid(url.searchParams.get('v'));
}

function valid(id: string | null | undefined): string | null {
  return id && /^[A-Za-z0-9_-]{11}$/.test(id) ? id : null;
}

/**
 * The URL the frame is pointed at. Separated so the check can read it.
 *
 * `origin` is passed only when it is a real web origin. A packaged Electron
 * build serves the renderer from `file://`, and `origin=file://` is not a thing
 * YouTube accepts - it refuses the API handshake outright, which is a player
 * that loads, shows a frame and never answers a command. Omitting the parameter
 * is allowed and is what that case needs.
 */
export function embedUrl(videoId: string, origin: string): string {
  const params = new URLSearchParams({
    enablejsapi: '1',
    // Asked for up front as well as commanded later. The command path needs the
    // handshake to have completed; this does not, so a player that is slow to
    // answer still starts on time for whoever added the track.
    autoplay: '1',
    // Nothing but this app drives the player: the call decides what plays, so
    // the embed's own controls would be a second set of buttons that change
    // what one person hears and nobody else.
    controls: '0',
    disablekb: '1',
    // No "watch next" grid over the last frame of a track, and no suggestions
    // from a channel nobody chose.
    rel: '0',
    modestbranding: '1',
    playsinline: '1',
    fs: '1',
  });
  if (/^https?:\/\//.test(origin)) {
    const safeOrigin = origin.replace('127.0.0.1', 'localhost');
    params.set('origin', safeOrigin);
    params.set('widget_referrer', safeOrigin);
  }
  return `${YOUTUBE_ORIGIN}/embed/${videoId}?${params.toString()}`;
}

/**
 * One embed, wrapped so the store can talk to it in milliseconds.
 *
 * The frame is created here and appended by the caller: a player with nowhere
 * to live does not autoplay, and the element has to be in the document before
 * the first command is worth sending.
 */
export class YouTubePlayer {
  readonly frame: HTMLIFrameElement;
  private state: YouTubeState = {
    positionMs: 0,
    durationMs: 0,
    playing: false,
    ended: false,
    title: null,
    error: null,
  };
  private ready = false;
  /** Commands sent before the frame answered, replayed once it does. */
  private readonly pending: Array<[string, unknown[]]> = [];
  private readonly listener: (event: MessageEvent) => void;
  private handshake: number | null = null;

  /** Where a message may come from: the embed, or the relay standing in for it. */
  private readonly origins: string[];

  constructor(
    videoId: string,
    private readonly onState: (state: YouTubeState) => void,
  ) {
    const relay = typeof window !== 'undefined' ? (window.betweenus?.youtubeRelay ?? null) : null;
    this.origins = messageOrigins(relay);
    this.frame = document.createElement('iframe');
    this.frame.src = playerSrc(videoId, window.location.origin, relay);
    this.frame.allow = 'autoplay; encrypted-media; fullscreen; picture-in-picture';
    this.frame.setAttribute('allowfullscreen', 'true');
    this.frame.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
    this.frame.referrerPolicy = 'strict-origin-when-cross-origin';
    // No `sandbox` attribute, and that is deliberate rather than an omission.
    //
    // It was `sandbox="allow-scripts allow-presentation"` and that is why
    // nothing ever played. Without `allow-same-origin` a frame is given an
    // *opaque* origin, so every message it posts arrives with
    // `event.origin === 'null'` - which the origin check below correctly
    // refused, every time. The handshake therefore never completed, the queued
    // `playVideo` was never flushed, and the result was a player that looked
    // present and was silent, with nothing in the console to say why.
    //
    // Adding `allow-same-origin` back would fix that and buy nothing: this
    // frame is already cross-origin, so the same-origin policy isolates it from
    // this document exactly as hard as the sandbox was pretending to. The
    // sandbox was security theatre that broke the feature.
    this.frame.setAttribute('title', 'Listen Together');
    this.frame.style.border = '0';
    this.frame.style.width = '100%';
    this.frame.style.height = '100%';

    this.listener = (event) => this.receive(event);
    window.addEventListener('message', this.listener);

    // The frame answers `listening` only once it has loaded, and there is no
    // load event that reliably arrives first across every runtime this app runs
    // in. Asking repeatedly until it replies is a hundred bytes a second for
    // about a second, and is the difference between a player that starts and
    // one that silently never does.
    this.handshake = window.setInterval(() => {
      if (this.ready) {
        this.stopHandshake();
        return;
      }
      this.post('listening', []);
    }, 250);
    this.post('listening', []);
  }

  private stopHandshake(): void {
    if (this.handshake !== null) window.clearInterval(this.handshake);
    this.handshake = null;
  }

  private receive(event: MessageEvent): void {
    // The check that makes this safe. Without it any frame or opener on the
    // page can post a message shaped like YouTube's and drive the player - or
    // worse, be believed about a title that is then drawn.
    if (!this.origins.includes(event.origin)) return;
    if (event.source !== this.frame.contentWindow) return;

    let message: { event?: string; info?: Record<string, unknown> };
    try {
      message = typeof event.data === 'string' ? JSON.parse(event.data) : event.data;
    } catch {
      return;
    }
    if (!message || typeof message !== 'object') return;

    if (message.event === 'onReady' || message.event === 'initialDelivery') {
      this.flush();
    }
    if (message.event === 'onError') {
      const code =
        typeof message.info === 'number'
          ? message.info
          : typeof message.info === 'object' && message.info && typeof (message.info as { errorCode?: unknown }).errorCode === 'number'
            ? (message.info as { errorCode: number }).errorCode
            : 150;
      const next = { ...this.state, error: code };
      this.state = next;
      this.onState(next);
      return;
    }
    if (message.event !== 'infoDelivery' && message.event !== 'initialDelivery') return;

    const info = message.info ?? {};
    const next = { ...this.state };
    if (typeof info.currentTime === 'number') next.positionMs = Math.round(info.currentTime * 1000);
    if (typeof info.duration === 'number' && info.duration > 0) {
      next.durationMs = Math.round(info.duration * 1000);
    }
    if (typeof info.playerState === 'number') {
      next.playing = info.playerState === PLAYING;
      next.ended = info.playerState === ENDED;
      // The first state that is not "unstarted" is the frame saying it exists,
      // which is when queued commands are worth sending.
      if (info.playerState !== UNSTARTED) this.flush();
      if (info.playerState === PLAYING) next.error = null;
    }
    if (typeof info.errorCode === 'number') {
      next.error = info.errorCode;
    }
    const data = info.videoData as { title?: unknown } | undefined;
    if (data && typeof data.title === 'string' && data.title) next.title = data.title;

    this.state = next;
    this.onState(next);
  }

  private flush(): void {
    if (this.ready) return;
    this.ready = true;
    this.stopHandshake();
    for (const [func, args] of this.pending.splice(0)) this.post('command', [], func, args);
  }

  private post(event: string, _args: unknown[], func?: string, args: unknown[] = []): void {
    const window_ = this.frame.contentWindow;
    if (!window_) return;
    const body = func ? { event, func, args } : { event };
    // `'*'` as the target: the frame's own origin is YouTube's and is the only
    // thing that can receive this, and naming it exactly has to be right for
    // whichever of the two hosts the player settled on. The message carries no
    // secret - it is "play", "pause", "seek to 1:04" - so the cost of being
    // wrong about the target is nothing, and the cost of being wrong about the
    // name is silence.
    window_.postMessage(JSON.stringify({ ...body, id: 'betweenus', channel: 'widget' }), '*');
  }

  private command(func: string, args: unknown[] = []): void {
    if (!this.ready) {
      // One entry per command, most recent wins: replaying a queue of six
      // seeks on the way in would make the player stutter through all of them.
      const at = this.pending.findIndex(([name]) => name === func);
      if (at !== -1) this.pending.splice(at, 1);
      this.pending.push([func, args]);
      return;
    }
    this.post('command', [], func, args);
  }

  play(): void {
    this.command('playVideo');
  }

  pause(): void {
    this.command('pauseVideo');
  }

  seek(positionMs: number): void {
    // `true` is "allow seeking ahead of what is buffered", which is what a
    // correction needs: the alternative is a player that agrees to catch up
    // only as far as it had already downloaded.
    this.command('seekTo', [positionMs / 1000, true]);
  }

  /** 0 to 100. Used for ducking under whoever is talking, not by a slider. */
  setVolume(volume: number): void {
    this.command('setVolume', [Math.round(Math.min(100, Math.max(0, volume)))]);
  }

  /** The last thing the frame said about itself. */
  current(): YouTubeState {
    return this.state;
  }

  close(): void {
    this.stopHandshake();
    window.removeEventListener('message', this.listener);
    this.frame.remove();
  }
}

/**
 * Which of the shared activities has the voice stage.
 *
 * A flag, and nothing else. The stage is the big rectangle in the middle of a
 * voice channel - the tiles, or a shared video, or a board - and everything two
 * people do together in a call is drawn there rather than in a popover hanging
 * off a button. That was tried and it was wrong twice: a games library is too
 * big for a popover, and a popover over a call is a thing that covers the faces
 * it is supposed to sit beside.
 *
 * So the Apps button opens an *Apps screen* on the stage, and picking something
 * there replaces it with that activity's own panel. One more screen, on the
 * surface everything else already uses.
 *
 * Local, like the other two panel flags: which screen one person is looking at
 * is not a thing to broadcast to the call.
 *
 * This store deliberately imports nothing. The three panels are mutually
 * exclusive, and that is enforced where the switching happens - `VoiceControls`
 * and `AppsPanel` - because a store that closed the other two would have to
 * import them, and they would have to import it back.
 */
import { create } from 'zustand';

interface AppsState {
  /** True while the chooser has the stage. */
  open: boolean;
  setOpen: (open: boolean) => void;
}

export const useAppsStore = create<AppsState>((set) => ({
  open: false,
  setOpen: (open) => set({ open }),
}));

/**
 * How this machine's microphone is set up. A machine, not an account: the
 * device names, the sensitivity that suits this room and the switches that suit
 * this headset are all properties of where you are sitting, so they belong in
 * local storage rather than on the server the way notification preferences do.
 *
 * Nothing here knows about peer connections. The voice store watches this and applies
 * what changed to the live room - which keeps the dependency pointing one way
 * and lets settings be changed before ever joining a call.
 */
import { create } from 'zustand';
import {
  DEFAULT_VOICE_SETTINGS,
  migrateVoiceSettings,
  type VoiceSettings,
} from '../services/voice-quality';

const STORAGE_KEY = 'betweenus.voice-settings';

function load(): VoiceSettings {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (!stored) return DEFAULT_VOICE_SETTINGS;
    // Spread over the defaults, so a setting added later has a value in a
    // profile that was written before it existed - and migrated first, because
    // a setting whose *type* changed is not fixed by having a default behind
    // it. See `migrateVoiceSettings`.
    return { ...DEFAULT_VOICE_SETTINGS, ...migrateVoiceSettings(JSON.parse(stored)) };
  } catch {
    return DEFAULT_VOICE_SETTINGS;
  }
}

interface AudioSettingsState {
  settings: VoiceSettings;
  update: (patch: Partial<VoiceSettings>) => void;
}

export const useAudioSettings = create<AudioSettingsState>((set, get) => ({
  settings: load(),
  update: (patch) => {
    const settings = { ...get().settings, ...patch };
    set({ settings });
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
    } catch {
      // A profile with no storage still gets the setting for this session.
    }
  },
}));

import { create } from 'zustand';
import type { PublicUser } from '@betweenus/shared-types';
import { ApiError, api, apiBaseUrl, configureApi } from '../services/api';
import { chatSocket, onSocketTokenRejected, presenceSocket } from '../services/socket';
import { initIdentity, resetE2ee, type BackupSecret } from '../services/e2ee';
import { cache } from '../services/cache';
import { stopWebPush } from '../services/web-push';

/** Both realtime sockets carry the same access token and reconnect together. */
function connectSockets(accessToken: string): void {
  chatSocket.connect(accessToken);
  presenceSocket.connect(accessToken);
}

const STORAGE_KEY = 'betweenus.refreshToken';
/**
 * The address of the last account signed in on this machine, so the form comes
 * back filled in. Only the address: a password belongs in the OS keychain or
 * nowhere, and the refresh token above is what actually keeps a session alive
 * across restarts.
 */
const EMAIL_KEY = 'betweenus.lastEmail';

/** Prefills the login form. Empty on a machine nobody has signed in on. */
export function rememberedEmail(): string {
  return localStorage.getItem(EMAIL_KEY) ?? '';
}

interface AuthState {
  user: PublicUser | null;
  accessToken: string | null;
  status: 'idle' | 'loading' | 'authenticated';
  error: string | null;
  login: (email: string, password: string) => Promise<void>;
  loginWithProvider: (provider: string) => Promise<void>;
  register: (email: string, username: string, password: string) => Promise<void>;
  /**
   * Spends a reset token and signs in on the new password.
   *
   * Worth knowing what it costs: the identity backup is sealed with the *old*
   * password, so a reset leaves it unreadable. This machine keeps the key it
   * already holds and carries on; a machine signing in for the first time after
   * a reset gets a new device key and can read what arrives from then on, not
   * what came before. That is the price of a password nobody remembers, and it
   * is the same price every end-to-end encrypted system charges.
   */
  resetPassword: (token: string, newPassword: string) => Promise<void>;
  restore: () => Promise<void>;
  /** Re-reads the profile after it has been edited in settings. */
  refreshUser: () => Promise<void>;
  logout: () => Promise<void>;
  clearError: () => void;
}

export const useAuthStore = create<AuthState>((set, get) => ({
  user: null,
  accessToken: null,
  status: 'idle',
  error: null,

  clearError: () => set({ error: null }),

  refreshUser: async () => {
    set({ user: await api.me() });
  },

  login: async (email, password) => {
    set({ status: 'loading', error: null });
    try {
      const result = await api.login(email, password);
      localStorage.setItem(EMAIL_KEY, email);
      applySession(set, result.accessToken, result.refreshToken, result.user, {
        value: password,
        kind: 'password',
      });
    } catch (error) {
      set({ status: 'idle', error: messageOf(error) });
    }
  },

  /**
   * Provider sign-in. The browser does the provider part; this window only
   * waits for the one-time code and trades it for a session.
   */
  loginWithProvider: async (provider) => {
    const bridge = window.betweenus;
    if (!bridge) {
      // In a tab the page itself is the redirect target: leave for the provider
      // and come back with `?code=`, which `restore` trades for a session. The
      // desktop app cannot do this - it has no origin to be sent back to, which
      // is what its loopback server stands in for.
      set({ status: 'loading', error: null });
      const back = `${window.location.origin}${window.location.pathname}`;
      window.location.assign(
        `${apiBaseUrl()}/api/v1/auth/oauth/${provider}/start?redirect=${encodeURIComponent(back)}`,
      );
      return;
    }

    set({ status: 'loading', error: null });
    try {
      const code = await bridge.startOAuth(
        `${apiBaseUrl()}/api/v1/auth/oauth/${provider}/start`,
      );
      if (!code) {
        set({ status: 'idle', error: 'Sign-in was cancelled' });
        return;
      }
      const result = await api.oauthExchange(code);
      applySession(set, result.accessToken, result.refreshToken, result.user);
    } catch (error) {
      set({ status: 'idle', error: messageOf(error) });
    }
  },

  register: async (email, username, password) => {
    set({ status: 'loading', error: null });
    try {
      const result = await api.register(email, username, password);
      localStorage.setItem(EMAIL_KEY, email);
      applySession(set, result.accessToken, result.refreshToken, result.user, {
        value: password,
        kind: 'password',
      });
    } catch (error) {
      set({ status: 'idle', error: messageOf(error) });
    }
  },

  resetPassword: async (token, newPassword) => {
    set({ status: 'loading', error: null });
    try {
      const result = await api.resetPassword(token, newPassword);
      localStorage.setItem(EMAIL_KEY, result.user.email);
      applySession(set, result.accessToken, result.refreshToken, result.user, {
        value: newPassword,
        kind: 'password',
      });
    } catch (error) {
      set({ status: 'idle', error: messageOf(error) });
      throw error;
    }
  },

  /** Silent sign-in on launch using the stored refresh token. */
  restore: async () => {
    // A provider sign-in that went through the browser comes back here, as a
    // one-time code on the URL. Taken off the address bar either way: a code is
    // single use, and leaving a spent one in the history is noise at best.
    const returned = new URLSearchParams(window.location.search).get('code');
    if (returned) {
      window.history.replaceState(null, '', window.location.pathname);
      set({ status: 'loading', error: null });
      try {
        const result = await api.oauthExchange(returned);
        applySession(set, result.accessToken, result.refreshToken, result.user);
        return;
      } catch (error) {
        set({ status: 'idle', error: messageOf(error) });
        return;
      }
    }

    if (!localStorage.getItem(STORAGE_KEY)) return;

    set({ status: 'loading' });
    const accessToken = await refreshSession();
    if (!accessToken) {
      set({ status: 'idle' });
      return;
    }

    try {
      const user = await api.me();
      // Before anything reads from it: a cache belonging to another account has
      // to be gone, not merely about to be.
      await cache.claim(user.id).catch(() => undefined);
      set({ user, status: 'authenticated', error: null });
      void initIdentity(user.id).catch(() => undefined);
    } catch {
      set({ status: 'idle' });
    }
  },

  logout: async () => {
    const stored = localStorage.getItem(STORAGE_KEY);
    // First, while there is still an access token to make the call with. A
    // push registration left behind sends this account's messages to whoever
    // opens this browser next, and the request that removes it is
    // authenticated - so it cannot be done after the session is torn down.
    await stopWebPush();
    chatSocket.disconnect();
    presenceSocket.disconnect();
    resetE2ee();
    localStorage.removeItem(STORAGE_KEY);
    // Only a deliberate sign-out empties the cache. A session that expired on
    // its own is coming back, and should come back instantly.
    void cache.clear().catch(() => undefined);
    set({ user: null, accessToken: null, status: 'idle' });
    if (stored) await api.logout(stored).catch(() => undefined);
  },
}));

type Setter = (partial: Partial<AuthState>) => void;

function applySession(
  set: Setter,
  accessToken: string,
  refreshToken: string,
  user: PublicUser,
  secret?: BackupSecret,
): void {
  localStorage.setItem(STORAGE_KEY, refreshToken);
  void cache.claim(user.id).catch(() => undefined);
  set({ user, accessToken, status: 'authenticated', error: null });
  connectSockets(accessToken);
  // Device key setup runs alongside the first server load; everything that
  // needs key material awaits the same promise, so the order does not matter.
  //
  // The password goes with it and no further: it is what unseals this account's
  // identity backup on a machine that holds no key yet, which is what makes the
  // account work anywhere rather than only where it was created. It is never
  // stored, and the server never receives anything derived from it.
  void initIdentity(user.id, secret).catch(() => undefined);
}

function messageOf(error: unknown): string {
  if (error instanceof ApiError) return error.message;
  return 'Could not reach the server. Is the backend running?';
}

/**
 * Refresh tokens rotate, so two concurrent refreshes would race and one of them
 * would present an already-consumed token and get the session killed. Every
 * caller shares one in-flight request instead.
 */
let refreshInFlight: Promise<string | null> | null = null;

function refreshSession(): Promise<string | null> {
  if (refreshInFlight) return refreshInFlight;

  refreshInFlight = (async () => {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (!stored) {
      // Nothing left to refresh with. A window that still believes it is signed
      // in would keep sending tokenless requests and show "Missing bearer token"
      // under every screen, so end the session and let the login form take over.
      if (useAuthStore.getState().status !== 'idle') {
        useAuthStore.setState({ user: null, accessToken: null, status: 'idle' });
      }
      return null;
    }
    try {
      const tokens = await api.refresh(stored);
      localStorage.setItem(STORAGE_KEY, tokens.refreshToken);
      useAuthStore.setState({ accessToken: tokens.accessToken });
      connectSockets(tokens.accessToken);
      return tokens.accessToken;
    } catch (error) {
      // Only the server *rejecting* the token ends the session. A network
      // failure, a gateway 502 or a service still starting says nothing about
      // whether this session is still good - and throwing the token away there
      // signed people out permanently the first time the app opened before the
      // backend did, which on a desktop that starts with the system is most
      // times. The token is kept, the login screen says why, and the next
      // start signs back in on its own.
      const rejected = error instanceof ApiError && error.status === 401;
      if (!rejected && useAuthStore.getState().user) {
        // A session that is already running stays running. The credential was
        // never refused - the network was - so ending the session here threw
        // people back to a login form over a lift, a sleeping laptop or a
        // gateway restart, which is the sign-out nobody could explain. The
        // stored token is untouched and the next request refreshes again.
        return null;
      }
      if (rejected) localStorage.removeItem(STORAGE_KEY);
      useAuthStore.setState({
        user: null,
        accessToken: null,
        status: 'idle',
        error: rejected ? null : messageOf(error),
      });
      return null;
    }
  })().finally(() => {
    refreshInFlight = null;
  });

  return refreshInFlight;
}

// Rotating refresh: the API client asks for a fresh access token on a 401.
configureApi(() => useAuthStore.getState().accessToken, refreshSession);

// And so does a socket whose token was rejected: it carries the access token in
// its URL, so it outlives it, and nothing else would have asked.
onSocketTokenRejected(refreshSession);

/**
 * This account's own profile, changed on another of its devices. The picture in
 * the corner is the one thing every screen of the app has on it, so it moves
 * without waiting for a reload here too.
 */
chatSocket.on((event) => {
  if (event.type !== 'user.updated') return;
  const { user } = useAuthStore.getState();
  if (!user || user.id !== event.user.id) return;
  useAuthStore.setState({
    user: {
      ...user,
      username: event.user.username,
      displayName: event.user.displayName,
      avatarUrl: event.user.avatarUrl,
    },
  });
});

import { create } from 'zustand';
import { hasBody } from '@betweenus/shared-types';
import type {
  Channel,
  ChannelReadReceipt,
  ChannelType,
  DirectChannel,
  Message,
  MessageAttachment,
  MessageCustomEmoji,
  MessageForward,
  MessageReply,
  ServerMember,
  ServerWithRole,
  UserSummary,
  UpdateServerMemberRequest,
  UpdateServerRequest,
} from '@betweenus/shared-types';
import { PERMISSIONS } from '@betweenus/permissions';
import { api } from '../services/api';
import { chatSocket } from '../services/socket';
import {
  UNDECRYPTABLE,
  decryptForChannel,
  encryptForChannel,
  keyChannel,
  syncChannelKeys,
} from '../services/e2ee';
import { decodeBody, encodeBody } from '../services/message-body';
import {
  dismissChannelNotification,
  notifyMessage,
  publishUnreadCount,
  windowIsFocused,
} from '../services/notifications';
import { mentionsMe } from '../services/mentions';
import { cache } from '../services/cache';
import { forgetAttachments, openAttachment, uploadAttachment } from '../services/attachments';
import { emojiFor, forgetEmoji, loadEmoji, usedEmoji } from '../services/server-emoji';
import { useAuthStore } from './auth';

/**
 * A message as the client holds it: decrypted, and with the attachment
 * manifest lifted out of the body. The server never sees this shape - it
 * stores one ciphertext string.
 */
export interface DecryptedMessage extends Message {
  attachments: MessageAttachment[];
  /** What this message answers, quoted inside the envelope. */
  replyTo?: MessageReply;
  /** Pictures for the `:name:` shortcodes in `content`, carried with it. */
  emoji?: MessageCustomEmoji[];
  /** Set when these are somebody else's words, carried in from elsewhere. */
  forwardedFrom?: MessageForward;
}

interface ChatState {
  /** Home is the direct-message side of the app; a server is everything else. */
  view: 'home' | 'server';
  servers: ServerWithRole[];
  channels: Channel[];
  /** Open conversations, kept apart from a server's channels. */
  directs: Channel[];
  members: ServerMember[];
  messages: DecryptedMessage[];
  activeServerId: string | null;
  activeChannelId: string | null;
  /** channelId -> unread message count, for the dot in the sidebar. */
  unread: Record<string, number>;
  /**
   * channelId -> the read marker as this client last saw it. Kept because the
   * divider below is "everything after this", and the marker moves the moment
   * a channel is opened - so it has to be read before it is advanced.
   */
  readMarkers: Record<string, string | null>;
  /**
   * channelId -> the message the "new messages" line is drawn above, or null
   * for a channel with nothing new. It is placed when the channel is opened and
   * left alone while it stays open, the way Discord does it: a line that moved
   * every time something arrived would be no use for finding your place.
   */
  divider: Record<string, string | null>;
  /**
   * Decrypted history per channel, so reopening one paints immediately instead
   * of clearing the view and waiting for a fetch and fifty decryptions.
   *
   * Memory only, and deliberately: this is plaintext, and writing it to disk
   * would undo what the encryption is for. It dies with the window.
   */
  history: Record<string, DecryptedMessage[]>;
  loadingMessages: boolean;
  /**
   * True from opening a server until its channels and members have answered.
   *
   * Both columns are drawn from lists that start empty, so without this they
   * cannot tell "this server has no voice channels" from "nobody has said yet"
   * - and they were saying the first while the second was true. The channel
   * sidebar has a cache to paint from and the member list has nothing at all,
   * which is why the member column used to vanish entirely for the length of
   * the fetch.
   */
  loadingServer: boolean;
  /**
   * channelId -> the id to ask for the next page before, null once the channel
   * has been read back to its first message. A channel with no entry has not
   * been opened yet.
   */
  cursors: Record<string, string | null>;
  /** True while an older page is in flight, so the scroll does not ask twice. */
  loadingOlder: boolean;
  error: string | null;
  /** What the right-hand column shows, if anything. */
  rightPanel: 'members' | 'pins' | 'search' | 'none';
  /** Pinned messages of the open channel, newest pin first. */
  pins: DecryptedMessage[];
  /** True while the pin list is being fetched and decrypted for this channel. */
  loadingPins: boolean;
  /**
   * A message the pinned list or the search results asked to be shown. The
   * message list watches it, scrolls there and highlights it, then clears it.
   */
  jumpTo: string | null;
  /**
   * channelId -> everyone else's read marker in it. The "seen by" row under
   * your own messages is derived from these; see `features/chat/receipts.ts`.
   * Loaded when a channel is opened and kept current by `channel.read`.
   */
  receipts: Record<string, ChannelReadReceipt[]>;

  loadServers: () => Promise<void>;
  /** Read markers live on the account, so a badge survives a restart. */
  loadUnread: () => Promise<void>;
  /**
   * "I am looking at this now": clears the badge for the open channel and moves
   * its marker on the account. Called when the window regains focus and when a
   * message arrives in a channel that is already on screen - without it, a
   * message that arrived while the window was in the background stayed counted
   * even after it had been read.
   */
  markActiveRead: () => void;
  /** The channel on screen, wherever it lives. */
  activeChannel: () => Channel | undefined;
  showHome: () => void;
  selectServer: (serverId: string) => Promise<void>;
  selectChannel: (channelId: string) => Promise<void>;
  loadDirects: () => Promise<void>;
  openDirectChannel: (direct: DirectChannel) => Promise<void>;
  createServer: (name: string) => Promise<void>;
  /** Joins with an invite code. A slug is not one. */
  joinServer: (code: string) => Promise<void>;
  createChannel: (options: {
    name: string;
    type?: ChannelType;
    isPrivate?: boolean;
    memberIds?: string[];
  }) => Promise<void>;
  /**
   * The page before the oldest message on screen. Called by the message list
   * when it is scrolled near the top; a no-op once the channel is exhausted.
   */
  loadOlder: () => Promise<void>;
  sendMessage: (
    content: string,
    attachments?: MessageAttachment[],
    replyTo?: MessageReply,
    /** One-time: its media may be opened once, and opening it destroys it. */
    viewOnce?: boolean,
  ) => Promise<void>;
  /**
   * The same message again, in another channel.
   *
   * A copy and not a pointer, because a pointer could not be read: every body
   * and every blob is sealed under the key of the channel it was sent to, and
   * the destination holds a different one. So the plaintext is re-sealed there
   * and the files are opened here and uploaded again - which is why this takes
   * as long as sending them did the first time.
   *
   * What travels is what the message said, not what happened to it since. The
   * reactions, the pins and the read receipts belong to the original and stay
   * with it; only the tag saying whose words these were comes along.
   */
  forwardMessage: (messageId: string, toChannelId: string) => Promise<void>;
  /**
   * Reports that this account has opened a one-time message, which is what
   * destroys it. Idempotent, and does nothing for the author's own message.
   */
  burnMessage: (messageId: string) => Promise<void>;
  /**
   * The message the composer is answering, per channel, so switching away and
   * back does not silently drop what was being replied to.
   */
  replyingTo: Record<string, MessageReply | null>;
  /** Starts a reply to a message in the open channel, or clears one with null. */
  setReplyTo: (reply: MessageReply | null) => void;
  /** Own message always; anyone else's with DELETE_MESSAGE in that server. */
  deleteMessage: (messageId: string) => Promise<void>;
  /** Rewrites the body of your own message, re-encrypted for the channel. */
  editMessage: (messageId: string, content: string) => Promise<void>;
  /** Pins or unpins, whichever the message is not already. */
  togglePin: (messageId: string) => Promise<void>;
  /** Adds the emoji, or takes it back when it is already yours. */
  react: (messageId: string, emoji: string) => Promise<void>;
  loadPins: () => Promise<void>;
  /** Who else has read the open channel. Cheap, and only for the open one. */
  loadReceipts: (channelId: string) => Promise<void>;
  showPanel: (panel: ChatState['rightPanel']) => void;
  /** Opens the message in the list, wherever the request came from. */
  jumpToMessage: (messageId: string) => void;
  clearJump: () => void;
  /** True when this account may delete a message it did not write. */
  canModerateMessages: () => boolean;
  /** True when this account may pin in the open channel. */
  canPin: () => boolean;
  /** Re-reads the member list of the server on screen. */
  refreshMembers: () => Promise<void>;
  /** Renames a server, sets its icon, or clears it - whatever the change holds. */
  saveServer: (change: UpdateServerRequest) => Promise<void>;
  leaveServer: () => Promise<void>;
  deleteServer: () => Promise<void>;
  /**
   * Adds someone to the server on screen, by the username they can be told.
   *
   * [shareHistory] decides whether they arrive able to read what was said
   * before them. Off by default, which is what the E2EE model does on its own:
   * they hold no earlier channel key and nothing offers them one.
   */
  addMember: (username: string, shareHistory?: boolean) => Promise<void>;
  updateMember: (userId: string, change: UpdateServerMemberRequest) => Promise<void>;
  kickMember: (userId: string) => Promise<void>;
  deleteChannel: (channelId: string) => Promise<void>;
  /** Drops a server from the client after leaving or deleting it. */
  forgetServer: (serverId: string) => void;
  reset: () => void;
}

export const useChatStore = create<ChatState>((set, get) => ({
  view: 'home',
  servers: [],
  channels: [],
  directs: [],
  members: [],
  messages: [],
  activeServerId: null,
  activeChannelId: null,
  unread: {},
  readMarkers: {},
  divider: {},
  history: {},
  loadingMessages: false,
  loadingServer: false,
  cursors: {},
  loadingOlder: false,
  error: null,
  rightPanel: 'none',
  pins: [],
  loadingPins: false,
  jumpTo: null,
  receipts: {},

  loadServers: async () => {
    // What was on screen last time, before anything is asked of the network.
    if (get().servers.length === 0) {
      const cached = await cache.servers().catch(() => null);
      if (cached && get().servers.length === 0) set({ servers: cached });
    }

    const servers = await api.servers();
    set({ servers });
    void cache.putServers(servers).catch(() => undefined);
    // Watch every server, not only the open one: being added to or removed
    // from one has to reach this client wherever it happens to be looking.
    chatSocket.syncServers(servers.map((server) => server.id));
  },

  loadUnread: async () => {
    // Whatever this device last knew, first. The markers decide where the
    // unread line goes, and a channel opened before the network answers used to
    // get no line at all - which is the whole of "the line does not survive a
    // restart": it was a race, not a missing feature.
    const stored = await cache.readMarkers().catch(() => null);
    if (stored && Object.keys(get().readMarkers).length === 0) set({ readMarkers: stored });

    const counts = await api.unread().catch(() => []);
    const unread: Record<string, number> = {};
    const readMarkers: Record<string, string | null> = {};
    for (const entry of counts) {
      if (entry.count > 0) unread[entry.channelId] = entry.count;
      readMarkers[entry.channelId] = entry.lastReadAt;
    }
    set({ readMarkers });
    void cache.putReadMarkers(readMarkers).catch(() => undefined);
    setUnread(unread);
    markersKnown();
  },

  markActiveRead: () => {
    const channelId = get().activeChannelId;
    if (!channelId) return;

    if (get().unread[channelId]) {
      const unread = { ...get().unread };
      delete unread[channelId];
      setUnread(unread);
    }

    // The line and the banner above it go with it, now rather than in five
    // seconds. They are placed when messages arrive at a window nobody is
    // looking at, and coming back to that window is reading them - a bar that
    // says "new messages" over messages already on screen is just wrong, and
    // sitting there for five seconds is long enough to be read as stuck.
    if (get().divider[channelId]) {
      set({ divider: { ...get().divider, [channelId]: null } });
    }

    void api
      .markChannelRead(channelId)
      .then((entry) =>
        set({ readMarkers: { ...get().readMarkers, [channelId]: entry.lastReadAt } }),
      )
      .catch(() => undefined);
  },

  activeChannel: () => {
    const { channels, directs, activeChannelId } = get();
    return [...channels, ...directs].find((channel) => channel.id === activeChannelId);
  },

  showHome: () => set({ view: 'home' }),

  /**
   * Conversations are loaded once at sign-in rather than when the home screen
   * is opened, because a direct message has to be able to arrive and be
   * notified about while the user is somewhere else entirely.
   */
  loadDirects: async () => {
    if (get().directs.length === 0) {
      const cached = await cache.directs().catch(() => null);
      if (cached && get().directs.length === 0) {
        set({ directs: cached.map(toDirectChannel) });
      }
    }

    const rows = await api.directChannels().catch(() => null);
    if (rows === null) return;
    void cache.putDirects(rows).catch(() => undefined);
    const directs = rows.map(toDirectChannel);
    set({ directs });
    chatSocket.syncSubscriptions(subscribable(get().channels, directs));
  },

  openDirectChannel: async (direct) => {
    const channel = toDirectChannel(direct);
    const known = get().directs.some((item) => item.id === channel.id);
    if (!known) set({ directs: [channel, ...get().directs] });
    set({ view: 'home' });
    await get().selectChannel(channel.id);
  },

  selectServer: async (serverId) => {
    set({
      view: 'server',
      activeServerId: serverId,
      channels: [],
      members: [],
      messages: [],
      loadingServer: true,
    });

    // The channel list this server had last time, painted while the fresh one
    // is fetched. A sidebar that appears instantly and corrects itself beats
    // an empty column and a spinner.
    const cachedChannels = await cache.channels(serverId).catch(() => null);
    if (cachedChannels && get().activeServerId === serverId && get().channels.length === 0) {
      set({ channels: cachedChannels });
    }

    // The emoji are needed before the first message renders, and they are a
    // small public list - so they are fetched alongside the channels rather
    // than lazily when a shortcode first appears.
    void loadEmoji(serverId);

    let channels: Channel[];
    let members: ServerMember[];
    try {
      [channels, members] = await Promise.all([
        api.channels(serverId),
        // Members carry the display names presence attaches status to.
        api.members(serverId).catch(() => []),
      ]);
    } finally {
      // In a `finally` because a channel list that failed to arrive must still
      // stop the skeletons: a stuck flag is grey bars for the life of the
      // window, which is a worse lie than the empty state this replaced. Only
      // if this is still the server on screen - a faster switch away has its own
      // fetch in flight and owns the flag now.
      if (get().activeServerId === serverId) set({ loadingServer: false });
    }
    set({ channels, members });
    void cache.putChannels(serverId, channels).catch(() => undefined);

    // Subscribed to every readable channel, not only the open one: a message in
    // another channel has to arrive for it to be counted or notified about.
    chatSocket.syncSubscriptions(subscribable(channels, get().directs));

    const first = channels.find((channel) => channel.type === 'TEXT');
    if (first) await get().selectChannel(first.id);
  },

  selectChannel: async (channelId) => {
    // The markers have to be in hand before the line can be placed at all. On a
    // cold start this is a race the channel used to win: the first channel
    // opens while `loadUnread` is still in flight, so there was no marker to
    // draw from and the line was simply absent until the next visit.
    await whenMarkersKnown();

    // Read before it is advanced: the "new messages" line is drawn from where
    // the marker stood when the channel was opened, and marking it read below
    // is what moves it.
    const previousMarker = get().readMarkers[channelId] ?? null;

    // Opening a channel clears its unread mark here and on the account, so the
    // next window to sign in does not show a badge for something already read.
    if (get().unread[channelId]) {
      const unread = { ...get().unread };
      delete unread[channelId];
      setUnread(unread);
    }
    void api
      .markChannelRead(channelId)
      .then((entry) =>
        set({ readMarkers: { ...get().readMarkers, [channelId]: entry.lastReadAt } }),
      )
      .catch(() => undefined);

    // A voice channel opens its own screen; there is no history to fetch and no
    // message socket to subscribe to.
    if (get().channels.find((channel) => channel.id === channelId)?.type === 'VOICE') {
      set({ activeChannelId: channelId, messages: [], loadingMessages: false, error: null });
      return;
    }

    // Whatever was read before is still true; show it now and refresh behind
    // it, rather than blanking the view for the round trip.
    const cached = get().history[channelId];
    set({
      activeChannelId: channelId,
      messages: cached ?? [],
      loadingMessages: cached === undefined,
      error: null,
      // Pins belong to a channel, so they go with it; the panel reloads them.
      pins: [],
      jumpTo: null,
    });
    chatSocket.subscribe(channelId);
    if (get().rightPanel === 'pins') void get().loadPins();
    // Who has read it, for the "seen by" row. Fetched per open channel rather
    // than for every channel at sign-in: it is only ever drawn for the one on
    // screen, and it goes stale the moment somebody reads anyway.
    void get().loadReceipts(channelId);

    // Nothing in memory: what this device has on disk, decrypted here rather
    // than waiting for the round trip. It is the same fifty messages the fetch
    // below is about to return, and on a slow connection - or none at all -
    // it is the difference between a conversation and a spinner.
    if (cached === undefined) {
      const stored = await cache.messages(channelId).catch(() => []);
      if (stored.length > 0 && get().activeChannelId === channelId) {
        const items = await Promise.all(stored.map(decrypt));
        if (get().activeChannelId === channelId && get().history[channelId] === undefined) {
          set({
            messages: items,
            history: { ...get().history, [channelId]: items },
            loadingMessages: false,
          });
        }
      }
    }

    // Members who joined after this channel was keyed need the key wrapped for
    // them; opening the channel is the natural moment to do it.
    void syncChannelKeys(channelId).catch(() => undefined);

    try {
      const page = await api.messages(channelId);
      void cache.putMessages(page.items).catch(() => undefined);
      const items = await Promise.all(page.items.map(decrypt));

      // Where the line goes: the first message somebody else wrote after this
      // account last read the channel. A channel with no marker at all is one
      // that has never been opened, and starting somebody's first visit with a
      // "new messages" banner across the whole history helps nobody.
      const me = useAuthStore.getState().user?.id;
      const firstUnread = previousMarker
        ? items.find(
            (message) =>
              message.author.id !== me &&
              new Date(message.createdAt).getTime() > new Date(previousMarker).getTime(),
          )
        : undefined;
      // It stays for as long as the channel is open. It used to be taken away
      // five seconds later, which made it a notification rather than a place -
      // and a place is what it is for: the point of the line is to still be
      // there when you have finished reading and want to know what was new.
      // Opening the channel again, with everything read, is what clears it.
      set({ divider: { ...get().divider, [channelId]: firstUnread?.id ?? null } });
      // The cache is written even when the user has already moved on - the
      // fetch was paid for, and the next visit gets it for free.
      set({
        history: { ...get().history, [channelId]: items },
        cursors: { ...get().cursors, [channelId]: page.nextCursor },
      });
      if (get().activeChannelId !== channelId) return;
      set({ messages: items, loadingMessages: false });
    } catch (error) {
      set({ loadingMessages: false, error: (error as Error).message });
    }
  },

  createServer: async (name) => {
    const server = await api.createServer(name);
    set({ servers: [...get().servers, server] });
    await get().selectServer(server.id);
  },

  joinServer: async (code) => {
    const server = await api.joinServer(code);
    const known = get().servers.some((item) => item.id === server.id);
    if (!known) set({ servers: [...get().servers, server] });
    await get().selectServer(server.id);
  },

  createChannel: async ({ name, type = 'TEXT', isPrivate, memberIds }) => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    const channel = await api.createChannel({ serverId, name, type, isPrivate, memberIds });
    set({ channels: [...get().channels, channel] });
    // Mint its key now, while we know we are a member: an unkeyed channel puts
    // the cost on whoever opens it next, and that used to fail for anyone but
    // the creator. A voice channel needs one too - the media key is this key.
    void keyChannel(channel.id).catch(() => undefined);
    // A voice channel is joined, not read, so selection stays where it was.
    if (channel.type === 'TEXT') await get().selectChannel(channel.id);
  },

  replyingTo: {},

  setReplyTo: (reply) => {
    const channelId = get().activeChannelId;
    if (!channelId) return;
    set({ replyingTo: { ...get().replyingTo, [channelId]: reply } });
  },

  loadOlder: async () => {
    const channelId = get().activeChannelId;
    if (!channelId || get().loadingOlder) return;
    const cursor = get().cursors[channelId];
    // Undefined is a channel whose first page has not landed yet; null is one
    // that has been read back to its first message. Neither has a page to ask
    // for, and both would otherwise be asked for on every scroll event.
    if (!cursor) return;

    set({ loadingOlder: true });
    try {
      const page = await api.messages(channelId, cursor);
      void cache.putMessages(page.items).catch(() => undefined);
      const older = await Promise.all(page.items.map(decrypt));

      // Re-read: decryption is async and the channel may have changed. The
      // cursor is still stored either way, so the fetch is not wasted.
      const state = useChatStore.getState();
      const known = new Set((state.history[channelId] ?? []).map((message) => message.id));
      const fresh = older.filter((message) => !known.has(message.id));
      const merged = [...fresh, ...(state.history[channelId] ?? [])];

      set({
        history: { ...state.history, [channelId]: merged },
        cursors: { ...state.cursors, [channelId]: page.nextCursor },
        ...(state.activeChannelId === channelId ? { messages: merged } : {}),
      });
    } catch {
      // Nothing to say: the history on screen is still the history on screen,
      // and an error banner over a scroll gesture is worse than a short list.
    } finally {
      set({ loadingOlder: false });
    }
  },

  sendMessage: async (content, attachments = [], replyTo, viewOnce = false) => {
    const channelId = get().activeChannelId;
    if (!channelId) return;
    // The server stores and forwards ciphertext only - and the attachment
    // manifest is inside it, so the names and types are encrypted too.
    // The pictures for whatever custom emoji the text uses, taken from the
    // server this channel belongs to. They travel inside the envelope so a
    // reader who is not in that server still sees them - see `server-emoji.ts`.
    const emoji = usedEmoji(content, emojiFor(get().activeServerId));

    const envelope = await encryptForChannel(
      channelId,
      encodeBody({
        text: content,
        attachments,
        ...(replyTo ? { replyTo } : {}),
        ...(emoji.length > 0 ? { emoji } : {}),
      }),
    );
    // No optimistic insert: the message arrives over the socket, so an
    // optimistic copy would have to be de-duplicated for no real gain.
    // The keys travel outside the envelope as well as inside it: the server
    // cannot read the manifest, and without them it could never sweep the
    // blobs when this message is deleted.
    await api.sendMessage(
      channelId,
      envelope,
      attachments.map((attachment) => attachment.key),
      viewOnce,
    );
  },

  forwardMessage: async (messageId, toChannelId) => {
    const original = get().messages.find((message) => message.id === messageId);
    if (!original) return;

    const from = original.channelId;
    const carried: MessageAttachment[] = [];
    for (const attachment of original.attachments) {
      const blob = await openAttachment(from, attachment);
      // `openAttachment` may have turned a HEIC into a JPEG on the way out of
      // the cache, so the blob's own type is the truthful one.
      const file = new File([blob], attachment.name, {
        type: blob.type || attachment.contentType,
      });
      carried.push(
        await uploadAttachment(toChannelId, file, undefined, {
          ...(attachment.duration != null
            ? { voice: { duration: attachment.duration, waveform: attachment.waveform ?? [] } }
            : {}),
        }),
      );
    }

    // The pictures the original carried, not the destination's. The text was
    // written somewhere else - possibly in another server entirely - and its
    // shortcodes mean what they meant there. Working them out again from where
    // it is landing would drop exactly the ones the pictures exist to keep
    // readable.
    const emoji = original.emoji ?? [];
    const envelope = await encryptForChannel(
      toChannelId,
      encodeBody({
        text: original.content,
        attachments: carried,
        ...(emoji.length > 0 ? { emoji } : {}),
        forwardedFrom: {
          author: original.author.displayName,
          channel: originName(get(), from),
        },
      }),
    );
    await api.sendMessage(
      toChannelId,
      envelope,
      carried.map((attachment) => attachment.key),
      false,
    );
  },

  /**
   * Records this account's look at a one-time message, which is what spends
   * it. Outside the encrypted envelope, because the server is the one that has
   * to act on it and it cannot read the envelope.
   *
   * Throws on failure, and the viewer waits on it: nothing is drawn until the
   * look is written down. The alternative - draw first, record after - is a
   * message that is one-time only when the request happened to succeed.
   */
  burnMessage: async (messageId) => {
    // Deliberately not swallowed. The viewer waits on this before it draws
    // anything, so a failure has to reach it: a picture shown when the look
    // was never written down is a look spent only when the network happened
    // to be working, which is not one look.
    await api.burnMessage(messageId);
  },

  /**
   * Deleting leaves a tombstone rather than a hole, so nothing is removed from
   * the view here: the `message.updated` event carries the deleted message back
   * with `deletedAt` set, and every client - including this one - draws the
   * same "message deleted" line from it.
   */
  deleteMessage: async (messageId) => {
    await api.deleteMessage(messageId);
  },

  editMessage: async (messageId, content) => {
    const channelId = get().activeChannelId;
    if (!channelId) return;
    // Re-encrypted under the same channel key: the server only ever sees the
    // replacement envelope, exactly as it saw the original.
    const existing = get().messages.find((message) => message.id === messageId);
    const envelope = await encryptForChannel(
      channelId,
      encodeBody({
        text: content,
        attachments: existing?.attachments ?? [],
        // An edit may introduce a shortcode that was not there before, so the
        // manifest is recomputed rather than carried over.
        ...(() => {
          const emoji = usedEmoji(content, emojiFor(get().activeServerId));
          return emoji.length > 0 ? { emoji } : {};
        })(),
        // An edit changes the words. What the message was answering is not one
        // of them, so the quote rides along untouched.
        ...(existing?.replyTo ? { replyTo: existing.replyTo } : {}),
      }),
    );
    await api.editMessage(messageId, envelope);
  },

  togglePin: async (messageId) => {
    const message =
      get().messages.find((item) => item.id === messageId) ??
      get().pins.find((item) => item.id === messageId);
    await (message?.pinnedAt ? api.unpinMessage(messageId) : api.pinMessage(messageId));
    await get().loadPins();
  },

  react: async (messageId, emoji) => {
    await api.reactToMessage(messageId, emoji);
  },

  loadReceipts: async (channelId) => {
    const receipts = await api.channelReads(channelId).catch(() => null);
    if (receipts === null) return;
    set({ receipts: { ...get().receipts, [channelId]: receipts } });
  },

  loadPins: async () => {
    const channelId = get().activeChannelId;
    if (!channelId) {
      set({ pins: [], loadingPins: false });
      return;
    }
    set({ loadingPins: true });
    try {
      const rows = await api.pins(channelId).catch(() => []);
      const pins = await Promise.all(rows.map((message) => decrypt(message)));
      if (get().activeChannelId === channelId) set({ pins });
    } finally {
      // A decryption that threw must still clear the flag, or the panel is grey
      // bars until the channel is changed.
      if (get().activeChannelId === channelId) set({ loadingPins: false });
    }
  },

  showPanel: (panel) => {
    set({ rightPanel: panel });
    if (panel === 'pins') void get().loadPins();
  },

  jumpToMessage: (messageId) => set({ jumpTo: messageId }),
  clearJump: () => set({ jumpTo: null }),

  canModerateMessages: () => {
    const { servers, activeServerId } = get();
    const server = servers.find((item) => item.id === activeServerId);
    return server?.permissions.includes(PERMISSIONS.DELETE_MESSAGE) ?? false;
  },

  /** A direct message has no roles, so both participants may pin in one. */
  canPin: () => {
    const { servers, activeServerId, view } = get();
    if (view === 'home') return true;
    const server = servers.find((item) => item.id === activeServerId);
    return server?.permissions.includes(PERMISSIONS.MANAGE_MESSAGE) ?? false;
  },

  refreshMembers: async () => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    const members = await api.members(serverId).catch(() => null);
    // Re-read: the user may have switched servers while this was in flight.
    if (members && get().activeServerId === serverId) set({ members });
  },

  saveServer: async (change) => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    const updated = await api.updateServer(serverId, change);
    set({
      servers: get().servers.map((server) => (server.id === serverId ? updated : server)),
    });
  },

  /** Leaving or deleting both end with no server on screen, so both go home. */
  leaveServer: async () => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    await api.leaveServer(serverId);
    get().forgetServer(serverId);
  },

  deleteServer: async () => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    await api.deleteServer(serverId);
    get().forgetServer(serverId);
  },

  forgetServer: (serverId) => {
    const servers = get().servers.filter((server) => server.id !== serverId);
    chatSocket.syncServers(servers.map((server) => server.id));
    set({
      servers,
      view: 'home',
      activeServerId: null,
      activeChannelId: null,
      channels: [],
      members: [],
      messages: [],
    });
    chatSocket.syncSubscriptions(subscribable([], get().directs));
  },

  addMember: async (username, shareHistory = false) => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    const member = await api.addMember(serverId, username, shareHistory);
    // Already a member: the list is right as it stands.
    if (get().members.some((item) => item.userId === member.userId)) return;
    set({ members: [...get().members, member] });
  },

  updateMember: async (userId, change) => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    const member = await api.updateMember(serverId, userId, change);
    set({
      members: get().members.map((item) => (item.userId === userId ? member : item)),
    });
  },

  kickMember: async (userId) => {
    const serverId = get().activeServerId;
    if (!serverId) return;
    await api.removeMember(serverId, userId);
    set({ members: get().members.filter((member) => member.userId !== userId) });
  },

  deleteChannel: async (channelId) => {
    await api.deleteChannel(channelId);
    const channels = get().channels.filter((channel) => channel.id !== channelId);
    set({ channels });
    chatSocket.syncSubscriptions(subscribable(channels, get().directs));
    if (get().activeChannelId === channelId) {
      const next = channels.find((channel) => channel.type === 'TEXT');
      if (next) await get().selectChannel(next.id);
      else set({ activeChannelId: null, messages: [] });
    }
  },

  reset: () => {
    setUnread({});
    forgetMarkers();
    forgetEmoji();
    set({
      view: 'home',
      servers: [],
      channels: [],
      directs: [],
      members: [],
      messages: [],
      activeServerId: null,
      activeChannelId: null,
      history: {},
      cursors: {},
      loadingServer: false,
      loadingOlder: false,
      error: null,
      pins: [],
      loadingPins: false,
      jumpTo: null,
      readMarkers: {},
      divider: {},
      replyingTo: {},
      receipts: {},
    });
  },
}));

/**
 * Marks the open channel read, at most once a second.
 *
 * A busy channel would otherwise mean one write per message arriving, and the
 * marker only has to be roughly current - it is a "you have seen up to here",
 * not an audit trail.
 */
/**
 * Resolves once the read markers are in hand.
 *
 * They arrive from `notification-service` a moment after sign-in, and the first
 * channel opens before that - so the unread line was being placed against an
 * empty marker table and came out as "nothing is new". That is not a line that
 * fails to survive a restart; it is a line that loses a race on every cold
 * start. The channel waits for the answer instead, and the cached markers make
 * that wait a disk read rather than a round trip.
 */
let markersKnown: () => void = () => undefined;
let markersReady: Promise<void> = new Promise<void>((resolve) => {
  markersKnown = resolve;
});

function whenMarkersKnown(): Promise<void> {
  return markersReady;
}

/** A new session asks again: the markers belong to whoever just signed in. */
function forgetMarkers(): void {
  markersReady = new Promise<void>((resolve) => {
    markersKnown = resolve;
  });
}

let readTimer: number | null = null;
function markActiveReadSoon(): void {
  if (readTimer !== null) return;
  readTimer = window.setTimeout(() => {
    readTimer = null;
    useChatStore.getState().markActiveRead();
  }, 1000);
}

/**
 * The one place unread counts are written, because two things follow every
 * change: the sidebar dots and the tray tooltip / dock badge.
 */
function setUnread(unread: Record<string, number>): void {
  useChatStore.setState({ unread });
  publishUnreadCount(Object.values(unread).reduce((total, count) => total + count, 0));
}

/**
 * Decrypts one message for display. A deleted message has no body to open -
 * the server emptied it - so it goes straight through as a tombstone.
 */
async function decrypt(message: Message): Promise<DecryptedMessage> {
  if (message.deletedAt) return { ...message, content: '', attachments: [] };
  // The server wrote this one and it has no body to open - what it says is in
  // its kind and its author. Handing an empty string to the channel key would
  // only produce a padlock for a row nobody sealed.
  if (!hasBody(message.kind)) return { ...message, content: '', attachments: [] };
  // A webhook body needs no key and never had one: `decryptForChannel` returns
  // anything that is not an envelope untouched, which is the same path every
  // row written before E2EE already takes. So there is nothing special to do
  // here - only something special *not* to do, which was blanking it above.
  return toDecrypted(message, await decryptForChannel(message.channelId, message.content));
}

/** Splits a decrypted body into the text and the files it carried. */
function toDecrypted(message: Message, plaintext: string): DecryptedMessage {
  // An undecryptable body is a placeholder, not a body - do not try to read
  // an attachment manifest out of it.
  if (plaintext === UNDECRYPTABLE) return { ...message, content: plaintext, attachments: [] };
  const body = decodeBody(plaintext);
  return {
    ...message,
    content: body.text,
    attachments: body.attachments,
    ...(body.replyTo ? { replyTo: body.replyTo } : {}),
    ...(body.emoji ? { emoji: body.emoji } : {}),
    ...(body.forwardedFrom ? { forwardedFrom: body.forwardedFrom } : {}),
  };
}

function notificationText(message: DecryptedMessage): string | null {
  // Somebody arriving is worth a line in the conversation and is not worth a
  // notification: it is not addressed to anybody, and a server that gains ten
  // members is otherwise ten buzzes. A webhook message is not that - it is a
  // build that broke or a disk that filled, which is the reason somebody
  // pointed a webhook at a chat channel in the first place.
  if (!hasBody(message.kind)) return null;
  if (message.content === UNDECRYPTABLE) return null;
  if (message.content.trim()) return message.content;
  return message.attachments.length > 0 ? 'Sent an attachment' : null;
}

/**
 * A direct message is a channel; the client only has to give it the shape the
 * rest of the app already knows, named after the person on the other end.
 */
function toDirectChannel(direct: DirectChannel): Channel {
  return {
    id: direct.channelId,
    serverId: null,
    name: direct.participant.displayName || direct.participant.username,
    type: 'DM',
    topic: null,
    isPrivate: true,
    createdAt: direct.createdAt,
  };
}

/** Channels a message can arrive in - everything except voice. */
function subscribable(channels: Channel[], directs: Channel[]): string[] {
  return [...channels, ...directs]
    .filter((channel) => channel.type !== 'VOICE')
    .map((channel) => channel.id);
}

/**
 * Replaces a message wherever this client is holding it - the open list, the
 * cached history of its channel, and the pinned panel. An edit, a deletion, a
 * pin and a reaction all arrive as the same replacement.
 */
/**
 * Drops the decrypted bytes of these messages' files.
 *
 * The keys come from the copies this store is holding, which is the only place
 * left that knows them: the manifest lives inside the encrypted body, and a
 * message that has been tombstoned or destroyed no longer has one. So this has
 * to run before the store's copy is replaced or removed.
 */
/**
 * What to call the place a forward came from.
 *
 * A channel has a name; a direct message is named after the person on the
 * other end, and naming them is the honest answer to "where did this come
 * from" - the alternative was a blank, which reads as a forward from nowhere.
 */
function originName(state: ChatState, channelId: string): string {
  return (
    [...state.channels, ...state.directs].find((channel) => channel.id === channelId)?.name ?? ''
  );
}

function forgetMessageAttachments(messageIds: string[]): void {
  const state = useChatStore.getState();
  const wanted = new Set(messageIds);
  const keys: string[] = [];
  for (const list of [state.messages, ...Object.values(state.history), state.pins]) {
    for (const message of list) {
      if (wanted.has(message.id)) keys.push(...message.attachments.map((file) => file.key));
    }
  }
  forgetAttachments(keys);
}

/**
 * Messages a viewer is currently open over, and the ones the server destroyed
 * while that was true.
 *
 * Ephemeral screen state rather than store state: nothing renders from it, it
 * does not survive a reload, and putting it in the store would re-render every
 * message list whenever a picture was opened.
 *
 * The problem it solves is a lifecycle one. A one-time message is burned as
 * its viewer opens - deliberately, because closing the viewer is not a promise
 * anybody can keep - and the server answers by destroying the row and saying
 * so. The viewer is drawn inside the message row, so acting on that
 * immediately unmounted the thing the person had just opened. They never saw
 * the picture they had spent their one look on.
 */
const heldOpen = new Set<string>();
const goneWhileOpen = new Set<string>();

/** Keeps a message on screen while its viewer is open, whatever the server says. */
export function holdMessage(messageId: string): void {
  heldOpen.add(messageId);
}

/** Lets it go again, and applies the removal if one arrived in the meantime. */
export function releaseMessage(messageId: string): void {
  heldOpen.delete(messageId);
  if (!goneWhileOpen.delete(messageId)) return;

  forgetMessageAttachments([messageId]);
  void cache.forgetMessages([messageId]).catch(() => undefined);
  forgetMessages(new Set([messageId]));
}

/** Takes messages out of every list this store keeps one in. */
function forgetMessages(messageIds: Set<string>): void {
  if (messageIds.size === 0) return;
  const state = useChatStore.getState();
  const keep = (items: DecryptedMessage[]): DecryptedMessage[] =>
    items.filter((item) => !messageIds.has(item.id));

  useChatStore.setState({
    messages: keep(state.messages),
    pins: keep(state.pins),
    history: Object.fromEntries(
      Object.entries(state.history).map(([channelId, items]) => [channelId, keep(items)]),
    ),
  });
}

/**
 * Drops whatever has outlived a disappearing window - either of them.
 *
 * Two windows, and the client has to enforce both for the same reason: it is
 * holding decrypted copies that no server can reach.
 *
 * The server's window is stamped on each message, and the server destroys
 * those itself and says so - so on a client that has been connected the whole
 * time this half finds nothing. It is for the one that has not: a laptop
 * asleep since yesterday wakes holding messages the server destroyed hours
 * ago, and would keep drawing them until something refetched the channel.
 *
 * This account's own window is never enforced by deletion anywhere, because it
 * is one-sided - the rows are somebody else's history too. The server leaves
 * them out of a history page, and this leaves them out of what is already on
 * screen and on disk. Without this half, switching the setting on hid nothing
 * that had already been fetched.
 */
export function pruneExpired(now = Date.now()): void {
  const state = useChatStore.getState();
  const personal = useAuthStore.getState().user?.messageTtlSeconds ?? null;
  const floor = personal ? now - personal * 1000 : null;

  const expired = new Set<string>();
  for (const list of [state.messages, ...Object.values(state.history), state.pins]) {
    for (const message of list) {
      const gone =
        (message.expiresAt && Date.parse(message.expiresAt) <= now) ||
        (floor !== null && Date.parse(message.createdAt) <= floor);
      if (gone) expired.add(message.id);
    }
  }
  if (expired.size === 0) return;

  forgetMessageAttachments([...expired]);
  void cache.forgetMessages([...expired]).catch(() => undefined);
  forgetMessages(expired);
}

function replaceMessage(message: DecryptedMessage): void {
  const state = useChatStore.getState();
  const swap = (items: DecryptedMessage[]): DecryptedMessage[] =>
    items.map((item) => (item.id === message.id ? message : item));

  const cached = state.history[message.channelId];
  useChatStore.setState({
    ...(cached ? { history: { ...state.history, [message.channelId]: swap(cached) } } : {}),
    messages: swap(state.messages),
    // A message that stopped being pinned - or was deleted - leaves the panel;
    // a newly pinned one is picked up by the reload below.
    pins:
      message.pinnedAt === null
        ? state.pins.filter((item) => item.id !== message.id)
        : swap(state.pins),
  });

  const newlyPinned =
    message.pinnedAt !== null && !state.pins.some((item) => item.id === message.id);
  if (newlyPinned && state.rightPanel === 'pins') void useChatStore.getState().loadPins();
}

/**
 * Repaint one account's face wherever this store is holding a copy of it.
 *
 * Patched rather than refetched because the copies are everywhere: every
 * message that account ever sent in an open channel, every page of history
 * cached behind it, the pins, the read receipts and the member list. Refetching
 * would be five calls to change three fields that arrived in the event.
 *
 * `replyTo.author` is deliberately left alone - it is a snapshot of how the
 * quoted message was signed when the reply was written, not a live reference.
 */
function patchProfile(user: UserSummary): void {
  const state = useChatStore.getState();
  const face = {
    username: user.username,
    displayName: user.displayName,
    avatarUrl: user.avatarUrl,
  };
  const inMessage = (message: DecryptedMessage): DecryptedMessage =>
    message.author.id === user.id ? { ...message, author: { ...message.author, ...face } } : message;
  const mapValues = <T>(record: Record<string, T[]>, map: (item: T) => T): Record<string, T[]> =>
    Object.fromEntries(Object.entries(record).map(([key, list]) => [key, list.map(map)]));

  useChatStore.setState({
    // A member row is the one place the about line is held, so it is patched
    // here and nowhere else - a message author carries a name and a picture
    // and has never carried a sentence about the person.
    members: state.members.map((member) =>
      member.userId === user.id ? { ...member, ...face, about: user.about } : member,
    ),
    messages: state.messages.map(inMessage),
    pins: state.pins.map(inMessage),
    history: mapValues(state.history, inMessage),
    receipts: mapValues(state.receipts, (receipt) =>
      receipt.user.id === user.id ? { ...receipt, user: { ...receipt.user, ...face } } : receipt,
    ),
  });
}

// Realtime events land here regardless of which component is mounted, for
// every subscribed channel - not only the one on screen.
chatSocket.on((event) => {
  if (event.type === 'user.updated') {
    patchProfile(event.user);
    return;
  }

  // A server was renamed or given a new picture. Only the sidebar entry holds
  // either, so this is a patch of one row rather than a reload of the list.
  if (event.type === 'server.updated') {
    const { servers } = useChatStore.getState();
    if (!servers.some((server) => server.id === event.serverId)) return;
    useChatStore.setState({
      servers: servers.map((server) =>
        server.id === event.serverId
          ? { ...server, name: event.name, iconUrl: event.iconUrl }
          : server,
      ),
    });
    return;
  }

  /**
   * This account cleared its own history, here or on another of its devices.
   *
   * Everything on screen and everything on disk goes: the cache holds sealed
   * envelopes the server will no longer hand back, and the open channel holds
   * the decrypted ones. Refetching is what fills both again, and what comes
   * back is whatever arrived after the cut.
   */
  if (event.type === 'chats.cleared') {
    const { activeChannelId } = useChatStore.getState();
    // One conversation leaves the rest of the cache alone: throwing away every
    // other channel's messages would turn "clear this chat" into a spinner on
    // the next four things the person opens.
    void (event.channelId
      ? cache.forgetChannel(event.channelId)
      : cache.clear()
    ).catch(() => undefined);

    const clearedHere = !event.channelId || event.channelId === activeChannelId;
    if (clearedHere) {
      useChatStore.setState({ messages: [], pins: [], divider: {}, receipts: {} });
      if (activeChannelId) void useChatStore.getState().selectChannel(activeChannelId);
    }
    // Whichever it was, the unread counts moved with it: a badge promising
    // messages that can no longer be opened is worse than no badge.
    void useChatStore.getState().loadUnread();
    return;
  }

  if (event.type === 'message.updated') {
    // A deletion arrives here as a tombstone, and a tombstone carries no
    // manifest - the body is empty. So the keys are read off the copy this
    // client is still holding, *before* it is replaced, or the decrypted
    // pictures stay in the attachment cache for the rest of the session with
    // nothing left that names them.
    if (event.message.deletedAt) forgetMessageAttachments([event.message.id]);
    // An edit, a deletion, a pin and a reaction all replace the stored row, so
    // the cache does not hand back a message that was taken down an hour ago.
    void cache.putMessages([event.message]).catch(() => undefined);
    void decrypt(event.message).then(replaceMessage);
    return;
  }

  /**
   * A message that left no tombstone: a one-time message somebody opened, or
   * one whose disappearing window closed.
   *
   * Nothing is drawn in its place, so it is removed rather than replaced -
   * from the view, from the pinned panel, from the on-disk cache, and from the
   * attachment cache holding its decrypted pictures.
   */
  if (event.type === 'message.gone') {
    // Not while somebody is looking at it. Burning happens as the viewer
    // opens, and the viewer is drawn inside the message row - so removing the
    // message here unmounted the row, which unmounted the viewer, which is why
    // a one-time picture vanished the instant it was opened. The removal is
    // held until the viewer closes; see `holdMessage`.
    if (heldOpen.has(event.messageId)) {
      goneWhileOpen.add(event.messageId);
      return;
    }
    forgetMessageAttachments([event.messageId]);
    void cache.forgetMessages([event.messageId]).catch(() => undefined);
    forgetMessages(new Set([event.messageId]));
    return;
  }

  // Somebody read a channel this client is subscribed to. One marker per
  // person, replaced rather than appended: it only ever moves forwards, and
  // keeping the old one would draw a face against a message they have since
  // read past.
  if (event.type === 'channel.read') {
    const self = useAuthStore.getState().user;
    // Your own marker, from another of your devices. It is not a receipt - the
    // row is about who else has seen your message - but it is exactly the
    // moment a notification standing for that conversation should go away:
    // somebody has just answered it at a laptop, and a toast still asking to be
    // looked at is asking twice.
    //
    // Also fires for the marker this window itself just posted, where there is
    // nothing standing and nothing to do. That is the cheap case, and paying
    // for it is better than a rule about which device sent what.
    if (event.userId === self?.id) {
      dismissChannelNotification(event.channelId);
      return;
    }
    const state = useChatStore.getState();
    const known = state.receipts[event.channelId];
    // A channel this client has never opened has no list to patch, and one
    // will be fetched whole when it is opened.
    if (!known) return;
    const existing = known.find((receipt) => receipt.user.id === event.userId);
    if (!existing) {
      // Somebody who had never read this channel before: their name is not on
      // any list here, so the whole thing is re-read rather than invented.
      void useChatStore.getState().loadReceipts(event.channelId);
      return;
    }
    useChatStore.setState({
      receipts: {
        ...state.receipts,
        [event.channelId]: known.map((receipt) =>
          receipt.user.id === event.userId ? { ...receipt, readAt: event.at } : receipt,
        ),
      },
    });
    return;
  }

  // Somebody joined or left a server this client is in. The member list is
  // small and the change is rare, so it is re-read rather than patched from a
  // payload - and the server list too, because this may be the client that was
  // added or removed.
  if (event.type === 'server.members.changed') {
    void (async () => {
      const store = useChatStore.getState();
      await store.loadServers().catch(() => undefined);
      const gone = !useChatStore
        .getState()
        .servers.some((server) => server.id === event.serverId);
      // Removed from the server that is on screen: leave it rather than keep
      // painting channels this account can no longer open.
      if (gone) {
        if (useChatStore.getState().activeServerId === event.serverId) {
          store.forgetServer(event.serverId);
        }
        return;
      }
      if (event.serverId === useChatStore.getState().activeServerId) {
        await store.refreshMembers();
      }
    })();
    return;
  }

  if (event.type !== 'message.created') return;
  const incoming = event.message;
  // Cached whether or not the channel is open: a conversation nobody has looked
  // at this session is exactly the one that should not be a spinner when the
  // badge is finally clicked.
  void cache.putMessages([incoming]).catch(() => undefined);

  void decryptForChannel(incoming.channelId, incoming.content).then((plaintext) => {
    const message = toDecrypted(incoming, plaintext);
    // Re-read: decryption is async, so the channel may have changed meanwhile.
    const state = useChatStore.getState();
    const active = incoming.channelId === state.activeChannelId;
    const self = useAuthStore.getState().user;
    const mine = incoming.author.id === self?.id;

    // Append to the cache as well as the view, so a channel read earlier in
    // the session is up to date when it is opened again.
    const cachedHistory = state.history[incoming.channelId];
    if (cachedHistory && !cachedHistory.some((existing) => existing.id === incoming.id)) {
      useChatStore.setState({
        history: { ...state.history, [incoming.channelId]: [...cachedHistory, message] },
      });
    }

    if (active && !state.messages.some((existing) => existing.id === incoming.id)) {
      useChatStore.setState({ messages: [...state.messages, message] });
    }

    if (mine) return;

    if (!active || !windowIsFocused()) {
      const count = (state.unread[incoming.channelId] ?? 0) + 1;
      setUnread({ ...state.unread, [incoming.channelId]: count });
      // First one to go unread in this channel: that is where the line goes,
      // including for a channel that is open behind an unfocused window.
      if (!state.divider[incoming.channelId]) {
        useChatStore.setState({
          divider: { ...state.divider, [incoming.channelId]: incoming.id },
        });
      }
    } else {
      // Arrived in the channel on screen, in a focused window: it has been
      // read as soon as it is drawn, so move the marker on the account too.
      // Otherwise the next sign-in counts it as unread.
      markActiveReadSoon();
    }

    notifyMessage({
      channelId: incoming.channelId,
      channelName:
        [...state.channels, ...state.directs].find(
          (channel) => channel.id === incoming.channelId,
        )?.name ?? 'a channel',
      author: incoming.author.displayName || incoming.author.username,
      authorId: incoming.author.id,
      // A message this device cannot read still deserves a notification, just
      // without quoting the placeholder into it. Nor is a file's name quoted:
      // the notification goes to the OS, which is outside the encrypted path.
      text: notificationText(message),
      active,
      // Decided here because this is where the plaintext exists at all: the
      // services see ciphertext, so "was I mentioned" is not a question any of
      // them could answer.
      mentioned: mentionsMe(notificationText(message), {
        username: self?.username ?? '',
        displayName: self?.displayName,
      }),
    });
  });
});

/**
 * Friends and direct message conversations - everything behind the home button
 * on the server rail.
 */
import { create } from 'zustand';
import type { BlockedUser, DirectChannel, Friend, UserSummary } from '@betweenus/shared-types';
import { api } from '../services/api';
import { chatSocket } from '../services/socket';
import { useAuthStore } from './auth';
import { useChatStore } from './chat';

interface FriendsState {
  friends: Friend[];
  directChannels: DirectChannel[];
  /** Everyone this account has blocked. Loaded with the friend list. */
  blocked: BlockedUser[];
  searchResults: UserSummary[];
  loading: boolean;
  error: string | null;

  load: () => Promise<void>;
  search: (query: string) => Promise<void>;
  clearSearch: () => void;
  add: (username: string) => Promise<void>;
  accept: (userId: string) => Promise<void>;
  remove: (userId: string) => Promise<void>;
  /** Blocks somebody: the friendship ends and the conversation closes. */
  block: (userId: string) => Promise<void>;
  unblock: (userId: string) => Promise<void>;
  /** Opens (or reopens) the conversation and puts it on screen. */
  openDirect: (userId: string) => Promise<void>;
  reset: () => void;
}

export const useFriendsStore = create<FriendsState>((set, get) => ({
  friends: [],
  directChannels: [],
  blocked: [],
  searchResults: [],
  loading: false,
  error: null,

  load: async () => {
    set({ loading: true, error: null });
    try {
      const [friends, directChannels, blocked] = await Promise.all([
        api.friends(),
        api.directChannels(),
        // A deployment that has not been migrated yet answers 404 here, and a
        // missing block list is not a reason for the friends screen to fail.
        api.blocked().catch(() => [] as BlockedUser[]),
      ]);
      set({ friends, directChannels, blocked, loading: false });
    } catch (error) {
      set({ loading: false, error: message(error) });
    }
  },

  search: async (query) => {
    const trimmed = query.trim();
    if (trimmed.length < 2) {
      set({ searchResults: [] });
      return;
    }
    try {
      set({ searchResults: await api.searchUsers(trimmed) });
    } catch (error) {
      set({ error: message(error) });
    }
  },

  clearSearch: () => set({ searchResults: [] }),

  add: async (username) => {
    set({ error: null });
    try {
      const friend = await api.addFriend(username);
      set({ friends: upsert(get().friends, friend) });
    } catch (error) {
      if (useAuthStore.getState().status === 'authenticated') {
        set({ error: message(error) });
      }
      throw error;
    }
  },

  accept: async (userId) => {
    const friend = await api.acceptFriend(userId);
    set({ friends: upsert(get().friends, friend) });
  },

  remove: async (userId) => {
    await api.removeFriend(userId);
    set({ friends: get().friends.filter((friend) => friend.user.id !== userId) });
  },

  block: async (userId) => {
    const entry = await api.blockUser(userId);
    // The friendship went with it on the server, and the conversation is closed
    // for both sides - so it leaves the two lists here as well rather than
    // waiting for the reload the announcement will trigger.
    set({
      blocked: [entry, ...get().blocked.filter((item) => item.user.id !== userId)],
      friends: get().friends.filter((friend) => friend.user.id !== userId),
      directChannels: get().directChannels.filter(
        (channel) => channel.participant.id !== userId,
      ),
      searchResults: get().searchResults.filter((person) => person.id !== userId),
    });
  },

  unblock: async (userId) => {
    await api.unblockUser(userId);
    set({ blocked: get().blocked.filter((item) => item.user.id !== userId) });
    // The conversation is open again and its channel was hidden while it was
    // not, so the list is re-read rather than reconstructed from memory.
    await get().load();
  },

  openDirect: async (userId) => {
    const channel = await api.openDirectChannel(userId);
    const known = get().directChannels.some((item) => item.channelId === channel.channelId);
    if (!known) set({ directChannels: [channel, ...get().directChannels] });
    await useChatStore.getState().openDirectChannel(channel);
  },

  reset: () =>
    set({ friends: [], directChannels: [], blocked: [], searchResults: [], error: null }),
}));

/**
 * A request, an acceptance, a removal or a new conversation on the other side:
 * the server says only that something changed, and both lists are re-read. They
 * are one call each and rarely change, so a payload per recipient would buy
 * nothing - see the note on `ServerChatEvent`.
 */
chatSocket.on((event) => {
  if (event.type === 'friends.changed') {
    void useFriendsStore.getState().load();
    void useChatStore.getState().loadDirects();
    return;
  }

  // A friend changed their picture or their name. Both lists name them, and
  // the conversation list is the one on screen while it happens.
  if (event.type === 'user.updated') {
    const { friends, directChannels, searchResults } = useFriendsStore.getState();
    const same = (person: UserSummary): UserSummary =>
      person.id === event.user.id ? event.user : person;
    useFriendsStore.setState({
      friends: friends.map((friend) => ({ ...friend, user: same(friend.user) })),
      directChannels: directChannels.map((direct) => ({
        ...direct,
        participant: same(direct.participant),
      })),
      searchResults: searchResults.map(same),
    });
  }
});

function upsert(friends: Friend[], incoming: Friend): Friend[] {
  const without = friends.filter((friend) => friend.user.id !== incoming.user.id);
  return [incoming, ...without];
}

function message(error: unknown): string {
  return error instanceof Error ? error.message : 'Something went wrong';
}

/**
 * Play Together: one board, two chairs, and everybody else watching.
 *
 * There is almost nothing in this store, and that is the design. The gateway
 * is the referee - it holds the board, applies the rules and says what came of
 * a move - so this keeps what it was last told and sends what was clicked. No
 * optimistic move is applied locally, deliberately: a board that showed a move
 * before it was refereed would show a different game to the person who made it
 * for as long as the round trip takes, and "my disc was there a second ago" is
 * the one thing a shared board must never do.
 *
 * What it does own is which panel is on the screen, which is local for the
 * same reason the listening panel's is: somebody folding the board away to
 * read a channel is not asking the other player to stop playing.
 */
import { create } from 'zustand';
import type { GameId, GameSession } from '@betweenus/shared-types';
import type { Mesh } from '../services/mesh';
import { canPlayMove, seatFor, turnLineFor } from '../services/game-view';
import { useAuthStore } from './auth';
import { useListenStore } from './listen';

interface GameState {
  /** What the call is playing, as the gateway last said. Null for nothing. */
  session: GameSession | null;
  /**
   * Whether the games panel has the voice stage.
   *
   * Local, and with a single render site in `VoiceChannelView` - the same rule
   * the listening panel learned the hard way, because `VoiceControls` is drawn
   * twice and a flag it drew from would draw two live panels side by side.
   */
  open: boolean;
  /**
   * Whether the board has the whole window.
   *
   * Local, like `open`, and for the same reason: how big a board is on one
   * person's screen is not a thing the other player is entitled to decide.
   * Carrom in particular wants the room - the coins are a fiftieth of the board
   * across, and a board sharing a stage with a seat rail and a row of faces is
   * a board where the difference between a thin cut and a miss is four pixels.
   */
  fullscreen: boolean;

  attach: (mesh: Mesh) => void;
  detach: () => void;
  receive: (session: GameSession | null) => void;

  setOpen: (open: boolean) => void;
  setFullscreen: (fullscreen: boolean) => void;
  /** Put a game on the table. Whoever does it takes the first chair. */
  openGame: (gameId: GameId) => void;
  sit: (seat: number) => void;
  stand: () => void;
  move: (move: number, params?: number[]) => void;
  rematch: () => void;
  close: () => void;
}

let mesh: Mesh | null = null;

export const useGameStore = create<GameState>((set, get) => ({
  session: null,
  open: false,
  fullscreen: false,

  attach: (next) => {
    mesh = next;
  },

  detach: () => {
    mesh = null;
    set({ session: null, open: false, fullscreen: false });
  },

  receive: (session) => {
    const previous = get().session;
    // The gateway numbers every change, so this client's echo of a state it has
    // already applied cannot undo a later one somebody else caused. Two people
    // moving within a second of each other is the ordinary case here, not an
    // edge: one of them is always answering the other.
    if (session && previous && session.rev <= previous.rev) return;
    set({ session });
  },

  setOpen: (open) => {
    // One stage, one thing on it. The listening panel and the board are both
    // full-width takeovers of the call, so opening either closes the other -
    // and a native browser view painting over a board would be the worse half
    // of that failure. The music itself carries on; only the panel folds away.
    if (open) useListenStore.getState().setOpen(false);
    // Closing the panel drops fullscreen with it. A hidden panel that is still
    // "fullscreen" is a flag waiting to swallow the window the next time
    // somebody opens a game.
    set(open ? { open } : { open, fullscreen: false });
  },

  setFullscreen: (fullscreen) => set({ fullscreen }),

  openGame: (gameId) => mesh?.sendGame({ type: 'game.open', gameId }),
  sit: (seat) => mesh?.sendGame({ type: 'game.sit', seat }),
  stand: () => mesh?.sendGame({ type: 'game.sit', seat: -1 }),
  move: (move, params) => mesh?.sendGame({ type: 'game.move', move, params }),
  rematch: () => mesh?.sendGame({ type: 'game.rematch' }),
  close: () => mesh?.sendGame({ type: 'game.close' }),
}));

/**
 * The same three questions as `services/game-view.ts`, asked about whoever is
 * signed in here. The arithmetic is there; this is the binding to this window.
 */
export function mySeat(session: GameSession | null): number {
  return seatFor(session, useAuthStore.getState().user?.id ?? null);
}

export function canPlay(session: GameSession | null, move: number): boolean {
  return canPlayMove(session, useAuthStore.getState().user?.id ?? null, move);
}

export function turnLine(session: GameSession | null): string {
  return turnLineFor(session, useAuthStore.getState().user?.id ?? null);
}

import { create } from 'zustand';

/**
 * Where this machine stands on encryption keys, for the parts of the UI that
 * have to say something about it.
 *
 *  - `absent`  nobody is signed in yet
 *  - `ready`   the identity is loaded; `backedUp` says whether *this machine's*
 *              key is the one in the account backup, which is the difference
 *              between "portable account" and "one machine away from
 *              unreadable history". `provisional` says this machine minted its
 *              own key because it could not open the account's - so it reads
 *              what arrives from now on, and history is still sealed to an
 *              identity it does not hold
 *  - `revoked` the owner revoked this machine from another one. Nothing new is
 *              wrapped for it, so it can read what it already had and nothing
 *              since; saying so beats a screen of "no key on this device yet"
 *
 * There is no `locked`. A machine that cannot open the account backup mints a
 * key of its own and signs in anyway - see `services/e2ee.ts` - so there is no
 * state in which the app is signed in and waiting to be told a secret. That
 * fork used to be permanent; it is `provisional` now, and every later sign-in
 * with a secret that opens the backup undoes it.
 */
export type IdentityStatus =
  | { status: 'absent' }
  | { status: 'ready'; backedUp: boolean; provisional?: boolean }
  | { status: 'revoked' };

interface IdentityState {
  identity: IdentityStatus;
  setIdentityStatus: (next: IdentityStatus) => void;
}

export const useIdentityStore = create<IdentityState>((set) => ({
  identity: { status: 'absent' },
  setIdentityStatus: (next) => set({ identity: next }),
}));

export function setIdentityStatus(next: IdentityStatus): void {
  useIdentityStore.getState().setIdentityStatus(next);
}

/**
 * Listen Together: one shared queue, one position, one player per window.
 *
 * The difference between this and sharing a browser tab with the sound on is
 * the whole reason it exists. A share is media: one upload per listener, the
 * music squeezed through a codec meant for speech, everybody hearing whatever
 * survived the trip, and the person sharing unable to alt-tab away from it.
 * Here nothing is uploaded at all. Each window streams the track itself, at
 * full quality, from the provider; what the call agrees on is a queue and a
 * number. That is a few hundred bytes when somebody presses a button, and
 * nothing at all in between.
 *
 * It is also why anybody can drive it. There is no host, because a host is a
 * person who eventually leaves and takes the music with them - the queue is a
 * thing the room built, and it belongs to the room.
 *
 * This store is the reconciler. The gateway says what should be happening; the
 * player says what is happening; and about five times a minute this compares
 * them and does the smallest thing that closes the gap. Everything harder than
 * that is somewhere else: the arithmetic is `listen-sync.ts`, the player is
 * `youtube.ts`, and the ordering is the gateway's.
 */
import { create } from 'zustand';
import { listenPositionAt, type ListenSession, type ListenTrack } from '@betweenus/shared-types';
import type { Mesh } from '../services/mesh';
import {
  CLOCK_SAMPLE_MS,
  DRIFT_CHECK_MS,
  ServerClock,
  correction,
  type ClockSample,
} from '../services/listen-sync';
import { YouTubePlayer, parseYouTube } from '../services/youtube';
import { useVoiceStore } from './voice';
import { useGameStore } from './game';

/**
 * How loud the music is while somebody is talking, as a fraction of the volume
 * that was set.
 *
 * This is the bit that makes it "working together" rather than "watching a
 * film". Two people with music on and a microphone open either shout over it or
 * turn it down by hand every time one of them starts a sentence, and the second
 * of those is what everybody actually does until they give up and mute. Pulling
 * it down automatically is what a person would do, done in eighty milliseconds.
 */
const DUCK = 0.25;

/**
 * How long the music stays down after the last word.
 *
 * Speech is not continuous - there is a gap between "so" and "the thing is" -
 * and a duck that recovers instantly pumps the volume up and down through every
 * sentence, which is far more distracting than the music was.
 */
const DUCK_HOLD_MS = 900;

/** Steps the volume takes on the way down and back, for a fade rather than a jump. */
const DUCK_FADE_STEPS = 6;
const DUCK_FADE_MS = 80;

interface ListenState {
  /** What the call is listening to, as the gateway last said. Null for nothing. */
  session: ListenSession | null;
  /**
   * Whether the Listen Together panel has the stage.
   *
   * Local: it is a view, not a shared decision. Somebody who folds the video
   * away to read something is not asking the rest of the call to stop watching.
   *
   * It is a single flag with a *single* render site, and that is the fix for a
   * real bug rather than a preference. The panel used to be a popover hung off
   * `VoiceControls` - which is rendered twice, once in the sidebar and once in
   * the channel view - so one flag drew two panels, side by side, both live.
   * A piece of shared state may only be drawn once.
   */
  open: boolean;
  /**
   * Which half of the panel is showing.
   *
   * `browse` is the real youtube.com and is the default, because looking for
   * something to play is what somebody opening this is doing. `playing` is the
   * video everybody is watching. They are tabs rather than two panels because
   * only one of them can have the space, and because a native browser view and
   * an embedded player must never be on screen at the same time - see
   * `ListenBrowser` on why a `WebContentsView` paints over everything.
   */
  tab: 'browse' | 'playing';
  /**
   * This window's own volume, 0-100, and nobody else's business.
   *
   * Shared transport, local volume: what is playing is a thing two people agree
   * on, how loud it is in one person's headphones is not.
   */
  volume: number;
  /** True while the music is turned down under somebody talking. */
  ducking: boolean;
  /**
   * How far this machine's clock is behind the gateway's, in milliseconds.
   *
   * In the store only so the seek bar can draw a position between messages.
   * The reconciler reads the clock itself.
   */
  clockOffset: number;
  /**
   * The browser refused to start the audio without a gesture, so a button has
   * to be pressed in this window before anything is heard.
   *
   * Only ever true for the person who did *not* start the track: their window
   * had no click in it, and an embedded player that is told to start playing
   * audio out of nowhere is exactly what autoplay policy exists to stop. Saying
   * so is the whole fix - the alternative is a session that looks like it is
   * playing and is silent, with nothing on screen to explain it.
   */
  needsGesture: boolean;
  error: string | null;

  attach: (mesh: Mesh) => void;
  detach: () => void;
  receive: (session: ListenSession | null) => void;
  sampleClock: (sample: ClockSample) => void;

  setOpen: (open: boolean) => void;
  setTab: (tab: 'browse' | 'playing') => void;
  setVolume: (volume: number) => void;
  /**
    * A pasted link or a bare id. Returns what went wrong, or null.
    *
    * `playNow` jumps to it as well, which is what pressing a video in the
    * browser means - the queue is where a second choice goes, not the first.
    */
  add: (input: string, playNow?: boolean) => string | null;
  remove: (trackId: string) => void;
  playPause: () => void;
  playIndex: (index: number) => void;
  skip: (delta: number) => void;
  seek: (positionMs: number) => void;
  stop: () => void;
  /** The click that lets a blocked player start. */
  allow: () => void;
}

/** The live pieces, outside the store: React must not re-render on a player tick. */
let mesh: Mesh | null = null;
let player: YouTubePlayer | null = null;
/** Which track the current player was built for, so it is rebuilt only on a change. */
let loadedTrackId: string | null = null;
/**
 * Where the player's frame lives: one element on `document.body`, always, that
 * is *moved over* whatever slot the UI is currently offering it.
 *
 * This is the shape the feature needs and the first version got wrong. An
 * iframe removed from the document stops playing and loses its position, so a
 * frame rendered inside a React component dies every time that component
 * unmounts - closing the panel, switching to a text channel, paging the grid.
 * Re-mounting it is not a fix either: a fresh frame is a fresh player, back at
 * zero, refused autoplay, and out of step with everybody.
 *
 * So the frame never moves in the DOM. A component claims the slot by handing
 * over its own element, and this positions the frame on top of it - `fixed`,
 * tracking that element's rectangle. When nothing claims it, the frame shrinks
 * into a corner and keeps playing, which is what "the music carries on while
 * you go and read something" has to mean.
 */
let host: HTMLDivElement | null = null;
/** The element the picture is currently drawn over, if any. */
let slot: HTMLElement | null = null;
let slotObserver: ResizeObserver | null = null;
let followFrame: number | null = null;

function playerHost(): HTMLDivElement {
  if (host) return host;
  host = document.createElement('div');
  host.style.cssText =
    'position:fixed;top:-9999px;left:-9999px;width:320px;height:180px;pointer-events:none;overflow:hidden;background:#000;border-radius:0.5rem;';
  document.body.append(host);
  follow();
  return host;
}

/**
 * Puts the frame where the claimed slot is, or parks it when there is none.
 *
 * Parked is positioned off-screen with valid video dimensions (320x180) rather
 * than 1px x 1px with zero opacity: Chromium treats 1px or zero-opacity
 * cross-origin iframes as invisible/dead, throttling their message loops,
 * background JS execution, and blocking audio/video playback.
 */
function follow(): void {
  if (!host) return;
  if (!slot || !slot.isConnected) {
    host.style.cssText =
      'position:fixed;top:-9999px;left:-9999px;width:320px;height:180px;pointer-events:none;overflow:hidden;';
    return;
  }
  const box = slot.getBoundingClientRect();
  host.style.cssText =
    'position:fixed;z-index:20;overflow:hidden;background:#000;border-radius:0.5rem;' +
    `left:${box.left}px;top:${box.top}px;width:${box.width}px;height:${box.height}px;`;
}

/**
 * A component offering the picture somewhere to be, or `null` on its way out.
 *
 * Followed on a frame loop rather than only on resize, because the rectangle
 * moves for reasons no observer reports: a sidebar opening, a banner appearing
 * above it, the window being dragged between monitors. One `getBoundingClientRect`
 * a frame is nothing next to the video it is positioning.
 */
export function claimListenSlot(element: HTMLElement | null): void {
  slot = element;
  slotObserver?.disconnect();
  slotObserver = null;
  if (followFrame !== null) cancelAnimationFrame(followFrame);
  followFrame = null;

  playerHost();
  follow();
  if (!element) return;

  slotObserver = new ResizeObserver(() => follow());
  slotObserver.observe(element);
  const tick = (): void => {
    follow();
    followFrame = requestAnimationFrame(tick);
  };
  followFrame = requestAnimationFrame(tick);
}
const clock = new ServerClock();
let driftTimer: number | null = null;
let clockTimer: number | null = null;
let duckTimer: number | null = null;
let fadeTimer: number | null = null;
let lastHeardAt = 0;
let unsubscribeVoice: (() => void) | null = null;
/**
 * Tracks whose end this window has already reported.
 *
 * The player sits at the end of a finished track saying "ended" until it is
 * told otherwise, so without this the same `ended` is sent five times a second
 * until the gateway's answer arrives. The gateway ignores the repeats, but a
 * client that shouts is a client that will shout at something else later.
 */
const reportedEnd = new Set<string>();
/** Tracks this window has already described, for the same reason. */
const reportedMeta = new Set<string>();

function currentTrack(session: ListenSession | null): ListenTrack | null {
  if (!session) return null;
  return session.queue[session.index] ?? null;
}

export const useListenStore = create<ListenState>((set, get) => ({
  session: null,
  open: false,
  volume: 60,
  tab: 'browse',
  ducking: false,
  clockOffset: 0,
  needsGesture: false,
  error: null,

  attach: (next) => {
    mesh = next;
    // Measured from the moment there is a socket rather than when a track is
    // added: the first sample is the least accurate one, and a session that
    // starts with eight of them behind it starts in step.
    next.sampleServerTime();
    clockTimer = window.setInterval(() => mesh?.sampleServerTime(), CLOCK_SAMPLE_MS);
    driftTimer = window.setInterval(() => reconcile(), DRIFT_CHECK_MS);

    // Ducking rides on the speaking detection the call already does, which is
    // measured from the audio itself rather than from whether a microphone is
    // open - so a muted person with a noisy room does not turn the music down.
    unsubscribeVoice = useVoiceStore.subscribe((state) => {
      if (state.tiles.some((tile) => tile.speaking)) lastHeardAt = Date.now();
    });
    duckTimer = window.setInterval(() => applyDuck(), 100);
  },

  detach: () => {
    mesh = null;
    for (const timer of [clockTimer, driftTimer, duckTimer, fadeTimer]) {
      if (timer !== null) window.clearInterval(timer);
    }
    clockTimer = driftTimer = duckTimer = fadeTimer = null;
    unsubscribeVoice?.();
    unsubscribeVoice = null;
    teardownPlayer();
    claimListenSlot(null);
    // Destroyed rather than hidden, here and only here: the sign-in is worth
    // keeping across a collapsed panel and is not worth keeping across a call
    // nobody is in.
    void window.betweenus?.youtubeClose?.();
    host?.remove();
    host = null;
    reportedEnd.clear();
    reportedMeta.clear();
    set({
      session: null,
      open: false,
      tab: 'browse',
      ducking: false,
      clockOffset: 0,
      needsGesture: false,
      error: null,
    });
  },

  receive: (session) => {
    const previous = get().session;
    // The gateway numbers every change, so this client's own echo of a state it
    // has already applied cannot undo a later one somebody else caused. Out of
    // order is not hypothetical: two people pressing skip within a second of
    // each other is the ordinary case this feature is for.
    if (session && previous && session.rev <= previous.rev) return;
    set({ session, error: null });
    if (!session) {
      teardownPlayer();
      set({ needsGesture: false });
      return;
    }
    reconcile();
  },

  sampleClock: (sample) => {
    clock.sample(sample);
    const offset = clock.offset();
    // Only when it has actually moved: this fires every fifteen seconds and a
    // set() that changes nothing still wakes every subscriber.
    if (offset !== get().clockOffset) set({ clockOffset: offset });
  },

  setOpen: (open) => {
    // The stage holds one thing. Opening this folds the games panel away, and
    // opening that folds this one - decided in the stores rather than in the
    // view, because the button exists twice and the rule must not.
    if (open) {
      useGameStore.getState().setOpen(false);
      if (get().session) set({ tab: 'playing' });
    }
    set({ open });
  },
  setTab: (tab) => set({ tab }),

  setVolume: (volume) => {
    set({ volume: Math.min(100, Math.max(0, Math.round(volume))) });
    applyDuck(true);
  },

  add: (input, playNow = false) => {
    const ref = parseYouTube(input);
    if (!ref) return 'That does not look like a YouTube link.';
    mesh?.sendListen({ type: 'listen.add', provider: 'youtube', ref, playNow });
    set({ error: null });
    // Stay on the browser. Adding a second track while looking for a third is
    // the normal case, and throwing somebody back to the player every time they
    // press add is the thing that makes queueing four songs annoying.
    // The click that added a track is a gesture in *this* window, which is what
    // lets its player start. Everybody else's window may still need one.
    set({ needsGesture: false });
    return null;
  },

  remove: (trackId) => mesh?.sendListen({ type: 'listen.remove', trackId }),

  playPause: () => {
    const session = get().session;
    if (!session) return;
    if (session.paused) {
      mesh?.sendListen({ type: 'listen.play' });
      return;
    }
    // The position goes with the pause, taken from this window's own player
    // rather than from the shared clock: the player is the thing that actually
    // stopped, and it stopped where it stopped.
    mesh?.sendListen({
      type: 'listen.pause',
      positionMs: player?.current().positionMs ?? listenPositionAt(session, clock.now()),
    });
  },

  playIndex: (index) => mesh?.sendListen({ type: 'listen.play', index }),
  skip: (delta) => mesh?.sendListen({ type: 'listen.skip', delta }),
  seek: (positionMs) => mesh?.sendListen({ type: 'listen.seek', positionMs: Math.round(positionMs) }),
  stop: () => mesh?.sendListen({ type: 'listen.stop' }),

  allow: () => {
    set({ needsGesture: false });
    player?.play();
    reconcile();
  },
}));

/**
 * Makes this window's player look like what the call says is happening.
 *
 * Called on every state change and on a timer, and it is deliberately the same
 * code both times: a correction that only runs on a message would never fix
 * drift, which accumulates while nothing is being sent, and one that only runs
 * on a timer would take five seconds to notice somebody pressed pause.
 */
function reconcile(): void {
  const store = useListenStore.getState();
  const session = store.session;
  const track = currentTrack(session);
  if (!session || !track) {
    teardownPlayer();
    return;
  }

  // A different track means a different video, and the embed loads one video.
  // Rebuilt rather than told to load another, because a frame that has already
  // been refused autoplay stays refused, and a fresh one gets a fresh answer.
  if (loadedTrackId !== track.id) {
    teardownPlayer();
    loadedTrackId = track.id;
    player = new YouTubePlayer(track.ref, (state) => onPlayerState(state));
    playerHost().append(player.frame);
    applyDuck(true);
    // Nothing else here: the player has not loaded, so telling it to seek is
    // telling nobody. The next tick, or its first state message, does it.
    return;
  }
  if (!player) return;

  const actual = player.current();
  if (session.paused && actual.playing) player.pause();
  if (!session.paused && !actual.playing && !actual.ended) player.play();

  const seekTo = correction(session, clock.now(), actual.positionMs);
  if (seekTo !== null) player.seek(seekTo);
}

/** What the embed says about itself, turned into what the call needs to know. */
function onPlayerState(state: ReturnType<YouTubePlayer['current']>): void {
  const store = useListenStore.getState();
  const session = store.session;
  const track = currentTrack(session);
  if (!session || !track) return;

  // The title and the length: a pasted link carries neither, and a player that
  // has loaded the video knows both. First window to say so fills them in for
  // everybody, and nothing on the server ever has to ask YouTube anything.
  if (!reportedMeta.has(track.id) && (state.title || state.durationMs > 0)) {
    if (!track.title || track.durationMs === 0) {
      reportedMeta.add(track.id);
      mesh?.sendListen({
        type: 'listen.meta',
        trackId: track.id,
        title: state.title ?? undefined,
        durationMs: state.durationMs || undefined,
      });
    }
  }

  if (state.ended && !reportedEnd.has(track.id)) {
    reportedEnd.add(track.id);
    // Every window sends this; the gateway advances once, because the second
    // and third arrivals are about a track that is no longer current.
    mesh?.sendListen({ type: 'listen.ended', trackId: track.id });
    return;
  }

  if (state.error) {
    let errorText = 'This video is unavailable for embedding on third-party sites.';
    if (state.error === 101 || state.error === 150) {
      errorText = 'The video owner does not allow embedding on third-party sites.';
    } else if (state.error === 2) {
      errorText = 'Invalid YouTube video link or ID.';
    } else if (state.error === 5) {
      errorText = 'HTML5 playback error on this video.';
    }
    if (store.error !== errorText) useListenStore.setState({ error: errorText });
  } else if (state.playing && store.error) {
    useListenStore.setState({ error: null });
  }

  // Told to play, loaded, and not playing: the browser refused. Nothing here
  // can fix that - a gesture in this window can, and saying so is the only
  // honest thing to put on screen.
  if (!session.paused && !state.playing && !state.ended && state.durationMs > 0 && !state.error) {
    if (!store.needsGesture) useListenStore.setState({ needsGesture: true });
  } else if (store.needsGesture && state.playing) {
    useListenStore.setState({ needsGesture: false });
  }
}

/**
 * Moves the volume towards where it should be: down while somebody is talking,
 * back up once they have stopped for long enough to have meant it.
 *
 * Faded rather than switched, because a volume that steps is more noticeable
 * than the music it was hiding. `immediate` is the volume slider, which is a
 * person asking for a change and should not have to wait half a second for it.
 */
function applyDuck(immediate = false): void {
  if (!player) return;
  const { volume, ducking } = useListenStore.getState();
  const talking = Date.now() - lastHeardAt < DUCK_HOLD_MS;
  const target = Math.round(volume * (talking ? DUCK : 1));

  if (talking !== ducking) useListenStore.setState({ ducking: talking });

  if (immediate) {
    if (fadeTimer !== null) window.clearInterval(fadeTimer);
    fadeTimer = null;
    player.setVolume(target);
    fadeFrom = target;
    return;
  }
  if (fadeFrom === target || fadeTimer !== null) return;

  const from = fadeFrom;
  const step = (target - from) / DUCK_FADE_STEPS;
  let taken = 0;
  fadeTimer = window.setInterval(() => {
    taken += 1;
    fadeFrom = taken >= DUCK_FADE_STEPS ? target : Math.round(from + step * taken);
    player?.setVolume(fadeFrom);
    if (taken >= DUCK_FADE_STEPS && fadeTimer !== null) {
      window.clearInterval(fadeTimer);
      fadeTimer = null;
    }
  }, DUCK_FADE_MS);
}

/** Where the fade currently is, so a second one starts from the truth. */
let fadeFrom = 60;

function teardownPlayer(): void {
  player?.close();
  player = null;
  loadedTrackId = null;
  if (useListenStore.getState().error) useListenStore.setState({ error: null });
}

/**
 * Self-check for per-person volume: `tsx src/stores/peerAudio.check.ts`.
 *
 * The arithmetic is one clamp, and the part worth pinning down is what it does
 * at the edges - a muted person is silent whatever their slider says, and a
 * person nobody has touched is exactly as loud as they arrived.
 */
import assert from 'node:assert/strict';
import { DEFAULT_PEER_AUDIO, elementVolume, isDefault } from './peerAudio';

// Nobody has touched them: full volume, and no entry worth storing.
assert.equal(elementVolume(undefined), 1);
assert.equal(isDefault(DEFAULT_PEER_AUDIO), true);

// The slider.
assert.equal(elementVolume({ volume: 0.5, muted: false }), 0.5);
assert.equal(elementVolume({ volume: 0, muted: false }), 0);

// Mute wins over the slider in both directions, so unmuting cannot arrive
// silent and muting cannot be undone by dragging.
assert.equal(elementVolume({ volume: 1, muted: true }), 0);
assert.equal(elementVolume({ volume: 0.3, muted: true }), 0);

// Nonsense from an older profile or a hand-edited store is clamped rather than
// handed to the element, which throws on anything outside 0..1.
assert.equal(elementVolume({ volume: 4, muted: false }), 1);
assert.equal(elementVolume({ volume: -2, muted: false }), 0);
assert.equal(elementVolume({ volume: Number.NaN, muted: false }), 0);

// Anything that is not the default is worth storing; the default is not.
assert.equal(isDefault({ volume: 1, muted: true }), false);
assert.equal(isDefault({ volume: 0.9, muted: false }), false);

console.log('peer-audio check ok');

/**
 * How loud each other person is, on this machine.
 *
 * The other half of what an audio settings screen is for. Input settings decide
 * how you sound; this decides how everyone else does - the person whose gain is
 * set too high, the one on a laptop microphone across a room, and the one you
 * would rather not hear at all while you keep listening to the others.
 *
 * A machine and not an account, the same reasoning `audioSettings.ts` gives:
 * somebody being too loud is a fact about these speakers and this room, and
 * carrying it to another device would be carrying the wrong thing.
 *
 * Keyed by user id rather than peer id. A peer id is per socket, so it changes
 * when somebody reconnects or moves the call to their laptop, and a volume that
 * resets when the other person's wifi drops is worse than none.
 */
import { create } from 'zustand';

const STORAGE_KEY = 'betweenus.peer-audio';

export interface PeerAudio {
  /** 0 to 1, where 1 is however loud they arrived. */
  volume: number;
  /** Silenced for me, without telling them and without touching anyone else. */
  muted: boolean;
}

export const DEFAULT_PEER_AUDIO: PeerAudio = { volume: 1, muted: false };

/**
 * What an `<audio>` element's `volume` should be.
 *
 * A muted person is zero rather than "not played": the track keeps arriving and
 * keeps being decoded, so unmuting is instant and their speaking ring still
 * moves - which is the difference between silencing somebody and pretending
 * they left.
 *
 * ponytail: 1 is the ceiling, because that is `HTMLMediaElement.volume`'s
 * ceiling. Boosting a quiet talker past their original level needs a WebAudio
 * gain node in the path, which is a bigger change than this is worth until
 * somebody actually asks for it.
 */
export function elementVolume(setting: PeerAudio | undefined): number {
  if (!setting) return DEFAULT_PEER_AUDIO.volume;
  if (setting.muted) return 0;
  // A clamp alone lets NaN through, and `element.volume = NaN` throws rather
  // than being ignored - which would take the whole sink down over a stored
  // value nobody can see.
  if (!Number.isFinite(setting.volume)) return 0;
  return Math.min(1, Math.max(0, setting.volume));
}

/** A setting that says nothing is not stored: the map holds the exceptions. */
export function isDefault(setting: PeerAudio): boolean {
  return setting.muted === DEFAULT_PEER_AUDIO.muted && setting.volume === DEFAULT_PEER_AUDIO.volume;
}

function load(): Record<string, PeerAudio> {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored ? (JSON.parse(stored) as Record<string, PeerAudio>) : {};
  } catch {
    return {};
  }
}

interface PeerAudioState {
  /** userId -> setting. Only people who are not at the default appear here. */
  people: Record<string, PeerAudio>;
  settingFor: (userId: string) => PeerAudio;
  setVolume: (userId: string, volume: number) => void;
  toggleMuted: (userId: string) => void;
  /** Puts one person back to normal, which is what removing them from the map is. */
  reset: (userId: string) => void;
}

export const usePeerAudio = create<PeerAudioState>((set, get) => ({
  people: load(),

  settingFor: (userId) => get().people[userId] ?? DEFAULT_PEER_AUDIO,

  setVolume: (userId, volume) => write(set, get, userId, { volume }),

  toggleMuted: (userId) => write(set, get, userId, { muted: !get().settingFor(userId).muted }),

  reset: (userId) => write(set, get, userId, DEFAULT_PEER_AUDIO),
}));

type Setter = (partial: Partial<PeerAudioState>) => void;

function write(
  set: Setter,
  get: () => PeerAudioState,
  userId: string,
  patch: Partial<PeerAudio>,
): void {
  const next = { ...get().settingFor(userId), ...patch };
  const people = { ...get().people };
  if (isDefault(next)) delete people[userId];
  else people[userId] = next;

  set({ people });
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(people));
  } catch {
    // No storage: the setting still holds for this session.
  }
}

/**
 * Online status, typing indicators and voice-channel membership, fed by the
 * `/ws/presence` socket.
 */
import { create } from 'zustand';
import type { ActiveStatus, PresenceStatus } from '@betweenus/shared-types';
import { presenceSocket } from '../services/socket';
import { notifyVoiceJoin } from '../services/notifications';
import { startIdleWatch, stopIdleWatch } from '../services/idle';
import { useAuthStore } from './auth';
import { useChatStore } from './chat';
import { useRingStore } from './ring';
import { useVoiceStore } from './voice';

/** How long a typing indicator stays up after the last keystroke event. */
const TYPING_TTL_MS = 5_000;
/** Do not send a typing event on every keystroke. */
const TYPING_THROTTLE_MS = 2_000;

interface TypingEntry {
  username: string;
  until: number;
}

interface PresenceState {
  online: Set<string>;
  /** userId -> what that person appears as. Nobody in here reads `invisible`. */
  statuses: Map<string, PresenceStatus>;
  /** This user's own status, which is the only place `invisible` shows up. */
  selfStatus: ActiveStatus;
  /**
   * What this user *picked*, which is not always what they appear as: the idle
   * watcher reports `idle` over a chosen `online` and puts it back afterwards.
   * Kept apart so an automatic idle cannot swallow a deliberate choice - a
   * person who set do-not-disturb and walked away comes back to do-not-disturb.
   */
  chosenStatus: ActiveStatus;
  /** channelId -> userId -> entry */
  typing: Map<string, Map<string, TypingEntry>>;
  /** channelId -> user ids currently in that voice channel */
  voice: Map<string, string[]>;
  /**
   * userId -> when that person was last here, ISO-8601.
   *
   * Only filled for people who are away: the server does not send it for
   * anybody online, because "online, last seen a moment ago" says one thing
   * twice and the second half is the half that goes stale.
   */
  lastSeen: Map<string, string>;

  isOnline: (userId: string) => boolean;
  statusOf: (userId: string) => PresenceStatus;
  lastSeenOf: (userId: string) => string | null;
  /**
   * "When were these people last here?" - asked when a card opens or a direct
   * message goes on screen. The answers arrive as ordinary `presence.changed`
   * events, so nothing here waits on a reply.
   */
  askLastSeen: (userIds: string[]) => void;
  typistsIn: (channelId: string) => string[];
  voiceMembers: (channelId: string) => string[];
  notifyTyping: (channelId: string) => void;
  setStatus: (status: ActiveStatus) => void;
  /**
   * The idle watcher's way in. Sends only when the reported status actually
   * changes, so a poll every half minute is not a message every half minute.
   */
  reportAutoStatus: (status: ActiveStatus) => void;
  reset: () => void;
}

let lastTypingSentAt = 0;

export const usePresenceStore = create<PresenceState>((set, get) => ({
  online: new Set(),
  statuses: new Map(),
  selfStatus: 'online',
  chosenStatus: 'online',
  typing: new Map(),
  voice: new Map(),
  lastSeen: new Map(),

  isOnline: (userId) => get().online.has(userId),

  statusOf: (userId) => get().statuses.get(userId) ?? 'offline',

  lastSeenOf: (userId) => get().lastSeen.get(userId) ?? null,

  askLastSeen: (userIds) => {
    const wanted = userIds.filter(Boolean);
    if (wanted.length === 0) return;
    presenceSocket.send({ type: 'presence.query', userIds: wanted });
  },

  typistsIn: (channelId) => {
    const now = Date.now();
    const entries = get().typing.get(channelId);
    if (!entries) return [];
    return [...entries.values()].filter((entry) => entry.until > now).map((e) => e.username);
  },

  voiceMembers: (channelId) => get().voice.get(channelId) ?? [],

  notifyTyping: (channelId) => {
    const now = Date.now();
    if (now - lastTypingSentAt < TYPING_THROTTLE_MS) return;
    lastTypingSentAt = now;
    presenceSocket.send({ type: 'typing.start', channelId });
  },

  /**
   * Optimistic: the picker closes on the chosen value straight away, and the
   * server's `status.self` confirms it a moment later.
   */
  setStatus: (status) => {
    set({ selfStatus: status, chosenStatus: status });
    presenceSocket.send({ type: 'status.set', status });
  },

  reportAutoStatus: (status) => {
    if (get().selfStatus === status) return;
    set({ selfStatus: status });
    presenceSocket.send({ type: 'status.set', status });
  },

  reset: () =>
    set({
      online: new Set(),
      statuses: new Map(),
      selfStatus: 'online',
      chosenStatus: 'online',
      typing: new Map(),
      voice: new Map(),
      lastSeen: new Map(),
    }),
}));

/**
 * Status lookup that actually re-renders when a status changes.
 *
 * `usePresenceStore((state) => state.statusOf)` selects a function, and that
 * reference never changes - so a component picking it out subscribed to
 * nothing, and the dot next to a name kept whatever colour it had when the
 * screen was first drawn. Selecting the map instead is what makes the
 * subscription real; the lookup on top of it is the same one.
 */
export function useStatusOf(): (userId: string) => PresenceStatus {
  const statuses = usePresenceStore((state) => state.statuses);
  return (userId) => statuses.get(userId) ?? 'offline';
}

/**
 * The same trick as `useStatusOf`, for the timestamp.
 *
 * Selecting `state.lastSeenOf` would select a function whose reference never
 * changes, so a header showing "last seen yesterday" would keep saying that
 * after the person came back and went again. Selecting the map is what makes
 * the subscription real.
 */
export function useLastSeenOf(): (userId: string) => string | null {
  const lastSeen = usePresenceStore((state) => state.lastSeen);
  return (userId) => lastSeen.get(userId) ?? null;
}

/**
 * Someone joining a voice channel is this app's closest thing to a ringing
 * phone, so it is worth a notification - unless it is this user, or a channel
 * they are already sitting in, where the tile appearing says it better.
 */
function announceVoiceJoins(channelId: string, before: string[], after: string[]): void {
  const joined = after.filter((userId) => !before.includes(userId));
  if (joined.length === 0) return;

  const me = useAuthStore.getState().user?.id;
  if (useVoiceStore.getState().channelId === channelId) return;

  const { channels, members } = useChatStore.getState();
  const channel = channels.find((item) => item.id === channelId);
  if (!channel) return;

  for (const userId of joined) {
    if (userId === me) continue;
    const member = members.find((item) => item.userId === userId);
    notifyVoiceJoin(channelId, channel.name, member?.displayName ?? 'Someone');
  }
}

presenceSocket.on((event) => {
  const state = usePresenceStore.getState();

  switch (event.type) {
    case 'presence.sync': {
      usePresenceStore.setState({
        online: new Set(event.users.map((user) => user.userId)),
        statuses: new Map(event.users.map((user) => [user.userId, user.status])),
        voice: new Map(event.voice.map((entry) => [entry.channelId, entry.userIds])),
      });
      return;
    }

    case 'status.self': {
      usePresenceStore.setState({ selfStatus: event.status });
      return;
    }

    case 'presence.changed': {
      const online = new Set(state.online);
      const statuses = new Map(state.statuses);
      if (event.user.status === 'offline') {
        online.delete(event.user.userId);
        statuses.delete(event.user.userId);
      } else {
        online.add(event.user.userId);
        statuses.set(event.user.userId, event.user.status);
      }

      // Kept rather than replaced when the event carries nothing: somebody
      // coming online sends no timestamp, and dropping the old one would make
      // the line under their name blank for the rest of the session the moment
      // they go away again.
      const lastSeen = new Map(state.lastSeen);
      if (event.user.lastSeenAt) lastSeen.set(event.user.userId, event.user.lastSeenAt);

      usePresenceStore.setState({ online, statuses, lastSeen });
      return;
    }

    case 'typing': {
      const typing = new Map(state.typing);
      const forChannel = new Map(typing.get(event.channelId) ?? []);
      forChannel.set(event.userId, {
        username: event.username,
        until: Date.now() + TYPING_TTL_MS,
      });
      typing.set(event.channelId, forChannel);
      usePresenceStore.setState({ typing });
      return;
    }

    case 'call.ring': {
      // Straight through: the ring store owns every decision about whether it
      // is worth showing - already in that call, already ringing, how long it
      // rings for. A socket handler that decided any of that would be a second
      // copy of those rules that the push path does not go through.
      useRingStore.getState().show({
        channelId: event.channelId,
        channelName: event.channelName,
        callerId: event.callerId,
        callerName: event.callerName,
        ...(event.callerAvatarUrl ? { callerAvatarUrl: event.callerAvatarUrl } : {}),
      });
      return;
    }

    // Answered or declined on another device of this same account. Answering
    // is visible in the roster below; declining reaches no roster at all, so
    // without this a window went on ringing after somebody said no elsewhere.
    case 'call.handled': {
      useRingStore.getState().handledElsewhere(event.channelId);
      return;
    }

    case 'voice.changed': {
      const voice = new Map(state.voice);
      const before = voice.get(event.voice.channelId) ?? [];
      voice.set(event.voice.channelId, event.voice.userIds);
      usePresenceStore.setState({ voice });
      announceVoiceJoins(event.voice.channelId, before, event.voice.userIds);

      // This account is in that call now, and this window is not the one that
      // put it there - so it is still ringing at somebody who is already
      // talking. The `call.handled` push says the same thing to the devices
      // that are not running; this is the road for the ones that are.
      const self = useAuthStore.getState().user?.id;
      if (self && event.voice.userIds.includes(self)) {
        useRingStore.getState().handledElsewhere(event.voice.channelId);
      }
      return;
    }

    default:
      return;
  }
});

/**
 * The idle watch runs for exactly as long as somebody is signed in.
 *
 * Driven from here rather than from the auth store, which would have to import
 * this one and the voice one to do it and would make a cycle out of three
 * modules that currently only point one way.
 */
useAuthStore.subscribe((state, previous) => {
  if (state.status === previous.status) return;

  if (state.status === 'authenticated') {
    startIdleWatch(
      (status) => usePresenceStore.getState().reportAutoStatus(status),
      () => usePresenceStore.getState().chosenStatus,
      // Being in a call is being present, whatever the keyboard has been doing.
      () => useVoiceStore.getState().channelId !== null,
    );
    return;
  }

  stopIdleWatch();
});

// Indicators expire on a timer, not on the next event, so a stale "typing…"
// disappears even when the typist goes quiet.
const typingTimer = setInterval(() => {
  const { typing } = usePresenceStore.getState();
  const now = Date.now();
  let changed = false;

  const next = new Map<string, Map<string, TypingEntry>>();
  for (const [channelId, entries] of typing) {
    const live = new Map([...entries].filter(([, entry]) => entry.until > now));
    if (live.size !== entries.size) changed = true;
    if (live.size > 0) next.set(channelId, live);
  }

  if (changed) usePresenceStore.setState({ typing: next });
}, 1_000);
typingTimer.unref?.();

/**
 * The controller side: the machines this account can reach, and the session it
 * currently holds on one of them.
 *
 * The store hides what the session was not granted, but hiding is not the
 * enforcement - the gateway refuses an event this client should never have sent
 * and audits the attempt. Both are on purpose: the UI should not offer what it
 * cannot do, and the server should not trust that it did not.
 */
import { create } from 'zustand';
import type {
  ClientRemoteEvent,
  RemoteMachineSummary,
  RemotePermission,
  RemoteScreen,
  RemoteSessionResponse,
  ServerRemoteEvent,
} from '@betweenus/shared-types';
import { api } from '../services/api';
import { wsUrl } from '../services/endpoint';
import { ScreenLink } from '../services/remote-peer';
import { chunksOf, safeFileName, type TransferProgress } from '../services/remote-transfer';
import { useAuthStore } from './auth';

/** Mouse moves are sampled: a session does not need 500 events a second. */
const MOVE_INTERVAL_MS = 25;

/**
 * How long the machine has to answer an offered file.
 *
 * Long enough for a machine that is busy, short enough that a controller is not
 * left staring at a progress bar that will never move. An agent that has gone
 * away answers nothing at all, and the session's own socket closing is the
 * other way this ends.
 */
const TRANSFER_ANSWER_TIMEOUT_MS = 30_000;

type SessionStatus = 'connecting' | 'waiting' | 'live' | 'ended';

interface RemoteState {
  machines: RemoteMachineSummary[];
  loading: boolean;
  error: string | null;

  session: RemoteSessionResponse | null;
  status: SessionStatus;
  /** Why it ended, for the panel that replaces the screen. */
  endedReason: string | null;
  /** The agent's screen, once it is publishing. */
  track: MediaStreamTrack | null;
  /**
   * The machine's own sound, when the session was granted `REMOTE_AUDIO` and
   * the machine can capture it. Null on a session without it, and on a machine
   * whose platform has no loopback - which is everything but Windows today.
   */
  audioTrack: MediaStreamTrack | null;
  /** Whether the controller is listening. Off by default: sound is a surprise. */
  listening: boolean;
  /**
   * What this session may do *now*. It starts as the session's frozen
   * permissions and changes when the machine lends or takes back control, so
   * the UI never renders from what it asked for.
   */
  permissions: RemotePermission[];
  /** True while the mouse and keyboard are being sent. Off is "just watching". */
  controlling: boolean;
  /** Set while waiting for somebody at the machine to answer. */
  requestingControl: boolean;
  /** The machine's displays. Empty until the agent says, and often just one. */
  screens: RemoteScreen[];
  /** Which of them is on the wire. The agent is the authority on this. */
  activeScreenId: string | null;
  /** The file being sent to the machine, and how far it has got. One at a time. */
  transfer: TransferProgress | null;

  load: () => Promise<void>;
  connect: (machineId: string) => Promise<void>;
  /**
   * Reaches whoever is sharing a screen in a voice channel, by their user id.
   * Watching somebody's screen and wanting the mouse is one thought, so it is
   * one button there rather than a trip through the machine list.
   */
  connectToOwner: (userId: string, alsoRequestControl?: boolean) => Promise<void>;
  disconnect: () => Promise<void>;
  sendMouse: (input: Omit<Extract<ClientRemoteEvent, { type: 'input.mouse' }>, 'type'>) => void;
  sendKey: (input: Omit<Extract<ClientRemoteEvent, { type: 'input.key' }>, 'type'>) => void;
  can: (permission: RemotePermission) => boolean;
  /** Asks the machine to send a different monitor. */
  selectScreen: (screenId: string) => void;
  /** Takes control, asking the machine for it when it was not granted up front. */
  requestControl: () => void;
  releaseControl: () => void;
  /** Sends one file to the machine. Refused while another one is in flight. */
  sendFile: (file: File) => Promise<void>;
  /** Gives up on the file being sent; the machine throws away what arrived. */
  cancelTransfer: () => void;
  /** Clears a finished transfer off the panel. */
  dismissTransfer: () => void;
  /** Turns the machine's own sound on and off, locally. */
  setListening: (listening: boolean) => void;
  reset: () => void;
}

let socket: WebSocket | null = null;
/** The connection the agent's screen arrives over. */
let link: ScreenLink | null = null;
let lastMoveAt = 0;
/** Set when the session was opened by "Request control"; fired once it is up. */
let requestControlOnOpen = false;

/**
 * The machine's answer to the file currently being offered.
 *
 * A transfer is two things that happen in different places - a message over the
 * gateway and a stream over the data channel - and this is the join between
 * them: `sendFile` waits here, and the socket handler settles it.
 */
let answering: {
  transferId: string;
  settle: (accepted: boolean, reason?: string) => void;
} | null = null;
/** Set by a cancel, read by the sending loop between chunks. */
let transferCancelled = false;

export const useRemoteStore = create<RemoteState>((set, get) => ({
  machines: [],
  loading: false,
  error: null,
  session: null,
  status: 'ended',
  endedReason: null,
  track: null,
  audioTrack: null,
  listening: false,
  permissions: [],
  controlling: false,
  requestingControl: false,
  screens: [],
  activeScreenId: null,
  transfer: null,

  load: async () => {
    set({ loading: true, error: null });
    try {
      set({ machines: await api.machines(), loading: false });
    } catch (error) {
      set({
        loading: false,
        error: error instanceof Error ? error.message : 'Could not list machines',
      });
    }
  },

  connect: async (machineId) => {
    await get().disconnect();
    set({ status: 'connecting', endedReason: null, error: null });

    let session: RemoteSessionResponse;
    try {
      session = await api.startRemoteSession(machineId);
    } catch (error) {
      set({
        status: 'ended',
        error: error instanceof Error ? error.message : 'That machine refused the session',
      });
      return;
    }

    set({
      session,
      status: 'waiting',
      permissions: session.permissions,
      controlling: false,
      requestingControl: false,
      screens: [],
      activeScreenId: null,
      transfer: null,
      audioTrack: null,
      // A session that may listen starts listening. The machine's owner agreed
      // to it when they granted the permission, and a toggle that has to be
      // found before anything is heard is a feature nobody knows is there.
      listening: session.permissions.includes('REMOTE_AUDIO'),
    });
    openSocket(session, set, get);
    openLink(session, set);
  },

  connectToOwner: async (userId, alsoRequestControl = false) => {
    let machines = get().machines;
    if (machines.length === 0) {
      await get().load();
      machines = get().machines;
    }

    const theirs = machines.filter((machine) => machine.ownerId === userId);
    const machine = theirs.find((candidate) => candidate.online) ?? theirs[0];
    if (!machine) {
      set({ error: 'You have no remote access to a machine of theirs' });
      return;
    }
    if (!machine.online) {
      set({ error: `${machine.name} is not online` });
      return;
    }

    requestControlOnOpen = alsoRequestControl;
    await get().connect(machine.id);
  },

  disconnect: async () => {
    const session = get().session;
    requestControlOnOpen = false;
    // A transfer waiting for an answer that is never coming has to be let go
    // before the socket does, or `sendFile` sits on a promise for its timeout.
    answering?.settle(false, 'The session ended');
    answering = null;
    transferCancelled = true;
    socket?.close();
    socket = null;

    link?.close();
    link = null;

    // The socket closing already tells the gateway, but a window that is being
    // torn down may not get the close out; the HTTP call is the belt.
    if (session) await api.endRemoteSession(session.sessionId).catch(() => undefined);
    stopClipboardSync();
    set({
      session: null,
      status: 'ended',
      track: null,
      audioTrack: null,
      listening: false,
      permissions: [],
      controlling: false,
      requestingControl: false,
      screens: [],
      activeScreenId: null,
      transfer: null,
    });
  },

  sendMouse: (input) => {
    if (!get().controlling || !get().can('REMOTE_CONTROL')) return;
    if (input.action === 'move') {
      const now = Date.now();
      if (now - lastMoveAt < MOVE_INTERVAL_MS) return;
      lastMoveAt = now;
    }
    send({ type: 'input.mouse', ...input });
  },

  sendKey: (input) => {
    if (!get().controlling || !get().can('REMOTE_CONTROL')) return;
    send({ type: 'input.key', ...input });
  },

  can: (permission) => get().permissions.includes(permission),

  selectScreen: (screenId) => {
    // Not written to `activeScreenId` here: the agent answers with a fresh
    // `screens` once the swap worked, and a label that moved before the picture
    // did would be a lie during the second it takes.
    send({ type: 'screen.select', screenId });
  },

  /**
   * One button, two behaviours. A session already granted control just starts
   * sending; one that was not asks the machine, and somebody sitting at it
   * answers - which is how RDP works, and the one case where a person present
   * outranks a stored grant.
   */
  requestControl: () => {
    if (!get().session) return;
    if (get().can('REMOTE_CONTROL')) {
      set({ controlling: true });
      return;
    }
    set({ requestingControl: true });
    send({ type: 'control.request' });
  },

  releaseControl: () => {
    set({ controlling: false });
    send({ type: 'control.release' });
  },

  /**
   * Sends one file to the machine.
   *
   * Two channels, in this order and no other: the offer goes over the gateway,
   * which is what checks `REMOTE_FILE_TRANSFER` and writes it down, and only
   * when the machine has answered do the bytes go down the data channel
   * directly. Sending first and asking afterwards would put a file on a machine
   * whose permission nothing had checked.
   */
  sendFile: async (file) => {
    const current = get().transfer;
    if (current && (current.status === 'offering' || current.status === 'sending')) {
      set({ error: 'One file at a time; that one is still going' });
      return;
    }
    if (!get().can('REMOTE_FILE_TRANSFER')) {
      set({ error: 'This session may not send files' });
      return;
    }
    if (!link?.dataReady) {
      set({ error: 'The link to the machine is not ready yet' });
      return;
    }

    const transferId = crypto.randomUUID();
    const name = safeFileName(file.name);
    transferCancelled = false;
    set({
      error: null,
      transfer: { transferId, name, size: file.size, moved: 0, status: 'offering' },
    });
    send({ type: 'file.offer', transferId, name, size: file.size });

    // Waits for `file.accepted`, or for the machine to say no. An empty file is
    // finished by the agent before it ever answers, and `file.done` settles
    // this too - see the socket handler.
    const answer = await new Promise<{ accepted: boolean; reason?: string }>((resolve) => {
      const timer = window.setTimeout(
        () => resolve({ accepted: false, reason: 'The machine did not answer' }),
        TRANSFER_ANSWER_TIMEOUT_MS,
      );
      answering = {
        transferId,
        settle: (accepted, reason) => {
          window.clearTimeout(timer);
          answering = null;
          resolve({ accepted, reason });
        },
      };
    });

    if (!answer.accepted) {
      // `file.done` on an empty file settles this as refused-but-finished; the
      // handler has already written the outcome, so nothing is overwritten here.
      const now = get().transfer;
      if (now?.transferId === transferId && now.status === 'offering') {
        set({ transfer: { ...now, status: 'refused', detail: answer.reason } });
      }
      return;
    }

    set((state) =>
      state.transfer?.transferId === transferId
        ? { transfer: { ...state.transfer, status: 'sending' } }
        : {},
    );

    try {
      let moved = 0;
      for await (const chunk of chunksOf(file)) {
        if (transferCancelled || get().transfer?.transferId !== transferId) return;
        // Awaited, so the loop is paced by the network rather than by how fast
        // the disk can be read - see `sendBytes`.
        await link.sendBytes(chunk);
        moved += chunk.byteLength;
        set((state) =>
          state.transfer?.transferId === transferId
            ? { transfer: { ...state.transfer, moved } }
            : {},
        );
      }
      // Not marked done here. The machine says when the last byte reached its
      // disk, which is a different moment from the last byte leaving this one.
    } catch (error) {
      send({ type: 'file.cancel', transferId, reason: 'send failed' });
      set((state) =>
        state.transfer?.transferId === transferId
          ? {
              transfer: {
                ...state.transfer,
                status: 'failed',
                detail: error instanceof Error ? error.message : 'The file could not be sent',
              },
            }
          : {},
      );
    }
  },

  cancelTransfer: () => {
    const current = get().transfer;
    if (!current || current.status === 'done' || current.status === 'cancelled') return;
    transferCancelled = true;
    answering?.settle(false, 'Cancelled');
    send({ type: 'file.cancel', transferId: current.transferId, reason: 'cancelled' });
    set({ transfer: { ...current, status: 'cancelled' } });
  },

  dismissTransfer: () => set({ transfer: null }),

  setListening: (listening) => set({ listening }),

  reset: () => {
    void get().disconnect();
    set({ machines: [], error: null, endedReason: null });
  },
}));

type Setter = (
  partial: Partial<RemoteState> | ((state: RemoteState) => Partial<RemoteState>),
) => void;

function openSocket(
  session: RemoteSessionResponse,
  set: Setter,
  get: () => RemoteState,
): void {
  const token = useAuthStore.getState().accessToken ?? '';
  const next = new WebSocket(
    `${wsUrl()}/ws/remote?sessionId=${encodeURIComponent(session.sessionId)}` +
      `&token=${encodeURIComponent(token)}`,
  );
  socket = next;

  // A session opened from "Request control" asks the moment there is something
  // to ask over; `send` is a no-op before the socket is up.
  next.onopen = () => {
    if (!requestControlOnOpen) return;
    requestControlOnOpen = false;
    get().requestControl();
  };

  next.onmessage = (raw) => {
    let event: ServerRemoteEvent;
    try {
      event = JSON.parse(String(raw.data)) as ServerRemoteEvent;
    } catch {
      return;
    }

    switch (event.type) {
      case 'control.changed':
        set({
          permissions: event.permissions,
          requestingControl: false,
          controlling: event.granted,
          ...(event.granted ? {} : { error: event.reason ?? null }),
        });
        return;

      case 'screens':
        set({ screens: event.screens, activeScreenId: event.activeId || null });
        return;

      case 'agent.state':
        if (event.state === 'refused') {
          set({ status: 'ended', endedReason: event.reason ?? 'The machine refused' });
        }
        return;

      case 'session.ended':
        set({ status: 'ended', endedReason: event.reason, track: null });
        void get().disconnect();
        return;

      case 'clipboard.set':
        // Remembered before writing so the poller does not read it straight
        // back out and send it round again.
        lastClipboard = event.text;
        window.betweenus?.clipboardWrite(event.text);
        return;

      // The machine's answer to an offered file, and the receipt when the last
      // byte has landed on its disk.
      case 'file.accepted':
        if (answering?.transferId === event.transferId) answering.settle(true);
        return;

      case 'file.refused':
        if (answering?.transferId === event.transferId) {
          answering.settle(false, event.reason);
          return;
        }
        // Refused part way through: the machine gave up on a file it had
        // already taken, so the sending loop is stopped rather than left
        // pushing bytes at a file that no longer exists.
        transferCancelled = true;
        set((state) =>
          state.transfer?.transferId === event.transferId
            ? { transfer: { ...state.transfer, status: 'refused', detail: event.reason } }
            : {},
        );
        return;

      case 'file.done':
        // An empty file is finished before it is ever accepted, so this settles
        // the wait as well as reporting the outcome.
        if (answering?.transferId === event.transferId) answering.settle(false, undefined);
        set((state) =>
          state.transfer?.transferId === event.transferId
            ? {
                transfer: {
                  ...state.transfer,
                  moved: state.transfer.size,
                  status: 'done',
                  detail: event.path,
                },
              }
            : {},
        );
        return;

      // The agent's offer, and its ICE candidates. Relayed by the gateway,
      // which reads none of it.
      case 'rtc.signal':
        void link?.accept(event.data);
        return;

      case 'error':
        set({ error: event.message });
        return;

      default:
        return;
    }
  };

  // A session with no socket is not a session; there is nothing to reconnect
  // to, because the gateway ended it the moment this closed.
  next.onclose = () => {
    if (socket === next) socket = null;
  };
  next.onerror = () => next.close();
}

/**
 * Waits for the agent's screen. Nothing is sent from this side.
 *
 * There is no subscription to size and nothing between the two machines to
 * resize anything: the desktop arrives at the size it was captured and the
 * element does the fitting. That was not true of the SFU build, where the
 * stream was sized to the video element and a remote desktop in a small window
 * came back soft no matter what the agent sent.
 *
 * The agent offers, so this end has nothing to do until a signal arrives - it
 * only has to exist first, or the offer would land with nowhere to go.
 */
function openLink(session: RemoteSessionResponse, set: Setter): void {
  link = new ScreenLink(false, {
    iceServers: session.iceServers,
    send: (data) => send({ type: 'rtc.signal', data }),
    onTrack: (track) => {
      set(track ? { track, status: 'live' } : { track: null });
      if (track) startClipboardSync();
    },
    // Only arrives when the machine put something on it, which it only does for
    // a session granted `REMOTE_AUDIO` on a platform that can capture loopback.
    onAudio: (track) => set({ audioTrack: track }),
    onFailed: (reason) => set({ status: 'ended', endedReason: reason, track: null }),
  });
}

/**
 * Clipboard sync, controller side. Polled for the same reason the agent polls:
 * there is no reliable clipboard change event, and a second is fast enough for
 * copy-then-paste.
 */
let clipboardTimer: number | null = null;
let lastClipboard = '';

function startClipboardSync(): void {
  stopClipboardSync();
  const bridge = window.betweenus;
  if (!bridge) return;

  clipboardTimer = window.setInterval(() => {
    if (!useRemoteStore.getState().can('REMOTE_CLIPBOARD')) return;
    void bridge.clipboardRead().then((text) => {
      if (!text || text === lastClipboard) return;
      lastClipboard = text;
      send({ type: 'clipboard.set', text });
    });
  }, 1000);
}

function stopClipboardSync(): void {
  if (clipboardTimer !== null) window.clearInterval(clipboardTimer);
  clipboardTimer = null;
  lastClipboard = '';
}

function send(event: ClientRemoteEvent): void {
  if (socket?.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
}

/**
 * Somebody is ringing you into a call.
 *
 * A voice channel is a room you wander into. A ring is somebody standing at
 * the door of it with your name - and that difference is the whole reason this
 * store exists rather than another line in the roster: it interrupts, it makes
 * a sound, and it waits for an answer.
 *
 * Two ways in, for the same reason there are two on the phone. The presence
 * socket carries it to a client that is running, which is the one somebody is
 * most likely sitting in front of; the service worker carries it to a tab that
 * is not. Both land here, and landing twice is not two rings - see `show`.
 *
 * What it never does is join anything on its own. Answering opens a
 * microphone, and only a person may do that.
 */
import { create } from 'zustand';
import { api } from '../services/api';
import { startRinging, stopRinging } from '../services/call-tones';
import { notifyRing } from '../services/notifications';
import { useChatStore } from './chat';
import { useVoiceStore } from './voice';

export interface Ring {
  channelId: string;
  channelName: string;
  callerId: string;
  callerName: string;
  callerAvatarUrl?: string;
}

/**
 * How long it rings before it gives up, in milliseconds.
 *
 * The same 45 seconds the phone rings for, so a call that stopped ringing on
 * one device has stopped ringing on all of them. A ringer with no timeout is a
 * modal somebody comes back to an hour later and answers a call that ended.
 */
export const RING_TIMEOUT_MS = 45_000;

interface RingState {
  /** The one being shown, or null. One at a time: this is a modal, not a list. */
  incoming: Ring | null;
  show: (ring: Ring) => void;
  /** Joins the call. The only path that opens a microphone. */
  answer: () => void;
  /**
   * Said no, on purpose, here.
   *
   * Separate from [dismiss] because it is the only one of the two that is
   * worth telling anybody about. The caller still is not told - a ring is not
   * a handshake, and it rings out for them either way - but this account's
   * *other* devices are, or they go on ringing at somebody who has already
   * decided.
   */
  decline: () => void;
  /** Said no, or it rang out. Silent: see [decline] for the half that is not. */
  dismiss: () => void;
  /**
   * Answered or declined somewhere else, on another device of this same
   * account.
   *
   * A ring is aimed at an *account*, so it lands on every device that account
   * owns - and dealing with it on one of them used to leave the rest ringing,
   * until they timed out or the whole call ended. Neither half could be seen
   * from here: answering puts the account in the roster, which is exactly who
   * the roster announcement is addressed *around*, and declining was not sent
   * anywhere at all.
   */
  handledElsewhere: (channelId: string) => void;
}

let timeout: number | null = null;

function clearTimer(): void {
  if (timeout !== null) window.clearTimeout(timeout);
  timeout = null;
}

export const useRingStore = create<RingState>((set, get) => ({
  incoming: null,

  show: (ring) => {
    // Already in that call. The person ringing cannot see the roster the
    // instant they press the button, so this is a normal thing to receive
    // rather than a mistake - and a ringer over a call you are already in is a
    // way to be hung up on by accident.
    const voice = useVoiceStore.getState();
    if (voice.channelId === ring.channelId && voice.status !== 'idle') return;

    // The same ring by both roads: the socket delivered it and the service
    // worker handed the push over as well. One ring.
    if (get().incoming?.channelId === ring.channelId) return;

    clearTimer();
    set({ incoming: ring });
    startRinging();
    notifyRing(ring.channelId, ring.channelName, ring.callerName);
    timeout = window.setTimeout(() => get().dismiss(), RING_TIMEOUT_MS);
  },

  answer: () => {
    const ring = get().incoming;
    clearTimer();
    stopRinging();
    set({ incoming: null });
    if (!ring) return;

    // The channel is opened as well as joined, so answering lands somewhere
    // that shows the call rather than joining it invisibly behind whatever was
    // already on screen.
    void useChatStore.getState().selectChannel(ring.channelId);
    void useVoiceStore.getState().join(ring.channelId);
  },

  decline: () => {
    const ring = get().incoming;
    get().dismiss();
    if (!ring) return;
    // Nothing waits on this and nothing is shown if it fails. The ringer here
    // is already down, which is what the person pressing the button asked for;
    // the other devices ring out on their own timer as they always did.
    void api.callDecline(ring.channelId).catch(() => undefined);
  },

  dismiss: () => {
    clearTimer();
    stopRinging();
    set({ incoming: null });
  },

  handledElsewhere: (channelId) => {
    if (get().incoming?.channelId !== channelId) return;
    get().dismiss();
  },
}));


/**
 * Answering a call that arrived some other way silences the ringer.
 *
 * Without this, joining the channel from the sidebar while it is ringing
 * leaves the ringtone playing over the call somebody has just walked into.
 */
useVoiceStore.subscribe((state, previous) => {
  if (state.channelId === previous.channelId) return;
  const ringing = useRingStore.getState().incoming;
  if (ringing && state.channelId === ringing.channelId) useRingStore.getState().dismiss();
});

/**
 * Giving somebody the mouse on a screen you are sharing in a call.
 *
 * This is not a remote-desktop session and it deliberately does not become one.
 * A remote session is a standing arrangement: the machine is enrolled, a grant
 * was written down beforehand, and a gateway enforces it. What happens in a
 * call is the opposite - two people are already talking, one of them is showing
 * the other a problem, and "here, you do it" should not need an administrator.
 * Teams calls it giving control, and the shape is the same one.
 *
 * So the whole exchange rides the peers' own data channels, directly between
 * the two clients, and the only authority is the person sharing clicking yes.
 * That is the right authority: it is their machine, they are sitting at it, and
 * they can see what is being done with it. Nothing here can start without them,
 * and one click ends it.
 *
 * What keeps it honest:
 *
 * - A data channel has exactly two ends. A message on the connection to a peer
 *   came from that peer and from nobody else - there is no server in between
 *   that could have written it, and the peer's identity came from the roster
 *   `call-service` built from authenticated sockets.
 * - Input is applied only from the one identity control was granted to, only
 *   while a screen is still being shared, and only when that share is a whole
 *   display - a window can be dragged between monitors, so there is no fraction
 *   of a screen to map a click onto, and control of one is refused.
 * - Control ends when the share ends, when the call does, when that person
 *   leaves, when either side presses the button, and when the person driving
 *   presses Escape.
 *
 * Pointers are the other half. Several people watch a share and any of them may
 * be pointing at something; each sends where their cursor is over the picture,
 * everyone draws everyone else's with a name on it, and a pointer that goes
 * quiet disappears. Only one person can drive, but everybody can point.
 */
import { create } from 'zustand';
import type { CallPeer } from '@betweenus/shared-types';
import type { Mesh } from '../services/mesh';
// Circular by design and safe: the voice store attaches this one, and this one
// only reads it from inside a function, long after both modules have loaded.
import { useVoiceStore } from './voice';

/**
 * Mouse moves are sampled; the far end does not need 500 events a second.
 *
 * ponytail: one reliable, ordered data channel carries pointers, mouse moves
 * and grants alike, where the SFU build could mark the cosmetic ones lossy. At
 * these rates it does not matter; a second unordered channel is the fix if a
 * bad link ever makes pointers lag behind the picture.
 */
const MOVE_INTERVAL_MS = 25;
/** Pointers are cosmetic, so they are sent less often. */
const POINTER_INTERVAL_MS = 60;
/** A pointer nobody has heard from in this long has left the picture. */
const POINTER_STALE_MS = 4_000;

const TOPIC = 'betweenus.share';

interface Person {
  identity: string;
  name: string;
}

/** A cursor to draw, in fractions of the shared screen. */
export interface SharePointer {
  identity: string;
  name: string;
  x: number;
  y: number;
  at: number;
}

type Wire =
  | { k: 'ask' }
  | { k: 'grant' }
  | { k: 'deny'; why: string }
  | { k: 'revoke' }
  | {
      k: 'm';
      a: 'move' | 'down' | 'up' | 'wheel';
      x: number;
      y: number;
      b?: 'left' | 'right' | 'middle';
      d?: number;
    }
  | { k: 'key'; a: 'down' | 'up'; key: string; code: string; mods?: string[] }
  | { k: 'p'; x: number; y: number }
  | { k: 'p.off' };

/** What actually crosses the channel, so a stray message is easy to ignore. */
interface Envelope {
  topic: string;
  message: Wire;
}

interface ShareControlState {
  /** Sharer side: people who have asked and have not been answered. */
  requests: Person[];
  /** Sharer side: who is driving this machine right now. */
  controller: Person | null;
  /** Viewer side: waiting for an answer. */
  asking: boolean;
  /** Viewer side: the identity whose screen this client is driving. */
  driving: string | null;
  /** Viewer side: why the last ask was turned down. */
  refusal: string | null;
  /** Everyone: identity -> where their cursor is over the share. */
  pointers: Record<string, SharePointer>;

  /** Called by the voice store when a call comes and goes. */
  attach: (mesh: Mesh) => void;
  detach: () => void;
  /** Called by the voice store for every data-channel message. */
  receive: (from: CallPeer, payload: unknown) => void;
  /** Called by the voice store when the roster changes. */
  peersChanged: (peers: CallPeer[]) => void;

  ask: (sharer: Person) => void;
  answer: (identity: string, granted: boolean) => void;
  /** Sharer takes it back, or the driver hands it over - same wire, same end. */
  stop: () => void;

  sendPointer: (x: number, y: number) => void;
  clearPointer: () => void;
  sendMouse: (
    action: 'move' | 'down' | 'up' | 'wheel',
    x: number,
    y: number,
    button?: 'left' | 'right' | 'middle',
    deltaY?: number,
  ) => void;
  /** `modifiers` is what was held at the moment of the press - see keyboard.ts. */
  sendKey: (action: 'down' | 'up', key: string, code: string, modifiers?: string[]) => void;
}

let mesh: Mesh | null = null;
let lastMoveAt = 0;
let lastPointerAt = 0;
let sweeper: number | null = null;
/** Who this client asked, so an unsolicited "yes" from anyone else is ignored. */
let asked: string | null = null;

function publish(message: Wire, to?: string[]): void {
  mesh?.sendData({ topic: TOPIC, message } satisfies Envelope, to);
}

export const useShareControlStore = create<ShareControlState>((set, get) => ({
  requests: [],
  controller: null,
  asking: false,
  driving: null,
  refusal: null,
  pointers: {},

  attach: (next) => {
    get().detach();
    mesh = next;

    // A cursor that stopped arriving has left the picture; nothing sends a
    // farewell when a window closes.
    sweeper = window.setInterval(() => {
      const cutoff = Date.now() - POINTER_STALE_MS;
      const pointers = Object.fromEntries(
        Object.entries(get().pointers).filter(([, pointer]) => pointer.at > cutoff),
      );
      if (Object.keys(pointers).length !== Object.keys(get().pointers).length) set({ pointers });
    }, 1_000);
  },

  detach: () => {
    if (sweeper !== null) window.clearInterval(sweeper);
    sweeper = null;
    mesh = null;
    asked = null;
    window.betweenus?.remoteTarget(null, 'call');
    set({
      requests: [],
      controller: null,
      asking: false,
      driving: null,
      refusal: null,
      pointers: {},
    });
  },

  receive: (from, payload) => {
    const envelope = payload as Envelope | null;
    if (!envelope || envelope.topic !== TOPIC || !envelope.message) return;
    onMessage(envelope.message, from, set, get);
  },

  // Somebody who leaves cannot still be driving, and their cursor should not be
  // left on screen.
  peersChanged: (peers) => {
    const present = new Set(peers.map((peer) => peer.peerId));

    set((state) => {
      const pointers = Object.fromEntries(
        Object.entries(state.pointers).filter(([identity]) => present.has(identity)),
      );
      const controllerGone = state.controller !== null && !present.has(state.controller.identity);
      const drivenGone = state.driving !== null && !present.has(state.driving);

      return {
        pointers,
        requests: state.requests.filter((person) => present.has(person.identity)),
        controller: controllerGone ? null : state.controller,
        driving: drivenGone ? null : state.driving,
        asking: drivenGone ? false : state.asking,
      };
    });

    if (get().controller === null) window.betweenus?.remoteTarget(null, 'call');
  },

  ask: (sharer) => {
    asked = sharer.identity;
    set({ asking: true, refusal: null, driving: null });
    publish({ k: 'ask' }, [sharer.identity]);
  },

  answer: (identity, granted) => {
    const request = get().requests.find((person) => person.identity === identity);
    set((state) => ({ requests: state.requests.filter((person) => person.identity !== identity) }));
    if (!request) return;

    if (!granted) {
      publish({ k: 'deny', why: 'declined' }, [identity]);
      return;
    }

    // The share can have stopped between the ask and the answer, and granting
    // control of a screen nobody is sending would be a grant with no picture
    // over it - the one situation where somebody is driving blind.
    const refusal = whyControlIsImpossible();
    if (refusal) {
      publish({ k: 'deny', why: refusal }, [identity]);
      return;
    }

    // Whatever was being controlled before is not any more: one driver.
    const previous = get().controller;
    if (previous && previous.identity !== identity) {
      publish({ k: 'revoke' }, [previous.identity]);
    }

    // Input arrives as a fraction of the shared display, so the main process
    // has to be told which display that is before the first event lands. Under
    // `call`, which is its own target: a machine can be in a remote session at
    // the same time, watching a different monitor, and the two must not
    // overwrite each other.
    window.betweenus?.remoteTarget(sharedDisplayId(), 'call');
    set({ controller: request });
    publish({ k: 'grant' }, [identity]);
  },

  stop: () => {
    const { controller, driving } = get();
    if (controller) {
      publish({ k: 'revoke' }, [controller.identity]);
      window.betweenus?.remoteTarget(null, 'call');
      set({ controller: null });
    }
    if (driving) {
      publish({ k: 'revoke' }, [driving]);
      asked = null;
      set({ driving: null, asking: false });
    }
  },

  sendPointer: (x, y) => {
    const now = Date.now();
    if (now - lastPointerAt < POINTER_INTERVAL_MS) return;
    lastPointerAt = now;
    publish({ k: 'p', x, y });
  },

  clearPointer: () => publish({ k: 'p.off' }),

  sendMouse: (action, x, y, button, deltaY) => {
    const target = get().driving;
    if (!target) return;
    if (action === 'move') {
      const now = Date.now();
      if (now - lastMoveAt < MOVE_INTERVAL_MS) return;
      lastMoveAt = now;
    }
    publish({ k: 'm', a: action, x, y, b: button, d: deltaY }, [target]);
  },

  sendKey: (action, key, code, modifiers) => {
    const target = get().driving;
    if (!target) return;
    publish({ k: 'key', a: action, key, code, mods: modifiers }, [target]);
  },
}));

type Setter = (
  partial:
    | Partial<ShareControlState>
    | ((state: ShareControlState) => Partial<ShareControlState>),
) => void;

function onMessage(
  message: Wire,
  from: CallPeer,
  set: Setter,
  get: () => ShareControlState,
): void {
  const identity = from.peerId;
  const name = from.username || from.peerId;

  switch (message.k) {
    case 'p':
      set((state) => ({
        pointers: {
          ...state.pointers,
          [identity]: { identity, name, x: message.x, y: message.y, at: Date.now() },
        },
      }));
      return;

    case 'p.off':
      set((state) => {
        const pointers = { ...state.pointers };
        delete pointers[identity];
        return { pointers };
      });
      return;

    // Somebody wants the mouse. Nothing is granted here - it goes in front of
    // the person sharing, and stays there until they answer.
    case 'ask': {
      const refusal = whyControlIsImpossible();
      if (refusal) {
        publish({ k: 'deny', why: refusal }, [identity]);
        return;
      }
      set((state) =>
        state.requests.some((person) => person.identity === identity)
          ? {}
          : { requests: [...state.requests, { identity, name }] },
      );
      return;
    }

    // Only from the person who was asked. An unsolicited "yes" is somebody
    // else's client being strange, and acting on it would point this window's
    // keyboard at a machine nobody offered.
    case 'grant':
      if (asked !== identity) return;
      asked = null;
      set({ driving: identity, asking: false, refusal: null });
      return;

    case 'deny':
      if (asked !== identity) return;
      asked = null;
      set({ asking: false, driving: null, refusal: message.why });
      return;

    // Sent by either side: the sharer taking it back, or the driver letting go.
    case 'revoke':
      if (get().controller?.identity === identity) {
        window.betweenus?.remoteTarget(null, 'call');
        set({ controller: null });
      }
      if (get().driving === identity) set({ driving: null, asking: false });
      return;

    case 'm': {
      if (!mayDrive(identity, get)) return;
      window.betweenus?.remoteMouse({
        action: message.a,
        x: message.x,
        y: message.y,
        button: message.b,
        deltaY: message.d,
        source: 'call',
      });
      return;
    }

    case 'key': {
      if (!mayDrive(identity, get)) return;
      window.betweenus?.remoteKey({
        action: message.a,
        key: message.key,
        code: message.code,
        modifiers: message.mods,
        source: 'call',
      });
      return;
    }

    default:
      return;
  }
}

/**
 * The check that matters, applied to every single input event rather than once
 * at the grant: the sender has to be the one person control was given to, and
 * the screen has to still be being shared. A grant that outlived its share
 * would be a way to keep driving a machine nobody is watching.
 */
function mayDrive(identity: string, get: () => ShareControlState): boolean {
  return get().controller?.identity === identity && sharedDisplayId() !== null;
}

/**
 * Which display this client is sharing, or null when it is sharing a window or
 * nothing at all.
 */
function sharedDisplayId(): string | null {
  const { screenEnabled, sharedDisplayId: displayId } = useVoiceStore.getState();
  return screenEnabled ? displayId : null;
}

function whyControlIsImpossible(): string | null {
  const { screenEnabled, sharedDisplayId: displayId } = useVoiceStore.getState();
  if (!screenEnabled) return 'they are not sharing a screen';
  if (!displayId) return 'a window is being shared, not a whole screen';
  if (window.betweenus?.platform !== 'win32') return 'control is not supported on that machine';
  return null;
}

/**
 * Statuses: posts that expire after a day, from the people you are friends
 * with.
 *
 * The whole tray is one call and it is re-read rather than patched, which is
 * the same bargain the friend list makes: the payload is small, it changes
 * rarely, and `seen` and `viewCount` differ per reader - so a carried event
 * would be a different payload per recipient composed on the server.
 *
 * The one thing kept locally rather than refetched is which posts this window
 * has already opened (`seenLocally`). The server is told the moment a post is
 * opened, but the answer to "does this ring still glow" has to change under
 * the reader's thumb rather than a round trip later.
 */
import { create } from 'zustand';
import type {
  CreateStatusRequest,
  StatusEntry,
  StatusFeed,
  StatusFeedEntry,
  StatusViewer,
} from '@betweenus/shared-types';
import { api } from '../services/api';
import { openStatusCaption, sealStatus } from '../services/e2ee';
import { chatSocket } from '../services/socket';
import { releaseStatusMedia } from '../services/status-media';

/**
 * A post as the composer knows it: the words, not the envelope.
 *
 * Sealing happens here rather than there, so the composer never handles a key
 * and every path into the tray - there is only one - seals the same way.
 */
export type StatusDraft = Omit<
  CreateStatusRequest,
  'keys' | 'senderDeviceId' | 'mediaIv' | 'mediaType'
>;

interface StatusState {
  mine: StatusEntry[];
  others: StatusFeedEntry[];
  loading: boolean;
  /** Whether the tray has ever been loaded, so an empty one can say so. */
  loaded: boolean;
  error: string | null;
  /**
   * Posts this window has opened since it started, by id.
   *
   * Held beside the server's `seen` rather than instead of it: the server is
   * the answer on a fresh window, and this is the answer while somebody is
   * looking. Merged in `runsOf` below, so nothing downstream has to know.
   */
  seenLocally: Set<string>;

  load: () => Promise<void>;
  post: (draft: StatusDraft, media?: Blob) => Promise<void>;
  markSeen: (statusId: string) => void;
  remove: (statusId: string) => Promise<void>;
  viewersOf: (statusId: string) => Promise<StatusViewer[]>;
  reset: () => void;
}

export const useStatusStore = create<StatusState>((set, get) => ({
  mine: [],
  others: [],
  loading: false,
  loaded: false,
  error: null,
  seenLocally: new Set(),

  load: async () => {
    set({ loading: true, error: null });
    try {
      const feed: StatusFeed = await api.statusFeed();
      // Captions are opened once, here, rather than in each place one is drawn:
      // decryption is asynchronous and everything downstream - the tray, the
      // player, the alt text - is not. A post we hold no key for keeps the
      // placeholder and is drawn like any other, because a friendship younger
      // than the post is not an error.
      const [mine, others] = await Promise.all([
        openCaptions(feed.mine),
        Promise.all(
          feed.others.map(async (run) => ({ ...run, statuses: await openCaptions(run.statuses) })),
        ),
      ]);
      set({ mine, others, loading: false, loaded: true });
    } catch (error) {
      // A deployment that has not been migrated yet answers 404 here, and a
      // missing status tray is not a reason for the home screen to fail - the
      // same allowance the block list gets in the friends store.
      set({ loading: false, loaded: true, error: message(error) });
    }
  },

  post: async (draft, media) => {
    // The directory is read now rather than held: this list is the audience,
    // and it is the list as it stands at the moment of posting - which is what
    // makes a friendship made afterwards not a way into what was posted before
    // it. See `sealStatus`.
    const devices = await api.statusAudience();
    const bytes = media ? new Uint8Array(await media.arrayBuffer()) : undefined;
    const sealed = await sealStatus({ caption: draft.caption, media: bytes }, devices);

    const entry = await api.postStatus(
      {
        ...draft,
        caption: sealed.caption,
        senderDeviceId: sealed.senderDeviceId,
        keys: sealed.keys,
        ...(sealed.media ? { mediaIv: sealed.media.iv } : {}),
        // What the bytes are once opened. The server cannot see them, so the
        // type has to travel beside them for the decoder to be handed one.
        ...(media?.type ? { mediaType: media.type } : {}),
      },
      sealed.media ? new Blob([sealed.media.ciphertext]) : undefined,
    );
    // Appended rather than refetched: the poster is looking at the tray they
    // just posted into, and the announcement that would refresh it is a round
    // trip away. The run is ordered oldest-first, so a new post goes last.
    // With the caption we typed, not the envelope that came back: this machine
    // has the words already, and opening what it just sealed would be a round
    // trip through its own key for no reason.
    set({ mine: [...get().mine, { ...entry, caption: draft.caption ?? null }] });
  },

  /**
   * Records a look, here and on the server.
   *
   * Local first and unconditionally: the ring has to stop glowing as the post
   * opens. The call behind it is fire-and-forget on purpose - a failed view
   * marker means somebody's status shows as unread again on the next window,
   * which is a smaller thing than a viewer that will not advance because a
   * request is in flight.
   */
  markSeen: (statusId) => {
    if (get().seenLocally.has(statusId)) return;
    set({ seenLocally: new Set(get().seenLocally).add(statusId) });
    void api.markStatusSeen(statusId).catch(() => undefined);
  },

  remove: async (statusId) => {
    await api.deleteStatus(statusId);
    releaseStatusMedia(statusId);
    set({ mine: get().mine.filter((status) => status.id !== statusId) });
  },

  viewersOf: (statusId) => api.statusViewers(statusId),

  reset: () =>
    set({ mine: [], others: [], loaded: false, error: null, seenLocally: new Set() }),
}));

/**
 * One person's run, with this window's own looks folded into `seen`.
 *
 * Every screen reads the tray through here rather than off the store, so the
 * "opened a second ago" case is answered the same way in the list, in the ring
 * and in the viewer.
 */
export function runsOf(state: StatusState): StatusFeedEntry[] {
  return state.others.map((run) => {
    const statuses = run.statuses.map((status) => ({
      ...status,
      seen: status.seen || state.seenLocally.has(status.id),
    }));
    return { ...run, statuses, unseen: statuses.some((status) => !status.seen) };
  });
}

/** The run belonging to one person, or null when they have posted nothing live. */
export function runOf(state: StatusState, userId: string): StatusFeedEntry | null {
  return runsOf(state).find((run) => run.author.id === userId) ?? null;
}

/**
 * What an avatar draws around itself: nothing, a solid ring, or a dim one.
 *
 * Kept as a function of the store rather than a boolean on each row because
 * every avatar in the app asks it, including ones that have never heard of the
 * status feature - see `Avatar`.
 */
export type StatusRing = 'none' | 'unseen' | 'seen';

export function ringFor(
  state: StatusState,
  userId: string | undefined,
  selfId: string | null,
): StatusRing {
  if (!userId) return 'none';
  if (userId === selfId) {
    return state.mine.length > 0 ? 'seen' : 'none';
  }
  const run = runOf(state, userId);
  if (!run) return 'none';
  return run.unseen ? 'unseen' : 'seen';
}

/**
 * Somebody posted, deleted, or aged out of a status. Announced rather than
 * carried, so the tray is re-read - one call, and the only way `seen` and
 * `viewCount` come back right for *this* reader.
 */
chatSocket.on((event) => {
  if (event.type === 'status.changed') void useStatusStore.getState().load();
});

/** Every caption in a run, opened. Order is kept: a run is drawn in it. */
function openCaptions(entries: StatusEntry[]): Promise<StatusEntry[]> {
  return Promise.all(
    entries.map(async (entry) => ({ ...entry, caption: await openStatusCaption(entry) })),
  );
}

function message(error: unknown): string {
  return error instanceof Error ? error.message : 'Something went wrong';
}

/**
 * "There is a newer BetweenUs than this one."
 *
 * One store for both clients, because the question is the same and only the
 * answer differs:
 *
 * - **Desktop.** A real update: ask GitHub, download the build this copy can
 *   actually apply, and hand the machine over to it. All of that is in the main
 *   process - see electron/updates.ts - and this drives it over the bridge.
 * - **Web.** A tab cannot install anything, so the whole update is a reload;
 *   what it watches for is the deployment changing under it. See
 *   services/web-update.ts.
 *
 * Which one is in play is not a build flag, it is whether the preload bridge is
 * there, exactly as everything else platform-specific in this app decides it.
 */
import { create } from 'zustand';
import { isDesktopRuntime } from '../services/platform';
import { watchForNewBuild } from '../services/web-update';

/** Where an update has got to. */
export type UpdateStage =
  | 'idle'
  | 'checking'
  | 'available'
  | 'downloading'
  | 'ready'
  | 'installing'
  | 'failed';

const DISMISSED_KEY = 'betweenus.updateDismissed';

/**
 * Dismissal is per version, so the next release is news again. A snooze in
 * days would be the other option; this is the same idea with nothing to keep
 * wound up, and the offer is one line at the top of the window rather than
 * something in the way.
 */
function dismissedVersion(): string {
  try {
    return localStorage.getItem(DISMISSED_KEY) ?? '';
  } catch {
    return '';
  }
}

function rememberDismissal(version: string): void {
  try {
    localStorage.setItem(DISMISSED_KEY, version);
  } catch {
    // A profile with no storage is asked again next launch. Not worth failing.
  }
}

interface UpdateState {
  /** Absent until the first check has said what this client can do. */
  info: DesktopUpdateInfo | null;
  stage: UpdateStage;
  offer: DesktopUpdateOffer | null;
  /** 0..1 while downloading, or -1 when the total size is unknown. */
  progress: number;
  error: string | null;
  /** Web only: the deployment has changed and this tab is behind it. */
  reloadReady: boolean;
  /** The version last waved away, so the next release is news again. */
  dismissed: string;
  /** True when there is something to say and it has not been waved away. */
  showing: () => boolean;

  /** Starts whichever watch this runtime has. Called once, from App. */
  start: () => () => void;
  check: () => Promise<void>;
  download: () => Promise<void>;
  install: () => Promise<void>;
  setChannel: (channel: DesktopUpdateChannel) => Promise<void>;
  dismiss: () => void;
}

/** How often the desktop app asks GitHub. Its rate limit is 60 an hour. */
const DESKTOP_POLL_MS = 6 * 60 * 60 * 1000;

export const useUpdateStore = create<UpdateState>((set, get) => ({
  info: null,
  stage: 'idle',
  offer: null,
  progress: 0,
  error: null,
  reloadReady: false,
  dismissed: dismissedVersion(),

  showing: () => {
    const { stage, offer, reloadReady, dismissed } = get();
    if (reloadReady) return true;
    if (stage === 'idle' || stage === 'checking' || stage === 'failed') return false;
    return offer !== null && offer.version !== dismissed;
  },

  start: () => {
    if (!isDesktopRuntime()) {
      return watchForNewBuild(() => set({ reloadReady: true }));
    }

    const bridge = window.betweenus;
    const stopProgress = bridge?.onUpdateProgress?.((progress) => set({ progress })) ?? (() => {});

    void bridge?.updateInfo?.().then((info) => {
      set({ info });
      // A build downloaded before the last quit is still waiting to be applied.
      if (info.downloaded) {
        set({ stage: 'ready' });
      }
    });

    // On launch and then rarely. A desktop release is not an hourly event, and
    // the check is also a button in settings for anybody who wants it sooner.
    void get().check();
    const timer = setInterval(() => void get().check(), DESKTOP_POLL_MS);

    return () => {
      clearInterval(timer);
      stopProgress();
    };
  },

  check: async () => {
    const bridge = window.betweenus;
    if (!bridge?.updateCheck) return;
    // A download in flight must not be replaced under itself by a poll.
    if (get().stage === 'downloading' || get().stage === 'installing') return;

    set({ stage: 'checking', error: null });
    try {
      const offer = await bridge.updateCheck();
      const info = (await bridge.updateInfo?.()) ?? get().info;
      const stage = offer
        ? info?.downloaded?.version === offer.version
          ? 'ready'
          : 'available'
        : 'idle';
      set({ info, offer, stage });
      // The "auto" in auto update. Waiting for a click before starting a
      // ninety-megabyte download meant the button that mattered - Restart and
      // install - was ten minutes away from every person who pressed the first
      // one. Nothing is ever installed without being asked: the download is
      // the slow half, and it is the half that can happen quietly.
      if (stage === 'available') await get().download();
    } catch (error) {
      set({ stage: 'failed', error: (error as Error).message });
    }
  },

  download: async () => {
    const { offer } = get();
    const bridge = window.betweenus;
    if (!offer || !bridge?.updateDownload) return;

    set({ stage: 'downloading', progress: 0, error: null });
    try {
      await bridge.updateDownload(offer);
      set({ stage: 'ready', progress: 1, info: (await bridge.updateInfo?.()) ?? get().info });
    } catch (error) {
      set({ stage: 'failed', error: (error as Error).message });
    }
  },

  install: async () => {
    const bridge = window.betweenus;
    if (!bridge?.updateInstall) return;

    set({ stage: 'installing', error: null });
    // On success the app is quitting, so there is nothing after this to set.
    const result = await bridge.updateInstall();
    if (!result.started) {
      set({ stage: 'ready', error: result.reason ?? 'The update could not be started.' });
    }
  },

  setChannel: async (channel) => {
    const settings = await window.betweenus?.setAppSettings?.({ updateChannel: channel });
    const info = get().info;
    // Said here rather than waited for: the settings screen draws the chosen
    // channel from `info`, and `info` was only refreshed by the check below -
    // so a check that failed, or was merely slow, left the button looking as
    // though the channel had not changed at all.
    set({
      offer: null,
      stage: 'idle',
      // The offer in hand was picked on the old channel and may not be on the
      // new one, so it is thrown away rather than left looking current.
      info: info ? { ...info, channel: settings?.updateChannel ?? channel } : info,
    });
    await get().check();
  },

  dismiss: () => {
    const { offer, reloadReady } = get();
    if (reloadReady) {
      set({ reloadReady: false });
      return;
    }
    if (!offer) return;
    rememberDismissal(offer.version);
    // The stage is kept: settings still shows what is waiting, it is only the
    // banner that goes away.
    set({ dismissed: offer.version });
  },
}));

/**
 * Voice-channel state: the client is connected to at most one at a time.
 *
 * The media itself is `mesh.ts` - one peer connection per other participant,
 * with no server in the path. This store decides when to join, captures the
 * local devices, flattens the mesh into tiles React can render, and tells
 * presence-service who is in the channel so other members see it without
 * joining.
 *
 * Identity here is a *peer* id, not a user id: one account can have two windows
 * open and each is its own end of its own connections. `userId` is carried
 * alongside for the things that are about the person rather than the
 * connection - finding their machine in the remote-desktop list, mostly.
 */
import { create } from 'zustand';
import type { CallPeer } from '@betweenus/shared-types';
import { api } from '../services/api';
import { callKeyForChannel } from '../services/e2ee';
import { Mesh, SLOTS, type Slot } from '../services/mesh';
import { presenceSocket } from '../services/socket';
import { isDesktopRuntime } from '../services/platform';
import { useAuthStore } from './auth';
import { useChatStore } from './chat';
import { useShareControlStore } from './shareControl';
import { useGameStore } from './game';
import { useListenStore } from './listen';
import { useAudioSettings } from './audioSettings';
import { startPushToTalk, stopPushToTalk } from '../services/push-to-talk';
import { notBeingHeard, type LinkStats } from '../services/call-stats';
import { visibleVideo } from '../services/media-presence';
import { NoiseGate } from '../services/mic-gate';
import {
  captureIsStale,
  chosenIsMissing,
  openAudioCapture,
  realDevices,
} from '../services/audio-devices';
import { playCallTone, rosterChange, setToneOutput } from '../services/call-tones';
import { micCapture, micEncoding, micProcessing, type VoiceSettings } from '../services/voice-quality';
import { shareOptions, type ShareIntent, type ShareSize } from '../services/share-quality';

/** The local participant's own key in every map here. */
export const LOCAL = 'local';

/** Application state sent over each encrypted peer data channel. */
const VOICE_STATE_TOPIC = 'betweenus.voice-state';
/**
 * `hold` is not one of the media slots: it says the sender has been pulled off
 * the call by something else - a phone call, on a phone - rather than that they
 * turned anything off. Optional, because a client too old to send it simply
 * never holds.
 */
type MediaState = Record<Slot, boolean> & { hold?: boolean };

interface MediaStateEnvelope {
  topic: typeof VOICE_STATE_TOPIC;
  media: MediaState;
}

export interface VoiceTile {
  /** Peer id, or `LOCAL`. Unique per connection, not per person. */
  identity: string;
  /** Who this is. Two tiles can share one, if somebody has two windows open. */
  userId: string;
  name: string;
  isLocal: boolean;
  speaking: boolean;
  micEnabled: boolean;
  /**
   * They are on another call and this one has their microphone shut.
   *
   * Different from `micEnabled`: they did not choose it, and it ends when the
   * other call does - which is worth saying rather than showing them as having
   * muted themselves.
   */
  held: boolean;
  videoTrack: MediaStreamTrack | null;
  audioTrack: MediaStreamTrack | null;
  /** Audio that came with a shared screen - a film's soundtrack, usually. */
  screenAudioTrack: MediaStreamTrack | null;
  /** Epoch ms of the last time this person was an active speaker. */
  lastSpokeAt: number;
}

/** A screen someone is sharing. Separate from their tile: both can be on. */
export interface VoiceShare {
  identity: string;
  userId: string;
  name: string;
  isLocal: boolean;
  track: MediaStreamTrack | null;
}

interface VoiceState {
  status: 'idle' | 'connecting' | 'connected';
  /**
   * When the call became a call, as a wall clock, for the duration on screen.
   *
   * The phone has shown this from the beginning and neither of the other two
   * clients did - not by choice: on Android an ongoing-call notification counts
   * itself, and a window or a tab has no notification to hang that on. So the
   * moment is recorded here and the clock is drawn.
   *
   * Set when the mesh comes up rather than when the join was asked for, because
   * a call that took four seconds to connect did not last four seconds longer
   * than it did.
   */
  connectedAt: number | null;
  channelId: string | null;
  /**
   * Where the call is, remembered rather than looked up.
   *
   * The call outlives the screen it was started from: switching servers throws
   * away `chat.channels`, so by the time the dock renders there is nothing left
   * to find the name in. Recording both at join is what lets the dock say where
   * you are and take you back to it.
   */
  channelName: string | null;
  callServerId: string | null;
  tiles: VoiceTile[];
  shares: VoiceShare[];
  /** Identity whose shared screen fills the stage, or null for the grid. */
  watching: string | null;
  micEnabled: boolean;
  /**
   * Push to talk: whether the key is down right now.
   *
   * Kept apart from `micEnabled`, which is the button and means "I intend to be
   * heard in this call at all". A muted microphone stays muted however long the
   * key is held, and letting the key go does not mute anybody.
   */
  talking: boolean;
  cameraEnabled: boolean;
  screenEnabled: boolean;
  /**
   * The display being shared, or null for a window. Handing control of a share
   * to somebody in the call needs it: a click arrives as a fraction of a screen
   * and a window has no such fraction - it can be dragged between two of them.
   */
  sharedDisplayId: string | null;
  /**
   * Whether media is end-to-end encrypted. Always true in a mesh: DTLS-SRTP
   * between two peers with nothing in between *is* end to end, and a peer whose
   * DTLS fingerprint is not signed with the channel key is never connected to.
   */
  encrypted: boolean;
  error: string | null;
  /** Clears the current error banner across all views. */
  dismissError: () => void;
  /**
   * Per-peer measurements, and a warning when they say something is wrong.
   *
   * Sampled for as long as the call lasts rather than only while a panel is
   * open, because the warning this exists for - a microphone sending nothing -
   * has to reach somebody who has no reason to go looking at statistics. Two
   * seconds, alongside the video poll the mesh already runs.
   */
  stats: LinkStats[];
  /**
   * Echo return loss enhancement, in dB, from the local microphone.
   *
   * A machine-wide reading rather than a per-link one: there is one canceller.
   * Null until a sample has been taken, and on builds that do not report it.
   * The settings screen turns this into the one sentence a person can act on.
   */
  echoErleDb: number | null;
  /** Set when this client is sending no audio while believing it is. */
  notHeard: boolean;
  /**
   * Who the call says is sharing their screen, or null for nobody.
   *
   * One share at a time, decided by the gateway. Kept even though the tiles
   * already carry a screen track each, because this is the *authority* and they
   * are the consequence: a peer that has taken over is holding it a moment
   * before its first frame arrives, and the button has to say so immediately.
   */
  screenHolder: string | null;

  join: (channelId: string) => Promise<void>;
  /**
   * `reason` is what ended the call when it was not the user: the mesh dying,
   * or this account joining the same call from another device. It survives the
   * hang-up so the client can say why the call went away, where clearing it
   * unconditionally left the message on screen for a few milliseconds.
   */
  leave: (reason?: string) => Promise<void>;
  toggleMic: () => Promise<void>;
  /** The push-to-talk key going down or coming up. */
  setTalking: (talking: boolean) => void;
  toggleCamera: () => Promise<void>;
  shareScreen: (
    source: ScreenSource | null,
    withAudio: boolean,
    intent: ShareIntent,
  ) => Promise<void>;
  /** `replaced` is set when somebody else took the screen, not the user. */
  stopScreenShare: (replaced?: boolean) => Promise<void>;
  watch: (identity: string | null) => void;
  /** Opens the channel the call is in, from wherever the client has wandered. */
  openCallChannel: () => Promise<void>;
}

/**
 * The live call. Outside the store because it is machinery rather than rendered
 * state, and because React must never re-render on a peer-connection event.
 */
let mesh: Mesh | null = null;

/** peerId -> what has arrived from them, by slot. */
const remoteTracks = new Map<string, Partial<Record<Slot, MediaStreamTrack | null>>>();
/** peerId -> the media switches the remote participant intentionally enabled. */
const remoteMediaStates = new Map<string, MediaState>();
let peers: CallPeer[] = [];
let speaking = new Set<string>();

/** What this client captured, so it can be stopped and replaced. */
const localTracks: Partial<Record<Slot, MediaStreamTrack | null>> = {};

/**
 * Identity -> when they last spoke. Kept outside the store because it is a
 * running record rather than rendered state: the grid sorts by it so whoever
 * just talked is on the first page.
 */
const lastSpoke = new Map<string, number>();

/**
 * The gate the microphone is published through, for as long as one call lasts.
 * Kept outside the store because it is a piece of audio plumbing rather than
 * rendered state: the sensitivity slider talks to it directly, which is what
 * lets a threshold change take effect without recapturing the track.
 */
let gate: NoiseGate | null = null;

/**
 * The gate's own audio context, one per window. Created on the first join,
 * which is a click, so it is never blocked by autoplay policy.
 */
let gateContext: AudioContext | null = null;

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : 'unknown error';
}

let joinCounter = 0;

export const useVoiceStore = create<VoiceState>((set, get) => ({
  status: 'idle',
  connectedAt: null,
  channelId: null,
  channelName: null,
  callServerId: null,
  tiles: [],
  shares: [],
  watching: null,
  micEnabled: false,
  talking: false,
  cameraEnabled: false,
  screenEnabled: false,
  sharedDisplayId: null,
  encrypted: false,
  error: null,
  dismissError: () => set({ error: null }),
  stats: [],
  echoErleDb: null,
  notHeard: false,
  screenHolder: null,

  join: async (channelId) => {
    if (get().channelId === channelId && get().status !== 'idle') return;

    const currentJoinId = ++joinCounter;

    const previousChannelId = get().channelId;
    if (previousChannelId) presenceSocket.send({ type: 'voice.leave', channelId: previousChannelId });
    teardown();

    const channel = useChatStore.getState().channels.find((item) => item.id === channelId);

    set({
      status: 'connecting',
      channelId,
      channelName: channel?.name ?? null,
      callServerId: channel?.serverId ?? useChatStore.getState().activeServerId,
      error: null,
      tiles: [],
      shares: [],
      watching: null,
      screenHolder: null,
    });

    try {
      const token = useAuthStore.getState().accessToken;
      if (!token) throw new Error('Not signed in');

      // The key is the channel's own, and it never leaves this machine: it is
      // used here only to sign this client's DTLS fingerprint, so the
      // signalling server cannot substitute one of its own and stand in the
      // middle. See mesh.ts.
      // Read here as well as per-link, so a channel this device holds no key
      // for fails the join outright instead of failing every peer in it. And
      // read *fresh*: a cached epoch is the one this client held when it last
      // opened the channel, and joining a call under a key everybody else has
      // already rotated past is the whole "their media key does not match"
      // failure, from the other side.
      const [, { iceServers }] = await Promise.all([
        callKeyForChannel(channelId, true),
        api.callIce(channelId),
      ]);

      if (joinCounter !== currentJoinId) return;

      const settings = useAudioSettings.getState().settings;

      const next = new Mesh({
        channelId,
        token,
        iceServers,
        // Re-read when the roster changes rather than snapshotted: see
        // `Mesh.channelKey`.
        channelKey: (refresh) => callKeyForChannel(channelId, refresh),
        onTrack: (peerId, slot, track) => {
          const slots = remoteTracks.get(peerId) ?? {};
          slots[slot] = track;
          remoteTracks.set(peerId, slots);
          refresh();
        },
        onPeers: (next_) => {
          // Before the list is replaced, and only once the call is up: the
          // roster that arrives on the way in is everybody already there, and
          // announcing them one by one is a fanfare nobody asked for.
          if (useVoiceStore.getState().status === 'connected') {
            const change = rosterChange(
              peers.map((peer) => peer.peerId),
              next_.map((peer) => peer.peerId),
            );
            if (change.joined) tone('join');
            if (change.left) tone('leave');
          }
          peers = next_;
          for (const peerId of [...remoteTracks.keys()]) {
            if (!peers.some((peer) => peer.peerId === peerId)) remoteTracks.delete(peerId);
          }
          for (const peerId of [...remoteMediaStates.keys()]) {
            if (!peers.some((peer) => peer.peerId === peerId)) remoteMediaStates.delete(peerId);
          }
          // Somebody who left cannot still be driving this machine.
          useShareControlStore.getState().peersChanged(peers);
          refresh();
        },
        onSpeaking: (next_) => {
          speaking = next_;
          const now = Date.now();
          for (const identity of speaking) lastSpoke.set(identity, now);
          refresh();
        },
        onData: (peer, payload) => {
          if (!receiveMediaState(peer, payload)) {
            useShareControlStore.getState().receive(peer, payload);
          }
        },
        onDataOpen: (peer) => publishMediaState([peer.peerId]),
        onProblem: (message) => {
          if (useVoiceStore.getState().channelId !== channelId) return;
          useVoiceStore.setState({ error: message });
        },
        onFatal: (message) => {
          if (get().channelId !== channelId) return;
          void get().leave(message);
        },
        onListen: (session) => {
          if (useVoiceStore.getState().channelId !== channelId) return;
          useListenStore.getState().receive(session);
        },
        onGame: (session) => {
          if (useVoiceStore.getState().channelId !== channelId) return;
          useGameStore.getState().receive(session);
        },
        onServerTime: (sample) => useListenStore.getState().sampleClock(sample),
        onScreenHolder: (peerId) => {
          if (useVoiceStore.getState().channelId !== channelId) return;
          set({ screenHolder: peerId });

          // Somebody else took it. Teams does this and it is the right way
          // round: the person who just pressed the button gets what they asked
          // for, and the previous share stops rather than the two of them
          // fighting over one stage. The capture is torn down here rather than
          // left running muted - a screen that is still being captured is still
          // a privacy question, whatever is being done with the frames.
          const local = useVoiceStore.getState();
          if (local.screenEnabled && peerId !== null && peerId !== mesh?.peerId()) {
            void get()
              .stopScreenShare(true)
              .then(() =>
                useVoiceStore.setState({
                  error: 'Somebody else started sharing, so your share stopped.',
                }),
              );
          }
        },
      });

      mesh = next;
      await next.setMicEncoding(micEncoding(settings));
      await next.join();

      if (joinCounter !== currentJoinId) {
        next.close();
        if (mesh === next) mesh = null;
        return;
      }

      let micEnabled = true;
      let micProblem: string | null = null;
      try {
        await openMicrophone(settings);
      } catch (error) {
        micEnabled = false;
        micProblem = `Connected, but microphone did not start (${messageOf(error)}). Use the mic button to retry.`;
      }

      if (joinCounter !== currentJoinId) {
        next.close();
        if (mesh === next) mesh = null;
        return;
      }

      presenceSocket.send({ type: 'voice.join', channelId });
      // Only while there is a call to talk into: a key that silences a
      // microphone nobody is listening to is a key that does nothing, and one
      // listened for all day is a listener for nothing.
      startPushToTalk();
      startStatsPoll();
      // Pointers and "give me the mouse" ride the peers' data channels, so they
      // exist for exactly as long as the mesh does.
      useShareControlStore.getState().attach(next);
      // The shared queue and the clock it runs on live for exactly as long as
      // the call does. It is not persisted anywhere: the queue two people built
      // while they worked has no meaning tomorrow.
      useListenStore.getState().attach(next);
      // The board goes the same way as the queue: it belongs to the call, it is
      // refereed by the gateway, and it is not written down anywhere.
      useGameStore.getState().attach(next);

      set({
        error: micProblem,
        status: 'connected',
        connectedAt: Date.now(),
        encrypted: true,
        micEnabled,
        cameraEnabled: false,
        screenEnabled: false,
        sharedDisplayId: null,
      });
      publishMediaState();
      refresh();
      // Your own arrival, the way Discord marks it: the confirmation that the
      // channel is live is the same sound everyone else in it just heard.
      tone('join');
    } catch (error) {
      if (joinCounter !== currentJoinId) return;
      teardown();
      set({
        status: 'idle',
        connectedAt: null,
        channelId: null,
        channelName: null,
        callServerId: null,
        error: error instanceof Error ? error.message : 'Could not join the voice channel',
      });
    }
  },

  leave: async (reason) => {
    // Only for a call that was actually up: leaving one that never connected
    // has nothing to say goodbye to.
    if (get().status === 'connected') tone('leave');
    joinCounter++;
    stopPushToTalk();
    stopStatsPoll();
    const { channelId } = get();
    if (channelId) presenceSocket.send({ type: 'voice.leave', channelId });
    useShareControlStore.getState().detach();
    useListenStore.getState().detach();
    useGameStore.getState().detach();
    teardown();
    // Close PiP overlay window if open
    void window.betweenus?.closePip();
    set({
      status: 'idle',
      connectedAt: null,
      channelId: null,
      channelName: null,
      callServerId: null,
      tiles: [],
      shares: [],
      watching: null,
      micEnabled: false,
      talking: false,
      cameraEnabled: false,
      screenEnabled: false,
      sharedDisplayId: null,
      screenHolder: null,
      error: reason ?? null,
    });

    // Switch to server's text channel if currently viewing a voice channel
    const activeChannel = useChatStore.getState().activeChannel();
    if (activeChannel?.type === 'VOICE') {
      const channels = useChatStore.getState().channels;
      const textChannel = channels.find(
        (c) => c.serverId === activeChannel.serverId && c.type === 'TEXT',
      );
      if (textChannel) {
        void useChatStore.getState().selectChannel(textChannel.id);
      }
    }
  },

  toggleMic: async () => {
    const { micEnabled, status } = get();
    if (!mesh || status !== 'connected') return;

    try {
      if (micEnabled) {
        await closeMicrophone();
        set({ micEnabled: false, error: null });
        publishMediaState();
        refresh();
        return;
      }
      await openMicrophone(useAudioSettings.getState().settings);
      set({ micEnabled: true, error: null });
      publishMediaState();
      refresh();
    } catch (error) {
      set({ error: `Microphone: ${messageOf(error)}` });
      refresh();
    }
  },

  /**
   * Opens or closes the captured microphone without republishing anything.
   *
   * `enabled` on the raw capture rather than a track swap: the gate downstream
   * of it keeps running and keeps its worklet, so a key held for a syllable
   * costs nothing and letting go is silent within a block. Republishing per
   * keypress would renegotiate the call several times a sentence.
   */
  setTalking: (talking) => {
    if (get().talking === talking) return;
    set({ talking });
    applyTalking();
  },

  toggleCamera: async () => {
    const { cameraEnabled, status } = get();
    if (!mesh || status !== 'connected') return;

    try {
      if (cameraEnabled) {
        stopLocal('camera');
        await mesh.setTrack('camera', null);
        set({ cameraEnabled: false, error: null });
        publishMediaState();
        refresh();
        return;
      }

      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      const track = stream.getVideoTracks()[0] ?? null;
      localTracks.camera = track;
      await mesh.setTrack('camera', track);
      set({ cameraEnabled: Boolean(track), error: null });
      publishMediaState();
      refresh();
    } catch (error) {
      set({ error: `Camera: ${messageOf(error)}` });
      refresh();
    }
  },

  /**
   * `source` is what the user picked in the picker; passing null shares the
   * primary screen, which is what a runtime without the Electron bridge gets.
   * The main process has to be told before capture starts - see electron/main.ts.
   *
   * Sharing system audio captures the machine's whole output mix, and that mix
   * includes the call itself coming out of the speakers - so without asking for
   * anything else, a share re-broadcasts everyone in the room back at them and
   * they hear themselves. `restrictOwnAudio` is the constraint that leaves this
   * app's own output out of the capture, which is exactly the difference wanted:
   * the film's soundtrack travels, the voices in the call do not.
   *
   * Everything about how it is *encoded* lives in `share-quality.ts`, including
   * why the defaults were never going to be watchable.
   */
  shareScreen: async (source, withAudio, intent) => {
    const { status } = get();
    if (!mesh || status !== 'connected') return;

    // Claimed before the picker's answer is turned into a capture, so the
    // person already sharing stops while this one is still starting. Claiming
    // afterwards would mean a moment with two live captures, which is the
    // moment somebody's private window is on somebody else's screen.
    mesh.claimScreen();

    try {
      await window.betweenus?.selectScreenSource(source?.id ?? '', withAudio);
      const options = shareOptions(
        intent,
        await captureSize(source),
        {
          // A soundtrack only when the share is one: the processing that makes
          // speech clear is the processing that ruins music, and a shared
          // terminal's beeps are not worth stereo Opus.
          music: intent === 'motion',
        },
        useAudioSettings.getState().settings.share,
      );
      if (!withAudio) options.capture.audio = false;

      const stream = await navigator.mediaDevices.getDisplayMedia({
        video: {
          width: { ideal: options.capture.video.width, max: Math.max(3840, options.capture.video.width) },
          height: { ideal: options.capture.video.height, max: Math.max(2160, options.capture.video.height) },
          frameRate: { ideal: options.capture.video.frameRate, max: 60 },
        },
        audio: options.capture.audio === false ? false : options.capture.audio,
      } as DisplayMediaStreamOptions);

      const video = stream.getVideoTracks()[0] ?? null;
      const audio = stream.getAudioTracks()[0] ?? null;
      // The encoder is told what it is looking at: a text profile keeps edges
      // sharp and drops frames, a motion one does the opposite.
      if (video) {
        video.contentHint = options.capture.contentHint;
        const settings = video.getSettings();
        if (settings.width && settings.height) {
          const realOptions = shareOptions(
            intent,
            { width: settings.width, height: settings.height },
            { music: intent === 'motion' },
            useAudioSettings.getState().settings.share,
          );
          options.publish = realOptions.publish;
        }
      }

      localTracks.screen = video;
      localTracks.screenAudio = audio;
      await mesh.setSharePublish(options.publish);
      await mesh.setTrack('screen', video);
      await mesh.setTrack('screenAudio', audio);

      // The OS "Stop sharing" bar, and the capture ending for any other reason,
      // never touch the button in this app - so the share stayed up with a dead
      // track behind it and everyone else kept staring at the last frame.
      // Ending the capture has to mean the same thing however it was ended.
      video?.addEventListener('ended', () => void get().stopScreenShare(), { once: true });

      // Watch your own share, so you can see what the others are seeing.
      set({
        screenEnabled: Boolean(video),
        // Null for a window, and for a runtime with no source list: control of
        // a share is refused unless a whole display is on the wire.
        sharedDisplayId: source?.displayId ?? null,
        error: null,
        watching: LOCAL,
      });
      publishMediaState();
      refresh();
    } catch (error) {
      set({ error: `Screen share: ${messageOf(error)}` });
      refresh();
    }
  },

  stopScreenShare: async (replaced = false) => {
    const { status, watching } = get();
    if (!mesh || status !== 'connected') return;

    // Releasing a claim somebody else already took would take the screen away
    // from them, so a share that stopped *because* it was replaced says
    // nothing. The gateway ignores it either way; not sending it keeps the two
    // ends telling the same story.
    if (!replaced) mesh.releaseScreen();

    try {
      stopLocal('screen');
      stopLocal('screenAudio');
      await mesh.setTrack('screen', null);
      await mesh.setTrack('screenAudio', null);
      await mesh.setSharePublish(null);
      // Control cannot outlive the share it was given over.
      useShareControlStore.getState().stop();

      set({
        screenEnabled: false,
        sharedDisplayId: null,
        error: null,
        watching: watching === LOCAL ? null : watching,
      });
      publishMediaState();
      refresh();
    } catch (error) {
      set({ error: `Screen share: ${messageOf(error)}` });
      refresh();
    }
  },

  watch: (identity) => set({ watching: identity }),

  openCallChannel: async () => {
    const { channelId, callServerId } = get();
    if (!channelId) return;

    const chat = useChatStore.getState();
    // The channel list is per server, so getting back to a call started on
    // another one means loading that server first - which is also what puts the
    // voice channel back in `channels`, where `selectChannel` looks for it.
    // `view` is in the condition because the home screen covers the server one:
    // being on the right server is not enough if the client is looking at a
    // direct message.
    if (callServerId && (chat.activeServerId !== callServerId || chat.view !== 'server')) {
      await chat.selectServer(callServerId);
    }
    await useChatStore.getState().selectChannel(channelId);
  },
}));

/** One tone, unless this machine has turned them off. */
function tone(which: 'join' | 'leave'): void {
  const settings = useAudioSettings.getState().settings;
  if (!settings.callTones) return;
  setToneOutput(settings.outputDeviceId);
  playCallTone(which);
}

/** Re-derives the rendered view from the mesh. Cheap; called on every event. */
function refresh(): void {
  const state = useVoiceStore.getState();
  if (state.status === 'idle') return;

  const next = snapshot();
  // A share that ends takes the stage with it. Leaving `watching` pointed at
  // somebody who has stopped sharing is a black rectangle with their name on it
  // and no way out of it but leaving the call.
  const watched = state.watching;
  const stillSharing = next.shares.some((share) => share.identity === watched);
  useVoiceStore.setState(watched === null || stillSharing ? next : { ...next, watching: null });
}

function snapshot(): { tiles: VoiceTile[]; shares: VoiceShare[] } {
  const state = useVoiceStore.getState();
  const self = useAuthStore.getState().user;

  const localTile: VoiceTile = {
    identity: LOCAL,
    userId: self?.id ?? LOCAL,
    name: self?.displayName || self?.username || 'You',
    isLocal: true,
    speaking: Boolean(state.micEnabled && speaking.has(LOCAL)),
    micEnabled: state.micEnabled,
    // Nothing takes the audio off a desktop window the way a phone call takes
    // it off a phone, so this end is never held.
    held: false,
    videoTrack: localTracks.camera ?? null,
    // Never played back locally: hearing your own microphone is a howl.
    audioTrack: null,
    screenAudioTrack: null,
    lastSpokeAt: lastSpoke.get(LOCAL) ?? 0,
  };

  const tiles: VoiceTile[] = [
    localTile,
    ...peers.map((peer) => {
      const slots = remoteTracks.get(peer.peerId) ?? {};
      const media = remoteMediaStates.get(peer.peerId);
      const micEnabled = media?.mic ?? Boolean(slots.mic);
      // A camera that has stopped is taken down by its owner saying so, never
      // by frames stopping - see `media-presence.ts`.
      const camera = visibleVideo(media?.camera, slots.camera ?? null);
      return {
        identity: peer.peerId,
        userId: peer.userId,
        name: peer.username,
        isLocal: false,
        speaking: Boolean(micEnabled && speaking.has(peer.peerId)),
        // Track mute means packets are not arriving right now; it does not
        // reliably mean the participant pressed their microphone button.
        micEnabled,
        held: media?.hold === true,
        videoTrack: camera,
        audioTrack: slots.mic ?? null,
        screenAudioTrack: slots.screenAudio ?? null,
        lastSpokeAt: lastSpoke.get(peer.peerId) ?? 0,
      };
    }),
  ];

  const shares: VoiceShare[] = [];
  if (state.screenEnabled && localTracks.screen) {
    shares.push({
      identity: LOCAL,
      userId: localTile.userId,
      name: localTile.name,
      isLocal: true,
      track: localTracks.screen,
    });
  }
  for (const peer of peers) {
    // Whether they are still sharing is what they say, not whether a frame
    // arrived this second. A still screen decodes nothing for minutes, and
    // reading that as the end is what closed the stage under a viewer and
    // offered them the share again.
    const track = visibleVideo(
      remoteMediaStates.get(peer.peerId)?.screen,
      remoteTracks.get(peer.peerId)?.screen ?? null,
    );
    if (!track) continue;
    shares.push({
      identity: peer.peerId,
      userId: peer.userId,
      name: peer.username,
      isLocal: false,
      track,
    });
  }

  return { tiles, shares };
}

function currentMediaState(): MediaState {
  const { micEnabled, cameraEnabled, screenEnabled } = useVoiceStore.getState();
  return {
    mic: micEnabled,
    camera: cameraEnabled,
    screen: screenEnabled,
    screenAudio: screenEnabled && Boolean(localTracks.screenAudio),
  };
}

function publishMediaState(to?: string[]): void {
  mesh?.sendData({ topic: VOICE_STATE_TOPIC, media: currentMediaState() } satisfies MediaStateEnvelope, to);
}

/** Returns true when the payload belongs to this store, even if malformed. */
function receiveMediaState(peer: CallPeer, payload: unknown): boolean {
  if (typeof payload !== 'object' || payload === null) return false;

  const envelope = payload as { topic?: unknown; media?: unknown };
  if (envelope.topic !== VOICE_STATE_TOPIC) return false;
  if (typeof envelope.media !== 'object' || envelope.media === null) return true;

  const media = envelope.media as Partial<Record<Slot, unknown>>;
  if (!SLOTS.every((slot) => typeof media[slot] === 'boolean')) return true;

  remoteMediaStates.set(peer.peerId, {
    mic: media.mic === true,
    camera: media.camera === true,
    screen: media.screen === true,
    screenAudio: media.screenAudio === true,
    hold: (media as { hold?: unknown }).hold === true,
  });
  refresh();
  return true;
}

/**
 * Captures the microphone, puts the gate on it, and sends the gated track.
 *
 * The gate rather than the raw capture is what goes on the wire, which is the
 * whole point of it: what the gate closes never reaches anybody.
 */
async function openMicrophone(settings: VoiceSettings): Promise<void> {
  if (!mesh) return;

  const stream = await openAudioCapture(micCapture(settings));
  const raw = stream.getAudioTracks()[0];
  if (!raw) throw new Error('That microphone handed back no audio');

  localTracks.mic = raw;
  await mesh.setMicEncoding(micEncoding(settings));
  await mesh.setTrack('mic', (await attachGate(raw, settings)) ?? raw);
  // Opening the microphone *is* the button being on, so it is recorded here
  // rather than by each caller afterwards.
  //
  // This is the whole of "I have to switch microphones every time I join".
  // `applyTalking` below reads `micEnabled` to decide whether the capture may
  // pass audio, and both callers that start a microphone - the join and the mic
  // button - used to set it only after this function returned. So the capture
  // at the top of every call was opened and immediately switched off against a
  // flag that was still false, and stayed off: nothing re-runs `applyTalking`
  // on its own. Changing the input device recaptured through here with the flag
  // by then true, which is why switching devices "fixed" it and why which
  // device was picked never mattered - the device was never the problem.
  //
  // Unless the call was left while the capture was still opening, in which case
  // there is no call for the button to be on for.
  if (useVoiceStore.getState().status === 'idle') return;
  useVoiceStore.setState({ micEnabled: true });
  // A microphone opened while push to talk is on starts closed, which is what
  // push to talk means. Opening it live for the instant between capture and the
  // first key press is the bug this line exists to prevent.
  applyTalking();
}

/**
 * Whether the microphone should be passing audio right now.
 *
 * Two conditions, and they are different questions: the button says whether
 * this client means to be heard in the call at all, and push to talk says
 * whether the key is down at this instant. An open mic (push to talk off) is
 * the first alone.
 */
function shouldPassAudio(): boolean {
  const { micEnabled, talking } = useVoiceStore.getState();
  if (!micEnabled) return false;
  return useAudioSettings.getState().settings.pushToTalk ? talking : true;
}

/**
 * Applies that to the capture, and to what everyone else sees.
 *
 * The raw track is the one switched, not the gate's output: the gate keeps
 * running either way, so nothing is renegotiated and nothing has to be rebuilt
 * when the key comes back down. The speaking ring is cleared in the same
 * breath, or a released key leaves the last "talking" state on screen.
 */
function applyTalking(): void {
  const raw = localTracks.mic;
  const pass = shouldPassAudio();
  if (raw) raw.enabled = pass;
  if (!pass) mesh?.setLocalSpeaking(false);
  refresh();
}

// --- Statistics --------------------------------------------------------------

let statsTimer: number | null = null;
/** Consecutive samples that carried no outbound audio at all. */
let quietSamples = 0;

/**
 * Every two seconds: often enough that a number on screen feels live and that a
 * dead microphone is noticed inside ten, slow enough that the difference
 * between two samples is a rate rather than noise.
 */
const STATS_POLL_MS = 2_000;

function startStatsPoll(): void {
  if (statsTimer !== null) return;
  quietSamples = 0;

  const tick = (): void => {
    const current = mesh;
    if (!current) return;
    void current.stats().then((stats) => {
      // The mesh may have gone while the sample was in flight; writing then
      // would leave numbers from a call that has ended on screen.
      if (mesh !== current) return;

      const intendsToSend = shouldPassAudio();
      quietSamples = stats.some((link) => link.sendingAudio) ? 0 : quietSamples + 1;
      useVoiceStore.setState({
        stats,
        echoErleDb: current.echoReturnLossEnhancementDb,
        notHeard: notBeingHeard(intendsToSend, stats, quietSamples),
      });
    });
  };

  statsTimer = window.setInterval(tick, STATS_POLL_MS);
  tick();
}

function stopStatsPoll(): void {
  if (statsTimer !== null) window.clearInterval(statsTimer);
  statsTimer = null;
  quietSamples = 0;
  useVoiceStore.setState({ stats: [], echoErleDb: null, notHeard: false });
}

async function closeMicrophone(): Promise<void> {
  await mesh?.setTrack('mic', null);
  await gate?.destroy().catch(() => undefined);
  gate = null;
  mesh?.setLocalSpeaking(false);
  stopLocal('mic');
}

/**
 * Puts the gate on the captured microphone and returns what should be sent.
 *
 * Never fatal: a call without a gate is the call this app had before the gate
 * existed, and losing the microphone over a failed processor would be a far
 * worse trade.
 */
async function attachGate(
  track: MediaStreamTrack,
  settings: VoiceSettings,
): Promise<MediaStreamTrack | null> {
  try {
    await gate?.destroy().catch(() => undefined);
    gate = new NoiseGate(settings.gateThresholdDb);

    gateContext ??= new AudioContext();
    await gateContext.resume().catch(() => undefined);

    // The gate already measures the level on the audio thread, so local
    // speaking is free rather than a second analyser doing the same arithmetic.
    gate.onLevel((level) => mesh?.setLocalSpeaking(level.open));
    await gate.init({ track, audioContext: gateContext });

    return gate.processedTrack ?? null;
  } catch (error) {
    gate = null;
    console.warn('[voice.ts] microphone gate not attached:', error);
    return null;
  }
}

function stopLocal(slot: Slot): void {
  const track = localTracks[slot];
  localTracks[slot] = null;
  track?.stop();
  // Every path out of a share comes through here - the button, the OS bar, and
  // leaving the call - so this is the one place that can tell the main process
  // the desktop no longer has to be held in composed flip for it.
  if (slot === 'screen' && track) void window.betweenus?.releaseScreenCapture();
}

/** Ends the call's machinery without touching rendered state. */
function teardown(): void {
  void gate?.destroy().catch(() => undefined);
  gate = null;
  mesh?.close();
  mesh = null;
  for (const slot of SLOTS) stopLocal(slot);
  remoteTracks.clear();
  remoteMediaStates.clear();
  peers = [];
  speaking = new Set();
  lastSpoke.clear();
}

/**
 * The real pixel size of what is about to be captured.
 *
 * A screen is exactly its display. A window is whatever size it happens to be,
 * which nothing here can ask for, so it gets the biggest display as a ceiling -
 * a capture is never scaled *up* to meet one, so an over-estimate costs
 * nothing while an under-estimate is a permanently soft picture.
 */
async function captureSize(source: ScreenSource | null): Promise<ShareSize> {
  const screenWidth = typeof window !== 'undefined' && window.screen ? window.screen.width : 1920;
  const screenHeight = typeof window !== 'undefined' && window.screen ? window.screen.height : 1080;
  const dpr = typeof window !== 'undefined' && window.devicePixelRatio ? window.devicePixelRatio : 1;
  const fallback = {
    width: Math.max(1920, Math.round(screenWidth * dpr)),
    height: Math.max(1080, Math.round(screenHeight * dpr)),
  };
  const displays = (await window.betweenus?.screenDisplays()) ?? [];
  if (displays.length === 0) return fallback;

  const exact = source?.displayId
    ? displays.find((display) => display.id === source.displayId)
    : undefined;
  if (exact) return { width: exact.width, height: exact.height };

  return displays.reduce(
    (biggest, display) =>
      display.width * display.height > biggest.width * biggest.height
        ? { width: display.width, height: display.height }
        : biggest,
    fallback,
  );
}

/**
 * Voice settings changed while a call is running.
 *
 * Three different costs, so three different paths: a threshold is a message to
 * the gate on the audio thread, the three processing switches are a constraint
 * applied to the track that is already open, and a different device or a
 * different mode is the only one that needs the microphone recaptured - the
 * bitrate and channel count are fixed when the connection is negotiated, and
 * only a new capture picks up a new device.
 */
async function applyAudioSettings(next: VoiceSettings, previous: VoiceSettings): Promise<void> {
  const { status, micEnabled } = useVoiceStore.getState();
  if (!mesh || status !== 'connected') return;

  // Output device is the sink's business, not the mesh's - see MediaSink.
  if (!micEnabled) return;

  // Turning push to talk off has to reopen the microphone there and then.
  // Without this it stays shut until the next time the key is pressed, which
  // is a setting that appears not to work.
  if (next.pushToTalk !== previous.pushToTalk) applyTalking();

  if (next.mode !== previous.mode || next.inputDeviceId !== previous.inputDeviceId) {
    await closeMicrophone();
    await openMicrophone(next).catch(() => undefined);
    return;
  }

  if (next.gateThresholdDb !== previous.gateThresholdDb) {
    gate?.setThreshold(next.gateThresholdDb);
  }

  const track = localTracks.mic;
  if (track) await track.applyConstraints(micProcessing(next)).catch(() => undefined);
}

useAudioSettings.subscribe((state, previous) => {
  if (state.settings === previous.settings) return;
  void applyAudioSettings(state.settings, previous.settings);
});

/**
 * The hardware changed under a live call.
 *
 * Nothing used to happen here, and that is the whole of "it keeps picking the
 * wrong microphone": a capture is bound to a device when it opens, so plugging
 * in a headset moved the operating system's default and left this call on the
 * webcam it started with. Unplugging and plugging the *chosen* device back in
 * was worse - the capture had already fallen back and never came home.
 *
 * `captureIsStale` decides; the debounce is because one headset arriving is
 * several `devicechange` events as its microphone, its speakers and its
 * grouping are registered one after another.
 */
const DEVICE_SETTLE_MS = 400;
let deviceSettleTimer: number | null = null;

/**
 * Lets go of a pinned device once that device is actually gone.
 *
 * A device id is remembered forever; the operating system's default is not.
 * Choose a headset once and every later call is pinned to it, so the call after
 * the headset is put away opens a microphone that is in a drawer. With
 * `followSystemDevices` on, the pin is dropped when the pinned device is no
 * longer connected and the system default wins.
 *
 * *That device*, and not merely "the hardware changed", which is what this used
 * to test and is the whole of "I have to pick my microphone again every time".
 * A device change is not a signal about the chosen device: a webcam arriving, a
 * monitor with speakers waking, a headset pairing - and, on the first call of
 * every session, the microphone permission being granted, which turns the
 * pre-permission placeholder list into the real one and is itself a
 * `devicechange`. Every one of those used to throw away a perfectly good
 * choice and fall back to a system default that, on the machine where the
 * system default is the wrong microphone, is silence.
 *
 * Dropping the pin is all this does: the settings subscription below recaptures
 * the microphone, and `MediaSink` re-points the speakers, both because the
 * setting changed. It runs whether or not a call is up, so the choice is
 * already right when the next one starts.
 */
function unpinDevices(devices: MediaDeviceInfo[]): void {
  const { settings, update } = useAudioSettings.getState();
  if (!settings.followSystemDevices) return;

  const patch: Partial<VoiceSettings> = {};
  if (chosenIsMissing(devices, 'audioinput', settings.inputDeviceId)) patch.inputDeviceId = null;
  if (chosenIsMissing(devices, 'audiooutput', settings.outputDeviceId)) patch.outputDeviceId = null;
  if (Object.keys(patch).length === 0) return;

  update(patch);
}

async function followDeviceChange(devices: MediaDeviceInfo[]): Promise<void> {
  const { status, micEnabled } = useVoiceStore.getState();
  if (!mesh || status !== 'connected' || !micEnabled) return;

  const settings = useAudioSettings.getState().settings;
  const captured = localTracks.mic?.getSettings().deviceId ?? null;
  if (!captureIsStale(settings.inputDeviceId, captured, devices)) return;

  await closeMicrophone();
  await openMicrophone(settings).catch(() => undefined);
}

if (typeof navigator !== 'undefined' && navigator.mediaDevices) {
  navigator.mediaDevices.addEventListener('devicechange', () => {
    if (deviceSettleTimer !== null) window.clearTimeout(deviceSettleTimer);
    deviceSettleTimer = window.setTimeout(() => {
      deviceSettleTimer = null;
      void (async () => {
        // Enumerated once here rather than read from the shared list: that list
        // is refreshed by the same event and may not have answered yet. Both
        // decisions below need it, and they have to agree about what is
        // plugged in.
        const devices = realDevices(
          await navigator.mediaDevices.enumerateDevices().catch(() => []),
        );
        // Before the recapture, so the recapture picks up the new choice rather
        // than reopening the device that has just been unplugged.
        unpinDevices(devices);
        await followDeviceChange(devices);
      })();
    }, DEVICE_SETTLE_MS);
  });
}

// Taking control of a share changes what its latency should be: a pointer that
// arrives two frames late is unusable, where two frames of cushion on something
// you are only watching is invisible.
useShareControlStore.subscribe((state, previous) => {
  if (state.driving === previous.driving) return;
  mesh?.setDriving(state.driving !== null);
});

/**
 * In a browser, closing the tab or reloading it ends the call outright - the
 * peer connections go with the page, and there is no undo. So the web client
 * asks the browser to confirm first, and only while a call is up.
 *
 * Desktop is not in this: an Electron window that closes has a tray icon and a
 * main process behind it, and the prompt would be a nuisance rather than a
 * rescue. `isDesktopRuntime` is the same runtime split the rest of the client
 * uses - see services/platform.ts.
 *
 * The browser writes the wording. All a page may do is ask for the prompt;
 * anything it puts in `returnValue` is ignored by every current browser.
 */
function warnBeforeUnload(event: BeforeUnloadEvent): void {
  event.preventDefault();
  event.returnValue = '';
}

if (typeof window !== 'undefined' && !isDesktopRuntime()) {
  useVoiceStore.subscribe((state, previous) => {
    const inCall = state.status !== 'idle';
    if (inCall === (previous.status !== 'idle')) return;
    // Registered only for the length of the call: an unconditional handler
    // makes every reload of the app a confirmation dialog.
    if (inCall) window.addEventListener('beforeunload', warnBeforeUnload);
    else window.removeEventListener('beforeunload', warnBeforeUnload);
  });
}

if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    void useVoiceStore.getState().leave();
  });
}

