// Rate-limit smoke: the burst a fixed window let through.
//
//   node rate-limit-smoke.mjs
//
// A fixed window keys its counter by `floor(now / window)`, so the budget
// refills all at once at a boundary an attacker can compute as easily as the
// server can. Twenty attempts in the last second of one minute and twenty in the
// first second of the next is forty attempts in two seconds, out of a limit that
// reads "20 per minute". The average was never the problem; the burst is the
// only thing a credential-stuffing run cares about.
//
// A sliding window measures from now, so there is no boundary to straddle. That
// is the property this file is for, and demonstrating it honestly would mean
// waiting out most of a sixty-second window - so it is demonstrated the fast way
// instead: seed the sorted set with entries at a chosen age, then make one real
// request and see what the service decides.
//
// Seeding is legitimate here rather than a cheat, because the thing under test
// is exactly "which entries still count". The alternative is a test that sleeps
// for thirty-five seconds and proves the same thing less precisely.
//
// The address comes from `x-real-ip`, which `clientAddress` trusts because in a
// deployment Nginx is the only thing that can set it. That is what lets this
// pick a fresh bucket per run instead of fighting over 127.0.0.1's.
//
// NEEDS auth-service and Redis.
import Redis from 'ioredis';

const AUTH = process.env.RATE_SMOKE_AUTH ?? 'http://127.0.0.1:3001';
const REDIS_URL = process.env.REDIS_URL ?? 'redis://127.0.0.1:6379';

/** From `CREDENTIALS_RATE_LIMIT` - read here rather than guessed at. */
const LIMIT = 20;
const WINDOW_MS = 60_000;

let failures = 0;
const ok = (label, condition, detail = '') => {
  if (!condition) {
    console.error(`FAIL ${label} ${detail}`);
    failures += 1;
    return;
  }
  console.log(`${label} ok`, detail);
};

const redis = new Redis(REDIS_URL, { maxRetriesPerRequest: 1 });

/** One login attempt from `address`. Returns the HTTP status, nothing else. */
const attempt = async (address, email = 'nobody@betweenus.local') => {
  const response = await fetch(`${AUTH}/api/v1/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-real-ip': address },
    body: JSON.stringify({ email, password: 'definitely-wrong-1' }),
  });
  return response.status;
};

/** A fresh address per case, so no case can be affected by another. */
let n = 0;
const nextAddress = () => `198.51.100.${(n += 1)}`;

const addrKey = (address) => `ratelimit:auth-credentials:addr:${address}`;

/** Puts `count` entries in the bucket, all `ageMs` old. */
const seed = async (address, count, ageMs) => {
  const at = Date.now() - ageMs;
  const members = [];
  for (let i = 0; i < count; i += 1) members.push(at, `seed-${address}-${i}`);
  await redis.zadd(addrKey(address), ...members);
};

try {
  // --- the limit is enforced at all -----------------------------------------
  //
  // Seeded to one below the budget, so a single real request is the one that
  // reaches it and the next is the one refused. Cheaper than twenty round trips
  // and it fails for the same reasons.
  const enforced = nextAddress();
  await seed(enforced, LIMIT - 1, 1_000);
  ok('the request that reaches the limit is allowed', (await attempt(enforced)) === 401);
  ok('and the one past it is refused', (await attempt(enforced)) === 429);

  // --- what has aged out does not count --------------------------------------
  //
  // A full budget's worth, all older than the window. Nothing here may count, so
  // the request lands in an empty bucket. If the prune's comparison were the
  // wrong way round this is the case that would say so.
  const aged = nextAddress();
  await seed(aged, LIMIT * 3, WINDOW_MS + 5_000);
  ok('entries older than the window are not counted', (await attempt(aged)) === 401);
  ok(
    'and they are pruned rather than left to accumulate',
    (await redis.zcard(addrKey(aged))) === 1,
  );

  // --- the burst a fixed window let through ----------------------------------
  //
  // The case this whole change is for. A full budget spent half a window ago is
  // still inside a window measured from now, so the next request is refused.
  //
  // Under the fixed window this replaced, entries that old were as likely as not
  // to be in the *previous* key - and this request would have been the first of
  // a fresh twenty.
  const straddling = nextAddress();
  await seed(straddling, LIMIT, WINDOW_MS / 2);
  ok(
    'a budget spent half a window ago still counts',
    (await attempt(straddling)) === 429,
    'this is the burst a fixed window allowed',
  );

  // ...and the same entries a moment past the window do not, which is what stops
  // the paragraph above from being "the limiter refuses everything".
  const expired = nextAddress();
  await seed(expired, LIMIT, WINDOW_MS + 1_000);
  ok('and the same budget a window ago does not', (await attempt(expired)) === 401);

  // --- the bucket cannot be grown without bound ------------------------------
  //
  // A sorted set holds a member per request, so an address being hammered is a
  // way to spend the service's memory through the endpoint meant to stop that.
  // Entries above the cap are trimmed, and trimming changes no answer: the count
  // is only compared against the budget, and the cap is above it.
  const flooded = nextAddress();
  await seed(flooded, LIMIT * 20, 1_000);
  ok('a flooded bucket is still refused', (await attempt(flooded)) === 429);
  const held = await redis.zcard(addrKey(flooded));
  ok('and is trimmed rather than kept whole', held <= LIMIT * 2, `${held} entries`);

  // --- nothing is left behind ------------------------------------------------
  const ttl = await redis.pttl(addrKey(flooded));
  ok('a bucket carries a TTL', ttl > 0 && ttl <= WINDOW_MS, `${ttl}ms`);

  // --- the account bucket is its own -----------------------------------------
  //
  // One request is counted twice, and an address out of budget must not be the
  // reason somebody else's account bucket refuses. Same account, fresh address.
  const otherAddress = nextAddress();
  ok(
    'an exhausted address does not exhaust the account bucket elsewhere',
    (await attempt(otherAddress, 'nobody@betweenus.local')) === 401,
  );

  for (const address of [enforced, aged, straddling, expired, flooded, otherAddress]) {
    await redis.del(addrKey(address));
  }
} finally {
  await redis.quit();
}

if (failures > 0) {
  console.error(`\n${failures} failed`);
  process.exit(1);
}
console.log('\nrate-limit smoke passed');

// Revocation smoke: a socket that is already open, and an account that stops
// being allowed to have one.
//
//   node revocation-smoke.mjs <adminUsername> <adminPassword>
//
// The gap this covers is the one `SECURITY.md` called "a live WebSocket outlives
// the token that opened it": a handshake is authenticated once and then trusted
// until it happens to disconnect, so disabling an account stopped new sessions
// and left every socket it already had delivering.
//
// Four cases, and the middle two are the ones worth having:
//
//   1. a chat, presence and call socket open on a healthy account stay open
//   2. disabling the account closes all three, with 4403
//   3. changing a password closes the sockets that predate it
//   4. and does *not* close one opened with the pair that request handed back
//
// Case 4 is the whole reason the event carries a timestamp rather than a flag.
// "Sign every session out" and "sign every *other* session out" are the same
// event with the line drawn in a different place, and without case 4 the one
// action meant to keep you signed in would sign you out.
//
// NEEDS auth-service, chat-service, presence-service and call-service running,
// plus Redis - the revocation travels over it - and an admin account to do the
// disabling.
import WebSocket from 'ws';

const AUTH = process.env.REVOKE_SMOKE_AUTH ?? 'http://127.0.0.1:3001';
const CHAT = process.env.REVOKE_SMOKE_CHAT ?? 'ws://127.0.0.1:3004/ws/chat';
const PRESENCE = process.env.REVOKE_SMOKE_PRESENCE ?? 'ws://127.0.0.1:3005/ws/presence';
const CALL = process.env.REVOKE_SMOKE_CALL ?? 'ws://127.0.0.1:3007/ws/call';

/** The close code a gateway uses for a revocation. See `SOCKET_REVOKED_CLOSE`. */
const REVOKED = 4403;

const [, , adminUser, adminPassword] = process.argv;
if (!adminUser || !adminPassword) {
  console.error('usage: node revocation-smoke.mjs <adminUsername> <adminPassword>');
  process.exit(2);
}

const json = async (url, options = {}) => {
  const response = await fetch(url, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers ?? {}) },
  });
  const body = await response.json().catch(() => null);
  if (!response.ok) throw new Error(`${url} -> ${response.status} ${JSON.stringify(body)}`);
  return body;
};

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

let failures = 0;
const ok = (label, condition, detail = '') => {
  if (!condition) {
    console.error(`FAIL ${label} ${detail}`);
    failures += 1;
    return;
  }
  console.log(`${label} ok`, detail);
};

/**
 * A socket that remembers how it was closed.
 *
 * `closedWith` stays null while it is open, which is what the "still there"
 * assertions read - a socket that was never going to be closed and a socket
 * that has not been closed *yet* look identical, so every check that expects a
 * close waits for one and every check that expects survival waits the same
 * length of time first.
 */
const connect = (url, token) =>
  new Promise((resolve, reject) => {
    const socket = new WebSocket(`${url}?token=${encodeURIComponent(token)}`);
    const handle = { socket, closedWith: null };
    socket.on('close', (code) => {
      handle.closedWith = code;
    });
    socket.on('error', () => {
      // A close is delivered after the error for the cases here; failing the
      // promise on it would turn "closed by the server" into a crash.
    });
    socket.on('open', () => resolve(handle));
    setTimeout(() => reject(new Error(`${url} did not open`)), 8000);
  });

const openAll = async (token) => ({
  chat: await connect(CHAT, token),
  presence: await connect(PRESENCE, token),
  call: await connect(CALL, token),
});

const closeAll = (sockets) => {
  for (const handle of Object.values(sockets)) handle.socket.close();
};

const suffix = Date.now().toString(36);
const password = 'hunter2000';

const victim = await json(`${AUTH}/api/v1/auth/register`, {
  method: 'POST',
  body: JSON.stringify({
    email: `revoke-${suffix}@betweenus.local`,
    username: `revoke${suffix}`,
    password,
  }),
});
console.log('account ok', victim.user.username);

// --- 1. a healthy account keeps its sockets ----------------------------------
let sockets = await openAll(victim.accessToken);
await sleep(1500);
ok(
  'a healthy account keeps its sockets',
  Object.values(sockets).every((handle) => handle.closedWith === null),
  JSON.stringify(Object.fromEntries(Object.entries(sockets).map(([k, v]) => [k, v.closedWith]))),
);

// --- 2. disabling the account closes them ------------------------------------
const admin = await json(`${AUTH}/api/v1/auth/login`, {
  method: 'POST',
  body: JSON.stringify({ email: adminUser, password: adminPassword }),
});
const adminAuth = { Authorization: `Bearer ${admin.accessToken}` };

await json(`${AUTH}/api/v1/admin/users/${victim.user.id}`, {
  method: 'PATCH',
  headers: adminAuth,
  body: JSON.stringify({ disabled: true }),
});

await sleep(2000);
for (const [name, handle] of Object.entries(sockets)) {
  ok(`disabling closes the ${name} socket`, handle.closedWith === REVOKED, String(handle.closedWith));
}

// Re-enable, so the rest of the file is about a live account again.
await json(`${AUTH}/api/v1/admin/users/${victim.user.id}`, {
  method: 'PATCH',
  headers: adminAuth,
  body: JSON.stringify({ disabled: false }),
});
closeAll(sockets);

// --- 3 and 4. a password change draws the line -------------------------------
//
// Sign in again: the tokens above were minted before the account was disabled
// and re-enabled, and this is about the password change rather than about them.
const session = await json(`${AUTH}/api/v1/auth/login`, {
  method: 'POST',
  body: JSON.stringify({ email: `revoke-${suffix}@betweenus.local`, password }),
});

sockets = await openAll(session.accessToken);
await sleep(1200);

// A second apart, so `iat` in seconds can actually tell the two tokens apart -
// the whole comparison is at second granularity, and a test that mints both in
// the same second proves nothing either way.
await sleep(1200);

const changed = await json(`${AUTH}/api/v1/auth/account/password`, {
  method: 'POST',
  headers: { Authorization: `Bearer ${session.accessToken}` },
  body: JSON.stringify({ currentPassword: password, newPassword: 'hunter3000' }),
});

// Opened with the pair the password change handed back, so it is dated at or
// after the line the same request drew.
const afterwards = await connect(CHAT, changed.accessToken);

await sleep(2000);
for (const [name, handle] of Object.entries(sockets)) {
  ok(
    `a password change closes the ${name} socket that predates it`,
    handle.closedWith === REVOKED,
    String(handle.closedWith),
  );
}
ok(
  'but not the one opened with the pair it handed back',
  afterwards.closedWith === null,
  String(afterwards.closedWith),
);

closeAll(sockets);
afterwards.socket.close();

if (failures > 0) {
  console.error(`\n${failures} failed`);
  process.exit(1);
}
console.log('\nrevocation smoke passed');
process.exit(0);

// Rotation-grace smoke: the interrupted refresh, and where its answer is kept.
//
//   node rotation-smoke.mjs
//
// Rotation is not atomic across the network. The server revokes a token, mints
// its successor, and the response is lost - a reload mid-refresh, a closed
// window, two tabs asking at once. The client then presents the only token it
// still has, which is the one already spent, and without a grace window that is
// indistinguishable from a stolen token: every session on every device revoked,
// and somebody signed out for good over a dropped packet.
//
// The window itself has worked since it was written. What this file is really
// about is *where the answer is kept*: it used to be a `Map` in one process, so
// a replay that landed on a second auth-service instance was still read as theft
// - which is why a second instance could not be run behind the gateway at all.
//
// So the assertions are in two halves:
//
//   1. the window behaves - a replay inside it is idempotent, and creates
//      nothing: no third token, no second session, nothing revoked
//   2. the answer is in Redis, under the key another instance would read, with a
//      TTL - which is the half that a single-instance test cannot see, and the
//      half that was missing
//
// NEEDS auth-service and Redis. Reads Redis directly, because "it is in shared
// storage" is exactly the claim that cannot be checked through the API.
import Redis from 'ioredis';

const AUTH = process.env.ROTATION_SMOKE_AUTH ?? 'http://127.0.0.1:3001';
const REDIS_URL = process.env.REDIS_URL ?? 'redis://127.0.0.1:6379';

let failures = 0;
const ok = (label, condition, detail = '') => {
  if (!condition) {
    console.error(`FAIL ${label} ${detail}`);
    failures += 1;
    return;
  }
  console.log(`${label} ok`, detail);
};

const json = async (url, options = {}) => {
  const response = await fetch(url, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers ?? {}) },
  });
  const body = await response.json().catch(() => null);
  if (!response.ok) throw new Error(`${url} -> ${response.status} ${JSON.stringify(body)}`);
  return body;
};

/** The `jti` a refresh token carries, which is what the grace entry is keyed by. */
const jtiOf = (token) => {
  const [, payload] = token.split('.');
  return JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')).jti;
};

const redis = new Redis(REDIS_URL, { maxRetriesPerRequest: 1 });

try {
  const suffix = Date.now().toString(36);
  const session = await json(`${AUTH}/api/v1/auth/register`, {
    method: 'POST',
    body: JSON.stringify({
      email: `rotate-${suffix}@betweenus.local`,
      username: `rotate${suffix}`,
      password: 'hunter2000',
    }),
  });
  console.log('account ok', session.user.username);

  const spent = session.refreshToken;
  const spentJti = jtiOf(spent);

  const rotated = await json(`${AUTH}/api/v1/auth/refresh`, {
    method: 'POST',
    body: JSON.stringify({ refreshToken: spent }),
  });
  ok('a rotation hands back a different token', rotated.refreshToken !== spent);

  // --- 2. where the answer is kept ------------------------------------------
  //
  // Read before the replay, so what is being checked is the record the *next*
  // instance would find rather than anything this request left behind.
  const key = `auth:rotated:${spentJti}`;
  const stored = await redis.get(key);
  ok('the rotation is recorded in Redis', stored !== null, key);

  if (stored) {
    const entry = JSON.parse(stored);
    ok(
      'and it is the pair the rotation produced',
      entry.tokens?.refreshToken === rotated.refreshToken,
    );
    // The timestamp is what makes the window live rather than captured: shorten
    // `REFRESH_REPLAY_GRACE_MS` and entries already written stop being answered,
    // instead of lingering for the old window's length.
    ok('with the time it was written', typeof entry.at === 'number' && entry.at > 0);
  }

  const ttl = await redis.pttl(key);
  // -1 is a key with no expiry, -2 is no key. Either would be a leak: one that
  // never goes, or one that was never there.
  ok('with a TTL, so nothing is left behind', ttl > 0, `${ttl}ms`);

  // --- 1. the window behaves -------------------------------------------------
  const replayed = await json(`${AUTH}/api/v1/auth/refresh`, {
    method: 'POST',
    body: JSON.stringify({ refreshToken: spent }),
  });
  ok(
    'a replay inside the window is answered with the same pair',
    replayed.refreshToken === rotated.refreshToken,
  );

  // A replay must create nothing. If it minted a third token the session would
  // still work and the damage would be invisible - which is why this is checked
  // by using the token the replay handed back rather than by counting rows.
  const again = await json(`${AUTH}/api/v1/auth/refresh`, {
    method: 'POST',
    body: JSON.stringify({ refreshToken: replayed.refreshToken }),
  });
  ok('and the pair it answered with is still live', Boolean(again.refreshToken));

  // --- 3. Redis going away is not a sign-out ---------------------------------
  //
  // The in-process map is kept deliberately, and this is what it is for. Take
  // the Redis entry away - which is what an unreachable Redis looks like to the
  // instance that wrote it - and the replay is still answered, because the
  // instance holding the socket is the one the client is retrying against.
  //
  // The first draft of this file asserted the opposite, that deleting the key
  // made the replay theft again. It does not, and should not: a Redis outage
  // turning every interrupted rotation into a full sign-out is strictly worse
  // than the per-process behaviour this change replaces. The window closing on
  // time is pinned in `src/check.ts`, deterministically and without a Redis.
  await redis.del(key);
  const afterRedisLost = await json(`${AUTH}/api/v1/auth/refresh`, {
    method: 'POST',
    body: JSON.stringify({ refreshToken: spent }),
  });
  ok(
    'losing the Redis entry falls back to the local map rather than signing out',
    afterRedisLost.refreshToken === rotated.refreshToken,
  );

  // And it is not silently rewritten: the fallback answers, it does not repair.
  ok('and the entry is not resurrected by the read', (await redis.get(key)) === null);
} finally {
  await redis.quit();
}

if (failures > 0) {
  console.error(`\n${failures} failed`);
  process.exit(1);
}
console.log('\nrotation smoke passed');

// Health smoke: the admin health page, pointed at a deployment that is
// genuinely sick.
//
//   node smoke.mjs <adminUsername> <password> [newPassword]
//
// Everything else about the page is a number read out of a healthy stack, which
// is the easy half and the half that was already exercised. The condition it
// exists for is the awkward one: **Postgres is up and slow**. A card that says
// `down` is a database that refused the connection, and anyone would find that
// without a health page. `degraded` is the one nobody had ever seen, so nobody
// knew whether the threshold, the timeout and the header badge agreed with each
// other.
//
// The three states, in order, against a running deployment:
//
//   healthy    everything answers inside SLOW_MS
//   degraded   Postgres answers, and takes longer than SLOW_MS to do it
//   down       Postgres does not answer inside PROBE_TIMEOUT_MS
//
// "Slow" is an egress delay on the database container - `tc netem`, applied
// from a throwaway container sharing its network namespace. That is not a
// simulation of the condition, it is the condition: the server is up, it is
// answering, and every answer takes longer to arrive than the page's threshold
// allows. It is what a saturated pool, a lock queue or a host that has started
// swapping looks like from a client, which is never a refused connection and
// always an answer that takes too long.
//
// The first attempt at this was `docker pause`, and it is worth saying why that
// does not work, because it is the obvious thing to reach for. A freeze is
// absorbed by whatever touches the database first, which on every admin route is
// `AdminGuard` reading the caller's role - so by the time the probes run, the
// database has been let go again and the card comes back green having measured
// nothing. Delay is different: it applies to each query separately, the guard's
// and the probe's alike, which is what makes this repeatable rather than a race.
//
// WHY THERE IS NO `down` CASE FOR THE POSTGRES CARD
//
// There cannot be one, and finding that out is half the point of this file. The
// guard's lookup and the health probe share a 2500ms deadline and the guard runs
// first, so a database slow enough to fail the probe has already failed the
// guard, and the answer is a 503 rather than a page with a red card on it. That
// is the correct behaviour and it is the last case below: the page cannot be
// drawn, so the request says why, quickly. Before the guard had a deadline it
// said nothing at all and waited - which meant the one screen whose purpose is
// to report an unresponsive database was the screen that could not be opened
// while it was.
//
// NEEDS a running auth-service, its dependencies, an admin account, and docker
// reachable from wherever this runs. On a machine where the daemon is inside
// WSL rather than on the host:
//
//   HEALTH_SMOKE_DOCKER="wsl.exe -d Ubuntu -u root -- docker" node smoke.mjs ...
//
// The container is `betweenus-dev-postgres` by default - `pnpm dev:infra` - and
// HEALTH_SMOKE_CONTAINER points it at the compose stack's `betweenus-postgres-1`
// instead. The delay needs an image carrying `tc`, run with NET_ADMIN on the
// database's network namespace; HEALTH_SMOKE_NETEM_IMAGE names it.
import { execFileSync } from 'node:child_process';

const AUTH = process.env.HEALTH_SMOKE_AUTH ?? 'http://127.0.0.1:3001';
const CONTAINER = process.env.HEALTH_SMOKE_CONTAINER ?? 'betweenus-dev-postgres';
const DOCKER = (process.env.HEALTH_SMOKE_DOCKER ?? 'docker').split(' ').filter(Boolean);
const NETEM_IMAGE = process.env.HEALTH_SMOKE_NETEM_IMAGE ?? 'nicolaka/netshoot:latest';

/**
 * Chosen against both deadlines at once, which is narrower than it looks.
 *
 * A query costs about twice this - measured, not assumed: 800ms of egress delay
 * puts the postgres card at around 1750ms, comfortably past SLOW_MS (750) and
 * comfortably inside PROBE_TIMEOUT_MS (2500). The ceiling is the guard rather
 * than the probe: `AdminGuard` spends several round trips of its own before the
 * handler runs, and at 1200ms it exceeds its 2500ms deadline and the request
 * comes back 503 with no page at all. Anything from roughly 500 to 1000 works;
 * 800 sits in the middle of that.
 */
const SLOW_DELAY_MS = 800;

const [, , username, password, newPassword] = process.argv;
if (!username || !password) {
  console.error('usage: node smoke.mjs <adminUsername> <password> [newPassword]');
  process.exit(2);
}

const docker = (...args) => {
  const [command, ...prefix] = DOCKER;
  return execFileSync(command, [...prefix, ...args], {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
};

const json = async (url, options = {}) => {
  const response = await fetch(url, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers ?? {}) },
  });
  const body = await response.json().catch(() => null);
  if (!response.ok) throw new Error(`${url} -> ${response.status} ${JSON.stringify(body)}`);
  return body;
};

const session = await json(`${AUTH}/api/v1/auth/login`, {
  method: 'POST',
  body: JSON.stringify({ email: username, password }),
});
let token = session.accessToken;

// The bootstrap account `pnpm admin:create` makes is created with
// change-on-login armed, so every admin route answers 403 until it is spent.
if (newPassword) {
  const changed = await json(`${AUTH}/api/v1/auth/account/password`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: JSON.stringify({ currentPassword: password, newPassword }),
  });
  token = changed.accessToken ?? token;
}
const auth = { Authorization: `Bearer ${token}` };

const snapshot = () => json(`${AUTH}/api/v1/admin/health`, { headers: auth });

const report = (label, health) => {
  const postgres = health.components.find((component) => component.id === 'postgres');
  console.log(
    `${label.padEnd(10)} overall=${health.overall.padEnd(9)}` +
      `postgres=${postgres.state.padEnd(9)}` +
      `latency=${String(postgres.latencyMs ?? '-').padStart(5)}ms  ${postgres.error ?? ''}`,
  );
  return { overall: health.overall, postgres: postgres.state };
};

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Runs `tc` inside the database's network namespace.
 *
 * A separate container rather than the postgres image, because that image has
 * neither `tc` nor NET_ADMIN - and adding either to the thing under test would
 * mean the deployment being measured is not the deployment that ships.
 */
const tc = (...args) =>
  docker(
    'run',
    '--rm',
    '--network',
    `container:${CONTAINER}`,
    '--cap-add',
    'NET_ADMIN',
    NETEM_IMAGE,
    'tc',
    ...args,
  );

const addDelay = (ms) => tc('qdisc', 'add', 'dev', 'eth0', 'root', 'netem', 'delay', `${ms}ms`);
const clearDelay = () => {
  try {
    tc('qdisc', 'del', 'dev', 'eth0', 'root');
  } catch {
    // Already gone, which is the state this is trying to reach.
  }
};

/**
 * Freezes the database, and thaws it whether or not anything goes wrong.
 *
 * The unpause is scheduled here rather than by a background shell on the docker
 * side: a `sleep && unpause` detached inside the invocation is killed when the
 * invocation returns, which leaves the database frozen and everything after it
 * hanging. A paused database left behind by a failed assertion is a bad half
 * hour for whoever runs this next.
 */
function freeze(ms) {
  docker('pause', CONTAINER);
  let thawed = false;
  const thaw = () => {
    if (thawed) return;
    thawed = true;
    try {
      docker('unpause', CONTAINER);
    } catch (error) {
      console.error(`could not unpause ${CONTAINER}: ${error.message}`);
    }
  };
  const timer = setTimeout(thaw, ms);
  return () => {
    clearTimeout(timer);
    thaw();
  };
}

/** A snapshot taken while every answer from the database is `ms` late. */
async function snapshotWhileSlow(ms, label) {
  addDelay(ms);
  try {
    return report(label, await snapshot());
  } finally {
    clearDelay();
    await sleep(500);
  }
}

// Warm the route once, so the first measured request is not also paying for a
// cold connection pool and a first-time query plan. The clear is for a delay
// left behind by a run that died between applying one and removing it.
clearDelay();
await snapshot();

const healthy = report('healthy', await snapshot());
const slow = await snapshotWhileSlow(SLOW_DELAY_MS, 'degraded');
const recovered = report('recovered', await snapshot());

// The guard's own deadline. With the database already frozen, the health page
// cannot be authorised and therefore cannot be drawn - and the only useful thing
// left to do is say so quickly. Before the deadline existed this request waited
// for as long as the freeze lasted, which meant the one screen whose purpose is
// to report an unresponsive database was the screen you could not open while it
// was.
let guardCode = null;
let guardMs = null;
{
  const thaw = freeze(9000);
  const started = Date.now();
  try {
    await snapshot();
    guardCode = 'NO_ERROR';
  } catch (error) {
    guardCode = /DATABASE_UNAVAILABLE/.test(error.message) ? 'DATABASE_UNAVAILABLE' : error.message;
  } finally {
    guardMs = Date.now() - started;
    thaw();
    await sleep(2000);
  }
}
console.log(`guard      answered in ${String(guardMs).padStart(5)}ms with ${guardCode}`);

const expect = (label, actual, wanted) => {
  if (actual !== wanted) {
    console.error(`FAIL ${label}: expected ${wanted}, got ${actual}`);
    process.exitCode = 1;
    return;
  }
  console.log(`${label} ok`);
};

console.log('');
expect('a healthy database reads up', healthy.postgres, 'up');
expect('and so does the deployment', healthy.overall, 'up');
// The two that are the point of the file.
expect('a slow database reads degraded', slow.postgres, 'degraded');
expect('and degrades the deployment with it', slow.overall, 'degraded');
// A page that goes red and stays red is no more use than one that never does.
expect('and it comes back on its own', recovered.postgres, 'up');
expect('as does the deployment', recovered.overall, 'up');
// And the guard says so rather than hanging.
expect('a frozen database is refused, not waited on', guardCode, 'DATABASE_UNAVAILABLE');
if (guardMs > 4000) {
  console.error(`FAIL the refusal took ${guardMs}ms; the deadline is 2500ms`);
  process.exitCode = 1;
} else {
  console.log('and it is refused inside the deadline ok');
}

if (!process.exitCode) console.log('\nhealth smoke passed');

import { Module } from '@nestjs/common';
import { envOr } from '@betweenus/config';
import { EventBus } from '@betweenus/events';
import { pingDatabase } from '@betweenus/database';
import { createHealthController } from '@betweenus/nest-common';
