/**
 * Admin panel: server health, storage and bandwidth.
 *
 * This is the screen somebody opens when they have been woken up, so the whole
 * thing is built around one rule: **a dead dependency degrades its own card and
 * nothing else**. Every probe below is wrapped, timed and given a deadline of
 * its own; the endpoint answers 200 with a page full of red rather than a 500
 * that says nothing about which of eight things is broken.
 *
 * The other rule is that nothing here is invented. Where a number cannot be
 * known honestly - the byte count of an S3 bucket, the socket count of a
 * gateway that keeps no per-socket bookkeeping - the field is null, or zero
 * with a comment saying why, rather than a plausible-looking guess.
 */
import { Injectable } from '@nestjs/common';
import { cpus, loadavg, platform } from 'node:os';
import { readdir, stat, statfs } from 'node:fs/promises';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import Redis from 'ioredis';
import { envOr, isProduction } from '@betweenus/config';
import { prisma } from '@betweenus/database';
import { getStorage, isS3Configured } from '@betweenus/storage';
import type {
  AdminBandwidth,
  AdminComponentHealth,
  AdminDatabaseStorage,
  AdminHealthState,
  AdminLiveConnections,
  AdminLiveEndpoint,
  AdminMediaStorage,
  AdminRelayHealth,
  AdminRuntimeHealth,
  AdminServerHealth,
  AdminTableSize,
} from '@betweenus/shared-types';
import { publicBaseUrl } from './oauth-providers';

/** How long any single probe gets before it is called `down`. */
const PROBE_TIMEOUT_MS = 2_500;

/**
 * Version from package.json, read once at startup. Used as the last fallback
 * for `appVersion` when neither `APP_VERSION` nor `npm_package_version` is set
 * (which happens when the process is started directly with `node dist/main.js`).
 */
const PACKAGE_VERSION = (() => {
  try {
    const pkg = JSON.parse(
      readFileSync(resolve(__dirname, '../../../package.json'), 'utf8'),
    ) as { version?: string };
    return pkg.version ?? null;
  } catch {
    return null;
  }
})();

/** Slower than this and the component is answering, but not well. */
const SLOW_MS = 750;

/**
 * The relay probe is two UDP round trips to another host, so it gets longer
 * than a local dependency does. Still bounded: a dead relay must not hold the
 * health page open.
 */
const RELAY_PROBE_TIMEOUT_MS = 6_000;

/** Biggest tables only: the panel draws a list, not a schema dump. */
const TABLE_LIMIT = 15;

/** Presence entries older than this are a client that died without saying so. */
const PRESENCE_STALE_MS = 90_000;

/** Bandwidth window bounds. A year of daily buckets is already a long chart. */
const MIN_WINDOW_DAYS = 1;
const MAX_WINDOW_DAYS = 365;
const DEFAULT_WINDOW_DAYS = 30;

/**
 * The window, clamped.
 *
 * A query string is a stranger: `?days=99999999` is a full sequential scan of
 * every call ever made, and `?days=-1` is a window that ends before it starts
 * and quietly returns nothing at all. Both come back as a number the chart can
 * draw.
 */
export function clampWindowDays(value: number): number {
  if (!Number.isFinite(value)) return DEFAULT_WINDOW_DAYS;
  return Math.min(Math.max(Math.trunc(value), MIN_WINDOW_DAYS), MAX_WINDOW_DAYS);
}

/**
 * The worst of several states, which is what the header badge shows.
 *
 * Deliberately pessimistic: one component down makes the deployment down, even
 * with seven green cards beside it, because a panel whose badge stays green
 * while Postgres is unreachable is a panel nobody will trust twice.
 */
export function worstState(states: AdminHealthState[]): AdminHealthState {
  if (states.includes('down')) return 'down';
  if (states.includes('degraded')) return 'degraded';
  return 'up';
}

/** A probe that answered, judged on how long it took about it. */
export function stateForLatency(latencyMs: number): AdminHealthState {
  return latencyMs > SLOW_MS ? 'degraded' : 'up';
}

/**
 * A connection string with any credentials taken out of it.
 *
 * `DATABASE_URL` and `REDIS_URL` both routinely carry `user:password@`, and
 * this response goes to a browser and into whatever that browser's console, an
 * error reporter or a support screenshot does with it next. Everything else
 * about the URL - scheme, host, port, database - is exactly what somebody
 * reading the panel needs, so only the userinfo is removed.
 *
 * The query string is searched too, and not as an afterthought: `?password=`
 * and `?sslpassword=` are ordinary in a Postgres URL, and `new URL` happily
 * parses `host:5432/db?password=hunter2` by reading `host:` as the scheme - so
 * a redaction that only cleared the userinfo would hand that one straight back
 * with the password still in it. That was a real failure of the first version
 * of this function, caught by the self-check rather than by a screenshot.
 *
 * A string that does not parse at all is not handed back on the chance that it
 * is harmless: it is replaced wholesale, because the one case that matters is
 * the malformed string that still has a secret in it.
 */
const SECRET_PARAM = /pass|secret|token|key|credential/i;

export function redactUrl(raw: string | null | undefined): string | null {
  if (!raw) return null;
  try {
    const url = new URL(raw);
    if (url.username || url.password) {
      url.username = '';
      url.password = '';
    }
    for (const name of [...url.searchParams.keys()]) {
      if (SECRET_PARAM.test(name)) url.searchParams.set(name, '***');
    }
    return url.toString();
  } catch {
    return '(unparseable url)';
  }
}

/**
 * A `BigInt` column as a JSON number.
 *
 * `bytes`, `bytesSent` and `bytesReceived` are `BigInt` in Postgres and
 * `JSON.stringify` throws outright on one, so this conversion is not a
 * nicety - it is the difference between a response and a 500. `Number()` is
 * what `calls.service.ts` already uses on the same columns and this stays
 * consistent with it, but it is lossy above 2^53, which is nine petabytes: past
 * that the figure on the panel is approximate and there is nothing a JSON
 * number can do about it. Null and undefined are zero, because "no rows
 * matched" is a real answer from every aggregate here.
 */
export function toNumber(value: bigint | number | null | undefined): number {
  if (value === null || value === undefined) return 0;
  return typeof value === 'bigint' ? Number(value) : value;
}

/**
 * A file extension, bucketed the way the panel groups storage.
 *
 * `Attachment` stores no content type - it cannot, since the bytes are sealed
 * and the manifest naming them lives inside the ciphertext - so the generated
 * storage key's extension is the only signal the server has. It comes from
 * `buildKey`, which lower-cases and strips the original filename's extension,
 * so it is a hint about what was uploaded rather than a declaration of it.
 */
export function kindOfExtension(extension: string | null): string {
  const ext = (extension ?? '').toLowerCase().replace(/^\./, '');
  if (/^(png|jpe?g|gif|webp|bmp|svg|avif|heic|heif|ico|tiff?)$/.test(ext)) return 'image';
  if (/^(mp4|webm|mov|mkv|avi|m4v|3gp|mpe?g|wmv)$/.test(ext)) return 'video';
  if (/^(mp3|ogg|oga|opus|wav|flac|aac|m4a|weba|amr)$/.test(ext)) return 'audio';
  if (/^(pdf|docx?|xlsx?|pptx?|odt|ods|odp|txt|md|rtf|csv|json|xml|zip|gz|7z|rar|tar)$/.test(ext)) {
    return 'document';
  }
  return 'other';
}

/** Runs `work` with a deadline, so one hung dependency cannot hold the page. */
async function withTimeout<T>(work: Promise<T>, ms: number): Promise<T> {
  let timer: NodeJS.Timeout | undefined;
  try {
    return await Promise.race([
      work,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(() => reject(new Error(`Timed out after ${ms}ms`)), ms);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/** One sentence, never a stack trace, and never long enough to be one. */
function messageOf(error: unknown): string {
  const text = error instanceof Error ? error.message : String(error);
  return text.split('\n')[0]?.slice(0, 200) ?? 'Unknown error';
}

/**
 * Runs one probe and turns whatever happens into a card.
 *
 * The `catch` here is the whole design: a probe may throw, time out, or return
 * a rejection from three layers down, and all of it becomes a red card with a
 * sentence on it. Nothing propagates out of this function.
 */
async function probe(
  id: string,
  label: string,
  url: string | null,
  work: () => Promise<Record<string, string | number> | void>,
): Promise<AdminComponentHealth> {
  const started = Date.now();
  try {
    const detail = await withTimeout(Promise.resolve().then(work), PROBE_TIMEOUT_MS);
    const latencyMs = Date.now() - started;
    return {
      id,
      label,
      state: stateForLatency(latencyMs),
      latencyMs,
      url,
      error: null,
      ...(detail ? { detail } : {}),
    };
  } catch (error) {
    return {
      id,
      label,
      state: 'down',
      latencyMs: null,
      url,
      error: messageOf(error),
    };
  }
}

/**
 * The sibling services this deployment expects to be able to reach.
 *
 * Two fallbacks, because there are two places this runs and they do not share a
 * name for anything. In a container, `chat-service` is a hostname compose
 * resolves. On a developer's machine, `pnpm dev:backend` puts the same service
 * on localhost and that hostname resolves to nothing at all - so the page came
 * up with four red cards, a `down` badge, and no relation to the deployment in
 * front of it. A health page that is red on every machine it is developed on is
 * a health page nobody looks at twice.
 *
 * `*_SERVICE_URL` still overrides both, for a deployment that puts them
 * somewhere else again.
 */
const SIBLINGS: Array<{ id: string; label: string; envVar: string; host: string; port: number }> = [
  { id: 'chat-service', label: 'Chat service', envVar: 'CHAT_SERVICE_URL', host: 'chat-service', port: 3004 },
  {
    id: 'presence-service',
    label: 'Presence service',
    envVar: 'PRESENCE_SERVICE_URL',
    host: 'presence-service',
    port: 3005,
  },
  { id: 'call-service', label: 'Call service', envVar: 'CALL_SERVICE_URL', host: 'call-service', port: 3007 },
  {
    id: 'remote-gateway',
    label: 'Remote gateway',
    envVar: 'REMOTE_GATEWAY_URL',
    host: 'remote-gateway',
    port: 3008,
  },
];

/** Where a sibling is, absent an explicit `*_SERVICE_URL`. */
function siblingUrl(sibling: (typeof SIBLINGS)[number]): string {
  const host = isProduction() ? sibling.host : '127.0.0.1';
  return envOr(sibling.envVar, `http://${host}:${sibling.port}`);
}

/** Rows as `pg_stat_user_tables` hands them back, before they are trimmed. */
interface TableSizeRow {
  table: string;
  rowEstimate: bigint;
  totalBytes: bigint;
  indexBytes: bigint;
}

interface DailyRow {
  date: string;
  bytes: bigint;
}

interface ExtensionRow {
  ext: string | null;
  count: bigint;
  bytes: bigint;
}

@Injectable()
export class AdminHealthService {
  /**
   * One connection, kept for the life of the process.
   *
   * A client per request would put a TCP connect and a handshake inside a probe
   * that is measuring round-trip latency, which measures the wrong thing.
   * `lazyConnect` keeps it from dialling at all until the first health request,
   * so a deployment where nobody ever opens the panel pays nothing for it.
   */
  private readonly redis = new Redis(envOr('REDIS_URL', 'redis://localhost:6379'), {
    maxRetriesPerRequest: 1,
    lazyConnect: true,
    connectTimeout: PROBE_TIMEOUT_MS,
  });

  /**
   * The whole screen, in one response.
   *
   * The sections run concurrently and each one owns its own failure: the
   * `catch` on every branch is what keeps a broken Redis from taking the
   * database panel down with it.
   */
  async snapshot(days: number): Promise<AdminServerHealth> {
    const windowDays = clampWindowDays(days);
    const [components, database, media, bandwidth, live, relay] = await Promise.all([
      this.components(),
      this.database(),
      this.media(),
      this.bandwidth(windowDays),
      this.live(),
      this.relay(),
    ]);

    return {
      at: new Date().toISOString(),
      // The relay is deliberately not folded into `overall`. Running without
      // one is the default and not a fault, and a deployment that chose
      // STUN-only must not be shown a permanently red badge for it. The relay
      // card carries its own state.
      overall: worstState(components.map((component) => component.state)),
      components,
      runtime: this.runtime(),
      database,
      media,
      bandwidth,
      live: { ...live, endpoints: this.endpoints(components, live) },
      relay,
    };
  }

  /**
   * The TURN relay, as `call-service` reports it.
   *
   * Asked rather than worked out here: `call-service` owns `TURN_URLS` and is
   * what hands ICE to clients, so it is the only source that cannot disagree
   * with what a call actually gets. Reading the variable a second time in this
   * process would recreate exactly the split-brain that removing the hosted
   * minting path was meant to end.
   *
   * A `call-service` that cannot be reached is reported as such rather than as
   * a broken relay: those are different problems with different fixes, and the
   * sibling probe above already says which one this is.
   */
  private async relay(): Promise<AdminRelayHealth> {
    const base = envOr('CALL_SERVICE_URL', 'http://call-service:3007');
    try {
      const response = await withTimeout(
        fetch(`${base}/api/v1/internal/relay`),
        RELAY_PROBE_TIMEOUT_MS,
      );
      if (!response.ok) throw new Error(`call-service answered ${response.status}`);
      return (await response.json()) as AdminRelayHealth;
    } catch (error) {
      return {
        configured: false,
        username: null,
        probes: [],
        state: 'down',
        error: `Could not ask call-service about the relay: ${messageOf(error)}`,
      };
    }
  }

  /**
   * What this process knows about the machine under it.
   *
   * Only ever the *auth-service* process, which matters when the services are
   * spread across hosts: this is the uptime and memory of the one answering,
   * not a deployment-wide figure, and the panel should label it as such.
   */
  private runtime(): AdminRuntimeHealth {
    const memory = process.memoryUsage();
    const [one = 0, five = 0, fifteen = 0] = loadavg();
    return {
      uptimeSeconds: Math.round(process.uptime()),
      memoryRssBytes: memory.rss,
      memoryHeapUsedBytes: memory.heapUsed,
      memoryHeapTotalBytes: memory.heapTotal,
      // Windows has no load average and Node reports [0, 0, 0] there. The
      // contract says so, so it is passed through rather than nulled.
      loadAverage: [one, five, fifteen],
      cpuCount: cpus().length,
      nodeVersion: process.version,
      platform: platform(),
      // The release tag when a pipeline set one, the package version otherwise.
      // PACKAGE_VERSION is the last resort for processes not started via npm.
      appVersion: process.env.APP_VERSION ?? process.env.npm_package_version ?? PACKAGE_VERSION,
    };
  }

  /**
   * Postgres' own accounting of itself.
   *
   * All of it is raw SQL because none of it is in the Prisma schema: table
   * sizes, backend counts and the server version live in catalog views no ORM
   * models. No caller input reaches any of these statements - the only
   * parameter anywhere in this file is the bandwidth cutoff, and that is bound
   * by Prisma rather than interpolated into the string.
   */
  private async database(): Promise<AdminDatabaseStorage> {
    try {
      return await withTimeout(this.readDatabase(), PROBE_TIMEOUT_MS);
    } catch {
      // The `postgres` component card already carries the reason; this section
      // simply has nothing to show.
      return { totalBytes: 0, tables: [], connections: 0, maxConnections: 0, version: null };
    }
  }

  private async readDatabase(): Promise<AdminDatabaseStorage> {
    const [size, tables, connections, maxConnections, version] = await Promise.all([
      prisma.$queryRaw<Array<{ bytes: bigint }>>`
        SELECT pg_database_size(current_database()) AS bytes
      `,
      // `n_live_tup` is the planner's estimate on purpose: an exact count(*) of
      // every table is a sequential scan of the entire database, which is a
      // strange thing for a health page to do to a server that is struggling.
      prisma.$queryRaw<TableSizeRow[]>`
        SELECT
          relname AS "table",
          n_live_tup AS "rowEstimate",
          pg_total_relation_size(relid) AS "totalBytes",
          pg_indexes_size(relid) AS "indexBytes"
        FROM pg_stat_user_tables
        ORDER BY pg_total_relation_size(relid) DESC
        LIMIT ${TABLE_LIMIT}
      `,
      prisma.$queryRaw<Array<{ count: bigint }>>`
        SELECT count(*) AS count FROM pg_stat_activity
      `,
      prisma.$queryRaw<Array<{ max_connections: string }>>`SHOW max_connections`,
      prisma.$queryRaw<Array<{ server_version: string }>>`SHOW server_version`,
    ]);

    const rows: AdminTableSize[] = tables.map((row) => ({
      table: row.table,
      rowEstimate: toNumber(row.rowEstimate),
      totalBytes: toNumber(row.totalBytes),
      indexBytes: toNumber(row.indexBytes),
    }));

    return {
      totalBytes: toNumber(size[0]?.bytes),
      tables: rows,
      connections: toNumber(connections[0]?.count),
      maxConnections: Number(maxConnections[0]?.max_connections ?? 0) || 0,
      version: version[0]?.server_version ?? null,
    };
  }

  /**
   * Where the uploads are and how much room they take.
   *
   * The two byte counts answer different questions and neither replaces the
   * other. `recordedBytes` is what the database says was stored; `diskBytes` is
   * what is actually on the volume, which includes anything the attachment
   * sweeper has not caught up with yet. The gap between them is the interesting
   * number, so both are reported rather than reconciled into one.
   */
  private async media(): Promise<AdminMediaStorage> {
    const driver = this.storageDriver();
    const base: AdminMediaStorage = {
      driver,
      recordedBytes: 0,
      diskBytes: null,
      diskFreeBytes: null,
      attachmentCount: 0,
      byKind: [],
      location: null,
    };

    const [recorded, disk] = await Promise.all([
      this.recordedMedia().catch(() => null),
      // S3 keeps both sizes null deliberately: listing every object in a bucket
      // costs a request per thousand keys, and the contract would rather have a
      // null than a number somebody was billed for.
      driver === 'local' ? this.localDisk().catch(() => null) : Promise.resolve(null),
    ]);

    return {
      ...base,
      ...(recorded ?? {}),
      ...(disk ?? {}),
      location:
        driver === 's3'
          ? (process.env.S3_BUCKET ?? null)
          : resolve(envOr('LOCAL_STORAGE_PATH', './storage-data')),
    };
  }

  /** `getStorage()` throws on a half-configured bucket; that is not fatal here. */
  private storageDriver(): 'local' | 's3' {
    try {
      return getStorage().name;
    } catch {
      return isS3Configured() ? 's3' : 'local';
    }
  }

  private async recordedMedia(): Promise<
    Pick<AdminMediaStorage, 'recordedBytes' | 'attachmentCount' | 'byKind'>
  > {
    // Grouped in SQL on the key's extension rather than by reading every row
    // back: the bucketing is then a handful of regexes over at most a few dozen
    // distinct extensions, however many million attachments there are.
    const rows = await prisma.$queryRaw<ExtensionRow[]>`
      SELECT
        lower(substring(key from '\\.([A-Za-z0-9]+)$')) AS ext,
        count(*) AS count,
        coalesce(sum(size), 0) AS bytes
      FROM attachments
      GROUP BY 1
    `;

    const byKind = new Map<string, { kind: string; count: number; bytes: number }>();
    let recordedBytes = 0;
    let attachmentCount = 0;

    for (const row of rows) {
      const kind = kindOfExtension(row.ext);
      const count = toNumber(row.count);
      const bytes = toNumber(row.bytes);
      recordedBytes += bytes;
      attachmentCount += count;
      const bucket = byKind.get(kind) ?? { kind, count: 0, bytes: 0 };
      bucket.count += count;
      bucket.bytes += bytes;
      byKind.set(kind, bucket);
    }

    return {
      recordedBytes,
      attachmentCount,
      byKind: [...byKind.values()].sort((a, b) => b.bytes - a.bytes),
    };
  }

  /**
   * The uploads directory, measured by walking it.
   *
   * Only ever done for the local driver, where the tree is a developer's or a
   * single host's and the walk is cheap. It counts apparent size rather than
   * blocks, which is the same figure the attachment rows are recorded in and
   * therefore the one that compares against them.
   */
  private async localDisk(): Promise<Pick<AdminMediaStorage, 'diskBytes' | 'diskFreeBytes'>> {
    const root = resolve(envOr('LOCAL_STORAGE_PATH', './storage-data'));
    const [diskBytes, stats] = await Promise.all([
      directorySize(root),
      statfs(root).catch(() => null),
    ]);
    return {
      diskBytes,
      diskFreeBytes: stats ? stats.bsize * stats.bavail : null,
    };
  }

  /**
   * What has moved over the window.
   *
   * **The call figures are not this host's traffic.** Media is peer-to-peer and
   * never touches the server, so these are the clients' own reported totals off
   * `CallSession` - the only place the number exists at all. A client that was
   * closed mid-call reported nothing and its row reads zero, so the totals are
   * a floor rather than a measurement. Attachment bytes, by contrast, are bytes
   * this deployment genuinely stored.
   */
  private async bandwidth(windowDays: number): Promise<AdminBandwidth> {
    const since = new Date(Date.now() - windowDays * 86_400_000);
    try {
      const [calls, attachments, daily] = await withTimeout(
        Promise.all([
          prisma.callSession.aggregate({
            where: { joinedAt: { gte: since } },
            _sum: { bytes: true, bytesSent: true, bytesReceived: true },
            _count: { _all: true },
          }),
          prisma.attachment.aggregate({
            where: { createdAt: { gte: since } },
            _sum: { size: true },
            _count: { _all: true },
          }),
          this.daily(since),
        ]),
        PROBE_TIMEOUT_MS,
      );

      return {
        windowDays,
        callBytes: toNumber(calls._sum.bytes),
        callBytesSent: toNumber(calls._sum.bytesSent),
        callBytesReceived: toNumber(calls._sum.bytesReceived),
        callSessions: calls._count._all,
        attachmentBytes: toNumber(attachments._sum.size),
        attachmentCount: attachments._count._all,
        daily,
      };
    } catch {
      return {
        windowDays,
        callBytes: 0,
        callBytesSent: 0,
        callBytesReceived: 0,
        callSessions: 0,
        attachmentBytes: 0,
        attachmentCount: 0,
        daily: [],
      };
    }
  }

  /**
   * One row per day that had traffic, oldest first.
   *
   * Two grouped queries merged in memory rather than a full outer join, because
   * the two sides are different date columns on different tables and the join
   * is more SQL than the merge is code. Days with nothing at all are left out:
   * the chart then draws a gap, which is what happened.
   */
  private async daily(since: Date): Promise<AdminBandwidth['daily']> {
    const [callDays, attachmentDays] = await Promise.all([
      prisma.$queryRaw<DailyRow[]>`
        SELECT to_char(date_trunc('day', "joinedAt"), 'YYYY-MM-DD') AS date,
               coalesce(sum(bytes), 0) AS bytes
        FROM call_sessions
        WHERE "joinedAt" >= ${since}
        GROUP BY 1
      `,
      prisma.$queryRaw<DailyRow[]>`
        SELECT to_char(date_trunc('day', "createdAt"), 'YYYY-MM-DD') AS date,
               coalesce(sum(size), 0) AS bytes
        FROM attachments
        WHERE "createdAt" >= ${since}
        GROUP BY 1
      `,
    ]);

    const days = new Map<string, { date: string; callBytes: number; attachmentBytes: number }>();
    const entryFor = (date: string): { date: string; callBytes: number; attachmentBytes: number } =>
      days.get(date) ?? { date, callBytes: 0, attachmentBytes: 0 };

    for (const row of callDays) {
      days.set(row.date, { ...entryFor(row.date), callBytes: toNumber(row.bytes) });
    }
    for (const row of attachmentDays) {
      days.set(row.date, { ...entryFor(row.date), attachmentBytes: toNumber(row.bytes) });
    }

    return [...days.values()].sort((a, b) => a.date.localeCompare(b.date));
  }

  /**
   * Who is connected right now, read straight out of Redis.
   *
   * Presence and the voice rosters are the only live state shared between
   * services, so they are the only live state a *different* service can report
   * on. The keys are `presence-service`'s own - `presence:online`,
   * `presence:voice:channels` and `presence:voice:<channelId>` - and this is a
   * second reader of them; if they ever change, this changes with them.
   */
  private async live(): Promise<Omit<AdminLiveConnections, 'endpoints'>> {
    const [presence, remote] = await Promise.all([
      this.presenceCounts().catch(() => ({ online: 0, calls: 0, participants: 0 })),
      prisma.remoteSession.count({ where: { endedAt: null } }).catch(() => 0),
    ]);

    return {
      onlineUsers: presence.online,
      // Presence is keyed per account, not per socket - two windows of the same
      // account are one entry in `presence:online`, and nothing anywhere keeps
      // a per-device count. So this is connected *accounts* and will never
      // exceed `onlineUsers`. Making it a true socket count would mean presence
      // keying by device, which is a change to presence-service, not to this.
      totalSockets: presence.online,
      activeCalls: presence.calls,
      activeCallParticipants: presence.participants,
      activeRemoteSessions: remote,
    };
  }

  private async presenceCounts(): Promise<{ online: number; calls: number; participants: number }> {
    // The same cutoff `PresenceStore` applies when it reads: an entry nobody
    // has refreshed is a client that died, not somebody who is online.
    const cutoff = Date.now() - PRESENCE_STALE_MS;
    const online = await withTimeout(
      this.redis.zcount('presence:online', cutoff, '+inf'),
      PROBE_TIMEOUT_MS,
    );

    const channels = await this.redis.smembers('presence:voice:channels');
    const sizes = await Promise.all(
      channels.map((channelId) => this.redis.scard(`presence:voice:${channelId}`)),
    );
    // A roster whose key has expired is a call `call-service` stopped
    // re-announcing; the index still names the channel, so an empty set is a
    // call that is over rather than a call with nobody in it.
    const live = sizes.filter((size) => size > 0);

    return {
      online,
      calls: live.length,
      participants: live.reduce((total, size) => total + size, 0),
    };
  }

  /**
   * The four realtime paths, as a client dials them.
   *
   * Built from the deployment's own public URL rather than a hardcoded host,
   * with the scheme swapped for its WebSocket equivalent - which is the whole
   * reason these are computed at all: an administrator checking whether the
   * tunnel is configured correctly wants to see the URL their clients actually
   * use, not the one this service would guess.
   */
  private endpoints(
    components: AdminComponentHealth[],
    live: Omit<AdminLiveConnections, 'endpoints'>,
  ): AdminLiveEndpoint[] {
    const base = publicBaseUrl().replace(/^http/, 'ws');
    const stateOf = (id: string): AdminHealthState =>
      components.find((component) => component.id === id)?.state ?? 'down';

    return [
      // `chat-service` keeps its subscriptions inside the gateway process and
      // publishes nothing about them, so there is no count to read. Zero here
      // means "not tracked"; the card's state still says whether the service is
      // answering, which is the question the endpoint list is really asked.
      {
        id: 'chat',
        label: 'Chat',
        url: `${base}/ws/chat`,
        connections: 0,
        state: stateOf('chat-service'),
      },
      {
        id: 'presence',
        label: 'Presence',
        url: `${base}/ws/presence`,
        connections: live.onlineUsers,
        state: stateOf('presence-service'),
      },
      {
        id: 'call',
        label: 'Voice & video',
        url: `${base}/ws/call`,
        connections: live.activeCallParticipants,
        state: stateOf('call-service'),
      },
      {
        id: 'remote',
        label: 'Remote desktop',
        url: `${base}/ws/remote`,
        connections: live.activeRemoteSessions,
        state: stateOf('remote-gateway'),
      },
    ];
  }

  /** Every dependency, probed concurrently, each failing only for itself. */
  private components(): Promise<AdminComponentHealth[]> {
    return Promise.all([
      probe('postgres', 'PostgreSQL', redactUrl(process.env.DATABASE_URL), async () => {
        await prisma.$queryRaw`SELECT 1`;
      }),
      probe('redis', 'Redis', redactUrl(envOr('REDIS_URL', 'redis://localhost:6379')), async () => {
        const pong = await this.redis.ping();
        if (pong !== 'PONG') throw new Error(`Unexpected reply: ${pong}`);
      }),
      ...SIBLINGS.map((sibling) => {
        const url = `${siblingUrl(sibling).replace(/\/$/, '')}/health`;
        // Redacted for the same reason the database URL is: a service URL with
        // basic-auth credentials in it is unusual but entirely legal.
        return probe(sibling.id, sibling.label, redactUrl(url), async () => {
          const response = await fetch(url, { signal: AbortSignal.timeout(PROBE_TIMEOUT_MS) });
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          const body: unknown = await response.json();
          const status =
            typeof body === 'object' && body !== null && 'status' in body
              ? String((body as { status: unknown }).status)
              : 'unknown';
          // A service answering `degraded` is reporting that its own dependency
          // is unwell; that is its card to be red, not this one's to hide.
          if (status !== 'ok') throw new Error(`Reported ${status}`);
          return { status };
        });
      }),
    ]);
  }
}

/**
 * Apparent size of everything under `root`, in bytes.
 *
 * Iterative rather than recursive, and `withFileTypes` so each entry costs one
 * `stat` and not two. A directory that has gone missing between the listing and
 * the walk contributes nothing rather than throwing the whole measurement away.
 *
 * ponytail: a full walk on every request. Fine for a local-disk deployment,
 * which is the only one that reaches here; cache it behind a timestamp if an
 * uploads tree ever gets big enough for an administrator to notice the wait.
 */
async function directorySize(root: string): Promise<number> {
  const pending = [root];
  let total = 0;

  while (pending.length > 0) {
    const dir = pending.pop();
    if (dir === undefined) break;
    const entries = await readdir(dir, { withFileTypes: true }).catch(() => []);
    for (const entry of entries) {
      const path = resolve(dir, entry.name);
      if (entry.isDirectory()) {
        pending.push(path);
      } else if (entry.isFile()) {
        const info = await stat(path).catch(() => null);
        total += info?.size ?? 0;
      }
    }
  }

  return total;
}

/**
 * The OAuth providers BetweenUs knows how to talk to, and how to read their
 * config out of the database.
 *
 * Adding a provider is a matter of adding an entry here - endpoints, scope and
 * how to read an id and a name out of its profile response - plus a button in
 * the clients. Credentials themselves are operator data, not code.
 */
import { openSecret } from '@betweenus/auth';
import { envOr } from '@betweenus/config';
import { prisma } from '@betweenus/database';

export type ProviderName = 'google' | 'github';

export interface ProviderProfile {
  id: string;
  email: string | null;
  /**
   * Whether the provider says it has proved this address belongs to whoever
   * just signed in.
   *
   * It decides whether the address may be used to find an existing account, so
   * a provider that does not say gets a `false` here rather than the benefit of
   * the doubt: an unverified address is a claim, and linking on a claim is
   * letting anybody who can type a victim's email into a new provider account
   * walk into the account behind it.
   */
  emailVerified: boolean;
  username: string;
  displayName: string;
  avatarUrl: string | null;
}

export interface ProviderDefinition {
  label: string;
  authorizeUrl: string;
  tokenUrl: string;
  scope: string;
  /** Fetches the signed-in person's profile with a provider access token. */
  profile: (accessToken: string) => Promise<ProviderProfile>;
}

const json = async (url: string, init: RequestInit): Promise<Record<string, unknown>> => {
  const response = await fetch(url, init);
  const body = (await response.json().catch(() => null)) as Record<string, unknown> | null;
  if (!response.ok || !body) {
    throw new Error(`${url} responded ${response.status}`);
  }
  return body;
};

export const PROVIDERS: Record<ProviderName, ProviderDefinition> = {
  google: {
    label: 'Google',
    authorizeUrl: 'https://accounts.google.com/o/oauth2/v2/auth',
    tokenUrl: 'https://oauth2.googleapis.com/token',
    scope: 'openid email profile',
    profile: async (accessToken) => {
      const me = await json('https://openidconnect.googleapis.com/v1/userinfo', {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      const email = typeof me.email === 'string' ? me.email : null;
      return {
        id: String(me.sub),
        email,
        // Google will hand out an address it has not verified; `email_verified`
        // is the field that says which kind this is, and it was being ignored.
        emailVerified: me.email_verified === true,
        username: email?.split('@')[0] ?? `google${String(me.sub).slice(0, 8)}`,
        displayName: typeof me.name === 'string' ? me.name : (email ?? 'Google user'),
        avatarUrl: typeof me.picture === 'string' ? me.picture : null,
      };
    },
  },
  github: {
    label: 'GitHub',
    authorizeUrl: 'https://github.com/login/oauth/authorize',
    tokenUrl: 'https://github.com/login/oauth/access_token',
    scope: 'read:user user:email',
    profile: async (accessToken) => {
      const headers = { Authorization: `Bearer ${accessToken}`, Accept: 'application/vnd.github+json' };
      const me = await json('https://api.github.com/user', { headers });

      // A GitHub account can keep its address private, in which case the
      // profile carries no email and the verified primary has to be asked for.
      // GitHub only lets a *verified* address be made public, so the one on
      // the profile is verified by construction, and the fallback below asks
      // for the verified primary explicitly.
      let email = typeof me.email === 'string' ? me.email : null;
      if (!email) {
        const addresses = (await fetch('https://api.github.com/user/emails', { headers })
          .then((response) => (response.ok ? response.json() : []))
          .catch(() => [])) as Array<{ email: string; primary: boolean; verified: boolean }>;
        email = addresses.find((entry) => entry.primary && entry.verified)?.email ?? null;
      }

      return {
        id: String(me.id),
        email,
        emailVerified: email !== null,
        username: typeof me.login === 'string' ? me.login : `github${String(me.id)}`,
        displayName: typeof me.name === 'string' && me.name ? me.name : String(me.login),
        avatarUrl: typeof me.avatar_url === 'string' ? me.avatar_url : null,
      };
    },
  },
};

export function isProviderName(value: string): value is ProviderName {
  return value === 'google' || value === 'github';
}

/** Public base URL of this deployment, as the provider will redirect back to it. */
export function publicBaseUrl(): string {
  return envOr('PUBLIC_API_URL', 'http://localhost:8080').replace(/\/$/, '');
}

export function callbackUrl(provider: ProviderName): string {
  return `${publicBaseUrl()}/api/v1/auth/oauth/${provider}/callback`;
}

export interface ProviderCredentials {
  clientId: string;
  clientSecret: string;
}

/** Credentials for an enabled provider, or null when it is off or unreadable. */
export async function credentialsFor(provider: ProviderName): Promise<ProviderCredentials | null> {
  const row = await prisma.oAuthProvider.findUnique({ where: { provider } });
  if (!row || !row.enabled || !row.clientId || !row.clientSecret) return null;

  const clientSecret = openSecret(row.clientSecret);
  // Sealed with a key this deployment no longer has: treat as unconfigured
  // rather than sending a garbage secret to the provider.
  if (!clientSecret) return null;

  return { clientId: row.clientId, clientSecret };
}

import { Body, Controller, Get, HttpCode, Patch, Post, Query, UseGuards } from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  AuthResponse,
  AuthTokens,
  ForgotPasswordResponse,
  PublicUser,
  UsernameAvailability,
} from '@betweenus/shared-types';
import { rateLimit } from '@betweenus/nest-common';
import { AuthService } from './auth.service';
import {
  ChangePasswordDto,
  ForgotPasswordDto,
  LoginDto,
  RefreshDto,
  RegisterDto,
  ResetPasswordDto,
  UpdateAccountDto,
} from './dto';
import { CREDENTIALS_RATE_LIMIT, LOGIN_RATE_LIMIT, SESSION_RATE_LIMIT } from './rate-limits';

const CredentialsRateLimit = rateLimit(CREDENTIALS_RATE_LIMIT);
const LoginRateLimit = rateLimit(LOGIN_RATE_LIMIT);
const SessionRateLimit = rateLimit(SESSION_RATE_LIMIT);

@Controller('auth')
export class AuthController {
  constructor(private readonly auth: AuthService) {}

  @Post('register')
  @UseGuards(CredentialsRateLimit)
  register(@Body() dto: RegisterDto): Promise<AuthResponse> {
    return this.auth.register(dto);
  }

  @Post('login')
  @HttpCode(200)
  @UseGuards(LoginRateLimit)
  login(@Body() dto: LoginDto): Promise<AuthResponse> {
    return this.auth.login(dto);
  }

  @Post('refresh')
  @HttpCode(200)
  @UseGuards(SessionRateLimit)
  refresh(@Body() dto: RefreshDto): Promise<AuthTokens> {
    return this.auth.refresh(dto.refreshToken);
  }

  @Post('logout')
  @HttpCode(204)
  async logout(@Body() dto: RefreshDto): Promise<void> {
    await this.auth.logout(dto.refreshToken);
  }

  /**
   * Whether a username can be registered. Unauthenticated, because the form
   * that asks is the one you fill in before you have an account.
   *
   * Rate limited with the credentials bucket: it answers a question about
   * whether an account exists, which is exactly what the login endpoint is
   * throttled for.
   */
  @Get('username-available')
  @UseGuards(CredentialsRateLimit)
  usernameAvailable(@Query('username') username = ''): Promise<UsernameAvailability> {
    return this.auth.usernameAvailable(username);
  }

  /**
   * What can be done about a forgotten password here. Answers the same thing
   * for an account that does not exist as for one that does - see the service.
   */
  @Post('forgot-password')
  @HttpCode(200)
  @UseGuards(CredentialsRateLimit)
  forgotPassword(@Body() dto: ForgotPasswordDto): Promise<ForgotPasswordResponse> {
    return this.auth.forgotPassword(dto.identifier);
  }

  /** Spends a reset token. The only path that sets a password without the old one. */
  @Post('reset-password')
  @HttpCode(200)
  @UseGuards(CredentialsRateLimit)
  resetPassword(@Body() dto: ResetPasswordDto): Promise<AuthResponse> {
    return this.auth.resetPassword(dto.token, dto.newPassword);
  }

  @Get('me')
  @UseGuards(JwtAuthGuard)
  me(@CurrentUser() user: AuthenticatedUser): Promise<PublicUser> {
    return this.auth.me(user.id);
  }

  /** Available to any signed-in account, not only admins. */
  @Post('account/password')
  @HttpCode(200)
  @UseGuards(SessionRateLimit, JwtAuthGuard)
  changePassword(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: ChangePasswordDto,
  ): Promise<AuthResponse> {
    return this.auth.changePassword(user.id, dto);
  }

  @Patch('account')
  @UseGuards(JwtAuthGuard)
  updateAccount(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: UpdateAccountDto,
  ): Promise<PublicUser> {
    return this.auth.updateAccount(user.id, dto);
  }
}

/**
 * The slice of Prisma `AuthService` uses, behind an injection token.
 *
 * The token exists so the self-check can hand the service a fake instead of a
 * live Postgres; production still gets the same `prisma` singleton every other
 * service holds.
 */
import { prisma } from '@betweenus/database';

export const AuthDatabase = 'AUTH_DATABASE';

export type AuthDb = Pick<typeof prisma, 'user' | 'refreshToken' | 'passwordReset'>;

export const authDatabaseProvider = {
  provide: AuthDatabase,
  useValue: prisma as AuthDb,
};

import { randomBytes } from 'node:crypto';
import {
  ConflictException,
  Inject,
  Injectable,
  UnauthorizedException,
  BadRequestException,
} from '@nestjs/common';
import {
  accessTokenLifetimeSeconds,
  hashPassword,
  hashToken,
  signAccessToken,
  signRefreshToken,
  validatePasswordStrength,
  verifyPassword,
  verifyRefreshToken,
} from '@betweenus/auth';
import { type User } from '@betweenus/database';
import { AuthDatabase, type AuthDb } from './auth.db';
import { EVENTS, EventBus, type EventPayloads } from '@betweenus/events';
import { envOr } from '@betweenus/config';
import { createLogger, type LogLevel } from '@betweenus/logger';
import { sharedRedis } from '@betweenus/nest-common';
import type {
  AuthResponse,
  AuthTokens,
  ForgotPasswordResponse,
  LastSeenVisibility,
  PublicUser,
  UsernameAvailability,
} from '@betweenus/shared-types';
import { MailService, NO_MAIL_MESSAGE } from '../mail/mail.service';
import { UsernameDirectory, normalizeUsername } from './username-directory';
import { publicBaseUrl } from '../admin/oauth-providers';
import type { ChangePasswordDto, LoginDto, RegisterDto, UpdateAccountDto } from './dto';

const logger = createLogger('auth-service', envOr('LOG_LEVEL', 'info') as LogLevel);

/**
 * Days a refresh token stays valid; mirrors JWT_REFRESH_TTL for the DB row.
 *
 * It slides: every refresh rotates the token and the successor gets the full
 * window again, so this is how long an app may go *unopened* before its owner
 * has to type a password. Ninety days rather than thirty because that is the
 * question it actually answers - a phone left in a drawer over a summer - and
 * nothing is weakened by it. The token is still revoked the moment it is spent,
 * a sign-out still ends it server-side, and theft detection still revokes the
 * whole family.
 */
const REFRESH_DAYS = Number(envOr('JWT_REFRESH_TTL', '90d').replace(/\D/g, '')) || 90;

/**
 * How long a token that has just been rotated still answers with the pair that
 * rotation produced, instead of being read as theft.
 *
 * Rotation is not atomic across the network: the server can revoke a token,
 * mint its successor, and have the response lost - a reload mid-refresh, a
 * window closed, a dropped connection, two tabs asking at once. The client then
 * presents the only token it still has, which is the one already spent, and
 * without this window that is indistinguishable from a stolen token: every
 * session on every device is revoked and the person is signed out for good.
 * Read live rather than captured, so a test can turn it off.
 *
 * Inside the window the reply is the *same* pair, not a new one. A replay
 * therefore creates nothing: an attacker holding the stolen token learns
 * nothing it did not already have, and the theft detection outside the window
 * is untouched.
 */
function replayGraceMs(): number {
  return Number(envOr('REFRESH_REPLAY_GRACE_MS', '30000')) || 0;
}

/** What is kept for one rotated token, in Redis and in the in-process map alike. */
interface RotationEntry {
  tokens: AuthTokens;
  /** Milliseconds since the epoch, compared against the window as it is now. */
  at: number;
}

/**
 * How long a reset token lives.
 *
 * Short, because the whole of its security is that it is a bearer credential
 * sitting in an inbox - or, for the administrator-granted door, handed to
 * whoever typed a username. Thirty minutes is long enough to read an email and
 * short enough that a window left open is not a way in tomorrow.
 */
const RESET_TTL_MINUTES = Number(envOr('PASSWORD_RESET_TTL_MINUTES', '30')) || 30;

@Injectable()
export class AuthService {
  constructor(
    private readonly events: EventBus,
    private readonly mail: MailService,
    private readonly usernames: UsernameDirectory,
    @Inject(AuthDatabase) private readonly db: AuthDb,
  ) {}

  async register(dto: RegisterDto): Promise<AuthResponse> {
    const policyError = validatePasswordStrength(dto.password);
    if (policyError) throw new BadRequestException({ code: 'WEAK_PASSWORD', message: policyError });

    const email = dto.email.toLowerCase().trim();
    // Lower-cased, not merely trimmed: signing in by name already lowercases
    // what was typed, so a mixed-case row was a row nobody could log in to.
    const username = normalizeUsername(dto.username);

    const existing = await this.db.user.findFirst({
      where: { OR: [{ email }, { username }] },
      select: { email: true },
    });
    if (existing) {
      // Same message for either collision - do not leak which field is taken.
      throw new ConflictException({
        code: 'ACCOUNT_EXISTS',
        message: 'Email or username is already registered',
      });
    }

    const user = await this.db.user.create({
      data: {
        email,
        username,
        displayName: username,
        passwordHash: await hashPassword(dto.password),
      },
    });

    this.usernames.remember(user.username);
    await this.events.publish(EVENTS.USER_CREATED, {
      userId: user.id,
      username: user.username,
      email: user.email,
    });

    const tokens = await this.issueTokens(user);
    return { ...tokens, user: toPublicUser(user) };
  }

  async login(dto: LoginDto): Promise<AuthResponse> {
    // The field is called `email` for compatibility but accepts either; an
    // address always contains an @, a username never may.
    const identifier = dto.email.toLowerCase().trim();
    const user = await this.db.user.findUnique({
      where: identifier.includes('@') ? { email: identifier } : { username: identifier },
    });

    // Always run a comparison so a missing account and a wrong password cost the same.
    const passwordOk = user
      ? await verifyPassword(dto.password, user.passwordHash)
      : await verifyPassword(dto.password, DUMMY_HASH);

    if (!user || !passwordOk) {
      throw new UnauthorizedException({
        code: 'INVALID_CREDENTIALS',
        message: 'Invalid email or password',
      });
    }

    assertEnabled(user);

    const tokens = await this.issueTokens(user);
    return { ...tokens, user: toPublicUser(user) };
  }

  /** Rotates the refresh token: the presented token is revoked as it is consumed. */
  async refresh(refreshToken: string): Promise<AuthTokens> {
    let payload;
    try {
      payload = verifyRefreshToken(refreshToken);
    } catch {
      throw new UnauthorizedException({
        code: 'INVALID_REFRESH_TOKEN',
        message: 'Refresh token is invalid or expired',
      });
    }

    const stored = await this.db.refreshToken.findUnique({ where: { id: payload.jti } });

    // A forgery carrying a real jti is theft with no innocent explanation, so it
    // is fatal whatever else is true of the row.
    if (stored && stored.tokenHash !== hashToken(refreshToken)) {
      await this.revokeFamily(stored.familyId, stored.userId, 'forgery');
      throw new UnauthorizedException({
        code: 'REFRESH_TOKEN_REUSED',
        message: 'Refresh token was already used; all sessions have been signed out',
      });
    }

    // Reuse detection: a token this account already spent means the token
    // leaked. The holder is unknown, so every live token for the account dies
    // and both parties have to log in again - unless this is the rotation that
    // just happened and whose answer never arrived, which is what the grace
    // window above exists for.
    if (stored && stored.revokedAt !== null) {
      const replayed = await this.rotationOf(stored.id);
      if (replayed) return replayed;

      await this.revokeFamily(stored.familyId, stored.userId, 'reuse');
      throw new UnauthorizedException({
        code: 'REFRESH_TOKEN_REUSED',
        message: 'Refresh token was already used; all sessions have been signed out',
      });
    }

    if (!stored || stored.expiresAt.getTime() < Date.now()) {
      throw new UnauthorizedException({
        code: 'INVALID_REFRESH_TOKEN',
        message: 'Refresh token is invalid or expired',
      });
    }

    const user = await this.db.user.findUnique({ where: { id: stored.userId } });
    if (!user) {
      throw new UnauthorizedException({ code: 'INVALID_REFRESH_TOKEN', message: 'Unknown account' });
    }

    // A disabled account keeps its refresh token but cannot spend it.
    assertEnabled(user);

    await this.db.refreshToken.update({
      where: { id: stored.id },
      data: { revokedAt: new Date() },
    });

    const tokens = await this.issueTokens(user, stored.familyId);
    await this.remember(stored.id, tokens);
    return tokens;
  }

  /**
   * What the token with this id was rotated into, for as long as a client that
   * missed the answer might ask again.
   *
   * In Redis, so a replay that lands on a *different* auth-service instance is
   * answered rather than read as theft. Per process, that case signed the
   * account out - every device of it - for the crime of a dropped response, and
   * it was the reason a second instance could not be run behind the gateway.
   *
   * The key's TTL is the cleanup and the *read* is the decision. Both, and not
   * either alone: a TTL with no timestamp means an entry written while the
   * window was thirty seconds is still answered after the window is turned off,
   * which is the auth-service check failing on the line that shortens it to
   * zero - and in a deployment, a configuration change that quietly does not
   * take effect for another thirty seconds. A timestamp with no TTL means keys
   * that are never collected. So the entry carries when it was written, the read
   * compares that against the window as it is *now*, and Redis sweeps up behind.
   */
  private rotationKey(jti: string): string {
    return `auth:rotated:${jti}`;
  }

  /**
   * The local half, kept deliberately.
   *
   * It is not a cache. It is what this falls back to when Redis does not answer,
   * and the reason to keep it is that the failure it prevents is the one being
   * fixed: without it, a Redis outage would turn every interrupted rotation into
   * a full sign-out, which is strictly worse than the per-process behaviour this
   * replaces. With it, an unreachable Redis degrades to exactly what the service
   * did before - one instance answers its own replays - and nothing regresses.
   *
   * It is read first for the same reason, plus one: the common case is a client
   * retrying within a second or two through the same connection, and that is
   * already the instance holding the answer.
   */
  private readonly rotated = new Map<string, RotationEntry>();

  /** The pair this token was rotated into, if the window is still open. */
  private async rotationOf(jti: string): Promise<AuthTokens | null> {
    const grace = replayGraceMs();
    if (grace <= 0) return null;

    const local = this.rotated.get(jti);
    if (local && Date.now() - local.at < grace) return local.tokens;

    try {
      const raw = await sharedRedis().get(this.rotationKey(jti));
      // No key is the ordinary answer, not an error: either the window closed or
      // this token was never rotated, and both are a replay to be refused.
      if (!raw) return null;
      const entry = JSON.parse(raw) as RotationEntry;
      return Date.now() - entry.at < grace ? entry.tokens : null;
    } catch (error) {
      // Fall back to what the local map said, which is "no". A Redis that cannot
      // be reached must not be a reason to hand a session to a replayed token,
      // and it is also not a reason to fail the request outright - the caller
      // below will treat this as theft, which is the pre-existing behaviour.
      logger.warn('Could not read a rotation grace entry', {
        jti,
        error: String(error),
      });
      return null;
    }
  }

  private async remember(jti: string, tokens: AuthTokens): Promise<void> {
    const grace = replayGraceMs();
    const cutoff = Date.now() - grace;
    for (const [id, entry] of this.rotated) {
      if (entry.at < cutoff) this.rotated.delete(id);
    }
    this.rotated.set(jti, { tokens, at: Date.now() });

    // Zero means the window is off - a test turning it off, or a deployment that
    // wants replays read as theft immediately. `PX 0` is an error rather than an
    // instant expiry, so there is nothing to write.
    if (grace <= 0) return;

    const entry: RotationEntry = { tokens, at: Date.now() };
    try {
      await sharedRedis().set(this.rotationKey(jti), JSON.stringify(entry), 'PX', grace);
    } catch (error) {
      // The local map already has it, so this instance still answers its own
      // replays. What is lost is the cross-instance half, which is what this
      // whole change is - so it is a warning and not a failed refresh.
      logger.warn('Could not store a rotation grace entry', {
        jti,
        error: String(error),
      });
    }
  }

  async logout(refreshToken: string): Promise<void> {
    try {
      const payload = verifyRefreshToken(refreshToken);
      await this.db.refreshToken.updateMany({
        where: { id: payload.jti, revokedAt: null },
        data: { revokedAt: new Date() },
      });
    } catch {
      // Logging out with a dead token is not an error worth surfacing.
    }
  }

  async me(userId: string): Promise<PublicUser> {
    const user = await this.db.user.findUnique({ where: { id: userId } });
    if (!user) {
      throw new UnauthorizedException({ code: 'UNKNOWN_USER', message: 'Account no longer exists' });
    }
    return toPublicUser(user);
  }

  /**
   * Changing the password clears `mustChangePassword` and signs every other
   * session out - including the one the generated password created.
   */
  async changePassword(userId: string, dto: ChangePasswordDto): Promise<AuthResponse> {
    const user = await this.db.user.findUnique({ where: { id: userId } });
    if (!user) {
      throw new UnauthorizedException({ code: 'UNKNOWN_USER', message: 'Account no longer exists' });
    }

    if (!(await verifyPassword(dto.currentPassword, user.passwordHash))) {
      throw new UnauthorizedException({
        code: 'INVALID_CREDENTIALS',
        message: 'Current password is incorrect',
      });
    }

    const policyError = validatePasswordStrength(dto.newPassword);
    if (policyError) throw new BadRequestException({ code: 'WEAK_PASSWORD', message: policyError });

    const updated = await this.db.user.update({
      where: { id: userId },
      data: {
        passwordHash: await hashPassword(dto.newPassword),
        mustChangePassword: false,
      },
    });
    await this.revokeEverySession(userId, 'password-change');
    // The open sockets as well, which is the case this feature is really for:
    // changing a password because somebody else is in the account. Their chat
    // socket was authenticated before this line and goes; the pair minted below
    // is dated after it and stays, so the person doing it keeps their session.
    //
    // Their own *existing* sockets go too - there is no way for a gateway to
    // tell one of an account's sockets from another - so the client reconnects
    // with the new token. A moment's reconnect on the device that just changed
    // its own password is the price of the intruder's socket closing at all.
    await this.revokeSockets(userId, 'password-changed');

    // Every session died, including this one - hand back a fresh pair so the
    // caller who just proved they know the password stays signed in.
    const tokens = await this.issueTokens(updated);
    return { ...tokens, user: toPublicUser(updated) };
  }

  /** Whether a name can be registered. Cheap by construction - see the directory. */
  usernameAvailable(username: string): Promise<UsernameAvailability> {
    const normalized = normalizeUsername(username);
    return this.usernames
      .available(normalized)
      .then((answer) => ({ username: normalized, ...answer }));
  }

  /**
   * What a forgotten password can be done about, on this deployment, for this
   * account.
   *
   * Three answers, and only one of them is about the account:
   *
   * - `reset`: an administrator has already put the account into reset mode, so
   *   this call mints the single-use token and the client goes straight to a
   *   new-password form. This is the door a deployment with no mail server
   *   uses, and it is deliberately the first thing checked - an operator who
   *   went and enabled it means it.
   * - `emailed`: a link went out, or the account does not exist. The two are
   *   the same answer on purpose. Anything that told them apart would turn this
   *   form into a way to enumerate who has an account here.
   * - `unavailable`: nothing is configured to send mail, which is a fact about
   *   the deployment and not about the account, so saying it leaks nothing.
   */
  async forgotPassword(identifier: string): Promise<ForgotPasswordResponse> {
    const trimmed = identifier.toLowerCase().trim();
    const user = await this.db.user.findUnique({
      where: trimmed.includes('@') ? { email: trimmed } : { username: trimmed },
    });

    // A disabled account gets the same nothing an unknown one does: it is
    // barred from signing in, and a new password would not change that.
    const eligible = user && user.disabledAt === null ? user : null;

    if (eligible?.passwordResetUntil && eligible.passwordResetUntil.getTime() > Date.now()) {
      const { token } = await this.mintReset(eligible.id, 'admin');
      return { outcome: 'reset', resetToken: token };
    }

    if (!(await this.mail.configured())) {
      return { outcome: 'unavailable', message: NO_MAIL_MESSAGE };
    }

    if (eligible) {
      const { token } = await this.mintReset(eligible.id, 'email');
      const link = `${publicBaseUrl()}/reset-password?token=${encodeURIComponent(token)}`;
      // The result is not inspected and not surfaced. A bounce is between the
      // operator and their mail server; the person at the form gets the same
      // sentence either way, which is the same reason the unknown-account case
      // does not differ.
      await this.mail.send({
        to: eligible.email,
        subject: 'Reset your BetweenUs password',
        text: [
          `Hello ${eligible.displayName},`,
          '',
          'Somebody asked to reset the password for your BetweenUs account.',
          'If that was not you, ignore this message - nothing has changed yet.',
          '',
          `Open this link to choose a new password: ${link}`,
          '',
          `Or paste this code into the app: ${token}`,
          '',
          `The link stops working in ${RESET_TTL_MINUTES} minutes and can be used once.`,
        ].join('\n'),
      });
    }

    return { outcome: 'emailed' };
  }

  /**
   * Spends a reset token and sets the password.
   *
   * Every session goes with it, the same as an ordinary password change: the
   * person who needed this door is very often the person whose account was
   * taken, and leaving the other side signed in would make the reset
   * decorative. The administrator-granted window is closed too, so one grant is
   * one reset rather than a standing invitation.
   */
  async resetPassword(token: string, newPassword: string): Promise<AuthResponse> {
    const policyError = validatePasswordStrength(newPassword);
    if (policyError) throw new BadRequestException({ code: 'WEAK_PASSWORD', message: policyError });

    const row = await this.db.passwordReset.findUnique({ where: { tokenHash: hashToken(token) } });
    if (!row || row.usedAt !== null || row.expiresAt.getTime() < Date.now()) {
      throw new UnauthorizedException({
        code: 'INVALID_RESET_TOKEN',
        message: 'This reset link has expired or has already been used',
      });
    }

    const user = await this.db.user.findUnique({ where: { id: row.userId } });
    if (!user) {
      throw new UnauthorizedException({ code: 'UNKNOWN_USER', message: 'Account no longer exists' });
    }
    assertEnabled(user);

    // Marked spent before the password moves. If the update fails afterwards
    // the token is burnt and the person asks again, which is the cheap failure;
    // the other order leaves a live token behind a password that already
    // changed, which is the expensive one.
    await this.db.passwordReset.update({ where: { id: row.id }, data: { usedAt: new Date() } });

    const updated = await this.db.user.update({
      where: { id: user.id },
      data: {
        passwordHash: await hashPassword(newPassword),
        mustChangePassword: false,
        passwordResetUntil: null,
      },
    });
    await this.revokeEverySession(user.id, 'password-reset');
    logger.warn('Password reset spent', { userId: user.id, source: row.source });

    const tokens = await this.issueTokens(updated);
    return { ...tokens, user: toPublicUser(updated) };
  }

  /**
   * A fresh single-use token, with only its hash left behind.
   *
   * Any token this account already had is burnt first: two live links is two
   * chances for the one that leaked, and the person asking again is asking
   * because the first did not reach them.
   */
  private async mintReset(userId: string, source: 'admin' | 'email'): Promise<{ token: string }> {
    await this.db.passwordReset.updateMany({
      where: { userId, usedAt: null },
      data: { usedAt: new Date() },
    });

    const token = randomBytes(32).toString('base64url');
    await this.db.passwordReset.create({
      data: {
        userId,
        tokenHash: hashToken(token),
        source,
        expiresAt: new Date(Date.now() + RESET_TTL_MINUTES * 60 * 1000),
      },
    });
    return { token };
  }

  async updateAccount(userId: string, dto: UpdateAccountDto): Promise<PublicUser> {
    const username = dto.username ? normalizeUsername(dto.username) : undefined;
    if (username) {
      const taken = await this.db.user.findUnique({ where: { username } });
      if (taken && taken.id !== userId) {
        throw new ConflictException({
          code: 'ACCOUNT_EXISTS',
          message: 'That username is already taken',
        });
      }
    }

    const updated = await this.db.user.update({
      where: { id: userId },
      data: {
        ...(username ? { username } : {}),
        ...(dto.displayName?.trim() ? { displayName: dto.displayName.trim() } : {}),
        // null is a real value here - it clears the picture back to the
        // initial - so only an absent key means "leave it alone".
        ...(dto.avatarUrl !== undefined ? { avatarUrl: dto.avatarUrl } : {}),
        // And the same for the wide one behind it: null clears it back to the
        // flat accent band, an absent key leaves it alone.
        ...(dto.coverUrl !== undefined ? { coverUrl: dto.coverUrl } : {}),
        // Trimmed, and an empty string is a value: it means "draw no line
        // under my name", which is different from never having touched it.
        ...(dto.about !== undefined ? { about: dto.about.trim() } : {}),
        // The wire spells it lower case and the column spells it upper; one
        // conversion each way, both in this file, so nothing else has to know
        // there are two spellings.
        ...(dto.lastSeenVisibility !== undefined
          ? { lastSeenVisibility: fromVisibility(dto.lastSeenVisibility) }
          : {}),
        // Same rule: null is "switch the personal disappearing window off",
        // which is a value, and an absent key is "do not touch it".
        ...(dto.messageTtlSeconds !== undefined
          ? { messageTtlSeconds: dto.messageTtlSeconds }
          : {}),
      },
    });

    if (username) this.usernames.remember(username);

    // Everyone who can see this account has the old picture and the old name on
    // screen right now. Published unconditionally rather than diffed: a write
    // that changed nothing is a broadcast nobody notices, where a diff that
    // gets one field wrong is a stale avatar until the next reload.
    await this.events.publish(EVENTS.USER_UPDATED, {
      user: {
        id: updated.id,
        username: updated.username,
        displayName: updated.displayName,
        avatarUrl: updated.avatarUrl,
        coverUrl: updated.coverUrl,
        about: updated.about,
      },
    });
    return toPublicUser(updated);
  }

  /**
   * Signs out one sign-in - the chain of tokens descended from it - and
   * nothing else. Used when a refresh token leaks.
   *
   * Scoped to the family rather than the account because a person is signed in
   * on more than one device, and the two chains have nothing to do with each
   * other: a token replayed on a phone says nothing about the laptop. Revoking
   * by `userId` here is what made a second device impossible to stay signed in
   * on - every interrupted rotation anywhere signed every device out.
   *
   * A stolen token is still contained: the thief and the victim share one
   * family, so both halves of the contested chain die together.
   */
  private async revokeFamily(familyId: string, userId: string, reason: string): Promise<void> {
    const { count } = await this.db.refreshToken.updateMany({
      where: { familyId, revokedAt: null },
      data: { revokedAt: new Date() },
    });
    // Audit trail: a reuse warning is the signal that a token was stolen.
    logger.warn('Refresh token family revoked', { familyId, reason, revoked: count });

    // A family is one chain on one device, but the token was stolen and nobody
    // knows which end is holding it - so the sockets go too, both ends of the
    // contested chain, the same way the refresh tokens do.
    //
    // `userId` is passed rather than looked up: both callers are holding the row
    // this family was found through, and a second query to re-read a column they
    // already have is a query for nothing.
    await this.revokeSockets(userId, 'token-reuse');
  }

  /** Signs out every device of an account. The password changing is the case. */
  private async revokeEverySession(userId: string, reason: string): Promise<void> {
    const { count } = await this.db.refreshToken.updateMany({
      where: { userId, revokedAt: null },
      data: { revokedAt: new Date() },
    });
    logger.warn('Refresh tokens revoked', { userId, reason, revoked: count });
  }

  /**
   * Tells the gateways to drop this account's open sockets.
   *
   * Revoking refresh tokens stops a session being *renewed*, which is fifteen
   * minutes late for an access token and forever for a socket - a handshake is
   * authenticated once and then trusted until it disconnects. This is the other
   * half, and it is a published event rather than a call because the sockets are
   * spread across four services and however many instances of each.
   *
   * The line is drawn at the current second, so anything minted from now on
   * survives it. That is what lets `changePassword` use the same call as
   * `disable`: the person changing their own password is handed a new pair in
   * the same response, and it is newer than the line.
   *
   * Failure is logged and swallowed. A revocation that cannot reach Redis must
   * not turn "your account is disabled" into a 500 that leaves the account
   * enabled - the refresh tokens are already dead in Postgres, which is the
   * durable half, and the socket is the fifteen-minute half.
   */
  private async revokeSockets(
    userId: string,
    reason: EventPayloads[typeof EVENTS.SESSION_REVOKED]['reason'],
  ): Promise<void> {
    try {
      await this.events.publish(EVENTS.SESSION_REVOKED, {
        userId,
        notBefore: Math.floor(Date.now() / 1000),
        reason,
      });
    } catch (error) {
      logger.warn('Could not publish a session revocation', { userId, reason, error: String(error) });
    }
  }

  /** Same session minting the password path uses; OAuth sign-in needs it too. */
  async issueTokensFor(user: User): Promise<AuthTokens> {
    return this.issueTokens(user);
  }

  /**
   * A new token, in [familyId]'s chain or starting one of its own.
   *
   * A sign-in starts a family; a rotation stays in the one it came from. That
   * is the whole of what makes two devices independent.
   */
  private async issueTokens(user: User, familyId?: string): Promise<AuthTokens> {
    const accessToken = signAccessToken(user);
    const { token: refreshToken, jti } = signRefreshToken(user.id);

    await this.db.refreshToken.create({
      data: {
        id: jti,
        userId: user.id,
        familyId: familyId ?? jti,
        tokenHash: hashToken(refreshToken),
        expiresAt: new Date(Date.now() + REFRESH_DAYS * 24 * 60 * 60 * 1000),
      },
    });

    return { accessToken, refreshToken, expiresIn: accessTokenLifetimeSeconds() };
  }
}

/** A disabled account is refused everywhere a session could be created. */
function assertEnabled(user: User): void {
  if (user.disabledAt === null) return;
  throw new UnauthorizedException({
    code: 'ACCOUNT_DISABLED',
    message: 'This account has been disabled',
  });
}

/** bcrypt hash of a value nobody can log in with; used to equalise login timing. */
const DUMMY_HASH = '$2a$12$C6UzMDM.H6dfI/f/IKcEe.4Y8Q3M4RwuHhWzR0GkD8hR4T6Bl0Wcy';

/**
 * The column's spelling of a last-seen setting, in the one the wire uses.
 *
 * An unknown value is read as the widest it could be narrowed from, which is
 * also what the column defaults to: guessing narrower would silently hide
 * people who never asked to be hidden, and this only ever sees a value written
 * by a build that had the enum.
 */
export function toVisibility(value: string): LastSeenVisibility {
  switch (value) {
    case 'FRIENDS':
      return 'friends';
    case 'NOBODY':
      return 'nobody';
    default:
      return 'everyone';
  }
}

/** And back, for a write. */
function fromVisibility(value: LastSeenVisibility): 'EVERYONE' | 'FRIENDS' | 'NOBODY' {
  switch (value) {
    case 'friends':
      return 'FRIENDS';
    case 'nobody':
      return 'NOBODY';
    case 'everyone':
      return 'EVERYONE';
  }
}

export function toPublicUser(user: User): PublicUser {
  return {
    id: user.id,
    email: user.email,
    username: user.username,
    displayName: user.displayName,
    avatarUrl: user.avatarUrl,
    coverUrl: user.coverUrl,
    about: user.about,
    lastSeenVisibility: toVisibility(user.lastSeenVisibility),
    role: user.role,
    mustChangePassword: user.mustChangePassword,
    messageTtlSeconds: user.messageTtlSeconds,
    createdAt: user.createdAt.toISOString(),
  };
}

/**
 * A Bloom filter, and nothing more than one.
 *
 * It answers one question - "have I definitely never seen this?" - and it
 * answers it without touching the database. A `false` from `mightHave` is
 * final: the filter has no false negatives, so a username it has never been
 * given is a username nobody has registered. A `true` is a maybe, and the
 * caller settles it with the query it was trying to avoid.
 *
 * That asymmetry is the whole point of using one here. Somebody typing a name
 * into the registration form generates a lookup per keystroke, and almost every
 * one of those is for a name nobody has - so almost every one is answered from
 * a bit array in memory, and the database only sees the handful of near-misses.
 *
 * Written out rather than taken from a package: it is two hash functions and a
 * `Uint8Array`, and a dependency in the sign-up path is a bigger thing to own
 * than thirty lines.
 */

/** Bits per entry and hash count for a target false-positive rate. */
export function sizing(expectedItems: number, falsePositiveRate: number): {
  bits: number;
  hashes: number;
} {
  const items = Math.max(1, Math.trunc(expectedItems));
  const rate = Math.min(Math.max(falsePositiveRate, 1e-6), 0.5);
  // The standard optimum: m = -n ln p / (ln 2)^2, k = (m/n) ln 2. Rounded up,
  // so the real rate is at or under the one asked for rather than near it.
  const bits = Math.ceil((-items * Math.log(rate)) / (Math.LN2 * Math.LN2));
  const hashes = Math.max(1, Math.round((bits / items) * Math.LN2));
  return { bits, hashes };
}

/** FNV-1a, 32-bit, seeded. Not a cryptographic hash and does not need to be. */
function fnv1a(value: string, seed: number): number {
  let hash = seed >>> 0;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    // The FNV prime, 16777619, by shifts - `Math.imul` keeps it 32-bit.
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash >>> 0;
}

export class BloomFilter {
  private readonly bits: Uint8Array;
  private readonly bitCount: number;
  private readonly hashes: number;
  /** How many values have been added; only ever read for diagnostics. */
  private items = 0;

  constructor(expectedItems: number, falsePositiveRate = 0.001) {
    const { bits, hashes } = sizing(expectedItems, falsePositiveRate);
    this.bitCount = bits;
    this.hashes = hashes;
    this.bits = new Uint8Array(Math.ceil(bits / 8));
  }

  get size(): number {
    return this.items;
  }

  add(value: string): void {
    for (const bit of this.positions(value)) {
      this.bits[bit >>> 3]! |= 1 << (bit & 7);
    }
    this.items += 1;
  }

  /** False is certain; true means "ask the database". */
  mightHave(value: string): boolean {
    for (const bit of this.positions(value)) {
      if ((this.bits[bit >>> 3]! & (1 << (bit & 7))) === 0) return false;
    }
    return true;
  }

  /**
   * Kirsch-Mitzenmacher double hashing: k indices from two hashes rather than
   * k independent ones, which costs two passes over the string instead of k
   * and is indistinguishable in false-positive rate.
   *
   * `h2` is forced odd so it is coprime with nothing in particular but never
   * zero - a zero step would put every index on the same bit.
   */
  private *positions(value: string): Generator<number> {
    const h1 = fnv1a(value, 0x811c9dc5);
    const h2 = fnv1a(value, 0x9e3779b9) | 1;
    for (let index = 0; index < this.hashes; index += 1) {
      // >>> 0 after the multiply-add, so the sum stays a 32-bit unsigned value
      // rather than drifting into the float range and losing its low bits.
      yield ((h1 + Math.imul(index, h2)) >>> 0) % this.bitCount;
    }
  }
}

import {
  IsEmail,
  IsIn,
  IsOptional,
  IsString,
  Length,
  Matches,
  MaxLength,
  MinLength,
  ValidateIf,
} from 'class-validator';
import {
  ABOUT_MAX_LENGTH,
  DISAPPEARING_WINDOWS,
  LAST_SEEN_VISIBILITIES,
  UPLOADED_PICTURE_URL,
} from '@betweenus/shared-types';
import type {
  ChangePasswordRequest,
  LastSeenVisibility,
  ForgotPasswordRequest,
  LoginRequest,
  RefreshRequest,
  RegisterRequest,
  ResetPasswordRequest,
  UpdateAccountRequest,
} from '@betweenus/shared-types';

export class RegisterDto implements RegisterRequest {
  @IsEmail()
  @MaxLength(254)
  email!: string;

  @IsString()
  @Length(3, 32)
  @Matches(/^[a-z0-9_.-]+$/i, {
    message: 'Username may contain letters, numbers, dot, dash and underscore only',
  })
  username!: string;

  @IsString()
  @MinLength(8)
  @MaxLength(200)
  password!: string;
}

export class LoginDto implements LoginRequest {
  /**
   * Email or username. The admin account is created with a username and no
   * memorable address, and people type whichever they remember anyway.
   */
  @IsString()
  @Length(3, 254, { message: 'Enter your username or email address' })
  email!: string;

  @IsString()
  @MaxLength(200)
  password!: string;
}

export class RefreshDto implements RefreshRequest {
  @IsString()
  @MaxLength(4096)
  refreshToken!: string;
}

export class ChangePasswordDto implements ChangePasswordRequest {
  @IsString()
  @MaxLength(200)
  currentPassword!: string;

  @IsString()
  @MinLength(8)
  @MaxLength(200)
  newPassword!: string;
}

export class ForgotPasswordDto implements ForgotPasswordRequest {
  /** Email or username - the same field the login form takes. */
  @IsString()
  @Length(3, 254, { message: 'Enter your username or email address' })
  identifier!: string;
}

export class ResetPasswordDto implements ResetPasswordRequest {
  @IsString()
  @Length(16, 200)
  token!: string;

  @IsString()
  @MinLength(8)
  @MaxLength(200)
  newPassword!: string;
}

export class UpdateAccountDto implements UpdateAccountRequest {
  @IsOptional()
  @IsString()
  @Length(3, 32)
  @Matches(/^[a-z0-9_.-]+$/i, {
    message: 'Username may contain letters, numbers, dot, dash and underscore only',
  })
  username?: string;

  @IsOptional()
  @IsString()
  @Length(1, 64)
  displayName?: string;

  /**
   * The line under the name on a profile card.
   *
   * An empty string is allowed and means "draw no line", so the lower bound is
   * zero rather than one. The upper bound is `ABOUT_MAX_LENGTH`, measured in
   * UTF-16 units by `MaxLength` where the clients count code points - a line of
   * astral emoji is therefore cut off by the client before it ever reaches a
   * limit here, which is the safe direction for the two counts to disagree in.
   */
  @IsOptional()
  @IsString()
  @MaxLength(ABOUT_MAX_LENGTH * 2)
  about?: string;

  /**
   * Who may see when this account was last here.
   *
   * Validated against the published list rather than trusted, because an
   * unrecognised value written straight through would be a privacy setting
   * nothing can read back - and the safe reading of one of those is the widest,
   * which is the opposite of what somebody narrowing it intended.
   */
  @IsOptional()
  @IsIn(LAST_SEEN_VISIBILITIES)
  lastSeenVisibility?: LastSeenVisibility;

  /**
   * An uploaded picture, or null to go back to the initial. It has to be one of
   * ours: an avatar renders in every client that can see the account, so an
   * arbitrary URL here would be a beacon that reports back who looked at it.
   */
  @ValidateIf((dto: UpdateAccountDto) => dto.avatarUrl !== null && dto.avatarUrl !== undefined)
  @IsString()
  @MaxLength(512)
  @Matches(UPLOADED_PICTURE_URL, { message: 'avatarUrl must be an uploaded picture' })
  avatarUrl?: string | null;

  /**
   * The wide picture behind the name, or null to go back to the flat accent
   * band. Held to the same rule as `avatarUrl` and for the same reason: a
   * profile picture is fetched by every client that can see the account, so an
   * arbitrary URL here would be a beacon reporting who looked at whom.
   */
  @ValidateIf((dto: UpdateAccountDto) => dto.coverUrl !== null && dto.coverUrl !== undefined)
  @IsString()
  @MaxLength(512)
  @Matches(UPLOADED_PICTURE_URL, { message: 'coverUrl must be an uploaded picture' })
  coverUrl?: string | null;

  /**
   * This account's own disappearing window in seconds, or null to switch it
   * off. One of the published list, for the same reason a server's is.
   *
   * It hides history from this account on every device it signs in on and
   * changes nothing for anybody else - so it is a preference and not a
   * retention policy, and a server's own window still outranks it.
   */
  @IsOptional()
  @IsIn([null, ...DISAPPEARING_WINDOWS], {
    message: 'messageTtlSeconds must be null or one of the published windows',
  })
  messageTtlSeconds?: number | null;
}

/**
 * "Is this username taken?", answered without a query in the common case.
 *
 * The registration form asks once per keystroke. Almost every one of those is
 * a name nobody has, and a Bloom filter answers exactly that shape of question
 * for free: it has no false negatives, so a name it has never been given is a
 * name that has never been registered, and only the near-misses reach Postgres.
 *
 * The database's unique constraint is still the thing that decides. This is a
 * cache in front of it and is treated as one - see `available` below, which
 * never returns "taken" on the filter's word alone.
 */
import { Inject, Injectable, type OnModuleInit } from '@nestjs/common';
import { envOr } from '@betweenus/config';
import { createLogger, type LogLevel } from '@betweenus/logger';
import { BloomFilter } from './bloom';
import { AuthDatabase, type AuthDb } from './auth.db';

const logger = createLogger('auth-service', envOr('LOG_LEVEL', 'info') as LogLevel);

/**
 * What the filter is sized for. Not a cap: exceeding it costs a higher
 * false-positive rate, which costs a database lookup that would have happened
 * anyway, and nothing else.
 */
const EXPECTED_ACCOUNTS = Number(envOr('USERNAME_BLOOM_CAPACITY', '200000')) || 200_000;
const FALSE_POSITIVE_RATE = 0.001;

/** The rule the DTO enforces, repeated here so the answer matches the refusal. */
const USERNAME_PATTERN = /^[a-z0-9_.-]{3,32}$/;

/**
 * Usernames are compared in lower case.
 *
 * They always were, one step downstream: signing in lowercases what was typed
 * before looking the account up. Doing it here as well is what makes that true
 * rather than nearly true - `Ayaan` and `ayaan` were two rows the unique index
 * was happy with and only one of which could ever log in by name.
 */
export function normalizeUsername(username: string): string {
  return username.trim().toLowerCase();
}

@Injectable()
export class UsernameDirectory implements OnModuleInit {
  private readonly filter = new BloomFilter(EXPECTED_ACCOUNTS, FALSE_POSITIVE_RATE);

  constructor(@Inject(AuthDatabase) private readonly db: AuthDb) {}

  /**
   * Loads every existing username into the filter at boot.
   *
   * ponytail: one filter per process, built once and never rebuilt. A username
   * registered against another instance is absent from this one's filter until
   * it restarts, which makes this instance say "available" for a name that is
   * not - and then the unique constraint refuses the registration with the
   * message it would have shown anyway. Share it through Redis if the answer
   * being momentarily optimistic ever matters more than it does today.
   */
  async onModuleInit(): Promise<void> {
    await this.warm();
  }

  async warm(): Promise<void> {
    const rows = await this.db.user.findMany({ select: { username: true } });
    for (const row of rows) this.filter.add(normalizeUsername(row.username));
    logger.info('Username filter warmed', { usernames: rows.length });
  }

  /** Called after a registration or a rename, so this process stops offering it. */
  remember(username: string): void {
    this.filter.add(normalizeUsername(username));
  }

  /**
   * Whether the name can be registered.
   *
   * The filter can only ever save a lookup, never cause a wrong "taken": a
   * `false` from it is certain, and a `true` is checked against the table
   * before anybody is told the name is gone.
   */
  async available(username: string): Promise<{ available: boolean; reason?: 'taken' | 'invalid' }> {
    const normalized = normalizeUsername(username);
    if (!USERNAME_PATTERN.test(normalized)) return { available: false, reason: 'invalid' };

    if (!this.filter.mightHave(normalized)) return { available: true };

    const taken = await this.db.user.findUnique({
      where: { username: normalized },
      select: { id: true },
    });
    return taken ? { available: false, reason: 'taken' } : { available: true };
  }
}

/**
 * The deployment's outgoing mail, and its absence.
 *
 * BetweenUs is meant to be self-hosted, and a self-hosted deployment very often
 * has no mail server at all - so "cannot send" is a first-class answer here
 * rather than an error. Every caller has to handle it, and what the person on
 * screen is told is that they should ask their administrator, which is true and
 * actionable in a way "500" is not.
 *
 * The transport is built per send rather than held open. Sends are rare - a
 * forgotten password, a test from the admin panel - and a pooled connection
 * would have to be torn down and rebuilt every time the settings change, which
 * is the only other thing that ever happens to it.
 */
import { Injectable } from '@nestjs/common';
import { createTransport } from 'nodemailer';
import { openSecret } from '@betweenus/auth';
import { prisma, type SmtpSetting } from '@betweenus/database';
import { envOr } from '@betweenus/config';
import { createLogger, type LogLevel } from '@betweenus/logger';

const logger = createLogger('auth-service', envOr('LOG_LEVEL', 'info') as LogLevel);

/** What every screen says when the operator has not configured a mail server. */
export const NO_MAIL_MESSAGE =
  'This server cannot send email. Ask your administrator to reset your password.';

export interface Mail {
  to: string;
  subject: string;
  text: string;
  html?: string;
}

@Injectable()
export class MailService {
  /** The stored row, or null when nobody has configured one. */
  async settings(): Promise<SmtpSetting | null> {
    return prisma.smtpSetting.findUnique({ where: { id: 'smtp' } });
  }

  /**
   * True when a send would actually be attempted. A row that exists but is
   * switched off, or one missing the two fields no SMTP session can start
   * without, is the same as no row at all.
   */
  async configured(): Promise<boolean> {
    const row = await this.settings();
    return Boolean(row?.enabled && row.host.trim() && row.fromAddress.trim());
  }

  /**
   * Sends, or says why it could not.
   *
   * Never throws. A mail server that is refusing connections must not turn a
   * password reset into a 500 - the caller decides what to do about it, and in
   * every case so far that is "tell them to ask their administrator".
   */
  async send(mail: Mail): Promise<{ ok: boolean; error?: string }> {
    const row = await this.settings();
    if (!row?.enabled || !row.host.trim() || !row.fromAddress.trim()) {
      return { ok: false, error: NO_MAIL_MESSAGE };
    }

    // A blank username means an unauthenticated relay, which is a normal shape
    // for a mail server sitting on the same private network.
    const password = row.password ? openSecret(row.password) : null;
    const transport = createTransport({
      host: row.host.trim(),
      port: row.port,
      secure: row.secure,
      ...(row.username.trim()
        ? { auth: { user: row.username.trim(), pass: password ?? '' } }
        : {}),
    });

    try {
      await transport.sendMail({
        from: row.fromName.trim()
          ? { name: row.fromName.trim(), address: row.fromAddress.trim() }
          : row.fromAddress.trim(),
        to: mail.to,
        subject: mail.subject,
        text: mail.text,
        ...(mail.html ? { html: mail.html } : {}),
      });
      return { ok: true };
    } catch (error) {
      // The host and the recipient, never the password and never the body.
      const reason = error instanceof Error ? error.message : 'Send failed';
      logger.warn('SMTP send failed', { host: row.host, reason });
      return { ok: false, error: reason };
    } finally {
      transport.close();
    }
  }
}

import { IsOptional, IsString, Length, MaxLength } from 'class-validator';
import type { OAuthExchangeRequest } from '@betweenus/shared-types';

export class OAuthExchangeDto implements OAuthExchangeRequest {
  @IsString()
  @MaxLength(100)
  code!: string;

  /** The secret behind the challenge, for a sign-in that was started with one. */
  @IsOptional()
  @IsString()
  @Length(43, 128)
  verifier?: string;
}

import {
  BadRequestException,
  Body,
  Controller,
  Get,
  HttpCode,
  NotFoundException,
  Param,
  Post,
  Query,
  Res,
  UseGuards,
} from '@nestjs/common';
import type { Response } from 'express';
import { rateLimit } from '@betweenus/nest-common';
import {
  API_CONTRACT_VERSION,
  type AuthResponse,
  type OAuthProviderSummary,
  type ServerVersion,
} from '@betweenus/shared-types';
import { isProviderName } from '../admin/oauth-providers';
import { OAuthExchangeDto } from './dto';
import { OAuthService } from './oauth.service';

/** A browser flow, so the budget is per address and roomy enough for retries. */
const OAuthRateLimit = rateLimit({ limit: 30, windowSeconds: 60, name: 'oauth' });

@Controller('auth/oauth')
export class OAuthController {
  constructor(private readonly oauth: OAuthService) {}

  /**
   * What this deployment speaks, so a client can find out it is too old before
   * a request fails in a way nobody can read.
   *
   * Public and unauthenticated, because the answer decides whether signing in
   * is worth attempting at all. It lives on the OAuth controller because the
   * client already probes `oauth/providers` on this exact path when it is
   * pointed at a deployment, so this costs no new routing anywhere.
   */
  @Get('version')
  version(): ServerVersion {
    return {
      contract: API_CONTRACT_VERSION,
      release: process.env.BETWEENUS_RELEASE ?? 'dev',
    };
  }

  /** Public: the login screen asks this before drawing its buttons. */
  @Get('providers')
  providers(): Promise<OAuthProviderSummary[]> {
    return this.oauth.enabledProviders();
  }

  /**
   * Entry point, opened in a real browser. `redirect` is where the finished
   * sign-in comes back to - a loopback URL for the desktop client.
   */
  @Get(':provider/start')
  @UseGuards(OAuthRateLimit)
  async start(
    @Param('provider') provider: string,
    @Query('redirect') redirect: string,
    @Query('challenge') challenge: string | undefined,
    @Res() response: Response,
  ): Promise<void> {
    if (!isProviderName(provider)) {
      throw new NotFoundException({ code: 'UNKNOWN_PROVIDER', message: 'No such provider' });
    }
    if (!redirect) {
      throw new BadRequestException({ code: 'BAD_REDIRECT', message: 'A redirect is required' });
    }
    response.redirect(await this.oauth.authorizeUrl(provider, redirect, challenge));
  }

  /** Where the provider sends the browser back to. Never called by a client. */
  @Get(':provider/callback')
  @UseGuards(OAuthRateLimit)
  async callback(
    @Param('provider') provider: string,
    @Query('code') code: string,
    @Query('state') state: string,
    @Res() response: Response,
  ): Promise<void> {
    if (!isProviderName(provider)) {
      throw new NotFoundException({ code: 'UNKNOWN_PROVIDER', message: 'No such provider' });
    }
    if (!code || !state) {
      throw new BadRequestException({
        code: 'OAUTH_CALLBACK_INVALID',
        message: 'The provider returned an incomplete response',
      });
    }
    response.redirect(await this.oauth.completeCallback(provider, code, state));
  }

  /** The client trades its one-time code for real tokens. */
  @Post('exchange')
  @HttpCode(200)
  @UseGuards(OAuthRateLimit)
  exchange(@Body() dto: OAuthExchangeDto): Promise<AuthResponse> {
    return this.oauth.exchange(dto.code, dto.verifier);
  }
}

/**
 * OAuth sign-in.
 *
 * The whole authorization-code exchange happens here, never in a client: the
 * client secret configured in the admin panel must not leave the server. A
 * desktop or web client opens `/start` in a real browser, the provider comes
 * back to `/callback`, and the client collects the session with a one-time code
 * over `/exchange`. That is the same shape whether the client is Electron
 * (loopback redirect) or a browser (back to the admin panel origin).
 *
 * Two short-lived Redis keys carry it: the request state (where to send the
 * browser afterwards) and the one-time code (which session to hand over).
 */
import { BadRequestException, Injectable, UnauthorizedException } from '@nestjs/common';
import { createHash, randomUUID, timingSafeEqual } from 'node:crypto';
import Redis from 'ioredis';
import { envOr } from '@betweenus/config';
import { prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { APP_REDIRECT_SCHEME, type AuthResponse, type OAuthProviderSummary } from '@betweenus/shared-types';
import { AuthService, toPublicUser } from '../auth/auth.service';
import {
  PROVIDERS,
  type ProviderName,
  type ProviderProfile,
  callbackUrl,
  credentialsFor,
} from '../admin/oauth-providers';

/** A browser round trip through a provider; generous, but not open-ended. */
const STATE_TTL_SECONDS = 600;
/** The client is already waiting when this is minted. */
const CODE_TTL_SECONDS = 120;

@Injectable()
export class OAuthService {
  private readonly redis = new Redis(envOr('REDIS_URL', 'redis://localhost:6379'), {
    maxRetriesPerRequest: 2,
  });

  constructor(
    private readonly auth: AuthService,
    private readonly events: EventBus,
  ) {}

  /** What the login screen should offer. Public - it names no credentials. */
  async enabledProviders(): Promise<OAuthProviderSummary[]> {
    const rows = await prisma.oAuthProvider.findMany({ where: { enabled: true } });
    return rows
      .filter((row): row is typeof row & { provider: ProviderName } => row.provider in PROVIDERS)
      .filter((row) => row.clientId && row.clientSecret)
      .map((row) => ({ provider: row.provider, label: PROVIDERS[row.provider].label }));
  }

  /**
   * URL to send the browser to, with the return address remembered server-side.
   *
   * [challenge] is the SHA-256 of a secret the client keeps, and it is what
   * makes a private-scheme redirect safe to answer: see [assertAllowedRedirect].
   * Absent for the desktop's loopback redirect, which nothing else on the
   * machine can bind to.
   */
  async authorizeUrl(
    provider: ProviderName,
    redirectUri: string,
    challenge?: string,
  ): Promise<string> {
    const credentials = await credentialsFor(provider);
    if (!credentials) {
      throw new BadRequestException({
        code: 'PROVIDER_DISABLED',
        message: 'That sign-in method is not enabled',
      });
    }

    assertAllowedRedirect(redirectUri, challenge);

    const state = randomUUID();
    await this.redis.set(
      stateKey(state),
      JSON.stringify({ provider, redirectUri, challenge }),
      'EX',
      STATE_TTL_SECONDS,
    );

    const definition = PROVIDERS[provider];
    const url = new URL(definition.authorizeUrl);
    url.searchParams.set('client_id', credentials.clientId);
    url.searchParams.set('redirect_uri', callbackUrl(provider));
    url.searchParams.set('response_type', 'code');
    url.searchParams.set('scope', definition.scope);
    url.searchParams.set('state', state);
    return url.toString();
  }

  /**
   * Provider callback: trades the code for a profile, finds or creates the
   * account, and returns where to send the browser next.
   */
  async completeCallback(provider: ProviderName, code: string, state: string): Promise<string> {
    const raw = await this.redis.get(stateKey(state));
    // Consumed on use: a replayed callback must not produce a second session.
    await this.redis.del(stateKey(state));
    if (!raw) {
      throw new UnauthorizedException({
        code: 'OAUTH_STATE_INVALID',
        message: 'This sign-in attempt expired; start again',
      });
    }

    const request = JSON.parse(raw) as {
      provider: ProviderName;
      redirectUri: string;
      challenge?: string;
    };
    if (request.provider !== provider) {
      throw new UnauthorizedException({
        code: 'OAUTH_STATE_INVALID',
        message: 'This sign-in attempt does not match',
      });
    }

    const profile = await this.fetchProfile(provider, code);
    const session = await this.signIn(provider, profile);

    const oneTimeCode = randomUUID();
    // The challenge rides with the session, so the code is only spendable by
    // whoever started the sign-in - not by whoever the redirect reached.
    await this.redis.set(
      codeKey(oneTimeCode),
      JSON.stringify({ session, challenge: request.challenge }),
      'EX',
      CODE_TTL_SECONDS,
    );

    const destination = new URL(request.redirectUri);
    destination.searchParams.set('code', oneTimeCode);
    return destination.toString();
  }

  /**
   * The client trades the one-time code for the session. Single use.
   *
   * When the sign-in was started with a challenge, the verifier behind it has
   * to come back too. An app that intercepted the redirect holds the code and
   * not the secret, and the code alone is worth nothing.
   */
  async exchange(code: string, verifier?: string): Promise<AuthResponse> {
    const raw = await this.redis.get(codeKey(code));
    // Consumed whatever happens next: a code that has been offered once, right
    // or wrong, must not be offered again.
    await this.redis.del(codeKey(code));
    if (!raw) {
      throw new UnauthorizedException({
        code: 'OAUTH_CODE_INVALID',
        message: 'This sign-in code is invalid or already used',
      });
    }

    const stored = JSON.parse(raw) as { session: AuthResponse; challenge?: string };
    if (stored.challenge && !matchesChallenge(verifier, stored.challenge)) {
      throw new UnauthorizedException({
        code: 'OAUTH_VERIFIER_INVALID',
        message: 'This sign-in was started somewhere else',
      });
    }
    return stored.session;
  }

  private async fetchProfile(provider: ProviderName, code: string): Promise<ProviderProfile> {
    const credentials = await credentialsFor(provider);
    if (!credentials) {
      throw new BadRequestException({
        code: 'PROVIDER_DISABLED',
        message: 'That sign-in method is not enabled',
      });
    }

    const definition = PROVIDERS[provider];
    const response = await fetch(definition.tokenUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
      body: new URLSearchParams({
        client_id: credentials.clientId,
        client_secret: credentials.clientSecret,
        code,
        grant_type: 'authorization_code',
        redirect_uri: callbackUrl(provider),
      }),
    });

    const body = (await response.json().catch(() => null)) as { access_token?: string } | null;
    if (!response.ok || !body?.access_token) {
      throw new UnauthorizedException({
        code: 'OAUTH_EXCHANGE_FAILED',
        message: 'The provider rejected this sign-in',
      });
    }

    return definition.profile(body.access_token);
  }

  /**
   * Links to an existing account by provider id, then by verified email, and
   * only creates a new account when neither matches.
   */
  private async signIn(provider: ProviderName, profile: ProviderProfile): Promise<AuthResponse> {
    const identity = await prisma.userIdentity.findUnique({
      where: { provider_providerAccountId: { provider, providerAccountId: profile.id } },
      include: { user: true },
    });

    let user = identity?.user ?? null;

    // Only a verified address may find an account. An unverified one is a
    // string the person signing in chose, so linking on it would mean anybody
    // who can type a victim's email into a fresh Google account walks into the
    // BetweenUs account behind it, password and all.
    if (!user && profile.email && profile.emailVerified) {
      // Same person, first time through this provider: link rather than
      // creating a duplicate account for an address that already exists.
      const byEmail = await prisma.user.findUnique({ where: { email: profile.email.toLowerCase() } });
      if (byEmail) {
        user = byEmail;
        await prisma.userIdentity.create({
          data: {
            userId: byEmail.id,
            provider,
            providerAccountId: profile.id,
            email: profile.email,
          },
        });
      }
    }

    if (!user) {
      // An unverified address does not become this account's address either:
      // it would sit there waiting for the person who really owns it to sign
      // in and be linked to it by the branch above.
      const verified = profile.emailVerified ? profile.email?.toLowerCase() : undefined;
      const email = verified ?? `${provider}-${profile.id}@users.noreply.betweenus`;
      user = await prisma.user.create({
        data: {
          email,
          username: await this.availableUsername(profile.username),
          displayName: profile.displayName,
          avatarUrl: profile.avatarUrl,
          // No password: this account signs in through the provider only. The
          // hash is a value no password can produce, not an empty string.
          passwordHash: 'oauth-only',
          identities: {
            create: { provider, providerAccountId: profile.id, email: profile.email },
          },
        },
      });

      await this.events.publish(EVENTS.USER_CREATED, {
        userId: user.id,
        username: user.username,
        email: user.email,
      });
    }

    if (user.disabledAt !== null) {
      throw new UnauthorizedException({
        code: 'ACCOUNT_DISABLED',
        message: 'This account has been disabled',
      });
    }

    const tokens = await this.auth.issueTokensFor(user);
    return { ...tokens, user: toPublicUser(user) };
  }

  /** `ayaan`, then `ayaan2`, `ayaan3` - usernames are unique platform-wide. */
  private async availableUsername(preferred: string): Promise<string> {
    const base = preferred.toLowerCase().replace(/[^a-z0-9_.-]/g, '').slice(0, 24) || 'user';
    for (let suffix = 0; suffix < 100; suffix += 1) {
      const candidate = suffix === 0 ? base : `${base}${suffix + 1}`;
      const taken = await prisma.user.findUnique({ where: { username: candidate } });
      if (!taken) return candidate;
    }
    return `${base}-${randomUUID().slice(0, 8)}`;
  }
}

const stateKey = (state: string): string => `oauth:state:${state}`;
const codeKey = (code: string): string => `oauth:code:${code}`;

/**
 * The origins a finished sign-in may be sent back to.
 *
 * Derived rather than configured. There used to be an `OAUTH_ALLOWED_REDIRECTS`
 * variable and it was the wrong shape of question to ask an operator: every
 * deployment's answer is "my own site", they are already telling us what that
 * is twice over, and getting it wrong produces a `BAD_REDIRECT` on the one
 * button nobody can test until the site is public. So the answer is read from
 * what the deployment has already had to set:
 *
 * - `PUBLIC_API_URL` - where a browser reaches this API. The web client and
 *   the admin panel are served from the same origin behind the same gateway,
 *   and the provider's own callback is a path on it, so a deployment that
 *   cannot trust this origin has nothing left to trust.
 * - `CORS_ORIGIN` - the sites this API already answers credentialed requests
 *   for. A wildcard is skipped: "any site may call the API" is not "any site
 *   may be handed a session code", and treating it as one would be the open
 *   redirect this whole function exists to prevent.
 *
 * Loopback is added by [isAllowedRedirect] itself, for the desktop client's
 * temporary server.
 */
export function trustedRedirectOrigins(): string {
  return [envOr('PUBLIC_API_URL', ''), envOr('CORS_ORIGIN', '')]
    .flatMap((value) => value.split(','))
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0 && entry !== '*')
    .join(',');
}

/**
 * Where a completed sign-in may be sent back to.
 *
 * An open redirect here hands a session to whoever asked for it - the one-time
 * code travels in the query string of exactly this URL - so the list is exact:
 * loopback (the desktop client's temporary server) and the deployment's own
 * origins.
 *
 * It used to be `redirectUri.startsWith(origin)`, and a prefix is not an
 * origin: an allow list naming `https://betweenus.example` also matched
 * `https://betweenus.example.attacker.test/`, which is a different site that would
 * have been handed the code. Origins are parsed and compared as origins now,
 * with a path prefix allowed only once the origin already matches.
 */
export function isAllowedRedirect(redirectUri: string, allowList: string): boolean {
  let url: URL;
  try {
    url = new URL(redirectUri);
  } catch {
    return false;
  }

  if (url.protocol === 'http:' && (url.hostname === '127.0.0.1' || url.hostname === 'localhost')) {
    return true;
  }

  for (const entry of allowList.split(',').map((value) => value.trim()).filter(Boolean)) {
    let allowed: URL;
    try {
      allowed = new URL(entry);
    } catch {
      // An entry that is not a URL cannot be compared as one, and comparing it
      // as a string is what this function exists to stop doing.
      continue;
    }
    if (url.origin !== allowed.origin) continue;
    // Within the origin a prefix is fine and is how a deployment names one
    // path of its own site; across origins it never was.
    if (allowed.pathname === '/' || url.pathname.startsWith(allowed.pathname)) return true;
  }

  return false;
}

/**
 * The base64url SHA-256 of [verifier], the way RFC 7636 computes an S256
 * challenge - so a client can use any PKCE library it already has.
 */
export function challengeFor(verifier: string): string {
  return createHash('sha256').update(verifier).digest('base64url');
}

/** Constant-time, because this is a secret being compared. */
export function matchesChallenge(verifier: string | undefined, challenge: string): boolean {
  if (!verifier) return false;
  const expected = Buffer.from(challenge);
  const actual = Buffer.from(challengeFor(verifier));
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}

/**
 * The redirect a mobile client comes back on.
 *
 * A phone has no loopback server, so the sign-in returns through a URL only the
 * app is registered for. Android will not promise that registration is
 * exclusive - a second app can claim `betweenus://` - so a private scheme is
 * accepted only for a flow that also carries a challenge. The code that arrives
 * at a hijacked redirect is then worth nothing without the secret behind it,
 * which never leaves the app that started the sign-in.
 *
 * A challenge is a base64url digest and nothing else: length and alphabet are
 * checked here so that an empty string, or something meant to be read as a
 * path, cannot pass for one.
 */
const CHALLENGE_PATTERN = /^[A-Za-z0-9_-]{43}$/;

export function isAppRedirect(redirectUri: string): boolean {
  try {
    return new URL(redirectUri).protocol === APP_REDIRECT_SCHEME;
  } catch {
    return false;
  }
}

function assertAllowedRedirect(redirectUri: string, challenge?: string): void {
  if (isAppRedirect(redirectUri)) {
    if (challenge && CHALLENGE_PATTERN.test(challenge)) return;
    throw new BadRequestException({
      code: 'CHALLENGE_REQUIRED',
      message: 'That redirect requires a sign-in challenge',
    });
  }

  if (isAllowedRedirect(redirectUri, trustedRedirectOrigins())) return;

  throw new BadRequestException({
    code: 'BAD_REDIRECT',
    message: 'That redirect target is not allowed',
  });
}

