import { Module } from '@nestjs/common';
import { envOr } from '@betweenus/config';
import { pingDatabase } from '@betweenus/database';
import { EventBus } from '@betweenus/events';
import { Logger, createLogger } from '@betweenus/logger';
import { createHealthController } from '@betweenus/nest-common';
import { CallGateway } from './call.gateway';
import { CallsController } from './modules/calls/calls.controller';
import { CallsService } from './modules/calls/calls.service';
import { RelayController } from './modules/calls/relay.controller';
import { RelayHealthService } from './modules/calls/relay-health.service';

const SERVICE_NAME = 'call-service';

@Module({
  controllers: [
    CallsController,
    RelayController,
    createHealthController(SERVICE_NAME, pingDatabase),
  ],
  providers: [
    CallsService,
    CallGateway,
    RelayHealthService,
    {
      // The roster this service holds is the only true one, so it publishes it
      // for presence-service to draw dots from.
      provide: EventBus,
      useFactory: (): EventBus =>
        new EventBus(envOr('REDIS_URL', 'redis://localhost:6379'), SERVICE_NAME),
    },
    {
      provide: Logger,
      useFactory: (): Logger => createLogger(SERVICE_NAME, envOr('LOG_LEVEL', 'info') as never),
    },
  ],
})
export class AppModule {}

/**
 * `/ws/call`: the switchboard two clients use to find each other.
 *
 * This gateway introduces peers and then gets out of the way. It knows who is
 * in which channel's call, it forwards an offer, an answer or an ICE candidate
 * from one peer to another, and that is the whole of it. It never sees a frame
 * of media, cannot decode one, and is not in the path where one travels - the
 * peer connections it helps set up run directly between the two machines.
 *
 * That is also why this works through a Cloudflare Tunnel when an SFU did not.
 * Everything crossing this gateway is small, text and reliable, which is what a
 * tunnel carries; the large, continuous, loss-tolerant half never goes near it.
 *
 * Two things it deliberately does not do:
 *
 * - It does not read a signal. `data` is forwarded verbatim, so the SDP a peer
 *   receives is the SDP the other peer wrote. Anything else would put this
 *   service in a position to rewrite a DTLS fingerprint, which is exactly what
 *   the fingerprint signature exists to make useless.
 * - It does not trust `from`. The sender's peer id comes from the socket the
 *   message arrived on, never from the message, so a client cannot sign its
 *   traffic as somebody else.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { resolveChannelAccess } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import { PERMISSIONS } from '@betweenus/permissions';
import {
  SIGNAL_MAX_PAYLOAD,
  authenticateHandshake,
  dropRevokedSockets,
} from '@betweenus/websocket';
import type {
  CallPeer,
  ClientCallEvent,
  GameSession,
  ListenSession,
  ServerCallEvent,
} from '@betweenus/shared-types';
import { apply as applyGame, type GameAction } from './game-session';
import { apply as applyListen, type ListenAction } from './listen-session';
import { otherDevicesInCall } from './devices';
import { deviceOf, peerIdFor } from './peer-identity';
import { CallsService, type ReportedUsage } from './modules/calls/calls.service';

const HEARTBEAT_INTERVAL_MS = 30_000;

/**
 * How long a peer's seat is held after its socket closes, before the others are
 * told it has gone.
 *
 * A phone loses its signalling socket constantly - a lift, a train, a screen
 * that went off, a doze the system decided on - and it comes back within a
 * second or two. Announcing `peer.left` the instant the socket drops made every
 * one of those a full mesh teardown: everybody closed their peer connection to
 * it, it rejoined, and everybody built a new one and renegotiated from nothing.
 * That is the call that connects, drops and connects again in a loop, and none
 * of it was ever about the media path.
 *
 * Inside this window a peer that comes back with the same id is not announced
 * as leaving or as arriving. Nobody's connection is touched, and ICE - which
 * has its own restart and its own deadline in every client - is left to do the
 * one job that is actually its own: find the media a path again.
 *
 * Shorter than the heartbeat, so a seat cannot outlive the roster that would
 * have corrected it, and much shorter than any client's signalling deadline.
 */
const REJOIN_GRACE_MS = 15_000;

/**
 * The ceiling the mesh imposes, enforced where it can be said clearly rather
 * than discovered as a call that degrades for everyone at once. Each
 * participant uploads one copy of its media per other participant, so the cost
 * of the tenth joiner is paid by the nine already talking.
 *
 * ponytail: a flat number for every channel. Per-channel limits are the fix if
 * a deployment ever wants voice-only rooms to go higher than video ones.
 */
const MAX_PEERS_PER_CALL = 8;

/**
 * How many numbers a move may carry beyond its index. A carrom shot needs
 * three; nothing needs more, and an array a client chose the length of is an
 * array a client chose the length of.
 */
const MAX_MOVE_PARAMS = 4;

/**
 * The numbers that complete a move, trimmed to something the rules can be
 * handed safely.
 *
 * This is the one field a client fills in with real numbers rather than an
 * index, and it goes straight into a physics simulation - so a NaN, an infinity
 * or an array of ten thousand entries would each be a shot that never comes to
 * rest, in a loop this process is running. Anything unusable becomes
 * `undefined`, which every rules module reads as "no aim given" and refuses.
 */
function sanitiseParams(params: unknown): number[] | undefined {
  if (!Array.isArray(params)) return undefined;
  if (params.length === 0 || params.length > MAX_MOVE_PARAMS) return undefined;
  const numbers = params.filter(
    (value): value is number => typeof value === 'number' && Number.isFinite(value),
  );
  if (numbers.length !== params.length) return undefined;
  return numbers;
}

interface SocketState extends CallPeer {
  channelId: string | null;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
  /** The open row in this person's call log, while they are in a call. */
  sessionId: string | null;
  /** Everybody else who has been in the call since this socket joined it. */
  metUserIds: Set<string>;
  /** What the client says it moved, reported on the way out. See `leave`. */
  usage: ReportedUsage;
}

@Injectable()
export class CallGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly state = new WeakMap<WebSocket, SocketState>();
  /**
   * channelId -> the sockets in that call.
   *
   * ponytail: in process, so this holds for a single call-service replica -
   * which is what the compose deployment runs. Two replicas would each see half
   * a call and peers would never be introduced across them. The upgrade path is
   * the one presence-service already uses: Redis Pub/Sub, with the roster in
   * Redis and signals published to a channel keyed by peer id.
   */
  private readonly calls = new Map<string, Set<WebSocket>>();

  /**
   * channelId -> the socket currently sharing its screen, if any.
   *
   * One share per call. Two of them is a stage with two pictures on it and no
   * way to say which one anybody means; every product that has tried it ended
   * up here. Held beside the roster rather than derived from the peer data
   * channels, because arbitration needs one answer and the mesh has no ordering
   * to produce one - the last claim wins, and "last" is only a thing the
   * gateway can decide.
   */
  private readonly sharing = new Map<string, WebSocket>();

  /**
   * channelId -> the Listen Together session in that call, if there is one.
   *
   * Beside the roster for the same reason `sharing` is: two people pressing
   * pause at the same moment need one answer, and a mesh has no ordering to
   * produce one. This gateway holds the sockets, so it is the only thing that
   * can say which press happened second.
   *
   * The music itself is nowhere near here. Each client plays the track from the
   * provider over its own connection; what crosses this gateway is a queue and
   * a position - signalling, exactly like an SDP, and for exactly the same
   * reason it works through a tunnel. Sharing a browser tab with the sound on
   * would have made it media, one upload per listener, re-encoded through a
   * codec meant for speech.
   */
  private readonly listening = new Map<string, ListenSession>();

  /**
   * channelId -> the game being played in that call, if there is one.
   *
   * Here for the third time and for the same reason as `sharing` and
   * `listening`: two people clicking the same square at the same moment need
   * one answer, and a mesh has no ordering to produce one. This gateway holds
   * the sockets, so it is the only thing that can say which click was second -
   * and it is also the referee, because a board a client could set is a board a
   * client could set to won.
   *
   * Nothing here is persisted. The game lives beside the roster and dies with
   * the call, which is what it is: three rounds of Connect Four while two
   * people waited for a build has no meaning tomorrow.
   */
  private readonly playing = new Map<string, GameSession>();

  /**
   * `channelId\u0000peerId` -> the "they have gone" nobody has been told yet.
   *
   * A closed socket takes its seat off the roster straight away - a ghost in
   * the peer list is somebody a new joiner tries to call and never reaches -
   * but the *announcement* waits out [REJOIN_GRACE_MS]. A peer that comes back
   * with the same id cancels it, and the rest of the call never learns anything
   * happened.
   */
  private readonly departing = new Map<string, NodeJS.Timeout>();

  constructor(
    private readonly logger: Logger,
    private readonly events: EventBus,
    /** Where a call's log entry is opened and closed - `this.calls` is the roster. */
    private readonly history: CallsService,
  ) {}

  /**
   * Says who is in a call, for anybody drawing it.
   *
   * The roster used to be whatever each client told presence-service it was
   * doing, which meant a client could put itself in a channel it had never
   * signalled into, and a client that crashed stayed in one until its presence
   * socket noticed. This gateway is the only thing that knows the truth - it
   * holds the sockets - so it is the thing that says it, on every change,
   * including the changes nobody announced.
   */
  private announceRoster(channelId: string): void {
    const userIds = [
      ...new Set(
        [...(this.calls.get(channelId) ?? [])].flatMap((member) => {
          const peer = this.state.get(member);
          return peer ? [peer.userId] : [];
        }),
      ),
    ];

    // One account with two windows is one person in the room, which is why this
    // is a set: the peer list is per socket and the roster is per person.
    void this.events
      .publish(EVENTS.CALL_ROSTER, { voice: { channelId, userIds } })
      .catch((error) => {
        this.logger.warn('Could not publish a call roster', {
          channelId,
          reason: String(error),
        });
      });
  }

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room: the four gateways keep different
   * bookkeeping and `clients` is the one thing all of them have. A revocation is
   * rare, and a scan of one instance's sockets is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  attach(httpServer: HttpServer): void {
    // The socket this matters most for, and the reason the fix is a revocation
    // event and not a shorter socket lifetime: closing a call socket ends a
    // call, so it must happen when somebody says so and never on a timer.
    // `close` runs the same teardown a dropped connection does - the roster is
    // re-announced and the call log row is closed - so the other people in the
    // call see them leave rather than freeze.
    void dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) => this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/call',
      maxPayload: SIGNAL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        socket.close(4401, 'Unauthorized');
        return;
      }

      // A peer id per device, not per socket and not per user. Two windows on
      // one account are still two peers - that is what stops the second one
      // disconnecting the first - but a reconnect from the same window is the
      // same peer, which is what stops a tunnel from rebuilding the mesh. See
      // `peerIdFor`.
      const state: SocketState = {
        peerId: peerIdFor(user.id, deviceOf(request.url)),
        userId: user.id,
        username: user.username,
        channelId: null,
        alive: true,
        issuedAt: user.issuedAt,
        sessionId: null,
        metUserIds: new Set<string>(),
        usage: noUsage(),
      };
      this.state.set(socket, state);
      this.send(socket, { type: 'ready', peerId: state.peerId });

      socket.on('pong', () => {
        const current = this.state.get(socket);
        if (current) current.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handle(socket, raw.toString());
      });

      // A socket that simply closed is a network, not a decision - and on a
      // phone it is a network that comes back in a second. The seat is held.
      socket.on('close', () => this.depart(socket, { hold: true }));

      socket.on('error', (error) => {
        this.logger.warn('Call socket error', { userId: user.id, reason: String(error) });
      });
    });

    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          // Terminating fires 'close', which is what takes them off the roster
          // and tells the others to tear their peer connection down.
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
      }

      // Said again, unchanged, on every beat.
      //
      // A roster is a replacement for one channel, so a channel that stops
      // being mentioned keeps whatever was last said about it - and if this
      // process restarted mid-call, what was last said about it was true of a
      // process that no longer exists. That is the ghost in a voice channel's
      // member list: somebody who left hours ago, listed forever, because the
      // only thing that could correct it never spoke about that channel again.
      //
      // Re-announcing turns the roster into something with a heartbeat, which
      // is what presence-service ages out. Nobody in this call means nothing is
      // published for it, which is exactly what "empty" has to look like.
      for (const channelId of this.calls.keys()) this.announceRoster(channelId);
    }, HEARTBEAT_INTERVAL_MS);

    this.logger.info('Call signalling gateway ready', { path: '/ws/call' });
  }

  private async handle(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientCallEvent;
    try {
      event = JSON.parse(raw) as ClientCallEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'join':
        await this.join(socket, state, event.channelId);
        return;

      case 'leave':
        // The only number in the log the server cannot take for itself: media
        // is peer to peer, so the client's own counters are the only counters.
        // It is clamped where it is written - see `usage.ts`.
        state.usage = {
          bytes: typeof event.bytes === 'number' ? event.bytes : 0,
          bytesSent: typeof event.bytesSent === 'number' ? event.bytesSent : 0,
          bytesReceived: typeof event.bytesReceived === 'number' ? event.bytesReceived : 0,
          links: event.links,
        };
        // Somebody pressed the button. No grace: they are not coming back, and
        // holding their seat is fifteen seconds of a frozen tile for everybody.
        this.depart(socket);
        return;

      case 'signal':
        this.relay(state, event.to, event.data);
        return;

      case 'screen.claim':
        this.claimScreen(socket, state);
        return;

      case 'screen.release':
        this.releaseScreen(socket, state);
        return;

      case 'ping':
        // The gateway's clock rides along, because a shared position is
        // meaningless without one: two machines disagree about what time it is
        // by whatever their clocks last drifted to, and this is the reference
        // every client measures its own offset against.
        this.send(socket, { type: 'pong', serverMs: Date.now() });
        return;

      case 'listen.add':
        this.listen(state, {
          kind: 'add',
          playNow: event.playNow === true,
          track: {
            // Minted here, not by the client: it is the identity two clients
            // agree a queue entry has, and a client that chose its own could
            // collide with one already in the queue - which is a `remove` that
            // takes away somebody else's track.
            id: randomUUID(),
            provider: event.provider,
            ref: event.ref,
            title: typeof event.title === 'string' ? event.title : '',
            durationMs: 0,
            addedByUserId: state.userId,
            addedByUsername: state.username,
          },
        });
        return;

      case 'listen.remove':
        this.listen(state, { kind: 'remove', trackId: event.trackId });
        return;

      case 'listen.play':
        this.listen(state, { kind: 'play', index: event.index });
        return;

      case 'listen.pause':
        this.listen(state, { kind: 'pause', positionMs: event.positionMs });
        return;

      case 'listen.seek':
        this.listen(state, { kind: 'seek', positionMs: event.positionMs });
        return;

      case 'listen.skip':
        this.listen(state, { kind: 'skip', delta: event.delta });
        return;

      case 'listen.stop':
        this.listen(state, { kind: 'stop' });
        return;

      case 'listen.ended':
        this.listen(state, { kind: 'ended', trackId: event.trackId });
        return;

      case 'listen.meta':
        this.listen(state, {
          kind: 'meta',
          trackId: event.trackId,
          title: event.title,
          durationMs: event.durationMs,
        });
        return;

      case 'game.open':
        this.game(state, { kind: 'open', gameId: event.gameId });
        return;

      case 'game.sit':
        this.game(state, { kind: 'sit', seat: event.seat });
        return;

      case 'game.move':
        this.game(state, {
          kind: 'move',
          move: event.move,
          // Bounded and cleaned here rather than trusted: this is the one field
          // a client fills in with real numbers, and it goes straight into a
          // physics simulation. A NaN, an array of ten thousand, or an infinity
          // would each be a shot that never comes to rest.
          params: sanitiseParams(event.params),
        });
        return;

      case 'game.rematch':
        this.game(state, { kind: 'rematch' });
        return;

      case 'game.close':
        this.game(state, { kind: 'close' });
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  private holdKey(channelId: string, peerId: string): string {
    return `${channelId}\u0000${peerId}`;
  }

  /**
   * Whether this join is the same peer coming back inside its grace window.
   *
   * True means the others still hold a live peer connection to it and must not
   * be told about any of this: no `peer.left` (cancelled here) and no
   * `peer.joined` (suppressed by the caller).
   */
  private resumeHeldSeat(channelId: string, peerId: string): boolean {
    const key = this.holdKey(channelId, peerId);
    const timer = this.departing.get(key);
    if (!timer) return false;
    clearTimeout(timer);
    this.departing.delete(key);
    return true;
  }

  private async join(socket: WebSocket, state: SocketState, channelId: string): Promise<void> {
    const access = await resolveChannelAccess(state.userId, channelId);
    if (!access) {
      // 404-shaped, for the same reason the REST path is: a non-member must not
      // learn the channel exists.
      this.send(socket, { type: 'error', code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
      return;
    }
    if (!access.permissions.includes(PERMISSIONS.START_CALL)) {
      this.send(socket, {
        type: 'error',
        code: 'MISSING_PERMISSION',
        message: `Missing permission ${PERMISSIONS.START_CALL}`,
      });
      return;
    }

    // One call per socket. Leaving the old one first keeps a roster honest when
    // a client switches channels without saying goodbye to the first.
    if (state.channelId && state.channelId !== channelId) this.depart(socket, { keepOpen: true });

    // One call per *account*, across every device it is signed in on. A peer id
    // is still per socket - two windows are still two ends of two connections -
    // but only one of them may be in a call at a time, so joining on the laptop
    // takes the call off the desktop rather than putting the same person in the
    // room twice, talking over themselves through two microphones.
    //
    // The old device is told why before it is dropped: `superseded` is what
    // lets it say "this call moved" instead of "the connection was lost". Its
    // socket stays open, so it can join again - which is what moving the call
    // back looks like from the other end.
    const otherDevices = otherDevicesInCall(
      this.calls.values(),
      (member) => this.state.get(member)?.userId,
      state.userId,
      socket,
    );
    for (const other of otherDevices) {
      // The same peer id is this device reconnecting, not another one: an old
      // socket the far end has not finished closing while its replacement is
      // already joining. It is not superseded, it is replaced - so it goes
      // quietly, holding its seat for the join happening two lines below. Told
      // otherwise, a phone with a slow-closing socket would announce its own
      // departure and arrival on every reconnect, which is the rebuild this
      // whole change exists to stop.
      const replaced = this.state.get(other)?.peerId === state.peerId;
      if (replaced) {
        this.depart(other, { keepOpen: true, hold: true });
        continue;
      }
      this.send(other, { type: 'superseded', channelId });
      this.depart(other, { keepOpen: true });
      this.logger.info('Call moved to another device', { userId: state.userId, channelId });
    }

    const members = this.calls.get(channelId) ?? new Set<WebSocket>();
    if (!members.has(socket) && members.size >= MAX_PEERS_PER_CALL) {
      this.send(socket, {
        type: 'error',
        code: 'CALL_FULL',
        message:
          `This call already has ${MAX_PEERS_PER_CALL} people in it. Media goes directly between ` +
          'participants, so every extra person costs everyone already talking another upload.',
      });
      return;
    }

    // The roster is taken before this socket is added, so a joiner is not told
    // about itself and does not try to connect to its own peer id.
    const peers: CallPeer[] = [...members].flatMap((member) => {
      const peer = this.state.get(member);
      return peer ? [{ peerId: peer.peerId, userId: peer.userId, username: peer.username }] : [];
    });

    // Who they are in the call with, recorded both ways: this join meets
    // everybody already here, and everybody already here has now met them. A
    // log entry is "who was in it while I was", so somebody who leaves before
    // the end still belongs in it.
    for (const member of members) {
      const peer = this.state.get(member);
      if (!peer || peer.userId === state.userId) continue;
      state.metUserIds.add(peer.userId);
      peer.metUserIds.add(state.userId);
    }

    // Before the seat is taken back, because taking it back is what decides
    // whether anybody else is told about it.
    const resumed = this.resumeHeldSeat(channelId, state.peerId);

    members.add(socket);
    this.calls.set(channelId, members);
    state.channelId = channelId;

    this.send(socket, { type: 'joined', channelId, peers });
    // A peer coming back inside its grace window never left as far as anybody
    // else is concerned. Announcing it would be an arrival for a connection
    // every one of them already holds - and the tear-down and rebuild that
    // follows is the whole of a call that connects and drops in a loop.
    if (!resumed) {
      this.broadcast(
        channelId,
        {
          type: 'peer.joined',
          peer: { peerId: state.peerId, userId: state.userId, username: state.username },
        },
        socket,
      );
    }

    this.announceRoster(channelId);

    // Whatever is already playing, to the newcomer only. They get the position
    // and the instant it was true, so their player opens partway through the
    // track everybody else is partway through rather than at the beginning.
    const listening = this.listening.get(channelId);
    if (listening) this.send(socket, { type: 'listen.state', session: listening });

    // And whatever is on the table, to the newcomer only. They arrive at the
    // board as it stands rather than at an empty one, which is the difference
    // between joining a game and being told there is one.
    const playing = this.playing.get(channelId);
    if (playing) this.send(socket, { type: 'game.state', session: playing });

    // The log row is opened here because here is where the join is known to
    // have been allowed. If they left while this was being written - a socket
    // that closes mid-await - it is closed straight away rather than left open
    // forever, which is what an unattended `endedAt` of null means.
    state.sessionId = await this.history.startSession(state.userId, channelId);
    if (state.sessionId && state.channelId !== channelId) {
      void this.history.endSession(state.sessionId, [...state.metUserIds], state.usage);
      state.sessionId = null;
    }

    this.logger.info('Peer joined a call', {
      userId: state.userId,
      channelId,
      peers: members.size,
    });
  }

  /**
   * Hands the screen to whoever asked for it last.
   *
   * The previous holder is told the same thing everybody else is - who holds it
   * now - and stops on its own. It is not sent a private "stop": every client
   * needs the new holder anyway, and one message that says the whole truth
   * cannot be applied by half the room and missed by the rest.
   */
  private claimScreen(socket: WebSocket, state: SocketState): void {
    const channelId = state.channelId;
    if (!channelId) return;
    if (this.sharing.get(channelId) === socket) return;

    this.sharing.set(channelId, socket);
    this.announceScreen(channelId);
    this.logger.info('Screen share taken over', { userId: state.userId, channelId });
  }

  /** Gives it up, if this socket is the one holding it. */
  private releaseScreen(socket: WebSocket, state: SocketState): void {
    const channelId = state.channelId;
    if (!channelId) return;
    // Only the holder may release: a late "I stopped" from whoever was replaced
    // would otherwise take the screen away from the person who just took it.
    if (this.sharing.get(channelId) !== socket) return;

    this.sharing.delete(channelId);
    this.announceScreen(channelId);
  }

  /**
   * Runs one Listen Together action and tells the call what came of it.
   *
   * Membership is the only permission asked for, and deliberately: everybody in
   * the call can change what is playing. A host is a person who eventually
   * leaves and takes the music with them, and the point of listening together
   * is that two people are doing it, not that one is performing it.
   *
   * The whole session is broadcast rather than a delta. It is a few hundred
   * bytes, it changes when somebody presses a button rather than continuously,
   * and a client that missed one message would otherwise hold a queue nobody
   * else has - which is the failure that cannot be noticed from inside.
   */
  private listen(state: SocketState, action: ListenAction): void {
    const channelId = state.channelId;
    if (!channelId) return;

    const before = this.listening.get(channelId) ?? null;
    const after = applyListen(before, action, state.userId, Date.now());
    // Nothing happened: a `duration` for a track that already had one, or an
    // `ended` for a track that stopped being current before it arrived. Saying
    // so anyway would make every client re-seek for no reason.
    if (after === before) return;

    if (after) this.listening.set(channelId, after);
    else this.listening.delete(channelId);

    this.broadcast(channelId, { type: 'listen.state', session: after });
  }

  /**
   * Runs one Play Together action and tells the call what came of it.
   *
   * The gateway is the referee, and this is the only place a board is ever
   * made: a client sends "column four", never a board. The rules come from
   * `@betweenus/shared-types`, which is also where the clients read them, so
   * what everybody draws and what is agreed here cannot drift apart.
   *
   * Membership is the only permission asked for. Who may *move* is a question
   * about the seats rather than about the channel, and the reducer answers it.
   */
  private game(state: SocketState, action: GameAction): void {
    if (!state.channelId) return;
    this.runGame(state.channelId, { userId: state.userId, username: state.username }, action);
  }

  /**
   * The same thing, addressed by channel rather than by socket.
   *
   * `depart` needs this: it clears `state.channelId` before it does anything
   * else, so by the time a leaver's chair has to be freed the socket no longer
   * knows which call it was in.
   */
  private runGame(
    channelId: string,
    actor: { userId: string; username: string },
    action: GameAction,
  ): void {
    const before = this.playing.get(channelId) ?? null;
    const after = applyGame(before, action, actor);
    // Nothing happened: an illegal move, a chair that filled while the click
    // was in flight, a rematch from somebody watching. Broadcasting anyway
    // would make every client redraw a board it already has.
    if (after === before) return;

    if (after) this.playing.set(channelId, after);
    else this.playing.delete(channelId);

    this.broadcast(channelId, { type: 'game.state', session: after });
  }

  private announceScreen(channelId: string): void {
    const holder = this.sharing.get(channelId);
    const peer = holder ? this.state.get(holder) : undefined;
    this.broadcast(channelId, {
      type: 'screen.holder',
      peerId: peer?.peerId ?? null,
      userId: peer?.userId ?? null,
    });
  }

  /**
   * Forwards one signal to one peer in the same call.
   *
   * Same-call is the check that matters: without it, a peer id learned anywhere
   * would let a client offer a connection into a channel it cannot see.
   */
  private relay(from: SocketState, to: string, data: unknown): void {
    if (!from.channelId) return;

    for (const member of this.calls.get(from.channelId) ?? []) {
      const peer = this.state.get(member);
      if (peer?.peerId !== to) continue;
      this.send(member, {
        type: 'signal',
        from: from.peerId,
        data: data as never,
      });
      return;
    }
  }

  /**
   * Takes a socket off its call and tells the others.
   *
   * `keepOpen` is the channel-switch case: the socket lives on, so its state is
   * kept and only its membership is dropped.
   */
  private depart(socket: WebSocket, options: DepartOptions = {}): void {
    const { keepOpen = false, hold = false } = options;
    const state = this.state.get(socket);
    if (!state) return;

    const { channelId, sessionId } = state;
    state.channelId = null;

    // Closed before anything else can throw, and before the state is dropped:
    // this is the only moment the duration is knowable, and a row left open is
    // an entry that reads as a call that never ended.
    if (sessionId) {
      state.sessionId = null;
      void this.history.endSession(sessionId, [...state.metUserIds], state.usage);
    }
    // A socket that stays open to join elsewhere starts a fresh log entry, so
    // it starts with a fresh idea of who it has met and what it has moved.
    state.metUserIds = new Set<string>();
    state.usage = noUsage();

    if (!keepOpen) this.state.delete(socket);
    if (!channelId) return;

    const members = this.calls.get(channelId);
    if (!members) return;
    members.delete(socket);
    if (members.size === 0) {
      this.calls.delete(channelId);
      // Nobody is listening, so there is nothing to listen to. The queue was a
      // thing this call built and it goes when the call does - keeping it would
      // mean the next person to join a quiet channel is played whatever the
      // last people left half-finished.
      this.listening.delete(channelId);
      // Same for the board: nobody is at the table, so there is no game. A kept
      // one would be a half-finished Reversi position waiting for whoever walks
      // into a quiet channel next.
      this.playing.delete(channelId);
    }

    // Somebody who left is not still sharing. Without this the screen stays
    // claimed by a socket that has gone, and the next person to press the
    // button is the only one who ever finds out.
    if (this.sharing.get(channelId) === socket) {
      this.sharing.delete(channelId);
      this.announceScreen(channelId);
    }

    // Everyone still in the call has a peer connection to this peer that will
    // never produce another frame. Saying so is what closes it; waiting for ICE
    // to time out is thirty seconds of a frozen tile.
    //
    // Unless nobody has said they are leaving. A socket that simply closed is a
    // network, not a decision, and on a phone it is a network that comes back
    // in a second - so the seat is held and the announcement waits. See
    // REJOIN_GRACE_MS.
    //
    // The chair at the game table is held on exactly the same terms, and it
    // has to be: freeing it the instant a socket blinks would let somebody else
    // sit down mid-game while the player it belongs to is still reconnecting.
    const actor = { userId: state.userId, username: state.username };
    if (!hold) {
      this.announceDeparture(channelId, state.peerId);
      this.runGame(channelId, actor, { kind: 'vacate', userId: state.userId });
    } else {
      const key = this.holdKey(channelId, state.peerId);
      const held = state.peerId;
      clearTimeout(this.departing.get(key));
      this.departing.set(
        key,
        setTimeout(() => {
          this.departing.delete(key);
          this.announceDeparture(channelId, held);
          this.runGame(channelId, actor, { kind: 'vacate', userId: actor.userId });
        }, REJOIN_GRACE_MS),
      );
    }

    this.logger.info('Peer left a call', {
      userId: state.userId,
      channelId,
      peers: members.size,
      held: hold,
    });
  }

  /** They are not coming back: tell the call, and correct the roster. */
  private announceDeparture(channelId: string, peerId: string): void {
    this.broadcast(channelId, { type: 'peer.left', peerId });
    this.announceRoster(channelId);
  }

  private broadcast(channelId: string, event: ServerCallEvent, except?: WebSocket): void {
    for (const member of this.calls.get(channelId) ?? []) {
      if (member === except) continue;
      this.send(member, event);
    }
  }

  private send(socket: WebSocket, event: ServerCallEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    for (const timer of this.departing.values()) clearTimeout(timer);
    this.departing.clear();
    this.server?.close();
  }
}

/**
 * How a socket is being taken off a call.
 *
 * `keepOpen` says the socket lives on - a channel switch, or a device being
 * replaced - so its state is kept and only its membership dropped. `hold` says
 * nobody has announced anything: the seat is kept for [REJOIN_GRACE_MS] and the
 * rest of the call is told only if it is not claimed back.
 */
interface DepartOptions {
  keepOpen?: boolean;
  hold?: boolean;
}

/** A stay nobody reported on: a window closed mid-call, or an older client. */
function noUsage(): ReportedUsage {
  return { bytes: 0, bytesSent: 0, bytesReceived: 0, links: [] };
}

/**
 * Self-check for "one call per account, across devices".
 *
 * The rule fails silently in both directions, which is why it is pinned down:
 * a scan that finds nobody leaves two devices in the room talking over each
 * other, and one that finds too much - the joining socket itself, or another
 * person on the same channel - hangs up on somebody who never joined anything.
 *
 * Run with `pnpm --filter @betweenus/call-service check`.
 */
import assert from 'node:assert/strict';
import { otherDevicesInCall } from './devices';

/** Stand-ins for sockets: identity is all the function uses them for. */
const desktop = { name: 'desktop' };
const laptop = { name: 'laptop' };
const phone = { name: 'phone' };
const someoneElse = { name: 'someone else' };

const owner = new Map<object, string>([
  [desktop, 'ana'],
  [laptop, 'ana'],
  [phone, 'ana'],
  [someoneElse, 'ben'],
]);

const userIdOf = (socket: object): string | undefined => owner.get(socket);

function theJoiningDeviceIsNeverItsOwnVictim(): void {
  const calls = [new Set<object>([desktop, someoneElse])];
  assert.deepEqual(otherDevicesInCall(calls, userIdOf, 'ana', desktop), []);
}

function anotherDeviceOfTheSameAccountIsFound(): void {
  const calls = [new Set<object>([desktop, someoneElse])];
  assert.deepEqual(otherDevicesInCall(calls, userIdOf, 'ana', laptop), [desktop]);
}

function aCallInAnotherChannelCountsToo(): void {
  // The point of the rule: the second device is joining a *different* channel,
  // and the first one still has to be taken out of the one it is in.
  const calls = [new Set<object>([someoneElse]), new Set<object>([desktop])];
  assert.deepEqual(otherDevicesInCall(calls, userIdOf, 'ana', laptop), [desktop]);
}

function everyOtherDeviceGoes(): void {
  const calls = [new Set<object>([desktop]), new Set<object>([phone, someoneElse])];
  assert.deepEqual(otherDevicesInCall(calls, userIdOf, 'ana', laptop), [desktop, phone]);
}

function nobodyElseIsTouched(): void {
  const calls = [new Set<object>([someoneElse])];
  assert.deepEqual(
    otherDevicesInCall(calls, userIdOf, 'ana', laptop),
    [],
    'another person in the same call is not another device of this account',
  );
}

function main(): void {
  theJoiningDeviceIsNeverItsOwnVictim();
  anotherDeviceOfTheSameAccountIsFound();
  aCallInAnotherChannelCountsToo();
  everyOtherDeviceGoes();
  nobodyElseIsTouched();
  console.log('call-service device self-check passed');
}

main();

/**
 * One call per account, across every device it is signed in on.
 *
 * A peer id is per socket - two windows really are two ends of two different
 * peer connections - but a *person* may only be in one call at a time, so
 * joining on a second device has to take the call off the first rather than put
 * the same person in the room twice with two live microphones.
 *
 * Kept out of the gateway and generic over the socket type so it can be checked
 * without a WebSocket server, which is the only part of this rule that can go
 * quietly wrong: a scan that finds nobody looks exactly like a rule that is off.
 */

/**
 * Every connection of `userId` currently in a call, except `except`.
 *
 * Rosters are scanned rather than a second index kept per user: there is one
 * small set per live call in this process, and the caller is about to drop each
 * result from the set it was found in - which is why this returns an array
 * rather than iterating lazily over collections that are about to change.
 *
 * ponytail: in-process, like the rosters themselves. It stops being true the
 * moment there are two call-service replicas, and it is fixed by exactly the
 * move that fixes the roster - keeping both in Redis.
 */
export function otherDevicesInCall<S>(
  calls: Iterable<Set<S>>,
  userIdOf: (socket: S) => string | undefined,
  userId: string,
  except: S,
): S[] {
  const found: S[] = [];
  for (const members of calls) {
    for (const member of members) {
      if (member === except) continue;
      if (userIdOf(member) === userId) found.push(member);
    }
  }
  return found;
}

/**
 * Self-check for the two games that are not grids: Carrom and Ludo.
 *
 * Both have a failure mode the other four do not. Carrom's is a simulation that
 * does not agree with itself - if the same shot on the same board produced two
 * different results, the gateway's board and the animation every client just
 * watched would be two different games, and nobody could say which was real.
 * Ludo's is a die: a roll decided anywhere but the gateway is a player who
 * decides their own sixes, and a turn that does not pass when a number is
 * unplayable is a board that has simply stopped.
 *
 * Run with `pnpm --filter @betweenus/call-service check`.
 */
import assert from 'node:assert/strict';
import {
  BOARD,
  GAMES,
  HOME,
  PIECES,
  QUEEN,
  ROLL,
  STRIKER,
  TOKENS,
  YARD,
  carromPieces,
  carromShot,
  coinsOf,
  dieOf,
  lastRoll,
  placeStriker,
  progressOf,
  simulate,
  tokenIndex,
  tokenMoves,
  trackSquare,
  type GameState,
} from '@betweenus/shared-types';

// --- The physics agrees with itself ----------------------------------------

{
  const carrom = GAMES.carrom;
  const start = carrom.create();

  // The break, twice, from the same board with the same aim. Identical to the
  // last bit, because that is the whole basis for letting a client animate a
  // shot the gateway refereed: it replays the same function on the same
  // numbers, so the last frame it draws is the board that was already sent.
  const first = carromShot(start, 0, [0, -Math.PI / 2, 0.9]);
  const second = carromShot(start, 0, [0, -Math.PI / 2, 0.9]);
  for (let index = 0; index < PIECES; index += 1) {
    assert.equal(first.pieces[index]!.x, second.pieces[index]!.x);
    assert.equal(first.pieces[index]!.y, second.pieces[index]!.y);
    assert.equal(first.pieces[index]!.onBoard, second.pieces[index]!.onBoard);
  }
  assert.deepEqual(first.pocketed, second.pocketed);
  assert.equal(first.frames.length, second.frames.length);

  // A break hits something. A shot up the middle that misses nineteen coins in
  // a circle would mean the aim, the placement or the radii are wrong.
  assert.equal(first.contact, true);
  // And it comes to rest: every piece stopped, inside the board.
  for (const piece of first.pieces) {
    assert.equal(piece.vx, 0);
    assert.equal(piece.vy, 0);
    if (!piece.onBoard) continue;
    assert.ok(piece.x >= 0 && piece.x <= BOARD, 'a piece left the board');
    assert.ok(piece.y >= 0 && piece.y <= BOARD, 'a piece left the board');
  }
  // Nothing ends up inside anything else. Overlap that survives to a standstill
  // is the separation step being wrong, and it looks like two coins welded
  // together for the rest of the game.
  for (let a = 0; a < PIECES; a += 1) {
    const first_ = first.pieces[a]!;
    if (!first_.onBoard) continue;
    for (let b = a + 1; b < PIECES; b += 1) {
      const other = first.pieces[b]!;
      if (!other.onBoard) continue;
      const dx = other.x - first_.x;
      const dy = other.y - first_.y;
      const reach = first_.radius + other.radius;
      assert.ok(
        dx * dx + dy * dy > reach * reach * 0.98,
        'two pieces came to rest inside each other',
      );
    }
  }
}

{
  // Friction actually stops things. A striker sent along an empty board must
  // come to rest rather than bouncing between the cushions for ever - which is
  // what a viscous `v *= 0.99` does, and why the friction here is Coulomb.
  const lone = simulate(
    [
      {
        x: 0.5,
        y: 0.9,
        vx: 0,
        vy: -2.5,
        radius: 0.0279,
        mass: 15,
        onBoard: true,
      },
    ],
    0,
  );
  assert.equal(lone.pieces[0]!.vx, 0);
  assert.equal(lone.pieces[0]!.vy, 0);
  // And it never left the table on the way.
  for (const frame of lone.frames) {
    assert.ok(frame[0]! >= 0 && frame[0]! <= BOARD);
    assert.ok(frame[1]! >= 0 && frame[1]! <= BOARD);
  }
}

{
  // A coin sent straight at a pocket goes down it, and is not simulated after.
  const potted = simulate(
    [{ x: 0.3, y: 0.3, vx: -1.2, vy: -1.2, radius: 0.0215, mass: 5.5, onBoard: true }],
    -1,
  );
  assert.deepEqual(potted.pocketed, [0]);
  assert.equal(potted.pieces[0]!.onBoard, false);
}

// --- Carrom, as rules -------------------------------------------------------

{
  const carrom = GAMES.carrom;
  const start = carrom.create();

  // Nineteen men and a striker that is not on the board yet: it is placed by
  // whoever is shooting, on their own line, and a striker sitting there before
  // anybody has aimed is a coin in the way of the break.
  const pieces = carromPieces(start);
  assert.equal(pieces.filter((piece) => piece.onBoard).length, 19);
  assert.equal(pieces[STRIKER]!.onBoard, false);
  assert.deepEqual(carrom.score(start), [0, 0]);

  // A shot needs its three numbers, and they have to mean something.
  assert.equal(carrom.apply(start, 0, 0), null);
  assert.equal(carrom.apply(start, 0, 0, [0, -Math.PI / 2]), null);
  assert.equal(carrom.apply(start, 0, 0, [0, Number.NaN, 0.5]), null);
  // A shot with no power is not a shot, and spending a turn on a striker that
  // did not move is worse than being told no.
  assert.equal(carrom.apply(start, 0, 0, [0, -Math.PI / 2, 0]), null);
  // Not your turn.
  assert.equal(carrom.apply(start, 1, 0, [0, Math.PI / 2, 0.9]), null);

  const broken = carrom.apply(start, 0, 0, [0, -Math.PI / 2, 0.9]);
  assert.ok(broken);
  assert.equal(broken.moveCount, 1);
  // The striker is off the board again between shots, whatever happened to it.
  assert.equal(broken.data[STRIKER * 3 + 2], 0);
  // Nineteen coins are still accounted for: on the board, or pocketed, never
  // simply gone.
  const accounted = carromPieces(broken).filter((piece) => piece.onBoard).length;
  assert.ok(accounted <= 19);
}

{
  // The striker is placed on the shooter's own line, clamped to it, and never
  // on top of a coin.
  const carrom = GAMES.carrom;
  const start = carrom.create();
  const bottom = placeStriker(start, 0, 0);
  const top = placeStriker(start, 1, 0);
  assert.ok(bottom.y > BOARD / 2, 'seat 0 shoots from the near edge');
  assert.ok(top.y < BOARD / 2, 'seat 1 shoots from the other one');
  // Asked for somewhere off the end of the line, it stays on the line.
  const far = placeStriker(start, 0, 9);
  assert.ok(far.x <= BOARD / 2 + 0.26 && far.x >= BOARD / 2 - 0.26);
}

{
  // A striker down a pocket is a foul: the turn passes even though a coin of
  // the shooter's went down in the same shot, and one of theirs comes back.
  const carrom = GAMES.carrom;
  const state = carrom.create();
  const data = [...state.data];
  // Clear the board except one white coin sitting over a corner pocket, and
  // aim the striker at it hard enough that both go down.
  for (let index = 0; index < PIECES; index += 1) data[index * 3 + 2] = 0;
  data[0 * 3] = 0.075;
  data[0 * 3 + 1] = 0.075;
  data[0 * 3 + 2] = 1;
  const staged: GameState = { ...state, data };

  const shot = carrom.apply(staged, 0, 0, [-1, (-3 * Math.PI) / 4, 1]);
  assert.ok(shot);
  // Whatever happened to the coin, the shooter cannot have been rewarded with
  // another go by pocketing the striker.
  const strikerDown = (shot.data[STRIKER * 3 + 2] ?? 0) === 0;
  if (strikerDown && (shot.data[PIECES * 3 + 6] ?? 0) === 1) {
    assert.equal(shot.turn, 1, 'a foul passes the turn');
  }
}

{
  // Clearing your colour wins it, and the queen goes to whoever cleared if
  // nobody had taken her - so a game never ends with her unclaimed.
  const carrom = GAMES.carrom;
  const state = carrom.create();
  const data = [...state.data];
  for (const index of coinsOf(0)) data[index * 3 + 2] = 0;
  // One coin of the shooter's left, sitting in front of a pocket.
  data[coinsOf(0)[0]! * 3] = 0.075;
  data[coinsOf(0)[0]! * 3 + 1] = 0.075;
  data[coinsOf(0)[0]! * 3 + 2] = 1;
  for (const index of coinsOf(1)) data[index * 3 + 2] = 1;
  data[QUEEN * 3 + 2] = 1;

  const staged: GameState = { ...state, data };
  const shot = carrom.apply(staged, 0, 0, [-1, (-3 * Math.PI) / 4, 1]);
  assert.ok(shot);
  if (shot.winner !== null) {
    assert.equal(shot.winner, 0);
    assert.equal(carrom.score(shot)[0]! >= 9, true);
  }
}

// --- Ludo -------------------------------------------------------------------

{
  const ludo = GAMES.ludo;
  const start = ludo.create();

  // Nothing to choose until the die has been thrown, and the throw is the move.
  assert.deepEqual(ludo.moves(start), [ROLL]);
  assert.equal(dieOf(start), 0);
  for (let token = 0; token < TOKENS; token += 1) {
    assert.equal(progressOf(start, 0, token), YARD);
    assert.equal(progressOf(start, 1, token), YARD);
  }

  // A token cannot be moved before a roll, and a roll cannot happen twice.
  assert.equal(ludo.apply(start, 0, 0), null);
  // The die is the gateway's: `apply` is handed one, and the same source gives
  // the same game. A client rolling its own would be a client choosing sixes.
  const rolledSix = ludo.apply(start, 0, ROLL, undefined, () => 0.99);
  assert.ok(rolledSix);
  assert.equal(dieOf(rolledSix), 6);
  assert.equal(ludo.apply(rolledSix, 0, ROLL, undefined, () => 0.1), null);

  // A six is the only way out of the yard, and it is another go.
  assert.deepEqual(ludo.moves(rolledSix), [0, 1, 2, 3]);
  const out = ludo.apply(rolledSix, 0, 0, undefined, () => 0.5);
  assert.ok(out);
  assert.equal(progressOf(out, 0, 0), 0);
  assert.equal(out.turn, 0, 'a six is another go');
  assert.equal(dieOf(out), 0, 'the die is spent');
}

{
  // A number nothing can take passes the turn by itself. A board that waited
  // for a click on an empty list of options is a board that has stopped, and
  // the person looking at it has no way to know whose fault that is.
  const ludo = GAMES.ludo;
  const start = ludo.create();
  const rolledThree = ludo.apply(start, 0, ROLL, undefined, () => 0.4);
  assert.ok(rolledThree);
  assert.equal(rolledThree.turn, 1, 'nothing can move on a three from the yard');
  assert.equal(dieOf(rolledThree), 0);

  // ...but the number it was is still there to be shown. This is the commonest
  // roll in the game - four tokens in the yard and anything but a six - and
  // when the board could only read `dieOf`, it was spent and cleared in the
  // same message it arrived in: a player pressed roll, saw nothing at all, and
  // watched the turn go to the other person.
  assert.deepEqual(lastRoll(rolledThree), { value: 3, seat: 0, dead: true });
}

{
  // A roll that *can* be played is recorded the same way, and is not marked
  // dead - so the board can say "a six" without saying it was wasted.
  const ludo = GAMES.ludo;
  const six = ludo.apply(ludo.create(), 0, ROLL, undefined, () => 0.99);
  assert.ok(six);
  assert.deepEqual(lastRoll(six), { value: 6, seat: 0, dead: false });
  assert.equal(dieOf(six), 6);
}

{
  // Three sixes and the turn is gone.
  const ludo = GAMES.ludo;
  let state = ludo.create();
  // Out on the first six, then two more.
  const first = ludo.apply(state, 0, ROLL, undefined, () => 0.99);
  assert.ok(first);
  const moved = ludo.apply(first, 0, 0, undefined, () => 0.5);
  assert.ok(moved);
  state = moved;
  const second = ludo.apply(state, 0, ROLL, undefined, () => 0.99);
  assert.ok(second);
  const movedAgain = ludo.apply(second, 0, 0, undefined, () => 0.5);
  assert.ok(movedAgain);
  const third = ludo.apply(movedAgain, 0, ROLL, undefined, () => 0.99);
  assert.ok(third);
  assert.equal(third.turn, 1, 'three sixes forfeits the turn');
  assert.equal(dieOf(third), 0);
}

{
  // A capture sends a token home and earns another go - and it can only happen
  // on the shared lap, never on a starred square.
  const ludo = GAMES.ludo;
  const state = ludo.create();
  const data = [...state.data];
  // Red is three short of a square blue is standing on, and that square is not
  // one of the safe ones.
  const target = 12;
  data[tokenIndex(0, 0)] = target - 3;
  data[tokenIndex(1, 0)] = (target - 26 + 52) % 52;
  assert.equal(trackSquare(0, target), trackSquare(1, data[tokenIndex(1, 0)]!));

  const staged: GameState = { ...state, data, turn: 0 };
  const rolled = ludo.apply(staged, 0, ROLL, undefined, () => 0.4);
  assert.ok(rolled);
  assert.equal(dieOf(rolled), 3);
  const taken = ludo.apply(rolled, 0, 0, undefined, () => 0.5);
  assert.ok(taken);
  assert.equal(progressOf(taken, 1, 0), YARD, 'the token went back to the yard');
  assert.equal(taken.turn, 0, 'a capture is another go');
}

{
  // Home has to be reached exactly, which is what makes the end of a game take
  // a while: a token one short of home cannot take a five.
  const ludo = GAMES.ludo;
  const state = ludo.create();
  const data = [...state.data];
  data[tokenIndex(0, 0)] = HOME - 1;
  for (let token = 1; token < TOKENS; token += 1) data[tokenIndex(0, token)] = HOME;
  const staged: GameState = { ...state, data, turn: 0 };

  const five = ludo.apply(staged, 0, ROLL, undefined, () => 0.7);
  assert.ok(five);
  assert.equal(five.turn, 1, 'an unusable five passes the turn');

  const one = ludo.apply(staged, 0, ROLL, undefined, () => 0.05);
  assert.ok(one);
  assert.equal(dieOf(one), 1);
  assert.deepEqual(tokenMoves(one), [0]);
  const home = ludo.apply(one, 0, 0, undefined, () => 0.5);
  assert.ok(home);
  assert.equal(progressOf(home, 0, 0), HOME);
  // Four tokens home is the game.
  assert.equal(home.winner, 0);
  assert.deepEqual(GAMES.ludo.score(home), [4, 0]);
}

console.log('game-physics.check.ts: ok');

/**
 * Self-check for Play Together: the referee, and the four sets of rules it
 * referees with.
 *
 * The failures here are the ones that look like somebody cheating. A move
 * accepted from the wrong seat is an opponent who plays twice. A turn that
 * alternates through a closed box in Dots and Boxes is a chain that scores for
 * the wrong person. A Reversi position where neither player can move and the
 * game does not end is a board two people stare at waiting for the other one.
 * None of them throws, and none of them can be told from a rules disagreement
 * by the people playing.
 *
 * Run with `pnpm --filter @betweenus/call-service check`.
 */
import assert from 'node:assert/strict';
import {
  GAMES,
  boxLines,
  connectFourAt,
  flips,
  horizontal,
  movesFor,
  reversiAt,
  vertical,
  type GameSession,
} from '@betweenus/shared-types';
import { apply } from './game-session';

const ANA = { userId: 'ana', username: 'ana' };
const BO = { userId: 'bo', username: 'bo' };
const CAI = { userId: 'cai', username: 'cai' };

/** A session with both chairs filled, which is the only state a game plays in. */
function seated(gameId: keyof typeof GAMES): GameSession {
  const opened = apply(null, { kind: 'open', gameId }, ANA);
  assert.ok(opened);
  const full = apply(opened, { kind: 'sit', seat: 1 }, BO);
  assert.ok(full);
  return full;
}

// --- Opening and sitting ----------------------------------------------------

const opened = apply(null, { kind: 'open', gameId: 'tic-tac-toe' }, ANA);
assert.ok(opened);
// Opening sits the opener down. Two actions to express one intention is one
// action too many, and the second is the one people forget - which leaves a
// board on everybody's screen that its own author is not playing.
assert.equal(opened.seats[0]?.userId, 'ana');
assert.equal(opened.seats[1], null);
assert.equal(opened.rev, 1);
assert.equal(opened.round, 1);
assert.deepEqual(opened.wins, [0, 0]);

// Anything but `open` against nothing stays nothing: a move that arrives after
// the last person closed the game must not resurrect a board.
assert.equal(apply(null, { kind: 'move', move: 0 }, ANA), null);
assert.equal(apply(null, { kind: 'sit', seat: 0 }, ANA), null);
assert.equal(apply(null, { kind: 'rematch' }, ANA), null);

// A game unknown to this build is refused rather than crashed into: an older
// client, or a newer one, is a thing that will happen.
assert.equal(apply(null, { kind: 'open', gameId: 'chess' as never }, ANA), null);

// Re-opening the game already on an untouched table changes nothing - that is a
// double-click on the library card, not a request to start again.
assert.equal(apply(opened, { kind: 'open', gameId: 'tic-tac-toe' }, ANA), opened);

const bothSeated = seated('tic-tac-toe');
assert.equal(bothSeated.seats[1]?.userId, 'bo');
assert.equal(bothSeated.rev, 2);

// The chair is taken. The third person is told so by the state everybody
// already has, rather than by an error nobody has anywhere to put.
assert.equal(apply(bothSeated, { kind: 'sit', seat: 1 }, CAI), bothSeated);
// And sitting where you already sit is not a change either.
assert.equal(apply(bothSeated, { kind: 'sit', seat: 1 }, BO), bothSeated);

// Standing up frees the chair and leaves the board alone.
const stood = apply(bothSeated, { kind: 'sit', seat: -1 }, BO);
assert.ok(stood);
assert.equal(stood.seats[1], null);
assert.equal(stood.state.moveCount, 0);
// A watcher standing up is not a change.
assert.equal(apply(stood, { kind: 'sit', seat: -1 }, CAI), stood);

// --- Who may move -----------------------------------------------------------

// One player is not a game. Without this the person who opened it could play
// both sides while they waited for somebody to join.
assert.equal(apply(opened, { kind: 'move', move: 0 }, ANA), opened);

// Watching is the common case - everybody in the call sees the board - so a
// move from somebody with no chair is ignored rather than treated as an attack,
// though it is the check that stops one.
assert.equal(apply(bothSeated, { kind: 'move', move: 0 }, CAI), bothSeated);

// Out of turn, from a real player, is the same answer.
assert.equal(apply(bothSeated, { kind: 'move', move: 0 }, BO), bothSeated);

const played = apply(bothSeated, { kind: 'move', move: 4 }, ANA);
assert.ok(played);
assert.equal(played.state.cells[4], 0);
assert.equal(played.state.turn, 1);
assert.equal(played.state.lastMove, 4);
assert.equal(played.rev, bothSeated.rev + 1);

// The square is gone. A second click on it - a double click, or somebody who
// did not see the first - is a message that raced, not a move.
assert.equal(apply(played, { kind: 'move', move: 4 }, BO), played);
// So is a square that is not on the board.
assert.equal(apply(played, { kind: 'move', move: 9 }, BO), played);
assert.equal(apply(played, { kind: 'move', move: -1 }, BO), played);
assert.equal(apply(played, { kind: 'move', move: 1.5 }, BO), played);

// --- Tic-tac-toe ------------------------------------------------------------

{
  // X down the top row against O in the middle row: 0, 3, 1, 4, 2.
  let session = seated('tic-tac-toe');
  for (const [actor, move] of [
    [ANA, 0],
    [BO, 3],
    [ANA, 1],
    [BO, 4],
    [ANA, 2],
  ] as const) {
    const next = apply(session, { kind: 'move', move }, actor);
    assert.ok(next);
    session = next;
  }
  assert.equal(session.state.winner, 0);
  assert.deepEqual(session.wins, [1, 0]);
  // A finished board takes no more moves.
  assert.equal(apply(session, { kind: 'move', move: 5 }, BO), session);

  // A rematch keeps the chairs and the tally, and counts the round.
  const again = apply(session, { kind: 'rematch' }, BO);
  assert.ok(again);
  assert.equal(again.round, 2);
  assert.deepEqual(again.wins, [1, 0]);
  assert.equal(again.state.moveCount, 0);
  assert.equal(again.state.winner, null);
  assert.equal(again.seats[0]?.userId, 'ana');

  // Mid-game it is refused: that would be a resignation dressed as a button,
  // and the way out of a game in progress is to close it.
  const started = apply(again, { kind: 'move', move: 0 }, ANA);
  assert.ok(started);
  assert.equal(apply(started, { kind: 'rematch' }, ANA), started);
  // And a watcher may not clear two other people's board even when it is over.
  assert.equal(apply(session, { kind: 'rematch' }, CAI), session);
}

{
  // A full board with no line is a draw, and it belongs to nobody: the tally
  // must not move. `winner` of -1 is falsy-adjacent to seat 0, which is exactly
  // the bug this asserts against.
  let session = seated('tic-tac-toe');
  for (const [actor, move] of [
    [ANA, 0],
    [BO, 1],
    [ANA, 2],
    [BO, 4],
    [ANA, 3],
    [BO, 5],
    [ANA, 7],
    [BO, 6],
    [ANA, 8],
  ] as const) {
    const next = apply(session, { kind: 'move', move }, actor);
    assert.ok(next);
    session = next;
  }
  assert.equal(session.state.winner, -1);
  assert.deepEqual(session.wins, [0, 0]);
}

// --- Connect Four -----------------------------------------------------------

{
  // The move is a column, and that is the whole point: two people pressing the
  // same column stack, rather than racing for one hole.
  let session = seated('connect-four');
  const first = apply(session, { kind: 'move', move: 3 }, ANA);
  assert.ok(first);
  assert.equal(first.state.cells[connectFourAt(5, 3)], 0);
  const second = apply(first, { kind: 'move', move: 3 }, BO);
  assert.ok(second);
  assert.equal(second.state.cells[connectFourAt(4, 3)], 1);
  assert.equal(second.state.cells[connectFourAt(5, 3)], 0);

  // Red takes columns 0-3 along the bottom; yellow answers in 4 each time.
  session = seated('connect-four');
  for (const [actor, move] of [
    [ANA, 0],
    [BO, 4],
    [ANA, 1],
    [BO, 4],
    [ANA, 2],
    [BO, 4],
    [ANA, 3],
  ] as const) {
    const next = apply(session, { kind: 'move', move }, actor);
    assert.ok(next);
    session = next;
  }
  assert.equal(session.state.winner, 0);
  assert.deepEqual(session.wins, [1, 0]);
}

{
  // A full column is not a move. It is the one illegal thing in this game that
  // a player can reach for by accident, so it is ignored rather than an error.
  let state = GAMES['connect-four'].create();
  for (let i = 0; i < 6; i += 1) {
    const next = GAMES['connect-four'].apply(state, state.turn, 0);
    assert.ok(next);
    state = next;
  }
  assert.equal(GAMES['connect-four'].apply(state, state.turn, 0), null);
  assert.ok(!GAMES['connect-four'].moves(state).includes(0));
}

// --- Reversi ----------------------------------------------------------------

{
  const rules = GAMES.reversi;
  const start = rules.create();
  // The opening four, and black to move with exactly four legal squares.
  assert.deepEqual(rules.score(start), [2, 2]);
  assert.equal(rules.moves(start).length, 4);

  // Capturing nothing is not a move, however empty the square is.
  assert.equal(rules.apply(start, 0, reversiAt(0, 0)), null);
  assert.equal(flips(start.cells, 0, reversiAt(0, 0)).length, 0);

  const played = rules.apply(start, 0, reversiAt(2, 3));
  assert.ok(played);
  // One disc placed, one turned over: black is three up, white one down.
  assert.deepEqual(rules.score(played), [4, 1]);
  assert.equal(played.turn, 1);
}

{
  // The pass. A position where white has nothing to play hands the turn
  // straight back to black rather than sitting there asking white for a move
  // they cannot make - a rule that is obvious at a table and invisible on a
  // screen, which is why it is in the rules and not behind a button.
  //
  // Black plays (0,0) and turns the two whites on the top row over. The only
  // white left is the one at (6,0), tucked against the bottom edge where every
  // line that could reach it starts off the board.
  const cells = Array<number>(64).fill(-1);
  cells[reversiAt(0, 1)] = 1;
  cells[reversiAt(0, 2)] = 1;
  cells[reversiAt(0, 3)] = 0;
  cells[reversiAt(6, 0)] = 1;
  cells[reversiAt(7, 0)] = 0;
  const state = {
    gameId: 'reversi' as const,
    cells,
    boxes: [],
    data: [],
    turn: 0,
    winner: null,
    lastMove: null,
    moveCount: 0,
  };

  const next = GAMES.reversi.apply(state, 0, reversiAt(0, 0));
  assert.ok(next);
  assert.deepEqual(movesFor(next.cells, 1), []);
  // Black played, white cannot answer, so it is black's move again - and the
  // game is not over, because black still has somewhere to go.
  assert.equal(next.turn, 0);
  assert.equal(next.winner, null);
  assert.ok(GAMES.reversi.moves(next).includes(reversiAt(5, 0)));
}

{
  // Neither side can move: the game ends there and is scored on discs, not on
  // whose turn it was. Here black takes the last two white discs off the board,
  // which leaves white with nothing to play and black with nothing to take.
  const cells = Array<number>(64).fill(-1);
  cells[reversiAt(0, 1)] = 1;
  cells[reversiAt(0, 2)] = 1;
  cells[reversiAt(0, 3)] = 0;
  const state = {
    gameId: 'reversi' as const,
    cells,
    boxes: [],
    data: [],
    turn: 0,
    winner: null,
    lastMove: null,
    moveCount: 0,
  };
  const next = GAMES.reversi.apply(state, 0, reversiAt(0, 0));
  assert.ok(next);
  assert.deepEqual(GAMES.reversi.score(next), [4, 0]);
  assert.deepEqual(GAMES.reversi.moves(next), []);
  assert.equal(next.winner, 0);
}

// --- Dots and Boxes ---------------------------------------------------------

{
  const rules = GAMES['dots-and-boxes'];
  let state = rules.create();
  // Three sides of the top-left box, alternating - nothing is claimed, so the
  // turn alternates with it.
  for (const line of [horizontal(0, 0), horizontal(1, 0), vertical(0, 0)]) {
    const next = rules.apply(state, state.turn, line);
    assert.ok(next);
    state = next;
  }
  assert.deepEqual(rules.score(state), [0, 0]);

  // The fourth side closes it, and closing means going again. This is the whole
  // game: a chain of boxes is a run of moves, and a reducer that alternated the
  // turn regardless would score the chain for the wrong person.
  const seat = state.turn;
  const closed = rules.apply(state, seat, vertical(0, 1));
  assert.ok(closed);
  assert.equal(closed.boxes[0], seat);
  assert.equal(closed.turn, seat);
  assert.equal(rules.score(closed)[seat], 1);

  // A line already drawn is not a move.
  assert.equal(rules.apply(closed, closed.turn, vertical(0, 1)), null);
  // Every box has four sides and every side is a real line.
  assert.equal(new Set(boxLines(0, 0)).size, 4);
}

{
  // A finished board is scored, and the winner is the one with more squares -
  // not the one who drew the last line.
  const rules = GAMES['dots-and-boxes'];
  let state = rules.create();
  let guard = 0;
  while (state.winner === null) {
    const moves = rules.moves(state);
    assert.ok(moves.length > 0);
    const next = rules.apply(state, state.turn, moves[0]!);
    assert.ok(next);
    state = next;
    guard += 1;
    assert.ok(guard <= 40, 'a 5x5 board has forty lines and cannot take more');
  }
  const [blue, green] = rules.score(state);
  assert.equal(blue! + green!, 16);
  assert.equal(state.winner, blue === green ? -1 : blue! > green! ? 0 : 1);
}

// --- Leaving and closing ----------------------------------------------------

{
  let session = seated('connect-four');
  const moved = apply(session, { kind: 'move', move: 0 }, ANA);
  assert.ok(moved);
  session = moved;

  // Bo leaves the call. The chair is freed so somebody else can take it; the
  // board is left exactly as it was, because a person who dropped a socket in a
  // lift has not resigned a game three moves in.
  const left = apply(session, { kind: 'vacate', userId: 'bo' }, BO);
  assert.ok(left);
  assert.equal(left.seats[1], null);
  assert.equal(left.state.moveCount, 1);
  assert.equal(left.state.cells.filter((owner) => owner !== -1).length, 1);

  // Vacating somebody who was only watching changes nothing.
  assert.equal(apply(left, { kind: 'vacate', userId: 'cai' }, CAI), left);

  // The new arrival starts at zero wins even in a chair that had some.
  const withWins: GameSession = { ...left, wins: [2, 3] };
  const took = apply(withWins, { kind: 'sit', seat: 1 }, CAI);
  assert.ok(took);
  assert.deepEqual(took.wins, [2, 0]);

  // Closing is for everybody, and anybody in the call may do it - including
  // somebody watching, because a board left behind by two people who wandered
  // off is otherwise on the screen until the call ends.
  assert.equal(apply(took, { kind: 'close' }, CAI), null);
}

console.log('game-session.check.ts: ok');

/**
 * Play Together: the referee, as one pure function.
 *
 * A game session is a board, two chairs and a tally. This decides what each of
 * those becomes when somebody opens a game, sits down, moves, asks for a
 * rematch or closes it - and it decides *nothing* about the rules of the game
 * itself. Those come from `@betweenus/shared-types`, where the clients read
 * them too, because a referee that disagreed with the boards being drawn in
 * front of people would be a game nobody could argue about.
 *
 * The reason this is a server at all, when the media is peer to peer and the
 * chat is not: two people clicking the same square within a moment of each
 * other need one answer, and a mesh has no ordering to give one. It is the same
 * argument as the screen-share claim and the listening session's pause, and it
 * costs the same - a few hundred bytes when a person presses something.
 *
 * Everything here is pure, so the whole of it is testable without a socket or a
 * call. See `game-session.check.ts`.
 *
 * ponytail: in memory beside the roster, exactly like `CallGateway.calls` and
 * the listening session. Two call-service replicas would each referee half a
 * game; the upgrade path is the same one - the roster in Redis, this beside it.
 */
import { randomInt } from 'node:crypto';
import {
  GAMES,
  gameRules,
  type GameId,
  type GameSeat,
  type GameSession,
} from '@betweenus/shared-types';

/** What a client asked for, once the gateway has decided who asked. */
export type GameAction =
  | { kind: 'open'; gameId: GameId }
  /** `seat` of -1 is standing up: still in the call, no longer playing. */
  | { kind: 'sit'; seat: number }
  /**
   * `params` completes a move that an index cannot express - a carrom shot's
   * placement, aim and power. The rules validate it; nothing here reads it.
   */
  | { kind: 'move'; move: number; params?: number[] }
  | { kind: 'rematch' }
  | { kind: 'close' }
  /** Not a button anybody presses - somebody left the call. See `vacate`. */
  | { kind: 'vacate'; userId: string };

/**
 * The die, and the only randomness in any of this.
 *
 * It is here rather than in the rules because the roll has to be decided once,
 * by the referee: a client that rolled its own would be a client that decides
 * its own sixes. `randomInt` rather than `Math.random` because a predictable
 * die in a game people are competing at is worth one import - the sequence a
 * seeded PRNG produces can be worked out from the rolls everybody has already
 * seen.
 */
const roll: () => number = () => randomInt(0, 1_000_000) / 1_000_000;

/** Who is acting, from the socket rather than from the message. */
export interface Actor {
  userId: string;
  username: string;
}

/**
 * Opens a game, with whoever opened it already sitting in the first chair.
 *
 * Sitting them down is the point. "Open a game and then take a seat" is two
 * actions to express one intention, and the second of them is the one somebody
 * forgets - leaving a board on everybody's screen that its own author is not
 * playing.
 */
function open(gameId: GameId, actor: Actor): GameSession | null {
  const rules = gameRules(gameId);
  if (!rules) return null;

  const seats: (GameSeat | null)[] = Array.from({ length: rules.definition.seats }, () => null);
  seats[0] = { userId: actor.userId, username: actor.username };

  return {
    rev: 1,
    gameId,
    seats,
    state: rules.create(),
    round: 1,
    wins: seats.map(() => 0),
    byUserId: actor.userId,
  };
}

/**
 * Applies one action. Returns the new session, or null when there is no longer
 * one - which is what the call is told, and what closes everybody's board.
 *
 * Returning the session unchanged means nobody is told anything, and that is
 * the ordinary answer to a message that raced: a move from the person whose
 * turn it no longer is, a click on a square somebody else just took, a second
 * `sit` in a chair that is now full. None of those is an error worth a round
 * trip - each is a thing that was true when it was sent.
 */
export function apply(
  session: GameSession | null,
  action: GameAction,
  actor: Actor,
): GameSession | null {
  if (action.kind === 'close') return null;

  if (!session) {
    // Opening is the only thing that can happen to nothing. A move arriving
    // after the last person closed the game must not resurrect a board.
    return action.kind === 'open' ? open(action.gameId, actor) : null;
  }

  const next = mutate(session, action, actor);
  if (!next) return null;
  if (next === session) return session;
  return { ...next, rev: session.rev + 1 };
}

function mutate(
  session: GameSession,
  action: GameAction,
  actor: Actor,
): GameSession | null {
  switch (action.kind) {
    case 'open': {
      // Changing the game is allowed to anybody, deliberately, and it is the
      // same argument as the listening queue having no host: a host is a person
      // who eventually leaves and takes the game with them. Re-opening the game
      // already on the table is a no-op rather than a board wipe, because that
      // is a double-click on the library card and not a request to abandon a
      // game in progress.
      if (action.gameId === session.gameId && session.state.moveCount === 0) return session;
      return open(action.gameId, actor);
    }

    case 'sit': {
      const seats = [...session.seats];
      const wins = [...session.wins];
      const current = seats.findIndex((seat) => seat?.userId === actor.userId);

      if (action.seat === -1) {
        // Standing up. The chair stays where it is - its tally goes with it,
        // so somebody who mis-clicks and sits back down has lost nothing.
        if (current === -1) return session;
        seats[current] = null;
        return { ...session, seats };
      }

      if (!Number.isInteger(action.seat) || action.seat < 0 || action.seat >= seats.length) {
        return session;
      }
      if (current === action.seat) return session;
      // Taken. Not an error: two people reaching for the last chair is the
      // ordinary case, and the second of them is simply told who is in it by
      // the state everybody already gets.
      if (seats[action.seat]) return session;

      if (current !== -1) seats[current] = null;
      seats[action.seat] = { userId: actor.userId, username: actor.username };
      // A new person in the chair starts at nothing. The tally belongs to the
      // chair, and inheriting somebody else's three wins by sitting where they
      // sat is a scoreboard that lies.
      if (session.seats[action.seat]?.userId !== actor.userId) wins[action.seat] = 0;
      return { ...session, seats, wins };
    }

    case 'move': {
      const rules = GAMES[session.gameId];
      const seat = session.seats.findIndex((chair) => chair?.userId === actor.userId);
      // Watching. Everybody in the call sees the board and most of them are not
      // playing it, so this is the common case rather than an attack - though
      // it is also the check that stops one.
      if (seat === -1) return session;
      // An empty chair is not an opponent. Without this the person who opened
      // the game could play both sides of it while they waited.
      if (session.seats.some((chair) => chair === null)) return session;

      const state = rules.apply(session.state, seat, action.move, action.params, roll);
      // Illegal, or simply late: the rules said no. Saying so back would be a
      // message about a board the sender already has.
      if (!state) return session;

      const wins = [...session.wins];
      // A draw is `-1` and belongs to nobody, which is why this is a bounds
      // check and not a truthiness one - seat 0 winning is falsy.
      if (state.winner !== null && state.winner >= 0) wins[state.winner] = (wins[state.winner] ?? 0) + 1;
      return { ...session, state, wins };
    }

    case 'rematch': {
      // Only from somebody at the table. A watcher clearing a finished game off
      // two other people's screens is not a thing to allow by accident.
      if (!session.seats.some((chair) => chair?.userId === actor.userId)) return session;
      // Mid-game this would be a resignation dressed as a button, so it is
      // refused: the way out of a game in progress is to close it, which says
      // what it does.
      if (session.state.winner === null && session.state.moveCount > 0) return session;
      return {
        ...session,
        state: GAMES[session.gameId].create(),
        round: session.round + 1,
      };
    }

    case 'vacate': {
      // Somebody left the call. Their chair is freed so the game can carry on
      // with whoever takes it, rather than sitting there waiting for a person
      // who has gone. The board is left exactly as it was - a game two people
      // are three moves into is not something to throw away because one of them
      // dropped a socket in a lift.
      const at = session.seats.findIndex((chair) => chair?.userId === action.userId);
      if (at === -1) return session;
      const seats = [...session.seats];
      seats[at] = null;
      return { ...session, seats };
    }

    default:
      return session;
  }
}

/**
 * Self-check for the Listen Together transport.
 *
 * Everything this guards is invisible when it breaks. A position stamped
 * against the wrong instant does not throw - it plays the music a second late
 * on one machine, which is exactly the thing this feature exists to prevent and
 * exactly the thing nobody can screenshot. An `ended` that is not idempotent
 * skips three tracks in a three-person call and looks like somebody else did
 * it. A queue with no ceiling is one person's afternoon in everybody's sidebar.
 *
 * Run with `pnpm --filter @betweenus/call-service check`.
 */
import assert from 'node:assert/strict';
import type { ListenSession, ListenTrack } from '@betweenus/shared-types';
import { MAX_QUEUE, apply, positionAt, sanitiseTrack } from './listen-session';

const T0 = 1_700_000_000_000;

function track(id: string, ref = 'dQw4w9WgXcQ', durationMs = 180_000): ListenTrack {
  return {
    id,
    provider: 'youtube',
    ref,
    title: `track ${id}`,
    durationMs,
    addedByUserId: 'ana',
    addedByUsername: 'ana',
  };
}

function start(): ListenSession {
  const session = apply(null, { kind: 'add', track: track('a') }, 'ana', T0);
  assert.ok(session);
  return session;
}

// --- Starting ---------------------------------------------------------------

// Adding the first track is what opens a session. There is no separate "start"
// because the person pressing it wants to hear something, not to open a room.
const first = start();
assert.equal(first.queue.length, 1);
assert.equal(first.index, 0);
assert.equal(first.paused, false);
assert.equal(first.positionMs, 0);
assert.equal(first.rev, 1);

// Anything but `add` against nothing stays nothing: a pause arriving after the
// last person closed the session must not resurrect it as an empty one.
assert.equal(apply(null, { kind: 'pause', positionMs: 0 }, 'ana', T0), null);
assert.equal(apply(null, { kind: 'skip', delta: 1 }, 'ana', T0), null);

// `playNow` adds and jumps in one action. Two messages could not do it: an add
// that arrived in between would move the index the play was aiming at, and the
// call would hear somebody else's track instead of the one that was pressed.
const playedNow = apply(
  apply(first, { kind: 'add', track: track('b') }, 'ana', T0),
  { kind: 'add', track: track('c'), playNow: true },
  'bo',
  T0 + 1_000,
);
assert.ok(playedNow);
assert.equal(playedNow.queue.length, 3);
assert.equal(playedNow.index, 2);
assert.equal(playedNow.positionMs, 0);
assert.equal(playedNow.paused, false);

// Without it the cursor stays where it was: a track queued while another plays
// does not interrupt it.
const appended = apply(first, { kind: 'add', track: track('d') }, 'bo', T0 + 1_000);
assert.ok(appended);
assert.equal(appended.index, 0);

// --- The clock, which is the whole feature ----------------------------------

// Playing: the position is where it was plus how long ago that was. This is the
// one line that lets a single message stay true without another one arriving.
assert.equal(positionAt(first, T0 + 5_000), 5_000);
assert.equal(positionAt(first, T0 + 90_000), 90_000);

// Paused: time passing changes nothing.
const paused = apply(first, { kind: 'pause', positionMs: 42_000 }, 'ben', T0 + 42_000)!;
assert.equal(paused.paused, true);
assert.equal(positionAt(paused, T0 + 42_000), 42_000);
assert.equal(positionAt(paused, T0 + 600_000), 42_000);

// Resuming from a pause carries on from where it stopped rather than restarting.
const resumed = apply(paused, { kind: 'play' }, 'ben', T0 + 100_000)!;
assert.equal(resumed.paused, false);
assert.equal(positionAt(resumed, T0 + 100_000), 42_000);
assert.equal(positionAt(resumed, T0 + 105_000), 47_000);

// A session left playing overnight reports the end of the track, not the middle
// of next Tuesday.
assert.equal(positionAt(first, T0 + 10 * 60 * 60 * 1000), 180_000);

// A change that is not about the transport must not move the transport. This is
// the freeze bug: re-stamping without recomputing the position rewinds the
// track by however long it had been playing. A pasted link has neither a title
// nor a length until somebody's player says so, which is when this happens.
const pasted = apply(
  null,
  { kind: 'add', track: { ...track('a'), title: '', durationMs: 0 } },
  'ana',
  T0,
)!;
const named = apply(pasted, { kind: 'meta', trackId: 'a', title: 'Real Title', durationMs: 200_000 }, 'ben', T0 + 52_000)!;
assert.equal(positionAt(named, T0 + 52_000), 52_000);
assert.equal(named.queue[0]!.durationMs, 200_000);
assert.equal(named.queue[0]!.title, 'Real Title');

// --- Two people pressing things ---------------------------------------------

// Every change is ordered by the gateway, so a client can drop its own echo of
// an older state and keep the newer one somebody else caused.
assert.equal(resumed.rev > paused.rev, true);
assert.equal(paused.rev > first.rev, true);
assert.equal(named.byUserId, 'ben');
assert.equal(paused.byUserId, 'ben');
assert.equal(resumed.byUserId, 'ben');

// First answer holds. A second client reporting a different title is either a
// different regional cut or somebody relabelling a track in everybody else's
// queue after the fact - either way, not a correction worth taking.
assert.equal(
  apply(named, { kind: 'meta', trackId: 'a', title: 'Something Else' }, 'cat', T0 + 53_000)!.queue[0]!.title,
  'Real Title',
);
assert.equal(
  apply(named, { kind: 'meta', trackId: 'a', durationMs: 999_000 }, 'cat', T0 + 53_000)!.queue[0]!.durationMs,
  200_000,
);
// And metadata for a track nobody here has is about a queue somebody else holds.
assert.equal(apply(named, { kind: 'meta', trackId: 'nope', title: 'x' }, 'cat', T0 + 54_000), named);

// A change that changes nothing is not a change: no rev, so nobody's player is
// disturbed by a message that arrived late.
const again = apply(named, { kind: 'meta', trackId: 'a', durationMs: 200_000 }, 'cat', T0 + 55_000)!;
assert.equal(again.rev, named.rev);
assert.equal(again, named);

// --- The queue --------------------------------------------------------------

let queued = apply(first, { kind: 'add', track: track('b') }, 'ben', T0 + 1_000)!;
queued = apply(queued, { kind: 'add', track: track('c') }, 'ben', T0 + 2_000)!;
assert.equal(queued.queue.length, 3);
// Adding does not interrupt what is playing.
assert.equal(queued.index, 0);
assert.equal(positionAt(queued, T0 + 2_000), 2_000);

// Removing something further down the queue leaves the needle exactly alone.
const trimmed = apply(queued, { kind: 'remove', trackId: 'c' }, 'ana', T0 + 3_000)!;
assert.equal(trimmed.index, 0);
assert.equal(positionAt(trimmed, T0 + 3_000), 3_000);

// Removing something *above* the needle shifts the cursor with it, so the same
// track goes on playing rather than the list sliding out from under it.
const jumped = apply(queued, { kind: 'play', index: 2 }, 'ana', T0 + 4_000)!;
assert.equal(jumped.index, 2);
const shifted = apply(jumped, { kind: 'remove', trackId: 'a' }, 'ana', T0 + 5_000)!;
assert.equal(shifted.index, 1);
assert.equal(shifted.queue[shifted.index]!.id, 'c');

// Removing what is playing moves to whatever took its place.
const replaced = apply(queued, { kind: 'remove', trackId: 'a' }, 'ana', T0 + 6_000)!;
assert.equal(replaced.queue[replaced.index]!.id, 'b');
assert.equal(replaced.positionMs, 0);

// Emptying the queue closes the session: a cursor into nothing is not a state.
let draining: ListenSession | null = first;
draining = apply(draining, { kind: 'remove', trackId: 'a' }, 'ana', T0 + 7_000);
assert.equal(draining, null);

// The ceiling holds, and holds without throwing away the session.
let full: ListenSession = first;
for (let index = 0; index < MAX_QUEUE + 10; index += 1) {
  full = apply(full, { kind: 'add', track: track(`x${index}`) }, 'ana', T0)!;
}
assert.equal(full.queue.length, MAX_QUEUE);

// --- Skipping ---------------------------------------------------------------

// Back within the first few seconds is "the previous track"; later it is
// "start this one again", which is what every music player does.
const onSecond = apply(queued, { kind: 'play', index: 1 }, 'ana', T0 + 10_000)!;
assert.equal(apply(onSecond, { kind: 'skip', delta: -1 }, 'ana', T0 + 12_000)!.index, 0);
assert.equal(apply(onSecond, { kind: 'skip', delta: -1 }, 'ana', T0 + 20_000)!.index, 1);
assert.equal(positionAt(apply(onSecond, { kind: 'skip', delta: -1 }, 'ana', T0 + 20_000)!, T0 + 20_000), 0);

// Running off the end stops at the end. It does not close the session: the
// queue two people built is not rubbish the moment the last track finishes.
const atEnd = apply(queued, { kind: 'skip', delta: 9 }, 'ana', T0 + 30_000)!;
assert.equal(atEnd.index, queued.queue.length - 1);
assert.equal(atEnd.paused, true);

// Running off the front rewinds rather than wrapping round to the end.
const atStart = apply(queued, { kind: 'skip', delta: -9 }, 'ana', T0 + 30_000)!;
assert.equal(atStart.index, 0);
assert.equal(atStart.paused, false);

// --- `ended`, which every client sends --------------------------------------

// Three people in the call means three of these. The first advances; the rest
// are about a track that is no longer playing and do nothing. Without this the
// three-person call skips three tracks and everybody blames somebody else.
const done = apply(queued, { kind: 'ended', trackId: 'a' }, 'ana', T0 + 180_000)!;
assert.equal(done.index, 1);
const twice = apply(done, { kind: 'ended', trackId: 'a' }, 'ben', T0 + 180_100)!;
assert.equal(twice.index, 1);
assert.equal(twice.rev, done.rev);
const thrice = apply(twice, { kind: 'ended', trackId: 'a' }, 'cat', T0 + 180_200)!;
assert.equal(thrice.index, 1);

// A paused session does not advance on a late `ended`.
const pausedThenEnded = apply(
  apply(queued, { kind: 'pause', positionMs: 179_000 }, 'ana', T0 + 179_000)!,
  { kind: 'ended', trackId: 'a' },
  'ben',
  T0 + 180_000,
)!;
assert.equal(pausedThenEnded.index, 0);

// --- Seeking ----------------------------------------------------------------

const sought = apply(queued, { kind: 'seek', positionMs: 60_000 }, 'ben', T0 + 30_000)!;
assert.equal(positionAt(sought, T0 + 30_000), 60_000);
assert.equal(sought.paused, false);
// Still running from there.
assert.equal(positionAt(sought, T0 + 35_000), 65_000);
// Past the end of a track whose length is known is clamped to the end, and
// negative nonsense is clamped to the start.
assert.equal(apply(queued, { kind: 'seek', positionMs: 9_999_999 }, 'ben', T0)!.positionMs, 180_000);
assert.equal(apply(queued, { kind: 'seek', positionMs: -5_000 }, 'ben', T0)!.positionMs, 0);
assert.equal(apply(queued, { kind: 'seek', positionMs: Number.NaN }, 'ben', T0)!.positionMs, 0);

// --- Stopping ---------------------------------------------------------------

assert.equal(apply(queued, { kind: 'stop' }, 'ana', T0), null);

// --- What may be put in front of other people -------------------------------

// The ref goes into an iframe URL in everybody's window, so it is checked
// against the provider's own alphabet rather than trusted.
assert.equal(sanitiseTrack(track('a', 'dQw4w9WgXcQ'))?.ref, 'dQw4w9WgXcQ');
assert.equal(sanitiseTrack(track('a', '../../evil')), null);
assert.equal(sanitiseTrack(track('a', 'a')), null);
assert.equal(sanitiseTrack(track('a', 'x'.repeat(64))), null);
assert.equal(sanitiseTrack({ ...track('a'), provider: 'spotify' as never }), null);

// A title is drawn in other people's windows, so it is bounded.
assert.equal(sanitiseTrack({ ...track('a'), title: 'x'.repeat(5_000) })!.title.length, 200);

// A duration nobody can justify makes the seek bar meaningless for everybody.
assert.equal(sanitiseTrack({ ...track('a'), durationMs: -1 })!.durationMs, 0);
assert.equal(sanitiseTrack({ ...track('a'), durationMs: Number.POSITIVE_INFINITY })!.durationMs, 0);
assert.equal(sanitiseTrack({ ...track('a'), durationMs: 1e12 })!.durationMs, 12 * 60 * 60 * 1000);

// And a rejected track never becomes a session.
assert.equal(apply(null, { kind: 'add', track: track('a', '!!') }, 'ana', T0), null);

console.log('call-service listen-session self-check passed');

/**
 * Listen Together: the shared transport, as one pure function.
 *
 * A listening session is a queue, a cursor into it, and an answer to "where is
 * the needle right now". The last of those is the only interesting part,
 * because "right now" is different on every machine in the call.
 *
 * The trick is that the session never stores a position. It stores a position
 * *and the instant it was true* - `positionMs` at `atServerMs` - so a client
 * that receives one message can work out the position at any later moment
 * without another message arriving. Playing is `positionMs + elapsed`; paused
 * is `positionMs`. One state, good until somebody presses something.
 *
 * Everything here is pure and takes `nowMs`, so the whole of it is testable
 * without a socket, a clock or a call. See `listen-session.check.ts` - the
 * failures this guards against are the ones that only appear as "the music is
 * two seconds behind on your machine and neither of us can prove it".
 *
 * Note what is *not* here: no persistence, no database, no history. A session
 * lives in memory beside the roster and dies with the call, which is what it
 * is - the queue three people built while they worked has no meaning tomorrow.
 *
 * ponytail: in process, exactly like `CallGateway.calls`. Two call-service
 * replicas would each hold half a session, and the upgrade path is the same
 * one - the roster in Redis, this state beside it.
 */
import { listenPositionAt, type ListenSession, type ListenTrack } from '@betweenus/shared-types';

/**
 * How long a queue may get.
 *
 * Not a resource limit - a hundred entries is a few kilobytes. It is a limit on
 * what one person can do to everybody else's screen, because the queue is
 * broadcast to the whole call and every entry carries a title somebody chose.
 */
export const MAX_QUEUE = 100;

/** Titles are drawn in other people's windows, so they are bounded here. */
export const MAX_TITLE = 200;

/** What a client asked for, once the gateway has decided who asked. */
export type ListenAction =
  | { kind: 'add'; track: ListenTrack; playNow?: boolean }
  | { kind: 'remove'; trackId: string }
  | { kind: 'play'; index?: number }
  | { kind: 'pause'; positionMs: number }
  | { kind: 'seek'; positionMs: number }
  | { kind: 'skip'; delta: number }
  | { kind: 'ended'; trackId: string }
  | { kind: 'meta'; trackId: string; title?: string; durationMs?: number }
  | { kind: 'stop' };

/**
 * Where the needle is at `nowMs`.
 *
 * The arithmetic lives in `@betweenus/shared-types` and not here, because it is
 * the meaning of `positionMs` and `atServerMs` rather than a decision this
 * service makes: a gateway that advanced the position differently from the
 * clients reading it would be a session where nobody is wrong and nobody
 * agrees.
 */
export const positionAt = listenPositionAt;

/**
 * Re-stamps a session at `nowMs` without changing what it is doing.
 *
 * Every mutation goes through this first. Skipping it is the bug that made a
 * session freeze on a title change: writing a new `atServerMs` while leaving
 * `positionMs` as it was an hour ago rewinds the track by an hour, and doing it
 * the other way - a new position under an old stamp - runs it forward by one.
 */
function restamp(session: ListenSession, nowMs: number): ListenSession {
  return { ...session, positionMs: positionAt(session, nowMs), atServerMs: nowMs };
}

/** Trims what a client supplied down to what may be shown to other people. */
export function sanitiseTrack(track: ListenTrack): ListenTrack | null {
  if (track.provider !== 'youtube') return null;
  // The provider's own alphabet. Anything else is either a typo or an attempt
  // to put a URL of somebody's choosing into an iframe in everybody's window.
  if (!/^[A-Za-z0-9_-]{6,24}$/.test(track.ref)) return null;
  return {
    ...track,
    title: track.title.slice(0, MAX_TITLE),
    durationMs: clampDuration(track.durationMs),
  };
}

function clampDuration(durationMs: number): number {
  if (!Number.isFinite(durationMs) || durationMs <= 0) return 0;
  // Twelve hours. Long enough for the longest thing anybody queues on purpose,
  // short enough that a nonsense number cannot make the seek bar meaningless.
  return Math.min(Math.round(durationMs), 12 * 60 * 60 * 1000);
}

function clampPosition(session: ListenSession, positionMs: number): number {
  if (!Number.isFinite(positionMs) || positionMs < 0) return 0;
  const duration = session.queue[session.index]?.durationMs ?? 0;
  return duration > 0 ? Math.min(Math.round(positionMs), duration) : Math.round(positionMs);
}

/**
 * Moves the cursor, and says what that means for the transport.
 *
 * Running off the end stops at the end rather than closing the session: the
 * queue is a thing two people built together, and the last track finishing is
 * not a reason to throw it away. Running off the front is a rewind to the start
 * of the first track, which is what pressing "previous" twice means everywhere.
 */
function move(session: ListenSession, to: number, nowMs: number): ListenSession {
  if (to < 0) return { ...session, index: 0, positionMs: 0, atServerMs: nowMs, paused: false };
  if (to >= session.queue.length) {
    const last = session.queue.length - 1;
    return {
      ...session,
      index: last,
      positionMs: session.queue[last]?.durationMs ?? 0,
      atServerMs: nowMs,
      paused: true,
    };
  }
  return { ...session, index: to, positionMs: 0, atServerMs: nowMs, paused: false };
}

/**
 * Applies one action. Returns the new session, or null when there is no longer
 * one - which is what the call is told, and what closes everybody's player.
 *
 * `session` being null and the action being `add` is how a session starts:
 * there is no "open a session" button, because a person who wants to listen
 * together wants to play something, and asking them to do two things first is
 * a step that exists only for the benefit of the state machine.
 */
export function apply(
  session: ListenSession | null,
  action: ListenAction,
  actorUserId: string,
  nowMs: number,
): ListenSession | null {
  if (action.kind === 'stop') return null;

  if (!session) {
    if (action.kind !== 'add') return null;
    const track = sanitiseTrack(action.track);
    if (!track) return session;
    return {
      rev: 1,
      queue: [track],
      index: 0,
      paused: false,
      positionMs: 0,
      atServerMs: nowMs,
      byUserId: actorUserId,
    };
  }

  // Compared against the *stamped* session, not the one that came in: restamping
  // always makes a new object, so `next === session` was never true and every
  // late `duration` bumped the rev and made every client re-seek for nothing.
  const stamped = restamp(session, nowMs);
  const next = mutate(stamped, action, nowMs);
  if (!next) return null;
  // Unchanged means nobody is told: a `duration` for a track that already had
  // one, or an `ended` for a track that is no longer playing, is a message that
  // arrived late rather than a thing that happened.
  if (next === stamped) return session;
  return { ...next, rev: session.rev + 1, byUserId: actorUserId };
}

function mutate(
  session: ListenSession,
  action: ListenAction,
  nowMs: number,
): ListenSession | null {
  switch (action.kind) {
    case 'add': {
      const track = sanitiseTrack(action.track);
      if (!track) return session;
      if (session.queue.length >= MAX_QUEUE) return session;
      const queued = { ...session, queue: [...session.queue, track] };
      // `playNow` is a play at the end of an add rather than a second message,
      // because the two have to be one decision: an add followed by a play is
      // two revs, and anything that arrives between them - somebody else's add,
      // a remove - moves the index the play was aiming at.
      return action.playNow ? move(queued, queued.queue.length - 1, nowMs) : queued;
    }

    case 'remove': {
      const at = session.queue.findIndex((track) => track.id === action.trackId);
      if (at === -1) return session;
      const queue = session.queue.filter((track) => track.id !== action.trackId);
      // The last one out closes the session, which is the only way an empty
      // queue can be described: a cursor into nothing is not a state.
      if (queue.length === 0) return null;
      if (at > session.index) return { ...session, queue };
      // Removing something before the cursor shifts the cursor with it, so the
      // track playing goes on playing - it is the same track, at the same
      // position, one place further up the list.
      if (at < session.index) return { ...session, queue, index: session.index - 1 };
      // Removing what is playing moves to whatever took its place, or to the
      // new end of the queue when it was the last entry.
      return move({ ...session, queue }, Math.min(session.index, queue.length - 1), nowMs);
    }

    case 'play': {
      if (action.index === undefined) return { ...session, paused: false };
      if (action.index < 0 || action.index >= session.queue.length) return session;
      // Jumping to the track already playing is a resume, not a restart: a
      // double-click on the current row should not lose everybody's place.
      if (action.index === session.index) return { ...session, paused: false };
      return move(session, action.index, nowMs);
    }

    case 'pause':
      return { ...session, paused: true, positionMs: clampPosition(session, action.positionMs) };

    case 'seek':
      return { ...session, positionMs: clampPosition(session, action.positionMs) };

    case 'skip': {
      const delta = Math.trunc(action.delta);
      if (delta === 0) return session;
      // Skipping back within the first few seconds of a track means "the
      // previous one"; later it means "start this one again", which is what
      // every music player does and what everybody's hands already expect.
      if (delta < 0 && positionAt(session, nowMs) > 3000) return move(session, session.index, nowMs);
      return move(session, session.index + delta, nowMs);
    }

    case 'ended': {
      // Late, or from a client whose player ran ahead. Everybody sends this;
      // only the first one that is about the track actually playing counts.
      if (session.queue[session.index]?.id !== action.trackId) return session;
      if (session.paused) return session;
      return move(session, session.index + 1, nowMs);
    }

    case 'meta': {
      const at = session.queue.findIndex((track) => track.id === action.trackId);
      if (at === -1) return session;
      const existing = session.queue[at]!;
      const durationMs = clampDuration(action.durationMs ?? 0);
      // Only what is still missing. A second client reporting the same title is
      // not news, and a client reporting a *different* one is either a
      // different regional cut or somebody trying to relabel a track in
      // everybody else's queue after the fact - either way, first answer holds.
      const title = existing.title || (action.title ?? '').slice(0, MAX_TITLE);
      const nextDuration = existing.durationMs || durationMs;
      if (title === existing.title && nextDuration === existing.durationMs) return session;
      const queue = [...session.queue];
      queue[at] = { ...existing, title, durationMs: nextDuration };
      return { ...session, queue };
    }

    default:
      return session;
  }
}

import 'reflect-metadata';
import type { Server as HttpServer } from 'node:http';
import { envOr, onIceProblem } from '@betweenus/config';
import { createLogger, type LogLevel } from '@betweenus/logger';
import { bootstrapService } from '@betweenus/nest-common';
import { AppModule } from './app.module';
import { CallGateway } from './call.gateway';

async function start(): Promise<void> {
  const app = await bootstrapService({
    service: 'call-service',
    module: AppModule,
    portVar: 'CALL_SERVICE_PORT',
    defaultPort: 3007,
  });

  // A revoked TURN key is invisible until somebody on a hostile network cannot
  // connect, so it says so here rather than nowhere.
  const logger = createLogger('call-service', envOr('LOG_LEVEL', 'info') as LogLevel);
  onIceProblem((message, error) => logger.error(message, error));

  // The signalling server shares the HTTP listener, so /ws/call and /health
  // live behind one port and one Nginx upstream - the same arrangement
  // presence-service uses.
  //
  // Nothing is verified against a media server at startup any more, because
  // there is not one to be wrong about. This service is ready when it is
  // listening.
  app.get(CallGateway).attach(app.getHttpServer() as HttpServer);
}

void start();

import { Body, Controller, Get, HttpCode, Post, Query, UseGuards } from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type { CallAnalytics, CallHistoryEntry, CallIceResponse } from '@betweenus/shared-types';
import { CallsService } from './calls.service';
import { CallDeclineDto, CallIceDto, CallRingDto } from './dto';

@Controller('calls')
@UseGuards(JwtAuthGuard)
export class CallsController {
  constructor(private readonly calls: CallsService) {}

  /**
   * No `Host` header is read here, unlike the token endpoint this replaced.
   * That header existed to catch a media-server address the caller could never
   * reach; nothing is advertised to a caller any more, so there is nothing that
   * could be wrong about where they are.
   */
  @Post('ice')
  ice(@CurrentUser() user: AuthenticatedUser, @Body() dto: CallIceDto): Promise<CallIceResponse> {
    return this.calls.ice(user.id, dto.channelId);
  }

  /**
   * "Come into this call."
   *
   * The caller is the authenticated user and never the body: a ring that could
   * name its own sender is a ring that could be sent as somebody else.
   */
  /**
   * This account's own call log. Whose is never a parameter: the only thing
   * that could be wrong about a private history is reading somebody else's.
   */
  @Get('history')
  history(@CurrentUser() user: AuthenticatedUser): Promise<CallHistoryEntry[]> {
    return this.calls.history(user.id);
  }

  /**
   * The same rows added up, for the page the log hangs under.
   *
   * `days` is a hint and not a promise: the service clamps it, because a client
   * asking for a hundred thousand days is a client asking for every row it has
   * ever written.
   */
  @Get('analytics')
  analytics(
    @CurrentUser() user: AuthenticatedUser,
    @Query('days') days?: string,
  ): Promise<CallAnalytics> {
    return this.calls.analytics(user.id, Number(days));
  }

  @Post('ring')
  @HttpCode(204)
  ring(@CurrentUser() user: AuthenticatedUser, @Body() dto: CallRingDto): Promise<void> {
    return this.calls.ring(user.id, dto.channelId, dto.userId);
  }

  /**
   * "I said no to that." Reaches this account's other devices and nobody else -
   * see `CallsService.decline`.
   */
  @Post('decline')
  @HttpCode(204)
  decline(@CurrentUser() user: AuthenticatedUser, @Body() dto: CallDeclineDto): Promise<void> {
    return this.calls.decline(user.id, dto.channelId);
  }
}

/**
 * Decides who may join a channel's call, and hands out ICE servers.
 *
 * That is the whole of it. There is no room to create, no token to sign and no
 * media server address to advertise, because media goes directly between the
 * participants - see `call.gateway.ts` for the introduction and `ice.ts` for
 * how a path between them is found.
 *
 * The permission check lives here as well as in the gateway on purpose: the
 * client asks for ICE servers before it opens the signalling socket, so a
 * member who may not start a call finds out from a 403 rather than from a
 * socket that connects and then refuses.
 */
import { ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
import { iceServers } from '@betweenus/config';
import { Prisma, prisma, resolveChannelAccess } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { PERMISSIONS } from '@betweenus/permissions';
import type {
  CallAnalytics,
  CallHistoryEntry,
  CallIceResponse,
  CallLinkReport,
  CallUsageTotals,
} from '@betweenus/shared-types';
import { ringIsAllowed, ringKey } from './ring-cooldown';
import { clampReportedBytes, clampReportedLinks } from './usage';

/** How far back a person's own call log goes when they open it. */
const HISTORY_LIMIT = 50;

@Injectable()
export class CallsService {
  constructor(private readonly events: EventBus) {}

  /**
   * When each pair last rang.
   *
   * ponytail: in memory, so two instances of this service would each allow one
   * ring per window. One instance is what the compose file runs - the same
   * assumption `push.service.ts` makes about its roster cache. Move both to
   * Redis together if there is ever a second.
   */
  private readonly lastRing = new Map<string, number>();

  async ice(userId: string, channelId: string): Promise<CallIceResponse> {
    await this.requireChannelAccess(userId, channelId);
    return { iceServers: await iceServers() };
  }

  /**
   * Rings one person into a call in a channel both of them can see.
   *
   * Three questions, and they are separate: may the caller start a call here,
   * may the person being rung be in this conversation at all, and have they
   * been rung too recently. The middle one is the one worth being careful
   * about - without it this endpoint is a way to make an arbitrary account's
   * phone ring by naming a channel they have never heard of.
   *
   * It does not require the caller to already be in the call. Ringing somebody
   * and then joining is a normal order to do it in, and refusing it would only
   * mean the client had to join first - which is a rule with no one behind it.
   */
  async ring(callerId: string, channelId: string, targetId: string): Promise<void> {
    if (callerId === targetId) {
      throw new ForbiddenException({
        code: 'CANNOT_RING_SELF',
        message: 'You cannot ring yourself',
      });
    }

    // The caller's access first, so somebody probing for channels they cannot
    // see gets the same 404 they would get from anything else.
    await this.requireChannelAccess(callerId, channelId);

    // And the recipient's, which is what stops this being a way to ring any
    // account in the deployment. `VIEW_CHANNEL` rather than `START_CALL`:
    // being able to hear the conversation is what makes an invitation into it
    // meaningful, and somebody who may not start a call may certainly be
    // invited to one.
    const target = await resolveChannelAccess(targetId, channelId);
    if (!target?.permissions.includes(PERMISSIONS.VIEW_CHANNEL)) {
      throw new ForbiddenException({
        code: 'CANNOT_RING_USER',
        message: 'They are not in this channel',
      });
    }

    const key = ringKey(callerId, targetId);
    const now = Date.now();
    if (!ringIsAllowed(this.lastRing.get(key), now)) {
      throw new ForbiddenException({
        code: 'RING_TOO_SOON',
        message: 'You just rang them. Give them a moment.',
      });
    }
    this.lastRing.set(key, now);

    const [channel, caller] = await Promise.all([
      prisma.channel.findUnique({ where: { id: channelId }, select: { name: true } }),
      prisma.user.findUnique({
        where: { id: callerId },
        select: { username: true, displayName: true, avatarUrl: true },
      }),
    ]);
    if (!channel || !caller) {
      throw new NotFoundException({ code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
    }

    // Everything a subscriber could need is on the event, so neither the push
    // fan-out nor the presence gateway reads a table this service owns.
    await this.events.publish(EVENTS.CALL_RING, {
      channelId,
      channelName: channel.name,
      callerId,
      callerName: caller.displayName || caller.username,
      ...(caller.avatarUrl ? { callerAvatarUrl: caller.avatarUrl } : {}),
      targetId,
    });
  }

  /**
   * "I have said no to that, here."
   *
   * Fans back to the account that declined and to nobody else, which is the
   * whole job: a ring is aimed at an account and lands on every device it
   * owns, so saying no on one of them used to leave the rest ringing until
   * they timed out. Answering at least showed up in `call.roster`; declining
   * left no trace anywhere, which is why it needed an endpoint of its own.
   *
   * Deliberately silent towards whoever rang. A ring is not a handshake - it
   * rings out for them either way - and telling the caller would be a new
   * feature rather than this one.
   *
   * Access is checked for the same reason the ring endpoint checks it: an
   * endpoint that takes any channel id from anyone is a way to probe which
   * ones exist. Nothing else here can fail. Declining a call that has already
   * ended, or one that never rang this account, is a no-op rather than an
   * error - the client is saying what it did, not asking permission, and there
   * is no state to be wrong about.
   */
  async decline(userId: string, channelId: string): Promise<void> {
    await this.requireChannelAccess(userId, channelId);
    await this.events.publish(EVENTS.CALL_DECLINED, { channelId, userId });
  }

  /**
   * Opens a row for one person's stay in one call.
   *
   * Called by the gateway once a join has been allowed, because the gateway is
   * the only thing that knows the join happened. The channel and server names
   * are copied in here: the log is read months later, and a join is the last
   * moment they are certainly still there to read.
   *
   * Returns null rather than throwing when the write fails. A call whose
   * history could not be opened is still a call, and taking it down over a
   * bookkeeping row would be the wrong trade every time.
   */
  async startSession(userId: string, channelId: string): Promise<string | null> {
    const channel = await prisma.channel
      .findUnique({
        where: { id: channelId },
        select: { name: true, serverId: true, server: { select: { name: true } } },
      })
      .catch(() => null);
    if (!channel) return null;

    const session = await prisma.callSession
      .create({
        data: {
          userId,
          channelId,
          channelName: channel.name,
          serverId: channel.serverId,
          serverName: channel.server?.name ?? null,
        },
        select: { id: true },
      })
      .catch(() => null);

    return session?.id ?? null;
  }

  /**
   * Closes it: when they left, who they were in it with, and what their machine
   * moved.
   *
   * `bytes` is the client's own count and nothing here can check it - the
   * service is not in the media path - so it is clamped rather than trusted.
   */
  async endSession(sessionId: string, peerIds: string[], usage: ReportedUsage): Promise<void> {
    const links = clampReportedLinks(usage.links);
    const sent = clampReportedBytes(usage.bytesSent);
    const received = clampReportedBytes(usage.bytesReceived);

    await prisma.callSession
      .update({
        where: { id: sessionId },
        data: {
          endedAt: new Date(),
          peerIds,
          // The total is still the total the client reported, not the sum of
          // the halves: a client that reports one and not the other should read
          // back as the number it actually gave rather than as a repair.
          bytes: BigInt(clampReportedBytes(usage.bytes)),
          bytesSent: BigInt(sent),
          bytesReceived: BigInt(received),
          // Prisma's JSON input type does not accept a typed array as itself.
          links: links as unknown as Prisma.InputJsonValue,
        },
      })
      .catch(() => undefined);
  }

  /**
   * One person's own call log, newest first.
   *
   * Only their own: there is no parameter for whose log to read, because a
   * "whose" is the only thing that could ever be wrong here.
   */
  async history(userId: string): Promise<CallHistoryEntry[]> {
    const sessions = await prisma.callSession.findMany({
      where: { userId },
      orderBy: { joinedAt: 'desc' },
      take: HISTORY_LIMIT,
    });

    // One lookup for every name on the page rather than one per row, and by
    // current name rather than a snapshot: somebody who renamed themselves
    // reads back as who they are now, which is who the reader is looking for.
    const peerIds = [...new Set(sessions.flatMap((session) => session.peerIds))];
    const people = peerIds.length
      ? await prisma.user.findMany({
          where: { id: { in: peerIds } },
          select: { id: true, username: true, displayName: true },
        })
      : [];
    const byId = new Map(people.map((person) => [person.id, person]));

    return sessions.map((session) => ({
      id: session.id,
      channelId: session.channelId,
      channelName: session.channelName,
      serverId: session.serverId,
      serverName: session.serverName,
      joinedAt: session.joinedAt.toISOString(),
      endedAt: session.endedAt?.toISOString() ?? null,
      durationSeconds: session.endedAt
        ? Math.max(0, Math.round((session.endedAt.getTime() - session.joinedAt.getTime()) / 1000))
        : null,
      // A peer whose account is gone is dropped rather than drawn as an id.
      peers: session.peerIds.flatMap((id) => {
        const person = byId.get(id);
        return person ? [person] : [];
      }),
      bytes: Number(session.bytes),
      bytesSent: Number(session.bytesSent),
      bytesReceived: Number(session.bytesReceived),
      links: readLinks(session.links),
    }));
  }

  /**
   * The same rows, added up: what calls have cost this account lately.
   *
   * Read from `call_sessions` rather than from a counter kept somewhere else,
   * so the totals and the log can never disagree - there is one set of rows and
   * two readings of it. The window is bounded and the rows are one person's, so
   * this is a small scan rather than the aggregate query it looks like.
   *
   * ponytail: added up in this process. A month of one account's calls is
   * hundreds of rows; `groupBy` in SQL is the fix if it is ever thousands, and
   * the shape of what comes back does not change when it is.
   */
  async analytics(userId: string, days: number): Promise<CallAnalytics> {
    const window = Math.min(Math.max(Math.round(days) || DEFAULT_ANALYTICS_DAYS, 1), MAX_ANALYTICS_DAYS);
    const since = startOfDay(new Date());
    since.setDate(since.getDate() - (window - 1));

    const sessions = await prisma.callSession.findMany({
      where: { userId, joinedAt: { gte: since } },
      orderBy: { joinedAt: 'asc' },
    });

    // Every day in the window, including the empty ones. A chart drawn from a
    // series with holes in it either invents the missing days or draws a week
    // as five points, and both are wrong in a way nobody reading it can see.
    const daily = new Map<string, CallUsageTotals>();
    for (let day = 0; day < window; day += 1) {
      const at = new Date(since);
      at.setDate(at.getDate() + day);
      daily.set(dayKey(at), emptyTotals());
    }

    const totals = emptyTotals();
    const channels = new Map<string, { channelId: string; channelName: string; serverName: string | null } & CallUsageTotals>();
    const peerSeconds = new Map<string, { calls: number; seconds: number }>();
    const transport = { direct: 0, relay: 0, unknown: 0 };

    for (const session of sessions) {
      const seconds = session.endedAt
        ? Math.max(0, Math.round((session.endedAt.getTime() - session.joinedAt.getTime()) / 1000))
        : 0;
      const sent = Number(session.bytesSent);
      const received = Number(session.bytesReceived);

      add(totals, seconds, sent, received);
      const day = daily.get(dayKey(session.joinedAt));
      if (day) add(day, seconds, sent, received);

      const channel = channels.get(session.channelId) ?? {
        channelId: session.channelId,
        channelName: session.channelName,
        serverName: session.serverName,
        ...emptyTotals(),
      };
      add(channel, seconds, sent, received);
      channels.set(session.channelId, channel);

      for (const peerId of new Set(session.peerIds)) {
        const peer = peerSeconds.get(peerId) ?? { calls: 0, seconds: 0 };
        peer.calls += 1;
        peer.seconds += seconds;
        peerSeconds.set(peerId, peer);
      }

      for (const link of readLinks(session.links)) {
        if (link.transport === 'direct') transport.direct += 1;
        else if (link.transport === 'relay') transport.relay += 1;
        else transport.unknown += 1;
      }
    }

    const people = peerSeconds.size
      ? await prisma.user.findMany({
          where: { id: { in: [...peerSeconds.keys()] } },
          select: { id: true, username: true, displayName: true },
        })
      : [];

    return {
      days: window,
      totals,
      daily: [...daily.entries()].map(([date, entry]) => ({ date, ...entry })),
      channels: [...channels.values()].sort((a, b) => b.seconds - a.seconds).slice(0, TOP_N),
      peers: people
        .map((person) => ({ ...person, ...(peerSeconds.get(person.id) ?? { calls: 0, seconds: 0 }) }))
        .sort((a, b) => b.seconds - a.seconds)
        .slice(0, TOP_N),
      transport,
    };
  }

  /**
   * The same resolver chat- and presence-service use, so a private channel or a
   * revoked permission takes effect here at the same moment it does there.
   */
  private async requireChannelAccess(userId: string, channelId: string): Promise<void> {
    const access = await resolveChannelAccess(userId, channelId);
    if (!access) {
      // 404, not 403: a non-member must not learn the channel exists.
      throw new NotFoundException({ code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
    }

    if (!access.permissions.includes(PERMISSIONS.START_CALL)) {
      throw new ForbiddenException({
        code: 'MISSING_PERMISSION',
        message: `Missing permission ${PERMISSIONS.START_CALL}`,
      });
    }
  }
}

/** What a client says one stay in a call moved. Nothing here is checkable. */
export interface ReportedUsage {
  bytes: number;
  bytesSent: number;
  bytesReceived: number;
  links: unknown;
}

/** How far back the analytics page looks when nothing says otherwise. */
const DEFAULT_ANALYTICS_DAYS = 30;
/** And the furthest it will, so one request cannot ask for every row ever. */
const MAX_ANALYTICS_DAYS = 365;
/** How many channels and people the page names before it stops being a list. */
const TOP_N = 5;

/**
 * The per-link detail back out of the JSON column.
 *
 * Clamped again on the way out rather than trusted because it was clamped on
 * the way in: the rows outlive the code that wrote them, and a shape this
 * version never wrote is exactly what an older one might have.
 */
function readLinks(value: unknown): CallLinkReport[] {
  return clampReportedLinks(value);
}

function emptyTotals(): CallUsageTotals {
  return { calls: 0, seconds: 0, bytesSent: 0, bytesReceived: 0 };
}

function add(totals: CallUsageTotals, seconds: number, sent: number, received: number): void {
  totals.calls += 1;
  totals.seconds += seconds;
  totals.bytesSent += sent;
  totals.bytesReceived += received;
}

/** Local date, because a day is what somebody reading a chart means by one. */
function dayKey(at: Date): string {
  const local = new Date(at.getTime() - at.getTimezoneOffset() * 60_000);
  return local.toISOString().slice(0, 10);
}

function startOfDay(at: Date): Date {
  const day = new Date(at);
  day.setHours(0, 0, 0, 0);
  return day;
}

import { IsUUID } from 'class-validator';
import type {
  CallDeclineRequest,
  CallIceRequest,
  CallRingRequest,
} from '@betweenus/shared-types';

export class CallIceDto implements CallIceRequest {
  @IsUUID()
  channelId!: string;
}

export class CallRingDto implements CallRingRequest {
  @IsUUID()
  channelId!: string;

  /** Who to ring. Whether they may be rung is the service's question, not this one's. */
  @IsUUID()
  userId!: string;
}

/**
 * Who declined is the authenticated user, so there is nothing here but the
 * channel. A decline that could name its own sender would be a way to silence
 * somebody else's phone.
 */
export class CallDeclineDto implements CallDeclineRequest {
  @IsUUID()
  channelId!: string;
}

/**
 * "Is the relay this deployment hands out actually working?"
 *
 * Answered here, in `call-service`, because this is the service that answers
 * `POST /api/v1/calls/ice`. The admin panel could read `TURN_URLS` itself and
 * probe from there, and it deliberately does not: a second reader of the same
 * setting can disagree with the first, and a panel showing a healthy relay
 * while clients are handed a different one is worse than no panel. This asks
 * the exact list `iceServers()` would give a client, so what is drawn is what
 * is served.
 *
 * The probe itself is a real TURN allocation - see `turn-probe.ts` for why
 * nothing weaker is worth showing an operator.
 */
import { Injectable } from '@nestjs/common';
import { iceServers } from '@betweenus/config';
import type { AdminRelayHealth, RelayProbeResult } from '@betweenus/shared-types';
import { probeRelay } from './turn-probe';

/**
 * How long one relay gets to answer.
 *
 * Two round trips over UDP to a VM that is usually in another country. Generous
 * enough that a slow path is reported as slow rather than as down, short enough
 * that a health page with a dead relay still draws promptly.
 */
const PROBE_TIMEOUT_MS = 2_000;

@Injectable()
export class RelayHealthService {
  async snapshot(): Promise<AdminRelayHealth> {
    // The same call a joining client makes, so this cannot drift from it.
    const servers = await iceServers();
    const relays = servers.filter((server) =>
      server.urls.some((url) => url.startsWith('turn:') || url.startsWith('turns:')),
    );

    if (relays.length === 0) {
      return { configured: false, username: null, probes: [], state: 'up', error: null };
    }

    // One entry carries every relay URL and one credential pair, which is the
    // shape `ice.ts` builds. Flattened here so each URL gets its own card.
    const probes: RelayProbeResult[] = (
      await Promise.all(
        relays.flatMap((relay) =>
          relay.urls.map((url) =>
            probeRelay(url, relay.username ?? '', relay.credential ?? '', PROBE_TIMEOUT_MS),
          ),
        ),
      )
    ).flat();

    return {
      configured: true,
      username: relays[0]?.username ?? null,
      probes,
      // A relay that could not be probed at all (TLS, TCP) is not a failure;
      // one that refused or never answered is.
      state: probes.some((probe) => probe.state === 'down' || probe.state === 'invalid')
        ? 'down'
        : 'up',
      error: null,
    };
  }
}

/**
 * The relay's state, for the admin panel.
 *
 * Not routed by the gateway. Nginx forwards the paths it names and
 * `/api/v1/internal` is not one of them, so this is reachable on the internal
 * Docker network and nowhere else - the same arrangement, and the same
 * reasoning, as `internal/presence` in presence-service. That is also why there
 * is no guard: there is no user here, only `auth-service` assembling a health
 * page.
 *
 * Nothing here returns `TURN_CREDENTIAL`. The username is shown because an
 * operator comparing the panel against `turnserver.conf` needs it; the secret
 * beside it is exactly what an admin API should never hand back, and the panel
 * has no use for it.
 */
import { Controller, Get } from '@nestjs/common';
import type { AdminRelayHealth } from '@betweenus/shared-types';
import { RelayHealthService } from './relay-health.service';

@Controller('internal/relay')
export class RelayController {
  constructor(private readonly relay: RelayHealthService) {}

  @Get()
  status(): Promise<AdminRelayHealth> {
    return this.relay.snapshot();
  }
}

/**
 * Self-check for the ring cooldown.
 *
 * Both directions are silent failures. Too permissive and there is no brake on
 * the one push in this app that is allowed to wake a phone past its owner's
 * preferences; too strict and ringing somebody back after they missed the call
 * quietly does nothing, with no error anywhere to say why.
 *
 * Run with `pnpm --filter @betweenus/call-service check`.
 */
import assert from 'node:assert/strict';
import { RING_COOLDOWN_MS, ringIsAllowed, ringKey } from './ring-cooldown';

const now = 1_700_000_000_000;

// Never rung before is always allowed, or nobody could ever ring anybody.
assert.equal(ringIsAllowed(undefined, now), true);

// Twice in a row is the thing being stopped.
assert.equal(ringIsAllowed(now, now), false);
assert.equal(ringIsAllowed(now - 1, now), false);
assert.equal(ringIsAllowed(now - (RING_COOLDOWN_MS - 1), now), false);

// The boundary is allowed rather than refused: a cooldown that has elapsed has
// elapsed, and an off-by-one here is a ring that fails for no visible reason.
assert.equal(ringIsAllowed(now - RING_COOLDOWN_MS, now), true);
assert.equal(ringIsAllowed(now - RING_COOLDOWN_MS * 2, now), true);

// A clock that went backwards - an NTP correction between two rings - must not
// unlock the cooldown. `now - lastRingAt` is negative there, which is less than
// the window, which is refused.
assert.equal(ringIsAllowed(now + 60_000, now), false);

// Direction matters: A ringing B is not B ringing A, so a missed call can be
// returned immediately.
assert.notEqual(ringKey('ana', 'ben'), ringKey('ben', 'ana'));
assert.equal(ringKey('ana', 'ben'), ringKey('ana', 'ben'));

console.log('call-service ring cooldown self-check passed');

/**
 * How often one person may ring another.
 *
 * A ring is the loudest thing this app can do to somebody: it takes a phone
 * out of Doze, lights the screen over the lock and plays a ringtone. Every
 * other push obeys a mute the recipient set; this one is allowed past the
 * quiet ones on purpose, because it was aimed at them by a person.
 *
 * So the recipient's preferences cannot be the only brake, and the brake here
 * is the simplest one that works: the same pair cannot ring again until the
 * ring they already sent has stopped mattering. Declining is honoured on the
 * client - a declined channel stays quiet until the call ends - and this is
 * what stops somebody simply pressing the button forty times.
 *
 * Pure, and tested, because a cooldown that is wrong in either direction is
 * invisible: too short and it is not a cooldown, too long and calling somebody
 * back after they hung up silently does nothing.
 */

/**
 * Seconds. Long enough that pressing the button again is a decision rather
 * than a reflex, short enough that ringing back after a missed call works.
 */
export const RING_COOLDOWN_MS = 30_000;

/** The key a pair of people share. Direction matters: a ring back is not a repeat. */
export function ringKey(callerId: string, targetId: string): string {
  return `${callerId}>${targetId}`;
}

/**
 * Whether this ring may go, given when the last one did.
 *
 * `undefined` is "never rung", which is always allowed. `now` is passed in so
 * the decision is a function of its inputs rather than of the clock.
 */
export function ringIsAllowed(lastRingAt: number | undefined, now: number): boolean {
  if (lastRingAt === undefined) return true;
  return now - lastRingAt >= RING_COOLDOWN_MS;
}

/**
 * That the STUN wire format written by hand in `turn-probe.ts` is the one on
 * the wire.
 *
 * Every assertion here is a mistake that produces the *same* symptom in
 * production - a relay answering `401` to a credential that is perfectly
 * correct - and none of them can be told apart by looking at the failure. That
 * is the whole reason this file exists: the protocol has no useful error
 * reporting, so the encoding has to be checked against the specification rather
 * than against a running relay.
 *
 * The one worth naming: `MESSAGE-INTEGRITY` is computed over a header whose
 * declared length already includes the 24 bytes of the attribute that has not
 * been appended yet (RFC 5389 §15.4). Get it wrong and every allocation is
 * refused, with an error that points at the credential instead of the code.
 *
 * Nothing here opens a socket. `probeRelay` needs a relay and belongs in
 * TESTING.md; these are the pure parts, which are the parts that are wrong.
 *
 * Run with: pnpm --filter @betweenus/call-service check
 */
import assert from 'node:assert/strict';
import { createHash, createHmac } from 'node:crypto';
import {
  decodeErrorCode,
  decodeXorAddress,
  encodeAttribute,
  encodeMessage,
  encodeSigned,
  longTermKey,
  parseMessage,
  parseTurnUrl,
} from './turn-probe';

const MAGIC_COOKIE = 0x2112a442;

function attributesArePaddedButNotOverDeclared(): void {
  // Three bytes of value: one byte of padding, and a declared length that still
  // says three. A parser that read the padded length would find an attribute
  // boundary one byte late for the rest of the message.
  const attribute = encodeAttribute(0x0006, Buffer.from('abc', 'utf8'));
  assert.equal(attribute.length, 8, 'padded to a four-byte boundary');
  assert.equal(attribute.readUInt16BE(2), 3, 'but the declared length excludes the padding');
  assert.equal(attribute.subarray(4, 7).toString('utf8'), 'abc');
  assert.equal(attribute.readUInt8(7), 0, 'padding is zero');

  const exact = encodeAttribute(0x0006, Buffer.from('abcd', 'utf8'));
  assert.equal(exact.length, 8, 'a value already on the boundary gains nothing');
}

function aMessageSurvivesARoundTrip(): void {
  const txid = Buffer.from('0123456789ab', 'utf8');
  const message = encodeMessage(0x0003, txid, [
    encodeAttribute(0x0019, Buffer.from([17, 0, 0, 0])),
    encodeAttribute(0x0006, Buffer.from('betweenus', 'utf8')),
  ]);

  assert.equal(message.readUInt32BE(4), MAGIC_COOKIE, 'the cookie is what marks it as STUN');
  assert.equal(message.readUInt16BE(2), message.length - 20, 'length counts the body only');

  const parsed = parseMessage(message);
  assert.ok(parsed, 'it parses back');
  assert.equal(parsed?.type, 0x0003);
  assert.ok(parsed?.txid.equals(txid), 'the transaction id survives, which is how a reply is matched');
  assert.equal(
    parsed?.attributes.get(0x0006)?.toString('utf8'),
    'betweenus',
    'and a padded attribute reads back without its padding',
  );
  assert.equal(parsed?.attributes.get(0x0019)?.readUInt8(0), 17, 'UDP');
}

function rubbishIsRejectedRatherThanGuessedAt(): void {
  assert.equal(parseMessage(Buffer.alloc(4)), null, 'too short to be a header');
  assert.equal(parseMessage(Buffer.alloc(20)), null, 'no magic cookie is not a STUN message');

  // A length field claiming more body than the datagram holds: a truncated or
  // hostile packet, and reading it would walk off the end of the buffer.
  const lying = encodeMessage(0x0003, Buffer.alloc(12), []);
  lying.writeUInt16BE(400, 2);
  assert.equal(parseMessage(lying), null, 'a length longer than the packet is refused');
}

/**
 * The signature the relay will recompute.
 *
 * Written out independently here rather than by calling the same helper: a
 * check that reuses the implementation's own arithmetic agrees with it whether
 * or not either is right.
 */
function integrityIsSignedOverTheLengthItWillHave(): void {
  const txid = Buffer.alloc(12, 7);
  const key = longTermKey('betweenus', 'example.org', 'secret');
  assert.deepEqual(
    key,
    createHash('md5').update('betweenus:example.org:secret').digest(),
    'MD5(username:realm:password), per RFC 5389 §15.4',
  );

  const attributes = [encodeAttribute(0x0019, Buffer.from([17, 0, 0, 0]))];
  const signed = encodeSigned(0x0003, txid, attributes, key);

  const integrity = signed.subarray(signed.length - 20);
  assert.equal(signed.readUInt16BE(signed.length - 24), 0x0008, 'MESSAGE-INTEGRITY is last');
  assert.equal(
    signed.readUInt16BE(2),
    signed.length - 20,
    'the declared length counts the integrity attribute',
  );

  // Recompute the way a relay does: everything before the attribute, with the
  // header length already counting it.
  const covered = signed.subarray(0, signed.length - 24);
  const expected = createHmac('sha1', key).update(covered).digest();
  assert.deepEqual(integrity, expected, 'the HMAC covers the message as the relay will read it');

  // And the failure this is really guarding: signing the shorter length.
  const naive = encodeMessage(0x0003, txid, attributes);
  const wrong = createHmac('sha1', key).update(naive).digest();
  assert.notDeepEqual(integrity, wrong, 'signing the pre-append length is the classic bug');
}

/** RFC 5389 §15.2's own worked example, which is why these constants look odd. */
function xorAddressesAreUnmasked(): void {
  const txid = Buffer.from('0123456789ab', 'utf8');

  // 192.0.2.1:32853 masked with the cookie.
  const value = Buffer.alloc(8);
  value.writeUInt8(0, 0);
  value.writeUInt8(0x01, 1);
  value.writeUInt16BE(32853 ^ (MAGIC_COOKIE >>> 16), 2);
  const cookie = Buffer.alloc(4);
  cookie.writeUInt32BE(MAGIC_COOKIE, 0);
  for (const [index, octet] of [192, 0, 2, 1].entries()) {
    value.writeUInt8(octet ^ (cookie[index] as number), 4 + index);
  }

  assert.equal(decodeXorAddress(value, txid), '192.0.2.1:32853');
  assert.equal(decodeXorAddress(Buffer.alloc(4), txid), null, 'a truncated address is not guessed');
}

function errorCodesReadAsNumbers(): void {
  // Class 4, number 01, with a reason - the refusal that carries the realm.
  const value = Buffer.concat([
    Buffer.from([0, 0, 4, 1]),
    Buffer.from('Unauthorized', 'utf8'),
  ]);
  assert.deepEqual(decodeErrorCode(value), { code: 401, reason: 'Unauthorized' });

  const forbidden = Buffer.concat([Buffer.from([0, 0, 4, 3]), Buffer.from('Forbidden', 'utf8')]);
  assert.equal(decodeErrorCode(forbidden).code, 403);
  assert.equal(decodeErrorCode(Buffer.alloc(2)).code, 0, 'a truncated code is 0, not a crash');
}

/**
 * URL parsing, including the defaults nobody remembers.
 *
 * `new URL` is not usable here: it refuses `turn:` outright, so the alternative
 * to this regex is not the platform parser, it is being wrong about ports.
 */
function turnUrlsAreReadTheWayRfc7065Says(): void {
  assert.deepEqual(parseTurnUrl('turn:203.0.113.10:3478'), {
    scheme: 'turn',
    host: '203.0.113.10',
    port: 3478,
    transport: 'udp',
  });

  assert.deepEqual(
    parseTurnUrl('turn:relay.example.com'),
    { scheme: 'turn', host: 'relay.example.com', port: 3478, transport: 'udp' },
    'turn: defaults to 3478 over UDP',
  );

  assert.deepEqual(
    parseTurnUrl('turns:relay.example.com'),
    { scheme: 'turns', host: 'relay.example.com', port: 5349, transport: 'tcp' },
    'turns: defaults to 5349 over TCP - a different port, not just a different scheme',
  );

  assert.equal(
    parseTurnUrl('turns:relay.example.com:443?transport=tcp')?.port,
    443,
    'an explicit port wins over the default',
  );

  assert.equal(
    parseTurnUrl('turn:relay.example.com:3478?transport=tcp')?.transport,
    'tcp',
    'and an explicit transport wins over the scheme default',
  );

  assert.equal(parseTurnUrl('stun:stun.example.com:3478'), null, 'STUN is not a relay');
  assert.equal(parseTurnUrl('https://relay.example.com'), null);
  assert.equal(parseTurnUrl('turn:relay.example.com:0'), null, 'port 0 is not a port');
  assert.equal(parseTurnUrl('turn:relay.example.com:70000'), null, 'nor is one past 65535');
}

function main(): void {
  attributesArePaddedButNotOverDeclared();
  aMessageSurvivesARoundTrip();
  rubbishIsRejectedRatherThanGuessedAt();
  integrityIsSignedOverTheLengthItWillHave();
  xorAddressesAreUnmasked();
  errorCodesReadAsNumbers();
  turnUrlsAreReadTheWayRfc7065Says();
  console.log('turn-probe self-check passed');
}

main();

/**
 * Asking a TURN relay, in its own protocol, whether it actually works.
 *
 * "Is the relay up" cannot be answered by pinging it, by opening a TCP socket
 * to it, or by reading the configuration. A relay can be reachable and still
 * refuse every allocation because the credential is wrong; it can accept
 * allocations and still be useless because a firewall drops the relayed port
 * range. The only answer worth showing an operator is the one the client will
 * get: **ask for an allocation with the credential the deployment hands out,
 * and see whether a relayed address comes back.**
 *
 * That is what this does. It is STUN/TURN (RFC 5389, RFC 8656) over UDP, in
 * about two hundred lines, with `node:dgram` and `node:crypto` and no
 * dependency - the wire format is small and a library for it would be a
 * dependency carried for one diagnostic.
 *
 * The exchange is the standard long-term credential dance:
 *
 * 1. `Allocate` with no credential. The relay is *expected* to refuse with
 *    `401`, and that refusal is where its `REALM` and `NONCE` come from. A
 *    relay that answers anything else here is misconfigured, and saying so is
 *    more useful than retrying.
 * 2. `Allocate` again, signed: `MESSAGE-INTEGRITY` is HMAC-SHA1 over the
 *    message under a key of `MD5(username:realm:password)`.
 * 3. Success carries `XOR-RELAYED-ADDRESS` - the address the relay would
 *    forward this call's media through. That address existing is the proof.
 * 4. `Refresh` with `LIFETIME=0`, to give the allocation straight back.
 *
 * **Step 4 is not politeness, it is required.** A relay is configured with
 * `user-quota` and `total-quota` precisely so a leaked credential cannot cost
 * unbounded bandwidth, and every client shares one username here, so the quota
 * is deployment-wide. A health page that allocated on every refresh and walked
 * away would exhaust that quota by itself and take real calls down - the
 * monitoring causing the outage it is watching for.
 *
 * MD5 and HMAC-SHA1 are not choices made here. RFC 5389 §15.4 specifies both
 * for long-term credentials, and a relay will reject anything else.
 *
 * Only `turn:` over UDP is probed. `turns:` and `?transport=tcp` are reported
 * as configured but unprobed rather than guessed at: they need a TLS handshake
 * and a framed TCP transport, which is a second implementation of all of this
 * for a listener most deployments do not have. An honest "not checked" beats a
 * green tick that means nothing.
 */
import { createHash, createHmac, randomBytes } from 'node:crypto';
import { createSocket } from 'node:dgram';
import type { RelayProbeResult } from '@betweenus/shared-types';

/** RFC 5389 §6. Present in every message, and how a reply is recognised. */
const MAGIC_COOKIE = 0x2112a442;

const METHOD_ALLOCATE = 0x0003;
const METHOD_REFRESH = 0x0004;
const CLASS_REQUEST = 0x0000;
const CLASS_SUCCESS = 0x0100;
const CLASS_ERROR = 0x0110;

const ATTR_USERNAME = 0x0006;
const ATTR_MESSAGE_INTEGRITY = 0x0008;
const ATTR_ERROR_CODE = 0x0009;
const ATTR_REALM = 0x0014;
const ATTR_NONCE = 0x0015;
const ATTR_XOR_RELAYED_ADDRESS = 0x0016;
const ATTR_REQUESTED_TRANSPORT = 0x0019;
const ATTR_XOR_MAPPED_ADDRESS = 0x0020;
const ATTR_LIFETIME = 0x000d;

/** RFC 8656: the transport the relayed traffic will use. 17 is UDP. */
const TRANSPORT_UDP = 17;

interface StunMessage {
  type: number;
  txid: Buffer;
  attributes: Map<number, Buffer>;
}

/** One attribute, padded to a four-byte boundary as the RFC requires. */
function encodeAttribute(type: number, value: Buffer): Buffer {
  const padding = (4 - (value.length % 4)) % 4;
  const out = Buffer.alloc(4 + value.length + padding);
  out.writeUInt16BE(type, 0);
  // The declared length excludes the padding, which is why it is not out.length.
  out.writeUInt16BE(value.length, 2);
  value.copy(out, 4);
  return out;
}

function encodeMessage(type: number, txid: Buffer, attributes: Buffer[]): Buffer {
  const body = Buffer.concat(attributes);
  const out = Buffer.alloc(20 + body.length);
  out.writeUInt16BE(type, 0);
  out.writeUInt16BE(body.length, 2);
  out.writeUInt32BE(MAGIC_COOKIE, 4);
  txid.copy(out, 8);
  body.copy(out, 20);
  return out;
}

/**
 * The same message, signed.
 *
 * The subtlety that makes every hand-rolled STUN client fail once: the HMAC is
 * computed over a header whose declared length **already counts the
 * MESSAGE-INTEGRITY attribute that is not appended yet** (RFC 5389 §15.4).
 * Signing the message as it stands and then appending produces a signature the
 * relay computes differently and rejects, with an error that says only "401".
 */
function encodeSigned(
  type: number,
  txid: Buffer,
  attributes: Buffer[],
  key: Buffer,
): Buffer {
  const unsigned = encodeMessage(type, txid, attributes);
  // 4 bytes of attribute header + 20 bytes of HMAC-SHA1.
  unsigned.writeUInt16BE(unsigned.length - 20 + 24, 2);
  const mac = createHmac('sha1', key).update(unsigned).digest();
  return Buffer.concat([unsigned, encodeAttribute(ATTR_MESSAGE_INTEGRITY, mac)]);
}

/** `MD5(username:realm:password)` - RFC 5389 §15.4, not a preference. */
function longTermKey(username: string, realm: string, password: string): Buffer {
  return createHash('md5').update(`${username}:${realm}:${password}`).digest();
}

export function parseMessage(buffer: Buffer): StunMessage | null {
  if (buffer.length < 20) return null;
  if (buffer.readUInt32BE(4) !== MAGIC_COOKIE) return null;

  const length = buffer.readUInt16BE(2);
  if (buffer.length < 20 + length) return null;

  const attributes = new Map<number, Buffer>();
  let offset = 20;
  const end = 20 + length;
  while (offset + 4 <= end) {
    const type = buffer.readUInt16BE(offset);
    const size = buffer.readUInt16BE(offset + 2);
    const from = offset + 4;
    if (from + size > end) break;
    // First wins: a duplicated attribute is malformed, and the first is the
    // one every other implementation reads.
    if (!attributes.has(type)) attributes.set(type, buffer.subarray(from, from + size));
    offset = from + size + ((4 - (size % 4)) % 4);
  }

  return { type: buffer.readUInt16BE(0), txid: buffer.subarray(8, 20), attributes };
}

/**
 * `XOR-MAPPED-ADDRESS` and friends, decoded.
 *
 * The XOR exists because middleboxes used to rewrite anything that looked like
 * an IP address in a packet body, including the one STUN was reporting back.
 */
export function decodeXorAddress(value: Buffer, txid: Buffer): string | null {
  if (value.length < 8) return null;
  const family = value.readUInt8(1);
  const port = value.readUInt16BE(2) ^ (MAGIC_COOKIE >>> 16);

  if (family === 0x01) {
    const raw = value.subarray(4, 8);
    const cookie = Buffer.alloc(4);
    cookie.writeUInt32BE(MAGIC_COOKIE, 0);
    const octets = Array.from(raw, (byte, index) => byte ^ (cookie[index] as number));
    return `${octets.join('.')}:${port}`;
  }

  if (family === 0x02) {
    if (value.length < 20) return null;
    const mask = Buffer.concat([Buffer.alloc(4), txid]);
    mask.writeUInt32BE(MAGIC_COOKIE, 0);
    const raw = value.subarray(4, 20);
    const parts: string[] = [];
    for (let index = 0; index < 16; index += 2) {
      const high = (raw[index] as number) ^ (mask[index] as number);
      const low = (raw[index + 1] as number) ^ (mask[index + 1] as number);
      parts.push(((high << 8) | low).toString(16));
    }
    return `[${parts.join(':')}]:${port}`;
  }

  return null;
}

export function decodeErrorCode(value: Buffer): { code: number; reason: string } {
  if (value.length < 4) return { code: 0, reason: '' };
  // Two zero bytes, then a class digit, then a number within the class.
  const code = (value.readUInt8(2) & 0x07) * 100 + value.readUInt8(3);
  return { code, reason: value.subarray(4).toString('utf8').slice(0, 120) };
}

/** What a `turn:`/`turns:` URL says, without the WHATWG parser, which refuses them. */
export function parseTurnUrl(
  url: string,
): { scheme: 'turn' | 'turns'; host: string; port: number; transport: 'udp' | 'tcp' } | null {
  const match = /^(turns?):(?:\/\/)?(\[[^\]]+\]|[^:?/]+)(?::(\d+))?(?:\?(.*))?$/i.exec(url.trim());
  if (!match) return null;

  const scheme = (match[1] as string).toLowerCase() as 'turn' | 'turns';
  const host = (match[2] as string).replace(/^\[|\]$/g, '');
  const query = match[4] ?? '';
  const named = /transport=(udp|tcp)/i.exec(query);

  // RFC 7065: turns: defaults to TCP, turn: to UDP, and either can say
  // otherwise. The default port differs too - 5349 for TLS.
  const transport = named
    ? ((named[1] as string).toLowerCase() as 'udp' | 'tcp')
    : scheme === 'turns'
      ? 'tcp'
      : 'udp';

  const port = match[3] ? Number(match[3]) : scheme === 'turns' ? 5349 : 3478;
  if (!Number.isInteger(port) || port < 1 || port > 65535) return null;

  return { scheme, host, port, transport };
}

/** Sends one datagram and waits for the reply carrying the same transaction id. */
function exchange(
  socket: ReturnType<typeof createSocket>,
  message: Buffer,
  host: string,
  port: number,
  txid: Buffer,
  timeoutMs: number,
): Promise<StunMessage> {
  return new Promise<StunMessage>((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error(`no answer within ${timeoutMs}ms`));
    }, timeoutMs);

    function cleanup(): void {
      clearTimeout(timer);
      socket.off('message', onMessage);
      socket.off('error', onError);
    }

    function onMessage(data: Buffer): void {
      const parsed = parseMessage(data);
      // Anything else on this socket belongs to a different exchange or is not
      // STUN at all; ignoring it rather than failing keeps a stray packet from
      // being reported as a broken relay.
      if (!parsed || !parsed.txid.equals(txid)) return;
      cleanup();
      resolve(parsed);
    }

    function onError(error: Error): void {
      cleanup();
      reject(error);
    }

    socket.on('message', onMessage);
    socket.on('error', onError);
    socket.send(message, port, host, (error) => {
      if (error) {
        cleanup();
        reject(error);
      }
    });
  });
}

/**
 * Allocates on the relay, reads the address back, and hands the allocation in.
 *
 * Never throws: every failure becomes a sentence on a card. An operator opening
 * a health page wants to know *which* thing is broken, and an exception here
 * would tell them only that something was.
 */
export async function probeRelay(
  url: string,
  username: string,
  credential: string,
  timeoutMs: number,
): Promise<RelayProbeResult> {
  const target = parseTurnUrl(url);
  if (!target) {
    return { url, state: 'invalid', latencyMs: null, relayedAddress: null, mappedAddress: null, error: 'Not a turn: or turns: URL this can read' };
  }

  if (target.transport !== 'udp' || target.scheme === 'turns') {
    return {
      url,
      state: 'unprobed',
      latencyMs: null,
      relayedAddress: null,
      mappedAddress: null,
      error: 'TLS and TCP listeners are not probed from here - verify with Trickle ICE',
    };
  }

  const socket = createSocket(target.host.includes(':') ? 'udp6' : 'udp4');
  const started = Date.now();

  try {
    // Round one: unauthenticated, purely to be refused and learn the realm.
    const firstId = randomBytes(12);
    const transport = Buffer.alloc(4);
    transport.writeUInt8(TRANSPORT_UDP, 0);
    const requestedTransport = encodeAttribute(ATTR_REQUESTED_TRANSPORT, transport);

    const challenge = await exchange(
      socket,
      encodeMessage(METHOD_ALLOCATE | CLASS_REQUEST, firstId, [requestedTransport]),
      target.host,
      target.port,
      firstId,
      timeoutMs,
    );

    const realm = challenge.attributes.get(ATTR_REALM);
    const nonce = challenge.attributes.get(ATTR_NONCE);
    if (!realm || !nonce) {
      const problem = challenge.attributes.get(ATTR_ERROR_CODE);
      const detail = problem ? decodeErrorCode(problem) : null;
      return {
        url,
        state: 'down',
        latencyMs: Date.now() - started,
        relayedAddress: null,
        mappedAddress: null,
        error: detail
          ? `Relay answered ${detail.code} ${detail.reason} instead of asking for credentials`
          : 'Relay did not ask for credentials, so it is not a TURN server or is misconfigured',
      };
    }

    // Round two: signed with the credential clients are actually given.
    const realmText = realm.toString('utf8');
    const key = longTermKey(username, realmText, credential);
    const secondId = randomBytes(12);
    const signed = encodeSigned(
      METHOD_ALLOCATE | CLASS_REQUEST,
      secondId,
      [
        requestedTransport,
        encodeAttribute(ATTR_USERNAME, Buffer.from(username, 'utf8')),
        encodeAttribute(ATTR_REALM, realm),
        encodeAttribute(ATTR_NONCE, nonce),
      ],
      key,
    );

    const answer = await exchange(socket, signed, target.host, target.port, secondId, timeoutMs);
    const latencyMs = Date.now() - started;

    if ((answer.type & CLASS_ERROR) === CLASS_ERROR) {
      const problem = answer.attributes.get(ATTR_ERROR_CODE);
      const detail = problem ? decodeErrorCode(problem) : { code: 0, reason: '' };
      return {
        url,
        state: 'down',
        latencyMs,
        relayedAddress: null,
        mappedAddress: null,
        error:
          detail.code === 401 || detail.code === 403
            ? `Relay refused the credential (${detail.code} ${detail.reason}). TURN_USERNAME or TURN_CREDENTIAL does not match the relay's own user= line`
            : `Relay refused the allocation: ${detail.code} ${detail.reason}`,
      };
    }

    const relayed = answer.attributes.get(ATTR_XOR_RELAYED_ADDRESS);
    const mapped = answer.attributes.get(ATTR_XOR_MAPPED_ADDRESS);
    const relayedAddress = relayed ? decodeXorAddress(relayed, secondId) : null;

    // Hand it straight back. See the note on quotas at the top of this file.
    await releaseAllocation(socket, target, username, realm, nonce, key, timeoutMs).catch(
      () => undefined,
    );

    if (!relayedAddress) {
      return {
        url,
        state: 'down',
        latencyMs,
        relayedAddress: null,
        mappedAddress: mapped ? decodeXorAddress(mapped, secondId) : null,
        error: 'Relay accepted the credential but returned no relayed address',
      };
    }

    return {
      url,
      state: 'up',
      latencyMs,
      relayedAddress,
      mappedAddress: mapped ? decodeXorAddress(mapped, secondId) : null,
      error: null,
    };
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error);
    return {
      url,
      state: 'down',
      latencyMs: null,
      relayedAddress: null,
      mappedAddress: null,
      error:
        text.includes('no answer')
          ? `${text} - the relay is unreachable from this service: firewall, security list, or coturn not running`
          : text.slice(0, 200),
    };
  } finally {
    socket.close();
  }
}

/** `Refresh` with a zero lifetime, which is TURN for "I am done with this". */
async function releaseAllocation(
  socket: ReturnType<typeof createSocket>,
  target: { host: string; port: number },
  username: string,
  realm: Buffer,
  nonce: Buffer,
  key: Buffer,
  timeoutMs: number,
): Promise<void> {
  const txid = randomBytes(12);
  const lifetime = Buffer.alloc(4);
  lifetime.writeUInt32BE(0, 0);

  await exchange(
    socket,
    encodeSigned(
      METHOD_REFRESH | CLASS_REQUEST,
      txid,
      [
        encodeAttribute(ATTR_LIFETIME, lifetime),
        encodeAttribute(ATTR_USERNAME, Buffer.from(username, 'utf8')),
        encodeAttribute(ATTR_REALM, realm),
        encodeAttribute(ATTR_NONCE, nonce),
      ],
      key,
    ),
    target.host,
    target.port,
    txid,
    timeoutMs,
  );
}

export { encodeAttribute, encodeMessage, encodeSigned, longTermKey, CLASS_SUCCESS };

/** `pnpm --filter @betweenus/call-service check` - the clamp on reported usage. */
import assert from 'node:assert/strict';
import { MAX_REPORTED_BYTES, clampReportedBytes, clampReportedLinks } from './usage';

assert.equal(clampReportedBytes(1024), 1024, 'an ordinary figure survives');
assert.equal(clampReportedBytes(0), 0);
assert.equal(clampReportedBytes(-5), 0, 'no call refunds data');
assert.equal(clampReportedBytes(Number.NaN), 0, 'nonsense reads as nothing');
assert.equal(clampReportedBytes(Number.POSITIVE_INFINITY), 0, 'infinity is nonsense, not a big number');
assert.equal(clampReportedBytes(MAX_REPORTED_BYTES * 10), MAX_REPORTED_BYTES);
assert.equal(clampReportedBytes(12.7), 12, 'whole bytes only');

assert.deepEqual(clampReportedLinks(undefined), [], 'a client that reports nothing reports nothing');
assert.deepEqual(clampReportedLinks([{ username: 'nobody' }]), [], 'a link with no peer is not a link');
assert.deepEqual(
  clampReportedLinks([
    {
      userId: 'u1',
      username: 'ayaan',
      bytesSent: 10.9,
      bytesReceived: -1,
      roundTripMs: 42.4,
      packetsLost: 3,
      packetsReceived: 100,
      transport: 'relay',
    },
  ]),
  [
    {
      userId: 'u1',
      username: 'ayaan',
      bytesSent: 10,
      bytesReceived: 0,
      roundTripMs: 42,
      packetsLost: 3,
      packetsReceived: 100,
      transport: 'relay',
    },
  ],
  'an ordinary link survives, rounded and floored',
);
assert.equal(
  clampReportedLinks([{ userId: 'u1', transport: 'sfu' }])[0]?.transport,
  null,
  'a transport nobody defined reads as unknown, not as itself',
);
assert.equal(
  clampReportedLinks(Array.from({ length: 500 }, (_, i) => ({ userId: `u${i}` }))).length,
  32,
  'a flood of links is cut to a call-sized number',
);

console.log('call usage clamp: ok');

/**
 * What to believe about a number only the client can measure.
 *
 * Media is peer to peer, so nothing on the server ever sees a byte of a call
 * and there is nothing here to check a client's figure against. It is written
 * into the log anyway, because "this call used 400 MB" is the whole point of
 * the log for anybody on a metered connection - but it is clamped first, so the
 * worst a broken or lying client can do is write a wrong number in its own row
 * rather than an absurd one, or a negative that would read as data refunded.
 */

import type { CallLinkReport } from '@betweenus/shared-types';

/** A tenth of a terabyte: past any real call, short of anything that overflows. */
export const MAX_REPORTED_BYTES = 100 * 1024 * 1024 * 1024;

export function clampReportedBytes(bytes: number): number {
  if (!Number.isFinite(bytes) || bytes <= 0) return 0;
  return Math.min(Math.floor(bytes), MAX_REPORTED_BYTES);
}

/** Past any real call: eight peers is the ceiling, and a link is not a call. */
const MAX_LINKS = 32;

/**
 * The per-peer detail, clamped the same way the total is.
 *
 * Everything here is the client's own account of its own connections, and
 * nothing on the server can check a single figure - so the job is not to decide
 * whether it is true but to make sure a broken or hostile client can only write
 * nonsense into its own row, at a bounded size. Anything unrecognisable is
 * dropped rather than repaired: a link with no `userId` is not a link.
 */
export function clampReportedLinks(value: unknown): CallLinkReport[] {
  if (!Array.isArray(value)) return [];

  return value.slice(0, MAX_LINKS).flatMap((entry) => {
    if (!entry || typeof entry !== 'object') return [];
    const link = entry as Record<string, unknown>;
    const userId = typeof link.userId === 'string' ? link.userId.slice(0, 64) : '';
    if (!userId) return [];

    const transport =
      link.transport === 'direct' || link.transport === 'relay' ? link.transport : null;

    return [
      {
        userId,
        username: typeof link.username === 'string' ? link.username.slice(0, 64) : '',
        bytesSent: clampReportedBytes(Number(link.bytesSent)),
        bytesReceived: clampReportedBytes(Number(link.bytesReceived)),
        roundTripMs: clampCount(link.roundTripMs, 60_000) || null,
        packetsLost: clampCount(link.packetsLost, MAX_PACKETS),
        packetsReceived: clampCount(link.packetsReceived, MAX_PACKETS),
        transport,
      } satisfies CallLinkReport,
    ];
  });
}

/** A packet count past which the figure says nothing anybody would read. */
const MAX_PACKETS = 1_000_000_000;

function clampCount(value: unknown, max: number): number {
  const count = Number(value);
  if (!Number.isFinite(count) || count <= 0) return 0;
  return Math.min(Math.round(count), max);
}

/**
 * Self-check for peer identity.
 *
 * Every failure here is silent and expensive. An id that changes across a
 * reconnect is a mesh rebuilt from nothing several times a call; an id that is
 * the *same* for two windows on one account is the second window disconnecting
 * the first; an id built from an unbounded client string is a peer list with a
 * kilobyte of somebody's choosing in it.
 *
 * Run with `pnpm --filter @betweenus/call-service check`.
 */
import assert from 'node:assert/strict';
import { deviceOf, peerIdFor } from './peer-identity';

// The whole point: the same device, twice, is the same peer. This is what a
// reconnect is, and the old per-socket id failed it every time.
assert.equal(peerIdFor('ana', 'phone-1'), peerIdFor('ana', 'phone-1'));

// Two windows on one account are still two peers.
assert.notEqual(peerIdFor('ana', 'phone-1'), peerIdFor('ana', 'laptop-1'));

// One shared machine, two accounts, two peers.
assert.notEqual(peerIdFor('ana', 'phone-1'), peerIdFor('ben', 'phone-1'));

// Handed to every other participant, so it carries neither the account nor the
// installation in the clear.
const id = peerIdFor('ana', 'phone-1');
assert.equal(/^[0-9a-f]{32}$/.test(id), true);
assert.equal(id.includes('ana'), false);
assert.equal(id.includes('phone-1'), false);

// A client that names no device gets the old behaviour: random, per socket.
assert.notEqual(peerIdFor('ana', null), peerIdFor('ana', null));

// What comes off the handshake.
assert.equal(deviceOf('/ws/call?token=abc&device=phone-1'), 'phone-1');
assert.equal(deviceOf('/ws/call?token=abc'), null);
assert.equal(deviceOf('/ws/call?device='), null);
assert.equal(deviceOf(undefined), null);
// Percent-encoded, because the clients encode it.
assert.equal(deviceOf('/ws/call?device=a%20b'), 'a b');
// Unbounded input is refused rather than truncated: half an id is a different
// peer, which is worse than no id at all.
assert.equal(deviceOf(`/ws/call?device=${'x'.repeat(128)}`), 'x'.repeat(128));
assert.equal(deviceOf(`/ws/call?device=${'x'.repeat(129)}`), null);

console.log('call-service peer identity self-check passed');

/**
 * What a peer is called, and for how long.
 *
 * A peer id is not a cosmetic label. Both ends of every connection in the mesh
 * decide who yields on a collision by comparing the two ids, so an id that
 * changes underneath a live call is two ends that disagree about who offers -
 * either nobody does, or both do, and in both cases the call connects and
 * carries nothing.
 *
 * The id used to be `randomUUID()` per socket. That was right about one thing:
 * one account with two windows open is two ends of two different peer
 * connections, and collapsing those onto one identity is what disconnected the
 * first window when the second joined. But a socket is not a window. It is the
 * least durable thing in the system - a phone loses one in a lift, on a train,
 * every time a screen goes off - so a peer changed its name several times per
 * call, and the only defence any client had was to tear the whole mesh down and
 * rebuild it. That is the call that connects, drops, and connects again.
 *
 * So: per device. Two windows are still two peers, and the same window coming
 * back is the same peer.
 *
 * Kept here rather than in the gateway so it can be checked without a socket,
 * which is the only reason either function is exported.
 */
import { createHash, randomUUID } from 'node:crypto';

/**
 * Hashed rather than concatenated: the value is handed to every other
 * participant in the call, and neither the account nor the installation it came
 * from is any of their business. Thirty-two hex characters is the same order of
 * collision resistance as the UUID it replaces.
 *
 * A client that names no device gets a random id - exactly the old behaviour,
 * which is what an older build should keep getting.
 */
export function peerIdFor(userId: string, device: string | null): string {
  if (!device) return randomUUID();
  return createHash('sha256').update(`${userId}:${device}`).digest('hex').slice(0, 32);
}

/**
 * The device this socket says it is, off the handshake query.
 *
 * Bounded and otherwise untouched: it is hashed, never stored and never shown,
 * but it arrives from a client and a client is not a source of good strings.
 */
export function deviceOf(url: string | undefined): string | null {
  if (!url) return null;
  let value: string | null;
  try {
    value = new URL(url, 'http://call').searchParams.get('device');
  } catch {
    return null;
  }
  if (!value) return null;
  return value.length <= MAX_DEVICE_LENGTH ? value : null;
}

const MAX_DEVICE_LENGTH = 128;

