import { createHealthController } from '@betweenus/nest-common';
import { MessagesController } from './modules/messages/messages.controller';
import { MessagesService } from './modules/messages/messages.service';
import { UnfurlService } from './modules/messages/unfurl.service';
import { ArrivalsService } from './modules/messages/arrivals.service';
import { DisappearingSweeper } from './modules/messages/disappearing-sweeper';
import { UploadsController } from './modules/uploads/uploads.controller';
import { ScratchSweeper } from './modules/uploads/scratch-sweeper';
import { AttachmentSweeper } from './modules/uploads/attachment-sweeper';
import { E2eeController } from './modules/e2ee/e2ee.controller';
import { E2eeService } from './modules/e2ee/e2ee.service';
import {
  BlocksController,
  DirectChannelsController,
  FriendsController,
  UserSearchController,
} from './modules/friends/friends.controller';
import { FriendsService } from './modules/friends/friends.service';
import {
  WebhookExecuteController,
  WebhooksController,
} from './modules/webhooks/webhooks.controller';
import { WebhooksService } from './modules/webhooks/webhooks.service';
import { StatusController } from './modules/status/status.controller';
import { StatusService } from './modules/status/status.service';
import { StatusSweeper } from './modules/status/status-sweeper';
import { ChatGateway } from './gateways/chat.gateway';

const SERVICE_NAME = 'chat-service';

@Module({
  controllers: [
    MessagesController,
    UploadsController,
    E2eeController,
    UserSearchController,
    FriendsController,
    BlocksController,
    DirectChannelsController,
    WebhooksController,
    StatusController,
    // Registered after WebhooksController so `/webhooks/:id/rotate` is matched
    // by the guarded route before `/webhooks/:id/:token` can swallow it.
    WebhookExecuteController,
    createHealthController(SERVICE_NAME, pingDatabase),
  ],
  providers: [
    MessagesService,
    UnfurlService,
    ArrivalsService,
    E2eeService,
    FriendsService,
    WebhooksService,
    StatusService,
    ChatGateway,
    ScratchSweeper,
    AttachmentSweeper,
    DisappearingSweeper,
    StatusSweeper,
    {
      provide: EventBus,
      useFactory: () => new EventBus(envOr('REDIS_URL', 'redis://localhost:6379'), SERVICE_NAME),
    },
    {
      // Logger is a class, so it doubles as its own injection token.
      provide: Logger,
      useFactory: (): Logger => createLogger(SERVICE_NAME, envOr('LOG_LEVEL', 'info') as never),
    },
  ],
})
export class AppModule {}

/**
 * `/ws/chat` realtime gateway.
 *
 * Sockets subscribe to channels they may read; delivery is driven by the Redis
 * `message.created` event, so every chat-service instance broadcasts to its own
 * sockets and horizontal scaling needs no sticky sessions.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { PERMISSIONS } from '@betweenus/permissions';
import {
  CONTROL_MAX_PAYLOAD,
  RoomRegistry,
  authenticateHandshake,
  channelRoom,
  dropRevokedSockets,
  serverRoom,
  userRoom,
} from '@betweenus/websocket';
import { Logger } from '@betweenus/logger';
import type { ClientChatEvent, ServerChatEvent, UserSummary } from '@betweenus/shared-types';
import { MessagesService } from '../modules/messages/messages.service';

const HEARTBEAT_INTERVAL_MS = 30_000;

interface SocketState {
  userId: string;
  username: string;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
}

@Injectable()
export class ChatGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly rooms = new RoomRegistry<WebSocket>();
  private readonly state = new WeakMap<WebSocket, SocketState>();

  constructor(
    private readonly messages: MessagesService,
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room, because the four gateways keep
   * different bookkeeping and `clients` is the one thing all of them have. A
   * revocation is rare; a scan of the sockets on one instance is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  /** Called from main.ts once Nest owns a listening HTTP server. */
  async attach(httpServer: HttpServer): Promise<void> {
    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/chat',
      maxPayload: CONTROL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        // Never downgrade to anonymous: close with a policy-violation code.
        socket.close(4401, 'Unauthorized');
        return;
      }

      this.state.set(socket, {
        userId: user.id,
        username: user.username,
        alive: true,
        issuedAt: user.issuedAt,
      });
      // Everything addressed at a person rather than a place - a friend
      // request, an acceptance, being added to a server - is delivered here.
      this.rooms.join(userRoom(user.id), socket);
      this.send(socket, { type: 'ready', userId: user.id });
      this.logger.info('WebSocket connected', { userId: user.id });

      socket.on('pong', () => {
        const state = this.state.get(socket);
        if (state) state.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handleClientEvent(socket, raw.toString());
      });

      socket.on('close', () => {
        this.rooms.leaveAll(socket);
        this.state.delete(socket);
        this.logger.info('WebSocket disconnected', { userId: user.id });
      });

      socket.on('error', (error) => {
        this.logger.warn('WebSocket error', { userId: user.id, reason: String(error) });
      });
    });

    // Drop sockets that stopped answering pings instead of leaking them.
    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
      }
    }, HEARTBEAT_INTERVAL_MS);

    // An account whose authority was withdrawn loses the sockets it already
    // had, which is the half of a revocation that was missing: a handshake is
    // checked once and then trusted until it happens to disconnect.
    await dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) =>
        this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    await this.events.subscribe(EVENTS.MESSAGE_CREATED, (envelope) => {
      const { message } = envelope.payload;
      this.broadcast(channelRoom(message.channelId), { type: 'message.created', message });
    });

    // An edit, a pin, a reaction and a deletion all reach the client as the
    // same event carrying the whole message - a deleted one is a tombstone with
    // `deletedAt` set, which is what the client has to draw.
    await this.events.subscribe(EVENTS.MESSAGE_UPDATED, (envelope) => {
      const { message } = envelope.payload;
      this.broadcast(channelRoom(message.channelId), { type: 'message.updated', message });
    });

    // Except when there is no tombstone. A one-time message that was opened,
    // and one whose disappearing window closed, are destroyed rather than
    // emptied - so what goes out is "forget this", not a message to redraw.
    await this.events.subscribe(EVENTS.MESSAGE_DELETED, (envelope) => {
      const { message, messageId, channelId } = envelope.payload;
      this.broadcast(
        channelRoom(channelId),
        message
          ? { type: 'message.updated', message }
          : { type: 'message.gone', messageId, channelId },
      );
    });

    // A read marker moved. Everyone subscribed to the channel is told, because
    // a read receipt is only useful to the person whose message was read - and
    // the marker is what every client derives "who has seen this" from.
    await this.events.subscribe(EVENTS.CHANNEL_READ, (envelope) => {
      const { channelId, userId, at } = envelope.payload;
      this.broadcast(channelRoom(channelId), { type: 'channel.read', channelId, userId, at });
    });

    // Somebody cleared their own history. It goes to that account's room and
    // nowhere else: every other participant's copy is exactly what it was, and
    // the only sockets that have anything to do are the ones holding this
    // account's own decrypted cache.
    await this.events.subscribe(EVENTS.CHATS_CLEARED, (envelope) => {
      const { userId, clearedAt, channelId } = envelope.payload;
      this.broadcast(userRoom(userId), { type: 'chats.cleared', clearedAt, channelId });
    });

    await this.events.subscribe(EVENTS.FRIEND_CHANGED, (envelope) => {
      for (const userId of envelope.payload.userIds) {
        this.broadcast(userRoom(userId), { type: 'friends.changed' });
      }
    });

    // Somebody posted, deleted, or aged out of a status. The audience was
    // worked out where the row was written - that is where the friend list
    // already was - so this only has to deliver it.
    await this.events.subscribe(EVENTS.STATUS_CHANGED, (envelope) => {
      const { userIds, authorId } = envelope.payload;
      this.deliver(userIds.map(userRoom), { type: 'status.changed', authorId });
    });

    // Every membership change reaches the same client event: the server's
    // watchers refresh their member list, and the person who joined, was
    // removed or had their permissions changed refreshes their own list of
    // servers - which is where the permissions their UI reads come from.
    for (const event of [
      EVENTS.SERVER_MEMBER_ADDED,
      EVENTS.SERVER_MEMBER_REMOVED,
      EVENTS.SERVER_MEMBER_UPDATED,
    ] as const) {
      await this.events.subscribe(event, (envelope) => {
        const { serverId, userId } = envelope.payload;
        this.deliver([serverRoom(serverId), userRoom(userId)], {
          type: 'server.members.changed',
          serverId,
        });
      });
    }

    // A renamed server, or one with a new picture. Everyone watching it is
    // holding the old one in a sidebar.
    await this.events.subscribe(EVENTS.SERVER_UPDATED, (envelope) => {
      const { serverId, name, iconUrl } = envelope.payload;
      this.broadcast(serverRoom(serverId), { type: 'server.updated', serverId, name, iconUrl });
    });

    // A changed profile has to reach everyone who draws it, which is a wider
    // set than any one room: the members of every server this account is in,
    // everyone it is friends with, and its own other devices.
    await this.events.subscribe(EVENTS.USER_UPDATED, (envelope) => {
      void this.broadcastProfile(envelope.payload.user);
    });

    this.logger.info('Chat WebSocket gateway ready', { path: '/ws/chat' });
  }

  private async handleClientEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientChatEvent;
    try {
      event = JSON.parse(raw) as ClientChatEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'ping':
        this.send(socket, { type: 'pong' });
        return;

      case 'channel.subscribe':
        try {
          // Re-check on every subscribe: permissions can change mid-session.
          await this.messages.requireChannelAccess(
            state.userId,
            event.channelId,
            PERMISSIONS.VIEW_CHANNEL,
          );
        } catch {
          this.send(socket, {
            type: 'error',
            code: 'CHANNEL_FORBIDDEN',
            message: 'Cannot subscribe to this channel',
          });
          return;
        }
        this.rooms.join(channelRoom(event.channelId), socket);
        return;

      case 'channel.unsubscribe':
        this.rooms.leave(channelRoom(event.channelId), socket);
        return;

      case 'server.subscribe': {
        // Membership, not permission: anyone in the server may know when its
        // member list changes, which is what the client re-reads.
        const membership = await prisma.serverMember.findUnique({
          where: { serverId_userId: { serverId: event.serverId, userId: state.userId } },
          select: { id: true },
        });
        if (!membership) {
          this.send(socket, {
            type: 'error',
            code: 'SERVER_FORBIDDEN',
            message: 'Cannot subscribe to this server',
          });
          return;
        }
        this.rooms.join(serverRoom(event.serverId), socket);
        return;
      }

      case 'server.unsubscribe':
        this.rooms.leave(serverRoom(event.serverId), socket);
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  /**
   * Who can see a profile: every server they share, plus every friendship.
   *
   * Friendships rather than DM channels because a direct message already
   * requires an accepted friendship - so the friend list is the same set, and
   * it is one query rather than two.
   */
  private async broadcastProfile(user: UserSummary): Promise<void> {
    const [memberships, friendships] = await Promise.all([
      prisma.serverMember.findMany({ where: { userId: user.id }, select: { serverId: true } }),
      prisma.friendship.findMany({
        where: { status: 'ACCEPTED', OR: [{ userAId: user.id }, { userBId: user.id }] },
        select: { userAId: true, userBId: true },
      }),
    ]);

    const rooms = [
      userRoom(user.id),
      ...memberships.map((row) => serverRoom(row.serverId)),
      ...friendships.map((row) => userRoom(row.userAId === user.id ? row.userBId : row.userAId)),
    ];
    this.deliver(rooms, { type: 'user.updated', user });
  }

  private broadcast(room: string, event: ServerChatEvent): void {
    for (const socket of this.rooms.members(room)) this.send(socket, event);
  }

  /** Several rooms, one delivery each - a socket in two of them is told once. */
  private deliver(rooms: string[], event: ServerChatEvent): void {
    const seen = new Set<WebSocket>();
    for (const room of rooms) {
      for (const socket of this.rooms.members(room)) seen.add(socket);
    }
    for (const socket of seen) this.send(socket, event);
  }

  private send(socket: WebSocket, event: ServerChatEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    this.server?.close();
  }
}

import 'reflect-metadata';
import type { Server as HttpServer } from 'node:http';
import { bootstrapService } from '@betweenus/nest-common';
import { AppModule } from './app.module';
import { ChatGateway } from './gateways/chat.gateway';

async function start(): Promise<void> {
  const app = await bootstrapService({
    service: 'chat-service',
    module: AppModule,
    portVar: 'CHAT_SERVICE_PORT',
    defaultPort: 3004,
  });

  // The WebSocket server shares the HTTP listener, so /ws/chat and the REST
  // routes live behind one port and one Nginx upstream.
  const gateway = app.get(ChatGateway);
  await gateway.attach(app.getHttpServer() as HttpServer);
}

void start();

import { Type } from 'class-transformer';
import {
  ArrayMaxSize,
  Equals,
  IsArray,
  IsIn,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Length,
  Max,
  Min,
  ValidateNested,
} from 'class-validator';
import type {
  BackupSecretKind,
  PublishChannelKeysRequest,
  PutIdentityBackupRequest,
  RegisterDeviceKeyRequest,
} from '@betweenus/shared-types';

/** A serialised ECDH P-256 JWK is ~200 chars; the cap is slack, not a guess. */
const MAX_PUBLIC_KEY_LENGTH = 1024;

/**
 * A device id is minted by the client and is opaque here. Not a UUID pipe: the
 * one thing the server must never do with it is assume a shape it did not
 * issue, and the rows carried over from the single-key directory are called
 * `legacy`.
 */
const MAX_DEVICE_ID_LENGTH = 128;

export class RegisterDeviceKeyDto implements RegisterDeviceKeyRequest {
  @IsString()
  @Length(1, MAX_DEVICE_ID_LENGTH)
  deviceId!: string;

  @IsString()
  @Length(1, MAX_PUBLIC_KEY_LENGTH)
  publicKey!: string;

  /** Shown in a list of this account's machines, so it is short and optional. */
  @IsOptional()
  @IsString()
  @Length(1, 64)
  label?: string;
}

/**
 * A sealed identity key. The server checks shape and size only - it cannot tell
 * a real blob from noise - except for the iteration floor, which is worth
 * enforcing: it is the one number in here that decides how expensive guessing
 * the user's secret would be for whoever steals the table.
 */
export class PutIdentityBackupDto implements PutIdentityBackupRequest {
  @Equals(1)
  v!: 1;

  @IsIn(['password', 'passphrase'])
  kind!: BackupSecretKind;

  @IsIn(['PBKDF2-SHA256'])
  kdf!: 'PBKDF2-SHA256';

  @IsInt()
  @Min(100_000)
  @Max(10_000_000)
  iterations!: number;

  @IsString()
  @Length(16, 128)
  salt!: string;

  @IsString()
  @Length(1, 64)
  iv!: string;

  // An ECDH P-256 key pair as JWK JSON is ~600 bytes; base64 of its ciphertext
  // is under 1 KB. The cap is slack for a future format, not a guess at this one.
  @IsString()
  @Length(1, 4096)
  ct!: string;

  @IsString()
  @Length(1, MAX_PUBLIC_KEY_LENGTH)
  publicKey!: string;
}

export class ChannelKeyEntryDto {
  @IsUUID()
  recipientUserId!: string;

  @IsString()
  @Length(1, MAX_DEVICE_ID_LENGTH)
  recipientDeviceId!: string;

  @IsString()
  @Length(1, MAX_PUBLIC_KEY_LENGTH)
  senderPublicKey!: string;

  @IsString()
  @Length(1, 512)
  wrappedKey!: string;

  @IsString()
  @Length(1, 64)
  iv!: string;
}

export class PublishChannelKeysDto implements PublishChannelKeysRequest {
  @IsUUID()
  channelId!: string;

  @IsInt()
  @Min(1)
  @Max(1_000_000)
  epoch!: number;

  @IsString()
  @Length(1, MAX_DEVICE_ID_LENGTH)
  senderDeviceId!: string;

  @IsArray()
  // One entry per member *device* now rather than per member, so the ceiling
  // rises with it. Still small enough that a bigger bundle is not a real server,
  // it is someone probing the endpoint.
  @ArrayMaxSize(2000)
  @ValidateNested({ each: true })
  @Type(() => ChannelKeyEntryDto)
  entries!: ChannelKeyEntryDto[];
}

import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  Param,
  ParseUUIDPipe,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  BackupSecretKind,
  ChannelKeysResponse,
  DeviceKey,
  IdentityBackupResponse,
} from '@betweenus/shared-types';
import { E2eeService } from './e2ee.service';
import { PublishChannelKeysDto, PutIdentityBackupDto, RegisterDeviceKeyDto } from './dto';

@Controller('e2ee')
@UseGuards(JwtAuthGuard)
export class E2eeController {
  constructor(private readonly e2ee: E2eeService) {}

  @Post('devices')
  registerDevice(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: RegisterDeviceKeyDto,
  ): Promise<DeviceKey> {
    return this.e2ee.registerDevice(user.id, dto.deviceId, dto.publicKey, dto.label);
  }

  /**
   * This account's own machines. Separate from `GET devices?channelId=`, which
   * answers "whose keys do I wrap for" - this one answers "what is signed in as
   * me", which is a question only the owner gets to ask.
   */
  @Get('devices/mine')
  myDevices(@CurrentUser() user: AuthenticatedUser): Promise<DeviceKey[]> {
    return this.e2ee.myDevices(user.id);
  }

  /** Stops a machine being wrapped for, and deletes what it was already given. */
  @Delete('devices/:deviceId')
  revokeDevice(
    @CurrentUser() user: AuthenticatedUser,
    @Param('deviceId') deviceId: string,
  ): Promise<DeviceKey> {
    return this.e2ee.revokeDevice(user.id, deviceId);
  }

  /**
   * The caller's sealed identity keys, for a machine that has none of its own.
   *
   * Plural: an account may hold a password-sealed blob and a passphrase-sealed
   * one, and a client opens whichever its secret matches.
   */
  @Get('backup')
  backup(@CurrentUser() user: AuthenticatedUser): Promise<IdentityBackupResponse> {
    return this.e2ee.identityBackup(user.id);
  }

  @Put('backup')
  async putBackup(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: PutIdentityBackupDto,
  ): Promise<{ ok: true }> {
    await this.e2ee.putIdentityBackup(user.id, dto);
    return { ok: true };
  }

  /**
   * Removes one kind of backup. What "do not let my account password recover my
   * messages" is made of, once a recovery passphrase is standing.
   */
  @Delete('backup/:kind')
  async deleteBackup(
    @CurrentUser() user: AuthenticatedUser,
    @Param('kind') kind: string,
  ): Promise<{ ok: true }> {
    if (kind !== 'password' && kind !== 'passphrase') {
      throw new BadRequestException({ code: 'INVALID_BACKUP_KIND', message: 'Unknown backup kind' });
    }
    await this.e2ee.deleteIdentityBackup(user.id, kind satisfies BackupSecretKind);
    return { ok: true };
  }

  @Get('devices')
  devices(
    @CurrentUser() user: AuthenticatedUser,
    @Query('channelId', ParseUUIDPipe) channelId: string,
  ): Promise<DeviceKey[]> {
    return this.e2ee.devicesForChannel(user.id, channelId);
  }

  @Get('keys/:channelId')
  keys(
    @CurrentUser() user: AuthenticatedUser,
    @Param('channelId', ParseUUIDPipe) channelId: string,
  ): Promise<ChannelKeysResponse> {
    return this.e2ee.keysForUser(user.id, channelId);
  }

  @Post('keys')
  publish(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: PublishChannelKeysDto,
  ): Promise<{ epoch: number; stored: number }> {
    return this.e2ee.publishKeys(user.id, dto);
  }
}

/**
 * Key directory for end-to-end encrypted channels.
 *
 * Everything stored here is either a public key or a ciphertext the server has
 * no key for. The service enforces *who may publish*, never *what is inside*.
 *
 * The device directory is user-level data and belongs in `user-service` once
 * that exists; it lives here for now so E2EE ships as one module and one route
 * (recorded as a deliberate shortcut in development/PLANNING.md).
 */
import { ForbiddenException, Injectable } from '@nestjs/common';
import { channelAudience, prisma } from '@betweenus/database';
import { PERMISSIONS } from '@betweenus/permissions';
import type {
  BackupSecretKind,
  ChannelKeysResponse,
  DeviceKey,
  IdentityBackup,
  IdentityBackupResponse,
  PublishChannelKeysRequest,
  PutIdentityBackupRequest,
} from '@betweenus/shared-types';
import { MessagesService } from '../messages/messages.service';

/**
 * How many epochs back a re-wrap is offered in one response.
 *
 * A ceiling rather than a policy: a client works through what it is given and
 * asks again, so a channel with a hundred epochs recovers over a few opens
 * instead of in one response nobody wants to build or parse.
 */
const MAX_GAP_EPOCHS = 20;

@Injectable()
export class E2eeService {
  constructor(private readonly messages: MessagesService) {}

  /**
   * Publishes (or rotates) one machine's public identity key.
   *
   * A revoked id stays revoked, and re-registering it is refused rather than
   * quietly clearing the flag. Allowing the machine to un-revoke itself would
   * make revocation a suggestion: the case it exists for is a laptop somebody
   * else is holding, and that laptop is running this same code.
   *
   * What revocation cannot do is stop a machine that still holds a valid
   * session from starting again as a *new* device - the app would have to be
   * reinstalled, but nothing here can tell that apart from a genuinely new
   * laptop. Ending the session is what answers that, and this is not a
   * substitute for it. See development/E2EE.md.
   */
  async registerDevice(
    userId: string,
    deviceId: string,
    publicKey: string,
    label?: string,
  ): Promise<DeviceKey> {
    const existing = await prisma.deviceKey.findUnique({
      where: { userId_deviceId: { userId, deviceId } },
      select: { revokedAt: true },
    });
    if (existing?.revokedAt) {
      throw new ForbiddenException({
        code: 'DEVICE_REVOKED',
        message: 'This device was revoked',
      });
    }

    const row = await prisma.deviceKey.upsert({
      where: { userId_deviceId: { userId, deviceId } },
      update: { publicKey, lastSeenAt: new Date(), ...(label ? { label } : {}) },
      create: { userId, deviceId, publicKey, label: label ?? null },
    });
    return toDeviceKey(row);
  }

  /** This account's own machines, newest first. Nobody else's. */
  async myDevices(userId: string): Promise<DeviceKey[]> {
    const rows = await prisma.deviceKey.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
    });
    return rows.map(toDeviceKey);
  }

  /**
   * Stops a machine being wrapped for, and takes away what it was already
   * given.
   *
   * The wraps go because leaving them is leaving the key: a revoked laptop
   * still holds its private half, and a row it can open is a row it can keep
   * opening. What it decrypted before this is gone - it was decrypted on a
   * machine somebody has decided not to trust, and no server-side deletion
   * reaches that.
   *
   * The row itself stays. When a device stopped being trusted is the only thing
   * anybody can audit afterwards, and a deleted row says nothing.
   */
  async revokeDevice(userId: string, deviceId: string): Promise<DeviceKey> {
    const row = await prisma.deviceKey.findUnique({
      where: { userId_deviceId: { userId, deviceId } },
    });
    if (!row) {
      throw new ForbiddenException({ code: 'DEVICE_NOT_FOUND', message: 'No such device' });
    }

    const [updated] = await prisma.$transaction([
      prisma.deviceKey.update({
        where: { id: row.id },
        data: { revokedAt: new Date() },
      }),
      prisma.channelKey.deleteMany({
        where: { recipientUserId: userId, recipientDeviceId: deviceId },
      }),
    ]);

    return toDeviceKey(updated);
  }

  /**
   * The caller's sealed identity key, or null if they never uploaded one.
   *
   * Handing this to whoever holds a session for the account is the point: it is
   * what turns "this machine" into "this account", and it is ciphertext under a
   * key derived from a secret that never reaches the server, so a session alone
   * does not open it.
   */
  async identityBackup(userId: string): Promise<IdentityBackupResponse> {
    const rows = await prisma.identityBackup.findMany({ where: { userId } });
    const backups = rows.map(toIdentityBackup);

    return {
      backups,
      // A client older than per-kind backups reads one blob and one kind. Give
      // it the password one when it exists, because the password is the secret
      // such a client actually holds at sign-in; handing it the passphrase blob
      // would make it decide it cannot open anything and mint its own identity.
      backup: backups.find((it) => it.kind === 'password') ?? backups[0] ?? null,
    };
  }

  /**
   * Replaces the caller's backup. Overwriting is the normal case - a changed
   * password re-seals the same identity under a new key - so there is no
   * "already exists" rule to enforce here, and no way for the server to tell a
   * good blob from a bad one anyway.
   */
  async putIdentityBackup(userId: string, dto: PutIdentityBackupRequest): Promise<void> {
    const data = {
      kdf: dto.kdf,
      iterations: dto.iterations,
      salt: dto.salt,
      iv: dto.iv,
      ciphertext: dto.ct,
      publicKey: dto.publicKey,
    };
    // Scoped to the kind, so writing a passphrase backup leaves the password
    // one standing. It used to be keyed on the account, and setting a
    // passphrase silently took away the only blob a fresh sign-in can open.
    await prisma.identityBackup.upsert({
      where: { userId_kind: { userId, kind: dto.kind } },
      update: data,
      create: { userId, kind: dto.kind, ...data },
    });
  }

  /**
   * Drops one kind of backup, which is how somebody says "my password must not
   * be able to recover my messages".
   *
   * Deleting the last one is allowed. It is the same thing as never having had
   * one, and refusing would be the server deciding how recoverable an account
   * is - a choice that belongs to whoever holds the keys, not to the courier.
   */
  async deleteIdentityBackup(userId: string, kind: BackupSecretKind): Promise<void> {
    await prisma.identityBackup.deleteMany({ where: { userId, kind } });
  }

  /**
   * Every device of every channel member, minus the revoked ones.
   *
   * Revoked devices are filtered here rather than left to the client, because
   * this is the list a client wraps the channel key against and "do not seal
   * anything for that laptop again" has to be enforced where the answer is
   * produced, not where it is used.
   */
  async devicesForChannel(userId: string, channelId: string): Promise<DeviceKey[]> {
    await this.messages.requireChannelAccess(userId, channelId, PERMISSIONS.VIEW_CHANNEL);
    const memberIds = await this.memberIds(channelId);

    const rows = await prisma.deviceKey.findMany({
      where: { userId: { in: memberIds }, revokedAt: null },
      orderBy: { createdAt: 'asc' },
    });
    return rows.map(toDeviceKey);
  }

  /** Wrapped keys addressed to the caller, plus who still needs a re-wrap. */
  async keysForUser(userId: string, channelId: string): Promise<ChannelKeysResponse> {
    await this.messages.requireChannelAccess(userId, channelId, PERMISSIONS.VIEW_CHANNEL);

    const [rows, latest] = await Promise.all([
      prisma.channelKey.findMany({
        // Every device of the caller, not only the one asking: a client holds
        // one private key, tries each row against it, and keeps what opens.
        // Filtering by device here would mean trusting a device id the caller
        // supplied, which is a claim rather than a fact.
        where: { channelId, recipientUserId: userId },
        orderBy: { epoch: 'asc' },
      }),
      prisma.channelKey.aggregate({ where: { channelId }, _max: { epoch: true } }),
    ]);

    const epoch = latest._max.epoch ?? 0;

    return {
      channelId,
      epoch,
      keys: rows.map((row) => ({
        epoch: row.epoch,
        recipientUserId: row.recipientUserId,
        recipientDeviceId: row.recipientDeviceId,
        senderUserId: row.senderUserId,
        senderDeviceId: row.senderDeviceId,
        senderPublicKey: row.senderPublicKey,
        wrappedKey: row.wrappedKey,
        iv: row.iv,
      })),
      missingRecipients: epoch === 0 ? [] : await this.missingAtEpoch(channelId, epoch),
      rekeyNeeded: epoch === 0 ? false : await this.staleAtEpoch(channelId, epoch),
      gaps: epoch === 0 ? [] : await this.gaps(channelId, epoch),
    };
  }

  /**
   * Machines missing an epoch *their owner already holds on another machine*,
   * across every epoch the channel has had.
   *
   * `missingRecipients` answers a narrower question - the current epoch only -
   * which keeps the next message readable and does nothing for the last year of
   * them. A machine that signs in today is missing every earlier epoch, cannot
   * re-wrap them for itself because it holds none of them, and had nothing
   * looking on its behalf. So it minted a fresh epoch and everything written
   * before it stayed sealed for good: the wall of padlocks a second device used
   * to open on.
   *
   * The "their owner already holds it" condition is the whole of the boundary,
   * and it is not a detail (but see `historySharedWith` for the one deliberate
   * exception to it). Without it this would hand every past epoch to
   * somebody who joined the channel yesterday, which is the opposite of the
   * rule the rest of this file keeps: a member reads from when they joined.
   * With it, the only thing being repaired is a person's own access on a second
   * machine - they can read those messages already, on the laptop in the next
   * room.
   *
   * Two queries whatever the number of epochs. Publishing against it is
   * governed as it always was: a caller may add to an existing epoch only while
   * holding that epoch's key.
   */
  private async gaps(
    channelId: string,
    epoch: number,
  ): Promise<Array<{ epoch: number; devices: DeviceKey[] }>> {
    const memberIds = await this.memberIds(channelId);
    const [covered, devices, withHistory] = await Promise.all([
      prisma.channelKey.findMany({
        where: { channelId },
        select: { epoch: true, recipientUserId: true, recipientDeviceId: true },
      }),
      prisma.deviceKey.findMany({
        where: { userId: { in: memberIds }, revokedAt: null },
      }),
      this.historySharedWith(channelId, memberIds),
    ]);

    const has = new Set(
      covered.map((row) => `${row.epoch}:${row.recipientUserId}:${row.recipientDeviceId}`),
    );
    /** Who may be given epoch E at all: whoever already has it somewhere. */
    const owners = new Set(covered.map((row) => `${row.epoch}:${row.recipientUserId}`));
    // Only epochs that exist. An epoch nobody ever minted is not a gap, and
    // inventing one here would ask a client to publish a key for it.
    const epochs = [...new Set(covered.map((row) => row.epoch))].sort((a, b) => b - a);

    return epochs
      .map((at) => ({
        epoch: at,
        devices: devices
          .filter(
            (device) =>
              // Either they already hold this epoch somewhere of their own, or
              // somebody deliberately let them in with the history - see
              // `historySharedWith`. Everyone else is offered nothing they did
              // not already have, which is the rule the whole of this file is
              // built on.
              (owners.has(`${at}:${device.userId}`) || withHistory.has(device.userId)) &&
              !has.has(`${at}:${device.userId}:${device.deviceId}`),
          )
          .map(toDeviceKey),
      }))
      .filter((gap) => gap.devices.length > 0)
      // The newest epochs matter most - they are what the next message uses -
      // and a channel with a long history should not be one enormous response.
      .slice(0, MAX_GAP_EPOCHS);
  }

  /**
   * Members somebody deliberately let in with the history that predates them.
   *
   * The rule everywhere else here is that a machine may only be handed an epoch
   * its owner already holds somewhere - so a newcomer reads from the moment
   * they arrive and no further back. That is still the default, and it is still
   * what happens unless a person with `MANAGE_MEMBER` said otherwise while
   * adding them.
   *
   * When they did, `server_members.historyShared` records it, and this is where
   * that note is turned into an answer: those members' devices appear in the
   * gap list for *every* epoch of every channel in the server, and the first
   * machine that already holds them seals them across. The server hands over
   * nothing itself - it holds no key - and the publish rules are unchanged: a
   * caller may still only add to an epoch it holds.
   *
   * A direct message has no server and therefore no such note. It also needs
   * none: both participants have been there since the first message.
   */
  private async historySharedWith(
    channelId: string,
    memberIds: string[],
  ): Promise<Set<string>> {
    if (memberIds.length === 0) return new Set();

    const channel = await prisma.channel.findUnique({
      where: { id: channelId },
      select: { serverId: true },
    });
    if (!channel?.serverId) return new Set();

    const shared = await prisma.serverMember.findMany({
      where: { serverId: channel.serverId, userId: { in: memberIds }, historyShared: true },
      select: { userId: true },
    });
    return new Set(shared.map((row) => row.userId));
  }

  /**
   * Does anybody outside the channel hold the current key?
   *
   * Derived rather than recorded, which is what makes it right without a
   * bookkeeping step somebody can forget: the answer is a comparison between
   * who was wrapped for and who is a member now, so every way of losing access -
   * dropped from a private channel's allowlist, kicked from the server, the
   * channel made private around them - produces it, including the ones added
   * later.
   */
  private async staleAtEpoch(channelId: string, epoch: number): Promise<boolean> {
    const [memberIds, holders] = await Promise.all([
      this.memberIds(channelId),
      prisma.channelKey.findMany({
        where: { channelId, epoch },
        select: { recipientUserId: true, createdAt: true },
      }),
    ]);

    const members = new Set(memberIds);
    if (holders.some((holder) => !members.has(holder.recipientUserId))) return true;

    // The second way to hold a key you should not: a machine that was trusted
    // when the epoch was minted and has been revoked since.
    //
    // It cannot be derived by looking for its wraps, because revoking deletes
    // them - that is most of what revoking *is*. What is left is the timing: a
    // device revoked after this epoch was created was a device this epoch was
    // wrapped for, so the epoch is on a machine nobody trusts any more.
    //
    // Over-rotating is a re-wrap nobody notices. Under-rotating is a lost
    // laptop reading the channel for as long as it stays on the same key, so
    // where the two answers differ this takes the expensive one.
    if (holders.length === 0) return false;
    const mintedAt = holders.reduce(
      (earliest, holder) => (holder.createdAt < earliest ? holder.createdAt : earliest),
      holders[0]!.createdAt,
    );

    const revokedSince = await prisma.deviceKey.findFirst({
      where: { userId: { in: memberIds }, revokedAt: { gt: mintedAt } },
      select: { id: true },
    });
    return revokedSince !== null;
  }

  /**
   * Stores a bundle of wrapped keys.
   *
   * Two rules keep a member from hijacking a channel's key: a new epoch must be
   * exactly the next one, and adding to an existing epoch requires already
   * holding that epoch's key. Existing entries are never overwritten.
   *
   * Minting the next epoch deliberately needs no key of its own: a member who
   * joined after the channel was keyed holds nothing, and if only a holder
   * could move the channel forward they would be locked out until one came
   * online. Nothing is given away by it - a member can read what is sent from
   * now on either way, and every earlier epoch stays sealed to whoever held it.
   */
  async publishKeys(
    userId: string,
    dto: PublishChannelKeysRequest,
  ): Promise<{ epoch: number; stored: number }> {
    await this.messages.requireChannelAccess(userId, dto.channelId, PERMISSIONS.SEND_MESSAGE);

    const latest = await prisma.channelKey.aggregate({
      where: { channelId: dto.channelId },
      _max: { epoch: true },
    });
    const currentEpoch = latest._max.epoch ?? 0;

    if (dto.epoch > currentEpoch) {
      if (dto.epoch !== currentEpoch + 1) {
        throw new ForbiddenException({
          code: 'EPOCH_OUT_OF_ORDER',
          message: `Next epoch is ${currentEpoch + 1}`,
        });
      }
    } else {
      // Any of the caller's devices holding this epoch is enough: the check is
      // "do you already have this key", and the person is the one who has it.
      const holdsKey = await prisma.channelKey.findFirst({
        where: { channelId: dto.channelId, epoch: dto.epoch, recipientUserId: userId },
        select: { id: true },
      });
      if (!holdsKey) {
        throw new ForbiddenException({
          code: 'EPOCH_NOT_HELD',
          message: 'Only a holder of this epoch may distribute it',
        });
      }
    }

    // Silently dropping non-members would hide a client bug; reject instead.
    const memberIds = new Set(await this.memberIds(dto.channelId));
    for (const entry of dto.entries) {
      if (!memberIds.has(entry.recipientUserId)) {
        throw new ForbiddenException({
          code: 'RECIPIENT_NOT_MEMBER',
          message: 'Recipient is not a member of this channel',
        });
      }
    }

    // And nothing is sealed for a device its owner has revoked. The client
    // fetches a filtered directory, so this only catches a stale bundle or a
    // client that decided to improvise - but it is the difference between a
    // revocation and a suggestion.
    const revoked = await prisma.deviceKey.findMany({
      where: {
        revokedAt: { not: null },
        OR: dto.entries.map((entry) => ({
          userId: entry.recipientUserId,
          deviceId: entry.recipientDeviceId,
        })),
      },
      select: { id: true },
    });
    if (revoked.length > 0) {
      throw new ForbiddenException({
        code: 'DEVICE_REVOKED',
        message: 'One of those devices has been revoked',
      });
    }

    const result = await prisma.channelKey.createMany({
      data: dto.entries.map((entry) => ({
        channelId: dto.channelId,
        epoch: dto.epoch,
        recipientUserId: entry.recipientUserId,
        recipientDeviceId: entry.recipientDeviceId,
        senderUserId: userId,
        senderDeviceId: dto.senderDeviceId,
        senderPublicKey: entry.senderPublicKey,
        wrappedKey: entry.wrappedKey,
        iv: entry.iv,
      })),
      skipDuplicates: true,
    });

    return { epoch: dto.epoch, stored: result.count };
  }

  /**
   * Who the key is wrapped for. `channelAudience` is the allowlist on a private
   * channel and every server member otherwise, so the people who can read the
   * channel and the people who get a key are the same set by construction.
   */
  private async memberIds(channelId: string): Promise<string[]> {
    return channelAudience(channelId);
  }

  /**
   * Devices that should hold this epoch and do not - one entry per machine.
   *
   * Per device rather than per person, which is the whole change: somebody who
   * signed in on a second laptop yesterday is not "covered" because their first
   * laptop was wrapped for. The comparison is against every unrevoked device of
   * every member.
   */
  private async missingAtEpoch(channelId: string, epoch: number): Promise<DeviceKey[]> {
    const memberIds = await this.memberIds(channelId);
    const [covered, devices] = await Promise.all([
      prisma.channelKey.findMany({
        where: { channelId, epoch },
        select: { recipientUserId: true, recipientDeviceId: true },
      }),
      prisma.deviceKey.findMany({
        where: { userId: { in: memberIds }, revokedAt: null },
      }),
    ]);

    const has = new Set(covered.map((row) => `${row.recipientUserId}:${row.recipientDeviceId}`));
    return devices
      .filter((device) => !has.has(`${device.userId}:${device.deviceId}`))
      .map(toDeviceKey);
  }
}

/** One row of the directory, as the contract has it. */
function toIdentityBackup(row: {
  kind: string;
  kdf: string;
  iterations: number;
  salt: string;
  iv: string;
  ciphertext: string;
  publicKey: string;
  updatedAt: Date;
}): IdentityBackup {
  return {
    v: 1,
    kind: row.kind as BackupSecretKind,
    kdf: row.kdf as IdentityBackup['kdf'],
    iterations: row.iterations,
    salt: row.salt,
    iv: row.iv,
    ct: row.ciphertext,
    publicKey: row.publicKey,
    updatedAt: row.updatedAt.toISOString(),
  };
}

/**
 * Exported for the status module, which wraps for the same directory this one
 * publishes: one shape for a device key, not two that nearly agree.
 */
export function toDeviceKey(row: {
  userId: string;
  deviceId: string;
  publicKey: string;
  label: string | null;
  revokedAt: Date | null;
  lastSeenAt: Date;
  createdAt: Date;
}): DeviceKey {
  return {
    userId: row.userId,
    deviceId: row.deviceId,
    publicKey: row.publicKey,
    label: row.label,
    revokedAt: row.revokedAt?.toISOString() ?? null,
    lastSeenAt: row.lastSeenAt.toISOString(),
    createdAt: row.createdAt.toISOString(),
  };
}

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { IsString, IsUUID, Length } from 'class-validator';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  BlockedUser,
  BlockUserRequest,
  DirectChannel,
  Friend,
  OpenDirectChannelRequest,
  SendFriendRequestRequest,
  UserSummary,
} from '@betweenus/shared-types';
import { FriendsService } from './friends.service';

export class SendFriendRequestDto implements SendFriendRequestRequest {
  @IsString()
  @Length(2, 32)
  username!: string;
}

export class OpenDirectChannelDto implements OpenDirectChannelRequest {
  @IsUUID()
  userId!: string;
}

export class BlockUserDto implements BlockUserRequest {
  @IsUUID()
  userId!: string;
}

@Controller('users')
@UseGuards(JwtAuthGuard)
export class UserSearchController {
  constructor(private readonly friends: FriendsService) {}

  @Get('search')
  search(
    @CurrentUser() user: AuthenticatedUser,
    @Query('q') query = '',
    /** `true` narrows the answer to this account's friends - see the service. */
    @Query('friendsOnly') friendsOnly = '',
  ): Promise<UserSummary[]> {
    return this.friends.search(user.id, query, friendsOnly === 'true');
  }
}

@Controller('friends')
@UseGuards(JwtAuthGuard)
export class FriendsController {
  constructor(private readonly friends: FriendsService) {}

  @Get()
  list(@CurrentUser() user: AuthenticatedUser): Promise<Friend[]> {
    return this.friends.list(user.id);
  }

  @Post()
  request(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: SendFriendRequestDto,
  ): Promise<Friend> {
    return this.friends.request(user.id, dto.username);
  }

  @Post(':userId/accept')
  accept(
    @CurrentUser() user: AuthenticatedUser,
    @Param('userId', ParseUUIDPipe) otherUserId: string,
  ): Promise<Friend> {
    return this.friends.accept(user.id, otherUserId);
  }

  @Delete(':userId')
  @HttpCode(204)
  remove(
    @CurrentUser() user: AuthenticatedUser,
    @Param('userId', ParseUUIDPipe) otherUserId: string,
  ): Promise<void> {
    return this.friends.remove(user.id, otherUserId);
  }
}

/**
 * The block list. Its own controller rather than a verb on `/friends`, because
 * blocking somebody you were never friends with is the ordinary case - the
 * relationship it ends is optional, and the one it creates is not a friendship.
 */
@Controller('blocks')
@UseGuards(JwtAuthGuard)
export class BlocksController {
  constructor(private readonly friends: FriendsService) {}

  @Get()
  list(@CurrentUser() user: AuthenticatedUser): Promise<BlockedUser[]> {
    return this.friends.blocked(user.id);
  }

  @Post()
  block(@CurrentUser() user: AuthenticatedUser, @Body() dto: BlockUserDto): Promise<BlockedUser> {
    return this.friends.block(user.id, dto.userId);
  }

  @Delete(':userId')
  @HttpCode(204)
  unblock(
    @CurrentUser() user: AuthenticatedUser,
    @Param('userId', ParseUUIDPipe) otherUserId: string,
  ): Promise<void> {
    return this.friends.unblock(user.id, otherUserId);
  }
}

@Controller('dm')
@UseGuards(JwtAuthGuard)
export class DirectChannelsController {
  constructor(private readonly friends: FriendsService) {}

  @Get()
  list(@CurrentUser() user: AuthenticatedUser): Promise<DirectChannel[]> {
    return this.friends.directChannels(user.id);
