    return this.friends.openDirectChannel(user.id, dto.userId);
  }
}

/**
 * Friends, and the direct message channels they unlock.
 *
 * This is user-level data and belongs in `user-service` once that exists - the
 * same deliberate shortcut the E2EE device directory takes, and recorded in
 * development/PLANNING.md. It lives in chat-service because a direct message is
 * a channel and chat-service already owns everything downstream of a channel id.
 */
import { BadRequestException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
import { blockedIdsAround, friendIdsOf, isBlockedBetween, prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import type {
  BlockedUser,
  DirectChannel,
  Friend,
  FriendshipStatus,
  UserSummary,
} from '@betweenus/shared-types';

const SEARCH_LIMIT = 20;

interface UserRow {
  id: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
  coverUrl: string | null;
  about: string;
}

@Injectable()
export class FriendsService {
  constructor(private readonly events: EventBus) {}

  /**
   * Finds people by username or display name. Anyone is findable, because a
   * request cannot be sent to someone who cannot be found; what is gated is the
   * conversation, not the search.
   */
  /**
   * Finds people by name.
   *
   * Two questions wear this one endpoint, and they want different answers.
   * "Who can I send a friend request to" is the whole directory, because a
   * stranger is exactly who you are looking for. "Who can I add to this
   * server" is only your friends - adding somebody to a server puts them in a
   * room and notifies them, so it is not a thing to do to a stranger, and
   * `server-service` refuses it either way. `friendsOnly` is which question is
   * being asked; the refusal is the rule and this is the courtesy of not
   * offering what will be refused.
   */
  async search(userId: string, query: string, friendsOnly = false): Promise<UserSummary[]> {
    const term = query.trim();
    if (term.length < 2) return [];

    const friendIds = friendsOnly ? await friendIdsOf(userId) : null;
    // Nobody to search: an empty `in` matches everything on some backends, so
    // it is answered here rather than handed to the query.
    if (friendIds?.length === 0) return [];

    // Blocked in either direction is not findable. Both halves matter and for
    // different reasons: somebody this account blocked should not reappear in
    // the box it just removed them from, and somebody who blocked *it* must not
    // be reachable by typing their name in again.
    const hidden = await blockedIdsAround(userId);
    const visibleFriendIds = friendIds?.filter((id) => !hidden.has(id));
    if (visibleFriendIds?.length === 0) return [];

    const rows = await prisma.user.findMany({
      where: {
        id: visibleFriendIds
          ? { in: visibleFriendIds }
          : { not: userId, ...(hidden.size > 0 ? { notIn: [...hidden] } : {}) },
        disabledAt: null,
        OR: [
          { username: { contains: term, mode: 'insensitive' } },
          { displayName: { contains: term, mode: 'insensitive' } },
        ],
      },
      select: {
        id: true,
        username: true,
        displayName: true,
        avatarUrl: true,
        coverUrl: true,
        about: true,
      },
      orderBy: { username: 'asc' },
      take: SEARCH_LIMIT,
    });
    return rows.map(toSummary);
  }

  /** Accepted friends and pending requests in both directions, one list. */
  async list(userId: string): Promise<Friend[]> {
    const rows = await prisma.friendship.findMany({
      where: { OR: [{ userAId: userId }, { userBId: userId }] },
      include: { userA: true, userB: true },
      orderBy: { updatedAt: 'desc' },
    });

    return rows.map((row) => {
      const other = row.userAId === userId ? row.userB : row.userA;
      const status = row.status as FriendshipStatus;
      return {
        user: toSummary(other),
        status,
        direction:
          status === 'ACCEPTED' ? null : row.requesterId === userId ? 'outgoing' : 'incoming',
        since: row.updatedAt.toISOString(),
      };
    });
  }

  /**
   * Sends a request, or accepts one that was already waiting - if they asked
   * first and you ask back, the obvious reading is yes.
   */
  async request(userId: string, username: string): Promise<Friend> {
    const target = await prisma.user.findUnique({ where: { username: username.trim() } });
    if (!target || target.disabledAt !== null) {
      throw new NotFoundException({ code: 'USER_NOT_FOUND', message: 'No such user' });
    }
    if (target.id === userId) {
      throw new BadRequestException({
        code: 'CANNOT_FRIEND_SELF',
        message: 'You are already your own company',
      });
    }

    // Same answer whichever way the block runs. Telling the sender "they have
    // blocked you" would make the request form a way to test for it, which is
    // the one thing the person who blocked them was trying to stop.
    if (await isBlockedBetween(userId, target.id)) {
      throw new NotFoundException({ code: 'USER_NOT_FOUND', message: 'No such user' });
    }

    const [userAId, userBId] = orderedPair(userId, target.id);
    const existing = await prisma.friendship.findUnique({
      where: { userAId_userBId: { userAId, userBId } },
    });

    if (existing?.status === 'ACCEPTED') return this.friendOf(userId, existing.id);
    if (existing) {
      // They asked first and this is the answer, so it is an acceptance -
      // which is a different notification from a request, and the far side
      // has already been told about the request.
      const answering = existing.requesterId !== userId;
      if (answering) {
        await prisma.friendship.update({
          where: { id: existing.id },
          data: { status: 'ACCEPTED' },
        });
      }
      await this.announce(userId, target.id, answering ? 'accepted' : 'requested');
      return this.friendOf(userId, existing.id);
    }

    const created = await prisma.friendship.create({
      data: { userAId, userBId, requesterId: userId, status: 'PENDING' },
    });
    await this.announce(userId, target.id, 'requested');
    return this.friendOf(userId, created.id);
  }

  /** Only the side that did not ask may accept. */
  async accept(userId: string, otherUserId: string): Promise<Friend> {
    const friendship = await this.require(userId, otherUserId);
    if (friendship.status === 'ACCEPTED') return this.friendOf(userId, friendship.id);
    if (friendship.requesterId === userId) {
      throw new ForbiddenException({
        code: 'CANNOT_ACCEPT_OWN_REQUEST',
        message: 'Wait for them to accept',
      });
    }

    await prisma.friendship.update({ where: { id: friendship.id }, data: { status: 'ACCEPTED' } });
    await this.announce(userId, otherUserId, 'accepted');
    return this.friendOf(userId, friendship.id);
  }

  /** Declining, cancelling and unfriending are all "there is no relationship". */
  async remove(userId: string, otherUserId: string): Promise<void> {
    const friendship = await this.require(userId, otherUserId);
    await prisma.friendship.delete({ where: { id: friendship.id } });
    await this.announce(userId, otherUserId, 'removed');
  }

  /**
   * Tells both sides to reload their list. The event carries no `Friend` of its
   * own because the DTO is written from the reader's side - direction, and who
   * asked - so one payload cannot serve both of them.
   *
   * `kind` is the half a notification needs and a screen refresh does not.
   * Omitting it says "reload", which is all a DM channel appearing is: nothing
   * about the friendship changed, so nobody's phone should buzz about it.
   */
  private async announce(
    userId: string,
    otherUserId: string,
    kind?: 'requested' | 'accepted' | 'removed',
  ): Promise<void> {
    await this.events.publish(EVENTS.FRIEND_CHANGED, {
      userIds: [userId, otherUserId],
      actorId: userId,
      kind,
    });
  }

  /** Everyone this account has blocked, most recent first. */
  async blocked(userId: string): Promise<BlockedUser[]> {
    const rows = await prisma.userBlock.findMany({
      where: { blockerId: userId },
      include: { blocked: true },
      orderBy: { createdAt: 'desc' },
    });
    return rows.map((row) => ({
      user: toSummary(row.blocked),
      blockedAt: row.createdAt.toISOString(),
    }));
  }

  /**
   * Blocks somebody, and ends whatever relationship there was.
   *
   * The friendship goes with it rather than being left in place, because a
   * blocked friend is a contradiction the rest of the app has no rendering
   * for: they would sit in the friend list with a conversation that answers
   * 404. The direct message channel is *not* deleted - it holds both people's
   * history, and one of them deciding to stop talking is not a reason to take
   * the other's copy away. `resolveChannelAccess` closes it for both while the
   * block stands, and unblocking opens the same channel again.
   */
  async block(userId: string, otherUserId: string): Promise<BlockedUser> {
    if (userId === otherUserId) {
      throw new BadRequestException({
        code: 'CANNOT_BLOCK_SELF',
        message: 'You cannot block yourself',
      });
    }
    const target = await prisma.user.findUnique({ where: { id: otherUserId } });
    if (!target) throw new NotFoundException({ code: 'USER_NOT_FOUND', message: 'No such user' });

    const [userAId, userBId] = orderedPair(userId, otherUserId);
    // One transaction: a block that landed without the friendship going with it
    // leaves exactly the contradiction above, and the window for it is a
    // request in flight rather than something rare.
    const row = await prisma.$transaction(async (tx) => {
      await tx.friendship.deleteMany({ where: { userAId, userBId } });
      return tx.userBlock.upsert({
        where: { blockerId_blockedId: { blockerId: userId, blockedId: otherUserId } },
        create: { blockerId: userId, blockedId: otherUserId },
        update: {},
      });
    });

    // Both sides reload. The far side is not told *why* their friend list got
    // shorter - it is the same event an ordinary removal sends.
    await this.announce(userId, otherUserId, 'removed');
    return { user: toSummary(target), blockedAt: row.createdAt.toISOString() };
  }

  /** Lifts a block. It does not restore the friendship the block ended. */
  async unblock(userId: string, otherUserId: string): Promise<void> {
    const { count } = await prisma.userBlock.deleteMany({
      where: { blockerId: userId, blockedId: otherUserId },
    });
    if (count === 0) {
      throw new NotFoundException({ code: 'BLOCK_NOT_FOUND', message: 'They are not blocked' });
    }
    await this.announce(userId, otherUserId, 'removed');
  }

  /** Direct message channels this user is part of, most recent first. */
  async directChannels(userId: string): Promise<DirectChannel[]> {
    const channels = await prisma.channel.findMany({
      where: { type: 'DM', members: { some: { userId } } },
      include: { members: { include: { user: true } } },
      orderBy: { createdAt: 'desc' },
    });

    // A conversation closed by a block is dropped from the list rather than
    // left in it to answer 404 when it is clicked. The rows are untouched: the
    // channel comes back, with its history, the moment the block is lifted.
    const hidden = await blockedIdsAround(userId);

    return channels
      .map((channel) => {
        const other = channel.members.find((member) => member.userId !== userId);
        if (!other || hidden.has(other.userId)) return null;
        return {
          channelId: channel.id,
          participant: toSummary(other.user),
          createdAt: channel.createdAt.toISOString(),
        };
      })
      .filter((channel): channel is DirectChannel => channel !== null);
  }

  /**
   * Opens the conversation with a friend, or returns the one that is already
   * open. Friendship is the gate: without it the search endpoint would be a way
   * to put a message in front of anyone at all.
   */
  async openDirectChannel(userId: string, otherUserId: string): Promise<DirectChannel> {
    if (await isBlockedBetween(userId, otherUserId)) {
      throw new NotFoundException({ code: 'USER_NOT_FOUND', message: 'No such user' });
    }
    const friendship = await this.require(userId, otherUserId);
    if (friendship.status !== 'ACCEPTED') {
      throw new ForbiddenException({
        code: 'NOT_FRIENDS',
        message: 'You can only message an accepted friend',
      });
    }

    const existing = await prisma.channel.findFirst({
      where: {
        type: 'DM',
        AND: [{ members: { some: { userId } } }, { members: { some: { userId: otherUserId } } }],
      },
      include: { members: { include: { user: true } } },
    });

    const channel =
      existing ??
      (await prisma.channel.create({
        data: {
          // A DM has no server, and its name is never shown - the other person's
          // name is what the client puts in the header.
          serverId: null,
          name: `dm-${userId.slice(0, 8)}-${otherUserId.slice(0, 8)}`,
          type: 'DM',
          isPrivate: true,
          members: { create: [{ userId }, { userId: otherUserId }] },
        },
        include: { members: { include: { user: true } } },
      }));

    const other = channel.members.find((member) => member.userId !== userId);
    if (!other) {
      throw new NotFoundException({ code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
    }
    // A conversation opened from one side has to appear on the other, or the
    // first message arrives in a channel that client has never heard of.
    if (!existing) await this.announce(userId, otherUserId);

    return {
      channelId: channel.id,
      participant: toSummary(other.user),
      createdAt: channel.createdAt.toISOString(),
    };
  }

  private async require(
    userId: string,
    otherUserId: string,
  ): Promise<{ id: string; status: string; requesterId: string }> {
    const [userAId, userBId] = orderedPair(userId, otherUserId);
    const friendship = await prisma.friendship.findUnique({
      where: { userAId_userBId: { userAId, userBId } },
      select: { id: true, status: true, requesterId: true },
    });
    if (!friendship) {
      throw new NotFoundException({
        code: 'FRIENDSHIP_NOT_FOUND',
        message: 'No request or friendship with that user',
      });
    }
    return friendship;
  }

  private async friendOf(userId: string, friendshipId: string): Promise<Friend> {
    const row = await prisma.friendship.findUniqueOrThrow({
      where: { id: friendshipId },
      include: { userA: true, userB: true },
    });
    const other = row.userAId === userId ? row.userB : row.userA;
    const status = row.status as FriendshipStatus;
    return {
      user: toSummary(other),
      status,
      direction: status === 'ACCEPTED' ? null : row.requesterId === userId ? 'outgoing' : 'incoming',
      since: row.updatedAt.toISOString(),
    };
  }
}

/** Lower id first, so one pair is one row however the request was made. */
function orderedPair(left: string, right: string): [string, string] {
  return left < right ? [left, right] : [right, left];
}

function toSummary(row: UserRow): UserSummary {
  return {
    id: row.id,
    username: row.username,
    displayName: row.displayName,
    avatarUrl: row.avatarUrl,
    coverUrl: row.coverUrl,
    about: row.about,
  };
}

/**
 * "VILEN is here."
 *
 * A server's member list is a screen somebody has to go and look at, so joining
 * used to be invisible: the first anyone knew of a new person was a message
 * from a name they had never seen. Discord's answer is the right one and this
 * is it - the conversation itself notes the arrival, in place, at the moment it
 * happened, so scrolling back tells you who turned up and when.
 *
 * It lives in chat-service rather than in server-service, which owns the
 * membership, for one reason: a row in a conversation is this service's, and so
 * is the `message.created` fan-out that puts it on everybody's screen. The
 * membership change arrives as an event like any other.
 *
 * Nothing here is encrypted, and nothing here needs to be. The row carries no
 * body at all: `kind` says what happened and `author` says who it happened to,
 * and both are facts the server already holds - it wrote the membership row a
 * moment ago. The sentence is the client's, which is also why it is in the
 * reader's language rather than in this file's.
 */
import { Injectable, OnModuleInit } from '@nestjs/common';
import { prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import { toMessage } from './messages.service';

@Injectable()
export class ArrivalsService implements OnModuleInit {
  constructor(
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  async onModuleInit(): Promise<void> {
    await this.events.subscribe(EVENTS.SERVER_MEMBER_ADDED, (envelope) => {
      const { serverId, userId } = envelope.payload;
      void this.announce(serverId, userId).catch((error: unknown) => {
        // A greeting that could not be written is not worth failing a join
        // over. They are in the server either way, which is the part that
        // mattered.
        this.logger.warn('Could not note an arrival', {
          serverId,
          userId,
          error: error instanceof Error ? error.message : String(error),
        });
      });
    });
  }

  /**
   * Where the line goes: the channel the server has had longest.
   *
   * Which is `#general` on a server nobody has rearranged, and on one that has
   * been rearranged it is still the channel everybody can see - it predates the
   * private ones, and a private one is exactly where an arrival must not be
   * announced. A voice channel has no history to put it in.
   */
  private async announce(serverId: string, userId: string): Promise<void> {
    const channel = await prisma.channel.findFirst({
      where: { serverId, type: 'TEXT', isPrivate: false },
      orderBy: { createdAt: 'asc' },
      select: { id: true },
    });
    if (!channel) return;

    // Said once. A membership event can be republished - a retry, two replicas
    // reading the same message - and a conversation that says somebody arrived
    // four times is worse than one that never said so.
    const already = await prisma.message.findFirst({
      where: { channelId: channel.id, authorId: userId, kind: 'MEMBER_JOIN' },
      select: { id: true },
    });
    if (already) return;

    const row = await prisma.message.create({
      data: { channelId: channel.id, authorId: userId, kind: 'MEMBER_JOIN', content: '' },
      include: { author: true, deletedBy: true, reactions: true, views: true },
    });

    await this.events.publish(EVENTS.MESSAGE_CREATED, { message: toMessage(row) });
  }
}

/**
 * Self-check: the cut-off two "clear" markers agree on.
 *
 * `laterOf` is four lines and one of them is a trap. Null here means "nothing
 * was ever cleared", not "cleared at the beginning of time" - and those are the
 * opposite answers: the first hides nothing, the second hides everything. A
 * `Math.max` over two nullable dates gets it exactly wrong, silently, and the
 * symptom is an empty conversation nobody can explain.
 *
 * The other half is precedence. Two markers exist because they answer different
 * questions - one write on the account for "clear everything", one write on the
 * row that already exists per (user, channel) for "clear this one" - and
 * neither subsumes the other. Later always wins, in both orders.
 */
import assert from 'node:assert/strict';
import { laterOf } from './messages.service';

const older = new Date('2026-01-01T00:00:00.000Z');
const newer = new Date('2026-06-01T00:00:00.000Z');

// Nothing cleared anywhere: no floor at all. This is every account today, and
// getting it wrong empties every conversation on the deployment.
assert.equal(laterOf(null, null), null);

// One marker set is that marker, whichever side it is on.
assert.equal(laterOf(older, null), older);
assert.equal(laterOf(null, older), older);

// Both set: the later one, in both orders.
assert.equal(laterOf(older, newer), newer);
assert.equal(laterOf(newer, older), newer);

// Equal instants: still a cut-off, and not null. "Clear everything" and "clear
// this conversation" landing in the same millisecond is not two people
// disagreeing, it is one answer said twice.
const same = new Date(newer);
assert.equal(laterOf(newer, same)?.getTime(), newer.getTime());

// The epoch is a real cut-off, not an absent one. `0` is falsy and a truthiness
// check here would read a genuine clear as "never cleared".
const epoch = new Date(0);
assert.equal(laterOf(epoch, null), epoch);
assert.equal(laterOf(epoch, newer), newer);

console.log('chat-service cleared check ok');

/**
 * Destroys messages whose disappearing window has closed.
 *
 * The window itself is a server's setting and is stamped onto each message as
 * it is sent (`Message.expiresAt`), so this pass has nothing to decide: it
 * collects whatever is past its own stamp. That is what makes changing a
 * server's window safe - it governs what is sent next, and never reaches back
 * through a channel to condemn what is already in it.
 *
 * The row is deleted rather than tombstoned, unlike an ordinary delete. A
 * conversation that fills up with "this message was deleted" for every message
 * that ever aged out is not a disappearing conversation; it is a conversation
 * with a very detailed index of what used to be in it.
 *
 * Blobs go first and by the same rule as everywhere else: the object before
 * the row, so a failure leaves something the attachment sweeper will collect
 * rather than something nothing can ever name again.
 *
 * ponytail: a timer in the process, like the two upload sweeps beside it. Two
 * replicas will overlap; the delete of an already-deleted row is a no-op and
 * the second one simply finds nothing.
 */
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import { purgeMessageAttachments } from '../uploads/attachment-sweeper';

/**
 * How often to look.
 *
 * A minute, where the upload sweeps run every six hours, and the difference is
 * what the two are for. A stray blob costs disk. A message that outlives its
 * window is the feature not working, and the shortest window on offer is an
 * hour - so a minute is a rounding error against it and is still one small
 * indexed query per replica per minute.
 */
const INTERVAL_MS = 60_000;

/** Not at boot: a service starting is the worst moment to add database work. */
const FIRST_RUN_DELAY_MS = 30_000;

/** How many one pass destroys, so a backlog is spread rather than dropped at once. */
const BATCH = 200;

/** Which rows a pass takes. Kept out of the sweep so it can be asserted on. */
export function expiredWhere(now: Date = new Date()): { expiresAt: { lte: Date } } {
  return { expiresAt: { lte: now } };
}

/**
 * Destroys what is past its window and returns how many went.
 *
 * The event per message is deliberate and is the point of doing this on the
 * server at all: a client that is on screen when the window closes has the
 * plaintext in memory and would happily keep drawing it. It is told to forget.
 */
export async function sweepExpired(events: EventBus, now: Date = new Date()): Promise<number> {
  const doomed = await prisma.message.findMany({
    where: expiredWhere(now),
    select: { id: true, channelId: true },
    orderBy: { expiresAt: 'asc' },
    take: BATCH,
  });
  if (doomed.length === 0) return 0;

  await purgeMessageAttachments(doomed.map((row) => row.id));
  await prisma.message.deleteMany({ where: { id: { in: doomed.map((row) => row.id) } } });

  for (const row of doomed) {
    await events.publish(EVENTS.MESSAGE_DELETED, {
      messageId: row.id,
      channelId: row.channelId,
      // No tombstone: a disappearing message that leaves a permanent marker
      // saying something was here has not disappeared.
      message: null,
    });
  }
  return doomed.length;
}

@Injectable()
export class DisappearingSweeper implements OnModuleInit, OnModuleDestroy {
  private timer: NodeJS.Timeout | null = null;
  private first: NodeJS.Timeout | null = null;

  constructor(
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  onModuleInit(): void {
    this.first = setTimeout(() => {
      void this.run();
      this.timer = setInterval(() => void this.run(), INTERVAL_MS);
      this.timer.unref?.();
    }, FIRST_RUN_DELAY_MS);
    this.first.unref?.();
  }

  private async run(): Promise<void> {
    try {
      const removed = await sweepExpired(this.events);
      if (removed > 0) this.logger.info('Swept expired messages', { removed });
    } catch (error) {
      this.logger.warn('Could not sweep expired messages', { reason: String(error) });
    }
  }

  onModuleDestroy(): void {
    if (this.first) clearTimeout(this.first);
    if (this.timer) clearInterval(this.timer);
  }
}

/**
 * What a disappearing window means, in the two places it is decided.
 *
 * Both are arithmetic that is invisible until it is wrong, and both fail in
 * the same expensive direction: an inverted comparison in the sweep destroys
 * every message the moment it is sent, and an accepted off-list window lets a
 * hand-edited row set a three-second retention nobody's client can undo.
 */
import assert from 'node:assert/strict';
import { DISAPPEARING_WINDOWS, disappearingWindowLabel, isDisappearingWindow } from '@betweenus/shared-types';
import { expiredWhere } from './disappearing-sweeper';

const now = new Date('2026-08-29T12:00:00.000Z');

// The sweep takes what is already past its stamp, and nothing that is not.
const where = expiredWhere(now);
assert.deepEqual(where, { expiresAt: { lte: now } });
assert.ok(where.expiresAt.lte <= now, 'the cutoff is now: a message stamped for tomorrow survives');

// Null never matches `lte`, so a message with no window is never collected -
// which is the whole of "off" and is worth stating rather than assuming.
assert.equal(Object.keys(where).length, 1, 'nothing else narrows the sweep');

// Only the published windows are settable. `null` is off and is always allowed.
assert.ok(isDisappearingWindow(null));
assert.ok(isDisappearingWindow(undefined));
for (const seconds of DISAPPEARING_WINDOWS) assert.ok(isDisappearingWindow(seconds));
assert.ok(!isDisappearingWindow(3), 'a three-second window is not on the list');
assert.ok(!isDisappearingWindow(86_401), 'nearly a day is not a day');
assert.ok(!isDisappearingWindow(-86_400), 'a window cannot run backwards');

// The list is ordered shortest to longest: every picker renders it in order.
const ordered = [...DISAPPEARING_WINDOWS].sort((left, right) => left - right);
assert.deepEqual([...DISAPPEARING_WINDOWS], ordered);

// One spelling per window, so three clients cannot disagree about what "8h" is.
assert.equal(disappearingWindowLabel(null), 'Off');
assert.equal(disappearingWindowLabel(86_400), '24 hours');
assert.equal(disappearingWindowLabel(604_800), '7 days');

console.log('disappearing: ok');

import {
  ArrayMaxSize,
  IsArray,
  IsBoolean,
  IsOptional,
  IsString,
  IsUUID,
  Length,
} from 'class-validator';
import { MAX_MESSAGE_CONTENT_LENGTH } from '@betweenus/shared-types';
import type {
  ClearChatsRequest,
  CreateMessageRequest,
  ReactToMessageRequest,
  UpdateMessageRequest,
} from '@betweenus/shared-types';

export class CreateMessageDto implements CreateMessageRequest {
  @IsUUID()
  channelId!: string;

  /**
   * Ciphertext envelope, not plaintext - see development/E2EE.md. The ceiling
   * is generous because the envelope also carries the attachment manifest:
   * a key, a name, a size and a content type per file, all encrypted.
   */
  @IsString()
  @Length(1, MAX_MESSAGE_CONTENT_LENGTH)
  content!: string;

  /**
   * Which uploaded blobs this message claims. Only keys this account uploaded
   * and nothing else has claimed are taken; anything else is ignored rather
   * than refused, because a message is not worth failing over a stale key.
   */
  @IsOptional()
  @IsArray()
  @ArrayMaxSize(50)
  @IsString({ each: true })
  attachmentKeys?: string[];

  /**
   * Send this as a one-time message: its media may be opened once by somebody
   * other than the author, and that opening destroys the row and its blobs.
   *
   * The one thing about a message the server is told in the clear besides who
   * sent it and when, and it has to be: burning is a row update and a blob
   * delete, neither of which a server that cannot read the body can be asked
   * to do by the body.
   */
  @IsOptional()
  @IsBoolean()
  viewOnce?: boolean;
}

export class UpdateMessageDto implements UpdateMessageRequest {
  /** The replacement envelope, same shape and same ceiling as the original. */
  @IsString()
  @Length(1, MAX_MESSAGE_CONTENT_LENGTH)
  content!: string;
}

export class ReactToMessageDto implements ReactToMessageRequest {
  /**
   * The emoji itself. The service checks it further - no whitespace, and short
   * enough to be one symbol rather than a paragraph.
   */
  @IsString()
  @Length(1, 32)
  emoji!: string;
}

export class MessageQueryDto {
  @IsUUID()
  channelId!: string;

  /** Message id to page backwards from. */
  @IsOptional()
  @IsUUID()
  before?: string;
}

export class PinQueryDto {
  @IsUUID()
  channelId!: string;
}

/**
 * What to clear. An absent or null `channelId` means every conversation, which
 * is what an older client that sends no body at all also means.
 */
export class ClearChatsDto implements ClearChatsRequest {
  @IsOptional()
  @IsUUID()
  channelId?: string | null;
}

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  ClearChatsResponse,
  LinkPreview,
  Message,
  Paginated,
} from '@betweenus/shared-types';
import { MessagesService } from './messages.service';
import { UnfurlService } from './unfurl.service';
import {
  ClearChatsDto,
  CreateMessageDto,
  MessageQueryDto,
  PinQueryDto,
  ReactToMessageDto,
  UpdateMessageDto,
} from './dto';

@Controller('messages')
@UseGuards(JwtAuthGuard)
export class MessagesController {
  constructor(
    private readonly messages: MessagesService,
    private readonly unfurlService: UnfurlService,
  ) {}

  @Get()
  history(
    @CurrentUser() user: AuthenticatedUser,
    @Query() query: MessageQueryDto,
  ): Promise<Paginated<Message>> {
    return this.messages.history(user.id, query.channelId, query.before);
  }

  // Ahead of `:messageId` routes, or `unfurl` is read as a message id.
  @Get('unfurl')
  unfurl(@Query('url') targetUrl?: string): Promise<LinkPreview | null> {
    if (!targetUrl) return Promise.resolve(null);
    return this.unfurlService.unfurl(targetUrl);
  }

  // Ahead of `:messageId` routes, or `pins` is read as a message id.
  @Get('pins')
  pins(
    @CurrentUser() user: AuthenticatedUser,
    @Query() query: PinQueryDto,
  ): Promise<Message[]> {
    return this.messages.pins(user.id, query.channelId);
  }

  /**
   * Hides this account's own history: one conversation when `channelId` is
   * given, every one of them when it is not. Ahead of `:messageId`, or `clear`
   * is read as a message id.
   */
  @Post('clear')
  @HttpCode(200)
  clear(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: ClearChatsDto,
  ): Promise<ClearChatsResponse> {
    return this.messages.clearChats(user.id, dto.channelId);
  }

  @Post()
  send(@CurrentUser() user: AuthenticatedUser, @Body() dto: CreateMessageDto): Promise<Message> {
    return this.messages.send(
      user.id,
      dto.channelId,
      dto.content,
      dto.attachmentKeys,
      dto.viewOnce,
    );
  }

  @Patch(':messageId')
  edit(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
    @Body() dto: UpdateMessageDto,
  ): Promise<Message> {
    return this.messages.edit(user.id, messageId, dto.content);
  }

  @Delete(':messageId')
  @HttpCode(204)
  remove(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<void> {
    return this.messages.remove(user.id, messageId);
  }

  /**
   * Spends a one-time message: the caller has opened its media, so it goes.
   *
   * A POST rather than the DELETE it resembles, because the caller is usually
   * not allowed to delete this message and is not claiming to be - they are
   * reporting that they looked at it, and the destruction is the server's
   * consequence rather than their request. 204 either way: a message already
   * burned by somebody else is not an error to whoever arrived second.
   */
  @Post(':messageId/burn')
  @HttpCode(204)
  burn(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<void> {
    return this.messages.burn(user.id, messageId);
  }

  @Put(':messageId/pin')
  pin(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<Message> {
    return this.messages.setPinned(user.id, messageId, true);
  }

  @Delete(':messageId/pin')
  unpin(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<Message> {
    return this.messages.setPinned(user.id, messageId, false);
  }

  /** One route for both directions: reacting with what you already chose undoes it. */
  @Post(':messageId/reactions')
  react(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
    @Body() dto: ReactToMessageDto,
  ): Promise<Message> {
    return this.messages.react(user.id, messageId, dto.emoji);
  }
}

import { BadRequestException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
import {
  channelAudience,
  prisma,
  resolveChannelAccess,
  type ChannelAccess,
} from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { PERMISSIONS, type Permission } from '@betweenus/permissions';
import {
  isDisappearingWindow,
  MAX_MESSAGE_CONTENT_LENGTH,
  type ClearChatsResponse,
  type Message,
  type MessageKind,
  type MessageReactionSummary,
  type Paginated,
} from '@betweenus/shared-types';
import { purgeMessageAttachments } from '../uploads/attachment-sweeper';

const PAGE_SIZE = 50;
/**
 * Content is an encrypted envelope, so the limit has to cover the attachment
 * manifest riding inside it as well as the words, and base64 on top of both.
 * Shared with the DTO so the two ceilings cannot drift apart again - they did,
 * and a message carrying ten pictures was refused by the lower of them.
 */
const MAX_CONTENT_LENGTH = MAX_MESSAGE_CONTENT_LENGTH;
/**
 * An emoji is a handful of code points - a base, a skin tone, a zero-width
 * joiner, a variation selector. The cap is on the string, not on how many
 * characters a human would count, and it exists so the column cannot be used as
 * free storage.
 */
const MAX_EMOJI_LENGTH = 32;
/** How many distinct people's reactions one message may carry. */
const MAX_REACTIONS_PER_MESSAGE = 200;

/**
 * How long a one-time message lives when nobody finishes opening it.
 *
 * It is normally destroyed the moment its last recipient has looked, but that
 * is a condition that may never arrive - one member of a channel who never
 * opens theirs would keep the ciphertext for ever. A week is long enough that
 * nobody loses a message they meant to open and short enough that an
 * unopened one is not indefinite storage.
 *
 * Never longer than a window the server itself set: a backstop that extended
 * a retention policy would be the opposite of one.
 */
const ONE_TIME_BACKSTOP_SECONDS = 7 * 24 * 60 * 60;

/**
 * The later of two cut-offs, treating null as "no cut-off at all" rather than
 * as the beginning of time - which is the difference between hiding nothing and
 * hiding everything.
 */
export function laterOf(left: Date | null, right: Date | null): Date | null {
  if (left === null) return right;
  if (right === null) return left;
  return left.getTime() >= right.getTime() ? left : right;
}

/**
 * Who still has a look coming, given a channel's audience and who has used
 * theirs.
 *
 * Split out from the database call so the policy can be asserted on without
 * one - it is the whole of the fix for "the first person to open it destroyed
 * it for everybody", and it is arithmetic over two lists.
 *
 * The author is never owed a look: re-reading what you sent spends nothing.
 * An audience of nobody but the author owes nothing either, which matters for
 * a channel emptied since the message was sent - holding ciphertext for a
 * recipient who no longer exists helps nobody.
 */
export function looksOwed(
  audience: string[],
  viewedBy: string[],
  authorId: string,
): string[] {
  const looked = new Set(viewedBy);
  return audience.filter((member) => member !== authorId && !looked.has(member));
}

/** Everything a `Message` is built from, in one place so every path agrees. */
const MESSAGE_INCLUDE = {
  author: true,
  deletedBy: true,
  reactions: { select: { userId: true, emoji: true } },
  views: { select: { userId: true } },
  // Only the three fields a client draws. `select` rather than `true`, because
  // the row also carries the token hash and every history page would otherwise
  // read it out of the database for no reason.
  webhook: { select: { id: true, name: true, avatarUrl: true } },
} as const;

@Injectable()
export class MessagesService {
  constructor(private readonly events: EventBus) {}

  /**
   * Newest-first page of a channel's history. `before` is a message id; the
   * cursor is opaque to the client.
   *
   * Deleted messages are included as tombstones - the body is already empty in
   * the database, and a conversation that silently closes over a removed
   * message is harder to follow than one that says something was here.
   */
  async history(userId: string, channelId: string, before?: string): Promise<Paginated<Message>> {
    await this.requireChannelAccess(userId, channelId, PERMISSIONS.VIEW_CHANNEL);

    const cursor = before
      ? await prisma.message.findUnique({ where: { id: before }, select: { createdAt: true } })
      : null;

    const clearedAt = await this.historyFloor(userId, channelId);
    const rows = await prisma.message.findMany({
      where: {
        channelId,
        ...(cursor || clearedAt
          ? {
              createdAt: {
                ...(cursor ? { lt: cursor.createdAt } : {}),
                ...(clearedAt ? { gt: clearedAt } : {}),
              },
            }
          : {}),
      },
      include: MESSAGE_INCLUDE,
      orderBy: { createdAt: 'desc' },
      take: PAGE_SIZE,
    });

    const items = rows.map(toMessage).reverse();
    const oldest = rows[rows.length - 1];
    return {
      items,
      nextCursor: rows.length === PAGE_SIZE && oldest ? oldest.id : null,
    };
  }

  /** Pinned messages of one channel, most recently pinned first. */
  async pins(userId: string, channelId: string): Promise<Message[]> {
    await this.requireChannelAccess(userId, channelId, PERMISSIONS.VIEW_CHANNEL);

    const clearedAt = await this.historyFloor(userId, channelId);
    const rows = await prisma.message.findMany({
      where: {
        channelId,
        pinnedAt: { not: null },
        deletedAt: null,
        ...(clearedAt ? { createdAt: { gt: clearedAt } } : {}),
      },
      include: MESSAGE_INCLUDE,
      orderBy: { pinnedAt: 'desc' },
      take: 100,
    });
    return rows.map(toMessage);
  }

  /**
   * Hides everything this account can currently see, everywhere, on every one
   * of its devices.
   *
   * Nothing is deleted. It cannot be: a message has two ends, the other one is
   * somebody else's history, and a button on this side that reached across and
   * took it away would be a different feature with a different name. What this
   * does is move one marker on the account, which every read path already
   * respects - so the other participant's view is untouched and this account's
   * phone, laptop and browser all agree without any of them being told
   * individually what to forget.
   *
   * "Everything it can currently see" and not "everything up to now": the cut
   * is stamped at the moment of the call, so a message that arrives a second
   * later is new mail rather than something the button quietly ate.
   */
  async clearChats(userId: string, channelId?: string | null): Promise<ClearChatsResponse> {
    const clearedAt = new Date();

    if (channelId) {
      // The same 404-for-both rule every other channel route follows, so a
      // stranger cannot use this to find out which channel ids exist.
      await this.requireChannelAccess(userId, channelId, PERMISSIONS.VIEW_CHANNEL);
      // The marker sits on the read row, which may not exist yet - somebody can
      // clear a conversation they have never opened on this device.
      await prisma.channelRead.upsert({
        where: { userId_channelId: { userId, channelId } },
        create: { userId, channelId, clearedAt },
        update: { clearedAt },
      });
    } else {
      await prisma.user.update({ where: { id: userId }, data: { chatsClearedAt: clearedAt } });
    }

    // The other devices are holding decrypted copies in their own caches, which
    // no refetch would clear - so this is carried rather than announced.
    await this.events.publish(EVENTS.CHATS_CLEARED, {
      userId,
      clearedAt: clearedAt.toISOString(),
      channelId: channelId ?? null,
    });
    return { clearedAt: clearedAt.toISOString(), channelId: channelId ?? null };
  }

  /**
   * This account's cut-off in this conversation: whichever of the two markers
   * is later, or null when it has never cleared anything.
   *
   * Two markers and not one because they answer different questions and neither
   * subsumes the other. "Clear everything" is one write on the account rather
   * than a fan-out over every channel; "clear this conversation" is one write
   * on the row that already exists per (user, channel). Later wins, so clearing
   * everything and then clearing one conversation again does the obvious thing,
   * and so does the reverse.
   *
   * The third marker is this account's personal disappearing window, which is
   * the same kind of thing in a different shape: not a moment somebody chose,
   * but one that slides forward with the clock. It belongs here rather than in
   * a filter of its own precisely because it is one-sided - a personal window
   * hides history from its owner and from nobody else, which is exactly what
   * these two markers already do. The server's own window is not here at all:
   * that one deletes the rows, so there is nothing left to filter.
   *
   * ponytail: two lookups per history page, both primary-key reads. Fold them
   * into the access check's query if a profiler ever says otherwise.
   */
  private async historyFloor(userId: string, channelId: string): Promise<Date | null> {
    const [account, conversation] = await Promise.all([
      prisma.user.findUnique({
        where: { id: userId },
        select: { chatsClearedAt: true, messageTtlSeconds: true },
      }),
      prisma.channelRead.findUnique({
        where: { userId_channelId: { userId, channelId } },
        select: { clearedAt: true },
      }),
    ]);

    const personal = account?.messageTtlSeconds
      ? new Date(Date.now() - account.messageTtlSeconds * 1000)
      : null;
    return laterOf(
      laterOf(account?.chatsClearedAt ?? null, conversation?.clearedAt ?? null),
      personal,
    );
  }

  /**
   * When a message sent into this channel now should stop existing, or null
   * when nothing says it should.
   *
   * Only the server's window is read. An account's own window is a filter over
   * what it is shown and has no business setting an expiry on somebody else's
   * copy - that asymmetry is the whole difference between the two settings,
   * and it is why the server's outranks the account's rather than the two
   * being combined.
   *
   * A direct message has no server, so it has no window: there is nobody to
   * set one and nobody it would bind.
   */
  private async expiryFor(serverId: string | null, viewOnce = false): Promise<Date | null> {
    const server = serverId
      ? await prisma.server.findUnique({
          where: { id: serverId },
          select: { messageTtlSeconds: true },
        })
      : null;

    const seconds = server?.messageTtlSeconds ?? null;
    // A window that is not on the list is a window somebody wrote into the
    // database by hand. Ignored rather than obeyed: the alternative is
    // honouring a three-second retention nobody's client can offer to undo.
    const configured = seconds && isDisappearingWindow(seconds) ? seconds : null;

    // A one-time message is destroyed when everyone has looked, which is a
    // condition that may never arrive: one member of a channel who never opens
    // theirs keeps the blob for ever. So it also gets a backstop, and the
    // shorter of the two wins - the backstop must never *extend* a window a
    // server actually set.
    const window = viewOnce ? Math.min(configured ?? ONE_TIME_BACKSTOP_SECONDS, ONE_TIME_BACKSTOP_SECONDS) : configured;
    if (!window) return null;
    return new Date(Date.now() + window * 1000);
  }

  async send(
    userId: string,
    channelId: string,
    content: string,
    attachmentKeys: string[] = [],
    viewOnce = false,
  ): Promise<Message> {
    const access = await this.requireChannelAccess(userId, channelId, PERMISSIONS.SEND_MESSAGE);

    const trimmed = content.trim();
    if (trimmed.length === 0 || trimmed.length > MAX_CONTENT_LENGTH) {
      throw new ForbiddenException({
        code: 'INVALID_MESSAGE',
        message: `Message must be 1-${MAX_CONTENT_LENGTH} characters`,
      });
    }

    // Stamped now rather than evaluated on read, so changing a server's window
    // governs what is sent next and never reaches back through the channel.
    const expiresAt = await this.expiryFor(access.serverId, viewOnce);

    const row = await prisma.message.create({
      data: { channelId, authorId: userId, content: trimmed, expiresAt, viewOnce },
      include: MESSAGE_INCLUDE,
    });

    // The blobs become this message's, so deleting it can take them with it.
    // Scoped to unclaimed uploads of this account: a key is not a capability,
    // and naming somebody else's must not move it.
    if (attachmentKeys.length > 0) {
      await prisma.attachment.updateMany({
        where: { key: { in: attachmentKeys.slice(0, 50) }, uploaderId: userId, messageId: null },
        data: { messageId: row.id },
      });
    }

    const message = toMessage(row);
    // The WebSocket gateway - in this process and in every other instance -
    // fans this out to subscribed sockets.
    await this.events.publish(EVENTS.MESSAGE_CREATED, { message });
    return message;
  }

  /**
   * Rewrites the body. The author only - a moderator may remove a message but
   * never put different words in somebody's mouth - and `editedAt` is stamped
   * so every client can say so.
   *
   * The new body replaces the old ciphertext, so an edit is not recoverable
   * from the database. There is no edit history and this build does not pretend
   * to keep one.
   */
  async edit(userId: string, messageId: string, content: string): Promise<Message> {
    const existing = await this.require(messageId);
    await this.requireChannelAccess(userId, existing.channelId, PERMISSIONS.SEND_MESSAGE);

    if (existing.authorId !== userId) {
      throw new ForbiddenException({
        code: 'NOT_MESSAGE_AUTHOR',
        message: 'Only the author can edit a message',
      });
    }

    const trimmed = content.trim();
    if (trimmed.length === 0 || trimmed.length > MAX_CONTENT_LENGTH) {
      throw new BadRequestException({
        code: 'INVALID_MESSAGE',
        message: `Message must be 1-${MAX_CONTENT_LENGTH} characters`,
      });
    }

    const row = await prisma.message.update({
      where: { id: existing.id },
      data: { content: trimmed, editedAt: new Date() },
      include: MESSAGE_INCLUDE,
    });

    const message = toMessage(row);
    await this.events.publish(EVENTS.MESSAGE_UPDATED, { message });
    return message;
  }

  /**
   * Deletes a message. The author may always delete their own; anyone else
   * needs `DELETE_MESSAGE` in that channel, which is what a moderator holds.
   *
   * It is a soft delete: `deletedAt` and, when somebody else did it,
   * `deletedById` are set and the body is emptied. The row stays so the
   * conversation can show a tombstone and so a page cursor handed out a moment
   * ago still points somewhere; the ciphertext does not.
   *
   * The blobs go with it, here and now. They used to be left to the attachment
   * sweeper, which is correct but runs every six hours - so "I deleted that
   * photo" meant "the ciphertext leaves the object store some time today",
   * which is not what anybody pressing delete is asking for. The sweeper is
   * still behind this as the backstop for whatever the immediate delete could
   * not reach.
   */
  async remove(userId: string, messageId: string): Promise<void> {
    const existing = await this.require(messageId);

    const access = await this.requireChannelAccess(
      userId,
      existing.channelId,
      PERMISSIONS.VIEW_CHANNEL,
    );
    const mine = existing.authorId === userId;
    if (!mine && !access.permissions.includes(PERMISSIONS.DELETE_MESSAGE)) {
      throw new ForbiddenException({
        code: 'MISSING_PERMISSION',
        message: 'You can only delete your own messages here',
      });
    }

    const row = await prisma.message.update({
      where: { id: existing.id },
      data: {
        deletedAt: new Date(),
        // Null when the author took their own message back: a client only
        // names the person when it was somebody else.
        deletedById: mine ? null : userId,
        content: '',
        // A deleted message cannot stay pinned, and its reactions go with it.
        pinnedAt: null,
        pinnedById: null,
        reactions: { deleteMany: {} },
      },
      include: MESSAGE_INCLUDE,
    });

    // After the row update, never before: a blob deleted for a message that
    // then failed to delete is a message rendering broken pictures for ever.
    await purgeMessageAttachments([row.id]);

    await this.events.publish(EVENTS.MESSAGE_DELETED, {
      messageId: row.id,
      channelId: row.channelId,
      message: toMessage(row),
    });
  }

  /**
   * Spends one person's look at a one-time message.
   *
   * One look *each*, not one look in total. This used to settle a race with a
   * conditional update on a single `viewedAt`, so the first person to open one
   * in a channel destroyed it and everybody else was shown "Opened" for
   * something they had never seen. That is not a one-time message; it is a
   * race to a message.
   *
   * So a look is a row, and the message survives until the rows cover everyone
   * who could see it. In a direct message that is one person and the behaviour
   * is unchanged; in a channel each member gets the look they were sent.
   *
   * The author is not a viewer. Re-reading what you sent spends nobody's look,
   * and a sender who burned their own message by scrolling past it would find
   * the feature unusable.
   *
   * Idempotent by the unique index on (message, user): opening twice from two
   * devices records one look, so the second one is not silently charged to
   * somebody else.
   */
  async burn(userId: string, messageId: string): Promise<void> {
    const row = await prisma.message.findFirst({
      where: { id: messageId, deletedAt: null },
      select: { id: true, channelId: true, authorId: true, viewOnce: true, viewedAt: true },
    });
    if (!row || !row.viewOnce) {
      throw new NotFoundException({ code: 'MESSAGE_NOT_FOUND', message: 'Message not found' });
    }
    await this.requireChannelAccess(userId, row.channelId, PERMISSIONS.VIEW_CHANNEL);

    // The author looking at their own does not spend anything.
    if (row.authorId === userId) return;

    await prisma.messageView.upsert({
      where: { messageId_userId: { messageId: row.id, userId } },
      create: { messageId: row.id, userId },
      update: {},
    });
    // The stamp the backstop expiry is measured from - the first look, not
    // this one. Written only once, so a slow second viewer cannot extend it.
    if (row.viewedAt === null) {
      await prisma.message.updateMany({
        where: { id: row.id, viewedAt: null },
        data: { viewedAt: new Date() },
      });
    }

    if (await this.everyoneHasLooked(row.id, row.channelId, row.authorId)) {
      await purgeMessageAttachments([row.id]);
      await prisma.message.delete({ where: { id: row.id } });
      await this.events.publish(EVENTS.MESSAGE_DELETED, {
        messageId: row.id,
        channelId: row.channelId,
        message: null,
      });
      return;
    }

    // Still somebody's look left in it. Everyone is told who has spent theirs,
    // so this account's other devices stop offering it and the author can see
    // that it has been opened.
    const updated = await prisma.message.findUniqueOrThrow({
      where: { id: row.id },
      include: MESSAGE_INCLUDE,
    });
    await this.events.publish(EVENTS.MESSAGE_UPDATED, { message: toMessage(updated) });
  }

  /**
   * Whether a one-time message has no looks left in it.
   *
   * "Everyone who could see it" is the channel's audience as it stands now,
   * minus the author. A member who joined after it was sent is deliberately
   * included: they can see the channel, so they can see the card, and a
   * message destroyed before they opened it would be another "Opened" for
   * something never shown.
   *
   * The corollary is that a channel where somebody never opens theirs keeps
   * the blob until the backstop expiry collects it - see `expiryFor`.
   */
  private async everyoneHasLooked(
    messageId: string,
    channelId: string,
    authorId: string,
  ): Promise<boolean> {
    const [audience, looks] = await Promise.all([
      channelAudience(channelId),
      prisma.messageView.findMany({ where: { messageId }, select: { userId: true } }),
    ]);

    return looksOwed(audience, looks.map((look) => look.userId), authorId).length === 0;
  }

  /**
   * Pins or unpins. In a server channel this is `MANAGE_MESSAGE`, because a pin
   * is a claim on everybody's channel header; in a direct message there is no
   * role to hold, so either participant may pin.
   */
  async setPinned(userId: string, messageId: string, pinned: boolean): Promise<Message> {
    const existing = await this.require(messageId);
    const access = await this.requireChannelAccess(
      userId,
      existing.channelId,
      PERMISSIONS.VIEW_CHANNEL,
    );

    if (access.serverId !== null && !access.permissions.includes(PERMISSIONS.MANAGE_MESSAGE)) {
      throw new ForbiddenException({
        code: 'MISSING_PERMISSION',
        message: `Missing permission ${PERMISSIONS.MANAGE_MESSAGE}`,
      });
    }

    const row = await prisma.message.update({
      where: { id: existing.id },
      data: pinned
        ? { pinnedAt: new Date(), pinnedById: userId }
        : { pinnedAt: null, pinnedById: null },
      include: MESSAGE_INCLUDE,
    });

    const message = toMessage(row);
    await this.events.publish(EVENTS.MESSAGE_UPDATED, { message });
    return message;
  }

  /**
   * Adds or removes the caller's reaction. Reacting twice with the same emoji
   * takes it back, which is what every client that has one does.
   *
   * The emoji is stored in the clear - see development/E2EE.md. It is the one
   * part of a message the server can read, and it is documented rather than
   * hidden.
   */
  async react(userId: string, messageId: string, emoji: string): Promise<Message> {
    const existing = await this.require(messageId);
    // Reacting is speaking in the channel, so it takes the same permission.
    await this.requireChannelAccess(userId, existing.channelId, PERMISSIONS.SEND_MESSAGE);

    const symbol = emoji.trim();
    if (symbol.length === 0 || symbol.length > MAX_EMOJI_LENGTH || /\s/.test(symbol)) {
      throw new BadRequestException({
        code: 'INVALID_EMOJI',
        message: 'That is not an emoji',
      });
    }

    const already = await prisma.messageReaction.findUnique({
      where: { messageId_userId_emoji: { messageId: existing.id, userId, emoji: symbol } },
      select: { id: true },
    });

    if (already) {
      await prisma.messageReaction.delete({ where: { id: already.id } });
    } else {
      const total = await prisma.messageReaction.count({ where: { messageId: existing.id } });
      if (total >= MAX_REACTIONS_PER_MESSAGE) {
        throw new BadRequestException({
          code: 'TOO_MANY_REACTIONS',
          message: 'That message has all the reactions it can hold',
        });
      }
      await prisma.messageReaction.create({
        data: { messageId: existing.id, userId, emoji: symbol },
      });
    }

    const row = await prisma.message.findUniqueOrThrow({
      where: { id: existing.id },
      include: MESSAGE_INCLUDE,
    });
    const message = toMessage(row);
    await this.events.publish(EVENTS.MESSAGE_UPDATED, { message });
    return message;
  }

  /**
   * Access is resolved by `@betweenus/database`, which is also what call- and
   * presence-service ask; the three of them used to keep their own copy of this
   * check. A channel the caller cannot see answers 404, not 403, so channel ids
   * cannot be probed for.
   */
  async requireChannelAccess(
    userId: string,
    channelId: string,
    permission: Permission,
  ): Promise<ChannelAccess> {
    const access = await resolveChannelAccess(userId, channelId);
    if (!access) {
      throw new NotFoundException({ code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
    }

    if (!access.permissions.includes(permission)) {
      throw new ForbiddenException({
        code: 'MISSING_PERMISSION',
        message: `Missing permission ${permission}`,
      });
    }
    return access;
  }

  /**
   * A live message, by id. A deleted one is gone as far as every write path is
   * concerned - it cannot be edited, pinned, reacted to or deleted again - and
   * a message in a channel the caller cannot see answers the same 404 as one
   * that never existed, because the access check has not run yet at this point.
   */
  private async require(
    messageId: string,
  ): Promise<{ id: string; channelId: string; authorId: string }> {
    const row = await prisma.message.findFirst({
      where: { id: messageId, deletedAt: null },
      select: { id: true, channelId: true, authorId: true },
    });
    if (!row) {
      throw new NotFoundException({ code: 'MESSAGE_NOT_FOUND', message: 'Message not found' });
    }
    return row;
  }
}

interface MessageRow {
  id: string;
  channelId: string;
  /** Optional so a caller that selected before the column existed still fits. */
  kind?: MessageKind;
  content: string;
  createdAt: Date;
  editedAt: Date | null;
  deletedAt: Date | null;
  pinnedAt: Date | null;
  expiresAt?: Date | null;
  viewOnce?: boolean;
  views?: Array<{ userId: string }>;
  author: {
    id: string;
    username: string;
    displayName: string;
    avatarUrl: string | null;
  };
  deletedBy?: {
    id: string;
    username: string;
    displayName: string;
    avatarUrl: string | null;
  } | null;
  reactions?: Array<{ userId: string; emoji: string }>;
  /**
   * The webhook that posted this, where one did. Optional so a caller that
   * selected before the column existed still fits this shape.
   *
   * `null` on the relation and a name on the row are different things: the
   * relation is `SetNull`, so a deleted webhook leaves its messages behind
   * carrying nothing but a name - see `webhookNameOf`.
   */
  webhookId?: string | null;
  webhook?: { id: string; name: string; avatarUrl: string | null } | null;
}

export function toMessage(row: MessageRow): Message {
  return {
    id: row.id,
    channelId: row.channelId,
    kind: row.kind ?? 'USER',
    content: row.content,
    author: {
      id: row.author.id,
      username: row.author.username,
      displayName: row.author.displayName,
      avatarUrl: row.author.avatarUrl,
    },
    createdAt: row.createdAt.toISOString(),
    editedAt: row.editedAt ? row.editedAt.toISOString() : null,
    deletedAt: row.deletedAt ? row.deletedAt.toISOString() : null,
    deletedBy: row.deletedBy
      ? {
          id: row.deletedBy.id,
          username: row.deletedBy.username,
          displayName: row.deletedBy.displayName,
          avatarUrl: row.deletedBy.avatarUrl,
        }
      : null,
    pinnedAt: row.pinnedAt ? row.pinnedAt.toISOString() : null,
    reactions: summarise(row.reactions ?? []),
    expiresAt: row.expiresAt ? row.expiresAt.toISOString() : null,
    viewOnce: row.viewOnce ?? false,
    viewedBy: (row.views ?? []).map((view) => view.userId),
    ...(row.kind === 'WEBHOOK'
      ? {
          webhook: {
            // Null once the webhook has been deleted. The message stays - the
            // relation is `SetNull` on purpose - so the client draws the name
            // and falls back to an initial for the picture.
            id: row.webhook?.id ?? null,
            name: row.webhook?.name ?? 'Webhook',
            avatarUrl: row.webhook?.avatarUrl ?? null,
          },
        }
      : {}),
  };
}

/** Groups the rows by emoji, keeping the order they were first used in. */
function summarise(rows: Array<{ userId: string; emoji: string }>): MessageReactionSummary[] {
  const groups = new Map<string, MessageReactionSummary>();
  for (const row of rows) {
    const group = groups.get(row.emoji) ?? { emoji: row.emoji, userIds: [] };
    group.userIds.push(row.userId);
    groups.set(row.emoji, group);
  }
  return [...groups.values()];
}

/**
 * When a one-time message has no looks left in it.
 *
 * This is the policy the reported bug was about: a single `viewedAt` meant the
 * first person to open one in a channel destroyed it, and everybody else was
 * shown "Opened" for something they had never been given. One look each is two
 * lists and a subtraction, and it is worth asserting because getting it wrong
 * in either direction is invisible - too eager destroys somebody's message
 * unread, too lax keeps ciphertext for ever.
 */
import assert from 'node:assert/strict';
import { looksOwed } from './messages.service';

const author = 'author';
const ada = 'ada';
const grace = 'grace';

// --- A direct message: two people, one of them the author ------------------

// Before the recipient looks, their look is owed - so the message survives.
assert.deepEqual(looksOwed([author, ada], [], author), [ada]);
// Once they have, nothing is owed and the message goes. This is the case that
// always worked, and it has to keep working.
assert.deepEqual(looksOwed([author, ada], [ada], author), []);

// --- A channel: the bug --------------------------------------------------

const room = [author, ada, grace];
// One person opening theirs leaves the other's look outstanding. Under the old
// single-stamp rule this was already "destroyed", which is the bug.
assert.deepEqual(looksOwed(room, [ada], author), [grace]);
assert.deepEqual(looksOwed(room, [grace], author), [ada]);
// Only when both have looked is it spent.
assert.deepEqual(looksOwed(room, [ada, grace], author), []);

// --- The author is not a viewer --------------------------------------------

// Re-reading your own spends nothing, so an author's "look" never counts
// towards the total and never appears as owed.
assert.deepEqual(looksOwed(room, [author], author), [ada, grace]);
assert.deepEqual(looksOwed([author], [], author), [], 'an author alone owes nothing');

// --- Odd shapes ------------------------------------------------------------

// A channel emptied since the message was sent: holding ciphertext for a
// recipient who no longer exists helps nobody.
assert.deepEqual(looksOwed([], [], author), []);
// Somebody who has left is not owed a look even though they used to be here.
assert.deepEqual(looksOwed([author, ada], [], author), [ada]);
// A look recorded for somebody no longer in the audience does not satisfy
// anybody else's - it is simply ignored.
assert.deepEqual(looksOwed([author, grace], [ada], author), [grace]);
// Two looks from the same person, which the unique index prevents but the
// arithmetic must survive anyway.
assert.deepEqual(looksOwed(room, [ada, ada], author), [grace]);

console.log('one-time: ok');

import { Injectable } from '@nestjs/common';
import type { LinkPreview } from '@betweenus/shared-types';

interface CachedPreview {
  preview: LinkPreview | null;
  expiresAt: number;
}

@Injectable()
export class UnfurlService {
  private readonly cache = new Map<string, CachedPreview>();
  private readonly CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes

  async unfurl(rawUrl: string): Promise<LinkPreview | null> {
    if (!rawUrl || typeof rawUrl !== 'string') return null;
    const trimmed = rawUrl.trim();

    // Check in-memory cache
    const cached = this.cache.get(trimmed);
    if (cached) {
      if (Date.now() < cached.expiresAt) {
        return cached.preview;
      }
      this.cache.delete(trimmed);
    }

    const preview = await this.fetchPreview(trimmed);

    // Evict old entries if cache is growing too large
    if (this.cache.size > 1000) {
      const now = Date.now();
      for (const [key, value] of this.cache) {
        if (value.expiresAt <= now) this.cache.delete(key);
      }
    }

    this.cache.set(trimmed, {
      preview,
      expiresAt: Date.now() + this.CACHE_TTL_MS,
    });

    return preview;
  }

  private async fetchPreview(targetUrl: string): Promise<LinkPreview | null> {
    let parsed: URL;
    try {
      parsed = new URL(targetUrl);
    } catch {
      return null;
    }

    // SSRF & Protocol validation
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return null;
    }

    if (this.isPrivateHost(parsed.hostname)) {
      return null;
    }

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 4000);

      const response = await fetch(parsed.href, {
        signal: controller.signal,
        headers: {
          'User-Agent': 'BetweenUs-Bot/1.0 (+https://betweenus.app; Link Preview)',
          'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          'Accept-Language': 'en-US,en;q=0.9',
        },
        redirect: 'follow',
      });

      clearTimeout(timeoutId);

      if (!response.ok) return null;

      const contentType = response.headers.get('content-type') || '';
      if (!contentType.includes('text/html') && !contentType.includes('application/xhtml+xml')) {
        return null;
      }

      // Read max 128 KB of HTML to prevent memory hogging on massive pages
      const reader = response.body?.getReader();
      if (!reader) return null;

      let html = '';
      let bytesRead = 0;
      const MAX_BYTES = 128 * 1024;

      while (bytesRead < MAX_BYTES) {
        const { done, value } = await reader.read();
        if (done) break;
        if (value) {
          bytesRead += value.length;
          html += new TextDecoder('utf-8').decode(value, { stream: true });
        }
      }
      reader.cancel().catch(() => {});

      return this.parseHtml(html, parsed);
    } catch {
      return null;
    }
  }

  private parseHtml(html: string, baseUrl: URL): LinkPreview {
    const ogTitle = this.extractMeta(html, 'og:title') || this.extractMeta(html, 'twitter:title') || this.extractTitle(html);
    const ogDescription = this.extractMeta(html, 'og:description') || this.extractMeta(html, 'twitter:description') || this.extractMeta(html, 'description');
    const rawImage = this.extractMeta(html, 'og:image') || this.extractMeta(html, 'twitter:image') || this.extractMeta(html, 'og:image:url');
    const ogSiteName = this.extractMeta(html, 'og:site_name') || baseUrl.hostname;
    const rawFavicon = this.extractFavicon(html);

    const image = rawImage ? this.resolveUrl(rawImage, baseUrl) : null;
    const favicon = rawFavicon ? this.resolveUrl(rawFavicon, baseUrl) : this.resolveUrl('/favicon.ico', baseUrl);

    return {
      url: baseUrl.href,
      title: ogTitle || null,
      description: ogDescription ? ogDescription.slice(0, 300) : null,
      image,
      siteName: ogSiteName || baseUrl.hostname,
      favicon,
    };
  }

  private extractMeta(html: string, property: string): string | null {
    const escaped = property.replace(':', '\\:');
    const pattern1 = new RegExp(`<meta[^>]*(?:property|name)=["']${escaped}["'][^>]*content=["']([^"']+)["']`, 'i');
    const match1 = html.match(pattern1);
    if (match1?.[1]) return this.decodeEntities(match1[1].trim());

    const pattern2 = new RegExp(`<meta[^>]*content=["']([^"']+)["'][^>]*(?:property|name)=["']${escaped}["']`, 'i');
    const match2 = html.match(pattern2);
    if (match2?.[1]) return this.decodeEntities(match2[1].trim());

    return null;
  }

  private extractTitle(html: string): string | null {
    const match = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    return match?.[1] ? this.decodeEntities(match[1].trim()) : null;
  }

  private extractFavicon(html: string): string | null {
    const match1 = html.match(/<link[^>]*rel=["'](?:shortcut )?icon["'][^>]*href=["']([^"']+)["']/i);
    if (match1?.[1]) return match1[1].trim();

    const match2 = html.match(/<link[^>]*href=["']([^"']+)["'][^>]*rel=["'](?:shortcut )?icon["']/i);
    if (match2?.[1]) return match2[1].trim();

    return null;
  }

  private resolveUrl(relativeOrAbsolute: string, baseUrl: URL): string | null {
    try {
      return new URL(relativeOrAbsolute, baseUrl).href;
    } catch {
      return null;
    }
  }

  private decodeEntities(str: string): string {
    return str
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&#x27;/g, "'")
      .replace(/&#x2F;/g, '/')
      .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)));
  }

  private isPrivateHost(hostname: string): boolean {
    const lower = hostname.toLowerCase();
    if (
      lower === 'localhost' ||
      lower.endsWith('.localhost') ||
      lower.endsWith('.local') ||
      lower.endsWith('.internal') ||
      lower === '127.0.0.1' ||
      lower === '0.0.0.0' ||
      lower === '::1' ||
      lower === '169.254.169.254'
    ) {
      return true;
    }

    const ipParts = lower.split('.').map(Number);
    if (ipParts.length === 4 && ipParts.every((n) => !isNaN(n) && n >= 0 && n <= 255)) {
      const p0 = ipParts[0] ?? -1;
      const p1 = ipParts[1] ?? -1;
      if (p0 === 10) return true;
      if (p0 === 127) return true;
      if (p0 === 192 && p1 === 168) return true;
      if (p0 === 172 && p1 >= 16 && p1 <= 31) return true;
      if (p0 === 169 && p1 === 254) return true;
    }
    return false;
  }
}

/**
 * The post body, put through the same pipe the running service uses.
 *
 * This file exists because of one bug and would have caught it in a second: a
 * custom `@Transform` on `keys` replaced the conversion `@Type` does, the wraps
 * arrived as plain objects, and the global pipe's `forbidNonWhitelisted` -
 * which sees a plain object as a class with no known properties - refused every
 * post with "keys.0.property recipientUserId should not exist". Nothing in a
 * typecheck can see that: the types were right and the runtime was not.
 *
 * So the options here are the ones `packages/nest-common` sets, and the body is
 * shaped the way multipart delivers one - every field a string, `keys` a JSON
 * blob - rather than the way a JSON client would.
 */
import assert from 'node:assert/strict';
import { plainToInstance } from 'class-transformer';
import { validateSync, type ValidationError } from 'class-validator';
import { CreateStatusDto } from './status.controller';

/** What `packages/nest-common` passes to `ValidationPipe`. */
const OPTIONS = { whitelist: true, forbidNonWhitelisted: true } as const;

const wrap = (recipientUserId: string) => ({
  recipientUserId,
  recipientDeviceId: 'laptop',
  senderPublicKey: '{"kty":"EC"}',
  wrappedKey: 'c2VhbGVk',
  iv: 'aXY=',
});

/**
 * Every complaint the pipe would make, flattened.
 *
 * Recursive, and that is the point: a refusal about a wrap is not on the `keys`
 * error, it is three levels down in `children` - `keys` -> `0` -> the property.
 * A first version of this file read only the top level, saw an empty
 * `constraints` there, and passed against the very bug it was written for.
 */
function complaints(body: Record<string, unknown>): string[] {
  const dto = plainToInstance(CreateStatusDto, body);
  return flatten(validateSync(dto, OPTIONS));
}

function flatten(errors: ValidationError[]): string[] {
  return errors.flatMap((error) => [
    ...Object.values(error.constraints ?? {}),
    ...flatten(error.children ?? []),
  ]);
}

const ada = '11111111-1111-4111-8111-111111111111';
const grace = '22222222-2222-4222-8222-222222222222';

// A text post with two wraps: the shape every client sends, and the one that
// used to be refused. The messages are kept in the failure so a regression
// reads as itself rather than as "1 error".
const text = complaints({
  kind: 'TEXT',
  caption: '{"v":1,"epoch":0,"iv":"aXY=","ct":"Y3Q="}',
  background: '#0F172A',
  senderDeviceId: 'phone',
  keys: JSON.stringify([wrap(ada), wrap(grace)]),
});
assert.deepEqual(text, [], 'the shape every client sends is accepted');

// The wraps really are validated, rather than passing because nothing looked:
// a device id that is not there is a refusal, not a default.
const missing = complaints({
  kind: 'TEXT',
  caption: 'sealed',
  senderDeviceId: 'phone',
  keys: JSON.stringify([{ ...wrap(ada), recipientDeviceId: undefined }]),
});
assert.ok(
  missing.some((complaint) => complaint.includes('recipientDeviceId')),
  'a wrap with no device id is refused, and the refusal names the field',
);

// And a field nobody declared is still refused, which is the protection
// `forbidNonWhitelisted` is there for - the fix must not have turned it off.
const extra = complaints({
  kind: 'TEXT',
  caption: 'sealed',
  senderDeviceId: 'phone',
  keys: JSON.stringify([{ ...wrap(ada), plaintext: 'oops' }]),
});
assert.deepEqual(extra, ['property plaintext should not exist']);

// A `keys` field that is not JSON at all refuses in the ordinary shape rather
// than throwing a SyntaxError out of the pipe.
const rubbish = complaints({
  kind: 'TEXT',
  caption: 'sealed',
  senderDeviceId: 'phone',
  keys: 'not json',
});
assert.deepEqual(
  rubbish,
  [],
  'an unparseable bundle is an empty one, which is a post only its author can read',
);

// A video post carries the IV and the type beside the file, and neither is a
// property the pipe strips.
const video = complaints({
  kind: 'VIDEO',
  caption: 'sealed',
  durationMs: '4000',
  mediaIv: 'aXY=',
  mediaType: 'video/mp4',
  senderDeviceId: 'phone',
  keys: JSON.stringify([wrap(ada)]),
});
assert.deepEqual(video, [], 'the IV and the type travel beside the file');

console.log('status dto check ok');

/**
 * Collects statuses whose 24 hours are up.
 *
 * The sweep is housekeeping, not the feature: the read path already filters on
 * `expiresAt`, so a post is invisible the moment it is due whether or not this
 * has run. That is deliberate - a status that outlives its window because a
 * timer was late would be the feature not working, and no interval is short
 * enough to be relied on for correctness.
 *
 * What it actually recovers is disk. The blob goes before the row, the same
 * order as everywhere else: a failure between the two leaves a row pointing at
 * nothing, which the next pass deletes anyway, rather than a blob nothing can
 * ever name.
 *
 * ponytail: a timer in the process, like the sweeps beside it. Two replicas
 * will overlap; deleting an already-deleted row is a no-op and the second pass
 * simply finds nothing.
 */
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { prisma } from '@betweenus/database';
import { Logger } from '@betweenus/logger';
import { getStorage } from '@betweenus/storage';

/**
 * How often to look. Five minutes, not the disappearing sweep's one: nothing
 * is waiting on this, because the read path has already stopped serving what
 * it collects.
 */
const INTERVAL_MS = 5 * 60_000;

/** Not at boot: a service starting is the worst moment to add database work. */
const FIRST_RUN_DELAY_MS = 45_000;

/** How many one pass takes, so a backlog is spread rather than dropped at once. */
const BATCH = 200;

/** Destroys what is past its stamp and returns how many went. */
export async function sweepExpiredStatuses(now: Date = new Date()): Promise<number> {
  const doomed = await prisma.status.findMany({
    where: { expiresAt: { lte: now } },
    select: { id: true, mediaKey: true },
    orderBy: { expiresAt: 'asc' },
    take: BATCH,
  });
  if (doomed.length === 0) return 0;

  const storage = getStorage();
  for (const row of doomed) {
    if (row.mediaKey) await storage.delete(row.mediaKey).catch(() => undefined);
  }
  // The view rows go with them: `status_views.statusId` cascades.
  await prisma.status.deleteMany({ where: { id: { in: doomed.map((row) => row.id) } } });
  return doomed.length;
}

@Injectable()
export class StatusSweeper implements OnModuleInit, OnModuleDestroy {
  private timer: NodeJS.Timeout | null = null;
  private first: NodeJS.Timeout | null = null;

  constructor(private readonly logger: Logger) {}

  onModuleInit(): void {
    this.first = setTimeout(() => {
      void this.run();
      this.timer = setInterval(() => void this.run(), INTERVAL_MS);
      this.timer.unref?.();
    }, FIRST_RUN_DELAY_MS);
    this.first.unref?.();
  }

  private async run(): Promise<void> {
    try {
      const removed = await sweepExpiredStatuses();
      if (removed > 0) this.logger.info('Swept expired statuses', { removed });
    } catch (error) {
      this.logger.warn('Could not sweep expired statuses', { reason: String(error) });
    }
  }

  onModuleDestroy(): void {
    if (this.first) clearTimeout(this.first);
    if (this.timer) clearInterval(this.timer);
  }
}

/**
 * The status rules worth asserting rather than reading: who a status may be
 * addressed to, whose wraps a post may actually carry, and what order the tray
 * comes back in.
 *
 * The audience rule is an authorization rule with three callers - the tray,
 * the single-post gate and the media download - so it is one function and this
 * is the thing that says what it means. The ordering is not security, but it
 * is the difference between "the run you have not watched is under your thumb"
 * and a list that reshuffles itself every time somebody posts twice.
 */
import assert from 'node:assert/strict';
import type { StatusEntry } from '@betweenus/shared-types';
import { keysForAudience, orderRuns, statusAudience } from './status.service';

const ada = 'ada';
const grace = 'grace';
const alan = 'alan';

// --- Audience -----------------------------------------------------------------

// A friend nobody has blocked can see it. That is the whole feature.
assert.deepEqual(statusAudience([ada, grace], new Set()), [ada, grace]);

// A block removes them, whichever side made it: `blockedIdsAround` returns
// both directions, and either one has to close the door. Relying on the block
// to have ended the friendship is not enough - unblocking does not restore
// one, so the two facts drift apart the moment somebody unblocks.
assert.deepEqual(statusAudience([ada, grace], new Set([grace])), [ada]);
assert.deepEqual(statusAudience([ada, grace], new Set([ada, grace])), []);

// Somebody who is not a friend was never in the list to be removed from it.
assert.deepEqual(statusAudience([], new Set([alan])), []);

// --- Whose wraps a post may carry ---------------------------------------------

const wrap = (recipientUserId: string) => ({
  recipientUserId,
  recipientDeviceId: `${recipientUserId}-laptop`,
  senderPublicKey: 'jwk',
  wrappedKey: 'sealed',
  iv: 'iv',
});

// The bundle is assembled by the client from a directory it read a moment
// earlier, and this is the gap between that read and the write: somebody who
// stopped being addressable in between is dropped here rather than handed a
// key by a client that had not heard yet.
assert.deepEqual(
  keysForAudience([wrap(ada), wrap(alan)], new Set([ada])).map((entry) => entry.recipientUserId),
  [ada],
);

// The author is always in their own audience: a post they cannot open on the
// machine that wrote it is the one failure nobody would ever recover from.
assert.deepEqual(
  keysForAudience([wrap(ada)], new Set([ada, grace])).map((entry) => entry.recipientUserId),
  [ada],
);

// And a bundle addressed to nobody who qualifies carries nothing - which is a
// post only its author can read, not an error.
assert.deepEqual(keysForAudience([wrap(alan)], new Set([ada])), []);

// --- Tray order ---------------------------------------------------------------

const person = (id: string) => ({
  id,
  username: id,
  displayName: id,
  avatarUrl: null,
  coverUrl: null,
  about: '',
});

const post = (createdAt: string, seen: boolean): StatusEntry => ({
  id: `${createdAt}-${String(seen)}`,
  authorId: 'whoever',
  kind: 'TEXT',
  mediaUrl: null,
  caption: 'hello',
  background: '#0F172A',
  durationMs: null,
  createdAt,
  expiresAt: '2030-01-01T00:00:00.000Z',
  seen,
  viewCount: null,
  mediaIv: null,
  mediaType: null,
  keys: [],
});

// An unopened run outranks an opened one even when the opened one is newer.
// This is the case a plain sort by time gets wrong, and it is the common one:
// somebody you have already caught up with posts again while somebody you have
// not sits below them.
const ordered = orderRuns([
  { author: person(ada), statuses: [post('2026-09-03T10:00:00.000Z', true)] },
  { author: person(grace), statuses: [post('2026-09-03T09:00:00.000Z', false)] },
]);
assert.deepEqual(
  ordered.map((run) => run.author.id),
  [grace, ada],
);
assert.deepEqual(
  ordered.map((run) => run.unseen),
  [true, false],
);

// Inside one half, newest first.
assert.deepEqual(
  orderRuns([
    { author: person(ada), statuses: [post('2026-09-03T08:00:00.000Z', false)] },
    { author: person(grace), statuses: [post('2026-09-03T09:00:00.000Z', false)] },
  ]).map((run) => run.author.id),
  [grace, ada],
);

// A run is unseen while *any* post in it is: catching up on the first two of
// somebody's three does not take their ring away.
const run = orderRuns([
  {
    author: person(alan),
    statuses: [
      post('2026-09-03T07:00:00.000Z', true),
      post('2026-09-03T08:00:00.000Z', true),
      post('2026-09-03T09:00:00.000Z', false),
    ],
  },
])[0]!;
assert.equal(run.unseen, true);
// The run is built oldest-first, so its newest post is what dates it.
assert.equal(run.latestAt, '2026-09-03T09:00:00.000Z');

console.log('status check ok');

/**
 * The status endpoints: post one, read the tray, mark one seen, see who saw
 * yours, take one down.
 *
 * Posting is one request carrying both the bytes and the caption, unlike an
 * attachment, which is uploaded first and claimed by a message later. Two
 * steps exist there because a message can carry several files and is composed
 * over time; a status is one file and one button, and a two-step version of it
 * leaves an orphaned blob every time somebody changes their mind between the
 * two steps.
 *
 * Everything a post says is sealed by the time it arrives: the caption is an
 * envelope, the file is ciphertext, and the bundle of wraps that decides who
 * may open it comes with them. So this controller no longer looks inside
 * anything - it cannot - and the checks that used to read the bytes have gone
 * with the plaintext they needed. `GET audience` is the other half: the
 * directory a client wraps against before it posts.
 */
import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Post,
  UploadedFile,
  UseGuards,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { Transform, plainToInstance } from 'class-transformer';
import {
  ArrayMaxSize,
  IsArray,
  IsHexColor,
  IsIn,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Length,
  Max,
  MaxLength,
  Min,
  ValidateNested,
} from 'class-validator';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import { MAX_UPLOAD_BYTES, buildKey, getStorage } from '@betweenus/storage';
import {
  STATUS_CAPTION_SEALED_MAX_LENGTH,
  STATUS_VIDEO_MAX_MS,
  type CreateStatusRequest,
  type DeviceKey,
  type StatusEntry,
  type StatusFeed,
  type StatusKeyEntry,
  type StatusKind,
  type StatusViewer,
} from '@betweenus/shared-types';
import { StatusService } from './status.service';

/** Ciphertext has no type of its own, and claiming one would be a lie. */
const OPAQUE = 'application/octet-stream';

/** A serialised ECDH P-256 JWK is ~200 chars; the cap is slack, not a guess. */
const MAX_PUBLIC_KEY_LENGTH = 1024;

/** Client-minted and opaque here, exactly as in the e2ee module's DTO. */
const MAX_DEVICE_ID_LENGTH = 128;

/** One wrap of the post's key, for one device. */
export class StatusKeyEntryDto implements StatusKeyEntry {
  @IsUUID()
  recipientUserId!: string;

  @IsString()
  @Length(1, MAX_DEVICE_ID_LENGTH)
  recipientDeviceId!: string;

  @IsString()
  @Length(1, MAX_PUBLIC_KEY_LENGTH)
  senderPublicKey!: string;

  @IsString()
  @Length(1, 512)
  wrappedKey!: string;

  @IsString()
  @Length(1, 64)
  iv!: string;
}

/**
 * A multipart body arrives as strings, so the numbers are converted before
 * they are validated rather than after - `@IsInt` on the string `"4000"` fails,
 * and the failure reads as "durationMs must be an integer" for a client that
 * sent an integer.
 */
export class CreateStatusDto implements CreateStatusRequest {
  @IsIn(['PHOTO', 'VIDEO', 'TEXT'])
  kind!: StatusKind;

  /**
   * The sealed caption, not the words - so the cap is on the envelope and the
   * readable length is the composer's business. The server cannot count
   * characters in a ciphertext and must not pretend to.
   */
  @IsOptional()
  @IsString()
  @MaxLength(STATUS_CAPTION_SEALED_MAX_LENGTH)
  caption?: string;

  /** The IV the file was sealed with. Required with a file, refused without. */
  @IsOptional()
  @IsString()
  @Length(1, 64)
  mediaIv?: string;

  /**
   * What the sealed bytes are once opened. Stored and returned as sent: it is
   * a hint for the client's decoder, never a claim about what is on disk -
   * what is on disk is ciphertext.
   */
  @IsOptional()
  @IsString()
  @Length(1, 128)
  mediaType?: string;

  @IsString()
  @Length(1, MAX_DEVICE_ID_LENGTH)
  senderDeviceId!: string;

  /**
   * The wraps. Arrives as a JSON string because the rest of the post is
   * multipart, and multipart has no arrays - the shape is validated below
   * exactly as if it had come in as JSON.
   *
   * The ceiling is a friend list times its devices. Bigger than that is not a
   * person with a lot of friends, it is somebody probing the endpoint.
   */
  @Transform(({ value }) => parseKeys(value))
  @IsArray()
  @ArrayMaxSize(2000)
  @ValidateNested({ each: true })
  keys!: StatusKeyEntryDto[];

  /**
   * Validated as a hex colour rather than against `STATUS_BACKGROUNDS`: the
   * palette is a client's choice of eight, and pinning the server to that list
   * would mean a deployment cannot add a ninth without a release of both.
   */
  @IsOptional()
  @IsHexColor()
  background?: string;

  @IsOptional()
  @Transform(({ value }) => (value === undefined || value === '' ? undefined : Number(value)))
  @IsInt()
  @Min(1)
  @Max(STATUS_VIDEO_MAX_MS)
  durationMs?: number;
}

@Controller('statuses')
@UseGuards(JwtAuthGuard)
export class StatusController {
  constructor(private readonly statuses: StatusService) {}

  /** Your own run, and one row per friend who has posted. */
  @Get()
  feed(@CurrentUser() user: AuthenticatedUser): Promise<StatusFeed> {
    return this.statuses.feed(user.id);
  }

  /**
   * Posts one. `file` is required for PHOTO and VIDEO and refused for TEXT -
   * a text status with an attachment is a photo status somebody mislabelled,
   * and storing the file under a row that will never draw it is a blob no
   * sweep can name.
   */
  @Post()
  @UseInterceptors(FileInterceptor('file', { limits: { fileSize: MAX_UPLOAD_BYTES, files: 1 } }))
  async create(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: CreateStatusDto,
    @UploadedFile() file: Express.Multer.File | undefined,
  ): Promise<StatusEntry> {
    if (dto.kind === 'TEXT') {
      if (file) {
        throw new BadRequestException({
          code: 'UNEXPECTED_FILE',
          message: 'A text status carries no file',
        });
      }
      if (!dto.caption?.trim()) {
        throw new BadRequestException({
          code: 'EMPTY_STATUS',
          message: 'A text status needs something to say',
        });
      }
      // Whether it says anything is the only thing that can be asked of it -
      // the words are sealed, so "is it blank" is answered by the composer.
      return this.statuses.create(user.id, dto, null);
    }

    if (!file) {
      throw new BadRequestException({ code: 'NO_FILE', message: 'No file was uploaded' });
    }
    // Nothing here sniffs the bytes any more, because there is nothing to
    // sniff: the file arrives sealed, and a magic-number check on ciphertext
    // would refuse every real post. What the file is once opened is `mediaType`
    // - a hint the author sent, stored as sent, and never trusted as a fact
    // about the object. The IV is what makes it openable at all, so a sealed
    // file without one is refused rather than stored unreadable for a day.
    if (!dto.mediaIv) {
      throw new BadRequestException({
        code: 'NO_MEDIA_IV',
        message: 'A sealed file needs the IV it was sealed with',
      });
    }

    // Under `status/`, which is the prefix the download route reads to know
    // this object is gated by a status key rather than by channel access.
    // Never under `attachments/`: that prefix means "claimed by a message or
    // by nobody", and a status is neither. No extension, for the same reason
    // an attachment has none - the name would describe the plaintext.
    const key = buildKey(`status/${user.id}`, '');
    const object = await getStorage().put(key, file.buffer, OPAQUE);
    return this.statuses.create(user.id, dto, object.key);
  }

  /**
   * Every device this account may seal a post for, right now: its own, and
   * every friend's.
   *
   * Read immediately before posting rather than cached, because this list *is*
   * the audience - a friend added a minute ago should be in it, and one who
   * blocked the caller a minute ago should not.
   */
  @Get('audience')
  audience(@CurrentUser() user: AuthenticatedUser): Promise<DeviceKey[]> {
    return this.statuses.audienceDevices(user.id);
  }

  /** Records that this account opened one. Idempotent. */
  @Post(':statusId/view')
  @HttpCode(204)
  view(
    @CurrentUser() user: AuthenticatedUser,
    @Param('statusId', ParseUUIDPipe) statusId: string,
  ): Promise<void> {
    return this.statuses.markViewed(user.id, statusId);
  }

  /** Who opened one of yours. Refused to everybody but its author. */
  @Get(':statusId/views')
  viewers(
    @CurrentUser() user: AuthenticatedUser,
    @Param('statusId', ParseUUIDPipe) statusId: string,
  ): Promise<StatusViewer[]> {
    return this.statuses.viewers(user.id, statusId);
  }

  @Delete(':statusId')
  @HttpCode(204)
  remove(
    @CurrentUser() user: AuthenticatedUser,
    @Param('statusId', ParseUUIDPipe) statusId: string,
  ): Promise<void> {
    return this.statuses.remove(user.id, statusId);
  }
}

/**
 * The wrap bundle, out of the multipart field it travelled in, as real DTOs.
 *
 * `plainToInstance` is the whole point of this function, and leaving it out is
 * a bug that has already happened: a custom `@Transform` replaces the
 * conversion `@Type` would have done, so the entries stayed plain objects, the
 * global pipe's `forbidNonWhitelisted` found a class with no known properties,
 * and every post came back "keys.0.property recipientUserId should not exist".
 *
 * A parse failure becomes an empty array rather than a thrown error, so the
 * validator produces the ordinary "keys must be an array" refusal in the
 * standard error shape instead of a raw `SyntaxError` escaping the pipe.
 */
function parseKeys(value: unknown): unknown {
  const raw = typeof value === 'string' ? tryParse(value) : value;
  if (!Array.isArray(raw)) return raw;
  return plainToInstance(StatusKeyEntryDto, raw);
}

function tryParse(value: string): unknown {
  try {
    return JSON.parse(value);
  } catch {
    return [];
  }
}

/**
 * Statuses: posts that expire after 24 hours and are read by accepted friends.
 *
 * The audience is the whole design. A status has no channel, so
 * `resolveChannelAccess` has nothing to answer here; the equivalent rule is
 * `friendIdsOf` plus the block list, and it is applied in exactly three places
 * - reading the tray, opening one post, and reading who saw yours. Every one
 * of them goes through `audienceOf` below rather than assembling the query
 * again, because three copies of an authorization rule is three chances to get
 * it wrong once.
 *
 * Expiry is stamped at write time and filtered at read time, so a sweep that
 * is late never shows a stale post: the row outliving its stamp is invisible
 * before it is collected. See `status-sweeper.ts` for the collection half.
 *
 * The content is end-to-end encrypted and the audience is frozen when it is
 * posted - the author wraps the post's key once per device of every friend it
 * had at that moment, and `status_keys` holds those wraps. So there are now two
 * gates rather than one, and they answer different questions: the friend rule
 * below still decides whom a post may be *addressed* to, and the wrap decides
 * who can actually open it. A friendship made after the post passes the first
 * and fails the second, which is the whole of "a new friend does not see
 * yesterday's update".
 */
import { ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
import { blockedIdsAround, friendIdsOf, prisma } from '@betweenus/database';
import type { Status, StatusKind as PrismaStatusKind } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { getStorage } from '@betweenus/storage';
import {
  STATUS_TTL_MS,
  type CreateStatusRequest,
  type DeviceKey,
  type StatusEntry,
  type StatusFeed,
  type StatusFeedEntry,
  type StatusKeyEntry,
  type StatusViewer,
  type UserSummary,
} from '@betweenus/shared-types';
import { toDeviceKey } from '../e2ee/e2ee.service';

interface UserRow {
  id: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
  coverUrl: string | null;
  about: string;
}

const USER_FIELDS = {
  id: true,
  username: true,
  displayName: true,
  avatarUrl: true,
  coverUrl: true,
  about: true,
} as const;

@Injectable()
export class StatusService {
  constructor(private readonly events: EventBus) {}

  /**
   * The tray: this account's own run, and one row per friend who has posted.
   *
   * Ordered newest-run-first with unopened runs ahead of opened ones, which is
   * the order every app with this feature uses and the only one where the
   * thing you have not seen is the thing under your thumb.
   */
  async feed(userId: string): Promise<StatusFeed> {
    const audience = await this.audienceOf(userId);
    const now = new Date();

    const rows = await prisma.status.findMany({
      where: {
        expiresAt: { gt: now },
        authorId: { in: [userId, ...audience] },
        // And a wrap addressed to this account, which is what makes the tray
        // agree with what the reader can actually open. Their own posts are
        // exempt from the condition rather than from the wrap: the author
        // seals for their own devices too, and a post they cannot open on
        // this machine is still theirs and still deletable.
        OR: [{ authorId: userId }, { keys: { some: { recipientUserId: userId } } }],
      },
      orderBy: { createdAt: 'asc' },
      include: {
        author: { select: USER_FIELDS },
        // Two view slices in one query rather than two round trips: whether
        // *this* reader has opened each post, and - for the reader's own posts
        // - how many people have.
        views: { where: { viewerId: userId }, select: { id: true } },
        _count: { select: { views: true } },
        // Every copy addressed to this account, one per machine they had when
        // the post was written. The client keeps whichever its private half
        // opens - see the note on `StatusEntry.keys`.
        keys: { where: { recipientUserId: userId } },
      },
    });

    const mine: StatusEntry[] = [];
    const byAuthor = new Map<string, { author: UserSummary; statuses: StatusEntry[] }>();

    for (const row of rows) {
      if (row.authorId === userId) {
        mine.push(toEntry(row, { seen: true, viewCount: row._count.views }));
        continue;
      }
      const group = byAuthor.get(row.authorId) ?? {
        author: toSummary(row.author),
        statuses: [],
      };
      group.statuses.push(toEntry(row, { seen: row.views.length > 0, viewCount: null }));
      byAuthor.set(row.authorId, group);
    }

    return { mine, others: orderRuns([...byAuthor.values()]) };
  }

  /**
   * Posts one.
   *
   * `mediaKey` is already in storage by the time this runs - the controller
   * puts the bytes there in the same request - so a failure below leaves an
   * object with no row. That is why it is deleted on the way out rather than
   * left for a sweep to guess at: nothing else ever writes under `status/`, so
   * an unreferenced object there is unambiguously rubbish.
   */
  async create(
    userId: string,
    dto: CreateStatusRequest,
    mediaKey: string | null,
  ): Promise<StatusEntry> {
    const now = new Date();
    // Only for people who may be addressed *now*: the client built its bundle
    // from the directory a moment ago, and somebody who has since blocked the
    // author must not get a wrap out of that gap. The author's own devices are
    // always allowed - they are sealing for themselves.
    const allowed = new Set([userId, ...(await this.audienceOf(userId))]);
    const entries = keysForAudience(dto.keys, allowed);

    let row: Status;
    try {
      // One transaction: a status whose keys failed to write is a post nobody
      // can ever open, including its author, and it would sit in the tray for
      // a day looking like a bug.
      row = await prisma.$transaction(async (tx) => {
        const created = await tx.status.create({
          data: {
            authorId: userId,
            kind: dto.kind as PrismaStatusKind,
            mediaKey,
            mediaIv: dto.mediaIv ?? null,
            mediaType: dto.mediaType ?? null,
            caption: dto.caption?.trim() || null,
            background: dto.background ?? null,
            durationMs: dto.durationMs ?? null,
            expiresAt: new Date(now.getTime() + STATUS_TTL_MS),
          },
        });
        if (entries.length > 0) {
          await tx.statusKey.createMany({
            data: entries.map((entry) => ({
              statusId: created.id,
              recipientUserId: entry.recipientUserId,
              recipientDeviceId: entry.recipientDeviceId,
              senderDeviceId: dto.senderDeviceId,
              senderPublicKey: entry.senderPublicKey,
              wrappedKey: entry.wrappedKey,
              iv: entry.iv,
            })),
            skipDuplicates: true,
          });
        }
        return created;
      });
    } catch (error) {
      if (mediaKey) await getStorage().delete(mediaKey).catch(() => undefined);
      throw error;
    }

    await this.announce(userId);
    return toEntry(
      {
        ...row,
        views: [],
        _count: { views: 0 },
        // What goes back to the author is only their own copies: this response
        // is read by the machine that posted, which already holds the key it
        // just minted, and nobody else's wrap is any of its business.
        keys: entries.filter((entry) => entry.recipientUserId === userId),
      },
      { seen: true, viewCount: 0 },
    );
  }

  /**
   * Records that this account opened somebody's post.
   *
   * Idempotent by the unique pair, so re-opening a status does not write a
   * second row and does not move the time on the first: what the author is
   * shown is when somebody first looked, not when they last scrolled past.
   * Opening your own is a no-op rather than an error - the client does not
   * special-case it, and a viewer list with the author in it would be a lie.
   */
  async markViewed(userId: string, statusId: string): Promise<void> {
    const row = await this.readable(userId, statusId);
    if (row.authorId === userId) return;

    await prisma.statusView.upsert({
      where: { statusId_viewerId: { statusId, viewerId: userId } },
      create: { statusId, viewerId: userId },
      update: {},
    });
    // The author's own tray shows a view count, and nobody else's changes.
    await this.events.publish(EVENTS.STATUS_CHANGED, {
      userIds: [row.authorId],
      authorId: row.authorId,
    });
  }

  /** Who opened one of your posts, newest first. Only the author may ask. */
  async viewers(userId: string, statusId: string): Promise<StatusViewer[]> {
    const row = await prisma.status.findUnique({
      where: { id: statusId },
      select: { authorId: true },
    });
    if (!row) throw new NotFoundException({ code: 'STATUS_NOT_FOUND', message: 'No such status' });
    if (row.authorId !== userId) {
      throw new ForbiddenException({
        code: 'FORBIDDEN',
        message: 'Only the author can see who viewed a status',
      });
    }

    const rows = await prisma.statusView.findMany({
      where: { statusId },
      orderBy: { viewedAt: 'desc' },
      include: { viewer: { select: USER_FIELDS } },
    });
    return rows.map((view) => ({
      user: toSummary(view.viewer),
      viewedAt: view.viewedAt.toISOString(),
    }));
  }

  /** Takes one of your own down early. The blob goes with it. */
  async remove(userId: string, statusId: string): Promise<void> {
    const row = await prisma.status.findUnique({
      where: { id: statusId },
      select: { authorId: true, mediaKey: true },
    });
    if (!row) throw new NotFoundException({ code: 'STATUS_NOT_FOUND', message: 'No such status' });
    if (row.authorId !== userId) {
      throw new ForbiddenException({
        code: 'FORBIDDEN',
        message: 'Only the author can delete a status',
      });
    }

    // Object first, then row: a failure between the two leaves a row pointing
    // at nothing, which draws as a broken post and can be deleted again. The
    // other order leaves a blob nothing can ever name.
    if (row.mediaKey) await getStorage().delete(row.mediaKey).catch(() => undefined);
    await prisma.status.delete({ where: { id: statusId } });
    await this.announce(userId);
  }

  /**
   * The one post, if this account is allowed it. Used by the view marker and
   * by the download gate - see `mayReadStatusMedia`.
   */
  private async readable(
    userId: string,
    statusId: string,
  ): Promise<{ authorId: string }> {
    const row = await prisma.status.findFirst({
      where: { id: statusId, expiresAt: { gt: new Date() } },
      select: { authorId: true },
    });
    if (!row) throw new NotFoundException({ code: 'STATUS_NOT_FOUND', message: 'No such status' });
    if (row.authorId === userId) return row;

    const audience = await this.audienceOf(userId);
    // Both gates. A wrap addressed to this account is what "may open it"
    // means; the friend list is what "may still see it" means, because
    // unfriending does not delete a wrap that was already written.
    if (!audience.includes(row.authorId) || !(await hasKey(userId, statusId))) {
      throw new ForbiddenException({
        code: 'FORBIDDEN',
        message: 'This status is not yours to see',
      });
    }
    return row;
  }

  /**
   * Whose statuses this account may read: accepted friends, minus anyone
   * either side has blocked.
   *
   * A block is checked in both directions because it is directional and either
   * direction closes the door - the same rule the conversation gate uses. It
   * is subtracted here rather than relied on to have ended the friendship,
   * because unblocking does not restore one and the two facts drift.
   */
  private async audienceOf(userId: string): Promise<string[]> {
    const [friends, blocked] = await Promise.all([
      friendIdsOf(userId),
      blockedIdsAround(userId),
    ]);
    return statusAudience(friends, blocked);
  }

  /**
   * Every device a post written now may be sealed for: the author's own, and
   * every friend's, minus the revoked ones.
   *
   * The same answer `devicesForChannel` gives for a channel, from the same
   * directory - a status simply has a friend list where a channel has a
   * membership. Revoked machines are filtered here rather than left to the
   * client for the same reason they are there: "never seal for that laptop
   * again" has to be enforced where the answer is produced.
   */
  async audienceDevices(userId: string): Promise<DeviceKey[]> {
    const audience = await this.audienceOf(userId);
    const rows = await prisma.deviceKey.findMany({
      where: { userId: { in: [userId, ...audience] }, revokedAt: null },
      orderBy: { createdAt: 'asc' },
    });
    return rows.map(toDeviceKey);
  }

  /**
   * Tells the author's friends - and the author's own other devices - to
   * re-read the tray.
   *
   * The audience is computed here because this is where the friend list is
   * already loaded; the gateway holds sockets and knows nothing about
   * friendships.
   */
  private async announce(authorId: string): Promise<void> {
    const friends = await friendIdsOf(authorId);
    await this.events.publish(EVENTS.STATUS_CHANGED, {
      userIds: [authorId, ...friends],
      authorId,
    });
  }
}

/**
 * Whether this account may fetch the bytes behind a `status/` key.
 *
 * Lives here, beside the audience rule it shares, rather than in the uploads
 * controller: that route already answers two different questions about two
 * kinds of object, and a third rule written inline there is the third place
 * the friendship check could drift out of step.
 */
export async function mayReadStatusMedia(userId: string, key: string): Promise<boolean> {
  const row = await prisma.status.findFirst({
    where: { mediaKey: key, expiresAt: { gt: new Date() } },
    select: { id: true, authorId: true },
  });
  if (!row) return false;
  if (row.authorId === userId) return true;

  const [friends, blocked, keyed] = await Promise.all([
    friendIdsOf(userId),
    blockedIdsAround(userId),
    hasKey(userId, row.id),
  ]);
  // The bytes are ciphertext, so this gate is not what keeps them secret - the
  // wrap is. It is still the same two questions the tray asks, and asking them
  // here stops anybody hoarding blobs they hold no key for.
  return keyed && statusAudience(friends, blocked).includes(row.authorId);
}

/** Whether a wrap of this post's key was addressed to any of an account's devices. */
async function hasKey(userId: string, statusId: string): Promise<boolean> {
  const row = await prisma.statusKey.findFirst({
    where: { statusId, recipientUserId: userId },
    select: { id: true },
  });
  return row !== null;
}

/**
 * Whose statuses an account may read, given its friends and its blocks.
 *
 * Split out of the query so the rule can be asserted on without a database,
 * and shared by the tray, the single-post gate and the media download - three
 * callers that must never answer this differently. A block is subtracted in
 * both directions (`blockedIdsAround` returns both) rather than relied on to
 * have ended the friendship, because unblocking does not restore one and the
 * two facts drift apart the moment somebody unblocks.
 */
export function statusAudience(friendIds: string[], blocked: Set<string>): string[] {
  return friendIds.filter((id) => !blocked.has(id));
}

/**
 * The wraps a bundle may actually contain: the ones addressed to somebody the
 * author may post to.
 *
 * The client assembles the bundle from a directory it read a moment earlier,
 * so this is not a formality - it is the gap between that read and this write,
 * and the person who blocked the author inside it. Sealing is done by the
 * author and cannot be checked here; who may be *addressed* can be, and is.
 */
export function keysForAudience(
  entries: StatusKeyEntry[],
  allowed: Set<string>,
): StatusKeyEntry[] {
  return entries.filter((entry) => allowed.has(entry.recipientUserId));
}

/**
 * The order the tray is drawn in: unopened runs first, then newest first
 * inside each half.
 *
 * That order is not a preference. A list sorted purely by time puts a run you
 * have already watched above one you have not the moment somebody posts twice,
 * and the thing under your thumb stops being the thing you opened the screen
 * for. Every app with this feature splits the list the same way.
 */
export function orderRuns(
  runs: Array<{ author: UserSummary; statuses: StatusEntry[] }>,
): StatusFeedEntry[] {
  return runs
    .map((run) => ({
      author: run.author,
      statuses: run.statuses,
      // The run is built oldest-first, so the last one is the newest.
      latestAt: run.statuses[run.statuses.length - 1]!.createdAt,
      unseen: run.statuses.some((status) => !status.seen),
    }))
    .sort((left, right) => {
      if (left.unseen !== right.unseen) return left.unseen ? -1 : 1;
      // ISO-8601 in UTC sorts lexicographically, which is why these are
      // compared as strings rather than parsed back into dates.
      return right.latestAt.localeCompare(left.latestAt);
    });
}

type StatusRow = Status & {
  views?: Array<{ id: string }>;
  _count?: { views: number };
  /** The wraps addressed to the reader - see `StatusEntry.keys`. */
  keys?: StatusKeyEntry[];
};

function toEntry(
  row: StatusRow,
  read: { seen: boolean; viewCount: number | null },
): StatusEntry {
  return {
    id: row.id,
    authorId: row.authorId,
    kind: row.kind,
    // The route, not the key: every client resolves this against whichever
    // deployment it is pointed at, the same way an attachment url is resolved.
    mediaUrl: row.mediaKey ? `/api/v1/uploads/${row.mediaKey}` : null,
    mediaIv: row.mediaIv,
    mediaType: row.mediaType,
    caption: row.caption,
    background: row.background,
    durationMs: row.durationMs,
    createdAt: row.createdAt.toISOString(),
    expiresAt: row.expiresAt.toISOString(),
    seen: read.seen,
    viewCount: read.viewCount,
    keys: (row.keys ?? []).map((entry) => ({
      recipientUserId: entry.recipientUserId,
      recipientDeviceId: entry.recipientDeviceId,
      senderPublicKey: entry.senderPublicKey,
      wrappedKey: entry.wrappedKey,
      iv: entry.iv,
    })),
  };
}

function toSummary(row: UserRow): UserSummary {
  return {
    id: row.id,
    username: row.username,
    displayName: row.displayName,
    avatarUrl: row.avatarUrl,
    coverUrl: row.coverUrl,
    about: row.about,
  };
}

/**
 * What the attachment sweep will and will not collect.
 *
 * The query is the policy, so this asserts on the query rather than on rows in
 * a database: the two arms, and which way round the grace period runs. An
 * inverted comparison here would delete every upload the moment it landed,
 * which is the failure worth one file of arithmetic.
 */
import assert from 'node:assert/strict';
import { sweepWhere } from './attachment-sweeper';

const HOUR = 60 * 60 * 1000;
const now = new Date('2026-08-16T12:00:00.000Z');

const where = sweepWhere(now, 24 * HOUR);
const [unclaimed, deleted] = where.OR;

// An unclaimed row is collected only once it is *older* than the grace period.
assert.equal(unclaimed?.messageId, null);
assert.deepEqual(unclaimed?.createdAt, { lte: new Date('2026-08-15T12:00:00.000Z') });
assert.ok(
  unclaimed!.createdAt.lte < now,
  'the cutoff is in the past: an upload from a minute ago must survive',
);

// A claimed row goes with its message, with no grace period of its own.
assert.deepEqual(deleted, { message: { deletedAt: { not: null } } });
assert.equal(Object.keys(deleted ?? {}).length, 1, 'nothing else narrows the deleted-message arm');

// A shorter grace means a later cutoff, not an earlier one.
const brief = sweepWhere(now, 1 * HOUR).OR[0]!;
assert.ok(brief.createdAt.lte > unclaimed!.createdAt.lte);

console.log('attachment-sweeper: ok');

/**
 * Removes attachment blobs nothing justifies keeping.
 *
 * Two kinds qualify. One is an upload nobody ever sent: a client that sealed a
 * file, uploaded it and then closed the composer leaves a paid-for object that
 * no message names. The other is a blob whose message is gone - deleted by its
 * author, deleted by a moderator, or destroyed with the channel, the server or
 * the account, all of which the null-on-delete foreign key turns into the same
 * unclaimed row.
 *
 * A message is soft-deleted, so a claimed row is collected on `deletedAt`
 * rather than on the row disappearing. The tombstone stays; the ciphertext it
 * used to point at does not.
 *
 * ponytail: a timer in the process, like the two sweeps either side of it.
 * Two replicas will overlap and both try to delete the same object, which is
 * why a delete that finds nothing is not an error.
 */
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { envNumber } from '@betweenus/config';
import { prisma } from '@betweenus/database';
import { Logger } from '@betweenus/logger';
import { getStorage } from '@betweenus/storage';

const HOUR_MS = 60 * 60 * 1000;

/** How often to look. Nothing here is urgent; it is disk, not correctness. */
const INTERVAL_MS = 6 * HOUR_MS;

/** Not at boot: a service starting is the worst moment to add storage work. */
const FIRST_RUN_DELAY_MS = 10 * 60_000;

/** How many objects one pass will delete, so a backlog is spread over passes. */
const BATCH = 500;

/**
 * How long an unclaimed upload is left alone.
 *
 * An upload is claimed by the message that carries it, which is sent seconds
 * later - but a client that uploads a large file, then waits for the user to
 * finish typing, is still holding a legitimately unclaimed blob. A day is far
 * longer than that gap and short enough that abandoned uploads do not
 * accumulate.
 */
function graceMs(): number {
  return envNumber('ATTACHMENT_GRACE_HOURS', 24) * HOUR_MS;
}

/**
 * Which rows a pass collects, as the query that finds them.
 *
 * Two arms, and the difference between them is the whole policy. A row that no
 * message ever claimed is only fair game once the grace period has passed,
 * because an upload in progress looks exactly like an abandoned one. A row
 * whose message has been deleted is fair game at once, however recently it was
 * uploaded - the message it belonged to is gone, and waiting a day to remove
 * what a moderator deleted is the wrong answer.
 *
 * Kept separate from the sweep so the decision can be asserted on without a
 * database: see `attachment-sweeper.check.ts`.
 */
export interface SweepWhere {
  OR: [
    { messageId: null; createdAt: { lte: Date } },
    { message: { deletedAt: { not: null } } },
  ];
}

export function sweepWhere(now: Date = new Date(), grace: number = graceMs()): SweepWhere {
  return {
    OR: [
      { messageId: null, createdAt: { lte: new Date(now.getTime() - grace) } },
      { message: { deletedAt: { not: null } } },
    ],
  };
}

/**
 * Removes the blobs of specific messages now, rather than at the next sweep.
 *
 * The sweeper on its own is correct but slow: up to six hours pass between
 * somebody deleting a photo and the ciphertext leaving the object store, and
 * "I deleted it" meaning "in a few hours" is not what anybody who presses that
 * button is asking for. So a delete, a burn and an expiry all call this, and
 * the sweeper stays behind them as the backstop that catches whatever this
 * could not reach - storage that was down, a process that died mid-delete, a
 * row orphaned by somebody else's cascade.
 *
 * Deliberately quiet about failure. The caller is a user pressing delete, and
 * the message is deleted whether or not the object store answered; what is
 * left behind is exactly what the sweeper exists to collect.
 */
export async function purgeMessageAttachments(messageIds: string[]): Promise<number> {
  if (messageIds.length === 0) return 0;

  const rows = await prisma.attachment.findMany({
    where: { messageId: { in: messageIds } },
    select: { id: true, key: true },
  });
  if (rows.length === 0) return 0;

  const storage = getStorage();
  const gone: string[] = [];
  for (const row of rows) {
    // Object first, then row - the same order and for the same reason as the
    // sweep below: a row removed first is a blob nothing can ever name again.
    try {
      await storage.delete(row.key);
      gone.push(row.id);
    } catch {
      // Left for the sweeper, which will find it unclaimed and try again.
    }
  }

  if (gone.length > 0) await prisma.attachment.deleteMany({ where: { id: { in: gone } } });
  return gone.length;
}

/** Deletes the objects and their rows. Returns how many objects went. */
export async function sweepAttachments(now: Date = new Date()): Promise<number> {
  const doomed = await prisma.attachment.findMany({
    where: sweepWhere(now),
    select: { id: true, key: true },
    orderBy: { createdAt: 'asc' },
    take: BATCH,
  });

  if (doomed.length === 0) return 0;

  const storage = getStorage();
  const gone: string[] = [];
  for (const row of doomed) {
    // The object goes first. A row removed before its object is a blob nothing
    // can ever name again; an object removed before its row is retried next
    // pass and deletes nothing the second time.
    try {
      await storage.delete(row.key);
      gone.push(row.id);
    } catch {
      // Storage that is unhappy now will be asked again in six hours.
    }
  }

  if (gone.length > 0) await prisma.attachment.deleteMany({ where: { id: { in: gone } } });
  return gone.length;
}

@Injectable()
export class AttachmentSweeper implements OnModuleInit, OnModuleDestroy {
  private timer: NodeJS.Timeout | null = null;
  private first: NodeJS.Timeout | null = null;

  constructor(private readonly logger: Logger) {}

  onModuleInit(): void {
    this.first = setTimeout(() => {
      void this.run();
      this.timer = setInterval(() => void this.run(), INTERVAL_MS);
      this.timer.unref?.();
    }, FIRST_RUN_DELAY_MS);
    this.first.unref?.();
  }

  private async run(): Promise<void> {
    try {
      const removed = await sweepAttachments();
      if (removed > 0) this.logger.info('Swept attachment blobs', { removed });
    } catch (error) {
      this.logger.warn('Could not sweep attachment blobs', { reason: String(error) });
    }
  }

  onModuleDestroy(): void {
    if (this.first) clearTimeout(this.first);
    if (this.timer) clearInterval(this.timer);
  }
}

import { Type } from 'class-transformer';
import {
  ArrayMaxSize,
  ArrayMinSize,
  IsArray,
  IsInt,
  IsNumberString,
  IsString,
  Length,
  Max,
  Min,
  ValidateNested,
} from 'class-validator';

export class StartMultipartDto {
  /** What the client says it is about to upload. Verified again on completion. */
  @IsInt()
  @Min(1)
  size!: number;
}

export class UploadPartDto {
  @IsString()
  @Length(1, 4096)
  ticket!: string;

  /** Multipart form fields arrive as text, so this is a numeric string. */
  @IsNumberString()
  partNumber!: string;
}

export class PartDto {
  @IsInt()
  @Min(1)
  @Max(10_000)
  partNumber!: number;

  @IsString()
  @Length(1, 256)
  etag!: string;
}

export class CompleteMultipartDto {
  @IsString()
  @Length(1, 4096)
  ticket!: string;

  @IsArray()
  @ArrayMinSize(1)
  @ArrayMaxSize(10_000)
  @ValidateNested({ each: true })
  @Type(() => PartDto)
  parts!: PartDto[];
}

export class AbortMultipartDto {
  @IsString()
  @Length(1, 4096)
  ticket!: string;
}

/**
 * Who may fetch the bytes of a one-time message.
 *
 * This is the rule the whole feature rests on. Everything the clients do - a
 * card that locks, a viewer that refuses to open twice - is software choosing
 * to behave, and a one-time message whose only guarantee is that the
 * recipient's client felt like keeping it is not a guarantee. The bytes come
 * through one door, and this is the check on it.
 *
 * Worth asserting rather than reading, because both refusals look redundant
 * until you ask what happens without them: without the author check a sender
 * re-opens their own message on a second device for ever, and without the
 * count check anybody replays the URL.
 */
import assert from 'node:assert/strict';
import { oneTimeLookLeft } from './uploads.controller';

const author = 'author';
const ada = 'ada';

// A recipient who has not looked has a look. This is the fetch that spends it,
// and it has to succeed - the view is recorded after the bytes are handed
// over, not before, or nobody could ever open one.
assert.equal(oneTimeLookLeft(ada, author, 0), true);

// And never again, however the second request is made: a rebuilt client, a
// replayed URL, a second device signed in to the same account.
assert.equal(oneTimeLookLeft(ada, author, 1), false);
assert.equal(oneTimeLookLeft(ada, author, 5), false);

// The author may not read it back, and not on the first attempt either. They
// sent it; it was never theirs to re-open. This is also the one case a client
// cannot enforce on its own, because the author is the account that had the
// plaintext to begin with.
assert.equal(oneTimeLookLeft(author, author, 0), false);
assert.equal(oneTimeLookLeft(author, author, 1), false);

// The author check is not a special case of the view count. An author who has
// never "viewed" their own message still has no look, which is the assertion
// that stops the first branch being deleted as redundant.
assert.equal(
  oneTimeLookLeft(author, author, 0),
  false,
  'an author with no view row is still refused',
);

console.log('one-time-read: ok');

/**
 * Clears out multipart uploads nobody finished.
 *
 * A client that starts a large upload and then closes, crashes or loses its
 * connection leaves its parts behind. `LocalStorageDriver.sweepStaleMultipart`
 * has always been able to remove them and nothing has ever called it, so a
 * deployment's scratch directory only grew - by the size of every abandoned
 * upload, which is by definition the large ones.
 *
 * S3 is deliberately not swept from here. A bucket has a lifecycle rule for
 * exactly this (`AbortIncompleteMultipartUpload`), it is one line of bucket
 * configuration, and walking a bucket from the application to do the same thing
 * would be slower, more expensive and a worse answer. The deployment documentation is where
 * that belongs; this covers the driver that has nobody else to do it.
 *
 * ponytail: a timer in the process. Two replicas will both sweep and race each
 * other into the same directories, which `sweepStaleMultipart` already treats
 * as normal - a part that has gone is a part that does not need removing.
 */
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { envNumber } from '@betweenus/config';
import { Logger } from '@betweenus/logger';
import { LocalStorageDriver, getStorage } from '@betweenus/storage';

const HOUR_MS = 60 * 60 * 1000;

/** How often to look. An abandoned upload is not urgent. */
const INTERVAL_MS = 6 * HOUR_MS;

/** Not at boot: a service starting is the worst moment to add disk work. */
const FIRST_RUN_DELAY_MS = 5 * 60_000;

/**
 * How long a scratch directory may sit untouched before it is fair game.
 *
 * Generously longer than any real upload: the client uploads parts one after
 * another, so an upload still in progress is touched every few seconds, and the
 * only thing this can catch is one that stopped. Twelve hours means a laptop
 * that was suspended mid-upload still finds its parts when it wakes.
 */
function maxAgeMs(): number {
  return envNumber('UPLOAD_SCRATCH_MAX_AGE_HOURS', 12) * HOUR_MS;
}

@Injectable()
export class ScratchSweeper implements OnModuleInit, OnModuleDestroy {
  private timer: NodeJS.Timeout | null = null;
  private first: NodeJS.Timeout | null = null;

  constructor(private readonly logger: Logger) {}

  onModuleInit(): void {
    if (!(getStorage() instanceof LocalStorageDriver)) return;

    this.first = setTimeout(() => {
      void this.run();
      this.timer = setInterval(() => void this.run(), INTERVAL_MS);
      this.timer.unref?.();
    }, FIRST_RUN_DELAY_MS);
    this.first.unref?.();
  }

  private async run(): Promise<void> {
    const storage = getStorage();
    if (!(storage instanceof LocalStorageDriver)) return;

    try {
      const removed = await storage.sweepStaleMultipart(maxAgeMs());
      if (removed > 0) this.logger.info('Swept abandoned uploads', { removed });
    } catch (error) {
      this.logger.warn('Could not sweep abandoned uploads', { reason: String(error) });
    }
  }

  onModuleDestroy(): void {
    if (this.first) clearTimeout(this.first);
    if (this.timer) clearInterval(this.timer);
  }
}

/**
 * File upload and download.
 *
 * Two kinds of object pass through here.
 *
 * *Pictures* - avatars and server icons - arrive in the clear, because the
 * member list on every client has to render them without holding a channel
 * key. They are checked against an image allowlist and a small size cap, and
 * they are the only thing this service ever serves inline.
 *
 * *Attachments* arrive already encrypted under the channel key: the client
 * seals the file before the first byte leaves it, so what lands here is opaque.
 * That is what lets a channel carry any file at all - there is no content type
 * to allowlist - and it is why attachments always download rather than render.
 *
 * Anything over one request body's worth goes up in parts. The session that
 * ties the parts together is a sealed ticket held by the client, not state held
 * here, so a second chat-service replica can accept the next part.
 */
import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  ForbiddenException,
  Req,
  Res,
  UnauthorizedException,
  UploadedFile,
  UseGuards,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import type { Request, Response } from 'express';
import { prisma, resolveChannelAccess } from '@betweenus/database';
import {
  CurrentUser,
  JwtAuthGuard,
  bearerToken,
  openSecret,
  sealSecret,
  verifyAccessToken,
  type AuthenticatedUser,
} from '@betweenus/auth';
import {
  MAX_ATTACHMENT_BYTES,
  MAX_PICTURE_BYTES,
  MAX_UPLOAD_BYTES,
  MULTIPART_PREFIX,
  assertSafeKey,
  buildKey,
  getStorage,
  detectPictureType,
  isInlineSafe,
  type MultipartSession,
  type StoredObject,
  type UploadedPart,
} from '@betweenus/storage';
import { mayReadStatusMedia } from '../status/status.service';
import {
  AbortMultipartDto,
  CompleteMultipartDto,
  StartMultipartDto,
  UploadPartDto,
} from './dto';

/** Ciphertext has no type of its own, and claiming one would be a lie. */
const OPAQUE = 'application/octet-stream';

/** How long a client has to finish an upload it started. */
const TICKET_TTL_MS = 6 * 60 * 60 * 1000;

interface TicketPayload extends MultipartSession {
  /** Who started it. A ticket is not transferable between accounts. */
  userId: string;
  expiresAt: number;
}

@Controller('uploads')
export class UploadsController {
  /**
   * An avatar or a server icon. The client has already downscaled it; this is
   * the check that the thing on the wire really is a small raster image.
   */
  @Post('picture')
  @UseGuards(JwtAuthGuard)
  @UseInterceptors(FileInterceptor('file', { limits: { fileSize: MAX_PICTURE_BYTES, files: 1 } }))
  async uploadPicture(
    @CurrentUser() user: AuthenticatedUser,
    @UploadedFile() file: Express.Multer.File | undefined,
  ): Promise<StoredObject> {
    if (!file) {
      throw new BadRequestException({ code: 'NO_FILE', message: 'No file was uploaded' });
    }
    // The bytes, not the header. `file.mimetype` and `file.originalname` are
    // both values the client chose, and this route used to write one into the
    // stored content type and the other into the key's extension - so a file
    // could claim to be a PNG and be anything, and the claim was what got served
    // back. What it *is* now decides both, and the claim is not consulted at all:
    // checking it as well would be two answers that can disagree.
    const detected = detectPictureType(file.buffer);
    if (!detected) {
      throw new BadRequestException({
        code: 'UNSUPPORTED_MEDIA_TYPE',
        message: 'That file is not a PNG, JPEG, GIF or WebP',
      });
    }

    const key = buildKey(`pictures/${user.id}`, `picture${detected.extension}`);
    return getStorage().put(key, file.buffer, detected.contentType);
  }

  /** An encrypted attachment small enough to arrive in one request. */
  @Post()
  @UseGuards(JwtAuthGuard)
  @UseInterceptors(FileInterceptor('file', { limits: { fileSize: MAX_UPLOAD_BYTES, files: 1 } }))
  async upload(
    @CurrentUser() user: AuthenticatedUser,
    @UploadedFile() file: Express.Multer.File | undefined,
  ): Promise<StoredObject> {
    if (!file) {
      throw new BadRequestException({ code: 'NO_FILE', message: 'No file was uploaded' });
    }

    // The key is generated from a UUID; the client filename never reaches it,
    // so an attacker cannot choose where the file lands. The real name travels
    // inside the encrypted message instead.
    const key = buildKey(`attachments/${user.id}`, '');
    const object = await getStorage().put(key, file.buffer, OPAQUE);
    return record(object, user.id);
  }

  // --- Multipart --------------------------------------------------------------

  @Post('multipart')
  @UseGuards(JwtAuthGuard)
  async startMultipart(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: StartMultipartDto,
  ): Promise<{ ticket: string; maxPartBytes: number }> {
    if (dto.size > MAX_ATTACHMENT_BYTES) {
      throw new BadRequestException({
        code: 'FILE_TOO_LARGE',
        message: `Attachments are limited to ${MAX_ATTACHMENT_BYTES} bytes`,
      });
    }

    const key = buildKey(`attachments/${user.id}`, '');
    const session = await getStorage().createMultipart(key, OPAQUE);
    return { ticket: issueTicket(session, user.id), maxPartBytes: MAX_UPLOAD_BYTES };
  }

  @Post('multipart/part')
  @UseGuards(JwtAuthGuard)
  @UseInterceptors(FileInterceptor('file', { limits: { fileSize: MAX_UPLOAD_BYTES, files: 1 } }))
  async uploadPart(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: UploadPartDto,
    @UploadedFile() file: Express.Multer.File | undefined,
  ): Promise<UploadedPart> {
    if (!file) {
      throw new BadRequestException({ code: 'NO_FILE', message: 'No part was uploaded' });
    }
    const session = openTicket(dto.ticket, user.id);
    const partNumber = Number(dto.partNumber);

    try {
      return await getStorage().uploadPart(session, partNumber, file.buffer);
    } catch (error) {
      throw new BadRequestException({
        code: 'PART_REJECTED',
        message: error instanceof Error ? error.message : 'The part was not stored',
      });
    }
  }

  @Post('multipart/complete')
  @UseGuards(JwtAuthGuard)
  async completeMultipart(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: CompleteMultipartDto,
  ): Promise<StoredObject> {
    const session = openTicket(dto.ticket, user.id);

    try {
      const object = await getStorage().completeMultipart(session, dto.parts);
      if (object.size > MAX_ATTACHMENT_BYTES) {
        // The declared size was a promise; this is the measurement. A client
        // that sent more parts than it announced does not get to keep them.
        await getStorage().delete(object.key);
        throw new BadRequestException({
          code: 'FILE_TOO_LARGE',
          message: `Attachments are limited to ${MAX_ATTACHMENT_BYTES} bytes`,
        });
      }
      return await record(object, user.id);
    } catch (error) {
      if (error instanceof BadRequestException) throw error;
      throw new BadRequestException({
        code: 'UPLOAD_INCOMPLETE',
        message: error instanceof Error ? error.message : 'The upload could not be assembled',
      });
    }
  }

  @Delete('multipart')
  @UseGuards(JwtAuthGuard)
  async abortMultipart(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: AbortMultipartDto,
  ): Promise<{ aborted: true }> {
    const session = openTicket(dto.ticket, user.id);
    await getStorage()
      .abortMultipart(session)
      // An upload that was never written to has nothing to abort, and the
      // client that gave up on it should not have to care.
      .catch(() => undefined);
    return { aborted: true };
  }

  // --- Download ---------------------------------------------------------------

  /**
   * Serves objects written by the local driver. With S3 configured the client
   * fetches the bucket URL directly and never reaches this route - it stays
   * mounted so the same message URLs keep working after a driver switch.
   *
   * Authentication is asked for on an attachment and not on a picture, and the
   * split is deliberate rather than an oversight.
   *
   * An attachment is ciphertext, so an unauthenticated read leaked nothing
   * readable - but "nothing readable" is not the same as "nothing". It leaked
   * the bytes and their size to anybody who ever saw the URL: a proxy log, a
   * browser history, a screenshot of a devtools panel. The key is an unguessable
   * UUID, so this was a capability URL, and a capability URL that never expires
   * is one leak away from permanent. The clients already send the header.
   *
   * Holding *a* session is not the same as being entitled to this object,
   * though, and for a while it was treated as if it were: any signed-in account
   * that came by a key could fetch the bytes behind it. So the row is consulted
   * as well - the uploader, or somebody who can see the channel the message
   * carrying it was sent to. It is still ciphertext either way; this is the
   * layer that stops a leaked key being a leaked file.
   *
   * A picture - an avatar, a server icon - is drawn by an `<img>` tag, which
   * cannot carry an Authorization header. Requiring one there would mean every
   * avatar in the app failing to load. It stays public, which
   * development/E2EE.md has always said it is.
   */
  @Get(':key(*)')
  async download(
    @Param('key') key: string,
    @Req() request: Request,
    @Res() response: Response,
  ): Promise<void> {
    try {
      assertSafeKey(key);
    } catch {
      throw new BadRequestException({ code: 'INVALID_KEY', message: 'Invalid object key' });
    }

    // Half-uploaded parts are scratch space, not objects anyone may read - and
    // that is true of the account that uploaded them too, so it is settled
    // before identity is looked at rather than after. Below the ownership check
    // this could never fire: `mayRead` wants an attachment row, a part has
    // none, and every request for one was refused as somebody else's file
    // rather than as the invalid key it is.
    if (key.startsWith(`${MULTIPART_PREFIX}/`)) {
      throw new BadRequestException({ code: 'INVALID_KEY', message: 'Invalid object key' });
    }

    if (!key.startsWith('pictures/')) {
      const userId = callerId(request);
      if (!userId) {
        throw new UnauthorizedException({
          code: 'UNAUTHORIZED',
          message: 'Sign in to fetch this object',
        });
      }
      if (!(await mayRead(userId, key))) {
        throw new ForbiddenException({
          code: 'FORBIDDEN',
          message: 'This file is not yours to fetch',
        });
      }
    }

    const storage = getStorage();
    if (!(await storage.exists(key))) {
      response.status(404).json({
        error: { code: 'OBJECT_NOT_FOUND', message: 'File not found', requestId: 'unknown' },
      });
      return;
    }

    // A picture and a status carry their real type, and in both cases only
    // because the bytes were checked on the way in - the key's extension is
    // written from what the file turned out to be, never from what it claimed.
    // An attachment is ciphertext and has no type to tell the truth about: it
    // is served as bytes, and the client decrypts it in memory.
    const typed = key.startsWith('pictures/') || key.startsWith('status/');
    const contentType = typed ? contentTypeFor(key) : OPAQUE;
    response.setHeader('Content-Type', contentType);
    response.setHeader('Cache-Control', 'private, max-age=86400');
    response.setHeader(
      'Content-Disposition',
      isInlineSafe(contentType) ? 'inline' : 'attachment',
    );
    response.setHeader('X-Content-Type-Options', 'nosniff');

    const stream = await storage.get(key);
    stream.on('error', () => response.destroy());
    stream.pipe(response);
  }
}

/**
 * Notes an uploaded blob so something can eventually collect it.
 *
 * Every attachment starts unclaimed. Sending a message claims the keys it
 * carries; anything still unclaimed when the grace period runs out was an
 * upload nobody sent, and the sweeper removes it either way. Recording it is
 * therefore not optional bookkeeping - a blob with no row is a blob no sweep
 * can ever name - so a failure here undoes the upload rather than leaving one
 * behind for ever.
 */
async function record(object: StoredObject, userId: string): Promise<StoredObject> {
  try {
    await prisma.attachment.create({
      data: { key: object.key, uploaderId: userId, size: object.size },
    });
  } catch (error) {
    await getStorage().delete(object.key).catch(() => undefined);
    throw new BadRequestException({
      code: 'UPLOAD_NOT_RECORDED',
      message: error instanceof Error ? error.message : 'The upload could not be recorded',
    });
  }
  return object;
}

/**
 * The multipart session, sealed so the client can hold it. Sealing rather than
 * storing means no session table, no Redis key, and no affinity between the
 * client and whichever replica answered the last request.
 */
function issueTicket(session: MultipartSession, userId: string): string {
  const payload: TicketPayload = { ...session, userId, expiresAt: Date.now() + TICKET_TTL_MS };
  return sealSecret(JSON.stringify(payload));
}

function openTicket(ticket: string, userId: string): MultipartSession {
  const raw = openSecret(ticket);
  if (!raw) {
    throw new BadRequestException({ code: 'INVALID_TICKET', message: 'Unknown upload' });
  }

  const payload = JSON.parse(raw) as TicketPayload;
  // A sealed ticket cannot be forged, but it can be replayed by whoever it
  // leaked to; bind it to the account that started the upload, and to a clock.
  if (payload.userId !== userId) {
    throw new BadRequestException({ code: 'INVALID_TICKET', message: 'Unknown upload' });
  }
  if (payload.expiresAt < Date.now()) {
    throw new BadRequestException({ code: 'UPLOAD_EXPIRED', message: 'This upload has expired' });
  }

  return { key: payload.key, contentType: payload.contentType, externalId: payload.externalId };
}

const EXTENSION_TYPES: Record<string, string> = {
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  // Status videos. `isInlineSafe` still says no to both, so they are sent as a
  // download and never rendered in this origin - the client fetches the bytes
  // and plays them from a blob URL of its own.
  '.mp4': 'video/mp4',
  '.webm': 'video/webm',
};

function contentTypeFor(key: string): string {
  const dot = key.lastIndexOf('.');
  const extension = dot >= 0 ? key.slice(dot).toLowerCase() : '';
  return EXTENSION_TYPES[extension] ?? OPAQUE;
}

/**
 * Who this request is, or null when it is nobody.
 *
 * `JwtAuthGuard` is the usual answer and is the wrong shape here: the guard
 * applies to a whole route, and this route serves two kinds of object with two
 * different rules - a picture is public because an `<img>` tag cannot send a
 * header, an attachment is not. So the check is a function rather than a
 * decorator, and it is the same verification the guard performs.
 */
function callerId(request: Request): string | null {
  const token = bearerToken(request.headers.authorization);
  if (!token) return null;
  try {
    return verifyAccessToken(token).sub;
  } catch {
    return null;
  }
}

/**
 * Whether this account is entitled to the object behind a key.
 *
 * Every attachment has a row - `record` makes sure of it, and undoes the upload
 * rather than leave one without - so a key with no row is a key to nothing, and
 * an unclaimed upload belongs to whoever made it and to nobody else. Once a
 * message carries it, the question becomes the same one the message itself
 * answers: can this account see that channel. `resolveChannelAccess` is where
 * that already lives, private channels and direct messages included.
 */
async function mayRead(userId: string, key: string): Promise<boolean> {
  // A status has no attachment row and no channel: its audience is a friend
  // list, and the rule lives beside that list rather than being written a
  // second time here. The prefix is what distinguishes the two - `buildKey` is
  // the only thing that writes it, and `assertSafeKey` above has already
  // refused anything that could climb out of it.
  if (key.startsWith('status/')) return mayReadStatusMedia(userId, key);

  const row = await prisma.attachment.findUnique({
    where: { key },
    select: {
      uploaderId: true,
      message: {
        select: {
          id: true,
          channelId: true,
          authorId: true,
          viewOnce: true,
          views: { where: { userId }, select: { id: true } },
        },
      },
    },
  });
  if (!row) return false;

  // A one-time message is the one case where holding the upload is not a
  // licence to read it, so the ownership shortcut below has to be gated
  // before it fires rather than after.
  if (row.message?.viewOnce) return mayOpenOneTime(userId, row.message);

  if (row.uploaderId === userId) return true;
  if (!row.message) return false;
  return (await resolveChannelAccess(userId, row.message.channelId)) !== null;
}

/**
 * Whether this account may fetch the bytes of a one-time message, which is a
 * narrower question than whether it may see the channel.
 *
 * This is where "one look" is actually enforced. Everything the clients do -
 * a card that locks, a viewer that will not open twice - is a client being
 * well behaved, and a one-time message whose only guarantee is that the
 * recipient's software chose to keep it is not a guarantee at all. The rule
 * lives here because this is the one door the bytes come through.
 *
 * Two refusals, and the first is the one people ask about:
 *
 * **The author may not read it back.** They sent it; it was never theirs to
 * re-open, and a sender who can look at it again on another device has a
 * message that is one-time for exactly one of the two people in the
 * conversation. It is also the case the clients cannot enforce on their own,
 * because the author is the account holding the plaintext to begin with.
 *
 * **Nobody may read it twice.** A view row exists from the moment somebody
 * spends their look, so the second fetch is refused however the request was
 * made - a rebuilt client, a replayed URL, a second device.
 *
 * The order matters: the look is recorded *after* the fetch, so the fetch that
 * spends it still succeeds and only the ones after it do not.
 */
function mayOpenOneTime(
  userId: string,
  message: { authorId: string; channelId: string; views: Array<{ id: string }> },
): Promise<boolean> {
  if (!oneTimeLookLeft(userId, message.authorId, message.views.length)) {
    return Promise.resolve(false);
  }
  return resolveChannelAccess(userId, message.channelId).then((access) => access !== null);
}

/**
 * Whether this account has a look left in a one-time message, before channel
 * access is even considered.
 *
 * Split out from the query so the rule can be asserted on without a database.
 * It is two comparisons and it is the whole of the guarantee, which is exactly
 * the kind of thing that gets "simplified" by somebody who reads the author
 * check as a redundant special case of the view check.
 */
export function oneTimeLookLeft(userId: string, authorId: string, viewsByCaller: number): boolean {
  // The author sent it. It was never theirs to re-open, and a sender who can
  // look again on another device has a message that is one-time for exactly
  // one of the two people in the conversation.
  if (userId === authorId) return false;
  // Spent. The row is written the moment somebody looks, so every fetch after
  // the first is refused however it was made.
  return viewsByCaller === 0;
}

import {
  IsArray,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Length,
  MaxLength,
  Matches,
  ValidateIf,
  ValidateNested,
} from 'class-validator';
import { Type } from 'class-transformer';
import {
  UPLOADED_PICTURE_URL,
  WEBHOOK_CONTENT_MAX_LENGTH,
  WEBHOOK_NAME_MAX_LENGTH,
  type CreateWebhookRequest,
  type ExecuteWebhookRequest,
  type UpdateWebhookRequest,
  type WebhookEmbed,
} from '@betweenus/shared-types';

export class CreateWebhookDto implements CreateWebhookRequest {
  @IsUUID()
  channelId!: string;

  @IsString()
  @Length(1, WEBHOOK_NAME_MAX_LENGTH)
  name!: string;

  /**
   * It has to be one of ours, for the reason an avatar does: this picture is
   * drawn in every client that can see the channel, so an arbitrary URL would
   * be a beacon reporting who read it.
   */
  @IsOptional()
  @ValidateIf((dto: CreateWebhookDto) => dto.avatarUrl !== null && dto.avatarUrl !== undefined)
  @IsString()
  @MaxLength(512)
  @Matches(UPLOADED_PICTURE_URL, { message: 'avatarUrl must be an uploaded picture' })
  avatarUrl?: string | null;
}

export class UpdateWebhookDto implements UpdateWebhookRequest {
  @IsOptional()
  @IsString()
  @Length(1, WEBHOOK_NAME_MAX_LENGTH)
  name?: string;

  @IsOptional()
  @ValidateIf((dto: UpdateWebhookDto) => dto.avatarUrl !== null && dto.avatarUrl !== undefined)
  @IsString()
  @MaxLength(512)
  @Matches(UPLOADED_PICTURE_URL, { message: 'avatarUrl must be an uploaded picture' })
  avatarUrl?: string | null;
}

/** The part of a Discord embed this app draws. See `renderBody`. */
export class WebhookEmbedDto implements WebhookEmbed {
  @IsOptional()
  @IsString()
  @MaxLength(256)
  title?: string;

  @IsOptional()
  @IsString()
  @MaxLength(WEBHOOK_CONTENT_MAX_LENGTH)
  description?: string;

  @IsOptional()
  @IsString()
  @MaxLength(2048)
  url?: string;

  @IsOptional()
  @IsInt()
  color?: number;

  /**
   * Left loose on purpose.
   *
   * Every field here is optional and every one of them is rendered by
   * `renderEmbed`, which reads each value defensively because the payloads
   * arrive from integrations written against Discord rather than against this.
   * Validating the shape strictly would turn "we did not draw your footer" into
   * "your deploy notification 400s", and the whole point of copying Discord's
   * body is that an existing integration works by changing only the URL.
   */
  @IsOptional()
  @IsArray()
  fields?: Array<{ name: string; value: string; inline?: boolean }>;

  @IsOptional()
  footer?: { text: string };

  @IsOptional()
  @IsString()
  timestamp?: string;
}

export class ExecuteWebhookDto implements ExecuteWebhookRequest {
  /**
   * Optional because `embeds` may carry the whole message. The service refuses
   * a payload that renders to nothing, which is the check that actually
   * matters and cannot be written as a decorator on one field.
   */
  @IsOptional()
  @IsString()
  @MaxLength(WEBHOOK_CONTENT_MAX_LENGTH)
  content?: string;

  /** Accepted and ignored; the response lists it. See `ignoredFields`. */
  @IsOptional()
  @IsString()
  @MaxLength(WEBHOOK_NAME_MAX_LENGTH)
  username?: string;

  /** Accepted and ignored; the response lists it. */
  @IsOptional()
  @IsString()
  @MaxLength(2048)
  avatar_url?: string;

  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => WebhookEmbedDto)
  embeds?: WebhookEmbedDto[];
}

/**
 * Self-check for how a Discord webhook payload becomes one plaintext body.
 *
 * Run with `pnpm --filter @betweenus/chat-service check`. Worth pinning because
 * the input is written by somebody else's integration against somebody else's
 * API: the interesting cases are all "a field arrived that this app does not
 * model", and the required behaviour is to keep the words and drop the
 * furniture rather than to refuse the request.
 */
import assert from 'node:assert/strict';
import { ignoredFields, renderBody } from './webhooks.service';

// --- the ordinary case: a bare content field ---------------------------------

assert.equal(renderBody({ content: 'Deploy finished' }), 'Deploy finished');
assert.equal(renderBody({ content: '  padded  ' }), 'padded', 'trimmed');

// --- nothing at all --------------------------------------------------------

// The service refuses these; what matters here is that they render empty
// rather than to whitespace, because whitespace would pass a length check.
assert.equal(renderBody({}), '');
assert.equal(renderBody({ content: '   ' }), '');
assert.equal(renderBody({ embeds: [] }), '');
assert.equal(renderBody({ embeds: [{}] }), '', 'an embed with no fields is not content');

// --- embeds become Markdown -------------------------------------------------

const embedded = renderBody({
  embeds: [{ title: 'Build #402', description: 'All checks passed' }],
});
assert.equal(embedded, '**Build #402**\nAll checks passed');

// A title with a URL is the one part of an embed anybody clicks.
assert.equal(
  renderBody({ embeds: [{ title: 'Build #402', url: 'https://ci.example.com/402' }] }),
  '**[Build #402](https://ci.example.com/402)**',
);

// Fields keep their names. Dropping them would leave a column of bare values
// with nothing saying what each one is.
assert.equal(
  renderBody({
    embeds: [{ fields: [{ name: 'Branch', value: 'master', inline: true }] }],
  }),
  '**Branch**\nmaster',
);

// A field with a value and no name is still worth printing.
assert.equal(renderBody({ embeds: [{ fields: [{ name: '', value: 'bare' }] }] }), 'bare');

// Content and embeds both, separated so they do not read as one paragraph.
assert.equal(
  renderBody({ content: 'Heads up', embeds: [{ description: 'disk 91% full' }] }),
  'Heads up\n\ndisk 91% full',
);

assert.equal(renderBody({ embeds: [{ footer: { text: 'ci-runner-3' } }] }), '_ci-runner-3_');

// --- hostile and malformed input --------------------------------------------

// These arrive from integrations written against Discord, so the renderer reads
// every value defensively rather than trusting the declared type. A payload
// that throws here would be a 500 on somebody's deploy notification.
assert.equal(renderBody({ content: 42 as never }), '', 'a non-string content is not content');
assert.equal(renderBody({ embeds: 'nope' as never }), '');
assert.equal(renderBody({ embeds: [{ fields: 'nope' as never }] }), '');
assert.equal(renderBody({ embeds: [{ title: null as never, description: 'kept' }] }), 'kept');

// --- the embed cap ----------------------------------------------------------

const many = renderBody({ embeds: Array.from({ length: 25 }, (_, i) => ({ title: `e${i}` })) });
assert.equal(many.split('\n\n').length, 10, 'at most WEBHOOK_EMBED_MAX embeds are rendered');
assert.ok(many.includes('**e9**') && !many.includes('**e10**'), 'and it keeps the first ten');

// --- what was accepted and then not used ------------------------------------

// Reported rather than swallowed: an integration whose picture or name is not
// showing up has no way to tell a policy from a bug, and would go looking for
// the bug.
assert.deepEqual(ignoredFields({ content: 'hi' }), [], 'a plain message ignores nothing');
assert.deepEqual(ignoredFields({ avatar_url: 'https://elsewhere.example/x.png' }), ['avatar_url']);
assert.deepEqual(ignoredFields({ username: 'Deploy Bot' }), ['username']);
assert.deepEqual(ignoredFields({ embeds: [{ color: 5814783 }] }), ['embed color']);
assert.ok(
  ignoredFields({ embeds: Array.from({ length: 25 }, () => ({})) }).includes('embeds beyond 10'),
);
// An empty string is not an override anybody made; saying it was ignored would
// be noise on every payload from a client that always sends the key.
assert.deepEqual(ignoredFields({ username: '', avatar_url: '' }), []);

console.log('webhook-body: ok');

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type { Message, WebhookSummary, WebhookWithToken } from '@betweenus/shared-types';
import { WebhooksService } from './webhooks.service';
import { CreateWebhookDto, ExecuteWebhookDto, UpdateWebhookDto } from './dto';

/**
 * Managing a channel's webhooks. Every route here needs `MANAGE_WEBHOOK` on the
 * channel's server, checked in the service rather than inline - see
 * `WebhooksService.requireManage`.
 *
 * Executing one is deliberately **not** here: it is unauthenticated, and a
 * controller-wide `JwtAuthGuard` with one route poking a hole in it is a hole
 * somebody eventually widens by accident. See `WebhookExecuteController`.
 */
@Controller('webhooks')
@UseGuards(JwtAuthGuard)
export class WebhooksController {
  constructor(private readonly webhooks: WebhooksService) {}

  @Get()
  list(
    @CurrentUser() user: AuthenticatedUser,
    @Query('channelId', ParseUUIDPipe) channelId: string,
  ): Promise<WebhookSummary[]> {
    return this.webhooks.list(user.id, channelId);
  }

  @Post()
  create(
    @CurrentUser() user: AuthenticatedUser,
    @Body() body: CreateWebhookDto,
  ): Promise<WebhookWithToken> {
    return this.webhooks.create(user.id, body.channelId, body.name, body.avatarUrl ?? null);
  }

  @Patch(':webhookId')
  update(
    @CurrentUser() user: AuthenticatedUser,
    @Param('webhookId', ParseUUIDPipe) webhookId: string,
    @Body() body: UpdateWebhookDto,
  ): Promise<WebhookSummary> {
    return this.webhooks.update(user.id, webhookId, body);
  }

  /** A new token, invalidating the old one. The only way back from a leak. */
  @Post(':webhookId/rotate')
  rotate(
    @CurrentUser() user: AuthenticatedUser,
    @Param('webhookId', ParseUUIDPipe) webhookId: string,
  ): Promise<WebhookWithToken> {
    return this.webhooks.rotate(user.id, webhookId);
  }

  @Delete(':webhookId')
  @HttpCode(204)
  remove(
    @CurrentUser() user: AuthenticatedUser,
    @Param('webhookId', ParseUUIDPipe) webhookId: string,
  ): Promise<void> {
    return this.webhooks.remove(user.id, webhookId);
  }
}

/**
 * The one unauthenticated route in this service.
 *
 * Its own controller precisely so it carries no `JwtAuthGuard` to exempt itself
 * from: the authority is the token in the path, and that is the whole point -
 * a webhook has to be callable by a `curl` in a deploy script that holds no
 * account, no refresh token and no way to get one.
 *
 * `POST` only, and never `GET`: a GET that posts a message is one a link
 * preview crawler fires by following the URL out of a chat window.
 */
@Controller('webhooks')
export class WebhookExecuteController {
  constructor(private readonly webhooks: WebhooksService) {}

  @Post(':webhookId/:token')
  @HttpCode(200)
  execute(
    // Not `ParseUUIDPipe`: an unauthenticated route should answer a malformed
    // id the same way it answers a wrong one, and a 400 saying "that is not a
    // UUID" tells a prober what shape to guess in.
    @Param('webhookId') webhookId: string,
    @Param('token') token: string,
    @Body() body: ExecuteWebhookDto,
  ): Promise<{ message: Message; ignored: string[] }> {
    return this.webhooks.execute(webhookId, token, body);
  }
}

/**
 * Webhooks: a URL an outside system POSTs to in order to say something in a
 * channel.
 *
 * Discord's shape, because it is the one every CI runner, alerting stack and
 * "send to chat" integration already speaks - one opaque URL carrying its own
 * authority, a JSON body with a `content` field, and no account, OAuth dance or
 * bot framework anywhere near it. A webhook that needed a client library would
 * not be reachable from the `curl` in somebody's deploy script, which is the
 * entire reason to have one.
 *
 * ## Why this lives in chat-service
 *
 * Managing a webhook is a channel operation and would fit `server-service`;
 * *executing* one writes a message and has to broadcast it, which only this
 * service can do. Splitting the two would put one `/api/v1/webhooks` prefix
 * across two upstreams in the gateway, so both halves are here and the routing
 * stays one line.
 *
 * ## The plaintext exception
 *
 * **A webhook body is stored and delivered in the clear.** This is the single
 * documented exception to the sealed-envelope rule, and it is deliberate.
 *
 * The design assumes every author holds the channel key. A build server does
 * not, cannot be given one - handing a channel key to a shell script is handing
 * away the channel, to everyone who can read that script, permanently - and
 * could not use one without this project shipping its crypto to every language
 * anybody writes a deploy script in.
 *
 * So the trade is made visible rather than hidden. `Message.kind` is `WEBHOOK`,
 * every client draws the row with a badge saying it was not encrypted, and the
 * channel says a webhook is attached. A channel with a webhook on it is a
 * channel whose guarantee is now "everything except what the robots say", and
 * the clients say exactly that instead of implying more.
 *
 * Nothing here weakens a *person's* message: `POST /api/v1/messages` still
 * takes a sealed envelope and this service still cannot read one.
 */
import { createHash, randomBytes } from 'node:crypto';
import { envOr } from '@betweenus/config';
import {
  ForbiddenException,
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { prisma, resolveChannelAccess } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { PERMISSIONS } from '@betweenus/permissions';
import {
  WEBHOOK_CONTENT_MAX_LENGTH,
  WEBHOOK_EMBED_MAX,
  type ExecuteWebhookRequest,
  type Message,
  type WebhookEmbed,
  type WebhookSummary,
  type WebhookWithToken,
} from '@betweenus/shared-types';
import { toMessage } from '../messages/messages.service';

/**
 * How many random bytes the token half of the URL carries.
 *
 * 32 bytes, base64url, is 43 characters - the same order as Discord's and far
 * past guessing. It is the *only* thing protecting a channel from anybody who
 * finds the URL, so it is sized as a secret rather than as an identifier.
 */
const TOKEN_BYTES = 32;

/** Only what a client draws. The row also carries the hash, which nothing may read. */
const WEBHOOK_SELECT = {
  id: true,
  channelId: true,
  name: true,
  avatarUrl: true,
  lastUsedAt: true,
  createdAt: true,
  createdBy: {
    select: { id: true, username: true, displayName: true, avatarUrl: true, coverUrl: true, about: true },
  },
} as const;

const MESSAGE_INCLUDE = {
  author: true,
  deletedBy: true,
  reactions: { select: { userId: true, emoji: true } },
  views: { select: { userId: true } },
  webhook: { select: { id: true, name: true, avatarUrl: true } },
} as const;

/**
 * SHA-256 of a token, which is the only form of it this service keeps.
 *
 * The same rule `RemoteMachine.agentTokenHash` and `PasswordReset.tokenHash`
 * already follow. Discord keeps its webhook URLs re-readable so it can show
 * them again; a token a database can be asked for is a token a database dump
 * hands over, and losing this one costs a rotation rather than an account.
 *
 * No salt and no slow KDF, deliberately: this is a 256-bit random value, not a
 * password, so there is no dictionary to run and nothing for a work factor to
 * buy. What it needs is a constant-time single lookup, which is what a unique
 * index on the digest gives.
 */
function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('hex');
}

@Injectable()
export class WebhooksService {
  constructor(private readonly events: EventBus) {}

  /**
   * Every webhook on a channel.
   *
   * `MANAGE_WEBHOOK` to *see* them and not merely to change them: the list is
   * how somebody finds out that a channel they are in is being posted into by
   * an outside system, and a member who can read that list can tell that the
   * channel's plaintext exception is live. That is worth showing, but the audit
   * question ("who let a robot in here") belongs with the people who can answer
   * it. Members learn a webhook exists from the badge on its messages, which is
   * the honest place for them to learn it.
   */
  async list(userId: string, channelId: string): Promise<WebhookSummary[]> {
    await this.requireManage(userId, channelId);
    const rows = await prisma.webhook.findMany({
      where: { channelId },
      select: WEBHOOK_SELECT,
      orderBy: { createdAt: 'asc' },
    });
    return rows.map(toSummary);
  }

  /**
   * Mints one, and returns the URL. This is the only moment the token exists in
   * readable form outside the caller's screen.
   */
  async create(
    userId: string,
    channelId: string,
    name: string,
    avatarUrl: string | null,
  ): Promise<WebhookWithToken> {
    await this.requireManage(userId, channelId);

    const token = randomBytes(TOKEN_BYTES).toString('base64url');
    const row = await prisma.webhook.create({
      data: {
        channelId,
        name: name.trim(),
        avatarUrl,
        createdById: userId,
        tokenHash: hashToken(token),
      },
      select: WEBHOOK_SELECT,
    });
    return { ...toSummary(row), url: urlFor(row.id, token) };
  }

  async update(
    userId: string,
    webhookId: string,
    changes: { name?: string; avatarUrl?: string | null },
  ): Promise<WebhookSummary> {
    const existing = await this.owned(userId, webhookId);
    const row = await prisma.webhook.update({
      where: { id: existing.id },
      data: {
        ...(changes.name !== undefined ? { name: changes.name.trim() } : {}),
        // null is a real value - it clears the picture back to the initial -
        // so only an absent key means "leave it alone".
        ...(changes.avatarUrl !== undefined ? { avatarUrl: changes.avatarUrl } : {}),
      },
      select: WEBHOOK_SELECT,
    });
    return toSummary(row);
  }

  /**
   * A new token for an existing webhook, invalidating the old one at once.
   *
   * The way back from a URL that has leaked, and the way back from one that was
   * simply not written down when it was created - which is the cost of hashing
   * it, and is why this endpoint is not optional.
   */
  async rotate(userId: string, webhookId: string): Promise<WebhookWithToken> {
    const existing = await this.owned(userId, webhookId);
    const token = randomBytes(TOKEN_BYTES).toString('base64url');
    const row = await prisma.webhook.update({
      where: { id: existing.id },
      data: { tokenHash: hashToken(token) },
      select: WEBHOOK_SELECT,
    });
    return { ...toSummary(row), url: urlFor(row.id, token) };
  }

  /**
   * Deletes it. What it has already said stays: `Message.webhookId` is
   * `SetNull`, so the history keeps its rows and they fall back to a name.
   * Deleting a webhook is closing a door, not retracting what came through it.
   */
  async remove(userId: string, webhookId: string): Promise<void> {
    const existing = await this.owned(userId, webhookId);
    await prisma.webhook.delete({ where: { id: existing.id } });
  }

  /**
   * Posts a message as the webhook. **Unauthenticated** - the token in the URL
   * is the whole of the authority, which is what makes it reachable from a
   * `curl` in a deploy script.
   *
   * Looked up by the digest, so a wrong token is one indexed miss rather than a
   * scan. A wrong token and a deleted webhook answer identically: the URL is
   * the secret, and distinguishing "no such webhook" from "wrong token" would
   * let anybody with an id confirm one exists.
   */
  async execute(
    webhookId: string,
    token: string,
    body: ExecuteWebhookRequest,
  ): Promise<{ message: Message; ignored: string[] }> {
    const webhook = await prisma.webhook.findFirst({
      where: { id: webhookId, tokenHash: hashToken(token) },
    });
    if (!webhook) {
      throw new NotFoundException({
        code: 'WEBHOOK_NOT_FOUND',
        message: 'No webhook with that id and token',
      });
    }

    const content = renderBody(body);
    if (content.length === 0) {
      throw new BadRequestException({
        code: 'INVALID_WEBHOOK_BODY',
        message: 'A webhook message needs content or at least one embed',
      });
    }
    if (content.length > WEBHOOK_CONTENT_MAX_LENGTH) {
      throw new BadRequestException({
        code: 'INVALID_WEBHOOK_BODY',
        // Named, because "too long" from an integration nobody is watching is a
        // silent failure somebody debugs for an afternoon.
        message: `Rendered message is ${content.length} characters; the limit is ${WEBHOOK_CONTENT_MAX_LENGTH}`,
      });
    }

    const row = await prisma.message.create({
      data: {
        channelId: webhook.channelId,
        // The row has to belong to a real account - `authorId` is not nullable,
        // and making it nullable to model robots would touch every query in
        // this service. The person who opened the door is the honest answer,
        // and no client draws it: `kind` is WEBHOOK, so they all draw the
        // webhook's own name over the top.
        authorId: webhook.createdById,
        kind: 'WEBHOOK',
        // Plaintext. See the file header - this is the documented exception.
        content,
        webhookId: webhook.id,
      },
      include: MESSAGE_INCLUDE,
    });

    // The first thing anybody asks about a webhook that "isn't working". Not
    // awaited with the message: a failed bookkeeping write must not turn a
    // delivered message into a 500 the sender then retries.
    void prisma.webhook
      .update({ where: { id: webhook.id }, data: { lastUsedAt: new Date() } })
      .catch(() => undefined);

    const message = toMessage(row);
    await this.events.publish(EVENTS.MESSAGE_CREATED, { message });
    return { message, ignored: ignoredFields(body) };
  }

  /** `MANAGE_WEBHOOK` on the channel's server. A direct message has no webhooks. */
  private async requireManage(userId: string, channelId: string): Promise<void> {
    const access = await resolveChannelAccess(userId, channelId);
    if (!access) {
      throw new NotFoundException({ code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
    }
    // A direct message belongs to two people and has no roles to hold the
    // permission - and a URL that posts into somebody's DMs forever is not a
    // thing this app is going to offer.
    if (access.serverId === null) {
      throw new ForbiddenException({
        code: 'WEBHOOK_NOT_ALLOWED',
        message: 'Direct messages cannot have webhooks',
      });
    }
    if (!access.permissions.includes(PERMISSIONS.MANAGE_WEBHOOK)) {
      throw new ForbiddenException({
        code: 'FORBIDDEN',
        message: `Missing permission ${PERMISSIONS.MANAGE_WEBHOOK}`,
      });
    }
  }

  /**
   * The webhook, once the caller has been shown to manage its channel.
   *
   * Resolved through the channel rather than by who created it: a webhook
   * belongs to the channel it posts into, so an administrator has to be able to
   * revoke one opened by somebody who has since left.
   */
  private async owned(userId: string, webhookId: string) {
    const row = await prisma.webhook.findUnique({ where: { id: webhookId } });
    if (!row) {
      throw new NotFoundException({ code: 'WEBHOOK_NOT_FOUND', message: 'Webhook not found' });
    }
    await this.requireManage(userId, row.channelId);
    return row;
  }
}

/**
 * Where a webhook's URL points.
 *
 * `PUBLIC_API_URL`, which is the same variable the OAuth callback is built
 * from - read from the environment rather than from the request, because this
 * URL is pasted into somebody else's system and has to be the deployment's
 * public address. A `Host` header behind a Cloudflare Tunnel is whatever the
 * tunnel put there, and a webhook URL that only works from inside the network
 * is a webhook URL that does not work.
 */
function urlFor(id: string, token: string): string {
  const base = envOr('PUBLIC_API_URL', 'http://localhost:8080').replace(/\/+$/, '');
  return `${base}/api/v1/webhooks/${id}/${token}`;
}

function toSummary(row: {
  id: string;
  channelId: string;
  name: string;
  avatarUrl: string | null;
  lastUsedAt: Date | null;
  createdAt: Date;
  createdBy: {
    id: string;
    username: string;
    displayName: string;
    avatarUrl: string | null;
    coverUrl: string | null;
    about: string;
  };
}): WebhookSummary {
  return {
    id: row.id,
    channelId: row.channelId,
    name: row.name,
    avatarUrl: row.avatarUrl,
    lastUsedAt: row.lastUsedAt ? row.lastUsedAt.toISOString() : null,
    createdAt: row.createdAt.toISOString(),
    createdBy: {
      id: row.createdBy.id,
      username: row.createdBy.username,
      displayName: row.createdBy.displayName,
      avatarUrl: row.createdBy.avatarUrl,
      coverUrl: row.createdBy.coverUrl,
      about: row.createdBy.about,
    },
  };
}

/**
 * Flattens a Discord payload into the one plaintext string a message body is.
 *
 * Embeds are rendered to Markdown rather than modelled, and that is the whole
 * design decision here. Every client in this app already renders Markdown in a
 * message; a structured embed would need a renderer in three clients, a place
 * in the sealed manifest it cannot go, and a fallback for the two years of
 * builds that predate it. Markdown is the fallback, so it is also the format.
 *
 * What is lost is the coloured bar down the left of a Discord embed. What is
 * kept is every word an integration sent, on every client, including the ones
 * already installed.
 *
 * Exported for `webhook-body.check.ts`.
 */
export function renderBody(body: ExecuteWebhookRequest): string {
  const parts: string[] = [];
  const content = typeof body.content === 'string' ? body.content.trim() : '';
  if (content) parts.push(content);

  const embeds = Array.isArray(body.embeds) ? body.embeds.slice(0, WEBHOOK_EMBED_MAX) : [];
  for (const embed of embeds) {
    const rendered = renderEmbed(embed);
    if (rendered) parts.push(rendered);
  }

  return parts.join('\n\n').trim();
}

function renderEmbed(embed: WebhookEmbed): string {
  const lines: string[] = [];

  const title = text(embed.title);
  if (title) {
    // A title with a URL becomes a link, which is what a Discord embed's title
    // does and is the only part of one anybody actually clicks.
    const url = text(embed.url);
    lines.push(url ? `**[${title}](${url})**` : `**${title}**`);
  }

  const description = text(embed.description);
  if (description) lines.push(description);

  for (const field of Array.isArray(embed.fields) ? embed.fields : []) {
    const name = text(field?.name);
    const value = text(field?.value);
    if (!name && !value) continue;
    // `inline` is dropped: it asks for a column layout, and a plaintext body
    // has no columns. Rendering it as a run-on line instead would lose the
    // field names, which are the half worth keeping.
    lines.push(name ? `**${name}**\n${value}` : value);
  }

  const footer = text(embed.footer?.text);
  if (footer) lines.push(`_${footer}_`);

  return lines.join('\n').trim();
}

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * Which fields of the payload were accepted and then not used.
 *
 * Returned in the response rather than swallowed. An integration that sends
 * `avatar_url` and sees its own picture ignored has no way to tell a policy
 * from a bug, and would go looking for the bug.
 */
export function ignoredFields(body: ExecuteWebhookRequest): string[] {
  const ignored: string[] = [];
  // Fetching an arbitrary URL would make every client that draws this message
  // beacon back to whoever supplied it, and would make this service fetch it
  // too. The webhook's own stored picture is used instead.
  if (typeof body.avatar_url === 'string' && body.avatar_url.length > 0) {
    ignored.push('avatar_url');
  }
  // A per-message name would need a column on every message to carry it, and
  // the thing it buys - one URL posting under several identities - is bought
  // instead by making several webhooks, which is a button rather than a schema
  // change. Reported rather than swallowed, so an integration whose name is not
  // showing up looks here instead of at its own code.
  if (typeof body.username === 'string' && body.username.length > 0) {
    ignored.push('username');
  }
  const embeds = Array.isArray(body.embeds) ? body.embeds : [];
  if (embeds.length > WEBHOOK_EMBED_MAX) ignored.push(`embeds beyond ${WEBHOOK_EMBED_MAX}`);
  if (embeds.some((embed) => typeof embed?.color === 'number')) ignored.push('embed color');
  return ignored;
}

