import { Body, Controller, Delete, Get, Param, Post, UseGuards } from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type { PushKeyResponse, RegisteredDevice } from '@betweenus/shared-types';
import { vapidPublicKey } from '../../push/webpush';
import { DevicesService } from './devices.service';
import { RegisterDeviceDto } from './dto';

@Controller('notifications/devices')
@UseGuards(JwtAuthGuard)
export class DevicesController {
  constructor(private readonly devices: DevicesService) {}

  /**
   * The application server key a browser needs before it can subscribe.
   *
   * Null when this deployment has no VAPID keys, which the client reads as
   * "this deployment does not do web push" and stops - rather than calling
   * `subscribe` with nothing and failing in a way that looks like a bug.
   *
   * The public half only. It is meant to be handed out: a subscription is
   * bound to it, which is what stops anybody else pushing to that browser.
   */
  @Get('key')
  key(): PushKeyResponse {
    return { vapidPublicKey: vapidPublicKey() };
  }

  /** Register on sign-in, and again on every token rotation. Idempotent. */
  @Post()
  register(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: RegisterDeviceDto,
  ): Promise<RegisteredDevice> {
    return this.devices.register(user.id, dto);
  }

  /**
   * Sign-out. Called *before* the tokens are discarded, because it needs one -
   * a row left behind pushes this account's messages at whoever holds the phone
   * next.
   */
  @Delete(':deviceId')
  async unregister(
    @CurrentUser() user: AuthenticatedUser,
    @Param('deviceId') deviceId: string,
  ): Promise<{ ok: true }> {
    await this.devices.unregister(user.id, deviceId);
    return { ok: true };
  }
}

/**
 * The push device registry, in both stores.
 *
 * **Postgres is what the fan-out reads.** It is one query joined against the
 * accounts and preferences already there, it is transactional, and it goes when
 * the account does - `device_tokens` cascades off `users`, so deleting somebody
 * cannot leave their phone being pushed to.
 *
 * **Firestore holds the same rows** - `deviceTokens/{uid}_{deviceId}`, carrying
 * the uid and the token - beside the Firebase project that minted them. That is
 * what makes the registry legible from the Firebase console, and what a Cloud
 * Function or a second sender would read if either ever exists.
 *
 * Postgres is the authority. Every Firestore write is best effort and is logged
 * rather than thrown: a registry mirror that cannot be written is a mirror that
 * is behind, and refusing to register a phone over it would be trading the
 * working store for the copy. They are reconciled by the next registration,
 * which the client makes on every sign-in and every rotation.
 *
 * One row per (account, installation), keyed on the installation and not on the
 * token: a token rotates, and a registry keyed on it grows a row per rotation
 * and then pushes at every dead one.
 *
 * A token is never logged - section 23 of CLAUDE.md - which includes the errors.
 */
import { Injectable } from '@nestjs/common';
import { prisma } from '@betweenus/database';
import { Logger } from '@betweenus/logger';
import type { RegisterDeviceRequest, RegisteredDevice } from '@betweenus/shared-types';
import { DEVICE_COLLECTION, MAX_IN_CLAUSE, deviceDocumentId, firestore } from '../../push/firestore';

/** One way to reach one installation, and which transport carries it. */
export interface PushAddress {
  token: string;
  platform: RegisteredDevice['platform'];
}

@Injectable()
export class DevicesService {
  constructor(private readonly logger: Logger) {}

  /**
   * Register, or refresh after a rotation. The same call for both: the client
   * cannot tell the difference either, and does not have to.
   */
  async register(userId: string, dto: RegisterDeviceRequest): Promise<RegisteredDevice> {
    const row = await prisma.$transaction(async (tx) => {
      // This token belonged to another row - another account on this phone, or
      // this account's own previous installation. It can only be in one place.
      const displaced = await tx.deviceToken.findMany({
        where: { token: dto.token, NOT: { userId, deviceId: dto.deviceId } },
        select: { userId: true, deviceId: true },
      });
      if (displaced.length > 0) {
        await tx.deviceToken.deleteMany({
          where: { token: dto.token, NOT: { userId, deviceId: dto.deviceId } },
        });
      }

      const fields = {
        token: dto.token,
        platform: dto.platform,
        label: dto.label ?? null,
        appVersion: dto.appVersion ?? null,
        lastSeenAt: new Date(),
      };

      const saved = await tx.deviceToken.upsert({
        where: { userId_deviceId: { userId, deviceId: dto.deviceId } },
        create: { userId, deviceId: dto.deviceId, ...fields },
        update: fields,
      });
      return { saved, displaced };
    });

    // The mirror, after the store that matters has committed.
    await this.mirrorDelete(row.displaced);
    await this.mirrorWrite(userId, dto);

    return {
      deviceId: row.saved.deviceId,
      platform: row.saved.platform as RegisteredDevice['platform'],
      label: row.saved.label,
      lastSeenAt: row.saved.lastSeenAt.toISOString(),
    };
  }

  /**
   * Sign-out, an account switch, or a server switch. Scoped to the caller, so
   * one account cannot unregister another's phone by guessing a device id.
   */
  async unregister(userId: string, deviceId: string): Promise<void> {
    await prisma.deviceToken.deleteMany({ where: { userId, deviceId } });
    await this.mirrorDelete([{ userId, deviceId }]);
  }

  /**
   * What this account can be reached on. Used by the fan-out, and nothing else.
   *
   * The platform comes back with the address because there are two transports
   * now: a phone's row is an FCM token and a browser's is a serialised Web Push
   * subscription, and the only thing that tells them apart is this column. A
   * fan-out that guessed from the string's shape would be one odd token away
   * from posting a registration id at a push service.
   */
  async tokensFor(userIds: string[]): Promise<Map<string, PushAddress[]>> {
    if (userIds.length === 0) return new Map();
    const rows = await prisma.deviceToken.findMany({
      where: { userId: { in: userIds } },
      select: { userId: true, token: true, platform: true },
    });
    const byUser = new Map<string, PushAddress[]>();
    for (const row of rows) {
      const address: PushAddress = {
        token: row.token,
        platform: row.platform as RegisteredDevice['platform'],
      };
      const addresses = byUser.get(row.userId);
      if (addresses) addresses.push(address);
      else byUser.set(row.userId, [address]);
    }
    return byUser;
  }

  /**
   * Tokens the transport has told us are dead - an uninstall, a clear-data, a
   * token that expired. Kept, they are a push attempt per message forever.
   */
  async forget(tokens: string[]): Promise<number> {
    if (tokens.length === 0) return 0;
    const doomed = await prisma.deviceToken.findMany({
      where: { token: { in: tokens } },
      select: { userId: true, deviceId: true },
    });
    const { count } = await prisma.deviceToken.deleteMany({ where: { token: { in: tokens } } });
    await this.mirrorDelete(doomed);
    return count;
  }

  // --- the Firestore mirror ---

  private async mirrorWrite(userId: string, dto: RegisterDeviceRequest): Promise<void> {
    const store = firestore();
    if (!store) return;
    const now = new Date();
    try {
      await store
        .collection(DEVICE_COLLECTION)
        .doc(deviceDocumentId(userId, dto.deviceId))
        .set(
          {
            uid: userId,
            deviceId: dto.deviceId,
            token: dto.token,
            platform: dto.platform,
            label: dto.label ?? null,
            appVersion: dto.appVersion ?? null,
            updatedAt: now,
          },
          // Merge, so a field some later version adds is not wiped by an
          // older one re-registering. No `createdAt`: Postgres has it, and
          // writing it here on every rotation would only make it a lie.
          { merge: true },
        );
    } catch (error: unknown) {
      // Never the token, and never fatal: Postgres already holds the row.
      this.logger.warn('Firestore device mirror write failed', { reason: String(error) });
    }
  }

  private async mirrorDelete(rows: { userId: string; deviceId: string }[]): Promise<void> {
    const store = firestore();
    if (!store || rows.length === 0) return;
    try {
      const batch = store.batch();
      for (const row of rows) {
        batch.delete(store.collection(DEVICE_COLLECTION).doc(deviceDocumentId(row.userId, row.deviceId)));
      }
      await batch.commit();
    } catch (error: unknown) {
      this.logger.warn('Firestore device mirror delete failed', { reason: String(error) });
    }
  }

  /**
   * The mirror, read back.
   *
   * Nothing in the send path uses this - Postgres answers that. It exists so
   * the mirror can be checked without opening the console, and so a future
   * sender that only has Firebase has somewhere to look. Chunked because
   * Firestore's `in` takes thirty values at a time.
   */
  async mirroredTokensFor(userIds: string[]): Promise<Map<string, string[]>> {
    const store = firestore();
    const byUser = new Map<string, string[]>();
    if (!store || userIds.length === 0) return byUser;

    for (let index = 0; index < userIds.length; index += MAX_IN_CLAUSE) {
      const chunk = userIds.slice(index, index + MAX_IN_CLAUSE);
      const snapshot = await store
        .collection(DEVICE_COLLECTION)
        .where('uid', 'in', chunk)
        .get();
      snapshot.forEach((document) => {
        const data = document.data() as { uid?: string; token?: string };
        if (!data.uid || !data.token) return;
        const tokens = byUser.get(data.uid);
        if (tokens) tokens.push(data.token);
        else byUser.set(data.uid, [data.token]);
      });
    }
    return byUser;
  }
}

import { IsIn, IsOptional, IsString, MaxLength, MinLength } from 'class-validator';
import type { DevicePlatform } from '@betweenus/shared-types';

/** Long enough that nothing sensible is refused, short enough to bound a row. */
const MAX_TOKEN = 4096;

export class RegisterDeviceDto {
  @IsString()
  @MinLength(1)
  @MaxLength(MAX_TOKEN)
  token!: string;

  @IsIn(['android', 'ios', 'web'])
  platform!: DevicePlatform;

  @IsString()
  @MinLength(1)
  @MaxLength(128)
  deviceId!: string;

  @IsOptional()
  @IsString()
  @MaxLength(120)
  label?: string;

  @IsOptional()
  @IsString()
  @MaxLength(40)
  appVersion?: string;
}

import {
  ArrayMaxSize,
  IsArray,
  IsBoolean,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Max,
  Min,
  ValidateIf,
} from 'class-validator';

/** A day has 1440 minutes; anything else is not a time of day. */
const MINUTES_IN_DAY = 1439;

export class UpdatePreferencesDto {
  @IsOptional()
  @IsBoolean()
  enabled?: boolean;

  // Null is meaningful here - it clears the window - so it has to pass the
  // validator rather than be rejected as a non-integer.
  @IsOptional()
  @ValidateIf((_object, value) => value !== null)
  @IsInt()
  @Min(0)
  @Max(MINUTES_IN_DAY)
  quietStartMinute?: number | null;

  @IsOptional()
  @ValidateIf((_object, value) => value !== null)
  @IsInt()
  @Min(0)
  @Max(MINUTES_IN_DAY)
  quietEndMinute?: number | null;

  /** The whole list, not a delta. Capped so one account cannot store a novel. */
  @IsOptional()
  @IsArray()
  @ArrayMaxSize(500)
  @IsString({ each: true })
  mutedChannelIds?: string[];

  /** Same shape and same cap: the mentions-only list is the other half of it. */
  @IsOptional()
  @IsArray()
  @ArrayMaxSize(500)
  @IsString({ each: true })
  mentionOnlyChannelIds?: string[];

  /** People rather than channels, same shape and same cap. */
  @IsOptional()
  @IsArray()
  @ArrayMaxSize(500)
  @IsString({ each: true })
  mutedUserIds?: string[];
}

export class MarkReadDto {
  @IsUUID()
  channelId!: string;
}

import { Body, Controller, Get, Param, Patch, Post, UseGuards } from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  ChannelReadReceipt,
  ChannelUnread,
  NotificationPreferences,
} from '@betweenus/shared-types';
import { NotificationsService } from './notifications.service';
import { MarkReadDto, UpdatePreferencesDto } from './dto';

@Controller('notifications')
@UseGuards(JwtAuthGuard)
export class NotificationsController {
  constructor(private readonly notifications: NotificationsService) {}

  @Get('preferences')
  preferences(@CurrentUser() user: AuthenticatedUser): Promise<NotificationPreferences> {
    return this.notifications.preferences(user.id);
  }

  @Patch('preferences')
  updatePreferences(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: UpdatePreferencesDto,
  ): Promise<NotificationPreferences> {
    return this.notifications.updatePreferences(user.id, dto);
  }

  @Get('unread')
  unread(@CurrentUser() user: AuthenticatedUser): Promise<ChannelUnread[]> {
    return this.notifications.unread(user.id);
  }

  /** Who else has read this channel - the receipts a "seen by" row is drawn from. */
  @Get('channels/:channelId/reads')
  receipts(
    @CurrentUser() user: AuthenticatedUser,
    @Param('channelId') channelId: string,
  ): Promise<ChannelReadReceipt[]> {
    return this.notifications.receipts(user.id, channelId);
  }

  @Post('read')
  markRead(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: MarkReadDto,
  ): Promise<ChannelUnread> {
    return this.notifications.markRead(user.id, dto.channelId);
  }
}

/**
 * Notification preferences and read state.
 *
 * This service raises nothing itself: the desktop client already receives every
 * message over `/ws/chat` and the OS notification is the Electron main
 * process's job. What the client cannot own is the part that has to outlive it
 * - which channels are muted, when the quiet hours are, and how far each
 * channel has been read. Those follow the account, so a mute set on one machine
 * holds on the next one and an unread badge survives a restart.
 *
 * It reads the shared schema like every other service; splitting the schema per
 * service is tracked in development/TODO.md.
 */
import { Injectable, NotFoundException } from '@nestjs/common';
import { channelAudience, prisma, resolveChannelAccess } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import type {
  ChannelReadReceipt,
  ChannelUnread,
  NotificationPreferences,
  UpdateNotificationPreferencesRequest,
} from '@betweenus/shared-types';

/** An account with no row is an account with these. */
const DEFAULTS: NotificationPreferences = {
  enabled: true,
  quietStartMinute: null,
  quietEndMinute: null,
  mutedChannelIds: [],
  mentionOnlyChannelIds: [],
  mutedUserIds: [],
};

@Injectable()
export class NotificationsService {
  constructor(private readonly events: EventBus) {}

  async preferences(userId: string): Promise<NotificationPreferences> {
    const row = await prisma.notificationSetting.findUnique({ where: { userId } });
    if (!row) return DEFAULTS;
    return {
      enabled: row.enabled,
      quietStartMinute: row.quietStartMinute,
      quietEndMinute: row.quietEndMinute,
      mutedChannelIds: row.mutedChannelIds,
      mentionOnlyChannelIds: row.mentionOnlyChannelIds,
      mutedUserIds: row.mutedUserIds,
    };
  }

  async updatePreferences(
    userId: string,
    patch: UpdateNotificationPreferencesRequest,
  ): Promise<NotificationPreferences> {
    // Only the fields actually sent are touched, so a client that knows about
    // one setting cannot wipe another it has never heard of.
    const changes = {
      ...(patch.enabled !== undefined ? { enabled: patch.enabled } : {}),
      ...(patch.quietStartMinute !== undefined ? { quietStartMinute: patch.quietStartMinute } : {}),
      ...(patch.quietEndMinute !== undefined ? { quietEndMinute: patch.quietEndMinute } : {}),
      ...(patch.mutedChannelIds !== undefined
        ? { mutedChannelIds: [...new Set(patch.mutedChannelIds)] }
        : {}),
      ...(patch.mentionOnlyChannelIds !== undefined
        ? { mentionOnlyChannelIds: [...new Set(patch.mentionOnlyChannelIds)] }
        : {}),
      ...(patch.mutedUserIds !== undefined
        ? { mutedUserIds: [...new Set(patch.mutedUserIds)] }
        : {}),
    };

    const row = await prisma.notificationSetting.upsert({
      where: { userId },
      create: { userId, ...changes },
      update: changes,
    });

    return {
      enabled: row.enabled,
      quietStartMinute: row.quietStartMinute,
      quietEndMinute: row.quietEndMinute,
      mutedChannelIds: row.mutedChannelIds,
      mentionOnlyChannelIds: row.mentionOnlyChannelIds,
      mutedUserIds: row.mutedUserIds,
    };
  }

  /**
   * Unread counts for every channel this user can read.
   *
   * The cutoff is the read marker; a channel with no marker counts from the
   * moment the user could first see it (joining the server, or being added to
   * a private channel or a DM), so joining an old server does not arrive with
   * a thousand unread messages.
   */
  async unread(userId: string): Promise<ChannelUnread[]> {
    const [memberships, seats] = await Promise.all([
      prisma.serverMember.findMany({ where: { userId }, select: { serverId: true, joinedAt: true } }),
      prisma.channelMember.findMany({ where: { userId }, select: { channelId: true, addedAt: true } }),
    ]);

    const joinedServer = new Map(memberships.map((m) => [m.serverId, m.joinedAt]));
    const joinedChannel = new Map(seats.map((seat) => [seat.channelId, seat.addedAt]));

    // Public channels of servers this user belongs to, plus every channel they
    // are named on - which is what a private channel and a DM both are.
    const channels = await prisma.channel.findMany({
      where: {
        type: { not: 'VOICE' },
        OR: [
          { serverId: { in: [...joinedServer.keys()] }, isPrivate: false },
          { id: { in: [...joinedChannel.keys()] } },
        ],
      },
      select: { id: true, serverId: true, createdAt: true },
    });

    // An account that cleared its history must not be told it has unread
    // messages it can no longer open. The cut is a floor under every channel's
    // cutoff rather than a separate rule - see `chatsClearedAt`.
    const cleared = await prisma.user.findUnique({
      where: { id: userId },
      select: { chatsClearedAt: true },
    });

    const reads = await prisma.channelRead.findMany({
      where: { userId, channelId: { in: channels.map((channel) => channel.id) } },
      select: { channelId: true, lastReadAt: true, clearedAt: true },
    });
    const readAt = new Map(reads.map((read) => [read.channelId, read.lastReadAt]));
    // Cleared per conversation, as well as the account-wide cut above.
    const clearedAt = new Map(
      reads.filter((read) => read.clearedAt !== null).map((read) => [read.channelId, read.clearedAt!]),
    );

    // ponytail: one count query per channel, because each has its own cutoff.
    // Fine at a few dozen channels; a single grouped raw query if it is not.
    return Promise.all(
      channels.map(async (channel) => {
        const marker = readAt.get(channel.id);
        const from =
          marker ??
          joinedChannel.get(channel.id) ??
          (channel.serverId ? joinedServer.get(channel.serverId) : undefined) ??
          channel.createdAt;
        // Whichever cut-off is latest wins: the account-wide one, this
        // conversation's own, or where they had read to.
        const since = [cleared?.chatsClearedAt, clearedAt.get(channel.id)].reduce<Date>(
          (latest, cut) => (cut && cut > latest ? cut : latest),
          from,
        );

        const count = await prisma.message.count({
          where: {
            channelId: channel.id,
            createdAt: { gt: since },
            deletedAt: null,
            // Your own message is never unread.
            authorId: { not: userId },
            // Nor is the conversation noting that somebody arrived. `onMessage`
            // in push.service.ts already declines to wake a phone for one -
            // addressed to nobody, and with no body to put in the notification -
            // and a badge that says a channel has something new in it should
            // agree with that rather than disagree per surface. A server that
            // gains ten members is not ten things to read.
            kind: 'USER',
          },
        });

        return { channelId: channel.id, count, lastReadAt: marker?.toISOString() ?? null };
      }),
    );
  }

  /**
   * "I am looking at this channel now." The marker is always the current time -
   * there is no way to mark read as of an older message, which keeps the count
   * monotonic and saves a rule about moving the marker backwards.
   */
  async markRead(userId: string, channelId: string): Promise<ChannelUnread> {
    // 404 for both a missing channel and one this user cannot see, so read
    // markers cannot be used to probe for channel ids.
    const access = await resolveChannelAccess(userId, channelId);
    if (!access) {
      throw new NotFoundException({ code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
    }

    const at = new Date();
    await prisma.channelRead.upsert({
      where: { userId_channelId: { userId, channelId } },
      create: { userId, channelId, lastReadAt: at },
      update: { lastReadAt: at },
    });

    // Their other devices, so a notification this account has already dealt
    // with stops sitting in a pocket. Published rather than pushed from here:
    // the fan-out belongs to `PushService`, which owns the tokens.
    await this.events.publish(EVENTS.CHANNEL_READ, {
      userId,
      channelId,
      at: at.toISOString(),
    });

    return { channelId, count: 0, lastReadAt: at.toISOString() };
  }

  /**
   * Who else has read this channel, and up to when.
   *
   * The caller is left out: a receipt is about somebody else having seen your
   * message, and your own marker is already the thing that moves when you read.
   * Anyone who can read the channel but has never opened it simply has no row,
   * which reads as "has not seen it" without a null to carry around.
   */
  async receipts(userId: string, channelId: string): Promise<ChannelReadReceipt[]> {
    // Same 404 as everywhere else: a channel this account cannot see does not
    // exist, so receipts cannot be used to probe for channel ids either.
    const access = await resolveChannelAccess(userId, channelId);
    if (!access) {
      throw new NotFoundException({ code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
    }

    // The audience, not every row: somebody who has since been removed from a
    // private channel keeps their old marker, and it is not the caller's
    // business any more.
    const audience = (await channelAudience(channelId)).filter((id) => id !== userId);
    if (audience.length === 0) return [];

    const reads = await prisma.channelRead.findMany({
      where: { channelId, userId: { in: audience } },
      orderBy: { lastReadAt: 'desc' },
      select: {
        lastReadAt: true,
        user: {
          select: { id: true, username: true, displayName: true, avatarUrl: true },
        },
      },
    });

    return reads.map((read) => ({
      user: read.user,
      readAt: read.lastReadAt.toISOString(),
    }));
  }
}

/**
 * The Firebase credentials, out of the environment and never off disk.
 *
 * A service account JSON file in the repository is one `git add .` away from
 * being a private key in a public history, and the file is not what a container
 * has anyway - it has an environment. So the same three fields the file carries
 * are read from three variables, and `scripts/firebase-env.mjs` turns a
 * downloaded key into the lines to paste. Nothing here ever opens a path.
 *
 * `FIREBASE_SERVICE_ACCOUNT` is the same JSON, base64 or raw, in one variable -
 * which is what a secrets manager tends to hand out. It wins when both are set.
 *
 * With none of them set push is simply off: `messaging()` returns null, the
 * fan-out logs once and does nothing, and every other part of this service
 * carries on. A deployment that has not configured Firebase is not a broken
 * deployment.
 */
import { cert, getApps, initializeApp, type App } from 'firebase-admin/app';
import { getMessaging, type Messaging } from 'firebase-admin/messaging';
import { env } from '@betweenus/config';

export interface FirebaseCredentials {
  projectId: string;
  clientEmail: string;
  privateKey: string;
}

/**
 * A private key survives an environment variable as `\n` rather than as a
 * newline - that is what `.env` files, Compose and every secrets UI do to it -
 * and OpenSSL rejects the result with an error about the PEM header. Undoing it
 * here is the one line that stops that being a half-hour every time.
 */
function normalisePrivateKey(value: string): string {
  return value.replace(/\\n/g, '\n').trim();
}

function fromSingleVariable(raw: string): FirebaseCredentials | null {
  // Base64 or raw JSON: both arrive in the same variable depending on who
  // filled it in, and telling them apart is cheaper than making people care.
  const text = raw.trim().startsWith('{')
    ? raw
    : Buffer.from(raw, 'base64').toString('utf8');
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(text) as Record<string, unknown>;
  } catch {
    return null;
  }
  const projectId = typeof parsed.project_id === 'string' ? parsed.project_id : '';
  const clientEmail = typeof parsed.client_email === 'string' ? parsed.client_email : '';
  const privateKey = typeof parsed.private_key === 'string' ? parsed.private_key : '';
  if (!projectId || !clientEmail || !privateKey) return null;
  return { projectId, clientEmail, privateKey: normalisePrivateKey(privateKey) };
}

export function firebaseCredentials(): FirebaseCredentials | null {
  const single = env('FIREBASE_SERVICE_ACCOUNT');
  if (single) return fromSingleVariable(single);

  const projectId = env('FIREBASE_PROJECT_ID');
  const clientEmail = env('FIREBASE_CLIENT_EMAIL');
  const privateKey = env('FIREBASE_PRIVATE_KEY');
  if (!projectId || !clientEmail || !privateKey) return null;
  return { projectId, clientEmail, privateKey: normalisePrivateKey(privateKey) };
}

let app: App | null = null;
let resolved = false;

/**
 * The one Firebase app this service has, or null when it is not configured.
 * Both the sender and the device registry hang off it - see `firestore.ts`.
 */
export function firebaseApp(): App | null {
  if (!resolved) {
    resolved = true;
    const credentials = firebaseCredentials();
    if (credentials) {
      app =
        getApps().find((existing) => existing.name === 'betweenus') ??
        initializeApp({ credential: cert(credentials), projectId: credentials.projectId }, 'betweenus');
    }
  }
  return app;
}

/** Null when Firebase is not configured. Built once, on first use. */
export function messaging(): Messaging | null {
  const current = firebaseApp();
  return current ? getMessaging(current) : null;
}

/**
 * The push device registry lives in Firestore.
 *
 * It is the one piece of BetweenUs state that is not in Postgres, and
 * deliberately: a registration token is Firebase's own identifier, it is
 * meaningless without the project that minted it, and it is the only thing here
 * whose lifetime is decided by Google rather than by us. Keeping it beside the
 * project that issues it means a deployment with no Firebase has no registry to
 * keep consistent, rather than a Postgres table full of tokens nobody can send
 * to.
 *
 * One document per (uid, installation), id `<uid>_<deviceId>`:
 *
 *   deviceTokens/{uid}_{deviceId}
 *     uid         the BetweenUs user id
 *     deviceId    client-minted, stable per installation
 *     token       the FCM registration token
 *     platform    android | ios | web
 *     label       "Pixel 8", untrusted, display only
 *     appVersion  the client build
 *     createdAt   / updatedAt
 *
 * Keyed on the installation and not on the token, because a token rotates - and
 * a collection keyed on it grows a document per rotation and then pushes to
 * every dead one.
 *
 * The database is created on first write: Firestore has no schema and no
 * migration, so the collection exists as soon as something is registered. The
 * one thing an operator must do is enable Firestore in the Firebase console
 * once - see FCM/README.md.
 */
import { getFirestore, type Firestore } from 'firebase-admin/firestore';
import { firebaseApp } from './firebase';

export const DEVICE_COLLECTION = 'deviceTokens';

/** Firestore's own ceiling on an `in` query, which is what the fan-out uses. */
export const MAX_IN_CLAUSE = 30;

let store: Firestore | null = null;
let resolved = false;

/** Null when Firebase is not configured, exactly as `messaging()` is. */
export function firestore(): Firestore | null {
  if (!resolved) {
    resolved = true;
    const app = firebaseApp();
    if (app) {
      store = getFirestore(app);
      // A field this service never reads back is a field it should not fail on.
      store.settings({ ignoreUndefinedProperties: true });
    }
  }
  return store;
}

/** One document per installation per account, and the id says so. */
export function deviceDocumentId(uid: string, deviceId: string): string {
  return `${uid}_${deviceId}`;
}

/**
 * Self-check for the focus lookup, which fails in the direction that hurts.
 *
 * A wrong "nobody is reading" is one redundant buzz. A wrong "everybody is
 * reading" is a message nobody is ever told about - so every failure this can
 * have, from a timeout to a malformed body, has to come back as the empty set.
 *
 * Run with `pnpm --filter @betweenus/notification-service check`.
 */
import assert from 'node:assert/strict';
import { focusedAmong } from './focus';

type Fetch = typeof globalThis.fetch;
const real: Fetch = globalThis.fetch;

/** Stands in for presence-service for one call. */
function answering(handler: (url: URL) => unknown): void {
  globalThis.fetch = ((input: Parameters<Fetch>[0]) => {
    const url = input instanceof URL ? input : new URL(String(input));
    const result = handler(url);
    if (result instanceof Error) return Promise.reject(result);
    return Promise.resolve(result as Response);
  }) as Fetch;
}

function ok(body: unknown): Response {
  return { ok: true, json: () => Promise.resolve(body) } as Response;
}

async function nobodyIsAskedAboutAnEmptyAudience(): Promise<void> {
  answering(() => {
    throw new Error('presence-service must not be called for an empty audience');
  });
  assert.deepEqual([...(await focusedAmong('channel', []))], []);
}

async function theAudienceAndTheChannelBothReachTheService(): Promise<void> {
  let seen: URL | null = null;
  answering((url) => {
    seen = url;
    return ok({ focused: ['ben'] });
  });

  const focused = await focusedAmong('chan_general', ['ana', 'ben']);
  assert.deepEqual([...focused], ['ben']);
  assert.equal(seen!.pathname, '/internal/presence/focus');
  assert.equal(seen!.searchParams.get('channelId'), 'chan_general');
  // One request for the batch, not one per recipient.
  assert.equal(seen!.searchParams.get('userIds'), 'ana,ben');
}

async function everyFailureMeansSendTheNotification(): Promise<void> {
  answering(() => new Error('connection refused'));
  assert.deepEqual([...(await focusedAmong('chan', ['ana']))], [], 'a service that is down');

  answering(() => ({ ok: false }) as Response);
  assert.deepEqual([...(await focusedAmong('chan', ['ana']))], [], 'a service that errored');

  answering(() => ({ ok: true, json: () => Promise.reject(new Error('not json')) }) as Response);
  assert.deepEqual([...(await focusedAmong('chan', ['ana']))], [], 'a body that is not JSON');

  answering(() => ok({}));
  assert.deepEqual([...(await focusedAmong('chan', ['ana']))], [], 'a body with no focused list');
}

async function main(): Promise<void> {
  try {
    await nobodyIsAskedAboutAnEmptyAudience();
    await theAudienceAndTheChannelBothReachTheService();
    await everyFailureMeansSendTheNotification();
  } finally {
    globalThis.fetch = real;
  }
  console.log('focus check ok');
}

void main();

/**
 * Who is already reading the conversation, asked of presence-service.
 *
 * A push exists to reach somebody who is not looking. If the same account has
 * the channel open in a focused window on a laptop, waking their phone for it
 * is noise - the message is on a screen in front of them before the buzz
 * arrives. This is the half of that rule a server can answer, and the reason it
 * has to be a server that answers it: only the server can see the *other*
 * devices.
 *
 * Presence owns the fact and this only asks for it, over the same internal HTTP
 * path `server-service` already uses for online counts. Reading Redis directly
 * from here would make a key presence-service owns into a thing two services
 * have to agree about.
 *
 * Failure is not suppression. A presence-service that is slow, down or
 * unreachable answers "nobody", so the push goes: a missed notification is a
 * message somebody never learns about, and a redundant one is a buzz. The first
 * is much worse than the second.
 */
import { envOr } from '@betweenus/config';

/**
 * Short on purpose. This is on the path of every message fan-out, and a
 * presence-service that has stopped answering must not hold up everybody
 * else's notifications while it fails.
 */
const TIMEOUT_MS = 1_500;

const base = (): string => envOr('PRESENCE_SERVICE_URL', 'http://presence-service:3005');

export async function focusedAmong(channelId: string, userIds: string[]): Promise<Set<string>> {
  if (userIds.length === 0) return new Set();

  const url = new URL(`${base()}/internal/presence/focus`);
  url.searchParams.set('channelId', channelId);
  url.searchParams.set('userIds', userIds.join(','));

  try {
    const response = await fetch(url, { signal: AbortSignal.timeout(TIMEOUT_MS) });
    if (!response.ok) return new Set();
    const body = (await response.json()) as { focused?: string[] };
    return new Set(body.focused ?? []);
  } catch {
    // Deliberately silent about which failure it was. Every one of them means
    // the same thing here - assume nobody is reading, and send.
    return new Set();
  }
}

/**
 * Fan-out: something happened, and somebody's phone is asleep.
 *
 * Everything already running - the desktop app, an open tab, a phone with the
 * app in front of somebody - is fed by `/ws/chat` and needs nothing from here.
 * This is only for the clients that are not running: a phone with the app
 * swiped away, and a browser with the tab closed.
 *
 * **Two transports, one design.** Phones go through FCM, browsers through Web
 * Push and VAPID, and the only thing that tells a row apart is its platform
 * column. Everything above the transport is shared - the audience, the
 * preference filter, the cross-device suppression, the data-only envelope - so
 * a new kind of push is written once and reaches both. A deployment can
 * configure either, both, or neither, and none of those is broken.
 *
 * Two rules shape every line below.
 *
 * **The push is data-only.** It never carries a `notification` block, so
 * Android never draws one on its own: the app is woken and writes the
 * notification itself. That is not a style choice. The body is sealed with the
 * channel key, so this service could not write a notification worth reading if
 * it wanted to - and the client is also the only side that knows whether the
 * channel is already on screen, which is what makes suppression look like
 * WhatsApp's rather than like a duplicate.
 *
 * **The filter here is the half a server can answer.** Off entirely, a muted
 * channel and a muted person are on the envelope, so they are decided here and
 * the phone is never woken. Quiet hours are on the recipient's clock and a
 * mention is inside the ciphertext, so both are decided on the client - the
 * push still goes, and the client drops it. See FCM/README.md.
 *
 * One more is decided here for a different reason: whether the recipient is
 * *already reading the channel on another device*. A client can only ever see
 * its own screen, so only a server can answer that one - it asks
 * presence-service, and drops those recipients from the fan-out. See
 * `docs/docs/architecture/push-suppression.md`.
 *
 * Five things are worth waking a phone for, and only the first carries words:
 *
 * - `message.created` - somebody said something.
 * - `message.deleted` - somebody unsaid it, and the notification drawn for it
 *   is now a lie. One of the two pushes here that exist to take something *off*
 *   a screen.
 * - `channel.read` - this account read the conversation somewhere else, so the
 *   notification for it on every other device has been dealt with. The other
 *   one that takes something away.
 * - `friend.request` / `friend.accepted` - somebody asked, or said yes.
 * - `server.member.added` - somebody put this account in a server.
 * - `call.roster` - who is in a call in a channel this account can hear. The
 *   whole roster rather than the arrival, because it is one notification that
 *   is rewritten as people come and go, and because an empty roster is the
 *   only thing that can say the call is over.
 * - `call.ring` - somebody is ringing this account into a call. The aimed
 *   version of the one above, and the difference is what earns it a ringtone
 *   and a full-screen ringer: a person pressed a button with this account's
 *   name under it, where a roster is a fact about a room.
 * - `call.handled` - this account answered or declined that ring somewhere.
 *   The third of the pushes that exist to take something away, and the only
 *   thing that can stop the ringer on the devices where nobody touched it.
 * - `remote.session` - somebody is on one of this account's machines. The one
 *   notification here that exists because of what it means when it is
 *   unexpected, and the only one that ignores every preference: see below.
 */
import { Injectable, OnModuleInit } from '@nestjs/common';
import { channelAudience, prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import type { EventName, EventPayloads } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import type {
  CallHandledPushData,
  CallPushData,
  CallRingPushData,
  ChannelReadPushData,
  FriendPushData,
  Message,
  MessageDeletedPushData,
  MessagePushData,
  PushData,
  RemoteSessionPushData,
  ServerMemberPushData,
} from '@betweenus/shared-types';
import { DevicesService } from '../modules/devices/devices.service';
import { messaging } from './firebase';
import { focusedAmong } from './focus';
import { joined, namesOf, rosterChanged, worthAnnouncing } from './roster';
import { sendWebPush, webPushReady } from './webpush';

/** FCM's own ceiling for one `sendEach` call. */
const MAX_PER_BATCH = 500;

/**
 * How long a woken client has to be worth waking. Past this the message is
 * old news and the badge on next launch says it better than a late buzz.
 */
const TIME_TO_LIVE_SECONDS = 60 * 60 * 24;

/** What FCM says when a token is dead: an uninstall, a clear-data, an expiry. */
const DEAD_TOKEN_CODES = new Set([
  'messaging/registration-token-not-registered',
  'messaging/invalid-registration-token',
  'messaging/invalid-argument',
]);

@Injectable()
export class PushService implements OnModuleInit {
  constructor(
    private readonly events: EventBus,
    private readonly devices: DevicesService,
    private readonly logger: Logger,
  ) {}

  /**
   * The last roster pushed per channel, so an announcement nobody's phone can
   * tell apart from the previous one is not a second buzz.
   *
   * ponytail: in memory, so two instances of this service would each push once
   * for the same roster. One instance is what the compose file runs; move this
   * to Redis if there is ever a second.
   */
  private readonly rosters = new Map<string, string[]>();

  async onModuleInit(): Promise<void> {
    // Said once, at boot, rather than per message. A deployment with neither
    // transport configured is a running deployment without push, not an error -
    // and one with a single transport reaches one kind of client, which is a
    // deliberate deployment rather than a half-broken one.
    if (!messaging()) {
      this.logger.info('Push to phones disabled: no Firebase credentials in the environment');
    }
    if (!webPushReady()) {
      this.logger.info('Push to browsers disabled: no VAPID keys in the environment');
    }

    await this.on(EVENTS.MESSAGE_CREATED, (payload) => this.onMessage(payload.message));
    await this.on(EVENTS.MESSAGE_DELETED, (payload) => this.onMessageDeleted(payload));
    await this.on(EVENTS.CHANNEL_READ, (payload) => this.onChannelRead(payload));
    await this.on(EVENTS.FRIEND_CHANGED, (payload) => this.onFriendChanged(payload));
    await this.on(EVENTS.SERVER_MEMBER_ADDED, (payload) => this.onServerMemberAdded(payload));
    await this.on(EVENTS.CALL_ROSTER, (payload) => this.onCallRoster(payload.voice));
    await this.on(EVENTS.CALL_RING, (payload) => this.onCallRing(payload));
    await this.on(EVENTS.CALL_DECLINED, (payload) =>
      this.cancelRing(payload.userId, payload.channelId, 'declined'),
    );
    await this.on(EVENTS.REMOTE_SESSION, (payload) => this.onRemoteSession(payload));
  }

  /**
   * One subscription, one place that catches. A fan-out that throws must not
   * take the bus handler with it: the next event is somebody else's phone.
   */
  private async on<K extends EventName>(
    event: K,
    handle: (payload: EventPayloads[K]) => Promise<void>,
  ): Promise<void> {
    await this.events.subscribe(event, (envelope) => {
      void handle(envelope.payload).catch((error: unknown) => {
        this.logger.error('Push fan-out failed', { event, reason: String(error) });
      });
    });
  }

  private async onMessage(message: Message): Promise<void> {
    // The conversation noting that somebody arrived is worth a line in the
    // history and is not worth waking a phone: it is addressed to nobody, and a
    // server that gains ten members would otherwise be ten buzzes. There is
    // also no body to put in the notification - the row carries none.
    if (message.kind && message.kind !== 'USER') return;

    const audience = (await channelAudience(message.channelId)).filter(
      (userId) => userId !== message.author.id,
    );
    if (audience.length === 0) return;

    const recipients = await this.allowed(audience, message);
    if (recipients.length === 0) return;

    /**
     * Anybody with this conversation open, on any of their devices, in a
     * focused window.
     *
     * They are reading it as it arrives, so none of their devices is woken -
     * including the ones that are asleep, which is the whole point: the rule is
     * per account, not per device. A different channel is a different key and
     * still buzzes everywhere, which is what makes this bearable.
     *
     * Asked after the preference filter rather than before it, so a channel
     * everybody has muted costs no request at all.
     */
    const reading = await focusedAmong(
      message.channelId,
      recipients.map((one) => one.userId),
    );
    const woken = recipients.filter((one) => !reading.has(one.userId));
    if (woken.length === 0) return;

    await this.deliver(
      woken.map((one) => ({
        userId: one.userId,
        data: this.payload(message, one.mentionsOnly),
      })),
    );
  }

  /**
   * A message was deleted, so the notification drawn for it has to go.
   *
   * The whole audience, with none of the filtering the message itself went
   * through: the point is to take a notification away, and a recipient who was
   * never sent one simply has nothing to remove. Filtering here would be a way
   * to leave a notification standing for a message that no longer exists - the
   * author included, since they may have deleted it from another machine.
   */
  private async onMessageDeleted(payload: {
    messageId: string;
    channelId: string;
  }): Promise<void> {
    const audience = await channelAudience(payload.channelId);
    if (audience.length === 0) return;

    const data: MessageDeletedPushData = {
      type: 'message.deleted',
      messageId: payload.messageId,
      channelId: payload.channelId,
    };
    // Normal priority: taking a stale notification off a screen is worth doing
    // and is not worth pulling a sleeping phone out of Doze for. It lands the
    // moment the phone is next awake, which is the moment anybody would see it.
    await this.deliver(
      audience.map((userId) => ({ userId, data })),
      { urgent: false },
    );
  }

  /**
   * This account read a channel on one of its devices, so the notification for
   * it goes away on the others.
   *
   * The mirror image of `onMessageDeleted`: no audience to work out, no
   * preferences to consult - a read marker is this account talking to itself,
   * and nobody else's phone is involved. It goes to every device including the
   * one that did the reading, which has already cleared its own notification
   * and does nothing with this.
   *
   * Normal priority. Taking a stale notification off a screen is worth doing
   * and is not worth pulling a sleeping phone out of Doze for; it lands the
   * moment the phone is next awake, which is the moment anybody would see it.
   */
  private async onChannelRead(payload: {
    userId: string;
    channelId: string;
    at: string;
  }): Promise<void> {
    const data: ChannelReadPushData = {
      type: 'channel.read',
      channelId: payload.channelId,
      at: payload.at,
    };
    await this.deliver([{ userId: payload.userId, data }], { urgent: false });
  }

  /**
   * Somebody asked to be friends, or said yes.
   *
   * Only the far side is told - the actor already knows what they just did -
   * and only for the two kinds that are news. Declining, cancelling and
   * unfriending all arrive as `removed`, and none of them is a notification.
   */
  private async onFriendChanged(payload: {
    userIds: string[];
    actorId?: string;
    kind?: 'requested' | 'accepted' | 'removed';
  }): Promise<void> {
    const { actorId, kind } = payload;
    if (!actorId || (kind !== 'requested' && kind !== 'accepted')) return;

    const recipients = payload.userIds.filter((userId) => userId !== actorId);
    if (recipients.length === 0) return;

    const actor = await prisma.user.findUnique({
      where: { id: actorId },
      select: { username: true, displayName: true, avatarUrl: true },
    });
    if (!actor) return;

    const data: FriendPushData = {
      type: kind === 'requested' ? 'friend.request' : 'friend.accepted',
      actorId,
      actorName: actor.displayName || actor.username,
    };
    if (actor.avatarUrl) data.actorAvatarUrl = actor.avatarUrl;

    await this.deliver((await this.enabled(recipients)).map((userId) => ({ userId, data })));
  }

  /** Added to a server: one person, one notification, no words to seal. */
  private async onServerMemberAdded(payload: {
    serverId: string;
    userId: string;
  }): Promise<void> {
    const server = await prisma.server.findUnique({
      where: { id: payload.serverId },
      select: { name: true, iconUrl: true, ownerId: true },
    });
    if (!server) return;
    // Creating a server adds its owner to it, and nobody needs telling they
    // have joined the thing they just made.
    if (server.ownerId === payload.userId) return;

    const data: ServerMemberPushData = {
      type: 'server.member.added',
      serverId: payload.serverId,
      serverName: server.name,
    };
    if (server.iconUrl) data.serverIconUrl = server.iconUrl;

    await this.deliver(
      (await this.enabled([payload.userId])).map((userId) => ({ userId, data })),
    );
  }

  /**
   * Who is in a call, told to the people who can hear the channel and are not
   * in it.
   *
   * This is the `call.started` fan-out the Android notes have been waiting
   * for, in the shape that turned out to be right: the roster, not the
   * arrival. One notification per channel, rewritten as people come and go,
   * and an empty roster is what cancels it - which is the only way a phone
   * that was told about a call ever finds out it is over.
   *
   * Announced at the two ends of a call only. It used to go out on every join
   * and every departure, and the audience is everybody who can hear the channel
   * *minus whoever is in it* - so hanging up moved somebody out of the roster,
   * into the audience, and straight into a notification telling them who was
   * still on the call they had just left.
   */
  private async onCallRoster(voice: { channelId: string; userIds: string[] }): Promise<void> {
    const { channelId, userIds } = voice;
    const previous = this.rosters.get(channelId);
    if (!rosterChanged(previous, userIds)) return;
    const first = previous === undefined;
    this.rosters.set(channelId, [...userIds]);

    // Whoever just arrived answered this call somewhere, so the ringer comes
    // down on the devices where they did not. Before the announcement and
    // never gated on preferences: an account that has turned notifications off
    // still has a ringer up if it was ringing before it turned them off, and a
    // cancel is not a notification.
    const answered = joined(previous, userIds);
    for (const userId of answered) await this.cancelRing(userId, channelId, 'answered');

    // A channel nobody has been told about, whose call has already ended:
    // nothing to cancel, so nothing to send.
    if (first && userIds.length === 0) return;

    // Only the two ends of a call. See `worthAnnouncing` for what the middle
    // used to cost the person who left it.
    if (!worthAnnouncing(previous, userIds)) return;

    const channel = await prisma.channel.findUnique({
      where: { id: channelId },
      select: { name: true },
    });
    if (!channel) return;

    const audience = (await channelAudience(channelId)).filter(
      (userId) => !userIds.includes(userId),
    );
    if (audience.length === 0) return;

    const data: CallPushData = {
      type: 'call.roster',
      channelId,
      channelName: channel.name,
      participants: namesOf(await namesFor(userIds)),
      count: String(userIds.length),
    };

    // A call is somebody waiting for an answer, so it is worth the Doze
    // exemption. A call that has *ended* is not: the notification it cancels
    // had already stopped mattering.
    await this.deliver(
      (await this.allowedInChannel(audience, channelId)).map((userId) => ({ userId, data })),
      { urgent: userIds.length > 0 },
    );
  }

  /**
   * Somebody is ringing this account into a call.
   *
   * The filter is deliberately thinner than the roster's. A ring is directed -
   * one person pressed a button with this account's name under it - so a muted
   * *channel* does not silence it: muting #general is saying you do not want
   * to hear about that room, not that a colleague may never call you from it.
   *
   * Two things still do. Notifications off entirely is the account saying it
   * wants no pushes at all, and that includes this one. A muted *person* is
   * the setting that exists for exactly this: somebody you do not want to hear
   * from, however they reach you. Ringing is the loudest way to reach anybody,
   * so it is the last thing that should get past it.
   *
   * Always urgent. A ring that arrives when the phone next wakes up is not a
   * ring, it is a missed call notice - and the client draws that from the
   * roster push it already gets.
   */
  private async onCallRing(payload: EventPayloads['call.ring']): Promise<void> {
    if ((await this.enabled([payload.targetId])).length === 0) return;
    if (await this.mutes(payload.targetId, payload.callerId)) return;

    const data: CallRingPushData = {
      type: 'call.ring',
      channelId: payload.channelId,
      channelName: payload.channelName,
      callerId: payload.callerId,
      callerName: payload.callerName,
    };
    if (payload.callerAvatarUrl) data.callerAvatarUrl = payload.callerAvatarUrl;

    await this.deliver([{ userId: payload.targetId, data }], { urgent: true });
  }

  /**
   * Takes the ringer down on the devices where nobody dealt with it.
   *
   * A ring is aimed at an *account*, so it lands on the phone, the laptop and
   * the browser tab alike - and the account is the one thing neither half of
   * the fan-out could tell afterwards. Answering is invisible to it: the roster
   * announcement is addressed to everybody who can hear the channel *minus
   * whoever is in the call*, so answering moves you into the one group it
   * skips. Declining was invisible too, because nothing about it was sent
   * anywhere at all. Either way the rest of the account's devices rang on until
   * they timed out or the whole call ended.
   *
   * Urgent, unlike the other two cancels here. A late badge correction is a
   * cosmetic delay; a late one of these is a phone going on ringing in somebody's
   * pocket while they are already talking - or while they have already said no.
   *
   * Past every preference, for the same reason `message.deleted` is: an account
   * that has switched notifications off can still have a ringer standing from
   * before it did, and taking one down is not a notification.
   */
  private async cancelRing(
    userId: string,
    channelId: string,
    how: CallHandledPushData['how'],
  ): Promise<void> {
    const data: CallHandledPushData = { type: 'call.handled', channelId, how };
    await this.deliver([{ userId, data }], { urgent: true });
  }

  /** Whether `userId` has muted `otherId`, whatever channel they write in. */
  private async mutes(userId: string, otherId: string): Promise<boolean> {
    const row = await prisma.notificationSetting.findUnique({
      where: { userId },
      select: { mutedUserIds: true },
    });
    return row?.mutedUserIds.includes(otherId) ?? false;
  }

  /**
   * Somebody started or ended a remote session on a machine this account owns.
   *
   * **This one ignores the preferences, and that is deliberate.** Everywhere
   * else a mute is somebody choosing not to be told about a conversation.
   * Remote access is the one capability whose misuse is invisible to the person
   * it happens to - they are, by definition, not sitting at the machine - so a
   * notification that a mute could switch off would be a notification an
   * attacker could arrange to be switched off. The only thing that stops it is
   * turning notifications off entirely, which is the account saying it wants no
   * pushes at all rather than "not this one".
   *
   * Only the owner is told. The person driving already knows what they did, and
   * a session on somebody else's machine is not news anyone else is entitled to.
   */
  private async onRemoteSession(payload: EventPayloads['remote.session']): Promise<void> {
    if (payload.ownerId === payload.actorId) return;

    const data: RemoteSessionPushData = {
      type: 'remote.session',
      sessionId: payload.sessionId,
      machineId: payload.machineId,
      machineName: payload.machineName,
      actorId: payload.actorId,
      actorName: payload.actorName,
      state: payload.state,
    };

    // A session starting is worth waking a phone for - it is the whole point.
    // One ending is a notification being taken away, and lands whenever the
    // device is next awake.
    await this.deliver(
      (await this.enabled([payload.ownerId])).map((userId) => ({ userId, data })),
      { urgent: payload.state === 'started' },
    );
  }

  /**
   * Every push goes out through here: the tokens, FCM's batch ceiling, and the
   * dead ones that come back.
   *
   * One entry per recipient rather than one payload for all of them, because
   * `message.created` writes a different payload per recipient - the
   * mentions-only flag is the reader's, not the message's.
   */
  private async deliver(
    recipients: { userId: string; data: PushData }[],
    options: { urgent?: boolean } = {},
  ): Promise<void> {
    if (recipients.length === 0) return;

    const byUser = await this.devices.tokensFor(recipients.map((one) => one.userId));
    const addresses = recipients.flatMap((recipient) =>
      (byUser.get(recipient.userId) ?? []).map((address) => ({ ...address, data: recipient.data })),
    );
    if (addresses.length === 0) return;

    // Two transports, split on the column that says which. Both halves run,
    // because an account can have a phone and a browser and neither is a
    // fallback for the other.
    const [native, web] = await Promise.all([
      this.deliverFcm(
        addresses.filter((address) => address.platform !== 'web'),
        options,
      ),
      sendWebPush(
        addresses
          .filter((address) => address.platform === 'web')
          .map((address) => ({ stored: address.token, data: address.data })),
        options,
      ),
    ]);

    const forgotten = await this.devices.forget([...native.dead, ...web.dead]);
    this.logger.info('Push sent', {
      type: recipients[0]?.data.type,
      recipients: recipients.length,
      delivered: native.delivered + web.delivered,
      forgotten,
    });
  }

  /** Phones, through Firebase. Nothing here reaches a browser. */
  private async deliverFcm(
    addresses: { token: string; data: PushData }[],
    options: { urgent?: boolean },
  ): Promise<{ delivered: number; dead: string[] }> {
    const transport = messaging();
    if (!transport || addresses.length === 0) return { delivered: 0, dead: [] };

    const messages = addresses.map((address) => ({
      token: address.token,
      data: address.data as unknown as Record<string, string>,
      android: {
        // The point of the push is a phone that is asleep, and a normal
        // priority data message is exactly what Doze holds back.
        priority: (options.urgent === false ? 'normal' : 'high') as 'normal' | 'high',
        ttl: TIME_TO_LIVE_SECONDS * 1000,
      },
    }));

    const dead: string[] = [];
    let delivered = 0;
    for (let index = 0; index < messages.length; index += MAX_PER_BATCH) {
      const batch = messages.slice(index, index + MAX_PER_BATCH);
      const response = await transport.sendEach(batch);
      delivered += response.successCount;
      response.responses.forEach((one, position) => {
        if (one.success) return;
        const code = one.error?.code ?? '';
        const token = batch[position]?.token;
        if (token && DEAD_TOKEN_CODES.has(code)) dead.push(token);
        // The code, never the token: a log line is not a place for a
        // credential that can push to somebody's phone.
        else this.logger.warn('Push rejected', { code });
      });
    }
    return { delivered, dead };
  }

  /** Accounts that have not turned notifications off altogether. */
  private async enabled(audience: string[]): Promise<string[]> {
    const off = await prisma.notificationSetting.findMany({
      where: { userId: { in: audience }, enabled: false },
      select: { userId: true },
    });
    const silent = new Set(off.map((row) => row.userId));
    return audience.filter((userId) => !silent.has(userId));
  }

  /** The same, plus the channel mute - which a call in that channel obeys too. */
  private async allowedInChannel(audience: string[], channelId: string): Promise<string[]> {
    const settings = await prisma.notificationSetting.findMany({
      where: { userId: { in: audience } },
      select: { userId: true, enabled: true, mutedChannelIds: true },
    });
    const byUser = new Map(settings.map((row) => [row.userId, row]));
    return audience.filter((userId) => {
      const row = byUser.get(userId);
      if (!row) return true;
      return row.enabled && !row.mutedChannelIds.includes(channelId);
    });
  }

  /**
   * Who, of the people who may read this channel, still wants waking.
   *
   * One query for every preference row rather than one per recipient: an
   * account with no row is an account with the defaults, which is most of them.
   */
  private async allowed(
    audience: string[],
    message: Message,
  ): Promise<{ userId: string; mentionsOnly: boolean }[]> {
    const settings = await prisma.notificationSetting.findMany({
      where: { userId: { in: audience } },
      select: {
        userId: true,
        enabled: true,
        mutedChannelIds: true,
        mentionOnlyChannelIds: true,
        mutedUserIds: true,
      },
    });
    const byUser = new Map(settings.map((row) => [row.userId, row]));

    return audience.flatMap((userId) => {
      const row = byUser.get(userId);
      if (!row) return [{ userId, mentionsOnly: false }];
      if (!row.enabled) return [];
      if (row.mutedChannelIds.includes(message.channelId)) return [];
      if (row.mutedUserIds.includes(message.author.id)) return [];
      return [{ userId, mentionsOnly: row.mentionOnlyChannelIds.includes(message.channelId) }];
    });
  }

  /**
   * The envelope, and the sealed body. Nothing here is anything the recipient
   * could not already read off `/ws/chat`, and the words are still ciphertext.
   */
  private payload(message: Message, mentionsOnly: boolean): MessagePushData {
    const data: MessagePushData = {
      type: 'message.created',
      messageId: message.id,
      channelId: message.channelId,
      authorId: message.author.id,
      authorName: message.author.displayName || message.author.username,
      content: message.content,
      createdAt: message.createdAt,
    };
    if (message.author.avatarUrl) data.authorAvatarUrl = message.author.avatarUrl;
    if (mentionsOnly) data.mentionsOnly = '1';
    return data;
  }
}

/**
 * Display names for a set of ids, in the order they were asked for. Somebody
 * who has since been deleted is left out rather than named "Unknown".
 */
async function namesFor(userIds: string[]): Promise<string[]> {
  if (userIds.length === 0) return [];
  const rows = await prisma.user.findMany({
    where: { id: { in: userIds } },
    select: { id: true, username: true, displayName: true },
  });
  const byId = new Map(rows.map((row) => [row.id, row.displayName || row.username]));
  return userIds.flatMap((userId) => {
    const name = byId.get(userId);
    return name ? [name] : [];
  });
}

/**
 * Self-check for the call fan-out's decisions.
 *
 * Both fail quietly. A roster that is wrongly "unchanged" is a call nobody is
 * told about; one that is wrongly "changed" is a buzz per socket, and one
 * account with two windows open produces two of those for the same person
 * arriving once.
 *
 * Run with `pnpm --filter @betweenus/notification-service check`.
 */
import assert from 'node:assert/strict';
import { joined, namesOf, rosterChanged, worthAnnouncing } from './roster';

function aChannelNeverSeenBeforeIsNewsOnlyIfSomebodyIsInIt(): void {
  assert.equal(rosterChanged(undefined, ['ana']), true);
  // Nothing has been said about this channel and its call is already over.
  assert.equal(rosterChanged(undefined, []), false);
}

function theSameRosterTwiceIsNotNews(): void {
  assert.equal(rosterChanged(['ana', 'ben'], ['ana', 'ben']), false);
  // Order is the gateway's, not a fact about the room.
  assert.equal(rosterChanged(['ana', 'ben'], ['ben', 'ana']), false);
}

function arrivingAndLeavingAreBothNews(): void {
  assert.equal(rosterChanged(['ana'], ['ana', 'ben']), true);
  assert.equal(rosterChanged(['ana', 'ben'], ['ana']), true);
  assert.equal(rosterChanged(['ana'], []), true);
  // Same size, different people: a swap in one announcement.
  assert.equal(rosterChanged(['ana'], ['ben']), true);
}

function aRosterReadsLikeASentenceUntilItIsAList(): void {
  assert.equal(namesOf([]), '');
  assert.equal(namesOf(['Ana']), 'Ana');
  assert.equal(namesOf(['Ana', 'Ben']), 'Ana and Ben');
  assert.equal(namesOf(['Ana', 'Ben', 'Cara']), 'Ana, Ben and Cara');
  assert.equal(namesOf(['Ana', 'Ben', 'Cara', 'Dev']), 'Ana, Ben and 2 others');
}

function answeringSomewhereIsWhatTakesTheRingerDownEverywhereElse(): void {
  // Ana rings Ben; Ben answers on his phone. His laptop is still ringing and
  // nothing else will ever tell it otherwise - he is in the roster now, so the
  // announcement below deliberately skips him.
  assert.deepEqual(joined(['ana'], ['ana', 'ben']), ['ben']);
  // The first person in is answering their own call, which is still the event
  // that silences the ring their other devices are showing.
  assert.deepEqual(joined(undefined, ['ana']), ['ana']);
  assert.deepEqual(joined([], ['ana']), ['ana']);
  // Leaving is not answering, and neither is standing still.
  assert.deepEqual(joined(['ana', 'ben'], ['ana']), []);
  assert.deepEqual(joined(['ana'], ['ana']), []);
  assert.deepEqual(joined(['ana'], []), []);
}

function theRoomIsToldWhenACallStartsAndWhenItEnds(): void {
  assert.equal(worthAnnouncing(undefined, ['ana']), true, 'a call starting is news');
  assert.equal(worthAnnouncing([], ['ana']), true, 'and so is one starting again');
  assert.equal(worthAnnouncing(['ana'], []), true, 'the end cancels the notification');

  // The bug this exists for: Ben leaves a call Ana is still on, stops being a
  // participant, becomes audience, and is sent "Ana is in the call" about the
  // call he has just put down.
  assert.equal(
    worthAnnouncing(['ana', 'ben'], ['ana']),
    false,
    'leaving a call must never notify the person who left about the one they left',
  );
  assert.equal(
    worthAnnouncing(['ana'], ['ana', 'ben']),
    false,
    'somebody joining a call already under way is not a second announcement',
  );
}

aChannelNeverSeenBeforeIsNewsOnlyIfSomebodyIsInIt();
answeringSomewhereIsWhatTakesTheRingerDownEverywhereElse();
theRoomIsToldWhenACallStartsAndWhenItEnds();
theSameRosterTwiceIsNotNews();
arrivingAndLeavingAreBothNews();
aRosterReadsLikeASentenceUntilItIsAList();

console.log('roster check ok');

/**
 * The two decisions the call fan-out makes that are worth testing, kept out of
 * the service because the service needs Firebase and a database to construct.
 */

/**
 * Whether this roster is news.
 *
 * `call.roster` is published on every join and every departure, and one account
 * with two windows open is two sockets and one person - so the same roster can
 * be announced twice in a row. Order is not meaningful either; the set is.
 * Pushing on a roster nobody's phone can tell apart from the last one is a
 * buzz for nothing.
 */
export function rosterChanged(previous: string[] | undefined, now: string[]): boolean {
  if (previous === undefined) return now.length > 0;
  if (previous.length !== now.length) return true;
  const held = new Set(previous);
  return now.some((userId) => !held.has(userId));
}

/**
 * A roster as a person would say it.
 *
 * Three names is where a notification stops being a sentence and starts being
 * a list, so the fourth onwards are counted rather than named.
 */
export function namesOf(names: string[]): string {
  const [first, second, third] = names;
  switch (names.length) {
    case 0:
      return '';
    case 1:
      return first as string;
    case 2:
      return `${first} and ${second}`;
    case 3:
      return `${first}, ${second} and ${third}`;
    default:
      return `${first}, ${second} and ${names.length - 2} others`;
  }
}

/**
 * Who has just arrived in a call.
 *
 * They have answered it *somewhere*, which is the only thing that can take a
 * ringer down on the devices where they did not. Nothing else knows: the ring
 * push is aimed at an account and lands on every device it owns, and the
 * account that answers is filtered straight out of the roster announcement
 * below - so before this, the other devices were told nothing at all and rang
 * on until they timed out or the whole call ended.
 */
export function joined(previous: string[] | undefined, now: string[]): string[] {
  const held = new Set(previous ?? []);
  return now.filter((userId) => !held.has(userId));
}

/**
 * Whether this roster change is worth announcing to the room.
 *
 * Only the two ends of a call: it starting, and it ending. `call.roster` used
 * to go out on *every* join and departure, and the audience is "everyone who
 * can hear the channel, minus whoever is in the call" - so the moment somebody
 * hung up they stopped being a participant, became audience, and were sent a
 * notification saying who was still on the call they had just left. Leaving a
 * call and being told about it is the clearest possible way to say the rule
 * was wrong.
 *
 * The middle of a call is not news either way. Somebody who wants to know who
 * is in it can look; somebody who does not is being buzzed once per arrival.
 * The end still has to be said, because an empty roster is the only thing that
 * cancels the notification the start put up.
 */
export function worthAnnouncing(previous: string[] | undefined, now: string[]): boolean {
  const started = (previous ?? []).length === 0 && now.length > 0;
  const ended = now.length === 0;
  return started || ended;
}

/**
 * The other transport: a browser with the tab closed.
 *
 * FCM reaches phones. Web Push reaches browsers, and it is a different protocol
 * with a different address, a different authentication scheme and a different
 * way of saying a subscription is dead. What it is not is a different *design*:
 * the payload is the same data-only envelope, the client still writes the
 * notification because the body is still sealed with the channel key, and the
 * whole filtering half of `push.service.ts` is shared.
 *
 * **No Firebase in this path.** A deployment with VAPID keys and no Firebase
 * project pushes to browsers and not to phones; one with Firebase and no VAPID
 * keys does the opposite. Neither is broken, and neither needs the other.
 *
 * VAPID is what identifies this deployment to a push service. The keys are an
 * ordinary P-256 pair: the public half is handed to browsers so they can bind a
 * subscription to it, and the private half signs a short-lived JWT per send.
 * Generate a pair with `npx web-push generate-vapid-keys`.
 */
import webpush, { WebPushError } from 'web-push';
import { env, envOr } from '@betweenus/config';
import type { PushData, WebPushSubscription } from '@betweenus/shared-types';

/**
 * How long a push service should hold the message for a browser that is not
 * there. The same day the FCM path uses, for the same reason: past that the
 * message is old news and the badge on next launch says it better.
 */
const TIME_TO_LIVE_SECONDS = 60 * 60 * 24;

let configured: boolean | null = null;

/**
 * True when this deployment can push to a browser at all.
 *
 * Resolved once. A missing key is a deployment without web push rather than an
 * error, and saying so per message would be noise on every message.
 */
export function webPushReady(): boolean {
  if (configured !== null) return configured;

  const publicKey = env('VAPID_PUBLIC_KEY');
  const privateKey = env('VAPID_PRIVATE_KEY');
  if (!publicKey || !privateKey) {
    configured = false;
    return false;
  }

  // The subject tells a push service who to complain to about this sender. A
  // mailto is what the spec suggests and what the services actually accept.
  webpush.setVapidDetails(
    envOr('VAPID_SUBJECT', 'mailto:admin@betweenus.local'),
    publicKey,
    privateKey,
  );
  configured = true;
  return true;
}

/** The half a browser is allowed to see, or null when there is none. */
export function vapidPublicKey(): string | null {
  return webPushReady() ? (env('VAPID_PUBLIC_KEY') ?? null) : null;
}

/**
 * Reads a stored address back into a subscription.
 *
 * Anything that is not one - an FCM token that reached this path by mistake,
 * a row written by an older client, a truncated string - is null rather than a
 * throw. One malformed row must not take a fan-out down with it.
 */
export function parseSubscription(stored: string): WebPushSubscription | null {
  if (!stored.startsWith('{')) return null;
  try {
    const parsed = JSON.parse(stored) as Partial<WebPushSubscription>;
    if (typeof parsed.endpoint !== 'string' || !parsed.endpoint) return null;
    if (typeof parsed.keys?.p256dh !== 'string' || typeof parsed.keys?.auth !== 'string') {
      return null;
    }
    return { endpoint: parsed.endpoint, keys: { p256dh: parsed.keys.p256dh, auth: parsed.keys.auth } };
  } catch {
    return null;
  }
}

/** What a send did, so the caller can drop the addresses that are gone. */
export interface WebPushOutcome {
  delivered: number;
  /** Stored addresses the push service says will never work again. */
  dead: string[];
}

/**
 * Sends one payload to a list of browsers.
 *
 * Sequential rather than batched because there is no batch: Web Push is one
 * HTTP request per subscription, to whichever service that browser uses. They
 * are fired together and settled together, so one slow push service does not
 * hold up the rest.
 *
 * **404 and 410 are the only fatal answers.** They mean the subscription is
 * gone - the tab's site data was cleared, permission was revoked, the browser
 * expired it - and keeping it is a failed request per message forever. Anything
 * else (a 429, a 500, a timeout) is the push service having a moment, and
 * dropping a working subscription over one is how somebody silently stops
 * getting notifications.
 */
export async function sendWebPush(
  addresses: { stored: string; data: PushData }[],
  options: { urgent?: boolean } = {},
): Promise<WebPushOutcome> {
  if (!webPushReady() || addresses.length === 0) return { delivered: 0, dead: [] };

  const results = await Promise.allSettled(
    addresses.map(async (address) => {
      const subscription = parseSubscription(address.stored);
      if (!subscription) throw new Error('not a subscription');
      await webpush.sendNotification(subscription, JSON.stringify(address.data), {
        TTL: TIME_TO_LIVE_SECONDS,
        // `high` wakes a service worker promptly; `normal` lets the browser
        // batch it with whatever else it was going to do. The distinction is
        // the same one the Android path makes with Doze.
        urgency: options.urgent === false ? 'normal' : 'high',
      });
    }),
  );

  const dead: string[] = [];
  let delivered = 0;
  results.forEach((result, index) => {
    if (result.status === 'fulfilled') {
      delivered += 1;
      return;
    }
    const stored = addresses[index]?.stored;
    if (stored && isGone(result.reason)) dead.push(stored);
  });

  return { delivered, dead };
}

function isGone(reason: unknown): boolean {
  if (reason instanceof WebPushError) return reason.statusCode === 404 || reason.statusCode === 410;
  // A row that will not parse is never going to parse. It is as dead as a
  // subscription the service has forgotten, and is dropped for the same reason.
  return reason instanceof Error && reason.message === 'not a subscription';
}

