// Presence smoke: three sockets, one channel. Covers the handshake,
// presence.sync, online/offline fanout, typing echo rules, the voice roster and
// the scoping - who is entitled to hear any of it.
//
// Carol is the point of the third socket. She shares no server and no
// friendship with the other two, so every event they generate must miss her:
// presence used to go to every connected socket, which made the online list the
// whole deployment's user directory and a typing event a channel id handed to
// strangers.
//
// Needs Postgres, Redis, auth-service, server-service, call-service and
// presence-service - call-service because the voice roster is published by it.
import WebSocket from 'ws';

const AUTH = 'http://127.0.0.1:3001';
const SERVER = 'http://127.0.0.1:3003';
const PRESENCE = 'ws://127.0.0.1:3005/ws/presence';
const CALL = 'ws://127.0.0.1:3007/ws/call';

const json = async (url, options = {}) => {
  const response = await fetch(url, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers ?? {}) },
  });
  const body = await response.json().catch(() => null);
  if (!response.ok) throw new Error(`${url} -> ${response.status} ${JSON.stringify(body)}`);
  return body;
};

const ok = (label, condition, detail = '') => {
  if (!condition) {
    console.error(`FAIL ${label} ${detail}`);
    process.exit(1);
  }
  console.log(`${label} ok`, detail);
};

/** A bare /ws/call socket - this file needs it to make a roster, not to call. */
const callSocket = (token) =>
  new Promise((resolve, reject) => {
    const socket = new WebSocket(CALL, { headers: { Authorization: `Bearer ${token}` } });
    socket.on('error', reject);
    socket.on('open', () => resolve(socket));
  });

const register = async (name) => {
  const suffix = `${Date.now().toString(36)}${name}`;
  return json(`${AUTH}/api/v1/auth/register`, {
    method: 'POST',
    body: JSON.stringify({
      email: `presence-${suffix}@betweenus.local`,
      username: `presence${suffix}`,
      password: 'hunter2000',
    }),
  });
};

/** Changes one account's last-seen privacy setting. */
const setLastSeenVisibility = (session, lastSeenVisibility) =>
  json(`${AUTH}/api/v1/auth/account`, {
    method: 'PATCH',
    headers: { Authorization: `Bearer ${session.accessToken}` },
    body: JSON.stringify({ lastSeenVisibility }),
  });

/**
 * A socket that keeps every server event, so a test can wait for one that may
 * already have arrived. Polling a buffer beats racing a listener.
 */
const connect = (token) =>
  new Promise((resolve, reject) => {
    const socket = new WebSocket(PRESENCE, { headers: { Authorization: `Bearer ${token}` } });
    const events = [];
    socket.on('message', (raw) => events.push(JSON.parse(raw.toString())));
    socket.on('error', reject);
    socket.on('open', () =>
      resolve({
        socket,
        events,
        send: (event) => socket.send(JSON.stringify(event)),
        /** Resolves with the first event matching `match`, or null after `ms`. */
        waitFor: async (match, ms = 4000, startFrom = 0) => {
          const deadline = Date.now() + ms;
          for (;;) {
            const hit = events.slice(startFrom).find(match);
            if (hit) return hit;
            if (Date.now() > deadline) return null;
            await new Promise((r) => setTimeout(r, 50));
          }
        },
      }),
    );
  });

const alice = await register('a');
const bob = await register('b');
const carol = await register('c');
console.log('accounts ok', alice.user.username, bob.user.username, carol.user.username);

const aliceAuth = { Authorization: `Bearer ${alice.accessToken}` };
const server = await json(`${SERVER}/api/v1/servers`, {
  method: 'POST',
  headers: aliceAuth,
  body: JSON.stringify({ name: `Presence ${Date.now().toString(36)}` }),
});

const voiceChannel = await json(`${SERVER}/api/v1/channels`, {
  method: 'POST',
  headers: aliceAuth,
  body: JSON.stringify({ serverId: server.id, name: 'lounge', type: 'VOICE' }),
});
console.log('voice channel ok', voiceChannel.name, voiceChannel.type);

// Bob shares the server, so he is entitled to Alice's presence. Carol is not
// added to anything, which is the whole of her job here.
//
// He joins on an invite rather than being added by name: adding by name needs
// a friendship, and a friendship would entitle Bob to Alice's presence on its
// own - which is exactly the entitlement this file is trying to isolate from
// shared membership. The invite keeps the two apart.
const invite = await json(`${SERVER}/api/v1/servers/${server.id}/invites`, {
  method: 'POST',
  headers: aliceAuth,
  body: JSON.stringify({}),
});
await json(`${SERVER}/api/v1/servers/join`, {
  method: 'POST',
  headers: { Authorization: `Bearer ${bob.accessToken}` },
  body: JSON.stringify({ code: invite.code }),
});
console.log('membership ok', bob.user.username);

const a = await connect(alice.accessToken);
const ready = await a.waitFor((event) => event.type === 'ready');
ok('handshake', ready?.userId === alice.user.id);

const sync = await a.waitFor((event) => event.type === 'presence.sync');
ok('presence.sync', Array.isArray(sync?.users) && Array.isArray(sync?.voice));
ok(
  'self online in sync',
  sync.users.some((user) => user.userId === alice.user.id && user.status === 'online'),
);

// An unauthenticated socket is closed, not downgraded to an anonymous session.
const anonClose = await new Promise((resolve) => {
  const anon = new WebSocket(PRESENCE);
  anon.on('close', (code) => resolve(code));
  anon.on('error', () => resolve(-1));
});
ok('anonymous rejected', anonClose === 4401, String(anonClose));

// Bob connecting must reach Alice's socket.
const b = await connect(bob.accessToken);
const bobOnline = await a.waitFor(
  (event) => event.type === 'presence.changed' && event.user.userId === bob.user.id,
);
ok('online fanout', bobOnline?.user.status === 'online');

// Carol shares nothing with either of them, so Bob coming online is not news
// she is entitled to. Her socket opened before his did, so if it were going to
// arrive it would have by now.
const c = await connect(carol.accessToken);
await c.waitFor((event) => event.type === 'presence.sync');
ok(
  'a stranger is not in the sync',
  !c.events
    .filter((event) => event.type === 'presence.sync')
    .some((event) => event.users.some((user) => user.userId === alice.user.id)),
);

// Typing is broadcast to others and never echoed to its author.
a.send({ type: 'typing.start', channelId: voiceChannel.id });
const typing = await b.waitFor((event) => event.type === 'typing');
ok('typing fanout', typing?.userId === alice.user.id && typing.channelId === voiceChannel.id);
ok('typing not echoed to author', !a.events.some((event) => event.type === 'typing'));
ok('typing not sent to a stranger', !c.events.some((event) => event.type === 'typing'));

// Carol is not a member of Alice's server, so the channel is not hers to touch.
c.send({ type: 'voice.join', channelId: voiceChannel.id });
const forbidden = await c.waitFor((event) => event.type === 'error');
ok('non-member voice join refused', forbidden?.code === 'CHANNEL_FORBIDDEN');

// A member asking the same thing is told nothing, which is the answer: the
// only job left for `voice.join` on this socket is to refuse the people who
// may not.
a.send({ type: 'voice.join', channelId: voiceChannel.id });
ok(
  'member voice join is not refused',
  (await a.waitFor((event) => event.type === 'error', 500)) === null,
);

// The roster itself comes from call-service, which owns the signalling sockets
// and so is the only thing that knows who is really in a call - this socket
// used to write it from whatever a client claimed. So Alice joins the call for
// real, over /ws/call, and the fanout is watched here.
const aliceCall = await callSocket(alice.accessToken);
aliceCall.send(JSON.stringify({ type: 'join', channelId: voiceChannel.id }));

const joined = await b.waitFor(
  (event) => event.type === 'voice.changed' && event.voice.channelId === voiceChannel.id,
);
ok('voice roster join', joined?.voice.userIds.includes(alice.user.id));

aliceCall.send(JSON.stringify({ type: 'leave' }));
const left = await b.waitFor(
  (event) =>
    event.type === 'voice.changed' &&
    event.voice.channelId === voiceChannel.id &&
    !event.voice.userIds.includes(alice.user.id),
);
ok('voice roster leave', left !== null);
aliceCall.close();
ok(
  'voice roster not sent to a stranger',
  !c.events.some((event) => event.type === 'voice.changed'),
);

a.send({ type: 'ping' });
ok('heartbeat', (await a.waitFor((event) => event.type === 'pong')) !== null);

// Status. Bob is the one who changes, so the closing assertion about Alice
// going offline still means what it says - the buffer is scanned from the
// start, and two users' offline events would otherwise be indistinguishable.
b.send({ type: 'status.set', status: 'dnd' });
ok(
  'status echoed to its owner',
  (await b.waitFor((event) => event.type === 'status.self' && event.status === 'dnd')) !== null,
);
ok(
  'status fanout',
  (await a.waitFor(
    (event) =>
      event.type === 'presence.changed' &&
      event.user.userId === bob.user.id &&
      event.user.status === 'dnd',
  )) !== null,
);

// Invisible is the one status nobody else may see: it must arrive as offline.
b.send({ type: 'status.set', status: 'invisible' });
ok(
  'invisible echoed to its owner',
  (await b.waitFor(
    (event) => event.type === 'status.self' && event.status === 'invisible',
  )) !== null,
);
ok(
  'invisible reaches others as offline',
  (await a.waitFor(
    (event) =>
      event.type === 'presence.changed' &&
      event.user.userId === bob.user.id &&
      event.user.status === 'offline',
  )) !== null,
);
ok(
  'invisible never leaks on the wire',
  !a.events.some(
    (event) => event.type === 'presence.changed' && event.user.status === 'invisible',
  ),
);

// --- last seen ---------------------------------------------------------------
//
// Bob is invisible by this point, which is exactly the case worth asserting: a
// status that hid him but went on publishing when he was last here would not be
// hiding him. Alice may ask - they share a server - and must be told `offline`
// without a timestamp that is ticking along behind the disguise.
const beforeBobQuery = a.events.length;
a.send({ type: 'presence.query', userIds: [bob.user.id] });
const bobSeen = await a.waitFor(
  (event) => event.type === 'presence.changed' && event.user.userId === bob.user.id,
  4000,
  beforeBobQuery,
);
ok('a query is answered', bobSeen !== null);
ok('an invisible user answers offline', bobSeen?.user.status === 'offline');

// Carol shares nothing with Alice, so asking about her must be answered with
// silence rather than with a status - a query anybody could aim at any id would
// be the "who is online" oracle the audience scoping exists to remove.
const before = a.events.length;
a.send({ type: 'presence.query', userIds: [carol.user.id] });
await new Promise((resolve) => setTimeout(resolve, 500));
ok(
  'a query about a stranger is answered with nothing',
  !a.events
    .slice(before)
    .some((event) => event.type === 'presence.changed' && event.user.userId === carol.user.id),
);

// Closing a socket takes that user offline for everyone still connected.
a.socket.close();
const offline = await b.waitFor(
  (event) =>
    event.type === 'presence.changed' &&
    event.user.userId === alice.user.id &&
    event.user.status === 'offline',
);
ok('offline fanout', offline !== null);
// And it carries no timestamp, deliberately. Who may read a last-seen time
// depends on the reader, and a broadcast has one payload for all of them - so
// the answer only ever travels down `presence.query`, which is per-asker.
ok('the offline broadcast carries no timestamp', offline?.user.lastSeenAt === undefined);

// Bob asks about Alice, who has just left and has never narrowed her setting.
// This is the path that may answer, and the only one.
const beforeAliceQuery = b.events.length;
b.send({ type: 'presence.query', userIds: [alice.user.id] });
const aliceSeen = await b.waitFor(
  (event) =>
    event.type === 'presence.changed' &&
    event.user.userId === alice.user.id &&
    typeof event.user.lastSeenAt === 'string',
  4000,
  beforeAliceQuery,
);
ok('a query answers with a last-seen time', aliceSeen !== null);
ok(
  'and it is when she actually left',
  Math.abs(Date.now() - new Date(aliceSeen.user.lastSeenAt).getTime()) < 5 * 60_000,
);

// --- the privacy setting, and the rule that makes it worth having ------------
//
// Alice narrows hers to friends. Bob shares a server with her and is not her
// friend, so the timestamp he could read a moment ago must stop arriving - the
// same query, the same account, a different answer.
await setLastSeenVisibility(alice, 'friends');
const beforeFriends = b.events.length;
b.send({ type: 'presence.query', userIds: [alice.user.id] });
await new Promise((resolve) => setTimeout(resolve, 500));
ok(
  'friends-only hides it from a server-mate',
  b.events
    .slice(beforeFriends)
    .filter((event) => event.type === 'presence.changed' && event.user.userId === alice.user.id)
    .every((event) => event.user.lastSeenAt === undefined),
);
// The status still arrives. It is the timestamp that is private, not the
// account - a query that went silent would say something by going silent.
ok(
  'but the status still arrives',
  b.events
    .slice(beforeFriends)
    .some((event) => event.type === 'presence.changed' && event.user.userId === alice.user.id),
);

// And reciprocity: Bob hides his own, Alice opens hers all the way back up, and
// Bob still gets nothing. This is the rule that stops the setting being a
// one-way mirror, and it is the one worth an end-to-end assertion because it
// depends on two accounts' settings at once.
await setLastSeenVisibility(alice, 'everyone');
await setLastSeenVisibility(bob, 'nobody');
const beforeHiding = b.events.length;
b.send({ type: 'presence.query', userIds: [alice.user.id] });
await new Promise((resolve) => setTimeout(resolve, 500));
ok(
  "somebody who hides their own reads nobody else's",
  b.events
    .slice(beforeHiding)
    .filter((event) => event.type === 'presence.changed' && event.user.userId === alice.user.id)
    .every((event) => event.user.lastSeenAt === undefined),
);
// Not "no presence.changed at all": Carol is in her own audience, so her own
// arrival comes back to her. Everything about anybody else is what must never
// reach her, and that is what this asserts.
ok(
  'no presence about strangers at all',
  c.events
    .filter((event) => event.type === 'presence.changed')
    .every((event) => event.user.userId === carol.user.id),
);

b.socket.close();
c.socket.close();
console.log('\nPRESENCE SMOKE PASSED');
process.exit(0);

import { Module } from '@nestjs/common';
import { envOr } from '@betweenus/config';
import { EventBus } from '@betweenus/events';
import { Logger, createLogger } from '@betweenus/logger';
import { createHealthController } from '@betweenus/nest-common';
import { PresenceController } from './presence.controller';
import { PresenceGateway } from './presence.gateway';
import { PresenceStore } from './presence.store';

const SERVICE_NAME = 'presence-service';

@Module({
  controllers: [createHealthController(SERVICE_NAME), PresenceController],
  providers: [
    PresenceStore,
    PresenceGateway,
    {
      provide: EventBus,
      useFactory: () => new EventBus(envOr('REDIS_URL', 'redis://localhost:6379'), SERVICE_NAME),
    },
    {
      provide: Logger,
      useFactory: (): Logger => createLogger(SERVICE_NAME, envOr('LOG_LEVEL', 'info') as never),
    },
  ],
})
export class AppModule {}

/**
 * Who is entitled to hear a given piece of presence.
 *
 * Every presence event used to go to every connected socket: a stranger going
 * idle, somebody typing in a channel on a server you are not in, a voice roster
 * for a room you cannot see. That is a privacy problem before it is a traffic
 * problem - the online list was effectively the whole deployment's user
 * directory, and a typing event named a channel id and a username to people
 * with no business knowing either.
 *
 * Two questions answer all of it, and both are symmetric, which is what makes
 * them cheap: the set of people who may hear about a *user* is the same set
 * that user may hear about, so an event is scoped once rather than once per
 * recipient.
 *
 * ponytail: a small TTL cache, not an invalidation scheme. Joining a server
 * means the new member's dot appears to the others within the TTL rather than
 * instantly, which is the same order of delay as the heartbeat that maintains
 * the online set in the first place.
 */
import { prisma } from '@betweenus/database';

/** How long an answer is reused. Long enough to matter, short enough to be dull. */
const TTL_MS = 30_000;

interface Cached {
  at: number;
  ids: Set<string>;
}

const userCache = new Map<string, Cached>();
const channelCache = new Map<string, Cached>();

function fresh(entry: Cached | undefined): Set<string> | null {
  if (!entry) return null;
  return Date.now() - entry.at < TTL_MS ? entry.ids : null;
}

/**
 * Everybody who shares a server with this user, plus their accepted friends,
 * plus the user themselves.
 *
 * A friendship counts on its own because a direct message is not on any server:
 * without it, two friends with no server in common would each see the other as
 * permanently offline.
 */
export async function audienceOfUser(userId: string): Promise<Set<string>> {
  const cached = fresh(userCache.get(userId));
  if (cached) return cached;

  const memberships = await prisma.serverMember.findMany({
    where: { userId },
    select: { serverId: true },
  });
  const serverIds = memberships.map((row) => row.serverId);

  const [peers, friendships] = await Promise.all([
    serverIds.length > 0
      ? prisma.serverMember.findMany({
          where: { serverId: { in: serverIds } },
          select: { userId: true },
        })
      : Promise.resolve([] as { userId: string }[]),
    prisma.friendship.findMany({
      where: { status: 'ACCEPTED', OR: [{ userAId: userId }, { userBId: userId }] },
      select: { userAId: true, userBId: true },
    }),
  ]);

  const ids = new Set<string>([userId]);
  for (const peer of peers) ids.add(peer.userId);
  for (const friendship of friendships) {
    ids.add(friendship.userAId);
    ids.add(friendship.userBId);
  }

  userCache.set(userId, { at: Date.now(), ids });
  return ids;
}

/**
 * Everybody entitled to know what happens in a channel: its allowlist when it
 * is private or a direct message, and the server's membership when it is not.
 *
 * A missing channel answers with nobody rather than everybody. An event about a
 * channel that does not exist is not an event anybody needs.
 */
export async function audienceOfChannel(channelId: string): Promise<Set<string>> {
  const cached = fresh(channelCache.get(channelId));
  if (cached) return cached;

  const channel = await prisma.channel.findUnique({
    where: { id: channelId },
    select: {
      serverId: true,
      isPrivate: true,
      members: { select: { userId: true } },
    },
  });

  const ids = new Set<string>();
  if (!channel) {
    channelCache.set(channelId, { at: Date.now(), ids });
    return ids;
  }

  if (channel.serverId === null || channel.isPrivate) {
    // A DM has exactly its two participants; a private channel has its
    // allowlist, and server membership grants nothing on top of it.
    for (const member of channel.members) ids.add(member.userId);
  } else {
    const members = await prisma.serverMember.findMany({
      where: { serverId: channel.serverId },
      select: { userId: true },
    });
    for (const member of members) ids.add(member.userId);
  }

  channelCache.set(channelId, { at: Date.now(), ids });
  return ids;
}

/** Called when membership changes underneath the cache, and by the tests. */
export function forgetAudiences(): void {
  userCache.clear();
  channelCache.clear();
}

/** Run with `tsx src/last-seen-visibility.check.ts`. Who may read whose last seen. */
import assert from 'node:assert/strict';
import type { LastSeenVisibility } from '@betweenus/shared-types';
import { maySeeLastSeen, readableLastSeen, toVisibility } from './last-seen-visibility';

/** A stranger who shares a server, asking about somebody with the given setting. */
const asks = (
  subject: LastSeenVisibility,
  asker: LastSeenVisibility = 'everyone',
  friends = false,
): boolean => maySeeLastSeen({ subject, asker, friends, self: false });

// --- the three tiers ---------------------------------------------------------

// "Everyone" is everyone who could already see the name; the audience check
// upstream is what makes that a smaller word than it looks.
assert.equal(asks('everyone'), true);
assert.equal(asks('everyone', 'everyone', true), true);

// "Friends" is an accepted friendship and nothing weaker. A server in common is
// not a friendship, which is the whole point of having the tier at all.
assert.equal(asks('friends', 'everyone', true), true);
assert.equal(asks('friends', 'everyone', false), false, 'a server-mate is not a friend');

assert.equal(asks('nobody'), false);
assert.equal(asks('nobody', 'everyone', true), false, 'nobody outranks a friendship');

// --- reciprocity -------------------------------------------------------------

// The rule that keeps the setting from being a one-way mirror: somebody who
// hides their own last seen does not get to read anybody else's, however
// generous that person has been.
assert.equal(asks('everyone', 'nobody'), false, 'a hider reads nobody');
assert.equal(asks('friends', 'nobody', true), false, 'not even a friend of theirs');
assert.equal(asks('nobody', 'nobody'), false);

// It is only `nobody` that disqualifies. Narrowing to friends is a limit on who
// reads you, not a forfeit of what you may read - which is also WhatsApp's rule.
assert.equal(asks('everyone', 'friends'), true, 'restricting to friends costs nothing');
assert.equal(asks('friends', 'friends', true), true);

// --- your own value is always yours ------------------------------------------

// Otherwise the settings page could not draw what the setting does, and an
// account set to `nobody` would be unable to see itself.
for (const setting of ['everyone', 'friends', 'nobody'] as LastSeenVisibility[]) {
  assert.equal(
    maySeeLastSeen({ subject: setting, asker: setting, friends: false, self: true }),
    true,
    `${setting}: your own last seen is yours to read`,
  );
}

// --- the batch answers the same way ------------------------------------------

const subjects = [
  { id: 'open', visibility: 'everyone' as LastSeenVisibility },
  { id: 'friendly', visibility: 'friends' as LastSeenVisibility },
  { id: 'closed', visibility: 'nobody' as LastSeenVisibility },
  { id: 'me', visibility: 'nobody' as LastSeenVisibility },
];

const seen = readableLastSeen('me', 'everyone', subjects, new Set(['friendly']));
assert.deepEqual([...seen].sort(), ['friendly', 'me', 'open']);

// The same batch asked by somebody who hides: nothing but themselves.
const hidden = readableLastSeen('me', 'nobody', subjects, new Set(['friendly']));
assert.deepEqual([...hidden], ['me'], 'a hider gets only their own back');

// An empty batch is an empty answer rather than a crash or a wildcard.
assert.equal(readableLastSeen('me', 'everyone', [], new Set()).size, 0);

// --- the column's spelling ---------------------------------------------------

assert.equal(toVisibility('EVERYONE'), 'everyone');
assert.equal(toVisibility('FRIENDS'), 'friends');
assert.equal(toVisibility('NOBODY'), 'nobody');

// A value this build does not know is read as the widest, which is what the
// column defaults to - a narrower guess would silently hide people who never
// asked to be hidden.
assert.equal(toVisibility(null), 'everyone');
assert.equal(toVisibility(undefined), 'everyone');
assert.equal(toVisibility('SOMETHING_NEWER'), 'everyone');

console.log('last-seen-visibility.check.ts ok');

/**
 * Who may read whose last-seen time.
 *
 * A pure function, apart from the four database reads that feed it, because
 * every interesting case here is a combination of two people's settings and a
 * relationship - and a rule about privacy that is only ever exercised by two
 * accounts on two laptops is a rule nobody checks.
 *
 * The three tiers are WhatsApp's, and so is the reciprocity: an account that
 * hides when it was last here does not get to read anybody else's. Without that
 * the setting is a one-way mirror, which everybody switches on the moment it
 * costs them nothing, and the feature stops meaning anything for everyone.
 *
 * `everyone` is the ceiling rather than the whole world. Presence is already
 * scoped to people who share a server or an accepted friendship - see
 * `audience.ts` - so the widest this can ever be is "everybody who could
 * already see your name", and this function is a filter on top of that rather
 * than a way around it.
 */
import type { LastSeenVisibility } from '@betweenus/shared-types';

/** What one account has decided, and what the asker has decided about theirs. */
export interface LastSeenQuestion {
  /** The subject's own setting - who they will let read it. */
  subject: LastSeenVisibility;
  /** The asker's setting. Only `nobody` matters here, and it disqualifies them. */
  asker: LastSeenVisibility;
  /** Whether the two hold an accepted friendship. */
  friends: boolean;
  /** Whether the asker is the subject. Your own value is always yours to read. */
  self: boolean;
}

/**
 * Whether the asker may read the subject's last-seen time.
 *
 * The caller has already established that the asker is in the subject's
 * audience; this decides nothing about people who cannot see each other at all,
 * because the answer there was already no.
 */
export function maySeeLastSeen(question: LastSeenQuestion): boolean {
  // Your own screen shows you your own value whatever you have chosen, or the
  // settings page could not draw what the setting does.
  if (question.self) return true;

  // Reciprocity, and it is checked first: somebody who hides their own is
  // refused before the subject's generosity is even consulted.
  if (question.asker === 'nobody') return false;

  switch (question.subject) {
    case 'everyone':
      return true;
    case 'friends':
      return question.friends;
    case 'nobody':
      return false;
  }
}

/**
 * The same decision for a batch, which is the shape a query actually arrives in.
 *
 * One asker, many subjects: a profile card asks about one person and a
 * conversation header about one, but a member column asks about a screenful,
 * and a database round trip per row is not the way to answer that.
 */
export function readableLastSeen(
  askerId: string,
  askerVisibility: LastSeenVisibility,
  subjects: { id: string; visibility: LastSeenVisibility }[],
  friendIds: Set<string>,
): Set<string> {
  const allowed = new Set<string>();
  for (const subject of subjects) {
    const may = maySeeLastSeen({
      subject: subject.visibility,
      asker: askerVisibility,
      friends: friendIds.has(subject.id),
      self: subject.id === askerId,
    });
    if (may) allowed.add(subject.id);
  }
  return allowed;
}

/** The database's spelling of the setting, in the one the wire uses. */
export function toVisibility(value: string | null | undefined): LastSeenVisibility {
  switch (value) {
    case 'FRIENDS':
      return 'friends';
    case 'NOBODY':
      return 'nobody';
    // An unknown value is somebody else's newer build, and the safe reading of
    // a privacy setting nobody here understands is the widest one it could be
    // narrowed from - which is what the column defaults to anyway.
    default:
      return 'everyone';
  }
}

import 'reflect-metadata';
import type { Server as HttpServer } from 'node:http';
import { bootstrapService } from '@betweenus/nest-common';
import { AppModule } from './app.module';
import { PresenceGateway } from './presence.gateway';

async function start(): Promise<void> {
  const app = await bootstrapService({
    service: 'presence-service',
    module: AppModule,
    portVar: 'PRESENCE_SERVICE_PORT',
    defaultPort: 3005,
  });

  // The WebSocket server shares the HTTP listener, so /ws/presence and /health
  // live behind one port and one Nginx upstream.
  const gateway = app.get(PresenceGateway);
  await gateway.attach(app.getHttpServer() as HttpServer);
}

void start();

/**
 * Presence over HTTP, for the services that need a number rather than a stream.
 *
 * `server-service` has to answer "how many of this server's members are here
 * right now" when it describes an invite, and it has no business reading
 * presence out of Redis itself: presence belongs to this service, and a second
 * reader of `presence:online` is a second thing to change when that key does.
 *
 * It is not routed by the gateway. Nginx forwards the paths it names and
 * nothing else, and `/api/v1/internal` is not one of them, so this is reachable
 * on the internal Docker network and nowhere else. That is also why there is no
 * guard: there is no user here to authenticate, only another service.
 */
import { Controller, Get, Query } from '@nestjs/common';
import { PresenceStore } from './presence.store';

@Controller('internal/presence')
export class PresenceController {
  constructor(private readonly store: PresenceStore) {}

  /**
   * Everyone online, as ids. Invisible users are already resolved to offline by
   * the store, so they are not in this list - being counted as present is
   * exactly what invisible means you are not.
   */
  /**
   * Which of these users is reading this channel right now.
   *
   * `notification-service` asks once per message, with the audience it has
   * already worked out, and drops the answer from the fan-out: a phone is not
   * worth waking for a conversation its owner is reading on a laptop. The
   * userIds come as one comma-separated parameter because a fan-out is a batch
   * and a request per recipient would be a request per recipient.
   *
   * Empty answer for an empty or missing list, which is the honest reading of
   * "none of nobody is looking".
   */
  @Get('focus')
  async focus(
    @Query('channelId') channelId?: string,
    @Query('userIds') userIds?: string,
  ): Promise<{ focused: string[] }> {
    const audience = (userIds ?? '').split(',').filter(Boolean);
    if (!channelId || audience.length === 0) return { focused: [] };
    return { focused: await this.store.focusedAmong(channelId, audience) };
  }

  @Get('online')
  async online(): Promise<{ userIds: string[] }> {
    const states = await this.store.onlineUsers();
    return { userIds: states.map((state) => state.userId) };
  }
}

/**
 * `/ws/presence` realtime gateway: online status, typing indicators and voice
 * channel membership.
 *
 * State lives in Redis and changes fan out over Redis Pub/Sub, so several
 * presence-service instances stay consistent without sticky sessions - the same
 * pattern the chat gateway uses.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { EVENTS, EventBus } from '@betweenus/events';
import { resolveChannelAccess } from '@betweenus/database';
import { PERMISSIONS } from '@betweenus/permissions';
import { Logger } from '@betweenus/logger';
import {
  CONTROL_MAX_PAYLOAD,
  authenticateHandshake,
  dropRevokedSockets,
} from '@betweenus/websocket';
import type { ClientPresenceEvent, ServerPresenceEvent } from '@betweenus/shared-types';
import { PresenceStore, isActiveStatus } from './presence.store';
import { audienceOfChannel, audienceOfUser } from './audience';

const HEARTBEAT_INTERVAL_MS = 30_000;

/**
 * The most accounts one `presence.query` will answer for.
 *
 * A card opens for one person and a conversation header asks about one; the
 * largest honest batch is a member column, and a column longer than this is
 * scrolled rather than read at once. The cap is here so that a client asking
 * about the whole user table gets an answer about a hundred of them instead of
 * a database query per id.
 */
const QUERY_LIMIT = 100;

interface SocketState {
  userId: string;
  username: string;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
  /**
   * The channel this window has on screen, or null. One at a time: a window
   * shows one conversation, and a second focus replaces the first rather than
   * adding to it.
   */
  focused: string | null;
}

@Injectable()
export class PresenceGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly state = new WeakMap<WebSocket, SocketState>();

  constructor(
    private readonly store: PresenceStore,
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  async attach(httpServer: HttpServer): Promise<void> {
    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/presence',
      maxPayload: CONTROL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        socket.close(4401, 'Unauthorized');
        return;
      }

      this.state.set(socket, {
        userId: user.id,
        username: user.username,
        alive: true,
        issuedAt: user.issuedAt,
        focused: null,
      });
      void this.onConnect(socket, user.id);

      socket.on('pong', () => {
        const state = this.state.get(socket);
        if (state) state.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handleClientEvent(socket, raw.toString());
      });

      socket.on('close', () => {
        void this.onDisconnect(socket, user.id);
      });

      socket.on('error', (error) => {
        this.logger.warn('Presence socket error', { userId: user.id, reason: String(error) });
      });
    });

    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
        // A live socket is a live user; this is what keeps them out of the
        // stale window in Redis.
        void this.store.touch(state.userId);
        // And a live socket still looking at a channel is still looking at it.
        // Without this the focus ages out after 90 seconds and a phone starts
        // buzzing for a conversation that is open on a desktop.
        if (state.focused) void this.store.focus(state.focused, state.userId);
      }

      void this.sweepVoice();
    }, HEARTBEAT_INTERVAL_MS);

    // Every one of these is scoped. A status change reaches the people who
    // share a server or a friendship with whoever changed; anything about a
    // channel reaches the people who can see that channel. Nothing goes to
    // every connected socket any more.
    // An account whose authority was withdrawn loses the sockets it already
    // had, which is the half of a revocation that was missing: a handshake is
    // checked once and then trusted until it happens to disconnect.
    await dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) => this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    await this.events.subscribe(EVENTS.PRESENCE_CHANGED, (envelope) => {
      const { user } = envelope.payload;
      void this.broadcastTo(audienceOfUser(user.userId), { type: 'presence.changed', user });
    });
    await this.events.subscribe(EVENTS.PRESENCE_TYPING, (envelope) => {
      const { channelId, userId, username } = envelope.payload;
      void this.broadcastTo(
        audienceOfChannel(channelId),
        { type: 'typing', channelId, userId, username },
        userId,
      );
    });
    await this.events.subscribe(EVENTS.PRESENCE_VOICE, (envelope) => {
      const { voice } = envelope.payload;
      void this.broadcastTo(audienceOfChannel(voice.channelId), { type: 'voice.changed', voice });
    });

    // The roster as call-service holds it, which is the only place it is really
    // known: it owns the signalling sockets, so it sees a join, a departure and
    // a crash alike. Written through to Redis so a client connecting later gets
    // the same answer in its sync.
    await this.events.subscribe(EVENTS.CALL_ROSTER, (envelope) => {
      const { voice } = envelope.payload;
      void this.store
        .replaceVoice(voice.channelId, voice.userIds)
        .then(() =>
          this.broadcastTo(audienceOfChannel(voice.channelId), { type: 'voice.changed', voice }),
        )
        .catch((error) => {
          this.logger.warn('Could not apply a call roster', {
            channelId: voice.channelId,
            reason: String(error),
          });
        });
    });

    // Somebody is ringing somebody else into a call. Straight to the person
    // being rung and to nobody else - a ring is directed, so it has no
    // audience to scope to and there is nothing here to broadcast.
    //
    // Every instance receives this and delivers to its own sockets; an
    // instance the target is not connected to does nothing, which is what
    // `sendToUser` already means. The push fan-out covers the devices that are
    // not connected to any of them.
    await this.events.subscribe(EVENTS.CALL_RING, (envelope) => {
      const ring = envelope.payload;
      this.sendToUser(ring.targetId, {
        type: 'call.ring',
        channelId: ring.channelId,
        channelName: ring.channelName,
        callerId: ring.callerId,
        callerName: ring.callerName,
        ...(ring.callerAvatarUrl ? { callerAvatarUrl: ring.callerAvatarUrl } : {}),
      });
    });

    // Somebody said no to a ring, on one of their devices. Straight back to
    // that same account and to nobody else - the caller is deliberately not
    // told, and nobody else was ever ringing.
    //
    // Answering needs no equivalent: a running client sees itself arrive in
    // `call.roster` above and draws the same conclusion. Declining reaches no
    // roster, so without this a laptop went on ringing after somebody said no
    // on their phone.
    await this.events.subscribe(EVENTS.CALL_DECLINED, (envelope) => {
      const { userId, channelId } = envelope.payload;
      this.sendToUser(userId, { type: 'call.handled', channelId, how: 'declined' });
    });

    this.logger.info('Presence WebSocket gateway ready', { path: '/ws/presence' });
  }

  /**
   * Empties the voice channels `call-service` has stopped speaking for.
   *
   * Its rosters expire now (see `replaceVoice`), which is what makes a call
   * that outlived its own service stop being a room full of ghosts. Expiring in
   * Redis fixes the next client to connect; this is what fixes the ones already
   * looking at it, which is where the ghost was actually being seen.
   */
  private async sweepVoice(): Promise<void> {
    try {
      for (const channelId of await this.store.expireVoice()) {
        await this.broadcastTo(audienceOfChannel(channelId), {
          type: 'voice.changed',
          voice: { channelId, userIds: [] },
        });
      }
    } catch (error) {
      this.logger.warn('Could not expire the call rosters', { reason: String(error) });
    }
  }

  private async onConnect(socket: WebSocket, userId: string): Promise<void> {
    await this.store.touch(userId);

    // Nothing is cleared here any more. A client connecting used to drop itself
    // from every voice channel on the assumption that a leftover was a dead
    // session - which was a fair guess while the roster was client-written, and
    // is now wrong: the roster belongs to call-service, and this connection
    // says nothing about whether that one is still up.
    this.send(socket, { type: 'ready', userId });

    const [users, voice, own, audience] = await Promise.all([
      this.store.onlineUsers(),
      this.store.allVoiceStates(),
      // The chosen status survives a restart, so the picker has to be told what
      // it currently is rather than assuming "online".
      this.store.statusOf(userId),
      audienceOfUser(userId),
    ]);

    // The same scoping the live events get. Without it the first message on a
    // socket is the whole deployment's online list, and every later one is
    // filtered - which is the sort of half-done that looks like it works.
    const visibleUsers = users.filter((user) => audience.has(user.userId));
    const rooms = await Promise.all(
      voice.map(async (room) => ({
        room,
        allowed: (await audienceOfChannel(room.channelId)).has(userId),
      })),
    );
    const visibleVoice = rooms.filter((entry) => entry.allowed).map((entry) => entry.room);

    this.send(socket, { type: 'presence.sync', users: visibleUsers, voice: visibleVoice });
    this.send(socket, { type: 'status.self', status: own });

    await this.publishStatus(userId);
    this.logger.info('Presence connected', { userId });
  }

  /** Tells everyone else what this user looks like, invisible resolved away. */
  private async publishStatus(userId: string): Promise<void> {
    const status = await this.store.visibleStatusOf(userId);
    await this.events.publish(EVENTS.PRESENCE_CHANGED, { user: { userId, status } });
  }

  private async onDisconnect(socket: WebSocket, userId: string): Promise<void> {
    const state = this.state.get(socket);
    this.state.delete(socket);

    // Before the early return below: this window is gone whether or not the
    // user has others, and a window that is gone is not reading anything.
    //
    // Focus is per user, so the entry is only removed if no *other* window of
    // theirs is still on that channel. Removing it unconditionally would leave
    // a gap - up to one heartbeat - in which a phone is woken for a
    // conversation that is open on a second screen right now.
    if (state?.focused && !this.stillFocused(userId, state.focused, socket)) {
      await this.store.blur(state.focused, userId);
    }

    // Another window of the same user may still be connected to this instance.
    if (this.hasOtherSocket(userId, socket)) return;

    await this.store.goOffline(userId);

    // The last window of this account has gone, so the last-seen value has
    // stopped moving - which is the moment it is worth a row rather than a
    // Redis key.
    await this.store.flushLastSeen(userId);

    // The event deliberately carries no timestamp. Who may read one depends on
    // the reader - the subject's `LastSeenVisibility`, a friendship, and whether
    // the reader has hidden their own - and a broadcast has one payload for
    // every recipient. Clients that care ask with `presence.query` when they see
    // somebody go offline, and that road is per-asker and can answer honestly.
    //
    // The call roster is not touched: a presence socket closing is not evidence
    // that a call ended, and call-service publishes the departure itself the
    // moment its own socket goes - including when it goes by being terminated
    // for missing a heartbeat.
    await this.events.publish(EVENTS.PRESENCE_CHANGED, {
      user: { userId, status: 'offline' },
    });
    this.logger.info('Presence disconnected', { userId });
  }

  /** Has this user another live window on `channelId`? See `onDisconnect`. */
  private stillFocused(userId: string, channelId: string, except: WebSocket): boolean {
    for (const socket of this.server?.clients ?? []) {
      if (socket === except) continue;
      if (socket.readyState !== WebSocket.OPEN) continue;
      const state = this.state.get(socket);
      if (state?.userId === userId && state.focused === channelId) return true;
    }
    return false;
  }

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room: the four gateways keep different
   * bookkeeping and `clients` is the one thing all of them have. A revocation is
   * rare, and a scan of one instance's sockets is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  /** Is this user connected through some socket other than `except`? */
  private hasOtherSocket(userId: string, except?: WebSocket): boolean {
    for (const socket of this.server?.clients ?? []) {
      if (socket === except) continue;
      if (socket.readyState !== WebSocket.OPEN) continue;
      if (this.state.get(socket)?.userId === userId) return true;
    }
    return false;
  }

  private async handleClientEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientPresenceEvent;
    try {
      event = JSON.parse(raw) as ClientPresenceEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'status.set': {
        if (!isActiveStatus(event.status)) {
          this.send(socket, {
            type: 'error',
            code: 'UNKNOWN_STATUS',
            message: 'Unsupported status',
          });
          return;
        }
        await this.store.setStatus(state.userId, event.status);
        // Every window of this user gets the real value; everyone else gets
        // what `publishStatus` resolves it to.
        this.sendToUser(state.userId, { type: 'status.self', status: event.status });
        await this.publishStatus(state.userId);
        return;
      }

      case 'ping':
        await this.store.touch(state.userId);
        this.send(socket, { type: 'pong' });
        return;

      /**
       * "When were these people last here?"
       *
       * Answered one `presence.changed` at a time rather than in a batch of its
       * own, so a client has exactly one road into its presence state and the
       * answer to a question and the news of a change are the same shape.
       *
       * Scoped through `audienceOfUser`, the same set every broadcast is scoped
       * to. Without it this would be the one event a client could aim at an
       * arbitrary id, and a "who is online" oracle over the whole deployment is
       * the thing `audience.ts` was written to remove.
       */
      case 'presence.query': {
        if (!Array.isArray(event.userIds) || event.userIds.length === 0) return;
        const asked = [...new Set(event.userIds)].slice(0, QUERY_LIMIT);

        let allowed: Set<string>;
        try {
          allowed = await audienceOfUser(state.userId);
        } catch (error) {
          this.logger.warn('Could not scope a presence query', { reason: String(error) });
          return;
        }

        const visible = asked.filter((userId) => allowed.has(userId));
        if (visible.length === 0) return;

        const [seen, statuses] = await Promise.all([
          // The privacy filter is inside this call, so anybody the asker may
          // not read is simply missing from the map - see `lastSeenOf`.
          this.store.lastSeenOf(state.userId, visible),
          Promise.all(visible.map((userId) => this.store.stateOf(userId))),
        ]);

        visible.forEach((userId, index) => {
          const status = statuses[index] ?? 'offline';
          const lastSeenAt = seen.get(userId);
          // Only for somebody who is not here. "Online, last seen a moment
          // ago" says one thing twice, and the second half goes stale first.
          this.send(socket, {
            type: 'presence.changed',
            user: {
              userId,
              status,
              ...(status === 'offline' && lastSeenAt ? { lastSeenAt } : {}),
            },
          });
        });
        return;
      }

      /**
       * The window is showing this channel and has the user's attention.
       *
       * Permission is checked, like typing: focus suppresses notifications, so
       * an unchecked one would let anybody silence a channel they cannot even
       * see for everybody who can.
       */
      case 'channel.focus': {
        if (!(await this.canAccessChannel(state.userId, event.channelId))) return;
        // One channel per window. Leaving the old one behind would have a
        // window that has moved on still suppressing the conversation it left.
        if (state.focused && state.focused !== event.channelId) {
          await this.store.blur(state.focused, state.userId);
        }
        state.focused = event.channelId;
        await this.store.focus(event.channelId, state.userId);
        return;
      }

      case 'channel.blur': {
        if (state.focused === event.channelId) state.focused = null;
        await this.store.blur(event.channelId, state.userId);
        return;
      }

      case 'typing.start':
        if (!(await this.canAccessChannel(state.userId, event.channelId))) return;
        await this.events.publish(EVENTS.PRESENCE_TYPING, {
          channelId: event.channelId,
          userId: state.userId,
          username: state.username,
        });
        return;

      // Both of these used to write the roster, which meant the roster was
      // whatever a client claimed: anybody could appear in a channel they had
      // never signalled into, and anybody who crashed stayed in one. The roster
      // now comes from `call-service`, which holds the signalling sockets and
      // therefore knows. These are kept because the permission answer is still
      // worth giving - a client that may not join should hear so from the
      // service it asked, not by watching a roster it never appears in.
      case 'voice.join': {
        if (!(await this.canAccessChannel(state.userId, event.channelId))) {
          this.send(socket, {
            type: 'error',
            code: 'CHANNEL_FORBIDDEN',
            message: 'Cannot join this voice channel',
          });
        }
        return;
      }

      case 'voice.leave':
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  /**
   * The same resolver chat- and call-service use. Typing and voice both need
   * only to see the channel, so `VIEW_CHANNEL` is the bar.
   */
  private async canAccessChannel(userId: string, channelId: string): Promise<boolean> {
    const access = await resolveChannelAccess(userId, channelId);
    return access !== null && access.permissions.includes(PERMISSIONS.VIEW_CHANNEL);
  }

  /** Every socket belonging to one user - a person may have several windows. */
  private sendToUser(userId: string, event: ServerPresenceEvent): void {
    for (const socket of this.server?.clients ?? []) {
      if (this.state.get(socket)?.userId === userId) this.send(socket, event);
    }
  }

  /**
   * Sends to the sockets whose user is in `audience`, and to nobody else.
   *
   * The audience is worked out once per event rather than once per socket,
   * which is what the symmetry in `audience.ts` buys: the set of people allowed
   * to hear about a user is the set that user is allowed to hear about.
   *
   * `exceptUserId` keeps a typing indicator from echoing to its own author.
   */
  private async broadcastTo(
    audience: Promise<Set<string>>,
    event: ServerPresenceEvent,
    exceptUserId?: string,
  ): Promise<void> {
    let allowed: Set<string>;
    try {
      allowed = await audience;
    } catch (error) {
      // A database that cannot answer must not turn into a broadcast to
      // everybody. Dropping the event is the safe direction: a dot is stale,
      // rather than shown to somebody with no right to it.
      this.logger.warn('Could not scope a presence event', { reason: String(error) });
      return;
    }

    for (const socket of this.server?.clients ?? []) {
      const state = this.state.get(socket);
      if (!state) continue;
      if (exceptUserId && state.userId === exceptUserId) continue;
      if (!allowed.has(state.userId)) continue;
      this.send(socket, event);
    }
  }

  private send(socket: WebSocket, event: ServerPresenceEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    this.server?.close();
  }
}

/**
 * Redis-backed presence state.
 *
 * Online users live in one sorted set scored by their last heartbeat, so a
 * crashed client ages out instead of appearing online forever, and no per-user
 * key bookkeeping is needed. Voice membership is a set per channel.
 *
 * Nothing here is durable on purpose: presence is realtime state, and Redis is
 * where the architecture puts it.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import Redis from 'ioredis';
import { prisma } from '@betweenus/database';
import { envOr } from '@betweenus/config';
import type {
  ActiveStatus,
  PresenceState,
  PresenceStatus,
  VoiceState,
} from '@betweenus/shared-types';
import { voiceLifetime } from './voice-lifetime';
import { readableLastSeen, toVisibility } from './last-seen-visibility';

const ONLINE_KEY = 'presence:online';
const STATUS_KEY = 'presence:status';
const VOICE_KEY = (channelId: string): string => `presence:voice:${channelId}`;
const VOICE_INDEX = 'presence:voice:channels';
const FOCUS_KEY = (channelId: string): string => `presence:focus:${channelId}`;
/**
 * userId -> the last millisecond this account was seen connected and visible.
 *
 * A hash rather than a score on `presence:online`, because that sorted set is
 * trimmed of anybody stale - which is precisely the moment the answer starts
 * being interesting. Nothing expires it: one small entry per account that has
 * ever connected, which is the same order as the user table.
 */
const LAST_SEEN_KEY = 'presence:lastseen';

/** Anything else in the hash is a status this build does not know; ignore it. */
const ACTIVE_STATUSES: ActiveStatus[] = ['online', 'idle', 'dnd', 'invisible'];

/** A client that has not checked in for this long is treated as gone. */
export const STALE_AFTER_MS = 90_000;

@Injectable()
export class PresenceStore implements OnModuleDestroy {
  private readonly redis = new Redis(envOr('REDIS_URL', 'redis://localhost:6379'), {
    maxRetriesPerRequest: null,
  });

  /**
   * Marks a user online, or refreshes their heartbeat, and notes the moment as
   * when they were last seen.
   *
   * An invisible account is skipped for the second half only. It is genuinely
   * connected, so it still ages correctly out of `presence:online`; it is just
   * not *seen*, and a last-seen time that kept ticking while somebody was
   * hidden would be a green dot spelled differently.
   */
  async touch(userId: string): Promise<void> {
    const now = Date.now();
    await this.redis.zadd(ONLINE_KEY, now, userId);
    if ((await this.statusOf(userId)) === 'invisible') return;
    await this.redis.hset(LAST_SEEN_KEY, userId, now);
  }

  async goOffline(userId: string): Promise<void> {
    await this.redis.zrem(ONLINE_KEY, userId);
  }

  /**
   * Writes the live last-seen value through to Postgres.
   *
   * Called when an account's last window closes, which is the only moment the
   * value stops changing and therefore the only moment it is worth a row write.
   * Redis answers while somebody is online and for as long as it keeps the
   * hash; this is what survives a wipe, a restart, or an absence long enough
   * that nobody remembers the session.
   *
   * A failure is logged nowhere and swallowed here on purpose: the caller is a
   * socket closing, and a database that is briefly unhappy must not turn a
   * disconnect into an unhandled rejection. The value stays in Redis and the
   * next disconnect writes it.
   */
  async flushLastSeen(userId: string): Promise<void> {
    const seen = await this.redis.hget(LAST_SEEN_KEY, userId);
    if (seen === null) return;
    try {
      await prisma.user.update({
        where: { id: userId },
        data: { lastSeenAt: new Date(Number(seen)) },
      });
    } catch {
      return;
    }
  }

  /**
   * When each of these accounts was last seen, ISO-8601, as far as `askerId` is
   * allowed to know.
   *
   * Redis and Postgres are both consulted rather than one falling back to the
   * other: Redis is ahead for anybody who has connected since the last flush,
   * and Postgres is the only answer for anybody whose entry a wipe took. Taking
   * the later of the two is right in both directions and needs no bookkeeping
   * about which store is authoritative.
   *
   * **The privacy filter lives here rather than at the call sites**, so there is
   * one place that decides who may read a last-seen time and no way to reach the
   * value without going through it. `LastSeenVisibility`, the friendship it may
   * depend on, and the reciprocity rule are all applied before anything is
   * returned - see `last-seen-visibility.ts` for what the rule actually is.
   *
   * An account that has never been seen, one whose setting excludes the asker,
   * and one the asker has disqualified themselves from reading are all simply
   * absent from the map. That is deliberate: every client already draws a
   * missing timestamp as no line at all, so which of the three reasons produced
   * it is not something the wire says.
   */
  async lastSeenOf(askerId: string, userIds: string[]): Promise<Map<string, string>> {
    if (userIds.length === 0) return new Map();

    const [live, rows, asker, friendships] = await Promise.all([
      this.redis.hmget(LAST_SEEN_KEY, ...userIds),
      prisma.user.findMany({
        where: { id: { in: userIds } },
        select: { id: true, lastSeenAt: true, lastSeenVisibility: true },
      }),
      prisma.user.findUnique({
        where: { id: askerId },
        select: { lastSeenVisibility: true },
      }),
      // Only the friendships that could matter - the asker's, with these
      // subjects - rather than their whole friend list.
      prisma.friendship.findMany({
        where: {
          status: 'ACCEPTED',
          OR: [
            { userAId: askerId, userBId: { in: userIds } },
            { userBId: askerId, userAId: { in: userIds } },
          ],
        },
        select: { userAId: true, userBId: true },
      }),
    ]);

    const friendIds = new Set(
      friendships.map((row) => (row.userAId === askerId ? row.userBId : row.userAId)),
    );
    const allowed = readableLastSeen(
      askerId,
      toVisibility(asker?.lastSeenVisibility),
      rows.map((row) => ({ id: row.id, visibility: toVisibility(row.lastSeenVisibility) })),
      friendIds,
    );

    const stored = new Map(rows.map((row) => [row.id, row.lastSeenAt?.getTime() ?? 0]));
    const seen = new Map<string, string>();
    userIds.forEach((userId, index) => {
      if (!allowed.has(userId)) return;
      const at = Math.max(Number(live[index] ?? 0), stored.get(userId) ?? 0);
      if (at > 0) seen.set(userId, new Date(at).toISOString());
    });
    return seen;
  }

  /**
   * The status a user chose. It outlives the connection on purpose: someone who
   * set themselves invisible expects to still be invisible after a restart.
   */
  async setStatus(userId: string, status: ActiveStatus): Promise<void> {
    await this.redis.hset(STATUS_KEY, userId, status);
  }

  async statusOf(userId: string): Promise<ActiveStatus> {
    const stored = await this.redis.hget(STATUS_KEY, userId);
    return isActiveStatus(stored) ? stored : 'online';
  }

  /**
   * What everyone else may see. An invisible user is reported `offline`, and
   * that resolution happens here rather than in the client, because a status
   * that only the UI hides is not invisible.
   */
  async visibleStatusOf(userId: string): Promise<PresenceStatus> {
    const status = await this.statusOf(userId);
    return status === 'invisible' ? 'offline' : status;
  }

  /**
   * One account's status as everybody else sees it, connection included.
   *
   * `visibleStatusOf` answers only what was *chosen*, and a chosen status
   * outlives the connection - so somebody who has never been seen, and
   * somebody who signed off a week ago, both read back `online` from it. This
   * is the one that asks whether they are actually here, and it is what a
   * `presence.query` needs: the question is being asked precisely about people
   * who are probably not.
   */
  async stateOf(userId: string): Promise<PresenceStatus> {
    const score = await this.redis.zscore(ONLINE_KEY, userId);
    if (score === null || Number(score) < Date.now() - STALE_AFTER_MS) return 'offline';
    return this.visibleStatusOf(userId);
  }

  async onlineUsers(): Promise<PresenceState[]> {
    const cutoff = Date.now() - STALE_AFTER_MS;
    // Drop stale entries as a side effect of reading, so no sweeper job is
    // needed for a set this small.
    await this.redis.zremrangebyscore(ONLINE_KEY, '-inf', cutoff);
    const ids = await this.redis.zrange(ONLINE_KEY, 0, -1);

    const states = await Promise.all(
      ids.map(async (userId) => ({ userId, status: await this.visibleStatusOf(userId) })),
    );
    // An invisible user resolves to `offline`, which is the same as not being
    // in the list at all - so leave them out rather than sending a contradiction.
    return states.filter((state) => state.status !== 'offline');
  }

  /**
   * Writes a channel's roster to exactly what `call-service` says it is.
   *
   * A replace rather than an add or a remove, because the authority sends the
   * whole roster: anything left in Redis that is not in it is a client that
   * said it joined and never did, or one that died without saying goodbye.
   *
   * And it expires, for the same reason `presence:online` does. A roster is
   * only ever replaced per channel, so a channel `call-service` never mentions
   * again keeps whatever it last said - which after that service restarts
   * mid-call is a room full of people who left. `call-service` re-announces
   * every live call on its heartbeat, three times inside this window, so a
   * roster that stops being refreshed is a roster nothing is behind any more.
   */
  async replaceVoice(channelId: string, userIds: string[]): Promise<VoiceState> {
    const key = VOICE_KEY(channelId);
    if (userIds.length === 0) {
      await this.redis.del(key);
      await this.redis.srem(VOICE_INDEX, channelId);
      return { channelId, userIds: [] };
    }

    // Delete and rewrite in one round trip, so a reader never sees the empty
    // moment in between.
    await this.redis
      .multi()
      .del(key)
      .sadd(key, ...userIds)
      .pexpire(key, STALE_AFTER_MS)
      .sadd(VOICE_INDEX, channelId)
      .exec();
    return { channelId, userIds };
  }

  /**
   * Rosters nothing has refreshed, dropped from the index and named.
   *
   * The key expires by itself; this is what notices, so the people looking at
   * that channel can be told rather than left on a stale list until they
   * reconnect. The gateway calls it on its heartbeat.
   */
  async expireVoice(): Promise<string[]> {
    const channels = await this.redis.smembers(VOICE_INDEX);
    const lifetimes = await Promise.all(
      channels.map((channelId) => this.redis.pttl(VOICE_KEY(channelId))),
    );

    const gone: string[] = [];
    await Promise.all(
      channels.map(async (channelId, index) => {
        switch (voiceLifetime(lifetimes[index] ?? -2)) {
          case 'gone':
            gone.push(channelId);
            return;
          // A roster written before rosters had a lifetime. Put on the same
          // clock rather than deleted outright, so a call that is genuinely
          // running is re-announced onto it instead of blinking empty.
          case 'adopt':
            await this.redis.pexpire(VOICE_KEY(channelId), STALE_AFTER_MS);
            return;
          case 'live':
            return;
        }
      }),
    );

    if (gone.length > 0) await this.redis.srem(VOICE_INDEX, ...gone);
    return gone;
  }

  // There were `joinVoice`, `leaveVoice` and `voiceChannelsOf` here, one per
  // thing a client claimed about itself. They are gone with the claim: a roster
  // arrives whole from call-service, so there is nothing to add, nothing to
  // remove, and no need to ask which channels somebody is in so that a
  // disconnect can guess its way out of them.

  /**
   * Who has this channel on screen, scored by when they last said so.
   *
   * The same shape as `presence:online` and for the same reason: a client that
   * dies without saying goodbye has to age out rather than suppress that
   * channel's notifications forever. The gateway clears the entry on a clean
   * disconnect, the score handles the unclean one, and the TTL on the key
   * itself means a channel nobody is reading leaves nothing behind in Redis.
   *
   * Per user, not per device. If any of somebody's windows is looking at the
   * channel, none of their devices needs to be woken for it.
   */
  async focus(channelId: string, userId: string): Promise<void> {
    const key = FOCUS_KEY(channelId);
    await this.redis
      .multi()
      .zadd(key, Date.now(), userId)
      .pexpire(key, STALE_AFTER_MS)
      .exec();
  }

  async blur(channelId: string, userId: string): Promise<void> {
    await this.redis.zrem(FOCUS_KEY(channelId), userId);
  }

  /**
   * Which of [userIds] are reading [channelId] right now.
   *
   * Stale entries are dropped as a side effect of the read, exactly as
   * `onlineUsers` does - there is no sweeper for either.
   */
  async focusedAmong(channelId: string, userIds: string[]): Promise<string[]> {
    if (userIds.length === 0) return [];
    const key = FOCUS_KEY(channelId);
    await this.redis.zremrangebyscore(key, '-inf', Date.now() - STALE_AFTER_MS);
    const reading = new Set(await this.redis.zrange(key, 0, -1));
    return userIds.filter((userId) => reading.has(userId));
  }

  async voiceState(channelId: string): Promise<VoiceState> {
    return { channelId, userIds: await this.redis.smembers(VOICE_KEY(channelId)) };
  }

  async allVoiceStates(): Promise<VoiceState[]> {
    const channels = await this.redis.smembers(VOICE_INDEX);
    const states = await Promise.all(channels.map((channelId) => this.voiceState(channelId)));
    // An expired roster leaves its channel in the index until the sweep gets to
    // it. Sending it as an empty room would be harmless; sending nothing is
    // what a client already understands as "nobody is in there".
    return states.filter((state) => state.userIds.length > 0);
  }

  async onModuleDestroy(): Promise<void> {
    await this.redis.quit();
  }
}

export function isActiveStatus(value: string | null): value is ActiveStatus {
  return value !== null && (ACTIVE_STATUSES as string[]).includes(value);
}

/** Run with `tsx src/voice-lifetime.check.ts`. */
import assert from 'node:assert/strict';
import { voiceLifetime } from './voice-lifetime';

// Redis: -2 is "no such key", -1 is "no expiry set". Swapping the two would
// empty every call that is actually running.
assert.equal(voiceLifetime(-2), 'gone');
assert.equal(voiceLifetime(-1), 'adopt');

// Anything counting down is a roster something is still behind.
assert.equal(voiceLifetime(90_000), 'live');
assert.equal(voiceLifetime(1), 'live');
// Zero comes back for a key in the millisecond before it goes; the next sweep
// reads -2 and clears it, which is soon enough and never early.
assert.equal(voiceLifetime(0), 'live');

console.log('voice-lifetime.check.ts ok');

/**
 * What a voice roster's remaining lifetime means.
 *
 * Redis answers `PTTL` with three different kinds of thing and only one of them
 * is a duration, so the reading is written out here rather than as three magic
 * numbers inside a loop - and checked, because getting -1 and -2 the wrong way
 * round deletes every live call instead of every dead one.
 */
export type VoiceLifetime =
  /** The key is gone: nothing refreshed it, so nobody is in that call. */
  | 'gone'
  /** No expiry at all - a roster written before rosters had one. */
  | 'adopt'
  /** Counting down, and being refreshed. Leave it alone. */
  | 'live';

export function voiceLifetime(pttlMs: number): VoiceLifetime {
  if (pttlMs === -2) return 'gone';
  if (pttlMs === -1) return 'adopt';
  return 'live';
}

