import { createHealthController } from '@betweenus/nest-common';
import { RemoteController } from './modules/remote/remote.controller';
import { RemoteService } from './modules/remote/remote.service';
import { RemoteGateway } from './remote.gateway';
import { RetentionSweeper } from './modules/remote/retention';

const SERVICE_NAME = 'remote-gateway';

@Module({
  controllers: [RemoteController, createHealthController(SERVICE_NAME, pingDatabase)],
  providers: [
    RemoteService,
    RemoteGateway,
    RetentionSweeper,
    {
      provide: EventBus,
      useFactory: () => new EventBus(envOr('REDIS_URL', 'redis://localhost:6379'), SERVICE_NAME),
    },
    {
      provide: Logger,
      useFactory: (): Logger => createLogger(SERVICE_NAME, envOr('LOG_LEVEL', 'info') as never),
    },
  ],
})
export class AppModule {}

import 'reflect-metadata';
import type { Server as HttpServer } from 'node:http';
import { bootstrapService } from '@betweenus/nest-common';
import { AppModule } from './app.module';
import { RemoteGateway } from './remote.gateway';

async function start(): Promise<void> {
  const app = await bootstrapService({
    service: 'remote-gateway',
    module: AppModule,
    portVar: 'REMOTE_GATEWAY_PORT',
    defaultPort: 3008,
  });

  // /ws/remote shares the HTTP listener with /api/v1/remote and /health, so the
  // whole service is one port and one Nginx upstream.
  const gateway = app.get(RemoteGateway);
  gateway.attach(app.getHttpServer() as HttpServer);
}

void start();

import {
  ArrayMaxSize,
  IsArray,
  IsISO8601,
  IsOptional,
  IsString,
  IsUUID,
  Length,
} from 'class-validator';
import type {
  EnrolMachineRequest,
  RemotePermission,
  SetRemoteGrantRequest,
  StartRemoteSessionRequest,
} from '@betweenus/shared-types';

export class EnrolMachineDto implements EnrolMachineRequest {
  @IsString()
  @Length(1, 64)
  name!: string;

  @IsString()
  @Length(1, 32)
  platform!: string;

  /** Present when this machine has enrolled before; it rotates the token. */
  @IsOptional()
  @IsUUID()
  machineId?: string;
}

export class RenameMachineDto {
  @IsString()
  @Length(1, 64)
  name!: string;
}

export class SetRemoteGrantDto implements SetRemoteGrantRequest {
  @IsUUID()
  userId!: string;

  /** Empty revokes. Names are validated against the vocabulary in the service. */
  @IsArray()
  @ArrayMaxSize(6)
  @IsString({ each: true })
  permissions!: RemotePermission[];

  @IsOptional()
  @IsISO8601()
  expiresAt?: string | null;
}

export class StartRemoteSessionDto implements StartRemoteSessionRequest {
  @IsUUID()
  machineId!: string;
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Headers,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  EnrolMachineResponse,
  RemoteAuditEntry,
  RemoteGrantSummary,
  RemoteMachineSummary,
  RemoteSessionResponse,
} from '@betweenus/shared-types';
import { RemoteService } from './remote.service';
import {
  EnrolMachineDto,
  RenameMachineDto,
  SetRemoteGrantDto,
  StartRemoteSessionDto,
} from './dto';

/**
 * `/api/v1/remote`. Thin: every rule lives in RemoteService, and the socket
 * gateway is what carries a live session.
 */
@Controller('remote')
@UseGuards(JwtAuthGuard)
export class RemoteController {
  constructor(private readonly remote: RemoteService) {}

  @Get('machines')
  machines(@CurrentUser() user: AuthenticatedUser): Promise<RemoteMachineSummary[]> {
    return this.remote.machines(user.id);
  }

  /** The agent calls this once, signed in as the person who owns the machine. */
  @Post('machines')
  enrol(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: EnrolMachineDto,
  ): Promise<EnrolMachineResponse> {
    return this.remote.enrol(user.id, dto);
  }

  @Patch('machines/:machineId')
  rename(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
    @Body() dto: RenameMachineDto,
  ): Promise<RemoteMachineSummary> {
    return this.remote.rename(user.id, machineId, dto.name);
  }

  @Delete('machines/:machineId')
  @HttpCode(204)
  remove(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
  ): Promise<void> {
    return this.remote.remove(user.id, machineId);
  }

  @Get('machines/:machineId/grants')
  grants(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
  ): Promise<RemoteGrantSummary[]> {
    return this.remote.grants(user.id, machineId);
  }

  /** One call sets or revokes; an empty permission list is the revocation. */
  @Put('machines/:machineId/grants')
  setGrant(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
    @Body() dto: SetRemoteGrantDto,
  ): Promise<RemoteGrantSummary[]> {
    return this.remote.setGrant(user.id, machineId, dto);
  }

  @Get('machines/:machineId/audit')
  audit(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
    @Query('limit') limit?: string,
  ): Promise<RemoteAuditEntry[]> {
    // `?limit=abc` is NaN, and NaN survives the service's clamp all the way to
    // the query. Anything that is not a number is no answer at all.
    const parsed = limit === undefined ? undefined : Number(limit);
    return this.remote.audit(
      user.id,
      machineId,
      parsed !== undefined && Number.isFinite(parsed) ? parsed : undefined,
    );
  }

  @Post('sessions')
  start(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: StartRemoteSessionDto,
  ): Promise<RemoteSessionResponse> {
    // No `Host` header is read here any more. It existed so the reply could
    // refuse to name a media server this caller could not dial; the reply names
    // no server at all now, so there is nothing about where they are that could
    // make it wrong.
    return this.remote.startSession(user, dto.machineId);
  }

  /**
   * Ending over HTTP as well as over the socket: a window that was closed
   * without a clean disconnect still has to be able to say the session is over.
   */
  @Delete('sessions/:sessionId')
  @HttpCode(204)
  async end(
    @CurrentUser() user: AuthenticatedUser,
    @Param('sessionId', ParseUUIDPipe) sessionId: string,
  ): Promise<void> {
    await this.remote.endSessionFor(user.id, sessionId, 'controller');
  }
}

/**
 * Everything a remote session needs before pixels move: enrolment, grants,
 * session lifecycle and the audit trail.
 *
 * The service decides *who may do what to which machine*. It never sees a
 * frame: the screen goes directly from the agent to the controller over a peer
 * connection, exactly the way a call does, and the gateway's part is relaying
 * the offer and answer that set it up.
 */
import { createHash, randomBytes } from 'node:crypto';
import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
  ServiceUnavailableException,
} from '@nestjs/common';
import { iceServers } from '@betweenus/config';
import {
  asRemotePermissions,
  prisma,
  recordRemoteAudit,
  resolveRemoteAccess,
  type RemoteAccess,
} from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { PERMISSIONS, type RemotePermission } from '@betweenus/permissions';
import type {
  EnrolMachineResponse,
  IceServer,
  RemoteAuditEntry,
  RemoteGrantSummary,
  RemoteMachineSummary,
  RemoteSessionResponse,
} from '@betweenus/shared-types';

/**
 * Reported by the ws gateway, which is the only thing that knows who is dialled
 * in - and, since the answer is shared through Redis, dialled in to any replica
 * rather than only to this one. Asynchronous for that reason.
 */
export interface AgentPresence {
  isOnline(machineId: string): Promise<boolean>;
  /** The subset of these machines with an agent connected. One round trip. */
  onlineAmong(machineIds: string[]): Promise<Set<string>>;
}

@Injectable()
export class RemoteService {
  constructor(private readonly events: EventBus) {}

  /**
   * Set by the WebSocket gateway at boot. Online-ness is a property of a live
   * socket, not of a column, so the HTTP side asks rather than storing it.
   */
  private presence: AgentPresence = {
    isOnline: async () => false,
    onlineAmong: async () => new Set(),
  };

  setPresence(presence: AgentPresence): void {
    this.presence = presence;
  }

  // --- Enrolment ------------------------------------------------------------

  /**
   * Enrols this machine, or rotates the token of one already enrolled.
   *
   * The token is returned once and stored hashed, the way a password is. An
   * agent that loses it enrols again, which is also how a stolen token is
   * revoked: the old one stops matching.
   */
  async enrol(
    userId: string,
    body: { name: string; platform: string; machineId?: string },
  ): Promise<EnrolMachineResponse> {
    const agentToken = randomBytes(32).toString('base64url');
    const agentTokenHash = hashToken(agentToken);

    if (body.machineId) {
      const existing = await prisma.remoteMachine.findUnique({
        where: { id: body.machineId },
        select: { id: true, ownerId: true },
      });
      // Someone else's machine id must not be re-enrolled into this account:
      // that would be a takeover with no more than a guessed uuid.
      if (!existing || existing.ownerId !== userId) {
        throw new NotFoundException({ code: 'MACHINE_NOT_FOUND', message: 'Machine not found' });
      }
    }

    const machine = body.machineId
      ? await prisma.remoteMachine.update({
          where: { id: body.machineId },
          data: { name: body.name, platform: body.platform, agentTokenHash },
        })
      : await prisma.remoteMachine.create({
          data: { ownerId: userId, name: body.name, platform: body.platform, agentTokenHash },
        });

    await recordRemoteAudit({
      machineId: machine.id,
      actorId: userId,
      action: body.machineId ? 'machine.reenrolled' : 'machine.enrolled',
      detail: { name: machine.name, platform: machine.platform },
    });

    return {
      machine: await this.summarise(machine.id, userId),
      agentToken,
    };
  }

  /** Machines this user owns, plus the ones they hold a live grant on. */
  async machines(userId: string): Promise<RemoteMachineSummary[]> {
    const now = new Date();
    const rows = await prisma.remoteMachine.findMany({
      where: {
        OR: [
          { ownerId: userId },
          {
            grants: {
              some: {
                userId,
                OR: [{ expiresAt: null }, { expiresAt: { gt: now } }],
              },
            },
          },
        ],
      },
      include: {
        owner: { select: { username: true } },
        grants: { where: { userId }, select: { permissions: true, expiresAt: true } },
      },
      orderBy: { name: 'asc' },
    });

    // One lookup for the whole list rather than one per machine.
    const online = await this.presence.onlineAmong(rows.map((row) => row.id));

    return rows
      .map((row) => {
        const isOwner = row.ownerId === userId;
        const grant = row.grants[0];
        const permissions = isOwner
          ? [...REMOTE_ALL]
          : asRemotePermissions(grant?.permissions ?? []);
        return {
          id: row.id,
          name: row.name,
          platform: row.platform,
          ownerId: row.ownerId,
          ownerUsername: row.owner.username,
          online: online.has(row.id),
          lastSeenAt: row.lastSeenAt?.toISOString() ?? null,
          permissions,
          expiresAt: isOwner ? null : (grant?.expiresAt?.toISOString() ?? null),
          createdAt: row.createdAt.toISOString(),
        };
      })
      // A grant emptied rather than deleted leaves a row that grants nothing;
      // it should not put a machine in somebody's list.
      .filter((machine) => machine.permissions.length > 0);
  }

  async rename(userId: string, machineId: string, name: string): Promise<RemoteMachineSummary> {
    await this.requireAdmin(userId, machineId);
    await prisma.remoteMachine.update({ where: { id: machineId }, data: { name } });
    await recordRemoteAudit({ machineId, actorId: userId, action: 'machine.renamed', detail: { name } });
    return this.summarise(machineId, userId);
  }

  /** Owner only: unenrolling is not something a delegated administrator does. */
  async remove(userId: string, machineId: string): Promise<void> {
    const access = await this.requireAccess(userId, machineId);
    if (!access.isOwner) {
      throw new ForbiddenException({
        code: 'NOT_MACHINE_OWNER',
        message: 'Only the machine owner can remove it',
      });
    }
    await prisma.remoteMachine.delete({ where: { id: machineId } });
  }

  // --- Grants ---------------------------------------------------------------

  async grants(userId: string, machineId: string): Promise<RemoteGrantSummary[]> {
    await this.requireAdmin(userId, machineId);
    const rows = await prisma.remoteGrant.findMany({
      where: { machineId },
      include: {
        user: { select: { id: true, username: true, displayName: true, avatarUrl: true } },
      },
      orderBy: { createdAt: 'asc' },
    });

    return rows.map((row) => ({
      userId: row.userId,
      username: row.user.username,
      displayName: row.user.displayName,
      avatarUrl: row.user.avatarUrl,
      permissions: asRemotePermissions(row.permissions),
      expiresAt: row.expiresAt?.toISOString() ?? null,
    }));
  }

  /**
   * Replaces one person's access wholesale. An empty permission list revokes,
   * which is why there is no separate delete: one call, one row, one meaning.
   *
   * A revocation ends whatever session that person currently holds - the
   * gateway is told through `onGrantRevoked`, wired in the module.
   */
  async setGrant(
    userId: string,
    machineId: string,
    body: { userId: string; permissions: string[]; expiresAt?: string | null },
  ): Promise<RemoteGrantSummary[]> {
    const access = await this.requireAdmin(userId, machineId);

    if (body.userId === access.ownerId) {
      throw new ConflictException({
        code: 'OWNER_GRANT',
        message: 'The owner already has every permission on this machine',
      });
    }

    const target = await prisma.user.findUnique({
      where: { id: body.userId },
      select: { id: true },
    });
    if (!target) {
      throw new NotFoundException({ code: 'USER_NOT_FOUND', message: 'No such user' });
    }

    const permissions = asRemotePermissions(body.permissions);
    // Unknown names are dropped rather than stored, so a client cannot invent a
    // permission and have it sit in the database looking official.
    if (permissions.length !== body.permissions.length && body.permissions.length > 0) {
      throw new BadRequestException({
        code: 'UNKNOWN_PERMISSION',
        message: 'That is not a remote permission',
      });
    }

    // Control without view is a session that can type into a screen nobody is
    // watching. Every other permission is additive on top of viewing.
    if (permissions.length > 0 && !permissions.includes(PERMISSIONS.REMOTE_VIEW)) {
      permissions.unshift(PERMISSIONS.REMOTE_VIEW);
    }

    const expiresAt = parseExpiry(body.expiresAt);

    await prisma.remoteGrant.upsert({
      where: { machineId_userId: { machineId, userId: body.userId } },
      create: {
        machineId,
        userId: body.userId,
        permissions,
        expiresAt,
        grantedById: userId,
      },
      update: { permissions, expiresAt, grantedById: userId },
    });

    await recordRemoteAudit({
      machineId,
      actorId: userId,
      action: 'permission.changed',
      detail: { userId: body.userId, permissions, expiresAt: expiresAt?.toISOString() ?? null },
    });

    if (permissions.length === 0) await this.onGrantRevoked(machineId, body.userId);

    return this.grants(userId, machineId);
  }

  /** Set by the module so a revoked grant can end a live session. */
  onGrantRevoked: (machineId: string, userId: string) => Promise<void> = async () => undefined;

  // --- Sessions -------------------------------------------------------------

  /**
   * Opens a session. The permissions are read once, here, and carried on the
   * session row: the relay enforces what was granted at the start, and a change
   * mid-session ends it rather than quietly widening or narrowing what the
   * other end is already doing.
   */
  async startSession(
    user: { id: string; username: string },
    machineId: string,
  ): Promise<RemoteSessionResponse> {
    const access = await this.requireAccess(user.id, machineId);
    if (!access.permissions.includes(PERMISSIONS.REMOTE_VIEW)) {
      await recordRemoteAudit({
        machineId,
        actorId: user.id,
        action: 'session.refused',
        detail: { reason: 'no-view-permission' },
      });
      throw new ForbiddenException({
        code: 'REMOTE_VIEW_REQUIRED',
        message: 'You cannot view this machine',
      });
    }

    if (!(await this.presence.isOnline(machineId))) {
      throw new ServiceUnavailableException({
        code: 'AGENT_OFFLINE',
        message: 'That machine is not connected',
      });
    }

    const machine = await prisma.remoteMachine.findUniqueOrThrow({
      where: { id: machineId },
      select: { name: true, ownerId: true },
    });

    const session = await prisma.remoteSession.create({
      data: { machineId, userId: user.id, permissions: access.permissions },
    });

    await recordRemoteAudit({
      machineId,
      actorId: user.id,
      sessionId: session.id,
      action: 'session.started',
      detail: { permissions: access.permissions },
    });

    // Somebody is on this machine, and the person who owns it is very likely
    // not sitting at it - that is what remote access is for. The audit trail
    // records this either way; the push is what makes it something anybody
    // finds out about at the time rather than afterwards.
    await this.announceSession(session.id, machineId, machine.name, machine.ownerId, user, 'started');

    return {
      sessionId: session.id,
      machineId,
      machineName: machine.name,
      permissions: access.permissions,
      iceServers: await iceServers(),
    };
  }

  /**
   * How the agent should try to reach the controller.
   *
   * The same list the controller got, and for the same reason it is a list
   * rather than an address: neither end is told where the other is. They
   * exchange candidates and ICE settles it.
   */
  async agentIceServers(): Promise<IceServer[]> {
    return iceServers();
  }

  async endSession(sessionId: string, reason: string): Promise<void> {
    const session = await prisma.remoteSession.findUnique({
      where: { id: sessionId },
      select: { id: true, machineId: true, userId: true, endedAt: true },
    });
    if (!session || session.endedAt) return;

    await prisma.remoteSession.update({
      where: { id: sessionId },
      data: { endedAt: new Date(), endedReason: reason },
    });
    await recordRemoteAudit({
      machineId: session.machineId,
      actorId: session.userId,
      sessionId,
      action: 'session.ended',
      detail: { reason },
    });

    const machine = await prisma.remoteMachine.findUnique({
      where: { id: session.machineId },
      select: { name: true, ownerId: true },
    });
    const actor = await prisma.user.findUnique({
      where: { id: session.userId },
      select: { username: true, displayName: true },
    });
    if (machine && actor) {
      await this.announceSession(
        sessionId,
        session.machineId,
        machine.name,
        machine.ownerId,
        { id: session.userId, username: actor.displayName || actor.username },
        'ended',
      );
    }
  }

  /**
   * Tells the bus a session started or ended.
   *
   * Best effort, and deliberately after the row and the audit entry: a Redis
   * that is unreachable must not be able to stop somebody reaching their own
   * machine. The trail is the record; this is the notification.
   */
  private async announceSession(
    sessionId: string,
    machineId: string,
    machineName: string,
    ownerId: string,
    actor: { id: string; username: string },
    state: 'started' | 'ended',
  ): Promise<void> {
    try {
      await this.events.publish(EVENTS.REMOTE_SESSION, {
        sessionId,
        machineId,
        machineName,
        ownerId,
        actorId: actor.id,
        actorName: actor.username,
        state,
      });
    } catch {
      // A session that happened and was not announced is still a session, and
      // `remote_audit` has it.
    }
  }

  /**
   * Ends a session on somebody's behalf, checking they are entitled to: the
   * controller holding it, or whoever administers the machine. A stranger with
   * a session id gets the same 404 they would get for a machine id.
   */
  async endSessionFor(userId: string, sessionId: string, reason: string): Promise<void> {
    const session = await prisma.remoteSession.findUnique({
      where: { id: sessionId },
      select: { id: true, machineId: true, userId: true, endedAt: true },
    });
    if (!session) {
      throw new NotFoundException({ code: 'SESSION_NOT_FOUND', message: 'Session not found' });
    }

    if (session.userId !== userId) {
      const access = await resolveRemoteAccess(userId, session.machineId);
      const mayAdminister =
        access !== null && (access.isOwner || access.permissions.includes(PERMISSIONS.REMOTE_ADMIN));
      if (!mayAdminister) {
        throw new NotFoundException({ code: 'SESSION_NOT_FOUND', message: 'Session not found' });
      }
    }

    if (session.endedAt) return;
    await this.endSession(sessionId, reason);
    await this.onSessionEnded(sessionId, session.machineId, reason);
  }

  /**
   * Set by the module so ending over HTTP also drops the live sockets. The
   * machine id travels with it because the two sockets may be on two different
   * instances, and the one that hears this may hold neither of them.
   */
  onSessionEnded: (sessionId: string, machineId: string, reason: string) => Promise<void> =
    async () => undefined;

  /** The machine's own history. Owner or a delegated administrator only. */
  async audit(userId: string, machineId: string, limit = 100): Promise<RemoteAuditEntry[]> {
    await this.requireAdmin(userId, machineId);
    const rows = await prisma.remoteAudit.findMany({
      where: { machineId },
      include: { actor: { select: { username: true } } },
      orderBy: { createdAt: 'desc' },
      take: Math.min(Math.max(limit, 1), 200),
    });

    return rows.map((row) => ({
      id: row.id,
      action: row.action,
      actorId: row.actorId,
      actorUsername: row.actor?.username ?? null,
      sessionId: row.sessionId,
      detail: (row.detail ?? null) as Record<string, unknown> | null,
      createdAt: row.createdAt.toISOString(),
    }));
  }

  // --- Agent credentials ----------------------------------------------------

  /**
   * Resolves the token an agent presents on its socket.
   *
   * One indexed lookup on the hash. It used to read every machine's hash and
   * compare them in constant time, which was the right instinct applied to the
   * wrong value: the thing being compared is a SHA-256 of a 256-bit random
   * token, so it has no structure for a timing signal to leak and no
   * near-misses for one to walk towards. What that cost was a full table read
   * on every agent reconnect - and reconnects are what an agent does all day.
   */
  async machineForAgentToken(token: string): Promise<{ id: string; ownerId: string } | null> {
    if (!token) return null;
    return prisma.remoteMachine.findUnique({
      where: { agentTokenHash: hashToken(token) },
      select: { id: true, ownerId: true },
    });
  }

  async touchMachine(machineId: string): Promise<void> {
    await prisma.remoteMachine
      .update({ where: { id: machineId }, data: { lastSeenAt: new Date() } })
      .catch(() => undefined);
  }

  // --- Shared -------------------------------------------------------------

  private async requireAccess(userId: string, machineId: string): Promise<RemoteAccess> {
    const access = await resolveRemoteAccess(userId, machineId);
    // 404 rather than 403: a stranger must not learn the machine exists.
    if (!access) {
      throw new NotFoundException({ code: 'MACHINE_NOT_FOUND', message: 'Machine not found' });
    }
    return access;
  }

  private async requireAdmin(userId: string, machineId: string): Promise<RemoteAccess> {
    const access = await this.requireAccess(userId, machineId);
    if (!access.isOwner && !access.permissions.includes(PERMISSIONS.REMOTE_ADMIN)) {
      throw new ForbiddenException({
        code: 'REMOTE_ADMIN_REQUIRED',
        message: 'You cannot administer this machine',
      });
    }
    return access;
  }

  private async summarise(machineId: string, userId: string): Promise<RemoteMachineSummary> {
    const list = await this.machines(userId);
    const found = list.find((machine) => machine.id === machineId);
    if (!found) {
      throw new NotFoundException({ code: 'MACHINE_NOT_FOUND', message: 'Machine not found' });
    }
    return found;
  }

}

const REMOTE_ALL: RemotePermission[] = [
  PERMISSIONS.REMOTE_VIEW,
  PERMISSIONS.REMOTE_CONTROL,
  PERMISSIONS.REMOTE_FILE_TRANSFER,
  PERMISSIONS.REMOTE_CLIPBOARD,
  PERMISSIONS.REMOTE_AUDIO,
  PERMISSIONS.REMOTE_ADMIN,
];

// There was a `roomName` and a `livekitUrl` here, and the second one threw
// `LIVEKIT_UNREACHABLE_URL` when a deployment advertised a media server address
// only the server itself could reach. Both are gone with the media server: no
// client is told where to connect any more, so there is no address that can be
// wrong for it.

function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('hex');
}

function parseExpiry(value: string | null | undefined): Date | null {
  if (value === null || value === undefined || value === '') return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new BadRequestException({ code: 'BAD_EXPIRY', message: 'That is not a date' });
  }
  if (date.getTime() <= Date.now()) {
    throw new BadRequestException({
      code: 'EXPIRY_IN_PAST',
      message: 'An expiry in the past would grant nothing',
    });
  }
  return date;
}

/**
 * Retention for remote sessions and their audit trail.
 *
 * Both tables only ever grew. A session row is finished the moment it ends and
 * is never read again except through the machine's history; an audit row is the
 * history. Neither is dangerous at the scale one deployment runs at, and both
 * are the sort of thing that is discovered years later as the reason a table
 * has forty million rows in it.
 *
 * The audit trail is the point of the feature, so the default keeps it for a
 * year - long enough to answer "who was on that machine in March" - while
 * finished sessions, which say nothing the audit rows do not, go after thirty
 * days. Both are environment variables because the answer is a policy, not a
 * fact, and some deployments have to keep records for longer than others.
 *
 * ponytail: a timer in the process, not a scheduler. Every replica runs it and
 * they will overlap harmlessly - deleting rows that are already gone deletes
 * nothing. A real job runner is the upgrade if that ever stops being true.
 */
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { envNumber } from '@betweenus/config';
import { prisma } from '@betweenus/database';
import { Logger } from '@betweenus/logger';

const DAY_MS = 24 * 60 * 60 * 1000;

/** How often the sweep runs once the service is up. */
const INTERVAL_MS = DAY_MS;

/** Waited out before the first sweep, so a boot is not also a delete storm. */
const FIRST_RUN_DELAY_MS = 60_000;

export interface RetentionPolicy {
  sessionDays: number;
  auditDays: number;
}

export function retentionPolicy(): RetentionPolicy {
  return {
    sessionDays: envNumber('REMOTE_SESSION_RETENTION_DAYS', 30),
    auditDays: envNumber('REMOTE_AUDIT_RETENTION_DAYS', 365),
  };
}

/**
 * Deletes what has aged out. Returns what it removed, for the log line and for
 * anything that wants to assert on it.
 *
 * Sessions are only swept once they have *ended*: a row with no `endedAt` is a
 * session that is either running or was orphaned by a crash, and deleting the
 * second kind would take the audit rows pointing at it with it.
 */
export async function sweepRemoteHistory(
  policy: RetentionPolicy = retentionPolicy(),
  now: Date = new Date(),
): Promise<{ sessions: number; audit: number }> {
  const sessionsBefore = new Date(now.getTime() - policy.sessionDays * DAY_MS);
  const auditBefore = new Date(now.getTime() - policy.auditDays * DAY_MS);

  // Audit first. A session's rows cascade when the session goes, so sweeping
  // the other way round would delete audit rows that are still inside their own
  // retention window - the trail is the record, and it outlives the session.
  const audit = await prisma.remoteAudit.deleteMany({ where: { createdAt: { lt: auditBefore } } });
  const sessions = await prisma.remoteSession.deleteMany({
    where: { endedAt: { not: null, lt: sessionsBefore } },
  });

  return { sessions: sessions.count, audit: audit.count };
}

@Injectable()
export class RetentionSweeper implements OnModuleInit, OnModuleDestroy {
  private timer: NodeJS.Timeout | null = null;
  private first: NodeJS.Timeout | null = null;

  constructor(private readonly logger: Logger) {}

  onModuleInit(): void {
    const policy = retentionPolicy();
    this.first = setTimeout(() => {
      void this.run(policy);
      this.timer = setInterval(() => void this.run(policy), INTERVAL_MS);
      this.timer.unref?.();
    }, FIRST_RUN_DELAY_MS);
    this.first.unref?.();
  }

  private async run(policy: RetentionPolicy): Promise<void> {
    try {
      const removed = await sweepRemoteHistory(policy);
      if (removed.sessions === 0 && removed.audit === 0) return;
      this.logger.info('Swept remote history', { ...removed, ...policy });
    } catch (error) {
      // A sweep that cannot run is not an outage. It runs again tomorrow.
      this.logger.warn('Could not sweep remote history', { reason: String(error) });
    }
  }

  onModuleDestroy(): void {
    if (this.first) clearTimeout(this.first);
    if (this.timer) clearInterval(this.timer);
  }
}

/**
 * `/ws/remote`: the relay between a controller and an agent.
 *
 * Two kinds of socket connect here and they authenticate differently. An agent
 * presents the token it was given at enrolment (`?agent=`); a controller
 * presents the usual access token and the session it was issued (`?sessionId=`).
 * Neither ever learns the other's address - the agent dialled out, the
 * controller dialled in, and this process is the only thing that sees both.
 *
 * Every input event is checked against the permissions frozen on the session
 * row, here, on the server. The desktop client hides what it cannot do, but
 * hiding is not enforcement.
 *
 * The two halves of a session need not be on the same instance: the agent
 * dialled out hours ago and the controller dialled in just now, through a load
 * balancer with no idea they belong together. So every message goes through
 * `toAgent` / `toController`, which deliver to a local socket when this instance
 * holds it and publish through `RemoteRelay` when it does not. Nothing in this
 * file may reach into `agents` or `controllers` directly to send.
 *
 * The one consequence worth naming: a controller's live permissions cannot be
 * read from memory when the controller is somebody else's socket. They are read
 * from the session row instead, which is the authoritative copy anyway - the
 * in-memory list is a cache of it, kept in step by `control.changed`.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import type { IncomingMessage, Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { envOr } from '@betweenus/config';
import { asRemotePermissions, prisma, recordRemoteAudit } from '@betweenus/database';
import { EventBus } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import { PERMISSIONS, type RemotePermission } from '@betweenus/permissions';
import {
  SIGNAL_MAX_PAYLOAD,
  authenticateHandshake,
  dropRevokedSockets,
} from '@betweenus/websocket';
import {
  REMOTE_TRANSFER_MAX_BYTES,
  type AgentRemoteEvent,
  type ClientRemoteEvent,
  type ServerRemoteEvent,
} from '@betweenus/shared-types';
import { RemoteService } from './modules/remote/remote.service';
import { RemoteRelay, type RelayTarget } from './remote.relay';

const HEARTBEAT_INTERVAL_MS = 30_000;

/** What a controller's event needs before it is relayed to the machine. */
const REQUIRED_PERMISSION: Record<string, RemotePermission> = {
  'input.mouse': PERMISSIONS.REMOTE_CONTROL,
  'input.key': PERMISSIONS.REMOTE_CONTROL,
  'clipboard.set': PERMISSIONS.REMOTE_CLIPBOARD,
  // `file.offer` is deliberately not here. It needs `REMOTE_FILE_TRANSFER`
  // like the rest, but it is also audited and size-checked, so it is handled
  // before this table is reached - and an entry here as well would be dead
  // code that reads like the thing doing the work.
};

interface AgentSocket {
  kind: 'agent';
  machineId: string;
  ownerId: string;
  alive: boolean;
}

interface ControllerSocket {
  kind: 'controller';
  sessionId: string;
  machineId: string;
  userId: string;
  username: string;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
  /**
   * Mutable, unlike the row it started from: the machine can lend control
   * mid-session and take it back. Every change is written to the session row
   * too, so the audit trail and a restart agree with what the relay enforces -
   * and so an instance that does not hold this socket can still read what this
   * session may do.
   */
  permissions: RemotePermission[];
  alive: boolean;
}

type SocketState = AgentSocket | ControllerSocket;

@Injectable()
export class RemoteGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly state = new WeakMap<WebSocket, SocketState>();
  /** machineId -> the agent's live socket *on this instance*. */
  private readonly agents = new Map<string, WebSocket>();
  /** sessionId -> the controller's live socket *on this instance*. */
  private readonly controllers = new Map<string, WebSocket>();
  private readonly relay = new RemoteRelay(
    envOr('REDIS_URL', 'redis://localhost:6379'),
    randomUUID(),
  );

  constructor(
    private readonly remote: RemoteService,
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  /**
   * The controller sockets this instance holds for one account.
   *
   * Controllers only. An agent socket is authenticated by the machine's own
   * token rather than by anybody's session, so a session revocation has nothing
   * to say about it - and dropping it would take a machine offline every time
   * its owner changed their password, which is a different feature with a
   * different answer.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter((socket) => {
      const state = this.state.get(socket);
      return state?.kind === 'controller' && state.userId === userId;
    });
  }

  attach(httpServer: HttpServer): void {
    this.remote.setPresence({
      isOnline: (machineId) => this.relay.isAgentOnline(machineId),
      onlineAmong: (machineIds) => this.relay.onlineAgents(machineIds),
    });
    this.remote.onGrantRevoked = (machineId, userId) => this.endSessionsFor(machineId, userId);
    this.remote.onSessionEnded = async (sessionId, machineId, reason) => {
      this.tearDown(sessionId, machineId, reason);
    };

    void this.relay.start((message) => this.deliverLocal(message.target, message.event, message.close));

    // A remote session belonging to an account that has just been disabled is
    // the socket it matters most to close: it is a live hand on somebody's
    // desktop. Dropping the controller ends the session through the same path
    // an ordinary disconnect does.
    void dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => {
        const state = this.state.get(socket);
        return state?.kind === 'controller' ? state.issuedAt : undefined;
      },
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) => this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/remote',
      maxPayload: SIGNAL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      void this.onConnection(socket, request);
    });

    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
        if (state.kind === 'agent') {
          void this.remote.touchMachine(state.machineId);
          // Renews the registry entry. It outlives two missed beats and no more,
          // so an instance that dies stops claiming its agents by itself.
          void this.relay.announceAgent(state.machineId);
        }
      }
    }, HEARTBEAT_INTERVAL_MS);

    this.logger.info('Remote WebSocket gateway ready', { path: '/ws/remote' });
  }

  private async onConnection(socket: WebSocket, request: IncomingMessage): Promise<void> {
    const url = new URL(request.url ?? '/', 'http://localhost');
    const agentToken = url.searchParams.get('agent');

    if (agentToken) {
      await this.acceptAgent(socket, agentToken);
      return;
    }
    await this.acceptController(socket, request, url.searchParams.get('sessionId'));
  }

  // --- Agents ---------------------------------------------------------------

  private async acceptAgent(socket: WebSocket, token: string): Promise<void> {
    const machine = await this.remote.machineForAgentToken(token);
    if (!machine) {
      socket.close(4401, 'Unauthorized');
      return;
    }

    // One agent per machine. A second connection is the same machine coming
    // back after a network drop, so the older socket is the stale one - and it
    // may be a socket on another instance, which is why the close is relayed
    // rather than only applied here.
    const previous = this.agents.get(machine.id);
    if (previous && previous !== socket) previous.close(4409, 'Replaced');

    this.agents.set(machine.id, socket);
    this.state.set(socket, {
      kind: 'agent',
      machineId: machine.id,
      ownerId: machine.ownerId,
      alive: true,
    });
    await this.remote.touchMachine(machine.id);
    // Claimed before the older socket elsewhere is told to go: the registry
    // should never have a window where the machine reads offline.
    await this.relay.announceAgent(machine.id);
    await this.relay.forward({ kind: 'agent', machineId: machine.id }, null, {
      code: 4409,
      reason: 'Replaced',
    });

    this.send(socket, { type: 'ready', role: 'agent', machineId: machine.id });
    this.logger.info('Remote agent connected', { machineId: machine.id });

    socket.on('pong', () => this.markAlive(socket));
    socket.on('message', (raw) => void this.onAgentEvent(socket, raw.toString()));
    socket.on('close', () => {
      // Only if this socket is still the registered one: a reconnect replaces
      // the entry before the old socket's close event arrives.
      if (this.agents.get(machine.id) !== socket) {
        this.state.delete(socket);
        return;
      }
      this.agents.delete(machine.id);
      this.state.delete(socket);
      void this.relay.forgetAgent(machine.id);
      // Every session on a machine that just went away is over; nothing is
      // going to answer for it.
      void this.endSessionsForMachine(machine.id, 'agent-offline');
      this.logger.info('Remote agent disconnected', { machineId: machine.id });
    });
    socket.on('error', (error) => {
      this.logger.warn('Remote agent socket error', {
        machineId: machine.id,
        reason: String(error),
      });
    });
  }

  private async onAgentEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (state?.kind !== 'agent') return;

    let event: AgentRemoteEvent;
    try {
      event = JSON.parse(raw) as AgentRemoteEvent;
    } catch {
      return;
    }

    switch (event.type) {
      case 'agent.ready':
        await this.remote.touchMachine(state.machineId);
        return;

      case 'session.accepted':
      case 'session.refused': {
        if (event.type === 'session.accepted') {
          this.toController(event.sessionId, {
            type: 'agent.state',
            sessionId: event.sessionId,
            state: 'accepted',
          });
          return;
        }

        this.toController(event.sessionId, {
          type: 'agent.state',
          sessionId: event.sessionId,
          state: 'refused',
          reason: event.reason,
        });
        // The person sitting at the machine said no. That is a refusal worth
        // keeping: it is the record that consent was asked for and withheld.
        await recordRemoteAudit({
          machineId: state.machineId,
          sessionId: event.sessionId,
          action: 'session.refused',
          detail: { reason: event.reason, by: 'agent' },
        });
        await this.remote.endSession(event.sessionId, 'refused');
        this.tearDown(event.sessionId, state.machineId, 'refused');
        return;
      }

      case 'session.ended':
        await this.remote.endSession(event.sessionId, 'agent');
        this.tearDown(event.sessionId, state.machineId, 'agent');
        return;

      case 'control.granted':
      case 'control.denied': {
        // Read from the session row rather than from a controller socket this
        // instance may not hold. The row is what the relay enforces against, so
        // it is also the right thing to change.
        const session = await this.liveSession(event.sessionId);
        if (!session) return;

        const granted = event.type === 'control.granted';
        const refusal = event.type === 'control.denied' ? (event.reason ?? 'declined') : null;
        let permissions = session.permissions;

        if (granted && !permissions.includes(PERMISSIONS.REMOTE_CONTROL)) {
          // Somebody at the machine said yes. That is a higher authority than a
          // stored grant, so it stands - but only for this session: it is
          // written to the session row, never to the grant.
          permissions = [...permissions, PERMISSIONS.REMOTE_CONTROL];
          await prisma.remoteSession
            .update({ where: { id: event.sessionId }, data: { permissions } })
            .catch(() => undefined);
        }

        await recordRemoteAudit({
          machineId: state.machineId,
          sessionId: event.sessionId,
          actorId: session.userId,
          action: granted ? 'control.granted' : 'control.denied',
          detail: granted ? {} : { reason: refusal },
        });

        this.toController(event.sessionId, {
          type: 'control.changed',
          sessionId: event.sessionId,
          permissions,
          granted,
          ...(granted ? {} : { reason: refusal ?? 'The machine refused' }),
        });
        return;
      }

      // Which displays the machine has. No permission of its own: a session
      // that may see the screen may know how many there are.
      case 'screens':
        this.toController(event.sessionId, {
          type: 'screens',
          screens: event.screens,
          activeId: event.activeId,
        });
        return;

      case 'clipboard.text': {
        // The machine's clipboard travelling to the controller needs the same
        // permission as the other direction.
        const session = await this.liveSession(event.sessionId);
        if (session?.permissions.includes(PERMISSIONS.REMOTE_CLIPBOARD)) {
          this.toController(event.sessionId, { type: 'clipboard.set', text: event.text });
        }
        return;
      }

      // The machine's answer to an offered file, and the receipt when the last
      // byte has landed. The `sessionId` the agent stamps is dropped here: a
      // controller holds exactly one session and has no use for it, which is
      // the same shape `screens` and `clipboard.set` already have.
      case 'file.accepted':
        this.toController(event.sessionId, {
          type: 'file.accepted',
          transferId: event.transferId,
        });
        return;

      case 'file.refused':
        this.toController(event.sessionId, {
          type: 'file.refused',
          transferId: event.transferId,
          reason: event.reason,
        });
        return;

      case 'file.done': {
        // Written down on arrival rather than on the offer, so the trail says
        // what reached the machine and not only what was aimed at it.
        const session = await this.liveSession(event.sessionId);
        await recordRemoteAudit({
          machineId: state.machineId,
          sessionId: event.sessionId,
          actorId: session?.userId ?? null,
          action: 'file.received',
          detail: { transferId: event.transferId, path: event.path },
        });
        this.toController(event.sessionId, {
          type: 'file.done',
          transferId: event.transferId,
          path: event.path,
        });
        return;
      }

      // The agent's half of setting up the peer connection, on its way to that
      // session's controller. Forwarded without being read: an SDP this gateway
      // rewrote would be an SDP it could put itself in the middle of.
      case 'rtc.signal':
        this.toController(event.sessionId, { type: 'rtc.signal', data: event.data });
        return;

      case 'pong':
        return;

      default:
        return;
    }
  }

  // --- Controllers ----------------------------------------------------------

  private async acceptController(
    socket: WebSocket,
    request: IncomingMessage,
    sessionId: string | null,
  ): Promise<void> {
    const user = authenticateHandshake(request);
    if (!user || !sessionId) {
      socket.close(4401, 'Unauthorized');
      return;
    }

    const session = await prisma.remoteSession.findUnique({
      where: { id: sessionId },
      select: {
        id: true,
        machineId: true,
        userId: true,
        permissions: true,
        endedAt: true,
        machine: { select: { name: true } },
      },
    });

    // The session is the authorization. It was issued to one person over HTTP
    // after the grant was checked; presenting somebody else's is not a way in.
    if (!session || session.endedAt || session.userId !== user.id) {
      socket.close(4403, 'Forbidden');
      return;
    }

    // Connected to any instance, not only this one.
    if (!(await this.relay.isAgentOnline(session.machineId))) {
      socket.close(4404, 'Agent offline');
      await this.remote.endSession(sessionId, 'agent-offline');
      return;
    }

    const permissions = asRemotePermissions(session.permissions);

    this.controllers.set(sessionId, socket);
    this.state.set(socket, {
      kind: 'controller',
      sessionId,
      machineId: session.machineId,
      userId: user.id,
      username: user.username,
      issuedAt: user.issuedAt,
      permissions,
      alive: true,
    });

    this.send(socket, { type: 'ready', role: 'controller', sessionId });

    // Only now does the machine hear about it: the agent is asked to consent
    // and, if it does, to offer its screen to the controller directly. It is
    // given ICE servers rather than an address, because nothing here knows or
    // needs to know where either end is.
    this.toAgent(session.machineId, {
      type: 'session.start',
      sessionId,
      controllerId: user.id,
      controllerName: user.username,
      permissions,
      iceServers: await this.remote.agentIceServers(),
    });

    this.logger.info('Remote session opened', {
      sessionId,
      machineId: session.machineId,
      userId: user.id,
    });

    socket.on('pong', () => this.markAlive(socket));
    socket.on('message', (raw) => void this.onControllerEvent(socket, raw.toString()));
    socket.on('close', () => {
      this.state.delete(socket);
      if (this.controllers.get(sessionId) === socket) this.controllers.delete(sessionId);
      void this.remote.endSession(sessionId, 'controller');
      this.toAgent(session.machineId, { type: 'session.ended', sessionId, reason: 'controller' });
    });
    socket.on('error', () => socket.close());
  }

  private async onControllerEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (state?.kind !== 'controller') return;

    let event: ClientRemoteEvent;
    try {
      event = JSON.parse(raw) as ClientRemoteEvent;
    } catch {
      return;
    }

    if (event.type === 'ping') {
      this.send(socket, { type: 'pong' });
      return;
    }

    if (event.type === 'session.end') {
      await this.remote.endSession(state.sessionId, 'controller');
      this.tearDown(state.sessionId, state.machineId, 'controller');
      return;
    }

    // Asking for control, RDP style. A session already granted it is answered
    // here and never bothers the machine; one that was not has to be let in by
    // whoever is sitting at it.
    if (event.type === 'control.request') {
      if (state.permissions.includes(PERMISSIONS.REMOTE_CONTROL)) {
        this.send(socket, {
          type: 'control.changed',
          sessionId: state.sessionId,
          permissions: state.permissions,
          granted: true,
        });
        return;
      }

      if (!(await this.requireAgent(socket, state.machineId))) return;

      await recordRemoteAudit({
        machineId: state.machineId,
        sessionId: state.sessionId,
        actorId: state.userId,
        action: 'control.requested',
      });
      this.toAgent(state.machineId, {
        type: 'control.requested',
        sessionId: state.sessionId,
        controllerName: state.username,
      });
      return;
    }

    // Handing control back mid-session. Only what the machine lent is taken
    // away - a session granted control up front keeps it.
    if (event.type === 'control.release') {
      state.permissions = state.permissions.filter(
        (permission) => permission !== PERMISSIONS.REMOTE_CONTROL,
      );
      await prisma.remoteSession
        .update({ where: { id: state.sessionId }, data: { permissions: state.permissions } })
        .catch(() => undefined);
      this.send(socket, {
        type: 'control.changed',
        sessionId: state.sessionId,
        permissions: state.permissions,
        granted: false,
      });
      this.toAgent(state.machineId, {
        type: 'control.changed',
        sessionId: state.sessionId,
        permissions: state.permissions,
        granted: false,
      });
      return;
    }

    // Choosing a monitor is a view decision, not a control one: a view-only
    // session is entitled to look at the other screen. The agent answers with a
    // fresh `screens`, so the controller never has to assume it worked.
    if (event.type === 'screen.select') {
      if (!(await this.requireAgent(socket, state.machineId))) return;
      this.toAgent(state.machineId, {
        type: 'screen.select',
        sessionId: state.sessionId,
        screenId: event.screenId,
      });
      return;
    }

    // The controller's half of setting up the peer connection, on its way to
    // the agent. No permission of its own: answering an offer is how a session
    // that may view the screen comes to see it, and REMOTE_VIEW was checked
    // before the session existed. Forwarded without being read, for the same
    // reason the other direction is.
    if (event.type === 'rtc.signal') {
      this.toAgent(state.machineId, {
        type: 'rtc.signal',
        sessionId: state.sessionId,
        data: event.data,
      });
      return;
    }

    // Giving up on a transfer needs no permission of its own. Refusing it
    // would leave the machine writing a file nobody is still sending, which is
    // worse than letting a session that may not send files cancel one it never
    // started.
    if (event.type === 'file.cancel') {
      if (!(await this.requireAgent(socket, state.machineId))) return;
      this.toAgent(state.machineId, event);
      return;
    }

    // A file arriving on a machine is the event somebody reads the trail for
    // afterwards, so it is written down before it is allowed rather than
    // counted in the bytes that never come past here. The size is what the
    // controller claims; the machine counts the bytes itself.
    if (event.type === 'file.offer') {
      if (!state.permissions.includes(PERMISSIONS.REMOTE_FILE_TRANSFER)) {
        await this.refuse(socket, state, event.type, PERMISSIONS.REMOTE_FILE_TRANSFER);
        return;
      }
      if (
        !Number.isSafeInteger(event.size) ||
        event.size <= 0 ||
        event.size > REMOTE_TRANSFER_MAX_BYTES
      ) {
        this.send(socket, {
          type: 'file.refused',
          transferId: event.transferId,
          reason: 'That file is too big to send',
        });
        return;
      }
      if (!(await this.requireAgent(socket, state.machineId))) return;
      await recordRemoteAudit({
        machineId: state.machineId,
        sessionId: state.sessionId,
        actorId: state.userId,
        action: 'file.offered',
        detail: { name: event.name, size: event.size, transferId: event.transferId },
      });
      this.toAgent(state.machineId, event);
      return;
    }

    const required = REQUIRED_PERMISSION[event.type];
    if (!required) {
      this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
      return;
    }

    if (!state.permissions.includes(required)) {
      await this.refuse(socket, state, event.type, required);
      return;
    }

    if (!(await this.requireAgent(socket, state.machineId))) return;
    this.toAgent(state.machineId, event as ServerRemoteEvent);
  }

  /**
   * Says no to one event, and writes down that it said no.
   *
   * Refusals are audited, not only rejected: a client that keeps asking for
   * something it was not granted is worth being able to see afterwards. Every
   * path that turns an event away goes through here, so a new permission cannot
   * arrive with a refusal that leaves no trace.
   */
  private async refuse(
    socket: WebSocket,
    state: ControllerSocket,
    event: string,
    required: RemotePermission,
  ): Promise<void> {
    this.send(socket, {
      type: 'error',
      code: `${required}_REQUIRED`,
      message: 'That is not permitted in this session',
    });
    await recordRemoteAudit({
      machineId: state.machineId,
      sessionId: state.sessionId,
      actorId: state.userId,
      action: 'input.refused',
      detail: { event, required },
    });
  }

  // --- Delivery -------------------------------------------------------------

  /** Local socket if this instance holds it, the relay otherwise. */
  private toAgent(
    machineId: string,
    event: ServerRemoteEvent,
    close?: { code: number; reason: string },
  ): void {
    const target: RelayTarget = { kind: 'agent', machineId };
    if (this.agents.has(machineId)) {
      this.deliverLocal(target, event, close);
      return;
    }
    void this.relay.forward(target, event, close);
  }

  private toController(
    sessionId: string,
    event: ServerRemoteEvent,
    close?: { code: number; reason: string },
  ): void {
    const target: RelayTarget = { kind: 'controller', sessionId };
    if (this.controllers.has(sessionId)) {
      this.deliverLocal(target, event, close);
      return;
    }
    void this.relay.forward(target, event, close);
  }

  /**
   * The one place a message reaches a socket, whether it came from this
   * instance or another one - which is what makes the cached copy of a
   * session's permissions impossible to get out of step: `control.changed` is
   * applied here, on the way past, wherever the controller happens to be.
   */
  private deliverLocal(
    target: RelayTarget,
    event: ServerRemoteEvent | null,
    close?: { code: number; reason: string },
  ): void {
    const socket =
      target.kind === 'agent'
        ? this.agents.get(target.machineId)
        : this.controllers.get(target.sessionId);
    if (!socket) return;

    if (target.kind === 'controller' && event?.type === 'control.changed') {
      const state = this.state.get(socket);
      if (state?.kind === 'controller') state.permissions = asRemotePermissions(event.permissions);
    }

    if (event) this.send(socket, event);
    if (close) socket.close(close.code, close.reason);
  }

  /** The session as the server holds it, or null if it is over. */
  private async liveSession(
    sessionId: string,
  ): Promise<{ userId: string; permissions: RemotePermission[] } | null> {
    const session = await prisma.remoteSession.findUnique({
      where: { id: sessionId },
      select: { userId: true, permissions: true, endedAt: true },
    });
    if (!session || session.endedAt) return null;
    return { userId: session.userId, permissions: asRemotePermissions(session.permissions) };
  }

  /** Tells the controller when the machine is not there, and answers whether it is. */
  private async requireAgent(socket: WebSocket, machineId: string): Promise<boolean> {
    if (await this.relay.isAgentOnline(machineId)) return true;
    this.send(socket, { type: 'error', code: 'AGENT_OFFLINE', message: 'The machine is gone' });
    return false;
  }

  // --- Teardown -------------------------------------------------------------

  /** Closes both ends of a session that is over, whoever ended it. */
  private tearDown(sessionId: string, machineId: string, reason: string): void {
    this.toController(sessionId, { type: 'session.ended', sessionId, reason }, {
      code: 4000,
      reason,
    });
    // The agent has to stop capturing whether or not the controller is still
    // there to be told - a session nobody is watching must not stay open.
    this.toAgent(machineId, { type: 'session.ended', sessionId, reason });
  }

  /** Every live session on a machine, for when its agent disappears. */
  private async endSessionsForMachine(machineId: string, reason: string): Promise<void> {
    const open = await prisma.remoteSession.findMany({
      where: { machineId, endedAt: null },
      select: { id: true },
    });
    for (const session of open) {
      await this.remote.endSession(session.id, reason);
      this.tearDown(session.id, machineId, reason);
    }
  }

  /**
   * A revoked grant takes effect immediately, including on a session already
   * running. Permissions are frozen when a session starts precisely so that
   * this is a decision rather than a race.
   */
  private async endSessionsFor(machineId: string, userId: string): Promise<void> {
    const open = await prisma.remoteSession.findMany({
      where: { machineId, userId, endedAt: null },
      select: { id: true },
    });
    for (const session of open) {
      await this.remote.endSession(session.id, 'revoked');
      this.tearDown(session.id, machineId, 'revoked');
    }
  }

  private markAlive(socket: WebSocket): void {
    const state = this.state.get(socket);
    if (state) state.alive = true;
  }

  private send(socket: WebSocket, event: ServerRemoteEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  async onModuleDestroy(): Promise<void> {
    if (this.heartbeat) clearInterval(this.heartbeat);
    this.server?.close();
    await this.relay.close();
  }
}

/**
 * The part of a remote session that has to cross a process boundary.
 *
 * A session is two sockets: an agent that dialled out from the machine, and a
 * controller that dialled in from somebody's client. Nothing makes them land on
 * the same replica - the agent connected hours ago and the controller connected
 * just now, through a load balancer that has no idea they belong together - so
 * with more than one `remote-gateway` running, a session whose two halves are on
 * different instances used to be a session where nothing happened at all.
 *
 * Two small things fix it, and both are Redis:
 *
 * - **A relay.** Every message is delivered to a local socket if this instance
 *   holds it, and published otherwise. Each instance ignores its own
 *   publications, so a message is never delivered twice.
 * - **A registry.** Which machines have an agent connected *anywhere*, so
 *   "that machine is not connected" is an answer about the deployment rather
 *   than about whichever instance happened to be asked. Keys expire, so an
 *   instance that dies does not leave its agents looking online for ever.
 *
 * The screen never comes near any of this. It is a peer connection between the
 * two machines; what crosses here is the signalling, the input events and the
 * teardown - small, textual, and already going over a WebSocket.
 */
import Redis from 'ioredis';
import type { ServerRemoteEvent } from '@betweenus/shared-types';

/** The socket a message is for, named by what identifies it rather than by address. */
export type RelayTarget =
  | { kind: 'agent'; machineId: string }
  | { kind: 'controller'; sessionId: string };

export interface RelayMessage {
  /** Which instance published it; its own subscriber drops it. */
  origin: string;
  target: RelayTarget;
  /** Null when the point is only to close the socket - a replaced agent. */
  event: ServerRemoteEvent | null;
  /** Close the socket after delivering. A teardown has to reach both ends. */
  close?: { code: number; reason: string };
}

const CHANNEL = 'remote.relay';

/**
 * How long an agent stays in the registry without being renewed. Three times
 * the gateway's heartbeat, so two missed renewals are survivable and a killed
 * instance's agents disappear inside a minute and a half.
 */
const AGENT_TTL_SECONDS = 90;

const agentKey = (machineId: string): string => `remote:agent:${machineId}`;

export class RemoteRelay {
  private readonly publisher: Redis;
  private subscriber: Redis | null = null;

  constructor(
    private readonly redisUrl: string,
    private readonly origin: string,
  ) {
    this.publisher = new Redis(redisUrl, { maxRetriesPerRequest: null });
  }

  /** Starts listening. `deliver` is called for messages from other instances only. */
  async start(deliver: (message: RelayMessage) => void): Promise<void> {
    this.subscriber = new Redis(this.redisUrl, { maxRetriesPerRequest: null });
    this.subscriber.on('message', (_channel: string, raw: string) => {
      let message: RelayMessage;
      try {
        message = JSON.parse(raw) as RelayMessage;
      } catch {
        return; // Not ours to make sense of.
      }
      // Our own publication coming back: the local socket was already served.
      if (message.origin === this.origin) return;
      deliver(message);
    });
    await this.subscriber.subscribe(CHANNEL);
  }

  /** Hands a message to whichever instance holds the socket. */
  async forward(
    target: RelayTarget,
    event: ServerRemoteEvent | null,
    close?: { code: number; reason: string },
  ): Promise<void> {
    const message: RelayMessage = { origin: this.origin, target, event, ...(close ? { close } : {}) };
    await this.publisher.publish(CHANNEL, JSON.stringify(message)).catch(() => undefined);
  }

  // --- Agent registry -------------------------------------------------------

  /** Records that this instance holds the agent for a machine, and renews it. */
  async announceAgent(machineId: string): Promise<void> {
    await this.publisher
      .set(agentKey(machineId), this.origin, 'EX', AGENT_TTL_SECONDS)
      .catch(() => undefined);
  }

  /**
   * Drops a machine from the registry when its agent disconnects here.
   *
   * Only if the entry is still ours: an agent that dropped and reconnected to
   * another instance is already registered there, and the close event for the
   * old socket arriving afterwards must not delete the new registration.
   *
   * ponytail: read-then-delete rather than a Lua compare-and-delete, so the
   * reconnect-in-between case can still lose a registration. It costs at most
   * one heartbeat of a machine reading offline, and the agent renews it.
   */
  async forgetAgent(machineId: string): Promise<void> {
    const holder = await this.publisher.get(agentKey(machineId)).catch(() => null);
    if (holder === this.origin) await this.publisher.del(agentKey(machineId)).catch(() => undefined);
  }

  /** Is this machine's agent connected to any instance? */
  async isAgentOnline(machineId: string): Promise<boolean> {
    return (await this.publisher.exists(agentKey(machineId)).catch(() => 0)) === 1;
  }

  /** The subset of these machines with an agent connected somewhere. One round trip. */
  async onlineAgents(machineIds: string[]): Promise<Set<string>> {
    if (machineIds.length === 0) return new Set();
    const values = await this.publisher.mget(machineIds.map(agentKey)).catch(() => []);
    return new Set(machineIds.filter((_, index) => values[index] != null));
  }

  async close(): Promise<void> {
    await this.publisher.quit().catch(() => undefined);
    if (this.subscriber) await this.subscriber.quit().catch(() => undefined);
  }
}

