  @IsInt()
  @Min(1)
  @Max(24 * 365)
  expiresInHours?: number | null;

  /** Absent or null for unlimited. */
  @IsOptional()
  @ValidateIf((_object, value) => value !== null)
  @IsInt()
  @Min(1)
  @Max(1000)
  maxUses?: number | null;
