/** Self-check: `pnpm --filter @betweenus/config check`. Secrets read from a file. */
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { env, requireEnv, resetEnvFileCache } from './index';

const dir = mkdtempSync(join(tmpdir(), 'betweenus-env-'));

try {
  const path = join(dir, 'jwt-secret');
  // The trailing newline `echo` leaves is the case this is really for: a signing
  // key that differs by one byte fails as an invalid signature rather than as a
  // configuration mistake, which is a bad afternoon.
  writeFileSync(path, 'file-secret\n');

  process.env.CHECK_SECRET_FILE = path;
  delete process.env.CHECK_SECRET;
  assert.equal(env('CHECK_SECRET'), 'file-secret');

  // The variable wins over the file, so an existing deployment is unaffected and
  // a one-boot override is still a matter of exporting something.
  process.env.CHECK_SECRET = 'inline-secret';
  assert.equal(env('CHECK_SECRET'), 'inline-secret');
  delete process.env.CHECK_SECRET;

  // Read once. The file changing underneath is not picked up without a restart,
  // which is deliberate: this sits under every token verification.
  writeFileSync(path, 'changed');
  assert.equal(env('CHECK_SECRET'), 'file-secret');
  resetEnvFileCache();
  assert.equal(env('CHECK_SECRET'), 'changed');

  // An unreadable or empty file is a boot failure, not an unset variable. The
  // two look identical from the outside and have very different fixes.
  resetEnvFileCache();
  process.env.CHECK_SECRET_FILE = join(dir, 'missing');
  assert.throws(() => env('CHECK_SECRET'), /could not be read/);

  resetEnvFileCache();
  const empty = join(dir, 'empty');
  writeFileSync(empty, '   \n');
  process.env.CHECK_SECRET_FILE = empty;
  assert.throws(() => env('CHECK_SECRET'), /which is empty/);

  delete process.env.CHECK_SECRET_FILE;
  assert.equal(env('CHECK_SECRET'), undefined);
  assert.throws(() => requireEnv('CHECK_SECRET'), /CHECK_SECRET_FILE/);

  console.log('config env check ok');
} finally {
  rmSync(dir, { recursive: true, force: true });
}

/**
 * That a client is always given a way to discover its own address, that a
 * deployment which configures no relay stays quiet about it exactly once, and
 * that a configured relay reaches the client with its credentials.
 *
 * The things worth pinning:
 *
 * - STUN is never absent. It is the one step of ICE with no fallback: a peer
 *   that cannot learn its public address has nothing to offer, and the call
 *   does not happen. An empty ICE list would be that failure, arriving from
 *   the code meant to prevent it.
 * - A configured relay is handed out. This is the whole point of the module,
 *   and the regression that motivated removing the hosted minting path was
 *   precisely this not happening while the configuration said it should.
 * - Nothing here touches the network. A relay read from the environment cannot
 *   fail to resolve, and a check that lets a `fetch` through would not notice
 *   if that stopped being true.
 *
 * Run with: pnpm --filter @betweenus/config check
 */
import assert from 'node:assert/strict';
import { iceServers, onIceProblem, resetIceWarnings, stunServers } from './ice';

/**
 * The relay, unset.
 *
 * A developer's own `.env` is loaded by this package, so a check that asserts
 * "no relay is configured" has to say so rather than assume it - one machine
 * with a coturn in its `.env` would otherwise fail a suite that passes
 * everywhere else.
 */
function unconfigureTheRelay(): void {
  delete process.env.TURN_URLS;
  delete process.env.TURN_USERNAME;
  delete process.env.TURN_CREDENTIAL;
}

/**
 * Nothing in this module may reach the network.
 *
 * Runs for the whole suite rather than per case: the reason the hosted path was
 * removed is that a network call in here can fail while the configuration looks
 * complete, and the way to keep that from coming back is for any `fetch` at all
 * to be a failed check rather than a slow one.
 */
function forbidTheNetwork(): () => void {
  const realFetch = globalThis.fetch;
  globalThis.fetch = (() => {
    throw new Error('ice must not reach the network: a relay is read from the environment');
  }) as typeof fetch;
  return () => {
    globalThis.fetch = realFetch;
  };
}

function stunIsAlwaysThere(): void {
  delete process.env.STUN_URLS;
  const servers = stunServers();
  assert.equal(servers.length, 1, 'the default is one entry with several URLs');
  assert.ok(
    (servers[0]?.urls.length ?? 0) >= 2,
    'more than one operator, because STUN has no fallback',
  );
  assert.ok(
    servers[0]?.urls.every((url) => url.startsWith('stun:')),
    'STUN only - a relay never arrives by this route',
  );
}

function anOperatorCanNameTheirOwn(): void {
  process.env.STUN_URLS = ' stun:stun.example.com:3478 , stun:backup.example.com:3478 ';
  assert.deepEqual(stunServers(), [
    { urls: ['stun:stun.example.com:3478', 'stun:backup.example.com:3478'] },
  ]);

  // Blank means blank, not "fall back to the default": an operator who empties
  // it has said something, and a call that then fails to connect is a clearer
  // signal than one silently talking to Google.
  process.env.STUN_URLS = '  ,  ';
  assert.deepEqual(stunServers(), []);
  delete process.env.STUN_URLS;
}

async function unconfiguredStillWorks(): Promise<void> {
  resetIceWarnings();
  unconfigureTheRelay();

  const servers = await iceServers();
  assert.ok(servers.length > 0, 'a usable answer: STUN needs no configuration');
  assert.ok(
    servers.every((server) => server.urls.every((url) => url.startsWith('stun:'))),
    'nothing is relayed on a deployment that configured no relay',
  );
}

/**
 * Running without a relay is recorded, once.
 *
 * The whole reason this line exists: with no relay, a call between two networks
 * that cannot reach each other directly joins, shows both people and then
 * carries nothing. From the outside that is indistinguishable from a broken
 * client, and an operator with no line in their log has nothing to go on. Once
 * per process rather than once per join, so it is findable rather than buried
 * under a thousand copies of itself.
 */
async function aMissingRelayIsSaidOutLoudExactlyOnce(): Promise<void> {
  resetIceWarnings();
  unconfigureTheRelay();

  const said: string[] = [];
  onIceProblem((message) => said.push(message));

  try {
    await iceServers();
    assert.equal(said.length, 1, 'a deployment with no relay is told so');
    assert.match(
      said[0] ?? '',
      /not an error/,
      'and told it is the default, not a misconfiguration to panic about',
    );

    await iceServers();
    await iceServers();
    assert.equal(said.length, 1, 'and not once per call, which would bury it');
  } finally {
    onIceProblem(() => undefined);
  }
}

/**
 * What a deployment running its own coturn gets.
 *
 * The regression this pins: a deployment whose configuration names a working
 * relay must hand that relay to clients. It stopped doing so once, silently,
 * because the answer was being fetched from somewhere that had started saying
 * `404` - and every call between two hostile NATs sat at "connecting" while the
 * relay it needed was named in the very same `.env`.
 */
async function theConfiguredRelayReachesTheClient(): Promise<void> {
  resetIceWarnings();
  process.env.TURN_URLS = ' turns:turn.example.com:443?transport=tcp , turn:turn.example.com:3478 ';
  process.env.TURN_USERNAME = 'betweenus';
  process.env.TURN_CREDENTIAL = 'secret';

  try {
    const servers = await iceServers();

    const relay = servers.find((server) => server.urls.some((url) => url.startsWith('turn')));
    assert.ok(relay, 'the relay reaches the client');
    assert.deepEqual(
      relay?.urls,
      ['turns:turn.example.com:443?transport=tcp', 'turn:turn.example.com:3478'],
      'comma-separated, trimmed, in the order the operator wrote them',
    );
    assert.equal(relay?.username, 'betweenus');
    assert.equal(relay?.credential, 'secret');

    assert.ok(
      servers[0]?.urls.every((url) => url.startsWith('stun:')),
      'and STUN still comes first: a relay is the fallback, not the path',
    );
  } finally {
    unconfigureTheRelay();
    resetIceWarnings();
  }
}

/**
 * A relay with no credentials is worse than no relay at all.
 *
 * `new RTCPeerConnection({ iceServers: [{ urls: 'turn:...' }] })` throws, so
 * handing one out does not degrade the calls that needed a relay - it takes
 * down every call in the deployment, including the ones that were connecting
 * on STUN alone.
 */
async function aHalfConfiguredRelayIsDroppedAndSaidOutLoud(): Promise<void> {
  resetIceWarnings();
  process.env.TURN_URLS = 'turns:turn.example.com:443?transport=tcp';
  delete process.env.TURN_USERNAME;
  delete process.env.TURN_CREDENTIAL;

  const said: string[] = [];
  onIceProblem((message) => said.push(message));

  try {
    const servers = await iceServers();
    assert.ok(
      servers.every((server) => server.urls.every((url) => url.startsWith('stun:'))),
      'no relay entry leaves without the credentials a client would throw over',
    );
    assert.ok(servers.length > 0, 'and the calls that never needed one still work');
    assert.ok(
      said.some((message) => /TURN_USERNAME or TURN_CREDENTIAL/.test(message)),
      'the operator is told which half is missing',
    );

    const before = said.length;
    await iceServers();
    assert.equal(said.length, before, 'once per process, like every other fact about the config');
  } finally {
    onIceProblem(() => undefined);
    unconfigureTheRelay();
    resetIceWarnings();
  }
}

/** STUN named in the relay variable is not a relay, and is not counted as one. */
async function stunInTheRelayVariableIsNotARelay(): Promise<void> {
  resetIceWarnings();
  process.env.TURN_URLS = 'stun:stun.example.com:3478';
  process.env.TURN_USERNAME = 'betweenus';
  process.env.TURN_CREDENTIAL = 'secret';

  const said: string[] = [];
  onIceProblem((message) => said.push(message));

  try {
    const servers = await iceServers();
    assert.ok(
      servers.every((server) => server.credential === undefined),
      'nothing is handed out carrying a credential for a server that wants none',
    );
    assert.ok(
      said.some((message) => /STUN servers belong in STUN_URLS/.test(message)),
      'and the operator is told where it should have gone',
    );
  } finally {
    onIceProblem(() => undefined);
    unconfigureTheRelay();
    resetIceWarnings();
  }
}

async function main(): Promise<void> {
  const restoreNetwork = forbidTheNetwork();
  try {
    stunIsAlwaysThere();
    anOperatorCanNameTheirOwn();
    await unconfiguredStillWorks();
    await aMissingRelayIsSaidOutLoudExactlyOnce();
    await theConfiguredRelayReachesTheClient();
    await aHalfConfiguredRelayIsDroppedAndSaidOutLoud();
    await stunInTheRelayVariableIsNotARelay();
  } finally {
    restoreNetwork();
  }
  console.log('ice self-check passed');
}

void main();

/**
 * How two peers find a path to each other.
 *
 * There is no media server in this deployment, so nothing here tells a client
 * where to dial. It hands out the two things WebRTC needs to work out a path on
 * its own, and they are not the same kind of thing at all:
 *
 * **STUN is address discovery, and is required.** A machine behind NAT does not
 * know what its own public address looks like from outside, so it cannot offer
 * one. It asks a STUN server, gets told, and puts that in its candidate list.
 * No media goes through a STUN server, no port has to be opened for it, and one
 * request per call is the whole of the traffic. Public servers are fine and the
 * default; a deployment that would rather not talk to Google can point
 * `STUN_URLS` somewhere else, including at its own coturn.
 *
 * **TURN is a relay, and is optional.** Some pairs of networks - symmetric NAT
 * on both sides, mobile carrier-grade NAT - cannot form a direct path however
 * well they describe themselves. TURN is a machine both ends can reach outbound
 * that forwards packets between them, and it is the only thing that makes those
 * calls work. It costs bandwidth and it puts a third party in the path, so it
 * stays unconfigured unless an operator decides otherwise: with none set, those
 * particular calls fail rather than being quietly relayed.
 *
 * A relay is configured one way and one way only: `TURN_URLS` + `TURN_USERNAME`
 * + `TURN_CREDENTIAL`, naming a server the operator runs or rents - coturn,
 * eturnal, a relay from a provider that hands out a long-term credential. There
 * is no credential API to mint against, so those are long-term values, rotated
 * by changing them and restarting.
 *
 * **Why there is exactly one way.** There used to be two: a hosted service whose
 * short-lived credentials were minted here over HTTPS, checked first, with this
 * as the fallback. It was removed after it failed in the way that shape of code
 * always eventually fails. The hosted key was deleted at the provider; every
 * mint answered `404`; and because a mint failure resolved to "no relay" rather
 * than to the relay sitting right there in the same configuration, a deployment
 * with a working coturn handed out STUN-only to every client. Calls between two
 * hostile NATs sat at "connecting" and nothing but one line in a log said why,
 * while each join paid the doomed round-trip before giving up. Reading a relay
 * out of local configuration cannot fail that way: there is no request, so there
 * is no request to fail, and what an operator configured is what clients get.
 *
 * **A relay has to be reachable, and a Cloudflare Tunnel cannot make one so.**
 * Both peers dial the relay outbound, so it opens no port on *this* host - but
 * it does need a public address of its own, which in practice means a small VM
 * rather than the machine behind the tunnel. The tunnel carries HTTP and
 * WebSocket: its edge terminates TLS on 443 and expects HTTP inside, and TURN
 * over TLS is its own binary protocol, so a `turns:` URL pointed at the
 * tunnel's hostname is refused by the edge before it reaches anything here.
 * cloudflared's TCP ingress does not close that gap either - it needs
 * cloudflared or WARP on the *client* side, which a browser's WebRTC stack has
 * no way to run. See `docs/docs/deployment/turn-server.md`.
 *
 * Privacy is unchanged by any of it. A relay forwards DTLS-SRTP it has no key
 * for, so a relayed call is as unreadable to whoever runs the relay as a direct
 * one is to everybody else.
 *
 * This lives in `config` rather than in a service because two services need the
 * same answer - `call-service` for a call, `remote-gateway` for a remote
 * session - and two implementations of "where can these peers meet" is how they
 * come to disagree. It logs through a callback rather than importing the
 * logger, so this package keeps its one dependency.
 */
import { env, envOr } from './index';

/**
 * One entry of a WebRTC `RTCConfiguration.iceServers`.
 *
 * Structurally the same as `IceServer` in `@betweenus/shared-types`, and declared
 * here rather than imported so this package keeps its single dependency. The
 * two are checked against each other where they meet, at each service's
 * boundary.
 */
export interface IceServerConfig {
  urls: string[];
  username?: string;
  credential?: string;
}

/**
 * Where to ask for one's own public address when the deployment says nothing.
 *
 * Two, from different operators: STUN is the one step with no fallback, and a
 * call that cannot get a candidate is a call that cannot happen.
 */
const DEFAULT_STUN = 'stun:stun.l.google.com:19302,stun:stun.cloudflare.com:3478';

/**
 * The STUN servers this deployment uses. Comma-separated, so an operator can
 * name several without a config file.
 *
 * Exported for the self-check; there is no other reason for it to be public.
 */
export function stunServers(): IceServerConfig[] {
  const urls = envOr('STUN_URLS', DEFAULT_STUN)
    .split(',')
    .map((url) => url.trim())
    .filter((url) => url.length > 0);

  return urls.length > 0 ? [{ urls }] : [];
}

/**
 * Where a configuration problem is reported. Set once at startup by whichever
 * service is using this; unset, a problem is silent, which is only right in a
 * test.
 */
type Reporter = (message: string, error: unknown) => void;

let report: Reporter = () => undefined;

/**
 * Tells this module how to log. Called by each service at startup, so a
 * deployment whose relay is half-configured says so in that service's own log
 * rather than nowhere.
 */
export function onIceProblem(reporter: Reporter): void {
  report = reporter;
}

/**
 * Whether the "there is no relay here" warning has been said.
 *
 * Once per process, not once per call: it is a fact about the deployment, and
 * repeating it on every join would bury the log it is trying to be found in.
 */
let warnedAboutNoRelay = false;

/** Same reasoning, for a relay that was half configured. */
let warnedAboutPartialTurn = false;

/**
 * The relay this deployment runs, or an empty list.
 *
 * Static credentials, because there is nothing to mint against: a coturn has no
 * credential API, so `TURN_USERNAME` and `TURN_CREDENTIAL` are long-term values
 * rotated by redeploying.
 *
 * **A `turn:` URL is never handed out without both credentials.** An
 * `RTCPeerConnection` constructor *throws* on a relay entry missing them, which
 * would take down the calls that connect on STUN alone - every call in the
 * deployment, to fix the few that need a relay. A half-configured relay is
 * therefore reported and dropped, and the caller is left on exactly the path it
 * would have had with nothing configured at all.
 */
function turnServers(): IceServerConfig[] {
  const urls = envOr('TURN_URLS', '')
    .split(',')
    .map((url) => url.trim())
    .filter((url) => url.length > 0);

  if (urls.length === 0) {
    // Recorded once, because the limit it describes is invisible from
    // everywhere else. Running without a relay is a legitimate choice and the
    // default one - but it means a pair of peers who cannot form a direct path
    // (two symmetric NATs, two mobile carriers, an office firewall that drops
    // UDP) get a call that rings, joins, shows both people and then never
    // carries a packet, which reads as a broken client rather than as a
    // deployment that has no relay. Clients retry such a link from scratch
    // several times before giving up, which is why one occasionally comes good
    // on its own; the ones that do not are this.
    if (!warnedAboutNoRelay) {
      warnedAboutNoRelay = true;
      report(
        'Running STUN-only: no TURN relay is configured, so calls between two networks ' +
          'that cannot form a direct path will connect and then carry no media. This is ' +
          'the default and is not an error. See docs/ for details.',
        null,
      );
    }
    return [];
  }

  const username = env('TURN_USERNAME');
  const credential = env('TURN_CREDENTIAL');
  if (!username || !credential) {
    if (!warnedAboutPartialTurn) {
      warnedAboutPartialTurn = true;
      report(
        'TURN_URLS is set but TURN_USERNAME or TURN_CREDENTIAL is not. A TURN server refuses ' +
          'an unauthenticated allocation and a client refuses to build a peer connection from ' +
          'a relay with no credentials, so this relay is being ignored and calls run STUN-only.',
        null,
      );
    }
    return [];
  }

  // `stun:` in this list would be a STUN server named in the relay variable:
  // harmless to a client, but it is not a relay and counting it as one would
  // report a deployment as relayed when it is not. STUN belongs in STUN_URLS.
  const relays = urls.filter((url) => url.startsWith('turn:') || url.startsWith('turns:'));
  if (relays.length === 0) {
    if (!warnedAboutPartialTurn) {
      warnedAboutPartialTurn = true;
      report(
        'TURN_URLS names no turn: or turns: URL, so this deployment has no relay. ' +
          'STUN servers belong in STUN_URLS.',
        null,
      );
    }
    return [];
  }

  return [{ urls: relays, username, credential }];
}

/**
 * Everything a client needs to find a path, STUN first.
 *
 * Never throws, and never reaches the network: both halves are read from this
 * process's own environment. Still `async` because both callers await it and
 * because that is the honest signature for "the answer a client is given",
 * which has been fetched before and may be again.
 */
export async function iceServers(): Promise<IceServerConfig[]> {
  return [...stunServers(), ...turnServers()];
}

/**
 * Test seam: the once-per-process warnings are process-wide and a self-check
 * needs them unsaid.
 */
export function resetIceWarnings(): void {
  warnedAboutNoRelay = false;
  warnedAboutPartialTurn = false;
}

/**
 * Typed environment access. Loads `.env` from the repo root once, then reads
 * variables with explicit required/optional semantics so a missing secret fails
 * at boot instead of at the first request.
 */
import { config as loadDotenv } from 'dotenv';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';

let loaded = false;

/** Walks up from cwd to find the repo-root `.env`. Safe to call repeatedly. */
export function loadEnv(): void {
  if (loaded) return;
  loaded = true;

  let dir = process.cwd();
  for (let i = 0; i < 6; i += 1) {
    const candidate = resolve(dir, '.env');
    if (existsSync(candidate)) {
      loadDotenv({ path: candidate });
      return;
    }
    const parent = resolve(dir, '..');
    if (parent === dir) break;
    dir = parent;
  }
  loadDotenv();
}

/**
 * Secrets read from a file rather than from the environment.
 *
 * `.env` is where a secret goes when there is nowhere better, and it has the two
 * problems every deployment eventually meets: it is one file holding every
 * secret, and its contents are in the environment of every process the service
 * spawns and in the output of `docker inspect`. `NAME_FILE=/run/secrets/name`
 * points at a file instead, which is what Docker and Podman secrets, Kubernetes
 * projected volumes, systemd credentials and a Vault Agent template all produce.
 * Rotation becomes replacing a file and restarting, with no `.env` edit and no
 * secret in a shell history.
 *
 * `NAME` wins if both are set, so an existing deployment is unaffected and an
 * override for one boot is still a matter of exporting a variable.
 *
 * Read once per path. This sits under `requireEnv`, which is on the path of
 * every request carrying a token, and a file read per verification is not.
 */
const fileValues = new Map<string, string>();

function envFromFile(name: string): string | undefined {
  const path = process.env[`${name}_FILE`];
  if (path === undefined || path === '') return undefined;

  const cached = fileValues.get(path);
  if (cached !== undefined) return cached;

  let contents: string;
  try {
    contents = readFileSync(path, 'utf8');
  } catch (cause) {
    // Loudly. A secret file that cannot be read looks exactly like a secret that
    // was never set, and the second one has a much less obvious fix.
    throw new Error(`${name}_FILE points at ${path}, which could not be read`, { cause });
  }

  // Trimmed, because `echo secret > file` and every editor leave a newline, and
  // a signing key that differs from the one next door by a trailing byte fails
  // as an invalid signature rather than as a configuration mistake.
  const value = contents.trim();
  if (value === '') {
    throw new Error(`${name}_FILE points at ${path}, which is empty`);
  }

  fileValues.set(path, value);
  return value;
}

/** Forgets what was read from disk, so a rotation test can change the file. */
export function resetEnvFileCache(): void {
  fileValues.clear();
}

export function env(name: string): string | undefined {
  loadEnv();
  const value = process.env[name];
  if (value !== undefined && value !== '') return value;
  return envFromFile(name);
}

export function requireEnv(name: string): string {
  const value = env(name);
  if (value === undefined) {
    throw new Error(`Missing required environment variable: ${name} (or ${name}_FILE)`);
  }
  return value;
}

export function envOr(name: string, fallback: string): string {
  return env(name) ?? fallback;
}

export function envNumber(name: string, fallback: number): number {
  const raw = env(name);
  if (raw === undefined) return fallback;
  const parsed = Number(raw);
  if (Number.isNaN(parsed)) {
    throw new Error(`Environment variable ${name} must be a number, got "${raw}"`);
  }
  return parsed;
}

export function envBool(name: string, fallback = false): boolean {
  const raw = env(name)?.toLowerCase();
  if (raw === undefined) return fallback;
  return raw === '1' || raw === 'true' || raw === 'yes';
}

export function isProduction(): boolean {
  return envOr('NODE_ENV', 'development') === 'production';
}

// There were three exports here - LOOPBACK, hostnameOf and
// unreachableFromCaller - whose whole job was to catch a deployment about to
// hand a client a media-server address only the server itself could reach.
// Nothing advertises an address any more, so there is nothing left to check.

/** Config every service needs. Service-specific values stay in the service. */
export interface BaseServiceConfig {
  nodeEnv: string;
  port: number;
  logLevel: string;
  corsOrigin: string;
  databaseUrl: string;
  redisUrl: string;
}

export function baseConfig(portVar: string, defaultPort: number): BaseServiceConfig {
  return {
    nodeEnv: envOr('NODE_ENV', 'development'),
    port: envNumber(portVar, defaultPort),
    logLevel: envOr('LOG_LEVEL', 'info'),
    corsOrigin: envOr('CORS_ORIGIN', '*'),
    databaseUrl: requireEnv('DATABASE_URL'),
    redisUrl: envOr('REDIS_URL', 'redis://localhost:6379'),
  };
}

export {
  iceServers,
  onIceProblem,
  resetIceWarnings,
  stunServers,
  type IceServerConfig,
} from './ice';

{
  "extends": "../../tsconfig.base.json",
  "compilerOptions": {
    "rootDir": "src",
    "outDir": "dist"
  },
  "include": ["src/**/*.ts"]
