{
  "name": "@betweenus/permissions",
  "private": true,
  "version": "0.1.0",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "check": "tsc -p tsconfig.json && node dist/check.js"
  },
  "dependencies": {
    "@betweenus/shared-types": "workspace:*"
  },
  "devDependencies": {
    "@types/node": "^20.14.10",
    "typescript": "^5.5.4"
  }
}

/**
 * Self-check: `pnpm --filter @betweenus/permissions check`.
 *
 * The interesting part is the override arithmetic - a grant that adds, a deny
 * that wins, and unknown strings that are ignored rather than trusted.
 */
import assert from 'node:assert/strict';
import {
  ASSIGNABLE_PERMISSIONS,
  PERMISSIONS,
  REMOTE_PERMISSIONS,
  SERVER_ROLES,
  isRemotePermission,
  effectivePermissions,
  hasPermission,
  isPermission,
  memberHasPermission,
  permissionsForRole,
} from './index';

// The role defaults still stand on their own.
assert.ok(hasPermission('MEMBER', PERMISSIONS.SEND_MESSAGE));
assert.ok(!hasPermission('MEMBER', PERMISSIONS.MANAGE_CHANNEL));
assert.ok(hasPermission('OWNER', PERMISSIONS.MANAGE_SERVER));

// A grant adds one capability without changing the role.
assert.ok(
  memberHasPermission('MEMBER', PERMISSIONS.MANAGE_CHANNEL, [PERMISSIONS.MANAGE_CHANNEL]),
  'a granted permission must be held',
);
assert.ok(
  !memberHasPermission('MEMBER', PERMISSIONS.MANAGE_MEMBER, [PERMISSIONS.MANAGE_CHANNEL]),
  'granting one permission must not grant another',
);

// Deny wins, whichever role the member holds.
assert.ok(
  !memberHasPermission('ADMIN', PERMISSIONS.DELETE_MESSAGE, [], [PERMISSIONS.DELETE_MESSAGE]),
  'a denial must beat the role default',
);
assert.ok(
  !memberHasPermission(
    'MEMBER',
    PERMISSIONS.MANAGE_CHANNEL,
    [PERMISSIONS.MANAGE_CHANNEL],
    [PERMISSIONS.MANAGE_CHANNEL],
  ),
  'a denial must beat an explicit grant',
);

// A database written by a newer build must not break this one.
assert.deepEqual(
  effectivePermissions('GUEST', ['NOT_A_PERMISSION'], ['ALSO_NOT_ONE']),
  permissionsForRole('GUEST'),
  'unknown permission names must be ignored',
);
assert.ok(!isPermission('MANAGE_EVERYTHING'));
assert.ok(isPermission(PERMISSIONS.VIEW_CHANNEL));

// No duplicates when a grant repeats what the role already gave.
const doubled = effectivePermissions('ADMIN', [PERMISSIONS.SEND_MESSAGE, PERMISSIONS.SEND_MESSAGE]);
assert.equal(new Set(doubled).size, doubled.length, 'effective permissions must be unique');

// Ownership and remote access are never handed out through the member editor.
assert.ok(!ASSIGNABLE_PERMISSIONS.includes(PERMISSIONS.MANAGE_SERVER));
assert.ok(!ASSIGNABLE_PERMISSIONS.includes(PERMISSIONS.REMOTE_CONTROL));

// Remote permissions are held per machine: no role implies one, and the member
// editor cannot hand one out either.
for (const role of SERVER_ROLES) {
  for (const remote of REMOTE_PERMISSIONS) {
    assert.ok(!permissionsForRole(role).includes(remote), `${role} must not imply ${remote}`);
    assert.ok(!ASSIGNABLE_PERMISSIONS.includes(remote), `${remote} must not be assignable`);
  }
}
assert.ok(isRemotePermission(PERMISSIONS.REMOTE_CONTROL));
assert.ok(!isRemotePermission(PERMISSIONS.SEND_MESSAGE));

// --- Custom roles ---
//
// A custom role adds; a denial still wins over it. That last one is the whole
// safety property: a member can collect any number of roles, and taking a
// capability away from them has to work anyway, or every revocation turns into
// a hunt for which role put it back.
assert.ok(
  memberHasPermission('MEMBER', PERMISSIONS.MANAGE_CHANNEL, [], [], [PERMISSIONS.MANAGE_CHANNEL]),
  'a custom role must grant its permissions',
);
assert.ok(
  !memberHasPermission(
    'MEMBER',
    PERMISSIONS.MANAGE_CHANNEL,
    [],
    [PERMISSIONS.MANAGE_CHANNEL],
    [PERMISSIONS.MANAGE_CHANNEL],
  ),
  'a denial must beat a custom role',
);
// And beat a grant and a role at once, from either direction.
assert.ok(
  !memberHasPermission(
    'ADMIN',
    PERMISSIONS.MANAGE_MEMBER,
    [PERMISSIONS.MANAGE_MEMBER],
    [PERMISSIONS.MANAGE_MEMBER],
    [PERMISSIONS.MANAGE_MEMBER],
  ),
  'a denial must beat every source at once',
);
// Two roles carrying the same permission is still one permission.
const fromRoles = effectivePermissions(
  'GUEST',
  [],
  [],
  [PERMISSIONS.SEND_MESSAGE, PERMISSIONS.SEND_MESSAGE, 'NOT_A_PERMISSION'],
);
assert.equal(new Set(fromRoles).size, fromRoles.length);
assert.ok(fromRoles.includes(PERMISSIONS.SEND_MESSAGE));
// Holding no custom role changes nothing.
assert.deepEqual(effectivePermissions('MEMBER', [], [], []), permissionsForRole('MEMBER'));

console.log('permissions self-check ok');

/**
 * Role and permission vocabulary. Constants and pure helpers only - no service
 * business logic, no database access.
 */
import type { ServerRole } from '@betweenus/shared-types';

export const SERVER_ROLES = ['OWNER', 'ADMIN', 'MODERATOR', 'MEMBER', 'GUEST'] as const;

export const PERMISSIONS = {
  VIEW_CHANNEL: 'VIEW_CHANNEL',
  SEND_MESSAGE: 'SEND_MESSAGE',
  DELETE_MESSAGE: 'DELETE_MESSAGE',
  /** Pinning and unpinning in a channel; a direct message needs no permission. */
  MANAGE_MESSAGE: 'MANAGE_MESSAGE',
  MANAGE_CHANNEL: 'MANAGE_CHANNEL',
  MANAGE_MEMBER: 'MANAGE_MEMBER',
  MANAGE_ROLE: 'MANAGE_ROLE',
  MANAGE_SERVER: 'MANAGE_SERVER',
  /**
   * Uploading and removing a server's own emoji.
   *
   * Its own permission rather than a corner of MANAGE_SERVER, because the
   * people a server actually wants doing this - whoever makes the pictures -
   * are rarely the people it wants renaming it or deleting channels. Discord
   * split it for the same reason.
   */
  MANAGE_EMOJI: 'MANAGE_EMOJI',
  /**
   * Creating, renaming, rotating and deleting a channel's webhooks.
   *
   * Its own permission and not a corner of `MANAGE_CHANNEL`, because holding it
   * is strictly more dangerous than renaming a channel: a webhook is a URL that
   * posts into that channel forever, with no account behind it and no sealed
   * body. Whoever may hand one out should be a decision somebody makes on
   * purpose, and the settings screen says what it costs beside the button.
   *
   * Admin and above by default, unlike `MANAGE_EMOJI`, which is admin-and-above
   * because the pictures are harmless. This one is not.
   */
  MANAGE_WEBHOOK: 'MANAGE_WEBHOOK',
  START_CALL: 'START_CALL',
  MANAGE_CALL: 'MANAGE_CALL',
  REMOTE_VIEW: 'REMOTE_VIEW',
  REMOTE_CONTROL: 'REMOTE_CONTROL',
  REMOTE_FILE_TRANSFER: 'REMOTE_FILE_TRANSFER',
  REMOTE_CLIPBOARD: 'REMOTE_CLIPBOARD',
  REMOTE_AUDIO: 'REMOTE_AUDIO',
  REMOTE_ADMIN: 'REMOTE_ADMIN',
} as const;

export type Permission = (typeof PERMISSIONS)[keyof typeof PERMISSIONS];


const MEMBER_PERMISSIONS: Permission[] = [
  PERMISSIONS.VIEW_CHANNEL,
  PERMISSIONS.SEND_MESSAGE,
  PERMISSIONS.START_CALL,
];

const MODERATOR_PERMISSIONS: Permission[] = [
  ...MEMBER_PERMISSIONS,
  PERMISSIONS.DELETE_MESSAGE,
  PERMISSIONS.MANAGE_MESSAGE,
  PERMISSIONS.MANAGE_CALL,
];

const ADMIN_PERMISSIONS: Permission[] = [
  ...MODERATOR_PERMISSIONS,
  PERMISSIONS.MANAGE_CHANNEL,
  PERMISSIONS.MANAGE_MEMBER,
  PERMISSIONS.MANAGE_ROLE,
  PERMISSIONS.MANAGE_EMOJI,
  PERMISSIONS.MANAGE_WEBHOOK,
];

/** Role -> permission map. Remote permissions are granted per machine, never by role. */
export const ROLE_PERMISSIONS: Record<ServerRole, Permission[]> = {
  OWNER: [...ADMIN_PERMISSIONS, PERMISSIONS.MANAGE_SERVER],
  ADMIN: ADMIN_PERMISSIONS,
  MODERATOR: MODERATOR_PERMISSIONS,
  MEMBER: MEMBER_PERMISSIONS,
  GUEST: [PERMISSIONS.VIEW_CHANNEL],
};

export function permissionsForRole(role: ServerRole): Permission[] {
  return ROLE_PERMISSIONS[role] ?? [];
}

export function hasPermission(role: ServerRole, permission: Permission): boolean {
  return permissionsForRole(role).includes(permission);
}

/** True for a string that names a permission this build knows about. */
export function isPermission(value: string): value is Permission {
  return Object.prototype.hasOwnProperty.call(PERMISSIONS, value);
}

/**
 * What a member may actually do: the built-in role's defaults, plus whatever the
 * custom roles they hold carry, plus what was granted to them individually,
 * minus what was denied.
 *
 * Deny is applied last and beats all three sources. That is the property worth
 * protecting: taking a capability away from one person has to work whatever
 * role they hold and however many custom roles they collect, or every revocation
 * becomes a hunt for which of them put it back.
 *
 * Unknown strings are ignored rather than rejected - a database written by a
 * newer build must not break an older one.
 */
export function effectivePermissions(
  role: ServerRole,
  granted: readonly string[] = [],
  denied: readonly string[] = [],
  fromCustomRoles: readonly string[] = [],
): Permission[] {
  const denySet = new Set(denied.filter(isPermission));
  const allowed = new Set<Permission>(permissionsForRole(role));
  for (const value of fromCustomRoles) if (isPermission(value)) allowed.add(value);
  for (const value of granted) if (isPermission(value)) allowed.add(value);
  return [...allowed].filter((permission) => !denySet.has(permission));
}

export function memberHasPermission(
  role: ServerRole,
  permission: Permission,
  granted: readonly string[] = [],
  denied: readonly string[] = [],
  fromCustomRoles: readonly string[] = [],
): boolean {
  return effectivePermissions(role, granted, denied, fromCustomRoles).includes(permission);
}

/**
 * Permissions an administrator may hand out or take away. Server ownership is
 * not delegable, so `MANAGE_SERVER` is not on the list - it comes with the role.
 */
export const ASSIGNABLE_PERMISSIONS: Permission[] = [
  PERMISSIONS.VIEW_CHANNEL,
  PERMISSIONS.SEND_MESSAGE,
  PERMISSIONS.DELETE_MESSAGE,
  PERMISSIONS.MANAGE_MESSAGE,
  PERMISSIONS.MANAGE_CHANNEL,
  PERMISSIONS.MANAGE_MEMBER,
  PERMISSIONS.MANAGE_ROLE,
  PERMISSIONS.MANAGE_EMOJI,
  PERMISSIONS.MANAGE_WEBHOOK,
  PERMISSIONS.START_CALL,
  PERMISSIONS.MANAGE_CALL,
];

/** Remote-access permissions, granted per user per machine with optional expiry. */
export const REMOTE_PERMISSIONS = [
  PERMISSIONS.REMOTE_VIEW,
  PERMISSIONS.REMOTE_CONTROL,
  PERMISSIONS.REMOTE_FILE_TRANSFER,
  PERMISSIONS.REMOTE_CLIPBOARD,
  PERMISSIONS.REMOTE_AUDIO,
  PERMISSIONS.REMOTE_ADMIN,
] as const;

export type RemotePermission = (typeof REMOTE_PERMISSIONS)[number];

export interface RemoteGrant {
  permission: RemotePermission;
  /** ISO timestamp. Null means the grant does not expire. */
  expiresAt: string | null;
}

export function isRemoteGrantActive(grant: RemoteGrant, now: Date = new Date()): boolean {
  return grant.expiresAt === null || new Date(grant.expiresAt).getTime() > now.getTime();
}

/**
 * True for a string that names a remote permission this build knows about.
 * Remote access is never implied by a server role, so this is the only gate:
 * a name that is not here grants nothing.
 */
export function isRemotePermission(value: string): value is RemotePermission {
  return (REMOTE_PERMISSIONS as readonly string[]).includes(value);
}

