/**
 * The carrom board, as physics.
 *
 * Twenty discs on a square with four holes in the corners, sliding, colliding
 * and slowing down. This file is the simulation: rigid bodies, Coulomb
 * friction, elastic collisions with restitution, cushions, and a piece that
 * disappears when its centre reaches a pocket.
 *
 * ## Why the simulation is in the contract
 *
 * Because both ends run it, and they must agree exactly.
 *
 * The gateway runs it to decide what the board became - that is the refereeing,
 * and it is the only answer that counts. The client runs the *same function on
 * the same numbers* to animate the shot, because a shot that arrived as a set
 * of final positions would be twenty coins teleporting. What it shows is
 * therefore not a guess at the physics: it is the physics, replayed.
 *
 * That only works because this is deterministic. Fixed timestep, fixed
 * iteration order, no clock, no randomness, no `Set` iteration and no
 * floating-point that depends on how fast a machine is. Two IEEE-754 doubles
 * doing the same operations in the same order give the same answer on every
 * machine that will ever run this, so the last frame the client draws is the
 * position the gateway already sent.
 *
 * ## The units
 *
 * The playing surface is 1 x 1. Everything else is in fractions of it, taken
 * from a real board (74 cm playing area, 3.18 cm men, 4.13 cm striker, 4.45 cm
 * pockets), so the coins are the size they are relative to the board rather
 * than the size that felt right.
 */

/** Playing surface, corner to corner. Everything is a fraction of this. */
export const BOARD = 1;

/** A carrom man: 3.18 cm across on a 74 cm board. */
export const COIN_RADIUS = 0.0215;
/** The striker: 4.13 cm, and heavier, which is what makes a break work. */
export const STRIKER_RADIUS = 0.0279;
/** A pocket: 4.45 cm across, centred on the corner circle. */
export const POCKET_RADIUS = 0.0301;
/** How far a pocket's centre sits from each edge. */
export const POCKET_INSET = 0.043;

/** Grams. The ratio is what matters: a striker outweighs a man three to one. */
const COIN_MASS = 5.5;
const STRIKER_MASS = 15;

/**
 * Sliding friction, as a deceleration in board-widths per second squared.
 *
 * Coulomb rather than viscous - a real coin loses speed at a constant rate and
 * stops, where a `v *= 0.99` per step never quite does and leaves the board
 * creeping for ever. This is the number that decides whether a gentle shot
 * crosses the board, so it is the one to change if the board feels wrong.
 */
const FRICTION = 0.62;

/** Coin on coin. Ivory-ish: lively, not perfectly elastic. */
const RESTITUTION = 0.94;
/** Cushions take more out of a shot than a coin does. */
const WALL_RESTITUTION = 0.72;

/** Below this a piece has stopped, and the shot is over when they all have. */
const REST_SPEED = 0.012;

/** Fixed step. Small enough that a fast striker cannot pass through a coin. */
export const DT = 1 / 480;
/** Longest a shot may run before it is declared over, in seconds. */
const MAX_SECONDS = 9;
/** How many steps make one drawn frame, so a client animates at about 60 Hz. */
export const STEPS_PER_FRAME = 8;

/** One disc on the board. */
export interface Piece {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  mass: number;
  /** False once it has gone down a hole. It stops being simulated. */
  onBoard: boolean;
}

/** Where the four pockets are. Ordered, because everything here is ordered. */
export const POCKETS: { x: number; y: number }[] = [
  { x: POCKET_INSET, y: POCKET_INSET },
  { x: BOARD - POCKET_INSET, y: POCKET_INSET },
  { x: POCKET_INSET, y: BOARD - POCKET_INSET },
  { x: BOARD - POCKET_INSET, y: BOARD - POCKET_INSET },
];

/** What one shot did, once everything has stopped. */
export interface ShotResult {
  pieces: Piece[];
  /** Indices that went down a hole, in the order they did. */
  pocketed: number[];
  /** Every `STEPS_PER_FRAME`th step, for a client to animate. */
  frames: number[][];
  /** Whether the striker touched anything at all. Missing entirely is a foul. */
  contact: boolean;
}

function speedSquared(piece: Piece): number {
  return piece.vx * piece.vx + piece.vy * piece.vy;
}

/**
 * Runs a shot to a standstill.
 *
 * `frames` is the whole point of returning more than the final position: the
 * client draws them in order and the coins move the way they actually moved.
 * They are sampled rather than kept per step, because a nine-second shot at
 * 480 Hz is four thousand snapshots of twenty coins and only sixty of them a
 * second are ever drawn.
 */
export function simulate(input: Piece[], striker: number): ShotResult {
  const pieces = input.map((piece) => ({ ...piece }));
  const pocketed: number[] = [];
  const frames: number[][] = [];
  let contact = false;
  let step = 0;
  const maxSteps = Math.round(MAX_SECONDS / DT);

  while (step < maxSteps) {
    step += 1;

    // 1. Move, and slow down. Friction is applied along the direction of
    //    travel and clamped at zero, so a coin stops rather than reversing -
    //    which is what subtracting more than the remaining speed would do.
    for (const piece of pieces) {
      if (!piece.onBoard) continue;
      const speed = Math.sqrt(speedSquared(piece));
      if (speed > 0) {
        const drop = FRICTION * DT;
        const scale = speed > drop ? (speed - drop) / speed : 0;
        piece.vx *= scale;
        piece.vy *= scale;
      }
      piece.x += piece.vx * DT;
      piece.y += piece.vy * DT;
    }

    // 2. Cushions. Position is corrected as well as velocity, or a coin driven
    //    into a wall sticks to it: it would be pushed back in one step and out
    //    again the next, for ever.
    for (const piece of pieces) {
      if (!piece.onBoard) continue;
      if (piece.x - piece.radius < 0) {
        piece.x = piece.radius;
        piece.vx = Math.abs(piece.vx) * WALL_RESTITUTION;
      } else if (piece.x + piece.radius > BOARD) {
        piece.x = BOARD - piece.radius;
        piece.vx = -Math.abs(piece.vx) * WALL_RESTITUTION;
      }
      if (piece.y - piece.radius < 0) {
        piece.y = piece.radius;
        piece.vy = Math.abs(piece.vy) * WALL_RESTITUTION;
      } else if (piece.y + piece.radius > BOARD) {
        piece.y = BOARD - piece.radius;
        piece.vy = -Math.abs(piece.vy) * WALL_RESTITUTION;
      }
    }

    // 3. Collisions, every pair, in index order. Order matters for
    //    reproducibility far more than it matters for realism: a three-coin
    //    pile-up resolved in a different order is a different board.
    for (let a = 0; a < pieces.length; a += 1) {
      const first = pieces[a]!;
      if (!first.onBoard) continue;
      for (let b = a + 1; b < pieces.length; b += 1) {
        const second = pieces[b]!;
        if (!second.onBoard) continue;

        const dx = second.x - first.x;
        const dy = second.y - first.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        const overlap = first.radius + second.radius - distance;
        if (overlap <= 0 || distance === 0) continue;

        const nx = dx / distance;
        const ny = dy / distance;

        // Push them apart in proportion to mass, so a struck coin moves more
        // than the striker does. Without this discs sink into each other and
        // the next step resolves the same collision again.
        const total = first.mass + second.mass;
        first.x -= nx * overlap * (second.mass / total);
        first.y -= ny * overlap * (second.mass / total);
        second.x += nx * overlap * (first.mass / total);
        second.y += ny * overlap * (first.mass / total);

        // Only the component along the line of centres is exchanged. The
        // tangential part is untouched, which is what makes a cut shot cut.
        const relative = (second.vx - first.vx) * nx + (second.vy - first.vy) * ny;
        if (relative > 0) continue;

        const impulse = (-(1 + RESTITUTION) * relative) / (1 / first.mass + 1 / second.mass);
        first.vx -= (impulse * nx) / first.mass;
        first.vy -= (impulse * ny) / first.mass;
        second.vx += (impulse * nx) / second.mass;
        second.vy += (impulse * ny) / second.mass;

        if (a === striker || b === striker) contact = true;
      }
    }

    // 4. Pockets. A piece is down when its *centre* is inside the hole, which
    //    is how a real one behaves - a coin overhanging the pocket stays up.
    for (let index = 0; index < pieces.length; index += 1) {
      const piece = pieces[index]!;
      if (!piece.onBoard) continue;
      for (const pocket of POCKETS) {
        const dx = piece.x - pocket.x;
        const dy = piece.y - pocket.y;
        if (dx * dx + dy * dy <= POCKET_RADIUS * POCKET_RADIUS) {
          piece.onBoard = false;
          piece.vx = 0;
          piece.vy = 0;
          pocketed.push(index);
          break;
        }
      }
    }

    if (step % STEPS_PER_FRAME === 0) frames.push(snapshot(pieces));

    // 5. Still? Then the shot is over. Checked after everything else so a
    //    collision in this very step is not mistaken for a standstill.
    let moving = false;
    for (const piece of pieces) {
      if (piece.onBoard && speedSquared(piece) > REST_SPEED * REST_SPEED) {
        moving = true;
        break;
      }
    }
    if (!moving) break;
  }

  // Anything still crawling is stopped, so the board the gateway stores is a
  // board at rest rather than one that would carry on if it were asked again.
  for (const piece of pieces) {
    piece.vx = 0;
    piece.vy = 0;
  }
  frames.push(snapshot(pieces));

  return { pieces, pocketed, frames, contact };
}

/** One frame: x, y and on-board for every piece, flat. */
function snapshot(pieces: Piece[]): number[] {
  const flat: number[] = [];
  for (const piece of pieces) {
    flat.push(piece.x, piece.y, piece.onBoard ? 1 : 0);
  }
  return flat;
}

/** A carrom man at rest. */
export function coin(x: number, y: number): Piece {
  return { x, y, vx: 0, vy: 0, radius: COIN_RADIUS, mass: COIN_MASS, onBoard: true };
}

/** The striker, aimed and struck. */
export function striker(x: number, y: number, vx: number, vy: number): Piece {
  return { x, y, vx, vy, radius: STRIKER_RADIUS, mass: STRIKER_MASS, onBoard: true };
}

/**
 * Carrom: nineteen men, a striker, and four holes.
 *
 * The rules are here; the physics is in `carrom-physics.ts`, and the split is
 * the interesting part. A move in this game is not a square - it is a shot:
 * where the striker sits on your baseline, which way it is pointed and how hard
 * it is hit. Three numbers, sent as `params`. What the board *becomes* is then
 * not a decision anybody makes - it is what nine seconds of sliding, colliding
 * and slowing down produce, and it is produced identically by the gateway (to
 * referee it) and by every client (to draw it).
 *
 * That is why this game can exist at all in a design where a client never sends
 * a board. The shot is small enough to relay and the result is reproducible, so
 * the gateway can check the aim and run the physics itself. A client that sent
 * twenty coin positions would be a client that can put every coin in a pocket.
 *
 * ## What is simplified
 *
 * The queen rule is the real one in outline: pocket the queen and you must
 * cover her with one of your own, or she goes back to the centre. Everything
 * around the edges of tournament carrom - the due, the board fouls, the three
 * consecutive fouls, the last-coin rule - is not here. This is the game two
 * people play on a table, not the one with an umpire.
 */
import {
  BOARD,
  COIN_RADIUS,
  STRIKER_RADIUS,
  simulate,
  striker as makeStriker,
  type Piece,
  type ShotResult,
} from './carrom-physics';
import type { GameRules, GameState } from './types';

/** Nine a side, the queen, and the striker - in that order, always. */
export const WHITE = [0, 1, 2, 3, 4, 5, 6, 7, 8];
export const BLACK = [9, 10, 11, 12, 13, 14, 15, 16, 17];
export const QUEEN = 18;
export const STRIKER = 19;
export const PIECES = 20;

/** Three numbers per piece - x, y, still-on-the-board - then the tail below. */
const TAIL = PIECES * 3;
/** Which seat owns the queen, or -1. */
const QUEEN_OWNER = TAIL;
/** Which seat pocketed the queen and has yet to cover her, or -1. */
const QUEEN_PENDING = TAIL + 1;
/** The shot that produced this board: seat, striker x, angle, power. */
const SHOT_SEAT = TAIL + 2;
const SHOT_X = TAIL + 3;
const SHOT_ANGLE = TAIL + 4;
const SHOT_POWER = TAIL + 5;
/** Whether that shot was a foul, so the board can say so without re-deciding. */
const SHOT_FOUL = TAIL + 6;
const DATA_LENGTH = TAIL + 7;

/** How far the baseline sits from the near edge. */
export const BASELINE = 0.115;
/** How far along the baseline the striker may be placed, either way of centre. */
export const BASELINE_HALF_WIDTH = 0.25;

/** The slowest and fastest a striker may be sent, in board-widths per second. */
const MIN_SPEED = 0.35;
const MAX_SPEED = 2.6;

/** The queen counts three, as she does everywhere. */
export const QUEEN_VALUE = 3;

function create(): GameState {
  const data = Array<number>(DATA_LENGTH).fill(0);
  const centre = BOARD / 2;

  // The standard opening circle: the queen in the middle, six alternating men
  // around her touching, then twelve alternating around those. Built from the
  // geometry rather than from a table of coordinates, so it stays right if the
  // coin size ever changes.
  const layout: { index: number; x: number; y: number }[] = [];
  layout.push({ index: QUEEN, x: centre, y: centre });

  let white = 0;
  let black = 0;
  const rings: { count: number; radius: number; offset: number }[] = [
    { count: 6, radius: COIN_RADIUS * 2, offset: 0 },
    { count: 12, radius: COIN_RADIUS * 4, offset: Math.PI / 12 },
  ];
  for (const ring of rings) {
    for (let i = 0; i < ring.count; i += 1) {
      const angle = ring.offset + (i * 2 * Math.PI) / ring.count;
      // Alternating, which is what makes a break scatter both colours.
      const index = i % 2 === 0 ? WHITE[white++]! : BLACK[black++]!;
      layout.push({
        index,
        x: centre + Math.cos(angle) * ring.radius,
        y: centre + Math.sin(angle) * ring.radius,
      });
    }
  }

  for (const piece of layout) {
    data[piece.index * 3] = piece.x;
    data[piece.index * 3 + 1] = piece.y;
    data[piece.index * 3 + 2] = 1;
  }
  // The striker starts off the board: it is placed by whoever is shooting, and
  // a striker sitting on the baseline before anybody has aimed is a coin in the
  // way of the break.
  data[STRIKER * 3] = centre;
  data[STRIKER * 3 + 1] = BOARD - BASELINE;
  data[STRIKER * 3 + 2] = 0;

  data[QUEEN_OWNER] = -1;
  data[QUEEN_PENDING] = -1;
  data[SHOT_SEAT] = -1;
  data[SHOT_FOUL] = 0;

  return {
    gameId: 'carrom',
    cells: [],
    boxes: [],
    data,
    turn: 0,
    winner: null,
    lastMove: null,
    moveCount: 0,
  };
}

/** The board as the physics wants it: twenty pieces, striker last. */
export function carromPieces(state: GameState): Piece[] {
  const pieces: Piece[] = [];
  for (let index = 0; index < PIECES; index += 1) {
    const radius = index === STRIKER ? STRIKER_RADIUS : COIN_RADIUS;
    pieces.push({
      x: state.data[index * 3] ?? 0,
      y: state.data[index * 3 + 1] ?? 0,
      vx: 0,
      vy: 0,
      radius,
      mass: index === STRIKER ? 15 : 5.5,
      onBoard: (state.data[index * 3 + 2] ?? 0) === 1,
    });
  }
  return pieces;
}

/** Which colour a seat plays. Seat 0 is white, as it is on a real board. */
export function coinsOf(seat: number): number[] {
  return seat === 0 ? WHITE : BLACK;
}

/** The line a seat shoots from: the near edge, from their point of view. */
export function baselineY(seat: number): number {
  return seat === 0 ? BOARD - BASELINE : BASELINE;
}

/** Which seat holds the queen, or -1 while she is on the board. */
export function queenOwner(state: GameState): number {
  return state.data[QUEEN_OWNER] ?? -1;
}

/** Which seat has pocketed the queen and still has to cover her, or -1. */
export function queenPending(state: GameState): number {
  return state.data[QUEEN_PENDING] ?? -1;
}

/** The shot that made this board: seat, x, angle, power - or null at the start. */
export function lastShot(
  state: GameState,
): { seat: number; x: number; angle: number; power: number; foul: boolean } | null {
  const seat = state.data[SHOT_SEAT] ?? -1;
  if (seat < 0) return null;
  return {
    seat,
    x: state.data[SHOT_X] ?? 0,
    angle: state.data[SHOT_ANGLE] ?? 0,
    power: state.data[SHOT_POWER] ?? 0,
    foul: (state.data[SHOT_FOUL] ?? 0) === 1,
  };
}

/**
 * Where the striker ends up when a seat asks for `x` along its baseline.
 *
 * Clamped rather than refused, and then nudged clear of anything sitting in the
 * way: a striker placed inside a coin is a shot that begins by exploding, and
 * a refusal here would be a legal-looking aim that silently does nothing.
 */
export function placeStriker(state: GameState, seat: number, x: number): { x: number; y: number } {
  const clamped = Math.max(-1, Math.min(1, Number.isFinite(x) ? x : 0));
  const y = baselineY(seat);
  const wanted = BOARD / 2 + clamped * BASELINE_HALF_WIDTH;

  const blocked = (at: number): boolean => {
    for (let index = 0; index < PIECES; index += 1) {
      if (index === STRIKER) continue;
      if ((state.data[index * 3 + 2] ?? 0) !== 1) continue;
      const dx = (state.data[index * 3] ?? 0) - at;
      const dy = (state.data[index * 3 + 1] ?? 0) - y;
      const reach = COIN_RADIUS + STRIKER_RADIUS;
      if (dx * dx + dy * dy < reach * reach) return true;
    }
    return false;
  };

  if (!blocked(wanted)) return { x: wanted, y };
  // Out from where they asked, both ways, in coin-widths. The first free spot
  // wins, so the striker lands as near as it can to the aim that was taken.
  for (let step = 1; step <= 40; step += 1) {
    const offset = step * COIN_RADIUS * 0.5;
    for (const candidate of [wanted - offset, wanted + offset]) {
      const limit = BOARD / 2 + BASELINE_HALF_WIDTH;
      if (candidate < BOARD / 2 - BASELINE_HALF_WIDTH || candidate > limit) continue;
      if (!blocked(candidate)) return { x: candidate, y };
    }
  }
  return { x: wanted, y };
}

/**
 * The direction a shot actually goes, given the angle asked for.
 *
 * Clamped into the half of the circle that points away from the shooter,
 * because a striker sent backwards is a coin in your own pocket and there is no
 * shot in carrom that means it.
 */
export function aimOf(seat: number, angle: number): { vxUnit: number; vyUnit: number } {
  const safe = Number.isFinite(angle) ? angle : -Math.PI / 2;
  let vx = Math.cos(safe);
  let vy = Math.sin(safe);
  // Seat 0 sits at the bottom of the board and plays up the screen, which is
  // negative y; seat 1 is the other way round.
  const forward = seat === 0 ? -1 : 1;
  if (Math.sign(vy) !== forward) {
    // Reflect rather than refuse: the nearest legal aim is the one along the
    // baseline, which is what a person pointing sideways meant.
    vy = 0.0001 * forward;
    const length = Math.sqrt(vx * vx + vy * vy);
    vx /= length;
    vy /= length;
  }
  return { vxUnit: vx, vyUnit: vy };
}

/**
 * Runs one shot, without deciding anything about the rules.
 *
 * Exported because the client draws with it: given the board before the shot
 * and the three numbers that describe it, this returns the frames the coins
 * actually moved through. The gateway calls the same function for the same
 * reason it applies the same rules - so the last frame a client draws is the
 * board the gateway already sent.
 */
export function carromShot(state: GameState, seat: number, params: number[]): ShotResult {
  const [x = 0, angle = -Math.PI / 2, power = 0.5] = params;
  const place = placeStriker(state, seat, x);
  const { vxUnit, vyUnit } = aimOf(seat, angle);
  const clampedPower = Math.max(0, Math.min(1, Number.isFinite(power) ? power : 0));
  const speed = MIN_SPEED + clampedPower * (MAX_SPEED - MIN_SPEED);

  const pieces = carromPieces(state);
  pieces[STRIKER] = makeStriker(place.x, place.y, vxUnit * speed, vyUnit * speed);
  return simulate(pieces, STRIKER);
}

function writePieces(data: number[], pieces: Piece[]): void {
  for (let index = 0; index < PIECES; index += 1) {
    const piece = pieces[index]!;
    data[index * 3] = piece.x;
    data[index * 3 + 1] = piece.y;
    data[index * 3 + 2] = piece.onBoard ? 1 : 0;
  }
}

/** Puts a coin back near the centre, in the first free spot spiralling out. */
function returnToCentre(data: number[], index: number): void {
  const centre = BOARD / 2;
  const free = (x: number, y: number): boolean => {
    for (let other = 0; other < PIECES; other += 1) {
      if (other === index || other === STRIKER) continue;
      if ((data[other * 3 + 2] ?? 0) !== 1) continue;
      const dx = (data[other * 3] ?? 0) - x;
      const dy = (data[other * 3 + 1] ?? 0) - y;
      if (dx * dx + dy * dy < (COIN_RADIUS * 2) ** 2) return false;
    }
    return true;
  };

  for (let ring = 0; ring < 12; ring += 1) {
    const radius = ring * COIN_RADIUS * 2;
    const points = ring === 0 ? 1 : ring * 6;
    for (let i = 0; i < points; i += 1) {
      const angle = (i * 2 * Math.PI) / points;
      const x = centre + Math.cos(angle) * radius;
      const y = centre + Math.sin(angle) * radius;
      if (free(x, y)) {
        data[index * 3] = x;
        data[index * 3 + 1] = y;
        data[index * 3 + 2] = 1;
        return;
      }
    }
  }
}

function pocketedCount(data: number[], indices: number[]): number {
  return indices.filter((index) => (data[index * 3 + 2] ?? 0) === 0).length;
}

export const carrom: GameRules = {
  definition: {
    id: 'carrom',
    name: 'Carrom',
    blurb: 'Flick the striker, sink your nine, and cover the queen. Real physics.',
    seats: 2,
    seatNames: ['White', 'Black'],
    seatColours: ['#f8fafc', '#334155'],
    length: '15 min',
  },

  aimed: true,

  create,

  // One kind of move - a shot - and the aim rides in `params`. The board draws
  // the aiming line itself, so there is nothing here to enumerate.
  moves: (state) => (state.winner === null ? [0] : []),

  apply: (state, seat, move, params) => {
    if (state.winner !== null) return null;
    if (seat !== state.turn) return null;
    if (move !== 0) return null;
    if (!params || params.length < 3) return null;
    if (!params.every((value) => Number.isFinite(value))) return null;
    // A shot with no power is not a shot. Refusing it beats a turn spent on a
    // striker that did not move.
    if ((params[2] ?? 0) <= 0.02) return null;

    const result = carromShot(state, seat, params);
    const data = [...state.data];
    writePieces(data, result.pieces);

    const mine = coinsOf(seat);
    const minePocketed = result.pocketed.filter((index) => mine.includes(index));
    const strikerDown = result.pocketed.includes(STRIKER);
    const queenDown = result.pocketed.includes(QUEEN);
    // Nothing touched at all: the striker crossed the board and hit nobody.
    // That is a foul everywhere the game is played.
    const foul = strikerDown || !result.contact;

    let owner = data[QUEEN_OWNER] ?? -1;
    let pending = data[QUEEN_PENDING] ?? -1;

    if (queenDown && owner === -1) {
      // Pocketed with one of your own in the same shot: she is covered, and
      // she is yours. Otherwise she waits on the next shot to be covered.
      if (minePocketed.length > 0 && !foul) {
        owner = seat;
        pending = -1;
      } else {
        pending = seat;
      }
    } else if (pending === seat) {
      if (minePocketed.length > 0 && !foul) {
        owner = seat;
        pending = -1;
      } else {
        // Uncovered. She goes back to the middle and the board is as it was
        // before anybody took her.
        returnToCentre(data, QUEEN);
        pending = -1;
      }
    }

    if (strikerDown) {
      // The penalty: one of your own comes back out. Nothing to give back is
      // simply a foul with no coin to pay it with.
      const paid = mine.find((index) => (data[index * 3 + 2] ?? 0) === 0);
      if (paid !== undefined) returnToCentre(data, paid);
    }

    // The striker never stays on the board between shots: it is placed by
    // whoever shoots next, on their own line.
    data[STRIKER * 3 + 2] = 0;

    data[QUEEN_OWNER] = owner;
    data[QUEEN_PENDING] = pending;
    data[SHOT_SEAT] = seat;
    data[SHOT_X] = params[0] ?? 0;
    data[SHOT_ANGLE] = params[1] ?? 0;
    data[SHOT_POWER] = params[2] ?? 0;
    data[SHOT_FOUL] = foul ? 1 : 0;

    // Pocket one of yours and you shoot again - which is the whole rhythm of
    // the game, and the reason a good player's turn lasts a while.
    const again = !foul && minePocketed.length > 0;

    const cleared = pocketedCount(data, mine) === mine.length;
    // Clearing your colour wins it. A tournament would make you take the queen
    // before your last coin; here she is awarded to whoever clears if she is
    // still unclaimed, which keeps the game from ending with nobody holding
    // her.
    let winner: number | null = null;
    if (cleared) {
      if (owner === -1) {
        owner = seat;
        data[QUEEN_OWNER] = seat;
        data[QUEEN_PENDING] = -1;
        data[QUEEN * 3 + 2] = 0;
      }
      winner = seat;
    }

    return {
      ...state,
      data,
      turn: again ? seat : seat === 0 ? 1 : 0,
      winner,
      lastMove: 0,
      moveCount: state.moveCount + 1,
    };
  },

  score: (state) => {
    const owner = state.data[QUEEN_OWNER] ?? -1;
    return [0, 1].map(
      (seat) =>
        pocketedCount(state.data, coinsOf(seat)) + (owner === seat ? QUEEN_VALUE : 0),
    );
  },
};

/**
 * Connect Four: seven columns, six rows, four in a line.
 *
 * The move is a *column*, not a square, which is the one thing about this game
 * that has to be right in a shared board: two people clicking the same column
 * within a moment of each other must produce two discs stacked, never two discs
 * in one hole. Sending a square would make that a race the gateway could not
 * see - it would receive two legal-looking placements. Sending a column makes
 * the second click land on top of the first, because the drop is computed after
 * the ordering rather than before it.
 */
import type { GameRules, GameState } from './types';

export const COLUMNS = 7;
export const ROWS = 6;

/** Index of the square at row `r` (0 is the top), column `c`. */
export function at(r: number, c: number): number {
  return r * COLUMNS + c;
}

function create(): GameState {
  return {
    gameId: 'connect-four',
    cells: Array<number>(COLUMNS * ROWS).fill(-1),
    boxes: [],
    data: [],
    turn: 0,
    winner: null,
    lastMove: null,
    moveCount: 0,
  };
}

/** The lowest empty row in a column, or -1 when it is full. */
export function landing(cells: number[], column: number): number {
  for (let r = ROWS - 1; r >= 0; r -= 1) {
    if (cells[at(r, column)] === -1) return r;
  }
  return -1;
}

/** The four squares that won it, or null - so the board can light them up. */
export function winningRun(cells: number[], from: number): number[] | null {
  const owner = cells[from];
  if (owner === undefined || owner === -1) return null;
  const r0 = Math.floor(from / COLUMNS);
  const c0 = from % COLUMNS;

  // Only the four directions, each explored both ways: a run through the last
  // disc is the only run that can be new, which is why this takes `from`
  // rather than sweeping the whole board on every move.
  for (const [dr, dc] of [
    [0, 1],
    [1, 0],
    [1, 1],
    [1, -1],
  ]) {
    const run = [from];
    for (const sign of [1, -1]) {
      let r = r0 + dr! * sign;
      let c = c0 + dc! * sign;
      while (r >= 0 && r < ROWS && c >= 0 && c < COLUMNS && cells[at(r, c)] === owner) {
        run.push(at(r, c));
        r += dr! * sign;
        c += dc! * sign;
      }
    }
    if (run.length >= 4) return run;
  }
  return null;
}

export const connectFour: GameRules = {
  definition: {
    id: 'connect-four',
    name: 'Connect Four',
    blurb: 'Drop a disc, take a column, get four in a line before they do.',
    seats: 2,
    seatNames: ['Red', 'Yellow'],
    seatColours: ['#f43f5e', '#facc15'],
    length: '5 min',
  },

  create,

  moves: (state) => {
    if (state.winner !== null) return [];
    const open: number[] = [];
    for (let c = 0; c < COLUMNS; c += 1) if (landing(state.cells, c) !== -1) open.push(c);
    return open;
  },

  apply: (state, seat, move) => {
    if (state.winner !== null) return null;
    if (seat !== state.turn) return null;
    if (!Number.isInteger(move) || move < 0 || move >= COLUMNS) return null;

    const row = landing(state.cells, move);
    if (row === -1) return null;

    const square = at(row, move);
    const cells = [...state.cells];
    cells[square] = seat;
    const moveCount = state.moveCount + 1;
    const won = winningRun(cells, square) !== null;
    return {
      ...state,
      cells,
      winner: won ? seat : moveCount === COLUMNS * ROWS ? -1 : null,
      turn: seat === 0 ? 1 : 0,
      lastMove: square,
      moveCount,
    };
  },

  score: (state) => [
    state.cells.filter((owner) => owner === 0).length,
    state.cells.filter((owner) => owner === 1).length,
  ],
};

/**
 * Dots and Boxes: draw a line between two dots, close a square, go again.
 *
 * The board is a 5x5 grid of dots, so a move is one of the forty lines between
 * them and the prize is one of the sixteen squares. `cells` holds the lines and
 * `boxes` holds the squares, which is the one game in the library that needs
 * both halves of `GameState` - see the note on that type.
 *
 * Closing a box means playing again, and that is the rule that makes the game:
 * a chain of five boxes is five moves in a row and the reason the endgame is
 * the whole endgame. It is also the rule a naive "alternate the turn" reducer
 * silently loses, which is why the turn here is decided by what the move did.
 */
import type { GameRules, GameState } from './types';

/** Dots per side. Boxes per side is one less. */
export const DOTS = 5;
export const CELLS = DOTS - 1;
/** Lines across the top of a row of boxes: `DOTS` rows of `CELLS`. */
export const HORIZONTALS = DOTS * CELLS;
export const LINES = HORIZONTALS * 2;

/** The horizontal line below dot-row `r`, at column `c`. */
export function horizontal(r: number, c: number): number {
  return r * CELLS + c;
}

/** The vertical line right of dot-column `c`, in row `r`. */
export function vertical(r: number, c: number): number {
  return HORIZONTALS + r * DOTS + c;
}

/** The four lines around box (r, c): top, bottom, left, right. */
export function boxLines(r: number, c: number): number[] {
  return [horizontal(r, c), horizontal(r + 1, c), vertical(r, c), vertical(r, c + 1)];
}

function create(): GameState {
  return {
    gameId: 'dots-and-boxes',
    cells: Array<number>(LINES).fill(-1),
    boxes: Array<number>(CELLS * CELLS).fill(-1),
    data: [],
    turn: 0,
    winner: null,
    lastMove: null,
    moveCount: 0,
  };
}

function counts(boxes: number[]): number[] {
  return [
    boxes.filter((owner) => owner === 0).length,
    boxes.filter((owner) => owner === 1).length,
  ];
}

export const dotsAndBoxes: GameRules = {
  definition: {
    id: 'dots-and-boxes',
    name: 'Dots and Boxes',
    blurb: 'Join the dots. Close a square and you go again - so save the chains.',
    seats: 2,
    seatNames: ['Blue', 'Green'],
    seatColours: ['#60a5fa', '#4ade80'],
    length: '10 min',
  },

  create,

  moves: (state) => {
    if (state.winner !== null) return [];
    return state.cells.flatMap((owner, index) => (owner === -1 ? [index] : []));
  },

  apply: (state, seat, move) => {
    if (state.winner !== null) return null;
    if (seat !== state.turn) return null;
    if (!Number.isInteger(move) || move < 0 || move >= LINES) return null;
    if (state.cells[move] !== -1) return null;

    const cells = [...state.cells];
    cells[move] = seat;

    // A line can close two boxes at once - the one either side of it - and
    // both belong to whoever drew it.
    const boxes = [...state.boxes];
    let claimed = 0;
    for (let r = 0; r < CELLS; r += 1) {
      for (let c = 0; c < CELLS; c += 1) {
        const index = r * CELLS + c;
        if (boxes[index] !== -1) continue;
        if (boxLines(r, c).every((line) => cells[line] !== -1)) {
          boxes[index] = seat;
          claimed += 1;
        }
      }
    }

    const finished = cells.every((owner) => owner !== -1);
    const [blue, green] = counts(boxes);

    return {
      ...state,
      cells,
      boxes,
      // Closing a box is another go. This is the whole game.
      turn: claimed > 0 ? seat : seat === 0 ? 1 : 0,
      winner: !finished ? null : blue! === green! ? -1 : blue! > green! ? 0 : 1,
      lastMove: move,
      moveCount: state.moveCount + 1,
    };
  },

  score: (state) => counts(state.boxes),
};

