    "typescript": "^5.5.4"
  }
}

/** Self-check: `pnpm --filter @betweenus/storage check`. Driver choice, traversal, round-trip. */
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { utimes } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import {
  LocalStorageDriver,
  assertPartNumber,
  assertSafeKey,
  buildKey,
  detectPictureType,
  detectVideoType,
  getStorage,
  isAllowedPicture,
  isInlineSafe,
  isS3Configured,
  setStorage,
} from './index';

async function main(): Promise<void> {
  // --- Driver selection: empty S3 config must fall back to local disk.
  for (const key of ['S3_ENDPOINT', 'S3_ACCESS_KEY', 'S3_SECRET_KEY', 'S3_BUCKET']) {
    delete process.env[key];
  }
  delete process.env.STORAGE_DRIVER;
  assert.equal(isS3Configured(), false);
  setStorage(null);
  assert.equal(getStorage().name, 'local');

  // A partially filled S3 config is still not configured - no half-broken S3.
  process.env.S3_ENDPOINT = 'http://localhost:9000';
  process.env.S3_BUCKET = 'betweenus';
  assert.equal(isS3Configured(), false);
  setStorage(null);
  assert.equal(getStorage().name, 'local');

  process.env.S3_ACCESS_KEY = 'key';
  process.env.S3_SECRET_KEY = 'secret';
  assert.equal(isS3Configured(), true);
  setStorage(null);
  assert.equal(getStorage().name, 's3');

  // Forcing local must win over a complete S3 config.
  process.env.STORAGE_DRIVER = 'local';
  setStorage(null);
  assert.equal(getStorage().name, 'local');

  // Forcing s3 without credentials must fail loudly, not fall back silently.
  process.env.STORAGE_DRIVER = 's3';
  delete process.env.S3_ACCESS_KEY;
  setStorage(null);
  assert.throws(() => getStorage(), /requires S3_ENDPOINT/);
  delete process.env.STORAGE_DRIVER;
  setStorage(null);

  // --- Key safety.
  assert.throws(() => assertSafeKey('../../etc/passwd'));
  assert.throws(() => assertSafeKey('/etc/passwd'));
  assert.throws(() => assertSafeKey('C:\\windows\\system32'));
  assert.throws(() => assertSafeKey(''));
  assertSafeKey('attachments/2026-08/abc.png');

  const key = buildKey('attachments/user-1', 'holiday photo.PNG');
  assert.match(key, /^attachments\/user-1\/\d{4}-\d{2}\/[0-9a-f-]{36}\.png$/);
  // The original filename must not survive into the key.
  assert.equal(key.includes('holiday'), false);

  // --- Local round-trip.
  const root = mkdtempSync(join(tmpdir(), 'betweenus-storage-'));
  try {
    const local = new LocalStorageDriver(root, '/api/v1/uploads');
    const stored = await local.put(key, Buffer.from('hello world'), 'image/png');
    assert.equal(stored.size, 11);
    assert.equal(stored.url, `/api/v1/uploads/${key}`);
    assert.equal(await local.exists(key), true);

    const chunks: Buffer[] = [];
    for await (const chunk of await local.get(key)) chunks.push(Buffer.from(chunk as Buffer));
    assert.equal(Buffer.concat(chunks).toString(), 'hello world');

    await local.delete(key);
    assert.equal(await local.exists(key), false);

    // Traversal must be refused by the driver, not just by the key check.
    await assert.rejects(local.put('../escape.txt', Buffer.from('x'), 'text/plain'));

    // --- Multipart round-trip: the object is the parts concatenated in part
    // order, whatever order they were uploaded or listed in.
    const bigKey = buildKey('attachments/user-1', 'movie.bin');
    const session = await local.createMultipart(bigKey, 'application/octet-stream');
    const third = await local.uploadPart(session, 3, Buffer.from('ccc'));
    const first = await local.uploadPart(session, 1, Buffer.from('aaa'));
    const second = await local.uploadPart(session, 2, Buffer.from('bbb'));

    const assembled = await local.completeMultipart(session, [third, first, second]);
    assert.equal(assembled.size, 9);
    const parts: Buffer[] = [];
    for await (const chunk of await local.get(bigKey)) parts.push(Buffer.from(chunk as Buffer));
    assert.equal(Buffer.concat(parts).toString(), 'aaabbbccc');

    // Completing must leave no scratch parts behind.
    assert.equal(await local.exists(`.multipart/${session.externalId}/00001`), false);

    // A fresh upload survives the sweep; the same one, aged, does not.
    const abandoned = await local.createMultipart(bigKey, 'application/octet-stream');
    await local.uploadPart(abandoned, 1, Buffer.from('x'));
    assert.equal(await local.sweepStaleMultipart(60_000), 0);

    await utimes(join(root, '.multipart', abandoned.externalId), new Date(0), new Date(0));
    assert.equal(await local.sweepStaleMultipart(60_000), 1);

    await assert.rejects(local.completeMultipart(session, []));
    assert.throws(() => assertPartNumber(0));
    assert.throws(() => assertPartNumber(10_001));
    assert.throws(() => assertPartNumber(1.5));
    assertPartNumber(1);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }

  // --- Upload policy.
  assert.equal(isAllowedPicture('image/png'), true);
  assert.equal(isAllowedPicture('image/png; charset=binary'), true);
  // A picture is served inline, so a script container is not a picture.
  assert.equal(isAllowedPicture('image/svg+xml'), false);
  assert.equal(isAllowedPicture('application/x-msdownload'), false);
  assert.equal(isInlineSafe('image/png'), true);
  assert.equal(isInlineSafe('image/svg+xml'), false);
  assert.equal(isInlineSafe('application/pdf'), false);

  // --- What a picture actually is.
  //
  // The header the client attached is not consulted any more, so everything
  // below is about bytes. The four that are accepted, and then the ones that
  // matter more: the shapes that used to get in by saying `image/png`.
  const png = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0]);
  const jpeg = Buffer.from([0xff, 0xd8, 0xff, 0xe0, 0, 0]);
  const gif87 = Buffer.from('GIF87a....', 'binary');
  const gif89 = Buffer.from('GIF89a....', 'binary');
  const webp = Buffer.concat([
    Buffer.from('RIFF', 'binary'),
    Buffer.from([0x24, 0x00, 0x00, 0x00]),
    Buffer.from('WEBP', 'binary'),
  ]);

  assert.deepEqual(detectPictureType(png), { contentType: 'image/png', extension: '.png' });
  assert.deepEqual(detectPictureType(jpeg), { contentType: 'image/jpeg', extension: '.jpg' });
  assert.deepEqual(detectPictureType(gif87), { contentType: 'image/gif', extension: '.gif' });
  assert.deepEqual(detectPictureType(gif89), { contentType: 'image/gif', extension: '.gif' });
  assert.deepEqual(detectPictureType(webp), { contentType: 'image/webp', extension: '.webp' });

  // Whatever the picture claims to be, its type comes out of its bytes - so the
  // key's extension and the stored content type agree with each other and with
  // the file, by construction rather than by a client's good manners.
  assert.equal(detectPictureType(png)?.contentType, 'image/png');
  assert.equal(detectPictureType(jpeg)?.extension, '.jpg');

  // An SVG is the one the allowlist named and this refuses without naming: it
  // has no binary signature, so it gets in only if somebody teaches this
  // function to recognise it.
  assert.equal(detectPictureType(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"/>')), null);
  assert.equal(detectPictureType(Buffer.from('<?xml version="1.0"?><svg/>')), null);

  // An HTML file, which is the other thing worth serving to nobody.
  assert.equal(detectPictureType(Buffer.from('<!doctype html><script>alert(1)</script>')), null);

  // A Windows executable, and a zip - both of which the old check accepted the
  // moment their uploader typed `image/png` into the form.
  assert.equal(detectPictureType(Buffer.from([0x4d, 0x5a, 0x90, 0x00])), null);
  assert.equal(detectPictureType(Buffer.from([0x50, 0x4b, 0x03, 0x04])), null);

  // Nothing at all, and not-quite-enough. A signature check that reads past the
  // end of a short buffer is a crash on an empty upload.
  assert.equal(detectPictureType(Buffer.alloc(0)), null);
  assert.equal(detectPictureType(Buffer.from([0x89, 0x50])), null);
  assert.equal(detectPictureType(Buffer.from([0xff, 0xd8])), null);

  // "RIFF" alone is a container, not a WebP - a WAV file starts the same way.
  assert.equal(
    detectPictureType(
      Buffer.concat([
        Buffer.from('RIFF', 'binary'),
        Buffer.from([0x24, 0x00, 0x00, 0x00]),
        Buffer.from('WAVE', 'binary'),
      ]),
    ),
    null,
  );

  // A picture with something appended is still that picture. This is deliberate:
  // the signature says what a renderer will do with the first bytes, and trailing
  // junk is a corrupt file rather than a different type. Worth pinning so nobody
  // "fixes" it into a whole-file parser.
  assert.equal(
    detectPictureType(Buffer.concat([png, Buffer.from('<script>alert(1)</script>')]))?.contentType,
    'image/png',
  );

  // --- Video signatures, for status posts.
  const mp4 = Buffer.concat([
    Buffer.from([0x00, 0x00, 0x00, 0x18]),
    Buffer.from('ftypmp42'),
  ]);
  const webm = Buffer.from([0x1a, 0x45, 0xdf, 0xa3, 0x01, 0x00, 0x00, 0x00]);
  assert.deepEqual(detectVideoType(mp4), { contentType: 'video/mp4', extension: '.mp4' });
  assert.deepEqual(detectVideoType(webm), { contentType: 'video/webm', extension: '.webm' });
  // A picture is not a video and a video is not a picture: the status route
  // picks one detector per kind, and each must refuse the other's bytes.
  assert.equal(detectVideoType(png), null);
  assert.equal(detectPictureType(mp4), null);
  // Not a container at all, and too short to be one.
  assert.equal(detectVideoType(Buffer.from('<!doctype html>')), null);
  assert.equal(detectVideoType(Buffer.from([0x1a, 0x45])), null);

  console.log('storage check ok');
}

void main();

/**
 * Object storage with a local-disk fallback.
 *
 * S3 is the target for production, but a developer should not need MinIO or an
 * AWS account to upload an avatar. When the S3 variables are empty the local
 * driver writes under `LOCAL_STORAGE_PATH` instead; both drivers expose the
 * same interface, so nothing above this package knows which is active.
 */
import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, readdir, rm, stat } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, extname, join, normalize, resolve, sep } from 'node:path';
import { pipeline } from 'node:stream/promises';
import { Readable } from 'node:stream';
import { env, envOr } from '@betweenus/config';

export interface StoredObject {
  /** Storage key, e.g. `attachments/2026/ab12….png`. Stable across drivers. */
  key: string;
  size: number;
  contentType: string;
  /** Path the client fetches. Local driver serves it from the owning service. */
  url: string;
}

/**
 * A multipart upload in progress. `externalId` is S3's upload id; the local
 * driver puts its own scratch-directory id there. The whole thing is handed
 * back to the client inside a sealed ticket, so no service holds session state
 * in memory and any replica can accept the next part.
 */
export interface MultipartSession {
  key: string;
  contentType: string;
  externalId: string;
}

export interface UploadedPart {
  /** 1-based, in the order the parts have to be concatenated. */
  partNumber: number;
  etag: string;
}

export interface StorageDriver {
  readonly name: 'local' | 's3';
  put(key: string, body: Buffer | Readable, contentType: string): Promise<StoredObject>;
  get(key: string): Promise<Readable>;
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
  urlFor(key: string): string;

  createMultipart(key: string, contentType: string): Promise<MultipartSession>;
  uploadPart(session: MultipartSession, partNumber: number, body: Buffer): Promise<UploadedPart>;
  completeMultipart(session: MultipartSession, parts: UploadedPart[]): Promise<StoredObject>;
  abortMultipart(session: MultipartSession): Promise<void>;
}

/**
 * Part numbers are S3's: 1-based and capped at 10 000. The same range is
 * enforced for the local driver so a file that uploads in development does not
 * fail the first time the deployment switches to a bucket.
 */
export function assertPartNumber(partNumber: number): void {
  if (!Number.isInteger(partNumber) || partNumber < 1 || partNumber > 10_000) {
    throw new Error(`Invalid part number: ${partNumber}`);
  }
}

/** Parts, deduplicated and in upload order, or a throw if any is missing. */
function orderParts(parts: UploadedPart[]): UploadedPart[] {
  if (parts.length === 0) throw new Error('A multipart upload needs at least one part');
  const byNumber = new Map<number, UploadedPart>();
  for (const part of parts) {
    assertPartNumber(part.partNumber);
    byNumber.set(part.partNumber, part);
  }
  return [...byNumber.values()].sort((a, b) => a.partNumber - b.partNumber);
}

/** Keys are generated, never taken from the client filename. */
export function buildKey(prefix: string, originalName: string): string {
  const extension = extname(originalName).toLowerCase().replace(/[^a-z0-9.]/g, '').slice(0, 10);
  const now = new Date();
  return `${prefix}/${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}/${randomUUID()}${extension}`;
}

/**
 * Rejects keys that would escape the storage root. Belt and braces: keys are
 * generated internally, but this is the boundary that must not be crossed.
 */
export function assertSafeKey(key: string): void {
  const normalized = normalize(key);
  if (
    key.length === 0 ||
    key.length > 512 ||
    normalized.startsWith('..') ||
    normalized.includes(`..${sep}`) ||
    normalized.startsWith(sep) ||
    /^[a-zA-Z]:/.test(normalized) ||
    key.includes('\0')
  ) {
    throw new Error(`Unsafe storage key: ${key}`);
  }
}

export class LocalStorageDriver implements StorageDriver {
  readonly name = 'local' as const;
  private readonly root: string;

  constructor(
    root: string,
    private readonly publicPrefix: string,
  ) {
    this.root = resolve(root);
  }

  private pathFor(key: string): string {
    assertSafeKey(key);
    const full = resolve(join(this.root, key));
    // resolve() collapses traversal; verify the result is still inside root.
    if (full !== this.root && !full.startsWith(this.root + sep)) {
      throw new Error(`Unsafe storage key: ${key}`);
    }
    return full;
  }

  async put(key: string, body: Buffer | Readable, contentType: string): Promise<StoredObject> {
    const target = this.pathFor(key);
    await mkdir(dirname(target), { recursive: true });

    if (Buffer.isBuffer(body)) {
      await pipeline(bufferToStream(body), createWriteStream(target));
    } else {
      await pipeline(body, createWriteStream(target));
    }

    const info = await stat(target);
    return { key, size: info.size, contentType, url: this.urlFor(key) };
  }

  async get(key: string): Promise<Readable> {
    return createReadStream(this.pathFor(key));
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }

  async exists(key: string): Promise<boolean> {
    try {
      await stat(this.pathFor(key));
      return true;
    } catch {
      return false;
    }
  }

  urlFor(key: string): string {
    return `${this.publicPrefix}/${key}`;
  }

  // --- Multipart ------------------------------------------------------------
  //
  // Parts are ordinary files under a scratch directory named after the upload;
  // completing concatenates them into the real key in part order. Nothing here
  // has to survive a restart: an abandoned upload leaves a scratch directory
  // that `sweepStaleMultipart` clears out.

  private partKey(session: MultipartSession, partNumber: number): string {
    return `${MULTIPART_PREFIX}/${session.externalId}/${String(partNumber).padStart(5, '0')}`;
  }

  async createMultipart(key: string, contentType: string): Promise<MultipartSession> {
    assertSafeKey(key);
    const session = { key, contentType, externalId: randomUUID() };
    await mkdir(dirname(this.pathFor(this.partKey(session, 1))), { recursive: true });
    return session;
  }

  async uploadPart(
    session: MultipartSession,
    partNumber: number,
    body: Buffer,
  ): Promise<UploadedPart> {
    assertPartNumber(partNumber);
    const target = this.pathFor(this.partKey(session, partNumber));
    await mkdir(dirname(target), { recursive: true });
    await pipeline(bufferToStream(body), createWriteStream(target));
    // The local driver has no ETag of its own; the size is enough to notice a
    // part that never arrived, and S3 is the only place the value is checked.
    return { partNumber, etag: `${partNumber}-${body.length}` };
  }

  async completeMultipart(
    session: MultipartSession,
    parts: UploadedPart[],
  ): Promise<StoredObject> {
    const ordered = orderParts(parts);
    const target = this.pathFor(session.key);
    await mkdir(dirname(target), { recursive: true });

    const output = createWriteStream(target);
    try {
      for (const part of ordered) {
        // `end: false` keeps the handle open across parts; the file is the
        // parts concatenated, in order, with nothing between them.
        await pipeline(createReadStream(this.pathFor(this.partKey(session, part.partNumber))), output, {
          end: false,
        });
      }
    } finally {
      output.end();
    }
    await new Promise<void>((resolve, reject) => {
      output.on('finish', resolve);
      output.on('error', reject);
    });

    await this.abortMultipart(session);
    const info = await stat(target);
    return {
      key: session.key,
      size: info.size,
      contentType: session.contentType,
      url: this.urlFor(session.key),
    };
  }

  async abortMultipart(session: MultipartSession): Promise<void> {
    await rm(this.pathFor(`${MULTIPART_PREFIX}/${session.externalId}`), {
      recursive: true,
      force: true,
    });
  }

  /**
   * Deletes scratch directories older than `maxAgeMs`. An upload the client
   * walked away from leaves its parts on disk otherwise; nothing else ever
   * collects them.
   */
  async sweepStaleMultipart(maxAgeMs: number): Promise<number> {
    const root = this.pathFor(MULTIPART_PREFIX);
    let removed = 0;
    let entries: string[];
    try {
      entries = await readdir(root);
    } catch {
      return 0; // Nothing has ever been uploaded in parts here.
    }

    for (const entry of entries) {
      const path = join(root, entry);
      try {
        const info = await stat(path);
        if (Date.now() - info.mtimeMs < maxAgeMs) continue;
        await rm(path, { recursive: true, force: true });
        removed += 1;
      } catch {
        // Raced with another sweep or with a completion; either is fine.
      }
    }
    return removed;
  }
}

/** Scratch space for parts. Never served: the download route rejects the prefix. */
export const MULTIPART_PREFIX = '.multipart';

export class S3StorageDriver implements StorageDriver {
  readonly name = 's3' as const;
  // Typed as unknown because @aws-sdk/client-s3 is optional at runtime.
  private client: unknown;

  constructor(
    private readonly config: {
      endpoint: string;
      region: string;
      bucket: string;
      accessKey: string;
      secretKey: string;
      publicUrl: string;
      forcePathStyle: boolean;
    },
  ) {}

  private async sdk(): Promise<typeof import('@aws-sdk/client-s3')> {
    // Dynamic import: local-only installs never need the AWS SDK loaded.
    return import('@aws-sdk/client-s3');
  }

  private async getClient(): Promise<import('@aws-sdk/client-s3').S3Client> {
    if (!this.client) {
      const { S3Client } = await this.sdk();
      this.client = new S3Client({
        endpoint: this.config.endpoint,
        region: this.config.region,
        forcePathStyle: this.config.forcePathStyle,
        credentials: {
          accessKeyId: this.config.accessKey,
          secretAccessKey: this.config.secretKey,
        },
      });
    }
    return this.client as import('@aws-sdk/client-s3').S3Client;
  }

  async put(key: string, body: Buffer | Readable, contentType: string): Promise<StoredObject> {
    assertSafeKey(key);
    const { PutObjectCommand } = await this.sdk();
    const client = await this.getClient();
    const buffer = Buffer.isBuffer(body) ? body : await streamToBuffer(body);

    await client.send(
      new PutObjectCommand({
        Bucket: this.config.bucket,
        Key: key,
        Body: buffer,
        ContentType: contentType,
      }),
    );

    return { key, size: buffer.length, contentType, url: this.urlFor(key) };
  }

  async get(key: string): Promise<Readable> {
    assertSafeKey(key);
    const { GetObjectCommand } = await this.sdk();
    const client = await this.getClient();
    const result = await client.send(
      new GetObjectCommand({ Bucket: this.config.bucket, Key: key }),
    );
    return result.Body as Readable;
  }

  async delete(key: string): Promise<void> {
    assertSafeKey(key);
    const { DeleteObjectCommand } = await this.sdk();
    const client = await this.getClient();
    await client.send(new DeleteObjectCommand({ Bucket: this.config.bucket, Key: key }));
  }

  async exists(key: string): Promise<boolean> {
    assertSafeKey(key);
    const { HeadObjectCommand } = await this.sdk();
    const client = await this.getClient();
    try {
      await client.send(new HeadObjectCommand({ Bucket: this.config.bucket, Key: key }));
      return true;
    } catch {
      return false;
    }
  }

  urlFor(key: string): string {
    return `${this.config.publicUrl.replace(/\/$/, '')}/${key}`;
  }

  // --- Multipart ------------------------------------------------------------
  //
  // S3's own multipart API. Every part but the last must be at least 5 MiB,
  // which is why the client's chunk size is well above that.

  async createMultipart(key: string, contentType: string): Promise<MultipartSession> {
    assertSafeKey(key);
    const { CreateMultipartUploadCommand } = await this.sdk();
    const client = await this.getClient();
    const result = await client.send(
      new CreateMultipartUploadCommand({
        Bucket: this.config.bucket,
        Key: key,
        ContentType: contentType,
      }),
    );
    if (!result.UploadId) throw new Error('S3 did not return an upload id');
    return { key, contentType, externalId: result.UploadId };
  }

  async uploadPart(
    session: MultipartSession,
    partNumber: number,
    body: Buffer,
  ): Promise<UploadedPart> {
    assertPartNumber(partNumber);
    const { UploadPartCommand } = await this.sdk();
    const client = await this.getClient();
    const result = await client.send(
      new UploadPartCommand({
        Bucket: this.config.bucket,
        Key: session.key,
        UploadId: session.externalId,
        PartNumber: partNumber,
        Body: body,
      }),
    );
    if (!result.ETag) throw new Error(`S3 did not return an ETag for part ${partNumber}`);
    return { partNumber, etag: result.ETag };
  }

  async completeMultipart(
    session: MultipartSession,
    parts: UploadedPart[],
  ): Promise<StoredObject> {
    const ordered = orderParts(parts);
    const { CompleteMultipartUploadCommand, HeadObjectCommand } = await this.sdk();
    const client = await this.getClient();

    await client.send(
      new CompleteMultipartUploadCommand({
        Bucket: this.config.bucket,
        Key: session.key,
        UploadId: session.externalId,
        MultipartUpload: {
          Parts: ordered.map((part) => ({ PartNumber: part.partNumber, ETag: part.etag })),
        },
      }),
    );

    const head = await client.send(
      new HeadObjectCommand({ Bucket: this.config.bucket, Key: session.key }),
    );
    return {
      key: session.key,
      size: head.ContentLength ?? 0,
      contentType: session.contentType,
      url: this.urlFor(session.key),
    };
  }

  async abortMultipart(session: MultipartSession): Promise<void> {
    const { AbortMultipartUploadCommand } = await this.sdk();
    const client = await this.getClient();
    await client.send(
      new AbortMultipartUploadCommand({
        Bucket: this.config.bucket,
        Key: session.key,
        UploadId: session.externalId,
      }),
    );
  }
}

/** True only when every S3 variable needed to talk to a bucket is present. */
export function isS3Configured(): boolean {
  return Boolean(env('S3_ENDPOINT') && env('S3_ACCESS_KEY') && env('S3_SECRET_KEY') && env('S3_BUCKET'));
}

let cached: StorageDriver | null = null;

/**
 * Picks the driver from the environment: S3 when fully configured, local disk
 * otherwise. `STORAGE_DRIVER=local|s3` forces one; forcing `s3` without the
 * variables is a boot-time error rather than a silent fallback.
 */
export function getStorage(): StorageDriver {
  if (cached) return cached;

  const forced = env('STORAGE_DRIVER');
  const useS3 = forced === 's3' || (forced !== 'local' && isS3Configured());

  if (useS3) {
    if (!isS3Configured()) {
      throw new Error(
        'STORAGE_DRIVER=s3 requires S3_ENDPOINT, S3_ACCESS_KEY, S3_SECRET_KEY and S3_BUCKET',
      );
    }
    cached = new S3StorageDriver({
      endpoint: envOr('S3_ENDPOINT', ''),
      region: envOr('S3_REGION', 'us-east-1'),
      bucket: envOr('S3_BUCKET', 'betweenus'),
      accessKey: envOr('S3_ACCESS_KEY', ''),
      secretKey: envOr('S3_SECRET_KEY', ''),
      publicUrl: envOr('S3_PUBLIC_URL', `${envOr('S3_ENDPOINT', '')}/${envOr('S3_BUCKET', 'betweenus')}`),
      forcePathStyle: envOr('S3_FORCE_PATH_STYLE', 'true') !== 'false',
    });
  } else {
    cached = new LocalStorageDriver(
      envOr('LOCAL_STORAGE_PATH', './storage-data'),
      envOr('LOCAL_STORAGE_PUBLIC_PREFIX', '/api/v1/uploads'),
    );
  }

  return cached;
}

/** Test hook - lets a check swap in a driver without touching the environment. */
export function setStorage(driver: StorageDriver | null): void {
  cached = driver;
}

function bufferToStream(buffer: Buffer): Readable {
  return Readable.from(buffer);
}

async function streamToBuffer(stream: Readable): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of stream) chunks.push(Buffer.from(chunk as Buffer));
  return Buffer.concat(chunks);
}

// --- Upload policy ----------------------------------------------------------
//
// Two kinds of object, with two different rules.
//
// *Pictures* - avatars and server icons - are stored in the clear, because
// every client that renders a member list has to be able to fetch them without
// holding a channel key. The server therefore has to care what they are: only
// raster image types, and small.
//
// *Attachments* are ciphertext. The client encrypts the file under the channel
// key before it is uploaded, so the bytes here are opaque, the content type is
// always `application/octet-stream`, and there is nothing to allowlist - which
// is what lets a channel carry any file at all. They are never served inline.

/** Ceiling for one request body: a single-shot upload, or one multipart part. */
export const MAX_UPLOAD_BYTES = Number(envOr('MAX_UPLOAD_BYTES', String(25 * 1024 * 1024)));

/** Ceiling for a whole attachment, assembled from however many parts. */
export const MAX_ATTACHMENT_BYTES = Number(
  envOr('MAX_ATTACHMENT_BYTES', String(100 * 1024 * 1024)),
);

/** Ceiling for an avatar or a server icon, which the client downscales first. */
export const MAX_PICTURE_BYTES = Number(envOr('MAX_PICTURE_BYTES', String(8 * 1024 * 1024)));

const PICTURE_MIME = new Set(['image/png', 'image/jpeg', 'image/gif', 'image/webp']);

/**
 * Content types accepted for an avatar or a server icon. SVG is deliberately
 * absent: it is a script container, and these are the only objects this server
 * ever serves inline.
 *
 * This answers what a *stored* picture may be. What arrives is decided by
 * `detectPictureType`, which reads the bytes rather than believing the header -
 * see there for why the two are not the same question.
 */
export function isAllowedPicture(contentType: string): boolean {
  return PICTURE_MIME.has(contentType.split(';')[0]?.trim().toLowerCase() ?? '');
}

/** What a picture turned out to be, once somebody looked at it. */
export interface PictureType {
  /** The content type it is stored and served as. */
  contentType: string;
  /** The extension its key gets, including the dot. */
  extension: string;
}

/**
 * The signatures this server recognises, longest first so a prefix cannot win
 * over a longer match. `null` in a pattern is a byte that may be anything.
 */
const PICTURE_SIGNATURES: Array<{ bytes: Array<number | null>; offset: number; type: PictureType }> = [
  // \x89 P N G \r \n \x1a \n - eight bytes chosen by its authors to catch
  // exactly the transfer mangling this kind of check is otherwise blind to.
  {
    offset: 0,
    bytes: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
    type: { contentType: 'image/png', extension: '.png' },
  },
  // "RIFF" then four bytes of length then "WEBP". The length is skipped rather
  // than checked: it is the container's business, and a wrong one is a corrupt
  // file rather than a differently-typed one.
  {
    offset: 0,
    bytes: [0x52, 0x49, 0x46, 0x46, null, null, null, null, 0x57, 0x45, 0x42, 0x50],
    type: { contentType: 'image/webp', extension: '.webp' },
  },
  {
    offset: 0,
    bytes: [0x47, 0x49, 0x46, 0x38, 0x37, 0x61], // GIF87a
    type: { contentType: 'image/gif', extension: '.gif' },
  },
  {
    offset: 0,
    bytes: [0x47, 0x49, 0x46, 0x38, 0x39, 0x61], // GIF89a
    type: { contentType: 'image/gif', extension: '.gif' },
  },
  // JPEG has no single magic number, only a start-of-image marker followed by
  // some marker or other. Three bytes is what every implementation uses.
  {
    offset: 0,
    bytes: [0xff, 0xd8, 0xff],
    type: { contentType: 'image/jpeg', extension: '.jpg' },
  },
];

/**
 * What these bytes actually are, or null if they are not a picture this server
 * will store.
 *
 * The upload used to believe the `Content-Type` the client attached, which is a
 * value the client chooses and the server then writes into a key, stores, and
 * hands back with an `<img>`-shaped URL. It was contained rather than
 * exploitable - the download route derives the type from the key's extension and
 * sends `nosniff`, so a file claiming to be a PNG could not become a script by
 * claiming harder - but "contained" is a property of three other decisions all
 * staying as they are, and none of them was written down as load-bearing.
 *
 * Reading the bytes removes the client from the question. The declared type is
 * not checked at all any more, because checking it *as well* would mean two
 * answers that can disagree, and the interesting case - bytes that are not what
 * the header says - is one this refuses whichever way the header points.
 *
 * SVG has no binary signature and therefore no entry here, which is a better
 * outcome than the allowlist that excluded it by name: a format that is a script
 * container gets in only if somebody deliberately teaches this function to
 * recognise it.
 */
export function detectPictureType(bytes: Buffer): PictureType | null {
  for (const signature of PICTURE_SIGNATURES) {
    if (bytes.length < signature.offset + signature.bytes.length) continue;
    const matches = signature.bytes.every(
      (byte, index) => byte === null || bytes[signature.offset + index] === byte,
    );
    if (matches) return signature.type;
  }
  return null;
}

/**
 * The video signatures this server recognises, for status posts.
 *
 * Two containers and no more. Every phone and every browser this app runs on
 * produces one of them, and each extra format here is another decoder a client
 * has to have - a status that will not play on the device it reaches is worse
 * than one that could not be posted.
 *
 * The same rule as `detectPictureType`: the bytes decide, and the declared type
 * is not consulted at all. A status video is served opaque and turned into a
 * blob URL by the client, so this is not defending an `<img>` origin - it is
 * making sure the one place that accepts a large unencrypted upload accepts
 * video and not anything at all.
 */
const VIDEO_SIGNATURES: Array<{ bytes: Array<number | null>; offset: number; type: PictureType }> = [
  // ISO base media: four bytes of box length, then "ftyp". The brand that
  // follows says mp4, m4v, 3gp or quicktime; all of them are the same
  // container and every one of them plays, so the brand is not checked.
  {
    offset: 4,
    bytes: [0x66, 0x74, 0x79, 0x70], // ftyp
    type: { contentType: 'video/mp4', extension: '.mp4' },
  },
  // EBML, which is WebM and Matroska. Distinguishing the two would mean
  // walking the header for the DocType, and a Matroska file that plays is not
  // a problem worth parsing for.
  {
    offset: 0,
    bytes: [0x1a, 0x45, 0xdf, 0xa3],
    type: { contentType: 'video/webm', extension: '.webm' },
  },
];

/** What these bytes are, or null if they are not a video this server stores. */
export function detectVideoType(bytes: Buffer): PictureType | null {
  for (const signature of VIDEO_SIGNATURES) {
    if (bytes.length < signature.offset + signature.bytes.length) continue;
    const matches = signature.bytes.every(
      (byte, index) => byte === null || bytes[signature.offset + index] === byte,
    );
    if (matches) return signature.type;
  }
  return null;
}

/** Content types safe to render inline; everything else downloads. */
export function isInlineSafe(contentType: string): boolean {
  const type = contentType.split(';')[0]?.trim().toLowerCase() ?? '';
  return type.startsWith('image/') && type !== 'image/svg+xml';
}

