/**
 * build-code-reference.mjs
 * Indexes the entire BetweenUs repository: full file tree and complete source code files
 * with their doc comments and symbols for the interactive Code Reference explorer.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, statSync } from 'node:fs';
import { resolve, dirname, extname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const rootDir = resolve(__dirname, '..');

function getLanguage(filePath) {
  const ext = extname(filePath).toLowerCase();
  switch (ext) {
    case '.ts':
    case '.tsx': return 'typescript';
    case '.kt': return 'kotlin';
    case '.prisma': return 'prisma';
    case '.js':
    case '.mjs': return 'javascript';
    case '.json': return 'json';
    case '.yml':
    case '.yaml': return 'yaml';
    case '.md': return 'markdown';
    case '.sh': return 'bash';
    default: return 'text';
  }
}

function getPackageName(filePath) {
  if (filePath.startsWith('apps/services/')) {
    const parts = filePath.split('/');
    return `@betweenus/${parts[2]}`;
  }
  if (filePath.startsWith('apps/android/')) return '@betweenus/android';
  if (filePath.startsWith('apps/desktop/')) return '@betweenus/desktop';
  if (filePath.startsWith('apps/web/')) return '@betweenus/web';
  if (filePath.startsWith('packages/')) {
    const parts = filePath.split('/');
    return `@betweenus/${parts[1]}`;
  }
  if (filePath.startsWith('infrastructure/')) return 'infrastructure';
  if (filePath.startsWith('scripts/')) return 'scripts';
  return 'root';
}

const ignoredDirs = new Set([
  'node_modules', 'dist', 'build', '.git', '.turbo', '.gradle',
  'kspCaches', 'bin', 'obj', 'coverage', '.idea', '.vscode',
  '.system_generated', 'cache', '.agent', '.agents', '.claude',
  '.codegraph', 'storage-data', 'pictures'
]);

function scan(dir, list = []) {
  const abs = resolve(rootDir, dir);
  if (!existsSync(abs)) return list;
  const entries = readdirSync(abs, { withFileTypes: true });
  for (const e of entries) {
    if (e.isDirectory()) {
      if (!ignoredDirs.has(e.name) && !e.name.startsWith('.')) {
        scan(join(dir, e.name), list);
      }
    } else {
      const ext = extname(e.name).toLowerCase();
      if (['.ts', '.tsx', '.kt', '.prisma', '.mjs', '.js', '.json', '.yml', '.yaml', '.md'].includes(ext)) {
        if (
          !e.name.endsWith('.d.ts') &&
          !e.name.endsWith('.map') &&
          !e.name.endsWith('lock.yaml') &&
          !e.name.endsWith('lock.json') &&
          !e.name.includes('codeReferenceData') &&
          !e.name.endsWith('.svg') &&
          !e.name.endsWith('.png') &&
          !e.name.endsWith('.jpeg')
        ) {
          const rel = join(dir, e.name).replace(/\\/g, '/');
          const full = resolve(rootDir, rel);
          const stat = statSync(full);
          // Only index text files under 350KB
          if (stat.size < 350 * 1024) {
            list.push(rel);
          }
        }
      }
    }
  }
  return list;
}

function buildFileTree(files) {
  const root = {
    name: 'Betweenus',
    path: 'Betweenus',
    type: 'directory',
    children: [],
  };

  for (const f of files) {
    const segments = f.path.split('/');
    let current = root;

    for (let i = 0; i < segments.length; i++) {
      const seg = segments[i];
      const isFile = i === segments.length - 1;
      const subPath = 'Betweenus/' + segments.slice(0, i + 1).join('/');

      let existing = current.children.find((c) => c.name === seg);
      if (!existing) {
        existing = {
          name: seg,
          path: subPath,
          type: isFile ? 'file' : 'directory',
          ...(isFile
            ? {
                fileId: f.id,
                language: f.language,
                lineCount: f.lineCount,
                byteSize: f.byteSize,
              }
            : {
                children: [],
              }),
        };
        current.children.push(existing);
      }
      current = existing;
    }
  }

  // Sort directories first, then alphabetical
  function sortNode(node) {
    if (node.children) {
      node.children.sort((a, b) => {
        if (a.type !== b.type) {
          return a.type === 'directory' ? -1 : 1;
        }
        return a.name.localeCompare(b.name);
      });
      node.children.forEach(sortNode);
    }
  }

  sortNode(root);
  return root;
}

export function buildCodeReference() {
  const filePaths = [];
  ['apps', 'packages', 'infrastructure', 'scripts'].forEach((d) => scan(d, filePaths));
  ['package.json', 'turbo.json', 'pnpm-workspace.yaml', 'README.md', 'CLAUDE.md', 'LICENSE'].forEach((f) => {
    if (existsSync(resolve(rootDir, f))) filePaths.push(f);
  });

  const filesResult = [];

  for (const relPath of filePaths) {
    const fullPath = resolve(rootDir, relPath);
    const code = readFileSync(fullPath, 'utf8');
    const lines = code.split('\n');
    const lang = getLanguage(relPath);
    const pkg = getPackageName(relPath);

    const symbols = [];
    let docCommentCount = 0;

    // Fast symbol and comment counting
    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.startsWith('/**') || trimmed.startsWith('///')) {
        docCommentCount++;
      }

      if (lang === 'typescript' || lang === 'javascript') {
        const tsMatch = line.match(/^export\s+(interface|type|class|enum|function|const)\s+([A-Za-z0-9_]+)/);
        if (tsMatch && symbols.length < 50) {
          symbols.push({ kind: tsMatch[1], name: tsMatch[2], lineNumber: idx + 1 });
        }
      } else if (lang === 'prisma') {
        const prismaMatch = line.match(/^(model|enum)\s+([A-Za-z0-9_]+)/);
        if (prismaMatch && symbols.length < 50) {
          symbols.push({ kind: prismaMatch[1], name: prismaMatch[2], lineNumber: idx + 1 });
        }
      } else if (lang === 'kotlin') {
        const ktMatch = line.match(/^(class|sealed\s+interface|interface|data\s+class|object|fun)\s+([A-Za-z0-9_]+)/);
        if (ktMatch && symbols.length < 50) {
          symbols.push({ kind: ktMatch[1], name: ktMatch[2], lineNumber: idx + 1 });
        }
      }
    });

    const fileId = relPath.replace(/[/.]/g, '-');

    filesResult.push({
      id: fileId,
      path: relPath,
      pkg,
      language: lang,
      lineCount: lines.length,
      byteSize: Buffer.byteLength(code, 'utf8'),
      code,
      symbols,
      docCommentCount,
    });
  }

  const fileTree = buildFileTree(filesResult);

  const payload = {
    generatedAt: new Date().toISOString(),
    totalFiles: filesResult.length,
    totalLines: filesResult.reduce((sum, f) => sum + f.lineCount, 0),
    fileTree,
    files: filesResult,
  };

  const outDir = resolve(rootDir, 'docs', 'src', 'data');
  if (!existsSync(outDir)) {
    mkdirSync(outDir, { recursive: true });
  }

  const outPath = resolve(outDir, 'codeReferenceData.json');
  writeFileSync(outPath, JSON.stringify(payload), 'utf8');
  console.log(`[code-reference] Indexed FULL repository: ${filesResult.length} files (${payload.totalLines} lines) -> ${outPath}`);
}

buildCodeReference();

#!/usr/bin/env node
/**
 * One data path for the whole deployment.
 *
 * A deployment says where its data lives once - BETWEENUS_DATA_PATH, or an
 * argument to this script - and this creates the tree under it and writes the
 * four bind paths compose actually mounts back into `.env`:
 *
 *   <root>/data/postgres    the database cluster
 *   <root>/data/redis       the AOF/RDB Redis keeps
 *   <root>/data/media       uploads: pictures/ and attachments/ below it
 *   <root>/backup           pg_dump archives, written by the backup service
 *
 * Compose cannot branch on whether a variable is set, so it interpolates one
 * variable per mount and each of those defaults to a named volume. Deriving
 * them here is what keeps the deployment's side of it a single path, and what
 * keeps a stack that never set one working exactly as before.
 *
 * Usage:
 *   node scripts/data-path.mjs                 # reads BETWEENUS_DATA_PATH from .env
 *   node scripts/data-path.mjs /srv/x/betweenus   # sets it, then does the same
 */
import { chownSync, existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const envFile = join(repoRoot, '.env');

/** The uid every service image runs as. A bind mount is never seeded from the
 *  image, so a root-owned uploads directory means EACCES on every attachment
 *  while the rest of the service works perfectly. */
const SERVICE_UID = 1000;

function readEnvFile() {
  if (!existsSync(envFile)) return { text: '', values: {} };
  const text = readFileSync(envFile, 'utf8');
  const values = {};
  for (const line of text.split(/\r?\n/)) {
    const match = /^\s*([A-Z0-9_]+)\s*=\s*(.*)$/.exec(line);
    if (match) values[match[1]] = match[2].trim().replace(/^["']|["']$/g, '');
  }
  return { text, values };
}

/** Replaces `KEY="value"` in place, or appends it under a header. */
function setEnv(text, key, value) {
  const line = `${key}="${value}"`;
  // `\\s` because this is a template literal: `\s` would be a plain "s" here,
  // and the pattern would then miss an indented or padded assignment.
  const pattern = new RegExp(`^[ \\t]*${key}[ \\t]*=.*$`, 'm');
  // A function replacement, so a `$` in a path is not read as `$1`/`$&`.
  if (pattern.test(text)) return text.replace(pattern, () => line);
  const header = text.includes('# --- Data path (written by scripts/data-path.mjs) ---')
    ? ''
    : '\n# --- Data path (written by scripts/data-path.mjs) ---\n';
  return `${text.replace(/\s*$/, '')}\n${header}${line}\n`;
}

// `node scripts/data-path.mjs --check` - rewriting somebody's .env is the one
// thing here that can quietly lose a value, so that is what is asserted.
if (process.argv.includes('--check')) {
  const { strict: assert } = await import('node:assert');
  assert.equal(setEnv('A="1"\nB="2"\n', 'A', 'x'), 'A="x"\nB="2"\n');
  // An indented or padded assignment is found, and comes back normalised.
  assert.equal(setEnv('  A = 1\n', 'A', 'x'), 'A="x"\n');
  assert.equal(setEnv('A="1"\n', 'A', '/srv/a$b'), 'A="/srv/a$b"\n');
  // A key that is not there is appended once, under one header.
  const first = setEnv('A="1"\n', 'B', '/b');
  assert.match(first, /^A="1"\n\n# --- Data path[^\n]*\nB="\/b"\n$/);
  assert.equal((setEnv(first, 'C', '/c').match(/# --- Data path/g) ?? []).length, 1);
  // A key that merely contains another's name is not mistaken for it.
  assert.equal(setEnv('POSTGRES_DATA_PATH="p"\n', 'DATA_PATH', '/d').includes('POSTGRES_DATA_PATH="p"'), true);
  console.log('data-path.mjs: ok');
  process.exit(0);
}

const { text, values } = readEnvFile();
const root = (process.argv[2] ?? process.env.BETWEENUS_DATA_PATH ?? values.BETWEENUS_DATA_PATH ?? '').trim();

if (!root) {
  console.error(
    'No data path given.\n\n' +
      '  node scripts/data-path.mjs /srv/example/docker/betweenus\n\n' +
      'or set BETWEENUS_DATA_PATH in .env and run it with no argument. Without one\n' +
      'the stack keeps its data in Docker named volumes, which is the default.',
  );
  process.exit(1);
}

if (!root.startsWith('/') && !/^[a-zA-Z]:/.test(root)) {
  console.error(`The data path must be absolute; got "${root}".`);
  process.exit(1);
}

const tree = {
  POSTGRES_DATA_PATH: join(root, 'data', 'postgres'),
  REDIS_DATA_PATH: join(root, 'data', 'redis'),
  UPLOAD_DATA_PATH: join(root, 'data', 'media'),
  BACKUP_DATA_PATH: join(root, 'backup'),
};

/** The two prefixes chat-service actually writes under `data/media`, created
 *  here so the tree is complete and legible before anything is uploaded.
 *
 *  Not `image/` and `video/`: an attachment is encrypted in the renderer, so
 *  the server never learns what it is - it stores an opaque blob and serves it
 *  as `application/octet-stream`. Splitting by media type would mean either
 *  trusting a filename the client chose or decrypting, and the second is the
 *  property the whole design exists to keep. Avatars and server icons are the
 *  exception - not encrypted, which is why `pictures/` can be its own place.
 */
const MEDIA_SUBDIRS = ['pictures', 'attachments'];

let next = setEnv(text, 'BETWEENUS_DATA_PATH', root);
for (const [key, path] of Object.entries(tree)) {
  mkdirSync(path, { recursive: true });
  next = setEnv(next, key, path.split(sep).join('/'));
}
for (const name of MEDIA_SUBDIRS) mkdirSync(join(tree.UPLOAD_DATA_PATH, name), { recursive: true });

// Postgres and Redis chown their own directory on start; the Node services do
// not, so uploads is the one that has to be handed over here.
if (process.platform !== 'win32') {
  const media = tree.UPLOAD_DATA_PATH;
  const backup = tree.BACKUP_DATA_PATH;
  try {
    for (const path of [media, ...MEDIA_SUBDIRS.map((name) => join(media, name))]) {
      if (statSync(path).uid !== SERVICE_UID) chownSync(path, SERVICE_UID, SERVICE_UID);
    }
  } catch {
    console.warn(
      `Could not chown ${media} to ${SERVICE_UID}:${SERVICE_UID} - run this as root, or\n` +
        `  sudo chown -R ${SERVICE_UID}:${SERVICE_UID} ${media}\n` +
        'or every upload fails with EACCES while the rest of the service works.',
    );
  }
  try {
    const { chmodSync } = await import('node:fs');
    chmodSync(backup, 0o777);
  } catch {
    // Ignore chmod errors if permissions cannot be set directly
  }
}

writeFileSync(envFile, next);

console.log(`Data path: ${root}\n`);
for (const [key, path] of Object.entries(tree)) console.log(`  ${key.padEnd(19)} ${path}`);
console.log(`  ${''.padEnd(19)} ${MEDIA_SUBDIRS.map((name) => `${name}/`).join(', ')} below the media path`);
console.log(
  '\nWritten to .env. Bring the stack up with `pnpm prod:up`.\n' +
    'Moving an existing deployment onto this path is a copy out of the old\n' +
    'volumes while it is down - see the deployment documentation.',
);

/**
 * `pnpm dev:duo` - two signed-in desktop windows for testing chat and calls.
 *
 * It seeds two accounts that share one server, starts the Vite dev server
 * once, then launches two Electron processes with separate profiles so each
 * window has its own session, its own localStorage and - importantly for E2EE -
 * its own device key.
 *
 * Backend services must already be running (`pnpm dev`).
 */
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import { existsSync, rmSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const desktopDir = path.join(repoRoot, 'apps', 'desktop');

const AUTH = process.env.AUTH_SERVICE_URL ?? 'http://127.0.0.1:3001';
const SERVER = process.env.SERVER_SERVICE_URL ?? 'http://127.0.0.1:3003';
const CHAT = process.env.CHAT_SERVICE_URL ?? 'http://127.0.0.1:3004';
const CALL = process.env.CALL_SERVICE_URL ?? 'http://127.0.0.1:3007';
const PRESENCE = process.env.PRESENCE_SERVICE_URL ?? 'http://127.0.0.1:3005';
const NOTIFICATION = process.env.NOTIFICATION_SERVICE_URL ?? 'http://127.0.0.1:3006';
const REMOTE = process.env.REMOTE_GATEWAY_URL ?? 'http://127.0.0.1:3008';
const RENDERER = 'http://localhost:5173';

// Must satisfy the password policy in @betweenus/auth: 8+ chars, a letter, a digit.
const PASSWORD = 'betweenus-dev-1';
const USERS = [
  { label: 'Alice', email: 'alice@betweenus.local', username: 'alice', profile: 'duo-a', x: 40, y: 60 },
  { label: 'Bob', email: 'bob@betweenus.local', username: 'bob', profile: 'duo-b', x: 760, y: 60 },
];
const SERVER_NAME = 'Duo Test';

async function json(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers ?? {}) },
  });
  const body = await response.json().catch(() => null);
  if (!response.ok) {
    const error = new Error(`${options.method ?? 'GET'} ${url} -> ${response.status}`);
    error.status = response.status;
    error.body = body;
    throw error;
  }
  return body;
}

async function healthy(name, base) {
  try {
    const body = await json(`${base}/health`);
    return body?.status === 'ok';
  } catch {
    console.error(`  x ${name} is not answering on ${base}`);
    return false;
  }
}

/** Registers the account, or signs in when it already exists. */
async function ensureUser(user) {
  try {
    return await json(`${AUTH}/api/v1/auth/register`, {
      method: 'POST',
      body: JSON.stringify({ email: user.email, username: user.username, password: PASSWORD }),
    });
  } catch (error) {
    if (error.status !== 409) throw error;
    return json(`${AUTH}/api/v1/auth/login`, {
      method: 'POST',
      body: JSON.stringify({ email: user.email, password: PASSWORD }),
    });
  }
}

async function seed() {
  const [alice, bob] = await Promise.all(USERS.map(ensureUser));
  const asAlice = { Authorization: `Bearer ${alice.accessToken}` };
  const asBob = { Authorization: `Bearer ${bob.accessToken}` };

  const owned = await json(`${SERVER}/api/v1/servers`, { headers: asAlice });
  const server =
    owned.find((item) => item.name === SERVER_NAME) ??
    (await json(`${SERVER}/api/v1/servers`, {
      method: 'POST',
      headers: asAlice,
      body: JSON.stringify({ name: SERVER_NAME }),
    }));

  // An invite per run, unlimited and non-expiring: this is a seed script, and
  // joining a server somebody is already in returns their membership unchanged,
  // so running it repeatedly stays harmless.
  const invite = await json(`${SERVER}/api/v1/servers/${server.id}/invites`, {
    method: 'POST',
    headers: asAlice,
    body: JSON.stringify({}),
  });
  await json(`${SERVER}/api/v1/servers/join`, {
    method: 'POST',
    headers: asBob,
    body: JSON.stringify({ code: invite.code }),
  });

  const channels = await json(
    `${SERVER}/api/v1/channels?serverId=${server.id}`,
    { headers: asAlice },
  );

  // A voice channel to click on, alongside the default #general text channel.
  let voice = channels.find((channel) => channel.type === 'VOICE');
  if (!voice) {
    voice = await json(`${SERVER}/api/v1/channels`, {
      method: 'POST',
      headers: asAlice,
      body: JSON.stringify({ serverId: server.id, name: 'lounge', type: 'VOICE' }),
    });
  }

  // A private channel Bob is deliberately not on, so the rule can be seen
  // rather than taken on trust: it is absent from Bob's sidebar entirely.
  let secret = channels.find((channel) => channel.name === 'owners-only');
  if (!secret) {
    secret = await json(`${SERVER}/api/v1/channels`, {
      method: 'POST',
      headers: asAlice,
      body: JSON.stringify({
        serverId: server.id,
        name: 'owners-only',
        type: 'TEXT',
        isPrivate: true,
        memberIds: [],
      }),
    });
  }

  const friendship = await seedFriendship(alice, bob, asAlice, asBob);

  return { server, channel: channels[0], voice, secret, friendship };
}

/**
 * Alice and Bob start as friends with a conversation open, because a direct
 * message needs two consenting accounts and typing the request by hand every
 * time is exactly the friction `dev:duo` exists to remove.
 */
async function seedFriendship(alice, bob, asAlice, asBob) {
  const existing = await json(`${CHAT}/api/v1/friends`, { headers: asAlice });
  const already = existing.find((friend) => friend.user.id === bob.user.id);

  if (!already) {
    await json(`${CHAT}/api/v1/friends`, {
      method: 'POST',
      headers: asAlice,
      body: JSON.stringify({ username: bob.user.username }),
    });
  }

  if (already?.status !== 'ACCEPTED') {
    await json(`${CHAT}/api/v1/friends/${alice.user.id}/accept`, {
      method: 'POST',
      headers: asBob,
    });
  }

  return json(`${CHAT}/api/v1/dm`, {
    method: 'POST',
    headers: asAlice,
    body: JSON.stringify({ userId: bob.user.id }),
  });
}

const mainBundle = path.join(desktopDir, 'dist-electron', 'main.js');

/**
 * Removes the previous main-process bundle so the wait below cannot pass on a
 * stale one - launching Electron against yesterday's main.js silently drops
 * whatever IPC handlers were added since.
 */
function clearMainBundle() {
  rmSync(mainBundle, { force: true });
}

function waitForRenderer(timeoutMs = 60_000) {
  const deadline = Date.now() + timeoutMs;

  return new Promise((resolve, reject) => {
    const poll = async () => {
      if (Date.now() > deadline) {
        reject(new Error('Vite dev server did not come up within 60s'));
        return;
      }
      try {
        const response = await fetch(RENDERER, { method: 'GET' });
        if (response.ok && existsSync(mainBundle)) {
          resolve();
          return;
        }
      } catch {
        // Not listening yet.
      }
      setTimeout(poll, 400);
    };
    void poll();
  });
}

function startVite() {
  const isWin = process.platform === 'win32';
  const command = isWin ? 'cmd.exe' : 'pnpm';
  const args = isWin
    ? ['/c', 'pnpm', '--filter', '@betweenus/desktop', 'dev']
    : ['--filter', '@betweenus/desktop', 'dev'];

  return spawn(command, args, {
    cwd: repoRoot,
    stdio: 'inherit',
    // The plugin still builds main/preload; it just does not launch Electron.
    env: { ...process.env, BETWEENUS_NO_ELECTRON: '1' },
  });
}

function startWindow(user) {
  const require = createRequire(path.join(desktopDir, 'package.json'));
  const electronBinary = require('electron');

  return spawn(electronBinary, ['.'], {
    cwd: desktopDir,
    stdio: 'inherit',
    env: {
      ...process.env,
      VITE_DEV_SERVER_URL: RENDERER,
      BETWEENUS_PROFILE: user.profile,
      BETWEENUS_WINDOW_LABEL: user.label,
      BETWEENUS_WINDOW_X: String(user.x),
      BETWEENUS_WINDOW_Y: String(user.y),
      BETWEENUS_DEV_EMAIL: user.email,
      BETWEENUS_DEV_PASSWORD: PASSWORD,
    },
  });
}

async function main() {
  console.log('Checking services...');
  const checks = await Promise.all([
    healthy('auth-service', AUTH),
    healthy('server-service', SERVER),
    healthy('chat-service', CHAT),
  ]);
  if (checks.some((ok) => !ok)) {
    console.error('\nStart the backend first:  pnpm dev:infra && pnpm dev');
    process.exit(1);
  }
  if (!(await healthy('call-service', CALL))) {
    console.warn('  ! call-service is down - chat will work, voice will not');
  }
  if (!(await healthy('presence-service', PRESENCE))) {
    console.warn('  ! presence-service is down - no online status or typing indicators');
  }
  if (!(await healthy('notification-service', NOTIFICATION))) {
    console.warn('  ! notification-service is down - unread marks and mutes will not persist');
  }

  if (!(await healthy('remote-gateway', REMOTE))) {
    console.warn('  ! remote-gateway is down - remote machines will not appear');
  }

  const { server, channel, voice, secret, friendship } = await seed();
  console.log(
    `Server "${server.name}" ready: #${channel?.name ?? 'general'}, voice "${voice.name}", ` +
      `private #${secret.name} (Alice only)`,
  );
  console.log(
    `Alice and Bob are friends, with a direct message open to ${friendship.participant.username}`,
  );
  console.log('Sign-in is automatic:');
  for (const user of USERS) console.log(`  - ${user.label} <${user.email}>`);

  clearMainBundle();
  const vite = startVite();
  await waitForRenderer();

  const windows = USERS.map(startWindow);
  console.log('\nTwo windows are open. Close both to stop, or press Ctrl+C.\n');

  let alive = windows.length;
  const killProcess = (child) => {
    if (!child || child.killed || !child.pid) return;
    if (process.platform === 'win32') {
      spawn('taskkill', ['/pid', String(child.pid), '/f', '/t'], { stdio: 'ignore' });
    } else {
      child.kill();
    }
  };

  const shutdown = () => {
    for (const child of [...windows, vite]) killProcess(child);
  };

  for (const child of windows) {
    child.on('exit', () => {
      alive -= 1;
      if (alive === 0) {
        killProcess(vite);
        process.exit(0);
      }
    });
  }

  process.on('SIGINT', () => {
    shutdown();
    process.exit(0);
  });

  process.on('SIGTERM', () => {
    shutdown();
    process.exit(0);
  });
}

main().catch((error) => {
  console.error(error.body ? `${error.message}\n${JSON.stringify(error.body)}` : error);
  // Setting the code rather than calling process.exit lets the already-spawned
  // children close their pipes; a hard exit here trips a libuv assertion.
  process.exitCode = 1;
});

/**
 * The gateway, for clients that cannot use a Vite proxy.
 *
 * `pnpm dev` gives the desktop and web clients a proxy table inside their own
 * dev servers, which stands in for Nginx. The Android client has no such thing:
 * it is a native app pointed at one address, so in development it needs
 * something real listening on one port that routes the same way.
 *
 * This is that, and nothing more - no TLS, no rate limiting, no auth. It
 * mirrors the route table in infrastructure/nginx/nginx.conf, which is the
 * thing it is standing in for; when that file changes, this one changes.
 *
  *   pnpm dev:gateway            # http://0.0.0.0:8090
 *
 * It binds every interface on purpose: an emulator reaches it on 10.0.2.2 and a
 * physical phone on the machine's LAN address, and neither can see loopback.
 * Production is Nginx in a container behind a Cloudflare Tunnel; this file is
 * never part of that.
 */
import { readFileSync } from 'node:fs';
import http from 'node:http';
import net from 'node:net';
import { networkInterfaces } from 'node:os';

/**
 * 8090 rather than 8080, which is what the Nginx container listens on. Two
 * reasons: `pnpm dev:infra` can be running at the same time as this, and on
 * Windows 8080 often falls inside a Hyper-V reserved port range and simply
 * cannot be bound - a failure that reads as "address already in use" with
 * nothing visibly listening.
 */
const PORT = Number(process.env.GATEWAY_PORT ?? 8090);

const AUTH = process.env.AUTH_SERVICE_URL ?? 'http://127.0.0.1:3001';
const SERVER = process.env.SERVER_SERVICE_URL ?? 'http://127.0.0.1:3003';
const CHAT = process.env.CHAT_SERVICE_URL ?? 'http://127.0.0.1:3004';
const PRESENCE = process.env.PRESENCE_SERVICE_URL ?? 'http://127.0.0.1:3005';
const NOTIFICATION = process.env.NOTIFICATION_SERVICE_URL ?? 'http://127.0.0.1:3006';
const CALL = process.env.CALL_SERVICE_URL ?? 'http://127.0.0.1:3007';
const REMOTE = process.env.REMOTE_GATEWAY_URL ?? 'http://127.0.0.1:3008';

/** Longest prefix wins, so `/api/v1/servers` cannot swallow `/api/v1/servers/x`. */
const ROUTES = [
  ['/api/v1/auth', AUTH],
  ['/api/v1/admin', AUTH],
  ['/api/v1/servers', SERVER],
  ['/api/v1/channels', SERVER],
  ['/api/v1/messages', CHAT],
  ['/api/v1/friends', CHAT],
  ['/api/v1/users', CHAT],
  ['/api/v1/dm', CHAT],
  ['/api/v1/uploads', CHAT],
  ['/api/v1/statuses', CHAT],
  ['/api/v1/webhooks', CHAT],
  ['/api/v1/e2ee', CHAT],
  ['/api/v1/calls', CALL],
  ['/api/v1/notifications', NOTIFICATION],
  ['/api/v1/remote', REMOTE],
  ['/ws/chat', CHAT],
  ['/ws/presence', PRESENCE],
  ['/ws/call', CALL],
  ['/ws/remote', REMOTE],
].sort((a, b) => b[0].length - a[0].length);

const upstreamFor = (url) => {
  const path = url.split('?')[0];
  const match = ROUTES.find(([prefix]) => path === prefix || path.startsWith(`${prefix}/`));
  return match?.[1] ?? null;
};

/**
 * `node scripts/dev-gateway.mjs --check`: every prefix Nginx routes is routed
 * here too.
 *
 * This file is a copy of a route table, and a copy drifts. It drifted once
 * already - `/api/v1/statuses` was added to Nginx and not here, so the feature
 * worked on the desktop, whose proxy is a third copy, and answered "No route"
 * on every Android device. One assertion in `pnpm check` is cheaper than
 * finding that out on a phone.
 */
if (process.argv.includes('--check')) {
  const conf = readFileSync(new URL('../infrastructure/nginx/nginx.conf', import.meta.url), 'utf8');
  const routed = new Set(ROUTES.map(([prefix]) => prefix));
  const missing = [...conf.matchAll(/^\s*location\s+(\/(?:api\/v1|ws)\/[^\s{]+)/gm)]
    .map((match) => match[1].replace(/\/$/, ''))
    .filter((prefix) => !routed.has(prefix));

  if (missing.length > 0) {
    console.error('dev-gateway is missing routes Nginx has: %s', [...new Set(missing)].join(' '));
    process.exit(1);
  }
  console.log('dev-gateway routes match nginx.conf');
  process.exit(0);
}

const server = http.createServer((request, response) => {
  const upstream = upstreamFor(request.url ?? '/');
  if (!upstream) {
    response.writeHead(404, { 'Content-Type': 'application/json' });
    response.end(JSON.stringify({ error: { code: 'NO_ROUTE', message: `No route for ${request.url}` } }));
    return;
  }

  const target = new URL(upstream);
  const proxied = http.request(
    {
      host: target.hostname,
      port: target.port,
      method: request.method,
      path: request.url,
      headers: { ...request.headers, host: target.host },
    },
    (upstreamResponse) => {
      response.writeHead(upstreamResponse.statusCode ?? 502, upstreamResponse.headers);
      upstreamResponse.pipe(response);
    },
  );

  proxied.on('error', (error) => {
    response.writeHead(502, { 'Content-Type': 'application/json' });
    response.end(
      JSON.stringify({ error: { code: 'UPSTREAM_DOWN', message: `${upstream}: ${error.message}` } }),
    );
  });

  request.pipe(proxied);
});

// WebSocket upgrades are the whole reason this exists rather than a one-liner:
// /ws/chat, /ws/presence, /ws/call and /ws/remote all arrive this way.
server.on('upgrade', (request, socket, head) => {
  const upstream = upstreamFor(request.url ?? '/');
  if (!upstream) {
    socket.destroy();
    return;
  }

  const target = new URL(upstream);
  const outbound = net.connect(Number(target.port), target.hostname, () => {
    const lines = [
      `GET ${request.url} HTTP/1.1`,
      ...Object.entries(request.headers).flatMap(([key, value]) =>
        Array.isArray(value) ? value.map((v) => `${key}: ${v}`) : [`${key}: ${value}`],
      ),
      '',
      '',
    ];
    outbound.write(lines.join('\r\n'));
    if (head?.length) outbound.write(head);
    outbound.pipe(socket);
    socket.pipe(outbound);
  });

  outbound.on('error', () => socket.destroy());
  socket.on('error', () => outbound.destroy());
});

/**
 * Every address a client could reach this on.
 *
 * `10.0.2.2` is the emulator's alias for this machine's loopback and means
 * nothing anywhere else, so a physical phone needs the LAN address - and
 * hunting for it with `ipconfig` is a detour every single time. Printing it
 * costs nothing and is the answer to "it works on the emulator".
 */
function lanAddresses() {
  return Object.values(networkInterfaces())
    .flat()
    .filter((entry) => entry && entry.family === 'IPv4' && !entry.internal)
    .map((entry) => entry.address);
}

server.listen(PORT, '0.0.0.0', () => {
  console.log(`dev gateway on http://0.0.0.0:${PORT}`);
  console.log('  emulator: http://10.0.2.2:%d', PORT);
  for (const address of lanAddresses()) {
    console.log('  device:   http://%s:%d', address, PORT);
  }
  console.log('            (same Wi-Fi, and the firewall has to allow inbound %d)', PORT);
  console.log('  routes:   %s', ROUTES.map(([prefix]) => prefix).join(' '));
});

import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import fs from 'node:fs';
import os from 'node:os';
import { execFileSync } from 'node:child_process';

const require = createRequire(import.meta.url);

function getPlatformExecutable() {
  const platform = process.env.npm_config_platform || os.platform();
  switch (platform) {
    case 'mas':
    case 'darwin':
      return 'Electron.app/Contents/MacOS/Electron';
    case 'freebsd':
    case 'openbsd':
    case 'linux':
      return 'electron';
    case 'win32':
      return 'electron.exe';
    default:
      throw new Error(`Unsupported platform: ${platform}`);
  }
}

function findElectronDirectories() {
  const repoRoot = fileURLToPath(new URL('../', import.meta.url));
  const candidatePaths = [
    path.join(repoRoot, 'node_modules', 'electron'),
    path.join(repoRoot, 'apps', 'desktop', 'node_modules', 'electron'),
  ];

  const dirs = new Set();
  for (const candidate of candidatePaths) {
    if (fs.existsSync(candidate)) {
      try {
        const real = fs.realpathSync(candidate);
        dirs.add(real);
      } catch {
        dirs.add(candidate);
      }
    }
  }

  try {
    const resolved = require.resolve('electron/package.json', {
      paths: [repoRoot, path.join(repoRoot, 'apps/desktop')],
    });
    dirs.add(path.dirname(resolved));
  } catch {}

  return Array.from(dirs);
}

function extractZip(zipPath, targetDir) {
  fs.mkdirSync(targetDir, { recursive: true });

  // Try tar first (available on modern Windows 10+, macOS, Linux)
  try {
    execFileSync('tar', ['-xf', zipPath, '-C', targetDir], { stdio: 'ignore' });
    return;
  } catch {}

  // On Windows, fallback to PowerShell Expand-Archive
  if (os.platform() === 'win32') {
    try {
      execFileSync(
        'powershell.exe',
        [
          '-NoProfile',
          '-NonInteractive',
          '-Command',
          `Expand-Archive -LiteralPath '${zipPath.replace(/'/g, "''")}' -DestinationPath '${targetDir.replace(/'/g, "''")}' -Force`,
        ],
        { stdio: 'ignore' },
      );
      return;
    } catch {}
  }

  // On Unix, fallback to unzip
  try {
    execFileSync('unzip', ['-q', '-o', zipPath, '-d', targetDir], {
      stdio: 'ignore',
    });
    return;
  } catch {}

  throw new Error(
    `Failed to extract ${zipPath} into ${targetDir}. Please ensure tar, powershell, or unzip is available.`,
  );
}

async function ensureElectronDir(electronDir) {
  const pkgPath = path.join(electronDir, 'package.json');
  if (!fs.existsSync(pkgPath)) return;

  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
  const version = pkg.version;
  const platformExecutable = getPlatformExecutable();
  const pathFilePath = path.join(electronDir, 'path.txt');
  const distDir = path.join(electronDir, 'dist');
  const executablePath = path.join(distDir, platformExecutable);

  const isReady =
    fs.existsSync(pathFilePath) &&
    fs.readFileSync(pathFilePath, 'utf-8').trim() === platformExecutable &&
    fs.existsSync(executablePath);

  if (isReady) {
    return;
  }

  console.log(`[ensure-electron] Setting up Electron v${version} in ${electronDir}...`);

  const { downloadArtifact } = require('@electron/get');
  const zipPath = await downloadArtifact({
    version,
    artifactName: 'electron',
    force: false,
    platform: process.env.npm_config_platform || os.platform(),
    arch: process.env.npm_config_arch || os.arch(),
  });

  console.log(`[ensure-electron] Extracting ${zipPath} -> ${distDir}`);
  extractZip(zipPath, distDir);

  fs.writeFileSync(pathFilePath, platformExecutable, 'utf-8');

  const srcTypeDefPath = path.join(distDir, 'electron.d.ts');
  const targetTypeDefPath = path.join(electronDir, 'electron.d.ts');
  if (fs.existsSync(srcTypeDefPath) && !fs.existsSync(targetTypeDefPath)) {
    try {
      fs.copyFileSync(srcTypeDefPath, targetTypeDefPath);
    } catch {}
  }

  if (!fs.existsSync(executablePath)) {
    throw new Error(
      `[ensure-electron] Verification failed: ${executablePath} does not exist after extraction.`,
    );
  }

  console.log(`[ensure-electron] Electron v${version} configured successfully.`);
}

async function main() {
  const dirs = findElectronDirectories();
  if (dirs.length === 0) {
    console.log('[ensure-electron] No electron installation found in node_modules.');
    return;
  }

  for (const dir of dirs) {
    await ensureElectronDir(dir);
  }
}

main().catch((err) => {
  console.error('[ensure-electron] Error:', err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Turn a downloaded Firebase service-account key into the three lines the
 * environment wants, and print them.
 *
 *   pnpm firebase:env ./serviceAccountKey.json      # prints the lines
 *   pnpm firebase:env ./serviceAccountKey.json --write  # appends them to .env
 *
 * The point is that the file itself never becomes part of the deployment. A
 * JSON private key sitting in the repository is one `git add .` away from being
 * a public one, and a container has an environment rather than a filesystem
 * anybody edits - so the key is read once, here, and then the file can go.
 *
 * `--single` prints the base64 one-variable form instead, which is what a
 * secrets manager usually wants.
 */
import { appendFileSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';

const args = process.argv.slice(2);
const path = args.find((arg) => !arg.startsWith('--'));
const write = args.includes('--write');
const single = args.includes('--single');

if (!path) {
  console.error('Usage: node scripts/firebase-env.mjs <serviceAccountKey.json> [--write] [--single]');
  process.exit(1);
}

const raw = readFileSync(resolve(path), 'utf8');
const key = JSON.parse(raw);
for (const field of ['project_id', 'client_email', 'private_key']) {
  if (typeof key[field] !== 'string' || key[field] === '') {
    console.error(`That does not look like a service-account key: ${field} is missing`);
    process.exit(1);
  }
}

// The newlines in the PEM are escaped, because a .env value is one line. The
// service undoes it on the way in - see push/firebase.ts.
const lines = single
  ? [`FIREBASE_SERVICE_ACCOUNT="${Buffer.from(raw, 'utf8').toString('base64')}"`]
  : [
      `FIREBASE_PROJECT_ID="${key.project_id}"`,
      `FIREBASE_CLIENT_EMAIL="${key.client_email}"`,
      // JSON.stringify does the escaping and the quoting in one: a PEM is
      // multi-line and a .env value is not, so the newlines have to survive as
      // `\n` and be undone again on the way in.
      `FIREBASE_PRIVATE_KEY=${JSON.stringify(key.private_key)}`,
    ];

if (write) {
  appendFileSync(resolve(process.cwd(), '.env'), `\n# Firebase Cloud Messaging - see docs/docs/architecture/notifications.md\n${lines.join('\n')}\n`);
  console.log(`Appended ${lines.length} line(s) to .env. Delete ${path} now - it is not needed again.`);
} else {
  console.log(lines.join('\n'));
}

const { app, nativeImage } = require('electron');
const fs = require('fs');
const path = require('path');

app.whenReady().then(() => {
  try {
    const svgPath = path.join(__dirname, '../apps/desktop/public/icon.svg');
    const pngPath = path.join(__dirname, '../apps/desktop/public/icon.png');
    const buildIconPath = path.join(__dirname, '../apps/desktop/build/icon.png');

    if (!fs.existsSync(svgPath)) {
      console.error('SVG file not found at:', svgPath);
      process.exit(1);
    }

    const image = nativeImage.createFromPath(svgPath);
    const pngBuffer = image.resize({ width: 512, height: 512 }).toPNG();

    fs.writeFileSync(pngPath, pngBuffer);
    console.log('Saved PNG icon to:', pngPath);

    const buildDir = path.dirname(buildIconPath);
    if (!fs.existsSync(buildDir)) {
      fs.mkdirSync(buildDir, { recursive: true });
    }
    fs.writeFileSync(buildIconPath, pngBuffer);
    console.log('Saved PNG icon to:', buildIconPath);

    // Generate 32x32 tray icon base64
    const trayBuffer = image.resize({ width: 32, height: 32 }).toPNG();
    const base64Tray = 'data:image/png;base64,' + trayBuffer.toString('base64');
    console.log('TRAY_ICON_BASE64_START');
    console.log(base64Tray);
    console.log('TRAY_ICON_BASE64_END');

    process.exit(0);
  } catch (err) {
    console.error('Error generating icon:', err);
    process.exit(1);
  }
});

#!/usr/bin/env node
// Builds the CHANGELOG entry for a release out of the commits behind it.
//
// One section per kind of change, in the order a reader cares about them:
// breaking first, then what is new, then what is fixed, then the rest. A
// commit's kind comes from its release marker if it has one and from its
// conventional-commit type if it does not, so `!feat: X` and `feat: X` land in
// the same place - the marker says "release now", the type says "this is a
// feature", and most commits only ever say the second.
//
// The subject is cleaned before it is printed: the marker and the type prefix
// are scaffolding for the tooling, not something anybody wants to read in a
// release note.
//
// Usage:
//   node scripts/release-notes.mjs --version 0.0.1 --subjects-file subjects.txt \
//     [--previous 0.0.0] [--repository owner/name] [--date 2026-08-21]
//   node scripts/release-notes.mjs --check     # self-check, no arguments

import { strictEqual, ok as assertOk } from 'node:assert';
import { readFileSync } from 'node:fs';

/** A commit the release flow wrote itself never appears in its own notes. */
const NOISE = [
  /^\s*chore\(release\):/i,
  /^\s*Merge (pull request|branch|remote-tracking)/i,
  /^\s*docs\(changelog\):/i,
];

// The scope is part of what gets stripped: `!feat(chat): x` is a marker with a
// scope, and leaving `(chat):` at the front of the note helps nobody.
const MARKER = /^\s*!(major|feat|fix|stable|alpha|beta|patch)(?![a-z0-9])(?:\([^)]*\))?[:\s-]*/i;
const TYPE = /^(feat|fix|chore|docs|refactor|perf|test|build|ci|style|revert)(\([^)]*\))?(!)?:\s*/i;

// The platforms a release builds, in the order the table lists them, and what
// to call them in front of a reader.
const TARGET_LABELS = [
  ['docker', 'Server images'],
  ['desktop', 'Desktop (Windows)'],
  ['android', 'Android'],
];

const SECTIONS = [
  ['breaking', '### ⚠ Breaking changes'],
  ['features', '### Features'],
  ['fixes', '### Bug fixes'],
  ['other', '### Other changes'],
];

/** Which section a subject belongs in. */
export function classify(subject) {
  const marker = MARKER.exec(subject);
  const kind = marker?.[1]?.toLowerCase();
  if (kind === 'major') return 'breaking';
  // `!` after the type is the conventional-commit way to say breaking, and it
  // outranks the type itself: `feat(api)!: drop v1` is a breaking change first.
  const type = TYPE.exec(subject.replace(MARKER, ''));
  if (type?.[3] === '!' || /\bBREAKING[ -]CHANGE\b/.test(subject)) return 'breaking';
  if (kind === 'feat') return 'features';
  if (kind === 'fix') return 'fixes';
  if (type) {
    const name = type[1].toLowerCase();
    if (name === 'feat') return 'features';
    if (name === 'fix') return 'fixes';
  }
  return 'other';
}

/** The subject with the tooling stripped off and a capital at the front. */
export function clean(subject) {
  const text = subject.replace(MARKER, '').replace(TYPE, '').trim().replace(/\.+$/, '');
  return text ? text[0].toUpperCase() + text.slice(1) : text;
}

/**
 * The what-was-built table. `targets` is what this release rebuilt;
 * everything else was carried forward from `carriedFrom`, the last release
 * that has the artifact.
 */
export function artifacts({ targets, carriedFrom, repository } = {}) {
  if (!targets || targets.length === 0) return '';
  const link = (version) =>
    repository
      ? `[v${version}](https://github.com/${repository}/releases/tag/v${version})`
      : `v${version}`;

  const rows = TARGET_LABELS.map(([target, label]) => {
    if (targets.includes(target)) return `| ${label} | Built here |`;
    // Without a version to carry from there is nothing to say but the truth.
    const from = carriedFrom ? `Carried forward from ${link(carriedFrom)}` : 'Not in this release';
    return `| ${label} | ${from} |`;
  });

  return ['### Artifacts', '', '| Platform | This release |', '| --- | --- |', ...rows].join('\n');
}

export function notes(subjects, { version, previous, repository, date, targets, carriedFrom } = {}) {
  const kept = subjects
    .map((subject) => subject.trim())
    .filter((subject) => subject && !NOISE.some((pattern) => pattern.test(subject)));

  const grouped = new Map(SECTIONS.map(([key]) => [key, []]));
  for (const subject of kept) {
    const line = clean(subject);
    const bucket = grouped.get(classify(subject));
    // The same subject twice - a cherry-pick, a revert and its re-land - is one
    // line, not two identical ones.
    if (line && !bucket.includes(line)) bucket.push(line);
  }

  const compare =
    repository && previous
      ? `https://github.com/${repository}/compare/v${previous}...v${version}`
      : '';
  const heading = compare ? `## [${version}](${compare})` : `## ${version}`;
  const stamp = date ?? new Date().toISOString().slice(0, 10);

  let body = '';
  for (const [key, title] of SECTIONS) {
    const items = grouped.get(key);
    if (items.length === 0) continue;
    body += `${title}\n\n${items.map((item) => `* ${item}`).join('\n')}\n\n`;
  }
  if (!body) body = `### Notes\n\n* Release ${version}\n\n`;

  const table = artifacts({ targets, carriedFrom, repository });
  if (table) body += `${table}\n`;

  return { heading: `${heading} (${stamp})`, body: body.trimEnd() };
}

/** Puts a new entry at the top of an existing CHANGELOG, below its title. */
export function insert(changelog, entry) {
  const block = `${entry.heading}\n\n${entry.body}\n`;
  if (changelog.includes(entry.heading)) return changelog;
  const title = '# Changelog\n\n';
  return changelog.startsWith(title)
    ? changelog.replace(title, `${title}${block}\n`)
    : `${title}${block}\n${changelog}`;
}

/** The section for one version, for a GitHub Release body. */
export function section(changelog, version) {
  const escaped = version.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = new RegExp(`^##\\s*\\[?${escaped}\\]?.*?(?=^##\\s|$(?![\\s\\S]))`, 'ms').exec(
    changelog,
  );
  if (!match) return '';
  const [, ...rest] = match[0].trim().split('\n');
  return rest.join('\n').trim();
}

function selfCheck() {
  strictEqual(classify('!major: drop the v1 API'), 'breaking');
  strictEqual(classify('feat(api)!: drop the v1 API'), 'breaking');
  strictEqual(classify('!feat: a new thing'), 'features');
  strictEqual(classify('feat(chat): a new thing'), 'features');
  strictEqual(classify('!fix: a broken thing'), 'fixes');
  strictEqual(classify('fix: a broken thing'), 'fixes');
  strictEqual(classify('docs: a written thing'), 'other');
  strictEqual(classify('something with no prefix'), 'other');
  // The marker says "release now", not what kind of change it is.
  strictEqual(classify('!alpha: fix(voice): a broken thing'), 'fixes');

  strictEqual(clean('!feat(chat): add pinning.'), 'Add pinning');
  strictEqual(clean('fix: the thing'), 'The thing');
  strictEqual(clean('!patch(desktop): rebuild the installer'), 'Rebuild the installer');
  // The marker says "rebuild now", not what kind of change it is.
  strictEqual(classify('!patch: fix(desktop): the installer'), 'fixes');

  const entry = notes(
    [
      '!feat(chat): add pinning',
      'fix(voice): stop the echo',
      'chore(release): v0.0.1',
      'Merge pull request #3 from x',
      'docs: explain it',
      'feat(api)!: drop v1',
      'fix(voice): stop the echo',
    ],
    { version: '0.1.0', previous: '0.0.1', repository: 'a/b', date: '2026-08-21' },
  );
  assertOk(entry.heading.includes('compare/v0.0.1...v0.1.0'), 'links the comparison');
  assertOk(entry.heading.endsWith('(2026-08-21)'), 'carries the date');
  assertOk(entry.body.includes('* Drop v1'), 'breaking listed');
  assertOk(entry.body.includes('* Add pinning'), 'feature listed');
  assertOk(entry.body.includes('* Stop the echo'), 'fix listed');
  assertOk(entry.body.includes('* Explain it'), 'other listed');
  assertOk(!entry.body.includes('v0.0.1\n'), 'the release commit is not a note');
  assertOk(!entry.body.includes('Merge pull request'), 'the merge commit is not a note');
  strictEqual(entry.body.match(/Stop the echo/g).length, 1, 'a repeated subject is one line');
  assertOk(
    entry.body.indexOf('Breaking') < entry.body.indexOf('Features'),
    'breaking comes first',
  );

  // The artifacts table says what was rebuilt and where the rest came from.
  const partial = notes(['!alpha(android): x'], {
    version: '0.0.7-alpha.1',
    repository: 'a/b',
    targets: ['android'],
    carriedFrom: '0.0.6',
  });
  assertOk(partial.body.includes('| Android | Built here |'), 'the built platform says so');
  assertOk(
    partial.body.includes('| Desktop (Windows) | Carried forward from [v0.0.6](https://github.com/a/b/releases/tag/v0.0.6) |'),
    'a skipped platform names and links where its artifacts came from',
  );
  assertOk(partial.body.includes('| Server images | Carried forward'), 'server images too');
  // A first release has nothing to carry from, and says that rather than
  // linking a tag that does not exist.
  assertOk(
    notes(['!alpha(android): x'], { version: '0.0.1-alpha.1', targets: ['android'] }).body.includes(
      '| Desktop (Windows) | Not in this release |',
    ),
    'no previous release means no carry-forward claim',
  );
  // No table at all when nobody said what was built - the old shape.
  assertOk(!notes(['fix: x'], { version: '1.0.0' }).body.includes('### Artifacts'));
  // The table is readable back out for the GitHub Release body.
  assertOk(
    section(insert('# Changelog\n\n', partial), '0.0.7-alpha.1').includes('| Android | Built here |'),
    'the table survives the round trip through the CHANGELOG',
  );

  // A release with nothing to say still says something.
  assertOk(notes(['chore(release): v1'], { version: '1.0.0' }).body.includes('Release 1.0.0'));

  const changelog = insert('# Changelog\n\n## 0.0.1 (2026-01-01)\n\n### Notes\n\n* old\n', entry);
  assertOk(changelog.indexOf('0.1.0') < changelog.indexOf('0.0.1'), 'newest first');
  strictEqual(insert(changelog, entry), changelog, 'inserting twice changes nothing');
  assertOk(section(changelog, '0.1.0').includes('Add pinning'), 'the section is readable back');
  assertOk(!section(changelog, '0.1.0').includes('old'), 'and stops at the next version');
  assertOk(section(changelog, '0.0.1').includes('* old'), 'including the last one');
  strictEqual(section(changelog, '9.9.9'), '', 'a version with no section is empty');

  console.log('release-notes self-check passed');
}

function main(argv) {
  if (argv.includes('--check')) return selfCheck();

  const arg = (name) => {
    const index = argv.indexOf(name);
    return index === -1 ? '' : (argv[index + 1] ?? '');
  };

  const subjectsFile = arg('--subjects-file');
  const subjects = subjectsFile
    ? readFileSync(subjectsFile, 'utf8').split('\n')
    : arg('--subject').split('\n');

  const entry = notes(subjects, {
    version: arg('--version'),
    previous: arg('--previous') || undefined,
    repository: arg('--repository') || undefined,
    date: arg('--date') || undefined,
    targets: arg('--targets') ? arg('--targets').split(',').filter(Boolean) : undefined,
    carriedFrom: arg('--carried-from') || undefined,
  });

  const path = arg('--changelog') || 'CHANGELOG.md';

  // Reads one version's notes back out, for a GitHub Release body. Deliberately
  // the file rather than the commits: what ships as the note is what was
  // reviewed on the release PR, edits included.
  if (argv.includes('--section')) {
    console.log(section(readFileSync(path, 'utf8'), arg('--version')));
    return;
  }

  if (argv.includes('--body-only')) {
    console.log(entry.body);
    return;
  }

  let existing = '';
  try {
    existing = readFileSync(path, 'utf8');
  } catch {
    existing = '# Changelog\n\n';
  }
  process.stdout.write(insert(existing, entry));
}

main(process.argv.slice(2));

#!/usr/bin/env node
// Works out the next version from the commit subjects of a push to master.
//
// A release is asked for by a marker at the START of a commit subject:
//
//   !major   1.4.2        -> 2.0.0          stable
//   !feat    1.4.2        -> 1.5.0          stable
//   !fix     1.4.2        -> 1.4.3          stable
//   !alpha   0.0.1        -> 0.0.2-alpha.1  pre-release
//            0.0.2-alpha.1 -> 0.0.2-alpha.2
//   !beta    0.0.2-alpha.3 -> 0.0.2-beta.1  promote, same base
//            0.0.2-beta.1  -> 0.0.2-beta.2
//   !stable  0.0.2-beta.2 -> 0.0.2          promote to stable, no bump
//   !patch   0.0.2        -> 0.0.2          no bump at all: rebuild in place
//
// WHAT A RELEASE BUILDS
//
// A marker may name the platforms it is for, in the scope position:
//
//   !alpha(android)          only the Android artifacts are built
//   !fix(android,desktop)    both clients, no server images
//   !feat                    everything, which is what an unscoped marker means
//
// The names are `docker` (every server image, `web` and `admin-web` among
// them), `desktop` and `android`, with a few aliases. Anything else in the
// scope is a conventional-commit scope and not a platform: `!feat(chat): x`
// builds all three, because `chat` is not a platform and guessing that it was
// meant as one would silently ship a release with two thirds of it missing.
//
// A platform left out is not left behind. Its previous artifacts are carried
// into the new release - the images are re-tagged under the new version, the
// installers and APKs are attached to it - so every version is a complete set
// whatever was rebuilt for it. See the table the notes carry.
//
// REBUILDING A VERSION IN PLACE
//
// `!patch` is the odd one out: it produces no new version, it replaces the
// artifacts of the one master already carries. The image tags are pushed over,
// the installers and the APKs are re-attached to the Release that exists, and
// the CHANGELOG is not touched - there is nothing new to say about a version
// whose contents did not change. It skips the release PR, because the diff that
// PR exists to show would be empty.
//
// Its scope works like any other marker's, so `!patch(desktop)` replaces the
// installer and leaves the images and the APKs where they are.
//
// THE DOCS SITE
//
// `docs` is a scope name too, and it is an extra rather than a platform: it asks
// for the Docusaurus site to be deployed once the release is published.
//
//   !fix(docs)             a full release, and the docs site after it
//   !fix(android,docs)     the APKs, and the docs site after it
//
// It never narrows what is built - a scope naming only `docs` still builds
// everything, the same as an empty one.
//
// A push with no marker is not a release. When several pushed commits carry
// markers the strongest wins, in the order listed above - a push containing
// both !fix and !alpha is a stable fix, because the alpha it would have
// produced is already contained in it.
//
// A channel can be promoted but not demoted in place: !alpha on a beta starts
// a fresh alpha on the NEXT patch, because 0.0.2-alpha.1 sorts below a
// 0.0.2-beta.1 that has already shipped.
//
// Usage:
//   node scripts/release-version.mjs --current 0.0.1 --subjects-file subjects.txt
//   node scripts/release-version.mjs --check      # self-check, no arguments

import { strictEqual, throws } from 'node:assert';
import { readFileSync } from 'node:fs';

const CHANNELS = { alpha: 1, beta: 2 };

// Strongest first: the winner of a push carrying more than one marker.
// `patch` is last: a push asking for a real release AND a rebuild of the old
// one wants the release, which already contains the rebuild.
const MARKERS = ['major', 'feat', 'fix', 'stable', 'beta', 'alpha', 'patch'];

const VERSION_RE = /^(\d+)\.(\d+)\.(\d+)(?:-(alpha|beta)\.(\d+))?$/;

// What a release can build, in the order the notes list them.
export const TARGETS = ['docker', 'desktop', 'android'];

// Neither a platform nor an artifact: the scope name that asks for the docs
// site to be deployed after the release, alongside whatever else was built.
const DOCS_ALIASES = new Set(['docs', 'doc', 'documentation', 'site']);

// The spellings a human reaches for. `web` and `admin-web` are Docker images
// like every other service, so they are the same target.
const TARGET_ALIASES = {
  docker: 'docker',
  server: 'docker',
  servers: 'docker',
  images: 'docker',
  backend: 'docker',
  web: 'docker',
  api: 'docker',
  desktop: 'desktop',
  windows: 'desktop',
  win: 'desktop',
  electron: 'desktop',
  android: 'android',
  apk: 'android',
  mobile: 'android',
};

// A commit the release flow wrote itself. Ignored, so re-running over a range
// that includes one does not release twice.
const RELEASE_COMMIT_RE = /^\s*chore\(release\):/i;

export function parseVersion(version) {
  const match = VERSION_RE.exec(String(version).trim());
  if (!match) throw new Error(`Invalid version '${version}'. Expected X.Y.Z or X.Y.Z-alpha.N.`);
  return {
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3]),
    channel: match[4] ?? '',
    pre: match[5] ? Number(match[5]) : 0,
  };
}

export function detectMarker(subjects) {
  const candidates = subjects
    .map((s) => s.trim())
    .filter((s) => s && !RELEASE_COMMIT_RE.test(s));
  const found = new Set();
  for (const subject of candidates) {
    const match = /^\s*!(major|feat|fix|stable|alpha|beta|patch)(?![a-z0-9])/i.exec(subject);
    if (match) found.add(match[1].toLowerCase());
  }
  return MARKERS.find((marker) => found.has(marker)) ?? '';
}

const SCOPE_RE = /^\s*!(?:major|feat|fix|stable|alpha|beta|patch)\(([^)]*)\)/i;

/**
 * The names in a marker's scope, or null when the scope is not one.
 *
 * The scope is shared with conventional commits, so it is only read as a name
 * list when EVERY word in it is one - `!feat(chat)` is a feature with a scope,
 * `!feat(android)` is a feature for one platform, and there is no third
 * reading. A scope holding one platform and one other word is a conventional
 * scope, not a half-understood platform list.
 */
function scopeNames(subject) {
  const match = SCOPE_RE.exec(String(subject).trim());
  if (!match) return null;
  const names = match[1]
    .split(/[,+\s]+/)
    .map((name) => name.trim().toLowerCase())
    .filter(Boolean);
  if (names.length === 0) return null;
  const known = (name) => name === 'all' || name in TARGET_ALIASES || DOCS_ALIASES.has(name);
  return names.every(known) ? names : null;
}

// The platforms a push asks for, from the scope of its markers. `all` is the
// explicit way to say what an empty scope means.
export function parseTargets(subjects) {
  const chosen = new Set();
  for (const subject of subjects) {
    for (const name of scopeNames(subject) ?? []) {
      // `docs` is an extra, not a platform, and never narrows what is built:
      // `!fix(docs)` is a full release that also deploys the site.
      if (DOCS_ALIASES.has(name)) continue;
      if (name === 'all') TARGETS.forEach((target) => chosen.add(target));
      else chosen.add(TARGET_ALIASES[name]);
    }
  }
  // No marker named a platform: build the lot, which is what every release did
  // before this existed.
  return chosen.size === 0 ? [...TARGETS] : TARGETS.filter((target) => chosen.has(target));
}

/** Whether any marker asked for the docs site to go out with the release. */
export function parseDocs(subjects) {
  return subjects.some((subject) =>
    (scopeNames(subject) ?? []).some((name) => DOCS_ALIASES.has(name)),
  );
}

export function nextVersion(current, marker) {
  const { major, minor, patch, channel, pre } = parseVersion(current);
  const stable = (m, n, p) => `${m}.${n}.${p}`;

  switch (marker) {
    case 'major':
      return stable(major + 1, 0, 0);
    case 'feat':
      return stable(major, minor + 1, 0);
    case 'fix':
      // From a pre-release this deliberately moves past it: 0.0.2-beta.1 is a
      // draft of 0.0.2, and !fix asks for the next fix, not for that draft to
      // be declared finished. !stable is what declares it finished.
      return stable(major, minor, patch + 1);
    case 'stable':
      if (!channel) throw new Error(`!stable needs a pre-release to promote; ${current} is already stable.`);
      return stable(major, minor, patch);
    case 'patch':
      // Deliberately not a bump. `!patch` rebuilds the artifacts of the
      // version that is already released, so the answer is that version.
      return channel
        ? `${stable(major, minor, patch)}-${channel}.${pre}`
        : stable(major, minor, patch);
    case 'alpha':
    case 'beta': {
      const sameOrLower = channel && CHANNELS[channel] <= CHANNELS[marker];
      if (sameOrLower) {
        const counter = channel === marker ? pre + 1 : 1;
        return `${stable(major, minor, patch)}-${marker}.${counter}`;
      }
      return `${stable(major, minor, patch + 1)}-${marker}.1`;
    }
    default:
      throw new Error(`Unknown marker '${marker}'.`);
  }
}

function selfCheck() {
  const eq = (current, marker, expected) =>
    strictEqual(nextVersion(current, marker), expected, `${current} + !${marker}`);

  eq('0.0.0', 'fix', '0.0.1');
  eq('0.0.0', 'alpha', '0.0.1-alpha.1');
  eq('0.0.1-alpha.1', 'alpha', '0.0.1-alpha.2');
  eq('0.0.1-alpha.3', 'beta', '0.0.1-beta.1');
  eq('0.0.1-beta.1', 'beta', '0.0.1-beta.2');
  eq('0.0.1-beta.2', 'stable', '0.0.1');
  eq('0.0.1-beta.2', 'alpha', '0.0.2-alpha.1');
  eq('0.0.1', 'alpha', '0.0.2-alpha.1');
  eq('0.0.1', 'feat', '0.1.0');
  eq('0.1.0', 'major', '1.0.0');
  eq('1.4.2', 'fix', '1.4.3');
  eq('0.0.2-beta.1', 'fix', '0.0.3');
  // !patch is the one marker that answers with the version it was given.
  eq('1.4.2', 'patch', '1.4.2');
  eq('0.0.2-alpha.3', 'patch', '0.0.2-alpha.3');

  throws(() => nextVersion('0.0.1', 'stable'), /already stable/);
  throws(() => parseVersion('1.2'), /Invalid version/);
  throws(() => parseVersion('1.2.3-rc.1'), /Invalid version/);

  strictEqual(detectMarker(['!feat: a thing']), 'feat');
  strictEqual(detectMarker(['docs: nothing']), '');
  // Strongest wins.
  strictEqual(detectMarker(['!alpha: x', '!fix: y']), 'fix');
  strictEqual(detectMarker(['!major: x', '!feat: y']), 'major');
  // The flow's own commits never trigger a release.
  strictEqual(detectMarker(['chore(release): v0.0.1']), '');
  // A marker has to start the subject, and has to be the whole word.
  strictEqual(detectMarker(['fix: mentions !feat in passing']), '');
  strictEqual(detectMarker(['!feature: not a marker']), '');
  // A scoped marker is still a marker.
  strictEqual(detectMarker(['!alpha(android): x']), 'alpha');
  strictEqual(detectMarker(['!patch: rebuild the installer']), 'patch');
  // A real release beats a rebuild of the old one: it already contains it.
  strictEqual(detectMarker(['!patch: x', '!fix: y']), 'fix');

  const targets = (subjects) => parseTargets(subjects).join(',');
  strictEqual(targets(['!alpha: everything']), 'docker,desktop,android');
  strictEqual(targets(['!alpha(android): x']), 'android');
  strictEqual(targets(['!fix(android,desktop): x']), 'desktop,android', 'listed in TARGETS order');
  strictEqual(targets(['!feat(web): x']), 'docker', 'web is a Docker image');
  strictEqual(targets(['!feat(all): x']), 'docker,desktop,android');
  // A conventional scope is not a platform list, and half of one is not either.
  strictEqual(targets(['!feat(chat): x']), 'docker,desktop,android');
  strictEqual(targets(['!feat(android,chat): x']), 'docker,desktop,android');
  // Two scoped markers in one push are the union of what they ask for.
  strictEqual(targets(['!alpha(android): x', '!fix(desktop): y']), 'desktop,android');
  // An unscoped marker beside a scoped one does not widen it: the scoped one
  // is the only statement anybody made about platforms.
  strictEqual(targets(['!alpha(android): x', 'fix: unrelated']), 'android');

  strictEqual(targets(['!patch(desktop): x']), 'desktop', 'a patch has a scope like any marker');

  // `docs` is an extra, never a narrowing: it says what happens after the
  // release, not what the release builds.
  const docs = (subjects) => parseDocs(subjects);
  strictEqual(docs(['!fix: x']), false);
  strictEqual(docs(['!fix(docs): x']), true);
  strictEqual(targets(['!fix(docs): x']), 'docker,desktop,android', 'docs alone builds everything');
  strictEqual(docs(['!fix(android,docs): x']), true);
  strictEqual(targets(['!fix(android,docs): x']), 'android', 'and does not widen a scope either');
  strictEqual(docs(['!patch(docs): x']), true, 'a patch can redeploy the site too');
  // Still a conventional scope when a word in it is neither.
  strictEqual(docs(['!fix(docs,chat): x']), false);
  strictEqual(docs(['docs: a written thing']), false, 'a docs commit is not a docs deploy');

  console.log('release-version self-check passed');
}

function main(argv) {
  if (argv.includes('--check')) return selfCheck();

  const arg = (name) => {
    const index = argv.indexOf(name);
    return index === -1 ? '' : (argv[index + 1] ?? '');
  };

  const current = arg('--current');
  const subjectsFile = arg('--subjects-file');
  const subjects = subjectsFile
    ? readFileSync(subjectsFile, 'utf8').split('\n')
    : arg('--subject').split('\n');

  const marker = detectMarker(subjects);
  const lines = marker
    ? [
        'release=true',
        `marker=${marker}`,
        `version=${nextVersion(current, marker)}`,
        `targets=${parseTargets(subjects).join(',')}`,
        `docs=${parseDocs(subjects)}`,
      ]
    : ['release=false'];

  const version = marker ? nextVersion(current, marker) : '';
  if (version) {
    const { channel } = parseVersion(version);
    lines.push(`channel=${channel || 'latest'}`, `prerelease=${channel ? 'true' : 'false'}`);
  }
  console.log(lines.join('\n'));
}

main(process.argv.slice(2));

/**
 * Render Android launcher icon PNGs directly from desktop SVG specs
 * with safe-zone scaling (54% mark size, centered), so it never cuts off
 * inside circle/squircle masks on any Android device.
 *
 *   node scripts/render-android-icons.js
 */
const { Resvg } = require('@resvg/resvg-js');
const fs = require('fs');
const path = require('path');

const desktopSvg = fs.readFileSync(
  path.join(__dirname, '../apps/desktop/public/icon.svg'),
  'utf8',
);

// Extract the two path elements (headset pads + headband) from the desktop SVG
const pathMatches = [...desktopSvg.matchAll(/<path\s+d="([^"]+)"\s+fill="([^"]+)"\s*\/>/g)];
if (pathMatches.length !== 2) throw new Error(`expected 2 paths, got ${pathMatches.length}`);

function icon({ rounded }) {
  const clip = rounded
    ? '<clipPath id="mask"><circle cx="512" cy="512" r="512"/></clipPath>'
    : '<clipPath id="mask"><rect x="0" y="0" width="1024" height="1024" rx="220"/></clipPath>';

  // 54% scale, centered at (512, 512)
  const scale = 0.54;
  const offsetX = 235.52;
  const offsetY = 253.56;

  return `<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024">
  <defs>
    ${clip}
    <linearGradient id="betweenusBg" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#5b21b6" />
      <stop offset="50%" stop-color="#3730a3" />
      <stop offset="100%" stop-color="#0f172a" />
    </linearGradient>
    <linearGradient id="betweenusHeadset" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#a78bfa" />
      <stop offset="100%" stop-color="#6c5ce7" />
    </linearGradient>
  </defs>
  <g clip-path="url(#mask)">
    <rect width="1024" height="1024" fill="url(#betweenusBg)"/>
    <g transform="translate(${offsetX} ${offsetY}) scale(${scale})">
      <path d="${pathMatches[0][1]}" fill="url(#betweenusHeadset)"/>
      <path d="${pathMatches[1][1]}" fill="#ffffff"/>
    </g>
  </g>
</svg>`;
}

const DENSITIES = {
  'mipmap-mdpi': 48,
  'mipmap-hdpi': 72,
  'mipmap-xhdpi': 96,
  'mipmap-xxhdpi': 144,
  'mipmap-xxxhdpi': 192,
};

function main() {
  const res = path.join(__dirname, '../apps/android/app/src/main/res');

  for (const [bucket, size] of Object.entries(DENSITIES)) {
    const directory = path.join(res, bucket);
    fs.mkdirSync(directory, { recursive: true });

    for (const rounded of [false, true]) {
      const svg = icon({ rounded });
      const png = new Resvg(svg, { fitTo: { mode: 'width', value: size } }).render().asPng();
      const name = rounded ? 'ic_launcher_round.png' : 'ic_launcher.png';
      fs.writeFileSync(path.join(directory, name), png);

      const stale = path.join(directory, name.replace(/\.png$/, '.webp'));
      if (fs.existsSync(stale)) fs.unlinkSync(stale);
    }
    console.log(`${bucket}: ${size}px`);
  }
}

main();

const { Resvg } = require('@resvg/resvg-js');
const fs = require('fs');
const path = require('path');

try {
  const svgPath = path.join(__dirname, '../apps/desktop/public/icon.svg');
  const svgData = fs.readFileSync(svgPath, 'utf8');

  const resvg = new Resvg(svgData, {
    fitTo: {
      mode: 'width',
      value: 512,
    },
  });

  const pngData = resvg.render();
  const pngBuffer = pngData.asPng();

  const targetPng = path.join(__dirname, '../apps/desktop/public/icon.png');
  const buildPng = path.join(__dirname, '../apps/desktop/build/icon.png');

  fs.mkdirSync(path.dirname(targetPng), { recursive: true });
  fs.mkdirSync(path.dirname(buildPng), { recursive: true });

  fs.writeFileSync(targetPng, pngBuffer);
  fs.writeFileSync(buildPng, pngBuffer);

  console.log('SUCCESS: Rendered high-res 512x512 PNG icon at', targetPng, 'Size:', pngBuffer.length, 'bytes');
} catch (err) {
  console.error('Error rendering SVG:', err);
  process.exit(1);
}

/**
 * Render a standalone 1024x1024 PNG of the BetweenUs launcher icon
 * (accent gradient background + white mark foreground) so Android Studio's
 * Image Asset wizard can consume it as a plain image file.
 *
 *   node scripts/render-launcher-source.js
 *
 * Output: apps/android/ic_launcher_source.png
 */
const { Resvg } = require('@resvg/resvg-js');
const fs = require('fs');
const path = require('path');

const vector = fs.readFileSync(
  path.join(__dirname, '../apps/android/ui-common/src/main/res/drawable/ic_betweenus_logo.xml'),
  'utf8',
);
const paths = [...vector.matchAll(/android:pathData="([^"]+)"/g)].map((m) => m[1]);
if (paths.length !== 2) throw new Error(`expected 2 paths, got ${paths.length}`);

const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1024" y2="1024" gradientUnits="userSpaceOnUse">
      <stop offset="0" stop-color="#8C6FFF"/>
      <stop offset="0.5" stop-color="#7C5CFF"/>
      <stop offset="1" stop-color="#5B3FE0"/>
    </linearGradient>
  </defs>
  <rect width="1024" height="1024" fill="url(#bg)"/>
  <path d="${paths[0]}" fill="#FFFFFF"/>
  <path d="${paths[1]}" fill="#FFFFFF" fill-opacity="0.92"/>
</svg>`;

const png = new Resvg(svg, { fitTo: { mode: 'width', value: 1024 } }).render().asPng();
const out = path.join(__dirname, '../apps/android/ic_launcher_source.png');
fs.writeFileSync(out, png);
console.log(`Wrote ${out} (${png.length} bytes)`);

#!/usr/bin/env node
/**
 * Automatically syncs root CHANGELOG.md into docs/docs/changelog.md
 * with Docusaurus frontmatter and release links.
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const rootDir = resolve(__dirname, '..');
const changelogSrc = resolve(rootDir, 'CHANGELOG.md');
const changelogDest = resolve(rootDir, 'docs', 'docs', 'changelog.md');

export function syncChangelog() {
  if (!existsSync(changelogSrc)) {
    console.warn(`[sync-changelog] Source file not found: ${changelogSrc}`);
    return;
  }

  const raw = readFileSync(changelogSrc, 'utf8');

  // Remove top-level # Changelog heading to avoid double headings
  let body = raw.replace(/^#\s+Changelog\s*\n+/i, '').trim();

  // Escape unescaped curly braces outside code fences for MDX compatibility
  body = body.replace(/(?<!`)\{([^`\n{}]+)\}(?!`)/g, '`{$1}`');

  const content = `---
title: Changelog
description: Complete release notes and historical changelog for BetweenUs.
displayed_sidebar: null
---

# Changelog

:::tip GitHub Releases
All production release binaries (Windows Desktop installer and Android APK), asset checksums, and version tag comparisons are published on [GitHub Releases](https://github.com/aiyu-ayaan/BetweenUs/releases).
:::

${body}
`;

  writeFileSync(changelogDest, content, 'utf8');
  console.log(`[sync-changelog] Synced ${changelogSrc} -> ${changelogDest}`);
}

syncChangelog();

{
  "$schema": "https://turbo.build/schema.json",
  // `pnpm dev` runs every service, the desktop renderer, the web client and the
  // admin panel at once, and each is a persistent task. Turbo refuses to start
  // when it has fewer slots than persistent tasks, so this has to stay ahead of
  // the number of packages with a `dev` script - it was ten the day the web
  // client landed, which is exactly the default.
  "concurrency": "20",
  "tasks": {
    "build": {
      "dependsOn": ["^build"],
      "outputs": ["dist/**", "build/**", "release/**"]
    },
    "dev": {
      "dependsOn": ["^build"],
      "cache": false,
      "persistent": true
    },
    // The dev gateway lives at the repo root rather than in a package, so it
    // needs the `//#` form to be runnable as a task at all. `pnpm dev` starts
    // it alongside everything else: the Android client is pointed at one
    // address and has no Vite proxy, so without this it has nothing to reach.
    "//#dev:gateway": {
      "cache": false,
      "persistent": true
    },
    "lint": {},
    "typecheck": {
      "dependsOn": ["^build"]
    },
    "check": {
      "dependsOn": ["^build"]
    }
  }
}
